/* View: D_PESSOA_NOTIFICADA, Owner: SYSDBA */
CREATE VIEW D_PESSOA_NOTIFICADA (PESSOA_ID, NOME, DOCUMENTO_ID, OBSERVACAO, NOTIFICACAO, ENDERECO, BAIRRO, CIDADE, UF, CEP, TELEFONE, DOCUMENTO) AS
 SELECT C.PESSOA_ID, P.NOME, C.DOCUMENTO_ID,        	   C.OBSERVACAO, C.NOTIFICADO, ENDERECO,                BAIRRO, CIDADE, UF, CEP, TELEFONE, DOCUMENTO FROM D_PESSOA_CITADA AS C INNER JOIN D_PESSOA AS P ON P.PESSOA_ID = C.PESSOA_ID WHERE NOTIFICADO = 'S';

/* View: D_TIPO_SERVICO_SINTERBR, Owner: SYSDBA */
CREATE VIEW D_TIPO_SERVICO_SINTERBR (ID, DESCRICAO) AS
  SELECT CAST(01 AS INT) AS ID ,'Registro'                    as DESCRICAO FROM RDB$DATABASE UNION ALL SELECT CAST(03 AS INT) AS ID ,'Pedido de Certidão'       as DESCRICAO FROM RDB$DATABASE UNION ALL SELECT CAST(04 AS INT) AS ID ,'Autenticação de Livros'   as DESCRICAO FROM RDB$DATABASE UNION ALL SELECT CAST(05 AS INT) AS ID ,'Notificação'              as DESCRICAO FROM RDB$DATABASE UNION ALL SELECT CAST(09 AS INT) AS ID ,'Complemento'              as DESCRICAO FROM RDB$DATABASE UNION ALL SELECT CAST(10 AS INT) AS ID ,'Viabilidade'              as DESCRICAO FROM RDB$DATABASE UNION ALL SELECT CAST(11 AS INT) AS ID ,'Entrega Eletrônica'       as DESCRICAO FROM RDB$DATABASE UNION ALL SELECT CAST(12 AS INT) AS ID ,'Registro (digitalização)' as DESCRICAO FROM RDB$DATABASE UNION ALL SELECT CAST(13 AS INT) AS ID ,'Digitalização'            as DESCRICAO FROM RDB$DATABASE UNION ALL SELECT CAST(15 AS INT) AS ID ,'Notificação CORI'         as DESCRICAO FROM RDB$DATABASE UNION ALL SELECT CAST(16 AS INT) AS ID ,'Desmaterialização'        as DESCRICAO FROM RDB$DATABASE ;

/* View: G_VW_GRAUINSTRUCAO, Owner: SYSDBA */
CREATE VIEW G_VW_GRAUINSTRUCAO (ID, TIPO, DESCRICAO) AS
 select     ID,     TIPO,     DESCRICAO FROM ( Select CAST(00 AS NUMERICO) AS ID, cast('Não Declarado' AS varchar_060) as TIPO, CAST('Não Declarado'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE UNION ALL Select CAST(01 AS NUMERICO) AS ID, cast('Analfabeto' AS varchar_060) as TIPO, CAST('Indivíduo que não sabe ler e escrever'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE  UNION ALL Select CAST(02 AS NUMERICO) AS ID, cast('Semi-analfabeto' AS varchar_060) as TIPO, CAST('Pessoa que aprendeu a ler e a escrever somente'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE  UNION ALL  Select CAST(03 AS NUMERICO) AS ID, cast('Ensino fundamental incompleto' AS varchar_060) as TIPO, CAST('Não concluiu todos os anos correspondentes a este ciclo de estudos (1ª a 9ª série)'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE  UNION ALL Select CAST(04 AS NUMERICO) AS ID, cast('Ensino fundamental completo' AS varchar_060) as TIPO, CAST('Concluiu o ciclo de estudos básicos (1ª a 9ª série)'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE  UNION ALL Select CAST(05 AS NUMERICO) AS ID, cast('Ensino médio incompleto' AS varchar_060) as TIPO, CAST('Não concluiu todos os anos correspondentes a este ciclo (1º ao 3º ano)'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE  UNION ALL Select CAST(06 AS NUMERICO) AS ID, cast('Ensino médio completo' AS varchar_060) as TIPO, CAST('Concluiu este ciclo de estudos (1º ao 3º ano)'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE  UNION ALL Select CAST(07 AS NUMERICO) AS ID, cast('Superior completo (ou graduação)' as varchar_060) as TIPO, CAST('Concluiu o curso de ensino superior (bacharelado ou licenciatura)'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE  UNION ALL Select CAST(08 AS NUMERICO) AS ID, cast('Pós-graduaçãoas' AS varchar_060) as TIPO, CAST('Especialização no âmbito do curso de ensino superior que foi concluído'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE  UNION ALL Select CAST(09 AS NUMERICO) AS ID, cast('Mestradoas' AS  varchar_060) as TIPO, CAST('Pós-graduação que garante o grau de mestre em determinada área'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE  UNION ALL Select CAST(10 AS NUMERICO) AS ID, cast('Doutoradoas' AS varchar_060) as TIPO, CAST('Pós-graduação que garante o grau de doutor em determinada área de pesquisa'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE  UNION ALL Select CAST(11 AS NUMERICO) AS ID, cast('Pós-Doutoradoas' AS varchar_060) as TIPO, CAST('Atividade de pesquisa ou estágio que pode ser realizada após a conclusão do doutorado'  as VARCHAR_120) AS DESCRICAO FROM RDB$DATABASE ) GRAU;

/* View: G_VW_LST_DEFICIENCIA, Owner: SYSDBA */
CREATE VIEW G_VW_LST_DEFICIENCIA (VWDEF_ID, DESCRICAO) AS
  select  VWDEF_ID,  DESCRICAO from( SELECT cast(1 as numerico) AS VWDEF_ID, cast('Deficiência Visual Parcial (Baixa visão)' as varchar_060) as DESCRICAO from RDB$DATABASE UNION ALL SELECT cast(2 as numerico) AS VWDEF_ID, cast('Deficiência Visual Completa (Cegueira)' as varchar_060) as DESCRICAO from RDB$DATABASE UNION ALL SELECT cast(3 as numerico) AS VWDEF_ID, cast('Deficiência Auditiva (Total)' as varchar_060) as DESCRICAO from RDB$DATABASE UNION ALL SELECT cast(4 as numerico) AS VWDEF_ID, cast('Deficiência Auditiva (Parcial)' as varchar_060) as DESCRICAO from RDB$DATABASE UNION ALL SELECT cast(5 as numerico) AS VWDEF_ID, cast('Deficiência Mental' as varchar_060) as DESCRICAO from RDB$DATABASE UNION ALL SELECT cast(6 as numerico) AS VWDEF_ID, cast('Deficiência Físicas Congênitas' as varchar_060) as DESCRICAO from RDB$DATABASE UNION ALL SELECT cast(7 as numerico) AS VWDEF_ID, cast('Deficiência Físicas Adquiridas' as varchar_060) as DESCRICAO from RDB$DATABASE UNION ALL SELECT cast(8 as numerico) AS VWDEF_ID, cast('Deficiência múltipla' as varchar_060) as DESCRICAO from RDB$DATABASE ) DEF;

/* View: G_VW_SELO_LIVRO_DISPONIVEL, Owner: SYSDBA */
CREATE VIEW G_VW_SELO_LIVRO_DISPONIVEL (SELO_LIVRO_ID, NUMERO, SIGLA, NUMERO_SELO, SELO_SITUACAO_ID) AS
   SELECT SELO_LIVRO_ID, NUMERO, SIGLA, NUMERO_SELO, SELO_SITUACAO_ID FROM G_SELO_LIVRO  WHERE SELO_SITUACAO_ID = 1;

/* View: R_PEDIDO_PENDENTE, Owner: SYSDBA */
CREATE VIEW R_PEDIDO_PENDENTE (PEDIDO_ID, DATA_PEDIDO, DATA_PREVISTA, APRESENTANTE_NOME, APRESENTANTE_CPF_CNPJ, APRESENTANTE_FONE, ADQUIRENTE_NOME, ADQUIRENTE_CPF_CNPJ, TRANSMITENTE_NOME, TRANSMITENTE_CPF_CNPJ, OBSERVACAO, VALOR_DEPOSITO, ANDAMENTO_ID, TB_TITULO_ID, ENDERECO, PROTOCOLO_DEVOLVIDO, NOVO_PEDIDO_ID, VALOR_DEVOLVIDO, INFORMADO_CONTA, NUMERO_BANCO, NUMERO_AGENCIA, NUMERO_CONTA, CPF_CNPJ_INFORMADO, QTDE_ETIQUETA, DATA_PRIORIDADE, USUARIO_PRIORIDADE_ID, NUMERO_OPERACAO, TIPO_CONTA, SENHA_NUMERO, SENHA_DATA, VALOR_COMPENSADO, NOME_TITULAR_CONTA, NUMERO_PAGINA, ORIGEM_PEDIDO, DATA_TITULO, TIPO_INCLUSAO, APRESENTANTE_EMAIL, TITULO_LIVRO, TITULO_FOLHA_INICIAL, TITULO_FOLHA_FINAL, TITULO_CONTRATO, MOTIVO_ISENTO, TIPO_COBRANCA, DESCRICAO_ISENTO_OUTROS, NUMERO_ONLINE, TIPO_ORIGEM_SITE, EMAIL_CONTATO, CELULAR_CONTATO, ADQUIRENTE_TIPO_DOC, TRANSMITENTE_TIPO_DOC, APRESENTANTE_TIPO_DOC, EMITIR_NOTA_PARA, OUTROS_TITULOS, ENDERECO_NFSE, ENDERECO_NUMERO_NFSE, ENDERECO_COMPL_NFSE, ENDERECO_BAIRRO_NFSE, ENDERECO_COD_MUN_NFSE, ENDERECO_CEP_NFSE, ENDERECO_MUNICIPIO_NFSE, ENDERECO_UF_NFSE, EH_OPTANTE_SIMPLES_NFSE, NFSE_RPS, CPF_NFSE, NOME_NFSE, TIPO_DOC_NFSE, XML_SOLICITACAO, IE_NFSE, IM_NFSE) AS
 SELECT * FROM R_PEDIDO  WHERE PEDIDO_ID NOT IN (SELECT PEDIDO_ID FROM R_PROTOCOLO WHERE PEDIDO_ID = R_PEDIDO.PEDIDO_ID) ;

/* View: R_PROTOCOLO_EM_ANDAMENTO, Owner: SYSDBA */
CREATE VIEW R_PROTOCOLO_EM_ANDAMENTO (PROTOCOLO_ID, PEDIDO_ID, DATA, NUMERO_ORDEM, ATOS_PRATICADOS, NATUREZA_TITULO_ID, TIPO_PROTOCOLO, LIVRO, FOLHA_NUMERO, FOLHA_FV, CODIGO_ACESSO, CODIGO_ACESSO_ONLINE, NUMERO_SELO) AS
 SELECT * FROM R_PROTOCOLO WHERE (TIPO_PROTOCOLO = '1' OR TIPO_PROTOCOLO = '2') AND PEDIDO_ID NOT IN (SELECT A.PEDIDO_ID FROM R_ANDAMENTO A,                                             R_TB_TIPO_ANDAMENTO T                       WHERE A.TB_TIPO_ANDAMENTO_ID = T.TB_TIPO_ANDAMENTO_ID                       AND A.PEDIDO_ID = R_PROTOCOLO.PEDIDO_ID                       AND (T.TIPO = 'R' OR T.TIPO = 'C')) ;

/* View: V_C_CAIXA_ITEM, Owner: SYSDBA */
CREATE VIEW V_C_CAIXA_ITEM (CAIXA_ITEM_ID, CAIXA_SERVICO_ID, USUARIO_SERVICO_ID, USUARIO_CAIXA_ID, CHAVE_SERVICO, DESCRICAO, DATA_PAGAMENTO, SITUACAO, TIPO_DOCUMENTO, TIPO_TRANSACAO, VALOR_SERVICO, VALOR_PAGO, CAIXA_CHEQUE_ID, HORA_PAGAMENTO, ESPECIE_PAGAMENTO, CAIXA_ID, SISTEMA_ID) AS
 SELECT CI.CAIXA_ITEM_ID,        CI.CAIXA_SERVICO_ID,        CI.USUARIO_SERVICO_ID,        CI.USUARIO_CAIXA_ID,        CI.CHAVE_SERVICO,        CI.DESCRICAO,        CI.DATA_PAGAMENTO,        CI.SITUACAO,        CI.TIPO_DOCUMENTO,        CI.TIPO_TRANSACAO,        CI.VALOR_SERVICO,        CI.VALOR_PAGO,        CI.CAIXA_CHEQUE_ID,        CI.HORA_PAGAMENTO,        CI.ESPECIE_PAGAMENTO,        CI.CAIXA_ID,        CS.SISTEMA_ID FROM C_CAIXA_ITEM CI LEFT JOIN C_CAIXA_SERVICO CS ON      CI.CAIXA_SERVICO_ID = CS.CAIXA_SERVICO_ID;

/* View: V_EMOLUMENTOS_PERIODO, Owner: SYSDBA */
CREATE VIEW V_EMOLUMENTOS_PERIODO (EMOLUMENTO_PERIODO_ID, DESCRICAO, SITUACAO, DATA_INICIAL, DATA_FINAL) AS
  select p.emolumento_periodo_id,         p.descricao,         p.situacao,         p.data_inicial,         (select first 1                 x.data_inicial           from g_emolumento_periodo x          where x.emolumento_periodo_id > p.emolumento_periodo_id            and x.data_inicial is not null)    from g_emolumento_periodo p   where p.data_inicial is not null;

/* View: V_G_SISTEMA_ROTINA, Owner: SYSDBA */
CREATE VIEW V_G_SISTEMA_ROTINA (SISTEMA_ROTINA_ID, CHAVE_ROTINA, DESCRICAO, SISTEMA_MENU_ID, ATALHO_SISTEMA, ATALHO_USUARIO, SISTEMA_ID) AS
 SELECT SR.SISTEMA_ROTINA_ID,        SR.CHAVE_ROTINA,        SR.DESCRICAO,        SR.SISTEMA_MENU_ID,        SR.ATALHO_SISTEMA,        SR.ATALHO_USUARIO,        SM.SISTEMA_ID FROM G_SISTEMA_ROTINA SR LEFT JOIN G_SISTEMA_MENU SM ON      SR.SISTEMA_MENU_ID = SM.SISTEMA_MENU_ID ;

/* View: V_TIPOCADASTRO_FAMILIA, Owner: SYSDBA */
CREATE VIEW V_TIPOCADASTRO_FAMILIA (ID, TIPO, DESCRICAO) AS
 SELECT     ID,     TIPO,     DESCRICAO   from     ( SELECT CAST(null as numerico) as ID, cast(null as varchar(1)) as TIPO ,CAST('Não Declarado' as varchar_015) as DESCRICAO from rdb$database WHERE 1=1      union all      SELECT CAST(1 as numerico) as ID, cast('1' as varchar(1)) as TIPO ,CAST('Pai' as varchar_015) as DESCRICAO from rdb$database WHERE 1=1      union all      SELECT CAST(2 as numerico) as ID, cast('2' as varchar(1)) as TIPO ,CAST('Mãe' as varchar_015) as DESCRICAO from rdb$database WHERE 1=1      union all      SELECT CAST(6 as numerico) as ID, cast('6' as varchar(1)) as TIPO ,CAST('Testemunha' as varchar_015) as DESCRICAO from rdb$database WHERE 1=1      union all      SELECT CAST(7 as numerico) as ID, cast('7' as varchar(1)) as TIPO ,CAST('Noivo' as varchar_015) as DESCRICAO from rdb$database WHERE 1=1      union all      SELECT CAST(8 as numerico) as ID, cast('8' as varchar(1)) as TIPO ,CAST('Noiva' as varchar_015) as DESCRICAO from rdb$database WHERE 1=1      union all      SELECT CAST(9 as numerico) as ID, cast('A' as varchar(1)) as TIPO ,CAST('Primeira Parte' as varchar_015) as DESCRICAO from rdb$database WHERE 1=1      union all      SELECT CAST(10 as numerico) as ID, cast('B' as varchar(1)) as TIPO ,CAST('Segunda Parte' as varchar_015) as DESCRICAO from rdb$database WHERE 1=1     )X;

