ALTER PROCEDURE C_ATOS_TABELIONATO (V_DATA_INICIAL DATE,
V_DATA_FINAL DATE)
RETURNS (ID INTEGER,
SISTEMA_ID VARCHAR_003,
TIPO_PROTOCOLO VARCHAR_090,
NUMERO_PROTOCOLO VARCHAR_030,
DATA_PROTOCOLO DATE,
NATUREZA VARCHAR_260,
DESCRICAO VARCHAR_260,
REQUERENTE VARCHAR_260,
VALOR_ATO NUMERIC(18, 4),
QUANTIDADE SMALLINT,
TOTAL_EMOLUMENTO NUMERIC(18, 4),
TAXA_JUDICIARIA NUMERIC(18, 4),
NUM_LIVRO VARCHAR_010,
NUM_FOLHA VARCHAR_030,
FUNDESP NUMERIC(18, 4))
AS 
declare variable V_VALOR_EMOLUMENTO numeric(18,4);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_SQL varchar(5000);
declare variable V_SQL2 varchar(5000);
declare variable V_COUNT integer;
BEGIN
  SELECT COUNT(*) FROM RDB$RELATIONS
  WHERE RDB$SYSTEM_FLAG = 0
  AND RDB$RELATION_NAME = 'T_ATO'
  INTO :V_COUNT;
  IF (:V_COUNT > 0) THEN --SE TIVER tabelionato
  BEGIN
    --SELECIONAR PROTOCOLOS REGISTRADOS DO TABELIONATO
    TOTAL_EMOLUMENTO = 0;
    QUANTIDADE = 1;

    V_SQL = ' SELECT A.ATO_ID,
               T.DESCRICAO,
               A.PROTOCOLO,
               A.DATA_LAVRATURA,
               A.ATO_TIPO_ID
        FROM T_ATO A
        LEFT JOIN T_ATO_TIPO AS T ON T.ATO_TIPO_ID = A.ATO_TIPO_ID
        WHERE (A.SITUACAO_ATO IN  ('||''''||'3'||''''||','||''''||'6'||''''||','||''''||'7'||''''||','||''''||'8'||''''||','||''''||'9'||''''||'))
        AND A.DATA_LAVRATURA BETWEEN CAST('||''''||:V_DATA_INICIAL||''''||' AS TIMESTAMP)
                                 AND CAST('||''''||:V_DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
        ORDER BY A.PROTOCOLO ';
      FOR EXECUTE STATEMENT :V_SQL
      INTO :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
             :V_ATO_TIPO_ID DO
    BEGIN
  
  --    V_DESCRICAO = '';
  --    V_DESCRICAO2 = '';
  --    SELECT LN.DESCRICAO, TA.DESCRICAO
  --    FROM T_ATO_TIPO TA, T_LIVRO_NATUREZA LN
  --    WHERE TA.LIVRO_NATUREZA_ID = LN.LIVRO_NATUREZA_ID
  --    AND TA.ATO_TIPO_ID = :V_ATO_TIPO_ID
  
  --    INTO :V_DESCRICAO, :V_DESCRICAO2;
  
  --    IF ((:V_DESCRICAO <> '') AND (:V_DESCRICAO IS NOT NULL)) THEN
  --    BEGIN
  --      NATUREZA = :V_DESCRICAO||' ('||:V_DESCRICAO2||')';
  --    END
      NATUREZA = :TIPO_PROTOCOLO;

      V_SQL2 = ' SELECT COALESCE((SELECT FIRST 1 PESSOA_NOME FROM T_ATO_VINCULOPARTE AS V WHERE A.ATO_ID = V.ATO_ID AND REQUERENTE = '||''''||'S'||''''||'),
             (COALESCE((SELECT FIRST 1 PESSOA_NOME FROM T_ATO_VINCULOPARTE AS V WHERE A.ATO_ID = V.ATO_ID AND TIPO_VINCULO IN (0,2) AND ORDEM = 1),
             (SELECT FIRST 1 PESSOA_NOME FROM T_ATO_VINCULOPARTE AS V WHERE A.ATO_ID = V.ATO_ID)))) AS PESSOA_NOME
      FROM T_ATO A WHERE ATO_ID = '||:ID;
      EXECUTE STATEMENT :V_SQL2
      INTO :REQUERENTE;
  
      TOTAL_EMOLUMENTO = 0;

      V_SQL2 = ' SELECT SUM(EMOLUMENTO) AS EMOLUMENTO FROM T_ATO_VINCULOVALOR
      WHERE ATO_ID = '||:ID;

      EXECUTE STATEMENT :V_SQL2
      INTO :TOTAL_EMOLUMENTO; -- soma total emolumento
      FUNDESP = (TOTAL_EMOLUMENTO * 0.1);
  
      TAXA_JUDICIARIA = 0;

      V_SQL2 = ' SELECT SUM(COALESCE(ROUND(TAXA_JUDICIARIA, 2),0)) AS TAXA_JUDICIARIA
      FROM T_ATO_VINCULOVALOR
      WHERE ATO_ID = '||:ID;

      EXECUTE STATEMENT :V_SQL2
      INTO :TAXA_JUDICIARIA;
  
      NUM_LIVRO = 0;

      V_SQL2 = ' SELECT CAST(cast(NUMERO_LIVRO as integer) AS varchar_010) FROM t_livro_andamento TL
      LEFT JOIN t_ato TA ON TL.livro_andamento_id = TA.livro_andamento_id
      WHERE TA.ato_id = '||:id;

      EXECUTE STATEMENT :V_SQL2
      into :num_livro;
  
      NUM_FOLHA = 0;

      V_SQL2 = ' SELECT  cast(FOLHA_INICIAL as integer)||'||''''||' a '||''''||'|| cast(FOLHA_FINAL as integer) from t_ato
      where ato_id = '||:id;

      EXECUTE STATEMENT :V_SQL2
      into :num_folha;
  
      V_SQL2 = ' SELECT SUM(COALESCE(ROUND(VALOR_DOCUMENTO, 2),0))
      FROM T_ATO_VINCULOVALOR
      WHERE ATO_ID = '||:ID;

      EXECUTE STATEMENT :V_SQL2
      INTO:VALOR_ATO;
  
      V_DESCRICAO = 'PROT. '||REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA;
      DESCRICAO = :V_DESCRICAO;
      SISTEMA_ID = 2;
      SUSPEND;
    END
  
    --SELECIONAR SERVIÇOS DE BALCÃO DO TABELIONATO
      QUANTIDADE = 0;
      FUNDESP = 0;
      TOTAL_EMOLUMENTO = 0;

      V_SQL = ' SELECT  2,
                  Case ST.TIPO_ITEM When '||''''||'R'||''''||' Then '||''''||'Reconhecimento'||''''||' When '||''''||'A'||''''||' Then '||''''||'AUTENTICACAO'||''''||' Else ST.DESCRICAO End,
                  NULL,
                  SP.DATA_PEDIDO,
                  ST.DESCRICAO AS DESCRICAO_SERVICO,
                  SP.APRESENTANTE,
                  (SI.VALOR) AS VALOR,
                  (SI.QTD) AS QTD,
                  (SI.EMOLUMENTO/SI.QTD) AS EMOLUMENTO,
                  (SI.TAXA_JUDICIARIA) AS TAXA,
                  0
          FROM T_SERVICO_ITEMPEDIDO SI
          LEFT OUTER JOIN T_SERVICO_PEDIDO SP ON SI.SERVICO_PEDIDO_ID = SP.SERVICO_PEDIDO_ID
          LEFT OUTER JOIN T_PESSOA P ON SI.PESSOA_ID = P.PESSOA_ID
          LEFT OUTER JOIN T_SERVICO_TIPO ST ON SI.SERVICO_TIPO_ID = ST.SERVICO_TIPO_ID
          WHERE SP.DATA_PEDIDO BETWEEN CAST('||''''||:V_DATA_INICIAL||''''||' AS TIMESTAMP)
            AND CAST('||''''||:V_DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
            AND SI.SITUACAO = '||''''||'F'||''''||'
          ';
       FOR EXECUTE STATEMENT :V_SQL
       INTO :SISTEMA_ID, :V_DESCRICAO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
            :DESCRICAO, :REQUERENTE, :VALOR_ATO, :QUANTIDADE, :TOTAL_EMOLUMENTO, :TAXA_JUDICIARIA, :id DO
       BEGIN
          NATUREZA  = :V_DESCRICAO;
          TIPO_PROTOCOLO = :DESCRICAO;
          DESCRICAO = :DESCRICAO || ' - QUANT.: ' || :QUANTIDADE;
          FUNDESP = (TOTAL_EMOLUMENTO * 0.1);
          SUSPEND;
       END  
  END
END ^

ALTER PROCEDURE C_ATUALIZAR_SELO_LIVRO (DATA_INICIAL VARCHAR(15) CHARACTER SET ISO8859_1,
DATA_FINAL VARCHAR(15) CHARACTER SET ISO8859_1,
PERCENTUAL_ISS NUMERIC(18, 2))
RETURNS (CORRIGIDO VARCHAR(3) CHARACTER SET ISO8859_1,
NOTA_FISCAL VARCHAR(50) CHARACTER SET ISO8859_1,
TIPO_ATO VARCHAR(20) CHARACTER SET ISO8859_1,
VALOR_EMOL_SEE NUMERIC(18, 2),
VALOR_EMOLUMENTO NUMERIC(18, 2),
VALOR_TJ_SEE NUMERIC(18, 2),
VALOR_TAXA_JUDICIARIA NUMERIC(18, 2),
QTDE_SEE INTEGER,
QTDE_CARTORIO INTEGER,
DATA_SEE DATE,
DATA_CARTORIO DATE)
AS 
declare variable SELO_LIVRO_ID integer;
declare variable QTDE_ATUALIZADO integer;
declare variable NOTA_FISCAL_TEMP varchar(50);
declare variable tipo_ato_temp varchar(20);

declare variable novo_valor_emol numeric(18,2);
declare variable novo_valor_tj numeric(18,2);
declare variable novo_valor_fundo numeric(18,2);
declare variable novo_valor_iss numeric(18,2);
declare variable novo_valor_total numeric(18,2);

declare variable selo_lote_id integer;
declare variable percentual_fundo numeric(18,2);

begin
  nota_fiscal = '';
  tipo_ato = '';
  qtde_see = 0;
  valor_emol_see = 0;
  valor_tj_see = 0;
  for select distinct nota_fiscal, cast(data_utilizacao as date) as data_utilizacao, codigo_ato, coalesce(valor_fundos,0) as quantidade,
        coalesce(valor_emolumento,0) as valor_emolumento, coalesce(valor_taxa_judiciaria,0) as valor_taxa_judiciaria
      from g_selo_decendio_item
      where cast(data_utilizacao as date) between :data_inicial and :data_final
      and coalesce(valor_fundos,0) > 0
      order by codigo_ato
      into :nota_fiscal, :data_see, :tipo_ato, :qtde_see, :valor_emol_see, :valor_tj_see do
  begin
    corrigido = 'N';
    nota_fiscal_temp = '';
    tipo_ato_temp = '';
    qtde_cartorio = 0;
    valor_emolumento = 0;
    valor_taxa_judiciaria = 0;
    select sl.selo_lote_id, sl.nota_fiscal, cast(sl.data_lote as date) as data_utilizacao, cast(sg.numero as integer) as codigo_ato, count(coalesce(si.selo_livro_id,0)) as quantidade,
      sum(coalesce(si.valor_emolumento,0)) as valor_emolumnento, sum(coalesce(si.valor_taxa_judiciaria,0)) as valor_taxa_judiciaria
    from g_selo_livro si, g_selo_lote sl, g_selo_grupo sg
    where si.selo_lote_id = sl.selo_lote_id
    and sl.selo_grupo_id = sg.selo_grupo_id
    and coalesce(si.selo_situacao_id,0) in (1,2,4)
    and sl.nota_fiscal = :nota_fiscal
    group by 1,2,3,4
    into :selo_lote_id, :nota_fiscal_temp, :data_cartorio, :tipo_ato_temp, :qtde_cartorio, :valor_emolumento, :valor_taxa_judiciaria;

    if ((:qtde_see <> :qtde_cartorio) or (:valor_emol_see <> :valor_emolumento) or (:valor_tj_see <> :valor_taxa_judiciaria)) then
    begin
      if (qtde_see = :qtde_cartorio) then
      begin
        novo_valor_tj = 0;
        if (:valor_tj_see > 0) then
        begin
          novo_valor_tj = cast((:valor_tj_see/:qtde_see) as numeric(18,2));
        end
        novo_valor_emol = 0;
        novo_valor_fundo = 0;
        novo_valor_iss = 0;
        if (:data_see < '24.03.2025') then
        begin
          percentual_fundo = 0.2125;
        end
        else
        begin
          percentual_fundo = 0.2425;
        end

        if (:valor_emol_see > 0) then
        begin
          novo_valor_emol = cast((:valor_emol_see/:qtde_see) as numeric(18,2));
          novo_valor_fundo = cast(cast((:valor_emol_see/:qtde_see) as numeric(18,2)) * :percentual_fundo as numeric(18,2));
          novo_valor_iss = cast(cast((:valor_emol_see/:qtde_see) as numeric(18,2)) * (:percentual_iss/100) as numeric(18,2));
        end
        novo_valor_total = :novo_valor_emol + :novo_valor_fundo + :novo_valor_iss + :novo_valor_tj;

        update g_selo_livro
        set valor_emolumento = :novo_valor_emol,
          valor_taxa_judiciaria = :novo_valor_tj,
          valor_fundesp = :novo_valor_fundo,
          valor_iss = :novo_valor_iss,
          valor_total = :novo_valor_total
        where selo_lote_id = :selo_lote_id
        and coalesce(selo_situacao_id,0) in (1,2);

        corrigido = 'S';
      end
      suspend;
    end
  end
end ^

ALTER PROCEDURE C_BALANCO_ANUAL (ANO NUMERICO,
REGISTRADOS_RI CHAR(1) CHARACTER SET ISO8859_1,
V_SELOS_ANTIGO VARCHAR(1) CHARACTER SET ISO8859_1 = 'N')
RETURNS (MES_ID NUMERICO,
TIPO_ID NUMERICO,
VALOR NUMERICO,
NATUREZA VARCHAR(500) CHARACTER SET ISO8859_1)
AS 
declare variable V_MES NUMERICO;
declare variable V_SALDO NUMERICO;
declare variable V_DATA_INI date;
declare variable V_DATA_FIM date;
BEGIN
    V_SALDO = 0;
    V_DATA_INI = CAST('01/01/' || CAST(CAST(:ANO AS INT) AS VARCHAR(04)) AS DATE);
    V_DATA_FIM = CAST('12/31/' || CAST(CAST(:ANO AS INT) AS VARCHAR(04)) AS DATE);

    V_MES = 1;
    WHILE(V_MES <= 12) DO
    BEGIN
        V_DATA_INI = CAST(CAST(V_MES AS INT)||'/01/'||CAST(CAST(:ANO AS INT) AS VARCHAR(04)) AS DATE);
        FOR SELECT :V_MES, 1, ROUND(COALESCE(SUM(COALESCE(VALOR,0)),0),2) FROM  c_balanco_mensal(:V_DATA_INI,:REGISTRADOS_RI, :V_SELOS_ANTIGO )
        WHERE TIPO = 'C'-- EXTRACT(MONTH FROM DATA_PROTOCOLO) = :V_MES AND EXTRACT(YEAR FROM DATA_PROTOCOLO) = :ANO
        --GROUP BY :V_MES, 1
        INTO :MES_ID, :TIPO_ID, :valor
        DO
        BEGIN
            V_SALDO = V_SALDO + :VALOR;
            SUSPEND;
        END
        SELECT :V_MES, 2, ROUND(COALESCE(SUM(COALESCE(VALOR,0)),0),2) FROM  c_balanco_mensal(:V_DATA_INI,:REGISTRADOS_RI, :V_SELOS_ANTIGO )
        WHERE TIPO = 'D'
        INTO :MES_ID, :TIPO_ID, :VALOR ;
        V_SALDO = V_SALDO - :VALOR;
        SUSPEND;
        MES_ID = :V_MES;
        VALOR = :V_SALDO;
        TIPO_ID = 3;
        NATUREZA = NULL;
        SUSPEND;
        V_MES = V_MES + 1;
        V_SALDO = 0;
    END
END ^

ALTER PROCEDURE C_BALANCO_DF (V_TIPO_BALANCO VARCHAR(2) CHARACTER SET ISO8859_1,
V_DATA VARCHAR(15) CHARACTER SET ISO8859_1 = '',
V_MES INTEGER = 0,
V_ANO INTEGER = 0)
RETURNS (TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_TERCEIRO NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TIPO_RETORNO VARCHAR(1) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(260) CHARACTER SET ISO8859_1,
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
SALDO_DP_MES_ANTERIOR NUMERIC(18, 2),
MENSAGEM_ERRO VARCHAR(300) CHARACTER SET ISO8859_1,
ANO INTEGER,
MES INTEGER,
MES_STRING VARCHAR(50) CHARACTER SET ISO8859_1,
TOTAL_REPASSE NUMERIC(18, 2),
TOTAL_LIQUIDO NUMERIC(18, 2),
TOTAL_DESPESA_DEDUTIVEL NUMERIC(18, 2),
TOTAL_DESPESA_NAO_DEDUTIVEL NUMERIC(18, 2))
AS 
DECLARE VARIABLE V_TIPO_RETORNO INTEGER;
  DECLARE VARIABLE V_DATA_INI DATE;
  DECLARE VARIABLE V_DATA_FIM DATE;
  DECLARE VARIABLE V_ANO_INFORMADO INTEGER;
  DECLARE VARIABLE V_MES_INFORMADO INTEGER;
  DECLARE VARIABLE V_DIA_INFORMADO INTEGER;
  DECLARE VARIABLE V_DATA_POSTERIOR DATE;
  declare variable V_NUMERO_ORDEM_INI INTEGER;
  declare variable V_DEPOSITO_INI DINHEIRO;
  declare variable V_SAIDA_INI DINHEIRO;
  declare variable V_DEPOSITO_PREVIO_MENSAL_ID INTEGER;
  declare variable V_SALDO_INI DINHEIRO;
  declare variable V_QTDE_LOGADO INTEGER;
  declare variable V_DIA_TEMP INTEGER;
BEGIN
  IF ((:V_MES > 0) AND (:V_ANO > 0)) THEN
  BEGIN
    SELECT ULTIMO_DIA FROM W_ULTIMO_DIA_MES(:V_MES, :V_ANO)
    INTO :V_DIA_INFORMADO;
    V_MES_INFORMADO = :V_MES;
    V_ANO_INFORMADO = :V_ANO;
  END
  ELSE
  BEGIN
    SELECT EXTRACT(DAY FROM CAST(:V_DATA AS DATE)), EXTRACT(MONTH FROM CAST(:V_DATA AS DATE)), EXTRACT(YEAR FROM CAST(:V_DATA AS DATE)) FROM RDB$DATABASE
    INTO :V_DIA_INFORMADO, :V_MES_INFORMADO, :V_ANO_INFORMADO;
  END

  MENSAGEM_ERRO = '';
  SALDO_DP_MES_ANTERIOR = 0;
  ANO = :V_ANO_INFORMADO;
  MES_STRING = '';

  V_TIPO_RETORNO = null;
  TOTAL_DESPESA = 0;
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_BRUTO = 0;
  TOTAL_TERCEIRO = 0;

  --VER SE EH NECESSÁRIO INICIALIZAR CADASTRO DE SALDOS DE DEPOSITOS PRÉVIOS -- SO IRA CALCULAR CORRETAMENTE APARTIR DE 01/12/2017
  IF (:V_TIPO_BALANCO = 'MP') THEN -- MENSAL DEPOSITO PREVIO
  BEGIN
    MES = :V_MES_INFORMADO;
    SELECT COUNT(*) FROM C_DEPOSITO_PREVIO_MENSAL
    INTO :V_QTDE_LOGADO;
    if (:V_QTDE_LOGADO = 0) then --É necessário inicializar
    begin
      select first 1 pr.numero_ordem
      from r_pedido_item Pi, r_protocolo pr
      where pi.pedido_id = pr.pedido_id
      and pr.tipo_protocolo = '1'
      and PR.DATA BETWEEN CAST('01.11.2017' AS TIMESTAMP)
                      AND CAST('30.11.2017' AS TIMESTAMP)+ 0.9999
      ORDER BY PR.NUMERO_ORDEM
      into :v_numero_ordem_ini;

      select sum((coalesce(pi.valor_emolumento,0) + coalesce(pi.valor_taxa_judiciaria,0) + coalesce(pi.valor_fundo_ri,0)) - coalesce(pi.valor_desconto,0))
      from r_pedido_item pi, r_protocolo pr
      where pi.pedido_id = pr.pedido_id
      and pr.tipo_protocolo = '1'
      and pr.numero_ordem > (:v_numero_ordem_ini - 1)
      and PR.DATA BETWEEN CAST('01.11.2017' AS TIMESTAMP)
                      AND CAST('30.11.2017' AS TIMESTAMP)+ 0.9999
      INTO :V_DEPOSITO_INI;

      V_DEPOSITO_INI = (:V_DEPOSITO_INI * 0.75);

      select sum((coalesce(pi.valor_emolumento,0) + coalesce(pi.valor_taxa_judiciaria,0) + coalesce(pi.valor_fundo_ri,0)) - coalesce(pi.valor_desconto,0))
      FROM R_PROTOCOLO PR, R_PEDIDO_ITEM PI, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
      WHERE PR.PEDIDO_ID = PI.PEDIDO_ID
      AND PI.PEDIDO_ID = A.PEDIDO_ID
      AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND PR.TIPO_PROTOCOLO = '1'
      and pr.numero_ordem > (:v_numero_ordem_ini - 1)
      AND ((TA.TIPO = 'R') OR (TA.TIPO = 'C'))--REGISTRADOS OU CANCELADOS
      and A.DATA BETWEEN CAST('01.11.2017' AS TIMESTAMP)
                     AND CAST('30.11.2017' AS TIMESTAMP)+ 0.9999
      INTO :V_SAIDA_INI;
      V_SAIDA_INI = (:V_SAIDA_INI * 0.75);

      V_SALDO_INI = (:V_DEPOSITO_INI - :V_SAIDA_INI);

      SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('C_DEPOSITO_PREVIO_MENSAL')
      INTO :V_DEPOSITO_PREVIO_MENSAL_ID;

      INSERT INTO c_deposito_previo_mensal(DEPOSITO_PREVIO_MENSAL_ID, DATA_INICIAL, DATA_FINAL, MES, ANO, SALDO_FINAL_MES, PROTOCOLO_INICIAL)
      VALUES(:V_DEPOSITO_PREVIO_MENSAL_ID, '01.11.2017', '30.11.2017', '11', '2017',:V_SALDO_INI, :v_numero_ordem_ini);
    end
    if (:v_mes_informado = 1) then
    begin
      select SALDO_FINAL_MES
      from C_DEPOSITO_PREVIO_MENSAL
      where mes = 12
      and ano = :V_ANO_INFORMADO - 1
      into :SALDO_DP_MES_ANTERIOR;
    end
    else
    begin
      select SALDO_FINAL_MES from C_DEPOSITO_PREVIO_MENSAL
      where mes = :V_MES_INFORMADO - 1
      and ano = :V_ANO_INFORMADO
      into :SALDO_DP_MES_ANTERIOR;
    end
    if (:SALDO_DP_MES_ANTERIOR = 0) then
    begin
      MENSAGEM_ERRO = 'Não existe saldo anterior calculado. VERIFIQUE.';
    end
  end
  --FIM INICIALIZAÇÃO CADASTRO

  IF (:V_TIPO_BALANCO = 'DP') THEN -- DIÁRIO deposito prévio
  BEGIN
    MES = :V_MES_INFORMADO;
    V_DATA_INI = CAST(:V_DATA AS DATE);
    V_DATA_FIM = CAST(:V_DATA AS DATE);
  END
  ELSE IF ((:V_TIPO_BALANCO = 'M') OR (:V_TIPO_BALANCO = 'MP') OR (:V_TIPO_BALANCO = 'E') ) THEN -- MENSAL
  BEGIN
    MES = :V_MES_INFORMADO;
    IF (:V_MES_INFORMADO < 10) THEN
    BEGIN
      V_DATA_INI = '01.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END
    ELSE
    BEGIN
      V_DATA_INI = '01.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END

    IF (:V_MES_INFORMADO < 10) THEN
    BEGIN
      V_DATA_FIM = V_DIA_INFORMADO||'.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END
    ELSE
    BEGIN
      V_DATA_FIM = V_DIA_INFORMADO||'.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END
  END
  ELSE IF (:V_TIPO_BALANCO = 'A')  THEN -- ANUAL
  BEGIN
    V_DATA_INI = '01.01.'||:V_ANO_INFORMADO;
    V_DATA_FIM = CAST(:V_DATA AS DATE);
  END

  IF (:V_TIPO_BALANCO = 'E') THEN -- Extrato mensal
  BEGIN
    FOR SELECT TIPO_RETORNO, SUM(COALESCE(TOTAL_DESPESA,0)),
      SUM(COALESCE(TOTAL_EMOLUMENTO,0)), SUM(COALESCE(TOTAL_TAXA_JUDICIARIA,0)), SUM(COALESCE(TOTAL_FUNDO,0)), SUM(COALESCE(QTDE,0)),
      SUM(COALESCE(TOTAL_EMOLUMENTO_REG,0)), SUM(COALESCE(TOTAL_TAXA_REG,0)), SUM(COALESCE(TOTAL_FUNDO_REG,0)), SUM(COALESCE(QTDE_REG,0)),
      SUM(COALESCE(TOTAL_EMOLUMENTO_AV,0)), SUM(COALESCE(TOTAL_TAXA_AV,0)), SUM(COALESCE(TOTAL_FUNDO_AV,0)), SUM(COALESCE(QTDE_AV,0)),
      SUM(COALESCE(TOTAL_EMOLUMENTO_CERT,0)), SUM(COALESCE(TOTAL_TAXA_CERT,0)), SUM(COALESCE(TOTAL_FUNDO_CERT,0)), SUM(COALESCE(QTDE_CERT,0)),
      SUM(COALESCE(TOTAL_EMOLUMENTO_BUSCA,0)), SUM(COALESCE(TOTAL_TAXA_BUSCA,0)), SUM(COALESCE(TOTAL_FUNDO_BUSCA,0)), SUM(COALESCE(QTDE_BUSCA,0)),
      SUM(COALESCE(TOTAL_EMOLUMENTO_REVAL,0)), SUM(COALESCE(TOTAL_TAXA_REVAL,0)), SUM(COALESCE(TOTAL_FUNDO_REVAL,0)), SUM(COALESCE(QTDE_REVAL,0))
      FROM C_DIARIO_AUX_RECEITA_DESPESA_DF(:V_DATA_INI, :V_DATA_FIM,'',0)
      GROUP BY TIPO_RETORNO
      INTO :V_TIPO_RETORNO, :TOTAL_DESPESA,
        :TOTAL_EMOLUMENTO, :TOTAL_TAXA_JUDICIARIA, :TOTAL_FUNDO, :QTDE,
        :TOTAL_EMOLUMENTO_REG, :TOTAL_TAXA_REG, :TOTAL_FUNDO_REG, :QTDE_REG,
        :TOTAL_EMOLUMENTO_AV, :TOTAL_TAXA_AV, :TOTAL_FUNDO_AV, :QTDE_AV,
        :TOTAL_EMOLUMENTO_CERT, :TOTAL_TAXA_CERT, :TOTAL_FUNDO_CERT, :QTDE_CERT,
        :TOTAL_EMOLUMENTO_BUSCA, :TOTAL_TAXA_BUSCA, :TOTAL_FUNDO_BUSCA, :QTDE_BUSCA,
        :TOTAL_EMOLUMENTO_REVAL, :TOTAL_TAXA_REVAL, :TOTAL_FUNDO_REVAL, :QTDE_REVAL  DO
    BEGIN
      TOTAL_REPASSE = 0;
      TIPO_RETORNO = 'C';
      IF (:V_TIPO_RETORNO = 1) THEN
      BEGIN
        DESCRICAO = 'Prenotação - Reg./Av. (25%)';
      END
      ELSE IF (:V_TIPO_RETORNO = 2) THEN
      BEGIN
        DESCRICAO = 'Prenotação - Reg./Av. (Penhora e-RIDFT) (25%)';
      END
      ELSE IF (:V_TIPO_RETORNO = 3) THEN
      BEGIN
        DESCRICAO = 'Alienação Fiduciária (e-RIDFT)';
      END
      ELSE IF (:V_TIPO_RETORNO = 4) THEN
      BEGIN
        DESCRICAO = 'Registro/Averbação - (75%)';
      END
      ELSE IF (:V_TIPO_RETORNO = 5) THEN
      BEGIN
        DESCRICAO = 'Registro/Averbação - (Penhora e-RIDFT) (75%)';
      END
      ELSE IF (:V_TIPO_RETORNO = 7) THEN
      BEGIN
        DESCRICAO = 'Certidão - (Solicitadas no cartório)';
      END
      ELSE IF (:V_TIPO_RETORNO = 8) THEN
      BEGIN
        DESCRICAO = 'Certidão - (Solicitadas através da Central de Cert.)';
      END
      ELSE IF (:V_TIPO_RETORNO = 9) THEN
      BEGIN
        DESCRICAO = 'Certidão - (Solicitadas no e-RIDFT)';
      END
      ELSE IF (:V_TIPO_RETORNO = 10) THEN
      BEGIN
        DESCRICAO = 'Alienação Fiduciária (Balcão)';
      END
      ELSE IF (:V_TIPO_RETORNO = 777) THEN
      BEGIN
        DESCRICAO = 'Despesas';
        TIPO_RETORNO = 'D';
      END
      ELSE IF (:V_TIPO_RETORNO = 888) THEN
      BEGIN
        DESCRICAO = 'Repasses';
        TIPO_RETORNO = 'R';
        TOTAL_REPASSE = :TOTAL_DESPESA;
      END
      ELSE IF (:V_TIPO_RETORNO = 666) THEN
      BEGIN
        DESCRICAO = 'Despesas não dedutíveis';
        TIPO_RETORNO = 'D';
      END
      select UPPER(mes_em_string) from w_mes_string(:mes)
      into :MES_STRING;
      SUSPEND;
    END
  END
  ELSE IF (:V_TIPO_BALANCO = 'M') THEN -- mensal
  BEGIN
    SELECT SUM(COALESCE(TOTAL_BRUTO,0)),SUM(COALESCE(TOTAL_DESPESA,0)),SUM(COALESCE(TOTAL_FUNDO,0)),0,
          SUM(COALESCE(TOTAL_EMOLUMENTO,0)),SUM(COALESCE(TOTAL_DESPESA,0)),
         (SUM(COALESCE(TOTAL_BRUTO,0)) - SUM(COALESCE(TOTAL_DESPESA,0))) AS TOTAL_LIQUIDO
    FROM C_DIARIO_AUX_RECEITA_DESPESA_DF(:V_DATA_INI, :V_DATA_FIM,'',0)
    INTO :TOTAL_BRUTO, :TOTAL_DESPESA, :TOTAL_FUNDO, :TOTAL_TERCEIRO, :TOTAL_EMOLUMENTO, :TOTAL_DESPESA, :TOTAL_LIQUIDO;
    TIPO_RETORNO = 'C';
    select UPPER(mes_em_string) from w_mes_string(:mes)
    into :MES_STRING;
    SUSPEND;
  END
  ELSE IF (:V_TIPO_BALANCO = 'A') THEN -- ANUAL
  BEGIN
    MES = 1;
    while (:mes <= :v_mes_informado) do
    begin
      if (:mes = :v_mes_informado) then
      begin
        V_DIA_TEMP = :V_DIA_INFORMADO;
      end
      else
      begin
        SELECT ULTIMO_DIA FROM W_ULTIMO_DIA_MES(:mes,:V_ANO_INFORMADO)
        into :V_DIA_TEMP;
      end

      IF (:MES < 10) THEN
      BEGIN
        V_DATA_INI = '01.0'||:MES||'.'||:V_ANO_INFORMADO;
      END
      ELSE
      BEGIN
        V_DATA_INI = '01.'||:MES||'.'||:V_ANO_INFORMADO;
      END

      IF (:MES < 10) THEN
      BEGIN
        V_DATA_FIM = V_DIA_TEMP||'.0'||:MES||'.'||:V_ANO_INFORMADO;
      END
      ELSE
      BEGIN
        V_DATA_FIM = V_DIA_TEMP||'.'||:MES||'.'||:V_ANO_INFORMADO;
      END

      select UPPER(mes_em_string) from w_mes_string(:mes)
      into :MES_STRING;

      SELECT SUM(COALESCE(TOTAL_BRUTO,0)),SUM(COALESCE(TOTAL_DESPESA,0)),SUM(COALESCE(TOTAL_FUNDO,0)),0,
          SUM(COALESCE(TOTAL_EMOLUMENTO,0)),SUM(COALESCE(TOTAL_DESPESA,0)),
         (SUM(COALESCE(TOTAL_BRUTO,0)) - SUM(COALESCE(TOTAL_DESPESA,0))) AS TOTAL_LIQUIDO
      FROM C_DIARIO_AUX_RECEITA_DESPESA_DF(:V_DATA_INI, :V_DATA_FIM, '',0)
      INTO :TOTAL_BRUTO, :TOTAL_DESPESA, :TOTAL_FUNDO, :TOTAL_TERCEIRO, :TOTAL_EMOLUMENTO, :TOTAL_DESPESA, :TOTAL_LIQUIDO;
      TIPO_RETORNO = 'C';
      SUSPEND;

      MES = (:MES + 1);
    END
  END
  ELSE
  BEGIN
    FOR SELECT SUM(COALESCE(TOTAL_BRUTO,0)), SUM(COALESCE(TOTAL_EMOLUMENTO,0)), SUM(COALESCE(TOTAL_TAXA_JUDICIARIA,0)),
      SUM(COALESCE(TOTAL_FUNDO,0)), SUM(COALESCE(TOTAL_DESPESA,0)), TIPO_RETORNO
      FROM C_DEPOSITO_PREVIO_DF(:V_DATA_INI,:V_DATA_FIM,0)
      GROUP BY TIPO_RETORNO
      INTO :TOTAL_BRUTO, :TOTAL_EMOLUMENTO, :TOTAL_TAXA_JUDICIARIA, :TOTAL_FUNDO,
        :TOTAL_DESPESA, :V_TIPO_RETORNO DO
    BEGIN
      TOTAL_REPASSE = 0;
      TIPO_RETORNO = 'C';
      IF (:V_TIPO_RETORNO = 1) THEN
      BEGIN
        DESCRICAO = 'Depósito prévio 75%';
      END
      ELSE IF (:V_TIPO_RETORNO = 2) THEN
      BEGIN
        DESCRICAO = 'Saída - Conversão depósito em receita';
        TIPO_RETORNO = 'D';
      END
      ELSE IF (:V_TIPO_RETORNO = 3) THEN
      BEGIN
        DESCRICAO = 'Saída - Devolução ao usuário';
        TIPO_RETORNO = 'D';
      END
      ELSE IF (:V_TIPO_RETORNO = 4) THEN
      BEGIN
        DESCRICAO = 'Saída - Devolução à Vara de Reg. Públicos';
        TIPO_RETORNO = 'D';
      END
      select mes_em_string from w_mes_string(:mes)
      into :MES_STRING;
      SUSPEND;
    END
  END
END ^

ALTER PROCEDURE C_BALANCO_MENSAL (V_DATA DATE,
V_REGISTRADOS_RI VARCHAR(1) CHARACTER SET ISO8859_1,
V_SELOS_ANTIGO VARCHAR(1) CHARACTER SET ISO8859_1 = 'N')
RETURNS (CAIXA_SERVICO_ID INTEGER,
GRUPO VARCHAR(600) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(3000) CHARACTER SET ISO8859_1,
VALOR NUMERIC(18, 4),
TIPO VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
declare variable V_DATA_VAR varchar(20);
declare variable INICIO_MES_ANT date;
declare variable FINAL_MES_ANT date;
declare variable INICIO_MES date;
declare variable FINAL_MES date;
declare variable VALOR_RECEITAS numeric(18,4);
declare variable VALOR_DESPESAS numeric(18,4);
declare variable SOMA_AUXILIAR numeric(18,4);
declare variable V_DATA_AUX date;
declare variable V_DATA_PARAM_INICIO_PROVIMENTO date;
declare variable V_DATA_PARAM_NOVO_SELO date;
declare variable V_DATA_PARAM_FINAL_MES date;
declare variable V_MES_PARAM_INICIO_PROVIMENTO numeric(18,4);
declare variable V_UTILIZAR_SALDO_MES_ANTERIOR varchar(30);
declare variable V_USAR_ANTIGO varchar(10);
BEGIN

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'DATA_SELO_NOVO', 5)
  INTO :V_DATA_VAR;

  V_DATA_PARAM_NOVO_SELO = :V_DATA;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'RELATORIO', 'DATA_INICIO_PROVIMENTO_34', 5)
  INTO :v_data_param_inicio_provimento;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'LIVRO_DIARIO_AUXILIAR', 'UTILIZAR_SALDO_MES_ANTERIOR', 5)
  INTO :v_utilizar_saldo_mes_anterior;

  SELECT :v_data_param_inicio_provimento - EXTRACT(DAY FROM :v_data_param_inicio_provimento) + 32 - EXTRACT(DAY FROM :v_data_param_inicio_provimento - EXTRACT(DAY FROM :v_data_param_inicio_provimento) + 32)
  FROM RDB$DATABASE INTO :v_data_param_final_mes;

  V_USAR_ANTIGO = 'N';
  v_mes_param_inicio_provimento = EXTRACT(MONTH FROM :v_data_param_inicio_provimento);

    IF ((EXTRACT(MONTH FROM :V_DATA) = v_mes_param_inicio_provimento + 1) AND (EXTRACT(YEAR FROM :V_DATA) = 2013)) THEN
    BEGIN
        --O SALDO ANTERIOR DO MÊS 08/2013, DEVERÁ SER APURADO A PARTIR DE 12/07/2013
        INICIO_MES_ANT =  :v_data_param_inicio_provimento;
        FINAL_MES_ANT  =  :v_data_param_final_mes;
        --INICIO E FINAL DO MÊS ATUAL
        INICIO_MES = :V_DATA;
        SELECT :INICIO_MES - EXTRACT(DAY FROM :INICIO_MES) + 32 - EXTRACT(DAY FROM :INICIO_MES - EXTRACT(DAY FROM :INICIO_MES) + 32)
        FROM RDB$DATABASE INTO :FINAL_MES; -- Último dia do mês anterior
    END
    ELSE IF ((EXTRACT(MONTH FROM :V_DATA) = v_mes_param_inicio_provimento) AND (EXTRACT(YEAR FROM :V_DATA) = 2013)) THEN
    BEGIN
        --O MÊS 07/2013 NÃO TEM SALDO ANTERIOR - PARA ISSO EU SETO UMA DATA NULA
        INICIO_MES_ANT = '12/31/1899';
        FINAL_MES_ANT  = '12/31/1899';
        --O SALDO DO MÊS 07/2013 DEVERÁ SER APURADO A PARTIR DE 12/07/2013
        INICIO_MES =  :v_data_param_inicio_provimento;
        FINAL_MES  =  :v_data_param_final_mes;
    END
    --ANULA AS DATAS QUANDO MÊS < 07
    ELSE IF ((EXTRACT(MONTH FROM :V_DATA) < v_mes_param_inicio_provimento) AND (EXTRACT(YEAR FROM :V_DATA) = 2013)) THEN
    BEGIN
        INICIO_MES_ANT = '12/31/1899';
        FINAL_MES_ANT  = '12/31/1899';
        INICIO_MES = '12/31/1899';
        FINAL_MES  = '12/31/1899';
    END
    --OS DEMAIS MESES CALCULA AS DATAS NORMALMENTE
    ELSE                                          
    BEGIN
      IF ((EXTRACT(MONTH FROM :V_DATA) <= LEFT(V_DATA_VAR,2)) AND (EXTRACT(YEAR FROM :V_DATA) <= right(V_DATA_VAR,4))) THEN
      BEGIN
        V_USAR_ANTIGO = 'S';
      END
      --PEGA DATA INICIAL E FINAL DO MÊS ANTERIOR NORMALMENTE
      SELECT DATEADD(MONTH, -1, :V_DATA) FROM RDB$DATABASE INTO :INICIO_MES_ANT; -- PRIMEIRO DIA DI MÊS ANTERIOR
      SELECT :INICIO_MES_ANT - EXTRACT(DAY FROM :INICIO_MES_ANT) + 32 - EXTRACT(DAY FROM :INICIO_MES_ANT - EXTRACT(DAY FROM :INICIO_MES_ANT) + 32)
      FROM RDB$DATABASE INTO :FINAL_MES_ANT; -- ÚLTIMO DIA DO MÊS ANTERIOR
      --INICIO E FINAL DO MÊS ATUAL
      INICIO_MES = :V_DATA;
      SELECT :INICIO_MES - EXTRACT(DAY FROM :INICIO_MES) + 32 - EXTRACT(DAY FROM :INICIO_MES - EXTRACT(DAY FROM :INICIO_MES) + 32)
      FROM RDB$DATABASE INTO :FINAL_MES; -- Último dia do mês anterior
    END

    if (coalesce(:V_USAR_ANTIGO,'') <> 'N') then
    begin
      SELECT  'PRESTAÇÃO DE CONTAS',
              'SALDO DE CAIXA (Remanescentes do mês anterior)',
              (SELECT ROUND(COALESCE(SUM(COALESCE(TOTAL_EMOLUMENTO,0)),0),2) FROM c_diario_auxiliar_receita(:INICIO_MES_ANT, :FINAL_MES_ANT, :V_REGISTRADOS_RI, :V_USAR_ANTIGO)) -
              (SELECT ROUND(COALESCE(SUM(COALESCE(TOTAL_DESPESA,0)),0),2) FROM c_diario_auxiliar_despesa(:INICIO_MES_ANT, :FINAL_MES_ANT)),
              NULL
              FROM RDB$DATABASE
              INTO
              :GRUPO,
              :DESCRICAO,
              :VALOR,
              :TIPO;
      SUSPEND;
    end

    if (coalesce(:V_USAR_ANTIGO,'') = 'S') then
    begin
        SELECT  'PRESTAÇÃO DE CONTAS',
                'RECEITA DO MÊS (Emolumentos + Aplicações Financeiras)',
                (SELECT ROUND(COALESCE(SUM(COALESCE(TOTAL_EMOLUMENTO,0)),0),2)  FROM c_diario_auxiliar_receita(:INICIO_MES, :FINAL_MES, :V_REGISTRADOS_RI, :V_USAR_ANTIGO))+ --PEGA OS VALORES EM G_SELO_LIVRO_ANTIGO
                (SELECT ROUND(COALESCE(SUM(COALESCE(TOTAL_EMOLUMENTO,0)),0),2)  FROM c_diario_auxiliar_receita(:V_DATA_PARAM_NOVO_SELO, :FINAL_MES, :V_REGISTRADOS_RI, 'N')), --PEGA OS VALORES EM G_SELO_LIVRO
                'C'
                FROM RDB$DATABASE
                INTO
                :GRUPO,
                :DESCRICAO,
                :VALOR,
                :TIPO;
        SUSPEND;
    END
    ELSE
    BEGIN
      for SELECT 'PRESTAÇÃO DE CONTAS',
             'RECEITA DO MÊS (Emolumentos + Aplicações Financeiras)',
             (SELECT ROUND(COALESCE(SUM(COALESCE(TOTAL_EMOLUMENTO,0)),0),2)  FROM c_diario_auxiliar_receita(:INICIO_MES, :FINAL_MES, :V_REGISTRADOS_RI, 'N')),
             'C'
             FROM RDB$DATABASE
             INTO
             :GRUPO,
             :DESCRICAO,
             :VALOR,
             :TIPO
            DO
            BEGIN
               select ROUND(COALESCE(SUM(COALESCE(valor_emolumento,0)),0),2)
                     FROM g_selo_livro where cast(data_inutilizacao as date)
                     between :INICIO_MES and :FINAL_MES
               into :SOMA_AUXILIAR;
                VALOR = ROUND(:valor-:SOMA_AUXILIAR,2);
                SUSPEND;
            END
    END

    FOR SELECT  DISTINCT(DESCRICAO_SERVICO),
            'DESPESAS',                 
            ROUND(COALESCE(SUM(COALESCE(TOTAL_DESPESA,0)),0),2),
            'D',
            SERVICO_CAIXA_ID
            FROM c_diario_auxiliar_despesa(:INICIO_MES, :FINAL_MES)
            GROUP BY DESCRICAO_SERVICO,SERVICO_CAIXA_ID
            INTO
            :DESCRICAO,
            :GRUPO,
            :valor, 
            :TIPO,
            :caixa_servico_id DO
    BEGIN
        SUSPEND;
    END

      FOR SELECT  DISTINCT(DESCRICAO_SERVICO),
            'REMUNERAÇÃO INTERINO',
            ROUND(COALESCE(SUM(COALESCE(TOTAL_DESPESA,0)),0),2),
            'D',
            SERVICO_CAIXA_ID
            FROM C_DIARIO_DESPESA_INTERINO(:INICIO_MES, :FINAL_MES)
            GROUP BY DESCRICAO_SERVICO,SERVICO_CAIXA_ID
            INTO
            :DESCRICAO,
            :GRUPO,
            :valor, 
            :TIPO,
            :caixa_servico_id DO
    BEGIN
        SUSPEND;
    END

END ^

ALTER PROCEDURE C_CAIXA_ATO (VPDATA VARCHAR(20) CHARACTER SET ISO8859_1)
RETURNS (VPCHAVE_REGISTRO VARCHAR(100) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE VCHAVE VARCHAR(20);
DECLARE VARIABLE VLISTA VARCHAR(1000);
DECLARE VARIABLE V_COUNT INTEGER;
DECLARE VARIABLE V_SQL VARCHAR(5000);
BEGIN
  SELECT COUNT(*) FROM RDB$RELATIONS
  WHERE RDB$SYSTEM_FLAG = 0
  AND RDB$RELATION_NAME = 'T_ATO'
  INTO :V_COUNT;
  IF (:V_COUNT > 0) THEN --SE TIVER tabelionato
  BEGIN
    VLISTA = '';
    V_SQL = ' SELECT ATO_ID FROM T_ATO
        WHERE DATA_LAVRATURA BETWEEN CAST('||''''||:VPDATA||''''||' AS TIMESTAMP)
                                 AND CAST('||''''||:VPDATA||''''||' AS TIMESTAMP) + 0.9999
          AND NOT ATO_ID IN (SELECT CHAVE_SERVICO FROM C_CAIXA_ITEM WHERE CAIXA_SERVICO_ID = 7 OR CAIXA_SERVICO_ID = 19) ';
    FOR EXECUTE STATEMENT :V_SQL
    INTO :VCHAVE DO
    BEGIN
      if (:VLISTA = '') then
           VLISTA = VCHAVE;
      ELSE VLISTA = VLISTA || ', ' || VCHAVE;
    END
    VPCHAVE_REGISTRO = VLISTA;
    SUSPEND;
  END
END ^

ALTER PROCEDURE C_CALCULO_FUNDO_ISS_DF (V_DATA_INICIAL DATE,
V_DATA_FINAL DATE)
RETURNS (VALOR_EMOLUMENTO DINHEIRO,
VALOR_FUNDO DINHEIRO,
VALOR_ISS DINHEIRO,
VALOR_PAGO DINHEIRO)
AS 
DECLARE VARIABLE V_VALOR_AUXILIAR DINHEIRO;

BEGIN
  SELECT ROUND(SUM(COALESCE(VALOR_PAGO,0)),2) FROM C_CAIXA_ITEM
  WHERE CAST(DATA_PAGAMENTO AS DATE) BETWEEN :V_DATA_INICIAL AND :V_DATA_FINAL
  AND TIPO_TRANSACAO = 'C'
  INTO :VALOR_PAGO;

  V_VALOR_AUXILIAR = ROUND((:VALOR_PAGO/1.05),2); -- TOTAL SEM ISS
  VALOR_ISS = :VALOR_PAGO - :V_VALOR_AUXILIAR; -- ISS DIFERENÇA ENTRE VALOR TOTAL E O VALOR AUXILIAR
  VALOR_EMOLUMENTO = ROUND(:V_VALOR_AUXILIAR/1.07,2); -- VALOR EMOLUMENTO
  VALOR_FUNDO =  :V_VALOR_AUXILIAR - :VALOR_EMOLUMENTO; -- DIFERENÇA ENTRE O VALOR AUXILIAR E O EMOLUMENTO

 SUSPEND;
END ^

ALTER PROCEDURE C_CORRIGE_SELO_LIVRO (DATA_INICIAL_LOTE VARCHAR(20) CHARACTER SET ISO8859_1,
DATA_FINAL_LOTE VARCHAR(20) CHARACTER SET ISO8859_1)
RETURNS (SELO_LOTE_ID INTEGER,
NUMERO_SELO VARCHAR(10) CHARACTER SET ISO8859_1,
DESCRICAO_SELO VARCHAR(260) CHARACTER SET ISO8859_1,
SIGLA VARCHAR(30) CHARACTER SET ISO8859_1,
QTDE_EXISTENTE INTEGER,
QTDE_CORRETA INTEGER,
STATUS VARCHAR(20) CHARACTER SET ISO8859_1)
AS 
declare variable V_QTDE_GERAR INTEGER;
  declare variable V_MAIOR_NUMERO INTEGER;
  declare variable V_QTDE_GERADA INTEGER;
BEGIN
  FOR SELECT lt.selo_lote_id, SG.numero, SG.descricao, LT.SIGLA, LT.quantidade,
        (select count(*) from g_selo_livro where selo_lote_id = lt.selo_lote_id),
        (select max(numero) from g_selo_livro where selo_lote_id = lt.selo_lote_id)
      FROM G_SELO_LOTE LT, G_SELO_GRUPO SG
      WHERE LT.SELO_GRUPO_ID = SG.SELO_GRUPO_ID
      AND LT.SITUACAO <> 'R'
      AND CAST(LT.data_lote AS DATE) BETWEEN :DATA_INICIAL_LOTE AND :DATA_FINAL_LOTE
      INTO :SELO_LOTE_ID, :NUMERO_SELO, :DESCRICAO_SELO, :SIGLA, :QTDE_CORRETA, :QTDE_EXISTENTE, :V_MAIOR_NUMERO DO
  BEGIN
    V_QTDE_GERADA = 0;
    if (:QTDE_CORRETA > :QTDE_EXISTENTE) then
    BEGIN
      if ((:V_MAIOR_NUMERO + 1) = :QTDE_EXISTENTE) then
      BEGIN
        V_QTDE_GERAR = QTDE_CORRETA - QTDE_EXISTENTE;
        V_QTDE_GERADA = 0;
        WHILE (:V_QTDE_GERAR > 0) DO
        BEGIN
          INSERT INTO G_SELO_LIVRO(SELO_LIVRO_ID, SELO_SITUACAO_ID, NUMERO, SELO_LOTE_ID, NUMERO_SELO, SIGLA)
          VALUES((SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('G_SELO_LIVRO')), 1, (:V_MAIOR_NUMERO + 1), :SELO_LOTE_ID, :NUMERO_SELO, :SIGLA);
          V_MAIOR_NUMERO = :V_MAIOR_NUMERO + 1;
          V_QTDE_GERAR = :V_QTDE_GERAR - 1;
          V_QTDE_GERADA = :V_QTDE_GERADA + 1;
        END
      END
    END
    STATUS = 'QTDE INSERIDA: '||:V_QTDE_GERADA;
    SUSPEND;
  END
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (TIPO_LIVRO VARCHAR(50) CHARACTER SET ISO8859_1,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
QTDE_REVAL INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
PROTOCOLO_ANTERIOR INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
declare variable VSEQ INTEGER;
declare variable VORDEM INTEGER;
BEGIN
 /* if (:V_DATA_FIM = '31.03.2024') then
  begin
    V_DATA_FIM = '17.03.2024';
  end*/

  FOR SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'ENTRADAS (DEPÓSITO PRÉVIO)', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_ENTRADA(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  UNION ALL
  SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'ENTRADAS (DEPÓSITO PRÉVIO)', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_APROVEITA(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  UNION ALL
  SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'ENTRADAS (DEPÓSITO PRÉVIO)', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_COMP_NOVO(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  UNION ALL
  SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'SAÍDAS', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_SAIDA_100(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  UNION ALL
  SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'SAÍDAS', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_SAIDA_25(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  UNION ALL
  SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'SAÍDAS', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_DEVOLUCAO(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  ORDER BY 1, 2, 3
  INTO :DATA, :TIPO_RETORNO, :NUMERO_PROTOCOLO, :SISTEMA_ID, :ID, :DATA_HORA, :TIPO_PROTOCOLO, :NATUREZA, :DESCRICAO,
    :TOTAL_EMOLUMENTO, :TOTAL_TAXA_JUDICIARIA, :TOTAL_FUNDO, :TOTAL_DESPESA,
    :TOTAL_BRUTO, :TOTAL_DESCONTO, :TOTAL_COMPENSADO, :QTDE, :TOTAL_EMOLUMENTO_REG, :TOTAL_TAXA_REG,
    :TOTAL_FUNDO_REG, :QTDE_REG, :TOTAL_EMOLUMENTO_AV, :TOTAL_TAXA_AV, :TOTAL_FUNDO_AV, :QTDE_AV,
    :TOTAL_EMOLUMENTO_CERT, :TOTAL_TAXA_CERT, :TOTAL_FUNDO_CERT, :QTDE_CERT, :TOTAL_EMOLUMENTO_BUSCA,
    :TOTAL_TAXA_BUSCA, :TOTAL_FUNDO_BUSCA, :QTDE_BUSCA, :TOTAL_EMOLUMENTO_REVAL, :TOTAL_TAXA_REVAL,
    :TOTAL_FUNDO_REVAL, :QTDE_REVAL, :MES, :ANO, :TOTAL_EMOLUMENTO_FOLHA, :TOTAL_TAXA_FOLHA,
    :TOTAL_FUNDO_FOLHA, :QTDE_FOLHA,  :PROTOCOLO_ANTERIOR, :TIPO_LIVRO, :NUMERO_ONLINE, :TOTAL_ISS, :TOTAL_GERAL_COM_ISS DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_100 (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER)
AS 
declare variable V_VALOR_EMOLUMENTO numeric(18,2);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(18,2);
declare variable V_VALOR_FUNDO numeric(18,2);
declare variable V_VALOR_BRUTO numeric(18,2);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_QTDE_REGISTRO integer;
declare variable V_QTDE_AVERBACAO integer;
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(1);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(1);
declare variable V_RETORNAR varchar(1);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_PROTOCOLO_ID integer;
declare variable V_CREDITO_INICIAL numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_DATA_PROT_TEMP date;
declare variable V_VALOR_COMPENSADO numeric(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_TOTAL_GERAL numeric(18,2);
declare variable V_TOTAL_GERAL_75 numeric(18,2);
BEGIN
  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  ORDEM = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    --INICIO REGISTRO DE IMOVEIS
    --REGISTRO DE IMOVEIS - SELECIONAR PROTOCOLADOS - ESCRITURACAO DE 100% - deposito
    TOTAL_EMOLUMENTO = 0;
    TOTAL_TAXA_JUDICIARIA = 0;
    TOTAL_FUNDO = 0;
    TOTAL_DESPESA = 0;

    TOTAL_BRUTO = 0;
    QTDE = 0;

    FOR SELECT CAST(PR.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          PE.TIPO_COBRANCA,
          (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
          (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
          PR.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
          EXTRACT(MONTH FROM PR.DATA),
          EXTRACT(YEAR FROM PR.DATA),
          pe.valor_compensado, pr.protocolo_id
        FROM R_PROTOCOLO PR, R_PEDIDO PE
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PR.TIPO_PROTOCOLO = '1'
        AND PR.PROTOCOLO_ID = :VP_PROTOCOLO_ID
        ORDER BY 1,2
        INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
          :V_TIPO_COBRANCA, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
          :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO, :V_VALOR_COMPENSADO, :V_PROTOCOLO_ID DO
    BEGIN
      if (:DATA > '30.04.2021') then
      begin
        V_QTDE_CONSOLIDACAO = 0;
        SISTEMA_ID = 1;
        TIPO_RETORNO = 1; --1=PRENOTACAO, DEPÓSITO PRÉVIO DE 100% RI/DF
  
        IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
        BEGIN
          V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
        END
        ELSE
        BEGIN
          SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
          WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
          AND I.PEDIDO_ID = :ID
          AND COALESCE(N.CONSOLIDACAO,'') = 'S'
          INTO :V_QTDE_CONSOLIDACAO;
    
          if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
          begin
            V_RETORNAR = 'N';
          end
          else
          begin
            V_RETORNAR = 'S';
          end
        END
        if (:V_RETORNAR = 'S') then
        begin
          SELECT FIRST 1 VALOR_PAGO FROM C_CAIXA_ITEM
          WHERE TIPO_SERVICO = :TIPO_PROTOCOLO
          AND CHAVE_SERVICO = :V_PROTOCOLO_ID
          AND tipo_transacao = 'C' --CREDITO
          ORDER BY DATA_PAGAMENTO
          INTO :V_VALOR_BRUTO;

          if (coalesce(:V_VALOR_COMPENSADO,0) > 0) then
          begin
            V_VALOR_BRUTO = (coalesce(:V_VALOR_BRUTO,0) + coalesce(:V_VALOR_COMPENSADO,0));
          end
    
          IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
          BEGIN
            NATUREZA = 'Registro/Averbação';
          END
          ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            NATUREZA = 'Averbação';
          END
          ELSE
          BEGIN
            NATUREZA = 'Registro';
          END    
    
          if (COALESCE(:V_VALOR_BRUTO,0) <= 0) then
          BEGIN
            V_VALOR_BRUTO = 0;
            V_VALOR_EMOLUMENTO = 0;
            V_VALOR_FUNDO = 0;
          END
          else
          begin
            V_VALOR_EMOLUMENTO = CAST(COALESCE((:V_VALOR_BRUTO * 0.9346),0) AS NUMERIC(18,2));
            V_VALOR_FUNDO = (:V_VALOR_BRUTO - :V_VALOR_EMOLUMENTO);
          end
          V_VALOR_TAXA_JUDICIARIA = 0;
    
          SELECT FIRST 1 N.DESCRICAO
          FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
          WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
          AND I.PEDIDO_ID = :ID
          ORDER BY SEQUENCIA
          INTO :V_NATUREZA_FORMAL;
    
          V_DESCRICAO = 'PROTOCOLO '||CAST(:NUMERO_PROTOCOLO AS VARCHAR(10))||' - [100%] - '||:V_NATUREZA_FORMAL;
          IF (:V_QTDE_REGISTRO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
          END
          IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
          END
          TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
          TOTAL_FUNDO = :V_VALOR_FUNDO;
          IF (:TOTAL_EMOLUMENTO < 0) THEN
          BEGIN
            TOTAL_EMOLUMENTO = 0;
            TOTAL_FUNDO = 0;
          END
          TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
          DESCRICAO = :V_DESCRICAO || ' (Dep.Prévio)';
    
          QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
          TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO;
  
          ORDEM = :ORDEM + 1;
  
          SUSPEND;
        END
      end
    END
  end
  else
  begin
    V_DATA_A_PESQUISAR = cast(:V_DATA_INI as date);
    WHILE (:V_DATA_A_PESQUISAR <= cast(:V_DATA_FIM as date)) DO
    BEGIN
      --INICIO REGISTRO DE IMOVEIS
      --REGISTRO DE IMOVEIS - SELECIONAR PROTOCOLADOS - ESCRITURACAO DE 100% - deposito
      TOTAL_EMOLUMENTO = 0;
      TOTAL_TAXA_JUDICIARIA = 0;
      TOTAL_FUNDO = 0;
      TOTAL_DESPESA = 0;
  
      TOTAL_BRUTO = 0;
      QTDE = 0;
  
      FOR SELECT CAST(PR.DATA AS DATE),
            PR.NUMERO_ORDEM,
            PR.PEDIDO_ID,
            PR.TIPO_PROTOCOLO,
            PE.TIPO_COBRANCA,
            (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
            (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
            PR.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
            EXTRACT(MONTH FROM PR.DATA),
            EXTRACT(YEAR FROM PR.DATA),
            pe.valor_compensado, pr.protocolo_id
          FROM R_PROTOCOLO PR, R_PEDIDO PE
          WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
          AND PR.TIPO_PROTOCOLO = '1'
          AND PR.DATA between CAST(:V_DATA_A_PESQUISAR AS DATE) AND CAST(:V_DATA_A_PESQUISAR AS DATE) + 0.99999
          ORDER BY 1,2
          INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
            :V_TIPO_COBRANCA, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
            :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO, :V_VALOR_COMPENSADO, :V_PROTOCOLO_ID DO
      BEGIN
        if (:DATA > '30.04.2021') then
        begin
          V_QTDE_CONSOLIDACAO = 0;
          SISTEMA_ID = 1;
          TIPO_RETORNO = 1; --1=PRENOTACAO, DEPÓSITO PRÉVIO DE 100% RI/DF
    
          IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
          BEGIN
            V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
          END
          ELSE
          BEGIN
            SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
            WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
            AND I.PEDIDO_ID = :ID
            AND COALESCE(N.CONSOLIDACAO,'') = 'S'
            INTO :V_QTDE_CONSOLIDACAO;
      
            if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
            begin
              V_RETORNAR = 'N';
            end
            else
            begin
              V_RETORNAR = 'S';
            end
          END
          if (:V_RETORNAR = 'S') then
          begin
            SELECT FIRST 1 VALOR_PAGO FROM C_CAIXA_ITEM
            WHERE TIPO_SERVICO = :TIPO_PROTOCOLO
            AND CHAVE_SERVICO = :V_PROTOCOLO_ID
            AND tipo_transacao = 'C' --CREDITO
            ORDER BY DATA_PAGAMENTO
            INTO :V_VALOR_BRUTO;

            if (coalesce(:V_VALOR_COMPENSADO,0) > 0) then
            begin
              V_VALOR_BRUTO = (coalesce(:V_VALOR_BRUTO,0) + coalesce(:V_VALOR_COMPENSADO,0));
            end

            IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
            BEGIN
              NATUREZA = 'Registro/Averbação';
            END
            ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
            BEGIN
              NATUREZA = 'Averbação';
            END
            ELSE
            BEGIN
              NATUREZA = 'Registro';
            END    
      
            if (COALESCE(:V_VALOR_BRUTO,0) <= 0) then
            BEGIN
              V_VALOR_BRUTO = 0;
              V_VALOR_EMOLUMENTO = 0;
              V_VALOR_FUNDO = 0;
            END
            else
            begin
              V_VALOR_EMOLUMENTO = CAST(COALESCE((:V_VALOR_BRUTO * 0.9346),0) AS NUMERIC(18,2));
              V_VALOR_FUNDO = (:V_VALOR_BRUTO - :V_VALOR_EMOLUMENTO);
            end
            V_VALOR_TAXA_JUDICIARIA = 0;
      
            SELECT FIRST 1 N.DESCRICAO
            FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
            WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
            AND I.PEDIDO_ID = :ID
            ORDER BY SEQUENCIA
            INTO :V_NATUREZA_FORMAL;
      
            V_DESCRICAO = 'PROTOCOLO '||CAST(:NUMERO_PROTOCOLO AS VARCHAR(10))||' - [100%] - '||:V_NATUREZA_FORMAL;
            IF (:V_QTDE_REGISTRO > 0) THEN
            BEGIN
              V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
            END
            IF (:V_QTDE_AVERBACAO > 0) THEN
            BEGIN
              V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
            END
            TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
            TOTAL_FUNDO = :V_VALOR_FUNDO;
            IF (:TOTAL_EMOLUMENTO < 0) THEN
            BEGIN
              TOTAL_EMOLUMENTO = 0;
              TOTAL_FUNDO = 0;
            END
            TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
            DESCRICAO = :V_DESCRICAO || ' (Dep.Prévio)';
      
            QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
            TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO;
    
            ORDEM = :ORDEM + 1;
    
            SUSPEND;
          END
        end
      END
      V_DATA_A_PESQUISAR = :V_DATA_A_PESQUISAR + 1;
    END
  end
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_APROVEITA (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
PROTOCOLO_ANTERIOR INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
declare variable V_VALOR_EMOLUMENTO numeric(18,2);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(18,2);
declare variable V_VALOR_FUNDO numeric(18,2);
declare variable V_VALOR_BRUTO numeric(18,2);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_QTDE_REGISTRO integer;
declare variable V_QTDE_AVERBACAO integer;
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(1);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(1);
declare variable V_RETORNAR varchar(1);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_CREDITO_INICIAL numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_DATA_PROT_TEMP date;
declare variable V_VALOR_COMPENSADO numeric(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_SQL varchar(3000);
declare variable v_periodo_padrao integer;
declare variable V_PEDIDO_ANTERIOR_ID integer;
declare variable V_PERIODO_PADRAO_ANTERIOR integer;
declare variable V_TOTAL_PEDIDO_ANTERIOR numeric(18,2);
declare variable V_TOTAL_PEDIDO_ANTERIOR_75 numeric(18,2);
declare variable V_TOTAL_PEDIDO numeric(18,2);
declare variable V_TOTAL_DESCONTAR numeric(18,2);
BEGIN
  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  ORDEM = 0;
  PROTOCOLO_ANTERIOR = 0;

  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  TOTAL_DESPESA = 0;

  TOTAL_BRUTO = 0;
  QTDE = 0;

  NUMERO_ONLINE = '';

  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = 'SELECT CAST(PR.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          PE.TIPO_COBRANCA,
          (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
          (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
          PR.DATA,
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM PR.DATA),
          EXTRACT(YEAR FROM PR.DATA),
          pe.valor_compensado,
          (SELECT COALESCE(TOTAL_EMOLUMENTO,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
          (SELECT COALESCE(TOTAL_FUNDO_RI,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_FUNDO_RI,
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||')
        FROM R_PROTOCOLO PR, R_PEDIDO PE
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND COALESCE(PE.VALOR_COMPENSADO,0) > 0
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||
        ' ORDER BY 1,2';
  end
  else
  begin
    V_SQL = 'SELECT CAST(PR.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          PE.TIPO_COBRANCA,
          (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
          (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
          PR.DATA,
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM PR.DATA),
          EXTRACT(YEAR FROM PR.DATA),
          pe.valor_compensado,
          (SELECT COALESCE(TOTAL_EMOLUMENTO,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
          (SELECT COALESCE(TOTAL_FUNDO_RI,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_FUNDO_RI,
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||')
        FROM R_PROTOCOLO PR, R_PEDIDO PE
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND COALESCE(PE.VALOR_COMPENSADO,0) > 0
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND PR.DATA BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
        ORDER BY 1,2';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
          :V_TIPO_COBRANCA, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
          :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO, :V_VALOR_COMPENSADO,
          :TOTAL_EMOLUMENTO, :TOTAL_FUNDO, :NUMERO_ONLINE DO
  BEGIN
    V_QTDE_CONSOLIDACAO = 0;
    SISTEMA_ID = 1;

    V_TOTAL_PEDIDO = coalesce(:TOTAL_EMOLUMENTO,0) + coalesce(:TOTAL_FUNDO,0);

    if (coalesce(:V_VALOR_COMPENSADO,0) > 0) then
    begin
      IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
      BEGIN
        V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
      END
      ELSE
      BEGIN
        SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
        WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
        AND I.PEDIDO_ID = :ID
        AND COALESCE(N.CONSOLIDACAO,'') = 'S'
        INTO :V_QTDE_CONSOLIDACAO;

        if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
        begin
          V_RETORNAR = 'N';
        end
        else
        begin
          V_RETORNAR = 'S';
        end
      END
    
      if (:V_RETORNAR = 'S') then
      begin
        ORDEM = :ORDEM + 1;

        V_TOTAL_DESCONTAR = 0;

        SELECT PR.NUMERO_ORDEM FROM R_PROTOCOLO PR, R_PEDIDO PE
        WHERE PR.pedido_id = PE.pedido_id
        AND PR.TIPO_PROTOCOLO = '1'
        AND PE.novo_pedido_id = :ID
        INTO :protocolo_anterior;

        --ver data e total do protocolo anterior
        select pr.data, coalesce(pe.pedido_id,0) from r_pedido pe, r_protocolo pr
        where pe.pedido_id = pr.pedido_id
        and pr.tipo_protocolo = '1'
        and pe.novo_pedido_id = :ID
        into :V_DATA_PROT_TEMP, :V_PEDIDO_ANTERIOR_ID;

        select first 1 emolumento_periodo_id from g_emolumento_periodo ep
        where :DATA >= ep.data_inicial
        order by ep.data_inicial
        into :V_PERIODO_PADRAO_ANTERIOR;

        SELECT (COALESCE(TOTAL_EMOLUMENTO,0) + COALESCE(TOTAL_FUNDO_RI,0))
        FROM R_TOTAL_PEDIDO_DF(:V_PEDIDO_ANTERIOR_ID, :V_PERIODO_PADRAO_ANTERIOR)
        INTO :V_TOTAL_PEDIDO_ANTERIOR;
        V_TOTAL_PEDIDO_ANTERIOR_75 = CAST((:V_TOTAL_PEDIDO_ANTERIOR * 0.75) AS NUMERIC(18,2));

        /*if ((COALESCE(:V_VALOR_COMPENSADO,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0)) > (COALESCE(:V_TOTAL_PEDIDO_ANTERIOR,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0))) then
        begin
          V_TOTAL_DESCONTAR = COALESCE(:V_TOTAL_PEDIDO_ANTERIOR,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0);
        end
        else
        begin
          V_TOTAL_DESCONTAR = COALESCE(:V_VALOR_COMPENSADO,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0);
        end*/

        TOTAL_BRUTO = coalesce(:V_VALOR_COMPENSADO,0) - coalesce(:V_TOTAL_DESCONTAR,0);

        TOTAL_ISS = round((total_bruto * 5),2);
        TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);
        TOTAL_GERAL_COM_ISS = :total_bruto;
        total_bruto = :total_bruto - :TOTAL_ISS;

        TIPO_RETORNO = 2;
        NATUREZA = 'Aproveitamento de valor de protocolo anterior';
        if (coalesce(:TOTAL_BRUTO,0) > 0) then
        begin
          SUSPEND;
        end
      end
    END
  end
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_CANC (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER)
AS 
declare variable V_VALOR_RECEITA numeric(18,2);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_QTDE_REGISTRO integer;
declare variable V_QTDE_AVERBACAO integer;
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(1);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(1);
declare variable V_RETORNAR varchar(1);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_PROTOCOLO_ID integer;
declare variable V_DEPOSITO_INICIAL numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_CONSOLIDACAO varchar(1);
declare variable V_DATA_PROT_TEMP date;
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_TOTAL_GERAL numeric(18,2);
declare variable V_TOTAL_GERAL_75 numeric(18,2);
declare variable V_DATA_CANCELAMENTO date;
declare variable V_TOTAL_DEPOSITO numeric(18,2);
declare variable V_VALOR_DEVOLVIDO numeric(18,2);

declare variable V_OFICIO varchar(3);
declare variable V_DATA_PROTOCOLO date;

declare variable V_TOTAL_EMOLUMENTO_TEMP numeric(18,2);
declare variable V_TOTAL_FUNDO_TEMP numeric(18,2);
declare variable V_TOTAL_PROTOCOLO_TEMP numeric(18,2);
declare variable V_TOTAL_PROTOCOLO_25_TEMP numeric(18,2);
declare variable V_VALOR_COMPENSADO_ENTRADA numeric(18,2);
declare variable V_VALOR_COMPENSADO_SAIDA numeric(18,2);

declare variable V_PEDIDO_ANTERIOR integer;
declare variable V_TOTAL_PEDIDO_ANTERIOR NUMERIC(18,2);
declare variable V_COMPENSADO_100 varchar(5);
BEGIN
  SELECT TRIM(C.VALOR) FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '5'
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'CARTORIO'
  AND C.NOME = 'CARTORIO_OFICIO'
  INTO :V_OFICIO;

  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  ORDEM = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    --SELECIONAR PROTOCOLOS CANCELADOS DO RI 25% como saída para receita
    --Lançamento como saída da conversão de 25% dado como depósito prévio em receita da serventia na data do registro/averbação
    TOTAL_EMOLUMENTO = 0;
    TOTAL_TAXA_JUDICIARIA = 0;
    TOTAL_FUNDO = 0;
    TOTAL_DESPESA = 0;

    TOTAL_BRUTO = 0;
    QTDE = 0;

    FOR SELECT CAST(A.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
          (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
          A.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
          EXTRACT(MONTH FROM A.DATA),
          EXTRACT(YEAR FROM A.DATA),
          PR.PROTOCOLO_ID, COALESCE(PE.NOVO_PEDIDO_ID,0),
          cast(pr.data as date),
          (SELECT COALESCE(TOTAL_EMOLUMENTO,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
          (SELECT COALESCE(TOTAL_FUNDO_RI,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_FUNDO_RI,
          COALESCE(PE.VALOR_COMPENSADO,0)
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PR.TIPO_PROTOCOLO = '1'
        AND TA.TIPO = 'C' --CANCELADOS
        AND PR.PROTOCOLO_ID = :VP_PROTOCOLO_ID
        AND A.ANDAMENTO_ID = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.pedido_id = A.pedido_id
                              AND TA2.TIPO = 'C') --PEGAR SOMENTE 1º ANDAMENTO DE CANCELADO
        ORDER BY 1,2
        INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
          :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
          :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO, :V_PROTOCOLO_ID, :V_NOVO_PEDIDO_ID,
          :V_DATA_PROTOCOLO, :V_TOTAL_EMOLUMENTO_TEMP, :V_TOTAL_FUNDO_TEMP, :V_VALOR_COMPENSADO_ENTRADA DO
    BEGIN
      if ((:V_DATA_PROTOCOLO <= '30.04.2021') and (:V_OFICIO <> '1')) then
      begin
        --nao fazer nada
      end
      else
      begin
        V_QTDE_CONSOLIDACAO = 0;
        SISTEMA_ID = 1;
        TIPO_RETORNO = 2; --2=LANCAMENTO COMO SAIDA DA CONVERSAO DO DEPOSITO PREVIO EM RECEITA (CANCELAMENTO-25%)
        V_DATA_CANCELAMENTO = :DATA;
        V_VALOR_COMPENSADO_SAIDA = 0;
  
        IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
        BEGIN
          NATUREZA = 'Registro/Averbação';
        END
        ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
        BEGIN
          NATUREZA = 'Averbação';
        END
        ELSE
        BEGIN
          NATUREZA = 'Registro';
        END    
  
        IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
        BEGIN
          V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
        END
        ELSE
        BEGIN
          SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
          WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
          AND I.PEDIDO_ID = :ID
          AND COALESCE(N.CONSOLIDACAO,'') = 'S'
          INTO :V_QTDE_CONSOLIDACAO;
    
          if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
          begin
            V_RETORNAR = 'N';
          end
          else
          begin
            V_RETORNAR = 'S';
          end
        END
  
        if (:V_RETORNAR = 'S') THEN
        BEGIN
          V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [25%] - '||:V_NATUREZA_FORMAL;
          IF (:V_QTDE_REGISTRO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
          END
          IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
          END
  
          --VERIFICAR SE HOUVE COMPENSACAO SAIDA
          /*if (:V_NOVO_PEDIDO_ID > 0) then --houve compensacao
          begin
            SELECT COALESCE(PE.VALOR_COMPENSADO,0)
            FROM R_PEDIDO PE
            WHERE PE.PEDIDO_ID = :V_NOVO_PEDIDO_ID
            INTO :V_VALOR_COMPENSADO_SAIDA;
          end*/

          --verificar se foi compensação de 100%
          V_COMPENSADO_100 = 'N';
          V_PEDIDO_ANTERIOR = null;
          V_TOTAL_PEDIDO_ANTERIOR = 0;
          if (coalesce(:V_VALOR_COMPENSADO_ENTRADA,0) > 0) then
          begin
            select pedido_id from r_pedido
            where novo_pedido_id = :ID
            into :V_PEDIDO_ANTERIOR;

            if (coalesce(:V_PEDIDO_ANTERIOR,0) > 0) then
            begin
              SELECT COALESCE(TOTAL_GERAL,0)
              FROM R_TOTAL_PEDIDO_DF(:V_PEDIDO_ANTERIOR)
              INTO :V_TOTAL_PEDIDO_ANTERIOR;

              if (:V_VALOR_COMPENSADO_ENTRADA = :V_TOTAL_PEDIDO_ANTERIOR) then --COMPENSACAO DE 100%
              begin
                V_COMPENSADO_100 = 'S';
              end
            end
          end
  
          SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
          WHERE CI.tipo_servico = '1' --PROTOCOLO
          AND CI.CHAVE_SERVICO = :V_PROTOCOLO_ID
          AND CI.tipo_transacao = 'C' --CREDITO
          AND ((cast(CI.data_pagamento as date) <= :V_DATA_CANCELAMENTO) or (extract(month from cast(CI.data_pagamento as date)) = extract(month from :V_DATA_CANCELAMENTO)))
          INTO :V_TOTAL_DEPOSITO;   --VALOR BRUTO RECEBIDO
          V_TOTAL_DEPOSITO = COALESCE(:V_TOTAL_DEPOSITO,0) + COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0);
  
          SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
          WHERE CI.tipo_servico = '1' --PROTOCOLO
          AND CI.CHAVE_SERVICO = :V_PROTOCOLO_ID
          AND CI.tipo_transacao = 'D' --DEBITO
          AND ((cast(CI.data_pagamento as date) <= :V_DATA_CANCELAMENTO) or (extract(month from cast(CI.data_pagamento as date)) = extract(month from :V_DATA_CANCELAMENTO)))
          INTO :V_VALOR_DEVOLVIDO;
          V_VALOR_DEVOLVIDO = COALESCE(:V_VALOR_DEVOLVIDO,0) + COALESCE(:V_VALOR_COMPENSADO_SAIDA,0);
  
          V_TOTAL_DEPOSITO = COALESCE(:V_TOTAL_DEPOSITO,0) - COALESCE(:V_VALOR_DEVOLVIDO,0);
  
          if (COALESCE(:V_TOTAL_DEPOSITO,0) < 0) then
          begin
            V_TOTAL_DEPOSITO = 0;
          end
  
          V_TOTAL_PROTOCOLO_TEMP = (coalesce(:V_TOTAL_EMOLUMENTO_TEMP,0) + coalesce(:V_TOTAL_FUNDO_TEMP,0));
          V_TOTAL_PROTOCOLO_25_TEMP = (:V_TOTAL_PROTOCOLO_TEMP * 0.25);
  
          if (COALESCE(:V_COMPENSADO_100,'') = 'S') then
          begin
            V_VALOR_RECEITA = CAST(((COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) - COALESCE(:V_TOTAL_PROTOCOLO_TEMP,0)) * 0.25) AS NUMERIC(18,2));
          end
          else if (:V_TOTAL_DEPOSITO > :V_TOTAL_PROTOCOLO_25_TEMP) then
          begin
            V_VALOR_RECEITA = :V_TOTAL_PROTOCOLO_25_TEMP;
          end
          else
          begin
            V_VALOR_RECEITA = :V_TOTAL_DEPOSITO;
          end
  
          if (COALESCE(:V_VALOR_RECEITA,0) < 0) then
          BEGIN
            V_VALOR_RECEITA = 0;
          END
  
          TOTAL_EMOLUMENTO = 0;
          TOTAL_TAXA_JUDICIARIA = 0;
          TOTAL_FUNDO = 0;
      
          TOTAL_DESPESA = :V_VALOR_RECEITA;
  
          DESCRICAO = :V_DESCRICAO || ' (Cancelado-->Conversão em receita)';
    
          QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
          TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO;
  
          ORDEM = :ORDEM + 1;
  
          SUSPEND;
  
          if (COALESCE(:v_valor_compensado_saida,0) > 0) then
          begin
            TIPO_RETORNO = 3; --3=LANCAMENTO COMO SAIDA COMO DEVOLUCAO AO USUARIO
            TOTAL_DESPESA = :v_valor_compensado_saida;
            if (:V_TOTAL_PROTOCOLO_TEMP >= :TOTAL_DESPESA) then
            begin
              V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
            end
            else
            begin
              V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [100%] - '||:V_NATUREZA_FORMAL;
            end
            DESCRICAO = :V_DESCRICAO || ' (Devolução ao usuário - Compensação)';
  
            ORDEM = :ORDEM + 1;
  
            SUSPEND;
          end
        END
      end
    END
  end
  else
  begin
    V_DATA_A_PESQUISAR = cast(:V_DATA_INI as date);
    WHILE (:V_DATA_A_PESQUISAR <= cast(:V_DATA_FIM as date)) DO
    BEGIN
      --SELECIONAR PROTOCOLOS CANCELADOS DO RI 25% como saída para receita
      --Lançamento como saída da conversão de 25% dado como depósito prévio em receita da serventia na data do registro/averbação
      TOTAL_EMOLUMENTO = 0;
      TOTAL_TAXA_JUDICIARIA = 0;
      TOTAL_FUNDO = 0;
      TOTAL_DESPESA = 0;
  
      TOTAL_BRUTO = 0;
      QTDE = 0;
  
      FOR SELECT CAST(A.DATA AS DATE),
            PR.NUMERO_ORDEM,
            PR.PEDIDO_ID,
            PR.TIPO_PROTOCOLO,
            T.DESCRICAO,
            PE.TIPO_COBRANCA,
            (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
            (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
            A.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
            EXTRACT(MONTH FROM A.DATA),
            EXTRACT(YEAR FROM A.DATA),
            PR.PROTOCOLO_ID, COALESCE(PE.NOVO_PEDIDO_ID,0),
            cast(pr.data as date),
            (SELECT COALESCE(TOTAL_EMOLUMENTO,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
            (SELECT COALESCE(TOTAL_FUNDO_RI,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_FUNDO_RI,
            COALESCE(PE.VALOR_COMPENSADO,0)
          FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
          WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
          AND PE.TB_TITULO_ID = T.TB_TITULO_ID
          AND PE.PEDIDO_ID = A.PEDIDO_ID
          AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
          AND PR.TIPO_PROTOCOLO = '1'
          AND TA.TIPO = 'C' --CANCELADOS
          AND A.DATA BETWEEN CAST(:V_DATA_A_PESQUISAR AS DATE) AND CAST(:V_DATA_A_PESQUISAR AS DATE) + 0.99999
          AND A.ANDAMENTO_ID = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                                WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                                AND A2.pedido_id = A.pedido_id
                                AND TA2.TIPO = 'C') --PEGAR SOMENTE 1º ANDAMENTO DE CANCELADO
          ORDER BY 1,2
          INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
            :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
            :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO, :V_PROTOCOLO_ID, :V_NOVO_PEDIDO_ID,
            :V_DATA_PROTOCOLO, :V_TOTAL_EMOLUMENTO_TEMP, :V_TOTAL_FUNDO_TEMP, :V_VALOR_COMPENSADO_ENTRADA DO
      BEGIN
        if ((:V_DATA_PROTOCOLO <= '30.04.2021') and (:V_OFICIO <> '1')) then
        begin
          --nao fazer nada
        end
        else
        begin
          V_QTDE_CONSOLIDACAO = 0;
          SISTEMA_ID = 1;
          TIPO_RETORNO = 2; --2=LANCAMENTO COMO SAIDA DA CONVERSAO DO DEPOSITO PREVIO EM RECEITA (CANCELAMENTO-25%)
          V_DATA_CANCELAMENTO = :DATA;
          V_VALOR_COMPENSADO_SAIDA = 0;
  
          IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
          BEGIN
            NATUREZA = 'Registro/Averbação';
          END
          ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            NATUREZA = 'Averbação';
          END
          ELSE
          BEGIN
            NATUREZA = 'Registro';
          END    
    
          IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
          BEGIN
            V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
          END
          ELSE
          BEGIN
            SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
            WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
            AND I.PEDIDO_ID = :ID
            AND COALESCE(N.CONSOLIDACAO,'') = 'S'
            INTO :V_QTDE_CONSOLIDACAO;
      
            if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
            begin
              V_RETORNAR = 'N';
            end
            else
            begin
              V_RETORNAR = 'S';
            end
          END
    
          if (:V_RETORNAR = 'S') THEN
          BEGIN
            V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [25%] - '||:V_NATUREZA_FORMAL;
            IF (:V_QTDE_REGISTRO > 0) THEN
            BEGIN
              V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
            END
            IF (:V_QTDE_AVERBACAO > 0) THEN
            BEGIN
              V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
            END
    
            --VERIFICAR SE HOUVE COMPENSACAO SAIDA
            if (:V_NOVO_PEDIDO_ID > 0) then --houve compensacao
            begin
              SELECT COALESCE(PE.VALOR_COMPENSADO,0)
              FROM R_PEDIDO PE
              WHERE PE.PEDIDO_ID = :V_NOVO_PEDIDO_ID
              INTO :V_VALOR_COMPENSADO_SAIDA;
            end
    
            SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
            WHERE CI.tipo_servico = '1' --PROTOCOLO
            AND CI.CHAVE_SERVICO = :V_PROTOCOLO_ID
            AND CI.tipo_transacao = 'C' --CREDITO
            AND ((cast(CI.data_pagamento as date) <= :V_DATA_CANCELAMENTO) or (extract(month from cast(CI.data_pagamento as date)) = extract(month from :V_DATA_CANCELAMENTO)))
            INTO :V_TOTAL_DEPOSITO;   --VALOR BRUTO RECEBIDO
            V_TOTAL_DEPOSITO = COALESCE(:V_TOTAL_DEPOSITO,0) + COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0);
    
            SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
            WHERE CI.tipo_servico = '1' --PROTOCOLO
            AND CI.CHAVE_SERVICO = :V_PROTOCOLO_ID
            AND CI.tipo_transacao = 'D' --DEBITO
            AND ((cast(CI.data_pagamento as date) <= :V_DATA_CANCELAMENTO) or (extract(month from cast(CI.data_pagamento as date)) = extract(month from :V_DATA_CANCELAMENTO)))
            INTO :V_VALOR_DEVOLVIDO;
            V_VALOR_DEVOLVIDO = COALESCE(:V_VALOR_DEVOLVIDO,0) + COALESCE(:V_VALOR_COMPENSADO_SAIDA,0);
  
            V_TOTAL_DEPOSITO = COALESCE(:V_TOTAL_DEPOSITO,0) - COALESCE(:V_VALOR_DEVOLVIDO,0);
  
            if (COALESCE(:V_TOTAL_DEPOSITO,0) < 0) then
            begin
              V_TOTAL_DEPOSITO = 0;
            end
  
            V_TOTAL_PROTOCOLO_TEMP = (coalesce(:V_TOTAL_EMOLUMENTO_TEMP,0) + coalesce(:V_TOTAL_FUNDO_TEMP,0));
            V_TOTAL_PROTOCOLO_25_TEMP = (:V_TOTAL_PROTOCOLO_TEMP * 0.25);
  
            if (:V_TOTAL_DEPOSITO > :V_TOTAL_PROTOCOLO_25_TEMP) then
            begin
              V_VALOR_RECEITA = :V_TOTAL_PROTOCOLO_25_TEMP;
            end
            else
            begin
              V_VALOR_RECEITA = :V_TOTAL_DEPOSITO;
            end
  
            if (COALESCE(:V_VALOR_RECEITA,0) < 0) then
            BEGIN
              V_VALOR_RECEITA = 0;
            END
    
            TOTAL_EMOLUMENTO = 0;
            TOTAL_TAXA_JUDICIARIA = 0;
            TOTAL_FUNDO = 0;
  
            TOTAL_DESPESA = :V_VALOR_RECEITA;
        
            DESCRICAO = :V_DESCRICAO || ' (Cancelado-->Conversão em receita)';
      
            QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
            TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO;
    
            ORDEM = :ORDEM + 1;
            if (:TOTAL_DESPESA > 0) then
            begin
              SUSPEND;
            end
    
            if (COALESCE(:v_valor_compensado_saida,0) > 0) then
            begin
              TIPO_RETORNO = 3; --3=LANCAMENTO COMO SAIDA COMO DEVOLUCAO AO USUARIO
              TOTAL_DESPESA = :v_valor_compensado_saida;
              if (:V_TOTAL_PROTOCOLO_TEMP >= :TOTAL_DESPESA) then
              begin
                V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
              end
              else
              begin
                V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [100%] - '||:V_NATUREZA_FORMAL;
              end
              DESCRICAO = :V_DESCRICAO || ' (Devolução ao usuário - Compensação)';
    
              ORDEM = :ORDEM + 1;
    
              SUSPEND;
            end
          END
        end
      END
      V_DATA_A_PESQUISAR = :V_DATA_A_PESQUISAR + 1;
    end
  end
END;
 ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_CANC_DEVOL (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER)
AS 
declare variable V_VALOR_EMOLUMENTO numeric(18,2);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(18,2);
declare variable V_VALOR_FUNDO numeric(18,2);
declare variable V_VALOR_DESCONTO numeric(18,2);
declare variable V_VALOR_DEVOLUCAO numeric(18,2);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_QTDE_REGISTRO integer;
declare variable V_QTDE_AVERBACAO integer;
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(1);
declare variable V_SERVICO_DEVOLUCAO_TJDFT varchar(10);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(1);
declare variable V_RETORNAR varchar(1);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_PROTOCOLO_ID integer;
declare variable V_DEPOSITO_INICIAL numeric(18,2);
declare variable V_CREDITO_INICIAL numeric(18,2);
declare variable V_TOTAL_PROTOCOLO numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_CONSOLIDACAO varchar(1);
declare variable V_DATA_PROT_TEMP date;
declare variable V_VALOR_COMPENSADO numeric(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_TOTAL_GERAL numeric(18,2);
declare variable V_TOTAL_GERAL_75 numeric(18,2);
BEGIN
  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  --BUSCAR VALORES DE PARAMETROS
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_TJDFT'
  INTO :V_SERVICO_DEVOLUCAO_TJDFT;

  ORDEM = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    --SELECIONAR PROTOCOLOS CANCELADOS DO RI 75% como devolução ao usuário
    --Lançamento como saída da conversão de 75% dado como depósito prévio como devolução ao usuario
    TOTAL_EMOLUMENTO = 0;
    TOTAL_TAXA_JUDICIARIA = 0;
    TOTAL_FUNDO = 0;
    TOTAL_DESPESA = 0;

    TOTAL_BRUTO = 0;
    QTDE = 0;

    FOR SELECT CAST(C.DATA_PAGAMENTO AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          C.DATA_PAGAMENTO, COALESCE(PE.TIPO_ORIGEM_SITE,''), C.CAIXA_SERVICO_ID,
          COALESCE(C.valor_pago,0),
          EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
          EXTRACT(YEAR FROM C.DATA_PAGAMENTO)
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA,
          C_CAIXA_ITEM C
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND C.CHAVE_SERVICO = PR.PROTOCOLO_ID
        AND PR.TIPO_PROTOCOLO = '1'
        AND TA.TIPO = 'C' --CANCELADOS
        AND A.ANDAMENTO_ID = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.pedido_id = A.pedido_id
                              AND TA2.TIPO = 'C') --PEGAR SOMENTE 1º ANDAMENTO DE CANCELADO
        AND PR.PROTOCOLO_ID = :VP_PROTOCOLO_ID
        AND C.DATA_PAGAMENTO >= CAST(A.data AS DATE)
        AND C.tipo_transacao = 'D' --DEBITO
        ORDER BY 1,2
        INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,   :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA,
          :DATA_HORA, :V_TIPO_ORIGEM_SITE, :V_CAIXA_SERVICO_ID, :V_VALOR_DEVOLUCAO, :MES, :ANO DO
    BEGIN
      V_QTDE_CONSOLIDACAO = 0;
      SISTEMA_ID = 1;

      if (:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) then
      begin
        TIPO_RETORNO = 4; --4=LANCAMENTO COMO SAIDA À VARA DE REGISTROS PUBLICOS
      end
      else
      begin
        TIPO_RETORNO = 3; --3=LANCAMENTO COMO SAIDA COMO DEVOLUCAO AO USUARIO
      end
  
      IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
      BEGIN
        V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
      END
      ELSE IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
      BEGIN
        V_RETORNAR = 'N';
      END
      ELSE
      BEGIN
        SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
        WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
        AND I.PEDIDO_ID = :ID
        AND COALESCE(N.CONSOLIDACAO,'') = 'S'
        INTO :V_QTDE_CONSOLIDACAO;
  
        if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
        begin
          V_RETORNAR = 'N';
        end
        else
        begin
          V_RETORNAR = 'S';
        end
      END

      if (:V_RETORNAR = 'S') THEN
      BEGIN
        SELECT QUANTIDADE_REGISTRO, QUANTIDADE_AVERBACAO, TOTAL_GERAL
        FROM R_TOTAL_PEDIDO_DF(:ID)
        into :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO, :V_TOTAL_GERAL;
  
        V_TOTAL_GERAL_75 = coalesce((coalesce(V_TOTAL_GERAL,0) * 0.75),0);
  
        IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
        BEGIN
          NATUREZA = 'Registro/Averbação';
        END
        ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
        BEGIN
          NATUREZA = 'Averbação';
        END
        ELSE
        BEGIN
          NATUREZA = 'Registro';
        END    
    
        if (COALESCE(:V_VALOR_DEVOLUCAO,0) < 0) then
        BEGIN
          V_VALOR_DEVOLUCAO = :V_VALOR_DEVOLUCAO * -1;
        END
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
    
        TOTAL_DESPESA = :V_VALOR_DEVOLUCAO;

        if (:TOTAL_DESPESA = :V_TOTAL_GERAL) then
        BEGIN
          V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [100%] - '||:V_NATUREZA_FORMAL;
        END
        ELSE
        BEGIN
          V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
        END

        if (:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) then
        begin
          DESCRICAO = :V_DESCRICAO || ' (Devolução à vara de registros públicos)';
        end
        else
        begin
          DESCRICAO = :V_DESCRICAO || ' (Devolução ao usuário)';
        end

        QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
        TOTAL_BRUTO = 0;
  
        ORDEM = :ORDEM + 1;

        SUSPEND;
      END
    END
  end
  else
  begin
    V_DATA_A_PESQUISAR = cast(:V_DATA_INI as date);
    WHILE (:V_DATA_A_PESQUISAR <= cast(:V_DATA_FIM as date)) DO
    BEGIN
      --SELECIONAR PROTOCOLOS CANCELADOS DO RI 75% como devolução ao usuário
      --Lançamento como saída da conversão de 75% dado como depósito prévio como devolução ao usuario
      TOTAL_EMOLUMENTO = 0;
      TOTAL_TAXA_JUDICIARIA = 0;
      TOTAL_FUNDO = 0;
      TOTAL_DESPESA = 0;
  
      TOTAL_BRUTO = 0;
      QTDE = 0;
  
      FOR SELECT CAST(C.DATA_PAGAMENTO AS DATE),
            PR.NUMERO_ORDEM,
            PR.PEDIDO_ID,
            PR.TIPO_PROTOCOLO,
            T.DESCRICAO,
            PE.TIPO_COBRANCA,
            C.DATA_PAGAMENTO, COALESCE(PE.TIPO_ORIGEM_SITE,''), C.CAIXA_SERVICO_ID,
            COALESCE(C.valor_pago,0),
            EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
            EXTRACT(YEAR FROM C.DATA_PAGAMENTO)
          FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA,
            C_CAIXA_ITEM C
          WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
          AND PE.TB_TITULO_ID = T.TB_TITULO_ID
          AND PE.PEDIDO_ID = A.PEDIDO_ID
          AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
          AND C.CHAVE_SERVICO = PR.PROTOCOLO_ID
          AND PR.TIPO_PROTOCOLO = '1'
          AND TA.TIPO = 'C' --CANCELADOS
          AND A.ANDAMENTO_ID = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                                WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                                AND A2.pedido_id = A.pedido_id
                                AND TA2.TIPO = 'C') --PEGAR SOMENTE 1º ANDAMENTO DE CANCELADO
          AND C.DATA_PAGAMENTO = CAST(:V_DATA_A_PESQUISAR AS DATE)
          AND C.DATA_PAGAMENTO >= CAST(A.data AS DATE)
          AND C.tipo_transacao = 'D' --DEBITO
          ORDER BY 1,2
          INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,   :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA,
            :DATA_HORA, :V_TIPO_ORIGEM_SITE, :V_CAIXA_SERVICO_ID, :V_VALOR_DEVOLUCAO, :MES, :ANO DO
      BEGIN
        V_QTDE_CONSOLIDACAO = 0;
        SISTEMA_ID = 1;
  
        if (:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) then
        begin
          TIPO_RETORNO = 4; --4=LANCAMENTO COMO SAIDA À VARA DE REGISTROS PUBLICOS
        end
        else
        begin
          TIPO_RETORNO = 3; --3=LANCAMENTO COMO SAIDA COMO DEVOLUCAO AO USUARIO
        end
    
        IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
        BEGIN
          V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
        END
        ELSE IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
        BEGIN
          V_RETORNAR = 'N';
        END
        ELSE
        BEGIN
          SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
          WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
          AND I.PEDIDO_ID = :ID
          AND COALESCE(N.CONSOLIDACAO,'') = 'S'
          INTO :V_QTDE_CONSOLIDACAO;
    
          if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
          begin
            V_RETORNAR = 'N';
          end
          else
          begin
            V_RETORNAR = 'S';
          end
        END
  
        if (:V_RETORNAR = 'S') THEN
        BEGIN
          SELECT QUANTIDADE_REGISTRO, QUANTIDADE_AVERBACAO, TOTAL_GERAL
          FROM R_TOTAL_PEDIDO_DF(:ID)
          into :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO, :V_TOTAL_GERAL;
    
          V_TOTAL_GERAL_75 = coalesce((coalesce(V_TOTAL_GERAL,0) * 0.75),0);
    
          IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
          BEGIN
            NATUREZA = 'Registro/Averbação';
          END
          ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            NATUREZA = 'Averbação';
          END
          ELSE
          BEGIN
            NATUREZA = 'Registro';
          END    
      
          if (COALESCE(:V_VALOR_DEVOLUCAO,0) < 0) then
          BEGIN
            V_VALOR_DEVOLUCAO = :V_VALOR_DEVOLUCAO * -1;
          END
          TOTAL_EMOLUMENTO = 0;
          TOTAL_TAXA_JUDICIARIA = 0;
          TOTAL_FUNDO = 0;
      
          TOTAL_DESPESA = :V_VALOR_DEVOLUCAO;

          if (:TOTAL_DESPESA = :V_TOTAL_GERAL) then
          BEGIN
            V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [100%] - '||:V_NATUREZA_FORMAL;
          END
          ELSE
          BEGIN
            V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
          END

          if (:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) then
          begin
            DESCRICAO = :V_DESCRICAO || ' (Devolução à vara de registros públicos)';
          end
          else
          begin
            DESCRICAO = :V_DESCRICAO || ' (Devolução ao usuário)';
          end
  
          QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
          TOTAL_BRUTO = 0;
    
          ORDEM = :ORDEM + 1;
  
          SUSPEND;
        END
      END
  
      V_DATA_A_PESQUISAR = :V_DATA_A_PESQUISAR + 1;
    end
  end
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_COMPL (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER)
AS 
declare variable V_VALOR_EMOLUMENTO numeric(18,2);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(18,2);
declare variable V_VALOR_FUNDO numeric(18,2);
declare variable V_VALOR_BRUTO numeric(18,2);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_QTDE_REGISTRO integer;
declare variable V_QTDE_AVERBACAO integer;
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(1);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(1);
declare variable V_RETORNAR varchar(1);
declare variable V_PROTOCOLO_INICIAL integer;
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_PROTOCOLO_ID integer;
declare variable V_DEPOSITO_INICIAL numeric(18,2);
declare variable V_CREDITO_INICIAL numeric(18,2);
declare variable V_TOTAL_PROTOCOLO numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_CONSOLIDACAO varchar(1);
declare variable V_DATA_PROT_TEMP date;
declare variable V_VALOR_COMPENSADO numeric(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_TOTAL_GERAL numeric(18,2);
declare variable V_COUNT_REGISTRO integer;
declare variable V_DATA_REGISTRO date;
declare variable V_DATA_CAIXA date;
BEGIN
  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  V_PROTOCOLO_INICIAL = 1;

  ORDEM = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    --INICIO REGISTRO DE IMOVEIS
    --REGISTRO DE IMOVEIS - SELECIONAR PROTOCOLADOS - ESCRITURACAO DE 100% - diferença de custas (entradas)
    TOTAL_EMOLUMENTO = 0;
    TOTAL_TAXA_JUDICIARIA = 0;
    TOTAL_FUNDO = 0;
    TOTAL_DESPESA = 0;
    V_DEPOSITO_INICIAL = 0;

    TOTAL_BRUTO = 0;
    QTDE = 0;

    FOR SELECT CAST(CI.DATA_PAGAMENTO AS DATE), COALESCE(CI.VALOR_PAGO,0),
          CI.CHAVE_SERVICO,
          EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
          EXTRACT(YEAR FROM CI.DATA_PAGAMENTO)
        FROM C_CAIXA_ITEM CI
        WHERE CI.tipo_servico = '1' --PROTOCOLO
        AND CI.CHAVE_SERVICO = :VP_PROTOCOLO_ID
        AND CI.tipo_transacao = 'C' --CREDITO
        AND CI.CAIXA_ITEM_ID <> (SELECT FIRST 1 CAIXA_ITEM_ID FROM C_CAIXA_ITEM
                                 WHERE TIPO_SERVICO = CI.TIPO_SERVICO
                                 AND CHAVE_SERVICO = CI.CHAVE_SERVICO
                                 ORDER BY DATA_PAGAMENTO) --IGNORAR PAGAMENTO INICIAL, POIS ENTROU COMO DEPOSITO PRENOTACAO
        INTO :DATA, :V_VALOR_BRUTO, :V_PROTOCOLO_ID, :MES, :ANO DO
    BEGIN
      V_RETORNAR = 'S';
      V_QTDE_CONSOLIDACAO = 0;
      DATA_HORA = :DATA;
      V_DATA_CAIXA = :DATA; --DATA EM FORMATO DATE

      SELECT PR.NUMERO_ORDEM, PR.TIPO_PROTOCOLO, PR.PEDIDO_ID, PE.TIPO_COBRANCA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
        (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
        (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO
      FROM r_protocolo PR, r_pedido PE
      where pr.pedido_id = pe.pedido_id
      and pr.protocolo_id = :v_protocolo_id
      into :NUMERO_PROTOCOLO, :TIPO_PROTOCOLO, :ID, :V_TIPO_COBRANCA, :V_TIPO_ORIGEM_SITE, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO;
  
      SISTEMA_ID = 1;
      TIPO_RETORNO = 1; --1=PRENOTACAO-Complemento de depósito (100%)

      IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
      BEGIN
        NATUREZA = 'Registro/Averbação';
      END
      ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
      BEGIN
        NATUREZA = 'Averbação';
      END
      ELSE
      BEGIN
        NATUREZA = 'Registro';
      END    
  
      IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
      BEGIN
        V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
      END
      ELSE
      BEGIN
        --PEGAR DATA DO REGISTRO
        SELECT COUNT(*) FROM R_PROTOCOLO PR, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
        WHERE PR.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PR.PROTOCOLO_ID = :V_PROTOCOLO_ID
        AND TA.TIPO = 'R' --REGISTRADOS
        INTO :V_COUNT_REGISTRO;

        if (COALESCE(:V_COUNT_REGISTRO,0) > 0) then
        begin
          SELECT FIRST 1 A.DATA FROM R_PROTOCOLO PR, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
          WHERE PR.PEDIDO_ID = A.PEDIDO_ID
          AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
          AND PR.PROTOCOLO_ID = :V_PROTOCOLO_ID
          AND TA.TIPO = 'R' --REGISTRADOS
          INTO :V_DATA_REGISTRO;

          if (:V_DATA_CAIXA > :V_DATA_REGISTRO) then
          begin
            V_RETORNAR = 'N';
          end
        end
        if (:V_RETORNAR = 'S') then
        begin
          SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
          WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
          AND I.PEDIDO_ID = :ID
          AND COALESCE(N.CONSOLIDACAO,'') = 'S'
          INTO :V_QTDE_CONSOLIDACAO;
  
          if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
          begin
            V_RETORNAR = 'N';
          end
          else
          begin
            V_RETORNAR = 'S';
          end
        end
      END
  
      if (:V_RETORNAR = 'S') THEN
      BEGIN
        if (COALESCE(:V_VALOR_BRUTO,0) <= 0) then
        BEGIN
          V_VALOR_BRUTO = 0;
        END
        V_VALOR_EMOLUMENTO = CAST(COALESCE((:V_VALOR_BRUTO * 0.9346),0) AS NUMERIC(18,2));
        V_VALOR_FUNDO = (:V_VALOR_BRUTO - :V_VALOR_EMOLUMENTO);
        V_VALOR_TAXA_JUDICIARIA = 0;

        SELECT T.DESCRICAO
        FROM R_PEDIDO PE, R_TB_TITULO T
        WHERE PE.PEDIDO_ID = :ID
        AND PE.tb_titulo_id = T.tb_titulo_id
        INTO :V_NATUREZA_FORMAL;
    
        V_DESCRICAO = 'PROTOCOLO '||CAST(:NUMERO_PROTOCOLO AS VARCHAR(10))||' - [100%] - '||:V_NATUREZA_FORMAL;
        IF (:V_QTDE_REGISTRO > 0) THEN
        BEGIN
          V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
        END
        IF (:V_QTDE_AVERBACAO > 0) THEN
        BEGIN
          V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
        END
        IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
        BEGIN
          TOTAL_EMOLUMENTO = 0;
          TOTAL_TAXA_JUDICIARIA = 0;
          TOTAL_FUNDO = 0;
          V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
        END
        ELSE
        BEGIN
          TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
          TOTAL_FUNDO = :V_VALOR_FUNDO;
          IF (:TOTAL_EMOLUMENTO < 0) THEN
          BEGIN
            TOTAL_EMOLUMENTO = 0;
            TOTAL_FUNDO = 0;
          END
          TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
        END
        DESCRICAO = :V_DESCRICAO || ' (Dep.Prévio - Complemento)';
  
        QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
        TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO;

        ORDEM = :ORDEM + 1;

        SUSPEND;
      END
    END
  end
  else
  begin
    V_DATA_A_PESQUISAR = cast(:V_DATA_INI as date);
    WHILE (:V_DATA_A_PESQUISAR <= cast(:V_DATA_FIM as date)) DO
    BEGIN
        --INICIO REGISTRO DE IMOVEIS
        --REGISTRO DE IMOVEIS - SELECIONAR PROTOCOLADOS - ESCRITURACAO DE 100% - diferença de custas (entradas)
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        TOTAL_DESPESA = 0;
        V_DEPOSITO_INICIAL = 0;
    
        TOTAL_BRUTO = 0;
        QTDE = 0;
    
        FOR SELECT CAST(CI.DATA_PAGAMENTO AS DATE), COALESCE(CI.VALOR_PAGO,0),
              CI.CHAVE_SERVICO,
              EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
              EXTRACT(YEAR FROM CI.DATA_PAGAMENTO)
            FROM C_CAIXA_ITEM CI
            WHERE CI.tipo_servico = '1' --PROTOCOLO
            AND CI.DATA_PAGAMENTO = CAST(:V_DATA_A_PESQUISAR AS DATE)
            AND CI.tipo_transacao = 'C' --CREDITO
            AND CI.CAIXA_ITEM_ID <> (SELECT FIRST 1 CAIXA_ITEM_ID FROM C_CAIXA_ITEM
                                     WHERE TIPO_SERVICO = CI.TIPO_SERVICO
                                     AND CHAVE_SERVICO = CI.CHAVE_SERVICO
                                     ORDER BY DATA_PAGAMENTO) --IGNORAR PAGAMENTO INICIAL, POIS ENTROU COMO DEPOSITO PRENOTACAO
            INTO :DATA, :V_VALOR_BRUTO, :V_PROTOCOLO_ID, :MES, :ANO DO
        BEGIN
          V_RETORNAR = 'S';
          V_QTDE_CONSOLIDACAO = 0;
          DATA_HORA = :DATA;
          V_DATA_CAIXA = :DATA; --DATA EM FORMATO DATE
  
          SELECT PR.NUMERO_ORDEM, PR.TIPO_PROTOCOLO, PR.PEDIDO_ID, PE.TIPO_COBRANCA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
            (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
            (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO
          FROM r_protocolo PR, r_pedido PE
          where pr.pedido_id = pe.pedido_id
          and pr.protocolo_id = :v_protocolo_id
          into :NUMERO_PROTOCOLO, :TIPO_PROTOCOLO, :ID, :V_TIPO_COBRANCA, :V_TIPO_ORIGEM_SITE, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO;
      
          SISTEMA_ID = 1;
          TIPO_RETORNO = 1; --1=PRENOTACAO-Complemento de depósito (100%)
  
          IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
          BEGIN
            NATUREZA = 'Registro/Averbação';
          END
          ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            NATUREZA = 'Averbação';
          END
          ELSE
          BEGIN
            NATUREZA = 'Registro';
          END    
      
          IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
          BEGIN
            V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
          END
          ELSE
          BEGIN
            --PEGAR DATA DO REGISTRO
            SELECT COUNT(*) FROM R_PROTOCOLO PR, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
            WHERE PR.PEDIDO_ID = A.PEDIDO_ID
            AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
            AND PR.PROTOCOLO_ID = :V_PROTOCOLO_ID
            AND TA.TIPO = 'R' --REGISTRADOS
            INTO :V_COUNT_REGISTRO;
    
            if (COALESCE(:V_COUNT_REGISTRO,0) > 0) then
            begin
              SELECT FIRST 1 A.DATA FROM R_PROTOCOLO PR, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
              WHERE PR.PEDIDO_ID = A.PEDIDO_ID
              AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
              AND PR.PROTOCOLO_ID = :V_PROTOCOLO_ID
              AND TA.TIPO = 'R' --REGISTRADOS
              INTO :V_DATA_REGISTRO;
    
              if (:V_DATA_CAIXA > :V_DATA_REGISTRO) then
              begin
                V_RETORNAR = 'N';
              end
            end
            if (:V_RETORNAR = 'S') then
            begin
              SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
              WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
              AND I.PEDIDO_ID = :ID
              AND COALESCE(N.CONSOLIDACAO,'') = 'S'
              INTO :V_QTDE_CONSOLIDACAO;
      
              if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
              begin
                V_RETORNAR = 'N';
              end
              else
              begin
                V_RETORNAR = 'S';
              end
            end
          END
      
          if (:V_RETORNAR = 'S') THEN
          BEGIN
            if (COALESCE(:V_VALOR_BRUTO,0) <= 0) then
            BEGIN
              V_VALOR_BRUTO = 0;
            END
            V_VALOR_EMOLUMENTO = CAST(COALESCE((:V_VALOR_BRUTO * 0.9346),0) AS NUMERIC(18,2));
            V_VALOR_FUNDO = (:V_VALOR_BRUTO - :V_VALOR_EMOLUMENTO);
            V_VALOR_TAXA_JUDICIARIA = 0;
    
            SELECT T.DESCRICAO
            FROM R_PEDIDO PE, R_TB_TITULO T
            WHERE PE.PEDIDO_ID = :ID
            AND PE.tb_titulo_id = T.tb_titulo_id
            INTO :V_NATUREZA_FORMAL;
        
            V_DESCRICAO = 'PROTOCOLO '||CAST(:NUMERO_PROTOCOLO AS VARCHAR(10))||' - [100%] - '||:V_NATUREZA_FORMAL;
            IF (:V_QTDE_REGISTRO > 0) THEN
            BEGIN
              V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
            END
            IF (:V_QTDE_AVERBACAO > 0) THEN
            BEGIN
              V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
            END
            IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
            BEGIN
              TOTAL_EMOLUMENTO = 0;
              TOTAL_TAXA_JUDICIARIA = 0;
              TOTAL_FUNDO = 0;
              V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
            END
            ELSE
            BEGIN
              TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
              TOTAL_FUNDO = :V_VALOR_FUNDO;
              IF (:TOTAL_EMOLUMENTO < 0) THEN
              BEGIN
                TOTAL_EMOLUMENTO = 0;
                TOTAL_FUNDO = 0;
              END
              TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
            END
            DESCRICAO = :V_DESCRICAO || ' (Dep.Prévio - Complemento)';
      
            QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
            TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO;
    
            ORDEM = :ORDEM + 1;
  
            SUSPEND;
          END
        END
        V_DATA_A_PESQUISAR = :V_DATA_A_PESQUISAR + 1;
    end
  END
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_COMP_NOVO (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
PROTOCOLO_ANTERIOR INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
declare variable V_VALOR_EMOLUMENTO numeric(18,2);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(18,2);
declare variable V_VALOR_FUNDO numeric(18,2);
declare variable V_VALOR_BRUTO numeric(18,2);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_QTDE_REGISTRO integer;
declare variable V_QTDE_AVERBACAO integer;
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(1);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(1);
declare variable V_RETORNAR varchar(1);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_CREDITO_INICIAL numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_DATA_PROT_TEMP date;
declare variable V_VALOR_COMPENSADO numeric(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_SQL varchar(3000);
declare variable v_periodo_padrao integer;
declare variable V_PEDIDO_ANTERIOR_ID integer;
declare variable V_PEDIDO_NOVO_ID integer;
declare variable V_PERIODO_PADRAO_ANTERIOR integer;
declare variable V_TOTAL_PEDIDO numeric(18,2);
declare variable V_TOTAL_PEDIDO_75 numeric(18,2);
declare variable V_TOTAL_DESCONTAR numeric(18,2);
BEGIN
  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  ORDEM = 0;
  PROTOCOLO_ANTERIOR = 0;

  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  TOTAL_DESPESA = 0;

  TOTAL_BRUTO = 0;
  QTDE = 0;

  NUMERO_ONLINE = '';

  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = 'SELECT CAST(PR.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          PE.TIPO_COBRANCA,
          (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
          (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
          PR.DATA,
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM PR.DATA),
          EXTRACT(YEAR FROM PR.DATA),
          (SELECT COALESCE(TOTAL_EMOLUMENTO,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
          (SELECT COALESCE(TOTAL_FUNDO_RI,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_FUNDO_RI,
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          pe.novo_pedido_id
        FROM R_PROTOCOLO PR, R_PEDIDO PE
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        and coalesce(pe.novo_pedido_id,0) > 0
        and (select COALESCE(VALOR_COMPENSADO,0) from r_pedido where pedido_id = pe.novo_pedido_id) > 0
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||
        ' ORDER BY 1,2';
  end
  else
  begin
    V_SQL = 'SELECT CAST(PR.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          PE.TIPO_COBRANCA,
          (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
          (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
          PR.DATA,
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM PR.DATA),
          EXTRACT(YEAR FROM PR.DATA),
          (SELECT COALESCE(TOTAL_EMOLUMENTO,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
          (SELECT COALESCE(TOTAL_FUNDO_RI,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_FUNDO_RI,
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          pe.novo_pedido_id
        FROM R_PROTOCOLO PR, R_PEDIDO PE
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        and coalesce(pe.novo_pedido_id,0) > 0
        and (select COALESCE(VALOR_COMPENSADO,0) from r_pedido where pedido_id = pe.novo_pedido_id) > 0
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND (select count(*) from r_protocolo pr2, r_pedido pe2
             where pr2.pedido_id = pe2.pedido_id
             and cast(pr2.data as date) BETWEEN '||''''||:V_DATA_INI||''''||' AND '||''''||:V_DATA_FIM||''''||'
             and pe2.pedido_id = pe.novo_pedido_id) > 0
        ORDER BY 1,2';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
          :V_TIPO_COBRANCA, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
          :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO,
          :TOTAL_EMOLUMENTO, :TOTAL_FUNDO, :NUMERO_ONLINE, :V_NOVO_PEDIDO_ID DO
  BEGIN
    V_QTDE_CONSOLIDACAO = 0;
    SISTEMA_ID = 1;

    V_TOTAL_PEDIDO = coalesce(:TOTAL_EMOLUMENTO,0) + coalesce(:TOTAL_FUNDO,0);

    IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
    BEGIN
      V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
    END
    ELSE
    BEGIN
      SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
      WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
      AND I.PEDIDO_ID = :ID
      AND COALESCE(N.CONSOLIDACAO,'') = 'S'
      INTO :V_QTDE_CONSOLIDACAO;

      if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
      begin
        V_RETORNAR = 'N';
      end
      else
      begin
        V_RETORNAR = 'S';
      end
    END
  
    if (:V_RETORNAR = 'S') then
    begin
      ORDEM = :ORDEM + 1;

      V_TOTAL_DESCONTAR = 0;

      SELECT PR.NUMERO_ORDEM, coalesce(pe.valor_compensado,0), coalesce(pe.pedido_id,0), pr.data
      FROM R_PROTOCOLO PR, R_PEDIDO PE
      WHERE PR.pedido_id = PE.pedido_id
      AND PR.TIPO_PROTOCOLO = '1'
      AND PE.pedido_id = :V_NOVO_PEDIDO_ID
      INTO :V_NOVO_PROTOCOLO, :V_VALOR_COMPENSADO, V_PEDIDO_NOVO_ID, :V_DATA_PROT_TEMP;

      DATA = :V_DATA_PROT_TEMP;

      V_TOTAL_PEDIDO_75 = CAST((:V_TOTAL_PEDIDO * 0.75) AS NUMERIC(18,2));

      if ((COALESCE(:V_VALOR_COMPENSADO,0) - COALESCE(:V_TOTAL_PEDIDO_75,0)) > (COALESCE(:V_TOTAL_PEDIDO,0) - COALESCE(:V_TOTAL_PEDIDO_75,0))) then
      begin
        V_TOTAL_DESCONTAR = COALESCE(:V_TOTAL_PEDIDO,0) - COALESCE(:V_TOTAL_PEDIDO_75,0);
      end
      else
      begin
        V_TOTAL_DESCONTAR = COALESCE(:V_VALOR_COMPENSADO,0) - COALESCE(:V_TOTAL_PEDIDO_75,0);
      end

      TIPO_RETORNO = 7; --7=Aproveitamento em novo protocolo
      NATUREZA = 'Aproveitamento de valor em novo protocolo';

      TOTAL_DESPESA = COALESCE(:V_VALOR_COMPENSADO,0) - COALESCE(:V_TOTAL_DESCONTAR,0);

      if (coalesce(:TOTAL_DESPESA,0) > 0) then
      begin
        SUSPEND;
      end
    end
  end
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_DEVOLUCAO (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
PROTOCOLO_ANTERIOR INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
declare variable V_VALOR_BRUTO numeric(18,2);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(1);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(1);
declare variable V_RETORNAR varchar(1);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_DEPOSITO_INICIAL numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_CONSOLIDACAO varchar(1);
declare variable V_DATA_PROT_TEMP date;
declare variable V_VALOR_COMPENSADO numeric(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_TOTAL_GERAL numeric(18,2);
declare variable V_TOTAL_GERAL_75 numeric(18,2);
declare variable V_VALOR_DEVOLVIDO numeric(18,2);

declare variable V_TOTAL_PROTOCOLO_TEMP numeric(18,2);

declare variable V_PEDIDO_ANTERIOR integer;
declare variable V_TOTAL_PEDIDO_ANTERIOR NUMERIC(18,2);
declare variable V_COMPENSADO_100 varchar(5);
declare variable V_COMPENSADO_75 varchar(5);
declare variable V_REG_AV VARCHAR(3);
declare variable V_SQL varchar(3000);
declare variable V_VALOR_COMPENSADO_100_EM_POSTERIOR NUMERIC(18,2);
declare variable V_TOTAL_PEDIDO NUMERIC(18,2);
DECLARE VARIABLE V_PERIODO_PADRAO VARCHAR(10);
declare variable V_STATUS_SELO_DIGITAL VARCHAR(3);
declare variable V_SERVICO_DEVOLUCAO_TJDFT varchar(10);
declare variable V_SERVICO_DEVOLUCAO_75 varchar(10);
declare variable V_DATA_PROTOCOLO date;
declare variable V_VALOR_DEVOLUCAO NUMERIC(18,2);
declare variable V_VALOR_ISS NUMERIC(18,2);
declare variable V_DEVOLUCAO_JUIZO VARCHAR(3);

BEGIN
  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  ORDEM = 0;
  PROTOCOLO_ANTERIOR = 0;

  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  TOTAL_DESPESA = 0;
  TOTAL_BRUTO = 0;
  QTDE = 0;
  NUMERO_ONLINE = '';

  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;

  --BUSCAR VALORES DE PARAMETROS
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_TJDFT'
  INTO :V_SERVICO_DEVOLUCAO_TJDFT;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_75'
  INTO :V_SERVICO_DEVOLUCAO_75;

  --cancelamentos
  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT CAST(C.DATA_PAGAMENTO AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          C.DATA_PAGAMENTO, COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          COALESCE(C.valor_pago,0),
          EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
          EXTRACT(YEAR FROM C.DATA_PAGAMENTO),
          COALESCE(TA.STATUS_SELO_DIGITAL,'||''''||''''||'),
          COALESCE(PE.NOVO_PEDIDO_ID,0),
          PR.DATA AS DATA_PROTOCOLO,
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          COALESCE(C.CAIXA_SERVICO_ID,0)
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA,
          C_CAIXA_ITEM C
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND C.CHAVE_SERVICO = PR.PROTOCOLO_ID
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND (TA.TIPO = '||''''||'C'||''''||') --Cancelados
        AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
        AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.PEDIDO_ID = PE.PEDIDO_ID
                              AND TA2.TIPO = '||''''||'C'||''''||'
                              ORDER BY A2.ANDAMENTO_ID)
        AND (C.tipo_transacao = '||''''||'D'||''''||') --Debito
        ORDER BY 1,2 ';
  end
  else
  begin
    V_SQL = ' SELECT CAST(C.DATA_PAGAMENTO AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          C.DATA_PAGAMENTO, COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          COALESCE(C.valor_pago,0),
          EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
          EXTRACT(YEAR FROM C.DATA_PAGAMENTO),
          COALESCE(TA.STATUS_SELO_DIGITAL,'||''''||''''||'),
          COALESCE(PE.NOVO_PEDIDO_ID,0),
          PR.DATA AS DATA_PROTOCOLO,
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          COALESCE(C.CAIXA_SERVICO_ID,0)
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA,
          C_CAIXA_ITEM C
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND C.CHAVE_SERVICO = PR.PROTOCOLO_ID
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND (TA.TIPO = '||''''||'C'||''''||') --Cancelados
        AND C.DATA_PAGAMENTO BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
        AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.PEDIDO_ID = PE.PEDIDO_ID
                              AND TA2.TIPO = '||''''||'C'||''''||'
                              ORDER BY A2.ANDAMENTO_ID)
        AND (C.tipo_transacao = '||''''||'D'||''''||') --Debito
        ORDER BY 1,2 ';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,   :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA,
           :DATA_HORA, :V_TIPO_ORIGEM_SITE, :V_VALOR_DEVOLUCAO, :MES, :ANO,
           :V_STATUS_SELO_DIGITAL, :V_NOVO_PEDIDO_ID, :V_DATA_PROTOCOLO, :NUMERO_ONLINE, :V_CAIXA_SERVICO_ID DO
  BEGIN
    V_QTDE_CONSOLIDACAO = 0;
    SISTEMA_ID = 1;
    IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
    BEGIN
      V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
    END
    /*ELSE IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
    BEGIN
      V_RETORNAR = 'N';
    END*/
    ELSE
    BEGIN
      SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
      WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
      AND I.PEDIDO_ID = :ID
      AND COALESCE(N.CONSOLIDACAO,'') = 'S'
      INTO :V_QTDE_CONSOLIDACAO;

      if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
      begin
        V_RETORNAR = 'N';
      end
      else
      begin
        V_RETORNAR = 'S';
      end
    END

    if (:V_RETORNAR = 'S') THEN
    BEGIN
      --verificar se foi compensação de 100% para novo protocolo
      V_VALOR_COMPENSADO_100_EM_POSTERIOR = 0;
      V_COMPENSADO_100 = 'N';
      V_COMPENSADO_75 = 'N';
      V_TOTAL_PEDIDO = 0;

      select first 1 emolumento_periodo_id from g_emolumento_periodo ep
      where :V_DATA_PROTOCOLO >= ep.data_inicial
      order by ep.data_inicial
      into :v_periodo_padrao;

      SELECT (COALESCE(TOTAL_EMOLUMENTO,0) + COALESCE(TOTAL_FUNDO_RI,0)),
             COALESCE(QUANTIDADE_REGISTRO,0) AS QTDE_REGISTRO,
             COALESCE(QUANTIDADE_AVERBACAO,0) AS QTDE_AVERBACAO,
             COALESCE(TOTAL_ISS,0)
      FROM R_TOTAL_PEDIDO_DF(:ID, :v_periodo_padrao)
      INTO :V_TOTAL_PEDIDO, :qtde_reg, :qtde_av, :V_VALOR_ISS;

      if (coalesce(:V_NOVO_PEDIDO_ID,0) > 0) then
      begin
        select coalesce(pe.valor_compensado,0) from r_pedido pe
        where pe.pedido_id = :V_NOVO_PEDIDO_ID
        into :V_VALOR_COMPENSADO_100_EM_POSTERIOR;

        if (:V_VALOR_COMPENSADO_100_EM_POSTERIOR >= (:V_TOTAL_PEDIDO+:V_VALOR_ISS)) then --COMPENSACAO DE 100%
        begin
          V_COMPENSADO_100 = 'S';
        end
        else if (:V_VALOR_COMPENSADO_100_EM_POSTERIOR > 0) then --COMPENSACAO DE 75%
        begin
          V_COMPENSADO_75 = 'S';
        end
      end

      V_DEVOLUCAO_JUIZO = '';
      if (:V_CAIXA_SERVICO_ID > 0) then
      begin
        select coalesce(devolucao_juizo,'') from c_caixa_servico
        where caixa_servico_id = :v_caixa_servico_id
        into :V_DEVOLUCAO_JUIZO;
      end

      if (coalesce(:V_COMPENSADO_100,'') = 'S') then
      begin
        TIPO_RETORNO = 7; --7=Aproveitamento em novo protocolo de 100%
        NATUREZA = 'Aproveitamento de valor em novo protocolo';
        TOTAL_DESPESA = COALESCE(:V_VALOR_COMPENSADO_100_EM_POSTERIOR,0);
      end
      else if (coalesce(:V_COMPENSADO_75,'') = 'S') then
      begin
        TIPO_RETORNO = 7; --7=Aproveitamento em novo protocolo de 75%
        NATUREZA = 'Aproveitamento de valor em novo protocolo';
        TOTAL_DESPESA = COALESCE(:V_VALOR_COMPENSADO_100_EM_POSTERIOR,0);
      end
      else if ((:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) or (:V_DEVOLUCAO_JUIZO = 'S'))  then
      begin
        TIPO_RETORNO = 8; --8=DEVOLUÇÃO À VARA DE REGISTROS PUBLICOS
        NATUREZA = 'Devolução à Vara de Registros Públicos';
        TOTAL_DESPESA = COALESCE(:V_VALOR_DEVOLUCAO,0);
      end
      else if ((COALESCE(:V_STATUS_SELO_DIGITAL,'') = '88')) then --SE HOUVE DEVOLUÇÃO DE 100%
      begin
        TIPO_RETORNO = 6; --6=DEVOLUÇÃO AO USUÁRIO DE 100%
        NATUREZA = 'Devolução ao usuário (100%)';
        if ((:V_TOTAL_PEDIDO+:V_VALOR_ISS) < COALESCE(:V_VALOR_DEVOLUCAO,0)) then
        begin
          TOTAL_DESPESA = COALESCE(:V_VALOR_DEVOLUCAO,0);
        end
        else
        begin
          TOTAL_DESPESA = (:V_TOTAL_PEDIDO+:V_VALOR_ISS);
        end
      end
      else
      begin
        if (COALESCE(:V_VALOR_DEVOLUCAO,0) >= (:V_TOTAL_PEDIDO+:V_VALOR_ISS)) then
        begin
          TIPO_RETORNO = 6; --6=DEVOLUÇÃO AO USUÁRIO DE 100%
          NATUREZA = 'Devolução ao usuário (100%)';
        end
        else
        begin
          TIPO_RETORNO = 5; --5=DEVOLUÇÃO AO USUÁRIO DE 75%
          NATUREZA = 'Devolução ao usuário (75%)';
        end
        TOTAL_DESPESA = COALESCE(:V_VALOR_DEVOLUCAO,0);
      end

      V_DESCRICAO = :V_NATUREZA_FORMAL;
      IF (:qtde_reg > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_reg||' REGISTRO(S)';
      END
      IF (:qtde_av > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_av||' AVERBAÇÃO(S)';
      END
      DESCRICAO = :V_DESCRICAO;
      ORDEM = :ORDEM + 1;

      if (coalesce(:TOTAL_DESPESA,0) > 0) then
      begin
        TOTAL_ISS = round((TOTAL_DESPESA * 5),2);
        TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);
        TOTAL_GERAL_COM_ISS = :TOTAL_DESPESA;
        TOTAL_DESPESA = :TOTAL_DESPESA - :TOTAL_ISS;

        SUSPEND;
      end
    END
  END

  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  ORDEM = 0;
  PROTOCOLO_ANTERIOR = 0;

  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  TOTAL_DESPESA = 0;
  TOTAL_BRUTO = 0;
  QTDE = 0;
  NUMERO_ONLINE = '';

  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;

  --Devolução de registros
  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT CAST(C.DATA_PAGAMENTO AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          C.DATA_PAGAMENTO, COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          COALESCE(C.valor_pago,0),
          EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
          EXTRACT(YEAR FROM C.DATA_PAGAMENTO),
          COALESCE(TA.STATUS_SELO_DIGITAL,'||''''||''''||'),
          COALESCE(PE.NOVO_PEDIDO_ID,0),
          PR.DATA AS DATA_PROTOCOLO,
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          COALESCE(C.CAIXA_SERVICO_ID,0)
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA,
          C_CAIXA_ITEM C
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND C.CHAVE_SERVICO = PR.PROTOCOLO_ID
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND (TA.TIPO = '||''''||'R'||''''||') --Registrados
        AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
        AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.PEDIDO_ID = PE.PEDIDO_ID
                              AND TA2.TIPO = '||''''||'R'||''''||'
                              ORDER BY A2.ANDAMENTO_ID)
        AND (C.tipo_transacao = '||''''||'D'||''''||') --Debito
        ORDER BY 1,2 ';
  end
  else
  begin
    V_SQL = ' SELECT CAST(C.DATA_PAGAMENTO AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          C.DATA_PAGAMENTO, COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          COALESCE(C.valor_pago,0),
          EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
          EXTRACT(YEAR FROM C.DATA_PAGAMENTO),
          COALESCE(TA.STATUS_SELO_DIGITAL,'||''''||''''||'),
          COALESCE(PE.NOVO_PEDIDO_ID,0),
          PR.DATA AS DATA_PROTOCOLO,
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          COALESCE(C.CAIXA_SERVICO_ID,0)
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA,
          C_CAIXA_ITEM C
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND C.CHAVE_SERVICO = PR.PROTOCOLO_ID
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND (TA.TIPO = '||''''||'R'||''''||') --Registrados
        AND C.DATA_PAGAMENTO BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
        AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.PEDIDO_ID = PE.PEDIDO_ID
                              AND TA2.TIPO = '||''''||'R'||''''||'
                              ORDER BY A2.ANDAMENTO_ID)
        AND (C.tipo_transacao = '||''''||'D'||''''||') --Debito
        ORDER BY 1,2 ';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,   :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA,
           :DATA_HORA, :V_TIPO_ORIGEM_SITE, :V_VALOR_DEVOLUCAO, :MES, :ANO,
           :V_STATUS_SELO_DIGITAL, :V_NOVO_PEDIDO_ID, :V_DATA_PROTOCOLO, :NUMERO_ONLINE, :V_CAIXA_SERVICO_ID DO
  BEGIN
    V_QTDE_CONSOLIDACAO = 0;
    SISTEMA_ID = 1;

    IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
    BEGIN
      V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
    END
    /*ELSE IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
    BEGIN
      V_RETORNAR = 'N';
    END*/
    ELSE
    BEGIN
      SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
      WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
      AND I.PEDIDO_ID = :ID
      AND COALESCE(N.CONSOLIDACAO,'') = 'S'
      INTO :V_QTDE_CONSOLIDACAO;

      if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
      begin
        V_RETORNAR = 'N';
      end
      else
      begin
        V_RETORNAR = 'S';
      end
    END

    V_DEVOLUCAO_JUIZO = '';
    if (:V_CAIXA_SERVICO_ID > 0) then
    begin
      select coalesce(devolucao_juizo,'') from c_caixa_servico
      where caixa_servico_id = :v_caixa_servico_id
      into :V_DEVOLUCAO_JUIZO;
    end

    if (:V_RETORNAR = 'S') THEN
    BEGIN
      if (cast(:V_CAIXA_SERVICO_ID as varchar(10)) = :V_SERVICO_DEVOLUCAO_75) then
      begin
        TIPO_RETORNO = 5; --6=DEVOLUÇÃO AO USUÁRIO DE 75%
        NATUREZA = 'Devolução ao usuário (75%)';
      end
      else
      begin
        TIPO_RETORNO = 6; --6=DEVOLUÇÃO AO USUÁRIO DE 100%
        NATUREZA = 'Devolução ao usuário (100%)';
      end
      TOTAL_DESPESA = COALESCE(:V_VALOR_DEVOLUCAO,0);

      V_DESCRICAO = :V_NATUREZA_FORMAL;
      IF (:qtde_reg > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_reg||' REGISTRO(S)';
      END
      IF (:qtde_av > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_av||' AVERBAÇÃO(S)';
      END
      DESCRICAO = :V_DESCRICAO;
      ORDEM = :ORDEM + 1;
      if (coalesce(:TOTAL_DESPESA,0) > 0) then
      begin
        TOTAL_ISS = round((TOTAL_DESPESA * 5),2);
        TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);
        TOTAL_GERAL_COM_ISS = :TOTAL_DESPESA;
        TOTAL_DESPESA = :TOTAL_DESPESA - :TOTAL_ISS;

        SUSPEND;
      end
    END
  END

  --Devolução TJDFT
  if (COALESCE(:VP_PROTOCOLO_ID,0) = 0) then
  begin
    V_SQL = ' SELECT CAST(C.DATA_PAGAMENTO AS DATE),
          NULL,
          NULL,
          NULL,
          NULL,
          NULL,
          C.DATA_PAGAMENTO, null,
          COALESCE(C.valor_pago,0),
          EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
          EXTRACT(YEAR FROM C.DATA_PAGAMENTO),
          NULL,
          NULL,
          NULL,
          NULL,
          COALESCE(C.CAIXA_SERVICO_ID,0)
        FROM C_CAIXA_ITEM C, C_CAIXA_SERVICO S
        WHERE C.caixa_servico_id = S.caixa_servico_id
        AND C.DATA_PAGAMENTO BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
        AND COALESCE(s.devolucao_juizo,'||''''||''''||') = '||''''||'S'||''''||'
        AND COALESCE(s.emitir_relatorio,'||''''||''''||') = '||''''||'S'||''''||'
        AND (C.tipo_transacao = '||''''||'D'||''''||') --Debito
        ORDER BY 1,2 ';
    FOR EXECUTE STATEMENT V_SQL
        INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,   :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA,
             :DATA_HORA, :V_TIPO_ORIGEM_SITE, :V_VALOR_DEVOLUCAO, :MES, :ANO,
             :V_STATUS_SELO_DIGITAL, :V_NOVO_PEDIDO_ID, :V_DATA_PROTOCOLO, :NUMERO_ONLINE, :V_CAIXA_SERVICO_ID DO
    BEGIN
      V_QTDE_CONSOLIDACAO = 0;
      SISTEMA_ID = 1;
      V_RETORNAR = 'S';
      TIPO_RETORNO = 8; --8=DEVOLUÇÃO À VARA DE REGISTROS PUBLICOS
      NATUREZA = 'Devolução à Vara de Registros Públicos';
      TOTAL_DESPESA = COALESCE(:V_VALOR_DEVOLUCAO,0);
      V_DESCRICAO = :V_NATUREZA_FORMAL;
      IF (:qtde_reg > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_reg||' REGISTRO(S)';
      END
      IF (:qtde_av > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_av||' AVERBAÇÃO(S)';
      END
      DESCRICAO = 'DEVOLUÇÃO À VARA DE REGISTROS PUBLICOS';
      ORDEM = :ORDEM + 1;
      if (coalesce(:TOTAL_DESPESA,0) > 0) then
      begin
        TOTAL_ISS = 0;
        TOTAL_GERAL_COM_ISS = :TOTAL_DESPESA;
        TOTAL_DESPESA = :TOTAL_DESPESA - :TOTAL_ISS;

        SUSPEND;
      end
    END
  END
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_ENTRADA (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
PROTOCOLO_ANTERIOR INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
declare variable V_VALOR_EMOLUMENTO numeric(18,2);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(18,2);
declare variable V_VALOR_FUNDO numeric(18,2);
declare variable V_VALOR_BRUTO numeric(18,2);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_QTDE_REGISTRO integer;
declare variable V_QTDE_AVERBACAO integer;
declare variable V_ORIGEM_PEDIDO varchar(3);
declare variable V_TIPO_DESPESA varchar(3);
declare variable V_REPASSE varchar(3);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(3);
declare variable V_RETORNAR varchar(3);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_CREDITO_INICIAL numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_DATA_PROT_TEMP date;
declare variable V_VALOR_COMPENSADO numeric(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_TOTAL_GERAL numeric(18,2);
declare variable V_TOTAL_GERAL_75 numeric(18,2);
declare variable V_SQL varchar(3000);
BEGIN
  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  ORDEM = 0;
  PROTOCOLO_ANTERIOR = 0;

  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  TOTAL_DESPESA = 0;

  TOTAL_BRUTO = 0;
  QTDE = 0;

  NUMERO_ONLINE = '';

  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT CAST(CI.DATA_PAGAMENTO AS DATE), PR.NUMERO_ORDEM,
                PR.PEDIDO_ID,
                PR.TIPO_PROTOCOLO,
                COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
                EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
                EXTRACT(YEAR FROM CI.DATA_PAGAMENTO),
                COALESCE(CI.VALOR_PAGO,0)
              FROM C_CAIXA_ITEM CI, R_PROTOCOLO PR, R_PEDIDO PE
              WHERE CI.CHAVE_SERVICO = PR.PROTOCOLO_ID
              AND PR.PEDIDO_ID = PE.PEDIDO_ID
              AND CI.tipo_servico = '||''''||'1'||''''||'
              AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
              AND CI.tipo_transacao = '||''''||'C'||''''||'
              AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||
             ' ORDER BY 1,2';
  end
  else
  begin
    V_SQL = ' SELECT CAST(CI.DATA_PAGAMENTO AS DATE), PR.NUMERO_ORDEM,
                PR.PEDIDO_ID,
                PR.TIPO_PROTOCOLO,
                COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
                EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
                EXTRACT(YEAR FROM CI.DATA_PAGAMENTO),
                COALESCE(CI.VALOR_PAGO,0)
              FROM C_CAIXA_ITEM CI, R_PROTOCOLO PR, R_PEDIDO PE
              WHERE CI.CHAVE_SERVICO = PR.PROTOCOLO_ID
              AND PR.PEDIDO_ID = PE.PEDIDO_ID
              AND CI.tipo_servico = '||''''||'1'||''''||'
              AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
              AND CI.tipo_transacao = '||''''||'C'||''''||'
              AND CI.DATA_PAGAMENTO BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
              ORDER BY 1,2';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
           :V_TIPO_ORIGEM_SITE, :MES, :ANO, :TOTAL_BRUTO DO
  BEGIN
    V_QTDE_CONSOLIDACAO = 0;
    SISTEMA_ID = 1;
    DATA_HORA = :DATA;
    TOTAL_ISS = 0;

    IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
    BEGIN
      V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
    END
    ELSE
    BEGIN
      SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
      WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
      AND I.PEDIDO_ID = :ID
      AND COALESCE(N.CONSOLIDACAO,'') = 'S'
      INTO :V_QTDE_CONSOLIDACAO;

      if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
      begin
        V_RETORNAR = 'N';
      end
      else
      begin
        V_RETORNAR = 'S';
      end
    END

    if (:V_RETORNAR = 'S') then
    begin
      ORDEM = :ORDEM + 1;

      if (coalesce(:TOTAL_BRUTO,0) > 0) then
      begin
        if (:ANO > 2021) then
        begin
          if ((:ANO = 2022) and (:MES < 7))then
          begin
            -- nao faca nada
          end
          else
          begin
            TOTAL_ISS = round((total_bruto * 5),2);
            TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);
            TOTAL_GERAL_COM_ISS = :total_bruto;
            total_bruto = :total_bruto - :TOTAL_ISS;
          end
        end
        TIPO_RETORNO = 1; --1=PRENOTACAO, DEPÓSITO PRÉVIO DE 100% RI/DF
        NATUREZA = 'Valor Recebido';
        SUSPEND;
      end
    END
  END
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_NEW (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (TIPO_LIVRO VARCHAR(50) CHARACTER SET ISO8859_1,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
QTDE_REVAL INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
PROTOCOLO_ANTERIOR INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
