TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
declare variable VSEQ INTEGER;
declare variable VORDEM INTEGER;
BEGIN
  if (:V_DATA_INI = '01.03.2024') then
  begin
    V_DATA_INI = '18.03.2024';
  end

  FOR SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'ENTRADAS (DEPÓSITO PRÉVIO)', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_ENTRADA(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  UNION ALL
  SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'ENTRADAS (DEPÓSITO PRÉVIO)', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_APROVEITA(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  UNION ALL
  SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'ENTRADAS (DEPÓSITO PRÉVIO)', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_COMP_NOVO(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  UNION ALL
  SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'SAÍDAS', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_SAIDA_100(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  UNION ALL
  SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'SAÍDAS', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_SAIDA_25(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  UNION ALL
  SELECT DATA, TIPO_RETORNO, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
    TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
    TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
    TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
    TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
    TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
    TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA,
    TOTAL_FUNDO_FOLHA, QTDE_FOLHA,  PROTOCOLO_ANTERIOR, 'SAÍDAS', NUMERO_ONLINE,
    TOTAL_ISS, TOTAL_GERAL_COM_ISS
    FROM C_DEPOSITO_PREVIO_DF_DEVOLUCAO(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
  ORDER BY 1, 2, 3
  INTO :DATA, :TIPO_RETORNO, :NUMERO_PROTOCOLO, :SISTEMA_ID, :ID, :DATA_HORA, :TIPO_PROTOCOLO, :NATUREZA, :DESCRICAO,
    :TOTAL_EMOLUMENTO, :TOTAL_TAXA_JUDICIARIA, :TOTAL_FUNDO, :TOTAL_DESPESA,
    :TOTAL_BRUTO, :TOTAL_DESCONTO, :TOTAL_COMPENSADO, :QTDE, :TOTAL_EMOLUMENTO_REG, :TOTAL_TAXA_REG,
    :TOTAL_FUNDO_REG, :QTDE_REG, :TOTAL_EMOLUMENTO_AV, :TOTAL_TAXA_AV, :TOTAL_FUNDO_AV, :QTDE_AV,
    :TOTAL_EMOLUMENTO_CERT, :TOTAL_TAXA_CERT, :TOTAL_FUNDO_CERT, :QTDE_CERT, :TOTAL_EMOLUMENTO_BUSCA,
    :TOTAL_TAXA_BUSCA, :TOTAL_FUNDO_BUSCA, :QTDE_BUSCA, :TOTAL_EMOLUMENTO_REVAL, :TOTAL_TAXA_REVAL,
    :TOTAL_FUNDO_REVAL, :QTDE_REVAL, :MES, :ANO, :TOTAL_EMOLUMENTO_FOLHA, :TOTAL_TAXA_FOLHA,
    :TOTAL_FUNDO_FOLHA, :QTDE_FOLHA,  :PROTOCOLO_ANTERIOR, :TIPO_LIVRO, :NUMERO_ONLINE, :TOTAL_ISS, :TOTAL_GERAL_COM_ISS DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_REG (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER)
AS 
declare variable V_VALOR_EMOLUMENTO numeric(18,2);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(18,2);
declare variable V_VALOR_FUNDO numeric(18,2);
declare variable V_VALOR_BRUTO numeric(18,2);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_QTDE_REGISTRO integer;
declare variable V_QTDE_AVERBACAO integer;
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(1);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(1);
declare variable V_RETORNAR varchar(1);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_PROTOCOLO_ID integer;
declare variable V_DEPOSITO_INICIAL numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_CONSOLIDACAO varchar(1);
declare variable V_DATA_PROT_TEMP date;
declare variable V_VALOR_COMPENSADO numeric(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_TOTAL_GERAL numeric(18,2);
declare variable V_TOTAL_GERAL_75 numeric(18,2);
declare variable V_DATA_REGISTRO date;
declare variable V_VALOR_DEVOLVIDO numeric(18,2);

declare variable V_OFICIO varchar(3);
declare variable V_DATA_PROTOCOLO date;

declare variable V_TOTAL_EMOLUMENTO_TEMP numeric(18,2);
declare variable V_TOTAL_FUNDO_TEMP numeric(18,2);
declare variable V_TOTAL_PROTOCOLO_TEMP numeric(18,2);
declare variable V_VALOR_COMPENSADO_ENTRADA numeric(18,2);

declare variable V_PEDIDO_ANTERIOR integer;
declare variable V_TOTAL_PEDIDO_ANTERIOR NUMERIC(18,2);
declare variable V_COMPENSADO_100 varchar(5);
BEGIN
  SELECT TRIM(C.VALOR) FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '5'
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'CARTORIO'
  AND C.NOME = 'CARTORIO_OFICIO'
  INTO :V_OFICIO;

  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  ORDEM = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    --SELECIONAR PROTOCOLOS REGISTRADOS DO RI 100% como saída
    --Lançamento como saída da conversão de 100% dado como depósito prévio em receita da serventia na data do registro/averbação
    TOTAL_EMOLUMENTO = 0;
    TOTAL_TAXA_JUDICIARIA = 0;
    TOTAL_FUNDO = 0;
    TOTAL_DESPESA = 0;

    TOTAL_BRUTO = 0;
    QTDE = 0;

    FOR SELECT CAST(A.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
          (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
          A.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
          EXTRACT(MONTH FROM A.DATA),
          EXTRACT(YEAR FROM A.DATA),
          PR.PROTOCOLO_ID,
          cast(pr.data as date),
          (SELECT COALESCE(TOTAL_EMOLUMENTO,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
          (SELECT COALESCE(TOTAL_FUNDO_RI,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_FUNDO_RI,
          COALESCE(PE.VALOR_COMPENSADO,0)
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PR.TIPO_PROTOCOLO = '1'
        AND TA.TIPO = 'R' --REGISTRADOS
        AND PR.PROTOCOLO_ID = :VP_PROTOCOLO_ID
        AND A.ANDAMENTO_ID = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.pedido_id = A.pedido_id
                              AND TA2.TIPO = 'R') --PEGAR SOMENTE 1º ANDAMENTO DE REGISTRO
        ORDER BY 1,2
        INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
          :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
          :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO, :V_PROTOCOLO_ID, :V_DATA_PROTOCOLO,
          :V_TOTAL_EMOLUMENTO_TEMP, :V_TOTAL_FUNDO_TEMP, :V_VALOR_COMPENSADO_ENTRADA DO
    BEGIN
      V_QTDE_CONSOLIDACAO = 0;
      SISTEMA_ID = 1;
      TIPO_RETORNO = 2; --2=LANCAMENTO COMO SAIDA DA CONVERSAO DO DEPOSITO PREVIO EM RECEITA (100%)
      V_DATA_REGISTRO = :DATA;

      IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
      BEGIN
        NATUREZA = 'Registro/Averbação';
      END
      ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
      BEGIN
        NATUREZA = 'Averbação';
      END
      ELSE
      BEGIN
        NATUREZA = 'Registro';
      END    

      IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
      BEGIN
        V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
      END
      ELSE
      BEGIN
        SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
        WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
        AND I.PEDIDO_ID = :ID
        AND COALESCE(N.CONSOLIDACAO,'') = 'S'
        INTO :V_QTDE_CONSOLIDACAO;
  
        if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
        begin
          V_RETORNAR = 'N';
        end
        else
        begin
          V_RETORNAR = 'S';
        end
      END

      if (:V_RETORNAR = 'S') THEN
      BEGIN
        --verificar se foi compensação de 100%
        V_COMPENSADO_100 = 'N';
        V_PEDIDO_ANTERIOR = null;
        V_TOTAL_PEDIDO_ANTERIOR = 0;
        if (coalesce(:V_VALOR_COMPENSADO_ENTRADA,0) > 0) then
        begin
          select pedido_id from r_pedido
          where novo_pedido_id = :ID
          into :V_PEDIDO_ANTERIOR;

          if (coalesce(:V_PEDIDO_ANTERIOR,0) > 0) then
          begin
            SELECT COALESCE(TOTAL_GERAL,0)
            FROM R_TOTAL_PEDIDO_DF(:V_PEDIDO_ANTERIOR)
            INTO :V_TOTAL_PEDIDO_ANTERIOR;

            if (:V_VALOR_COMPENSADO_ENTRADA = :V_TOTAL_PEDIDO_ANTERIOR) then --COMPENSACAO DE 100%
            begin
              V_COMPENSADO_100 = 'S';
              V_VALOR_COMPENSADO_ENTRADA = CAST((:V_VALOR_COMPENSADO_ENTRADA * 0.75) AS NUMERIC(18,2));
            end
          end
        end

        V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [100%] - '||:V_NATUREZA_FORMAL;
        IF (:V_QTDE_REGISTRO > 0) THEN
        BEGIN
          V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
        END
        IF (:V_QTDE_AVERBACAO > 0) THEN
        BEGIN
          V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
        END

        SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
        WHERE CI.tipo_servico = '1' --PROTOCOLO
        AND CI.CHAVE_SERVICO = :V_PROTOCOLO_ID
        AND CI.tipo_transacao = 'C' --CREDITO
        AND CI.data_pagamento <= :V_DATA_REGISTRO
        INTO :V_VALOR_BRUTO;
        V_VALOR_BRUTO = COALESCE(:V_VALOR_BRUTO,0) + COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0);

        SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
        WHERE CI.tipo_servico = '1' --PROTOCOLO
        AND CI.CHAVE_SERVICO = :V_PROTOCOLO_ID
        AND CI.tipo_transacao = 'D' --DEBITO
        AND CI.data_pagamento <= :V_DATA_REGISTRO
        INTO :V_VALOR_DEVOLVIDO;

        V_VALOR_BRUTO = COALESCE(:V_VALOR_BRUTO,0) - COALESCE(:V_VALOR_DEVOLVIDO,0);

        if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
        BEGIN
          V_VALOR_BRUTO = 0;
        END

        V_TOTAL_PROTOCOLO_TEMP = (coalesce(:V_TOTAL_EMOLUMENTO_TEMP,0) + coalesce(:V_TOTAL_FUNDO_TEMP,0));
        if (:V_VALOR_BRUTO > :V_TOTAL_PROTOCOLO_TEMP) then
        begin
          V_VALOR_BRUTO = :V_TOTAL_PROTOCOLO_TEMP;
        end

        if ((:V_DATA_PROTOCOLO <= '30.04.2021') and (:V_OFICIO <> '1')) then
        begin
          if (:V_VALOR_BRUTO > (:V_TOTAL_PROTOCOLO_TEMP*0.75)) then
          begin
            V_VALOR_BRUTO = :V_TOTAL_PROTOCOLO_TEMP * 0.75;
          end
        end

        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
    
        TOTAL_DESPESA = :V_VALOR_BRUTO;

        DESCRICAO = :V_DESCRICAO || ' (Registrado-->Conversão em receita)';
  
        QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
        TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO;
  
        ORDEM = :ORDEM + 1;

        SUSPEND;
      END
    end
  end
  else
  begin
    V_DATA_A_PESQUISAR = cast(:V_DATA_INI as date);
    WHILE (:V_DATA_A_PESQUISAR <= cast(:V_DATA_FIM as date)) DO
    BEGIN
      --SELECIONAR PROTOCOLOS REGISTRADOS DO RI 100% como saída
      --Lançamento como saída da conversão de 100% dado como depósito prévio em receita da serventia na data do registro/averbação
      TOTAL_EMOLUMENTO = 0;
      TOTAL_TAXA_JUDICIARIA = 0;
      TOTAL_FUNDO = 0;
      TOTAL_DESPESA = 0;
  
      TOTAL_BRUTO = 0;
      QTDE = 0;
  
      FOR SELECT CAST(A.DATA AS DATE),
            PR.NUMERO_ORDEM,
            PR.PEDIDO_ID,
            PR.TIPO_PROTOCOLO,
            T.DESCRICAO,
            PE.TIPO_COBRANCA,
            (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
            (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
            A.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
            EXTRACT(MONTH FROM A.DATA),
            EXTRACT(YEAR FROM A.DATA),
            PR.PROTOCOLO_ID,
            cast(pr.data as date),
            (SELECT COALESCE(TOTAL_EMOLUMENTO,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
            (SELECT COALESCE(TOTAL_FUNDO_RI,0) FROM R_TOTAL_PEDIDO_DF(PE.PEDIDO_ID)) AS TOTAL_FUNDO_RI,
            COALESCE(PE.VALOR_COMPENSADO,0)
          FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
          WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
          AND PE.TB_TITULO_ID = T.TB_TITULO_ID
          AND PE.PEDIDO_ID = A.PEDIDO_ID
          AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
          AND PR.TIPO_PROTOCOLO = '1'
          AND TA.TIPO = 'R' --REGISTRADOS
          AND A.DATA BETWEEN CAST(:V_DATA_A_PESQUISAR AS DATE) AND CAST(:V_DATA_A_PESQUISAR AS DATE) + 0.999
          AND A.ANDAMENTO_ID = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                                WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                                AND A2.pedido_id = A.pedido_id
                                AND TA2.TIPO = 'R') --PEGAR SOMENTE 1º ANDAMENTO DE REGISTRO
          ORDER BY 1,2
          INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
            :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
            :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO, :V_PROTOCOLO_ID, :V_DATA_PROTOCOLO,
            :V_TOTAL_EMOLUMENTO_TEMP, :V_TOTAL_FUNDO_TEMP, :V_VALOR_COMPENSADO_ENTRADA DO
      BEGIN
        V_QTDE_CONSOLIDACAO = 0;
        SISTEMA_ID = 1;
        TIPO_RETORNO = 2; --2=LANCAMENTO COMO SAIDA DA CONVERSAO DO DEPOSITO PREVIO EM RECEITA (100%)
        V_DATA_REGISTRO = :DATA;
  
        IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
        BEGIN
          NATUREZA = 'Registro/Averbação';
        END
        ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
        BEGIN
          NATUREZA = 'Averbação';
        END
        ELSE
        BEGIN
          NATUREZA = 'Registro';
        END    
  
        IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
        BEGIN
          V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
        END
        ELSE
        BEGIN
          SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
          WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
          AND I.PEDIDO_ID = :ID
          AND COALESCE(N.CONSOLIDACAO,'') = 'S'
          INTO :V_QTDE_CONSOLIDACAO;
    
          if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
          begin
            V_RETORNAR = 'N';
          end
          else
          begin
            V_RETORNAR = 'S';
          end
        END
  
        if (:V_RETORNAR = 'S') THEN
        BEGIN
          V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [100%] - '||:V_NATUREZA_FORMAL;
          IF (:V_QTDE_REGISTRO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
          END
          IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
          END
          --verificar se foi compensação de 100%
          V_PEDIDO_ANTERIOR = null;
          V_TOTAL_PEDIDO_ANTERIOR = 0;
          if (coalesce(:V_VALOR_COMPENSADO_ENTRADA,0) > 0) then
          begin
            select pedido_id from r_pedido
            where novo_pedido_id = :ID
            into :V_PEDIDO_ANTERIOR;
    
            if (coalesce(:V_PEDIDO_ANTERIOR,0) > 0) then
            begin
              SELECT COALESCE(TOTAL_GERAL,0)
              FROM R_TOTAL_PEDIDO_DF(:V_PEDIDO_ANTERIOR)
              INTO :V_TOTAL_PEDIDO_ANTERIOR;
    
              if (:V_VALOR_COMPENSADO_ENTRADA = :V_TOTAL_PEDIDO_ANTERIOR) then --COMPENSACAO DE 100%
              begin
                V_COMPENSADO_100 = 'S';
                V_VALOR_COMPENSADO_ENTRADA = CAST((:V_VALOR_COMPENSADO_ENTRADA * 0.75) AS NUMERIC(18,2));
              end
            end
          end

          SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
          WHERE CI.tipo_servico = '1' --PROTOCOLO
          AND CI.CHAVE_SERVICO = :V_PROTOCOLO_ID
          AND CI.tipo_transacao = 'C' --CREDITO
          AND CI.data_pagamento <= :V_DATA_REGISTRO
          INTO :V_VALOR_BRUTO;
          V_VALOR_BRUTO = COALESCE(:V_VALOR_BRUTO,0) + COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0);

          SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
          WHERE CI.tipo_servico = '1' --PROTOCOLO
          AND CI.CHAVE_SERVICO = :V_PROTOCOLO_ID
          AND CI.tipo_transacao = 'D' --DEBITO
          AND CI.data_pagamento <= :V_DATA_REGISTRO
          INTO :V_VALOR_DEVOLVIDO;

          V_VALOR_BRUTO = COALESCE(:V_VALOR_BRUTO,0) - COALESCE(:V_VALOR_DEVOLVIDO,0);
  
          if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
          BEGIN
            V_VALOR_BRUTO = 0;
          END

          V_TOTAL_PROTOCOLO_TEMP = (coalesce(:V_TOTAL_EMOLUMENTO_TEMP,0) + coalesce(:V_TOTAL_FUNDO_TEMP,0));
          if (:V_VALOR_BRUTO > :V_TOTAL_PROTOCOLO_TEMP) then
          begin
            V_VALOR_BRUTO = :V_TOTAL_PROTOCOLO_TEMP;
          end
  
          if ((:V_DATA_PROTOCOLO <= '30.04.2021') and (:V_OFICIO <> '1')) then
          begin
            if (:V_VALOR_BRUTO > (:V_TOTAL_PROTOCOLO_TEMP*0.75)) then
            begin
              V_VALOR_BRUTO = :V_TOTAL_PROTOCOLO_TEMP * 0.75;
            end
          end

          TOTAL_EMOLUMENTO = 0;
          TOTAL_TAXA_JUDICIARIA = 0;
          TOTAL_FUNDO = 0;
      
          TOTAL_DESPESA = :V_VALOR_BRUTO;
  
          DESCRICAO = :V_DESCRICAO || ' (Registrado-->Conversão em receita)';
    
          QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
          TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO;
    
          ORDEM = :ORDEM + 1;
  
          SUSPEND;
        END
      END
      V_DATA_A_PESQUISAR = :V_DATA_A_PESQUISAR + 1;
    end
  end
END;
 ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_REG_DEVOL (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER)
AS 
declare variable V_VALOR_EMOLUMENTO numeric(18,2);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(18,2);
declare variable V_VALOR_FUNDO numeric(18,2);
declare variable V_VALOR_DESCONTO numeric(18,2);
declare variable V_VALOR_DEVOLUCAO numeric(18,2);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_QTDE_REGISTRO integer;
declare variable V_QTDE_AVERBACAO integer;
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(1);
declare variable V_SERVICO_DEVOLUCAO_TJDFT varchar(10);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(1);
declare variable V_RETORNAR varchar(1);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_PROTOCOLO_ID integer;
declare variable V_DEPOSITO_INICIAL numeric(18,2);
declare variable V_CREDITO_INICIAL numeric(18,2);
declare variable V_TOTAL_PROTOCOLO numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_CONSOLIDACAO varchar(1);
declare variable V_DATA_PROT_TEMP date;
declare variable V_VALOR_COMPENSADO numeric(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_TOTAL_GERAL numeric(18,2);
declare variable V_TOTAL_GERAL_75 numeric(18,2);
declare variable V_NUMERO_CARTORIO varchar(5);
BEGIN
  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  --BUSCAR VALORES DE PARAMETROS
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_TJDFT'
  INTO :V_SERVICO_DEVOLUCAO_TJDFT;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'CARTORIO'
  AND C.NOME = 'CARTORIO_NUMERO'
  INTO :V_NUMERO_CARTORIO;


  ORDEM = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    --SELECIONAR PROTOCOLOS CANCELADOS DO RI 75% como devolução ao usuário
    --Lançamento como saída da conversão de 75% dado como depósito prévio como devolução ao usuario
    TOTAL_EMOLUMENTO = 0;
    TOTAL_TAXA_JUDICIARIA = 0;
    TOTAL_FUNDO = 0;
    TOTAL_DESPESA = 0;

    TOTAL_BRUTO = 0;
    QTDE = 0;

    FOR SELECT CAST(C.DATA_PAGAMENTO AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          C.DATA_PAGAMENTO, COALESCE(PE.TIPO_ORIGEM_SITE,''), C.CAIXA_SERVICO_ID,
          COALESCE(C.valor_pago,0),
          EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
          EXTRACT(YEAR FROM C.DATA_PAGAMENTO)
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA,
          C_CAIXA_ITEM C
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND C.CHAVE_SERVICO = PR.PROTOCOLO_ID
        AND PR.TIPO_PROTOCOLO = '1'
        AND TA.TIPO = 'R' --REGISTRADOS
        AND A.ANDAMENTO_ID = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.pedido_id = A.pedido_id
                              AND TA2.TIPO = 'R') --PEGAR SOMENTE 1º ANDAMENTO DE REGISTRADO
        AND PR.PROTOCOLO_ID = :VP_PROTOCOLO_ID
        AND C.DATA_PAGAMENTO >= CAST(A.data AS DATE)
        AND C.tipo_transacao = 'D' --DEBITO
        ORDER BY 1,2
        INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,   :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA,
          :DATA_HORA, :V_TIPO_ORIGEM_SITE, :V_CAIXA_SERVICO_ID, :V_VALOR_DEVOLUCAO, :MES, :ANO DO
    BEGIN
      V_QTDE_CONSOLIDACAO = 0;
      SISTEMA_ID = 1;

      if (:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) then
      begin
        TIPO_RETORNO = 4; --4=LANCAMENTO COMO SAIDA À VARA DE REGISTROS PUBLICOS
      end
      else
      begin
        TIPO_RETORNO = 3; --3=LANCAMENTO COMO SAIDA COMO DEVOLUCAO AO USUARIO
      end
  
      IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
      BEGIN
        V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
      END
      ELSE IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
      BEGIN
        V_RETORNAR = 'N';
      END
      ELSE
      BEGIN
        SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
        WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
        AND I.PEDIDO_ID = :ID
        AND COALESCE(N.CONSOLIDACAO,'') = 'S'
        INTO :V_QTDE_CONSOLIDACAO;
  
        if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
        begin
          V_RETORNAR = 'N';
        end
        else
        begin
          V_RETORNAR = 'S';
        end
      END

      if (:V_RETORNAR = 'S') THEN
      BEGIN
        SELECT QUANTIDADE_REGISTRO, QUANTIDADE_AVERBACAO, TOTAL_GERAL
        FROM R_TOTAL_PEDIDO_DF(:ID)
        into :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO, :V_TOTAL_GERAL;
  
        V_TOTAL_GERAL_75 = coalesce((coalesce(V_TOTAL_GERAL,0) * 0.75),0);
  
        IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
        BEGIN
          NATUREZA = 'Registro/Averbação';
        END
        ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
        BEGIN
          NATUREZA = 'Averbação';
        END
        ELSE
        BEGIN
          NATUREZA = 'Registro';
        END    
    
        V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
    
        if (COALESCE(:V_VALOR_DEVOLUCAO,0) < 0) then
        BEGIN
          V_VALOR_DEVOLUCAO = :V_VALOR_DEVOLUCAO * -1;
        END
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
    
        TOTAL_DESPESA = :V_VALOR_DEVOLUCAO;

        if (:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) then
        begin
          DESCRICAO = :V_DESCRICAO || ' (Devolução à vara de registros públicos)';
        end
        else
        begin
          DESCRICAO = :V_DESCRICAO || ' (Devolução ao usuário)';
        end

        QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
        TOTAL_BRUTO = 0;
  
        ORDEM = :ORDEM + 1;

        SUSPEND;
      END
    END
  end
  else
  begin
    if (:V_NUMERO_CARTORIO = '4') then
    begin




       --ROTINA PARA O 4DF
      V_DATA_A_PESQUISAR = cast(:V_DATA_INI as date);
      WHILE (:V_DATA_A_PESQUISAR <= cast(:V_DATA_FIM as date)) DO
      BEGIN
        --SELECIONAR PROTOCOLOS CANCELADOS DO RI 75% como devolução ao usuário
        --Lançamento como saída da conversão de 75% dado como depósito prévio como devolução ao usuario
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        TOTAL_DESPESA = 0;
    
        TOTAL_BRUTO = 0;
        QTDE = 0;
    
        FOR SELECT CAST(a.data AS DATE),
              PR.NUMERO_ORDEM,
              PR.PEDIDO_ID,
              PR.TIPO_PROTOCOLO,
              T.DESCRICAO,
              PE.TIPO_COBRANCA,
              A.data, COALESCE(PE.TIPO_ORIGEM_SITE,''), a.tb_tipo_andamento_id,
              0,
              EXTRACT(MONTH FROM a.data),
              EXTRACT(YEAR FROM a.data)
            FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
            WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
            AND PE.TB_TITULO_ID = T.TB_TITULO_ID
            AND PE.PEDIDO_ID = A.PEDIDO_ID
            AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
            and a.tb_tipo_andamento_id in (7,49,57)
            AND PR.TIPO_PROTOCOLO = '1'
            AND TA.TIPO = 'C' --cancelados
            AND A.ANDAMENTO_ID = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                                  WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                                  AND A2.pedido_id = A.pedido_id
                                  AND TA2.TIPO = 'C') --PEGAR SOMENTE 1º ANDAMENTO DE cancelado
            AND cast(a.data as date) = :V_DATA_A_PESQUISAR
            AND cast(a.data as date) >= CAST(A.data AS DATE)
            ORDER BY 1,2
            INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,   :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA,
              :DATA_HORA, :V_TIPO_ORIGEM_SITE, :V_CAIXA_SERVICO_ID, :V_VALOR_DEVOLUCAO, :MES, :ANO DO
        BEGIN
          V_QTDE_CONSOLIDACAO = 0;
          SISTEMA_ID = 1;
    
          if (:V_CAIXA_SERVICO_ID = 57) then
          begin
            TIPO_RETORNO = 4; --4=LANCAMENTO COMO SAIDA À VARA DE REGISTROS PUBLICOS
          end
          else
          begin
            TIPO_RETORNO = 3; --3=LANCAMENTO COMO SAIDA COMO DEVOLUCAO AO USUARIO
          end
      
          IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
          BEGIN
            V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
          END
          ELSE IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
          BEGIN
            V_RETORNAR = 'N';
          END
          ELSE
          BEGIN
            SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
            WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
            AND I.PEDIDO_ID = :ID
            AND COALESCE(N.CONSOLIDACAO,'') = 'S'
            INTO :V_QTDE_CONSOLIDACAO;
      
            if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
            begin
              V_RETORNAR = 'N';
            end
            else
            begin
              V_RETORNAR = 'S';
            end
          END
    
          if (:V_RETORNAR = 'S') THEN
          BEGIN
            SELECT QUANTIDADE_REGISTRO, QUANTIDADE_AVERBACAO, TOTAL_GERAL
            FROM R_TOTAL_PEDIDO_DF(:ID)
            into :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO, :V_TOTAL_GERAL;


      
            if (:V_CAIXA_SERVICO_ID = 49) then --100%
            begin
              V_TOTAL_GERAL_75 = coalesce(:V_TOTAL_GERAL,0);
            end
            else
            begin
              --75%
              V_TOTAL_GERAL_75 = CAST(coalesce((coalesce(:V_TOTAL_GERAL,0) * 0.75),0) AS NUMERIC(18,2));
            end
      
            IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
            BEGIN
              NATUREZA = 'Registro/Averbação';
            END
            ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
            BEGIN
              NATUREZA = 'Averbação';
            END
            ELSE
            BEGIN
              NATUREZA = 'Registro';
            END    
        
            if (:V_CAIXA_SERVICO_ID = 49) then --100%
            begin
              V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [100%] - '||:V_NATUREZA_FORMAL;
            end
            else
            begin
              V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
            end
        
            TOTAL_EMOLUMENTO = 0;
            TOTAL_TAXA_JUDICIARIA = 0;
            TOTAL_FUNDO = 0;
        
            TOTAL_DESPESA = :V_TOTAL_GERAL_75;
    
            if (:V_CAIXA_SERVICO_ID = 57 ) then
            begin
              DESCRICAO = :V_DESCRICAO || ' (Devolução à vara de registros públicos)';
            end
            else
            begin
              DESCRICAO = :V_DESCRICAO || ' (Devolução ao usuário)';
            end
    
            QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
            TOTAL_BRUTO = 0;
      
            ORDEM = :ORDEM + 1;
    
            SUSPEND;
          END
        END
    
        V_DATA_A_PESQUISAR = :V_DATA_A_PESQUISAR + 1;
      end







    end
    else
    begin
      V_DATA_A_PESQUISAR = cast(:V_DATA_INI as date);
      WHILE (:V_DATA_A_PESQUISAR <= cast(:V_DATA_FIM as date)) DO
      BEGIN
        --SELECIONAR PROTOCOLOS CANCELADOS DO RI 75% como devolução ao usuário
        --Lançamento como saída da conversão de 75% dado como depósito prévio como devolução ao usuario
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        TOTAL_DESPESA = 0;
    
        TOTAL_BRUTO = 0;
        QTDE = 0;
    
        FOR SELECT CAST(C.DATA_PAGAMENTO AS DATE),
              PR.NUMERO_ORDEM,
              PR.PEDIDO_ID,
              PR.TIPO_PROTOCOLO,
              T.DESCRICAO,
              PE.TIPO_COBRANCA,
              C.DATA_PAGAMENTO, COALESCE(PE.TIPO_ORIGEM_SITE,''), C.CAIXA_SERVICO_ID,
              COALESCE(C.valor_pago,0),
              EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
              EXTRACT(YEAR FROM C.DATA_PAGAMENTO)
            FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA,
              C_CAIXA_ITEM C
            WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
            AND PE.TB_TITULO_ID = T.TB_TITULO_ID
            AND PE.PEDIDO_ID = A.PEDIDO_ID
            AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
            AND C.CHAVE_SERVICO = PR.PROTOCOLO_ID
            AND PR.TIPO_PROTOCOLO = '1'
            AND TA.TIPO = 'R' --REGISTRADOS
            AND A.ANDAMENTO_ID = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                                  WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                                  AND A2.pedido_id = A.pedido_id
                                  AND TA2.TIPO = 'R') --PEGAR SOMENTE 1º ANDAMENTO DE REGISTRADO
            AND C.DATA_PAGAMENTO = :V_DATA_A_PESQUISAR
            AND C.DATA_PAGAMENTO >= CAST(A.data AS DATE)
            AND C.tipo_transacao = 'D' --DEBITO
            ORDER BY 1,2
            INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,   :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA,
              :DATA_HORA, :V_TIPO_ORIGEM_SITE, :V_CAIXA_SERVICO_ID, :V_VALOR_DEVOLUCAO, :MES, :ANO DO
        BEGIN
          V_QTDE_CONSOLIDACAO = 0;
          SISTEMA_ID = 1;
    
          if (:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) then
          begin
            TIPO_RETORNO = 4; --4=LANCAMENTO COMO SAIDA À VARA DE REGISTROS PUBLICOS
          end
          else
          begin
            TIPO_RETORNO = 3; --3=LANCAMENTO COMO SAIDA COMO DEVOLUCAO AO USUARIO
          end
      
          IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
          BEGIN
            V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
          END
          ELSE IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
          BEGIN
            V_RETORNAR = 'N';
          END
          ELSE
          BEGIN
            SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
            WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
            AND I.PEDIDO_ID = :ID
            AND COALESCE(N.CONSOLIDACAO,'') = 'S'
            INTO :V_QTDE_CONSOLIDACAO;
      
            if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
            begin
              V_RETORNAR = 'N';
            end
            else
            begin
              V_RETORNAR = 'S';
            end
          END
    
          if (:V_RETORNAR = 'S') THEN
          BEGIN
            SELECT QUANTIDADE_REGISTRO, QUANTIDADE_AVERBACAO, TOTAL_GERAL
            FROM R_TOTAL_PEDIDO_DF(:ID)
            into :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO, :V_TOTAL_GERAL;
      
            V_TOTAL_GERAL_75 = coalesce((coalesce(V_TOTAL_GERAL,0) * 0.75),0);
      
            IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
            BEGIN
              NATUREZA = 'Registro/Averbação';
            END
            ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
            BEGIN
              NATUREZA = 'Averbação';
            END
            ELSE
            BEGIN
              NATUREZA = 'Registro';
            END    
        
            V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
        
            if (COALESCE(:V_VALOR_DEVOLUCAO,0) < 0) then
            BEGIN
              V_VALOR_DEVOLUCAO = :V_VALOR_DEVOLUCAO * -1;
            END
            TOTAL_EMOLUMENTO = 0;
            TOTAL_TAXA_JUDICIARIA = 0;
            TOTAL_FUNDO = 0;
        
            TOTAL_DESPESA = :V_VALOR_DEVOLUCAO;
    
            if (:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) then
            begin
              DESCRICAO = :V_DESCRICAO || ' (Devolução à vara de registros públicos)';
            end
            else
            begin
              DESCRICAO = :V_DESCRICAO || ' (Devolução ao usuário)';
            end
    
            QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
            TOTAL_BRUTO = 0;
      
            ORDEM = :ORDEM + 1;
    
            SUSPEND;
          END
        END
    
        V_DATA_A_PESQUISAR = :V_DATA_A_PESQUISAR + 1;
      end
    end
  end
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_SAIDA_100 (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
PROTOCOLO_ANTERIOR INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(1);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(1);
declare variable V_RETORNAR varchar(1);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_DEPOSITO_INICIAL numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_CONSOLIDACAO varchar(1);
declare variable V_DATA_PROT_TEMP date;
declare variable V_VALOR_COMPENSADO numeric(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_TOTAL_GERAL numeric(18,2);
declare variable V_TOTAL_GERAL_75 numeric(18,2);
declare variable V_DATA_REGISTRO date;
declare variable V_VALOR_DEVOLVIDO numeric(18,2);
declare variable V_TOTAL_PROTOCOLO_TEMP numeric(18,2);
declare variable V_PEDIDO_ANTERIOR integer;
declare variable V_TOTAL_PEDIDO numeric(18,2);
declare variable V_TOTAL_PEDIDO_ANTERIOR numeric(18,2);
declare variable V_TOTAL_PEDIDO_ANTERIOR_75 numeric(18,2);
declare variable V_COMPENSADO_100 varchar(5);
declare variable V_REG_AV varchar(3);
declare variable V_SQL varchar(3000);
declare variable V_PEDIDO_ANTERIOR_ID integer;
declare variable V_PERIODO_PADRAO_ANTERIOR integer;
declare variable V_PERIODO_PADRAO integer;
declare variable V_VALOR_BRUTO numeric(18,2);
declare variable V_PERCENTUAL numeric(18,2);
declare variable V_DATA_PROTOCOLO DATE;
declare variable V_TOTAL_DESCONTAR numeric(18,2);
declare variable V_CARTORIO varchar(5);
declare variable V_TOTAL_ISS numeric(18,2);
BEGIN
  --BUSCAR VALORES DE PARAMETROS
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'CARTORIO'
  AND C.NOME = 'CARTORIO_NUMERO'
  INTO :V_CARTORIO;

  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  ORDEM = 0;
  PROTOCOLO_ANTERIOR = 0;

  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  TOTAL_DESPESA = 0;
  TOTAL_BRUTO = 0;
  QTDE = 0;
  NUMERO_ONLINE = '';

  V_VALOR_BRUTO = 0;

  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT CAST(A.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          A.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM A.DATA),
          EXTRACT(YEAR FROM A.DATA),
          coalesce(PI.QUANTIDADE,0),
          coalesce(PI.valor_emolumento,0),
          coalesce(PI.valor_fundo_ri,0),
          e.REG_AVERB,
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          COALESCE(PE.VALOR_COMPENSADO,0),
          CAST(PR.DATA AS DATE),
          coalesce(PI.VALOR_ISS,0)
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, G_EMOLUMENTO E
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND PE.PEDIDO_ID = PI.PEDIDO_ID
        AND PI.emolumento_id = E.emolumento_id
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND (TA.TIPO = '||''''||'R'||''''||') --Registrados
        AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
        AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.PEDIDO_ID = PE.PEDIDO_ID
                              AND TA2.TIPO = '||''''||'R'||''''||'
                              ORDER BY A2.ANDAMENTO_ID)
        ORDER BY 1,2 ';
  end
  else
  begin
    V_SQL = ' SELECT CAST(A.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          A.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM A.DATA),
          EXTRACT(YEAR FROM A.DATA),
          coalesce(PI.QUANTIDADE,0),
          coalesce(PI.valor_emolumento,0),
          coalesce(PI.valor_fundo_ri,0),
          e.REG_AVERB,
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          COALESCE(PE.VALOR_COMPENSADO,0),
          CAST(PR.DATA AS DATE),
          coalesce(PI.VALOR_ISS,0)
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, G_EMOLUMENTO E
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND PE.PEDIDO_ID = PI.PEDIDO_ID
        AND PI.emolumento_id = E.emolumento_id
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND (TA.TIPO = '||''''||'R'||''''||') --Registrados
        AND A.DATA BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
        AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.PEDIDO_ID = PE.PEDIDO_ID
                              AND TA2.TIPO = '||''''||'R'||''''||'
                              ORDER BY A2.ANDAMENTO_ID)
        ORDER BY 1,2 ';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
          :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA,
          :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO,
          :qtde, :total_emolumento, :total_fundo, :v_reg_av,
          :NUMERO_ONLINE, :V_VALOR_COMPENSADO, :V_DATA_PROTOCOLO, :V_TOTAL_ISS DO
  BEGIN
    V_DESCRICAO = '';
    V_QTDE_CONSOLIDACAO = 0;
    SISTEMA_ID = 1;
    TIPO_RETORNO = 3; --3=LANCAMENTO COMO SAIDA DA CONVERSAO DO DEPOSITO PREVIO EM RECEITA (100%)
    NATUREZA = 'Conversão em receita (100%)';
    V_DATA_REGISTRO = :DATA;
    qtde_av = 0;
    qtde_reg = 0;

    if (coalesce(:v_reg_av,'') = 'A') then
    begin
      qtde_av = :qtde;
    end
    else
    begin
      qtde_reg = :qtde;
    end

    IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
    BEGIN
      V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
    END
    ELSE
    BEGIN
      SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
      WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
      AND I.PEDIDO_ID = :ID
      AND COALESCE(N.CONSOLIDACAO,'') = 'S'
      INTO :V_QTDE_CONSOLIDACAO;

      if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
      begin
        V_RETORNAR = 'N';
      end
      else
      begin
        V_RETORNAR = 'S';
      end
    END

    if (:V_RETORNAR = 'S') THEN
    BEGIN
      V_DESCRICAO = :V_NATUREZA_FORMAL;
      IF (:qtde_reg > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_reg||' REGISTRO(S)';
      END
      IF (:qtde_av > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_av||' AVERBAÇÃO(S)';
      END

      V_TOTAL_DESCONTAR = 0;
      if (coalesce(:V_VALOR_COMPENSADO,0) > 0) then
      begin
        --ver data e total do protocolo anterior
        select pr.data, coalesce(pe.pedido_id,0) from r_pedido pe, r_protocolo pr
        where pe.pedido_id = pr.pedido_id
        and pr.tipo_protocolo = '1'
        and pe.novo_pedido_id = :ID
        into :V_DATA_PROT_TEMP, :V_PEDIDO_ANTERIOR_ID;

        select first 1 emolumento_periodo_id from g_emolumento_periodo ep
        where :V_DATA_PROT_TEMP >= ep.data_inicial
        order by ep.data_inicial
        into :V_PERIODO_PADRAO_ANTERIOR;

        SELECT (COALESCE(TOTAL_EMOLUMENTO,0) + COALESCE(TOTAL_FUNDO_RI,0))
        FROM R_TOTAL_PEDIDO_DF(:V_PEDIDO_ANTERIOR_ID, :V_PERIODO_PADRAO_ANTERIOR)
        INTO :V_TOTAL_PEDIDO_ANTERIOR;
        V_TOTAL_PEDIDO_ANTERIOR_75 = CAST((:V_TOTAL_PEDIDO_ANTERIOR * 0.75) AS NUMERIC(18,2));

        select first 1 emolumento_periodo_id from g_emolumento_periodo ep
        where :V_DATA_PROTOCOLO >= ep.data_inicial
        order by ep.data_inicial
        into :V_PERIODO_PADRAO;

        SELECT (COALESCE(TOTAL_EMOLUMENTO,0) + COALESCE(TOTAL_FUNDO_RI,0))
        FROM R_TOTAL_PEDIDO_DF(:ID, :V_PERIODO_PADRAO)
        INTO :V_TOTAL_PEDIDO;

        V_VALOR_BRUTO = coalesce(:TOTAL_EMOLUMENTO,0) + coalesce(:TOTAL_FUNDO,0) + coalesce(:V_TOTAL_ISS,0);

        /*if (COALESCE(:V_VALOR_COMPENSADO,0) > COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0)) then
        begin
          if ((COALESCE(:V_VALOR_COMPENSADO,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0)) > (COALESCE(:V_TOTAL_PEDIDO_ANTERIOR,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0))) then
          begin
            V_TOTAL_DESCONTAR = COALESCE(:V_TOTAL_PEDIDO_ANTERIOR,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0);
          end
          else
          begin
            V_TOTAL_DESCONTAR = COALESCE(:V_VALOR_COMPENSADO,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0);
          end

          V_PERCENTUAL = cast((COALESCE(:V_TOTAL_DESCONTAR,0) / COALESCE(:V_TOTAL_PEDIDO,0)) as numeric(18,2));

          V_VALOR_BRUTO = :V_VALOR_BRUTO * (1-COALESCE(:V_PERCENTUAL,0));

          TOTAL_EMOLUMENTO = cast((:V_VALOR_BRUTO * 0.9346) as numeric(18,2));
          TOTAL_FUNDO = coalesce(:V_VALOR_BRUTO,0) - coalesce(:TOTAL_EMOLUMENTO,0);
        end*/
      end
      else
      begin
        V_VALOR_BRUTO = COALESCE(:total_emolumento,0) + COALESCE(:total_fundo,0)+ coalesce(:V_TOTAL_ISS,0);
      end

      if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
      BEGIN
        V_VALOR_BRUTO = 0;
      END

      DESCRICAO = :V_DESCRICAO;

      if (:V_CARTORIO = '9') then
      begin
        select pr.data from r_pedido pe, r_protocolo pr
        where pe.pedido_id = pr.pedido_id
        and pr.tipo_protocolo = '1'
        and pe.pedido_id = :ID
        into :V_DATA_PROT_TEMP;
        if (:v_data_prot_temp < cast('01.04.2021' as date)) then
        begin
          V_VALOR_BRUTO = cast((:V_VALOR_BRUTO * 0.75) as numeric(15,2));
        end
      end

      TOTAL_DESPESA = :V_VALOR_BRUTO;

      ORDEM = :ORDEM + 1;

      if (coalesce(:TOTAL_DESPESA,0) > 0) then
      begin
        TOTAL_ISS = round((TOTAL_DESPESA * 5),2);
        TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);
        TOTAL_GERAL_COM_ISS = :TOTAL_DESPESA;
        TOTAL_DESPESA = :TOTAL_DESPESA - :TOTAL_ISS;

        SUSPEND;
      end
    END
  END
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_SAIDA_25 (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
PROTOCOLO_ANTERIOR INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
declare variable V_VALOR_BRUTO numeric(18,2);
declare variable V_VALOR_BRUTO_75 numeric(18,2);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(200);
declare variable V_QTDE2 numeric(18,4);
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(1);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_DATA_NOVO_PROTOCOLO timestamp;
declare variable V_TIPO_ORIGEM_SITE varchar(1);
declare variable V_RETORNAR varchar(1);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE integer;
declare variable V_DEPOSITO_INICIAL numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable V_CONSOLIDACAO varchar(1);
declare variable V_DATA_PROT_TEMP date;
declare variable V_DATA_PROT_ANTERIOR date;
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_NATUREZA_FORMAL varchar(260);
declare variable V_NOVO_PROTOCOLO integer;
declare variable V_DATA_A_PESQUISAR date;
declare variable V_TOTAL_GERAL numeric(18,2);
declare variable V_TOTAL_GERAL_75 numeric(18,2);
declare variable V_VALOR_DEVOLVIDO numeric(18,2);

declare variable V_TOTAL_PROTOCOLO_TEMP numeric(18,2);

declare variable V_PEDIDO_ANTERIOR integer;
declare variable V_TOTAL_PEDIDO_ANTERIOR NUMERIC(18,2);
declare variable V_TOTAL_PEDIDO_ANTERIOR_75 NUMERIC(18,2);
declare variable V_TOTAL_PEDIDO NUMERIC(18,2);
declare variable V_SQL varchar(3000);
declare variable V_STATUS_SELO_DIGITAL VARCHAR(3);
declare variable V_VALOR_COMPENSADO_ENTRADA NUMERIC(18,2);
DECLARE VARIABLE V_PERIODO_PADRAO VARCHAR(10);
declare variable V_PERIODO_PADRAO_ANTERIOR VARCHAR(10);
declare variable V_TOTAL_DESCONTAR numeric(18,2);
declare variable V_PEDIDO_ANTERIOR_ID integer;
declare variable V_TOTAL_ISS numeric(18,2);
declare variable V_TOTAL_DESPESA_SEM_ISS numeric(18,2);
declare variable V_CREDITO numeric(18,2);
declare variable V_DEBITO numeric(18,2);
declare variable V_PROTOCOLO_ID integer;
BEGIN
  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  ORDEM = 0;
  PROTOCOLO_ANTERIOR = 0;

  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  TOTAL_DESPESA = 0;
  TOTAL_BRUTO = 0;
  QTDE = 0;
  NUMERO_ONLINE = '';

  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;

  V_TOTAL_ISS = 0;
  V_TOTAL_DESPESA_SEM_ISS = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT CAST(A.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          A.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM A.DATA),
          EXTRACT(YEAR FROM A.DATA),
          TA.STATUS_SELO_DIGITAL,
          COALESCE(PE.NOVO_PEDIDO_ID,0),
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          cast(pr.data as date),
          COALESCE(PE.VALOR_COMPENSADO,0),
          PR.PROTOCOLO_ID
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND (TA.TIPO = '||''''||'C'||''''||') --Cancelados
        AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
        AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.PEDIDO_ID = PE.PEDIDO_ID
                              AND TA2.TIPO = '||''''||'C'||''''||'
                              ORDER BY A2.ANDAMENTO_ID)
        ORDER BY 1,2 ';
  end
  else
  begin
    V_SQL = ' SELECT CAST(A.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          T.DESCRICAO,
          PE.TIPO_COBRANCA,
          A.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM A.DATA),
          EXTRACT(YEAR FROM A.DATA),
          TA.STATUS_SELO_DIGITAL,
          COALESCE(PE.NOVO_PEDIDO_ID,0),
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          cast(pr.data as date),
          COALESCE(PE.VALOR_COMPENSADO,0),
          PR.PROTOCOLO_ID
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND (TA.TIPO = '||''''||'C'||''''||') --Cancelados
        AND A.DATA BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
        AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                              AND A2.PEDIDO_ID = PE.PEDIDO_ID
                              AND TA2.TIPO = '||''''||'C'||''''||'
                              ORDER BY A2.ANDAMENTO_ID)
        ORDER BY 1,2 ';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
          :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA,
          :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO,
          :V_STATUS_SELO_DIGITAL,
          :V_NOVO_PEDIDO_ID, :NUMERO_ONLINE, :V_DATA_PROT_TEMP,
          :V_VALOR_COMPENSADO_ENTRADA, :V_PROTOCOLO_ID  DO
  BEGIN
    V_DESCRICAO = '';
    V_QTDE_CONSOLIDACAO = 0;
    SISTEMA_ID = 1;
    qtde_av = 0;
    qtde_reg = 0;
    TOTAL_DESPESA = 0;
    V_TOTAL_DESPESA_SEM_ISS = 0;

    if ((COALESCE(:V_STATUS_SELO_DIGITAL,'') = '88')) then --SE HOUVE DEVOLUÇÃO DE 100%
    begin
      V_RETORNAR = 'N'; --NAO RETORNAR, POIS HOUVE DEVOLUÇÃO DE 100%
    end
    else if (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
    BEGIN
      V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
    END
    ELSE
    BEGIN
      SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
      WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
      AND I.PEDIDO_ID = :ID
      AND COALESCE(N.CONSOLIDACAO,'') = 'S'
      INTO :V_QTDE_CONSOLIDACAO;

      if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
      begin
        V_RETORNAR = 'N';
      end
      else
      begin
        V_RETORNAR = 'S';
      end
    END

    if (:V_RETORNAR = 'S') THEN
    BEGIN
      select first 1 emolumento_periodo_id from g_emolumento_periodo ep
      where :V_DATA_PROT_TEMP >= ep.data_inicial
      order by ep.data_inicial
      into :v_periodo_padrao;

      SELECT COALESCE(TOTAL_EMOLUMENTO,0),
        COALESCE(TOTAL_FUNDO_RI,0),
        COALESCE(QUANTIDADE_REGISTRO,0),
        COALESCE(QUANTIDADE_AVERBACAO,0),
        COALESCE(TOTAL_ISS,0)
      FROM R_TOTAL_PEDIDO_DF(:ID, :V_PERIODO_PADRAO)
      INTO :total_emolumento, :total_fundo, :qtde_reg, :qtde_av, :V_TOTAL_ISS;

      qtde = coalesce(:qtde_reg,0) + coalesce(:qtde_av,0);

      V_TOTAL_PEDIDO = COALESCE(:total_emolumento,0) + COALESCE(:total_fundo,0);

      --Calculando os Créditos
      SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
      WHERE TIPO_SERVICO = '1'
      AND CHAVE_SERVICO = :V_PROTOCOLO_ID
      AND TIPO_TRANSACAO = 'C'
      INTO :V_CREDITO;

      --Calculando os Debitos
      SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
      WHERE TIPO_SERVICO = '1'
      AND CHAVE_SERVICO = :V_PROTOCOLO_ID
      AND TIPO_TRANSACAO = 'D'
      INTO :V_DEBITO;

      V_CREDITO = COALESCE(:V_CREDITO,0) - COALESCE(:V_DEBITO,0);
      if (COALESCE(:V_CREDITO,0) < 0) then
      BEGIN
        V_CREDITO = 0;
      END

      V_DESCRICAO = :V_NATUREZA_FORMAL;
      IF (:qtde_reg > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_reg||' REGISTRO(S)';
      END

      IF (:qtde_av > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_av||' AVERBAÇÃO(S)';
      END

      V_VALOR_BRUTO = COALESCE(:total_emolumento,0) + COALESCE(:total_fundo,0);
      if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
      BEGIN
        V_VALOR_BRUTO = 0;
        V_VALOR_BRUTO_75 = 0;
      END
      ELSE
      BEGIN
        V_TOTAL_DESPESA_SEM_ISS = CAST((COALESCE(:V_VALOR_BRUTO,0) * 0.25) AS NUMERIC(18,2));
        V_VALOR_BRUTO = :V_VALOR_BRUTO + COALESCE(:v_total_iss,0);
        V_VALOR_BRUTO_75 = CAST((:v_valor_bruto * 0.75) AS NUMERIC(18,2));
        TOTAL_DESPESA = CAST((COALESCE(:V_VALOR_BRUTO,0) * 0.25) AS NUMERIC(18,2));

        if (:V_CREDITO < :TOTAL_DESPESA) then
        BEGIN
          TOTAL_DESPESA = :V_CREDITO;
          V_TOTAL_DESPESA_SEM_ISS = CAST(COALESCE((:TOTAL_DESPESA/1.05),0) AS NUMERIC(18,2));
          if (TOTAL_DESPESA < 0) THEN
          begin
            TOTAL_DESPESA = 0;
            V_TOTAL_DESPESA_SEM_ISS = 0;
          end
        END
      END

      DESCRICAO = :V_DESCRICAO;
      if (coalesce(:V_VALOR_COMPENSADO_ENTRADA,0) > 0) then
      begin
        --ver data e total do protocolo anterior
        select pr.data, coalesce(pe.pedido_id,0) from r_pedido pe, r_protocolo pr
        where pe.pedido_id = pr.pedido_id
        and pr.tipo_protocolo = '1'
        and pe.novo_pedido_id = :ID
        into :V_DATA_PROT_ANTERIOR, :V_PEDIDO_ANTERIOR_ID;

        select first 1 emolumento_periodo_id from g_emolumento_periodo ep
        where :V_DATA_PROT_ANTERIOR >= ep.data_inicial
        order by ep.data_inicial
        into :V_PERIODO_PADRAO_ANTERIOR;

        SELECT (COALESCE(TOTAL_EMOLUMENTO,0) + COALESCE(TOTAL_FUNDO_RI,0))
        FROM R_TOTAL_PEDIDO_DF(:V_PEDIDO_ANTERIOR_ID, :V_PERIODO_PADRAO_ANTERIOR)
        INTO :V_TOTAL_PEDIDO_ANTERIOR;
        V_TOTAL_PEDIDO_ANTERIOR_75 = CAST((:V_TOTAL_PEDIDO_ANTERIOR * 0.75) AS NUMERIC(18,2));

        if (COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) > COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0)) then
        begin
          if ((COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0)) > (COALESCE(:V_TOTAL_PEDIDO_ANTERIOR,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0))) then
          begin
            V_TOTAL_DESCONTAR = COALESCE(:V_TOTAL_PEDIDO_ANTERIOR,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0);
          end
          else
          begin
            V_TOTAL_DESCONTAR = COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0);
          end
          TOTAL_DESPESA = :TOTAL_DESPESA - COALESCE(:V_TOTAL_DESCONTAR,0);
          V_TOTAL_DESPESA_SEM_ISS = :V_TOTAL_DESPESA_SEM_ISS - COALESCE(:V_TOTAL_DESCONTAR,0);
        end
      end
      if (:TOTAL_DESPESA < 0) then
      begin
        TOTAL_DESPESA = 0;
        V_TOTAL_DESPESA_SEM_ISS = 0;
      end

      TOTAL_EMOLUMENTO = cast((:V_TOTAL_DESPESA_SEM_ISS * 0.9346) as numeric(18,2));
      TOTAL_FUNDO = coalesce(:V_TOTAL_DESPESA_SEM_ISS,0) - coalesce(:TOTAL_EMOLUMENTO,0);

      TIPO_RETORNO = 4; --4=LANCAMENTO COMO SAIDA DA CONVERSAO DO DEPOSITO PREVIO EM RECEITA (25%)
      NATUREZA = 'Conversão em receita (25%)';
      ORDEM = :ORDEM + 1;
      if (coalesce(:TOTAL_DESPESA,0) > 0) then
      begin
        TOTAL_ISS = round((TOTAL_DESPESA * 5),2);
        TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);
        TOTAL_GERAL_COM_ISS = :TOTAL_DESPESA;
        TOTAL_DESPESA = :TOTAL_DESPESA - :TOTAL_ISS;

        SUSPEND;
      end
    END
  END
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_DF_V2 (V_DATA_INI DATE,
V_DATA_FIM DATE)
RETURNS (SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_ISS NUMERIC(18, 2),
TOTAL_TERCEIRO NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER)
AS 
DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(18,2);
DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(18,2);
DECLARE VARIABLE V_VALOR_FUNDO NUMERIC(18,2);
DECLARE VARIABLE V_VALOR_BRUTO NUMERIC(18,2);
DECLARE VARIABLE V_TIPO_COBRANCA VARCHAR(1);
DECLARE VARIABLE V_DESCRICAO VARCHAR(200);
DECLARE VARIABLE V_ATO_TIPO_ID INTEGER;
DECLARE VARIABLE V_DESCRICAO2 VARCHAR(200);
DECLARE VARIABLE V_QTDE2 NUMERIC(18,4);
DECLARE VARIABLE V_QTDE_REGISTRO INTEGER;
DECLARE VARIABLE V_QTDE_AVERBACAO INTEGER;
DECLARE VARIABLE V_ORIGEM_PEDIDO VARCHAR(1);
DECLARE VARIABLE V_TIPO_DESPESA VARCHAR(1);
DECLARE VARIABLE V_REPASSE VARCHAR(1);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_75 VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_100 VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_APRESENTANTE VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_TJDFT VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DIFERENCA_CUSTA_ENTRADA VARCHAR(10);
DECLARE VARIABLE V_NOVO_PEDIDO_ID INTEGER;
DECLARE VARIABLE V_DATA_NOVO_PROTOCOLO TIMESTAMP;
DECLARE VARIABLE V_TIPO_ORIGEM_SITE VARCHAR(1);
declare variable V_RETORNAR VARCHAR(1);
declare variable V_PROTOCOLO_INICIAL INTEGER;
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_QTDE INTEGER;
declare variable V_PROTOCOLO_ID INTEGER;
DECLARE VARIABLE V_DEPOSITO_INICIAL NUMERIC(18,2);
declare variable V_CREDITO_INICIAL NUMERIC(18,2);
declare variable V_TOTAL_PROTOCOLO NUMERIC(18,2);
declare variable V_QTDE_CONSOLIDACAO INTEGER;
declare variable V_VERSAO VARCHAR(3);

declare variable V_MODELO_DIARIO_AUXILIAR VARCHAR(3);
declare variable V_CONSOLIDACAO VARCHAR(1);
declare variable V_VALOR_TEMP NUMERIC(18,2);
declare variable V_DATA_PROT_TEMP DATE;
declare variable V_VALOR_COMPENSADO NUMERIC(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO NUMERIC(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO NUMERIC(18,2);

declare variable V_NATUREZA_FORMAL VARCHAR(260);

declare variable V_NOVO_PROTOCOLO INTEGER;

declare variable V_DATA_TEMP DATE;
BEGIN
  --iniciar campos nao usados
  TOTAL_DESCONTO = 0;
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;

  --BUSCAR VALORES DE PARAMETROS
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_75'
  INTO :V_SERVICO_DEVOLUCAO_75;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_100'
  INTO :V_SERVICO_DEVOLUCAO_100;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_APRESENTANTE'
  INTO :V_SERVICO_DEVOLUCAO_APRESENTANTE;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_TJDFT'
  INTO :V_SERVICO_DEVOLUCAO_TJDFT;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DIFERENCA_CUSTA_ENTRADA'
  INTO :V_SERVICO_DIFERENCA_CUSTA_ENTRADA;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '5'
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'LIVRO_DIARIO_AUXILIAR'
  AND C.NOME = 'VERSAO_DEPOSITO_PREVIO_DF'
  INTO :V_VERSAO;

  V_PROTOCOLO_INICIAL = 1;

  --PEGAR MODELO DO DIÁRIO AUXILIAR - O PADRAO ATUAL É "1"
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('CAIXA','DADP','MODELO_DIARIO_AUXILIAR',1)
  INTO :V_MODELO_DIARIO_AUXILIAR;

  V_DATA_TEMP = :V_DATA_INI;

  WHILE (:V_DATA_TEMP <= :V_DATA_FIM) DO
  BEGIN

      if (COALESCE(:V_VERSAO,'') = '2') then
      begin
        --vesao 2
    
        --INICIO REGISTRO DE IMOVEIS
        --REGISTRO DE IMOVEIS - SELECIONAR PROTOCOLADOS - ESCRITURACAO DE 75% - deposito
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        TOTAL_DESPESA = 0;
    
        TOTAL_ISS = 0;
        TOTAL_TERCEIRO = 0;
        TOTAL_BRUTO = 0;
        QTDE = 0;
    
        FOR SELECT CAST(PR.DATA AS DATE),
              PR.NUMERO_ORDEM,
              PR.PEDIDO_ID,
              PR.TIPO_PROTOCOLO,
              PE.TIPO_COBRANCA,
              (SELECT (((TOTAL_EMOLUMENTO + total_fundo_ri + total_taxa) - TOTAL_DESCONTO)*0.75) FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_BRUTO,
              (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
              (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
              PR.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
              EXTRACT(MONTH FROM PR.DATA),
              EXTRACT(YEAR FROM PR.DATA),
              PE.valor_compensado, pr.protocolo_id
            FROM R_PROTOCOLO PR, R_PEDIDO PE
            WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
            AND PR.TIPO_PROTOCOLO = '1'
            AND PR.DATA BETWEEN CAST(:V_DATA_TEMP AS TIMESTAMP)
                            AND CAST(:V_DATA_TEMP AS TIMESTAMP)+ 0.9999
            AND PR.NUMERO_ORDEM > (:V_PROTOCOLO_INICIAL - 1)
            ORDER BY 1,2
            INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
              :V_TIPO_COBRANCA, :V_VALOR_BRUTO, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
              :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO, :V_VALOR_COMPENSADO, :V_PROTOCOLO_ID DO
        BEGIN
          V_QTDE_CONSOLIDACAO = 0;
          SISTEMA_ID = 1;
          TIPO_RETORNO = 1; --1=PRENOTACAO, DEPÓSITO PRÉVIO DE 75% RI/DF
          TOTAL_ISS = 0;
          TOTAL_TERCEIRO = 0;
    
          IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
          BEGIN
            NATUREZA = 'Registro/Averbação';
          END
          ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            NATUREZA = 'Averbação';
          END
          ELSE
          BEGIN
            NATUREZA = 'Registro';
          END    
      
          IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
          BEGIN
            V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
          END
          ELSE
          BEGIN
            SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
            WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
            AND I.PEDIDO_ID = :ID
            AND COALESCE(N.CONSOLIDACAO,'') = 'S'
            INTO :V_QTDE_CONSOLIDACAO;
      
            if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
            begin
              V_RETORNAR = 'N';
            end
            else
            begin
              V_RETORNAR = 'S';
            end
          END
      
          if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
          BEGIN
            V_VALOR_BRUTO = 0;
          END
          V_VALOR_EMOLUMENTO = CAST(COALESCE((:V_VALOR_BRUTO * 0.9346),0) AS NUMERIC(18,2));
          V_VALOR_FUNDO = (:V_VALOR_BRUTO - :V_VALOR_EMOLUMENTO);
          V_VALOR_TAXA_JUDICIARIA = 0;
          if ((:v_valor_emolumento < 0.5) and (:v_valor_emolumento > -0.5)) then
          begin
            V_VALOR_EMOLUMENTO = 0;
            V_VALOR_FUNDO = 0;
            V_VALOR_TAXA_JUDICIARIA = 0;
          end
    
          --SELECT T.DESCRICAO
          --FROM R_PEDIDO PE, R_TB_TITULO T
          --WHERE PE.PEDIDO_ID = :ID
          --AND PE.tb_titulo_id = T.tb_titulo_id
          --INTO :NATUREZA;
    
          --ALTERACAO EM 17/09/2019
          V_CONSOLIDACAO = '';
          SELECT FIRST 1 N.DESCRICAO, N.CONSOLIDACAO
          FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
          WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
          AND I.PEDIDO_ID = :ID
          ORDER BY SEQUENCIA
          INTO :V_NATUREZA_FORMAL, :V_CONSOLIDACAO;
    
          V_VALOR_TEMP = 0;
          if (COALESCE(:V_MODELO_DIARIO_AUXILIAR,'') = '2') then  -- se for "MODELO 2" pega valor do caixa.
          begin
            if ((:V_TIPO_ORIGEM_SITE <> '3') AND (COALESCE(:V_CONSOLIDACAO,'') <> 'S')) THEN --se nao for notificacao de alienacao fiduciaria eridft
            begin
              SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
              WHERE TIPO_SERVICO = :TIPO_PROTOCOLO
              AND CHAVE_SERVICO = :V_PROTOCOLO_ID
              AND TIPO_TRANSACAO = 'C'
              AND CAST(DATA_PAGAMENTO AS DATE) = CAST(:DATA AS DATE)
              INTO :V_VALOR_TEMP;
              V_VALOR_EMOLUMENTO = CAST((COALESCE(:V_VALOR_TEMP,0) * 0.9346) AS NUMERIC(18,2));
              V_VALOR_FUNDO = (:V_VALOR_TEMP - :V_VALOR_EMOLUMENTO);
              if (COALESCE(:V_VALOR_COMPENSADO,0) > 0) then
              BEGIN
                V_VALOR_EMOLUMENTO_COMPENSADO = CAST((COALESCE(:V_VALOR_COMPENSADO,0) * 0.9346) AS NUMERIC(18,2));
                V_VALOR_FUNDO_COMPENSADO = (:V_VALOR_COMPENSADO - :V_VALOR_EMOLUMENTO_COMPENSADO);
      
                V_VALOR_EMOLUMENTO = COALESCE(:V_VALOR_EMOLUMENTO,0) + V_VALOR_EMOLUMENTO_COMPENSADO;
                V_VALOR_FUNDO = COALESCE(:V_VALOR_FUNDO,0) + V_VALOR_FUNDO_COMPENSADO;
              END
    
              V_VALOR_EMOLUMENTO = V_VALOR_EMOLUMENTO - (CAST((:V_VALOR_EMOLUMENTO * 0.25) AS NUMERIC(14,2)));
              V_VALOR_FUNDO = V_VALOR_FUNDO - (CAST((:V_VALOR_FUNDO * 0.25) AS NUMERIC(14,2)));
            end
          end
          --FIM ALTERACAO EM 17/09/2019
    
          V_DESCRICAO = 'PROTOCOLO '||CAST(:NUMERO_PROTOCOLO AS VARCHAR(10))||' - [75%] - '||:V_NATUREZA_FORMAL;
          IF (:V_QTDE_REGISTRO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
          END
          IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
          END
          IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
          BEGIN
            TOTAL_EMOLUMENTO = 0;
            TOTAL_TAXA_JUDICIARIA = 0;
            TOTAL_FUNDO = 0;
            V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
          END
          ELSE
          BEGIN
            TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
            TOTAL_FUNDO = :V_VALOR_FUNDO;
            IF (:TOTAL_EMOLUMENTO < 0) THEN
            BEGIN
              TOTAL_EMOLUMENTO = 0;
              TOTAL_FUNDO = 0;
            END
            TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
          END
          QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
          TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO + :TOTAL_ISS + :TOTAL_TERCEIRO;
    
          DESCRICAO = :V_DESCRICAO || ' (Dep.Prévio)';
          if (:V_RETORNAR = 'S') THEN
          BEGIN
            SUSPEND;
          END
        END
      
        --SELECIONAR PROTOCOLOS REGISTRADOS DO RI 75% como saída
        --Lançamento como saída da conversão de 75% dado como depósito prévio em receita da serventia na data do registro/averbação
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        TOTAL_DESPESA = 0;
    
        TOTAL_ISS = 0;
        TOTAL_TERCEIRO = 0;
        TOTAL_BRUTO = 0;
        QTDE = 0;
    
        FOR SELECT CAST(A.DATA AS DATE),
              PR.NUMERO_ORDEM,
              PR.PEDIDO_ID,
              PR.TIPO_PROTOCOLO,
              T.DESCRICAO,
              PE.TIPO_COBRANCA,
              (SELECT (((TOTAL_EMOLUMENTO + total_fundo_ri + total_taxa) - TOTAL_DESCONTO) - (((TOTAL_EMOLUMENTO + total_fundo_ri + total_taxa) - TOTAL_DESCONTO)*0.25)) FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_BRUTO,
              (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
              (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
              A.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
              EXTRACT(MONTH FROM A.DATA),
              EXTRACT(YEAR FROM A.DATA)
            FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
            WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
            AND PE.TB_TITULO_ID = T.TB_TITULO_ID
            AND PE.PEDIDO_ID = A.PEDIDO_ID
            AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
            AND PR.TIPO_PROTOCOLO = '1'
            AND TA.TIPO = 'R' --REGISTRADOS
            AND A.DATA BETWEEN CAST(:V_DATA_TEMP AS TIMESTAMP)
                           AND CAST(:V_DATA_TEMP AS TIMESTAMP)+ 0.9999
            AND PR.NUMERO_ORDEM > (:V_PROTOCOLO_INICIAL - 1)
            ORDER BY 1,2
            INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
              :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA, :V_VALOR_BRUTO, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
              :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO DO
        BEGIN
          V_QTDE_CONSOLIDACAO = 0;
          SISTEMA_ID = 1;
          TIPO_RETORNO = 2; --2=LANCAMENTO COMO SAIDA DA CONVERSAO DO DEPOSITO PREVIO EM RECEITA
    
          TOTAL_ISS = 0;
          TOTAL_TERCEIRO = 0;
    
          IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
          BEGIN
            NATUREZA = 'Registro/Averbação';
          END
          ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            NATUREZA = 'Averbação';
          END
          ELSE
          BEGIN
            NATUREZA = 'Registro';
          END    
    
          IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
          BEGIN
            V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
          END
          ELSE
          BEGIN
            SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
            WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
            AND I.PEDIDO_ID = :ID
            AND COALESCE(N.CONSOLIDACAO,'') = 'S'
            INTO :V_QTDE_CONSOLIDACAO;
      
            if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
            begin
              V_RETORNAR = 'N';
            end
            else
            begin
              V_RETORNAR = 'S';
            end
          END
      
          V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
          IF (:V_QTDE_REGISTRO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
          END
          IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
          END
      
          if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
          BEGIN
            V_VALOR_BRUTO = 0;
          END
          TOTAL_EMOLUMENTO = 0;
          TOTAL_TAXA_JUDICIARIA = 0;
          TOTAL_FUNDO = 0;
      
          IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
          BEGIN
            TOTAL_DESPESA = 0;
            V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
          END
          ELSE
          BEGIN
            TOTAL_DESPESA = :V_VALOR_BRUTO;
          END
          DESCRICAO = :V_DESCRICAO || ' (Conversão em receita)';
    
          QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
          TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO + :TOTAL_ISS + :TOTAL_TERCEIRO;
      
          if (:V_RETORNAR = 'S') THEN
          BEGIN
            SUSPEND;
          END
        END
      
        --SELECIONAR PROTOCOLOS CANCELADOS DO RI 75% como saída
        --Lançamento como saída da conversão de 75% dado como depósito prévio como devolução ao usuário
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        TOTAL_DESPESA = 0;
    
        TOTAL_ISS = 0;
        TOTAL_TERCEIRO = 0;
        TOTAL_BRUTO = 0;
        QTDE = 0;
    
        FOR SELECT CAST(A.DATA AS DATE),
              PR.NUMERO_ORDEM,
              PR.PEDIDO_ID,
              PR.TIPO_PROTOCOLO,
              T.DESCRICAO,
              PE.TIPO_COBRANCA,
              (SELECT (((TOTAL_EMOLUMENTO + total_fundo_ri + total_taxa) - TOTAL_DESCONTO)*0.75) FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_BRUTO,
              (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
              (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
              A.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
              EXTRACT(MONTH FROM A.DATA),
              EXTRACT(YEAR FROM A.DATA)
            FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
            WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
            AND PE.TB_TITULO_ID = T.TB_TITULO_ID
            AND PE.PEDIDO_ID = A.PEDIDO_ID
            AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
            AND PR.TIPO_PROTOCOLO = '1'
            AND TA.TIPO = 'C' --CANCELADOS
            AND A.DATA BETWEEN CAST(:V_DATA_TEMP AS TIMESTAMP)
                           AND CAST(:V_DATA_TEMP AS TIMESTAMP)+ 0.9999
            AND PR.NUMERO_ORDEM > (:V_PROTOCOLO_INICIAL - 1)
            ORDER BY 1,2
            INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
              :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA, :V_VALOR_BRUTO, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
              :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO DO
        BEGIN
          V_QTDE_CONSOLIDACAO = 0;
          SISTEMA_ID = 1;
          TIPO_RETORNO = 3; --2=LANCAMENTO COMO SAIDA DA CONVERSAO DO DEPOSITO PREVIO EM DEVOLUCAO
    
          TOTAL_ISS = 0;
          TOTAL_TERCEIRO = 0;
    
          IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
          BEGIN
            NATUREZA = 'Registro/Averbação';
          END
          ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            NATUREZA = 'Averbação';
          END
          ELSE
          BEGIN
            NATUREZA = 'Registro';
          END    
    
          IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
          BEGIN
            V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
          END
          ELSE
          BEGIN
            SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
            WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
            AND I.PEDIDO_ID = :ID
            AND COALESCE(N.CONSOLIDACAO,'') = 'S'
            INTO :V_QTDE_CONSOLIDACAO;
      
            if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
            begin
              V_RETORNAR = 'N';
            end
            else
            begin
              V_RETORNAR = 'S';
            end
          END
      
          V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
          IF (:V_QTDE_REGISTRO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
          END
          IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
          END
      
          if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
          BEGIN
            V_VALOR_BRUTO = 0;
          END
          TOTAL_EMOLUMENTO = 0;
          TOTAL_TAXA_JUDICIARIA = 0;
          TOTAL_FUNDO = 0;
      
          IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
          BEGIN
            TOTAL_DESPESA = 0;
            V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
          END
          ELSE
          BEGIN
            TOTAL_DESPESA = :V_VALOR_BRUTO;
          END
          DESCRICAO = :V_DESCRICAO || ' (Conversão em receita)';
    
          QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
          TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO + :TOTAL_ISS + :TOTAL_TERCEIRO;
      
          if (:V_RETORNAR = 'S') THEN
          BEGIN
            SUSPEND;
          END
        END
        --final versao 2
      end
      else
      begin
        --INICIO REGISTRO DE IMOVEIS
        --REGISTRO DE IMOVEIS - SELECIONAR PROTOCOLADOS - ESCRITURACAO DE 75% - deposito
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        TOTAL_DESPESA = 0;
    
        TOTAL_ISS = 0;
        TOTAL_TERCEIRO = 0;
        TOTAL_BRUTO = 0;
        QTDE = 0;
    
        FOR SELECT CAST(PR.DATA AS DATE),
              PR.NUMERO_ORDEM,
              PR.PEDIDO_ID,
              PR.TIPO_PROTOCOLO,
              PE.TIPO_COBRANCA,
              (SELECT (CREDITO_INICIAL - (((TOTAL_EMOLUMENTO + total_fundo_ri + total_taxa) - TOTAL_DESCONTO)*0.25)) FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_BRUTO,
              (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
              (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
              PR.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
              EXTRACT(MONTH FROM PR.DATA),
              EXTRACT(YEAR FROM PR.DATA),
              pe.valor_compensado, pr.protocolo_id
            FROM R_PROTOCOLO PR, R_PEDIDO PE
            WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
            AND PR.TIPO_PROTOCOLO = '1'
            AND PR.DATA BETWEEN CAST(:V_DATA_TEMP AS TIMESTAMP)
                            AND CAST(:V_DATA_TEMP AS TIMESTAMP)+ 0.9999
            AND PR.NUMERO_ORDEM > (:V_PROTOCOLO_INICIAL - 1)
            ORDER BY 1,2
            INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
              :V_TIPO_COBRANCA, :V_VALOR_BRUTO, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
              :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO, :V_VALOR_COMPENSADO, :V_PROTOCOLO_ID DO
        BEGIN
          V_QTDE_CONSOLIDACAO = 0;
          SISTEMA_ID = 1;
          TIPO_RETORNO = 1; --1=PRENOTACAO, DEPÓSITO PRÉVIO DE 75% RI/DF
    
          TOTAL_ISS = 0;
          TOTAL_TERCEIRO = 0;
    
          IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
          BEGIN
            NATUREZA = 'Registro/Averbação';
          END
          ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            NATUREZA = 'Averbação';
          END
          ELSE
          BEGIN
            NATUREZA = 'Registro';
          END    
    
          IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
          BEGIN
            V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
          END
          ELSE
          BEGIN
            SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
            WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
            AND I.PEDIDO_ID = :ID
            AND COALESCE(N.CONSOLIDACAO,'') = 'S'
            INTO :V_QTDE_CONSOLIDACAO;
      
            if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
            begin
              V_RETORNAR = 'N';
            end
            else
            begin
              V_RETORNAR = 'S';
            end
          END
      
          if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
          BEGIN
            V_VALOR_BRUTO = 0;
          END
          else
          begin
            SELECT CREDITO_INICIAL, ((TOTAL_EMOLUMENTO + total_fundo_ri + total_taxa) - TOTAL_DESCONTO)
            FROM R_TOTAL_PEDIDO(:ID)
            INTO :V_CREDITO_INICIAL, :V_TOTAL_PROTOCOLO;
      
            if (coalesce(:V_CREDITO_INICIAL,0) > coalesce(:V_TOTAL_PROTOCOLO,0)) then
            begin
              V_VALOR_BRUTO = CAST((coalesce(:V_TOTAL_PROTOCOLO,0) * 0.75) AS NUMERIC(18,2));
            end
          end
      
          V_VALOR_EMOLUMENTO = CAST(COALESCE((:V_VALOR_BRUTO * 0.9346),0) AS NUMERIC(18,2));
          V_VALOR_FUNDO = (:V_VALOR_BRUTO - :V_VALOR_EMOLUMENTO);
          V_VALOR_TAXA_JUDICIARIA = 0;
          if ((:v_valor_emolumento < 0.5) and (:v_valor_emolumento > -0.5)) then
          begin
            V_VALOR_EMOLUMENTO = 0;
            V_VALOR_FUNDO = 0;
            V_VALOR_TAXA_JUDICIARIA = 0;
          end
      
          --SELECT T.DESCRICAO
          --FROM R_PEDIDO PE, R_TB_TITULO T
          --WHERE PE.PEDIDO_ID = :ID
          --AND PE.tb_titulo_id = T.tb_titulo_id
          --INTO :NATUREZA;
    
          --ALTERACAO EM 17/09/2019
          V_CONSOLIDACAO = '';
          SELECT FIRST 1 N.DESCRICAO, N.CONSOLIDACAO
          FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
          WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
          AND I.PEDIDO_ID = :ID
          ORDER BY SEQUENCIA
          INTO :V_NATUREZA_FORMAL, :V_CONSOLIDACAO;
    
          V_VALOR_TEMP = 0;
          if (COALESCE(:V_MODELO_DIARIO_AUXILIAR,'') = '2') then  -- se for "MODELO 2" pega valor do caixa.
          begin
            if ((:V_TIPO_ORIGEM_SITE <> '3') AND (COALESCE(:V_CONSOLIDACAO,'') <> 'S')) THEN --se nao for notificacao de alienacao fiduciaria eridft
            begin
              SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
              WHERE TIPO_SERVICO = :TIPO_PROTOCOLO
              AND CHAVE_SERVICO = :V_PROTOCOLO_ID
              AND TIPO_TRANSACAO = 'C'
              AND CAST(DATA_PAGAMENTO AS DATE) = CAST(:DATA AS DATE)
              INTO :V_VALOR_TEMP;
              V_VALOR_EMOLUMENTO = CAST((COALESCE(:V_VALOR_TEMP,0) * 0.9346) AS NUMERIC(18,2));
              V_VALOR_FUNDO = (:V_VALOR_TEMP - :V_VALOR_EMOLUMENTO);
              if (COALESCE(:V_VALOR_COMPENSADO,0) > 0) then
              BEGIN
                V_VALOR_EMOLUMENTO_COMPENSADO = CAST((COALESCE(:V_VALOR_COMPENSADO,0) * 0.9346) AS NUMERIC(18,2));
                V_VALOR_FUNDO_COMPENSADO = (:V_VALOR_COMPENSADO - :V_VALOR_EMOLUMENTO_COMPENSADO);
      
                V_VALOR_EMOLUMENTO = COALESCE(:V_VALOR_EMOLUMENTO,0) + V_VALOR_EMOLUMENTO_COMPENSADO;
                V_VALOR_FUNDO = COALESCE(:V_VALOR_FUNDO,0) + V_VALOR_FUNDO_COMPENSADO;
              END
    
              V_VALOR_EMOLUMENTO = V_VALOR_EMOLUMENTO - (CAST((:V_VALOR_EMOLUMENTO * 0.25) AS NUMERIC(14,2)));
              V_VALOR_FUNDO = V_VALOR_FUNDO - (CAST((:V_VALOR_FUNDO * 0.25) AS NUMERIC(14,2)));
            end
          end
          --FIM ALTERACAO EM 17/09/2019
      
          V_DESCRICAO = 'PROTOCOLO '||CAST(:NUMERO_PROTOCOLO AS VARCHAR(10))||' - [75%] - '||:V_NATUREZA_FORMAL;
          IF (:V_QTDE_REGISTRO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
          END
          IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
          END
          IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
          BEGIN
            TOTAL_EMOLUMENTO = 0;
            TOTAL_TAXA_JUDICIARIA = 0;
            TOTAL_FUNDO = 0;
            V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
          END
          ELSE
          BEGIN
            TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
            TOTAL_FUNDO = :V_VALOR_FUNDO;
            IF (:TOTAL_EMOLUMENTO < 0) THEN
            BEGIN
              TOTAL_EMOLUMENTO = 0;
              TOTAL_FUNDO = 0;
            END
            TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
          END
          DESCRICAO = :V_DESCRICAO || ' (Dep.Prévio)';
    
          QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
          TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO + :TOTAL_ISS + :TOTAL_TERCEIRO;
    
          if (:V_RETORNAR = 'S') THEN
          BEGIN
            SUSPEND;
          END
        END
      
        if (COALESCE(:V_MODELO_DIARIO_AUXILIAR,'') <> '2') then  -- se NÃO for "MODELO 2"
        begin
          --INICIO REGISTRO DE IMOVEIS
          --REGISTRO DE IMOVEIS - SELECIONAR PROTOCOLADOS - ESCRITURACAO DE 75% - diferença de custas (entradas)
          TOTAL_EMOLUMENTO = 0;
          TOTAL_TAXA_JUDICIARIA = 0;
          TOTAL_FUNDO = 0;
          TOTAL_DESPESA = 0;
          V_DEPOSITO_INICIAL = 0;
      
          TOTAL_ISS = 0;
          TOTAL_TERCEIRO = 0;
          TOTAL_BRUTO = 0;
          QTDE = 0;
      
          FOR SELECT CAST(CI.DATA_PAGAMENTO AS DATE), COALESCE(CI.VALOR_PAGO,0),
                CI.CHAVE_SERVICO,
                EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
                EXTRACT(YEAR FROM CI.DATA_PAGAMENTO)
              FROM C_CAIXA_ITEM CI
              WHERE CI.tipo_servico = '1' --PROTOCOLO
              AND CAST(CI.DATA_PAGAMENTO AS DATE) BETWEEN :V_DATA_TEMP AND :V_DATA_TEMP
              AND CI.CAIXA_SERVICO_ID = :V_SERVICO_DIFERENCA_CUSTA_ENTRADA
              INTO :DATA, :V_VALOR_BRUTO, :V_PROTOCOLO_ID, :MES, :ANO DO
          BEGIN
            V_QTDE_CONSOLIDACAO = 0;
            DATA_HORA = :DATA;
      
            TOTAL_ISS = 0;
            TOTAL_TERCEIRO = 0;
      
            SELECT PR.NUMERO_ORDEM, PR.TIPO_PROTOCOLO, PR.PEDIDO_ID, PE.TIPO_COBRANCA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
              (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
              (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_AVERBACAO
            FROM r_protocolo PR, r_pedido PE
            where pr.pedido_id = pe.pedido_id
            and pr.protocolo_id = :v_protocolo_id
            into :NUMERO_PROTOCOLO, :TIPO_PROTOCOLO, :ID, :V_TIPO_COBRANCA, :V_TIPO_ORIGEM_SITE, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO;
        
            SELECT CREDITO_INICIAL, (CREDITO_INICIAL - (((TOTAL_EMOLUMENTO + total_fundo_ri + total_taxa) - TOTAL_DESCONTO)*0.25)), (TOTAL_EMOLUMENTO + total_fundo_ri + total_taxa)
            FROM R_TOTAL_PEDIDO(:ID)
            INTO :V_CREDITO_INICIAL, :V_DEPOSITO_INICIAL, :V_TOTAL_PROTOCOLO;
        
            if (coalesce(:v_deposito_inicial,0) < 0) then
            begin
              V_VALOR_BRUTO = (:V_VALOR_BRUTO + :V_CREDITO_INICIAL) - CAST((:V_TOTAL_PROTOCOLO * 0.25) AS NUMERIC(18,2));
            end
        
            SISTEMA_ID = 1;
            TIPO_RETORNO = 1; --1=PRENOTACAO, DEPÓSITO PRÉVIO DE 75% RI/DF
    
            IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
            BEGIN
              NATUREZA = 'Registro/Averbação';
            END
            ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
            BEGIN
              NATUREZA = 'Averbação';
            END
            ELSE
            BEGIN
              NATUREZA = 'Registro';
            END    
        
            IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
            BEGIN
              V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
            END
            ELSE
            BEGIN
              SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
              WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
              AND I.PEDIDO_ID = :ID
              AND COALESCE(N.CONSOLIDACAO,'') = 'S'
              INTO :V_QTDE_CONSOLIDACAO;
        
              if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
              begin
                V_RETORNAR = 'N';
              end
              else
              begin
                V_RETORNAR = 'S';
              end
            END
        
            if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
            BEGIN
              V_VALOR_BRUTO = 0;
            END
            V_VALOR_EMOLUMENTO = CAST(COALESCE((:V_VALOR_BRUTO * 0.9346),0) AS NUMERIC(18,2));
            V_VALOR_FUNDO = (:V_VALOR_BRUTO - :V_VALOR_EMOLUMENTO);
            V_VALOR_TAXA_JUDICIARIA = 0;
            if ((:v_valor_emolumento < 0.5) and (:v_valor_emolumento > -0.5)) then
            begin
              V_VALOR_EMOLUMENTO = 0;
              V_VALOR_FUNDO = 0;
              V_VALOR_TAXA_JUDICIARIA = 0;
            end
        
            SELECT T.DESCRICAO
            FROM R_PEDIDO PE, R_TB_TITULO T
            WHERE PE.PEDIDO_ID = :ID
            AND PE.tb_titulo_id = T.tb_titulo_id
            INTO :V_NATUREZA_FORMAL;
        
            V_DESCRICAO = 'PROTOCOLO '||CAST(:NUMERO_PROTOCOLO AS VARCHAR(10))||' - [75%] - '||:V_NATUREZA_FORMAL;
            IF (:V_QTDE_REGISTRO > 0) THEN
            BEGIN
              V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
            END
            IF (:V_QTDE_AVERBACAO > 0) THEN
            BEGIN
              V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
            END
            IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
            BEGIN
              TOTAL_EMOLUMENTO = 0;
              TOTAL_TAXA_JUDICIARIA = 0;
              TOTAL_FUNDO = 0;
              V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
            END
            ELSE
            BEGIN
              TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
              TOTAL_FUNDO = :V_VALOR_FUNDO;
              IF (:TOTAL_EMOLUMENTO < 0) THEN
              BEGIN
                TOTAL_EMOLUMENTO = 0;
                TOTAL_FUNDO = 0;
              END
              TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
            END
            DESCRICAO = :V_DESCRICAO || ' (Dep.Prévio - Dif. Custas)';
      
            QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
            TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO + :TOTAL_ISS + :TOTAL_TERCEIRO;
      
            if (:V_RETORNAR = 'S') THEN
            BEGIN
              SUSPEND;
            END
          END
        end
      
        --SELECIONAR PROTOCOLOS REGISTRADOS DO RI 75% como saída
        --Lançamento como saída da conversão de 75% dado como depósito prévio em receita da serventia na data do registro/averbação
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        TOTAL_DESPESA = 0;
    
        TOTAL_ISS = 0;
        TOTAL_TERCEIRO = 0;
        TOTAL_BRUTO = 0;
        QTDE = 0;
    
        FOR SELECT CAST(A.DATA AS DATE),
              PR.NUMERO_ORDEM,
              PR.PEDIDO_ID,
              PR.TIPO_PROTOCOLO,
              T.DESCRICAO,
              PE.TIPO_COBRANCA,
              (SELECT (CREDITO - (((TOTAL_EMOLUMENTO + total_fundo_ri + total_taxa) - TOTAL_DESCONTO)*0.25)) FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_BRUTO,
              (SELECT QUANTIDADE_REGISTRO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_REGISTRO,
              (SELECT QUANTIDADE_AVERBACAO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS QTDE_AVERBACAO,
              A.DATA, COALESCE(PE.TIPO_ORIGEM_SITE,''),
              EXTRACT(MONTH FROM A.DATA),
              EXTRACT(YEAR FROM A.DATA)
            FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
            WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
            AND PE.TB_TITULO_ID = T.TB_TITULO_ID
            AND PE.PEDIDO_ID = A.PEDIDO_ID
            AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
            AND PR.TIPO_PROTOCOLO = '1'
            AND TA.TIPO = 'R' --REGISTRADOS
            AND A.DATA BETWEEN CAST(:V_DATA_TEMP AS TIMESTAMP)
                           AND CAST(:V_DATA_TEMP AS TIMESTAMP)+ 0.9999
            AND PR.NUMERO_ORDEM > (:V_PROTOCOLO_INICIAL - 1)
            ORDER BY 1,2
            INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,
              :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA, :V_VALOR_BRUTO, :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO,
              :DATA_HORA, :V_TIPO_ORIGEM_SITE, :MES, :ANO DO
        BEGIN
          V_QTDE_CONSOLIDACAO = 0;
          SISTEMA_ID = 1;
          TIPO_RETORNO = 2; --2=LANCAMENTO COMO SAIDA DA CONVERSAO DO DEPOSITO PREVIO EM RECEITA
    
          TOTAL_ISS = 0;
          TOTAL_TERCEIRO = 0;
    
          IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
          BEGIN
            NATUREZA = 'Registro/Averbação';
          END
          ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            NATUREZA = 'Averbação';
          END
          ELSE
          BEGIN
            NATUREZA = 'Registro';
          END    
    
          IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
          BEGIN
            V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
          END
          ELSE
          BEGIN
            SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
            WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
            AND I.PEDIDO_ID = :ID
            AND COALESCE(N.CONSOLIDACAO,'') = 'S'
            INTO :V_QTDE_CONSOLIDACAO;
      
            if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
            begin
              V_RETORNAR = 'N';
            end
            else
            begin
              V_RETORNAR = 'S';
            end
          END
      
          V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
          IF (:V_QTDE_REGISTRO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
          END
          IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
          END
      
          if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
          BEGIN
            V_VALOR_BRUTO = 0;
          END
          else
          begin
            SELECT CREDITO_INICIAL, ((TOTAL_EMOLUMENTO + total_fundo_ri + total_taxa) - TOTAL_DESCONTO)
            FROM R_TOTAL_PEDIDO(:ID)
            INTO :V_CREDITO_INICIAL, :V_TOTAL_PROTOCOLO;
      
            if (coalesce(:V_CREDITO_INICIAL,0) > coalesce(:V_TOTAL_PROTOCOLO,0)) then
            begin
              V_VALOR_BRUTO = CAST((coalesce(:V_TOTAL_PROTOCOLO,0) * 0.75) AS NUMERIC(18,2));
            end
          end
      
          TOTAL_EMOLUMENTO = 0;
          TOTAL_TAXA_JUDICIARIA = 0;
          TOTAL_FUNDO = 0;
      
          IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
          BEGIN
            TOTAL_DESPESA = 0;
            V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
          END
          ELSE
          BEGIN
            TOTAL_DESPESA = :V_VALOR_BRUTO;
          END
          DESCRICAO = :V_DESCRICAO || ' (Conversão em receita)';
    
          QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
          TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO + :TOTAL_ISS + :TOTAL_TERCEIRO;
      
          if (:V_RETORNAR = 'S') THEN
          BEGIN
            SUSPEND;
          END
        END
      
        --SELECIONAR PROTOCOLOS CANCELADOS DO RI 75% como devolução ao usuário
        --Lançamento como saída da conversão de 75% dado como depósito prévio como devolução ao usuario
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        TOTAL_DESPESA = 0;
    
        TOTAL_ISS = 0;
        TOTAL_TERCEIRO = 0;
        TOTAL_BRUTO = 0;
        QTDE = 0;
    
        FOR SELECT CAST(C.DATA_PAGAMENTO AS DATE),
              PR.NUMERO_ORDEM,
              PR.PEDIDO_ID,
              PR.TIPO_PROTOCOLO,
              T.DESCRICAO,
              PE.TIPO_COBRANCA,
              C.DATA_PAGAMENTO, COALESCE(PE.TIPO_ORIGEM_SITE,''), C.CAIXA_SERVICO_ID,
              COALESCE(C.valor_pago,0),
              EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
              EXTRACT(YEAR FROM C.DATA_PAGAMENTO)
            FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA,
              C_CAIXA_ITEM C
            WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
            AND PE.TB_TITULO_ID = T.TB_TITULO_ID
            AND PE.PEDIDO_ID = A.PEDIDO_ID
            AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
            AND C.CHAVE_SERVICO = PR.PROTOCOLO_ID
            AND PR.TIPO_PROTOCOLO = '1'
            AND TA.TIPO = 'C' --CANCELADOS
            AND C.DATA_PAGAMENTO BETWEEN CAST(:V_DATA_TEMP AS TIMESTAMP)
                                     AND CAST(:V_DATA_TEMP AS TIMESTAMP)+ 0.9999
            AND C.CAIXA_SERVICO_ID IN (:V_SERVICO_DEVOLUCAO_75, :V_SERVICO_DEVOLUCAO_100, :V_SERVICO_DEVOLUCAO_APRESENTANTE, :V_SERVICO_DEVOLUCAO_TJDFT)
            AND PR.NUMERO_ORDEM > (:V_PROTOCOLO_INICIAL - 1)
            ORDER BY 1,2
            INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO,   :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA,
              :DATA_HORA, :V_TIPO_ORIGEM_SITE, :V_CAIXA_SERVICO_ID, :V_VALOR_BRUTO, :MES, :ANO DO
        BEGIN
          V_QTDE_CONSOLIDACAO = 0;
          SISTEMA_ID = 1;
    
          TOTAL_ISS = 0;
          TOTAL_TERCEIRO = 0;
    
          if (:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) then
          begin
            TIPO_RETORNO = 4; --4=LANCAMENTO COMO SAIDA À VARA DE REGISTROS PUBLICOS
          end
          else
          begin
            TIPO_RETORNO = 3; --3=LANCAMENTO COMO SAIDA COMO DEVOLUCAO AO USUARIO
          end
      
          SELECT QUANTIDADE_REGISTRO, QUANTIDADE_AVERBACAO
          FROM R_TOTAL_PEDIDO(:ID)
          into :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO;
    
          IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
          BEGIN
            NATUREZA = 'Registro/Averbação';
          END
          ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            NATUREZA = 'Averbação';
          END
          ELSE
          BEGIN
            NATUREZA = 'Registro';
          END    
      
          IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
          BEGIN
            V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
          END
          ELSE
          BEGIN
            SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
            WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
            AND I.PEDIDO_ID = :ID
            AND COALESCE(N.CONSOLIDACAO,'') = 'S'
            INTO :V_QTDE_CONSOLIDACAO;
      
            if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
            begin
              V_RETORNAR = 'N';
            end
            else
            begin
              V_RETORNAR = 'S';
            end
          END
      
          V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
      
          if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
          BEGIN
            V_VALOR_BRUTO = 0;
          END
          TOTAL_EMOLUMENTO = 0;
          TOTAL_TAXA_JUDICIARIA = 0;
          TOTAL_FUNDO = 0;
      
          IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
          BEGIN
            --NÃO FAZ NADA
            TOTAL_DESPESA = 0;
          END
          ELSE
          BEGIN
            TOTAL_DESPESA = :V_VALOR_BRUTO;
      
            if (:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) then
            begin
              DESCRICAO = :V_DESCRICAO || ' (Devolução à vara de registros públicos)';
            end
            else
            begin
              DESCRICAO = :V_DESCRICAO || ' (Devolução ao usuário)';
            end
    
            QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
            TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO + :TOTAL_ISS + :TOTAL_TERCEIRO;
      
            if (:V_RETORNAR = 'S') THEN
            BEGIN
              SUSPEND;
            END
          END
        END
      
        --SELECIONAR PROTOCOLOS CANCELADOS DO RI 75% como devolução ao usuário feito por COMPENSACAO
        --Lançamento como saída da conversão de 75% dado como depósito prévio como devolução ao usuario FEITO POR COMPENSACAO
        FOR SELECT CAST(PR.DATA AS DATE), PR.NUMERO_ORDEM, PE.PEDIDO_ID, PE.VALOR_COMPENSADO,
              EXTRACT(MONTH FROM PR.DATA),
              EXTRACT(YEAR FROM PR.DATA)
            FROM R_PEDIDO PE, R_PROTOCOLO PR
            WHERE PE.PEDIDO_ID = PR.PEDIDO_ID
            AND PR.TIPO_PROTOCOLO = '1'
            AND COALESCE(PE.VALOR_COMPENSADO,0) > 0
            AND PR.DATA BETWEEN CAST(:V_DATA_TEMP AS TIMESTAMP)
                            AND CAST(:V_DATA_TEMP AS TIMESTAMP)+ 0.9999
            ORDER BY 1,2
            INTO :V_DATA_NOVO_PROTOCOLO, :V_NOVO_PROTOCOLO, :V_NOVO_PEDIDO_ID,  :V_VALOR_BRUTO, :MES, :ANO DO
        BEGIN
          V_QTDE_CONSOLIDACAO = 0;
          SISTEMA_ID = 1;
          TIPO_RETORNO = 3; --3=LANCAMENTO COMO SAIDA COMO DEVOLUCAO AO USUARIO
      
          DATA_HORA = :V_DATA_NOVO_PROTOCOLO;
          DATA = CAST(:V_DATA_NOVO_PROTOCOLO AS DATE);
      
          --PEGAR DADOS DO PROTOCOLO CANCELADO
          SELECT FIRST 1 PR.PEDIDO_ID, PR.TIPO_PROTOCOLO, PR.NUMERO_ORDEM, T.DESCRICAO,
            PE.TIPO_COBRANCA, COALESCE(PE.TIPO_ORIGEM_SITE,'')
          FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T
          WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
          AND PE.TB_TITULO_ID = T.TB_TITULO_ID
          AND PR.TIPO_PROTOCOLO = '1'
          AND PE.NOVO_PEDIDO_ID = :V_NOVO_PEDIDO_ID
          INTO :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO,
            :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA, :V_TIPO_ORIGEM_SITE;
      
          V_QTDE = 0;
          SELECT COUNT(*) FROM R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
          WHERE A.PEDIDO_ID = :ID
          AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
          AND TA.TIPO = 'C' --CANCELADOS
          INTO :V_QTDE;
      
          if (:V_QTDE > 0) then --EXISTE CANCELAMENTO NO PROTOCOLO
          BEGIN
            SELECT QUANTIDADE_REGISTRO, QUANTIDADE_AVERBACAO
            FROM R_TOTAL_PEDIDO(:ID)
            into :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO;
    
            IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
            BEGIN
              NATUREZA = 'Registro/Averbação';
            END
            ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
            BEGIN
              NATUREZA = 'Averbação';
            END
            ELSE
            BEGIN
              NATUREZA = 'Registro';
            END    
      
            IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
            BEGIN
              V_RETORNAR = 'N'; --NAO RETORNAR, POIS NAO TEM DEPOSITO PREVIO PARA ESTE TIPO
            END
            ELSE
            BEGIN
              SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
              WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
              AND I.PEDIDO_ID = :ID
              AND COALESCE(N.CONSOLIDACAO,'') = 'S'
              INTO :V_QTDE_CONSOLIDACAO;
          
              if (coalesce(V_QTDE_CONSOLIDACAO,0) > 0) then
              begin
                V_RETORNAR = 'N';
              end
              else
              begin
                V_RETORNAR = 'S';
              end
            END
      
            V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
      
            if (COALESCE(:V_VALOR_BRUTO,0) < 0) then
            BEGIN
              V_VALOR_BRUTO = 0;
            END
            TOTAL_EMOLUMENTO = 0;
            TOTAL_TAXA_JUDICIARIA = 0;
            TOTAL_FUNDO = 0;
      
            IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
            BEGIN
              --NÃO FAZ NADA
              TOTAL_DESPESA = 0;
            END
            ELSE
            BEGIN
              TOTAL_DESPESA = :V_VALOR_BRUTO;
      
              DESCRICAO = :V_DESCRICAO || ' (Devolução ao usuário - Compensação)';
      
              if (:V_RETORNAR = 'S') THEN
              BEGIN
                SUSPEND;
              END
            END
          END
        END
      end
    
      --Valores complementares fora da data do protocolo
      if (COALESCE(:V_MODELO_DIARIO_AUXILIAR,'') = '2') then  -- se for "MODELO 2"
      begin
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        QTDE = 0;
        TOTAL_TERCEIRO = 0;
        TOTAL_BRUTO = 0;
    
        V_VALOR_TEMP = 0;
    
        SISTEMA_ID = 1;
        FOR SELECT COALESCE(VALOR_PAGO,0), CHAVE_SERVICO, CAST(DATA_PAGAMENTO AS DATE), DATA_PAGAMENTO,
              EXTRACT(MONTH FROM DATA_PAGAMENTO), EXTRACT(YEAR FROM DATA_PAGAMENTO)
            FROM C_CAIXA_ITEM
            WHERE TIPO_SERVICO = '1' --PROTOCOLOS
            AND COALESCE(CHAVE_SERVICO,0) > 0
            AND TIPO_TRANSACAO = 'C'
            AND DATA_PAGAMENTO BETWEEN CAST(:V_DATA_TEMP AS TIMESTAMP)
                                   AND CAST(:V_DATA_TEMP AS TIMESTAMP)+ 0.9999
            ORDER BY CAIXA_ITEM_ID
            INTO :V_VALOR_TEMP, :V_PROTOCOLO_ID, :DATA, :DATA_HORA, :MES, :ANO DO
        BEGIN
          TIPO_PROTOCOLO = '1';
          SELECT PE.PEDIDO_ID, PR.NUMERO_ORDEM, CAST(PR.DATA AS DATE), PE.TIPO_COBRANCA, COALESCE(PE.ORIGEM_PEDIDO,''), COALESCE(PE.TIPO_ORIGEM_SITE,'')
          FROM R_PROTOCOLO PR, R_PEDIDO PE
          WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
          AND PROTOCOLO_ID = :V_PROTOCOLO_ID
          INTO :ID, :NUMERO_PROTOCOLO, :V_DATA_PROT_TEMP, :V_TIPO_COBRANCA, :V_ORIGEM_PEDIDO, :V_TIPO_ORIGEM_SITE;
    
          if (:DATA > :V_DATA_PROT_TEMP) then --se a data for após o protocolo
          begin
            V_VALOR_EMOLUMENTO = CAST((COALESCE(:V_VALOR_TEMP,0) * 0.9346) AS NUMERIC(18,2));
            V_VALOR_FUNDO = (:V_VALOR_TEMP - :V_VALOR_EMOLUMENTO);
            V_DESCRICAO = 'PROTOCOLO '||CAST(:NUMERO_PROTOCOLO AS VARCHAR(10))||' - [75%] - Complemento';
            DESCRICAO = :V_DESCRICAO;
      
            V_VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO - CAST((:V_VALOR_EMOLUMENTO * 0.25) AS NUMERIC(18,2));
            V_VALOR_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA - CAST((:V_VALOR_TAXA_JUDICIARIA * 0.25) AS NUMERIC(18,2));
            V_VALOR_FUNDO = V_VALOR_FUNDO - CAST((:V_VALOR_FUNDO * 0.25) AS NUMERIC(18,2));
    
            TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
            IF (:TOTAL_EMOLUMENTO < 0) THEN
            BEGIN
              TOTAL_EMOLUMENTO = 0;
            END
            TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
            TOTAL_FUNDO = :V_VALOR_FUNDO;
            TOTAL_TERCEIRO = 0;
            TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO + :TOTAL_TERCEIRO;
    
            IF (:V_ORIGEM_PEDIDO = '2') THEN --ERIDFT
            BEGIN
              IF (:V_TIPO_ORIGEM_SITE = '1') THEN --PENHORA
              BEGIN
                TIPO_RETORNO = 2; --PRENOTACAO REG/AV (Penhora online) (25%)
              END
              ELSE IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT) --> contabilizar 100%
              BEGIN
                TIPO_RETORNO = 3; --PRENOTACAO NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
              END
              ELSE
              BEGIN
                TIPO_RETORNO = 1; --PRENOTACAO REG/AV (25%)
              END
            END
            ELSE --SOLICITADAS NO CARTORIO
            BEGIN
              if (COALESCE(:V_CONSOLIDACAO,'') = 'S') then
              begin
                TIPO_RETORNO = 10; --consolidação (balcão) (100%)
              end
              else
              begin
                TIPO_RETORNO = 1; --PRENOTACAO REG/AV (25%)
              end
            END
      
            SUSPEND;
          end
        END
      end
      V_DATA_TEMP = :V_DATA_TEMP + 1;
  end

END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_GO (DATA_INI TIMESTAMP,
DATA_FIM TIMESTAMP)
RETURNS (ID INTEGER,
DATA DATAHORA,
PROTOCOLO INTEGER,
DESCRICAO VARCHAR_260,
VALOR_EMOLUMENTO DINHEIRO,
VALOR_TAXA_JUDICIARIA DINHEIRO,
VALOR_FUNDESP DINHEIRO,
VALOR_ISS DINHEIRO,
VALOR_TOTAL DINHEIRO,
TIPO_LANCAMENTO VARCHAR_001,
SISTEMA_ID INTEGER,
MES INTEGER,
ANO INTEGER,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_TERCEIRO NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
QTDE NUMERIC(18, 2),
TIPO_RETORNO INTEGER,
STATUS VARCHAR_060)
AS 
DECLARE VARIABLE V_TABELA VARCHAR(20);
DECLARE VARIABLE V_LOTE INTEGER;
DECLARE VARIABLE V_TOTAL_SELO DINHEIRO;
DECLARE VARIABLE V_PROTOCOLO_ID INTEGER;
DECLARE VARIABLE V_PEDIDO_ID INTEGER;
DECLARE VARIABLE V_PEDIDO_ITEM_ID INTEGER;
DECLARE VARIABLE V_CAMPO_ID INTEGER;
DECLARE VARIABLE V_VALOR_TOTAL DINHEIRO;
DECLARE VARIABLE V_VALOR_PAGO DINHEIRO;
DECLARE VARIABLE V_VALOR_PAGO_TEMP DINHEIRO;
DECLARE VARIABLE V_DATA_PROTOCOLO DATE;
DECLARE VARIABLE V_DATA_EXAME DATE;
DECLARE VARIABLE V_DATA_RECEITA DATE;
declare variable V_DATA_RECEITA_RI DATE;
DECLARE VARIABLE V_QTDE_EXAME INTEGER;
DECLARE VARIABLE V_PROTOCOLO_ID_TEMP INTEGER;
DECLARE VARIABLE V_TIPO_PROT_TEMP VARCHAR(3);
BEGIN
  -- LISTAR DEPOSITOS DO PERIODO
  FOR
  SELECT D.DEPOSITO_PREVIO_ID,
         D.PROTOCOLO,
         D.DESCRICAO,
         D.DATA_LANCTO,
         D.TIPO_LANCAMENTO,
         (COALESCE(D.EMOLUMENTOS,0) +
          COALESCE(D.TAXAJUDIC,0) +
          COALESCE(D.FUNDOS,0) +
          COALESCE(D.ISS,0)) VALOR_TOTAL,
         D.SISTEMA_ID,
         D.NLOTE,
          EXTRACT(MONTH FROM D.DATA_LANCTO),
          EXTRACT(YEAR FROM D.DATA_LANCTO),
          COALESCE(D.EMOLUMENTOS,0),
          COALESCE(D.TAXAJUDIC,0),
          COALESCE(D.FUNDOS,0),
          COALESCE(D.ISS,0)
  FROM G_DEPOSITO_PREVIO D
  WHERE D.DATA_LANCTO BETWEEN :DATA_INI AND :DATA_FIM +0.9999
   AND (COALESCE(D.EMOLUMENTOS,0) +
          COALESCE(D.TAXAJUDIC,0) +
          COALESCE(D.FUNDOS,0) +
          COALESCE(D.ISS,0)) > 0
    AND SISTEMA_ID <> 13
    INTO :ID, :PROTOCOLO, :DESCRICAO, :DATA,  :TIPO_LANCAMENTO, :VALOR_TOTAL, :SISTEMA_ID, :V_LOTE, :MES, :ANO,
         :VALOR_EMOLUMENTO, :VALOR_TAXA_JUDICIARIA, :VALOR_FUNDESP, VALOR_ISS  DO
  BEGIN
     IF (V_LOTE > 0) THEN
     BEGIN
       STATUS = '';
       IF (:TIPO_LANCAMENTO = 'D') THEN
       BEGIN
         SELECT SUM(COALESCE(S.VALOR_EMOLUMENTO,0) +
                    COALESCE(S.VALOR_TAXA_JUDICIARIA,0) +
                    COALESCE(S.VALOR_FUNDESP,0) +
                    COALESCE(S.VALOR_ISS,0))
           FROM G_SELO_LIVRO S
          WHERE S.DATA BETWEEN :DATA AND :DATA +0.9999
            AND S.NLOTE IS NOT NULL
            AND S.NLOTE = (:V_LOTE)
           INTO :V_TOTAL_SELO;

           IF (COALESCE(V_TOTAL_SELO,0) > 0) THEN
           BEGIN
             SELECT first 1 CAST(S.DATA AS DATE)  FROM G_SELO_LIVRO S
             WHERE S.DATA BETWEEN :DATA AND :DATA +0.9999
            AND S.NLOTE IS NOT NULL
            AND S.NLOTE = (:V_LOTE)
            INTO :V_DATA_RECEITA;

             STATUS = 'Convertido em receita: '||(LPAD(EXTRACT(DAY FROM V_DATA_RECEITA), 2, '0') || '/' ||
                     LPAD(EXTRACT(MONTH FROM V_DATA_RECEITA), 2, '0') || '/' ||
                     LPAD(EXTRACT(YEAR FROM V_DATA_RECEITA), 4, '0'));
           END
           ELSE
           BEGIN
             STATUS = '';
           END


         IF (COALESCE((VALOR_TOTAL - COALESCE(V_TOTAL_SELO,0)),0) > 0) THEN
         BEGIN
           VALOR_TOTAL = (VALOR_TOTAL - COALESCE(V_TOTAL_SELO,0));
           SUSPEND;
         END
          SELECT SUM(COALESCE(S.VALOR_EMOLUMENTO,0) +
                    COALESCE(S.VALOR_TAXA_JUDICIARIA,0) +
                    COALESCE(S.VALOR_FUNDESP,0) +
                    COALESCE(S.VALOR_ISS,0))
           FROM G_SELO_LIVRO_ANTIGO S
          WHERE S.DATA BETWEEN :DATA AND :DATA +0.9999
            AND S.NLOTE IS NOT NULL
            AND S.NLOTE = (:V_LOTE)
           INTO :V_TOTAL_SELO;

         IF (COALESCE((VALOR_TOTAL - COALESCE(V_TOTAL_SELO,0)),0) > 0) THEN
         BEGIN
           VALOR_TOTAL = (VALOR_TOTAL - COALESCE(V_TOTAL_SELO,0));
           SUSPEND;
         END
       END
       ELSE
       BEGIN
         -- LISTAR AS DEVOLUÇÕES AO CLIENTE
         VALOR_TOTAL = VALOR_TOTAL * -1;
          STATUS = '';
         SUSPEND;
       END
     END
  END

  -- LISTANDO OS SELOS CONVERTIDOS EM RECEITAS
  FOR
  SELECT S.SELO_LIVRO_ID,
         S.DESCRICAO,
         S.DATA,
         S.VALOR_EMOLUMENTO * -1,
         S.VALOR_TAXA_JUDICIARIA  * -1,
         S.VALOR_FUNDESP * -1,
         S.VALOR_ISS * -1,
         (S.VALOR_TOTAL+S.VALOR_ISS) * -1,
         LEFT(S.TABELA,2),
         EXTRACT(MONTH FROM S.DATA),
         EXTRACT(YEAR FROM S.DATA)
    FROM G_SELO_LIVRO S
   WHERE S.DATA BETWEEN :DATA_INI AND :DATA_FIM + 0.9999
     AND S.NLOTE IS NOT NULL
     AND COALESCE(S.NLOTE,0) > 0
     AND TABELA NOT IN ('P_TITULO','P_CERTIDAO')
    INTO :ID, :DESCRICAO, :DATA, :VALOR_EMOLUMENTO, :VALOR_TAXA_JUDICIARIA, :VALOR_FUNDESP, :VALOR_ISS, :VALOR_TOTAL, :V_TABELA, :MES, :ANO DO
  BEGIN
     TIPO_LANCAMENTO = 'R';
     STATUS = '';
     IF (:V_TABELA = 'R_') THEN
        SISTEMA_ID = 1;
     IF (:V_TABELA = 'T_') THEN
        SISTEMA_ID = 2;
     IF (:V_TABELA = 'D_') THEN
        SISTEMA_ID = 7;
     IF (:V_TABELA = 'V_') THEN
        SISTEMA_ID = 12;
     IF (:V_TABELA = 'P_') THEN
        SISTEMA_ID = 13;

     SUSPEND;
  END
   -- LISTANDO OS SELOS CONVERTIDOS EM RECEITAS
  FOR
  SELECT S.SELO_LIVRO_ID,
         S.DESCRICAO,
         S.DATA,
         S.VALOR_EMOLUMENTO * -1,
         S.VALOR_TAXA_JUDICIARIA  * -1,
         S.VALOR_FUNDESP * -1,
         S.VALOR_ISS * -1,
         (S.VALOR_TOTAL+S.VALOR_ISS) * -1,
         LEFT(S.TABELA,2),
         EXTRACT(MONTH FROM S.DATA),
         EXTRACT(YEAR FROM S.DATA)
    FROM G_SELO_LIVRO_ANTIGO S
   WHERE S.DATA BETWEEN :DATA_INI AND :DATA_FIM + 0.9999
     AND S.NLOTE IS NOT NULL
     AND COALESCE(S.NLOTE,0) > 0
    INTO :ID, :DESCRICAO, :DATA, :VALOR_EMOLUMENTO, :VALOR_TAXA_JUDICIARIA, :VALOR_FUNDESP, :VALOR_ISS, :VALOR_TOTAL, :V_TABELA, :MES, :ANO DO
  BEGIN
     TIPO_LANCAMENTO = 'R';
     IF (:V_TABELA = 'R_') THEN
        SISTEMA_ID = 1;
     IF (:V_TABELA = 'T_') THEN
        SISTEMA_ID = 2;
     IF (:V_TABELA = 'D_') THEN
        SISTEMA_ID = 7;
     IF (:V_TABELA = 'V_') THEN
        SISTEMA_ID = 12;
     IF (:V_TABELA = 'P_') THEN
        SISTEMA_ID = 13;

     SUSPEND;
  END
  --LISTAR DEP. PREVIO RI, SOMENTE DE PROTOCOLOS
  --VALOR_EMOLUMENTO = 0;
  --VALOR_TAXA_JUDICIARIA = 0;
 -- VALOR_FUNDESP = 0;
 -- VALOR_ISS = 0;
  VALOR_TOTAL = 0;
  PROTOCOLO = 0;

  FOR SELECT DISTINCT
        (SELECT FIRST 1 PR.PROTOCOLO_ID
         FROM R_PROTOCOLO PR, R_PEDIDO_ITEM PI
         WHERE PR.PEDIDO_ID = PI.PEDIDO_ID
         AND PR.TIPO_PROTOCOLO = '1'
         AND PI.PEDIDO_ITEM_ID = S.CAMPO_ID) AS PROTOCOLO_ID,

         CAST(S.DATA AS DATE) AS DATA,
         S.TABELA
      FROM G_SELO_LIVRO S
      WHERE CAST(S.DATA AS DATE) BETWEEN :DATA_INI AND :DATA_FIM
      AND S.SELO_SITUACAO_ID = 2
      AND S.TABELA = 'R_PEDIDO_ITEM'    --SOMENTE PROTOCOLO
      ORDER BY CAST(S.DATA AS DATE), S.DESCRICAO
  INTO :V_PROTOCOLO_ID, :DATA,  :V_TABELA DO
  BEGIN
    IF (COALESCE(:V_PROTOCOLO_ID, 0) > 0)  THEN
    BEGIN
      SELECT DATA, NUMERO_ORDEM, PEDIDO_ID
      FROM R_PROTOCOLO
      WHERE PROTOCOLO_ID = :V_PROTOCOLO_ID
      INTO :V_DATA_PROTOCOLO, :PROTOCOLO, :V_PEDIDO_ID;


      SELECT SUM(COALESCE(ITR.VALOR_EMOLUMENTO,0)), SUM(COALESCE(ITR.VALOR_TAXA_JUDICIARIA,0)),
             SUM(COALESCE(ITR.VALOR_FUNDO_RI,0)), SUM(COALESCE(ITR.VALOR_ISS,0))
      FROM R_PEDIDO_ITEM ITR WHERE ITR.PEDIDO_ID = :V_PEDIDO_ID
      INTO :VALOR_EMOLUMENTO, :VALOR_TAXA_JUDICIARIA, :VALOR_FUNDESP, :VALOR_ISS;

      --VERIFICAR SE EXISTE ALGUM DEPOSITO
      V_VALOR_PAGO = 0;
      FOR SELECT PROTOCOLO_ID, TIPO_PROTOCOLO FROM R_PROTOCOLO
          WHERE PEDIDO_ID = :V_PEDIDO_ID
          INTO :V_PROTOCOLO_ID_TEMP, :V_TIPO_PROT_TEMP DO
      BEGIN
        SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
        WHERE TIPO_SERVICO = :V_TIPO_PROT_TEMP
        AND CHAVE_SERVICO = :V_PROTOCOLO_ID_TEMP
        INTO :V_VALOR_PAGO_TEMP;

        V_VALOR_PAGO = :V_VALOR_PAGO + COALESCE(:V_VALOR_PAGO_TEMP,0);
      END

      /*SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
      WHERE ((TIPO_SERVICO = '1') OR (TIPO_SERVICO = '2'))
      AND CHAVE_SERVICO IN (SELECT PROTOCOLO_ID FROM R_PROTOCOLO WHERE PEDIDO_ID = :V_PEDIDO_ID)
      INTO :V_VALOR_PAGO;*/

      IF (COALESCE(:V_VALOR_PAGO, 0) > 0) THEN --EXISTE DEPOSITO
      BEGIN
        SELECT COUNT(*) FROM R_PROTOCOLO
        WHERE TIPO_PROTOCOLO = '2' --EXAME
        AND PEDIDO_ID = :V_PEDIDO_ID
        INTO :V_QTDE_EXAME;

        IF (COALESCE(:V_QTDE_EXAME,0) > 0) THEN
        BEGIN
          SELECT DATA
          FROM R_PROTOCOLO
          WHERE TIPO_PROTOCOLO = '2' --EXAME
          AND PEDIDO_ID = :V_PEDIDO_ID
          INTO :V_DATA_EXAME;
        END
        ELSE
        BEGIN
          V_DATA_EXAME = :V_DATA_PROTOCOLO;
        END

        --CALCULAR VALOR TOTAL
        VALOR_TOTAL = 0;
        FOR SELECT PEDIDO_ITEM_ID
            FROM R_PEDIDO_ITEM
            WHERE PEDIDO_ID = :V_PEDIDO_ID
            INTO :V_PEDIDO_ITEM_ID DO
        BEGIN
          SELECT SUM(COALESCE(S.VALOR_EMOLUMENTO,0)+COALESCE(S.VALOR_TAXA_JUDICIARIA,0)+COALESCE(S.VALOR_FUNDESP,0)+COALESCE(S.VALOR_ISS,0)) AS VALOR_TOTAL
          FROM G_SELO_LIVRO S
          WHERE CAST(S.DATA AS DATE) = :DATA
          AND S.CAMPO_ID = :V_PEDIDO_ITEM_ID
          INTO :V_VALOR_TOTAL;
  
          VALOR_TOTAL = :VALOR_TOTAL + COALESCE(:V_VALOR_TOTAL,0);
        END
        STATUS = '';
        IF (:V_DATA_PROTOCOLO = :DATA) THEN --SE DATA DO SELO = DATA DO PROTOCOLO --> CONSIDERAR DEPOSITO
        BEGIN
          V_VALOR_PAGO = 0;
          FOR SELECT PROTOCOLO_ID, TIPO_PROTOCOLO FROM R_PROTOCOLO
              WHERE PEDIDO_ID = :V_PEDIDO_ID
              INTO :V_PROTOCOLO_ID_TEMP, :V_TIPO_PROT_TEMP DO
          BEGIN
            SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
            WHERE TIPO_SERVICO = :V_TIPO_PROT_TEMP
            AND CHAVE_SERVICO = :V_PROTOCOLO_ID_TEMP
            INTO :V_VALOR_PAGO_TEMP;
    
            V_VALOR_PAGO = :V_VALOR_PAGO + COALESCE(:V_VALOR_PAGO_TEMP,0);
          END

          /*SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
          WHERE ((TIPO_SERVICO = '1') OR (TIPO_SERVICO = '2'))
          AND CHAVE_SERVICO IN (SELECT PROTOCOLO_ID FROM R_PROTOCOLO WHERE PEDIDO_ID = :V_PEDIDO_ID)
          AND CAST(DATA_PAGAMENTO AS DATE) BETWEEN :V_DATA_EXAME AND :V_DATA_PROTOCOLO
          INTO :V_VALOR_PAGO;*/
          STATUS = '';
          SELECT FIRST 1 COALESCE(CAST(S.DATA AS DATE),NULL)
           FROM G_SELO_LIVRO S, r_pedido_item RI, r_protocolo RP
            WHERE S.campo_id = RI.pedido_item_id
            AND RI.pedido_id = RP.pedido_id
            AND TABELA = 'R_PEDIDO_ITEM'
            AND RP.protocolo_id = :V_PROTOCOLO_ID_TEMP
            ORDER BY S.DATA DESC
            INTO :V_DATA_RECEITA_RI;

          if (CAST(:V_DATA_RECEITA_RI AS DATE ) <> CAST(:DATA AS DATE) ) THEN
            STATUS = 'Convertido em receita: '||(LPAD(EXTRACT(DAY FROM :V_DATA_RECEITA_RI), 2, '0') || '/' ||
                     LPAD(EXTRACT(MONTH FROM :V_DATA_RECEITA_RI), 2, '0') || '/' ||
                     LPAD(EXTRACT(YEAR FROM :V_DATA_RECEITA_RI), 4, '0'));
          ELSE
            STATUS = '';

          if (STATUS = '') then
          begin
            SELECT FIRST 1 COALESCE(CAST(ci.DATA_pagamento AS DATE),NULL)
           FROM c_caixa_item ci
           where ci.chave_servico = :V_PROTOCOLO_ID_TEMP
           and ci.tipo_transacao = 'D'
            ORDER BY ci.DATA_pagamento DESC
            INTO :V_DATA_RECEITA_RI;

          if (CAST(:V_DATA_RECEITA_RI AS DATE ) <> CAST(:DATA AS DATE) ) THEN
            STATUS = 'Devolução feita em: '||(LPAD(EXTRACT(DAY FROM :V_DATA_RECEITA_RI), 2, '0') || '/' ||
                     LPAD(EXTRACT(MONTH FROM :V_DATA_RECEITA_RI), 2, '0') || '/' ||
                     LPAD(EXTRACT(YEAR FROM :V_DATA_RECEITA_RI), 4, '0'));
          ELSE
            STATUS = '';

          end

         -- STATUS = 'CONVERTIDO EM RECEITA DATA: '||:DATA;
          TIPO_LANCAMENTO = 'D';
          VALOR_TOTAL = :V_VALOR_PAGO - :VALOR_TOTAL;
          IF (:VALOR_TOTAL < 0) THEN
          BEGIN
            VALOR_TOTAL = 0;
          END
        END
        ELSE
        BEGIN
          TIPO_LANCAMENTO = 'R';
          VALOR_TOTAL = :VALOR_TOTAL * (-1);
          STATUS = '';
        END

        DESCRICAO = 'PROTOCOLO '||CAST(:PROTOCOLO AS VARCHAR(30));
        SISTEMA_ID = 1;
  
        SUSPEND;
      END
    END
  END
   FOR SELECT DISTINCT
        (SELECT FIRST 1 PR.PROTOCOLO_ID
         FROM R_PROTOCOLO PR, R_PEDIDO_ITEM PI
         WHERE PR.PEDIDO_ID = PI.PEDIDO_ID
         AND PR.TIPO_PROTOCOLO = '1'
         AND PI.PEDIDO_ITEM_ID = S.CAMPO_ID) AS PROTOCOLO_ID,

         CAST(S.DATA AS DATE) AS DATA,
         S.TABELA
      FROM G_SELO_LIVRO_ANTIGO S
      WHERE CAST(S.DATA AS DATE) BETWEEN :DATA_INI AND :DATA_FIM
      AND S.SELO_SITUACAO_ID = 2
      AND S.TABELA = 'R_PEDIDO_ITEM'    --SOMENTE PROTOCOLO
      ORDER BY CAST(S.DATA AS DATE), S.DESCRICAO
  INTO :V_PROTOCOLO_ID, :DATA,  :V_TABELA DO
  BEGIN
    IF (COALESCE(:V_PROTOCOLO_ID, 0) > 0)  THEN
    BEGIN
      SELECT DATA, NUMERO_ORDEM, PEDIDO_ID
      FROM R_PROTOCOLO
      WHERE PROTOCOLO_ID = :V_PROTOCOLO_ID
      INTO :V_DATA_PROTOCOLO, :PROTOCOLO, :V_PEDIDO_ID;

      --VERIFICAR SE EXISTE ALGUM DEPOSITO
      V_VALOR_PAGO = 0;
      FOR SELECT PROTOCOLO_ID, TIPO_PROTOCOLO FROM R_PROTOCOLO
          WHERE PEDIDO_ID = :V_PEDIDO_ID
          INTO :V_PROTOCOLO_ID_TEMP, :V_TIPO_PROT_TEMP DO
      BEGIN
        SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
        WHERE TIPO_SERVICO = :V_TIPO_PROT_TEMP
        AND CHAVE_SERVICO = :V_PROTOCOLO_ID_TEMP
        INTO :V_VALOR_PAGO_TEMP;

        V_VALOR_PAGO = :V_VALOR_PAGO + COALESCE(:V_VALOR_PAGO_TEMP,0);
      END

      /*SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
      WHERE ((TIPO_SERVICO = '1') OR (TIPO_SERVICO = '2'))
      AND CHAVE_SERVICO IN (SELECT PROTOCOLO_ID FROM R_PROTOCOLO WHERE PEDIDO_ID = :V_PEDIDO_ID)
      INTO :V_VALOR_PAGO;*/

      IF (COALESCE(:V_VALOR_PAGO, 0) > 0) THEN --EXISTE DEPOSITO
      BEGIN
        SELECT COUNT(*) FROM R_PROTOCOLO
        WHERE TIPO_PROTOCOLO = '2' --EXAME
        AND PEDIDO_ID = :V_PEDIDO_ID
        INTO :V_QTDE_EXAME;

        IF (COALESCE(:V_QTDE_EXAME,0) > 0) THEN
        BEGIN
          SELECT DATA
          FROM R_PROTOCOLO
          WHERE TIPO_PROTOCOLO = '2' --EXAME
          AND PEDIDO_ID = :V_PEDIDO_ID
          INTO :V_DATA_EXAME;
        END
        ELSE
        BEGIN
          V_DATA_EXAME = :V_DATA_PROTOCOLO;
        END

        --CALCULAR VALOR TOTAL
        VALOR_TOTAL = 0;
        FOR SELECT PEDIDO_ITEM_ID
            FROM R_PEDIDO_ITEM
            WHERE PEDIDO_ID = :V_PEDIDO_ID
            INTO :V_PEDIDO_ITEM_ID DO
        BEGIN
          SELECT SUM(COALESCE(S.VALOR_EMOLUMENTO,0)+COALESCE(S.VALOR_TAXA_JUDICIARIA,0)+COALESCE(S.VALOR_FUNDESP,0)+COALESCE(S.VALOR_ISS,0)) AS VALOR_TOTAL
          FROM G_SELO_LIVRO_ANTIGO S
          WHERE CAST(S.DATA AS DATE) = :DATA
          AND S.CAMPO_ID = :V_PEDIDO_ITEM_ID
          INTO :V_VALOR_TOTAL;
  
          VALOR_TOTAL = :VALOR_TOTAL + COALESCE(:V_VALOR_TOTAL,0);
        END

        IF (:V_DATA_PROTOCOLO = :DATA) THEN --SE DATA DO SELO = DATA DO PROTOCOLO --> CONSIDERAR DEPOSITO
        BEGIN
          V_VALOR_PAGO = 0;
          FOR SELECT PROTOCOLO_ID, TIPO_PROTOCOLO FROM R_PROTOCOLO
              WHERE PEDIDO_ID = :V_PEDIDO_ID
              INTO :V_PROTOCOLO_ID_TEMP, :V_TIPO_PROT_TEMP DO
          BEGIN
            SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
            WHERE TIPO_SERVICO = :V_TIPO_PROT_TEMP
            AND CHAVE_SERVICO = :V_PROTOCOLO_ID_TEMP
            INTO :V_VALOR_PAGO_TEMP;
    
            V_VALOR_PAGO = :V_VALOR_PAGO + COALESCE(:V_VALOR_PAGO_TEMP,0);
          END

          /*SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
          WHERE ((TIPO_SERVICO = '1') OR (TIPO_SERVICO = '2'))
          AND CHAVE_SERVICO IN (SELECT PROTOCOLO_ID FROM R_PROTOCOLO WHERE PEDIDO_ID = :V_PEDIDO_ID)
          AND CAST(DATA_PAGAMENTO AS DATE) BETWEEN :V_DATA_EXAME AND :V_DATA_PROTOCOLO
          INTO :V_VALOR_PAGO;*/

          TIPO_LANCAMENTO = 'D';
          VALOR_TOTAL = :V_VALOR_PAGO - :VALOR_TOTAL;
          IF (:VALOR_TOTAL < 0) THEN
          BEGIN
            VALOR_TOTAL = 0;
          END
        END
        ELSE
        BEGIN
          TIPO_LANCAMENTO = 'R';
          VALOR_TOTAL = :VALOR_TOTAL * (-1);
        END

        DESCRICAO = 'PROTOCOLO '||CAST(:PROTOCOLO AS VARCHAR(30));
        SISTEMA_ID = 1;
  
        SUSPEND;
      END
    END
  END
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_GO_NEW (DATA_INI TIMESTAMP,
DATA_FIM TIMESTAMP)
RETURNS (ID INTEGER,
DATA DATAHORA,
PROTOCOLO INTEGER,
DESCRICAO VARCHAR_260,
VALOR_TOTAL DINHEIRO,
TIPO_LANCAMENTO VARCHAR_030,
SISTEMA_ID INTEGER,
MES INTEGER,
ANO INTEGER,
QTDE INTEGER,
ESPECIE_PAGAMENTO VARCHAR_003,
VALOR_RECEITA DINHEIRO,
VALOR_DESPESAS DINHEIRO,
VALOR_DEVOLUCOES DINHEIRO,
VALOR_SELOS DINHEIRO,
TIPO VARCHAR_003)
AS 
declare variable V_VALOR_INUTILIZADOS DINHEIRO;
begin
  -- Pegar todas as entradas receita e trazer o bruto
   for select 'Entrada RECEITA BRUTA ' AS descricao, sum(valor_pago), 'A' AS ESPECIE_PAGAMENTO,  'Receita Bruta' TIPO_LANCAMENTO
   from c_caixa_item where  caixa_servico_id <> 1
   and cast(data_pagamento as date)
   between :DATA_INI and :DATA_FIM
   and tipo_transacao = 'C'
   group by descricao, ESPECIE_PAGAMENTO, TIPO_LANCAMENTO
   into :DESCRICAO, :VALOR_TOTAL, ESPECIE_PAGAMENTO, TIPO_LANCAMENTO do
   begin
     VALOR_RECEITA = :VALOR_TOTAL;
    VALOR_DESPESAS = 0;
    VALOR_DEVOLUCOES  = 0;
    VALOR_SELOS  = 0;
    Tipo = 'A';
    suspend;
   end
   VALOR_DESPESAS = 0;
    -- Pegar as despesas de fundos pagos
   for select  ci.descricao, SUM(VALOR_PAGO), '' AS ESPECIE_PAGAMENTO,  'Saída- Despesas Dedutíveis' TIPO_LANCAMENTO
   from c_caixa_item ci
   left join c_caixa_servico cs
   on ci.caixa_servico_id = cs.caixa_servico_id
    where ci.tipo_transacao = 'D'
   and cs.emitir_relatorio = 'N'
   and ci.caixa_servico_id <> 1
   and cs.caixa_servico_id not in (select caixa_servico_id from
                               c_caixa_servico where descricao
                               like '%Devolu%')
   and cast(data_pagamento as date)
   between :DATA_INI and :DATA_FIM
   group by descricao, ESPECIE_PAGAMENTO, TIPO_LANCAMENTO
   into :DESCRICAO, :VALOR_TOTAL, ESPECIE_PAGAMENTO, TIPO_LANCAMENTO do
   begin
     VALOR_DESPESAS = :VALOR_TOTAL;
     VALOR_RECEITA = 0;
     VALOR_DEVOLUCOES  = 0;
     VALOR_SELOS  = 0;
     Tipo = 'B';
    suspend;
  end
   VALOR_DEVOLUCOES = 0;
  --- LISTAR DEVOLUÇÕES
   for select  ci.descricao, sum(VALOR_PAGO), '' as ESPECIE_PAGAMENTO,  'Saída-Devoluções' TIPO_LANCAMENTO
   from c_caixa_item ci
   left join c_caixa_servico cs
   on ci.caixa_servico_id = cs.caixa_servico_id
    where ci.tipo_transacao = 'D'
   --and cs.emitir_relatorio = 'N'
   and cs.caixa_servico_id in (select caixa_servico_id from
                               c_caixa_servico where descricao
                               like '%Devolu%' )
   and cs.caixa_servico_id in (select caixa_servico_id from
                               c_caixa_servico where tipo_transacao = 'D'
                               and descricao
                               like '%Diferen%' )

   and ci.caixa_servico_id <> 1
   and cast(data_pagamento as date)
   between :DATA_INI and :DATA_FIM
   group by descricao, ESPECIE_PAGAMENTO, TIPO_LANCAMENTO
   into :DESCRICAO, :VALOR_TOTAL, ESPECIE_PAGAMENTO, TIPO_LANCAMENTO do
   begin
     VALOR_DEVOLUCOES = :VALOR_TOTAL;
     VALOR_RECEITA = 0;
     VALOR_DESPESAS = 0;
     VALOR_SELOS  = 0;
     Tipo = 'C';
    suspend;
  end
   Tipo = 'D';
   -- Pegar as despesas de fundos pagos
   for select  ci.descricao, SUM(VALOR_PAGO), '' AS ESPECIE_PAGAMENTO,  'Saída- Despesas Operacionais' TIPO_LANCAMENTO
   from c_caixa_item ci
   left join c_caixa_servico cs
   on ci.caixa_servico_id = cs.caixa_servico_id
    where ci.tipo_transacao = 'D'
   and cs.emitir_relatorio = 'S'
   and ci.caixa_servico_id <> 1
   and cs.caixa_servico_id not in (13)
   and cast(data_pagamento as date)
   between :DATA_INI and :DATA_FIM
   group by descricao, ESPECIE_PAGAMENTO, TIPO_LANCAMENTO
   into :DESCRICAO, :VALOR_TOTAL, ESPECIE_PAGAMENTO, TIPO_LANCAMENTO do
   begin
     VALOR_DESPESAS = :VALOR_TOTAL;
     VALOR_RECEITA = 0;
     VALOR_DEVOLUCOES  = 0;
     VALOR_SELOS  = 0;
     Tipo = 'D';
    suspend;
  end

end ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_RI (V_DATA_INI DATE,
V_DATA_FIM DATE)
RETURNS (PEDIDO_ID INTEGER,
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
DATA_PROTOCOLO DATE,
NATUREZA VARCHAR(120) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(200) CHARACTER SET ISO8859_1,
QUANTIDADE INTEGER,
TOTAL_EMOLUMENTO NUMERIC(18, 4))
AS 
declare variable V_VALOR_EMOLUMENTO numeric(18,4);
declare variable V_QUANTIDADE numeric(18,4);
declare variable V_TIPO_COBRANCA varchar(1);
declare variable V_DESCRICAO varchar(200);
BEGIN
  TOTAL_EMOLUMENTO = 0;
  QUANTIDADE = 0;
  --SELECIONAR PROTOCOLOS
  FOR SELECT PR.PEDIDO_ID,
        PR.TIPO_PROTOCOLO,
        PR.NUMERO_ORDEM,
        CAST(PR.DATA AS DATE),       
        T.DESCRICAO,
        PE.TIPO_COBRANCA,
        (SELECT TOTAL_EMOLUMENTO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.TB_TITULO_ID = T.TB_TITULO_ID
      AND PR.TIPO_PROTOCOLO = '1' 
      AND PR.DATA BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)
                      AND CAST(:V_DATA_FIM AS TIMESTAMP)+ 0.9999
      ORDER BY PR.NUMERO_ORDEM
      INTO :PEDIDO_ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO, 
        :NATUREZA, :V_TIPO_COBRANCA, :V_VALOR_EMOLUMENTO DO
  BEGIN    
    V_DESCRICAO = 'Prot. '||:NUMERO_PROTOCOLO||' - '||:NATUREZA;
    IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
    BEGIN
      TOTAL_EMOLUMENTO = 0;
      V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
    END
    ELSE
    BEGIN
      TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;    
    END
    DESCRICAO = :V_DESCRICAO;
    SUSPEND;
  END  
  
/*  TOTAL_EMOLUMENTO = 0;
  QUANTIDADE = 0;
  --SELECIONAR PEDIDOS DE CERTIDAO  
  FOR SELECT SUM(COALESCE(PI.QUANTIDADE,0)), 
        SUM(COALESCE(PI.VALOR_EMOLUMENTO,0)), 
        N.DESCRICAO
      FROM R_PROTOCOLO PR, R_PEDIDO_ITEM PI, G_NATUREZA_TITULO N
      WHERE PR.PEDIDO_ID = PI.PEDIDO_ID
      AND PI.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID      
      AND (PR.TIPO_PROTOCOLO = '3' OR PR.TIPO_PROTOCOLO = '4')
      AND PR.DATA BETWEEN CAST(:V_DATA AS TIMESTAMP) 
                      AND CAST(:V_DATA AS TIMESTAMP)+ 0.9999 
      GROUP BY N.DESCRICAO
      INTO :QUANTIDADE, :TOTAL_EMOLUMENTO, :NATUREZA DO
  BEGIN         
    PEDIDO_ID = NULL;
    TIPO_PROTOCOLO = '3';
    NUMERO_PROTOCOLO = NULL;
    DATA_PROTOCOLO = :V_DATA;  
    V_DESCRICAO = :NATUREZA||' - Quant.: '||:QUANTIDADE;
    DESCRICAO = :V_DESCRICAO;
    SUSPEND;
  END    */
END ^

ALTER PROCEDURE C_DEPOSITO_PREVIO_VALIDAR (PLOTE INTEGER,
PDATA DATE)
AS 
declare variable VDEPPREVIOID integer;
declare variable VSELO_EMOLUMENTOS DINHEIRO;
declare variable VSELO_TAXAJUDIC DINHEIRO;
declare variable VSELO_FUNDOS DINHEIRO;
declare variable VSELO_ISS DINHEIRO;
declare variable VSELO_VALORTOTAL DINHEIRO;
declare variable VTOTAL_DEPOSITO DINHEIRO;
declare variable vLote integer;
begin

   /* Veriicando se existe deposito previo na data do servico
      caso exista, entao deduzir o valor e desabilitar o emolumento
      para que nao saia no relatorio do livro de deposito previo */
   vdepprevioid = 0;
   select d.deposito_previo_id,
          (coalesce(d.emolumentos,0) +
           coalesce(d.taxajudic,0) +
           coalesce(d.fundos,0) +
           coalesce(d.iss,0))
     from g_deposito_previo d
    where d.nlote = :plote
      and cast(d.data_lancto as date) = cast(:PDATA as date)
     into :vdepprevioid, vtotal_deposito;

   /* Deposito feito no mesmo dia localizado */
   if (coalesce(vdepprevioid,0) <> 0) then
   begin
     vSelo_emolumentos = 0;
     vSelo_taxajudic = 0;
     vSelo_fundos = 0;
     vSelo_iss = 0;

     /* Totalizando o selos do lote */
     select sum(coalesce(s.VALOR_EMOLUMENTO,0)),
            sum(coalesce(s.VALOR_TAXA_JUDICIARIA,0)),
            sum(coalesce(s.VALOR_FUNDESP,0)),
            sum(coalesce(s.VALOR_ISS,0)),
            sum(coalesce(s.VALOR_EMOLUMENTO,0) +
                coalesce(s.VALOR_TAXA_JUDICIARIA,0) +
                coalesce(s.VALOR_FUNDESP,0) +
                coalesce(s.VALOR_ISS,0))
       from G_SELO_LIVRO s
      where s.nlote = :plote
        and cast(s.data as date) = cast(:PDATA as date)
       into :vSelo_emolumentos,
            :vSelo_taxajudic,
            :vSelo_fundos,
            :vSelo_iss,
            :vSelo_valortotal;

     if (vSelo_valortotal <> 0) then
     begin

       /* retirando o selo do livro de deposito previo */
       update G_SELO_LIVRO
          set nlote = :PLOTE * -1
        where nlote = :plote
         and cast(data as date) = cast(:PDATA as date);

       vLote = PLOTE;
       if (coalesce(vSelo_valortotal,0) = coalesce(vtotal_deposito,0)) then
          vLote = PLOTE *-1;

       /* Desabilitar o deposito caso ja tenha sido usado todo o saldo no mesmo dia */
       update g_deposito_previo
          set nlote = :vLOTE,
              valor_total = (coalesce(emolumentos,0) +
                             coalesce(taxajudic,0) +
                             coalesce(fundos,0) +
                             coalesce(iss,0))
        where deposito_previo_id = :vdepprevioid
          and nlote = :PLOTE;

     end
   end
  suspend;
end ^

ALTER PROCEDURE C_DIARIO_AUXILIAR_DEPOSITO_PREVIO_DF_NEW (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (SISTEMA_ID INTEGER,
PEDIDO_ID INTEGER,
PROTOCOLO_ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
DATA_PROTOCOLO TIMESTAMP,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
DESCRICAO_DEPOSITO VARCHAR(1000) CHARACTER SET ISO8859_1,
QTDE INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2),
ORIGEM_PEDIDO VARCHAR(3) CHARACTER SET ISO8859_1,
TIPO_ORIGEM_SITE VARCHAR(3) CHARACTER SET ISO8859_1,
TIPO_LIVRO VARCHAR(50) CHARACTER SET ISO8859_1,
TOTAL_ENTRADA NUMERIC(18, 2),
TOTAL_SAIDA NUMERIC(18, 2),
PROTOCOLO_ANTERIOR INTEGER)
AS 
declare variable V_SQL varchar(3000);
declare variable V_QTDE_CONSOLIDACAO integer;
declare variable v_novo_pedido_id integer;
declare variable V_EMOLUMENTO_PERIODO_ID integer;
declare variable v_valor_compensado numeric(18,2);
DECLARE VARIABLE V_TOTAL_DEPOSITO NUMERIC(18,2);
declare variable v_total_devolvido numeric(18,2);
declare variable V_TOTAL_PEDIDO numeric(18,2);
declare variable V_PERCENTUAL_CALC numeric(18,2);
declare variable V_SERVICO_DEVOLUCAO_TJDFT varchar(10);
declare variable V_REG_AV varchar(3);
declare variable V_CAIXA_SERVICO_ID integer;
declare variable V_DEVOLUCAO_JUIZO VARCHAR(3);
BEGIN

  --ENTRADA - DEPOSITO INICIAL
  TOTAL_EMOLUMENTO = 0;
  TOTAL_FUNDO = 0;
  TOTAL_BRUTO = 0;
  QTDE = 0;
  NUMERO_ONLINE = '';
  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;
  PROTOCOLO_ANTERIOR = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    SELECT PEDIDO_ID FROM R_PROTOCOLO
    WHERE PROTOCOLO_ID = :VP_PROTOCOLO_ID
    INTO :PEDIDO_ID;

    V_SQL = ' SELECT CAST(CI.DATA_PAGAMENTO AS DATE),
                PR.NUMERO_ORDEM,
                PR.PEDIDO_ID,
                PR.PROTOCOLO_ID,
                PR.TIPO_PROTOCOLO,
                PR.DATA,
                CI.DATA_PAGAMENTO,
                EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
                EXTRACT(YEAR FROM CI.DATA_PAGAMENTO),
                COALESCE(CI.VALOR_PAGO,0), PE.NUMERO_ONLINE,
                COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
                COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||')
              FROM C_CAIXA_ITEM CI, R_PROTOCOLO PR, R_PEDIDO PE
              WHERE CI.CHAVE_SERVICO = PR.PROTOCOLO_ID
              AND PR.PEDIDO_ID = PE.PEDIDO_ID
              AND CI.tipo_servico = '||''''||'1'||''''||'
              AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
              AND CI.tipo_transacao = '||''''||'C'||''''||'
              AND PE.PEDIDO_ID = '||:PEDIDO_ID||
             ' ORDER BY 1,2';
  end
  else
  begin
    V_SQL = ' SELECT CAST(CI.DATA_PAGAMENTO AS DATE),
                PR.NUMERO_ORDEM,
                PR.PEDIDO_ID,
                PR.PROTOCOLO_ID,
                PR.TIPO_PROTOCOLO,
                PR.DATA,
                CI.DATA_PAGAMENTO,
                EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
                EXTRACT(YEAR FROM CI.DATA_PAGAMENTO),
                COALESCE(CI.VALOR_PAGO,0), PE.NUMERO_ONLINE,
                COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
                COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||')
              FROM C_CAIXA_ITEM CI, R_PROTOCOLO PR, R_PEDIDO PE
              WHERE CI.CHAVE_SERVICO = PR.PROTOCOLO_ID
              AND PR.PEDIDO_ID = PE.PEDIDO_ID
              AND CI.tipo_servico = '||''''||'1'||''''||'
              AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
              AND CI.tipo_transacao = '||''''||'C'||''''||'
              AND CAST(CI.DATA_PAGAMENTO AS DATE) BETWEEN '||''''||:V_DATA_INI||''''||' AND '||''''||:V_DATA_FIM||''''||'
              ORDER BY 1,2';
  end

  SISTEMA_ID = 1;
  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :PEDIDO_ID, :PROTOCOLO_ID, :TIPO_PROTOCOLO, :DATA_PROTOCOLO, :DATA_HORA,
           :MES, :ANO, :TOTAL_BRUTO, :NUMERO_ONLINE, :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE DO
  BEGIN
    DESCRICAO_DEPOSITO = 'Depósito inicial';
    TIPO_RETORNO = 1; --1=PRENOTACAO, DEPÓSITO PRÉVIO
    QTDE = 1;
    TIPO_LIVRO = 'ENTRADAS (DEPÓSITO PRÉVIO)';

    V_QTDE_CONSOLIDACAO = 0;
    TOTAL_ISS = 0;

    TOTAL_ENTRADA = 0;
