                                    AND TA2.TIPO = '||''''||'C'||''''||'
                                    ORDER BY A2.ANDAMENTO_ID)
              and (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') <> '||''''||'3'||''''||')
              and (select count(*) from r_pedido_item pi2, g_emolumento e2
                   where pi2.emolumento_id = e2.emolumento_id
                   and pi2.pedido_id = pe.pedido_id
                   and ((COALESCE(e2.item_df,'||''''||''''||') = '||''''||'7a'||''''||') or
                        (COALESCE(e2.item_df,'||''''||''''||') = '||''''||'7b'||''''||'))) = 0
              ORDER BY 1,2 ';
  end

  SISTEMA_ID = 1;
  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :PEDIDO_ID, :PROTOCOLO_ID, :TIPO_PROTOCOLO, DATA_HORA,
           :DATA_PROTOCOLO, :MES, :ANO, :NUMERO_ONLINE, :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE, :v_valor_compensado DO
  BEGIN
    DESCRICAO_DEPOSITO = 'Conversão em receita (25%)';
    TIPO_RETORNO = 4; --4=Conversão em receita (25%)
    TIPO_LIVRO = 'SAÍDAS';

    TOTAL_ENTRADA = 0;
    TOTAL_SAIDA = 0;

    PROTOCOLO_ANTERIOR = 0;

    SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
    WHERE CI.tipo_servico = '1' --PROTOCOLO
    AND CI.CHAVE_SERVICO = :PROTOCOLO_ID
    AND CI.tipo_transacao = 'C' --CREDITO
    AND ((CAST(CI.data_pagamento AS DATE) <= :DATA) OR (EXTRACT(MONTH FROM CAST(CI.data_pagamento AS DATE)) = EXTRACT(MONTH FROM :DATA)))
    INTO :V_TOTAL_DEPOSITO;   --VALOR BRUTO RECEBIDO

    SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
    WHERE CI.tipo_servico = '1' --PROTOCOLO
    AND CI.CHAVE_SERVICO = :PROTOCOLO_ID
    AND CI.tipo_transacao = 'D' --DÉBITO
    AND ((CAST(CI.data_pagamento AS DATE) <= :DATA) OR (EXTRACT(MONTH FROM CAST(CI.data_pagamento AS DATE)) = EXTRACT(MONTH FROM :DATA)))
    INTO :v_total_devolvido;   --VALOR devolvido

    if (coalesce(:v_total_devolvido,0) > 0) then
    begin
      V_TOTAL_DEPOSITO = coalesce(:V_TOTAL_DEPOSITO,0) - coalesce(:v_total_devolvido,0);
    end

    IF (COALESCE(:v_valor_compensado,0) > 0) THEN
    BEGIN
      V_TOTAL_DEPOSITO = COALESCE(:V_TOTAL_DEPOSITO,0) + COALESCE(:v_valor_compensado,0);
    END

    --if ((coalesce(:TIPO_ORIGEM_SITE,'') = '11') or (coalesce(:TIPO_ORIGEM_SITE,'') = '14')) then --ONR PENHORA ou ONR E-PROTOCOLO
    if (coalesce(:NUMERO_ONLINE,'') <> '') then
    begin
      TOTAL_BRUTO = :V_TOTAL_DEPOSITO;
      TOTAL_ISS = round((coalesce(total_bruto,0) * 5),2);
      TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);
      total_bruto = coalesce(:total_bruto,0) - coalesce(:total_iss,0);
      TOTAL_FUNDO = round((coalesce(total_bruto,0) * 7),2);
      TOTAL_FUNDO = round(cast((:TOTAL_FUNDO / 107) as numeric(18,5)),2);
      total_emolumento = coalesce(:total_bruto,0) - coalesce(:TOTAL_FUNDO,0);
      TOTAL_GERAL_COM_ISS = coalesce(:total_bruto,0) + coalesce(:total_iss,0);
      TOTAL_SAIDA = :total_bruto;

      if (coalesce(:TOTAL_BRUTO,0) > 0) then
      begin
        TOTAL_SAIDA = :TOTAL_BRUTO;
        SUSPEND;
      end
    end
    else
    begin
      SELECT FIRST 1 emolumento_periodo_id FROM g_emolumento_periodo ep
      WHERE :data_protocolo >= ep.data_inicial
      ORDER BY ep.data_inicial
      INTO :V_EMOLUMENTO_PERIODO_ID;

      SELECT COALESCE(TOTAL_GERAL,0),
        COALESCE(TOTAL_EMOLUMENTO,0),
        COALESCE(TOTAL_FUNDO_RI,0),
        COALESCE(TOTAL_ISS,0),
        COALESCE(QUANTIDADE_ITEM,0)
      FROM R_TOTAL_PEDIDO_DF(:PEDIDO_ID, :V_EMOLUMENTO_PERIODO_ID)
      INTO :V_TOTAL_PEDIDO, :total_emolumento, :total_fundo, :TOTAL_ISS, :qtde;

      IF (COALESCE(:V_TOTAL_DEPOSITO,0) >= (CAST((COALESCE(:V_TOTAL_PEDIDO,0)*0.25) AS NUMERIC(18,2)))) THEN --se houve deposito suficiente para cobrir os 25%
      BEGIN
        TOTAL_EMOLUMENTO = CAST((COALESCE(TOTAL_EMOLUMENTO,0) * 0.25) AS NUMERIC(18,2));
        TOTAL_FUNDO = CAST((COALESCE(TOTAL_FUNDO,0) * 0.25) AS NUMERIC(18,2));
      END
      ELSE
      BEGIN
        --calcular percentual recebido
        V_PERCENTUAL_CALC = CAST((COALESCE(:V_TOTAL_DEPOSITO,0)/COALESCE(:V_TOTAL_PEDIDO,0)) AS NUMERIC(18,2));

        TOTAL_EMOLUMENTO = CAST((COALESCE(:TOTAL_EMOLUMENTO,0) * :V_PERCENTUAL_CALC) AS NUMERIC(18,2));
        TOTAL_FUNDO = CAST((COALESCE(:TOTAL_FUNDO,0) * :V_PERCENTUAL_CALC) AS NUMERIC(18,2));
      END
      TOTAL_ISS = CAST(((COALESCE(:total_emolumento,0) + COALESCE(:total_fundo,0)) * 0.05) AS NUMERIC(18,2));

      TOTAL_BRUTO = COALESCE(:TOTAL_EMOLUMENTO,0)+COALESCE(:TOTAL_FUNDO,0);
      TOTAL_GERAL_COM_ISS = coalesce(:total_bruto,0) + coalesce(:total_iss,0);

      if (coalesce(:TOTAL_BRUTO,0) > 0) then
      begin
        TOTAL_SAIDA = :TOTAL_BRUTO;
        SUSPEND;
      end
    end
  END
  --FIM (SAIDA) Conversão em receita - Cancelamento 25% (TIPO_RETORNO 4)


  --(SAIDA) Devolução ao usuário (TIPO_RETORNO 5 ou 8) 5=Devolução ao usuário e 8=Devolução à vara de reg. públicos
  TOTAL_EMOLUMENTO = 0;
  TOTAL_FUNDO = 0;
  TOTAL_BRUTO = 0;
  QTDE = 0;
  NUMERO_ONLINE = '';
  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;

  --BUSCAR VALORES DE PARAMETROS
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_TJDFT'
  INTO :V_SERVICO_DEVOLUCAO_TJDFT;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT CAST(C.DATA_PAGAMENTO AS DATE),
                PR.NUMERO_ORDEM,
                PR.PEDIDO_ID,
                PR.PROTOCOLO_ID,
                PR.TIPO_PROTOCOLO,
                C.DATA_PAGAMENTO,
                PR.DATA,
                EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
                EXTRACT(YEAR FROM C.DATA_PAGAMENTO),
                COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
                COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
                COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
                COALESCE(C.valor_pago,0),
                TA.TIPO,
                COALESCE(C.CAIXA_SERVICO_ID,0)
              FROM R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, C_CAIXA_ITEM C
              WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
              AND PE.PEDIDO_ID = A.PEDIDO_ID
              AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
              AND C.CHAVE_SERVICO = PR.PROTOCOLO_ID
              AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
              AND ((TA.TIPO = '||''''||'C'||''''||') or (TA.TIPO = '||''''||'R'||''''||')) --Cancelados
              AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
              AND ((A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                    WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                    AND A2.PEDIDO_ID = PE.PEDIDO_ID
                    AND TA2.TIPO = '||''''||'R'||''''||'
                    ORDER BY A2.ANDAMENTO_ID)) or
                   (A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                    WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                    AND A2.PEDIDO_ID = PE.PEDIDO_ID
                    AND TA2.TIPO = '||''''||'C'||''''||'
                    ORDER BY A2.ANDAMENTO_ID)))
              and (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') <> '||''''||'3'||''''||')
              and (select count(*) from r_pedido_item pi2, g_emolumento e2
                   where pi2.emolumento_id = e2.emolumento_id
                   and pi2.pedido_id = pe.pedido_id
                   and ((COALESCE(e2.item_df,'||''''||''''||') = '||''''||'7a'||''''||') or
                        (COALESCE(e2.item_df,'||''''||''''||') = '||''''||'7b'||''''||'))) = 0
              AND (C.tipo_transacao = '||''''||'D'||''''||') --Debito
              ORDER BY 1,2 ';
  end
  else
  begin
    V_SQL = ' SELECT CAST(C.DATA_PAGAMENTO AS DATE),
                PR.NUMERO_ORDEM,
                PR.PEDIDO_ID,
                PR.PROTOCOLO_ID,
                PR.TIPO_PROTOCOLO,
                C.DATA_PAGAMENTO,
                PR.DATA,
                EXTRACT(MONTH FROM C.DATA_PAGAMENTO),
                EXTRACT(YEAR FROM C.DATA_PAGAMENTO),
                COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
                COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
                COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
                COALESCE(C.valor_pago,0),
                TA.TIPO,
                COALESCE(C.CAIXA_SERVICO_ID,0)
              FROM R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, C_CAIXA_ITEM C
              WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
              AND PE.PEDIDO_ID = A.PEDIDO_ID
              AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
              AND C.CHAVE_SERVICO = PR.PROTOCOLO_ID
              AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
              AND ((TA.TIPO = '||''''||'C'||''''||') or (TA.TIPO = '||''''||'R'||''''||')) --Cancelados
              AND CAST(C.DATA_PAGAMENTO AS DATE) BETWEEN '||''''||:V_DATA_INI||''''||' AND '||''''||:V_DATA_FIM||''''||'
              AND ((A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                    WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                    AND A2.PEDIDO_ID = PE.PEDIDO_ID
                    AND TA2.TIPO = '||''''||'R'||''''||'
                    ORDER BY A2.ANDAMENTO_ID)) or
                   (A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                    WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                    AND A2.PEDIDO_ID = PE.PEDIDO_ID
                    AND TA2.TIPO = '||''''||'C'||''''||'
                    ORDER BY A2.ANDAMENTO_ID)))
              and (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') <> '||''''||'3'||''''||')
              and (select count(*) from r_pedido_item pi2, g_emolumento e2
                   where pi2.emolumento_id = e2.emolumento_id
                   and pi2.pedido_id = pe.pedido_id
                   and ((COALESCE(e2.item_df,'||''''||''''||') = '||''''||'7a'||''''||') or
                        (COALESCE(e2.item_df,'||''''||''''||') = '||''''||'7b'||''''||'))) = 0
              AND (C.tipo_transacao = '||''''||'D'||''''||') --Debito
              ORDER BY 1,2 ';
  end

  SISTEMA_ID = 1;
  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :PEDIDO_ID, :PROTOCOLO_ID, :TIPO_PROTOCOLO, DATA_HORA,
           :DATA_PROTOCOLO, :MES, :ANO, :NUMERO_ONLINE, :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE, :v_total_devolvido, :V_REG_AV,
           :V_CAIXA_SERVICO_ID DO
  BEGIN
    TOTAL_ENTRADA = 0;
    TOTAL_SAIDA = 0;

    V_DEVOLUCAO_JUIZO = '';
    if (:V_CAIXA_SERVICO_ID > 0) then
    begin
      select coalesce(devolucao_juizo,'') from c_caixa_servico
      where caixa_servico_id = :v_caixa_servico_id
      into :V_DEVOLUCAO_JUIZO;
    end

    if ((:V_CAIXA_SERVICO_ID = :V_SERVICO_DEVOLUCAO_TJDFT ) or (:V_DEVOLUCAO_JUIZO = 'S'))  then
    begin
      TIPO_RETORNO = 8; --8=DEVOLUÇÃO À VARA DE REGISTROS PUBLICOS
      DESCRICAO_DEPOSITO = 'Devolução à Vara de Registros Públicos';
      TOTAL_GERAL_COM_ISS = COALESCE(:v_total_devolvido,0);
    end
    else
    begin
      TIPO_RETORNO = 5; --5=DEVOLUÇÃO AO USUÁRIO
      DESCRICAO_DEPOSITO = 'Devolução ao usuário';
      TOTAL_GERAL_COM_ISS = COALESCE(:v_total_devolvido,0);
    end
    TIPO_LIVRO = 'SAÍDAS';

    PROTOCOLO_ANTERIOR = 0;

    TOTAL_EMOLUMENTO = CAST(((:TOTAL_GERAL_COM_ISS * 100)/105) AS NUMERIC(18,2));
    TOTAL_ISS = COALESCE(:TOTAL_GERAL_COM_ISS,0) - COALESCE(:TOTAL_EMOLUMENTO,0);
    TOTAL_EMOLUMENTO = CAST(((:TOTAL_EMOLUMENTO * 100)/107) AS NUMERIC(18,2));
    TOTAL_FUNDO = COALESCE(:TOTAL_GERAL_COM_ISS,0) - (COALESCE(:TOTAL_EMOLUMENTO,0) + COALESCE(:TOTAL_ISS,0));

    TOTAL_BRUTO = COALESCE(:TOTAL_EMOLUMENTO,0)+COALESCE(:TOTAL_FUNDO,0);

    if (coalesce(:TOTAL_BRUTO,0) > 0) then
    begin
      TOTAL_SAIDA = :TOTAL_BRUTO;
      SUSPEND;
    end
   END
   --FIM (SAIDA) Devolução ao usuário (TIPO_RETORNO 5 e 8)
END ^

ALTER PROCEDURE C_DIARIO_AUXILIAR_DESPESA (V_DATA_INICIAL DATE,
V_DATA_FINAL DATE)
RETURNS (DESCRICAO VARCHAR(3000) CHARACTER SET ISO8859_1,
DATA_PAGAMENTO DATE,
TOTAL_DESPESA NUMERIC(18, 4),
SERVICO_CAIXA_ID INTEGER,
DESCRICAO_SERVICO VARCHAR(3000) CHARACTER SET ISO8859_1,
TIPO_DESPESA VARCHAR(10) CHARACTER SET ISO8859_1,
TOTAL_RECEITA NUMERIC(18, 4))
AS 
declare variable V_REPASSE varchar(15);
BEGIN
  FOR SELECT CI.DESCRICAO, 
        COALESCE(CI.VALOR_PAGO,0),
        CI.DATA_PAGAMENTO, CS.DESCRICAO,
        CS.REPASSE,
        CS.CAIXA_SERVICO_ID
      FROM C_CAIXA_ITEM CI, C_CAIXA_SERVICO CS
      WHERE CI.CAIXA_SERVICO_ID = CS.CAIXA_SERVICO_ID
      AND CS.TIPO_TRANSACAO = 'D'
      AND CS.EMITIR_RELATORIO = 'S'
      AND CS.SITUACAO = 'A'
      AND CI.DATA_PAGAMENTO BETWEEN CAST(:V_DATA_INICIAL AS TIMESTAMP) 
                                AND CAST(:V_DATA_FINAL AS TIMESTAMP)+ 0.9999 
      ORDER BY CI.DATA_PAGAMENTO
      INTO :DESCRICAO, :TOTAL_DESPESA, :DATA_PAGAMENTO, :DESCRICAO_SERVICO,
        :V_REPASSE, :SERVICO_CAIXA_ID DO
  BEGIN   
    IF (:V_REPASSE = 'S') THEN
    BEGIN
      TIPO_DESPESA = 'R';
    END
    ELSE
    BEGIN
      TIPO_DESPESA = 'D';
    END 
    
    SUSPEND;
  END
END ^

ALTER PROCEDURE C_DIARIO_AUXILIAR_DESPESA_DF (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1)
RETURNS (DATA_PAGAMENTO TIMESTAMP,
DATA_HORA_PAGAMENTO TIMESTAMP,
DESCRICAO_DESPESA VARCHAR(260) CHARACTER SET ISO8859_1,
TIPO_DESPESA VARCHAR(120) CHARACTER SET ISO8859_1,
TOTAL_DESPESA NUMERIC(18, 2),
QTDE INTEGER,
MES INTEGER,
ANO INTEGER,
REPASSE VARCHAR(3) CHARACTER SET ISO8859_1,
ITEM_DF VARCHAR(10) CHARACTER SET ISO8859_1,
ITEM INTEGER,
LETRA VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
declare variable V_REPETIR_DESCRICAO VARCHAR(3);
begin
  for SELECT CAST(CI.DATA_PAGAMENTO AS DATE) data_pagamento,
        CI.DATA_PAGAMENTO data_hora_pagamento,
        CI.DESCRICAO descricao_despesa,
        CS.descricao tipo_despesa,
        COALESCE(CI.VALOR_PAGO,0) total_despesa,
        CS.REPASSE,
        EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
        EXTRACT(YEAR FROM CI.DATA_PAGAMENTO),
        CS.REPETIR_DESCRICAO
      FROM C_CAIXA_ITEM CI, C_CAIXA_SERVICO CS
      WHERE CI.CAIXA_SERVICO_ID = CS.CAIXA_SERVICO_ID
      AND CS.TIPO_TRANSACAO = 'D'
      AND CS.EMITIR_RELATORIO = 'S'
      AND CS.SITUACAO = 'A'
      AND CI.DATA_PAGAMENTO BETWEEN CAST(:V_DATA_INI AS TIMESTAMP) AND CAST(:V_DATA_FIM AS TIMESTAMP) + 0.999
      ORDER BY CI.DATA_PAGAMENTO
      into :DATA_PAGAMENTO, :DATA_HORA_PAGAMENTO, :descricao_despesa, :tipo_despesa, :TOTAL_DESPESA,
           :REPASSE, :MES, :ANO, :V_REPETIR_DESCRICAO do
  begin
    if (coalesce(:repasse,'') = 'S') then
    begin
      ITEM_DF = '99r';--REPASSE
      ITEM = 99;
      LETRA = 'r';
    end
    else
    begin
      ITEM_DF = '99d';
      ITEM = 99;
      LETRA = 'd';
    end

    if (COALESCE(:V_REPETIR_DESCRICAO,'') = 'S') then
    begin
      descricao_despesa = :tipo_despesa || ' - '||:descricao_despesa;
    end
    suspend;
  end
end ^

ALTER PROCEDURE C_DIARIO_AUXILIAR_RECEITA (V_DATA_INICIAL DATE,
V_DATA_FINAL DATE,
V_RI_SOMENTE_APOS_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
V_SELOS_ANTIGO VARCHAR(1) CHARACTER SET ISO8859_1 = 'N')
RETURNS (SISTEMA_ID INTEGER,
ID INTEGER,
TIPO_PROTOCOLO VARCHAR(300) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO VARCHAR(300) CHARACTER SET ISO8859_1,
DATA_PROTOCOLO DATE,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(5000) CHARACTER SET ISO8859_1,
QUANTIDADE SMALLINT,
FUNDOS_ESTADUAIS NUMERIC(15, 3),
TAXA_JUDICIAIRA NUMERIC(15, 3),
VALOR_ISS NUMERIC(15, 3),
TOTAL_EMOLUMENTO NUMERIC(18, 4))
AS 
declare variable V_DATA_VAR VARCHAR_010;
declare variable USAR_DATA_EXPORTACAO VARCHAR_003;
declare variable V_DESCRICAO_AUX varchar(3000);
declare variable V_DATA_NOVO_ATO_PRATICADO varchar(25);
declare variable DATA_PARAMETRO date;
declare variable DATA_INICIO date;
declare variable DATA_FINAL date;
declare variable V_NOVO VARCHAR_010;
declare variable V_ANTIGO VARCHAR_010;
declare variable DATA_INICIO_NOVO date;
declare variable DATA_FIM_NOVO date;
declare variable V_SOMAFUNDO blob sub_type 0 segment size 80;
declare variable V_VALOR_EMOLUMENTO numeric(18,4);
declare variable V_VALOR_TAXA numeric(18,4);
declare variable V_QUANTIDADE numeric(18,4);
declare variable V_TIPO_COBRANCA varchar(10);
declare variable V_DESCRICAO varchar(3000);
declare variable V_SOMA_FUNDOESTADUAL VARCHAR_030;
declare variable V_PERCENTUAL_RETER_CANCELADO varchar(35);
declare variable V_PERCENTUAL integer;
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(3000);
declare variable V_SQL varchar(8000);
declare variable V_SQL2 varchar(8000);
declare variable V_COUNT integer;
declare variable SELO_SITUACAO_ID numeric(18,4);
BEGIN

  SELECT FIRST 1 CNF.VALOR
  FROM G_CONFIG CNF
  WHERE   CNF.SECAO = 'GERAL' AND
          CNF.NOME = 'DATA_NOVO_ATO_PRATICADO'
  INTO :V_DATA_NOVO_ATO_PRATICADO;

  SELECT FIRST 1 CNF.VALOR
  FROM G_CONFIG CNF
  WHERE CNF.SECAO = 'LIVRO_DIARIO_AUXILIAR' AND
        CNF.NOME = 'USAR_DATA_EXPORTACAO'
   INTO :USAR_DATA_EXPORTACAO;

    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'DATA_SELO_NOVO', 5)
  INTO :V_DATA_VAR;

  data_parametro = CAST(:V_DATA_NOVO_ATO_PRATICADO AS timestamp);

  SELECT VALOR FROM G_CONFIG WHERE NOME =  'SOMA_FUNDESP' INTO :V_SOMAFUNDO;
  SELECT VALOR FROM G_CONFIG WHERE NOME =  'SOMA_FUNDO_ESTADUAL' INTO :V_SOMA_FUNDOESTADUAL;

  --OUTRAS RECEITAS
  if ((:V_SELOS_ANTIGO = 'N') and (USAR_DATA_EXPORTACAO = 'N')) then
  begin
     TOTAL_EMOLUMENTO = 0;
      QUANTIDADE = 0;
      FOR SELECT ci.caixa_item_id,
            NULL,
            CI.CAIXA_ITEM_ID,
            CI.DATA_PAGAMENTO,
            CI.DESCRICAO,
            NULL,
            COALESCE(CI.emolumento,coalesce(ci.valor_pago,0)),
            COALESCE(CI.taxa_judiciaria,0),
            COALESCE(CI.fundo_ri,0),
            COALESCE(CI.iss,0),
            1
          FROM C_CAIXA_ITEM CI, C_CAIXA_SERVICO CS
          WHERE CI.CAIXA_SERVICO_ID = CS.CAIXA_SERVICO_ID
          AND CS.TIPO_TRANSACAO = 'C'
          AND CS.EMITIR_RELATORIO = 'S'
          AND CS.SITUACAO = 'A'
          AND (CS.SISTEMA_ID = 9)
          AND CI.DATA_PAGAMENTO BETWEEN CAST(:V_DATA_INICIAL AS TIMESTAMP)
                                    AND CAST(:V_DATA_FINAL AS TIMESTAMP)+ 0.9999
          INTO :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
            :NATUREZA, :V_TIPO_COBRANCA, :TOTAL_EMOLUMENTO, :taxa_judiciaira,
            :fundos_estaduais, :valor_iss, :quantidade DO
      BEGIN
        DESCRICAO = :NATUREZA;
        SISTEMA_ID = 999;
        SUSPEND;
      END
  end


 IF (((:V_DATA_INICIAL)  <  (CAST(:data_parametro AS timestamp))) AND
 ((:v_data_final)  > (CAST(:data_parametro AS timestamp)))) THEN
 BEGIN
   DATA_INICIO = V_DATA_INICIAL;
   DATA_FINAL  = DATA_PARAMETRO;
   DATA_INICIO_NOVO = DATA_PARAMETRO+1;
   DATA_FIM_NOVO    = V_DATA_FINAL;
   v_antigo = 'S';
   v_novo = 'S';
 end
 ELSE
 BEGIN
   if ( ((:v_data_final)  <=  (CAST(:data_parametro AS timestamp))) ) then
   begin
     DATA_INICIO = V_DATA_INICIAL;
     DATA_FINAL  = v_data_final;
     v_antigo = 'S';
     v_novo = 'N';
   end
   ELSE
   BEGIN
     DATA_INICIO_NOVO = V_DATA_INICIAL;
     DATA_FIM_NOVO    = V_DATA_FINAL;
     v_antigo = 'N';
     v_novo = 'S';
   END
 END

 IF (v_antigo = 'S') THEN
 BEGIN
  --PERCENTUAL A RETER QUANDO CANCELADO
  SELECT FIRST 1 C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO CG
  WHERE C.CONFIG_GRUPO_ID = CG.CONFIG_GRUPO_ID
  AND CG.SISTEMA_ID = 5
  AND CG.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'LIVRO_DIARIO_AUXILIAR'
  AND C.NOME = 'PERCENTUAL_RETER_CANCELADO_RI'
  INTO :V_PERCENTUAL_RETER_CANCELADO;
  IF (:V_PERCENTUAL_RETER_CANCELADO = '') THEN
  BEGIN
    V_PERCENTUAL_RETER_CANCELADO = '0';
  END
  V_PERCENTUAL = CAST(:V_PERCENTUAL_RETER_CANCELADO AS INTEGER);


  SELECT COUNT(*) FROM RDB$RELATIONS
  WHERE RDB$SYSTEM_FLAG = 0
  AND RDB$RELATION_NAME = 'R_PROTOCOLO'
  INTO :V_COUNT;

  IF (:V_COUNT > 0) THEN --SE TIVER RI
  BEGIN
    IF (:V_RI_SOMENTE_APOS_REGISTRO = 'S') THEN
    BEGIN
      --SELECIONAR PROTOCOLOS REGISTRADOS DO RI
      TOTAL_EMOLUMENTO = 0;
      taxa_judiciaira = 0;
      FUNDOS_ESTADUAIS = 0;
      QUANTIDADE = 0;
      V_SQL = ' SELECT PR.PEDIDO_ID,
            PR.TIPO_PROTOCOLO,
            PR.NUMERO_ORDEM,
            CAST(A.DATA AS DATE),
            T.DESCRICAO,
            PE.TIPO_COBRANCA,
            (SELECT TOTAL_EMOLUMENTO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
            (SELECT TOTAL_TAXA FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_TAXA, 1
          FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
          WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
          AND PE.TB_TITULO_ID = T.TB_TITULO_ID
          AND PE.PEDIDO_ID = A.PEDIDO_ID
          AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
          AND PR.TIPO_PROTOCOLO = 1
          AND TA.TIPO = '||''''||'R'||''''||'
          AND A.DATA BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP)
                         AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
          ORDER BY PR.DATA ';
      FOR EXECUTE STATEMENT :V_SQL INTO
        :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
        :NATUREZA, :V_TIPO_COBRANCA, :V_VALOR_EMOLUMENTO, :v_valor_taxa, :quantidade  DO
      BEGIN
        V_DESCRICAO = 'PROT. '|| REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA||' [REGISTRADO]';
        IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
        BEGIN
          TOTAL_EMOLUMENTO = 0;
          TAXA_JUDICIAIRA = 0;
          FUNDOS_ESTADUAIS = 0;
          V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
        END
        ELSE
        BEGIN
          FUNDOS_ESTADUAIS = (coalesce(:V_VALOR_EMOLUMENTO,0) * 0.10);
          TAXA_JUDICIAIRA = :V_VALOR_TAXA;
          TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
        END
        DESCRICAO = :V_DESCRICAO;
        SISTEMA_ID = 1;
        SUSPEND;
      END

      IF (:V_PERCENTUAL_RETER_CANCELADO > 0) THEN
      BEGIN
        taxa_judiciaira = 0;
        TOTAL_EMOLUMENTO = 0;
        FUNDOS_ESTADUAIS = 0;
        QUANTIDADE = 0;
        --SELECIONAR PROTOCOLOS CANCELADOS DO RI
        V_SQL = ' SELECT PR.PEDIDO_ID,
              PR.TIPO_PROTOCOLO,
              PR.NUMERO_ORDEM,
              CAST(A.DATA AS DATE),
              T.DESCRICAO,
              PE.TIPO_COBRANCA,
              (SELECT TOTAL_EMOLUMENTO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
              (SELECT TOTAL_TAXA FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_TAXA, 1
            FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
            WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
            AND PE.TB_TITULO_ID = T.TB_TITULO_ID
            AND PE.PEDIDO_ID = A.PEDIDO_ID
            AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
            AND PR.TIPO_PROTOCOLO = 1
            AND TA.TIPO = '||''''||'C'||''''||'
            AND A.DATA BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP)
                           AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
            ORDER BY PR.DATA ';
        FOR EXECUTE STATEMENT :V_SQL
            INTO :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
              :NATUREZA, :V_TIPO_COBRANCA, :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA, :quantidade DO
        BEGIN
          V_DESCRICAO = 'PROT. '||REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA||' [CANCELADO]';
          IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
          BEGIN
            TOTAL_EMOLUMENTO = 0;
            taxa_judiciaira = 0;
            FUNDOS_ESTADUAIS = 0;
            V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
          END
          ELSE
          BEGIN
            TAXA_JUDICIAIRA = (:v_valor_taxa * :V_PERCENTUAL)/100;
            TOTAL_EMOLUMENTO = (:V_VALOR_EMOLUMENTO * :V_PERCENTUAL)/100;
            FUNDOS_ESTADUAIS = (coalesce(:TOTAL_EMOLUMENTO,0) * 0.10);
          END
          DESCRICAO = :V_DESCRICAO;
          SISTEMA_ID = 1;
          SUSPEND;
        END
      END
    END
    ELSE
    BEGIN
      --SELECIONAR PROTOCOLOS
      TOTAL_EMOLUMENTO = 0;
      TAXA_JUDICIAIRA = 0;
      FUNDOS_ESTADUAIS = 0;
      QUANTIDADE = 0;
      V_SQL = 'SELECT PR.PEDIDO_ID,
            PR.TIPO_PROTOCOLO,
            PR.NUMERO_ORDEM,
            CAST(PR.DATA AS DATE),
            PE.TIPO_COBRANCA,
            (SELECT TOTAL_EMOLUMENTO - TOTAL_DESCONTO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
            (SELECT TOTAL_TAXA - TOTAL_DESCONTO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_TAXA, 1
          FROM R_PROTOCOLO PR, R_PEDIDO PE
          WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
          AND PR.TIPO_PROTOCOLO = 1
          AND PR.DATA BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP)
                          AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
          ORDER BY PR.DATA ';
      FOR EXECUTE STATEMENT :V_SQL
          INTO :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
            :V_TIPO_COBRANCA, :V_VALOR_EMOLUMENTO, :v_valor_taxa, :quantidade DO
      BEGIN
        V_SQL2 = 'SELECT FIRST 1 N.DESCRICAO
        FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
        WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
        AND I.PEDIDO_ID = '||:ID||'
        ORDER BY SEQUENCIA ';

        EXECUTE STATEMENT :V_SQL2
        INTO :NATUREZA;
        V_DESCRICAO = 'PROT. '||REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA;
        IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
        BEGIN
          TOTAL_EMOLUMENTO = 0;
          TAXA_JUDICIAIRA = 0;
          FUNDOS_ESTADUAIS = 0;
          V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';
        END
        ELSE
        BEGIN
          TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
          TAXA_JUDICIAIRA = :v_valor_taxa;
          FUNDOS_ESTADUAIS = (coalesce(:V_VALOR_EMOLUMENTO,0) * 0.10);
        END
        DESCRICAO = :V_DESCRICAO;
        SISTEMA_ID = 1;
        SUSPEND;
      END
    END

    --SELECIONAR PEDIDOS DE CERTIDAO DO RI
    TOTAL_EMOLUMENTO = 0;
    taxa_judiciaira = 0;
    FUNDOS_ESTADUAIS = 0;
    QUANTIDADE = 0;
    V_SQL = ' SELECT SUM(COALESCE(PI.QUANTIDADE,0)),
          SUM(COALESCE(PI.VALOR_EMOLUMENTO,0)),
          SUM(COALESCE(PI.valor_taxa_judiciaria,0)),
          N.DESCRICAO,
          CAST(PR.DATA AS DATE), 1
        FROM R_PROTOCOLO PR, R_PEDIDO_ITEM PI, G_NATUREZA_TITULO N
        WHERE PR.PEDIDO_ID = PI.PEDIDO_ID
        AND PI.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
        AND (PR.TIPO_PROTOCOLO = 3 OR PR.TIPO_PROTOCOLO = 4)
        AND PR.DATA BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP)
                       AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
        GROUP BY N.DESCRICAO, CAST(PR.DATA AS DATE) ';
    FOR EXECUTE STATEMENT :V_SQL
        INTO :QUANTIDADE, :TOTAL_EMOLUMENTO, :taxa_judiciaira, :NATUREZA, :DATA_PROTOCOLO, :quantidade DO
    BEGIN
      FUNDOS_ESTADUAIS = (coalesce(:TOTAL_EMOLUMENTO,0) * 0.10);
      V_DESCRICAO = :NATUREZA||' - QUANT.: '||:QUANTIDADE;
      DESCRICAO = :V_DESCRICAO;
      SISTEMA_ID = 1;
      SUSPEND;
    END
  END

  SELECT COUNT(*) FROM RDB$RELATIONS
  WHERE RDB$SYSTEM_FLAG = 0
  AND RDB$RELATION_NAME = 'T_ATO'
  INTO :V_COUNT;
  IF (:V_COUNT > 0) THEN --SE TIVER TABELIONATO
  BEGIN
    --SELECIONAR PROTOCOLOS REGISTRADOS DO TABELIONATO
    TOTAL_EMOLUMENTO = 0;
    taxa_judiciaira = 0;
    FUNDOS_ESTADUAIS = 0;
    QUANTIDADE = 0;
    V_SQL = ' SELECT A.ATO_ID,
               T.Descricao,
               A.PROTOCOLO,
               A.DATA_LAVRATURA,
               NULL,
               A.ATO_TIPO_ID
        FROM T_ATO A
        LEFT JOIN T_ATO_TIPO AS T ON T.ATO_TIPO_ID = A.ATO_TIPO_ID
        WHERE (A.SITUACAO_ATO IN  ('||''''||'3'||''''||','||''''||'6'||''''||','||''''||'7'||''''||','||''''||'8'||''''||','||''''||'9'||''''||'))
        AND A.ATO_TIPO_ID IS NOT NULL
        AND A.DATA_LAVRATURA BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP)
                                 AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
        ORDER BY A.PROTOCOLO';
    FOR EXECUTE STATEMENT :V_SQL
        INTO :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
          :V_TIPO_COBRANCA, :V_ATO_TIPO_ID DO
    BEGIN
      V_DESCRICAO = '';
      V_DESCRICAO2 = '';

      V_SQL2 = ' SELECT LN.DESCRICAO, TA.DESCRICAO
      FROM T_ATO_TIPO TA, T_LIVRO_NATUREZA LN
      WHERE TA.LIVRO_NATUREZA_ID = LN.LIVRO_NATUREZA_ID
      AND TA.ATO_TIPO_ID = '||:V_ATO_TIPO_ID;

      EXECUTE STATEMENT :V_SQL2
      INTO :V_DESCRICAO, :V_DESCRICAO2;
  
      IF ((:V_DESCRICAO <> '') AND (:V_DESCRICAO IS NOT NULL)) THEN
      BEGIN
        NATUREZA = :V_DESCRICAO||' ('||:V_DESCRICAO2||')';
      END
  
      TOTAL_EMOLUMENTO = 0;
      taxa_judiciaira = 0;
      V_SQL2 = ' SELECT sum(COALESCE(ROUND(EMOLUMENTO, 2),0)),
             sum(COALESCE(ROUND(taxa_judiciaria, 2),0)),
             1
             FROM T_ATO_VINCULOVALOR
             WHERE ATO_ID = '||:ID;
       EXECUTE STATEMENT :V_SQL2
       INTO :TOTAL_EMOLUMENTO, :taxa_judiciaira, :QUANTIDADE;
  
      FUNDOS_ESTADUAIS = (coalesce(:TOTAL_EMOLUMENTO,0) * 0.10);
      V_DESCRICAO = 'PROT. '||REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA;
      DESCRICAO = :V_DESCRICAO;
      SISTEMA_ID = 2;
      SUSPEND;
    END
    V_DESCRICAO = '';
    V_DESCRICAO2 = '';

    --SELECIONAR SERVIÇOS DE BALCÃO DO TABELIONATO
    V_SQL = ' SELECT  si.servico_itempedido_id,2,
     CASE ST.TIPO_ITEM
        WHEN '||''''||'R'||''''||' THEN '||''''||'RECONHECIMENTO '||''''||'
        ELSE '||''''||''''||'
     END,
     NULL,
     SP.DATA_PEDIDO,
     ST.DESCRICAO AS DESCRICAO_SERVICO,
     (SI.QTD),
     (SI.EMOLUMENTO) AS EMOLUMENTO,
     (SI.taxa_judiciaria) AS TAXA_JUDICIARIA
              FROM T_SERVICO_ITEMPEDIDO SI
                LEFT OUTER JOIN T_SERVICO_PEDIDO SP ON
                SI.SERVICO_PEDIDO_ID = SP.SERVICO_PEDIDO_ID
                LEFT OUTER JOIN T_PESSOA P ON
                SI.PESSOA_ID = P.PESSOA_ID
                LEFT OUTER JOIN T_SERVICO_TIPO ST ON
                SI.SERVICO_TIPO_ID = ST.SERVICO_TIPO_ID
              WHERE SP.DATA_PEDIDO BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP)
                     AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
                AND SI.SITUACAO = '||''''||'F'||'''';
     FOR EXECUTE STATEMENT :V_SQL
     INTO :id,  :SISTEMA_ID, :V_DESCRICAO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
          :DESCRICAO, :QUANTIDADE, :TOTAL_EMOLUMENTO, :taxa_judiciaira DO

    BEGIN
      --DESCRICAO =trim(:DESCRICAO);--|| :DESCRICAO || ' - QUANT.: ' || :QUANTIDADE);
      FUNDOS_ESTADUAIS = (coalesce((:TOTAL_EMOLUMENTO*:quantidade),0) * 0.10);
      natureza = 'Balcão';
      SUSPEND;
    END
  END

  SELECT COUNT(*) FROM RDB$RELATIONS
  WHERE RDB$SYSTEM_FLAG = 0
  AND RDB$RELATION_NAME = 'D_DOCUMENTO'
  INTO :V_COUNT;
  IF (:V_COUNT > 0) THEN --SE TIVER RTD
  BEGIN
    --SELECIONAR PROTOCOLOS REGISTRADOS DO RTD
    TOTAL_EMOLUMENTO = 0;
    QUANTIDADE = 0;
    FUNDOS_ESTADUAIS = 0;
    V_SQL = ' SELECT D.DOCUMENTO_ID,'||''''||'RTD'||''''||',
          D.PROTOCOLO,
          D.DATA_REGISTRO,
          TD.DESCRICAO,
          NULL,
          COALESCE(D.VALOR_CUSTAS,0),
          COALESCE(D.taxa_judiciaria,0), 1
        FROM D_DOCUMENTO D, D_TIPO_DOCUMENTO TD
        WHERE D.TIPO_DOCUMENTO_ID = TD.TIPO_DOCUMENTO_ID
        AND D.DATA_REGISTRO BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP)
                                AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
     UNION
       SELECT C.CERTIDAO_ID,'||''''||'RTD'||''''||',
              C.CERTIDAO_ID,
              C.DATA_PEDIDO,
              C.DESCRICAO,
              NULL,
              COALESCE(C.VALOR_EMOLUMENTO, 0),
              COALESCE(C.valor_taxa, 0), 1
                FROM D_CERTIDAO C
                WHERE C.DATA_PEDIDO BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP)
                                AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999 ';
    FOR EXECUTE STATEMENT :V_SQL
        INTO :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
          :NATUREZA, :V_TIPO_COBRANCA, :TOTAL_EMOLUMENTO, :taxa_judiciaira, :quantidade DO
    BEGIN
      FUNDOS_ESTADUAIS = (coalesce(:TOTAL_EMOLUMENTO,0) * 0.10);
      V_DESCRICAO = 'PROT. '|| REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA;
      DESCRICAO = :V_DESCRICAO;
      SISTEMA_ID = 7;
      SUSPEND;
    END
  END

  SELECT COUNT(*) FROM RDB$RELATIONS
  WHERE RDB$SYSTEM_FLAG = 0
  AND RDB$RELATION_NAME = 'V_SERVICO_REALIZADO'
  INTO :V_COUNT;
  IF (:V_COUNT > 0) THEN --SE TIVER CIVIL
  BEGIN
    --SELECIONAR PROTOCOLOS REGISTRADOS DO CIVIL
    TOTAL_EMOLUMENTO = 0;
    taxa_judiciaira = 0;
    FUNDOS_ESTADUAIS = 0;
    QUANTIDADE = 0;
    V_SQL = ' SELECT SR.SERVICO_REALIZADO_ID,'||''''||'CIVIL'||''''||',
          SR.NUMERO_SERIE,
          SR.DATA_ATO,
          ST.DESCRICAO,
          NULL,
          COALESCE(SR.EMOLUMENTO,0),
          COALESCE(SR.taxa_judiciaria,0),
          1
        FROM V_SERVICO_REALIZADO SR, V_SERVICO_TIPO ST
        WHERE SR.SERVICO_TIPO_ID = ST.SERVICO_TIPO_ID
        AND ST.ATO_PRATICADO = '||''''||'S'||''''||'
        AND SR.SITUACAO = '||''''||'4'||''''||'
        AND SR.DATA_ATO BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP)
                            AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
        ORDER BY SR.NUMERO_SERIE ';
    FOR EXECUTE STATEMENT :V_SQL
        INTO :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
          :NATUREZA, :V_TIPO_COBRANCA, :TOTAL_EMOLUMENTO, :taxa_judiciaira,:quantidade DO
    BEGIN
      FUNDOS_ESTADUAIS = 0;--(coalesce(:TOTAL_EMOLUMENTO,0) * 0.10);
      V_DESCRICAO = :NATUREZA;
      DESCRICAO = :V_DESCRICAO;
      SISTEMA_ID = 12;
      SUSPEND;
    END
  END

  SELECT COUNT(*) FROM RDB$RELATIONS
  WHERE RDB$SYSTEM_FLAG = 0
  AND RDB$RELATION_NAME = 'P_TITULO'
  INTO :V_COUNT;
  IF (:V_COUNT > 0) THEN --SE TIVER PROTESTO
  BEGIN
  --SELECIONAR PROTOCOLOS REGISTRADOS DO PROTESTO
          --APONTAMENTOS DO PROTESTO:

                  TOTAL_EMOLUMENTO = 0;
                  taxa_judiciaira = 0;
                  FUNDOS_ESTADUAIS = 0;
                  QUANTIDADE = 0;

                  V_SQL = ' SELECT  T.TITULO_ID,'||''''||'PROTESTO'||''''||',
                              T.NUMERO_APONTAMENTO,
                              T.DATA_APONTAMENTO,
                              E.DESCRICAO,
                              NULL,
                              COALESCE(T.VALOR_EMOLUMENTO,0) + COALESCE(T.VALOR_TAXA_INTIMACAO,0),
                              COALESCE(T.valor_taxa_judiciaria,0), 1
                  FROM P_TITULO T, P_ESPECIE E
                  WHERE E.ESPECIE_ID = T.ESPECIE_ID AND
                        T.DATA_APONTAMENTO BETWEEN  CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP) AND
                                                    CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
                  ORDER BY T.TITULO_ID ';

                  FOR EXECUTE STATEMENT :V_SQL
                  INTO
                    :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
                    :NATUREZA, :V_TIPO_COBRANCA, :TOTAL_EMOLUMENTO, :taxa_judiciaira, :quantidade DO
                  BEGIN
                    FUNDOS_ESTADUAIS = (coalesce(:TOTAL_EMOLUMENTO,0) * 0.10);
                    V_DESCRICAO = 'APONTAMENTO '||REPLACE(:NUMERO_PROTOCOLO, '.00','') ||' - '||:NATUREZA;
                    DESCRICAO = :V_DESCRICAO;
                    SISTEMA_ID = 13;
                    SUSPEND;
                  END

          --AVERBAÇÕES (CANCELAMENTOS, PAGAMENTOS OU DESISTÊNCIAS)

                  V_SQL = ' SELECT T.TITULO_ID,'||''''||'PROTESTO'||''''||',
                             T.NUMERO_APONTAMENTO,
                             T.DATA_PAGO,
                             E.DESCRICAO,
                             NULL,
                             COALESCE(T.VALOR_TAXA_AVERB, 0) + COALESCE(T.VALOR_TAXA_CANCEL, 0), 1
                      FROM P_TITULO T
                      LEFT JOIN P_ESPECIE E  ON E.ESPECIE_ID  = T.ESPECIE_ID
                        WHERE E.ESPECIE_ID = T.ESPECIE_ID
                          AND T.DATA_PAGO BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP) AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999 AND T.VALOR_TAXA_AVERB > 0
                      UNION
                      SELECT T.TITULO_ID,'||''''||'PROTESTO'||''''||',
                             T.NUMERO_APONTAMENTO,
                             T.DATA_CANCELAMENTO,
                             E.DESCRICAO,
                             NULL,
                             COALESCE(T.VALOR_TAXA_AVERB, 0) + COALESCE(T.VALOR_TAXA_CANCEL, 0), 1
                      FROM P_TITULO T
                      LEFT JOIN P_ESPECIE E  ON E.ESPECIE_ID  = T.ESPECIE_ID
                        WHERE E.ESPECIE_ID = T.ESPECIE_ID
                          AND T.DATA_CANCELAMENTO BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP) AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999 ';
                  FOR EXECUTE STATEMENT :V_SQL
                  INTO
                    :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
                    :NATUREZA, :V_TIPO_COBRANCA, :TOTAL_EMOLUMENTO, :quantidade  DO
                  BEGIN
                    taxa_judiciaira = 0;
                    FUNDOS_ESTADUAIS = 0;
                    V_DESCRICAO = 'AVERBAÇÃO '||REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA;
                    DESCRICAO = :V_DESCRICAO;
                    SISTEMA_ID = 13;
                    SUSPEND;
                  END

          --CERTIDÕES
      V_SQL = ' SELECT
         C.CERTIDAO_ID,
         '||''''||'PROTESTO'||''''||',
         C.CERTIDAO_ID,
         DATA_CERTIDAO,
         CASE TIPO_CERTIDAO
            WHEN '||''''||'P'||''''||' THEN '||''''||'CERTIDÃO POSITIVA'||''''||'
            WHEN '||''''||'N'||''''||' THEN '||''''||'CERTIDÃO NEGATIVA'||''''||'
            WHEN '||''''||'R'||''''||' THEN '||''''||'CERTIDÃO RELAÇÃO'||''''||'
            WHEN '||''''||'T'||''''||' THEN '||''''||'CERTIDÃO TRASLADO'||''''||'
         END,
         NULL,
         COALESCE(VALOR_EMOLUMENTO,0) + COALESCE(VALOR_TAXA_EXTRA, 0),
         COALESCE(valor_taxa_judiciaria,0), 1
      FROM P_CERTIDAO C
      WHERE
            C.DATA_CERTIDAO BETWEEN CAST('||''''||:DATA_INICIO||''''||' AS TIMESTAMP)
            AND CAST('||''''||:DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999
      ORDER BY C.CERTIDAO_ID ';
      FOR EXECUTE STATEMENT :V_SQL
      INTO
        :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA_PROTOCOLO,
        :NATUREZA, :V_TIPO_COBRANCA, :TOTAL_EMOLUMENTO, :taxa_judiciaira, :quantidade  DO
      BEGIN
        FUNDOS_ESTADUAIS = (coalesce(:TOTAL_EMOLUMENTO,0) * 0.10);
        V_DESCRICAO = 'CERTIDÃO: '||REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA;
        DESCRICAO = :V_DESCRICAO;
        SISTEMA_ID = 13;
        SUSPEND;
      END
     END
  END
  if (v_novo = 'S') then
  BEGIN
    V_SQL = ' SELECT S.TABELA, 1, 1, 1,
             CASE POSITION(''*'', S.DESCRICAO) WHEN 0 THEN COALESCE(S.DESCRICAO,G.DESCRICAO)
             ELSE SUBSTRING(S.DESCRICAO FROM 1 FOR POSITION(''*'', S.DESCRICAO)-1)
             END AS DESCRICAO , NULL , ';
    if  (USAR_DATA_EXPORTACAO = 'S') then
        BEGIN
          if (V_SELOS_ANTIGO = 'S') then
          BEGIN
            V_SQL = V_SQL || ' cast(S.DATA as date) DATA_EXPORTACAO, ';
          END
          ELSE
          BEGIN
            V_SQL = V_SQL || ' cast(S.DATA as date) DATA_EXPORTACAO, ';
          END
        END
        ELSE
        BEGIN
          V_SQL = V_SQL || ' cast(S.DATA as date) DATA_EXPORTACAO, ';
        END
    IF ((V_SOMAFUNDO = 'N') AND CAST(:DATA_INICIO_NOVO AS DATE) < '2016/03/28') THEN
      V_SQL = V_SQL || '(S.VALOR_EMOLUMENTO-S.VALOR_FUNDESP) AS VALOR_EMOLUMENT,';
    ELSE
    begin
      IF ((V_SOMAFUNDO = 'S') AND CAST(:DATA_INICIO_NOVO AS DATE) < '2016/03/28') THEN
         V_SQL = V_SQL || 'ROUND(COALESCE(S.VALOR_EMOLUMENTO,0),2) AS VALOR_EMOLUMENT,';
      else
      begin
        IF (V_SOMA_FUNDOESTADUAL = 'S') THEN
          V_SQL = V_SQL || 'ROUND(COALESCE(S.VALOR_TOTAL,0),2) AS VALOR_EMOLUMENT,';
        else
          V_SQL = V_SQL || 'ROUND(COALESCE(S.VALOR_EMOLUMENTO,0),2) AS VALOR_EMOLUMENT,';
      end
    end
    V_SQL = V_SQL || 'CASE TIPO_CARTORIO WHEN 1 THEN 2 WHEN 2 THEN 1 WHEN 3 THEN 12 WHEN 4 THEN 7 WHEN 5 THEN 13 END AS SISTEMA_ID,
        S.VALOR_FUNDESP,S.VALOR_TAXA_JUDICIARIA,S.VALOR_ISS, s.selo_situacao_id, g.descricao_completa ';
    if (V_SELOS_ANTIGO = 'S') then
    begin
        V_SQL = V_SQL || ' FROM G_SELO_LIVRO_ANTIGO  S
        LEFT JOIN  G_SELO_LOTE_ANTIGO AS L ';
    end
    else
    begin
        V_SQL = V_SQL || ' FROM G_SELO_LIVRO  S
        LEFT JOIN  G_SELO_LOTE AS L ';
    end
        V_SQL = V_SQL ||  ' ON L.SELO_LOTE_ID = S.SELO_LOTE_ID
        LEFT JOIN  G_SELO_GRUPO G
        ON G.SELO_GRUPO_ID = L.SELO_GRUPO_ID
        WHERE S.SELO_SITUACAO_ID IN(2) ';

        if  (USAR_DATA_EXPORTACAO = 'S') then
        BEGIN
          if (V_SELOS_ANTIGO = 'S') then
          begin
            V_SQL = V_SQL || ' and s.DATA BETWEEN CAST('||''''||:DATA_INICIO_NOVO||''''||' AS TIMESTAMP)
                    and cast('||''''||:DATA_FIM_NOVO||''''||' as timestamp) + 0.9999 ';
          end
          else
          begin
            V_SQL = V_SQL || ' and s.DATA BETWEEN CAST('||''''||:DATA_INICIO_NOVO||''''||' AS TIMESTAMP)
                    and cast('||''''||:DATA_FIM_NOVO||''''||' as timestamp) + 0.9999 ';
          end
        END
        ELSE
        BEGIN
          V_SQL = V_SQL || ' and S.DATA BETWEEN CAST('||''''||:DATA_INICIO_NOVO||''''||' AS TIMESTAMP)
           and cast('||''''||:DATA_FIM_NOVO||''''||' as timestamp) + 0.9999 ';
        END


    FOR EXECUTE STATEMENT :V_SQL INTO
      :NATUREZA, :quantidade , :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO,
      :V_DESCRICAO, :V_TIPO_COBRANCA,:DATA_PROTOCOLO, :TOTAL_EMOLUMENTO, :sistema_id,:FUNDOS_ESTADUAIS,:TAXA_JUDICIAIRA,:VALOR_ISS,
      :selo_situacao_id, :v_descricao_aux DO
    BEGIN
      --V_DESCRICAO = :NATUREZA;--' '||REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA;
      DESCRICAO = :V_DESCRICAO;
      if (TRIM(COALESCE(DESCRICAO,'')) = '') then
        DESCRICAO = :v_descricao_aux;
      if ((coalesce(SELO_SITUACAO_ID, 0) = 4) )then
      begin
        TOTAL_EMOLUMENTO = 0;
        TAXA_JUDICIAIRA = 0;
        FUNDOS_ESTADUAIS = 0;
        VALOR_ISS = 0;
      end
      SUSPEND;
    END
  END
END ^

ALTER PROCEDURE C_DIARIO_AUXILIAR_RECEITA_DF (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_TIPO_PROTOCOLO VARCHAR(3) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (SISTEMA_ID INTEGER,
PEDIDO_ID INTEGER,
PROTOCOLO_ID INTEGER,
DATA_ANDAMENTO TIMESTAMP,
DATA_HORA_ANDAMENTO TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
DATA_PROTOCOLO TIMESTAMP,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
NATUREZA_TITULO_ID INTEGER,
DESCRICAO_NATUREZA VARCHAR(260) CHARACTER SET ISO8859_1,
EMOLUMENTO_ID INTEGER,
DESCRICAO_EMOLUMENTO VARCHAR(260) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
QTDE INTEGER,
MES INTEGER,
ANO INTEGER,
ITEM_DF VARCHAR(10) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2),
ORIGEM_PEDIDO VARCHAR(3) CHARACTER SET ISO8859_1,
TIPO_ORIGEM_SITE VARCHAR(3) CHARACTER SET ISO8859_1,
TIPO_COBRANCA VARCHAR(3) CHARACTER SET ISO8859_1,
REGISTRADO_CANCELADO VARCHAR(3) CHARACTER SET ISO8859_1,
ITEM INTEGER,
LETRA VARCHAR(10) CHARACTER SET ISO8859_1,
QTDE_FOLHA INTEGER)
AS 
DECLARE VARIABLE V_SQL VARCHAR(3000);
DECLARE VARIABLE V_VALOR_COMPENSADO_ENTRADA NUMERIC(18,2);
DECLARE VARIABLE V_TOTAL_PEDIDO NUMERIC(18,2);
DECLARE VARIABLE V_TOTAL_DEPOSITO NUMERIC(18,2);
DECLARE VARIABLE v_total_devolvido NUMERIC(18,2);
DECLARE VARIABLE V_EMOLUMENTO_PERIODO_ID VARCHAR(10);
DECLARE VARIABLE V_PERCENTUAL_CALC NUMERIC(18,2);
DECLARE VARIABLE V_QUANTIDADE_ITEM INTEGER;

DECLARE VARIABLE V_TOTAL_EMOLUMENTO_FOLHA NUMERIC(18,2);
DECLARE VARIABLE V_TOTAL_FUNDO_FOLHA NUMERIC(18,2);
DECLARE VARIABLE V_TOTAL_ISS_FOLHA NUMERIC(18,2);
declare variable v_item varchar(10);
declare variable v_pedido_item_id integer;
BEGIN
  SISTEMA_ID = 1;

  --PROTOCOLOS REGISTRADOS ou CANCELADOS
  IF ((COALESCE(:VP_TIPO_PROTOCOLO,'') = 'T') OR (COALESCE(:VP_TIPO_PROTOCOLO,'') = '1')) THEN
  BEGIN
    TOTAL_EMOLUMENTO = 0;
    TOTAL_FUNDO = 0;
    QTDE = 0;
    TOTAL_BRUTO = 0;

    TOTAL_ISS = 0;
    TOTAL_GERAL_COM_ISS = 0;

    NUMERO_ONLINE = '';
    natureza_titulo_id = 0;
    descricao_natureza = '';
    emolumento_id = 0;
    descricao_emolumento = '';
    REGISTRADO_CANCELADO = '';
    qtde_folha = 0;

    IF (COALESCE(:VP_PROTOCOLO_ID,0) > 0) THEN
    BEGIN
      V_SQL = ' SELECT CAST(A.DATA AS DATE),
          e.item_df,
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          COALESCE(PE.TIPO_COBRANCA,'||''''||''''||'),
          A.DATA,
          COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM A.DATA),
          EXTRACT(YEAR FROM A.DATA),
          PR.PROTOCOLO_ID,
          cast(pr.data as date),
          COALESCE(PE.VALOR_COMPENSADO,0),
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          coalesce(PI.QUANTIDADE,0), coalesce(PI.valor_emolumento,0), coalesce(PI.valor_fundo_ri,0), NT.descricao,
          coalesce(PI.valor_iss,0), nt.natureza_titulo_id, e.emolumento_id, e.descricao, ta.tipo
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, G_EMOLUMENTO E, g_natureza_titulo NT
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND PE.PEDIDO_ID = PI.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PI.EMOLUMENTO_ID = E.EMOLUMENTO_ID
        and pi.natureza_titulo_id = nt.natureza_titulo_id
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
        AND ((COALESCE(TA.TIPO,'||''''||''''||') = '||''''||'R'||''''||') or (COALESCE(TA.TIPO,'||''''||''''||') = '||''''||'C'||''''||'))
        AND ((A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
              AND A2.PEDIDO_ID = PE.PEDIDO_ID
              AND TA2.TIPO = '||''''||'R'||''''||'
              ORDER BY A2.ANDAMENTO_ID)) or
             (A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
              AND A2.PEDIDO_ID = PE.PEDIDO_ID
              AND TA2.TIPO = '||''''||'C'||''''||'
              ORDER BY A2.ANDAMENTO_ID)))
        and (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') <> '||''''||'3'||''''||')
        and (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') <> '||''''||'11'||''''||')
        and (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') <> '||''''||'14'||''''||')
        and (COALESCE(e.item_df,'||''''||''''||') <> '||''''||'7a'||''''||')
        and (COALESCE(e.item_df,'||''''||''''||') <> '||''''||'7b'||''''||')
        and (COALESCE(NT.CONSOLIDACAO,'||''''||''''||') <> '||''''||'S'||''''||')
        ORDER BY 1,2,3 ';
    END
    ELSE
    BEGIN
      V_SQL = ' SELECT CAST(A.DATA AS DATE),
          e.item_df,
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          COALESCE(PE.TIPO_COBRANCA,'||''''||''''||'),
          A.DATA,
          COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM A.DATA),
          EXTRACT(YEAR FROM A.DATA),
          PR.PROTOCOLO_ID,
          cast(pr.data as date),
          COALESCE(PE.VALOR_COMPENSADO,0),
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          coalesce(PI.QUANTIDADE,0), coalesce(PI.valor_emolumento,0), coalesce(PI.valor_fundo_ri,0), NT.descricao,
          coalesce(PI.valor_iss,0), nt.natureza_titulo_id, e.emolumento_id, e.descricao, ta.tipo
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, G_EMOLUMENTO E, g_natureza_titulo NT
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND PE.PEDIDO_ID = PI.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PI.EMOLUMENTO_ID = E.EMOLUMENTO_ID
        and pi.natureza_titulo_id = nt.natureza_titulo_id
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND A.DATA BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
        AND ((COALESCE(TA.TIPO,'||''''||''''||') = '||''''||'R'||''''||') or (COALESCE(TA.TIPO,'||''''||''''||') = '||''''||'C'||''''||'))
        AND ((A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
              AND A2.PEDIDO_ID = PE.PEDIDO_ID
              AND TA2.TIPO = '||''''||'R'||''''||'
              ORDER BY A2.ANDAMENTO_ID)) or
             (A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
              AND A2.PEDIDO_ID = PE.PEDIDO_ID
              AND TA2.TIPO = '||''''||'C'||''''||'
              ORDER BY A2.ANDAMENTO_ID)))
        and (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') <> '||''''||'3'||''''||')
        and (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') <> '||''''||'11'||''''||')
        and (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') <> '||''''||'14'||''''||')
        and (COALESCE(e.item_df,'||''''||''''||') <> '||''''||'7a'||''''||')
        and (COALESCE(e.item_df,'||''''||''''||') <> '||''''||'7b'||''''||')
        and (COALESCE(NT.CONSOLIDACAO,'||''''||''''||') <> '||''''||'S'||''''||')
        ORDER BY 1,2,3 ';
    END
  
    FOR EXECUTE STATEMENT V_SQL
        INTO :DATA_ANDAMENTO, :item_df, :NUMERO_PROTOCOLO, :PEDIDO_ID, :TIPO_PROTOCOLO, :TIPO_COBRANCA, :DATA_HORA_ANDAMENTO, :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE,
          :MES, :ANO, :PROTOCOLO_ID, :DATA_PROTOCOLO, :V_VALOR_COMPENSADO_ENTRADA, :NUMERO_ONLINE, :QTDE, :TOTAL_EMOLUMENTO, :TOTAL_FUNDO,
          :descricao_natureza, :total_iss, :natureza_titulo_id, :emolumento_id, :descricao_emolumento, :registrado_cancelado DO
    BEGIN
      V_TOTAL_PEDIDO = 0;
      V_QUANTIDADE_ITEM = 0;
  
      IF ((COALESCE(registrado_cancelado,'') <> 'C') AND (COALESCE(registrado_cancelado,'') <> 'R')) THEN
      BEGIN
        registrado_cancelado = '';
      END
  
      IF (COALESCE(registrado_cancelado,'') = 'C') THEN
      BEGIN
        IF ((:item_df = '1') OR (:item_df = '3a') OR (:item_df = '3b') OR (:item_df = '4') OR (:item_df = '5a') OR (:item_df = '5b') OR (:item_df = '5c') OR (:item_df = '6')) THEN
        BEGIN
          item_df = '99a'; --cancelamento de registro
        END
        ELSE IF ((:item_df = '2a') OR (:item_df = '2b') OR (:item_df = '7a') OR (:item_df = '7b') OR (:item_df = '7c') OR (:item_df = '8a') OR (:item_df = '8b')) THEN
        BEGIN
          item_df = '99b'; --cancelamento de averbação
        END
        ELSE
        BEGIN
          item_df = '99c'; --cancelamento outros
        END
      END

      select item, letra from C_RETORNA_ITEM_LETRA_DF(:item_df)
      into :item, :letra;

  
      IF (COALESCE(:TIPO_COBRANCA,'') = '1') THEN --se for ISENTO
      BEGIN
        TOTAL_EMOLUMENTO = 0;
        TOTAL_FUNDO = 0;
        TOTAL_BRUTO = 0;
      
        TOTAL_ISS = 0;
        TOTAL_GERAL_COM_ISS = 0;
  
        --SUSPEND;
      END
      ELSE
      BEGIN
        IF (COALESCE(registrado_cancelado,'') = 'C') THEN
        BEGIN
          SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
          WHERE CI.tipo_servico = '1' --PROTOCOLO
          AND CI.CHAVE_SERVICO = :PROTOCOLO_ID
          AND CI.tipo_transacao = 'C' --CREDITO
          AND ((CAST(CI.data_pagamento AS DATE) <= :data_andamento) OR (EXTRACT(MONTH FROM CAST(CI.data_pagamento AS DATE)) = EXTRACT(MONTH FROM :data_andamento)))
          INTO :V_TOTAL_DEPOSITO;   --VALOR BRUTO RECEBIDO
  
          SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
          WHERE CI.tipo_servico = '1' --PROTOCOLO
          AND CI.CHAVE_SERVICO = :PROTOCOLO_ID
          AND CI.tipo_transacao = 'D' --CREDITO
          AND ((CAST(CI.data_pagamento AS DATE) <= :data_andamento) OR (EXTRACT(MONTH FROM CAST(CI.data_pagamento AS DATE)) = EXTRACT(MONTH FROM :data_andamento)))
          INTO :v_total_devolvido;   --VALOR devolvido
  
          IF (COALESCE(:v_total_devolvido,0) > 0) THEN
          BEGIN
            V_TOTAL_DEPOSITO = COALESCE(:V_TOTAL_DEPOSITO,0) - COALESCE(:v_total_devolvido,0);
          END
  
          IF (COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) > 0) THEN
          BEGIN
            V_TOTAL_DEPOSITO = COALESCE(:V_TOTAL_DEPOSITO,0) + COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0);
          END

          SELECT FIRST 1 emolumento_periodo_id FROM g_emolumento_periodo ep
          WHERE :data_protocolo >= ep.data_inicial
          ORDER BY ep.data_inicial
          INTO :V_EMOLUMENTO_PERIODO_ID;
  
          SELECT COALESCE(TOTAL_GERAL,0), COALESCE(QUANTIDADE_ITEM,0)
          FROM R_TOTAL_PEDIDO_DF(:PEDIDO_ID, :V_EMOLUMENTO_PERIODO_ID)
          INTO :V_TOTAL_PEDIDO, :V_QUANTIDADE_ITEM;
  
          if (coalesce(:NUMERO_ONLINE,'') <> '') then
          begin
            TOTAL_EMOLUMENTO = CAST(((:V_TOTAL_DEPOSITO * 100)/107) AS NUMERIC(18,2));
            TOTAL_FUNDO = COALESCE(:V_TOTAL_DEPOSITO,0) - COALESCE(:TOTAL_EMOLUMENTO,0);
          end
          else if (COALESCE(:V_TOTAL_DEPOSITO,0) >= (CAST((COALESCE(:V_TOTAL_PEDIDO,0)*0.25) AS NUMERIC(18,2)))) THEN --se houve deposito suficiente para cobrir os 25%
          BEGIN
            TOTAL_EMOLUMENTO = CAST((COALESCE(TOTAL_EMOLUMENTO,0) * 0.25) AS NUMERIC(18,2));
            TOTAL_FUNDO = CAST((COALESCE(TOTAL_FUNDO,0) * 0.25) AS NUMERIC(18,2));
          END
          ELSE
          BEGIN
            IF (:V_QUANTIDADE_ITEM = 1) THEN
            BEGIN
              TOTAL_EMOLUMENTO = CAST(((:V_TOTAL_DEPOSITO * 100)/107) AS NUMERIC(18,2));
              TOTAL_FUNDO = COALESCE(:V_TOTAL_DEPOSITO,0) - COALESCE(:TOTAL_EMOLUMENTO,0);
            END
            ELSE
            BEGIN
              --calcular percentual recebido
              V_PERCENTUAL_CALC = CAST((COALESCE(:V_TOTAL_DEPOSITO,0)/COALESCE(:V_TOTAL_PEDIDO,0)) AS NUMERIC(18,2));

              TOTAL_EMOLUMENTO = CAST((COALESCE(:TOTAL_EMOLUMENTO,0) * :V_PERCENTUAL_CALC) AS NUMERIC(18,2));
              TOTAL_FUNDO = CAST((COALESCE(:TOTAL_FUNDO,0) * :V_PERCENTUAL_CALC) AS NUMERIC(18,2));
            END
          END
          TOTAL_ISS = CAST(((COALESCE(:total_emolumento,0) + COALESCE(:total_fundo,0)) * 0.05) AS NUMERIC(18,2));
        end

        TOTAL_BRUTO = COALESCE(:TOTAL_EMOLUMENTO,0) + COALESCE(:TOTAL_FUNDO,0);
        TOTAL_GERAL_COM_ISS = :TOTAL_BRUTO + :TOTAL_ISS;
  
        IF (COALESCE(:TOTAL_BRUTO,0) > 0) THEN
        BEGIN
          SUSPEND;
        END
      END
    END
  end
  --FIM SELECIONAR PROTOCOLOS REGISTRADOS/CANCELADOS


  --PROTOCOLOS CANCELADOS de ONR-Penhora e ONR-E-PROTOCOLO
  IF ((COALESCE(:VP_TIPO_PROTOCOLO,'') = 'T') OR (COALESCE(:VP_TIPO_PROTOCOLO,'') = '1')) THEN
  BEGIN
    TOTAL_EMOLUMENTO = 0;
    TOTAL_FUNDO = 0;
    QTDE = 0;
    TOTAL_BRUTO = 0;

    TOTAL_ISS = 0;
    TOTAL_GERAL_COM_ISS = 0;

    NUMERO_ONLINE = '';
    natureza_titulo_id = 0;
    descricao_natureza = '';
    emolumento_id = 0;
    descricao_emolumento = '';
    REGISTRADO_CANCELADO = '';
    qtde_folha = 0;

    IF (COALESCE(:VP_PROTOCOLO_ID,0) > 0) THEN
    BEGIN
      V_SQL = ' SELECT CAST(A.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          COALESCE(PE.TIPO_COBRANCA,'||''''||''''||'),
          A.DATA,
          COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM A.DATA),
          EXTRACT(YEAR FROM A.DATA),
          PR.PROTOCOLO_ID,
          cast(pr.data as date),
          COALESCE(PE.VALOR_COMPENSADO,0),
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||')
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
        AND (COALESCE(TA.TIPO,'||''''||''''||') = '||''''||'C'||''''||')
        AND (A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
              AND A2.PEDIDO_ID = PE.PEDIDO_ID
              AND TA2.TIPO = '||''''||'C'||''''||'
              ORDER BY A2.ANDAMENTO_ID))
        and ((COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') = '||''''||'11'||''''||') or
            (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') = '||''''||'14'||''''||'))
        ORDER BY 1,2 ';
    END
    ELSE
    BEGIN
      V_SQL = ' SELECT CAST(A.DATA AS DATE),
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          COALESCE(PE.TIPO_COBRANCA,'||''''||''''||'),
          A.DATA,
          COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM A.DATA),
          EXTRACT(YEAR FROM A.DATA),
          PR.PROTOCOLO_ID,
          cast(pr.data as date),
          COALESCE(PE.VALOR_COMPENSADO,0),
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||')
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND A.DATA BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
        AND (COALESCE(TA.TIPO,'||''''||''''||') = '||''''||'C'||''''||')
        AND (A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
              WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
              AND A2.PEDIDO_ID = PE.PEDIDO_ID
              AND TA2.TIPO = '||''''||'C'||''''||'
              ORDER BY A2.ANDAMENTO_ID))
        and ((COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') = '||''''||'11'||''''||') or
            (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') = '||''''||'14'||''''||'))
        ORDER BY 1,2 ';
    END
  
    FOR EXECUTE STATEMENT V_SQL
        INTO :DATA_ANDAMENTO, :NUMERO_PROTOCOLO, :PEDIDO_ID, :TIPO_PROTOCOLO, :TIPO_COBRANCA, :DATA_HORA_ANDAMENTO, :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE,
          :MES, :ANO, :PROTOCOLO_ID, :DATA_PROTOCOLO, :V_VALOR_COMPENSADO_ENTRADA, :NUMERO_ONLINE DO
    BEGIN
      V_TOTAL_PEDIDO = 0;
      V_QUANTIDADE_ITEM = 0;

      select first 1 e.item_df from r_pedido_item i, g_emolumento e
      where i.emolumento_id = e.emolumento_id
      and i.pedido_id = :pedido_id
      into :item_df;

      IF ((:item_df = '1') OR (:item_df = '3a') OR (:item_df = '3b') OR (:item_df = '4') OR (:item_df = '5a') OR (:item_df = '5b') OR (:item_df = '5c') OR (:item_df = '6')) THEN
      BEGIN
        item_df = '99a'; --cancelamento de registro
      END
      ELSE IF ((:item_df = '2a') OR (:item_df = '2b') OR (:item_df = '7a') OR (:item_df = '7b') OR (:item_df = '7c') OR (:item_df = '8a') OR (:item_df = '8b')) THEN
      BEGIN
        item_df = '99b'; --cancelamento de averbação
      END
      ELSE
      BEGIN
        item_df = '99c'; --cancelamento outros
      END

      select item, letra from C_RETORNA_ITEM_LETRA_DF(:item_df)
      into :item, :letra;

      SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
      WHERE CI.tipo_servico = '1' --PROTOCOLO
      AND CI.CHAVE_SERVICO = :PROTOCOLO_ID
      AND CI.tipo_transacao = 'C' --CREDITO
      AND ((CAST(CI.data_pagamento AS DATE) <= :data_andamento) OR (EXTRACT(MONTH FROM CAST(CI.data_pagamento AS DATE)) = EXTRACT(MONTH FROM :data_andamento)))
      INTO :V_TOTAL_DEPOSITO;   --VALOR BRUTO RECEBIDO
  
      SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
      WHERE CI.tipo_servico = '1' --PROTOCOLO
      AND CI.CHAVE_SERVICO = :PROTOCOLO_ID
      AND CI.tipo_transacao = 'D' --CREDITO
      AND ((CAST(CI.data_pagamento AS DATE) <= :data_andamento) OR (EXTRACT(MONTH FROM CAST(CI.data_pagamento AS DATE)) = EXTRACT(MONTH FROM :data_andamento)))
      INTO :v_total_devolvido;   --VALOR devolvido
  
      IF (COALESCE(:v_total_devolvido,0) > 0) THEN
      BEGIN
        V_TOTAL_DEPOSITO = COALESCE(:V_TOTAL_DEPOSITO,0) - COALESCE(:v_total_devolvido,0);
      END
  
      IF (COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) > 0) THEN
      BEGIN
        V_TOTAL_DEPOSITO = COALESCE(:V_TOTAL_DEPOSITO,0) + COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0);
      END

      TOTAL_BRUTO = :V_TOTAL_DEPOSITO;
      TOTAL_ISS = round((coalesce(total_bruto,0) * 5),2);
      TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);
      total_bruto = coalesce(:total_bruto,0) - coalesce(:total_iss,0);
      TOTAL_FUNDO = round((coalesce(total_bruto,0) * 7),2);
      TOTAL_FUNDO = round(cast((:TOTAL_FUNDO / 107) as numeric(18,5)),2);
      total_emolumento = coalesce(:total_bruto,0) - coalesce(:TOTAL_FUNDO,0);
      TOTAL_GERAL_COM_ISS = coalesce(:total_bruto,0) + coalesce(:total_iss,0);

      IF (COALESCE(:TOTAL_BRUTO,0) > 0) THEN
      BEGIN
        SUSPEND;
      END
    END
  end
  --FIM SELECIONAR PROTOCOLOS CANCELADOS de ONR-Penhora e ONR-E-PROTOCOLO

  --PROTOCOLOS de consolidação
  IF ((COALESCE(:VP_TIPO_PROTOCOLO,'') = 'T') OR (COALESCE(:VP_TIPO_PROTOCOLO,'') = '1')) THEN
  BEGIN
    TOTAL_EMOLUMENTO = 0;
    TOTAL_FUNDO = 0;
    QTDE = 0;
    TOTAL_BRUTO = 0;
  
    TOTAL_ISS = 0;
    TOTAL_GERAL_COM_ISS = 0;
  
    NUMERO_ONLINE = '';
    natureza_titulo_id = 0;
    descricao_natureza = '';
    emolumento_id = 0;
    descricao_emolumento = '';
    REGISTRADO_CANCELADO = '';
    IF (COALESCE(:VP_PROTOCOLO_ID,0) > 0) THEN
    BEGIN
      V_SQL = ' SELECT CAST(PR.DATA AS DATE),
          e.item_df,
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          COALESCE(PE.TIPO_COBRANCA,'||''''||''''||'),
          PR.DATA,
          COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM PR.DATA),
          EXTRACT(YEAR FROM PR.DATA),
          PR.PROTOCOLO_ID,
          cast(pr.data as date),
          COALESCE(PE.VALOR_COMPENSADO,0),
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          coalesce(PI.QUANTIDADE,0), coalesce(PI.valor_emolumento,0), coalesce(PI.valor_fundo_ri,0), NT.descricao,
          coalesce(PI.valor_iss,0), nt.natureza_titulo_id, e.emolumento_id, e.descricao
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, G_EMOLUMENTO E, g_natureza_titulo NT
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = PI.PEDIDO_ID
        AND PI.EMOLUMENTO_ID = E.EMOLUMENTO_ID
        and pi.natureza_titulo_id = nt.natureza_titulo_id
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
        and ((COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') = '||''''||'3'||''''||') or
             (COALESCE(e.item_df,'||''''||''''||') = '||''''||'7a'||''''||') or
             (COALESCE(e.item_df,'||''''||''''||') = '||''''||'7b'||''''||') or
             (COALESCE(NT.CONSOLIDACAO,'||''''||''''||') = '||''''||'S'||''''||'))
        ORDER BY 1,2,3 ';
    END
    ELSE
    BEGIN
      V_SQL = ' SELECT CAST(PR.DATA AS DATE),
          e.item_df,
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          COALESCE(PE.TIPO_COBRANCA,'||''''||''''||'),
          PR.DATA,
          COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM PR.DATA),
          EXTRACT(YEAR FROM PR.DATA),
          PR.PROTOCOLO_ID,
          cast(pr.data as date),
          COALESCE(PE.VALOR_COMPENSADO,0),
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          coalesce(PI.QUANTIDADE,0), coalesce(PI.valor_emolumento,0), coalesce(PI.valor_fundo_ri,0), NT.descricao,
          coalesce(PI.valor_iss,0), nt.natureza_titulo_id, e.emolumento_id, e.descricao
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, G_EMOLUMENTO E, g_natureza_titulo NT
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = PI.PEDIDO_ID
        AND PI.EMOLUMENTO_ID = E.EMOLUMENTO_ID
        and pi.natureza_titulo_id = nt.natureza_titulo_id
        AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND PR.DATA BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
        and ((COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') = '||''''||'3'||''''||') or
             (COALESCE(e.item_df,'||''''||''''||') = '||''''||'7a'||''''||') or
             (COALESCE(e.item_df,'||''''||''''||') = '||''''||'7b'||''''||') or
             (COALESCE(NT.CONSOLIDACAO,'||''''||''''||') = '||''''||'S'||''''||'))
        ORDER BY 1,2,3 ';
    END
  
    FOR EXECUTE STATEMENT V_SQL
        INTO :DATA_ANDAMENTO, :item_df, :NUMERO_PROTOCOLO, :PEDIDO_ID, :TIPO_PROTOCOLO, :TIPO_COBRANCA, :DATA_HORA_ANDAMENTO, :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE,
          :MES, :ANO, :PROTOCOLO_ID, :DATA_PROTOCOLO, :V_VALOR_COMPENSADO_ENTRADA, :NUMERO_ONLINE, :QTDE, :TOTAL_EMOLUMENTO, :TOTAL_FUNDO,
          :descricao_natureza, :total_iss, :natureza_titulo_id, :emolumento_id, :descricao_emolumento DO
    BEGIN
      select item, letra from C_RETORNA_ITEM_LETRA_DF(:item_df)
      into :item, :letra;

      if (coalesce(:item,0) <> 7) then
      begin
        item = 7;
        letra = 'a';
        item_df = '7a';
      end

      V_TOTAL_PEDIDO = 0;
      V_QUANTIDADE_ITEM = 0;
  
      registrado_cancelado = '';
  
      IF (COALESCE(:TIPO_COBRANCA,'') = '1') THEN --se for ISENTO
      BEGIN
        TOTAL_EMOLUMENTO = 0;
        TOTAL_FUNDO = 0;
        TOTAL_BRUTO = 0;
      
        TOTAL_ISS = 0;
        TOTAL_GERAL_COM_ISS = 0;
  
        --SUSPEND;
      END
      ELSE
      BEGIN
        TOTAL_BRUTO = COALESCE(:TOTAL_EMOLUMENTO,0) + COALESCE(:TOTAL_FUNDO,0);
        TOTAL_GERAL_COM_ISS = :TOTAL_BRUTO + :TOTAL_ISS;
  
        IF (COALESCE(:TOTAL_BRUTO,0) > 0) THEN
        BEGIN
          SUSPEND;
        END
      END
    END
  end
  --FIM SELECIONAR PROTOCOLOS consolidação


  --PROTOCOLOS de CERTIDÃO
  IF ((COALESCE(:VP_TIPO_PROTOCOLO,'') = 'T') OR (COALESCE(:VP_TIPO_PROTOCOLO,'') = '3')) THEN
  BEGIN
    TOTAL_EMOLUMENTO = 0;
    TOTAL_FUNDO = 0;
    QTDE = 0;
    TOTAL_BRUTO = 0;
  
    TOTAL_ISS = 0;
    TOTAL_GERAL_COM_ISS = 0;
  
    NUMERO_ONLINE = '';
    natureza_titulo_id = 0;
    descricao_natureza = '';
    emolumento_id = 0;
    descricao_emolumento = '';
    REGISTRADO_CANCELADO = '';
    IF (COALESCE(:VP_PROTOCOLO_ID,0) > 0) THEN
    BEGIN
      V_SQL = ' SELECT DISTINCT CAST(A.DATA AS DATE),
          e.item_df,
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          COALESCE(PE.TIPO_COBRANCA,'||''''||''''||'),
          A.DATA,
          COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM A.DATA),
          EXTRACT(YEAR FROM A.DATA),
          PR.PROTOCOLO_ID,
          CAST(PR.DATA AS DATE), 
          COALESCE(PE.VALOR_COMPENSADO,0),
          COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
          coalesce(PI.QUANTIDADE,0), coalesce(PI.valor_emolumento,0), coalesce(PI.valor_fundo_ri,0), NT.descricao,
          coalesce(pi.valor_iss,0), nt.natureza_titulo_id, e.emolumento_id, e.descricao,
          coalesce(PI.quantidade_folha_excedente,0),
          pi.pedido_item_id
        FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, G_EMOLUMENTO E, G_NATUREZA_TITULO NT
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PE.PEDIDO_ID = PI.PEDIDO_ID
        AND PE.TB_TITULO_ID = T.TB_TITULO_ID
        AND PE.PEDIDO_ID = A.PEDIDO_ID
        AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND PI.emolumento_id = E.emolumento_id
        AND PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID
        AND (PR.TIPO_PROTOCOLO = '||''''||'3'||''''||')
        AND TA.STATUS_SELO_DIGITAL = '||''''||'9'||''''||'
        AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
        AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
          WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
          AND A2.PEDIDO_ID = PE.PEDIDO_ID
          AND TA2.STATUS_SELO_DIGITAL = '||''''||'9'||''''||'
          ORDER BY A2.ANDAMENTO_ID)
        AND (SELECT COUNT(*) FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
          WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
          AND A2.PEDIDO_ID = PE.PEDIDO_ID
          AND TA2.TIPO = '||''''||'C'||''''||') = 0
       ORDER BY 1,2,3 ';
    END
    ELSE
    BEGIN
      V_SQL = ' SELECT DISTINCT CAST(A.DATA AS DATE),
          e.item_df,
          PR.NUMERO_ORDEM,
          PR.PEDIDO_ID,
          PR.TIPO_PROTOCOLO,
          COALESCE(PE.TIPO_COBRANCA,'||''''||''''||'),
          A.DATA,
          COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
          COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
          EXTRACT(MONTH FROM A.DATA),
