        AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
          WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
          AND A2.PEDIDO_ID = PE.PEDIDO_ID
          AND TA2.STATUS_SELO_DIGITAL = '||''''||'9'||''''||'
          ORDER BY A2.ANDAMENTO_ID)
        AND (SELECT COUNT(*) FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
          WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
          AND A2.PEDIDO_ID = PE.PEDIDO_ID
          AND TA2.TIPO = '||''''||'C'||''''||') = 0
       ORDER BY 1,2,3 ';
    END
  
    FOR EXECUTE STATEMENT V_SQL
        INTO :DATA_ANDAMENTO, :item_df, :NUMERO_PROTOCOLO, :PEDIDO_ID, :TIPO_PROTOCOLO, :TIPO_COBRANCA, :DATA_HORA_ANDAMENTO, :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE,
          :MES, :ANO, :PROTOCOLO_ID, :DATA_PROTOCOLO, :V_VALOR_COMPENSADO_ENTRADA, :NUMERO_ONLINE, :QTDE, :TOTAL_EMOLUMENTO, :TOTAL_FUNDO,
          :descricao_natureza, :total_iss, :natureza_titulo_id, :emolumento_id, :descricao_emolumento, :qtde_folha, :v_pedido_item_id DO
    BEGIN
      if ((coalesce(:numero_online,'') <> '') and (coalesce(:item_df,'') = '10a')) then
      begin
        item_df = '10a1';
      end

      select item, letra from C_RETORNA_ITEM_LETRA_DF(:item_df)
      into :item, :letra;

      V_TOTAL_PEDIDO = 0;
      V_QUANTIDADE_ITEM = 0;
  
      registrado_cancelado = '';
  
      IF (COALESCE(:TIPO_COBRANCA,'') = '1') THEN --se for ISENTO
      BEGIN
        TOTAL_EMOLUMENTO = 0;
        TOTAL_FUNDO = 0;
        TOTAL_BRUTO = 0;
  
        TOTAL_ISS = 0;
        TOTAL_GERAL_COM_ISS = 0;
  
        --SUSPEND;
      END
      ELSE
      BEGIN
        IF (COALESCE(:qtde_folha,0) > 0) THEN
        BEGIN
          SELECT FIRST 1 emolumento_periodo_id FROM g_emolumento_periodo ep
          WHERE :data_protocolo >= ep.data_inicial
          ORDER BY ep.data_inicial desc
          INTO :V_EMOLUMENTO_PERIODO_ID;
  
          SELECT first 1 COALESCE(gi.VALOR_EMOLUMENTO,0), COALESCE(gi.VALOR_FUNDO_RI,0)
          from g_emolumento g, g_emolumento_item gi
          where g.emolumento_id = gi.emolumento_id
          and gi.emolumento_periodo_id = :V_EMOLUMENTO_PERIODO_ID
          and g.item_df = '10c'
          order by gi.emolumento_item_id desc
          INTO :V_TOTAL_EMOLUMENTO_FOLHA, :V_TOTAL_FUNDO_FOLHA;

          V_TOTAL_EMOLUMENTO_FOLHA = (COALESCE(:V_TOTAL_EMOLUMENTO_FOLHA,0) * COALESCE(:qtde_folha,0));
          V_TOTAL_FUNDO_FOLHA = (COALESCE(:V_TOTAL_FUNDO_FOLHA,0) * COALESCE(:qtde_folha,0));
          V_TOTAL_ISS_FOLHA = CAST(((COALESCE(:V_TOTAL_EMOLUMENTO_FOLHA,0) + COALESCE(:V_TOTAL_FUNDO_FOLHA,0)) * 0.05) AS NUMERIC(18,2));
  
          --enviar emolumento principal
          TOTAL_EMOLUMENTO = :TOTAL_EMOLUMENTO - :V_TOTAL_EMOLUMENTO_FOLHA;
          TOTAL_FUNDO = :TOTAL_FUNDO - :V_TOTAL_FUNDO_FOLHA;
          TOTAL_ISS = :TOTAL_ISS - :V_TOTAL_ISS_FOLHA;
          TOTAL_BRUTO = COALESCE(:TOTAL_EMOLUMENTO,0) + COALESCE(:TOTAL_FUNDO,0);
          TOTAL_GERAL_COM_ISS = :TOTAL_BRUTO + :TOTAL_ISS;
          IF (COALESCE(:TOTAL_BRUTO,0) > 0) THEN
          BEGIN
            SUSPEND;
          END
  
          qtde = :qtde_folha;
          item_df = '10c';--folha excedente
          item = 10;
          letra = 'c';
          descricao_natureza = 'Folha Excedente';
          descricao_emolumento = 'Folha Excedente';
          TOTAL_EMOLUMENTO = :V_TOTAL_EMOLUMENTO_FOLHA;
          TOTAL_FUNDO = :V_TOTAL_FUNDO_FOLHA;
          TOTAL_ISS = :V_TOTAL_ISS_FOLHA;
          TOTAL_BRUTO = COALESCE(:TOTAL_EMOLUMENTO,0) + COALESCE(:TOTAL_FUNDO,0);
          TOTAL_GERAL_COM_ISS = :TOTAL_BRUTO + :TOTAL_ISS;
          IF (COALESCE(:TOTAL_BRUTO,0) > 0) THEN
          BEGIN
            SUSPEND;
          END
        END
        ELSE
        BEGIN
          TOTAL_BRUTO = COALESCE(:TOTAL_EMOLUMENTO,0) + COALESCE(:TOTAL_FUNDO,0);
          TOTAL_GERAL_COM_ISS = :TOTAL_BRUTO + :TOTAL_ISS;
  
          IF (COALESCE(:TOTAL_BRUTO,0) > 0) THEN
          BEGIN
            SUSPEND;
          END
        END
      END
    END
  end
  --FIM SELECIONAR CERTIDÃO
END ^

ALTER PROCEDURE C_DIARIO_AUXILIAR_RECEITA_DF_REGIME_CAIXA (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1)
RETURNS (SISTEMA_ID INTEGER,
PEDIDO_ID INTEGER,
PROTOCOLO_ID INTEGER,
DATA_ANDAMENTO TIMESTAMP,
DATA_HORA_ANDAMENTO TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
DATA_PROTOCOLO TIMESTAMP,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
NATUREZA_TITULO_ID INTEGER,
DESCRICAO_NATUREZA VARCHAR(260) CHARACTER SET ISO8859_1,
EMOLUMENTO_ID INTEGER,
DESCRICAO_EMOLUMENTO VARCHAR(260) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
MES INTEGER,
ANO INTEGER,
ITEM_DF VARCHAR(10) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2),
ORIGEM_PEDIDO VARCHAR(3) CHARACTER SET ISO8859_1,
TIPO_ORIGEM_SITE VARCHAR(3) CHARACTER SET ISO8859_1,
ITEM INTEGER,
LETRA VARCHAR(10) CHARACTER SET ISO8859_1,
TOTAL_DEVOLVIDO_EMOLUMENTO NUMERIC(18, 2),
TOTAL_DEVOLVIDO_FUNDO NUMERIC(18, 2),
TOTAL_DEVOLVIDO_ISS NUMERIC(18, 2),
TOTAL_DEVOLVIDO_BRUTO NUMERIC(18, 2),
TOTAL_DEVOLVIDO_BRUTO_COM_ISS NUMERIC(18, 2),
NATUREZA VARCHAR(260) CHARACTER SET ISO8859_1,
CAIXA_ITEM_ID INTEGER,
QUANTIDADE INTEGER)
AS 
DECLARE VARIABLE V_SQL VARCHAR(3000);
  declare variable v_tipo_transacao varchar(3);
  declare variable qtde_folha integer;
  declare variable periodo_padrao varchar(10);
  declare variable total_folha NUMERIC(18,2);
  declare variable total_temp NUMERIC(18,2);
  declare variable item_temp VARCHAR(10); --numero do item da tabela nova
  declare variable repasse varchar(10);
BEGIN

  SISTEMA_ID = 1;

  --PROTOCOLOS REGISTRADOS ou CANCELADOS
  TOTAL_EMOLUMENTO = 0;
  TOTAL_FUNDO = 0;
  TOTAL_BRUTO = 0;

  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;

  NUMERO_ONLINE = '';
  natureza_titulo_id = 0;
  descricao_natureza = '';
  emolumento_id = 0;
  descricao_emolumento = '';
  V_SQL = ' SELECT CAST(CI.DATA_PAGAMENTO AS DATE),
      PR.NUMERO_ORDEM,
      PR.PEDIDO_ID,
      PR.TIPO_PROTOCOLO,
      CI.DATA_PAGAMENTO,
      COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
      COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
      EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
      EXTRACT(YEAR FROM CI.DATA_PAGAMENTO),
      PR.PROTOCOLO_ID,
      cast(pr.data as date),
      COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
      CI.tipo_transacao,
      COALESCE(CI.VALOR_PAGO,0),
      COALESCE(CS.REPASSE,'||''''||''''||'),
      ci.caixa_item_id
      FROM C_CAIXA_ITEM CI
                            left join C_CAIXA_SERVICO CS
                            on CI.CAIXA_SERVICO_ID = CS.CAIXA_SERVICO_ID
                            left join G_USUARIO U
                            ON CI.USUARIO_SERVICO_ID = U.USUARIO_ID
                            left join R_PROTOCOLO PR
                            ON CI.CHAVE_SERVICO = PR.PROTOCOLO_ID
                            left join R_PEDIDO PE
                            ON PR.PEDIDO_ID = PE.PEDIDO_ID
                            left join R_TB_TITULO TI
                            on pe.tb_titulo_id = ti.tb_titulo_id '||
           ' WHERE CAST(CI.DATA_PAGAMENTO AS DATE) BETWEEN '||''''||:V_DATA_INI||''''||' AND '||''''||:V_DATA_FIM||''''||
           ' AND ((CI.SITUACAO = '||''''||'4'||''''||') or (CI.CAIXA_SERVICO_ID = 1 )) '||
           ' ORDER BY CAST(CI.DATA_PAGAMENTO AS DATE), CI.DESCRICAO ';
  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA_ANDAMENTO, :NUMERO_PROTOCOLO, :PEDIDO_ID, :TIPO_PROTOCOLO, :DATA_HORA_ANDAMENTO, :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE,
        :MES, :ANO, :PROTOCOLO_ID, :DATA_PROTOCOLO, :NUMERO_ONLINE, :v_tipo_transacao, :TOTAL_GERAL_COM_ISS, :repasse, :caixa_item_id do
  BEGIN
    item_df = '';
    descricao_natureza = '';
    natureza_titulo_id = NULL;
    emolumento_id = NULL;
    descricao_emolumento = '';
    TOTAL_EMOLUMENTO = 0;
    TOTAL_FUNDO = 0;
    TOTAL_BRUTO = 0;
    TOTAL_ISS = 0;

    TOTAL_DEVOLVIDO_EMOLUMENTO = 0;
    TOTAL_DEVOLVIDO_FUNDO = 0;
    TOTAL_DEVOLVIDO_ISS = 0;
    TOTAL_DEVOLVIDO_BRUTO = 0;
    TOTAL_DEVOLVIDO_BRUTO_COM_ISS = 0;
    QUANTIDADE = 0;
    qtde_folha = 0;

    item = null;
    letra = '';

    if (coalesce(:v_tipo_transacao,'') = 'C') then
    begin
      if (coalesce(:NUMERO_PROTOCOLO,0) > 0) then
      begin
        select first 1 e.item_df, NT.descricao, nt.natureza_titulo_id, e.emolumento_id, e.descricao
        from r_pedido_item pi, g_emolumento e, g_natureza_titulo nt
        where pi.emolumento_id = e.emolumento_id
        and pi.natureza_titulo_id = nt.natureza_titulo_id
        and pi.pedido_id = :pedido_id
        order by pi.pedido_item_id
        into :item_df, :descricao_natureza, :natureza_titulo_id, :emolumento_id, :descricao_emolumento;

        if ((coalesce(:numero_online,'') <> '') and (coalesce(:item_df,'') = '10a')) then
        begin
          item_df = '10a1';
        end
  
        if (coalesce(:TOTAL_GERAL_COM_ISS,0) > 0 ) then
        begin
          qtde_folha = 0;
          if (coalesce(:TIPO_PROTOCOLO,'') = '3') then
          begin
            SELECT SUM(quantidade_folha_excedente) FROM R_PEDIDO_ITEM WHERE PEDIDO_ID = :PEDIDO_ID
            into :qtde_folha;
          end

          total_folha = 0;
          total_temp = 0;
          if (coalesce(:qtde_folha,0) > 0) then
          begin
            SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','PERIODO_PADRAO',1)
            into :periodo_padrao;

            SELECT FIRST 1 (coalesce(ei.valor_emolumento,0) + coalesce(ei.valor_fundo_ri,0))
            from g_emolumento e, g_emolumento_item ei
            where e.emolumento_id = ei.emolumento_id
            and ei.emolumento_periodo_id = :periodo_padrao
            and e.reg_averb = 'F'
            into :total_folha;

            total_folha = :total_folha * 1.05;
            total_folha = :total_folha * :qtde_folha;
          end

          item_temp = '';
          if (coalesce(:total_folha,0) > 0) then
          begin
            if (coalesce(:total_folha,0) < coalesce(:TOTAL_GERAL_COM_ISS,0)) then
            begin
              total_temp = coalesce(:TOTAL_GERAL_COM_ISS,0) - coalesce(:total_folha,0);

              TOTAL_GERAL_COM_ISS = coalesce(:total_folha,0);

              TOTAL_ISS = round((coalesce(TOTAL_GERAL_COM_ISS,0) * 5),2);
              TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);
  
              total_bruto = coalesce(:TOTAL_GERAL_COM_ISS,0) - coalesce(:total_iss,0);
      
              TOTAL_FUNDO = round((coalesce(total_bruto,0) * 7),2);
              TOTAL_FUNDO = round(cast((:TOTAL_FUNDO / 107) as numeric(18,5)),2);
      
              total_emolumento = coalesce(:total_bruto,0) - coalesce(:TOTAL_FUNDO,0);

              item_temp = :ITEM_DF;

              ITEM_DF = '10c';
              item = 10;
              letra = 'c';
              NATUREZA = :ITEM_DF||' - Folha excedente';

              suspend;

              item_df = :item_temp;
              TOTAL_GERAL_COM_ISS = :total_temp;
            end
            else
            begin
              TOTAL_ISS = round((coalesce(TOTAL_GERAL_COM_ISS,0) * 5),2);
              TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);
  
              total_bruto = coalesce(:TOTAL_GERAL_COM_ISS,0) - coalesce(:total_iss,0);
      
              TOTAL_FUNDO = round((coalesce(total_bruto,0) * 7),2);
              TOTAL_FUNDO = round(cast((:TOTAL_FUNDO / 107) as numeric(18,5)),2);
      
              total_emolumento = coalesce(:total_bruto,0) - coalesce(:TOTAL_FUNDO,0);

              item_temp = :ITEM_DF;

              ITEM_DF = '10c';
              item = 10;
              letra = 'c';
              NATUREZA = :ITEM_DF||' - Folha excedente';

              suspend;


              total_temp = 0;
              TOTAL_GERAL_COM_ISS = 0;
            end
          end
        end

        if (coalesce(:TOTAL_GERAL_COM_ISS,0) > 0 ) then
        begin
          TOTAL_ISS = round((coalesce(TOTAL_GERAL_COM_ISS,0) * 5),2);
          TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);
  
          total_bruto = coalesce(:TOTAL_GERAL_COM_ISS,0) - coalesce(:total_iss,0);
  
          TOTAL_FUNDO = round((coalesce(total_bruto,0) * 7),2);
          TOTAL_FUNDO = round(cast((:TOTAL_FUNDO / 107) as numeric(18,5)),2);
  
          total_emolumento = coalesce(:total_bruto,0) - coalesce(:TOTAL_FUNDO,0);

          select item, letra from C_RETORNA_ITEM_LETRA_DF(:item_df)
          into :item, :letra;

          if (:ITEM_DF = '1') then
          begin
            NATUREZA = :ITEM_DF||' - Registro de qualquer título ou documento com conteúdo econômico';
          end
          else if (:ITEM_DF = '2a') then
          begin
            NATUREZA = :ITEM_DF||' - Averbação de qualquer título ou documento com conteúdo econômico';
          end
          else if (:ITEM_DF = '2b') then
          begin
            NATUREZA = :ITEM_DF||' - Averbação sem conteúdo econômico';
          end
          else if (:ITEM_DF = '3a') then
          begin
            NATUREZA = :ITEM_DF||' - Registro de loteamento ou desmembramento urbano ou rural';
          end
          else if (:ITEM_DF = '3b') then
          begin
            NATUREZA = :ITEM_DF||' - Registro de loteamento - Intimação ou notificação';
          end
          else if (:ITEM_DF = '4') then
          begin
            NATUREZA = :ITEM_DF||' - Registro de incorporação imobiliária ou registro de instituição de condomínio';
          end
          else if (:ITEM_DF = '5a') then
          begin
            NATUREZA = :ITEM_DF||' - Registro de convenção de condomínio';
          end
          else if (:ITEM_DF = '5b') then
          begin
            NATUREZA = :ITEM_DF||' - Registro de pacto antenupcial no Livro 3';
          end
          else if (:ITEM_DF = '5c') then
          begin
            NATUREZA = :ITEM_DF||' - Abertura de matrícula de imóvel urbano ou rural';
          end
          else if (:ITEM_DF = '6') then
          begin
            NATUREZA = :ITEM_DF||' - Registro de cédula de crédito e hipoteca cedular, por imóvel';
          end
          else if (:ITEM_DF = '7a') then
          begin
            NATUREZA = :ITEM_DF||' - Procedimento para constituição em mora';
          end
          else if (:ITEM_DF = '7b') then
          begin
            NATUREZA = :ITEM_DF||' - Notificação do devedor';
          end
          else if (:ITEM_DF = '7c') then
          begin
            NATUREZA = :ITEM_DF||' - Averbação da consolidação da propriedade';
          end
          else if (:ITEM_DF = '8a') then
          begin
            NATUREZA = :ITEM_DF||' - Averbação de retificação';
          end
          else if (:ITEM_DF = '8b') then
          begin
            NATUREZA = :ITEM_DF||' - Expedição de notificação, por confrontante';
          end
          else if (:ITEM_DF = '9a') then
          begin
            NATUREZA = :ITEM_DF||' - Pelo primeiro recebimento e abertura de conta';
          end
          else if (:ITEM_DF = '9b') then
          begin
            NATUREZA = :ITEM_DF||' - Pelo recebimento de cada prestação seguinte';
          end
          else if (:ITEM_DF = '10a') then
          begin
            NATUREZA = :ITEM_DF||' - Certidão';
          end
          else if (:ITEM_DF = '10a1') then
          begin
            NATUREZA = :ITEM_DF||' - Certidão ONR';
          end
          else if (:ITEM_DF = '10b') then
          begin
            NATUREZA = :ITEM_DF||' - Certidão expedida por outra serventia';
          end
          else if (:ITEM_DF = '10c') then
          begin
            NATUREZA = :ITEM_DF||' - Folha excedente';
          end
          else if (:ITEM_DF = '11a') then
          begin
            NATUREZA = :ITEM_DF||' - Informação de banco de dados relativa aos atos praticados, fornecida eletronicamente';
          end
          else if (:ITEM_DF = '11b') then
          begin
            NATUREZA = :ITEM_DF||' - Cópia autêntica de documento arquivado utilizado para instruir ato';
          end
          else if (:ITEM_DF = '11c') then
          begin
            NATUREZA = :ITEM_DF||' - Cópia autêntica de documento arquivado utilizado para instruir ato';
          end
          else
          begin
             NATUREZA = '';
          end

          SUSPEND;
        end
      end
      else
      begin
        item_df = '33';--outras receitas
        item = 33;
        letra = '';

        if (coalesce(:TOTAL_GERAL_COM_ISS,0) > 0 ) then
        begin
          TOTAL_ISS = 0;

          total_bruto = coalesce(:TOTAL_GERAL_COM_ISS,0);
  
          TOTAL_FUNDO = 0;

          total_emolumento = 0;

          NATUREZA = 'Outras Receitas';

          SUSPEND;
        end
      end
    end
    else
    begin
      TOTAL_DEVOLVIDO_BRUTO_COM_ISS = :TOTAL_GERAL_COM_ISS;
      TOTAL_GERAL_COM_ISS = 0;

      if (coalesce(:TOTAL_DEVOLVIDO_BRUTO_COM_ISS,0) > 0 ) then
      begin
        if (coalesce(:NUMERO_PROTOCOLO,0) > 0) then
        begin
          TOTAL_DEVOLVIDO_ISS = round((coalesce(TOTAL_DEVOLVIDO_BRUTO_COM_ISS,0) * 5),2);
          TOTAL_DEVOLVIDO_ISS = round(cast((:TOTAL_DEVOLVIDO_ISS / 105) as numeric(18,5)),2);
  
          TOTAL_DEVOLVIDO_BRUTO = coalesce(:TOTAL_DEVOLVIDO_BRUTO_COM_ISS,0) - coalesce(:TOTAL_DEVOLVIDO_ISS,0);
  
          TOTAL_DEVOLVIDO_FUNDO = round((coalesce(TOTAL_DEVOLVIDO_BRUTO,0) * 7),2);
          TOTAL_DEVOLVIDO_FUNDO = round(cast((:TOTAL_DEVOLVIDO_FUNDO / 107) as numeric(18,5)),2);
  
          TOTAL_DEVOLVIDO_EMOLUMENTO = coalesce(:TOTAL_DEVOLVIDO_BRUTO,0) - coalesce(:TOTAL_DEVOLVIDO_FUNDO,0);

          NATUREZA = 'Devolução ao usuário';

          item_df = '88a';
          item = 88;
          letra = 'a';
        end
        else
        begin
          if (coalesce(:repasse,'') = 'S') then
          begin
            TOTAL_DEVOLVIDO_ISS = 0;

            TOTAL_DEVOLVIDO_BRUTO = coalesce(:TOTAL_DEVOLVIDO_BRUTO_COM_ISS,0);
  
            TOTAL_DEVOLVIDO_FUNDO = 0;

            TOTAL_DEVOLVIDO_EMOLUMENTO = 0;

            NATUREZA = 'Repasse';

            item_df = '99r';
            item = 99;
            letra = 'r';
          end
          else
          begin
            TOTAL_DEVOLVIDO_ISS = 0;

            TOTAL_DEVOLVIDO_BRUTO = coalesce(:TOTAL_DEVOLVIDO_BRUTO_COM_ISS,0);
  
            TOTAL_DEVOLVIDO_FUNDO = 0;

            TOTAL_DEVOLVIDO_EMOLUMENTO = 0;

            NATUREZA = 'Despesas';

            item_df = '99d';
            item = 99;
            letra = 'd';
          end
        end
        suspend;
      end
    end
  end
end ^

ALTER PROCEDURE C_DIARIO_AUX_NOTAS_DF (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
V_TIPO_PESQUISA VARCHAR(3) CHARACTER SET ISO8859_1,
V_PROTOCOLO_ID INTEGER = 0)
RETURNS (SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_PROTOCOLO TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_CARTORIO NUMERIC(18, 2),
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL NUMERIC(18, 2),
TOTAL_NF_EMITIDO NUMERIC(18, 2),
TOTAL_NF_NO_MES NUMERIC(18, 2),
TOTAL_NF_FORA_MES NUMERIC(18, 2),
STATUS VARCHAR(50) CHARACTER SET ISO8859_1)
AS 
declare variable VSEQ INTEGER;
  declare variable v_data_andamento timestamp;
  declare variable item_df varchar(10);
  declare variable v_qtde integer;
BEGIN
  if (coalesce(:V_PROTOCOLO_ID,0) = 0) then
  begin
    FOR SELECT data, data_protocolo, 1 AS TIPO_RECEITA, NUMERO_PROTOCOLO, SISTEMA_ID, pedido_id, TIPO_PROTOCOLO, NUMERO_ONLINE,
      (SUM(COALESCE(TOTAL_EMOLUMENTO,0)) + SUM(COALESCE(TOTAL_FUNDO,0))) AS TOTAL_CARTORIO,
      COALESCE((SELECT SUM(COALESCE(VALOR_NOTA,0)) FROM R_NOTAS_DO_PROTOCOLO(pedido_id)),0) AS TOTAL_NF_EMITIDO,
      SUM(COALESCE(TOTAL_ISS,0))
      FROM C_DIARIO_AUX_REC_DESPESA_DF_NEW(:V_DATA_INI,:V_DATA_FIM, 'T', 0)
      where tipo_livro = 'C'
      GROUP BY 1,2,3,4,5,6,7,8
    ORDER BY 2, 3, 4
    INTO :v_data_andamento, :data_protocolo, :VSEQ, :NUMERO_PROTOCOLO, :SISTEMA_ID, :ID, :TIPO_PROTOCOLO, :NUMERO_ONLINE, :TOTAL_CARTORIO, :TOTAL_NF_EMITIDO, :TOTAL_ISS DO
    BEGIN
      select first 1 e.item_df from r_protocolo pr, r_pedido_item pi, g_emolumento e
      where pr.pedido_id = pi.pedido_id
      and pi.emolumento_id = e.emolumento_id
      and pr.pedido_id = :id
      order by pr.tipo_protocolo, pi.pedido_item_id
      into :item_df;
  
  
      if (:ITEM_DF = '1') then
      begin
