ALTER PROCEDURE C_DIARIO_AUX_RECEITA_DESPESA_DF (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_TIPO_PROTOCOLO VARCHAR(3) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (TIPO_LIVRO VARCHAR(50) CHARACTER SET ISO8859_1,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TIPO_ATO VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
declare variable VSEQ INTEGER;
BEGIN
  TIPO_LIVRO = 'RECEITA E DESPESA';
  /*if (:V_DATA_FIM = '31.03.2024') then
  begin
    V_DATA_FIM = '17.03.2024';
  end*/
  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    if (COALESCE(:VP_TIPO_PROTOCOLO,'') = '3') then
    begin
      FOR SELECT DATA, 4 AS TIPO_RECEITA, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
        TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
        TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
        TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
        TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
        TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
        TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TIPO_RETORNO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA, TOTAL_FUNDO_FOLHA, QTDE_FOLHA,
        NUMERO_ONLINE, TIPO_ATO, TOTAL_ISS, TOTAL_GERAL_COM_ISS
        FROM C_DIARIO_AUX_REC_DESP_DF_CERT(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
      ORDER BY 1, 2, 3
      INTO :DATA, :VSEQ, :NUMERO_PROTOCOLO, :SISTEMA_ID, :ID, :DATA_HORA, :TIPO_PROTOCOLO, :NATUREZA, :DESCRICAO,
        :TOTAL_EMOLUMENTO, :TOTAL_TAXA_JUDICIARIA, :TOTAL_FUNDO, :TOTAL_DESPESA,
        :TOTAL_BRUTO, :TOTAL_DESCONTO, :TOTAL_COMPENSADO, :QTDE, :TOTAL_EMOLUMENTO_REG, :TOTAL_TAXA_REG,
        :TOTAL_FUNDO_REG, :QTDE_REG, :TOTAL_EMOLUMENTO_AV, :TOTAL_TAXA_AV, :TOTAL_FUNDO_AV, :QTDE_AV,
        :TOTAL_EMOLUMENTO_CERT, :TOTAL_TAXA_CERT, :TOTAL_FUNDO_CERT, :QTDE_CERT, :TOTAL_EMOLUMENTO_BUSCA,
        :TOTAL_TAXA_BUSCA, :TOTAL_FUNDO_BUSCA, :QTDE_BUSCA, :TOTAL_EMOLUMENTO_REVAL, :TOTAL_TAXA_REVAL,
        :TOTAL_FUNDO_REVAL, :QTDE_REVAL, :MES, :ANO, :TIPO_RETORNO, :TOTAL_EMOLUMENTO_FOLHA, :TOTAL_TAXA_FOLHA, :TOTAL_FUNDO_FOLHA, :QTDE_FOLHA,
        :NUMERO_ONLINE, :TIPO_ATO, :TOTAL_ISS, TOTAL_GERAL_COM_ISS DO
      BEGIN
        SUSPEND;
      END
    end
    else
    begin
    FOR SELECT DATA, 1 AS TIPO_RECEITA, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
        TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
        TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
        TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
        TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
        TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
        TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TIPO_RETORNO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA, TOTAL_FUNDO_FOLHA, QTDE_FOLHA,
        NUMERO_ONLINE, TIPO_ATO, TOTAL_ISS, TOTAL_GERAL_COM_ISS
        FROM C_DIARIO_AUX_REC_DESP_DF_REG(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
      UNION ALL
      SELECT DATA, 2 AS TIPO_RECEITA, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
        TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
        TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
        TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
        TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
        TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
        TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TIPO_RETORNO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA, TOTAL_FUNDO_FOLHA, QTDE_FOLHA,
        NUMERO_ONLINE, TIPO_ATO, TOTAL_ISS, TOTAL_GERAL_COM_ISS
        FROM C_DIARIO_AUX_REC_DESP_DF_100(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
      UNION ALL
      SELECT DATA, 3 AS TIPO_RECEITA, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
        TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
        TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
        TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
        TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
        TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
        TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TIPO_RETORNO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA, TOTAL_FUNDO_FOLHA, QTDE_FOLHA,
        NUMERO_ONLINE, TIPO_ATO, TOTAL_ISS, TOTAL_GERAL_COM_ISS
        FROM C_DIARIO_AUX_REC_DESP_DF_CANC(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
      ORDER BY 1, 2, 3
      INTO :DATA, :VSEQ, :NUMERO_PROTOCOLO, :SISTEMA_ID, :ID, :DATA_HORA, :TIPO_PROTOCOLO, :NATUREZA, :DESCRICAO,
        :TOTAL_EMOLUMENTO, :TOTAL_TAXA_JUDICIARIA, :TOTAL_FUNDO, :TOTAL_DESPESA,
        :TOTAL_BRUTO, :TOTAL_DESCONTO, :TOTAL_COMPENSADO, :QTDE, :TOTAL_EMOLUMENTO_REG, :TOTAL_TAXA_REG,
        :TOTAL_FUNDO_REG, :QTDE_REG, :TOTAL_EMOLUMENTO_AV, :TOTAL_TAXA_AV, :TOTAL_FUNDO_AV, :QTDE_AV,
        :TOTAL_EMOLUMENTO_CERT, :TOTAL_TAXA_CERT, :TOTAL_FUNDO_CERT, :QTDE_CERT, :TOTAL_EMOLUMENTO_BUSCA,
        :TOTAL_TAXA_BUSCA, :TOTAL_FUNDO_BUSCA, :QTDE_BUSCA, :TOTAL_EMOLUMENTO_REVAL, :TOTAL_TAXA_REVAL,
        :TOTAL_FUNDO_REVAL, :QTDE_REVAL, :MES, :ANO, :TIPO_RETORNO, :TOTAL_EMOLUMENTO_FOLHA, :TOTAL_TAXA_FOLHA, :TOTAL_FUNDO_FOLHA, :QTDE_FOLHA,
        :NUMERO_ONLINE, :TIPO_ATO, :TOTAL_ISS, :TOTAL_GERAL_COM_ISS DO
      BEGIN
        SUSPEND;
      END
    end
  end
  else
  begin
    FOR SELECT DATA, 1 AS TIPO_RECEITA, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
      TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
      TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
      TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
      TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
      TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
      TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TIPO_RETORNO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA, TOTAL_FUNDO_FOLHA, QTDE_FOLHA,
      NUMERO_ONLINE, TIPO_ATO, TOTAL_ISS, TOTAL_GERAL_COM_ISS
      FROM C_DIARIO_AUX_REC_DESP_DF_REG(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
    UNION ALL
    SELECT DATA, 2 AS TIPO_RECEITA, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
      TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
      TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
      TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
      TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
      TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
      TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TIPO_RETORNO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA, TOTAL_FUNDO_FOLHA, QTDE_FOLHA,
      NUMERO_ONLINE, TIPO_ATO, TOTAL_ISS, TOTAL_GERAL_COM_ISS
      FROM C_DIARIO_AUX_REC_DESP_DF_100(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
    UNION ALL
    SELECT DATA, 3 AS TIPO_RECEITA, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
      TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
      TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
      TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
      TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
      TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
      TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TIPO_RETORNO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA, TOTAL_FUNDO_FOLHA, QTDE_FOLHA,
      NUMERO_ONLINE, TIPO_ATO, TOTAL_ISS, TOTAL_GERAL_COM_ISS
      FROM C_DIARIO_AUX_REC_DESP_DF_CANC(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
    UNION ALL
    SELECT DATA, 4 AS TIPO_RECEITA, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
      TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
      TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
      TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
      TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
      TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
      TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TIPO_RETORNO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA, TOTAL_FUNDO_FOLHA, QTDE_FOLHA,
      NUMERO_ONLINE, TIPO_ATO, TOTAL_ISS, TOTAL_GERAL_COM_ISS
      FROM C_DIARIO_AUX_REC_DESP_DF_CERT(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
    UNION ALL
    SELECT DATA, 5 AS TIPO_RECEITA, NUMERO_PROTOCOLO, SISTEMA_ID, ID, DATA_HORA, TIPO_PROTOCOLO, NATUREZA, DESCRICAO,
      TOTAL_EMOLUMENTO, TOTAL_TAXA_JUDICIARIA, TOTAL_FUNDO, TOTAL_DESPESA,
      TOTAL_BRUTO, TOTAL_DESCONTO, TOTAL_COMPENSADO, QTDE, TOTAL_EMOLUMENTO_REG, TOTAL_TAXA_REG,
      TOTAL_FUNDO_REG, QTDE_REG, TOTAL_EMOLUMENTO_AV, TOTAL_TAXA_AV, TOTAL_FUNDO_AV, QTDE_AV,
      TOTAL_EMOLUMENTO_CERT, TOTAL_TAXA_CERT, TOTAL_FUNDO_CERT, QTDE_CERT, TOTAL_EMOLUMENTO_BUSCA,
      TOTAL_TAXA_BUSCA, TOTAL_FUNDO_BUSCA, QTDE_BUSCA, TOTAL_EMOLUMENTO_REVAL, TOTAL_TAXA_REVAL,
      TOTAL_FUNDO_REVAL, QTDE_REVAL, MES, ANO, TIPO_RETORNO, TOTAL_EMOLUMENTO_FOLHA, TOTAL_TAXA_FOLHA, TOTAL_FUNDO_FOLHA, QTDE_FOLHA,
      NUMERO_ONLINE, TIPO_ATO, TOTAL_ISS, TOTAL_GERAL_COM_ISS
      FROM C_DIARIO_AUX_REC_DESP_DF_DESP(:V_DATA_INI,:V_DATA_FIM, :VP_PROTOCOLO_ID)
    ORDER BY 1, 2, 3
    INTO :DATA, :VSEQ, :NUMERO_PROTOCOLO, :SISTEMA_ID, :ID, :DATA_HORA, :TIPO_PROTOCOLO, :NATUREZA, :DESCRICAO,
      :TOTAL_EMOLUMENTO, :TOTAL_TAXA_JUDICIARIA, :TOTAL_FUNDO, :TOTAL_DESPESA,
      :TOTAL_BRUTO, :TOTAL_DESCONTO, :TOTAL_COMPENSADO, :QTDE, :TOTAL_EMOLUMENTO_REG, :TOTAL_TAXA_REG,
      :TOTAL_FUNDO_REG, :QTDE_REG, :TOTAL_EMOLUMENTO_AV, :TOTAL_TAXA_AV, :TOTAL_FUNDO_AV, :QTDE_AV,
      :TOTAL_EMOLUMENTO_CERT, :TOTAL_TAXA_CERT, :TOTAL_FUNDO_CERT, :QTDE_CERT, :TOTAL_EMOLUMENTO_BUSCA,
      :TOTAL_TAXA_BUSCA, :TOTAL_FUNDO_BUSCA, :QTDE_BUSCA, :TOTAL_EMOLUMENTO_REVAL, :TOTAL_TAXA_REVAL,
      :TOTAL_FUNDO_REVAL, :QTDE_REVAL, :MES, :ANO, :TIPO_RETORNO, :TOTAL_EMOLUMENTO_FOLHA, :TOTAL_TAXA_FOLHA, :TOTAL_FUNDO_FOLHA, :QTDE_FOLHA,
      :NUMERO_ONLINE, :TIPO_ATO, :TOTAL_ISS, :TOTAL_GERAL_COM_ISS  DO
    BEGIN
      SUSPEND;
    END
  END
END ^

ALTER PROCEDURE C_DIARIO_AUX_RECEITA_DESPESA_GO (V_DATA_INI DATE,
V_DATA_FIM DATE,
V_SELOS_ANTIGO VARCHAR(1) CHARACTER SET ISO8859_1 = 'N')
RETURNS (VALOR_PAGO NUMERICO,
APRESENTANTE VARCHAR_260,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(100) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(2000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_ISS NUMERIC(18, 2),
TOTAL_TERCEIRO NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
QTDE NUMERIC(18, 2),
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
STATUS VARCHAR_060)
AS 
declare variable V_FORNECEDOR_ID NUMERICO;
declare variable V_FORNECEDOR VARCHAR_120;
declare variable V_VALOR_EMOLUMENTO numeric(18,4);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(18,4);
declare variable V_VALOR_FUNDO numeric(18,4);
declare variable V_TIPO_COBRANCA varchar(10);
declare variable V_DESCRICAO varchar(2000);
declare variable V_ATO_TIPO_ID integer;
declare variable V_DESCRICAO2 varchar(2000);
declare variable V_QTDE2 numeric(18,4);
declare variable V_QTDE_REGISTRO integer;
declare variable V_QTDE_AVERBACAO integer;
declare variable V_ORIGEM_PEDIDO varchar(1);
declare variable V_TIPO_DESPESA varchar(1);
declare variable V_REPASSE varchar(20);
declare variable V_DATA_PARAM_NOVO_SELO date;
declare variable V_USAR_ANTIGO varchar(1);
declare variable V_DATA_VAR varchar(20);
BEGIN
  --INICIO REGISTRO DE IMOVEIS
  --REGISTRO DE IMOVEIS - SELECIONAR PROTOCOLADOS - ESCRITURACAO DE 25%
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_TERCEIRO = 0;
  TOTAL_BRUTO = 0;

  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;

  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;

  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;

  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;

  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;

  TOTAL_DESPESA = 0;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'DATA_SELO_NOVO', 5)
  INTO :V_DATA_VAR;

   V_USAR_ANTIGO = 'N';

   IF (((EXTRACT(MONTH FROM :V_DATA_INI) <= LEFT(V_DATA_VAR,2))
  AND (EXTRACT(YEAR FROM :V_DATA_INI) <= right(V_DATA_VAR,4))) or
  ((EXTRACT(MONTH FROM :V_DATA_INI) <> LEFT(V_DATA_VAR,2))
  AND (EXTRACT(YEAR FROM :V_DATA_INI) <= right(V_DATA_VAR,4)))      ) THEN
  BEGIN
    V_USAR_ANTIGO = 'S';
  END

  if (coalesce(:V_USAR_ANTIGO,'') = 'S') then
  begin
     --SELECIONAR PROTOCOLOS
      FOR  SELECT SISTEMA_ID,
                1,
                TIPO_PROTOCOLO,
                CASE TRIM(NUMERO_PROTOCOLO) WHEN ''
                THEN 0 ELSE  NUMERO_PROTOCOLO
                END AS NUMERO_PROTOCOLO,
                DATA_PROTOCOLO,
                natureza,
                DESCRICAO,
                '2',
                COALESCE(TOTAL_EMOLUMENTO,0),
                COALESCE(TAXA_JUDICIAIRA,0),
                COALESCE(FUNDOS_ESTADUAIS,0),
                QUANTIDADE,
                0,
                '2',
                DATA_PROTOCOLO,
                1,
                VALOR_ISS,
                EXTRACT(MONTH FROM DATA_PROTOCOLO),
                EXTRACT(YEAR FROM DATA_PROTOCOLO)
          FROM c_diario_auxiliar_receita(:V_DATA_INI, :V_DATA_FIM, 'N', :V_USAR_ANTIGO)
          INTO :sistema_id, :V_QTDE_AVERBACAO, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA,
            :NATUREZA,:V_DESCRICAO, :V_TIPO_COBRANCA, :total_emolumento,:total_taxa_judiciaria,:total_fundo,
             :id, :V_QTDE_REGISTRO,   :V_ORIGEM_PEDIDO, :DATA_HORA, :tipo_retorno, :TOTAL_ISS, :MES, :ANO DO
              BEGIN
               -- V_DESCRICAO = ' '||REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA;
                DESCRICAO = :V_DESCRICAO;
                SUSPEND;
              END

     --SELECIONAR PROTOCOLOS
      FOR  SELECT SISTEMA_ID,
                1,
                TIPO_PROTOCOLO,
                CASE TRIM(NUMERO_PROTOCOLO) WHEN ''
                THEN 0 ELSE  NUMERO_PROTOCOLO
                END AS NUMERO_PROTOCOLO,
                DATA_PROTOCOLO,
                natureza,
                DESCRICAO,
                '2',
                COALESCE(TOTAL_EMOLUMENTO,0),
                COALESCE(TAXA_JUDICIAIRA,0),
                COALESCE(FUNDOS_ESTADUAIS,0),
                QUANTIDADE,
                0,
                '2',
                DATA_PROTOCOLO,
                1,
                VALOR_ISS,
                EXTRACT(MONTH FROM DATA_PROTOCOLO),
                EXTRACT(YEAR FROM DATA_PROTOCOLO)
          FROM c_diario_auxiliar_receita(:V_DATA_INI, :V_DATA_FIM, 'N', 'N')
          INTO :sistema_id, :V_QTDE_AVERBACAO, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA,
            :NATUREZA,:V_DESCRICAO, :V_TIPO_COBRANCA, :total_emolumento,:total_taxa_judiciaria,:total_fundo,
             :id, :V_QTDE_REGISTRO,   :V_ORIGEM_PEDIDO, :DATA_HORA, :tipo_retorno, :TOTAL_ISS, :MES, :ANO DO
              BEGIN
               -- V_DESCRICAO = ' '||REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA;
                DESCRICAO = :V_DESCRICAO;
                SUSPEND;
              END
   END
   ELSE
   BEGIN
     --SELECIONAR PROTOCOLOS
      FOR  SELECT SISTEMA_ID,
                1,
                TIPO_PROTOCOLO,
                CASE TRIM(NUMERO_PROTOCOLO) WHEN ''
                THEN 0 ELSE  NUMERO_PROTOCOLO
                END AS NUMERO_PROTOCOLO,
                DATA_PROTOCOLO,
                natureza,
                DESCRICAO,
                '2',
                COALESCE(TOTAL_EMOLUMENTO,0),
                COALESCE(TAXA_JUDICIAIRA,0),
                COALESCE(FUNDOS_ESTADUAIS,0),
                QUANTIDADE,
                0,
                '2',
                DATA_PROTOCOLO,
                1,
                VALOR_ISS,
                EXTRACT(MONTH FROM DATA_PROTOCOLO),
                EXTRACT(YEAR FROM DATA_PROTOCOLO)
          FROM c_diario_auxiliar_receita(:V_DATA_INI, :V_DATA_FIM, 'N', :V_USAR_ANTIGO)
          INTO :sistema_id, :V_QTDE_AVERBACAO, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA,
            :NATUREZA,:V_DESCRICAO, :V_TIPO_COBRANCA, :total_emolumento,:total_taxa_judiciaria,:total_fundo,
             :id, :V_QTDE_REGISTRO,   :V_ORIGEM_PEDIDO, :DATA_HORA, :tipo_retorno, :TOTAL_ISS, :MES, :ANO DO
              BEGIN
               -- V_DESCRICAO = ' '||REPLACE(:NUMERO_PROTOCOLO, '.00', '') ||' - '||:NATUREZA;
                DESCRICAO = :V_DESCRICAO;
                SUSPEND;
              END
   END
  --INICIO DESPESAS
  FOR SELECT 1,case trim(CI.DESCRICAO) when ''
               then '0'
               else trim(CI.DESCRICAO)
               end as descricao,
        COALESCE(CI.VALOR_PAGO,0),
        CAST(CI.DATA_PAGAMENTO AS DATE),         
        CS.REPASSE,
        CI.DATA_PAGAMENTO,
        EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
        EXTRACT(YEAR FROM CI.DATA_PAGAMENTO),
        CF.NOME,
        CI.FORNECEDOR_ID
      FROM C_CAIXA_ITEM CI
      left join  C_CAIXA_SERVICO CS
      on  CI.CAIXA_SERVICO_ID = CS.CAIXA_SERVICO_ID
      left join  C_FORNECEDOR CF
      on CF.FORNECEDOR_ID = CI.FORNECEDOR_ID
      WHERE CS.TIPO_TRANSACAO = 'D'
      AND CS.EMITIR_RELATORIO = 'S'
      AND CS.SITUACAO = 'A'
      AND CI.DATA_PAGAMENTO BETWEEN CAST(:V_DATA_INI AS TIMESTAMP) 
                                AND CAST(:V_DATA_FIM AS TIMESTAMP)+ 0.9999 
      ORDER BY CI.DATA_PAGAMENTO     
      INTO :id,:DESCRICAO, :TOTAL_DESPESA, :DATA,  :V_REPASSE,
      :DATA_HORA, :MES, :ANO, :V_FORNECEDOR, :V_FORNECEDOR_ID DO
  BEGIN   
    IF (:V_REPASSE = 'S') THEN
    BEGIN
      V_TIPO_DESPESA = 'R';
    END
    ELSE
    BEGIN
      V_TIPO_DESPESA = 'D';
    END 
    IF (:V_TIPO_DESPESA = 'R') THEN -- REPASSE
    BEGIN
      TIPO_RETORNO = 888;
    END
    ELSE --DESPESA
    BEGIN
      TIPO_RETORNO = 777;
    END
    if (COALESCE(:V_FORNECEDOR_ID,'') <> '') then
    BEGIN
     DESCRICAO = :V_FORNECEDOR||' - '||:DESCRICAO;
    END
    SISTEMA_ID = :TIPO_RETORNO;
    TIPO_PROTOCOLO = '';
    NUMERO_PROTOCOLO = 0;
    NATUREZA = '';
    TOTAL_EMOLUMENTO = 0;
    TOTAL_FUNDO = 0;
    total_taxa_judiciaria = 0;
   TOTAL_ISS = 0;
    SUSPEND;
  END    
  --FIM DAS DESPESAS
  
END ^

ALTER PROCEDURE C_DIARIO_AUX_REC_DESPESA_DF_NEW (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_TIPO_PROTOCOLO VARCHAR(3) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (SISTEMA_ID INTEGER,
PEDIDO_ID INTEGER,
PROTOCOLO_ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
DATA_PROTOCOLO TIMESTAMP,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
NATUREZA_TITULO_ID INTEGER,
DESCRICAO_NATUREZA VARCHAR(260) CHARACTER SET ISO8859_1,
EMOLUMENTO_ID INTEGER,
DESCRICAO_EMOLUMENTO VARCHAR(260) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
QTDE INTEGER,
MES INTEGER,
ANO INTEGER,
ITEM_DF VARCHAR(10) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2),
