NATUREZA VARCHAR(260) CHARACTER SET ISO8859_1,
TIPO_LIVRO VARCHAR(3) CHARACTER SET ISO8859_1,
ITEM INTEGER,
LETRA VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
declare variable VSEQ INTEGER;
BEGIN
  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    for select SISTEMA_ID, PEDIDO_ID, PROTOCOLO_ID, DATA_ANDAMENTO AS DATA, DATA_HORA_ANDAMENTO AS DATA_HORA, TIPO_PROTOCOLO ,
