          emolumento_id, descricao_emolumento, TOTAL_EMOLUMENTO, TOTAL_FUNDO, TOTAL_BRUTO, QTDE, MES, ANO,
          ITEM_DF, TOTAL_ISS, TOTAL_GERAL_COM_ISS, ORIGEM_PEDIDO, TIPO_ORIGEM_SITE, TIPO_COBRANCA, REGISTRADO_CANCELADO, 0 AS TOTAL_DESPESA,
          ITEM, LETRA
        from C_DIARIO_AUXILIAR_RECEITA_DF(null, null, :VP_TIPO_PROTOCOLO, :VP_PROTOCOLO_ID)
        order by data_andamento, tipo_protocolo, numero_protocolo
    into :SISTEMA_ID, :PEDIDO_ID, :PROTOCOLO_ID, :DATA, :DATA_HORA, :TIPO_PROTOCOLO ,
