      end
      else if (:ITEM_DF = '11c') then
      begin
        NATUREZA = :ITEM_DF||' - Cópia autêntica de documento arquivado utilizado para instruir ato';
      end
      else if (:ITEM_DF = '99a') then
      begin
        NATUREZA = 'Cancelamento de Prenotação de Registro';
      end
      else if (:ITEM_DF = '99b') then
      begin
        NATUREZA = 'Cancelamento de Prenotação de Averbação';
      end
      else if (:ITEM_DF = '99c') then
      begin
        NATUREZA = 'Cancelamento Outros';
      end
      else if (:ITEM_DF = '99r') then
      begin
        NATUREZA = 'Repasses';
        TIPO_LIVRO = 'R';
      end
      else if (:ITEM_DF = '99d') then
      begin
        NATUREZA = 'Despesas';
        TIPO_LIVRO = 'D';
      end

      suspend;
    end
  end
  else
  begin
    for select DATA_ANDAMENTO AS DATA, ITEM, LETRA, TIPO_PROTOCOLO, NUMERO_PROTOCOLO, SISTEMA_ID, PEDIDO_ID, PROTOCOLO_ID,
          DATA_HORA_ANDAMENTO AS DATA_HORA, DATA_PROTOCOLO, NUMERO_ONLINE,
          natureza_titulo_id, descricao_natureza, emolumento_id, descricao_emolumento, TOTAL_EMOLUMENTO, TOTAL_FUNDO,
          TOTAL_BRUTO, QTDE, MES, ANO, ITEM_DF, TOTAL_ISS, TOTAL_GERAL_COM_ISS, ORIGEM_PEDIDO, TIPO_ORIGEM_SITE,
          TIPO_COBRANCA, REGISTRADO_CANCELADO, 0 AS TOTAL_DESPESA
        from C_DIARIO_AUXILIAR_RECEITA_DF(:V_DATA_INI, :V_DATA_FIM, :VP_TIPO_PROTOCOLO, 0)
        UNION ALL
        select DATA_PAGAMENTO as data, ITEM, LETRA, '' as tipo_protocolo, 0 as numero_protocolo, 1 as sistema_id, 0 as pedido_id, 0 as protocolo_id,
          DATA_HORA_PAGAMENTO as data_hora, DATA_PAGAMENTO as data_protocolo, '' as numero_online,
          0 as natureza_titulo_id, descricao_despesa as descricao_natureza, 0 as emolumento_id, '' as descricao_emolumento, 0 as total_emolumento, 0 as total_fundo,
          0 as total_bruto, QTDE, MES, ANO, ITEM_DF, 0 as total_iss, 0 as total_geral_com_iss, '' as origem_pedido, '' as tipo_origem_site,
          '' as tipo_cobranca, '' as registrado_cancelado, TOTAL_DESPESA
        from C_DIARIO_AUXILIAR_DESPESA_DF(:V_DATA_INI, :V_DATA_FIM)
        order by 1,4
    into :DATA, :ITEM, :LETRA, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :SISTEMA_ID, :PEDIDO_ID, :PROTOCOLO_ID, :DATA_HORA,
          :DATA_PROTOCOLO, :NUMERO_ONLINE, :natureza_titulo_id, :descricao_natureza, :emolumento_id, :descricao_emolumento,
          :TOTAL_EMOLUMENTO, :TOTAL_FUNDO, :TOTAL_BRUTO, :QTDE, :MES, :ANO, :ITEM_DF, :TOTAL_ISS, :TOTAL_GERAL_COM_ISS,
          :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE, :TIPO_COBRANCA, :REGISTRADO_CANCELADO, :TOTAL_DESPESA do
    begin
      TIPO_LIVRO = 'C';
      if (:ITEM_DF = '1') then
      begin
        NATUREZA = :ITEM_DF||' - Registro de qualquer título ou documento com conteúdo econômico';
      end
      else if (:ITEM_DF = '2a') then
      begin
        NATUREZA = :ITEM_DF||' - Averbação de qualquer título ou documento com conteúdo econômico';
      end
      else if (:ITEM_DF = '2b') then
      begin
        NATUREZA = :ITEM_DF||' - Averbação sem conteúdo econômico';
      end
      else if (:ITEM_DF = '3a') then
      begin
        NATUREZA = :ITEM_DF||' - Registro de loteamento ou desmembramento urbano ou rural';
      end
      else if (:ITEM_DF = '3b') then
      begin
        NATUREZA = :ITEM_DF||' - Registro de loteamento - Intimação ou notificação';
      end
      else if (:ITEM_DF = '4') then
      begin
        NATUREZA = :ITEM_DF||' - Registro de incorporação imobiliária ou registro de instituição de condomínio';
      end
      else if (:ITEM_DF = '5a') then
      begin
        NATUREZA = :ITEM_DF||' - Registro de convenção de condomínio';
      end
      else if (:ITEM_DF = '5b') then
      begin
        NATUREZA = :ITEM_DF||' - Registro de pacto antenupcial no Livro 3';
      end
      else if (:ITEM_DF = '5c') then
      begin
        NATUREZA = :ITEM_DF||' - Abertura de matrícula de imóvel urbano ou rural';
      end
      else if (:ITEM_DF = '6') then
      begin
        NATUREZA = :ITEM_DF||' - Registro de cédula de crédito e hipoteca cedular, por imóvel';
      end
      else if (:ITEM_DF = '7a') then
      begin
        NATUREZA = :ITEM_DF||' - Procedimento para constituição em mora';
      end
      else if (:ITEM_DF = '7b') then
      begin
        NATUREZA = :ITEM_DF||' - Notificação do devedor';
      end
      else if (:ITEM_DF = '7c') then
      begin
        NATUREZA = :ITEM_DF||' - Averbação da consolidação da propriedade';
      end
      else if (:ITEM_DF = '8a') then
      begin
        NATUREZA = :ITEM_DF||' - Averbação de retificação';
      end
      else if (:ITEM_DF = '8b') then
      begin
        NATUREZA = :ITEM_DF||' - Expedição de notificação, por confrontante';
      end
      else if (:ITEM_DF = '9a') then
      begin
        NATUREZA = :ITEM_DF||' - Pelo primeiro recebimento e abertura de conta';
      end
      else if (:ITEM_DF = '9b') then
      begin
        NATUREZA = :ITEM_DF||' - Pelo recebimento de cada prestação seguinte';
      end
      else if (:ITEM_DF = '10a') then
      begin
        NATUREZA = :ITEM_DF||' - Certidão';
      end
      else if (:ITEM_DF = '10a1') then
      begin
        NATUREZA = :ITEM_DF||' - Certidão ONR';
      end
