      end
      else if (:ITEM_DF = '10c') then
      begin
        NATUREZA = :ITEM_DF||' - Folha excedente';
      end
      else if (:ITEM_DF = '11a') then
      begin
        NATUREZA = :ITEM_DF||' - Informação de banco de dados relativa aos atos praticados, fornecida eletronicamente';
      end
      else if (:ITEM_DF = '11b') then
      begin
        NATUREZA = :ITEM_DF||' - Cópia autêntica de documento arquivado utilizado para instruir ato';
      end
      else if (:ITEM_DF = '11c') then
      begin
        NATUREZA = :ITEM_DF||' - Cópia autêntica de documento arquivado utilizado para instruir ato';
      end
      else if (:ITEM_DF = '99a') then
      begin
        NATUREZA = 'Cancelamento de Prenotação de Registro';
      end
      else if (:ITEM_DF = '99b') then
      begin
