END ^

ALTER PROCEDURE C_DIARIO_AUX_REC_DESP_DF_100 (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TIPO_ATO VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
DECLARE VARIABLE V_TIPO_COBRANCA VARCHAR(1);
DECLARE VARIABLE V_DESCRICAO VARCHAR(200);
DECLARE VARIABLE V_ATO_TIPO_ID INTEGER;
DECLARE VARIABLE V_QTDE2 NUMERIC(18,4);
DECLARE VARIABLE V_QTDE_REGISTRO INTEGER;
DECLARE VARIABLE V_QTDE_AVERBACAO INTEGER;
DECLARE VARIABLE V_ORIGEM_PEDIDO VARCHAR(1);
DECLARE VARIABLE V_TIPO_ORIGEM_SITE VARCHAR(1);
DECLARE VARIABLE V_TIPO_DESPESA VARCHAR(3);
DECLARE VARIABLE V_REPASSE VARCHAR(1);
DECLARE VARIABLE V_PEDIDO_ID INTEGER;

DECLARE VARIABLE V_VALOR_EMOLUMENTO_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_EMOLUMENTO_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_EMOLUMENTO_REVAL NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_REVAL NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_REVAL NUMERIC(18,4);
declare variable V_CONSOLIDACAO VARCHAR(1);

declare variable V_PROTOCOLO_ID INTEGER;
declare variable V_VALOR_TEMP NUMERIC(18,2);
declare variable V_DATA_PROT_TEMP DATE;
declare variable V_VALOR_COMPENSADO NUMERIC(18,2);

declare variable V_VALOR_EMOLUMENTO_COMPENSADO NUMERIC(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO NUMERIC(18,2);

declare variable V_DIFERENCA_EMOL NUMERIC(18,2);
declare variable V_DIFERENCA_FUNDO NUMERIC(18,2);

declare variable V_NATUREZA_FORMAL VARCHAR(260);

declare variable V_SQL varchar(3000);

declare variable V_REG_AV VARCHAR(3);
BEGIN
  --INICIO REGISTRO DE IMOVEIS
  --SELECIONAR PROTOCOLOS CONSOLIDACAO DE ALIENACAO 100%
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_BRUTO = 0;
  TOTAL_DESCONTO = 0;

  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;

  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;

  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;

  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;

  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;

  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  TOTAL_DESPESA = 0;

  V_PEDIDO_ID = 0;

  TOTAL_ISS = 0;

  DESCRICAO = '';

  NUMERO_ONLINE = '';
  TIPO_ATO = '1-RECEITA';
  NATUREZA = 'PROCEDIMENTO DE CONSOLIDAÇÃO DE PROPRIEDADE FIDUCIÁRIA';

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = 'SELECT PR.PEDIDO_ID,
        PR.TIPO_PROTOCOLO,
        PR.NUMERO_ORDEM,
        CAST(PR.DATA AS DATE),
        PE.TIPO_COBRANCA,
        PR.DATA, COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
        COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
        EXTRACT(MONTH FROM PR.DATA),
        EXTRACT(YEAR FROM PR.DATA),
        PR.PROTOCOLO_ID,
        PE.VALOR_COMPENSADO,
        T.DESCRICAO,
        COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
        coalesce(PI.QUANTIDADE,0), coalesce(PI.QUANTIDADE_BUSCA,0), coalesce(PI.quantidade_folha_excedente,0),
        coalesce(PI.valor_emolumento,0), coalesce(PI.valor_fundo_ri,0), e.REG_AVERB, coalesce(PI.valor_iss,0)
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI,  R_TB_TITULO T, g_emolumento e, G_NATUREZA_TITULO NT
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.PEDIDO_ID = PI.PEDIDO_ID
      and pe.tb_titulo_id = t.tb_titulo_id
      AND PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID
      AND PI.emolumento_id = E.emolumento_id
      AND PR.TIPO_PROTOCOLO = ''1''
      AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||
      ' AND ((COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') = '||''''||'3'||''''||') or
        (COALESCE(NT.CONSOLIDACAO,'||''''||''''||') = '||''''||'S'||''''||'))
       ORDER BY PR.NUMERO_ORDEM ';
  end
  else
  begin
    V_SQL = 'SELECT PR.PEDIDO_ID,
        PR.TIPO_PROTOCOLO,
        PR.NUMERO_ORDEM,
        CAST(PR.DATA AS DATE),
        PE.TIPO_COBRANCA,
        PR.DATA, COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
        COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
        EXTRACT(MONTH FROM PR.DATA),
        EXTRACT(YEAR FROM PR.DATA),
        PR.PROTOCOLO_ID,
        PE.VALOR_COMPENSADO,
        T.DESCRICAO,
        COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
        coalesce(PI.QUANTIDADE,0), coalesce(PI.QUANTIDADE_BUSCA,0), coalesce(PI.quantidade_folha_excedente,0),
        coalesce(PI.valor_emolumento,0), coalesce(PI.valor_fundo_ri,0), e.REG_AVERB, coalesce(PI.valor_iss,0)
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, g_emolumento e, G_NATUREZA_TITULO NT
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.PEDIDO_ID = PI.PEDIDO_ID
      and pe.tb_titulo_id = t.tb_titulo_id
      AND PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID
      AND PI.emolumento_id = E.emolumento_id
      AND PR.TIPO_PROTOCOLO = ''1''
      AND PR.DATA BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS timestamp)
                      AND CAST('||''''||:V_DATA_FIM||''''||' AS timestamp) + 0.999
      AND ((COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') = '||''''||'3'||''''||') or
        (COALESCE(NT.CONSOLIDACAO,'||''''||''''||') = '||''''||'S'||''''||'))
       ORDER BY PR.NUMERO_ORDEM ';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA,
        :V_TIPO_COBRANCA, :DATA_HORA, :V_ORIGEM_PEDIDO, :V_TIPO_ORIGEM_SITE,
        :MES, :ANO, :V_PROTOCOLO_ID, :V_VALOR_COMPENSADO, :V_NATUREZA_FORMAL,
        :NUMERO_ONLINE, :qtde, :qtde_busca, :qtde_folha,
        :total_emolumento, :total_fundo, :V_REG_AV, :total_iss DO
  BEGIN
    QTDE_REG = 0;
    QTDE_AV = 0;

    TOTAL_EMOLUMENTO_REG = 0;
    TOTAL_TAXA_REG = 0;
    TOTAL_FUNDO_REG = 0;

    TOTAL_EMOLUMENTO_AV = 0;
    TOTAL_TAXA_AV = 0;
    TOTAL_FUNDO_AV = 0;

    IF (COALESCE(:V_REG_AV,'') = 'A') THEN
    BEGIN
      --V_DESCRICAO = 'Averbação [100%]-(Consolidação de Prop. Fiduciária)';
      QTDE_AV = :QTDE;
      TOTAL_EMOLUMENTO_AV = :total_emolumento;
      TOTAL_FUNDO_AV = :total_fundo;
    END
    ELSE
    BEGIN
      --V_DESCRICAO = 'Registro [100%]-(Consolidação de Prop. Fiduciária)';
      QTDE_REG = :QTDE;
      TOTAL_EMOLUMENTO_REG = :total_emolumento;
      TOTAL_FUNDO_REG = :total_fundo;
    END

    SISTEMA_ID = 1;

    IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT) --> contabilizar 100%
    BEGIN
      TIPO_RETORNO = 7; --PRENOTACAO NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
    END
    ELSE
    BEGIN
      TIPO_RETORNO = 8; --PRENOTACAO ALIENACAO FIDUCIARIA (Balcão) (100%)
    END

    IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
    BEGIN
      TOTAL_EMOLUMENTO = 0;
      TOTAL_TAXA_JUDICIARIA = 0;
      TOTAL_FUNDO = 0;
      TOTAL_BRUTO = 0;
      TOTAL_DESCONTO = 0;

      --V_DESCRICAO = :V_DESCRICAO || ' - (ISENTO)';

      TOTAL_EMOLUMENTO_REG = 0;
      TOTAL_TAXA_REG = 0;
      TOTAL_FUNDO_REG = 0;

      TOTAL_EMOLUMENTO_AV = 0;
      TOTAL_TAXA_AV = 0;
      TOTAL_FUNDO_AV = 0;

      TOTAL_ISS = 0;
    END
    ELSE
    BEGIN
      IF (:TOTAL_EMOLUMENTO < 0) THEN
      BEGIN
        TOTAL_EMOLUMENTO = 0;
      END
      TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO;
      TOTAL_GERAL_COM_ISS = :TOTAL_BRUTO + :TOTAL_ISS;
      IF (:TOTAL_EMOLUMENTO_REG < 0) THEN
      BEGIN
        TOTAL_EMOLUMENTO_REG = 0;
      END
    END
    --DESCRICAO = :V_DESCRICAO;
    SUSPEND;
    V_PEDIDO_ID = :ID;
  END
  --FIM REGISTRO DE IMOVEIS
END ^

ALTER PROCEDURE C_DIARIO_AUX_REC_DESP_DF_25 (V_DATA_INI DATE,
V_DATA_FIM DATE)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_ISS NUMERIC(18, 2),
TOTAL_TERCEIRO NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER)
AS 
DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL NUMERIC(18,4);

DECLARE VARIABLE V_VALOR_EMOLUMENTO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL_REG NUMERIC(18,4);

DECLARE VARIABLE V_VALOR_EMOLUMENTO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL_AV NUMERIC(18,4);

DECLARE VARIABLE V_TIPO_COBRANCA VARCHAR(1);
DECLARE VARIABLE V_DESCRICAO VARCHAR(200);
DECLARE VARIABLE V_ATO_TIPO_ID INTEGER;
DECLARE VARIABLE V_DESCRICAO2 VARCHAR(200);
DECLARE VARIABLE V_QTDE2 NUMERIC(18,4);
DECLARE VARIABLE V_QTDE_REGISTRO INTEGER;
DECLARE VARIABLE V_QTDE_AVERBACAO INTEGER;
DECLARE VARIABLE V_ORIGEM_PEDIDO VARCHAR(1);
DECLARE VARIABLE V_TIPO_ORIGEM_SITE VARCHAR(1);
DECLARE VARIABLE V_TIPO_DESPESA VARCHAR(3);
DECLARE VARIABLE V_REPASSE VARCHAR(1);
DECLARE VARIABLE V_PEDIDO_ID INTEGER;
DECLARE VARIABLE V_TIPO_CONTABILIZACAO_PED_CERTIDAO VARCHAR(1);


DECLARE VARIABLE V_VALOR_EMOLUMENTO_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_EMOLUMENTO_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_EMOLUMENTO_REVAL NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_REVAL NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_REVAL NUMERIC(18,4);
declare variable V_RETORNAR VARCHAR(1);
declare variable V_CONSOLIDACAO VARCHAR(1);

declare variable V_MODELO_DIARIO_AUXILIAR VARCHAR(3);

declare variable V_PROTOCOLO_ID INTEGER;
declare variable V_VALOR_TEMP NUMERIC(18,2);
declare variable V_DATA_PROT_TEMP DATE;
declare variable V_VALOR_COMPENSADO NUMERIC(18,2);

declare variable V_VALOR_EMOLUMENTO_COMPENSADO NUMERIC(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO NUMERIC(18,2);

declare variable V_REPETIR_DESCRICAO VARCHAR(1);
declare variable V_DESCRICAO_SERVICO VARCHAR(60);
declare variable V_CARTORIO_NUMERO VARCHAR(3);

declare variable V_DIFERENCA_EMOL NUMERIC(18,2);
declare variable V_DIFERENCA_FUNDO NUMERIC(18,2);

declare variable V_NATUREZA_FORMAL VARCHAR(260);

BEGIN
  --INICIO REGISTRO DE IMOVEIS

  --DESATUALIZADO

/*
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_TERCEIRO = 0;
  TOTAL_BRUTO = 0;
  TOTAL_DESCONTO = 0;


  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;

  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;

  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;

  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;

  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;

  TOTAL_DESPESA = 0;

  --BUSCAR NUMERO DO CARTORIO
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'CARTORIO'
  AND C.NOME = 'CARTORIO_NUMERO'
  INTO :V_CARTORIO_NUMERO;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('CAIXA','DADP','TIPO_CONTABILIZACAO_PED_CERTIDAO',1)
  INTO :V_TIPO_CONTABILIZACAO_PED_CERTIDAO;

  --PEGAR MODELO DO DIÁRIO AUXILIAR - O PADRAO ATUAL É "1"
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('CAIXA','DADP','MODELO_DIARIO_AUXILIAR',1)
  INTO :V_MODELO_DIARIO_AUXILIAR;


  -- REGISTRO DE IMOVEIS - SELECIONAR PROTOCOLADOS - ESCRITURACAO DE 25%
  V_VALOR_EMOLUMENTO_COMPENSADO = 0;
  V_VALOR_FUNDO_COMPENSADO = 0;
  V_PEDIDO_ID = 0;
  ORDEM = 0;
  FOR SELECT PR.PEDIDO_ID,
        PR.TIPO_PROTOCOLO,
        PR.NUMERO_ORDEM,
        CAST(PR.DATA AS DATE),
        PE.TIPO_COBRANCA,
        PR.DATA, COALESCE(PE.ORIGEM_PEDIDO,''),
        COALESCE(PE.TIPO_ORIGEM_SITE,''),
        EXTRACT(MONTH FROM PR.DATA),
        EXTRACT(YEAR FROM PR.DATA),
        PR.PROTOCOLO_ID,
        PE.VALOR_COMPENSADO
      FROM R_PROTOCOLO PR, R_PEDIDO PE
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PR.TIPO_PROTOCOLO = '1'
      AND PR.DATA BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)
                      AND CAST(:V_DATA_FIM AS TIMESTAMP)+ 0.999
      ORDER BY PR.NUMERO_ORDEM
      INTO :ID, :TIPO_PROTOCOLO, :NUMERO_PROTOCOLO, :DATA,
        :V_TIPO_COBRANCA, :DATA_HORA, :V_ORIGEM_PEDIDO, :V_TIPO_ORIGEM_SITE,
        :MES, :ANO, :V_PROTOCOLO_ID, :V_VALOR_COMPENSADO DO
  BEGIN
    ORDEM = :ORDEM + 1;
    V_RETORNAR = 'S';
    V_DESCRICAO = '';
    IF (:ID <> :V_PEDIDO_ID) THEN
    BEGIN
      SELECT (COALESCE(TOTAL_EMOLUMENTO,0)) AS TOTAL_EMOLUMENTO,
        (COALESCE(TOTAL_TAXA,0)) AS TOTAL_TAXA_JUDICIARIA,
        (COALESCE(TOTAL_FUNDO_RI,0)) AS TOTAL_FUNDO,
        (COALESCE(TOTAL_DESCONTO,0)) AS TOTAL_DESCONTO,

        (COALESCE(TOTAL_EMOLUMENTO_REG,0)) AS TOTAL_EMOLUMENTO_REG,
        (COALESCE(TOTAL_TAXA_REG,0)) AS TOTAL_TAXA_REG,
        (COALESCE(TOTAL_FUNDO_RI_REG,0)) AS TOTAL_FUNDO_REG,
        (COALESCE(TOTAL_DESCONTO_REG,0)) AS TOTAL_DESCONTO_REG,

        (COALESCE(TOTAL_EMOLUMENTO_AV,0)) AS TOTAL_EMOLUMENTO_AV,
        (COALESCE(TOTAL_TAXA_AV,0)) AS TOTAL_TAXA_AV,
        (COALESCE(TOTAL_FUNDO_RI_AV,0)) AS TOTAL_FUNDO_AV,
        (COALESCE(TOTAL_DESCONTO_AV,0)) AS TOTAL_DESCONTO_AV,

        COALESCE(QUANTIDADE_REGISTRO,0) AS QTDE_REGISTRO,
        COALESCE(QUANTIDADE_AVERBACAO,0) AS QTDE_AVERBACAO
      FROM R_TOTAL_PEDIDO(:ID)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO, :V_VALOR_DESCONTO,
        :V_VALOR_EMOLUMENTO_REG, :V_VALOR_TAXA_REG, :V_VALOR_FUNDO_REG, :V_VALOR_DESCONTO_REG,
        :V_VALOR_EMOLUMENTO_AV, :V_VALOR_TAXA_AV, :V_VALOR_FUNDO_AV, :V_VALOR_DESCONTO_AV,
        :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO;

      --CORRECAO
      V_VALOR_TOTAL = (:V_VALOR_EMOLUMENTO+:V_VALOR_TAXA_JUDICIARIA+:V_VALOR_FUNDO) - :V_VALOR_DESCONTO;
      V_VALOR_TOTAL_REG = (:V_VALOR_EMOLUMENTO_REG+:V_VALOR_TAXA_REG+:V_VALOR_FUNDO_REG) - :V_VALOR_DESCONTO_REG;
      V_VALOR_TOTAL_AV = (:V_VALOR_EMOLUMENTO_AV+:V_VALOR_TAXA_AV+:V_VALOR_FUNDO_AV) - :V_VALOR_DESCONTO_AV;

      V_VALOR_EMOLUMENTO = cast((:V_VALOR_TOTAL * 0.9346) as numeric(18,2));
      V_VALOR_FUNDO = :V_VALOR_TOTAL - :V_VALOR_EMOLUMENTO;
      V_VALOR_TAXA_JUDICIARIA = 0;
      V_VALOR_EMOLUMENTO_REG = cast((:V_VALOR_TOTAL_REG * 0.9346) as numeric(18,2));
      V_VALOR_FUNDO_REG = :V_VALOR_TOTAL_REG - :V_VALOR_EMOLUMENTO_REG;
      V_VALOR_TAXA_REG = 0;
      V_VALOR_EMOLUMENTO_AV = cast((:V_VALOR_TOTAL_AV * 0.9346) as numeric(18,2));
      V_VALOR_FUNDO_AV = :V_VALOR_TOTAL_AV - :V_VALOR_EMOLUMENTO_AV;
      V_VALOR_TAXA_AV = 0;
      --FINAL CORRECAO

      TOTAL_ISS = 0;
      SISTEMA_ID = 1;

      V_CONSOLIDACAO = '';
      SELECT FIRST 1 N.DESCRICAO, N.CONSOLIDACAO
      FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
      WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
      AND I.PEDIDO_ID = :ID
      ORDER BY SEQUENCIA
      INTO :V_NATUREZA_FORMAL, :V_CONSOLIDACAO;

      V_VALOR_TEMP = 0;
      if (COALESCE(:V_MODELO_DIARIO_AUXILIAR,'') = '2') then  -- se for "MODELO 2" pega valor do caixa.
      begin
        if ((:V_TIPO_ORIGEM_SITE = '3') OR (COALESCE(:V_CONSOLIDACAO,'') = 'S')) THEN --se for notificacao de alienacao fiduciaria eridft
        begin
          V_RETORNAR = 'N';
        END
        BEGIN
          V_RETORNAR = 'S';

          SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
          WHERE TIPO_SERVICO = :TIPO_PROTOCOLO
          AND CHAVE_SERVICO = :V_PROTOCOLO_ID
          AND TIPO_TRANSACAO = 'C'
          AND CAST(DATA_PAGAMENTO AS DATE) = CAST(:DATA AS DATE)
          INTO :V_VALOR_TEMP;

          V_VALOR_EMOLUMENTO = CAST((COALESCE(:V_VALOR_TEMP,0) * 0.9346) AS NUMERIC(18,2));
          V_VALOR_FUNDO = (:V_VALOR_TEMP - :V_VALOR_EMOLUMENTO);

          if (COALESCE(:V_VALOR_COMPENSADO,0) > 0) then
          BEGIN
            V_VALOR_EMOLUMENTO_COMPENSADO = CAST((COALESCE(:V_VALOR_COMPENSADO,0) * 0.9346) AS NUMERIC(18,2));
            V_VALOR_FUNDO_COMPENSADO = (:V_VALOR_COMPENSADO - :V_VALOR_EMOLUMENTO_COMPENSADO);
  
            V_VALOR_EMOLUMENTO = COALESCE(:V_VALOR_EMOLUMENTO,0) + V_VALOR_EMOLUMENTO_COMPENSADO;
            V_VALOR_FUNDO = COALESCE(:V_VALOR_FUNDO,0) + V_VALOR_FUNDO_COMPENSADO;
          END

          if ((:V_VALOR_EMOLUMENTO_REG + :V_VALOR_EMOLUMENTO_AV) > :V_VALOR_EMOLUMENTO) then
          begin
            if (:V_VALOR_EMOLUMENTO_REG > :V_VALOR_EMOLUMENTO) then
            begin
              V_VALOR_EMOLUMENTO_REG = :V_VALOR_EMOLUMENTO;
              V_VALOR_FUNDO_REG = :V_VALOR_FUNDO;
              V_VALOR_EMOLUMENTO_AV = 0;
              V_VALOR_FUNDO_AV = 0;
            end
            else
            begin
              V_VALOR_EMOLUMENTO_AV = :V_VALOR_EMOLUMENTO - :V_VALOR_EMOLUMENTO_REG;
              V_VALOR_FUNDO_AV = V_VALOR_FUNDO - V_VALOR_FUNDO_REG;
            end
          end
          else if ((:V_VALOR_EMOLUMENTO_REG + :V_VALOR_EMOLUMENTO_AV) < :V_VALOR_EMOLUMENTO) then
          begin
            V_DIFERENCA_EMOL = (:V_VALOR_EMOLUMENTO - (:V_VALOR_EMOLUMENTO_REG + :V_VALOR_EMOLUMENTO_AV));
            V_DIFERENCA_FUNDO = (:V_VALOR_FUNDO - (:V_VALOR_FUNDO_REG + :V_VALOR_FUNDO_AV));
            if (:V_VALOR_EMOLUMENTO_REG > 0) then
            begin
              V_VALOR_EMOLUMENTO_REG = :V_VALOR_EMOLUMENTO_REG + :V_DIFERENCA_EMOL;
              V_VALOR_FUNDO_REG = :V_VALOR_FUNDO_REG + :V_DIFERENCA_FUNDO;
            end
            else
            begin
              V_VALOR_EMOLUMENTO_AV = :V_VALOR_EMOLUMENTO_AV + :V_DIFERENCA_EMOL;
              V_VALOR_FUNDO_AV = :V_VALOR_FUNDO_AV + :V_DIFERENCA_FUNDO;
            end
          end
        end
      end
      IF ((:V_TIPO_ORIGEM_SITE = '3') OR (COALESCE(:V_CONSOLIDACAO,'') = 'S')) THEN --se for notificacao de alienacao fiduciaria eridft
      BEGIN
        V_RETORNAR = 'N';
      END
      ELSE
      BEGIN
        V_RETORNAR = 'S';
        V_DESCRICAO = 'Protocolo '||CAST(:NUMERO_PROTOCOLO AS VARCHAR(10))||' - [25%] - '||:V_NATUREZA_FORMAL;
        V_VALOR_EMOLUMENTO = CAST((:V_VALOR_EMOLUMENTO * 0.25) AS NUMERIC(14,2));
        V_VALOR_TAXA_JUDICIARIA = CAST((:V_VALOR_TAXA_JUDICIARIA * 0.25) AS NUMERIC(14,2));
        V_VALOR_FUNDO = CAST((:V_VALOR_FUNDO * 0.25) AS NUMERIC(14,2));
        V_VALOR_EMOLUMENTO_AV = CAST((:V_VALOR_EMOLUMENTO_AV * 0.25) AS NUMERIC(14,2));
        V_VALOR_TAXA_AV = CAST((:V_VALOR_TAXA_AV * 0.25) AS NUMERIC(14,2));
        V_VALOR_FUNDO_AV = CAST((:V_VALOR_FUNDO_AV * 0.25) AS NUMERIC(14,2));
        V_VALOR_EMOLUMENTO_REG = CAST((:V_VALOR_EMOLUMENTO_REG * 0.25) AS NUMERIC(14,2));
        V_VALOR_TAXA_REG = CAST((V_VALOR_TAXA_REG * 0.25) AS NUMERIC(14,2));
        V_VALOR_FUNDO_REG = CAST((V_VALOR_FUNDO_REG * 0.25) AS NUMERIC(14,2));

        --correcao de 1 centavo
        if ((:V_VALOR_EMOLUMENTO+:V_VALOR_TAXA_JUDICIARIA+:V_VALOR_FUNDO) <> (:V_VALOR_EMOLUMENTO_AV+:V_VALOR_TAXA_AV+:V_VALOR_FUNDO_AV+V_VALOR_EMOLUMENTO_REG+V_VALOR_TAXA_REG+V_VALOR_FUNDO_REG)) then
        BEGIN
          if (((:V_VALOR_EMOLUMENTO+:V_VALOR_TAXA_JUDICIARIA+:V_VALOR_FUNDO) - (:V_VALOR_EMOLUMENTO_AV+:V_VALOR_TAXA_AV+:V_VALOR_FUNDO_AV+V_VALOR_EMOLUMENTO_REG+V_VALOR_TAXA_REG+V_VALOR_FUNDO_REG)) = -0.01) then
          begin
            if (:V_VALOR_FUNDO_AV > 0) then
            begin
              V_VALOR_FUNDO_AV = :V_VALOR_FUNDO_AV - 0.01;
            end
            else
            begin
              V_VALOR_FUNDO_REG = :V_VALOR_FUNDO_REG - 0.01;
            end
          end
        END
      end

      IF (:V_QTDE_REGISTRO > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
      END
      IF (:V_QTDE_AVERBACAO > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
      END

      NATUREZA = 'Prenotação';

      QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
      QTDE_REG = COALESCE(:V_QTDE_REGISTRO,0);
      QTDE_AV = COALESCE(:V_QTDE_AVERBACAO,0);

      IF (:V_ORIGEM_PEDIDO = '2') THEN --ERIDFT
      BEGIN
        IF (:V_TIPO_ORIGEM_SITE = '1') THEN --PENHORA
        BEGIN
          TIPO_RETORNO = 2; --PRENOTACAO REG/AV (Penhora online) (25%)
        END
        ELSE IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT) --> contabilizar 100%
        BEGIN
          TIPO_RETORNO = 3; --PRENOTACAO NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
        END
        ELSE
        BEGIN
          TIPO_RETORNO = 1; --PRENOTACAO REG/AV (25%)
        END
      END
      ELSE --SOLICITADAS NO CARTORIO
      BEGIN
        if (COALESCE(:V_CONSOLIDACAO,'') = 'S') then
        begin
          TIPO_RETORNO = 10; --consolidação (balcão) (100%)
        end
        else
        begin
          TIPO_RETORNO = 1; --PRENOTACAO REG/AV (25%)
        end
      END

      IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO
      BEGIN
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        TOTAL_TERCEIRO = 0;
        TOTAL_BRUTO = 0;
        TOTAL_DESCONTO = 0;

        V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';

        TOTAL_EMOLUMENTO_REG = 0;
        TOTAL_TAXA_REG = 0;
        TOTAL_FUNDO_REG = 0;

        TOTAL_EMOLUMENTO_AV = 0;
        TOTAL_TAXA_AV = 0;
        TOTAL_FUNDO_AV = 0;
      END
      ELSE
      BEGIN
        TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
        IF (:TOTAL_EMOLUMENTO < 0) THEN
        BEGIN
          TOTAL_EMOLUMENTO = 0;
        END
        TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
        TOTAL_FUNDO = :V_VALOR_FUNDO;
        TOTAL_TERCEIRO = 0;
        TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO + :TOTAL_TERCEIRO;
        TOTAL_DESCONTO = :V_VALOR_DESCONTO;

        TOTAL_EMOLUMENTO_REG = :V_VALOR_EMOLUMENTO_REG;
        IF (:TOTAL_EMOLUMENTO_REG < 0) THEN
        BEGIN
          TOTAL_EMOLUMENTO_REG = 0;
        END
        TOTAL_TAXA_REG = :V_VALOR_TAXA_REG;
        TOTAL_FUNDO_REG = :V_VALOR_FUNDO_REG;

        TOTAL_EMOLUMENTO_AV = :V_VALOR_EMOLUMENTO_AV;
        IF (:TOTAL_EMOLUMENTO_AV < 0) THEN
        BEGIN
          TOTAL_EMOLUMENTO_AV = 0;
        END
        TOTAL_TAXA_AV = :V_VALOR_TAXA_AV;
        TOTAL_FUNDO_AV = :V_VALOR_FUNDO_AV;
      END
      DESCRICAO = :V_DESCRICAO;
      if (COALESCE(:V_RETORNAR,'') = 'S') THEN
      begin
        SUSPEND;
      end
    END
    V_PEDIDO_ID = :ID;
  END -- FIM REGISTRO DE IMOVEIS - SELECIONAR PROTOCOLADOS - ESCRITURACAO DE 25%*/

END ^

ALTER PROCEDURE C_DIARIO_AUX_REC_DESP_DF_75 (V_DATA_INI DATE,
V_DATA_FIM DATE)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_ISS NUMERIC(18, 2),
TOTAL_TERCEIRO NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER)
AS 
DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL NUMERIC(18,4);

DECLARE VARIABLE V_VALOR_EMOLUMENTO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL_REG NUMERIC(18,4);

DECLARE VARIABLE V_VALOR_EMOLUMENTO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL_AV NUMERIC(18,4);

DECLARE VARIABLE V_TIPO_COBRANCA VARCHAR(1);
DECLARE VARIABLE V_DESCRICAO VARCHAR(200);
DECLARE VARIABLE V_ATO_TIPO_ID INTEGER;
DECLARE VARIABLE V_DESCRICAO2 VARCHAR(200);
DECLARE VARIABLE V_QTDE2 NUMERIC(18,4);
DECLARE VARIABLE V_QTDE_REGISTRO INTEGER;
DECLARE VARIABLE V_QTDE_AVERBACAO INTEGER;
DECLARE VARIABLE V_ORIGEM_PEDIDO VARCHAR(1);
DECLARE VARIABLE V_TIPO_ORIGEM_SITE VARCHAR(1);
DECLARE VARIABLE V_TIPO_DESPESA VARCHAR(3);
DECLARE VARIABLE V_REPASSE VARCHAR(1);
DECLARE VARIABLE V_PEDIDO_ID INTEGER;
DECLARE VARIABLE V_TIPO_CONTABILIZACAO_PED_CERTIDAO VARCHAR(1);


DECLARE VARIABLE V_VALOR_EMOLUMENTO_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_EMOLUMENTO_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_EMOLUMENTO_REVAL NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_REVAL NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_REVAL NUMERIC(18,4);
declare variable V_RETORNAR VARCHAR(1);
declare variable V_CONSOLIDACAO VARCHAR(1);

declare variable V_MODELO_DIARIO_AUXILIAR VARCHAR(3);

declare variable V_PROTOCOLO_ID INTEGER;
declare variable V_VALOR_TEMP NUMERIC(18,2);
declare variable V_DATA_PROT_TEMP DATE;
declare variable V_VALOR_COMPENSADO NUMERIC(18,2);

declare variable V_VALOR_EMOLUMENTO_COMPENSADO NUMERIC(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO NUMERIC(18,2);

declare variable V_REPETIR_DESCRICAO VARCHAR(1);
declare variable V_DESCRICAO_SERVICO VARCHAR(60);
declare variable V_CARTORIO_NUMERO VARCHAR(3);

declare variable V_DIFERENCA_EMOL NUMERIC(18,2);
declare variable V_DIFERENCA_FUNDO NUMERIC(18,2);

declare variable V_NATUREZA_FORMAL VARCHAR(260);
BEGIN
  --INICIO REGISTRO DE IMOVEIS

  --DESATUALIZADO

/*

  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_TERCEIRO = 0;
  TOTAL_BRUTO = 0;
  TOTAL_DESCONTO = 0;


  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;

  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;

  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;

  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;

  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;

  TOTAL_DESPESA = 0;

  --BUSCAR NUMERO DO CARTORIO
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'CARTORIO'
  AND C.NOME = 'CARTORIO_NUMERO'
  INTO :V_CARTORIO_NUMERO;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('CAIXA','DADP','TIPO_CONTABILIZACAO_PED_CERTIDAO',1)
  INTO :V_TIPO_CONTABILIZACAO_PED_CERTIDAO;

  --PEGAR MODELO DO DIÁRIO AUXILIAR - O PADRAO ATUAL É "1"
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('CAIXA','DADP','MODELO_DIARIO_AUXILIAR',1)
  INTO :V_MODELO_DIARIO_AUXILIAR;

  --SELECIONAR PROTOCOLOS REGISTRADOS DO RI 75%
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_TERCEIRO = 0;
  TOTAL_BRUTO = 0;
  TOTAL_DESCONTO = 0;

  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;

  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;

  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;

  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;

  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;

  TOTAL_DESPESA = 0;

  V_PEDIDO_ID = 0;
  ORDEM = 0;
  FOR SELECT DISTINCT CAST(A.DATA AS DATE),
        PR.NUMERO_ORDEM,
        PR.PEDIDO_ID,
        PR.TIPO_PROTOCOLO,
        T.DESCRICAO,
        PE.TIPO_COBRANCA,
        A.DATA, COALESCE(PE.ORIGEM_PEDIDO,''), COALESCE(PE.TIPO_ORIGEM_SITE,''), EXTRACT(MONTH FROM A.DATA), EXTRACT(YEAR FROM A.DATA)
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.TB_TITULO_ID = T.TB_TITULO_ID
      AND PE.PEDIDO_ID = A.PEDIDO_ID
      AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND PR.TIPO_PROTOCOLO = '1'
      AND (TA.TIPO = 'R')  --REGISTRADOS
      AND A.DATA BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)
                     AND CAST(:V_DATA_FIM AS TIMESTAMP)+ 0.9999
      AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
        WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
        AND A2.PEDIDO_ID = PE.PEDIDO_ID
        AND TA2.TIPO = 'R' --REGISTRADOS   --PARA PEGAR SOMENTE 1 ANDAMENTO DE REGISTRADO
        ORDER BY A2.ANDAMENTO_ID)
      ORDER BY 1,2
      INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO, :V_NATUREZA_FORMAL, :V_TIPO_COBRANCA, :DATA_HORA, :V_ORIGEM_PEDIDO, :V_TIPO_ORIGEM_SITE, :MES, :ANO DO
  BEGIN
    ORDEM = :ORDEM + 1;
    V_RETORNAR = 'S';
    V_DESCRICAO = '';
    IF (:ID <> :V_PEDIDO_ID) THEN
    BEGIN
      SELECT CAST((COALESCE(TOTAL_EMOLUMENTO,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_EMOLUMENTO,
        CAST((COALESCE(TOTAL_TAXA,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_TAXA_JUDICIARIA,
        CAST((COALESCE(TOTAL_FUNDO_RI,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_FUNDO,
        CAST((COALESCE(TOTAL_DESCONTO,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_DESCONTO,

        CAST((COALESCE(TOTAL_EMOLUMENTO_REG,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_EMOLUMENTO_REG,
        CAST((COALESCE(TOTAL_TAXA_REG,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_TAXA_REG,
        CAST((COALESCE(TOTAL_FUNDO_RI_REG,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_FUNDO_REG,
        CAST((COALESCE(TOTAL_DESCONTO_REG,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_DESCONTO_REG,

        CAST((COALESCE(TOTAL_EMOLUMENTO_AV,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_EMOLUMENTO_AV,
        CAST((COALESCE(TOTAL_TAXA_AV,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_TAXA_AV,
        CAST((COALESCE(TOTAL_FUNDO_RI_AV,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_FUNDO_AV,
        CAST((COALESCE(TOTAL_DESCONTO_AV,0) * 0.75) AS NUMERIC(18,2)) AS TOTAL_DESCONTO_AV,

        COALESCE(QUANTIDADE_REGISTRO,0) AS QTDE_REGISTRO,
        COALESCE(QUANTIDADE_AVERBACAO,0) AS QTDE_AVERBACAO
      FROM R_TOTAL_PEDIDO(:ID)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO, :V_VALOR_DESCONTO,
        :V_VALOR_EMOLUMENTO_REG, :V_VALOR_TAXA_REG, :V_VALOR_FUNDO_REG, :V_VALOR_DESCONTO_REG,
        :V_VALOR_EMOLUMENTO_AV, :V_VALOR_TAXA_AV, :V_VALOR_FUNDO_AV, :V_VALOR_DESCONTO_AV,
        :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO;

      --CORRECAO
      V_VALOR_TOTAL = (:V_VALOR_EMOLUMENTO+:V_VALOR_TAXA_JUDICIARIA+:V_VALOR_FUNDO) - :V_VALOR_DESCONTO;
      V_VALOR_TOTAL_REG = (:V_VALOR_EMOLUMENTO_REG+:V_VALOR_TAXA_REG+:V_VALOR_FUNDO_REG) - :V_VALOR_DESCONTO_REG;
      V_VALOR_TOTAL_AV = (:V_VALOR_EMOLUMENTO_AV+:V_VALOR_TAXA_AV+:V_VALOR_FUNDO_AV) - :V_VALOR_DESCONTO_AV;

      V_VALOR_EMOLUMENTO = cast((:V_VALOR_TOTAL * 0.9346) as numeric(18,2));
      V_VALOR_FUNDO = :V_VALOR_TOTAL - :V_VALOR_EMOLUMENTO;
      V_VALOR_TAXA_JUDICIARIA = 0;
      V_VALOR_EMOLUMENTO_REG = cast((:V_VALOR_TOTAL_REG * 0.9346) as numeric(18,2));
      V_VALOR_FUNDO_REG = :V_VALOR_TOTAL_REG - :V_VALOR_EMOLUMENTO_REG;
      V_VALOR_TAXA_REG = 0;
      V_VALOR_EMOLUMENTO_AV = cast((:V_VALOR_TOTAL_AV * 0.9346) as numeric(18,2));
      V_VALOR_FUNDO_AV = :V_VALOR_TOTAL_AV - :V_VALOR_EMOLUMENTO_AV;
      V_VALOR_TAXA_AV = 0;
      --FINAL CORRECAO

      --correcao de 1 centavo
      if ((:V_VALOR_EMOLUMENTO+:V_VALOR_TAXA_JUDICIARIA+:V_VALOR_FUNDO) <> (:V_VALOR_EMOLUMENTO_AV+:V_VALOR_TAXA_AV+:V_VALOR_FUNDO_AV+V_VALOR_EMOLUMENTO_REG+V_VALOR_TAXA_REG+V_VALOR_FUNDO_REG)) then
      BEGIN
        if (((:V_VALOR_EMOLUMENTO+:V_VALOR_TAXA_JUDICIARIA+:V_VALOR_FUNDO) - (:V_VALOR_EMOLUMENTO_AV+:V_VALOR_TAXA_AV+:V_VALOR_FUNDO_AV+V_VALOR_EMOLUMENTO_REG+V_VALOR_TAXA_REG+V_VALOR_FUNDO_REG)) = -0.01) then
        begin
          if (:V_VALOR_FUNDO_AV > 0) then
          begin
            V_VALOR_FUNDO_AV = :V_VALOR_FUNDO_AV - 0.01;
          end
          else
          begin
            V_VALOR_FUNDO_REG = :V_VALOR_FUNDO_REG - 0.01;
          end
        end
      END

      V_CONSOLIDACAO = '';
      SELECT FIRST 1 N.CONSOLIDACAO
      FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
      WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
      AND I.PEDIDO_ID = :ID
      ORDER BY SEQUENCIA
      INTO :V_CONSOLIDACAO;

      TOTAL_ISS = 0;
      SISTEMA_ID = 1;

      IF (:V_ORIGEM_PEDIDO = '2') THEN --ERIDFT
      BEGIN
        IF (:V_TIPO_ORIGEM_SITE = '1') THEN --PENHORA
        BEGIN
          TIPO_RETORNO = 5; --REGISTRO/AVERBACAO (Penhora online) (75%)
        END
        ELSE IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
        BEGIN
          --TIPO_RETORNO = 6; --REGISTRO/AVERBACAO ALIENACAO FIDUCIARIA (e-RIDFT) (75%)
          V_RETORNAR = 'N'; --NAO RETORNAR, POIS ESTA RETORNANDO OS 100% NA PRENOTACAO
        END
        ELSE
        BEGIN
          TIPO_RETORNO = 4; --REGISTRO/AVERBACAO (75%)
        END
      END
      ELSE --SOLICITADAS NO CARTORIO
      BEGIN
        if (COALESCE(:V_CONSOLIDACAO,'') = 'S') then
        begin
          V_RETORNAR = 'N'; --NAO RETORNAR, POIS ESTA RETORNANDO OS 100% NA PRENOTACAO
        end
        else
        begin
          TIPO_RETORNO = 4; --PRENOTACAO REG/AV (75%)
        end
      END

      V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' - [75%] - '||:V_NATUREZA_FORMAL;
      IF (:V_QTDE_REGISTRO > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
      END
      IF (:V_QTDE_AVERBACAO > 0) THEN
      BEGIN
        V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
      END
    
      IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
      BEGIN
        NATUREZA = 'Registro/Averbação';
      END
      ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
      BEGIN
        NATUREZA = 'Averbação';
      END
      ELSE
      BEGIN
        NATUREZA = 'Registro';
      END    
    
      QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
      QTDE_REG = COALESCE(:V_QTDE_REGISTRO,0);
      QTDE_AV = COALESCE(:V_QTDE_AVERBACAO,0);

      IF (:V_TIPO_COBRANCA = '1') THEN --ISENTO OU CANCELADO
      BEGIN
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        TOTAL_TERCEIRO = 0;
        TOTAL_BRUTO = 0;
        TOTAL_DESCONTO = 0;

        V_DESCRICAO = :V_DESCRICAO || ' (ISENTO)';

        TOTAL_EMOLUMENTO_REG = 0;
        TOTAL_TAXA_REG = 0;
        TOTAL_FUNDO_REG = 0;

        TOTAL_EMOLUMENTO_AV = 0;
        TOTAL_TAXA_AV = 0;
        TOTAL_FUNDO_AV = 0;
      END
      ELSE
      BEGIN
        TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
        IF (:TOTAL_EMOLUMENTO < 0) THEN
        BEGIN
          TOTAL_EMOLUMENTO = 0;
        END
        TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
        TOTAL_FUNDO = :V_VALOR_FUNDO;
        TOTAL_TERCEIRO = 0;
        TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO + :TOTAL_TERCEIRO;
        TOTAL_DESCONTO = :V_VALOR_DESCONTO;

        TOTAL_EMOLUMENTO_REG = :V_VALOR_EMOLUMENTO_REG;
        IF (:TOTAL_EMOLUMENTO_REG < 0) THEN
        BEGIN
          TOTAL_EMOLUMENTO_REG = 0;
        END
        TOTAL_TAXA_REG = :V_VALOR_TAXA_REG;
        TOTAL_FUNDO_REG = :V_VALOR_FUNDO_REG;


        TOTAL_EMOLUMENTO_AV = :V_VALOR_EMOLUMENTO_AV;
        IF (:TOTAL_EMOLUMENTO_AV < 0) THEN
        BEGIN
          TOTAL_EMOLUMENTO_AV = 0;
        END
        TOTAL_TAXA_AV = :V_VALOR_TAXA_AV;
        TOTAL_FUNDO_AV = :V_VALOR_FUNDO_AV;
      END
      DESCRICAO = :V_DESCRICAO;
      if (:V_RETORNAR = 'S') THEN
      BEGIN
        SUSPEND;
      END
    END
    V_PEDIDO_ID = :ID;
  END --FIM SELECIONAR PROTOCOLOS REGISTRADOS DO RI 75%*/
END ^

ALTER PROCEDURE C_DIARIO_AUX_REC_DESP_DF_CANC (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TIPO_ATO VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
DECLARE VARIABLE V_TIPO_COBRANCA VARCHAR(3);
DECLARE VARIABLE V_DESCRICAO VARCHAR(200);
DECLARE VARIABLE V_ATO_TIPO_ID INTEGER;
DECLARE VARIABLE V_QTDE2 NUMERIC(18,4);
DECLARE VARIABLE V_QTDE_REGISTRO INTEGER;
DECLARE VARIABLE V_QTDE_AVERBACAO INTEGER;
DECLARE VARIABLE V_ORIGEM_PEDIDO VARCHAR(3);
DECLARE VARIABLE V_TIPO_ORIGEM_SITE VARCHAR(3);
DECLARE VARIABLE V_TIPO_DESPESA VARCHAR(3);
DECLARE VARIABLE V_REPASSE VARCHAR(3);
DECLARE VARIABLE V_PEDIDO_ID INTEGER;

declare variable V_CONSOLIDACAO VARCHAR(3);

declare variable V_PROTOCOLO_ID INTEGER;
declare variable V_VALOR_TEMP NUMERIC(18,2);
declare variable V_DATA_PROT_TEMP DATE;
declare variable V_VALOR_COMPENSADO NUMERIC(18,2);

declare variable V_VALOR_EMOLUMENTO_COMPENSADO NUMERIC(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO NUMERIC(18,2);

DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL_CHEIO NUMERIC(18,4);

DECLARE VARIABLE V_VALOR_EMOLUMENTO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL_REG NUMERIC(18,4);

DECLARE VARIABLE V_VALOR_EMOLUMENTO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL_AV NUMERIC(18,4);

declare variable V_DIFERENCA_EMOL NUMERIC(18,2);
declare variable V_DIFERENCA_FUNDO NUMERIC(18,2);

declare variable V_NATUREZA_FORMAL VARCHAR(260);

declare variable V_DATA_CANCELAMENTO DATE;

declare variable V_SQL varchar(3000);

declare variable V_QTDE_CODHAB INTEGER;

declare variable V_OFICIO varchar(3);
declare variable V_DATA_PROTOCOLO date;
declare variable V_VALOR_COMPENSADO_ENTRADA NUMERIC(18,2);
declare variable V_VALOR_COMPENSADO_SAIDA NUMERIC(18,2);
declare variable V_NOVO_PEDIDO_ID INTEGER;
declare variable V_COMPENSADO_100 varchar(5);
declare variable V_PEDIDO_ANTERIOR_ID integer;

DECLARE VARIABLE V_PERIODO_PADRAO VARCHAR(10);
DECLARE VARIABLE V_PERIODO_PADRAO_ANTERIOR VARCHAR(10);

declare variable V_STATUS_SELO_DIGITAL VARCHAR(3);

declare variable V_VALOR_COMPENSADO_POSTERIOR NUMERIC(18,2);

declare variable V_TOTAL_PEDIDO NUMERIC(18,2);
declare variable V_TOTAL_PEDIDO_ANTERIOR NUMERIC(18,2);
declare variable V_TOTAL_PEDIDO_ANTERIOR_75 NUMERIC(18,2);
declare variable V_TOTAL_DESCONTAR NUMERIC(18,2);

declare variable V_TOTAL_DEVOLVIDO NUMERIC(18,2);
declare variable V_TOTAL_DEPOSITO NUMERIC(18,2);

declare variable V_PERCENT_DESCONTO NUMERIC(8,3);

DECLARE VARIABLE V_VALOR_ISS NUMERIC(18,4);
BEGIN
  SELECT TRIM(C.VALOR) FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '5'
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'CARTORIO'
  AND C.NOME = 'CARTORIO_OFICIO'
  INTO :V_OFICIO;

  --INICIO REGISTRO DE IMOVEIS
  --SELECIONAR PROTOCOLOS CANCELADOS DO RI 25%
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_BRUTO = 0;
  TOTAL_DESCONTO = 0;

  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;

  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;

  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;

  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;

  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;

  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  TOTAL_DESPESA = 0;
  TOTAL_GERAL_COM_ISS = 0;

  V_PEDIDO_ID = 0;

  NUMERO_ONLINE = '';
  TIPO_ATO = '1-RECEITA';
  NATUREZA = 'CANCELAMENTO DE PROTOCOLO DE REGISTRO/AVERBAÇÃO COM COBRANÇA DE 25% DOS EMOLUMENTOS';

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT DISTINCT CAST(A.DATA AS DATE),
        PR.NUMERO_ORDEM,
        PR.PEDIDO_ID,
        PR.TIPO_PROTOCOLO,
        PE.TIPO_COBRANCA,
        A.DATA, COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'), COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'), EXTRACT(MONTH FROM A.DATA),
        EXTRACT(YEAR FROM A.DATA), PR.PROTOCOLO_ID, cast(pr.data as date),
        COALESCE(PE.VALOR_COMPENSADO,0), COALESCE(PE.NOVO_PEDIDO_ID,0),
        COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
        TA.STATUS_SELO_DIGITAL
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.TB_TITULO_ID = T.TB_TITULO_ID
      AND PE.PEDIDO_ID = A.PEDIDO_ID
      AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
      AND (TA.TIPO = '||''''||'C'||''''||')
      AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
      AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                            WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                            AND A2.PEDIDO_ID = PE.PEDIDO_ID
                            AND TA2.TIPO = '||''''||'C'||''''||'
                            ORDER BY A2.ANDAMENTO_ID)
      ORDER BY 1,2 ';
  end
  else
  begin
    V_SQL = ' SELECT DISTINCT CAST(A.DATA AS DATE),
        PR.NUMERO_ORDEM,
        PR.PEDIDO_ID,
        PR.TIPO_PROTOCOLO,
        PE.TIPO_COBRANCA,
        A.DATA, COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'), COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'), EXTRACT(MONTH FROM A.DATA),
        EXTRACT(YEAR FROM A.DATA), PR.PROTOCOLO_ID, cast(pr.data as date),
        COALESCE(PE.VALOR_COMPENSADO,0), COALESCE(PE.NOVO_PEDIDO_ID,0),
        COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
        TA.STATUS_SELO_DIGITAL
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.TB_TITULO_ID = T.TB_TITULO_ID
      AND PE.PEDIDO_ID = A.PEDIDO_ID
      AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
      AND (TA.TIPO = '||''''||'C'||''''||')
      AND A.DATA BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
      AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
                            WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
                            AND A2.PEDIDO_ID = PE.PEDIDO_ID
                            AND TA2.TIPO = '||''''||'C'||''''||'
                            ORDER BY A2.ANDAMENTO_ID)
      ORDER BY 1,2 ';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO, :V_TIPO_COBRANCA, :DATA_HORA, :V_ORIGEM_PEDIDO, :V_TIPO_ORIGEM_SITE,
        :MES, :ANO, :V_PROTOCOLO_ID, :V_DATA_PROTOCOLO, :V_VALOR_COMPENSADO_ENTRADA, :V_NOVO_PEDIDO_ID, :NUMERO_ONLINE,
        :V_STATUS_SELO_DIGITAL DO
  BEGIN
    IF (:ID <> :V_PEDIDO_ID) THEN
    BEGIN
      V_CONSOLIDACAO = '';
      SELECT FIRST 1 N.CONSOLIDACAO, N.descricao
      FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
      WHERE I.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
      AND I.PEDIDO_ID = :ID
      ORDER BY SEQUENCIA
      INTO :V_CONSOLIDACAO, :V_NATUREZA_FORMAL;

      IF ((:V_TIPO_ORIGEM_SITE = '3') or (COALESCE(:V_CONSOLIDACAO,'') = 'S') or (COALESCE(:V_STATUS_SELO_DIGITAL,'') = '88')) THEN --SE FOR NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA OU DEVOLUÇÃO DE 100%
      begin
        --nao fazer nada, pois já entrou 100% na protocolização
      end
      else
      begin
        V_VALOR_COMPENSADO_SAIDA = 0;
        V_DESCRICAO = '';
        V_DATA_CANCELAMENTO = :DATA;

        select first 1 emolumento_periodo_id from g_emolumento_periodo ep
        where :DATA >= ep.data_inicial
        order by ep.data_inicial
        into :v_periodo_padrao;

        if (:V_TIPO_COBRANCA <> '1') THEN --não é isento
        begin
          SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
          WHERE CI.tipo_servico = '1' --PROTOCOLO
          AND CI.CHAVE_SERVICO = :V_PROTOCOLO_ID
          AND CI.tipo_transacao = 'C' --CREDITO
          AND ((CAST(CI.data_pagamento AS DATE) <= :V_DATA_CANCELAMENTO) or (extract(month from cast(CI.data_pagamento as date)) = extract(month from :V_DATA_CANCELAMENTO)))
          INTO :V_TOTAL_DEPOSITO;   --VALOR BRUTO RECEBIDO

          V_PEDIDO_ANTERIOR_ID = 0;
          V_TOTAL_DESCONTAR = 0;
          if (coalesce(:V_VALOR_COMPENSADO_ENTRADA,0) > 0) then
          begin
            --ver data e total do protocolo anterior
            select pr.data, coalesce(pe.pedido_id,0) from r_pedido pe, r_protocolo pr
            where pe.pedido_id = pr.pedido_id
            and pr.tipo_protocolo = '1'
            and pe.novo_pedido_id = :ID
            into :V_DATA_PROT_TEMP, :V_PEDIDO_ANTERIOR_ID;

            select first 1 emolumento_periodo_id from g_emolumento_periodo ep
            where :DATA >= ep.data_inicial
            order by ep.data_inicial
            into :V_PERIODO_PADRAO_ANTERIOR;

            SELECT (COALESCE(TOTAL_EMOLUMENTO,0) + COALESCE(TOTAL_FUNDO_RI,0))
            FROM R_TOTAL_PEDIDO_DF(:V_PEDIDO_ANTERIOR_ID, :V_PERIODO_PADRAO_ANTERIOR)
            INTO :V_TOTAL_PEDIDO_ANTERIOR;
            V_TOTAL_PEDIDO_ANTERIOR_75 = CAST((:V_TOTAL_PEDIDO_ANTERIOR * 0.75) AS NUMERIC(18,2));

            if (COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) > COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0)) then
            begin
              V_TOTAL_DEPOSITO = coalesce(:V_TOTAL_DEPOSITO,0) + COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0);
              if ((COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0)) > (COALESCE(:V_TOTAL_PEDIDO_ANTERIOR,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0))) then
              begin
                V_TOTAL_DESCONTAR = COALESCE(:V_TOTAL_PEDIDO_ANTERIOR,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0);
              end
              else
              begin
                V_TOTAL_DESCONTAR = COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0);
              end
            end
            else
            begin
              V_TOTAL_DEPOSITO = coalesce(:V_TOTAL_DEPOSITO,0) + COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0);
              V_TOTAL_DESCONTAR = 0;
            end
          end

          SELECT SUM(COALESCE(CI.VALOR_PAGO,0)) FROM C_CAIXA_ITEM CI
          WHERE CI.tipo_servico = '1' --PROTOCOLO
          AND CI.CHAVE_SERVICO = :V_PROTOCOLO_ID
          AND CI.tipo_transacao = 'D' --DEBITO
          AND ((CAST(CI.data_pagamento AS DATE) <= :V_DATA_CANCELAMENTO) or (extract(month from cast(CI.data_pagamento as date)) = extract(month from :V_DATA_CANCELAMENTO)))
          INTO :V_TOTAL_DEVOLVIDO;   --VALOR BRUTO DEVOLVIDO

          SELECT CAST((COALESCE(TOTAL_EMOLUMENTO,0) * 0.25) AS NUMERIC(18,2)) AS TOTAL_EMOLUMENTO,
            0 AS TOTAL_TAXA_JUDICIARIA,
            CAST((COALESCE(TOTAL_FUNDO_RI,0) * 0.25) AS NUMERIC(18,2)) AS TOTAL_FUNDO,
            0 AS TOTAL_DESCONTO,
    
            CAST((COALESCE(TOTAL_EMOLUMENTO_REG,0) * 0.25) AS NUMERIC(18,2)) AS TOTAL_EMOLUMENTO_REG,
            0 AS TOTAL_TAXA_REG,
            CAST((COALESCE(TOTAL_FUNDO_RI_REG,0) * 0.25) AS NUMERIC(18,2)) AS TOTAL_FUNDO_REG,
            0 AS TOTAL_DESCONTO_REG,
    
            CAST((COALESCE(TOTAL_EMOLUMENTO_AV,0) * 0.25) AS NUMERIC(18,2)) AS TOTAL_EMOLUMENTO_AV,
            0 AS TOTAL_TAXA_AV,
            CAST((COALESCE(TOTAL_FUNDO_RI_AV,0) * 0.25) AS NUMERIC(18,2)) AS TOTAL_FUNDO_AV,
            0 AS TOTAL_DESCONTO_AV,
    
            COALESCE(QUANTIDADE_REGISTRO,0) AS QTDE_REGISTRO,
            COALESCE(QUANTIDADE_AVERBACAO,0) AS QTDE_AVERBACAO,
            (COALESCE(TOTAL_EMOLUMENTO,0) + COALESCE(TOTAL_FUNDO_RI,0)) AS TOTAL_CHEIO,

            CAST((COALESCE(TOTAL_ISS,0) * 0.25) AS NUMERIC(18,2)) AS TOTAL_ISS
          FROM R_TOTAL_PEDIDO_DF(:ID, :V_PERIODO_PADRAO)
          INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO, :V_VALOR_DESCONTO,
            :V_VALOR_EMOLUMENTO_REG, :V_VALOR_TAXA_REG, :V_VALOR_FUNDO_REG, :V_VALOR_DESCONTO_REG,
            :V_VALOR_EMOLUMENTO_AV, :V_VALOR_TAXA_AV, :V_VALOR_FUNDO_AV, :V_VALOR_DESCONTO_AV,
            :V_QTDE_REGISTRO, :V_QTDE_AVERBACAO, :V_VALOR_TOTAL_CHEIO, :V_VALOR_ISS;
    
          --CORRECAO
          V_VALOR_TOTAL = (:V_VALOR_EMOLUMENTO+:V_VALOR_TAXA_JUDICIARIA+:V_VALOR_FUNDO) - :V_VALOR_DESCONTO;
          V_VALOR_TOTAL_REG = (:V_VALOR_EMOLUMENTO_REG+:V_VALOR_TAXA_REG+:V_VALOR_FUNDO_REG) - :V_VALOR_DESCONTO_REG;
          V_VALOR_TOTAL_AV = (:V_VALOR_EMOLUMENTO_AV+:V_VALOR_TAXA_AV+:V_VALOR_FUNDO_AV) - :V_VALOR_DESCONTO_AV;
    
          V_VALOR_EMOLUMENTO = cast((:V_VALOR_TOTAL * 0.9346) as numeric(18,2));
          V_VALOR_FUNDO = :V_VALOR_TOTAL - :V_VALOR_EMOLUMENTO;
          V_VALOR_TAXA_JUDICIARIA = 0;
          V_VALOR_EMOLUMENTO_REG = cast((:V_VALOR_TOTAL_REG * 0.9346) as numeric(18,2));
          V_VALOR_FUNDO_REG = :V_VALOR_TOTAL_REG - :V_VALOR_EMOLUMENTO_REG;
          V_VALOR_TAXA_REG = 0;
          V_VALOR_EMOLUMENTO_AV = cast((:V_VALOR_TOTAL_AV * 0.9346) as numeric(18,2));
          V_VALOR_FUNDO_AV = :V_VALOR_TOTAL_AV - :V_VALOR_EMOLUMENTO_AV;
          V_VALOR_TAXA_AV = 0;
          --FINAL CORRECAO
    
          SISTEMA_ID = 1;
    
          if ((coalesce(:V_VALOR_TOTAL,0) > 0) and (coalesce(:V_TOTAL_DEPOSITO,0) > coalesce(:V_TOTAL_DEVOLVIDO,0)) and (coalesce(:V_TOTAL_DEPOSITO,0) > 0)) then
          begin
            IF (:V_ORIGEM_PEDIDO = '2') THEN --ERIDFT
            BEGIN
              IF (:V_TIPO_ORIGEM_SITE = '1') THEN --PENHORA
              BEGIN
                TIPO_RETORNO = 10; --CANCELAMENTO (Penhora online) (25%)
              END
              ELSE
              BEGIN
                TIPO_RETORNO = 9; --CANCELAMENTO (25%)
              END
            END
            ELSE --SOLICITADAS NO CARTORIO
            BEGIN
              TIPO_RETORNO = 9; --CANCELAMENTO (25%)
            END
  
            V_DESCRICAO = :V_NATUREZA_FORMAL||' (Cancelado - 25% RETIDO)';
            IF (:V_QTDE_REGISTRO > 0) THEN
            BEGIN
              V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
            END
            IF (:V_QTDE_AVERBACAO > 0) THEN
            BEGIN
              V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
            END
          
            QTDE = COALESCE(:V_QTDE_REGISTRO,0) + COALESCE(:V_QTDE_AVERBACAO,0);
            QTDE_REG = COALESCE(:V_QTDE_REGISTRO,0);
            QTDE_AV = COALESCE(:V_QTDE_AVERBACAO,0);
      
            TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
            TOTAL_FUNDO = :V_VALOR_FUNDO;
            TOTAL_ISS = :V_VALOR_ISS;

            if (COALESCE(:V_TOTAL_DESCONTAR,0) > 0) then
            begin
              TOTAL_BRUTO = (:TOTAL_EMOLUMENTO + :TOTAL_FUNDO) - :V_TOTAL_DESCONTAR;

              V_PERCENT_DESCONTO = CAST((COALESCE(:V_TOTAL_DESCONTAR,0) / COALESCE(:TOTAL_BRUTO,0)) AS NUMERIC(10,2));

              TOTAL_EMOLUMENTO_REG = :V_VALOR_EMOLUMENTO_REG * (1 - :V_PERCENT_DESCONTO);
              TOTAL_FUNDO_REG = :V_VALOR_FUNDO_REG * (1 - :V_PERCENT_DESCONTO);
      
              TOTAL_EMOLUMENTO_AV = :V_VALOR_EMOLUMENTO_AV * (1 - :V_PERCENT_DESCONTO);
              TOTAL_FUNDO_AV = :V_VALOR_FUNDO_AV * (1 - :V_PERCENT_DESCONTO);

              TOTAL_EMOLUMENTO = :TOTAL_EMOLUMENTO_REG +  :TOTAL_EMOLUMENTO_AV;
              TOTAL_FUNDO = :TOTAL_FUNDO_REG + :TOTAL_FUNDO_AV;

              TOTAL_BRUTO = (:TOTAL_EMOLUMENTO + :TOTAL_FUNDO);

              TOTAL_ISS = :TOTAL_ISS * (1 - :V_PERCENT_DESCONTO);
            end
            else
            begin
              TOTAL_BRUTO = (:TOTAL_EMOLUMENTO + :TOTAL_FUNDO);

              TOTAL_EMOLUMENTO_REG = :V_VALOR_EMOLUMENTO_REG;
              TOTAL_FUNDO_REG = :V_VALOR_FUNDO_REG;
      
              TOTAL_EMOLUMENTO_AV = :V_VALOR_EMOLUMENTO_AV;
              TOTAL_FUNDO_AV = :V_VALOR_FUNDO_AV;
            end
            TOTAL_GERAL_COM_ISS = :TOTAL_BRUTO + :TOTAL_ISS;

            if (:V_TOTAL_DEPOSITO < :TOTAL_GERAL_COM_ISS) then
            begin
              TOTAL_GERAL_COM_ISS = :V_TOTAL_DEPOSITO;
              TOTAL_BRUTO = CAST(COALESCE((:TOTAL_GERAL_COM_ISS/1.05),0) AS NUMERIC(18,2));
              TOTAL_ISS = :TOTAL_GERAL_COM_ISS - :TOTAL_BRUTO;

              TOTAL_EMOLUMENTO = CAST(COALESCE((:TOTAL_BRUTO/1.07),0) AS NUMERIC(18,2));
              TOTAL_FUNDO = :TOTAL_BRUTO - :TOTAL_EMOLUMENTO;
            end

            DESCRICAO = :V_DESCRICAO;
            if (COALESCE(:TOTAL_BRUTO,0) > 0) then
            begin
              SUSPEND;
            end
          end
        end
      END
    END
    V_PEDIDO_ID = :ID;
  END --FIM SELECIONAR PROTOCOLOS REGISTRADOS DO RI 25%
END ^

ALTER PROCEDURE C_DIARIO_AUX_REC_DESP_DF_CERT (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TIPO_ATO VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
DECLARE VARIABLE V_TIPO_COBRANCA VARCHAR(3);
DECLARE VARIABLE V_DESCRICAO VARCHAR(200);
DECLARE VARIABLE V_ORIGEM_PEDIDO VARCHAR(3);

declare variable V_PROTOCOLO_ID INTEGER;

declare variable V_STRING_TEMP VARCHAR(20);

declare variable V_SQL varchar(3000);

declare variable V_EMOLUMENTO_ID_BUSCA INTEGER;
declare variable V_EMOLUMENTO_ID_FOLHA INTEGER;
declare variable V_EMOLUMENTO_PERIODO_ID INTEGER;

declare variable V_DATA_PROTOCOLO DATE;
declare variable V_PEDIDO_ITEM_ID INTEGER;
declare variable V_REG_AVERB VARCHAR(3);

DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(14,2);
DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(14,2);
DECLARE VARIABLE V_VALOR_FUNDO_RI NUMERIC(14,2);

BEGIN
  --INICIO REGISTRO DE IMOVEIS
  --SELECIONAR PEDIDOS DE CERTIDAO DO RI
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_BRUTO = 0;
  TOTAL_DESCONTO = 0;

  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;

  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;

  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;

  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;

  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;

  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  TOTAL_DESPESA = 0;

  NUMERO_ONLINE = '';
  TIPO_ATO = '1-RECEITA';

  NATUREZA = 'DEMAIS ATOS';

  V_REG_AVERB = '';

  TOTAL_ISS = 0;

  TOTAL_GERAL_COM_ISS = 0;

  --APOS CERTIDAO EMITIDA
  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT DISTINCT CAST(A.DATA AS DATE),
      PR.NUMERO_ORDEM,
      PR.PEDIDO_ID,
        PR.TIPO_PROTOCOLO,
        PE.TIPO_COBRANCA,
        PE.ORIGEM_PEDIDO, A.DATA,
        EXTRACT(MONTH FROM A.DATA), EXTRACT(YEAR FROM A.DATA),
        PR.PROTOCOLO_ID,
        COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
        coalesce(PI.QUANTIDADE,0), coalesce(PI.valor_emolumento,0), coalesce(PI.valor_fundo_ri,0),
        coalesce(PI.QUANTIDADE_BUSCA,0), coalesce(PI.quantidade_folha_excedente,0),
        NT.descricao,  CAST(PR.DATA AS DATE), PI.PEDIDO_ITEM_ID, E.reg_averb, coalesce(pi.valor_iss,0)
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, G_NATUREZA_TITULO NT, G_EMOLUMENTO E
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.PEDIDO_ID = PI.PEDIDO_ID
      AND PE.TB_TITULO_ID = T.TB_TITULO_ID
      AND PE.PEDIDO_ID = A.PEDIDO_ID
      AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID
      AND PI.emolumento_id = E.emolumento_id
      AND (PR.TIPO_PROTOCOLO = '||''''||'3'||''''||' OR PR.TIPO_PROTOCOLO = '||''''||'4'||''''||')
      AND TA.STATUS_SELO_DIGITAL = '||''''||'9'||''''||'
      AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
      AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
        WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
        AND A2.PEDIDO_ID = PE.PEDIDO_ID
        AND TA2.STATUS_SELO_DIGITAL = '||''''||'9'||''''||'
        ORDER BY A2.ANDAMENTO_ID)
      AND (SELECT COUNT(*) FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
        WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
        AND A2.PEDIDO_ID = PE.PEDIDO_ID
        AND TA2.TIPO = '||''''||'C'||''''||') = 0
     ORDER BY 1,2 ';
  end
  else
  begin
    V_SQL = ' SELECT DISTINCT CAST(A.DATA AS DATE),
      PR.NUMERO_ORDEM,
      PR.PEDIDO_ID,
        PR.TIPO_PROTOCOLO,
        PE.TIPO_COBRANCA,
        PE.ORIGEM_PEDIDO, A.DATA,
        EXTRACT(MONTH FROM A.DATA), EXTRACT(YEAR FROM A.DATA),
        PR.PROTOCOLO_ID,
        COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
        coalesce(PI.QUANTIDADE,0), coalesce(PI.valor_emolumento,0), coalesce(PI.valor_fundo_ri,0),
        coalesce(PI.QUANTIDADE_BUSCA,0), coalesce(PI.quantidade_folha_excedente,0),
        NT.descricao,  CAST(PR.DATA AS DATE), PI.PEDIDO_ITEM_ID, E.reg_averb, coalesce(pi.valor_iss,0)
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, G_NATUREZA_TITULO NT, G_EMOLUMENTO E
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.PEDIDO_ID = PI.PEDIDO_ID
      AND PE.TB_TITULO_ID = T.TB_TITULO_ID
      AND PE.PEDIDO_ID = A.PEDIDO_ID
      AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID
      AND PI.emolumento_id = E.emolumento_id
      AND (PR.TIPO_PROTOCOLO = '||''''||'3'||''''||' OR PR.TIPO_PROTOCOLO = '||''''||'4'||''''||')
      AND TA.STATUS_SELO_DIGITAL = '||''''||'9'||''''||'
      AND A.DATA BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS timestamp) AND CAST('||''''||:V_DATA_FIM||''''||' AS timestamp) + 0.999
      AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
        WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
        AND A2.PEDIDO_ID = PE.PEDIDO_ID
        AND TA2.STATUS_SELO_DIGITAL = '||''''||'9'||''''||'
        ORDER BY A2.ANDAMENTO_ID)
      AND (SELECT COUNT(*) FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
        WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
        AND A2.PEDIDO_ID = PE.PEDIDO_ID
        AND TA2.TIPO = '||''''||'C'||''''||') = 0
     ORDER BY 1,2 ';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO, :V_TIPO_COBRANCA, :V_ORIGEM_PEDIDO, :DATA_HORA,
        :MES, :ANO, :V_PROTOCOLO_ID, :NUMERO_ONLINE, :qtde, :total_emolumento, :total_fundo, :qtde_busca, :qtde_folha,
        :V_DESCRICAO, :V_DATA_PROTOCOLO, :V_PEDIDO_ITEM_ID, :V_REG_AVERB, :total_iss DO
  BEGIN
    SISTEMA_ID = 1;
    TOTAL_EMOLUMENTO_CERT = 0;
    TOTAL_FUNDO_CERT = 0;
    QTDE_CERT = 0;
  
    TOTAL_EMOLUMENTO_BUSCA = 0;
    TOTAL_FUNDO_BUSCA = 0;

    TOTAL_EMOLUMENTO_REVAL = 0;
    TOTAL_FUNDO_REVAL = 0;
    QTDE_REVAL = 0;
  
    TOTAL_EMOLUMENTO_FOLHA = 0;
    TOTAL_FUNDO_FOLHA = 0;

    TOTAL_GERAL_COM_ISS = 0;

    if (coalesce(:total_emolumento,0) > 0) then
    begin
        IF (:V_ORIGEM_PEDIDO = '2') THEN --ERIDFT
        BEGIN
          TIPO_RETORNO = 18; --CERTIDÕES/BUSCAS (e-RIDFT)
          --V_DESCRICAO = 'Pedido '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||'[eRIDFT]';
        END
        ELSE if (:V_ORIGEM_PEDIDO = '3') THEN --CENTRAL DE CERTIDAO
        BEGIN
          TIPO_RETORNO = 18; --CERTIDÕES/BUSCAS/FOLHAS EXCEDENTES/REVALIDACAO (SOLICITADAS ATRAVÉS DA CENTRAL DE CERTIDÕES)
          --V_DESCRICAO = 'Pedido '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||'[Central de certidão]';
        END
        ELSE --SOLICITADAS NO CARTORIO
        BEGIN
          TIPO_RETORNO = 15; --CERTIDÕES/BUSCAS/FOLHAS EXCEDENTES/REVALIDACAO (SOLICITADAS NO PRÓPRIO CARTÓRIO)
          --V_DESCRICAO = 'Pedido '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||'[Balcão]';
        END

        if (:tipo_retorno = 18) then --eridft
        begin
          qtde_folha = 0;
        end

        SELECT FIRST 1 EMOLUMENTO_PERIODO_ID  FROM G_EMOLUMENTO_PERIODO
        WHERE :V_DATA_PROTOCOLO >= data_inicial
        ORDER BY data_inicial desc
        into :v_emolumento_periodo_id;
    
        if (:V_DATA_PROTOCOLO < cast('18.03.2024' as date)) then
        begin
          SELECT FIRST 1 EMOLUMENTO_ID FROM G_EMOLUMENTO_ITEM
          WHERE CODIGO_SELO = 'L48'
          AND EMOLUMENTO_PERIODO_ID = :v_emolumento_periodo_id
          INTO :V_EMOLUMENTO_ID_BUSCA;
        
          SELECT FIRST 1 EMOLUMENTO_ID FROM G_EMOLUMENTO_ITEM
          WHERE CODIGO_SELO = 'L43'
          AND EMOLUMENTO_PERIODO_ID = :v_emolumento_periodo_id
          INTO :V_EMOLUMENTO_ID_FOLHA;
        end
        else
        begin
          SELECT FIRST 1 EMOLUMENTO_ID FROM G_EMOLUMENTO_ITEM
          WHERE CODIGO_SELO = 'L127'
          AND EMOLUMENTO_PERIODO_ID = :v_emolumento_periodo_id
          INTO :V_EMOLUMENTO_ID_BUSCA;
        
          SELECT FIRST 1 EMOLUMENTO_ID FROM G_EMOLUMENTO_ITEM
          WHERE CODIGO_SELO = 'L126'
          AND EMOLUMENTO_PERIODO_ID = :v_emolumento_periodo_id
          INTO :V_EMOLUMENTO_ID_FOLHA;
        end


        if (coalesce(:qtde_busca,0) > 0) then
        begin
          SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
          FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_BUSCA, :V_EMOLUMENTO_PERIODO_ID, 0)
          INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;
    
          TOTAL_EMOLUMENTO_BUSCA = (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:qtde_busca,0));
          TOTAL_FUNDO_BUSCA = (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:qtde_busca,0));
        end
        if (coalesce(:qtde_folha,0) > 0) then
        begin
          SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
          FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_FOLHA, :V_EMOLUMENTO_PERIODO_ID, 0)
          INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;
    
          TOTAL_EMOLUMENTO_FOLHA = (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:qtde_folha,0));
          TOTAL_FUNDO_FOLHA = (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:qtde_folha,0));
        end
    
        if (COALESCE(:V_REG_AVERB,'') = 'B') then
        begin
          qtde_busca = :qtde_busca + :qtde;
          TOTAL_EMOLUMENTO_BUSCA = :total_emolumento;
          TOTAL_FUNDO_BUSCA = :total_fundo;
          qtde_folha = 0;
          total_emolumento_folha = 0;
          total_fundo_folha = 0;
        end
        else if (COALESCE(:V_REG_AVERB,'') = 'F') then
        begin
          qtde_folha = :qtde_folha + :qtde;
          TOTAL_EMOLUMENTO_FOLHA = :total_emolumento;
          TOTAL_FUNDO_FOLHA = :total_fundo;
          qtde_busca = 0;
          TOTAL_EMOLUMENTO_BUSCA = 0;
          TOTAL_FUNDO_BUSCA = 0;
        end
        else if (COALESCE(:V_REG_AVERB,'') = 'V') then
        begin
          QTDE_REVAL = :qtde;
          TOTAL_EMOLUMENTO_REVAL = :total_emolumento;
          TOTAL_FUNDO_REVAL = :total_fundo;
          qtde_folha = 0;
          total_emolumento_folha = 0;
          total_fundo_folha = 0;
          qtde_busca = 0;
          TOTAL_EMOLUMENTO_BUSCA = 0;
          TOTAL_FUNDO_BUSCA = 0;
        end
        else
        begin
          qtde_cert = :qtde;
          TOTAL_EMOLUMENTO_CERT = :total_emolumento - (:TOTAL_EMOLUMENTO_BUSCA + :total_emolumento_folha);
          TOTAL_FUNDO_CERT = :total_fundo - (:TOTAL_FUNDO_BUSCA + :total_FUNDO_folha);
    
          if (:total_emolumento_cert <= 0) then
          begin
            total_emolumento_cert = :total_emolumento;
            total_fundo_cert = :total_fundo;
            qtde_folha = 0;
            total_emolumento_folha = 0;
            total_fundo_folha = 0;
            qtde_busca = 0;
            TOTAL_EMOLUMENTO_BUSCA = 0;
            TOTAL_FUNDO_BUSCA = 0;
          end
        end
    
        QTDE = COALESCE(:QTDE_CERT,0) + COALESCE(:QTDE_BUSCA,0) + COALESCE(:QTDE_REVAL,0) + COALESCE(:qtde_folha,0);
    
        IF (coalesce(:V_TIPO_COBRANCA,'') <> '1') THEN --não for ISENTO
        BEGIN
          IF (:TOTAL_EMOLUMENTO < 0) THEN
          BEGIN
            TOTAL_EMOLUMENTO = 0;
          END
          TOTAL_BRUTO = :TOTAL_EMOLUMENTO + :TOTAL_TAXA_JUDICIARIA + :TOTAL_FUNDO;
          TOTAL_GERAL_COM_ISS = :TOTAL_BRUTO + :TOTAL_ISS;
    
          if (coalesce(:QTDE_CERT,0) > 0) then
          begin
            select RETORNO from W_TROCAR_PONTO_POR_VIRGULA(CAST((CAST(((:TOTAL_EMOLUMENTO_CERT + :TOTAL_TAXA_CERT + :TOTAL_FUNDO_CERT)) AS NUMERIC(18,2))) AS VARCHAR(10))) into :V_STRING_TEMP;
            V_DESCRICAO = :V_DESCRICAO||' - Cert.('||CAST(:QTDE_CERT AS VARCHAR(10))||'-R$'||coalesce(:V_STRING_TEMP,'')||')';
          end
          if (coalesce(:qtde_busca,0) > 0) then
          begin
            select RETORNO from W_TROCAR_PONTO_POR_VIRGULA(CAST((CAST(((:total_emolumento_busca + :total_taxa_busca + :total_fundo_busca)) AS NUMERIC(18,2))) AS VARCHAR(10))) into :V_STRING_TEMP;
            V_DESCRICAO = :V_DESCRICAO||' - Busca('||CAST(:qtde_busca AS VARCHAR(10))||'-R$'||coalesce(:V_STRING_TEMP,'')||')';
          end
          if (coalesce(:QTDE_REVAL,0) > 0) then
          begin
            select RETORNO from W_TROCAR_PONTO_POR_VIRGULA(CAST((CAST(((:total_emolumento_reval + :total_taxa_reval + :total_fundo_reval)) AS NUMERIC(18,2))) AS VARCHAR(10))) into :V_STRING_TEMP;
            V_DESCRICAO = :V_DESCRICAO||' - Rev.('||CAST(:QTDE_REVAL AS VARCHAR(10))||'-R$'||coalesce(:V_STRING_TEMP,'')||')';
          end
          if (coalesce(:qtde_folha,0) > 0) then
          begin
            select RETORNO from W_TROCAR_PONTO_POR_VIRGULA(CAST((CAST(((:total_emolumento_folha + :total_taxa_folha + :total_fundo_folha)) AS NUMERIC(18,2))) AS VARCHAR(10))) into :V_STRING_TEMP;
            V_DESCRICAO = :V_DESCRICAO||' - Folha exc.('||CAST(:qtde_folha AS VARCHAR(10))||'-R$'||coalesce(:V_STRING_TEMP,'')||')';
          end
          DESCRICAO = :V_DESCRICAO;
          SUSPEND;
        END
    end
  END
END ^

ALTER PROCEDURE C_DIARIO_AUX_REC_DESP_DF_COMPL (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (ORDEM INTEGER,
SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER)
AS 
DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL NUMERIC(18,4);

DECLARE VARIABLE V_VALOR_EMOLUMENTO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL_REG NUMERIC(18,4);

DECLARE VARIABLE V_VALOR_EMOLUMENTO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL_AV NUMERIC(18,4);

DECLARE VARIABLE V_TIPO_COBRANCA VARCHAR(1);
DECLARE VARIABLE V_DESCRICAO VARCHAR(200);
DECLARE VARIABLE V_ATO_TIPO_ID INTEGER;
DECLARE VARIABLE V_DESCRICAO2 VARCHAR(200);
DECLARE VARIABLE V_QTDE2 NUMERIC(18,4);
DECLARE VARIABLE V_QTDE_REGISTRO INTEGER;
DECLARE VARIABLE V_QTDE_AVERBACAO INTEGER;
DECLARE VARIABLE V_ORIGEM_PEDIDO VARCHAR(1);
DECLARE VARIABLE V_TIPO_ORIGEM_SITE VARCHAR(1);
DECLARE VARIABLE V_TIPO_DESPESA VARCHAR(3);
DECLARE VARIABLE V_REPASSE VARCHAR(1);
DECLARE VARIABLE V_PEDIDO_ID INTEGER;

DECLARE VARIABLE V_VALOR_EMOLUMENTO_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_EMOLUMENTO_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_EMOLUMENTO_REVAL NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_REVAL NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_REVAL NUMERIC(18,4);
declare variable V_RETORNAR VARCHAR(1);
declare variable V_CONSOLIDACAO VARCHAR(1);

declare variable V_PROTOCOLO_ID INTEGER;
declare variable V_VALOR_TEMP NUMERIC(18,2);
declare variable V_VALOR_COMPENSADO NUMERIC(18,2);

declare variable V_VALOR_EMOLUMENTO_COMPENSADO NUMERIC(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO NUMERIC(18,2);

declare variable V_REPETIR_DESCRICAO VARCHAR(1);
declare variable V_DESCRICAO_SERVICO VARCHAR(60);

declare variable V_DIFERENCA_EMOL NUMERIC(18,2);
declare variable V_DIFERENCA_FUNDO NUMERIC(18,2);

declare variable V_SQL varchar(2000);

declare variable V_DATA_CAIXA date;
declare variable V_DATA_REGISTRO date;
declare variable V_COUNT_REGISTRO integer;
declare variable V_QTDE_CONSOLIDACAO integer;

declare variable v_data_reg_av date;

declare variable v_data_emissao date;

declare variable v_tipo_servico varchar(3);
declare variable V_CAIXA_ITEM_ID INTEGER;
declare variable V_CAIXA_ITEM_ID_TEMP INTEGER;
BEGIN
  --ROTINA USADA PARA COMPLEMENTO DE PED. DE CERTIDÃO
  --INICIO REGISTRO DE IMOVEIS
  --Valores complementares fora da data do pedido
  V_VALOR_TEMP = 0;

  SISTEMA_ID = 1;

  ORDEM = 0;
  
  NATUREZA = '';

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT COALESCE(CI.VALOR_PAGO,0), CI.CHAVE_SERVICO, CAST(CI.DATA_PAGAMENTO AS DATE), CI.DATA_PAGAMENTO,
        EXTRACT(MONTH FROM CI.DATA_PAGAMENTO), EXTRACT(YEAR FROM CI.DATA_PAGAMENTO), CI.TIPO_SERVICO, CI.CAIXA_ITEM_ID
      FROM C_CAIXA_ITEM CI
      WHERE COALESCE(CI.CHAVE_SERVICO,0) > 0
      AND CI.TIPO_SERVICO = '||''''||'3'||''''||'
      AND CI.TIPO_TRANSACAO = '||''''||'C'||''''||'
      AND CI.CHAVE_SERVICO = '||:VP_PROTOCOLO_ID||'
      ORDER BY CI.CAIXA_ITEM_ID ';
  end
  else
  begin
    V_SQL = ' SELECT COALESCE(CI.VALOR_PAGO,0), CI.CHAVE_SERVICO, CAST(CI.DATA_PAGAMENTO AS DATE), CI.DATA_PAGAMENTO,
        EXTRACT(MONTH FROM CI.DATA_PAGAMENTO), EXTRACT(YEAR FROM CI.DATA_PAGAMENTO), CI.TIPO_SERVICO, CI.CAIXA_ITEM_ID
      FROM C_CAIXA_ITEM CI
      WHERE COALESCE(CI.CHAVE_SERVICO,0) > 0
      AND CI.TIPO_SERVICO = '||''''||'3'||''''||'
      AND CI.TIPO_TRANSACAO = '||''''||'C'||''''||'
      AND CI.DATA_PAGAMENTO BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS timestamp) AND (CAST('||''''||:V_DATA_FIM||''''||' AS timestamp) + 0.999)
      ORDER BY CI.CAIXA_ITEM_ID ';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :V_VALOR_TEMP, :V_PROTOCOLO_ID, :DATA, :DATA_HORA, :MES, :ANO, :v_tipo_servico, :V_CAIXA_ITEM_ID DO
  BEGIN
    SELECT FIRST 1 CAIXA_ITEM_ID FROM C_CAIXA_ITEM
    WHERE TIPO_SERVICO = :v_tipo_servico
    AND CHAVE_SERVICO = :V_PROTOCOLO_ID
    ORDER BY DATA_PAGAMENTO, CAIXA_ITEM_ID
    INTO :V_CAIXA_ITEM_ID_TEMP;

    if (v_caixa_item_id <> v_caixa_item_id_temp) then
    begin
        V_DATA_CAIXA = :DATA;
    
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        QTDE = 0;
        TOTAL_BRUTO = 0;
        TOTAL_DESCONTO = 0;
      
        TOTAL_EMOLUMENTO_REG = 0;
        TOTAL_TAXA_REG = 0;
        TOTAL_FUNDO_REG = 0;
        QTDE_REG = 0;
      
        TOTAL_EMOLUMENTO_AV = 0;
        TOTAL_TAXA_AV = 0;
        TOTAL_FUNDO_AV = 0;
        QTDE_AV = 0;
      
        TOTAL_EMOLUMENTO_CERT = 0;
        TOTAL_TAXA_CERT = 0;
        TOTAL_FUNDO_CERT = 0;
        QTDE_CERT = 0;
      
        TOTAL_EMOLUMENTO_BUSCA = 0;
        TOTAL_TAXA_BUSCA = 0;
        TOTAL_FUNDO_BUSCA = 0;
        QTDE_BUSCA = 0;
      
        TOTAL_EMOLUMENTO_REVAL = 0;
        TOTAL_TAXA_REVAL = 0;
        TOTAL_FUNDO_REVAL = 0;
        QTDE_REVAL = 0;
    
        TOTAL_EMOLUMENTO_FOLHA = 0;
        TOTAL_TAXA_FOLHA = 0;
        TOTAL_FUNDO_FOLHA = 0;
        QTDE_FOLHA = 0;
      
        TOTAL_DESPESA = 0;
    
        ORDEM = :ORDEM + 1;
        V_DESCRICAO = '';
    
        V_RETORNAR = 'N';
    
        SELECT PE.PEDIDO_ID, PR.NUMERO_ORDEM, PE.TIPO_COBRANCA, COALESCE(PE.ORIGEM_PEDIDO,''),
          COALESCE(PE.TIPO_ORIGEM_SITE,'')
        FROM R_PROTOCOLO PR, R_PEDIDO PE
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PROTOCOLO_ID = :V_PROTOCOLO_ID
        INTO :ID, :NUMERO_PROTOCOLO, :V_TIPO_COBRANCA, :V_ORIGEM_PEDIDO, :V_TIPO_ORIGEM_SITE;
    
        v_data_emissao = null;
    
        SELECT FIRST 1 cast(A2.data as date) FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
        WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
        AND A2.PEDIDO_ID = :ID
        AND TA2.STATUS_SELO_DIGITAL = '9'
        ORDER BY A2.ANDAMENTO_ID
        INTO :v_data_emissao;
    
        if (((:V_TIPO_ORIGEM_SITE = '2') and (:V_TIPO_ORIGEM_SITE = '3')) or ((:v_data_emissao is not null) and (:DATA > :v_data_emissao)))  then
        begin
          V_RETORNAR = 'S';
          TIPO_PROTOCOLO = '3';
    
          SELECT  (COALESCE(TOTAL_EMOLUMENTO_CERT,0)) AS TOTAL_EMOLUMENTO_CERT,
            0, COALESCE(TOTAL_FUNDO_RI_CERT,0) AS TOTAL_FUNDO_CERT,
            COALESCE(QUANTIDADE_CERTIDAO,0) AS QTDE_CERTIDAO,
      
            (COALESCE(TOTAL_EMOLUMENTO_BUSCA,0))  AS TOTAL_EMOLUMENTO_BUSCA,
            0, COALESCE(TOTAL_FUNDO_RI_BUSCA,0) AS TOTAL_FUNDO_BUSCA,
            COALESCE(QUANTIDADE_BUSCA,0) AS QTDE_BUSCA,
      
            (COALESCE(TOTAL_EMOLUMENTO_REVAL,0)) AS TOTAL_EMOLUMENTO_REVAL,
            0, COALESCE(TOTAL_FUNDO_RI_REVAL,0) AS TOTAL_FUNDO_REVAL,
            COALESCE(QUANTIDADE_REVALIDACAO,0) AS QTDE_REVALIDACAO
          FROM R_TOTAL_PEDIDO_DF(:ID)
          INTO :V_VALOR_EMOLUMENTO_CERT, :V_VALOR_TAXA_CERT, :V_VALOR_FUNDO_CERT, :QTDE_CERT,
            :V_VALOR_EMOLUMENTO_BUSCA, :V_VALOR_TAXA_BUSCA, :V_VALOR_FUNDO_BUSCA, :QTDE_BUSCA,
            :V_VALOR_EMOLUMENTO_REVAL, :V_VALOR_TAXA_REVAL, :V_VALOR_FUNDO_REVAL, :QTDE_REVAL;
          NATUREZA = 'Certidão';
          V_DESCRICAO = 'PEDIDO '||CAST(:NUMERO_PROTOCOLO AS VARCHAR(10))||' - CERTIDÃO (Complemento)';
      
          V_VALOR_EMOLUMENTO = CAST((COALESCE(:V_VALOR_TEMP,0) * 0.9346) AS NUMERIC(18,2));
          V_VALOR_FUNDO = (:V_VALOR_TEMP - :V_VALOR_EMOLUMENTO);
          DESCRICAO = :V_DESCRICAO;
      
          if ((:V_VALOR_EMOLUMENTO_CERT + :V_VALOR_EMOLUMENTO_BUSCA + V_VALOR_EMOLUMENTO_REVAL) > :V_VALOR_EMOLUMENTO) then
          begin
            if (:V_VALOR_EMOLUMENTO_CERT > :V_VALOR_EMOLUMENTO) then
            begin
              V_VALOR_EMOLUMENTO_CERT = :V_VALOR_EMOLUMENTO;
              V_VALOR_FUNDO_CERT = :V_VALOR_FUNDO;
              V_VALOR_EMOLUMENTO_BUSCA = 0;
              V_VALOR_FUNDO_BUSCA = 0;
              V_VALOR_EMOLUMENTO_REVAL = 0;
              V_VALOR_FUNDO_REVAL = 0;
            end
            else if (:V_VALOR_EMOLUMENTO_BUSCA > :V_VALOR_EMOLUMENTO) then
            begin
              V_VALOR_EMOLUMENTO_CERT = 0;
              V_VALOR_FUNDO_CERT = 0;
              V_VALOR_EMOLUMENTO_BUSCA = :V_VALOR_EMOLUMENTO;
              V_VALOR_FUNDO_BUSCA = :V_VALOR_FUNDO;
              V_VALOR_EMOLUMENTO_REVAL = 0;
              V_VALOR_FUNDO_REVAL = 0;
            end
            else if (:V_VALOR_EMOLUMENTO_REVAL > :V_VALOR_EMOLUMENTO) then
            begin
              V_VALOR_EMOLUMENTO_CERT = 0;
              V_VALOR_FUNDO_CERT = 0;
              V_VALOR_EMOLUMENTO_BUSCA = 0;
              V_VALOR_FUNDO_BUSCA = 0;
              V_VALOR_EMOLUMENTO_REVAL = :V_VALOR_EMOLUMENTO;
              V_VALOR_FUNDO_REVAL = :V_VALOR_FUNDO;
            end
            else
            begin
              V_VALOR_EMOLUMENTO_BUSCA = :V_VALOR_EMOLUMENTO - :V_VALOR_EMOLUMENTO_CERT;
              V_VALOR_FUNDO_BUSCA = V_VALOR_FUNDO - V_VALOR_FUNDO_CERT;
              V_VALOR_EMOLUMENTO_REVAL = 0;
              V_VALOR_FUNDO_REVAL = 0;
            end
          end
          else if ((:V_VALOR_EMOLUMENTO_CERT + :V_VALOR_EMOLUMENTO_BUSCA + V_VALOR_EMOLUMENTO_REVAL) < :V_VALOR_EMOLUMENTO) then
          begin
            V_DIFERENCA_EMOL = (:V_VALOR_EMOLUMENTO - (:V_VALOR_EMOLUMENTO_CERT + :V_VALOR_EMOLUMENTO_BUSCA + V_VALOR_EMOLUMENTO_REVAL));
            V_DIFERENCA_FUNDO = (:V_VALOR_FUNDO - (:V_VALOR_FUNDO_CERT + :V_VALOR_FUNDO_BUSCA + V_VALOR_FUNDO_REVAL));
            if (:V_VALOR_EMOLUMENTO_CERT > 0) then
            begin
              V_VALOR_EMOLUMENTO_CERT = :V_VALOR_EMOLUMENTO_CERT + :V_DIFERENCA_EMOL;
              V_VALOR_FUNDO_CERT = :V_VALOR_FUNDO_CERT + :V_DIFERENCA_FUNDO;
            end
            else if (:V_VALOR_EMOLUMENTO_BUSCA > 0) then
            begin
              V_VALOR_EMOLUMENTO_BUSCA = :V_VALOR_EMOLUMENTO_BUSCA + :V_DIFERENCA_EMOL;
              V_VALOR_FUNDO_BUSCA = :V_VALOR_FUNDO_BUSCA + :V_DIFERENCA_FUNDO;
            end
            else
            begin
              V_VALOR_EMOLUMENTO_REVAL = :V_VALOR_EMOLUMENTO_REVAL + :V_DIFERENCA_EMOL;
              V_VALOR_FUNDO_REVAL = :V_VALOR_FUNDO_REVAL + :V_DIFERENCA_FUNDO;
            end
          end
      
          TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
          IF (:TOTAL_EMOLUMENTO < 0) THEN
          BEGIN
            TOTAL_EMOLUMENTO = 0;
          END
          TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
          TOTAL_FUNDO = :V_VALOR_FUNDO;
          TOTAL_BRUTO = COALESCE(:TOTAL_EMOLUMENTO,0) + COALESCE(:TOTAL_TAXA_JUDICIARIA,0) + COALESCE(:TOTAL_FUNDO,0);
          TOTAL_DESCONTO = :V_VALOR_DESCONTO;
      
          TOTAL_EMOLUMENTO_CERT = :V_VALOR_EMOLUMENTO_CERT;
          IF (:TOTAL_EMOLUMENTO_CERT < 0) THEN
          BEGIN
            TOTAL_EMOLUMENTO_CERT = 0;
          END
          TOTAL_TAXA_CERT = :V_VALOR_TAXA_CERT;
          TOTAL_FUNDO_CERT = :V_VALOR_FUNDO_CERT;
      
          TOTAL_EMOLUMENTO_BUSCA = :V_VALOR_EMOLUMENTO_BUSCA;
          IF (:TOTAL_EMOLUMENTO_BUSCA < 0) THEN
          BEGIN
            TOTAL_EMOLUMENTO_BUSCA = 0;
          END
          TOTAL_TAXA_BUSCA = :V_VALOR_TAXA_BUSCA;
          TOTAL_FUNDO_BUSCA = :V_VALOR_FUNDO_BUSCA;
      
          TOTAL_EMOLUMENTO_REVAL = :V_VALOR_EMOLUMENTO_REVAL;
          IF (:TOTAL_EMOLUMENTO_REVAL < 0) THEN
          BEGIN
            TOTAL_EMOLUMENTO_REVAL = 0;
          END
          TOTAL_TAXA_REVAL = :V_VALOR_TAXA_REVAL;
          TOTAL_FUNDO_REVAL = :V_VALOR_FUNDO_REVAL;
      
          QTDE = COALESCE(:QTDE_CERT,0) + COALESCE(:QTDE_BUSCA,0) + COALESCE(:QTDE_REVAL,0);
      
          IF (:V_ORIGEM_PEDIDO = '2') THEN --ERIDFT
          BEGIN
            TIPO_RETORNO = 9; --CERTIDÕES/BUSCAS (e-RIDFT)
          END
          ELSE if (:V_ORIGEM_PEDIDO = '3') THEN --CENTRAL DE CERTIDAO
          BEGIN
            TIPO_RETORNO = 9; --CERTIDÕES/BUSCAS/FOLHAS EXCEDENTES/REVALIDACAO (SOLICITADAS ATRAVÉS DA CENTRAL DE CERTIDÕES)
          END
          ELSE --SOLICITADAS NO CARTORIO
          BEGIN
            TIPO_RETORNO = 7; --CERTIDÕES/BUSCAS/FOLHAS EXCEDENTES/REVALIDACAO (SOLICITADAS NO PRÓPRIO CARTÓRIO)
          END
        end
    
        if (:V_RETORNAR = 'S') then
        begin
          SUSPEND;
        end
     end
  END


  --ROTINA USADA PARA COMPLEMENTO DE PPROTOCOLOS
  --INICIO REGISTRO DE IMOVEIS
  --Valores complementares APÓS REGISTRO OU CANCELAMENTO
  V_VALOR_TEMP = 0;

  SISTEMA_ID = 1;

  ORDEM = 0;
  
  NATUREZA = '';

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT COALESCE(CI.VALOR_PAGO,0), CI.CHAVE_SERVICO, CAST(CI.DATA_PAGAMENTO AS DATE), CI.DATA_PAGAMENTO,
        EXTRACT(MONTH FROM CI.DATA_PAGAMENTO), EXTRACT(YEAR FROM CI.DATA_PAGAMENTO), CI.TIPO_SERVICO, CI.CAIXA_ITEM_ID
      FROM C_CAIXA_ITEM CI
      WHERE COALESCE(CI.CHAVE_SERVICO,0) > 0
      AND CI.TIPO_SERVICO = '||''''||'1'||''''||'
      AND CI.TIPO_TRANSACAO = '||''''||'C'||''''||'
      AND CI.CHAVE_SERVICO = '||:VP_PROTOCOLO_ID||'
      ORDER BY CI.CAIXA_ITEM_ID ';
  end
  else
  begin
    V_SQL = ' SELECT COALESCE(CI.VALOR_PAGO,0), CI.CHAVE_SERVICO, CAST(CI.DATA_PAGAMENTO AS DATE), CI.DATA_PAGAMENTO,
        EXTRACT(MONTH FROM CI.DATA_PAGAMENTO), EXTRACT(YEAR FROM CI.DATA_PAGAMENTO), CI.TIPO_SERVICO, CI.CAIXA_ITEM_ID
      FROM C_CAIXA_ITEM CI
      WHERE COALESCE(CI.CHAVE_SERVICO,0) > 0
      AND CI.TIPO_SERVICO = '||''''||'1'||''''||'
      AND CI.TIPO_TRANSACAO = '||''''||'C'||''''||'
      AND CI.DATA_PAGAMENTO BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS timestamp) AND (CAST('||''''||:V_DATA_FIM||''''||' AS timestamp) + 0.9999)
      ORDER BY CI.CAIXA_ITEM_ID ';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :V_VALOR_TEMP, :V_PROTOCOLO_ID, :DATA, :DATA_HORA, :MES, :ANO, :v_tipo_servico, :V_CAIXA_ITEM_ID DO
  BEGIN
    SELECT FIRST 1 CAIXA_ITEM_ID FROM C_CAIXA_ITEM
    WHERE TIPO_SERVICO = :v_tipo_servico
    AND CHAVE_SERVICO = :V_PROTOCOLO_ID
    ORDER BY DATA_PAGAMENTO, CAIXA_ITEM_ID
    INTO :V_CAIXA_ITEM_ID_TEMP;

    if (v_caixa_item_id <> v_caixa_item_id_temp) then
    begin
        V_DATA_CAIXA = :DATA;
    
        TOTAL_EMOLUMENTO = 0;
        TOTAL_TAXA_JUDICIARIA = 0;
        TOTAL_FUNDO = 0;
        QTDE = 0;
        TOTAL_BRUTO = 0;
        TOTAL_DESCONTO = 0;
      
        TOTAL_EMOLUMENTO_REG = 0;
        TOTAL_TAXA_REG = 0;
        TOTAL_FUNDO_REG = 0;
        QTDE_REG = 0;
      
        TOTAL_EMOLUMENTO_AV = 0;
        TOTAL_TAXA_AV = 0;
        TOTAL_FUNDO_AV = 0;
        QTDE_AV = 0;
      
        TOTAL_EMOLUMENTO_CERT = 0;
        TOTAL_TAXA_CERT = 0;
        TOTAL_FUNDO_CERT = 0;
        QTDE_CERT = 0;
      
        TOTAL_EMOLUMENTO_BUSCA = 0;
        TOTAL_TAXA_BUSCA = 0;
        TOTAL_FUNDO_BUSCA = 0;
        QTDE_BUSCA = 0;
      
        TOTAL_EMOLUMENTO_REVAL = 0;
        TOTAL_TAXA_REVAL = 0;
        TOTAL_FUNDO_REVAL = 0;
        QTDE_REVAL = 0;
    
        TOTAL_EMOLUMENTO_FOLHA = 0;
        TOTAL_TAXA_FOLHA = 0;
        TOTAL_FUNDO_FOLHA = 0;
        QTDE_FOLHA = 0;
      
        TOTAL_DESPESA = 0;
    
        ORDEM = :ORDEM + 1;
        V_DESCRICAO = '';
    
        V_RETORNAR = 'N';
        SELECT PE.PEDIDO_ID, PR.NUMERO_ORDEM, PE.TIPO_COBRANCA, COALESCE(PE.ORIGEM_PEDIDO,''),
          COALESCE(PE.TIPO_ORIGEM_SITE,'')
        FROM R_PROTOCOLO PR, R_PEDIDO PE
        WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
        AND PROTOCOLO_ID = :V_PROTOCOLO_ID
        INTO :ID, :NUMERO_PROTOCOLO, :V_TIPO_COBRANCA, :V_ORIGEM_PEDIDO, :V_TIPO_ORIGEM_SITE;
    
        v_data_reg_av = null;
    
        select first 1 a.data from r_andamento a, r_tb_tipo_andamento ta
        where a.tb_tipo_andamento_id = ta.tb_tipo_andamento_id
        and (ta.tipo = 'R' or ta.tipo = 'C')
        and a.pedido_id = :ID
        into :v_data_reg_av;
    
        if ((:v_data_reg_av is not null) and (:DATA > :v_data_reg_av)) then
        begin
          V_RETORNAR = 'S';
    
          TIPO_PROTOCOLO = '1';
      
          SELECT  (COALESCE(TOTAL_EMOLUMENTO_REG,0)) AS TOTAL_EMOLUMENTO_REG,
            0, COALESCE(TOTAL_FUNDO_RI_REG,0) AS TOTAL_FUNDO_REG,
            COALESCE(QUANTIDADE_REGISTRO,0) AS QTDE_REGISTRO,
      
            (COALESCE(TOTAL_EMOLUMENTO_AV,0))  AS TOTAL_EMOLUMENTO_AV,
            0, COALESCE(TOTAL_FUNDO_RI_AV,0) AS TOTAL_FUNDO_AV,
            COALESCE(QUANTIDADE_AVERBACAO,0) AS QTDE_AVERBACAO
          FROM R_TOTAL_PEDIDO_DF(:ID)
          INTO :V_VALOR_EMOLUMENTO_REG, :V_VALOR_TAXA_REG, :V_VALOR_FUNDO_REG, :QTDE_REG,
            :V_VALOR_EMOLUMENTO_AV, :V_VALOR_TAXA_AV, :V_VALOR_FUNDO_AV, :QTDE_AV;
      
          V_DESCRICAO = 'PROTOCOLO '|| CAST(:NUMERO_PROTOCOLO AS VARCHAR(10)) ||' (Complmento) ';
          IF (:V_QTDE_REGISTRO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_REGISTRO||' REGISTRO(S)';
          END
          IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            V_DESCRICAO = :V_DESCRICAO || ' - ' ||:V_QTDE_AVERBACAO||' AVERBAÇÃO(S)';
          END
      
          IF ((:V_QTDE_REGISTRO > 0) AND (:V_QTDE_AVERBACAO > 0)) THEN
          BEGIN
            NATUREZA = 'Registro/Averbação';
          END
          ELSE IF (:V_QTDE_AVERBACAO > 0) THEN
          BEGIN
            NATUREZA = 'Averbação';
          END
          ELSE
          BEGIN
            NATUREZA = 'Registro';
          END    
      
          V_VALOR_EMOLUMENTO = CAST((COALESCE(:V_VALOR_TEMP,0) * 0.9346) AS NUMERIC(18,2));
          V_VALOR_FUNDO = (:V_VALOR_TEMP - :V_VALOR_EMOLUMENTO);
          DESCRICAO = :V_DESCRICAO;
      
          if ((:V_VALOR_EMOLUMENTO_REG + :V_VALOR_EMOLUMENTO_AV) > :V_VALOR_EMOLUMENTO) then
          begin
            if (:V_VALOR_EMOLUMENTO_REG > :V_VALOR_EMOLUMENTO) then
            begin
              V_VALOR_EMOLUMENTO_REG = :V_VALOR_EMOLUMENTO;
              V_VALOR_FUNDO_REG = :V_VALOR_FUNDO;
              V_VALOR_EMOLUMENTO_AV = 0;
              V_VALOR_FUNDO_AV = 0;
            end
            else if (:V_VALOR_EMOLUMENTO_AV > :V_VALOR_EMOLUMENTO) then
            begin
              V_VALOR_EMOLUMENTO_REG = 0;
              V_VALOR_FUNDO_REG = 0;
              V_VALOR_EMOLUMENTO_AV = :V_VALOR_EMOLUMENTO;
              V_VALOR_FUNDO_AV = :V_VALOR_FUNDO;
            end
            else
            begin
              V_VALOR_EMOLUMENTO_AV = :V_VALOR_EMOLUMENTO - :V_VALOR_EMOLUMENTO_REG;
              V_VALOR_FUNDO_AV = V_VALOR_FUNDO - V_VALOR_FUNDO_REG;
            end
          end
          else if ((:V_VALOR_EMOLUMENTO_REG + :V_VALOR_EMOLUMENTO_AV) < :V_VALOR_EMOLUMENTO) then
          begin
            V_DIFERENCA_EMOL = (:V_VALOR_EMOLUMENTO - (:V_VALOR_EMOLUMENTO_REG + :V_VALOR_EMOLUMENTO_AV));
            V_DIFERENCA_FUNDO = (:V_VALOR_FUNDO - (:V_VALOR_FUNDO_REG + :V_VALOR_FUNDO_AV));
            if (:V_VALOR_EMOLUMENTO_REG > 0) then
            begin
              V_VALOR_EMOLUMENTO_REG = :V_VALOR_EMOLUMENTO_REG + :V_DIFERENCA_EMOL;
              V_VALOR_FUNDO_REG = :V_VALOR_FUNDO_REG + :V_DIFERENCA_FUNDO;
            end
            else
            begin
              V_VALOR_EMOLUMENTO_AV = :V_VALOR_EMOLUMENTO_AV + :V_DIFERENCA_EMOL;
              V_VALOR_FUNDO_AV = :V_VALOR_FUNDO_AV + :V_DIFERENCA_FUNDO;
            end
          end
      
          TOTAL_EMOLUMENTO = :V_VALOR_EMOLUMENTO;
          IF (:TOTAL_EMOLUMENTO < 0) THEN
          BEGIN
            TOTAL_EMOLUMENTO = 0;
          END
          TOTAL_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA;
          TOTAL_FUNDO = :V_VALOR_FUNDO;
          TOTAL_BRUTO = COALESCE(:TOTAL_EMOLUMENTO,0) + COALESCE(:TOTAL_TAXA_JUDICIARIA,0) + COALESCE(:TOTAL_FUNDO,0);
          TOTAL_DESCONTO = :V_VALOR_DESCONTO;
      
          TOTAL_EMOLUMENTO_REG = :V_VALOR_EMOLUMENTO_REG;
          IF (:TOTAL_EMOLUMENTO_REG < 0) THEN
          BEGIN
            TOTAL_EMOLUMENTO_REG = 0;
          END
          TOTAL_TAXA_REG = :V_VALOR_TAXA_REG;
          TOTAL_FUNDO_REG = :V_VALOR_FUNDO_REG;
      
          TOTAL_EMOLUMENTO_AV = :V_VALOR_EMOLUMENTO_AV;
          IF (:TOTAL_EMOLUMENTO_AV < 0) THEN
          BEGIN
            TOTAL_EMOLUMENTO_AV = 0;
          END
          TOTAL_TAXA_AV = :V_VALOR_TAXA_AV;
          TOTAL_FUNDO_AV = :V_VALOR_FUNDO_AV;
      
          QTDE = COALESCE(:QTDE_REG,0) + COALESCE(:QTDE_AV,0);
      
          IF (:V_ORIGEM_PEDIDO = '2') THEN --ERIDFT
          BEGIN
            IF (:V_TIPO_ORIGEM_SITE = '1') THEN --PENHORA
            BEGIN
              TIPO_RETORNO = 12; --REGISTRO/AVERBACAO (Penhora online) (100%)
            END
            ELSE IF (:V_TIPO_ORIGEM_SITE = '3') THEN --NOTIFICAÇÃO DE ALIENACAO FIDUCIÁRIA (e-RIDFT)
            BEGIN
              V_RETORNAR = 'N'; --NAO RETORNAR, POIS ESTA RETORNANDO OS 100% NA PRENOTACAO
            END
            ELSE
            BEGIN
              TIPO_RETORNO = 11; --REGISTRO/AVERBACAO (100%)
            END
          END
          ELSE --SOLICITADAS NO CARTORIO
          BEGIN
            if (COALESCE(:V_CONSOLIDACAO,'') = 'S') then
            begin
              V_RETORNAR = 'N'; --NAO RETORNAR, POIS ESTA RETORNANDO OS 100% NA PRENOTACAO
            end
            else
            begin
              TIPO_RETORNO = 11; --REG/AV (100%)
            end
          END
        end
    
        if (:V_RETORNAR = 'S') then
        begin
          SUSPEND;
        end
    end
  END
END ^

ALTER PROCEDURE C_DIARIO_AUX_REC_DESP_DF_DESP (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
