NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TIPO_ATO VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL NUMERIC(18,4);

DECLARE VARIABLE V_VALOR_EMOLUMENTO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO_REG NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL_REG NUMERIC(18,4);

DECLARE VARIABLE V_VALOR_EMOLUMENTO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_DESCONTO_AV NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TOTAL_AV NUMERIC(18,4);

DECLARE VARIABLE V_TIPO_COBRANCA VARCHAR(3);
DECLARE VARIABLE V_ATO_TIPO_ID INTEGER;
DECLARE VARIABLE V_QTDE2 NUMERIC(18,4);
DECLARE VARIABLE V_QTDE_REGISTRO INTEGER;
DECLARE VARIABLE V_QTDE_AVERBACAO INTEGER;
DECLARE VARIABLE V_ORIGEM_PEDIDO VARCHAR(3);
DECLARE VARIABLE V_TIPO_ORIGEM_SITE VARCHAR(3);
DECLARE VARIABLE V_TIPO_DESPESA VARCHAR(3);
DECLARE VARIABLE V_REPASSE VARCHAR(3);
DECLARE VARIABLE V_VALOR_EMOLUMENTO_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_CERT NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_EMOLUMENTO_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_BUSCA NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_EMOLUMENTO_REVAL NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_TAXA_REVAL NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_FUNDO_REVAL NUMERIC(18,4);
declare variable V_RETORNAR VARCHAR(1);
declare variable V_CONSOLIDACAO VARCHAR(1);

declare variable V_PROTOCOLO_ID INTEGER;
declare variable V_VALOR_TEMP NUMERIC(18,2);
declare variable V_DATA_PROT_TEMP DATE;
declare variable V_VALOR_COMPENSADO NUMERIC(18,2);

declare variable V_VALOR_EMOLUMENTO_COMPENSADO NUMERIC(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO NUMERIC(18,2);

declare variable V_REPETIR_DESCRICAO VARCHAR(1);
declare variable V_DESCRICAO_SERVICO VARCHAR(60);

declare variable V_DIFERENCA_EMOL NUMERIC(18,2);
declare variable V_DIFERENCA_FUNDO NUMERIC(18,2);

DECLARE VARIABLE V_SERVICO_DEVOLUCAO_75 VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_100 VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_APRESENTANTE VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_TJDFT VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DIFERENCA_CUSTA_ENTRADA VARCHAR(10);
declare variable V_NATUREZA_FORMAL VARCHAR(260);
declare variable V_CAIXA_SERVICO_ID integer;
DECLARE VARIABLE V_VALOR_BRUTO NUMERIC(18,2);
declare variable V_TOTAL_GERAL numeric(18,2);
declare variable V_TOTAL_GERAL_75 numeric(18,2);
declare variable V_QTDE_CONSOLIDACAO INTEGER;

declare variable V_SQL varchar(3000);

BEGIN
  --INICIO REGISTRO DE IMOVEIS
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_BRUTO = 0;
  TOTAL_DESCONTO = 0;


  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;

  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;

  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;

  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;

  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;

  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  TOTAL_DESPESA = 0;

  NUMERO_ONLINE = '';
  TIPO_ATO = '2-DESPESA';
  NATUREZA = 'DESPESAS PAGAS (E)';

  --BUSCAR VALORES DE PARAMETROS
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_75'
  INTO :V_SERVICO_DEVOLUCAO_75;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_100'
  INTO :V_SERVICO_DEVOLUCAO_100;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_APRESENTANTE'
  INTO :V_SERVICO_DEVOLUCAO_APRESENTANTE;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_TJDFT'
  INTO :V_SERVICO_DEVOLUCAO_TJDFT;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DIFERENCA_CUSTA_ENTRADA'
  INTO :V_SERVICO_DIFERENCA_CUSTA_ENTRADA;

  --INICIO DESPESAS
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_BRUTO = 0;
  TOTAL_DESCONTO = 0;

  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;

  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;

  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;

  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;

  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;

  TOTAL_DESPESA = 0;

  V_REPETIR_DESCRICAO = '';
  V_DESCRICAO_SERVICO = '';

  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT CI.DESCRICAO,
        COALESCE(CI.VALOR_PAGO,0),
        CAST(CI.DATA_PAGAMENTO AS DATE),
        CS.REPASSE,
        CI.DATA_PAGAMENTO,
        EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
        EXTRACT(YEAR FROM CI.DATA_PAGAMENTO),
        CS.REPETIR_DESCRICAO, CS.DESCRICAO
      FROM C_CAIXA_ITEM CI, C_CAIXA_SERVICO CS
      WHERE CI.CAIXA_SERVICO_ID = CS.CAIXA_SERVICO_ID
      AND CS.TIPO_TRANSACAO = '||''''||'D'||''''||'
      AND CS.EMITIR_RELATORIO = '||''''||'S'||''''||'
      AND CS.SITUACAO = '||''''||'A'||''''||'
      AND CI.CHAVE_SERVICO = '||:VP_PROTOCOLO_ID||'
      ORDER BY CI.DATA_PAGAMENTO ';
  end
  else
  begin
    V_SQL = ' SELECT CI.DESCRICAO,
        COALESCE(CI.VALOR_PAGO,0),
        CAST(CI.DATA_PAGAMENTO AS DATE),
        CS.REPASSE,
        CI.DATA_PAGAMENTO,
        EXTRACT(MONTH FROM CI.DATA_PAGAMENTO),
        EXTRACT(YEAR FROM CI.DATA_PAGAMENTO),
        CS.REPETIR_DESCRICAO, CS.DESCRICAO
      FROM C_CAIXA_ITEM CI, C_CAIXA_SERVICO CS
      WHERE CI.CAIXA_SERVICO_ID = CS.CAIXA_SERVICO_ID
      AND CS.TIPO_TRANSACAO = '||''''||'D'||''''||'
      AND CS.EMITIR_RELATORIO = '||''''||'S'||''''||'
      AND CS.SITUACAO = '||''''||'A'||''''||'
      AND CI.DATA_PAGAMENTO BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
      ORDER BY CI.DATA_PAGAMENTO ';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :DESCRICAO, :TOTAL_DESPESA, :DATA,  :V_REPASSE, :DATA_HORA, :MES, :ANO, :V_REPETIR_DESCRICAO, :V_DESCRICAO_SERVICO DO
  BEGIN
    if (COALESCE(:V_REPETIR_DESCRICAO,'') = 'S') then
    BEGIN
      DESCRICAO = :v_descricao_servico || ' - '||:DESCRICAO;
    END

    IF (:V_REPASSE = 'S') THEN
    BEGIN
      V_TIPO_DESPESA = 'R';
    END
    ELSE
    BEGIN
      V_TIPO_DESPESA = 'D';
    END

    TIPO_RETORNO = 777;
    SISTEMA_ID = :TIPO_RETORNO;
    ID = 0;
    TIPO_PROTOCOLO = '';
    NUMERO_PROTOCOLO = 0;
    TOTAL_EMOLUMENTO = 0;
    TOTAL_FUNDO = 0;
    TOTAL_BRUTO = 0;
    TOTAL_DESCONTO = 0;

    SUSPEND;
  END
  --FIM DAS DESPESAS
END ^

ALTER PROCEDURE C_DIARIO_AUX_REC_DESP_DF_REG (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
VP_PROTOCOLO_ID INTEGER)
RETURNS (SISTEMA_ID INTEGER,
ID INTEGER,
DATA TIMESTAMP,
DATA_HORA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_PROTOCOLO INTEGER,
NATUREZA VARCHAR(1000) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_DESCONTO NUMERIC(18, 2),
TOTAL_COMPENSADO NUMERIC(18, 2),
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
MES INTEGER,
ANO INTEGER,
TIPO_RETORNO INTEGER,
NUMERO_ONLINE VARCHAR(20) CHARACTER SET ISO8859_1,
TIPO_ATO VARCHAR(20) CHARACTER SET ISO8859_1,
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2))
AS 
declare variable V_TIPO_COBRANCA varchar(3);
declare variable V_DESCRICAO varchar(200);
declare variable V_ATO_TIPO_ID integer;
declare variable V_QTDE2 numeric(18,4);
declare variable V_ORIGEM_PEDIDO varchar(3);
declare variable V_TIPO_ORIGEM_SITE varchar(3);
declare variable V_TIPO_DESPESA varchar(3);
declare variable V_REPASSE varchar(3);
declare variable V_VALOR_TEMP numeric(18,2);
declare variable V_DATA_PROT_TEMP date;
declare variable V_VALOR_COMPENSADO numeric(18,2);
declare variable V_VALOR_EMOLUMENTO_COMPENSADO numeric(18,2);
declare variable V_VALOR_FUNDO_COMPENSADO numeric(18,2);
declare variable V_DIFERENCA_EMOL numeric(18,2);
declare variable V_DIFERENCA_FUNDO numeric(18,2);
declare variable V_DATA_REGISTRO date;
declare variable V_SQL varchar(3000);
declare variable V_QTDE_CODHAB integer;
declare variable V_PROTOCOLO_ID integer;
declare variable V_OFICIO varchar(3);
declare variable V_DATA_PROTOCOLO date;
declare variable V_VALOR_COMPENSADO_ENTRADA numeric(18,2);
declare variable V_PEDIDO_ANTERIOR integer;
declare variable V_TOTAL_PEDIDO_ANTERIOR numeric(18,2);
declare variable V_PERCENTUAL numeric(18,2);
declare variable V_TOTAL_PEDIDO_ANTERIOR_75 numeric(18,2);
declare variable V_COMPENSADO_100 varchar(5);
declare variable V_TOTAL_PEDIDO numeric(18,2);
declare variable V_REG_AV varchar(3);
declare variable V_CONVENIO_CODHAB varchar(3);
declare variable V_PEDIDO_ANTERIOR_ID integer;
declare variable V_PERIODO_PADRAO_ANTERIOR integer;
declare variable V_PERIODO_PADRAO integer;
declare variable V_TOTAL_DESCONTAR numeric(18,2);
declare variable V_CARTORIO varchar(5);
BEGIN
  SELECT TRIM(C.VALOR) FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '5'
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'CARTORIO'
  AND C.NOME = 'CARTORIO_OFICIO'
  INTO :V_OFICIO;

  --BUSCAR VALORES DE PARAMETROS
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = '1'
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'CARTORIO'
  AND C.NOME = 'CARTORIO_NUMERO'
  INTO :V_CARTORIO;


  --INICIO REGISTRO DE IMOVEIS
  --SELECIONAR PROTOCOLOS REGISTRADOS DO RI 100%
  TOTAL_COMPENSADO = 0;
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_BRUTO = 0;
  TOTAL_DESCONTO = 0;

  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;

  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;

  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;

  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;

  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;

  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;

  TOTAL_DESPESA = 0;

  TOTAL_ISS = 0;
  TOTAL_GERAL_COM_ISS = 0;

  NUMERO_ONLINE = '';
  TIPO_ATO = '1-RECEITA';
  NATUREZA = 'REGISTRO/AVERBAÇÃO';

  if (COALESCE(:VP_PROTOCOLO_ID,0) > 0) then
  begin
    V_SQL = ' SELECT CAST(A.DATA AS DATE),
        PR.NUMERO_ORDEM,
        PR.PEDIDO_ID,
        PR.TIPO_PROTOCOLO,
        COALESCE(PE.TIPO_COBRANCA,'||''''||''''||'),
        A.DATA,
        COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
        COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
        EXTRACT(MONTH FROM A.DATA),
        EXTRACT(YEAR FROM A.DATA),
        PR.PROTOCOLO_ID,
        cast(pr.data as date),
        COALESCE(PE.VALOR_COMPENSADO,0),
        COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
        coalesce(PI.QUANTIDADE,0), coalesce(PI.valor_emolumento,0), coalesce(PI.valor_fundo_ri,0), e.REG_AVERB, e.convenio_codhab, NT.descricao,
        coalesce(PI.valor_iss,0)
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, G_EMOLUMENTO E, g_natureza_titulo NT
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.TB_TITULO_ID = T.TB_TITULO_ID
      AND PE.PEDIDO_ID = A.PEDIDO_ID
      AND PE.PEDIDO_ID = PI.PEDIDO_ID
      AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND PI.EMOLUMENTO_ID = E.EMOLUMENTO_ID
      and pi.natureza_titulo_id = nt.natureza_titulo_id
      AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
      AND (COALESCE(TA.TIPO,'||''''||''''||') = '||''''||'R'||''''||')
      AND PR.PROTOCOLO_ID = '||:VP_PROTOCOLO_ID||'
      AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
        WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
        AND A2.PEDIDO_ID = PE.PEDIDO_ID
        AND TA2.TIPO = '||''''||'R'||''''||'
        ORDER BY A2.ANDAMENTO_ID)
      and (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') <> '||''''||'3'||''''||')
      and (COALESCE(NT.CONSOLIDACAO,'||''''||''''||') <> '||''''||'S'||''''||')
      ORDER BY 1,2 ';
  end
  else
  begin
    V_SQL = ' SELECT CAST(A.DATA AS DATE),
        PR.NUMERO_ORDEM,
        PR.PEDIDO_ID,
        PR.TIPO_PROTOCOLO,
        COALESCE(PE.TIPO_COBRANCA,'||''''||''''||'),
        A.DATA,
        COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||'),
        COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||'),
        EXTRACT(MONTH FROM A.DATA),
        EXTRACT(YEAR FROM A.DATA),
        PR.PROTOCOLO_ID,
        cast(pr.data as date),
        COALESCE(PE.VALOR_COMPENSADO,0),
        COALESCE(PE.NUMERO_ONLINE,'||''''||''''||'),
        coalesce(PI.QUANTIDADE,0), coalesce(PI.valor_emolumento,0), coalesce(PI.valor_fundo_ri,0), e.REG_AVERB, e.convenio_codhab, NT.descricao,
        coalesce(PI.valor_iss,0)
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, R_TB_TITULO T, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, G_EMOLUMENTO E, g_natureza_titulo NT
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.TB_TITULO_ID = T.TB_TITULO_ID
      AND PE.PEDIDO_ID = A.PEDIDO_ID
      AND PE.PEDIDO_ID = PI.PEDIDO_ID
      AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND PI.EMOLUMENTO_ID = E.EMOLUMENTO_ID
      and pi.natureza_titulo_id = nt.natureza_titulo_id
      AND PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
      AND (COALESCE(TA.TIPO,'||''''||''''||') = '||''''||'R'||''''||')
      AND A.DATA BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.999
      AND A.andamento_id = (SELECT FIRST 1 A2.ANDAMENTO_ID FROM R_ANDAMENTO A2, R_TB_TIPO_ANDAMENTO TA2
        WHERE A2.TB_TIPO_ANDAMENTO_ID = TA2.TB_TIPO_ANDAMENTO_ID
        AND A2.PEDIDO_ID = PE.PEDIDO_ID
        AND TA2.TIPO = '||''''||'R'||''''||'
        ORDER BY A2.ANDAMENTO_ID)
      and (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||') <> '||''''||'3'||''''||')
      and (COALESCE(NT.CONSOLIDACAO,'||''''||''''||') <> '||''''||'S'||''''||')
      ORDER BY 1,2 ';
  end

  FOR EXECUTE STATEMENT V_SQL
      INTO :DATA, :NUMERO_PROTOCOLO, :ID, :TIPO_PROTOCOLO, :V_TIPO_COBRANCA, :DATA_HORA, :V_ORIGEM_PEDIDO, :V_TIPO_ORIGEM_SITE,
        :MES, :ANO, :V_PROTOCOLO_ID, :V_DATA_PROTOCOLO, :V_VALOR_COMPENSADO_ENTRADA, :NUMERO_ONLINE,
        :QTDE, :TOTAL_EMOLUMENTO, :TOTAL_FUNDO, :V_REG_AV, :v_convenio_codhab, :V_DESCRICAO, :total_iss DO
  BEGIN
    V_DATA_REGISTRO = :DATA;

    V_COMPENSADO_100 = 'N';
    V_PEDIDO_ANTERIOR = null;
    V_TOTAL_PEDIDO_ANTERIOR = 0;

    TOTAL_TAXA_JUDICIARIA = 0;

    SISTEMA_ID = 1;

    qtde_reg = 0;
    qtde_av = 0;

    IF (:V_ORIGEM_PEDIDO = '2') THEN --ERIDFT
    BEGIN
      IF (:V_TIPO_ORIGEM_SITE = '1') THEN --PENHORA
      BEGIN
        IF (:V_REG_AV = 'A') THEN
        begin
          TIPO_RETORNO = 5; --AVERBACAO (Penhora online) (100%)
          qtde_av = :qtde;
        end
        else
        begin
          TIPO_RETORNO = 2; --REGISTRO (Penhora online) (100%)
          qtde_reg = :qtde;
        end
      END
      ELSE
      BEGIN
      /*  IF (:V_REG_AV = 'A') THEN
        begin
          TIPO_RETORNO = 4; --AVERBACAO (100%)
          qtde_av = :qtde;
        end
        else
        begin
          TIPO_RETORNO = 1; --REGISTRO (100%)
          qtde_reg = :qtde;
        end*/
        TIPO_RETORNO = 21; --E-PROTOCOLO REG E AV (ONR)
      END
    END
    ELSE --SOLICITADAS NO CARTORIO
    BEGIN
      IF (:V_REG_AV = 'A') THEN
      begin
        TIPO_RETORNO = 4; --AVERBACAO (100%)
        qtde_av = :qtde;
      end
      else
      begin
        TIPO_RETORNO = 1; --REGISTRO (100%)
        qtde_reg = :qtde;
      end
    END

    TOTAL_EMOLUMENTO_REG = 0;
    TOTAL_FUNDO_REG = 0;
    TOTAL_EMOLUMENTO_AV = 0;
    TOTAL_FUNDO_AV = 0;

    IF (:qtde_av > 0) THEN
    BEGIN
      V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_av||' AVERBAÇÃO(S)';

      TOTAL_EMOLUMENTO_AV = :TOTAL_EMOLUMENTO;
      TOTAL_FUNDO_AV = :TOTAL_FUNDO;
    END
    else
    BEGIN
      V_DESCRICAO = :V_DESCRICAO || ' - ' ||:qtde_reg||' REGISTRO(S)';

      TOTAL_EMOLUMENTO_REG = :TOTAL_EMOLUMENTO;
      TOTAL_FUNDO_REG = :TOTAL_FUNDO;
    END

    IF (COALESCE(:V_TIPO_COBRANCA,'') <> '1') THEN --se não for ISENTO OU CANCELADO
    BEGIN
      V_PEDIDO_ANTERIOR_ID = 0;
      V_TOTAL_DESCONTAR = 0;
      if (coalesce(:V_VALOR_COMPENSADO_ENTRADA,0) > 0) then
      begin
        --ver data e total do protocolo anterior
        select pr.data, coalesce(pe.pedido_id,0) from r_pedido pe, r_protocolo pr
        where pe.pedido_id = pr.pedido_id
        and pr.tipo_protocolo = '1'
        and pe.novo_pedido_id = :ID
        into :V_DATA_PROT_TEMP, :V_PEDIDO_ANTERIOR_ID;

        select first 1 emolumento_periodo_id from g_emolumento_periodo ep
        where :V_DATA_PROT_TEMP >= ep.data_inicial
        order by ep.data_inicial
        into :V_PERIODO_PADRAO_ANTERIOR;

        SELECT (COALESCE(TOTAL_EMOLUMENTO,0) + COALESCE(TOTAL_FUNDO_RI,0))
        FROM R_TOTAL_PEDIDO_DF(:V_PEDIDO_ANTERIOR_ID, :V_PERIODO_PADRAO_ANTERIOR)
        INTO :V_TOTAL_PEDIDO_ANTERIOR;
        V_TOTAL_PEDIDO_ANTERIOR_75 = CAST((:V_TOTAL_PEDIDO_ANTERIOR * 0.75) AS NUMERIC(18,2));

        select first 1 emolumento_periodo_id from g_emolumento_periodo ep
        where :V_DATA_PROTOCOLO >= ep.data_inicial
        order by ep.data_inicial
        into :V_PERIODO_PADRAO;

        SELECT (COALESCE(TOTAL_EMOLUMENTO,0) + COALESCE(TOTAL_FUNDO_RI,0))
        FROM R_TOTAL_PEDIDO_DF(:ID, :V_PERIODO_PADRAO)
        INTO :V_TOTAL_PEDIDO;

        TOTAL_BRUTO = coalesce(:TOTAL_EMOLUMENTO,0) + coalesce(:TOTAL_FUNDO,0);

        /*if (COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) > COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0)) then
        begin
          if ((COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0)) > (COALESCE(:V_TOTAL_PEDIDO_ANTERIOR,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0))) then
          begin
            V_TOTAL_DESCONTAR = COALESCE(:V_TOTAL_PEDIDO_ANTERIOR,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0);
          end
          else
          begin
            V_TOTAL_DESCONTAR = COALESCE(:V_VALOR_COMPENSADO_ENTRADA,0) - COALESCE(:V_TOTAL_PEDIDO_ANTERIOR_75,0);
          end

          V_PERCENTUAL = cast((COALESCE(:V_TOTAL_DESCONTAR,0) / COALESCE(:V_TOTAL_PEDIDO,0)) as numeric(18,2));

          TOTAL_BRUTO = :TOTAL_BRUTO * (1-COALESCE(:V_PERCENTUAL,0));
          TOTAL_ISS = :TOTAL_ISS * (1-COALESCE(:V_PERCENTUAL,0));
          TOTAL_EMOLUMENTO = cast((:TOTAL_BRUTO * 0.9346) as numeric(18,2));
          TOTAL_FUNDO = coalesce(:TOTAL_BRUTO,0) - coalesce(:TOTAL_EMOLUMENTO,0);

          if (:qtde_av > 0) THEN
          begin
            TOTAL_EMOLUMENTO_AV = :TOTAL_EMOLUMENTO;
            TOTAL_FUNDO_AV = :TOTAL_FUNDO;
          end
          else
          begin
            TOTAL_EMOLUMENTO_REG = :TOTAL_EMOLUMENTO;
            TOTAL_FUNDO_REG = :TOTAL_FUNDO;
          end
        end*/
      end
      else
      begin
        TOTAL_BRUTO = coalesce(:TOTAL_EMOLUMENTO,0) + coalesce(:TOTAL_FUNDO,0);
      end
      DESCRICAO = :V_DESCRICAO;
      TOTAL_GERAL_COM_ISS = :TOTAL_BRUTO + :TOTAL_ISS;
      if (COALESCE(:TOTAL_BRUTO,0) > 0) then
      begin
          if (:V_CARTORIO = '9') then
          begin
            if (:v_data_protocolo < cast('01.04.2021' as date)) then
            begin
              TOTAL_BRUTO = cast((:TOTAL_BRUTO * 0.75) as numeric(15,2));
              TOTAL_EMOLUMENTO = cast((:TOTAL_EMOLUMENTO * 0.75) as numeric(15,2));
              TOTAL_FUNDO = cast((:TOTAL_FUNDO * 0.75) as numeric(15,2));
              TOTAL_EMOLUMENTO_REG = cast((:TOTAL_EMOLUMENTO_REG * 0.75) as numeric(15,2));
              TOTAL_FUNDO_REG = cast((:TOTAL_FUNDO_REG * 0.75) as numeric(15,2));
              TOTAL_EMOLUMENTO_AV = cast((:TOTAL_EMOLUMENTO_AV * 0.75) as numeric(15,2));
              TOTAL_FUNDO_AV = cast((:TOTAL_FUNDO_AV * 0.75) as numeric(15,2));
              if (COALESCE(:TOTAL_ISS,0) > 0) then
              begin
                TOTAL_ISS = cast((:TOTAL_ISS * 0.75) as numeric(15,2));
              end
              TOTAL_GERAL_COM_ISS = :TOTAL_BRUTO + :TOTAL_ISS;
            end
          end
        SUSPEND;
      end
    END
  END --FIM SELECIONAR PROTOCOLOS REGISTRADOS DO RI 100%
END ^

ALTER PROCEDURE C_DIARIO_DESPESA_INTERINO (V_DATA_INICIAL DATE,
V_DATA_FINAL DATE)
RETURNS (DESCRICAO VARCHAR(200) CHARACTER SET ISO8859_1,
DATA_PAGAMENTO DATE,
TOTAL_DESPESA NUMERIC(18, 4),
SERVICO_CAIXA_ID INTEGER,
DESCRICAO_SERVICO VARCHAR(60) CHARACTER SET ISO8859_1,
TIPO_DESPESA VARCHAR(1) CHARACTER SET ISO8859_1)
AS 
declare variable V_REPASSE varchar(1);
BEGIN
  FOR SELECT CI.DESCRICAO, 
        COALESCE(CI.VALOR_PAGO,0),
        CI.DATA_PAGAMENTO, CS.DESCRICAO,
        CS.REPASSE,
        CS.CAIXA_SERVICO_ID
      FROM C_CAIXA_ITEM CI, C_CAIXA_SERVICO CS
      WHERE CI.CAIXA_SERVICO_ID = CS.CAIXA_SERVICO_ID
      AND CS.TIPO_TRANSACAO = 'D'
      AND CS.SITUACAO = 'A'
      AND CI.DATA_PAGAMENTO BETWEEN CAST(:V_DATA_INICIAL AS TIMESTAMP) 
                                AND CAST(:V_DATA_FINAL AS TIMESTAMP)+ 0.9999 
      AND CS.descricao like '%REMUNERAÇÃO INTERINO%'
      ORDER BY CI.DATA_PAGAMENTO
      INTO :DESCRICAO, :TOTAL_DESPESA, :DATA_PAGAMENTO, :DESCRICAO_SERVICO,
        :V_REPASSE, :SERVICO_CAIXA_ID DO
  BEGIN   
    IF (:V_REPASSE = 'S') THEN
    BEGIN
      TIPO_DESPESA = 'R';
    END
    ELSE
    BEGIN
      TIPO_DESPESA = 'D';
    END 
    
    SUSPEND;
  END    
END ^

ALTER PROCEDURE C_ESTORNA_SELOS (VPSELO_INI INTEGER,
VPSELO_FIM INTEGER,
VPLOTE INTEGER)
RETURNS (STATUS VARCHAR_030)
AS 
DECLARE VARIABLE VSELO VARCHAR(20);
BEGIN
  STATUS = 'DESATUALIZADO';

  UPDATE G_SELO_LIVRO SET
  TABELA = NULL, 
  CAMPO_ID = NULL,
  DATA = NULL,
  DESCRICAO = NULL,
  OBSERVACAO = NULL, 
  USUARIO_ID = NULL,
  IP_MAQUINA = NULL,
  APRESENTANTE = NULL, 
  VALOR_EMOLUMENTO = NULL, 
  VALOR_TAXA_JUDICIARIA = NULL, 
  VALOR_FUNDESP = NULL, 
  TAG_SELO = NULL,
  SELO_SITUACAO_ID = 1
  WHERE SELO_LIVRO_ID BETWEEN :VPSELO_INI AND :VPSELO_FIM AND SELO_LOTE_ID = :VPLOTE;

  STATUS = 'ATUALIZADO';
  SUSPEND;
END ^

ALTER PROCEDURE C_EXPORTAR_SELOS_GO (V_DATA_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_STATUS VARCHAR(3) CHARACTER SET ISO8859_1,
V_CODIGO_EXPORTACAO VARCHAR(10) CHARACTER SET ISO8859_1,
V_TIPO_CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1,
V_SELO_GRUPO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_SELO_LOTE_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_ENVIO_AUTOMATICO VARCHAR(1) CHARACTER SET ISO8859_1)
RETURNS (SELO_RETIFICADO VARCHAR_060,
VALOR_INFORMACOES_CENTRAIS DINHEIRO,
NOTA_FISCAL VARCHAR(30) CHARACTER SET ISO8859_1,
SELO_LIVRO_ID INTEGER,
NUMERO_AGRUPADOR VARCHAR(30) CHARACTER SET ISO8859_1,
NUMERO_SELO VARCHAR(30) CHARACTER SET ISO8859_1,
CODIGO_EXPORTACAO INTEGER,
DATA_EXPORTACAO DATE,
SIGLA VARCHAR(30) CHARACTER SET ISO8859_1,
NUMERO INTEGER,
TIPO_ATO INTEGER,
APRESENTANTE VARCHAR(120) CHARACTER SET ISO8859_1,
NOME_COMPLETO VARCHAR(120) CHARACTER SET ISO8859_1,
DATA TIMESTAMP,
IP_MAQUINA VARCHAR(30) CHARACTER SET ISO8859_1,
VALOR_FSE NUMERICO,
VALOR_TOTAL DINHEIRO,
VALOR_EMOLUMENTO DINHEIRO,
VALOR_TAXA_JUDICIARIA DINHEIRO,
VALOR_FUNDESP DINHEIRO,
APONTAMENTO_PROTESTO NUMERICO,
ID_DO_ATO_ISENTADO INTEGER,
EH_AGRUPADOR INTEGER,
TAG_SELO TEXTO_BLOB,
ERRO_NAO_ENVIADO VARCHAR(5000) CHARACTER SET ISO8859_1,
ENVIO_IMEDIATO VARCHAR(1) CHARACTER SET ISO8859_1,
TABELA VARCHAR(30) CHARACTER SET ISO8859_1,
CAMPO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR_260,
PROTOCOLO NUMERICO,
ISS NUMERICO,
STATUS_RET_EXPORT VARCHAR_003,
SITUACAO_DIFERIDO VARCHAR_001,
MENSAGEM_RET_EXPORT TEXTO_BLOB,
SELO_SITUACAO_ID NUMERICO,
OBSERVACAO VARCHAR_090,
CHAVE_PEDIDO VARCHAR_090,
IDAP VARCHAR_120,
CPF_CNPJ VARCHAR_030,
DISTRIBUIDOR DINHEIRO,
FUNDO_SELO DINHEIRO,
MOTIVO_ISENCAO VARCHAR_260,
TIPO_ENVOLVIDO VARCHAR_120)
AS 
declare variable V_SQL varchar(5000);
declare variable V_SQL1 varchar(5000);
declare variable V_DATA_TEMP timestamp;
declare variable V_DATA_PROTOCOLO timestamp;
BEGIN
    V_SQL = '  SELECT SO.NOTA_FISCAL,
         SL.SELO_LIVRO_ID,
         SL.NUMERO_AGRUPADOR,
         SL.NUMERO_SELO,
         SL.CODIGO_EXPORTACAO,
         SL.DATA_EXPORTACAO,
         SL.SIGLA, SL.NUMERO,
         SG.NUMERO AS TIPO_ATO,
         SL.APRESENTANTE,
         U.NOME_COMPLETO,
         SL.DATA,
         SL.IP_MAQUINA,
         SL.VALOR_TOTAL,
         SL.VALOR_EMOLUMENTO,
         SL.VALOR_INFORMACOES_CENTRAIS,
         SL.VALOR_TAXA_JUDICIARIA,
         SL.VALOR_FUNDESP,
         coalesce(SL.ID_DO_ATO_ISENTADO,0) ID_DO_ATO_ISENTADO,
         SL.APONTAMENTO_PROTESTO,
         SL.TAG_SELO,
         SL.ENVIO_IMEDIATO,
         SL.TABELA,
         SL.CAMPO_ID,
         sl.descricao,
         SL.PROTOCOLO,
         SL.VALOR_ISS,
         SL.STATUS_RET_EXPORT,
         SL.MENSAGEM_RET_EXPORT,
         SL.SELO_SITUACAO_ID,
         SL.OBSERVACAO
       FROM G_SELO_LIVRO SL
       LEFT JOIN G_SELO_LOTE SO ON
         SL.SELO_LOTE_ID = SO.SELO_LOTE_ID
       LEFT JOIN G_SELO_GRUPO SG ON
         SO.SELO_GRUPO_ID = SG.SELO_GRUPO_ID
       LEFT JOIN G_USUARIO U ON
         SL.USUARIO_ID = U.USUARIO_ID
       WHERE NOT SG.TIPO_CARTORIO IS NULL
       AND DATA IS NOT NULL ';

    IF ((COALESCE(:V_DATA_INICIAL,'') <> '') AND (COALESCE(:V_DATA_FINAL,'') <> '')) THEN
    BEGIN
      V_SQL = :V_SQL || ' and SL.envio_imediato = ''S'' or ';
      V_SQL = :V_SQL || ' sl.data between cast('||''''||:V_DATA_INICIAL||''''||' as timestamp) ';
       IF (COALESCE(:V_STATUS,'') = '1') THEN --somente nao exportados
       BEGIN
         V_SQL = :V_SQL || ' -10 ';
       END
        V_SQL = :V_SQL || ' and cast('||''''||:V_DATA_FINAL||''''||' as timestamp) ';

       IF (COALESCE(:V_STATUS,'') <> '1') THEN --TODOS
       BEGIN
         V_SQL = :V_SQL || ' AND SL.selo_situacao_id in (2,3,4) ';
       END

    END
    
    IF (COALESCE(:V_STATUS,'') = '1') THEN --somente nao exportados
    BEGIN
      V_SQL = :V_SQL || ' AND SL.selo_situacao_id in (2) AND SL.DATA_EXPORTACAO IS NULL ';
    END
    
    IF (COALESCE(:V_CODIGO_EXPORTACAO,'') <> '') THEN --somente ja exportados
    BEGIN
      V_SQL = :V_SQL || ' AND SL.selo_situacao_id in (2,3,4) AND SL.CODIGO_EXPORTACAO = '||COALESCE(:V_CODIGO_EXPORTACAO,'');
    END
    
    IF (COALESCE(:V_TIPO_CARTORIO,'') <> '') THEN --por tipo de cartorio
    BEGIN
      V_SQL = :V_SQL || ' AND SG.TIPO_CARTORIO = '||COALESCE(:V_TIPO_CARTORIO,'');
    END
    
    IF (COALESCE(:V_SELO_GRUPO_ID,'') <> '') THEN --por selo_grupo_id
    BEGIN
      V_SQL = :V_SQL || ' AND SG.SELO_GRUPO_ID = '||COALESCE(:V_SELO_GRUPO_ID,'');
    END

    IF (:V_ENVIO_AUTOMATICO <> 'S') THEN --ENVIA SOMENTE OS TIPOS DE ATOS CONFIGURADOS EM G_SELO_GRUPO
    BEGIN
      V_SQL = :V_SQL || ' AND SG.ENVIO_AUTOMATICO = ''S''';
    END
    
    IF (COALESCE(:V_SELO_LOTE_ID,'') <> '') THEN --por SELO_LOTE_ID
    BEGIN
      V_SQL = :V_SQL || ' AND SL.SELO_LOTE_ID = '||COALESCE(:V_SELO_LOTE_ID,'');
    END


    FOR EXECUTE STATEMENT :V_SQL INTO
      :NOTA_FISCAL, :SELO_LIVRO_ID, :NUMERO_AGRUPADOR, :NUMERO_SELO, :CODIGO_EXPORTACAO,
      :DATA_EXPORTACAO,  :SIGLA, :NUMERO, :TIPO_ATO, :APRESENTANTE, :NOME_COMPLETO, :DATA, 
      :IP_MAQUINA,  :VALOR_TOTAL, :VALOR_EMOLUMENTO,:VALOR_INFORMACOES_CENTRAIS, :VALOR_TAXA_JUDICIARIA, :VALOR_FUNDESP,
      :ID_DO_ATO_ISENTADO,:APONTAMENTO_PROTESTO, :TAG_SELO,:ENVIO_IMEDIATO, :Tabela, :Campo_id, :DESCRICAO, :PROTOCOLO,
      :ISS, :STATUS_RET_EXPORT, :MENSAGEM_RET_EXPORT, :SELO_SITUACAO_ID, :OBSERVACAO  DO
    BEGIN
      SELECT VPERRO FROM c_valida_selo(:selo_livro_id,:numero_agrupador,:tipo_ato,:numero_selo,:Tabela,:Campo_id)
      into :ERRO_NAO_ENVIADO;

      if (coalesce(:SELO_SITUACAO_ID,0) > 2 )then
        ERRO_NAO_ENVIADO = ERRO_NAO_ENVIADO||' '||OBSERVACAO;

      if (:ERRO_NAO_ENVIADO <> '') then
        ERRO_NAO_ENVIADO = ERRO_NAO_ENVIADO||' '||DESCRICAO;
    
     if (Trim(:APRESENTANTE) = '') then
        ERRO_NAO_ENVIADO = ERRO_NAO_ENVIADO||' Nome Apresentante não vinculado';
  
    if ((:ID_DO_ATO_ISENTADO > 0) and (:VALOR_EMOLUMENTO > 0)) then
       ID_DO_ATO_ISENTADO = 0;

     VALOR_TOTAL = VALOR_TOTAL+ISS;

      /*if ((coalesce(:PROTOCOLO,0) = 0) and (Tabela = 'R_PEDIDO_ITEM')) then
      BEGIN
        V_SQL1 = ' select pr.numero_ordem from r_protocolo pr, r_pedido_item pi '||
                 ' where pr.pedido_id = pi.pedido_id ' ||
                 ' and pr.tipo_protocolo = ''1'' '||
                 ' and pi.pedido_item_id = '||:Campo_id;
          execute statement V_SQL1
          INTO :PROTOCOLO;
      END*/
      if ((Tabela = 'R_PEDIDO_ITEM') and (coalesce(:Campo_id,'')<> '' ) ) then
      BEGIN
        V_SQL1 = ' select pr.numero_ordem from r_protocolo pr, r_pedido_item pi '||
                 ' where pr.pedido_id = pi.pedido_id ' ||
                 ' and pr.tipo_protocolo = ''1'' '||
                 ' and pi.pedido_item_id = '||:Campo_id;
          execute statement V_SQL1
          INTO :PROTOCOLO;
      END

      if ((coalesce(:PROTOCOLO,0) = 0) and (Tabela = 'S_CONTROLE') AND( TIPO_ATO IN (964,965,966,1428)) ) then
      begin
        ERRO_NAO_ENVIADO = ERRO_NAO_ENVIADO||' TIPO DE ATO EXIGE PROTOCOLO';
      end

      EH_AGRUPADOR = 2;
      IF (:NUMERO_AGRUPADOR = :NUMERO_SELO) THEN
      BEGIN
        EH_AGRUPADOR = 1;
        END
      ELSE
      BEGIN
          IF ((Char_Length(:NUMERO_AGRUPADOR) = 23) ) THEN
          BEGIN
            V_DATA_TEMP = NULL;

            SELECT FIRST 1 DATA FROM G_SELO_LIVRO
            WHERE NUMERO_SELO = :NUMERO_AGRUPADOR
            AND DATA IS NOT NULL
            INTO :V_DATA_TEMP;

            if (:V_DATA_TEMP IS NOT NULL) then
            BEGIN
              if (CAST(:V_DATA_TEMP AS DATE) < CAST('30.03.2015' AS DATE)) then
              begin
                DATA = :V_DATA_TEMP;
              end
            END
           END
      END

      --verificacao de atualizacao tabela 2019
    --  if ((coalesce(:PROTOCOLO,0) > 0) and (cast(:V_DATA_PROTOCOLO AS DATE) < '01.02.2019') and (cast(:DATA AS DATE) >= '01.02.2019')) then
    --  begin
       -- DATA = :V_DATA_PROTOCOLO;
    --  end

      SUSPEND;
    END
END ^

ALTER PROCEDURE C_EXPORTAR_SELOS_NOVO_GO (V_DATA_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_STATUS VARCHAR(3) CHARACTER SET ISO8859_1,
V_CODIGO_EXPORTACAO VARCHAR(10) CHARACTER SET ISO8859_1,
V_TIPO_CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1,
V_SELO_GRUPO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_SELO_LOTE_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_ENVIO_AUTOMATICO VARCHAR(1) CHARACTER SET ISO8859_1)
RETURNS (VALOR_FSE NUMERICO,
VALOR_INFORMACOES_CENTRAIS DINHEIRO,
NOTA_FISCAL VARCHAR(30) CHARACTER SET ISO8859_1,
SELO_LIVRO_ID INTEGER,
NUMERO_AGRUPADOR VARCHAR(30) CHARACTER SET ISO8859_1,
NUMERO_SELO VARCHAR(30) CHARACTER SET ISO8859_1,
CODIGO_EXPORTACAO INTEGER,
DATA_EXPORTACAO DATE,
SIGLA VARCHAR(30) CHARACTER SET ISO8859_1,
NUMERO INTEGER,
TIPO_ATO INTEGER,
APRESENTANTE VARCHAR(120) CHARACTER SET ISO8859_1,
NOME_COMPLETO VARCHAR(120) CHARACTER SET ISO8859_1,
DATA TIMESTAMP,
IP_MAQUINA VARCHAR(30) CHARACTER SET ISO8859_1,
VALOR_TOTAL DINHEIRO,
VALOR_EMOLUMENTO DINHEIRO,
VALOR_TAXA_JUDICIARIA DINHEIRO,
VALOR_FUNDESP DINHEIRO,
APONTAMENTO_PROTESTO NUMERICO,
ID_DO_ATO_ISENTADO INTEGER,
EH_AGRUPADOR INTEGER,
TAG_SELO TEXTO_BLOB,
ERRO_NAO_ENVIADO VARCHAR(5000) CHARACTER SET ISO8859_1,
ENVIO_IMEDIATO VARCHAR(1) CHARACTER SET ISO8859_1,
TABELA VARCHAR(30) CHARACTER SET ISO8859_1,
CAMPO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR_120,
PROTOCOLO NUMERICO,
ISS NUMERICO)
AS 
declare variable V_SQL varchar(2000);
declare variable V_DATA_TEMP timestamp;
BEGIN
    V_SQL = '  SELECT SO.NOTA_FISCAL,
         SL.SELO_LIVRO_ID,
         SL.NUMERO_AGRUPADOR,
         SL.NUMERO_SELO,
         SL.CODIGO_EXPORTACAO,
         SL.DATA_EXPORTACAO,
         SL.SIGLA, SL.NUMERO,
         SG.NUMERO AS TIPO_ATO,
         SL.APRESENTANTE,
         U.NOME_COMPLETO,
         SL.DATA,
         SL.IP_MAQUINA,
         SL.VALOR_TOTAL,
         SL.VALOR_EMOLUMENTO,
         SL.VALOR_INFORMACOES_CENTRAIS,
         SL.VALOR_TAXA_JUDICIARIA,
         SL.VALOR_FUNDESP,
         SL.ID_DO_ATO_ISENTADO,
         SL.APONTAMENTO_PROTESTO,
         SL.TAG_SELO,
         SL.ENVIO_IMEDIATO,
         SL.TABELA,
         SL.CAMPO_ID,
         sl.descricao,
        SL.PROTOCOLO,
        SL.VALOR_ISS
       FROM G_SELO_LIVRO SL
       LEFT JOIN G_SELO_LOTE SO ON
         SL.SELO_LOTE_ID = SO.SELO_LOTE_ID
       LEFT JOIN G_SELO_GRUPO SG ON
         SO.SELO_GRUPO_ID = SG.SELO_GRUPO_ID
       LEFT JOIN G_USUARIO U ON
         SL.USUARIO_ID = U.USUARIO_ID
       WHERE NOT SG.TIPO_CARTORIO IS NULL
       AND SL.selo_situacao_id = 2 ';

    IF ((COALESCE(:V_DATA_INICIAL,'') <> '') AND (COALESCE(:V_DATA_FINAL,'') <> '')) THEN
    BEGIN
      V_SQL = :V_SQL || ' and SL.envio_imediato = ''S'' or ';
      V_SQL = :V_SQL || ' sl.data between cast('||''''||:V_DATA_INICIAL||''''||' as timestamp)
        and cast('||''''||:V_DATA_FINAL||''''||' as timestamp) ';
    END
    
    IF (COALESCE(:V_STATUS,'') = '1') THEN --somente nao exportados
    BEGIN
      V_SQL = :V_SQL || ' AND SL.DATA_EXPORTACAO IS NULL ';
    END
    
    IF (COALESCE(:V_CODIGO_EXPORTACAO,'') <> '') THEN --somente ja exportados
    BEGIN
      V_SQL = :V_SQL || ' AND SL.CODIGO_EXPORTACAO = '||COALESCE(:V_CODIGO_EXPORTACAO,'');
    END
    
    IF (COALESCE(:V_TIPO_CARTORIO,'') <> '') THEN --por tipo de cartorio
    BEGIN
      V_SQL = :V_SQL || ' AND SG.TIPO_CARTORIO = '||COALESCE(:V_TIPO_CARTORIO,'');
    END
    
    IF (COALESCE(:V_SELO_GRUPO_ID,'') <> '') THEN --por selo_grupo_id
    BEGIN
      V_SQL = :V_SQL || ' AND SG.SELO_GRUPO_ID = '||COALESCE(:V_SELO_GRUPO_ID,'');
    END

    IF (:V_ENVIO_AUTOMATICO <> 'S') THEN --ENVIA SOMENTE OS TIPOS DE ATOS CONFIGURADOS EM G_SELO_GRUPO
    BEGIN
      V_SQL = :V_SQL || ' AND SG.ENVIO_AUTOMATICO = ''S''';
    END
    
    IF (COALESCE(:V_SELO_LOTE_ID,'') <> '') THEN --por SELO_LOTE_ID
    BEGIN
      V_SQL = :V_SQL || ' AND SL.SELO_LOTE_ID = '||COALESCE(:V_SELO_LOTE_ID,'');
    END

    FOR EXECUTE STATEMENT :V_SQL INTO
      :NOTA_FISCAL, :SELO_LIVRO_ID, :NUMERO_AGRUPADOR, :NUMERO_SELO, :CODIGO_EXPORTACAO,
      :DATA_EXPORTACAO,  :SIGLA, :NUMERO, :TIPO_ATO, :APRESENTANTE, :NOME_COMPLETO, :DATA, 
      :IP_MAQUINA,  :VALOR_TOTAL, :VALOR_EMOLUMENTO,:VALOR_INFORMACOES_CENTRAIS, :VALOR_TAXA_JUDICIARIA, :VALOR_FUNDESP,
      :ID_DO_ATO_ISENTADO,:APONTAMENTO_PROTESTO, :TAG_SELO,:ENVIO_IMEDIATO, :Tabela, :Campo_id, :DESCRICAO, :PROTOCOLO, :ISS  DO
    BEGIN
      EH_AGRUPADOR = 2;
      SELECT VPERRO FROM c_valida_selo(:selo_livro_id,:numero_agrupador,:tipo_ato,:numero_selo,:tabela,:campo_id)
      into :ERRO_NAO_ENVIADO;
      IF (:NUMERO_AGRUPADOR = :NUMERO_SELO) THEN
      BEGIN
        EH_AGRUPADOR = 1;
        END
      ELSE
      BEGIN
          IF ((Char_Length(:NUMERO_AGRUPADOR) = 23) ) THEN
          BEGIN
            V_DATA_TEMP = NULL;

            SELECT DATA FROM G_SELO_LIVRO
            WHERE NUMERO_SELO = :NUMERO_AGRUPADOR
            AND DATA IS NOT NULL
            INTO :V_DATA_TEMP;
    
            if (:V_DATA_TEMP IS NOT NULL) then
            BEGIN
              if (CAST(:V_DATA_TEMP AS DATE) < CAST('30.03.2017' AS DATE)) then
              begin
                DATA = :V_DATA_TEMP;
              end
            END
           END
      END
      SUSPEND;
    END
END ^

ALTER PROCEDURE C_EXPORTAR_SELOS_PR (V_DATA_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
