SIGLA VARCHAR(30) CHARACTER SET ISO8859_1,
NUMERO INTEGER,
TIPO_ATO INTEGER,
APRESENTANTE VARCHAR(120) CHARACTER SET ISO8859_1,
NOME_COMPLETO VARCHAR(120) CHARACTER SET ISO8859_1,
DATA TIMESTAMP,
IP_MAQUINA VARCHAR(30) CHARACTER SET ISO8859_1,
VALOR_FSE NUMERICO,
VALOR_TOTAL DINHEIRO,
VALOR_EMOLUMENTO DINHEIRO,
VALOR_TAXA_JUDICIARIA DINHEIRO,
VALOR_FUNDESP DINHEIRO,
APONTAMENTO_PROTESTO NUMERICO,
ID_DO_ATO_ISENTADO INTEGER,
EH_AGRUPADOR INTEGER,
TAG_SELO TEXTO_BLOB,
ERRO_NAO_ENVIADO VARCHAR(5000) CHARACTER SET ISO8859_1,
ENVIO_IMEDIATO VARCHAR(1) CHARACTER SET ISO8859_1,
TABELA VARCHAR(30) CHARACTER SET ISO8859_1,
CAMPO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR_260,
PROTOCOLO NUMERICO,
ISS NUMERICO,
STATUS_RET_EXPORT VARCHAR_003,
SITUACAO_DIFERIDO VARCHAR_001,
MENSAGEM_RET_EXPORT TEXTO_BLOB,
SELO_SITUACAO_ID NUMERICO,
OBSERVACAO VARCHAR_090,
CHAVE_PEDIDO VARCHAR_090,
IDAP VARCHAR_120,
CPF_CNPJ VARCHAR_030,
DISTRIBUIDOR DINHEIRO,
FUNDO_SELO DINHEIRO,
MOTIVO_ISENCAO VARCHAR_260,
TIPO_ENVOLVIDO VARCHAR_120)
AS 
declare variable V_SQL varchar(5000);
declare variable V_SQL1 varchar(5000);
declare variable V_DATA_TEMP timestamp;
declare variable V_DATA_PROTOCOLO timestamp;
BEGIN
    V_SQL = '  SELECT SO.NOTA_FISCAL,
         SL.SELO_LIVRO_ID,
         SL.NUMERO_AGRUPADOR,
         SL.NUMERO_SELO,
         SL.CODIGO_EXPORTACAO,
         SL.DATA_EXPORTACAO,
         SL.SIGLA, SL.NUMERO,
         SL.TIPO_ATO AS TIPO_ATO,
         SL.APRESENTANTE,
         U.NOME_COMPLETO,
         SL.DATA,
         SL.IP_MAQUINA,
         SL.VALOR_TOTAL,
         SL.VALOR_EMOLUMENTO,
         SL.VALOR_INFORMACOES_CENTRAIS,
         SL.VALOR_TAXA_JUDICIARIA,
         SL.VALOR_FUNDESP,
         SL.ID_DO_ATO_ISENTADO,
         SL.APONTAMENTO_PROTESTO,
         SL.TAG_SELO,
         SL.ENVIO_IMEDIATO,
         SL.TABELA,
         SL.CAMPO_ID,
         sl.descricao,
         SL.PROTOCOLO,
         SL.VALOR_ISS,
         SL.STATUS_RET_EXPORT,
         SL.MENSAGEM_RET_EXPORT,
         SL.SELO_SITUACAO_ID,
         SL.OBSERVACAO,
         SO.SIGLA,
         SL.IDAP,
         SL.cpfcnpj,
         SL.motivo_isencao,
         SL.tipo_envolvido,
         SL.selo_retificado,
         SL.distribuidor,
         sl.fundo_selo
       FROM G_SELO_LIVRO SL
       LEFT JOIN G_SELO_LOTE SO ON
         SL.SELO_LOTE_ID = SO.SELO_LOTE_ID
       LEFT JOIN G_SELO_GRUPO SG ON
         SO.SELO_GRUPO_ID = SG.SELO_GRUPO_ID
       LEFT JOIN G_USUARIO U ON
         SL.USUARIO_ID = U.USUARIO_ID
       WHERE NOT SG.TIPO_CARTORIO IS NULL
       AND DATA IS NOT NULL ';

    IF ((COALESCE(:V_DATA_INICIAL,'') <> '') AND (COALESCE(:V_DATA_FINAL,'') <> '')) THEN
    BEGIN
      V_SQL = :V_SQL || ' and SL.envio_imediato = ''S'' or ';
      V_SQL = :V_SQL || ' sl.data between cast('||''''||:V_DATA_INICIAL||''''||' as timestamp) ';
       IF (COALESCE(:V_STATUS,'') = '1') THEN --somente nao exportados
       BEGIN
         V_SQL = :V_SQL || ' -10 ';
       END
        V_SQL = :V_SQL || ' and cast('||''''||:V_DATA_FINAL||''''||' as timestamp) ';

       IF (COALESCE(:V_STATUS,'') <> '1') THEN --TODOS
       BEGIN
         V_SQL = :V_SQL || ' AND SL.selo_situacao_id in (2,3,4) ';
       END

    END
    
    IF (COALESCE(:V_STATUS,'') = '1') THEN --somente nao exportados
    BEGIN
      V_SQL = :V_SQL || ' AND SL.selo_situacao_id in (2) AND SL.DATA_EXPORTACAO IS NULL ';
    END
    
    IF (COALESCE(:V_CODIGO_EXPORTACAO,'') <> '') THEN --somente ja exportados
    BEGIN
      V_SQL = :V_SQL || ' AND SL.selo_situacao_id in (2,3,4) AND SL.CODIGO_EXPORTACAO = '||COALESCE(:V_CODIGO_EXPORTACAO,'');
    END
    
    IF (COALESCE(:V_TIPO_CARTORIO,'') <> '') THEN --por tipo de cartorio
    BEGIN
      V_SQL = :V_SQL || ' AND SG.TIPO_CARTORIO = '||COALESCE(:V_TIPO_CARTORIO,'');
    END
    
    IF (COALESCE(:V_SELO_GRUPO_ID,'') <> '') THEN --por selo_grupo_id
    BEGIN
      V_SQL = :V_SQL || ' AND SG.SELO_GRUPO_ID = '||COALESCE(:V_SELO_GRUPO_ID,'');
    END

    IF (:V_ENVIO_AUTOMATICO <> 'S') THEN --ENVIA SOMENTE OS TIPOS DE ATOS CONFIGURADOS EM G_SELO_GRUPO
    BEGIN
      V_SQL = :V_SQL || ' AND SG.ENVIO_AUTOMATICO = ''S''';
    END
    
    IF (COALESCE(:V_SELO_LOTE_ID,'') <> '') THEN --por SELO_LOTE_ID
    BEGIN
      V_SQL = :V_SQL || ' AND SL.SELO_LOTE_ID = '||COALESCE(:V_SELO_LOTE_ID,'');
    END

     V_SQL = V_SQL || ' union ALL  SELECT SO.NOTA_FISCAL,
         SL.SELO_LIVRO_ID,
         SL.NUMERO_AGRUPADOR,
         SL.NUMERO_SELO,
         SL.CODIGO_EXPORTACAO,
         SL.DATA_EXPORTACAO,
         SL.SIGLA, SL.NUMERO,
         SL.TIPO_ATO AS TIPO_ATO,
         SL.APRESENTANTE,
         U.NOME_COMPLETO,
         SL.DATA,
         SL.IP_MAQUINA,
         SL.VALOR_TOTAL,
         SL.VALOR_EMOLUMENTO,
         SL.VALOR_INFORMACOES_CENTRAIS,
         SL.VALOR_TAXA_JUDICIARIA,
         SL.VALOR_FUNDESP,
         SL.ID_DO_ATO_ISENTADO,
         SL.APONTAMENTO_PROTESTO,
         SL.TAG_SELO,
         SL.ENVIO_IMEDIATO,
         SL.TABELA,
         SL.CAMPO_ID,
         sl.descricao,
         SL.PROTOCOLO,
         SL.VALOR_ISS,
         SL.STATUS_RET_EXPORT,
         SL.MENSAGEM_RET_EXPORT,
         SL.SELO_SITUACAO_ID,
         SL.OBSERVACAO,
         SO.SIGLA,
         SL.IDAP,
         SL.cpfcnpj,
         SL.motivo_isencao,
         SL.tipo_envolvido,
         SL.selo_retificado,
         sl.distribuidor,
         sl.fundo_selo
       FROM G_SELO_LIVRO_ANTIGO SL
       LEFT JOIN G_SELO_LOTE_ANTIGO SO ON
         SL.SELO_LOTE_ID = SO.SELO_LOTE_ID
       LEFT JOIN G_SELO_GRUPO SG ON
         SO.SELO_GRUPO_ID = SG.SELO_GRUPO_ID
       LEFT JOIN G_USUARIO U ON
         SL.USUARIO_ID = U.USUARIO_ID
       WHERE NOT SG.TIPO_CARTORIO IS NULL
       AND DATA IS NOT NULL ';

    IF ((COALESCE(:V_DATA_INICIAL,'') <> '') AND (COALESCE(:V_DATA_FINAL,'') <> '')) THEN
    BEGIN
      V_SQL = :V_SQL || ' and SL.envio_imediato = ''S'' or ';
      V_SQL = :V_SQL || ' sl.data between cast('||''''||:V_DATA_INICIAL||''''||' as timestamp) ';
       IF (COALESCE(:V_STATUS,'') = '1') THEN --somente nao exportados
       BEGIN
         V_SQL = :V_SQL || ' -10 ';
       END
        V_SQL = :V_SQL || ' and cast('||''''||:V_DATA_FINAL||''''||' as timestamp) ';

       IF (COALESCE(:V_STATUS,'') <> '1') THEN --TODOS
       BEGIN
         V_SQL = :V_SQL || ' AND SL.selo_situacao_id in (2,3,4) ';
       END

    END
    
    IF (COALESCE(:V_STATUS,'') = '1') THEN --somente nao exportados
    BEGIN
      V_SQL = :V_SQL || ' AND SL.selo_situacao_id in (2) AND SL.DATA_EXPORTACAO IS NULL ';
    END
    
    IF (COALESCE(:V_CODIGO_EXPORTACAO,'') <> '') THEN --somente ja exportados
    BEGIN
      V_SQL = :V_SQL || ' AND SL.selo_situacao_id in (2,3,4) AND SL.CODIGO_EXPORTACAO = '||COALESCE(:V_CODIGO_EXPORTACAO,'');
    END
    
    IF (COALESCE(:V_TIPO_CARTORIO,'') <> '') THEN --por tipo de cartorio
    BEGIN
      V_SQL = :V_SQL || ' AND SG.TIPO_CARTORIO = '||COALESCE(:V_TIPO_CARTORIO,'');
    END
    
    IF (COALESCE(:V_SELO_GRUPO_ID,'') <> '') THEN --por selo_grupo_id
    BEGIN
      V_SQL = :V_SQL || ' AND SG.SELO_GRUPO_ID = '||COALESCE(:V_SELO_GRUPO_ID,'');
    END

    IF (:V_ENVIO_AUTOMATICO <> 'S') THEN --ENVIA SOMENTE OS TIPOS DE ATOS CONFIGURADOS EM G_SELO_GRUPO
    BEGIN
      V_SQL = :V_SQL || ' AND SG.ENVIO_AUTOMATICO = ''S''';
    END
    
    IF (COALESCE(:V_SELO_LOTE_ID,'') <> '') THEN --por SELO_LOTE_ID
    BEGIN
      V_SQL = :V_SQL || ' AND SL.SELO_LOTE_ID = '||COALESCE(:V_SELO_LOTE_ID,'');
    END
    FOR EXECUTE STATEMENT :V_SQL INTO
      :NOTA_FISCAL, :SELO_LIVRO_ID, :NUMERO_AGRUPADOR, :NUMERO_SELO, :CODIGO_EXPORTACAO,
      :DATA_EXPORTACAO,  :SIGLA, :NUMERO, :TIPO_ATO, :APRESENTANTE, :NOME_COMPLETO, :DATA, 
      :IP_MAQUINA,  :VALOR_TOTAL, :VALOR_EMOLUMENTO,:VALOR_INFORMACOES_CENTRAIS, :VALOR_TAXA_JUDICIARIA, :VALOR_FUNDESP,
      :ID_DO_ATO_ISENTADO,:APONTAMENTO_PROTESTO, :TAG_SELO,:ENVIO_IMEDIATO, :Tabela, :Campo_id, :DESCRICAO, :PROTOCOLO,
      :ISS, :STATUS_RET_EXPORT, :MENSAGEM_RET_EXPORT, :SELO_SITUACAO_ID, :OBSERVACAO, :CHAVE_PEDIDO, :IDAP, :cpf_cnpj,
      :motivo_isencao, :tipo_envolvido, :selo_retificado, :distribuidor, :fundo_selo  DO
    BEGIN

     VALOR_TOTAL = VALOR_TOTAL+ISS+COALESCE(DISTRIBUIDOR,0);
     --++COALESCE(fundo_selo,0);

      if ((Tabela = 'R_PEDIDO_ITEM') and (coalesce(:Campo_id,'')<> '' ) ) then
      BEGIN
        V_SQL1 = ' select pr.numero_ordem from r_protocolo pr, r_pedido_item pi '||
                 ' where pr.pedido_id = pi.pedido_id ' ||
                 ' and pr.tipo_protocolo = ''1'' '||
                 ' and pi.pedido_item_id = '||:Campo_id;
          execute statement V_SQL1
          INTO :PROTOCOLO;
      END

      if ((coalesce(:PROTOCOLO,0) = 0) and (Tabela = 'S_CONTROLE') AND( TIPO_ATO IN (964,965,966,1428)) ) then
      begin
        ERRO_NAO_ENVIADO = ERRO_NAO_ENVIADO||' TIPO DE ATO EXIGE PROTOCOLO';
      end

      EH_AGRUPADOR = 2;
      IF (:NUMERO_AGRUPADOR = :NUMERO_SELO) THEN
      BEGIN
        EH_AGRUPADOR = 1;
        END
      ELSE
      BEGIN
          IF ((Char_Length(:NUMERO_AGRUPADOR) = 23) ) THEN
          BEGIN
            V_DATA_TEMP = NULL;

            SELECT FIRST 1 DATA FROM G_SELO_LIVRO
            WHERE NUMERO_SELO = :NUMERO_AGRUPADOR
            AND DATA IS NOT NULL
            INTO :V_DATA_TEMP;

            if (:V_DATA_TEMP IS NOT NULL) then
            BEGIN
              if (CAST(:V_DATA_TEMP AS DATE) < CAST('30.03.2015' AS DATE)) then
              begin
                DATA = :V_DATA_TEMP;
              end
            END
           END
      END
      SUSPEND;
    END
END ^

ALTER PROCEDURE C_EXPORTAR_SELOS_TO (V_DATA_INICIAL VARCHAR_030,
V_DATA_FINAL VARCHAR_030,
V_STATUS VARCHAR_003,
V_CODIGO_EXPORTACAO VARCHAR_010,
V_TIPO_CARTORIO VARCHAR_003,
V_SELO_GRUPO_ID VARCHAR_010,
V_SELO_LOTE_ID VARCHAR_010,
V_CODIGO_ATO VARCHAR_010)
RETURNS (SELO_RETIFICADO VARCHAR_060,
VALOR_FSE NUMERICO,
VALOR_INFORMACOES_CENTRAIS DINHEIRO,
APONTAMENTO_PROTESTO NUMERICO,
NOTA_FISCAL VARCHAR_030,
SELO_LIVRO_ID INTEGER,
NUMERO_AGRUPADOR VARCHAR_030,
NUMERO_SELO VARCHAR_030,
CODIGO_EXPORTACAO INTEGER,
DATA_EXPORTACAO DATE,
SIGLA VARCHAR_030,
NUMERO INTEGER,
TIPO_ATO INTEGER,
APRESENTANTE VARCHAR_120,
NOME_COMPLETO VARCHAR_120,
DATA TIMESTAMP,
IP_MAQUINA VARCHAR_030,
VALOR_TOTAL DINHEIRO,
VALOR_EMOLUMENTO DINHEIRO,
VALOR_TAXA_JUDICIARIA DINHEIRO,
VALOR_FUNDESP DINHEIRO,
ID_DO_ATO_ISENTADO INTEGER,
EH_AGRUPADOR INTEGER,
ERRO_NAO_ENVIADO VARCHAR(5000) CHARACTER SET ISO8859_1,
ENVIO_IMEDIATO VARCHAR(1) CHARACTER SET ISO8859_1,
TABELA VARCHAR(30) CHARACTER SET ISO8859_1,
CAMPO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR_120,
PROTOCOLO NUMERICO,
ISS NUMERICO,
TAG_SELO TEXTO_BLOB,
STATUS_RET_EXPORT VARCHAR_003,
SITUACAO_DIFERIDO VARCHAR_001,
MENSAGEM_RET_EXPORT TEXTO_BLOB,
CHAVE_PEDIDO VARCHAR_090,
IDAP VARCHAR_120,
CPF_CNPJ VARCHAR_030,
DISTRIBUIDOR DINHEIRO,
FUNDO_SELO DINHEIRO,
MOTIVO_ISENCAO VARCHAR_260,
TIPO_ENVOLVIDO VARCHAR_120)
AS 
declare variable V_SQL varchar(2000);
BEGIN

    V_SQL = '  SELECT SO.NOTA_FISCAL,
                      SL.SELO_LIVRO_ID,
                      SL.NUMERO_AGRUPADOR,
                      (SL.SIGLA || LPAD(CAST(SL.NUMERO AS INTEGER), 6, ''0'')) as NUMERO_SELO,
                      SL.CODIGO_EXPORTACAO,
                      SL.DATA_EXPORTACAO,
                      SL.SIGLA,
                      SL.NUMERO,
                      SL.TIPO_ATO,
                      SL.APRESENTANTE,
                      U.NOME_COMPLETO,
                      SL.DATA,
                      SL.IP_MAQUINA,
                      SL.VALOR_TOTAL,
                      SL.VALOR_EMOLUMENTO,
                      COALESCE(SL.VALOR_INFORMACOES_CENTRAIS,0) VALOR_INFORMACOES_CENTRAIS,
                      SL.VALOR_TAXA_JUDICIARIA,
                      SL.VALOR_FUNDESP,
                      SL.ID_DO_ATO_ISENTADO,
                      null,
                      null,
                      SL.TAG_SELO,
                      SL.SITUACAO_DIFERIDO,
                      SL.MENSAGEM_RET_EXPORT,
                      SL.VALOR_ISS,
                      SL.VALOR_FUNDO_SELO,
                      SL.tabela,
                      SL.campo_id
               FROM G_SELO_LIVRO SL
               LEFT JOIN G_SELO_LOTE SO ON SL.SELO_LOTE_ID = SO.SELO_LOTE_ID
               LEFT JOIN G_SELO_GRUPO SG ON SO.SELO_GRUPO_ID = SG.SELO_GRUPO_ID
               LEFT JOIN G_USUARIO U ON SL.USUARIO_ID = U.USUARIO_ID
               WHERE NOT SG.TIPO_CARTORIO IS NULL
                 AND SL.selo_situacao_id = 2 ';

    IF ((COALESCE(:V_DATA_INICIAL,'') <> '') AND (COALESCE(:V_DATA_FINAL,'') <> '')) THEN
    BEGIN
      V_SQL = :V_SQL || ' and sl.data between cast('||''''||:V_DATA_INICIAL||''''||' as timestamp)
        and cast('||''''||:V_DATA_FINAL||''''||' as timestamp) '; 
    END
    
    IF (COALESCE(:V_STATUS,'') = '1') THEN --somente nao exportados
    BEGIN
      V_SQL = :V_SQL || ' AND SL.DATA_EXPORTACAO IS NULL ';
    END
    
    IF (COALESCE(V_CODIGO_EXPORTACAO ,'') <> '') THEN --somente ja exportados
    BEGIN
      V_SQL = :V_SQL || ' AND SL.CODIGO_EXPORTACAO = '||COALESCE(:V_CODIGO_EXPORTACAO,'');
    END
    
    IF (COALESCE(:V_TIPO_CARTORIO,'') <> '') THEN --por tipo de cartorio
    BEGIN
      V_SQL = :V_SQL || ' AND SG.TIPO_CARTORIO = '||COALESCE(:V_TIPO_CARTORIO,'');
    END
    
    IF (COALESCE(:V_SELO_GRUPO_ID,'') <> '') THEN --por selo_grupo_id
    BEGIN
      V_SQL = :V_SQL || ' AND SG.SELO_GRUPO_ID = '||COALESCE(:V_SELO_GRUPO_ID,'');
    END
    
    IF (COALESCE(:V_SELO_LOTE_ID,'') <> '') THEN --por SELO_LOTE_ID
    BEGIN
      V_SQL = :V_SQL || ' AND SL.SELO_LOTE_ID = '||COALESCE(:V_SELO_LOTE_ID,'');
    END
    IF (COALESCE(:V_CODIGO_ATO,'') <> '') THEN --por CODIGO_ATO
    BEGIN
      V_SQL = :V_SQL || ' AND SL.TIPO_ATO = '||COALESCE(:V_CODIGO_ATO,'');
    END

    FOR EXECUTE STATEMENT :V_SQL INTO
      :NOTA_FISCAL, :SELO_LIVRO_ID, :NUMERO_AGRUPADOR, :NUMERO_SELO, :CODIGO_EXPORTACAO,
      :DATA_EXPORTACAO, :SIGLA, :NUMERO, :TIPO_ATO, :APRESENTANTE, :NOME_COMPLETO, :DATA, :IP_MAQUINA,
      :VALOR_TOTAL, :VALOR_EMOLUMENTO, :VALOR_INFORMACOES_CENTRAIS, :VALOR_TAXA_JUDICIARIA, :VALOR_FUNDESP,
      :ID_DO_ATO_ISENTADO,:APONTAMENTO_PROTESTO, :PROTOCOLO,  :TAG_SELO, :SITUACAO_DIFERIDO,:MENSAGEM_RET_EXPORT,
      :ISS, :valor_fse, :tabela, :campo_id DO
    BEGIN
      EH_AGRUPADOR = 2;
     ERRO_NAO_ENVIADO = '';

    if (COALESCE(:VALOR_EMOLUMENTO,0) > 10) then
    BEGIN
      if (COALESCE(:valor_fse,0) = 0 ) then
      begin
        SELECT MAX(FUNDO_SELO) FROM G_EMOLUMENTO_ITEM
        INTO :VALOR_FSE;
      end
      VALOR_TOTAL = VALOR_EMOLUMENTO+VALOR_FSE+ISS+VALOR_TAXA_JUDICIARIA+VALOR_FUNDESP+coalesce(VALOR_INFORMACOES_CENTRAIS,0);
    END
    ELSE
    BEGIN
      VALOR_FSE = 0;
      VALOR_TOTAL = VALOR_TOTAL+ISS;
    END

    if (COALESCE(:TAG_SELO,'') = '') then
        ERRO_NAO_ENVIADO = 'TAG VAZIA';

      IF (:NUMERO_AGRUPADOR = :NUMERO_SELO) THEN
      BEGIN
        EH_AGRUPADOR = 1;
      END
      SUSPEND;
    END
END ^

ALTER PROCEDURE C_EXTRATO_DEPOSITO_PREVIO_DF (V_MES INTEGER,
V_ANO INTEGER)
RETURNS (TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TIPO_RETORNO VARCHAR(1) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(260) CHARACTER SET ISO8859_1,
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
SALDO_DP_MES_ANTERIOR NUMERIC(18, 2),
MENSAGEM_ERRO VARCHAR(300) CHARACTER SET ISO8859_1,
ANO INTEGER,
MES INTEGER,
MES_STRING VARCHAR(50) CHARACTER SET ISO8859_1,
TOTAL_REPASSE NUMERIC(18, 2),
TOTAL_LIQUIDO NUMERIC(18, 2),
TOTAL_DESPESA_DEDUTIVEL NUMERIC(18, 2),
TOTAL_DESPESA_NAO_DEDUTIVEL NUMERIC(18, 2),
TIPO_DEPOSITO INTEGER)
AS 
DECLARE VARIABLE V_DATA_INI DATE;
  DECLARE VARIABLE V_DATA_FIM DATE;
  DECLARE VARIABLE V_ANO_INFORMADO INTEGER;
  DECLARE VARIABLE V_MES_INFORMADO INTEGER;
  DECLARE VARIABLE V_DIA_INFORMADO INTEGER;
  DECLARE VARIABLE V_DATA_POSTERIOR DATE;
  declare variable V_NUMERO_ORDEM_INI INTEGER;
  declare variable V_DEPOSITO_INI DINHEIRO;
  declare variable V_SAIDA_INI DINHEIRO;
  declare variable V_DEPOSITO_PREVIO_MENSAL_ID INTEGER;
  declare variable V_SALDO_INI DINHEIRO;
  declare variable V_QTDE_LOGADO INTEGER;
  declare variable V_DIA_TEMP INTEGER;
BEGIN
  SELECT ULTIMO_DIA FROM W_ULTIMO_DIA_MES(:V_MES, :V_ANO)
  INTO :V_DIA_INFORMADO;
  V_MES_INFORMADO = :V_MES;
  V_ANO_INFORMADO = :V_ANO;

  MENSAGEM_ERRO = '';
  SALDO_DP_MES_ANTERIOR = 0;
  ANO = :V_ANO_INFORMADO;
  MES_STRING = '';

  TOTAL_DESPESA = 0;
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;
  TOTAL_BRUTO = 0;

  MES = :V_MES_INFORMADO;
  IF (:V_MES_INFORMADO < 10) THEN
  BEGIN
    V_DATA_INI = '01.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END
  ELSE
  BEGIN
    V_DATA_INI = '01.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END

  IF (:V_MES_INFORMADO < 10) THEN
  BEGIN
    V_DATA_FIM = V_DIA_INFORMADO||'.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END
  ELSE
  BEGIN
    V_DATA_FIM = V_DIA_INFORMADO||'.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END

  --saldo mes anterior
  if (:v_mes_informado = 1) then
  begin
    select SALDO_FINAL_MES
    from C_DEPOSITO_PREVIO_MENSAL
    where mes = 12
    and ano = :V_ANO_INFORMADO - 1
    into :SALDO_DP_MES_ANTERIOR;
  end
  else
  begin
    select SALDO_FINAL_MES from C_DEPOSITO_PREVIO_MENSAL
    where mes = :V_MES_INFORMADO - 1
    and ano = :V_ANO_INFORMADO
    into :SALDO_DP_MES_ANTERIOR;
  end

  if ((:V_MES = 3) and (:V_ANO = 2024)) then
  begin
    V_DATA_FIM = '17.03.2024';
  end

  FOR SELECT SUM(COALESCE(TOTAL_BRUTO,0)), SUM(COALESCE(TOTAL_DESPESA,0)), TIPO_RETORNO
    FROM C_DEPOSITO_PREVIO_DF(:V_DATA_INI,:V_DATA_FIM, 0)
    GROUP BY TIPO_RETORNO
    ORDER BY TIPO_RETORNO
    INTO :TOTAL_BRUTO, :TOTAL_DESPESA, :TIPO_RETORNO DO
  BEGIN
    select mes_em_string from w_mes_string(:mes)
    into :MES_STRING;
    SUSPEND;
  END
END ^

ALTER PROCEDURE C_EXTRATO_DEP_PREVIO_DF_NEW (V_MES INTEGER,
V_ANO INTEGER)
RETURNS (TOTAL_ENTRADA NUMERIC(18, 2),
TOTAL_SAIDA NUMERIC(18, 2),
QTDE INTEGER,
TIPO_RETORNO INTEGER,
TIPO_LIVRO VARCHAR(50) CHARACTER SET ISO8859_1,
DESCRICAO_DEPOSITO VARCHAR(1000) CHARACTER SET ISO8859_1,
SALDO_DP_MES_ANTERIOR NUMERIC(18, 2),
ANO INTEGER,
MES INTEGER,
MES_STRING VARCHAR(50) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_DATA_INI DATE;
  DECLARE VARIABLE V_DATA_FIM DATE;
  DECLARE VARIABLE V_ANO_INFORMADO INTEGER;
  DECLARE VARIABLE V_MES_INFORMADO INTEGER;
  DECLARE VARIABLE V_DIA_INFORMADO INTEGER;
  DECLARE VARIABLE V_DATA_POSTERIOR DATE;
  declare variable V_NUMERO_ORDEM_INI INTEGER;
  declare variable V_DEPOSITO_INI DINHEIRO;
  declare variable V_SAIDA_INI DINHEIRO;
  declare variable V_DEPOSITO_PREVIO_MENSAL_ID INTEGER;
  declare variable V_SALDO_INI DINHEIRO;
  declare variable V_QTDE_LOGADO INTEGER;
  declare variable V_DIA_TEMP INTEGER;
BEGIN
  SELECT ULTIMO_DIA FROM W_ULTIMO_DIA_MES(:V_MES, :V_ANO)
  INTO :V_DIA_INFORMADO;
  V_MES_INFORMADO = :V_MES;
  V_ANO_INFORMADO = :V_ANO;

  SALDO_DP_MES_ANTERIOR = 0;
  ANO = :V_ANO_INFORMADO;
  MES_STRING = '';
  MES = :V_MES_INFORMADO;

  TOTAL_SAIDA = 0;
  TOTAL_ENTRADA = 0;
  QTDE = 0;

  IF (:V_MES_INFORMADO < 10) THEN
  BEGIN
    V_DATA_INI = '01.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END
  ELSE
  BEGIN
    V_DATA_INI = '01.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END

  IF (:V_MES_INFORMADO < 10) THEN
  BEGIN
    V_DATA_FIM = V_DIA_INFORMADO||'.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END
  ELSE
  BEGIN
    V_DATA_FIM = V_DIA_INFORMADO||'.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END

  if ((:V_ANO = 2024) and (:V_MES = 3)) then
  begin
    V_DATA_INI = '18.03.2024';
  end

  --saldo mes anterior
  if (:v_mes_informado = 1) then
  begin
    select SALDO_FINAL_MES
    from C_DEPOSITO_PREVIO_MENSAL
    where mes = 12
    and ano = :V_ANO_INFORMADO - 1
    into :SALDO_DP_MES_ANTERIOR;
  end
  else
  begin
    select SALDO_FINAL_MES from C_DEPOSITO_PREVIO_MENSAL
    where mes = :V_MES_INFORMADO - 1
    and ano = :V_ANO_INFORMADO
    into :SALDO_DP_MES_ANTERIOR;
  end

  if ((:V_MES = 3) and (:V_ANO = 2024)) then
  begin
    V_DATA_INI = '18.03.2024';
  end

  FOR SELECT SUM(COALESCE(TOTAL_ENTRADA,0)), SUM(COALESCE(TOTAL_SAIDA,0)), TIPO_RETORNO
    FROM C_DIARIO_AUXILIAR_DEPOSITO_PREVIO_DF_NEW(:V_DATA_INI,:V_DATA_FIM, 0)
    GROUP BY TIPO_RETORNO
    ORDER BY TIPO_RETORNO
    INTO :TOTAL_ENTRADA, :TOTAL_SAIDA, :TIPO_RETORNO DO
  BEGIN
    select mes_em_string from w_mes_string(:mes)
    into :MES_STRING;
    SUSPEND;
  END
END ^

ALTER PROCEDURE C_EXTRATO_MENSAL_DIARIO_AUX_DF (V_MES INTEGER,
V_ANO INTEGER,
V_DIA VARCHAR(20) CHARACTER SET ISO8859_1 = '')
RETURNS (TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TIPO_RETORNO VARCHAR(1) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(260) CHARACTER SET ISO8859_1,
QTDE INTEGER,
TOTAL_EMOLUMENTO_REG NUMERIC(18, 2),
TOTAL_TAXA_REG NUMERIC(18, 2),
TOTAL_FUNDO_REG NUMERIC(18, 2),
QTDE_REG INTEGER,
TOTAL_EMOLUMENTO_AV NUMERIC(18, 2),
TOTAL_TAXA_AV NUMERIC(18, 2),
TOTAL_FUNDO_AV NUMERIC(18, 2),
QTDE_AV INTEGER,
TOTAL_EMOLUMENTO_CERT NUMERIC(18, 2),
TOTAL_TAXA_CERT NUMERIC(18, 2),
TOTAL_FUNDO_CERT NUMERIC(18, 2),
QTDE_CERT INTEGER,
TOTAL_EMOLUMENTO_BUSCA NUMERIC(18, 2),
TOTAL_TAXA_BUSCA NUMERIC(18, 2),
TOTAL_FUNDO_BUSCA NUMERIC(18, 2),
QTDE_BUSCA INTEGER,
TOTAL_EMOLUMENTO_REVAL NUMERIC(18, 2),
TOTAL_TAXA_REVAL NUMERIC(18, 2),
TOTAL_FUNDO_REVAL NUMERIC(18, 2),
QTDE_REVAL INTEGER,
TOTAL_EMOLUMENTO_FOLHA NUMERIC(18, 2),
TOTAL_TAXA_FOLHA NUMERIC(18, 2),
TOTAL_FUNDO_FOLHA NUMERIC(18, 2),
QTDE_FOLHA INTEGER,
SALDO_DP_MES_ANTERIOR NUMERIC(18, 2),
MENSAGEM_ERRO VARCHAR(300) CHARACTER SET ISO8859_1,
ANO INTEGER,
MES INTEGER,
MES_STRING VARCHAR(50) CHARACTER SET ISO8859_1,
TOTAL_REPASSE NUMERIC(18, 2),
TOTAL_LIQUIDO NUMERIC(18, 2),
TOTAL_DESPESA_DEDUTIVEL NUMERIC(18, 2),
TOTAL_DESPESA_NAO_DEDUTIVEL NUMERIC(18, 2),
TIPO_RECEITA INTEGER,
TOTAL_ISS NUMERIC(18, 2))
AS 
DECLARE VARIABLE V_DATA_INI DATE;
  DECLARE VARIABLE V_DATA_FIM DATE;
  DECLARE VARIABLE V_ANO_INFORMADO INTEGER;
  DECLARE VARIABLE V_MES_INFORMADO INTEGER;
  DECLARE VARIABLE V_DIA_INFORMADO INTEGER;
  DECLARE VARIABLE V_DATA_POSTERIOR DATE;
  declare variable V_NUMERO_ORDEM_INI INTEGER;
  declare variable V_DEPOSITO_INI DINHEIRO;
  declare variable V_SAIDA_INI DINHEIRO;
  declare variable V_DEPOSITO_PREVIO_MENSAL_ID INTEGER;
  declare variable V_SALDO_INI DINHEIRO;
  declare variable V_QTDE_LOGADO INTEGER;
  declare variable V_DIA_TEMP INTEGER;
BEGIN
  SELECT ULTIMO_DIA FROM W_ULTIMO_DIA_MES(:V_MES, :V_ANO)
  INTO :V_DIA_INFORMADO;
  V_MES_INFORMADO = :V_MES;
  V_ANO_INFORMADO = :V_ANO;

  MENSAGEM_ERRO = '';
  SALDO_DP_MES_ANTERIOR = 0;
  ANO = :V_ANO_INFORMADO;
  MES_STRING = '';

  TOTAL_DESPESA = 0;
  TOTAL_EMOLUMENTO = 0;
  TOTAL_TAXA_JUDICIARIA = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;
  TOTAL_EMOLUMENTO_REG = 0;
  TOTAL_TAXA_REG = 0;
  TOTAL_FUNDO_REG = 0;
  QTDE_REG = 0;
  TOTAL_EMOLUMENTO_AV = 0;
  TOTAL_TAXA_AV = 0;
  TOTAL_FUNDO_AV = 0;
  QTDE_AV = 0;
  TOTAL_EMOLUMENTO_CERT = 0;
  TOTAL_TAXA_CERT = 0;
  TOTAL_FUNDO_CERT = 0;
  QTDE_CERT = 0;
  TOTAL_EMOLUMENTO_BUSCA = 0;
  TOTAL_TAXA_BUSCA = 0;
  TOTAL_FUNDO_BUSCA = 0;
  QTDE_BUSCA = 0;
  TOTAL_EMOLUMENTO_REVAL = 0;
  TOTAL_TAXA_REVAL = 0;
  TOTAL_FUNDO_REVAL = 0;
  QTDE_REVAL = 0;
  TOTAL_EMOLUMENTO_FOLHA = 0;
  TOTAL_TAXA_FOLHA = 0;
  TOTAL_FUNDO_FOLHA = 0;
  QTDE_FOLHA = 0;
  TOTAL_BRUTO = 0;

  TOTAL_ISS = 0;

  if (coalesce(:V_DIA,'') <> '') then
  begin
    V_DATA_INI = :V_DIA;
    V_DATA_FIM = :V_DIA;
  end
  else if ((coalesce(:V_DIA,'') = '') and (:V_MES = 0)) then
  begin
    V_DATA_INI = '01.01'||'.'||:V_ANO_INFORMADO;
    V_DATA_FIM = '31.12'||'.'||:V_ANO_INFORMADO;
  end
  else if  ((:V_MES = 3) and (:V_ANO = 2024)) then
  begin
    V_DATA_INI = '01.03.2024';
    V_DATA_FIM = '17.03.2024';
  end
  else
  begin
    MES = :V_MES_INFORMADO;
    IF (:V_MES_INFORMADO < 10) THEN
    BEGIN
      V_DATA_INI = '01.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END
    ELSE
    BEGIN
      V_DATA_INI = '01.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END
  
    IF (:V_MES_INFORMADO < 10) THEN
    BEGIN
      V_DATA_FIM = V_DIA_INFORMADO||'.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END
    ELSE
    BEGIN
      V_DATA_FIM = V_DIA_INFORMADO||'.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END
  end

  /*if ((:V_MES = 3) and (:V_ANO = 2024)) then
  begin
    V_DATA_FIM = '17.03.2024';
  end*/

  FOR SELECT TIPO_RETORNO, SUM(COALESCE(TOTAL_DESPESA,0)),
    SUM(COALESCE(TOTAL_EMOLUMENTO,0)), SUM(COALESCE(TOTAL_TAXA_JUDICIARIA,0)), SUM(COALESCE(TOTAL_FUNDO,0)), SUM(COALESCE(QTDE,0)),
    SUM(COALESCE(TOTAL_EMOLUMENTO_REG,0)), SUM(COALESCE(TOTAL_TAXA_REG,0)), SUM(COALESCE(TOTAL_FUNDO_REG,0)), SUM(COALESCE(QTDE_REG,0)),
    SUM(COALESCE(TOTAL_EMOLUMENTO_AV,0)), SUM(COALESCE(TOTAL_TAXA_AV,0)), SUM(COALESCE(TOTAL_FUNDO_AV,0)), SUM(COALESCE(QTDE_AV,0)),
    SUM(COALESCE(TOTAL_EMOLUMENTO_CERT,0)), SUM(COALESCE(TOTAL_TAXA_CERT,0)), SUM(COALESCE(TOTAL_FUNDO_CERT,0)), SUM(COALESCE(QTDE_CERT,0)),
    SUM(COALESCE(TOTAL_EMOLUMENTO_BUSCA,0)), SUM(COALESCE(TOTAL_TAXA_BUSCA,0)), SUM(COALESCE(TOTAL_FUNDO_BUSCA,0)), SUM(COALESCE(QTDE_BUSCA,0)),
    SUM(COALESCE(TOTAL_EMOLUMENTO_REVAL,0)), SUM(COALESCE(TOTAL_TAXA_REVAL,0)), SUM(COALESCE(TOTAL_FUNDO_REVAL,0)), SUM(COALESCE(QTDE_REVAL,0)),
    SUM(COALESCE(TOTAL_EMOLUMENTO_FOLHA,0)), SUM(COALESCE(TOTAL_TAXA_FOLHA,0)), SUM(COALESCE(TOTAL_FUNDO_FOLHA,0)), SUM(COALESCE(QTDE_FOLHA,0)),
    SUM(COALESCE(TOTAL_ISS,0))
    FROM C_DIARIO_AUX_RECEITA_DESPESA_DF(:V_DATA_INI, :V_DATA_FIM, '', 0)
    GROUP BY TIPO_RETORNO
    ORDER BY TIPO_RETORNO
    INTO :TIPO_RECEITA, :TOTAL_DESPESA,
      :TOTAL_EMOLUMENTO, :TOTAL_TAXA_JUDICIARIA, :TOTAL_FUNDO, :QTDE,
      :TOTAL_EMOLUMENTO_REG, :TOTAL_TAXA_REG, :TOTAL_FUNDO_REG, :QTDE_REG,
      :TOTAL_EMOLUMENTO_AV, :TOTAL_TAXA_AV, :TOTAL_FUNDO_AV, :QTDE_AV,
      :TOTAL_EMOLUMENTO_CERT, :TOTAL_TAXA_CERT, :TOTAL_FUNDO_CERT, :QTDE_CERT,
      :TOTAL_EMOLUMENTO_BUSCA, :TOTAL_TAXA_BUSCA, :TOTAL_FUNDO_BUSCA, :QTDE_BUSCA,
      :TOTAL_EMOLUMENTO_REVAL, :TOTAL_TAXA_REVAL, :TOTAL_FUNDO_REVAL, :QTDE_REVAL,
      :TOTAL_EMOLUMENTO_FOLHA, :TOTAL_TAXA_FOLHA, :TOTAL_FUNDO_FOLHA, :QTDE_FOLHA,
      :TOTAL_ISS
  DO
  BEGIN
    TOTAL_REPASSE = 0;
    TIPO_RETORNO = 'C';

    select UPPER(mes_em_string) from w_mes_string(:mes)
    into :MES_STRING;

    IF (:TIPO_RECEITA = 1) THEN
    BEGIN
      DESCRICAO = 'Registro';
    END
    ELSE IF (:TIPO_RECEITA = 2) THEN
    BEGIN
      DESCRICAO = 'Registro (Penhora online)';
    END
    ELSE IF (:TIPO_RECEITA = 3) THEN
    BEGIN
      DESCRICAO = 'Registro (Convênio CODHAB)';
    END
    ELSE IF (:TIPO_RECEITA = 4) THEN
    BEGIN
      DESCRICAO = 'Averbação';
    END
    ELSE IF (:TIPO_RECEITA = 5) THEN
    BEGIN
      DESCRICAO = 'Averbação (Penhora online)';
    END
    ELSE IF (:TIPO_RECEITA = 6) THEN
    BEGIN
      DESCRICAO = 'Averbação (Convênio CODHAB)';
    END
    ELSE IF (:TIPO_RECEITA = 7) THEN
    BEGIN
      DESCRICAO = 'Procedimento de consolidação de propriedade fiduciária (e-RIDFT)';
    END
    ELSE IF (:TIPO_RECEITA = 8) THEN
    BEGIN
      DESCRICAO = 'Procedimento de consolidação de propriedade fiduciária (Balcão)';
    END
    ELSE IF (:TIPO_RECEITA = 9) THEN
    BEGIN
      DESCRICAO = 'Cancelamento de protocolo de registro (25%)';
    END
    ELSE IF (:TIPO_RECEITA = 10) THEN
    BEGIN
      DESCRICAO = 'Cancelamento de protocolo de registro (Penhora online) (25%)';
    END
    ELSE IF (:TIPO_RECEITA = 11) THEN
    BEGIN
      DESCRICAO = 'Cancelamento de protocolo de registro (Convênio CODHAB) (25%)';
    END
    ELSE IF (:TIPO_RECEITA = 12) THEN
    BEGIN
      DESCRICAO = 'Cancelamento de protocolo de averbação (25%)';
    END
    ELSE IF (:TIPO_RECEITA = 13) THEN
    BEGIN
      DESCRICAO = 'Cancelamento de protocolo de averbação (Penhora online) (25%)';
    END
    ELSE IF (:TIPO_RECEITA = 14) THEN
    BEGIN
      DESCRICAO = 'Cancelamento de protocolo de averbação (Convênio CODHAB) (25%)';
    END
    ELSE IF (:TIPO_RECEITA = 15) THEN
    BEGIN
      DESCRICAO = 'Certidão (Balcão)';
    END                     
    ELSE IF (:TIPO_RECEITA = 16) THEN
    BEGIN
      DESCRICAO = 'Busca (Balcão)';
    END
    ELSE IF (:TIPO_RECEITA = 17) THEN
    BEGIN
      DESCRICAO = 'Folha Excedente (Balcão)';
    END
    ELSE IF (:TIPO_RECEITA = 18) THEN
    BEGIN
      DESCRICAO = 'Certidão (ONR)';
    END
    ELSE IF (:TIPO_RECEITA = 19) THEN
    BEGIN
      DESCRICAO = 'Busca (ONR)';
    END
    ELSE IF (:TIPO_RECEITA = 20) THEN
    BEGIN
      DESCRICAO = 'Folha Excedente (ONR)';
    END
    ELSE IF (:TIPO_RECEITA = 21) THEN
    BEGIN
      DESCRICAO = 'E-protocolo - Registro e averbação (ONR)';
    END
    ELSE IF (:TIPO_RECEITA = 777) THEN
    BEGIN
      DESCRICAO = 'Despesas';
      TIPO_RETORNO = 'D';
    END

    SUSPEND;
  END
END ^

ALTER PROCEDURE C_EXTRATO_MEN_DIARIO_AUX_DF_NEW (V_MES INTEGER,
V_ANO INTEGER,
V_DIA VARCHAR(20) CHARACTER SET ISO8859_1 = '')
RETURNS (TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_ISS NUMERIC(18, 2),
TOTAL_DESPESA NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_BRUTO_COM_ISS NUMERIC(18, 2),
TIPO_RETORNO VARCHAR(1) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(260) CHARACTER SET ISO8859_1,
QTDE INTEGER,
ANO INTEGER,
MES INTEGER,
MES_STRING VARCHAR(50) CHARACTER SET ISO8859_1,
TIPO_RECEITA VARCHAR(10) CHARACTER SET ISO8859_1,
ITEM INTEGER,
LETRA VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_DATA_INI DATE;
  DECLARE VARIABLE V_DATA_FIM DATE;
  DECLARE VARIABLE V_ANO_INFORMADO INTEGER;
  DECLARE VARIABLE V_MES_INFORMADO INTEGER;
  DECLARE VARIABLE V_DIA_INFORMADO INTEGER;
  DECLARE VARIABLE V_DATA_POSTERIOR DATE;
  declare variable V_NUMERO_ORDEM_INI INTEGER;
  declare variable V_DEPOSITO_INI DINHEIRO;
  declare variable V_SAIDA_INI DINHEIRO;
  declare variable V_DEPOSITO_PREVIO_MENSAL_ID INTEGER;
  declare variable V_SALDO_INI DINHEIRO;
  declare variable V_QTDE_LOGADO INTEGER;
  declare variable V_DIA_TEMP INTEGER;
BEGIN
  SELECT ULTIMO_DIA FROM W_ULTIMO_DIA_MES(:V_MES, :V_ANO)
  INTO :V_DIA_INFORMADO;
  V_MES_INFORMADO = :V_MES;
  V_ANO_INFORMADO = :V_ANO;

  ANO = :V_ANO_INFORMADO;
  MES_STRING = '';

  TOTAL_DESPESA = 0;
  TOTAL_EMOLUMENTO = 0;
  TOTAL_FUNDO = 0;
  QTDE = 0;

  TOTAL_BRUTO = 0;

  TOTAL_ISS = 0;

  if (coalesce(:V_DIA,'') <> '') then
  begin
    V_DATA_INI = :V_DIA;
    V_DATA_FIM = :V_DIA;
  end
  else if ((coalesce(:V_DIA,'') = '') and (:V_MES = 0)) then
  begin
    V_DATA_INI = '01.01'||'.'||:V_ANO_INFORMADO;
    V_DATA_FIM = '31.12'||'.'||:V_ANO_INFORMADO;
  end
  else
  begin
    MES = :V_MES_INFORMADO;
    IF (:V_MES_INFORMADO < 10) THEN
    BEGIN
      V_DATA_INI = '01.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END
    ELSE
    BEGIN
      V_DATA_INI = '01.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END
  
    IF (:V_MES_INFORMADO < 10) THEN
    BEGIN
      V_DATA_FIM = :V_DIA_INFORMADO||'.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END
    ELSE
    BEGIN
      V_DATA_FIM = :V_DIA_INFORMADO||'.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
    END
  end

  if ((:V_ANO = 2024) and (:V_MES = 3)) then
  begin
    V_DATA_INI = '18.03.2024';
  end


  FOR SELECT ITEM_DF, ITEM, LETRA, NATUREZA, SUM(COALESCE(TOTAL_DESPESA,0)),
    SUM(COALESCE(TOTAL_EMOLUMENTO,0)), SUM(COALESCE(TOTAL_FUNDO,0)), SUM(COALESCE(QTDE,0)),
    SUM(COALESCE(TOTAL_ISS,0)), SUM(COALESCE(TOTAL_BRUTO,0)), (SUM(COALESCE(TOTAL_BRUTO,0))+SUM(COALESCE(TOTAL_ISS,0)))
    FROM C_DIARIO_AUX_REC_DESPESA_DF_NEW(:V_DATA_INI, :V_DATA_FIM, 'T', 0)
    GROUP BY ITEM_DF, ITEM, LETRA, NATUREZA
    ORDER BY ITEM, LETRA
    INTO :TIPO_RECEITA, :ITEM, :LETRA, :DESCRICAO, :TOTAL_DESPESA,
      :TOTAL_EMOLUMENTO, :TOTAL_FUNDO, :QTDE,
      :TOTAL_ISS, :TOTAL_BRUTO, :TOTAL_BRUTO_COM_ISS
  DO
  BEGIN
    select UPPER(mes_em_string) from w_mes_string(:mes)
    into :MES_STRING;

    IF (:TIPO_RECEITA = '99r') THEN
    BEGIN
      TIPO_RETORNO = 'R';
    END
    ELSE IF (:TIPO_RECEITA = '99d') THEN
    BEGIN
      TIPO_RETORNO = 'D';
    END
    ELSE
    BEGIN
      TIPO_RETORNO = 'C';
    END
    SUSPEND;
  END
END ^

ALTER PROCEDURE C_EXTRATO_MEN_DIARIO_AUX_DF_NEW_REGIME_CAIXA (V_MES INTEGER,
V_ANO INTEGER)
RETURNS (TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_FUNDO NUMERIC(18, 2),
TOTAL_ISS NUMERIC(18, 2),
TOTAL_BRUTO NUMERIC(18, 2),
TOTAL_GERAL_COM_ISS NUMERIC(18, 2),
TIPO_RETORNO VARCHAR(1) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(260) CHARACTER SET ISO8859_1,
ANO INTEGER,
MES INTEGER,
MES_STRING VARCHAR(50) CHARACTER SET ISO8859_1,
TIPO_RECEITA VARCHAR(10) CHARACTER SET ISO8859_1,
ITEM INTEGER,
LETRA VARCHAR(10) CHARACTER SET ISO8859_1,
TOTAL_DEVOLVIDO_EMOLUMENTO NUMERIC(18, 2),
TOTAL_DEVOLVIDO_FUNDO NUMERIC(18, 2),
TOTAL_DEVOLVIDO_ISS NUMERIC(18, 2),
TOTAL_DEVOLVIDO_BRUTO NUMERIC(18, 2),
TOTAL_DEVOLVIDO_BRUTO_COM_ISS NUMERIC(18, 2))
AS 
DECLARE VARIABLE V_DATA_INI DATE;
  DECLARE VARIABLE V_DATA_FIM DATE;
  DECLARE VARIABLE V_ANO_INFORMADO INTEGER;
  DECLARE VARIABLE V_MES_INFORMADO INTEGER;
  DECLARE VARIABLE V_DIA_INFORMADO INTEGER;
  DECLARE VARIABLE V_DATA_POSTERIOR DATE;
  declare variable V_NUMERO_ORDEM_INI INTEGER;
  declare variable V_DEPOSITO_INI DINHEIRO;
  declare variable V_SAIDA_INI DINHEIRO;
  declare variable V_DEPOSITO_PREVIO_MENSAL_ID INTEGER;
  declare variable V_SALDO_INI DINHEIRO;
  declare variable V_QTDE_LOGADO INTEGER;
  declare variable V_DIA_TEMP INTEGER;
BEGIN
  SELECT ULTIMO_DIA FROM W_ULTIMO_DIA_MES(:V_MES, :V_ANO)
  INTO :V_DIA_INFORMADO;
  V_MES_INFORMADO = :V_MES;
  V_ANO_INFORMADO = :V_ANO;

  ANO = :V_ANO_INFORMADO;
  MES_STRING = '';

  TOTAL_EMOLUMENTO = 0;
  TOTAL_FUNDO = 0;

  TOTAL_BRUTO = 0;

  TOTAL_ISS = 0;

  MES = :V_MES_INFORMADO;
  IF (:V_MES_INFORMADO < 10) THEN
  BEGIN
    V_DATA_INI = '01.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END
  ELSE
  BEGIN
    V_DATA_INI = '01.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END
  
  IF (:V_MES_INFORMADO < 10) THEN
  BEGIN
    V_DATA_FIM = :V_DIA_INFORMADO||'.0'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END
  ELSE
  BEGIN
    V_DATA_FIM = :V_DIA_INFORMADO||'.'||:V_MES_INFORMADO||'.'||:V_ANO_INFORMADO;
  END

  if ((:V_ANO = 2024) and (:V_MES = 3)) then
  begin
    V_DATA_INI = '18.03.2024';
  end

  FOR SELECT ITEM_DF, ITEM, LETRA, NATUREZA,
    SUM(COALESCE(TOTAL_GERAL_COM_ISS,0)) TOTAL_GERAL_COM_ISS,
    SUM(COALESCE(TOTAL_DEVOLVIDO_BRUTO_COM_ISS,0)) TOTAL_DEVOLVIDO_BRUTO_COM_ISS
    FROM C_DIARIO_AUXILIAR_RECEITA_DF_REGIME_CAIXA(:V_DATA_INI, :V_DATA_FIM)
    GROUP BY ITEM_DF, ITEM, LETRA, NATUREZA
    ORDER BY ITEM, LETRA
  INTO :TIPO_RECEITA, :ITEM, :LETRA, :DESCRICAO,
      :TOTAL_GERAL_COM_ISS, :TOTAL_DEVOLVIDO_BRUTO_COM_ISS DO
  BEGIN
    select UPPER(mes_em_string) from w_mes_string(:mes)
    into :MES_STRING;

    IF ((:TIPO_RECEITA = '88a') or (:TIPO_RECEITA = '99r') or (:TIPO_RECEITA = '99d'))  THEN
    BEGIN
      TIPO_RETORNO = 'D';

      TOTAL_DEVOLVIDO_ISS = round((coalesce(TOTAL_DEVOLVIDO_BRUTO_COM_ISS,0) * 5),2);
      TOTAL_DEVOLVIDO_ISS = round(cast((:TOTAL_DEVOLVIDO_ISS / 105) as numeric(18,5)),2);

      TOTAL_DEVOLVIDO_BRUTO = coalesce(:TOTAL_DEVOLVIDO_BRUTO_COM_ISS,0) - coalesce(:TOTAL_DEVOLVIDO_ISS,0);

      TOTAL_DEVOLVIDO_FUNDO = round((coalesce(TOTAL_DEVOLVIDO_BRUTO,0) * 7),2);
      TOTAL_DEVOLVIDO_FUNDO = round(cast((:TOTAL_DEVOLVIDO_FUNDO / 107) as numeric(18,5)),2);

      TOTAL_DEVOLVIDO_EMOLUMENTO = coalesce(:TOTAL_DEVOLVIDO_BRUTO,0) - coalesce(:TOTAL_DEVOLVIDO_FUNDO,0);

      TOTAL_EMOLUMENTO = 0;
      TOTAL_FUNDO = 0;
      TOTAL_ISS = 0;
      TOTAL_BRUTO = 0;
      TOTAL_GERAL_COM_ISS = 0;
    END
    ELSE
    BEGIN
      TIPO_RETORNO = 'C';

      if (:TIPO_RECEITA = '33') then --outras receitas
      begin
        TOTAL_ISS = 0;

        total_bruto = coalesce(:TOTAL_GERAL_COM_ISS,0);

        TOTAL_FUNDO = 0;
        total_emolumento = 0;
      end
      else
      begin
        TOTAL_ISS = round((coalesce(TOTAL_GERAL_COM_ISS,0) * 5),2);
        TOTAL_ISS = round(cast((:TOTAL_ISS / 105) as numeric(18,5)),2);

        total_bruto = coalesce(:TOTAL_GERAL_COM_ISS,0) - coalesce(:total_iss,0);

        TOTAL_FUNDO = round((coalesce(total_bruto,0) * 7),2);
        TOTAL_FUNDO = round(cast((:TOTAL_FUNDO / 107) as numeric(18,5)),2);

        total_emolumento = coalesce(:total_bruto,0) - coalesce(:TOTAL_FUNDO,0);
      end

      TOTAL_DEVOLVIDO_EMOLUMENTO = 0;
      TOTAL_DEVOLVIDO_FUNDO = 0;
      TOTAL_DEVOLVIDO_ISS = 0;
      TOTAL_DEVOLVIDO_BRUTO = 0;
      TOTAL_DEVOLVIDO_BRUTO_COM_ISS = 0;
    END
    SUSPEND;
  END
END ^

ALTER PROCEDURE C_INSERE_CAIXA_ITEM (ESPECIE_PAGAMENTO VARCHAR_001,
CAIXA_SERVICO_ID INTEGER,
USUARIO_SERVICO_ID INTEGER,
USUARIO_CAIXA_ID INTEGER,
CHAVE_SERVICO INTEGER,
DESCRICAO VARCHAR_120,
SITUACAO VARCHAR_001,
TIPO_DOCUMENTO VARCHAR_001,
TIPO_TRANSACAO VARCHAR_001,
VALOR_SERVICO DINHEIRO,
VALOR_PAGO DINHEIRO,
OBSERVACAO VARCHAR_120,
CAIXA_CHEQUE_ID INTEGER,
HORA_PAGAMENTO VARCHAR_010,
CAIXA_ID INTEGER,
RECIBO_ID INTEGER,
TIPO_SERVICO VARCHAR_003,
QTD INTEGER,
APRESENTANTE VARCHAR_120,
REGISTRADO VARCHAR_001,
EMOLUMENTO DINHEIRO,
TAXA_JUDICIARIA DINHEIRO,
FUNDESP DINHEIRO,
DESCONTO DINHEIRO,
VALOR_DOCUMENTO DINHEIRO,
OUTRA_TAXA1 DINHEIRO,
CHAVE_SERVICO_SEC INTEGER,
EMOLUMENTO_ITEM_ID INTEGER,
CAIXA_REGISTROSELO_ID INTEGER,
FUNDO_RI DINHEIRO,
TABELA VARCHAR_030,
CAMPO_ID NUMERICO)
RETURNS (STATUS VARCHAR_001,
CAIXA_ITEM_ID NUMERICO)
AS 
declare variable USAR_ISS VARCHAR_001;
declare variable VPSITUACAO VARCHAR_001;
declare variable SITUACAO_PAGAMENTO VARCHAR_001;
declare variable USAR_ARREDONDAMENTO VARCHAR_001;
declare variable COBRAR_ISS_USUARIO VARCHAR_001;
declare variable PERCENTUAL_ISS DINHEIRO;
declare variable VALOR_ISS DINHEIRO;
declare variable TOTAL DINHEIRO;
BEGIN
   SELECT COALESCE(VALOR, 'N') FROM G_CONFIG
   WHERE NOME  = 'ENVIAR_VALOR_CAIXA_CONFIRMADO'
     AND SECAO = 'CAIXA'
     AND CONFIG_GRUPO_ID IN ( SELECT CONFIG_GRUPO_ID FROM G_CONFIG_GRUPO WHERE SISTEMA_ID = 13 AND DESCRICAO = 'PRINCIPAL') INTO :SITUACAO_PAGAMENTO;

   SELECT COALESCE(VALOR, 'N') FROM G_CONFIG
   WHERE NOME  = 'USAR_ARRENDONDAMENTO_SEM_CASA_DECIMAL'
     AND SECAO = 'GERAL'
     AND CONFIG_GRUPO_ID IN ( SELECT CONFIG_GRUPO_ID FROM G_CONFIG_GRUPO WHERE SISTEMA_ID = 5 AND DESCRICAO = 'PRINCIPAL') INTO :USAR_ARREDONDAMENTO;

   SELECT COALESCE(VALOR, 'N') FROM G_CONFIG
   WHERE NOME  = 'USAR_ISS'
     AND SECAO = 'GERAL'
     AND CONFIG_GRUPO_ID IN ( SELECT CONFIG_GRUPO_ID FROM G_CONFIG_GRUPO WHERE SISTEMA_ID = 5 AND DESCRICAO = 'PRINCIPAL') INTO :USAR_ISS;

   SELECT COALESCE(VALOR, 'N') FROM G_CONFIG
   WHERE NOME  = 'COBRAR_ISS_USUARIO'
     AND SECAO = 'GERAL'
     AND CONFIG_GRUPO_ID IN ( SELECT CONFIG_GRUPO_ID FROM G_CONFIG_GRUPO WHERE SISTEMA_ID = 5 AND DESCRICAO = 'PRINCIPAL') INTO :COBRAR_ISS_USUARIO;

  SELECT REPLACE(COALESCE(VALOR, 0),',','.') FROM G_CONFIG
   WHERE NOME  = 'PERCENTUAL_ISS'
     AND SECAO = 'GERAL'
     AND CONFIG_GRUPO_ID IN ( SELECT CONFIG_GRUPO_ID FROM G_CONFIG_GRUPO WHERE SISTEMA_ID = 5 AND DESCRICAO = 'PRINCIPAL') INTO :PERCENTUAL_ISS;

  IF (:USAR_ISS = 'N') THEN
  BEGIN
    SELECT COALESCE(VALOR, 'N') FROM G_CONFIG
   WHERE NOME  = 'USAR_ISS'
     AND SECAO = 'ISS'
     AND CONFIG_GRUPO_ID IN ( SELECT CONFIG_GRUPO_ID FROM G_CONFIG_GRUPO WHERE SISTEMA_ID = 13  AND DESCRICAO = 'TITULO') INTO :USAR_ISS;

   SELECT COALESCE(VALOR, 'N') FROM G_CONFIG
   WHERE NOME  = 'COBRAR_ISS'
     AND SECAO = 'ISS'
     AND CONFIG_GRUPO_ID IN ( SELECT CONFIG_GRUPO_ID FROM G_CONFIG_GRUPO WHERE SISTEMA_ID = 13  AND DESCRICAO = 'TITULO') INTO :COBRAR_ISS_USUARIO;

  SELECT REPLACE(COALESCE(VALOR, 0),',','.') FROM G_CONFIG
   WHERE NOME  = 'PERCENTUAL_ISS'
     AND SECAO = 'ISS'
     AND CONFIG_GRUPO_ID IN ( SELECT CONFIG_GRUPO_ID FROM G_CONFIG_GRUPO WHERE SISTEMA_ID = 13  AND DESCRICAO = 'TITULO') INTO :PERCENTUAL_ISS;
 END 
TOTAL = :VALOR_PAGO;

 IF ((:USAR_ISS = 'S') AND (:COBRAR_ISS_USUARIO = 'S') AND (:PERCENTUAL_ISS > 0 ))THEN
   BEGIN
     VALOR_ISS = ROUND((:EMOLUMENTO * :PERCENTUAL_ISS)/100,2);
     VALOR_SERVICO = :VALOR_SERVICO + :VALOR_ISS;
     VALOR_PAGO = :VALOR_PAGO + :VALOR_ISS;
     if ((:total -:VALOR_ISS) = (:VALOR_PAGO - (:VALOR_ISS*2))) then
       VALOR_PAGO = :total;
   END
   ELSE VALOR_ISS = 0;
   IF (:usar_arredondamento = 'S')THEN
   BEGIN
     VALOR_SERVICO = ROUND(:VALOR_SERVICO,0);
     VALOR_PAGO    = ROUND(:VALOR_PAGO,0);
   END
   ELSE
     TOTAL = :VALOR_PAGO;

   if (SITUACAO_PAGAMENTO = 'N') then
   begin
     VPSITUACAO = '3';
   end
   else
     VPSITUACAO = '4';

   STATUS = 'N';
   CAIXA_ITEM_ID = (SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('C_CAIXA_ITEM'));
   INSERT INTO C_CAIXA_ITEM (ESPECIE_PAGAMENTO, CAIXA_ITEM_ID, CAIXA_SERVICO_ID, USUARIO_SERVICO_ID, USUARIO_CAIXA_ID,
                             CHAVE_SERVICO, DESCRICAO, DATA_PAGAMENTO, SITUACAO, TIPO_DOCUMENTO, TIPO_TRANSACAO,
                             VALOR_SERVICO, VALOR_PAGO, OBSERVACAO, CAIXA_CHEQUE_ID, HORA_PAGAMENTO, CAIXA_ID, RECIBO_ID,
                             TIPO_SERVICO, QTD, APRESENTANTE, REGISTRADO, EMOLUMENTO,
                             TAXA_JUDICIARIA, FUNDESP, DESCONTO, VALOR_DOCUMENTO, OUTRA_TAXA1, CHAVE_SERVICO_SEC,
                             EMOLUMENTO_ITEM_ID, CAIXA_REGISTROSELO_ID, FUNDO_RI, ISS,TABELA,CAMPO_ID)
   VALUES (:ESPECIE_PAGAMENTO, :CAIXA_ITEM_ID, :CAIXA_SERVICO_ID, :USUARIO_SERVICO_ID, :USUARIO_CAIXA_ID, :CHAVE_SERVICO,
           :DESCRICAO, CURRENT_DATE, :VPSITUACAO, :TIPO_DOCUMENTO, :TIPO_TRANSACAO, :VALOR_SERVICO, :VALOR_PAGO,
           :OBSERVACAO, :CAIXA_CHEQUE_ID, :HORA_PAGAMENTO, :CAIXA_ID, :RECIBO_ID, :TIPO_SERVICO, :QTD, :APRESENTANTE,
           :REGISTRADO, :EMOLUMENTO, :TAXA_JUDICIARIA, :FUNDESP, :DESCONTO,
           :VALOR_DOCUMENTO, :OUTRA_TAXA1, :CHAVE_SERVICO_SEC, :EMOLUMENTO_ITEM_ID, :CAIXA_REGISTROSELO_ID, :FUNDO_RI, :VALOR_ISS,:TABELA,:CAMPO_ID);

   STATUS = 'S';
   SUSPEND;
END ^

