ALTER PROCEDURE C_RETORNA_MES_ANO (V_DATA TIMESTAMP)
RETURNS (ANO NUMERIC(15, 2),
MES_ANO VARCHAR(100) CHARACTER SET ISO8859_1)
AS 
declare variable MES integer;
BEGIN
  ANO = extract (YEAR  FROM V_DATA);
  MES = extract (MONTH FROM V_DATA);
  IF (MES = 1) THEN
  BEGIN
    MES_ANO = '01 JANEIRO';
  END
  ELSE
   IF (MES = 2) THEN
  BEGIN
    MES_ANO = '02 FEVEREIRO';
  END
  ELSE
   IF (MES = 3) THEN
  BEGIN
    MES_ANO = '03 MARÇO';
  END
  ELSE
   IF (MES = 4) THEN
  BEGIN
    MES_ANO = '04 ABRIL';
  END
  ELSE
   IF (MES = 5) THEN
  BEGIN
    MES_ANO = '05 MAIO';
  END
  ELSE
   IF (MES = 6) THEN
  BEGIN
    MES_ANO = '06 JUNHO';
  END
  ELSE
   IF (MES = 7) THEN
  BEGIN
    MES_ANO = '07 JULHO';
  END
  ELSE
   IF (MES = 8) THEN
  BEGIN
    MES_ANO = '08 AGOSTO';
  END
  ELSE
   IF (MES = 9) THEN
  BEGIN
    MES_ANO = '09 SETEMBRO';
  END
  ELSE
   IF (MES = 10) THEN
  BEGIN
    MES_ANO = '10 OUTUBRO';
  END
  ELSE
   IF (MES = 11) THEN
  BEGIN
    MES_ANO = '11 NOVEMBRO';
  END
  ELSE
   IF (MES = 12) THEN
  BEGIN
    MES_ANO = '12 DEZEMBRO';
  END
  SUSPEND;
END ^

ALTER PROCEDURE C_SOLICITAR_SELO_TO (VPIDSISTEMA VARCHAR_003,
VPDESCRICAO VARCHAR_030,
VPQTD VARCHAR(4) CHARACTER SET ISO8859_1)
RETURNS (VPSELOS VARCHAR_030)
AS 
DECLARE VARIABLE VISELO varchar_030;
DECLARE VARIABLE VILISTA varchar_060;
BEGIN
  VILISTA = '';
  FOR SELECT FIRST(:VPQTD) CAST(SL.SELO_LIVRO_ID AS INTEGER)
      FROM G_SELO_LIVRO SL
      LEFT OUTER JOIN G_SELO_LOTE ST  ON SL.SELO_LOTE_ID = ST.SELO_LOTE_ID
      LEFT OUTER JOIN G_SELO_GRUPO SG ON ST.SELO_GRUPO_ID = SG.SELO_GRUPO_ID
      WHERE ST.SITUACAO = 'I'
        AND SL.SELO_SITUACAO_ID = 1
        AND SG.SISTEMA_ID = :VPIDSISTEMA
        AND SG.DESCRICAO = :VPDESCRICAO
      ORDER BY SL.SELO_LIVRO_ID ASC
  INTO :VISELO DO
  BEGIN
    IF (:VILISTA = '') THEN
      VILISTA = VISELO;
    ELSE VILISTA = VILISTA ||', '||VISELO;
  END
  UPDATE G_SELO_LIVRO SET
  SELO_SITUACAO_ID = 2
  WHERE CAST(SELO_LIVRO_ID as varchar_030) in (:VILISTA);
  VPSELOS = VILISTA;
  SUSPEND;
END ^

ALTER PROCEDURE C_TOTAL_MENSAL_DEP_PREVIO_GO (V_DATA_INICIAL DATE,
V_DATA_FINAL DATE)
RETURNS (TOTAL NUMERIC(18, 4),
DESCRICAO VARCHAR(60) CHARACTER SET ISO8859_1)
AS 
BEGIN
  select coalesce(Sum(VALOR_TOTAL),0),'DEPÓSITO PRÉVIO'  FROM c_deposito_previo_go(:V_DATA_INICIAL, :V_DATA_FINAL) where tipo_lancamento = 'D'
  INTO :TOTAL, :DESCRICAO;
  SUSPEND;
  select coalesce(Sum(VALOR_TOTAL),0),'CONVERSÃO EM RECEITA'  FROM c_deposito_previo_go(:V_DATA_INICIAL, :V_DATA_FINAL) where tipo_lancamento = 'R'
  INTO :TOTAL, :DESCRICAO;   SUSPEND;
  select coalesce(Sum(VALOR_TOTAL),0),'SAÍDA - DEVOLUÇÃO USUÁRIO'  FROM c_deposito_previo_go(:V_DATA_INICIAL, :V_DATA_FINAL) where tipo_lancamento IN( 'S','V')
  INTO :TOTAL, :DESCRICAO;   SUSPEND;

  SELECT 'SALDO',
        (select coalesce(Sum(VALOR_TOTAL),0)  FROM c_deposito_previo_go(:V_DATA_INICIAL, :V_DATA_FINAL)where tipo_lancamento = 'D') -
        ((SELECT coalesce(Sum(VALOR_TOTAL),0)*-1  FROM c_deposito_previo_go(:V_DATA_INICIAL, :V_DATA_FINAL)where tipo_lancamento = 'R') +
        (SELECT coalesce(Sum(VALOR_TOTAL),0)*-1  FROM c_deposito_previo_go(:V_DATA_INICIAL, :V_DATA_FINAL)where tipo_lancamento = 'S'))  DEV_CLIENTE
  from RDB$DATABASE
  INTO :DESCRICAO, :TOTAL;   SUSPEND;
END ^

ALTER PROCEDURE C_VALIDA_SELO (SELO_LIVRO_ID VARCHAR_015,
AGRUPADOR VARCHAR_030,
TIPO_ATO INTEGER,
NUM_ATO VARCHAR_030,
TABELA VARCHAR_030,
CAMPO_ID VARCHAR_030)
RETURNS (VPERRO VARCHAR(500) CHARACTER SET ISO8859_1)
AS 
declare variable V_VALOR_ISENTADO NUMERICO;
declare variable VERRO varchar(500);
declare variable V_ATO_ISENTADO NUMERICO;
declare variable V_NUM_ATO_AGRUPADOR integer;
declare variable V_NUM_ATO_EXITE integer;
BEGIN
VPERRO ='';
VERRO = ''; --'ERRO TIPO DE ATO: '||TIPO_ATO||' COM AGRUPADOR ERRADO'; --NUM_ATO É O Nº DO SELO

   --(TIPO_ATO = 1289) -- Civil (TIPO_ATO = 1277) -- RI  (TIPO_ATO = 963)  -- Notas  (TIPO_ATO = 1359) -- RTD (TIPO_ATO = 1393) THEN-- Protesto
  IF   ( (TIPO_ATO = 3006)or (TIPO_ATO = 2970) or (TIPO_ATO = 2447) or (TIPO_ATO = 3078)or (TIPO_ATO = 3114)) THEN
  BEGIN
    V_ATO_ISENTADO = (SELECT COALESCE(GS.id_do_ato_isentado,0) FROM G_SELO_LIVRO GS WHERE GS.selo_livro_id = :selo_livro_id);

    IF (V_ATO_ISENTADO = 0) THEN
      VPERRO = 'Erro: ID do Ato Isentado Não Informado';

    V_VALOR_ISENTADO = (SELECT COALESCE(GS.valor_emolumento,0)+
                               COALESCE(GS.valor_taxa_judiciaria,0)+
                               COALESCE(GS.valor_fundesp,0)+
                               COALESCE(GS.valor_iss,0)+
                               COALESCE(GS.valor_total,0) FROM G_SELO_LIVRO GS WHERE GS.selo_livro_id = :selo_livro_id);

    IF (V_VALOR_ISENTADO > 0) THEN
      VPERRO = 'Erro: Valor Ato Isentado Inválido';
  END

  SUSPEND;
END ^

ALTER PROCEDURE C_VALIDA_SERVICO_SELO (TIPO_ATO VARCHAR_015,
TABELA VARCHAR_030,
CAMPO_ID VARCHAR_030)
RETURNS (VPERRO VARCHAR(500) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_QTD_SERVICO INTEGER;
DECLARE VARIABLE V_QTD_SELO INTEGER;
DECLARE VARIABLE V_QTD_TIPO_ATO INTEGER;
DECLARE VARIABLE V_QTD_TIPO_SELO INTEGER;
DECLARE VARIABLE V_ERRO_QTD VARCHAR_120;
DECLARE VARIABLE V_ERRO_NATUREZA VARCHAR_120;
DECLARE VARIABLE V_SQL varchar_1000;
BEGIN
VPERRO ='OK';
V_ERRO_QTD = 'QUANTIDADE DE ITENS DO SERVIÇO DIFERE DA QUANTIDADE DE SELOS GERADOS.';
V_ERRO_NATUREZA =  'SELO GERADO NÃO CONFERE COM SERVIÇO';

      IF ((TABELA = 'T_ATO')) THEN
      BEGIN
          V_SQL = ' SELECT SUM(QUANTIDADE) FROM T_ATO_VINCULOVALOR WHERE ATO_ID = '|| :CAMPO_ID;
          execute statement V_SQL
          INTO :V_QTD_SERVICO;
            
            
          V_SQL = ' SELECT COUNT(SELO_LIVRO_ID) FROM G_SELO_LIVRO WHERE TABELA =  ''T_ATO'' AND CAMPO_ID ='|| :CAMPO_ID;
          execute statement V_SQL
          INTO :V_QTD_SELO;
            
          IF (:V_QTD_SERVICO <> :V_QTD_SELO) THEN
            VPERRO = V_ERRO_QTD;
          ELSE
          BEGIN
                V_SQL =' SELECT COUNT(NUMERO) FROM g_selo_grupo GP
                         LEFT JOIN g_emolumento_item GI ON GP.selo_grupo_id = GI.selo_grupo_id
                         LEFT JOIN t_ato_vinculovalor TV ON TV.emolumento_item_id = GI.emolumento_item_id
                         WHERE TV.ato_id = '||:campo_id||' AND CAST(GP.numero AS INTEGER) = CAST('||:TIPO_ATO||' AS INTEGER)';
                execute statement V_SQL
                INTO :v_qtd_tipo_ato;
    
                V_SQL = ' SELECT COUNT(CAMPO_ID) FROM G_SELO_LIVRO GL
                         LEFT JOIN G_SELO_LOTE GS ON GL.selo_lote_id = GS.selo_lote_id
                         LEFT JOIN G_SELO_GRUPO GP ON GP.selo_grupo_id = GS.selo_grupo_id
                         WHERE GL.tabela = ''T_ATO'' AND GL.campo_id = '||:campo_id||
                         'and CAST(GP.numero AS INTEGER) = CAST('||:tipo_ato|| 'AS INTEGER)';
                execute statement V_SQL
                INTO :V_QTD_TIPO_SELO;
    

                if (v_qtd_tipo_ato <> V_QTD_TIPO_SELO) then
                  VPERRO = V_ERRO_NATUREZA;
          END
      END

      IF (TABELA = 'T_SERVICO_ITEMPEDIDO')  THEN
      BEGIN
          V_SQL = 'SELECT SUM(QTD) FROM T_SERVICO_ITEMPEDIDO WHERE SERVICO_ITEMPEDIDO_ID = '|| :CAMPO_ID;
          execute statement V_SQL
          INTO :V_QTD_SERVICO;
        
        
          V_SQL = 'SELECT COUNT(SELO_LIVRO_ID) FROM G_SELO_LIVRO WHERE TABELA = ''T_SERVICO_ITEMPEDIDO'' AND CAMPO_ID = '||:CAMPO_ID;
          execute statement V_SQL
          INTO :V_QTD_SELO;
        
          IF (:V_QTD_SERVICO <> :V_QTD_SELO) THEN
            VPERRO = V_ERRO_QTD;
          ELSE
          BEGIN
                V_SQL = 'SELECT SUM(TV.qtd) FROM g_selo_grupo GP
                LEFT JOIN g_emolumento_item GI ON GP.selo_grupo_id = GI.selo_grupo_id
                LEFT JOIN T_SERVICO_ITEMPEDIDO TV ON TV.emolumento_item_id = GI.emolumento_item_id
                WHERE TV.SERVICO_ITEMPEDIDO_ID = '||:campo_id ||' AND CAST(GP.numero AS INTEGER) = CAST('||:TIPO_ATO||' AS INTEGER)';
                execute statement V_SQL
                INTO :v_qtd_tipo_ato;
    
                V_SQL = 'SELECT COUNT(CAMPO_ID) FROM G_SELO_LIVRO GL
                LEFT JOIN G_SELO_LOTE GS ON GL.selo_lote_id = GS.selo_lote_id
                LEFT JOIN G_SELO_GRUPO GP ON GP.selo_grupo_id = GS.selo_grupo_id
                WHERE GL.tabela = ''T_SERVICO_ITEMPEDIDO'' AND GL.campo_id = '||:campo_id||
              ' and CAST(GP.numero AS INTEGER) = CAST('||:tipo_ato||' AS INTEGER)';
                execute statement V_SQL
                INTO :V_QTD_TIPO_SELO;
    
                if (CAST(TIPO_ATO AS INTEGER) not between  958 and 959) then
                begin
                  if ((v_qtd_tipo_ato <> V_QTD_TIPO_SELO)AND ((CAST(TIPO_ATO AS INTEGER) <> 958))) then
                    VPERRO = V_ERRO_NATUREZA;
                end
          END
      END

      IF (TABELA = 'D_DOCUMENTO') THEN
      BEGIN
          V_SQL = 'SELECT SUM(QTD) FROM D_DOCUMENTO_ITENS WHERE DOCUMENTO_ID = '||:CAMPO_ID;
          execute statement V_SQL
          INTO :V_QTD_SERVICO;
            
            
          V_SQL = 'SELECT COUNT(SELO_LIVRO_ID) FROM G_SELO_LIVRO WHERE TABELA = ''D_DOCUMENTO'' AND CAMPO_ID ='|| :CAMPO_ID;
          execute statement V_SQL
          INTO :V_QTD_SELO;
            
          IF (:V_QTD_SERVICO <> :V_QTD_SELO) THEN
            VPERRO = V_ERRO_QTD;
          ELSE
          BEGIN
            V_SQL = 'SELECT (TV.qtd) FROM g_selo_grupo GP
            LEFT JOIN g_emolumento_item GI ON GP.selo_grupo_id = GI.selo_grupo_id
            LEFT JOIN d_documento_itens TV ON TV.emolumento_item_id = GI.emolumento_item_id
            WHERE TV.documento_id = '||:campo_id|| ' AND CAST(GP.numero AS INTEGER) = CAST( '||:TIPO_ATO||' AS INTEGER)';
            execute statement V_SQL
            INTO :v_qtd_tipo_ato;

            V_SQL = 'SELECT COUNT(CAMPO_ID) FROM G_SELO_LIVRO GL
            LEFT JOIN G_SELO_LOTE GS ON GL.selo_lote_id = GS.selo_lote_id
            LEFT JOIN G_SELO_GRUPO GP ON GP.selo_grupo_id = GS.selo_grupo_id
            WHERE GL.tabela = ''D_DOCUMENTO'' AND GL.campo_id = '||:campo_id||
            'and CAST(GP.numero AS INTEGER) = CAST('||:tipo_ato||' AS INTEGER)';
            execute statement V_SQL
            INTO :V_QTD_TIPO_SELO;

            if (v_qtd_tipo_ato <> V_QTD_TIPO_SELO) then
              VPERRO = V_ERRO_NATUREZA;
          END
      END

      IF (TABELA = 'D_CERTIDAO') THEN
      BEGIN
          V_SQL = 'SELECT SUM(QTD_PAGINA) FROM D_CERTIDAO  WHERE CERTIDAO_ID = '|| :CAMPO_ID;
          execute statement V_SQL
          INTO :V_QTD_SERVICO;
            
            
          V_SQL = 'SELECT COUNT(SELO_LIVRO_ID) FROM G_SELO_LIVRO WHERE TABELA = ''D_CERTIDAO'' AND CAMPO_ID = '||:CAMPO_ID;
          execute statement V_SQL
          INTO :V_QTD_SELO;
            
          IF (:V_QTD_SERVICO <> :V_QTD_SELO) THEN
            VPERRO = V_ERRO_QTD;
          ELSE
          BEGIN
                V_SQL = 'SELECT COUNT(GP.NUMERO) FROM g_selo_grupo GP
                LEFT JOIN g_emolumento_item GI ON GP.selo_grupo_id = GI.selo_grupo_id
                LEFT JOIN D_CERTIDAO TV ON TV.emolumento_item_id = GI.emolumento_item_id
                WHERE TV.certidao_id = '||:campo_id|| 'AND CAST(GP.numero AS INTEGER) = CAST('||:TIPO_ATO|| ' AS INTEGER)';
                execute statement V_SQL
                INTO :v_qtd_tipo_ato;
    
                V_SQL = 'SELECT COUNT(CAMPO_ID) FROM G_SELO_LIVRO GL
                LEFT JOIN G_SELO_LOTE GS ON GL.selo_lote_id = GS.selo_lote_id
                LEFT JOIN G_SELO_GRUPO GP ON GP.selo_grupo_id = GS.selo_grupo_id
                WHERE GL.tabela = ''D_CERTIDAO'' AND GL.campo_id = '||:campo_id ||
                'and CAST(GP.numero AS INTEGER) = CAST('||:tipo_ato|| ' AS INTEGER)';
                execute statement V_SQL
                INTO :V_QTD_TIPO_SELO;
            if (v_qtd_tipo_ato <> V_QTD_TIPO_SELO) then
              VPERRO = V_ERRO_NATUREZA;
        END
      END

      IF (TABELA = 'V_SERVICO_REALIZADO') THEN
      BEGIN

          V_SQL = 'SELECT SUM(QTD) FROM V_SERVICO_REALIZADO WHERE SERVICO_REALIZADO_ID = '||:CAMPO_ID;
          execute statement V_SQL
          INTO :V_QTD_SERVICO;
            
            
          V_SQL = 'SELECT COUNT(SELO_LIVRO_ID) FROM G_SELO_LIVRO WHERE TABELA = '||:TABELA|| 'AND CAMPO_ID = '||:CAMPO_ID;
          execute statement V_SQL
          INTO :V_QTD_SELO;
    
          IF (:V_QTD_SERVICO <> :V_QTD_SELO) THEN
            VPERRO = V_ERRO_QTD;
          ELSE
          BEGIN

            V_SQL = 'SELECT cast(gp.numero as integer) FROM G_SELO_LIVRO GL
            LEFT JOIN G_SELO_LOTE GS ON GL.selo_lote_id = GS.selo_lote_id
            LEFT JOIN G_SELO_GRUPO GP ON GP.selo_grupo_id = GS.selo_grupo_id
            WHERE GL.tabela = ''V_SERVICO_REALIZADO'' AND GL.campo_id = '||:campo_id||
          ' and CAST(GP.numero AS INTEGER) = CAST('||:tipo_ato||' AS INTEGER)';
            execute statement V_SQL
            INTO :V_QTD_TIPO_SELO;

            if (V_QTD_TIPO_SELO <> CAST(:tipo_ato AS INTEGER)) then
              VPERRO = V_ERRO_NATUREZA;
          END
      END

      IF ((TABELA = 'P_TITULO') AND (TIPO_ATO = 1372)) THEN
      BEGIN

          V_SQL = 'SELECT COUNT(PESSOA_VINCULO_ID) FROM P_PESSOA_VINCULO  WHERE TIPO_VINCULO = ''DEVEDOR''
          AND  GERAR_SELO = ''S'' AND TITULO_ID = '|| :CAMPO_ID;
          execute statement V_SQL
          INTO :V_QTD_SERVICO;
            
            
          V_SQL = 'SELECT COUNT(SELO_LIVRO_ID) FROM G_SELO_LIVRO WHERE TABELA = ''P_TITULO'' AND CAMPO_ID = '||:CAMPO_ID||
          'AND DESCRICAO LIKE ''%INTIMAÇÃO%''';
          execute statement V_SQL
          INTO :V_QTD_SELO;
            
          IF (:V_QTD_SERVICO <> :V_QTD_SELO) THEN
            VPERRO = V_ERRO_QTD;

      END

      IF (TABELA = 'R_PEDIDO_ITEM') THEN
      BEGIN

      END
    
      IF (TABELA = 'R_PEDIDO_ITEM_NUMERO') THEN
      BEGIN
    
      END

   SUSPEND;
END ^

ALTER PROCEDURE C_VALORES_FUNDOS_GO (VALOR_TOTAL_FUNDO NUMERIC(18, 2),
DATA_PEDIDO DATAHORA)
RETURNS (VALOR NUMERICO,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1)
AS 
declare variable V_VALOR_BASE_CALCULO numeric(18,2);
declare variable V_PERC_FEMAL VARCHAR_003;
declare variable FUNDESP_10 numeric(18,2);
declare variable FUNESP_8 numeric(18,2);
declare variable ESTADO_3 numeric(18,2);
declare variable MEDIDAS_PENAIS_4 numeric(18,2);
declare variable FUNEMP_3 numeric(18,2);
declare variable FUNCOMP_3 numeric(18,2);
declare variable ADVOGADOS_2 numeric(18,2);
declare variable FUNPROGE_2 numeric(18,2);
declare variable FUNDEPEG_2 numeric(18,2);
declare variable FUNDEPEG_125 numeric(18,2);
declare variable ADMFANZD125 numeric(18,2);
declare variable FUNDO_PENIT240 numeric(18,2);
declare variable FECAD160 numeric(18,2);
declare variable FUNDAF numeric(18,2);
declare variable FEMAL numeric(18,2);
declare variable V_COUNT numeric(18,2);
declare variable GRUPO_SEFAZ numeric(18,2);
BEGIN
  /*
    Marcos roberto atualização do FUNCOMP para 6 %
  */
  if (CAST(DATA_PEDIDO AS DATE) >= CAST('24.03.2025' AS DATE)) then
    V_VALOR_BASE_CALCULO = ROUND((:VALOR_TOTAL_FUNDO * 100)/24.25,2);
  else
    V_VALOR_BASE_CALCULO = ROUND((:VALOR_TOTAL_FUNDO * 100)/21.25,2);

  FUNDESP_10 = ROUND(:V_VALOR_BASE_CALCULO * 0.10,2);
  FUNESP_8 = ROUND(:V_VALOR_BASE_CALCULO * 0.08,2);
  ESTADO_3 = ROUND(:V_VALOR_BASE_CALCULO * 0.03,2);
  ADVOGADOS_2 = ROUND(:V_VALOR_BASE_CALCULO * 0.02,2);
  FUNPROGE_2 = ROUND(:V_VALOR_BASE_CALCULO * 0.02,2);
  FUNDEPEG_125 = ROUND(:V_VALOR_BASE_CALCULO * 0.0125,2);
  ADMFANZD125 =ROUND(:V_VALOR_BASE_CALCULO * 0.0125,2);
  FUNDO_PENIT240= ROUND(:V_VALOR_BASE_CALCULO * 0.0240,2);
  FECAD160 = ROUND(:V_VALOR_BASE_CALCULO * 0.0160,2);
  FUNEMP_3 = ROUND(:V_VALOR_BASE_CALCULO * 0.03,2);

/*
  altera a porcentagem de 3% para 6% apenas depois no dia 20.03.2025 em diante
*/
  if (CAST(DATA_PEDIDO AS DATE) >= CAST('24.03.2025' AS DATE)) then
    FUNCOMP_3 = ROUND(:V_VALOR_BASE_CALCULO * 0.06,2);
  else
    FUNCOMP_3 = ROUND(:V_VALOR_BASE_CALCULO * 0.03,2);

  FEMAL = ROUND(:V_VALOR_BASE_CALCULO * 0.025,2);

  GRUPO_SEFAZ = COALESCE(:FUNESP_8,0) + COALESCE(:ESTADO_3,0) + COALESCE(:MEDIDAS_PENAIS_4,0) + COALESCE(:ADVOGADOS_2,0) + COALESCE(:FUNPROGE_2,0) + COALESCE(:FUNDEPEG_2,0)+COALESCE(:FUNDAF,0) ;

  V_PERC_FEMAL = '2,5';

  select 'Emolumentos:', ROUND(0 * 0.0160,2) VALOR FROM RDB$DATABASE
  INTO :descricao , :valor;
  SUSPEND;

   select 'Taxa Jud.:', ROUND(0 * 0.0160,2) VALOR FROM RDB$DATABASE
  INTO :descricao , :valor;
  SUSPEND;

  select 'FUNDESP:', ROUND(:V_VALOR_BASE_CALCULO * 0.10,2) VALOR FROM RDB$DATABASE
  INTO :descricao , :valor;
  SUSPEND;

  select 'FUNEMP:', ROUND(:V_VALOR_BASE_CALCULO * 0.03,2) VALOR FROM RDB$DATABASE
  INTO :descricao , :valor;
  SUSPEND;

  select 'ADV. DATIVOS:', ROUND(:V_VALOR_BASE_CALCULO * 0.02,2) VALOR FROM RDB$DATABASE
  INTO :descricao , :valor;
  SUSPEND;

  select 'PROCURADORIA:', ROUND(:V_VALOR_BASE_CALCULO * 0.02,2) VALOR FROM RDB$DATABASE
  INTO :descricao , :valor;
  SUSPEND;

  select 'DEFENSORIA:', ROUND(:V_VALOR_BASE_CALCULO * 0.0125,2)-0.01 VALOR FROM RDB$DATABASE
  INTO :descricao , :valor;
  SUSPEND;

  if (DATA_PEDIDO >= CAST('24.03.2025' AS DATE)) then
  begin
    select 'FUNCOMP:', ROUND(:V_VALOR_BASE_CALCULO * 0.06,2) VALOR FROM RDB$DATABASE
    INTO :descricao , :valor;
    SUSPEND;
  end
  else
  begin
    select 'FUNCOMP:', ROUND(:V_VALOR_BASE_CALCULO * 0.03,2) VALOR FROM RDB$DATABASE
    INTO :descricao , :valor;
    SUSPEND;
  end
END ^

ALTER PROCEDURE C_VALORES_INDIVIDUAIS_FUNDOS_GO (VALOR_TOTAL_FUNDO NUMERIC(18, 2))
RETURNS (FUNDESP_10 NUMERIC(18, 2),
FUNESP_8 NUMERIC(18, 2),
