  --SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'DATA_ALTERACAO_FUND_EST', 5)
  --INTO :V_DATA_ALT_FUNDO;
  --2022/06/29


  SELECT CURRENT_date FROM RDB$DATABASE
  into :vdataatual;

  if (vdataatual >= cast('24.03.2025' as date) ) then
  BEGIN
    V_VALOR_BASE_CALCULO = ROUND((:VALOR_TOTAL_FUNDO * 100)/V_PERCENTUAL,2);
    
      FUNDESP_10 = ROUND(:V_VALOR_BASE_CALCULO * 0.10,2);
