                          'Fundesp(10%=R$'||REPLACE(CAST(:FUNDESP_10 AS VARCHAR(18)),'.',',')||'); '
                          ||'Funemp (3,00%=R$'||REPLACE(CAST(:FUNEMP_3 AS VARCHAR(18)),'.',',')||'); '
                          ||'Funcomp(6%=R$'||REPLACE(CAST(:FUNCOMP_3 AS VARCHAR(18)),'.',',')||'); '
                          ||'Fedapsaj(2%=R$'||REPLACE(CAST(:ADVOGADOS_2 AS VARCHAR(18)),'.',',')||'); '
                          ||'Funproge(2%=R$'||REPLACE(CAST(:PROCURADORIA_2 AS VARCHAR(18)),'.',',')||'); '
                          ||'Fundepeg(1,25%=R$'||REPLACE(CAST(:FUNDEPEG_125 AS VARCHAR(18)),'.',',')||'); ';

      RELACAO_DETALHADA = 'FUNDOS ESTADUAIS:'
                          ||ASCII_CHAR(13)||'Fundo Especial de Reaparelhamento e Modernização do Poder Judiciário - FUNDESP/PJ(10%=R$'||REPLACE(CAST(:FUNDESP_10 AS VARCHAR(18)),'.',',')||'); '
                          ||ASCII_CHAR(13)||'Fundo Especial de Modernização e Aprimoramento Funcional do Ministério Público do Estado de Goiás - FUNEMP/GO(3%=R$'||REPLACE(CAST(:FUNEMP_3 AS VARCHAR(18)),'.',',')||'); '
                          ||ASCII_CHAR(13)||'Fundo de Compensação dos Atos Gratuitos Praticados pelos Notários e Registradores e de Complementação da Receita Mínima das Serventias Deficitárias - FUNCOMP(6%=R$'||REPLACE(CAST(:FUNCOMP_3 AS VARCHAR(18)),'.',',')||'); '
                          ||ASCII_CHAR(13)||'Fundo Especial de Pagamento dos Advogados Dativos e do Sistema de Acesso à Justiça(2%=R$'||REPLACE(CAST(:ADVOGADOS_2 AS VARCHAR(18)),'.',',')||'); '
                          ||ASCII_CHAR(13)||'Procuradoria (2%=R$'||REPLACE(CAST(:PROCURADORIA_2 AS VARCHAR(18)),'.',',')||'); '
                          ||ASCII_CHAR(13)||'Fundo de Manutenção e Reaparelhamento da Defensoria Pública do Estado - FUNDEPEG(1,25%=R$'||REPLACE(CAST(:FUNDEPEG_125 AS VARCHAR(18)),'.',',')||'); ';
  END
  ELSE
  BEGIN
    V_VALOR_BASE_CALCULO = ROUND((:VALOR_TOTAL_FUNDO * 100)/V_PERCENTUAL,2);
    
      FUNDESP_10 = ROUND(:V_VALOR_BASE_CALCULO * 0.10,2);
      FUNEMP_3 = ROUND(:V_VALOR_BASE_CALCULO * 0.03,2); --Ministério público

      FUNCOMP_3 = ROUND(:V_VALOR_BASE_CALCULO * 0.03,2); -- Atos gratuitos

      ADVOGADOS_2 = ROUND(:V_VALOR_BASE_CALCULO * 0.02,2);
      PROCURADORIA_2 = ROUND(:V_VALOR_BASE_CALCULO * 0.02,2); --Fundo Procuradoria
      FUNDEPEG_125 = ROUND(:V_VALOR_BASE_CALCULO * 0.0125,2); --Fundo Defensoria
    
      RELACAO_SINTETICA =-- 'Fundos Estaduais:R$'||REPLACE(CAST(:VALOR_TOTAL_FUNDO AS VARCHAR(18)),'.',',')||' '
                          'Fundesp(10%=R$'||REPLACE(CAST(:FUNDESP_10 AS VARCHAR(18)),'.',',')||'); '
                          ||'Funemp (3,00%=R$'||REPLACE(CAST(:FUNEMP_3 AS VARCHAR(18)),'.',',')||'); '
                          ||'Funcomp(3%=R$'||REPLACE(CAST(:FUNCOMP_3 AS VARCHAR(18)),'.',',')||'); '
                          ||'Fedapsaj(2%=R$'||REPLACE(CAST(:ADVOGADOS_2 AS VARCHAR(18)),'.',',')||'); '
                          ||'Funproge(2%=R$'||REPLACE(CAST(:PROCURADORIA_2 AS VARCHAR(18)),'.',',')||'); '
                          ||'Fundepeg(1,25%=R$'||REPLACE(CAST(:FUNDEPEG_125 AS VARCHAR(18)),'.',',')||'); ';

      RELACAO_DETALHADA = 'FUNDOS ESTADUAIS:'
                          ||ASCII_CHAR(13)||'Fundo Especial de Reaparelhamento e Modernização do Poder Judiciário - FUNDESP/PJ(10%=R$'||REPLACE(CAST(:FUNDESP_10 AS VARCHAR(18)),'.',',')||'); '
                          ||ASCII_CHAR(13)||'Fundo Especial de Modernização e Aprimoramento Funcional do Ministério Público do Estado de Goiás - FUNEMP/GO(3%=R$'||REPLACE(CAST(:FUNEMP_3 AS VARCHAR(18)),'.',',')||'); '
                          ||ASCII_CHAR(13)||'Fundo de Compensação dos Atos Gratuitos Praticados pelos Notários e Registradores e de Complementação da Receita Mínima das Serventias Deficitárias - FUNCOMP(3%=R$'||REPLACE(CAST(:FUNCOMP_3 AS VARCHAR(18)),'.',',')||'); '
                          ||ASCII_CHAR(13)||'Fundo Especial de Pagamento dos Advogados Dativos e do Sistema de Acesso à Justiça(2%=R$'||REPLACE(CAST(:ADVOGADOS_2 AS VARCHAR(18)),'.',',')||'); '
                          ||ASCII_CHAR(13)||'Procuradoria (2%=R$'||REPLACE(CAST(:PROCURADORIA_2 AS VARCHAR(18)),'.',',')||'); '
                          ||ASCII_CHAR(13)||'Fundo de Manutenção e Reaparelhamento da Defensoria Pública do Estado - FUNDEPEG(1,25%=R$'||REPLACE(CAST(:FUNDEPEG_125 AS VARCHAR(18)),'.',',')||'); ';
  END
  SUSPEND;
END ^

ALTER PROCEDURE C_VERIFICA_SE_EH_FERIADO (V_DATA VARCHAR(12) CHARACTER SET ISO8859_1)
RETURNS (SIM_NAO VARCHAR(2) CHARACTER SET ISO8859_1)
AS 
declare variable V_FERIADO integer;
declare variable V_DIA integer;
declare variable V_MES integer;
declare variable V_ANO integer;
BEGIN
  SELECT RIGHT(:V_DATA,2) FROM RDB$DATABASE INTO :V_DIA;
  SELECT RIGHT(LEFT(:V_DATA,7),2) FROM RDB$DATABASE INTO :V_MES;
  SELECT LEFT(:V_DATA,4) FROM RDB$DATABASE INTO :V_ANO;

  SELECT FIRST 1 FERIADO_ID FROM G_FERIADO  G
  WHERE SITUACAO = 'A'
  AND G.dia = :V_DIA
  AND G.mes = :V_MES
  AND G.ano = :V_ANO
  AND G.tipo = 'V'
  INTO :V_FERIADO;
  IF (:V_FERIADO > 0) THEN
  BEGIN
    SIM_NAO = 'S';
  END
  ELSE
  BEGIN
    SELECT FIRST 1 FERIADO_ID FROM G_FERIADO  G
    WHERE SITUACAO = 'A'
    AND G.dia = :V_DIA
    AND G.mes = :V_MES
    AND G.tipo = 'F'
    INTO :V_FERIADO;

    IF (:V_FERIADO > 0) THEN
    BEGIN
      SIM_NAO = 'S';
    END
    ELSE
    BEGIN
      SELECT FIRST 1 FERIADO_ID FROM G_FERIADO
      WHERE SITUACAO = 'A'
      AND DATA BETWEEN CAST(:V_DATA AS TIMESTAMP) AND CAST(:V_DATA AS TIMESTAMP) + 0.9999
      INTO :V_FERIADO;
      IF (:V_FERIADO > 0) THEN
      BEGIN
        SIM_NAO = 'S';
      END
      ELSE
      BEGIN
        SIM_NAO = 'N';
      END
    END
  END
  SUSPEND;
END ^

ALTER PROCEDURE D_INDICADOR_PESSOAL (ID_PESSOA VARCHAR_015,
VDATAREGINI VARCHAR_015,
VDATAREGFIN VARCHAR_015,
VNOME VARCHAR_120,
VCPFCNPJ VARCHAR_015,
VSOMENTEAPRE VARCHAR_001 = '')
RETURNS (VIPEDIDO INTEGER,
VIREGISTRO VARCHAR_260,
VILIVRO VARCHAR_010,
VIPROTOCOLO INTEGER,
VIREGISTRO_NUMERO INTEGER,
VITIPO_DOCUMENTO INTEGER,
VIDOCUMENTO VARCHAR_260,
VIDATA_REGISTRO DATAHORA,
LIVRO_NUMERO NUMERICO,
LIVRO_PAGINA_INI NUMERICO,
LIVRO_PAGINA_FIM NUMERICO,
DESCRICAO VARCHAR_260,
LIVRO_NUMERO_LETRA VARCHAR_090)
AS 
declare variable VSQL VARCHAR_1000;
BEGIN
  VSQL = ' select distinct D.DOCUMENTO_ID, REGISTRO, LIVRO, D.PROTOCOLO, D.NUMERO_REGISTRO, D.TIPO_DOCUMENTO_ID,
                coalesce(D.DATA_REGISTRO, D.DATA_PEDIDO) as DATA_REGISTRO, T.DESCRICAO, D.LIVRO_NUMERO,
                D.LIVRO_PAGINA_INI, D.LIVRO_PAGINA_FIM, VS.DESCRICAO, D.LIVRO || '' - '' || D.livro_numero LIVRO_NUMERO_LETRA
             from D_DOCUMENTO D
             left join D_TIPO_DOCUMENTO T on T.TIPO_DOCUMENTO_ID = D.TIPO_DOCUMENTO_ID
             left join D_PESSOA_CITADA C on C.DOCUMENTO_ID = D.DOCUMENTO_ID
             left join D_VINCULO_SINTER VS ON VS.VINCULO_SINTER_ID = C.VINCULO_SINTER_ID
             where 1 = 1 ';

  if ((COALESCE(:ID_PESSOA,'') <> '') and (COALESCE(:ID_PESSOA,'') <> '0')) then
  begin
    if (coalesce(:VSOMENTEAPRE, '') = 'S') then
    begin
        --VSQL = VSQL || ' AND VS.DESCRICAO = ''APRESENTANTE'' ';
        VSQL = VSQL || ' AND D.APRESENTANTE_ID = '||:ID_PESSOA;
    end
    else
    begin
        VSQL = VSQL || ' AND ((C.PESSOA_ID = '||:ID_PESSOA;
        VSQL = VSQL || ' AND COALESCE(VS.DESCRICAO, '''') <> ''APRESENTANTE'') ';
        VSQL = VSQL || '  OR D.APRESENTANTE_ID = '||:ID_PESSOA||' )';
    end
    if ((COALESCE(:VDATAREGINI,'')<> '') AND (COALESCE(:VDATAREGFIN,'')<>'')) then
    begin
      VSQL = VSQL || 'AND D.DATA_REGISTRO BETWEEN CAST('''||:VDATAREGINI||''' AS TIMESTAMP)
      AND CAST('''||:VDATAREGFIN||''' AS TIMESTAMP)+0.9999 ';
    end
  end
  else
  begin
    if ((COALESCE(:VDATAREGINI,'')<> '') AND (COALESCE(:VDATAREGFIN,'')<>'')) then
    begin
      VSQL = VSQL || 'AND D.DATA_REGISTRO BETWEEN CAST('''||:VDATAREGINI||''' AS TIMESTAMP)
      AND CAST('''||:VDATAREGFIN||''' AS TIMESTAMP)+0.9999 ';
    end
  
    if (coalesce(:VNOME,'') <> '') then
    begin
      VSQL = VSQL || ' and D.APRESENTANTE = '''||:VNOME||''' ';
    end
  
    if (coalesce(:VCPFCNPJ,'') <> '') then
    begin
      VSQL = VSQL || ' and D.CPF_CNPJ = '''||:VCPFCNPJ||''' ';
    end
  end

  VSQL = VSQL||'ORDER BY D.DOCUMENTO_ID ';

  FOR  EXECUTE STATEMENT  :VSQL
  INTO :VIPEDIDO, :VIREGISTRO, :VILIVRO, :VIPROTOCOLO, :VIREGISTRO_NUMERO,
       :VITIPO_DOCUMENTO, :VIDATA_REGISTRO, :VIDOCUMENTO, :LIVRO_NUMERO, :LIVRO_PAGINA_INI,
       :LIVRO_PAGINA_FIM, :DESCRICAO, :LIVRO_NUMERO_LETRA DO

  SUSPEND;
END ^

ALTER PROCEDURE D_PESQUISA_PROTOCOLO (V_NUMERO_APONTAMENTO_INI VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_APONTAMENTO_FIN VARCHAR(10) CHARACTER SET ISO8859_1,
V_DATA_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_REGISTRO VARCHAR(5) CHARACTER SET ISO8859_1,
V_LIVRO VARCHAR(1) CHARACTER SET ISO8859_1,
V_IMPRIME_T_DIAS VARCHAR(1) CHARACTER SET ISO8859_1,
V_IMPRIME_APENAS_EXISTENTES VARCHAR(1) CHARACTER SET ISO8859_1)
RETURNS (DOCUMENTO_ID NUMERICO,
NUMERO_REGISTRO NUMERICO,
LIVRO VARCHAR(3) CHARACTER SET ISO8859_1,
DATA_REGISTRO TIMESTAMP,
APRESENTANTE VARCHAR(120) CHARACTER SET ISO8859_1,
VALOR_DOCUMENTO NUMERICO,
TIPO_DOCUMENTO_ID NUMERICO,
NUMERO_PAGINAS NUMERICO,
TAXA_JUDICIARIA NUMERICO,
VALOR_CUSTAS NUMERICO,
LIVRO_NUMERO NUMERICO,
LIVRO_PAGINA_INI NUMERICO,
LIVRO_PAGINA_FIM NUMERICO,
DESCRICAO VARCHAR(260) CHARACTER SET ISO8859_1,
PROTOCOLO NUMERICO,
TIPO_REGISTRO VARCHAR(3) CHARACTER SET ISO8859_1,
NUMERO_AVERBACAO NUMERICO,
LETRA_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
LETRA_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
LETRA_LIVRO VARCHAR(1) CHARACTER SET ISO8859_1,
FOLHA_PROTOCOLO NUMERICO,
LIVRO_PROTOCOLO VARCHAR(120) CHARACTER SET ISO8859_1,
REGISTRO VARCHAR(10) CHARACTER SET ISO8859_1,
DATA_PROTOCOLO TIMESTAMP,
VALOR_TOTAL_ITEM NUMERICO,
VALOR_TAXA_JUDICIARIA_ITEM NUMERICO,
VALOR_EMOLUMENTO_ITEM NUMERICO,
VALOR_ISS_ITEM NUMERICO,
VALOR_FUNCIVIL_ITEM NUMERICO,
VALOR_INFORMACOES_CENTRAIS_ITEM NUMERICO,
DESCRICAO_ANDAMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
NATUREZA_SINTER VARCHAR(90) CHARACTER SET ISO8859_1,
SUB_SINDER VARCHAR(90) CHARACTER SET ISO8859_1,
TIPO_ATO VARCHAR(90) CHARACTER SET ISO8859_1,
SUBTIPO_ATO VARCHAR(90) CHARACTER SET ISO8859_1)
AS 
declare variable V_SQL varchar(10000);
declare variable V_SQL_FILTRO varchar(5000);
declare variable V_DATA_TEMP timestamp;
declare variable V_DATA_MAX timestamp;
declare variable V_DATA_MIM timestamp;
declare variable V_INI integer;
declare variable V_FIN integer;
declare variable V_DIA_APONTAMENTO integer;
declare variable SIM_NAO varchar(2);
declare variable V_FERIADO integer;
declare variable V_DATA_COUNT timestamp;
declare variable V_DATA_EXISTE timestamp;
declare variable V_SQLPESQDATA varchar(10000);
begin

--V_IMPRIME_T_DIAS = 'S';
V_SQL        = ' ';
V_SQL_FILTRO = ' ';
    V_SQL = '   SELECT DISTINCT D.DOCUMENTO_ID,
                       D.NUMERO_REGISTRO as NUMERO_REGISTRO,
                       D.LIVRO AS LIVRO,
                       cast(cast(coalesce(D.DATA_PROTOCOLO,d.data_registro) as date) as timestamp) as DATA_REGISTRO,
                       D.APRESENTANTE AS APRESENTANTE,
                       D.VALOR_DOCUMENTO AS VALOR_DOCUMENTO,
                       D.TIPO_DOCUMENTO_ID AS TIPO_DOCUMENTO_ID,
                       D.NUMERO_PAGINAS AS NUMERO_PAGINAS,
                       D.TAXA_JUDICIARIA AS TAXA_JUDICIARIA,
                       D.VALOR_CUSTAS AS VALOR_CUSTAS,
                       D.LIVRO_NUMERO AS LIVRO_NUMERO,
                       D.LIVRO_PAGINA_INI AS LIVRO_PAGINA_INI,
                       D.LIVRO_PAGINA_FIM AS LIVRO_PAGINA_FIM,
                       TD.DESCRICAO AS DESCRICAO,
                       D.PROTOCOLO AS PROTOCOLO,
                       D.TIPO_REGISTRO AS TIPO_REGISTRO,
                       D.NUMERO_AVERBACAO AS NUMERO_AVERBACAO,
                       D.LETRA_PROTOCOLO AS LETRA_PROTOCOLO,
                       D.LETRA_REGISTRO AS LETRA_REGISTRO,
                       D.LETRA_LIVRO AS LETRA_LIVRO,
                       D.FOLHA_PROTOCOLO AS FOLHA_PROTOCOLO,
                       D.LIVRO_PROTOCOLO AS LIVRO_PROTOCOLO,
                       D.REGISTRO AS REGISTRO,
                       cast(cast(coalesce(D.DATA_PROTOCOLO,d.data_registro) as date) as timestamp)  AS DATA_PROTOCOLO,
                       SUM(DI.VALOR_TOTAL_ITEM) as VALOR_TOTAL_ITEM,
                       SUM(DI.VALOR_TAXA_JUDICIARIA_ITEM) as VALOR_TAXA_JUDICIARIA_ITEM,
                       SUM(DI.VALOR_EMOLUMENTO_ITEM) as VALOR_EMOLUMENTO_ITEM,
                       SUM(DI.VALOR_ISS_ITEM) as VALOR_ISS_ITEM,
                       SUM(DI.VALOR_FUNCIVIL_ITEM) as VALOR_FUNCIVIL_ITEM,
                       SUM(DI.VALOR_INFORMACOES_CENTRAIS) as VALOR_INFORMACOES_CENTRAIS_ITEM,
                       case ( select first 1 tipo_andamento_id
                               from D_ANDAMENTO DA
                               where DA.documento_id = D.documento_id
                                order by andamento_id desc)
                           when ''1002'' then ''Cancelado''
                           when ''1000'' then ''Registrado''
                           when ''1001'' then ''Protocolado''
                       else
                       '' '' end as DESCRICAO_ANDAMENTO,
                       N.DESCRICAO NATUREZA_SINTER, S.DESCRICAO SUB_SINDER,
                       TS.DESCRICAO TIPO_ATO, SS.DESCRICAO SUBTIPO_ATO
                  FROM D_DOCUMENTO D
                  LEFT JOIN D_DOCUMENTO_ITENS di on di.documento_id = d.documento_id
                  LEFT JOIN D_TIPO_DOCUMENTO TD ON D.TIPO_DOCUMENTO_ID = TD.TIPO_DOCUMENTO_ID
                  LEFT JOIN D_ANDAMENTO DA on DA.documento_id = D.documento_id

                   left join D_NATUREZA_SINTER N on N.NATUREZA_SINTER_ID = TD.NATUREZA_SINTER_ID
                   left join D_SUBNATUREZA_SINTER S on S.SUBNATUREZA_SINTER_ID = TD.SUBNATUREZA_SINTER_ID
                  LEFT JOIN D_TIPOATO_SINTER TS on TS.TIPOATO_SINTER_ID = D.TIPOATO_SINTER_ID
                  LEFT JOIN D_SUBTIPOATO_SINTER SS ON SS.SUBTIPOATO_SINTER_ID = D.SUBTIPOATO_SINTER_ID
                 WHERE 1 =1
                 AND D.PROTOCOLO is not null  '; --TA.tipo_andamento_id DESC

        --se protocolo estifer marcado
        if ((COALESCE(:V_NUMERO_APONTAMENTO_INI,'') <> '') and (COALESCE(:V_NUMERO_APONTAMENTO_FIN,'') <> '')) then
        begin
          V_SQL_FILTRO = :V_SQL_FILTRO || 'AND D.PROTOCOLO BETWEEN '''||:V_NUMERO_APONTAMENTO_INI|| '''
                              AND  ' ||:V_NUMERO_APONTAMENTO_FIN||'  ';
        end
        -- se periodo estiver marcado
        if ((COALESCE(:V_DATA_INICIAL,'') <> '') and (COALESCE(:V_DATA_FINAL,'') <> '')) then
        begin
          V_SQL_FILTRO = :V_SQL_FILTRO || ' AND D.DATA_PROTOCOLO BETWEEN CAST(''' ||:V_DATA_INICIAL|| '''  AS TIMESTAMP )
                              AND CAST(  ''' ||:V_DATA_FINAL|| ''' AS TIMESTAMP) + 0.9999 ';
        end

        if (coalesce(:V_REGISTRO, '') <> '' ) then
        begin
            V_SQL_FILTRO = :V_SQL_FILTRO || ' AND D.REGISTRO = ''' || :V_REGISTRO || ''' ';
            if (coalesce(:V_LIVRO, '') <> '' ) then
            begin
                V_SQL_FILTRO = :V_SQL_FILTRO || 'AND D.LIVRO = ''' || V_LIVRO || ''' ';
            end
        end

            V_SQL = :V_SQL || :V_SQL_FILTRO || '
                             group by
                             D.DOCUMENTO_ID,
                             NUMERO_REGISTRO,
                             LIVRO,
                             DATA_REGISTRO,
                             APRESENTANTE,
                             VALOR_DOCUMENTO,
                             TIPO_DOCUMENTO_ID,
                             NUMERO_PAGINAS,
                             TAXA_JUDICIARIA,
                             VALOR_CUSTAS,
                             LIVRO_NUMERO,
                             LIVRO_PAGINA_INI,
                             LIVRO_PAGINA_FIM,
                             DESCRICAO,
                             PROTOCOLO,
                             TIPO_REGISTRO,
                             NUMERO_AVERBACAO,
                             LETRA_PROTOCOLO,
                             LETRA_REGISTRO,
                             LETRA_LIVRO,
                             FOLHA_PROTOCOLO,
                             LIVRO_PROTOCOLO,
                             REGISTRO,
                             DATA_PROTOCOLO,
                             DESCRICAO_ANDAMENTO,
                             N.DESCRICAO,
                             NATUREZA_SINTER,
                             S.DESCRICAO,
                             SUB_SINDER,
                             TIPO_ATO,
                             SUBTIPO_ATO,
                             TS.TIPOATO_SINTER_ID,
                             SS.SUBTIPOATO_SINTER_ID';

    for execute statement :V_SQL into
        :DOCUMENTO_ID, :NUMERO_REGISTRO, :LIVRO, :DATA_REGISTRO, :APRESENTANTE,
        :VALOR_DOCUMENTO, :TIPO_DOCUMENTO_ID, :NUMERO_PAGINAS, :TAXA_JUDICIARIA,
        :VALOR_CUSTAS, :LIVRO_NUMERO, :LIVRO_PAGINA_INI, :LIVRO_PAGINA_FIM,
        :DESCRICAO, :PROTOCOLO, :TIPO_REGISTRO, :NUMERO_AVERBACAO, :LETRA_PROTOCOLO,
        :LETRA_REGISTRO, :LETRA_LIVRO, :FOLHA_PROTOCOLO, :LIVRO_PROTOCOLO,
        :REGISTRO, :DATA_PROTOCOLO, :VALOR_TOTAL_ITEM, :VALOR_TAXA_JUDICIARIA_ITEM,
        :VALOR_EMOLUMENTO_ITEM, :VALOR_ISS_ITEM, :VALOR_FUNCIVIL_ITEM, :VALOR_INFORMACOES_CENTRAIS_ITEM,
        :DESCRICAO_ANDAMENTO, :NATUREZA_SINTER, :SUB_SINDER, :TIPO_ATO, :SUBTIPO_ATO DO
    begin
        suspend;
    end

    if (COALESCE(V_IMPRIME_APENAS_EXISTENTES, '') = 'N') then
    begin
      if ((COALESCE(:V_DATA_INICIAL,'') <> '') and (COALESCE(:V_DATA_FINAL,'') <> '')) then
       begin
          V_DATA_MAX = V_DATA_FINAL;
          V_DATA_MIM = V_DATA_INICIAL;
       end
       else
       begin
           V_SQL = ' SELECT max(D.DATA_PROTOCOLO)
                       FROM D_DOCUMENTO D
                       LEFT JOIN D_TIPO_DOCUMENTO TD ON D.TIPO_DOCUMENTO_ID = TD.TIPO_DOCUMENTO_ID
                      WHERE 1=1 ' || V_SQL_FILTRO;
      
           EXECUTE STATEMENT V_SQL INTO V_DATA_MAX;
           --SUSPEND;
      
           V_SQL = 'SELECT MIN(D.DATA_PROTOCOLO)
                      FROM D_DOCUMENTO D
                 LEFT JOIN D_TIPO_DOCUMENTO TD ON D.TIPO_DOCUMENTO_ID = TD.TIPO_DOCUMENTO_ID
                     WHERE 1=1 ' || V_SQL_FILTRO;
      
           EXECUTE STATEMENT V_SQL INTO V_DATA_MIM;
  
       end
  
       V_FIN = V_DATA_MAX - V_DATA_MIM ;
       V_INI = 0;
       V_DATA_MIM = :V_DATA_MIM;
       while(V_INI <= V_FIN ) do
       begin
       v_data_count = :v_data_mim+1+:v_ini;
          if (coalesce(V_IMPRIME_T_DIAS, 'N') = 'S') then
          begin
              V_DATA_EXISTE = null;
  
              V_SQLPESQDATA = '
                      select first 1 d.DATA_PROTOCOLO
                      from d_documento D
                      left join d_tipo_documento TD on d.tipo_documento_id = td.tipo_documento_id
                      where CAST(CAST(D.DATA_PROTOCOLO AS DATE) AS TIMESTAMP) = '''||:V_DATA_MIM ||''' ';
  
              if (coalesce(:V_REGISTRO, '') <> '' ) then
              begin
                    V_SQLPESQDATA = V_SQLPESQDATA || 'AND D.REGISTRO = '''||:V_REGISTRO||''' ';
  
                   if (coalesce(:V_LIVRO, '') <> '' ) then
                   begin
                      V_SQLPESQDATA = V_SQLPESQDATA ||'AND D.LIVRO = ''' ||V_LIVRO|| ''' ' ;
                   end
              end
                      execute statement V_SQLPESQDATA into V_DATA_EXISTE;
                      --select first 1 coalesce(d.data_protocolo,d.data_pedido)
                     -- from d_documento D
                     -- left join d_tipo_documento TD on d.tipo_documento_id = td.tipo_documento_id
                      --where CAST(CAST(coalesce(d.data_protocolo,d.data_pedido) AS DATE) AS TIMESTAMP) = :v_data_count
                      --into :V_DATA_EXISTE;
              if (coalesce(:V_DATA_EXISTE, '') = '') then
              begin
                  DOCUMENTO_ID = -1; NUMERO_REGISTRO = null; LIVRO = null; DATA_REGISTRO = V_DATA_MIM; APRESENTANTE = null;
                  VALOR_DOCUMENTO = null; TIPO_DOCUMENTO_ID = null; NUMERO_PAGINAS = null; TAXA_JUDICIARIA = null;
                  VALOR_CUSTAS = null; LIVRO_NUMERO = null; LIVRO_PAGINA_INI = null; LIVRO_PAGINA_FIM = null;
                  DESCRICAO = null; PROTOCOLO = null; TIPO_REGISTRO = null; NUMERO_AVERBACAO = null; LETRA_PROTOCOLO = null;
                  LETRA_REGISTRO = null; LETRA_LIVRO = null; FOLHA_PROTOCOLO = null; LIVRO_PROTOCOLO = null;
                  REGISTRO = null; DATA_PROTOCOLO = V_DATA_MIM; VALOR_TOTAL_ITEM = null; VALOR_TAXA_JUDICIARIA_ITEM = null;
                  VALOR_EMOLUMENTO_ITEM = null; VALOR_ISS_ITEM = null; VALOR_FUNCIVIL_ITEM = null; VALOR_INFORMACOES_CENTRAIS_ITEM = null;
                  DESCRICAO_ANDAMENTO = null; NATUREZA_SINTER = null; SUB_SINDER = null;  TIPO_ATO = null; SUBTIPO_ATO = null;
      
                  SUSPEND;
              end
          end
          else
          begin
              -- verifica o dia da semana semana de 0 a 6
              select extract(WEEKDAY from :V_DATA_MIM)
              from RDB$DATABASE INTO :V_DIA_APONTAMENTO;
  
              if ((V_DIA_APONTAMENTO <> 0) AND (V_DIA_APONTAMENTO <> 6)) then
              begin
              -- verifica se é feriado ou final de semana
                  V_FERIADO = 0;
                  SELECT FIRST 1 coalesce(FERIADO_ID,0) FROM G_FERIADO
                  WHERE SITUACAO = 'A'
                  AND (DIA = (extract (day from cast(:V_DATA_MIM as timestamp ))))
                  AND (MES = (extract (month from cast(:V_DATA_MIM as timestamp ))))
                  AND (ANO = (extract (year from cast(:V_DATA_MIM as timestamp ))))
                  INTO :V_FERIADO;
  
                  -- antiga pesquisa, caso precise voltar
                 /* SELECT FIRST 1 coalesce(FERIADO_ID,0) FROM G_FERIADO
                  WHERE SITUACAO = 'A'
                  AND DATA BETWEEN CAST(:V_DATA_MIM AS TIMESTAMP)
                  AND CAST(:V_DATA_MIM AS TIMESTAMP) + 0.9999
                  INTO :V_FERIADO;*/
  
               --   IF (coalesce(:V_FERIADO,0) > 0) THEN
              --    BEGIN
                --      SIM_NAO = 'S';
              --    END
               --   ELSE
               --   BEGIN
               --       SIM_NAO = 'N';
                --  END
                  --suspend;
                  if (coalesce(:V_FERIADO,0) = 0) then
                  begin
                      V_DATA_EXISTE = null;
  
                      V_SQLPESQDATA = '
                      select first 1 d.DATA_PROTOCOLO
                      from d_documento D
                      left join d_tipo_documento TD on d.tipo_documento_id = td.tipo_documento_id
                      where CAST(CAST(D.DATA_PROTOCOLO AS DATE) AS TIMESTAMP) = '''||:V_DATA_MIM ||''' ';
  
                      if (coalesce(:V_REGISTRO, '') <> '' ) then
                      begin
                            V_SQLPESQDATA = V_SQLPESQDATA || 'AND D.REGISTRO = '''||:V_REGISTRO||''' ';
  
                           if (coalesce(:V_LIVRO, '') <> '' ) then
                           begin
                              V_SQLPESQDATA = V_SQLPESQDATA ||'AND D.LIVRO = ''' ||V_LIVRO|| ''' ' ;
                           end
                      end
                      execute statement V_SQLPESQDATA into V_DATA_EXISTE;
                      --into :V_DATA_EXISTE;
  
                      if (coalesce(V_DATA_EXISTE, '') = '' ) then
                      begin
                          DOCUMENTO_ID = -1; NUMERO_REGISTRO = null; LIVRO = null; DATA_REGISTRO = V_DATA_MIM; APRESENTANTE = null;
                          VALOR_DOCUMENTO = null; TIPO_DOCUMENTO_ID = null; NUMERO_PAGINAS = null; TAXA_JUDICIARIA = null;
                          VALOR_CUSTAS = null; LIVRO_NUMERO = null; LIVRO_PAGINA_INI = null; LIVRO_PAGINA_FIM = null;
                          DESCRICAO = null; PROTOCOLO = null; TIPO_REGISTRO = null; NUMERO_AVERBACAO = null; LETRA_PROTOCOLO = null;
                          LETRA_REGISTRO = null; LETRA_LIVRO = null; FOLHA_PROTOCOLO = null; LIVRO_PROTOCOLO = null;
                          REGISTRO = null; DATA_PROTOCOLO = V_DATA_MIM; VALOR_TOTAL_ITEM = null; VALOR_TAXA_JUDICIARIA_ITEM = null;
                          VALOR_EMOLUMENTO_ITEM = null; VALOR_ISS_ITEM = null; VALOR_FUNCIVIL_ITEM = null; VALOR_INFORMACOES_CENTRAIS_ITEM = null;
                          DESCRICAO_ANDAMENTO = null; NATUREZA_SINTER = null; SUB_SINDER = null; TIPO_ATO = null; SUBTIPO_ATO = null;

                          SUSPEND;
                      end
                  end
                  else
                  begin
                     SIM_NAO = 'N';
                  end
              end
          end
          V_DATA_MIM = :V_DATA_MIM + 1;
          V_INI = :V_INI + 1;
      end
  end
end ^

ALTER PROCEDURE D_SELAR_REGISTRO_RTD (REGISTRO_ID NUMERICO)
RETURNS (STRING VARCHAR(1000) CHARACTER SET ISO8859_1)
AS 
declare variable AUXM NUMERICO;
declare variable AUXP NUMERICO;
BEGIN
  STRING = '';
 select COUNT(SELO_LIVRO_ID) from g_selo_livro
  where  tabela = 'D_DOCUMENTO' AND SELO_SITUACAO_ID = 2
  AND CAMPO_ID = :REGISTRO_ID
  INTO :AUXM;

 select SUM(D.qtd) from D_DOCUMENTO_ITENS D
  where  D.documento_id = :REGISTRO_ID
  INTO :AUXP;

  if (coalesce(AuxM,0) = coalesce(Auxp,0))  then
  begin
     STRING = 'OK';
  end
  else
  begin
      STRING = '';
  end
  SUSPEND;
END ^

ALTER PROCEDURE D_SP_PESSOA (VNOME VARCHAR(1000) CHARACTER SET ISO8859_1)
RETURNS (VPROTOCOLO VARCHAR(1000) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE VPESID INTEGER;
DECLARE VARIABLE VDOCID INTEGER;
DECLARE VARIABLE VLISTA VARCHAR(1000) CHARACTER SET ISO8859_1;
BEGIN
  VLISTA = '';
  FOR SELECT PESSOA_ID FROM D_PESSOA WHERE NOME LIKE :VNOME || '%' INTO VPESID DO
  BEGIN
    FOR SELECT PC.DOCUMENTO_ID FROM D_PESSOA_CITADA PC
        LEFT JOIN D_PESSOA P ON PC.PESSOA_ID = P.PESSOA_ID
        WHERE PC.PESSOA_ID = :VPESID
        INTO :VDOCID DO
    BEGIN
      IF (:VLISTA IS NOT NULL) THEN
      BEGIN
        VLISTA = VLISTA || ',' || VDOCID;
      END
    END
  END
  VPROTOCOLO = VLISTA;
  SUSPEND;
END ^

ALTER PROCEDURE D_SP_PESSOA_NOME (VNOME VARCHAR(1000) CHARACTER SET ISO8859_1)
RETURNS (VPROTOCOLO VARCHAR(1000) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE VPESID INTEGER;
DECLARE VARIABLE VDOCID INTEGER;
DECLARE VARIABLE VLISTA VARCHAR(1000) CHARACTER SET ISO8859_1;
BEGIN
  VLISTA = '';
  FOR SELECT PESSOA_ID FROM D_PESSOA WHERE NOME LIKE :VNOME || '%' INTO VPESID DO
  BEGIN
    FOR SELECT PC.PESSOA_ID FROM D_PESSOA_CITADA PC
        LEFT JOIN D_PESSOA P ON PC.PESSOA_ID = P.PESSOA_ID
        WHERE PC.PESSOA_ID = :VPESID
        INTO :VDOCID DO
    BEGIN
      IF (:VLISTA IS NOT NULL) THEN
      BEGIN
        VLISTA = VLISTA || ',' || VDOCID;
      END
    END
  END
  VPROTOCOLO = VLISTA;
  SUSPEND;
END ^

ALTER PROCEDURE G_AJUSTAR_GRUPO_SELO_DUPLICADO RETURNS (NUMERO INTEGER,
DESCRICAO VARCHAR(1000) CHARACTER SET ISO8859_1)
AS 
declare variable vcount integer;
  declare variable vQtdeAjustada integer;
  declare variable selo_grupo_id integer;
  declare variable JaPassei varchar(3);
  declare variable selo_grupo_id_novo integer;
begin
  vQtdeAjustada = 0;
  for select count(*), g.numero from g_selo_grupo g
      where g.situacao = 'A'
      and (select count(*) from g_selo_grupo where id_tipo_ato_antigo = g.selo_grupo_id) = 0
      group by g.numero
      having count(*) > 1
      into :vcount, :numero do
  begin
    JaPassei = 'N';
    selo_grupo_id_novo = 0;
    for select g.selo_grupo_id, g.descricao from g_selo_grupo g
        where g.numero = :numero
        and g.situacao = 'A'
        and (select count(*) from g_selo_grupo where id_tipo_ato_antigo = g.selo_grupo_id) = 0
        order by g.selo_grupo_id desc
        into :selo_grupo_id, :descricao do
    begin
      if (:JaPassei = 'S') then
      begin
        update g_selo_lote
        set selo_grupo_id = :selo_grupo_id_novo
        where selo_grupo_id = :selo_grupo_id;

        update g_emolumento_item
        set selo_grupo_id = :selo_grupo_id_novo
        where selo_grupo_id = :selo_grupo_id;

        delete from g_selo_grupo
        where selo_grupo_id = :selo_grupo_id;

        suspend;
      end
      else
      begin
        JaPassei = 'S';
        selo_grupo_id_novo = :selo_grupo_id;
      end
    end
  end
end ^

ALTER PROCEDURE G_ATUALIZA_AGENDA_MSN (V_USUARIO_ID VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (AGENDA_ID NUMERIC(12, 2),
TIPO_EVENTO NUMERIC(12, 2),
DATA_INICIO TIMESTAMP,
DATA_FIM TIMESTAMP,
ASSUNTO VARCHAR(260) CHARACTER SET ISO8859_1,
MENSAGEM VARCHAR(260) CHARACTER SET ISO8859_1,
COR NUMERIC(12, 2),
OPCAO NUMERIC(12, 2),
STATUS NUMERIC(12, 2),
USUARIO_ID NUMERIC(12, 2),
USUARIO_AGENDOU_ID NUMERIC(12, 2),
MENSAGEM_FINALIZADO BLOB,
DATA_HORA_CADASTRO TIMESTAMP,
DATA_HORA_ENVIADO TIMESTAMP,
DATA_HORA_FINALIZADO TIMESTAMP,
DATA_HORA_AVISADO TIMESTAMP,
NOMEUSUARIOAGENDOU VARCHAR(100) CHARACTER SET ISO8859_1)
AS 
BEGIN
  FOR SELECT   AGENDA_ID, TIPO_EVENTO, DATA_INICIO,
                   DATA_FIM, ASSUNTO, MENSAGEM,
                   COR, OPCAO, STATUS,
                   USUARIO_ID, USUARIO_AGENDOU_ID, 
                   MENSAGEM_FINALIZADO, DATA_HORA_CADASTRO,
                   DATA_HORA_ENVIADO, DATA_HORA_FINALIZADO,
                   DATA_HORA_AVISADO
         FROM G_AGENDA
         WHERE USUARIO_ID = :V_USUARIO_ID
         AND (DATA_HORA_ENVIADO IS NULL OR  DATA_HORA_AVISADO IS NULL)
         INTO        :AGENDA_ID, :TIPO_EVENTO, :DATA_INICIO,
                   :DATA_FIM, :ASSUNTO, :MENSAGEM,
                   :COR, :OPCAO, :STATUS,
                   :USUARIO_ID, :USUARIO_AGENDOU_ID, 
                   :MENSAGEM_FINALIZADO, :DATA_HORA_CADASTRO,
                   :DATA_HORA_ENVIADO, :DATA_HORA_FINALIZADO,
                   :DATA_HORA_AVISADO DO
  BEGIN
    SELECT LOGIN FROM G_USUARIO
    WHERE USUARIO_ID = :USUARIO_AGENDOU_ID
    INTO :NOMEUSUARIOAGENDOU;  
    SUSPEND;
  END
END ^

ALTER PROCEDURE G_ATUALIZA_CHAT_MSN (V_USUARIO_ID VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (CHAT_ID NUMERIC(18, 2),
DATA TIMESTAMP,
USUARIO_RECEBEU_ID NUMERIC(18, 2),
USUARIO_ENVIOU_ID NUMERIC(18, 2),
RECEBEU VARCHAR(15) CHARACTER SET ISO8859_1,
MENSAGEM_BLOB BLOB,
NOMEUSUARIO VARCHAR(60) CHARACTER SET ISO8859_1)
AS 
BEGIN
  FOR SELECT  CHAT_ID,  DATA,  USUARIO_RECEBEU_ID,
                           USUARIO_ENVIOU_ID, RECEBEU,
                           MENSAGEM_BLOB
         FROM G_CHAT
         WHERE USUARIO_RECEBEU_ID = :V_USUARIO_ID
         AND          EXCLUIR = 'N'
         INTO        :CHAT_ID, :DATA,  :USUARIO_RECEBEU_ID,
                           :USUARIO_ENVIOU_ID, :RECEBEU,
                           :MENSAGEM_BLOB DO
  BEGIN
    SELECT LOGIN FROM G_USUARIO
    WHERE USUARIO_ID = :USUARIO_ENVIOU_ID
    INTO :NOMEUSUARIO ;
    SUSPEND;
  END
END ^

ALTER PROCEDURE G_ATUALIZA_CHAT_NA_TELA (V_USUARIO_RECEBEU_ID VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (CHAT_ID NUMERIC(18, 2),
DATA TIMESTAMP,
USUARIO_RECEBEU_ID NUMERIC(18, 2),
USUARIO_ENVIOU_ID NUMERIC(18, 2),
RECEBEU VARCHAR(15) CHARACTER SET ISO8859_1,
MENSAGEM_BLOB BLOB,
NOME_USUARIO_ENVIO VARCHAR(60) CHARACTER SET ISO8859_1)
AS 
BEGIN
  FOR SELECT CHAT_ID, DATA, USUARIO_RECEBEU_ID,
        USUARIO_ENVIOU_ID, RECEBEU, MENSAGEM_BLOB
      FROM G_CHAT
      WHERE USUARIO_RECEBEU_ID = :V_USUARIO_RECEBEU_ID
      AND RECEBEU = 'S'
      AND EXCLUIR = 'N'
      ORDER BY DATA
      INTO :CHAT_ID, :DATA, :USUARIO_RECEBEU_ID,
        :USUARIO_ENVIOU_ID, :RECEBEU, :MENSAGEM_BLOB DO
  BEGIN
    SELECT LOGIN FROM G_USUARIO
    WHERE USUARIO_ID = :USUARIO_ENVIOU_ID
    INTO :NOME_USUARIO_ENVIO;
    SUSPEND;
  END
END ^

ALTER PROCEDURE G_BUSCAR_CONFIG (V_NOME_GRUPO VARCHAR(60) CHARACTER SET ISO8859_1,
V_NOME_SECAO VARCHAR(60) CHARACTER SET ISO8859_1,
V_NOME_PARAMETRO VARCHAR(120) CHARACTER SET ISO8859_1,
V_SISTEMA_ID INTEGER)
RETURNS (STATUS CHAR(1) CHARACTER SET ISO8859_1,
VALOR_PARAMETRO VARCHAR_1000,
VALOR_PARAMETRO_TEXTO BLOB,
CONFIG_ID INTEGER)
AS 
BEGIN
  SELECT FIRST 1 COALESCE(C.VALOR,''), COALESCE(C.TEXTO,''), C.config_id
  FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.DESCRICAO = :V_NOME_GRUPO
  AND G.SISTEMA_ID = :V_SISTEMA_ID
  AND C.SECAO = :V_NOME_SECAO
  AND C.NOME = :V_NOME_PARAMETRO
  AND COALESCE(C.TERMINAL,'') = ''
  INTO :VALOR_PARAMETRO, :VALOR_PARAMETRO_TEXTO, :CONFIG_ID;
  IF ((COALESCE(:VALOR_PARAMETRO,'') = '') AND (COALESCE(:VALOR_PARAMETRO_TEXTO,'') = '')) THEN
  BEGIN
    STATUS = 'F';
  END
  ELSE
  BEGIN
    STATUS = 'T';
  END
  SUSPEND;
END ^

ALTER PROCEDURE G_BUSCAR_CONFIG_GERAL (V_NOME_GRUPO VARCHAR(60) CHARACTER SET ISO8859_1,
V_NOME_SECAO VARCHAR(60) CHARACTER SET ISO8859_1,
V_NOME_PARAMETRO VARCHAR(120) CHARACTER SET ISO8859_1,
V_SISTEMA_ID INTEGER,
V_TABELA_CONFIG VARCHAR(120) CHARACTER SET ISO8859_1,
V_TERMINAL VARCHAR(30) CHARACTER SET ISO8859_1 = '')
RETURNS (STATUS CHAR(1) CHARACTER SET ISO8859_1,
VALOR_PARAMETRO VARCHAR(1000) CHARACTER SET ISO8859_1,
VALOR_PARAMETRO_TEXTO BLOB,
CONFIG_ID INTEGER)
AS 
DECLARE VARIABLE V_SQL VARCHAR(2000);
  declare variable V_COUNT INTEGER;
BEGIN
  IF (COALESCE(:V_TABELA_CONFIG,'') = 'G_CONFIG') THEN
  BEGIN
    IF (COALESCE(:V_TERMINAL,'') = '') THEN
    BEGIN
      SELECT FIRST 1 COALESCE(C.VALOR,''), COALESCE(C.TEXTO,''), C.CONFIG_ID
      FROM G_CONFIG C, G_CONFIG_GRUPO G
      WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
      AND G.DESCRICAO = :V_NOME_GRUPO
      AND G.SISTEMA_ID = :V_SISTEMA_ID
      AND C.SECAO = :V_NOME_SECAO
      AND C.NOME = :V_NOME_PARAMETRO
      AND COALESCE(C.TERMINAL,'') = ''
      ORDER BY C.NOME, C.TERMINAL DESC
      INTO :VALOR_PARAMETRO, :VALOR_PARAMETRO_TEXTO, :CONFIG_ID;
    END
    ELSE
    BEGIN
      SELECT COUNT(*)
      FROM G_CONFIG C, G_CONFIG_GRUPO G
      WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
      AND G.DESCRICAO = :V_NOME_GRUPO
      AND G.SISTEMA_ID = :V_SISTEMA_ID
      AND C.SECAO = :V_NOME_SECAO
      AND C.NOME = :V_NOME_PARAMETRO
      AND COALESCE(C.TERMINAL,'') = :V_TERMINAL
      INTO :V_COUNT;
  
      IF (:V_COUNT > 0) THEN
      BEGIN
        SELECT FIRST 1 COALESCE(C.VALOR,''), COALESCE(C.TEXTO,''), C.CONFIG_ID
        FROM G_CONFIG C, G_CONFIG_GRUPO G
        WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
        AND G.DESCRICAO = :V_NOME_GRUPO
        AND G.SISTEMA_ID = :V_SISTEMA_ID
        AND C.SECAO = :V_NOME_SECAO
        AND C.NOME = :V_NOME_PARAMETRO
        AND COALESCE(C.TERMINAL,'') = :V_TERMINAL
        ORDER BY C.NOME, C.TERMINAL DESC
        INTO :VALOR_PARAMETRO, :VALOR_PARAMETRO_TEXTO, :CONFIG_ID;
      END
      ELSE
      BEGIN
        SELECT FIRST 1 COALESCE(C.VALOR,''), COALESCE(C.TEXTO,''), C.CONFIG_ID
        FROM G_CONFIG C, G_CONFIG_GRUPO G
        WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
        AND G.DESCRICAO = :V_NOME_GRUPO
        AND G.SISTEMA_ID = :V_SISTEMA_ID
        AND C.SECAO = :V_NOME_SECAO
        AND C.NOME = :V_NOME_PARAMETRO
        AND COALESCE(C.TERMINAL,'') = ''
        ORDER BY C.NOME, C.TERMINAL DESC
        INTO :VALOR_PARAMETRO, :VALOR_PARAMETRO_TEXTO, :CONFIG_ID;
      END
    END
  END
  ELSE
  BEGIN
    SELECT FIRST 1 COALESCE(C.VALOR,''), COALESCE(C.TEXTO,''), C.CONFIG_ID
    FROM PW_CONFIG C, PW_CONFIG_GRUPO G
    WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
    AND G.DESCRICAO = :V_NOME_GRUPO
    AND G.SISTEMA_ID = :V_SISTEMA_ID
    AND C.SECAO = :V_NOME_SECAO
    AND C.NOME = :V_NOME_PARAMETRO
    AND COALESCE(C.TERMINAL,'') = ''
    ORDER BY C.NOME, C.TERMINAL DESC
    INTO :VALOR_PARAMETRO, :VALOR_PARAMETRO_TEXTO, :CONFIG_ID;
  END

  IF ((COALESCE(:VALOR_PARAMETRO,'') = '') AND (COALESCE(:VALOR_PARAMETRO_TEXTO,'') = '')) THEN
  BEGIN
    STATUS = 'F';
  END
  ELSE
  BEGIN
    STATUS = 'T';
  END
  SUSPEND;
END ^

ALTER PROCEDURE G_BUSCAR_EMOLUMENTO (V_EMOLUMENTO_ID INTEGER,
V_EMOLUMENTO_PERIODO_ID INTEGER,
V_VALOR_DOCUMENTO NUMERIC(14, 2))
RETURNS (VALOR_EMOLUMENTO NUMERIC(14, 2),
VALOR_TAXA_JUDICIARIA NUMERIC(14, 2),
VALOR_OUTRA_TAXA1 NUMERIC(14, 2),
VALOR_FUNDO_RI NUMERIC(14, 2),
VALOR_TOTAL NUMERIC(14, 2),
CODIGO_TABELA VARCHAR(30) CHARACTER SET ISO8859_1,
CODIGO_SELO VARCHAR(30) CHARACTER SET ISO8859_1,
SELO_GRUPO_ID INTEGER,
TIPO_OBJETIVO VARCHAR(3) CHARACTER SET ISO8859_1,
EMOLUMENTO_ITEM_ID INTEGER,
EMOLUMENTO_ACRESCE NUMERIC(14, 2),
TAXA_ACRESCE NUMERIC(14, 2),
FUNCIVIL_ACRESCE NUMERIC(14, 2),
FUNDO_SELO NUMERIC(14, 2),
PAGINA_EXTRA NUMERIC(14, 2),
DISTRIBUIDOR NUMERIC(14, 2),
REG_AVERB VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
declare variable V_FUNDO_SELO DINHEIRO;
declare variable V_VALOR_POR_EXCEDENTE_EMOL DINHEIRO;
declare variable V_VALOR_POR_EXCEDENTE_TJ DINHEIRO;
declare variable V_VALOR_POR_EXCEDENTE_FUNDO DINHEIRO;
declare variable V_VALOR_FRACAO DINHEIRO;
declare variable V_VALOR_LIMITE_EXCEDENTE_EMOL DINHEIRO;
declare variable V_VALOR_LIMITE_EXCEDENTE_TJ DINHEIRO;
declare variable V_VALOR_LIMITE_EXCEDENTE_FUNDO DINHEIRO;
declare variable V_VALOR_INICIO DINHEIRO;
declare variable V_VALOR_EXCEDIDO DINHEIRO;
declare variable V_QTDE_EXCEDENTE numeric(14,10);
declare variable V_QTDE_EXC_INTEIRO integer;
declare variable V_QTDE_EXC_FRACAO DINHEIRO;
BEGIN
  SELECT FIRST 1 COALESCE(I.VALOR_EMOLUMENTO,0), COALESCE(I.VALOR_TAXA_JUDICIARIA,0), 
    COALESCE(I.VALOR_OUTRA_TAXA1,0), COALESCE(I.VALOR_FUNDO_RI,0), I.CODIGO_SELO, 
    I.CODIGO_TABELA, I.SELO_GRUPO_ID, I.EMOLUMENTO_ITEM_ID, E.TIPO_OBJETIVO,
    COALESCE(I.EMOLUMENTO_ACRESCE,0), COALESCE(I.TAXA_ACRESCE,0), COALESCE(I.FUNCIVIL_ACRESCE,0),
    COALESCE(VALOR_POR_EXCEDENTE_EMOL, 0),
    COALESCE(VALOR_POR_EXCEDENTE_TJ, 0),
    COALESCE(VALOR_POR_EXCEDENTE_FUNDO, 0),
    COALESCE(VALOR_FRACAO, 0),
    COALESCE(VALOR_LIMITE_EXCEDENTE_EMOL, 0),
    COALESCE(VALOR_LIMITE_EXCEDENTE_TJ, 0),
    COALESCE(VALOR_LIMITE_EXCEDENTE_FUNDO, 0),
    COALESCE(VALOR_INICIO, 0),
    COALESCE(FUNDO_SELO, 0),
    COALESCE(I.PAGINA_EXTRA, 0),
    COALESCE(E.REG_AVERB, '')
  FROM G_EMOLUMENTO E, G_EMOLUMENTO_ITEM I
  WHERE E.EMOLUMENTO_ID = I.EMOLUMENTO_ID
  AND I.EMOLUMENTO_ID = :V_EMOLUMENTO_ID
  AND :V_VALOR_DOCUMENTO BETWEEN I.VALOR_INICIO AND I.VALOR_FIM
  AND I.EMOLUMENTO_PERIODO_ID = :V_EMOLUMENTO_PERIODO_ID
  INTO :VALOR_EMOLUMENTO, :VALOR_TAXA_JUDICIARIA, :VALOR_OUTRA_TAXA1,
    :VALOR_FUNDO_RI, :CODIGO_SELO, :CODIGO_TABELA,
    :SELO_GRUPO_ID, :EMOLUMENTO_ITEM_ID, :TIPO_OBJETIVO,
    :EMOLUMENTO_ACRESCE, :TAXA_ACRESCE, :FUNCIVIL_ACRESCE,
    :V_VALOR_POR_EXCEDENTE_EMOL, :V_VALOR_POR_EXCEDENTE_TJ, :V_VALOR_POR_EXCEDENTE_FUNDO,
    :V_VALOR_FRACAO, :V_VALOR_LIMITE_EXCEDENTE_EMOL, :V_VALOR_LIMITE_EXCEDENTE_TJ,
    :V_VALOR_LIMITE_EXCEDENTE_FUNDO, :V_VALOR_INICIO, :FUNDO_SELO,:PAGINA_EXTRA, :REG_AVERB;
  
  IF (:V_VALOR_POR_EXCEDENTE_EMOL > 0) THEN
  BEGIN
    V_VALOR_EXCEDIDO = :V_VALOR_DOCUMENTO - (:V_VALOR_INICIO - 0.01);
    V_VALOR_EXCEDIDO =  V_VALOR_EXCEDIDO +0.04;
    if (COALESCE(:V_VALOR_EXCEDIDO,0) > 0) then
    BEGIN
      if (:V_VALOR_EXCEDIDO < :V_VALOR_FRACAO) then
      BEGIN
        V_QTDE_EXCEDENTE = 1;
      END
      ELSE
      BEGIN
        V_QTDE_EXCEDENTE = (:V_VALOR_EXCEDIDO / :V_VALOR_FRACAO);
      END
      V_QTDE_EXC_INTEIRO = TRUNC(:V_QTDE_EXCEDENTE);
      if (:V_QTDE_EXCEDENTE > :V_QTDE_EXC_INTEIRO) then
      BEGIN
        V_QTDE_EXC_INTEIRO = :V_QTDE_EXC_INTEIRO + 1;
      END
      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (:V_QTDE_EXC_INTEIRO * :V_VALOR_POR_EXCEDENTE_EMOL);
      IF (:VALOR_FUNDO_RI > 0) THEN
      BEGIN
        VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (:V_QTDE_EXC_INTEIRO * :V_VALOR_POR_EXCEDENTE_FUNDO);
      END
      IF (:VALOR_OUTRA_TAXA1 > 0) THEN
      BEGIN
        VALOR_OUTRA_TAXA1 = :VALOR_OUTRA_TAXA1 + (:V_QTDE_EXC_INTEIRO * :V_VALOR_POR_EXCEDENTE_FUNDO);
        VALOR_FUNDO_RI = 0;
      END
      IF (:VALOR_TAXA_JUDICIARIA > 0) THEN
      BEGIN
        VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (:V_QTDE_EXC_INTEIRO * :V_VALOR_POR_EXCEDENTE_TJ);
      END
      IF (:VALOR_EMOLUMENTO > :V_VALOR_LIMITE_EXCEDENTE_EMOL) THEN
      BEGIN
        VALOR_EMOLUMENTO = :V_VALOR_LIMITE_EXCEDENTE_EMOL;
        IF (:VALOR_FUNDO_RI > 0) THEN
        BEGIN
          VALOR_FUNDO_RI = :V_VALOR_LIMITE_EXCEDENTE_FUNDO;
        END
        IF (:VALOR_TAXA_JUDICIARIA > 0) THEN
        BEGIN
          VALOR_TAXA_JUDICIARIA = :V_VALOR_LIMITE_EXCEDENTE_TJ;
        END
        IF (:VALOR_OUTRA_TAXA1 > 0) THEN
        BEGIN
          VALOR_OUTRA_TAXA1 = :V_VALOR_LIMITE_EXCEDENTE_FUNDO;
        END
      END
    END
  END
  IF (:VALOR_FUNDO_RI > 0) THEN
  BEGIN
    VALOR_TOTAL = :VALOR_EMOLUMENTO + :VALOR_TAXA_JUDICIARIA + :VALOR_OUTRA_TAXA1 + :VALOR_FUNDO_RI + :EMOLUMENTO_ACRESCE + :TAXA_ACRESCE + :FUNCIVIL_ACRESCE+ :FUNDO_SELO;
  END
  IF (:VALOR_OUTRA_TAXA1 > 0) THEN
  BEGIN
    VALOR_TOTAL = :VALOR_EMOLUMENTO + :VALOR_TAXA_JUDICIARIA + :VALOR_OUTRA_TAXA1 + :VALOR_FUNDO_RI + :EMOLUMENTO_ACRESCE + :TAXA_ACRESCE + :FUNCIVIL_ACRESCE + :FUNDO_SELO;
  END
  SUSPEND;
END ^

ALTER PROCEDURE G_BUSCA_DADOS_PESSOA (V_CAMPO_ID NUMERICO,
V_TABELA VARCHAR_120)
RETURNS (EMAIL_EMISSOR VARCHAR_260,
PESSOA_ID NUMERICO,
TABELA VARCHAR_030,
SERVENTIA VARCHAR_030,
SERVENTIAID NUMERICO,
NOME VARCHAR_120,
SEXO VARCHAR_001,
CPF_CNPJ VARCHAR_030,
CPF_TERCEIRO VARCHAR_001,
PESSOA_TIPO VARCHAR_010,
ENDERECO VARCHAR_090,
BAIRRO VARCHAR_060,
CIDADE VARCHAR_060,
UF VARCHAR_003,
CEP VARCHAR_015,
TELEFONE VARCHAR_015,
DOCUMENTO VARCHAR_030,
DOCUMENTO_ID NUMERICO,
ESTADO_CIVIL_ID NUMERICO,
PROFISSAO_ID NUMERICO,
DATA_NASCIMENTO DATAHORA,
PAIS_NASCIMENTO NUMERICO,
UF_NATURALIDADE VARCHAR_003,
NACIONALIDADE VARCHAR_030,
NOME_PAI VARCHAR_120,
NOME_MAE VARCHAR_120,
CIDADE_NATURALIDADE VARCHAR_060,
DATA_EMISSAO_DOC DATAHORA,
UF_EMISSOR VARCHAR_003,
ORGAO_EMISSOR VARCHAR_030)
AS 
declare variable VSQL varchar(5000);
declare variable VSQL_T varchar(5000);
declare variable ITABELA integer;
begin

  vSQL_T = '';
  vSQL = 'select pessoa_id,'||ascii_char(13)
       ||'       tabela,'||ascii_char(13)
       ||'       serventia,'||ascii_char(13)
       ||'       serventiaid,'||ascii_char(13)
       ||'       nome,'||ascii_char(13)
       ||'       sexo,'||ascii_char(13)
       ||'       cpf_cnpj,'||ascii_char(13)
       ||'       cpf_terceiro,'||ascii_char(13)
       ||'       (case when char_length(cpf_cnpj)=14 then '''||'J'||''' else '''||'F'||''' end) pessoa_tipo,'||ascii_char(13)
       ||'       endereco,'||ascii_char(13)
       ||'       bairro,'||ascii_char(13)
       ||'       cidade,'||ascii_char(13)
       ||'       uf,'||ascii_char(13)
       ||'       cep,'||ascii_char(13)
       ||'       telefone,'||ascii_char(13)
       ||'       documento,'||ascii_char(13)
       ||'       documento_id,'||ascii_char(13)
       ||'       estado_civil_id,'||ascii_char(13)
       ||'       profissao_id, '||ascii_char(13)
       ||'       data_nascimento, '||ascii_char(13)
       ||'       pais_nascimento, '||ascii_char(13)
       ||'       uf_naturalidade, '||ascii_char(13)
       ||'       nacionalidade, '||ascii_char(13)
       ||'       nome_pai, '||ascii_char(13)
       ||'       nome_mae, '||ascii_char(13)
       ||'       cidade_naturalidade, '||ascii_char(13)
       ||'       data_emissao_doc, '||ascii_char(13)
       ||'       uf_emissor, '||ascii_char(13)
       ||'       orgao_emissor '||ascii_char(13)
       ||'  from ('||ascii_char(13);

  iTabela = (select count(rdb$relation_id) from rdb$relations where rdb$system_flag = 0 and rdb$relation_name = 'D_PESSOA');
  if ((iTabela > 0) AND (:V_TABELA = 'D_PESSOA' )) then
  begin
    vSQL_T = vSQL_T
         ||' select d.pessoa_id,'||ascii_char(13)
         ||'        '''||'d_pessoa'||''' tabela,'||ascii_char(13)
         ||'        '''||'RTD'||''' serventia,'||ascii_char(13)
         ||'        cast(7 as numerico) serventiaid,'||ascii_char(13)
         ||'        d.nome,'||ascii_char(13)
         ||'        '''' sexo,'||ascii_char(13)
         ||'        d.cpfcnpj cpf_cnpj,'||ascii_char(13)
         ||'        '''||'N'||''' cpf_terceiro,'||ascii_char(13)
         ||'        d.endereco,'||ascii_char(13)
         ||'        d.bairro,'||ascii_char(13)
         ||'        d.cidade,'||ascii_char(13)
         ||'        d.uf,'||ascii_char(13)
         ||'        d.cep,'||ascii_char(13)
         ||'        d.telefone,'||ascii_char(13)
         ||'        d.documento,'||ascii_char(13)
         ||'        cast(null as numerico) documento_id,'||ascii_char(13)
         ||'        cast(null as numerico) estado_civil_id,'||ascii_char(13)
         ||'        cast(null as numerico) profissao_id,'||ascii_char(13)
         ||'        cast(null as datahora) data_nascimento,'||ascii_char(13)
         ||'        cast(null as numerico) pais_nascimento,'||ascii_char(13)
         ||'        '''' uf_naturalidade,'||ascii_char(13)
         ||'        '''' nacionalidade,'||ascii_char(13)
         ||'        '''' nome_pai,'||ascii_char(13)
         ||'        '''' nome_mae,'||ascii_char(13)
         ||'        '''' cidade_naturalidade,'||ascii_char(13)
         ||'        cast(null as datahora) data_emissao_doc,'||ascii_char(13)
         ||'        '''' uf_emissor,'||ascii_char(13)
         ||'        cast(null as numerico) orgao_emissor'||ascii_char(13)
         ||'   from d_pessoa d'||ascii_char(13);
  end

  iTabela = (select count(rdb$relation_id) from rdb$relations where rdb$system_flag = 0 and rdb$relation_name = 'P_PESSOA');
  if ((iTabela > 0) AND (:V_TABELA = 'P_PESSOA' )) then
  begin
    if (vSQL_T <> '') then
        vSQL_T = vSQL_T||' union all';

    vSQL_T = vSQL_T
         ||' select p.pessoa_id,'||ascii_char(13)
         ||'        '''||'p_pessoa'||''' tabela,'||ascii_char(13)
         ||'        '''||'Protesto'||''' serventia,'||ascii_char(13)
         ||'        cast(13 as numerico) serventiaid,'||ascii_char(13)
         ||'        p.nome,'||ascii_char(13)
         ||'        '''' sexo,'||ascii_char(13)
         ||'        p.cpfcnpj cpf_cnpj,'||ascii_char(13)
         ||'        '''||'N'||''' cpf_terceiro,'||ascii_char(13)
