         ||'        r.nacionalidade,'||ascii_char(13)
         ||'        '''' nome_pai,'||ascii_char(13)
         ||'        '''' nome_mae,'||ascii_char(13)
         ||'        '''' cidade_naturalidade,'||ascii_char(13)
         ||'        cast(null as datahora) data_emissao_doc,'||ascii_char(13)
         ||'        r.ORGAO_EXPEDIDOR_UF uf_emissor,'||ascii_char(13)
         ||'        r.ORGAO_EXPEDIDOR orgao_emissor'||ascii_char(13)
