         ||'        t.estrangeiro_nat_tb_pais_id pais_nascimento,'||ascii_char(13)
         ||'        t.uf uf_naturalidade,'||ascii_char(13)
         ||'        t.nacionalidade nacionalidade,'||ascii_char(13)
         ||'        t.nome_pai nome_pai,'||ascii_char(13)
         ||'        t.nome_mae nome_mae,'||ascii_char(13)
         ||'        t.naturalidade cidade_naturalidade,'||ascii_char(13)
         ||'        t.documento_expedicao data_emissao_doc,'||ascii_char(13)
         ||'        t.documento_uf uf_emissor, '||ascii_char(13)
         ||'        coalesce(cast(o.Orgao_emissor_id as integer),0) orgao_emissor'||ascii_char(13)
