         ||'   left outer join G_ORGAO_EMISSOR o on (t.documento_orgao = o.abreviatura) ';
  end

  iTabela = (select count(rdb$relation_id) from rdb$relations where rdb$system_flag = 0 and rdb$relation_name = 'V_PESSOA');
  if ((iTabela > 0) AND (:V_TABELA = 'V_PESSOA' )) then
  begin
    if (vSQL_T <> '') then
        vSQL_T = vSQL_T||' union all';

    vSQL_T = vSQL_T
         ||' select v.pessoa_id,'||ascii_char(13)
         ||'        '''||'v_pessoa'||''' tabela,'||ascii_char(13)
         ||'        '''||'Registro Civil'||''' serventia,'||ascii_char(13)
         ||'        cast(12 as numerico) serventiaid,'||ascii_char(13)
