         ||'        v.uf,'||ascii_char(13)
         ||'        v.cep,'||ascii_char(13)
         ||'        substring(v.telefone from 1 for 15) telefone,'||ascii_char(13)
         ||'        substring(v.documento from 1 for 30) documento,'||ascii_char(13)
         ||'        v.tb_documentotipo_id documento_id,'||ascii_char(13)
         ||'        v.tb_estadocivil_id estado_civil_id,'||ascii_char(13)
         ||'        v.tb_profissao_id profissao_id,'||ascii_char(13)
         ||'        v.data_nascimento data_nascimento,'||ascii_char(13)
         ||'        v.pais_nascimento pais_nascimento,'||ascii_char(13)
         ||'        v.uf_naturalidade,'||ascii_char(13)
         ||'        v.nacionalidade nacionalidade,'||ascii_char(13)
         ||'        v.nome_pai nome_pai,'||ascii_char(13)
         ||'        v.nome_mae nome_mae,'||ascii_char(13)
         ||'        v.naturalidade cidade_naturalidade,'||ascii_char(13)
         ||'        v.data_emissao_doc,'||ascii_char(13)
         ||'        v.uf_emissor_doc uf_emissor, '||ascii_char(13)
         ||'        substring(o.abreviatura from 1 for 30) orgao_emissor'||ascii_char(13)
         ||'   from v_pessoa v'||ascii_char(13)
         ||'   left outer join G_ORGAO_EMISSOR o on (v.ORGAO_EMISSOR_ID = o.ORGAO_EMISSOR_ID) ';
  end

  vSQL = vSQL
      || vSQL_T
      ||'        ) x'||ascii_char(13)
      ||'  where x.PESSOA_ID = '||:V_CAMPO_ID;

  FOR execute statement vSQL
      into :pessoa_id, :tabela, :serventia, :serventiaid, :nome, :sexo, :cpf_cnpj, :cpf_terceiro,
           :pessoa_tipo, :endereco, :bairro, :cidade, :uf,  :cep, :telefone, :documento,
           :documento_id, :estado_civil_id, :profissao_id, :data_nascimento, :pais_nascimento,
           :uf_naturalidade, :nacionalidade, :nome_pai, :nome_mae, :cidade_naturalidade,
           :data_emissao_doc, :uf_emissor, :orgao_emissor do
  begin
    suspend;
  end
end ^

ALTER PROCEDURE G_CORRIGE_SELOS_GO RETURNS (SELO_LOTE_ID INTEGER,
SIGLA VARCHAR(30) CHARACTER SET ISO8859_1,
QUANTIDADE INTEGER,
NUMERO_INICIAL INTEGER,
NUMERO_FINAL INTEGER,
STATUS VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
declare variable V_NUMERO_INICIAL_CHAR VARCHAR(10);
  declare variable V_NUMERO_FINAL_CHAR VARCHAR(10);
  declare variable V_SIGLA VARCHAR(20);
BEGIN
  FOR SELECT SELO_LOTE_ID, SIGLA, QUANTIDADE, NUMERO_INICIAL, NUMERO_FINAL
      FROM G_SELO_LOTE
      WHERE NUMERO_INICIAL > 99999
      AND CHAR_LENGTH(SIGLA) = 17
      INTO :SELO_LOTE_ID, :SIGLA, :QUANTIDADE, :NUMERO_INICIAL, :NUMERO_FINAL DO
  BEGIN
    V_NUMERO_INICIAL_CHAR = CAST(CAST(:NUMERO_INICIAL AS INTEGER) AS VARCHAR(10));
    V_NUMERO_INICIAL_CHAR = SUBSTRING(:V_NUMERO_INICIAL_CHAR FROM 2 FOR 5);

    V_NUMERO_FINAL_CHAR = CAST(CAST(:NUMERO_FINAL AS INTEGER) AS VARCHAR(10));
    V_NUMERO_FINAL_CHAR = SUBSTRING(:V_NUMERO_FINAL_CHAR FROM 2 FOR 5);

    V_SIGLA = SUBSTRING(:NUMERO_INICIAL FROM 1 FOR 1)||:SIGLA;

    UPDATE G_SELO_LOTE
    SET NUMERO_INICIAL = CAST(:V_NUMERO_INICIAL_CHAR AS INTEGER),
      NUMERO_FINAL = CAST(:V_NUMERO_FINAL_CHAR AS INTEGER),
      SIGLA = :V_SIGLA
    WHERE SELO_LOTE_ID = :SELO_LOTE_ID;

    UPDATE G_SELO_LIVRO
    SET SIGLA = SIGLA || SUBSTRING(CAST(CAST(NUMERO AS INTEGER) AS VARCHAR(6)) FROM 1 FOR 1),
      NUMERO = CAST(SUBSTRING(CAST(CAST(NUMERO AS INTEGER) AS VARCHAR(6)) FROM 2 FOR 5) AS INTEGER)
    WHERE SELO_LOTE_ID = :SELO_LOTE_ID;

    STATUS = 'OK';

    SUSPEND;
  END
END ^

ALTER PROCEDURE G_DIAS_PROTESTO (V_DATA_INI DATE,
QDT NUMERICO)
RETURNS (V_DATA DATE)
AS 
declare variable CONTADOR NUMERICO;
declare variable V_DIA NUMERICO;
declare variable FERIADO VARCHAR_060;
declare variable DATALOOP date;
BEGIN
  CONTADOR = 0;
  DATALOOP = V_DATA_INI;
  WHILE (CONTADOR < QDT) DO
  BEGIN
    SELECT coalesce(SIM_NAO, 'N') FROM G_VERIFICA_SE_EH_FERIADO(CAST(cast(:DATALOOP as date) AS VARCHAR(12))) INTO :FERIADO;
    if ((FERIADO = 'S') OR (EXTRACT(WEEKDAY FROM :DATALOOP) IN (0,6))) THEN
    BEGIN
      DATALOOP = dateadd(DAY, 1, DATALOOP);
    END ELSE
    BEGIN
      CONTADOR = CONTADOR + 1;
      DATALOOP = dateadd(DAY, 1, DATALOOP);
    END
  END
    V_DATA = DATALOOP;
  SUSPEND;

end ^

ALTER PROCEDURE G_DIAS_UTEIS (V_DATA_INI DATE,
V_DATA_FIM DATE)
RETURNS (DIAS NUMERICO)
AS 
declare variable contador numerico;
declare variable v_dia numerico;
declare variable feriado varchar_060;
BEGIN
    CONTADOR = 0;
    WHILE (V_DATA_INI < V_DATA_FIM) DO
    BEGIN
        SELECT EXTRACT(WEEKDAY FROM :V_DATA_INI) FROM RDB$DATABASE INTO :V_DIA;
        IF(V_DIA <> 6 AND V_DIA <> 0) THEN
        begin
            SELECT coalesce(SIM_NAO, 'N') FROM C_VERIFICA_SE_EH_FERIADO(CAST(cast(:V_DATA_INI as date) AS VARCHAR(12))) INTO :FERIADO;
            if (FERIADO <> 'S') THEN
            BEGIN
                CONTADOR = CONTADOR + 1;
            END
        END
        V_DATA_INI = dateadd(DAY, 1, V_DATA_INI);
    END
    DIAS = CONTADOR;
    SUSPEND;
END ^

ALTER PROCEDURE G_ESTOQUE_SELO (V_SELO_GRUPO_ID NUMERIC(18, 2),
V_DATA VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (V_QTD INTEGER)
AS 
DECLARE VARIABLE V_QTD_USADA NUMERIC(12, 2);
DECLARE VARIABLE V_QTD_LOTE NUMERIC(12, 2);
BEGIN
  SELECT SUM((NUMERO_FINAL+1) - NUMERO_INICIAL) AS QTD
  FROM G_SELO_LOTE
  WHERE DATA_LOTE <= :V_DATA
    AND SELO_GRUPO_ID = :V_SELO_GRUPO_ID
  INTO :V_QTD_LOTE;

  SELECT SUM((NUMERO_FINAL+1) - NUMERO_INICIAL) AS QTD
  FROM G_SELO_LOTE
  WHERE DATA_LOTE <= :V_DATA
    AND SELO_GRUPO_ID = :V_SELO_GRUPO_ID
  INTO :V_QTD_LOTE;

  SELECT COUNT(SL.SELO_LIVRO_ID) AS QTD
  FROM G_SELO_LIVRO SL LEFT JOIN G_SELO_LOTE ST ON
    SL.SELO_LOTE_ID = ST.SELO_LOTE_ID
  WHERE SL.SELO_SITUACAO_ID > 1
    AND ST.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
    AND DATA <= :V_DATA
  INTO :V_QTD_USADA;

  V_QTD = V_QTD_LOTE - V_QTD_USADA;

  SUSPEND;
END ^

ALTER PROCEDURE G_GERADOR_RECURSIVO (V_DATA_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_EVITAFERIADOS VARCHAR(1) CHARACTER SET ISO8859_1)
RETURNS (DATA_GERADA DATE,
CONTADOR INTEGER,
DIA_SEMANA VARCHAR(40) CHARACTER SET ISO8859_1)
AS 
declare variable V_SQL varchar(10000);
declare variable VDATAINICIAL date;
declare variable VDATAFINAL date;
declare variable ROW_CONTADOR integer;
declare variable DIASEMANA integer;
declare variable FERIADO integer;
declare variable DIA varchar(40);
begin
  vdatainicial = CAST(:V_DATA_INICIAL AS DATE );
  vdatafinal = CAST(:V_DATA_FINAL AS DATE );
  ROW_CONTADOR = 1;
 while  (vdatainicial <= vdatafinal) do
  begin
    DIASEMANA = extract(WEEKDAY from :vdatainicial);
    DIA = CASE :DIASEMANA
     WHEN 0 THEN 'DOMINGO'
     WHEN 1 THEN 'SEGUNDA-FEIRA'
     WHEN 2 THEN 'TERÇA-FEIRA'
     WHEN 3 THEN 'QUARTA-FEIRA'
     WHEN 4 THEN 'QUINTA-FEIRA'
     WHEN 5 THEN 'SEXTA-FEIRA'
     WHEN 6 THEN 'SÁBADO'
   END;

    if  ((V_EVITAFERIADOS ='S') AND ( (DIASEMANA IN (0,6)) OR EXISTS(SELECT FIRST 1 FERIADO_ID FROM G_FERIADO
         WHERE SITUACAO = 'A' AND (DIA = (extract (day from cast(:vdatainicial as timestamp ))))
         AND (MES = (extract (month from cast(:vdatainicial as timestamp ))))))) THEN
      FERIADO = :ROW_CONTADOR;
     ELSE
      for select :vdatainicial as dtini, :ROW_CONTADOR, :DIA FROM RDB$DATABASE into :DATA_GERADA, :CONTADOR, DIA_SEMANA do
    BEGIN
    suspend;
    END
    vdatainicial = dateadd(day, 1 ,vdatainicial);
    ROW_CONTADOR = ROW_CONTADOR +1;
   END
end ^

ALTER PROCEDURE G_GERAR_STRING_RANDOMICA (V_TAMANHO INTEGER)
RETURNS (STRING VARCHAR(100) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_INTEIRO INTEGER;
  DECLARE VARIABLE V_LETRAS VARCHAR(100);
  DECLARE VARIABLE V_CONT INTEGER;
  DECLARE VARIABLE V_LENGHT INTEGER;
BEGIN
  STRING = '';
  V_LETRAS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  V_LENGHT = CHAR_LENGTH(:V_LETRAS);

  V_CONT = 0;
  WHILE (:V_CONT < :V_TAMANHO) DO
  BEGIN
    V_INTEIRO = TRUNC(((rand()*9)*(:V_LENGHT/10))+1);
    STRING = :STRING || SUBSTRING(:V_LETRAS FROM :V_INTEIRO FOR 1);
    V_CONT = :V_CONT + 1;
  END
  SUSPEND;
END ^

ALTER PROCEDURE G_PESQUISA_ANIVERSARIO (V_DATA_INI VARCHAR(10) CHARACTER SET ISO8859_1,
V_DATA_FIN VARCHAR(10) CHARACTER SET ISO8859_1,
V_SELECIONADO VARCHAR(1) CHARACTER SET ISO8859_1)
RETURNS (NOME VARCHAR(100) CHARACTER SET ISO8859_1,
CIDADE VARCHAR(50) CHARACTER SET ISO8859_1,
UF VARCHAR(3) CHARACTER SET ISO8859_1,
TELEFONE VARCHAR(30) CHARACTER SET ISO8859_1,
CIVIL NUMERICO,
EMAIL VARCHAR(120) CHARACTER SET ISO8859_1,
DATA_NASCIMENTO TIMESTAMP,
DATA VARCHAR(15) CHARACTER SET ISO8859_1,
SISTEMA VARCHAR(30) CHARACTER SET ISO8859_1,
SISTEMA_ID NUMERICO,
SELECIONADO VARCHAR(1) CHARACTER SET ISO8859_1,
PESSOA_ID NUMERICO)
AS 
declare variable V_SQL VARCHAR(10000);
declare variable V_SQL_TABELA VARCHAR(1000);
declare variable V_WHERE VARCHAR(1000);
declare variable V_EXISTE numerico;
declare variable v_sistema varchar(20);
declare variable v_existe_sistema numerico;
declare variable v_condicao varchar(10);

BEGIN

    if ((extract (month from cast(:V_DATA_INI as timestamp ))) = (extract (month from cast(:V_DATA_FIN as timestamp )))) then
    begin
     v_condicao = 'AND';
    end else v_condicao = 'OR';


    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('ATO_PRATICADO', 'GERAL', 'SISTEMAS_ATO_PRATICADO', 5)
    INTO :v_sistema;

    V_SQL_TABELA = 'SELECT COUNT(*) AS EXISTE FROM RDB$RELATIONS
                          WHERE RDB$SYSTEM_FLAG = 0
                            AND RDB$RELATION_NAME = ''P_PESSOA'' ';
    EXECUTE STATEMENT V_SQL_TABELA INTO V_EXISTE;
    BEGIN
        SUSPEND;
    END

    v_existe_sistema = position ('5' in :v_sistema);

    if (  :v_existe_sistema > 0  ) then
    begin
        if (V_EXISTE = 1) then
        BEGIN
            V_SQL = ' select NOME
                            ,CIDADE
                            ,UF
                            ,TELEFONE
                            ,ESTADO_CIVIL_ID as civil
                            ,EMAIL
                            ,DATA_NASCIMENTO as DATA_NASCIMENTO
                            ,((extract (month from(DATA_NASCIMENTO ))) ||''/''|| ( extract (day from (DATA_NASCIMENTO))) )  as DATA
                            ,(select descricao
                                from g_sistema
                                where sistema_id = 13) as sistema
                            ,13 as sistema_id
                            ,'''||:v_selecionado||''' as SELECIONADO
                            ,PESSOA_ID
                        from p_pessoa
                        WHERE 1=1
                        and --verifica o mes
                        (extract (month from(DATA_NASCIMENTO )))  >= (extract (month from cast('''||V_DATA_INI||''' as timestamp )))
                        and
                        (extract (month from(DATA_NASCIMENTO )))  <= (extract (month from cast('''||V_DATA_FIN||''' as timestamp )))
                    
                        and( --verifica o dia
                        (extract (day from(DATA_NASCIMENTO )))  >= (extract (day from cast('''||V_DATA_INI||''' as timestamp )))
                        and (extract (month from(DATA_NASCIMENTO ))) <= (extract (month from cast('''||V_DATA_INI||''' as timestamp ))) '
                        ||:v_condicao||
                          ' (extract (day from(DATA_NASCIMENTO )))  <= (extract (day from cast('''||V_DATA_FIN||''' as timestamp )))
                        and (extract (month from(DATA_NASCIMENTO ))) = (extract (month from cast('''||V_DATA_FIN||''' as timestamp ))))';

            FOR EXECUTE STATEMENT V_SQL INTO
                :NOME, :CIDADE, :UF, :TELEFONE,
                :CIVIL, :EMAIL, :DATA_NASCIMENTO,
                :DATA, :sistema, :sistema_id, :SELECIONADO, :PESSOA_ID DO
            BEGIN
                SUSPEND;
            END
        END
    end
    V_SQL_TABELA = 'SELECT COUNT(*) AS EXISTE FROM RDB$RELATIONS
                          WHERE RDB$SYSTEM_FLAG = 0
                            AND RDB$RELATION_NAME = ''T_PESSOA'' ';
    EXECUTE STATEMENT V_SQL_TABELA INTO V_EXISTE;
    BEGIN
        SUSPEND;
    END

    v_existe_sistema = position ('2' in :v_sistema);

    if (  :v_existe_sistema > 0  ) then
    begin
        if (V_EXISTE = 1) then
        BEGIN
            V_SQL = ' select NOME
                            ,CIDADE
                            ,UF
                            ,TELEFONE
                            ,TB_ESTADOCIVIL_ID as civil
                            ,EMAIL
                            ,DATA_NASCIMENTO as DATA_NASCIMENTO
                            ,((extract (month from(DATA_NASCIMENTO ))) ||''/''|| ( extract (day from (DATA_NASCIMENTO))) )  as DATA
                            ,(select descricao
                                from g_sistema
                                where sistema_id = 2) as sistema
                            ,2 as sistema_id
                            ,'''||:v_selecionado||''' as SELECIONADO
                            ,PESSOA_ID
                        from t_pessoa
                        WHERE 1=1
                        and --verifica o mes
                        (extract (month from(DATA_NASCIMENTO )))  >= (extract (month from cast('''||V_DATA_INI||''' as timestamp )))
                        and
                        (extract (month from(DATA_NASCIMENTO )))  <= (extract (month from cast('''||V_DATA_FIN||''' as timestamp )))
                    
                        and( --verifica o dia
                        (extract (day from(DATA_NASCIMENTO )))  >= (extract (day from cast('''||V_DATA_INI||''' as timestamp )))
                        and (extract (month from(DATA_NASCIMENTO ))) <= (extract (month from cast('''||V_DATA_INI||''' as timestamp ))) '
                       ||:v_condicao||
                          ' (extract (day from(DATA_NASCIMENTO )))  <= (extract (day from cast('''||V_DATA_FIN||''' as timestamp )))
                        and (extract (month from(DATA_NASCIMENTO ))) = (extract (month from cast('''||V_DATA_FIN||''' as timestamp ))))';
    
            FOR EXECUTE STATEMENT V_SQL INTO
                :NOME, :CIDADE, :UF, :TELEFONE,
                :CIVIL, :EMAIL, :DATA_NASCIMENTO,
                :DATA, :sistema, :sistema_id, :SELECIONADO, :PESSOA_ID DO
            BEGIN
                SUSPEND;
            END
    
        END
    end

    V_SQL_TABELA = 'SELECT COUNT(*) AS EXISTE FROM RDB$RELATIONS
                          WHERE RDB$SYSTEM_FLAG = 0
                            AND RDB$RELATION_NAME = ''R_PESSOA'' ';
    EXECUTE STATEMENT V_SQL_TABELA INTO V_EXISTE;
    BEGIN
        SUSPEND;
    END

    v_existe_sistema = position ('1' in :v_sistema);

    if (  :v_existe_sistema > 0  ) then
    begin
        if (V_EXISTE = 1) then
        BEGIN
            V_SQL = ' select NOME
                             ,CIDADE
                             ,UF
                             ,TELEFONE
                            ,TB_ESTADOCIVIL_ID as civil
                            ,EMAIL
                            ,DATA_NASCIMENTO as DATA_NASCIMENTO
                            ,((extract (month from(DATA_NASCIMENTO ))) ||''/''|| ( extract (day from (DATA_NASCIMENTO))) )  as DATA
                            ,(select descricao
                                from g_sistema
                                where sistema_id = 1) as sistema
                            , 1 as sistema_id
                            ,'''||:v_selecionado||''' as SELECIONADO
                            ,PESSOA_ID
                        from R_PESSOA
                        WHERE 1=1
                        and --verifica o mes
                        (extract (month from(DATA_NASCIMENTO )))  >= (extract (month from cast('''||V_DATA_INI||''' as timestamp )))
                        and
                        (extract (month from(DATA_NASCIMENTO )))  <= (extract (month from cast('''||V_DATA_FIN||''' as timestamp )))
                    
                        and( --verifica o dia
                        (extract (day from(DATA_NASCIMENTO )))  >= (extract (day from cast('''||V_DATA_INI||''' as timestamp )))
                        and (extract (month from(DATA_NASCIMENTO ))) <= (extract (month from cast('''||V_DATA_INI||''' as timestamp ))) '
                        ||:v_condicao||
                         ' (extract (day from(DATA_NASCIMENTO )))  <= (extract (day from cast('''||V_DATA_FIN||''' as timestamp )))
                        and (extract (month from(DATA_NASCIMENTO ))) = (extract (month from cast('''||V_DATA_FIN||''' as timestamp ))))';
    
            FOR EXECUTE STATEMENT V_SQL INTO
                :NOME, :CIDADE, :UF, :TELEFONE,
                :CIVIL, :EMAIL, :DATA_NASCIMENTO,
                :DATA, :sistema, :sistema_id, :SELECIONADO, :PESSOA_ID DO
            BEGIN
                SUSPEND;
            END
    
        END
    end

    V_SQL_TABELA = 'SELECT COUNT(*) AS EXISTE FROM RDB$RELATIONS
                          WHERE RDB$SYSTEM_FLAG = 0
                            AND RDB$RELATION_NAME = ''D_PESSOA'' ';
    EXECUTE STATEMENT V_SQL_TABELA INTO V_EXISTE;
    BEGIN
        SUSPEND;
    END

    v_existe_sistema = position ('3' in :v_sistema);

    if (  :v_existe_sistema > 0  ) then
    begin
        if (V_EXISTE = 1) then
        BEGIN
            V_SQL = ' select NOME
                            ,CIDADE
                            ,UF
                            ,TELEFONE
                            ,TB_ESTADOCIVIL_ID as civil
                            ,EMAIL
                            ,DATA_NASCMENTO as DATA_NASCIMENTO
                            ,((extract (month from(DATA_NASCMENTO ))) ||''/''|| ( extract (day from (DATA_NASCMENTO))) )  as DATA
                            ,(select descricao
                                from g_sistema
                                where sistema_id = 7) as sistema
                            ,7 as sistema_id
                            ,'''||:v_selecionado||''' as SELECIONADO
                            ,PESSOA_ID
                        from D_PESSOA
                        WHERE 1=1
                        and --verifica o mes
                        (extract (month from(DATA_NASCMENTO )))  >= (extract (month from cast('''||V_DATA_INI||''' as timestamp )))
                        and
                        (extract (month from(DATA_NASCMENTO )))  <= (extract (month from cast('''||V_DATA_FIN||''' as timestamp )))
                    
                        and( --verifica o dia
                        (extract (day from(DATA_NASCMENTO )))  >= (extract (day from cast('''||V_DATA_INI||''' as timestamp )))
                        and (extract (month from(DATA_NASCMENTO ))) <= (extract (month from cast('''||V_DATA_INI||''' as timestamp ))) '
                        ||:v_condicao||
                         ' (extract (day from(DATA_NASCMENTO )))  <= (extract (day from cast('''||V_DATA_FIN||''' as timestamp )))
                        and (extract (month from(DATA_NASCMENTO ))) = (extract (month from cast('''||V_DATA_FIN||''' as timestamp ))))';
    
            FOR EXECUTE STATEMENT V_SQL INTO
                :NOME, :CIDADE, :UF, :TELEFONE,
                :CIVIL, :EMAIL, :DATA_NASCIMENTO,
                :DATA, :sistema, :sistema_id, :SELECIONADO, :PESSOA_ID DO
            BEGIN
                SUSPEND;
            END
    
        END
    end
END ^

ALTER PROCEDURE G_PESQUISA_PESSOAS (V_CPF_CNPJ VARCHAR_030,
V_NOME VARCHAR_260)
RETURNS (PESSOA_ID NUMERICO,
TABELA VARCHAR_030,
PESSOA_TIPO VARCHAR_003,
SERVENTIA VARCHAR_030,
SERVENTIAID NUMERICO,
NOME VARCHAR_260,
CPF_CNPJ VARCHAR_030,
CPF_TERCEIRO VARCHAR_001,
DOCUMENTO VARCHAR_030)
AS 
declare variable VSQL varchar(5000);
declare variable VSQL_T varchar(5000);
declare variable ITABELA integer;
begin
  vSQL_T = '';
  vSQL = 'select  pessoa_id,'||ascii_char(13)
       ||'       tabela,'||ascii_char(13)
       ||'       serventia,'||ascii_char(13)
       ||'       serventiaid,'||ascii_char(13)
       ||'       nome,'||ascii_char(13)
       ||'       cpf_cnpj,'||ascii_char(13)
       ||'       cpf_terceiro,'||ascii_char(13)
       ||'       pessoa_tipo,'||ascii_char(13)
       ||'       documento'||ascii_char(13)
       ||'  from ('||ascii_char(13);

  iTabela = (select count(rdb$relation_id) from rdb$relations where rdb$system_flag = 0 and rdb$relation_name = 'D_PESSOA');
  if (iTabela > 0) then
  begin
    vSQL_T = vSQL_T
         ||' select  d.pessoa_id,'||ascii_char(13)
         ||'        '''||'d_pessoa'||''' tabela,'||ascii_char(13)
         ||'        '''||'RTD'||''' serventia,'||ascii_char(13)
         ||'        cast(7 as numerico) serventiaid,'||ascii_char(13)
         ||'        d.nome,'||ascii_char(13)
         ||'        d.cpfcnpj cpf_cnpj,'||ascii_char(13)
         ||'        '''||'N'||''' cpf_terceiro,'||ascii_char(13)
         ||'       (case when char_length(cpfcnpj)=14 then '''||'J'||''' else '''||'F'||''' end) pessoa_tipo,'||ascii_char(13)
         ||'        d.documento'||ascii_char(13)
         ||'   from d_pessoa d'||ascii_char(13);
  end

  iTabela = (select count(rdb$relation_id) from rdb$relations where rdb$system_flag = 0 and rdb$relation_name = 'P_PESSOA');
  if (iTabela > 0) then
  begin
    if (vSQL_T <> '') then
        vSQL_T = vSQL_T||' union all';

    vSQL_T = vSQL_T
         ||' select p.pessoa_id,'||ascii_char(13)
         ||'        '''||'p_pessoa'||''' tabela,'||ascii_char(13)
         ||'        '''||'Protesto'||''' serventia,'||ascii_char(13)
         ||'        cast(13 as numerico) serventiaid,'||ascii_char(13)
         ||'        p.nome,'||ascii_char(13)
         ||'        p.cpfcnpj cpf_cnpj,'||ascii_char(13)
         ||'        '''||'N'||''' cpf_terceiro,'||ascii_char(13)
         ||'       (case when char_length(cpfcnpj)=14 then '''||'J'||''' else '''||'F'||''' end) pessoa_tipo,'||ascii_char(13)
         ||'        p.rg documento'||ascii_char(13)
         ||'   from p_pessoa p'||ascii_char(13);
  end

  iTabela = (select count(rdb$relation_id) from rdb$relations where rdb$system_flag = 0 and rdb$relation_name = 'R_PESSOA');
  if (iTabela > 0) then
  begin
    if (vSQL_T <> '') then
        vSQL_T = vSQL_T||' union all';

    vSQL_T = vSQL_T
         ||' select  r.pessoa_id,'||ascii_char(13)
         ||'        '''||'r_pessoa'||''' tabela,'||ascii_char(13)
         ||'        '''||'Registro de ImÃ³veis'||''' serventia,'||ascii_char(13)
         ||'        cast(1 as numerico) serventiaid,'||ascii_char(13)
         ||'        r.nome,'||ascii_char(13)
         ||'        r.cpf_cnpj,'||ascii_char(13)
         ||'        r.cpf_terceiro,'||ascii_char(13)
         ||'       (case when char_length(cpf_cnpj)=14 then '''||'J'||''' else '''||'F'||''' end) pessoa_tipo,'||ascii_char(13)
         ||'        substring(r.documento from 1 for 30) documento'||ascii_char(13)
         ||'   from r_pessoa r'||ascii_char(13);
  end

  iTabela = (select count(rdb$relation_id) from rdb$relations where rdb$system_flag = 0 and rdb$relation_name = 'T_PESSOA');
  if (iTabela > 0) then
  begin
    if (vSQL_T <> '') then
        vSQL_T = vSQL_T||' union all';

    vSQL_T = vSQL_T
         ||' select  t.pessoa_id,'||ascii_char(13)
         ||'        '''||'t_pessoa'||''' tabela,'||ascii_char(13)
         ||'        '''||'Tabelionato'||''' serventia,'||ascii_char(13)
         ||'        cast(2 as numerico) serventiaid,'||ascii_char(13)
         ||'        t.nome,'||ascii_char(13)
         ||'        t.cpf_cnpj,'||ascii_char(13)
         ||'        t.cpf_terceiro,'||ascii_char(13)
         ||'       (case when char_length(cpf_cnpj)=14 then '''||'J'||''' else '''||'F'||''' end) pessoa_tipo,'||ascii_char(13)
         ||'        t.documento'||ascii_char(13)
         ||'   from t_pessoa t'||ascii_char(13);
  end

  iTabela = (select count(rdb$relation_id) from rdb$relations where rdb$system_flag = 0 and rdb$relation_name = 'V_PESSOA');
  if (iTabela > 0) then
  begin
    if (vSQL_T <> '') then
        vSQL_T = vSQL_T||' union all';

    vSQL_T = vSQL_T
         ||' select  v.pessoa_id,'||ascii_char(13)
         ||'        '''||'v_pessoa'||''' tabela,'||ascii_char(13)
         ||'        '''||'Registro Civil'||''' serventia,'||ascii_char(13)
         ||'        cast(12 as numerico) serventiaid,'||ascii_char(13)
         ||'        v.nome,'||ascii_char(13)
         ||'        v.cpf_cnpj,'||ascii_char(13)
         ||'        v.cpf_terceiro,'||ascii_char(13)
         ||'       (case when char_length(cpf_cnpj)=14 then '''||'J'||''' else '''||'F'||''' end) pessoa_tipo,'||ascii_char(13)
         ||'        substring(v.documento from 1 for 30)'||ascii_char(13)
         ||'   from v_pessoa v'||ascii_char(13);
  end
  vSQL = vSQL
      || vSQL_T
      ||'        ) x'||ascii_char(13);
      if (:v_cpf_cnpj <> '') then
      begin
        vSQL = vSQL ||'  where x.cpf_cnpj = '||:v_cpf_cnpj||''||ascii_char(13);
      end
      else
      begin
        vSQL = vSQL ||'   where (x.nome like '''||:v_nome||''')'||ascii_char(13);
      end

  FOR execute statement vSQL
      into :pessoa_id, :tabela, :serventia, :serventiaid, :nome, :cpf_cnpj, :cpf_terceiro,:PESSOA_TIPO, :documento do
  begin
    suspend;
  end
end ^

ALTER PROCEDURE G_RETIRAR_ACENTUACAO (NOME VARCHAR(1000) CHARACTER SET ISO8859_1)
RETURNS (NOME_SEM_ACENTUACAO VARCHAR(1000) CHARACTER SET ISO8859_1)
AS 
declare variable I integer;
declare variable AUX varchar(1000);
declare variable STR varchar(1);
BEGIN
  AUX = UPPER(:NOME);
  I = 0;
  WHILE (:I < CHAR_LENGTH(:AUX)) DO
  BEGIN
    I = (:I + 1);
    STR = SUBSTRING(:AUX FROM :I FOR 1);
    SELECT CASE 
      WHEN (:STR IN ('Á', 'Â', 'Ã', 'À', 'Ä', 'Å')) THEN 'A'
      WHEN (:STR IN ('É', 'Ê', 'È', 'Ë')) THEN 'E'
      WHEN (:STR IN ('Í', 'Î', 'Ì', 'Ï')) THEN 'I'
      WHEN (:STR IN ('Ó', 'Ô', 'Õ', 'Ò', 'Ö')) THEN 'O'
      WHEN (:STR IN ('Ú', 'Û', 'Ù', 'Ü')) THEN 'U'
      WHEN (:STR IN ('Ç')) THEN 'C'
      WHEN (:STR IN ('Ñ')) THEN 'N'
      WHEN (:STR IN ('Ý', '')) THEN 'Y'
      WHEN (:STR IN ('&')) THEN 'e'
      ELSE :STR
      END AS VSTR      
    FROM RDB$DATABASE
    INTO :STR;
    IF (:I = 1) THEN
    BEGIN
      AUX = :STR|| SUBSTRING(:AUX FROM 2 FOR (CHAR_LENGTH(:AUX) -1));
    END
    ELSE
    BEGIN
      AUX = SUBSTRING(:AUX FROM 1 FOR (:I-1))||:STR||SUBSTRING(:AUX FROM (:I+1) FOR (CHAR_LENGTH(:AUX) -I));
    END      
  END
  NOME_SEM_ACENTUACAO = :AUX;
  SUSPEND;
END ^

ALTER PROCEDURE G_RETORNA_NUMERO (TEXTO VARCHAR(100) CHARACTER SET ISO8859_1)
RETURNS (RETORNO VARCHAR(100) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE CH CHAR(1);

BEGIN
  Retorno = '';
  WHILE (Texto IS NOT NULL AND Texto <> '') DO
  BEGIN
    Ch = SUBSTRING(Texto FROM 1 FOR 1);
    IF (Ch >= '0' AND Ch <= '9') THEN
      Retorno = Retorno || Ch;
    Texto = SUBSTRING(Texto FROM 2 FOR 100);
  END
  if (Retorno = '') then
    Retorno = '0';
  SUSPEND;
END ^

ALTER PROCEDURE G_SELOS_DISPONIVEL (V_SELO_GRUPO_ID DINHEIRO)
RETURNS (QTD INTEGER)
AS 
declare variable V_QTDE integer;
declare variable V_SELO_LOTE_ID integer;
BEGIN
   QTD = 0;
     FOR SELECT SELO_LOTE_ID FROM G_SELO_LOTE
                WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID 
                AND SITUACAO IN ('I','A')
                INTO :V_SELO_LOTE_ID DO
            BEGIN        
              SELECT COUNT(*) FROM G_SELO_LIVRO 
              WHERE SELO_SITUACAO_ID = 1 --SITUACAO DISPONIVEL
              AND SELO_LOTE_ID = :V_SELO_LOTE_ID
              INTO :V_QTDE;
              QTD = (QTD + COALESCE(:V_QTDE,0));
            END
    SUSPEND;
END ^

ALTER PROCEDURE G_SELO_CRITICAR (DECENDIO_ID INTEGER)
RETURNS (S_DECENDIO_ITEM_ID INTEGER,
S_NOTA_FISCAL VARCHAR_015,
S_DESCRICAO_ATO VARCHAR_260,
S_CODIGO_ATO VARCHAR_030,
S_NOME_PARTE VARCHAR_120,
S_VALOR_EMOLUMENTO DINHEIRO,
S_VALOR_EMOLUMENTO_OK VARCHAR_001,
S_VALOR_EMOLUMENTO_ENVIADO DINHEIRO,
S_VALOR_TAXA_JUDICIARIA DINHEIRO,
S_VALOR_TAXA_JUDICIARIA_OK VARCHAR_001,
S_VALOR_TAXA_JUDICIARIA_ENVIADO DINHEIRO,
S_VALOR_FUNDOS DINHEIRO,
S_VALOR_FUNDOS_OK VARCHAR_001,
S_VALOR_FUNDOS_CALCULO DINHEIRO,
S_VALOR_ISS DINHEIRO,
S_VALOR_ISS_OK VARCHAR_001,
S_VALOR_ISS_CALCULO DINHEIRO,
S_DATA_UTILIZACAO DATAHORA,
S_DATA_UTILIZACAO_OK VARCHAR_001,
S_DATA_UTILIZACAO_ENVIADO DATAHORA,
S_DATA_ENVIO DATAHORA,
S_DATA_ENVIO_OK VARCHAR_001,
S_DATA_ENVIO_ENVIADO DATAHORA,
S_SEM_ERROS VARCHAR_001,
S_SISTEMA_ID INTEGER,
S_SISTEMA VARCHAR_015)
AS 
declare variable DATAFINAL DATAHORA;
declare variable DATAINICIAL DATAHORA;
declare variable USAR_ISS VARCHAR_001;
declare variable PERC_ISS DINHEIRO;
declare variable TIPO_ATO integer;
declare variable ACHOU_ATO VARCHAR_001;
declare variable SITUACAO integer;
declare variable CODATO VARCHAR_030;
declare variable V_PERCENTUAL_FUNDOS_ESTADUAIS integer;
begin
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'PERCENTUAL_FUNDOS_ESTADUAIS', 5) INTO :V_PERCENTUAL_FUNDOS_ESTADUAIS;
  if (COALESCE(:V_PERCENTUAL_FUNDOS_ESTADUAIS,0) = 0) then
  BEGIN
    V_PERCENTUAL_FUNDOS_ESTADUAIS = 40;
  END
  V_PERCENTUAL_FUNDOS_ESTADUAIS = (:V_PERCENTUAL_FUNDOS_ESTADUAIS/100);

  SELECT COALESCE(VALOR, 'N')
    FROM G_CONFIG
   WHERE NOME  = 'USAR_ISS'
     AND SECAO = 'GERAL'
     AND CONFIG_GRUPO_ID IN ( SELECT CONFIG_GRUPO_ID FROM G_CONFIG_GRUPO WHERE SISTEMA_ID = 5 AND DESCRICAO = 'PRINCIPAL')
    INTO :USAR_ISS;

  SELECT REPLACE(COALESCE(VALOR, 0),',','.') FROM G_CONFIG
   WHERE NOME  = 'PERCENTUAL_ISS'
     AND SECAO = 'GERAL'
     AND CONFIG_GRUPO_ID IN ( SELECT CONFIG_GRUPO_ID FROM G_CONFIG_GRUPO WHERE SISTEMA_ID = 5 AND DESCRICAO = 'PRINCIPAL')
     INTO :PERC_ISS;

     SELECT DATA_INICIO, DATA_FIM from G_SELO_DECENDIO WHERE SELO_DECENDIO_ID = :decendio_id
     INTO :datainicial , :DATAFINAL;

    FOR
    SELECT     codigo_ato,
           Sum(COALESCE(valor_emolumento,0)) valor_emolumento,
           sum(COALESCE(valor_taxa_judiciaria,0)) valor_taxa_judiciaria,
           sum(COALESCE(VALOR_FUNDOS,0)) QTD
      FROM G_SELO_DECENDIO_ITEM
     WHERE g_selo_decendio_id = :DECENDIO_ID
     group by codigo_ato
      INTO :S_CODIGO_ATO, :S_VALOR_EMOLUMENTO, :S_VALOR_TAXA_JUDICIARIA, :S_VALOR_FUNDOS DO
     BEGIN
       S_VALOR_EMOLUMENTO_OK      = 'N';
       S_VALOR_TAXA_JUDICIARIA_OK = 'N';
       S_DATA_UTILIZACAO_OK       = 'N';
       S_DATA_ENVIO_OK            = 'N';
       SITUACAO                   = 2;

       S_VALOR_EMOLUMENTO_ENVIADO = null;
       S_VALOR_TAXA_JUDICIARIA_ENVIADO = null;
       S_VALOR_FUNDOS = null;
       S_VALOR_ISS = null;
       S_DATA_UTILIZACAO_OK = null;
       S_DATA_UTILIZACAO_ENVIADO = null;
       S_DATA_ENVIO_OK = 'N';
       S_DATA_ENVIO_ENVIADO = null;
       ACHOU_ATO = 'N';

     select descricao_completa,
     Case TIPO_CARTORIO
   When 1 Then 'TN'
   When 2 Then 'RI'
   When 3 Then 'RC'
   When 4 Then 'RTD'
   When 5 Then 'PT'
   End as Sistema from g_selo_grupo where numero = CAST(:S_CODIGO_ATO AS NUMERICO)
     into :s_descricao_ato, :s_sistema;

     SELECT SUM(COALESCE(VALOR_EMOLUMENTO,0)),
            SUM(COALESCE(VALOR_TAXA_JUDICIARIA,0)),
            COUNT(SELO_LIVRO_ID)
     FROM g_selo_lote GL
     LEFT JOIN g_selo_livro GS ON GL.selo_lote_id = GS.selo_lote_id
     LEFT JOIN G_SELO_GRUPO GP ON GL.selo_grupo_id = GP.selo_grupo_id
     WHERE CAST(GL.data_lote AS DATE) BETWEEN CAST(:DATAINICIAL AS DATE) AND CAST(:DATAFINAL AS DATE)
     AND GP.numero = CAST(:S_CODIGO_ATO AS NUMERICO)
         into :S_VALOR_EMOLUMENTO_ENVIADO,
              :S_VALOR_TAXA_JUDICIARIA_ENVIADO,
              :S_VALOR_FUNDOS;
       if (S_VALOR_EMOLUMENTO_ENVIADO <> S_VALOR_EMOLUMENTO  )  then
       begin
         S_VALOR_EMOLUMENTO_OK      = 'N';
       end
       else
         S_VALOR_EMOLUMENTO_OK      = 'S';

       if (S_VALOR_TAXA_JUDICIARIA_ENVIADO <> S_VALOR_TAXA_JUDICIARIA  )  then
       begin
         S_VALOR_TAXA_JUDICIARIA_OK      = 'N';
       end
       else
         S_VALOR_TAXA_JUDICIARIA_OK      = 'S';


       if ((S_VALOR_TAXA_JUDICIARIA_OK = 'N')or(S_VALOR_EMOLUMENTO_OK = 'N')) then
         S_SEM_ERROS = 'N';
       else
         S_SEM_ERROS = 'S';

       suspend;
     END
end ^

ALTER PROCEDURE G_SP_SEQUENCIAS (TABELA VARCHAR(30) CHARACTER SET ISO8859_1)
RETURNS (SEQUENCIA NUMERIC(10, 2))
AS 
declare variable V_COUNT integer;
declare variable V_CAMPO_ID varchar(100);
declare variable V_SEQ integer;
declare variable V_TABELA varchar(100);
BEGIN
  V_SEQ = 0;
  V_TABELA = UPPER(:TABELA);
  V_CAMPO_ID = TRIM(SUBSTRING(:V_TABELA FROM 3 FOR 100)||'_ID');

  --VERIFICAR SE SEQUENCIA ESTA EM DUPLICIDADE
  SELECT COUNT(*) FROM G_SEQUENCIA
  WHERE TABELA = :V_TABELA
  INTO :V_COUNT;
  IF (:V_COUNT > 1) THEN
  BEGIN
    DELETE FROM G_SEQUENCIA
    WHERE TABELA = :V_TABELA;
    V_COUNT = 0;
  END

  --SE SEQUENCIA NAO EXISTIR, CRIA ELA COM VALOR ZERADO
  IF (:V_COUNT = 0) THEN
  BEGIN
    INSERT INTO G_SEQUENCIA (TABELA, SEQUENCIA) VALUES (:V_TABELA, 0);
  END

  --LOCK NO REGISTRO
  SELECT SEQUENCIA FROM G_SEQUENCIA
  WHERE TABELA = :V_TABELA
  FOR UPDATE WITH LOCK
  INTO :V_SEQ;

  --SE SEQUENCIA = 0, VERIFICAR SE TABELA E CAMPO EXISTEM E CASO SIM, PEGA ULTIMO VALOR
  IF (:V_SEQ = 0) THEN
  BEGIN
    --verificar se tabel existe
    SELECT COUNT(RDB$RELATION_NAME) FROM RDB$RELATIONS
    WHERE RDB$SYSTEM_FLAG = 0
    AND RDB$RELATION_NAME = :V_TABELA
    INTO :V_COUNT;
    IF (:V_COUNT > 0) THEN
    BEGIN
      SELECT COUNT(*) FROM RDB$RELATION_FIELDS
      WHERE RDB$FIELD_NAME = :V_CAMPO_ID
      AND RDB$RELATION_NAME = :V_TABELA
      INTO :V_COUNT;
      IF (:V_COUNT > 0) THEN
      BEGIN
        EXECUTE STATEMENT 'SELECT COALESCE(MAX('||:V_CAMPO_ID||'),0) FROM '||:V_TABELA INTO :V_SEQ;
      END
    END
  END

  --PEGAR PROXIMA SEQUENCIA
  V_SEQ = :V_SEQ + 1;
  UPDATE G_SEQUENCIA SET SEQUENCIA = :V_SEQ WHERE TABELA = :V_TABELA;

  SEQUENCIA = :V_SEQ;

  SUSPEND;
END ^

ALTER PROCEDURE G_SP_SEQUENCIASNEW (TABELA VARCHAR(30) CHARACTER SET ISO8859_1,
INCREMENTA INTEGER = 1)
RETURNS (SEQUENCIA NUMERIC(10, 2))
AS 
declare variable V_COUNT integer;
declare variable V_CAMPO_ID varchar(100);
declare variable V_SEQ integer;
declare variable V_TABELA varchar(100);
BEGIN
/*
 Adenevaldo Pinto 04/05/2022
 Implementação do parametro incrementa o qual e responsavel pelas operaçoes da seuguencia
 numeros positivos serao incrementados tipo
  1 a seguencia vai avançar um numero
 -1 a sequencia vai subtrair um numero
  0 a sequencia mostra apenas o valor atual sem alteração
*/

  V_SEQ = 0;
  V_TABELA = UPPER(:TABELA);
  V_CAMPO_ID = TRIM(SUBSTRING(:V_TABELA FROM 3 FOR 100)||'_ID');

  --VERIFICAR SE SEQUENCIA ESTA EM DUPLICIDADE
  SELECT COUNT(*) FROM G_SEQUENCIA
  WHERE TABELA = :V_TABELA
  INTO :V_COUNT;
  IF (:V_COUNT > 1) THEN
  BEGIN
    DELETE FROM G_SEQUENCIA
    WHERE TABELA = :V_TABELA;
    V_COUNT = 0;
  END

  --SE SEQUENCIA NAO EXISTIR, CRIA ELA COM VALOR ZERADO
  IF (:V_COUNT = 0) THEN
  BEGIN
    INSERT INTO G_SEQUENCIA (TABELA, SEQUENCIA) VALUES (:V_TABELA, 0);
  END

  --LOCK NO REGISTRO
  SELECT SEQUENCIA FROM G_SEQUENCIA
  WHERE TABELA = :V_TABELA
  FOR UPDATE WITH LOCK
  INTO :V_SEQ;

  --SE SEQUENCIA = 0, VERIFICAR SE TABELA E CAMPO EXISTEM E CASO SIM, PEGA ULTIMO VALOR
  IF (:V_SEQ = 0) THEN
  BEGIN
    --verificar se tabel existe
    SELECT COUNT(RDB$RELATION_NAME) FROM RDB$RELATIONS
    WHERE RDB$SYSTEM_FLAG = 0
    AND RDB$RELATION_NAME = :V_TABELA
    INTO :V_COUNT;
    IF (:V_COUNT > 0) THEN
    BEGIN
      SELECT COUNT(*) FROM RDB$RELATION_FIELDS
      WHERE RDB$FIELD_NAME = :V_CAMPO_ID
      AND RDB$RELATION_NAME = :V_TABELA
      INTO :V_COUNT;
      IF (:V_COUNT > 0) THEN
      BEGIN
        EXECUTE STATEMENT 'SELECT COALESCE(MAX('||:V_CAMPO_ID||'),0) FROM '||:V_TABELA INTO :V_SEQ;
      END
    END
  END

  --PEGAR PROXIMA SEQUENCIA
  if (INCREMENTA <> 0) then
  begin
    V_SEQ = :V_SEQ +  INCREMENTA;
    UPDATE G_SEQUENCIA SET SEQUENCIA = :V_SEQ WHERE TABELA = :V_TABELA;
  end

  SEQUENCIA = :V_SEQ;

  SUSPEND;
END ^

