ALTER PROCEDURE G_VERIFICA_SE_EH_FERIADO (V_DATA VARCHAR(12) CHARACTER SET ISO8859_1)
RETURNS (SIM_NAO VARCHAR(2) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_FERIADO INTEGER;
BEGIN
  SELECT FIRST 1 FERIADO_ID FROM G_FERIADO
  WHERE SITUACAO = 'A'
  AND DATA BETWEEN CAST(:V_DATA AS TIMESTAMP) AND CAST(:V_DATA AS TIMESTAMP) + 0.9999
  INTO :V_FERIADO;
  IF (:V_FERIADO > 0) THEN
  BEGIN
    SIM_NAO = 'S';
  END
  ELSE
  BEGIN
    SIM_NAO = 'N';
  END
  SUSPEND;
END ^

ALTER PROCEDURE P_AJUSTA_SELOS (V_DATA_INICIAL DATAHORA,
V_DATA_FINAL DATAHORA)
RETURNS (TITULOS_ATUALIZADOS VARCHAR_120)
AS 
DECLARE VARIABLE TITULO_ID INTEGER;
 DECLARE VARIABLE NUMERO_AGRUPADOR VARCHAR_030;
BEGIN
  TITULOS_ATUALIZADOS = '';
  FOR SELECT TITULO_ID FROM P_TITULO WHERE DATA_APONTAMENTO BETWEEN :V_DATA_INICIAL AND :V_DATA_FINAL INTO :TITULO_ID DO
  BEGIN
    IF (COALESCE(:TITULO_ID,0) > 0) THEN
    BEGIN
      SELECT FIRST 1 NUMERO_AGRUPADOR FROM G_SELO_LIVRO
      WHERE CAMPO_ID = :TITULO_ID  AND TABELA = 'P_TITULO' AND DESCRICAO LIKE '%APONTAMENTO%' INTO :NUMERO_AGRUPADOR;

      IF(COALESCE(:NUMERO_AGRUPADOR,'') <> '') THEN
      BEGIN
        UPDATE G_SELO_LIVRO SET
        NUMERO_AGRUPADOR = :NUMERO_AGRUPADOR
        WHERE CAMPO_ID = :TITULO_ID AND TABELA = 'P_TITULO';

        TITULOS_ATUALIZADOS =  :TITULO_ID;
        SUSPEND;
      END

    END
  END
END ^

ALTER PROCEDURE P_ATOS_PRATICADOS_PROTESTO (VPDATAINICIAL DATAHORA,
VPDATAFINAL DATAHORA,
VPAPONTAMENTOS VARCHAR_001,
VPAVERBACOES VARCHAR_001,
VPCERTIDOES VARCHAR_001)
RETURNS (PROTOCOLO NUMERICO,
DATA DATAHORA,
REQUERENTE VARCHAR_090,
EMOLUMENTOS NUMERICO,
TAXA_JUDICIARIA NUMERICO,
TAXA_AVERBACAO NUMERICO,
TAXA_FUNDESP NUMERICO,
VALOR_DOCUMENTO NUMERICO,
OCORRENCIA VARCHAR_090,
NATUREZA VARCHAR_090,
TIPO VARCHAR_030)
AS 
begin

    if (vpApontamentos = 'S') then
    begin
        FOR
        SELECT T.NUMERO_APONTAMENTO,
        T.DATA_APONTAMENTO AS DATA,
        PA.NOME AS APRESENTANTE,
        COALESCE(T.VALOR_EMOLUMENTO,0)
            + COALESCE(T.VALOR_TAXA_INTIMACAO,0)
            + COALESCE(T.VALOR_TAXA_EDITAL , 0)
            + COALESCE(T.VALOR_TAXA_CORREIOS, 0) AS EMOLUMENTOS,
        COALESCE(T.VALOR_TAXA_JUDICIARIA, 0) AS TX_JUDICIARIA,
        0.00 AS TX_AVERBACAO,
        ((COALESCE(T.VALOR_EMOLUMENTO,0)
            + COALESCE(T.VALOR_TAXA_INTIMACAO,0)
            + COALESCE(T.VALOR_TAXA_EDITAL , 0)
            + COALESCE(T.VALOR_TAXA_CORREIOS, 0)) * 0.1) as TX_FUNDESP,
        COALESCE(T.VALOR_TITULO, 0) AS VALOR_DOCUMENTO,
        O.DESCRICAO AS OCORRENCIA,
        N.DESCRICAO AS NATUREZA,
        'APONTAMENTOS' as TIPO
        FROM P_TITULO T LEFT JOIN P_PESSOA_VINCULO PA ON PA.TITULO_ID = T.TITULO_ID AND PA.TIPO_VINCULO = 'APRESENTANTE'
        LEFT JOIN P_ESPECIE        N  ON N.ESPECIE_ID  = T.ESPECIE_ID
        LEFT JOIN P_OCORRENCIAS    O  ON O.OCORRENCIAS_ID     = T.OCORRENCIA_ID
        WHERE cast(T.DATA_APONTAMENTO as date) BETWEEN :vpDataInicial AND :vpDataFinal
        into :Protocolo, :Data, :Requerente, :Emolumentos, :Taxa_Judiciaria, :Taxa_averbacao, :Taxa_Fundesp, :Valor_documento, :Ocorrencia, :Natureza, :Tipo
        do
        SUSPEND;
    end

    if (vpAverbacoes = 'S') then
    begin
        for
        SELECT T.NUMERO_APONTAMENTO,
        T.DATA_CANCELAMENTO AS DATA,
        PA.NOME AS APRESENTANTE,
        0,
        0,
        COALESCE(T.VALOR_TAXA_AVERB, 0) + COALESCE(T.VALOR_TAXA_CANCEL, 0) AS TX_AVERBACAO,
        ((COALESCE(T.VALOR_TAXA_AVERB, 0) + COALESCE(T.VALOR_TAXA_CANCEL, 0)) * 0.1),
        0,
        O.DESCRICAO AS OCORRENCIA,
        N.DESCRICAO AS NATUREZA,
        'AVERBAÇÕES' as TIPO
        FROM P_TITULO T LEFT JOIN P_PESSOA_VINCULO PA ON PA.TITULO_ID = T.TITULO_ID AND PA.TIPO_VINCULO = 'APRESENTANTE'
        LEFT JOIN P_ESPECIE        N  ON N.ESPECIE_ID  = T.ESPECIE_ID
        LEFT JOIN P_OCORRENCIAS    O  ON O.OCORRENCIAS_ID     = T.OCORRENCIA_ID
        WHERE cast(T.DATA_CANCELAMENTO as date) BETWEEN :vpDataInicial AND :vpDataFinal
        into :Protocolo, :Data, :Requerente, :Emolumentos, :Taxa_Judiciaria, :Taxa_averbacao, :Taxa_Fundesp, :Valor_documento, :Ocorrencia, :Natureza, :Tipo
        do
        SUSPEND;
    END

    if (vpCertidoes = 'S') then
    begin
        for
        SELECT CERTIDAO_ID,
        DATA_CERTIDAO AS DATA,
        NOME,
        coalesce(VALOR_EMOLUMENTO,0)
            + COALESCE(VALOR_TAXA_EXTRA, 0),
        COALESCE(VALOR_TAXA_JUDICIARIA, 0),
        0,
        ((coalesce(VALOR_EMOLUMENTO,0) + COALESCE(VALOR_TAXA_EXTRA, 0)) * 0.1),
        0,
        'Certidão' AS OCORRENCIA,
        CASE TIPO_CERTIDAO
            WHEN 'P' THEN 'CERTIDÃO POSITIVA'
            WHEN 'N' THEN 'CERTIDÃO NEGATIVA'
            WHEN 'R' THEN 'CERTIDÃO RELAÇÃO'
            WHEN 'T' THEN 'CERTIDÃO TRASLADO'
        END  AS NATUREZA,
        'CERTIDÕES' as TIPO
        FROM P_CERTIDAO
        WHERE cast(DATA_CERTIDAO as date) BETWEEN :vpDataInicial AND :vpDataFinal
        into :Protocolo, :Data, :Requerente, :Emolumentos, :Taxa_Judiciaria, :Taxa_averbacao, :Taxa_Fundesp, :Valor_documento, :Ocorrencia, :Natureza, :Tipo
        do
        suspend;
    end


end ^

ALTER PROCEDURE P_DATA_VAZIA (DATA_INICIAL DATAHORA,
DATA_FINAL DATAHORA,
DIAS INTEGER)
RETURNS (TITULO_ID NUMERICO,
ESPECIE VARCHAR_003,
PROTOCOLO NUMERICO,
DATA_APONTAMENTO DATAHORA,
DATA_INTIMACAO DATAHORA,
APRESENTANTE VARCHAR_120,
VALOR_TITULO NUMERICO,
NATUREZA VARCHAR_260,
ESPECIE_ID NUMERICO,
NUMERO_LIVRO NUMERICO,
NUMERO_LIVRO_APONT VARCHAR_015,
NOSSO_NUMERO VARCHAR_030,
TIPO_ENDOSSO VARCHAR_001,
LIVRO VARCHAR_060,
FOLHA_APONTAMENTO NUMERICO,
DEVEDOR VARCHAR_120,
OCORRENCIA VARCHAR_260,
DATA_ACEITE DATAHORA,
DATA_DESISTENCIA DATAHORA,
DATA_PAGO DATAHORA,
DATA_PROTESTO DATAHORA,
DATA_CANCELAMENTO DATAHORA,
CREDOR VARCHAR_120,
CPFCNPJ_CREDOR VARCHAR_015,
CPFCNPJ_DEVEDOR VARCHAR_015,
DATA_EMISSAO_TITULO DATAHORA,
DATA_VENCIMENTO_TITULO DATAHORA,
FOLHA_PROTESTO NUMERICO,
NUMERO_PROTESTO NUMERICO,
CEDENTE_NOME VARCHAR_120,
CPFCNPJ_CEDENTE VARCHAR_015,
CIDADE_AGENCIA VARCHAR_030,
NUMERO_TITULO VARCHAR_030,
VALOR_TOTAL_CUSTAS DINHEIRO,
VALOR_TOTAL NUMERICO,
VALOR_TAXA_JUROS NUMERICO,
VALOR_TAXA_JUDICIARIA NUMERICO,
VALOR_TAXA_INTIMACAO NUMERICO,
VALOR_TAXA_FUNDESP NUMERICO,
VALOR_TAXA_EDITAL NUMERICO,
VALOR_TAXA_CORREIOS NUMERICO,
VALOR_TAXA_CANCEL NUMERICO,
VALOR_TAXA_AVERB NUMERICO,
VALOR_ISS NUMERICO,
VALOR_DESCONTO NUMERICO,
VALOR_EMOLUMENTO NUMERICO,
STATUS_IMPORTACAO VARCHAR_001,
LIVRO_PAGAMENTO NUMERICO,
LETRA_LIVRO_PAGAMENTO VARCHAR_003,
FOLHA_LIVRO_PAGAMENTO NUMERICO,
NUMERO_SELO VARCHAR_060,
QTD_PARCELA NUMERICO,
PAGAMENTO_POSTERIOR VARCHAR_001)
AS 
declare variable V_COUNT integer;
declare variable V_data datahora;
declare variable V_DIA NUMERICO;
declare variable FERIADO VARCHAR_060;
BEGIN
v_count = CAST(:DATA_INICIAL AS DATE) - CAST(:DATA_FINAL AS DATE);
FOR WITH RECURSIVE
DATES (DT) AS (
SELECT  CAST(:DATA_INICIAL AS DATE)
FROM RDB$DATABASE
UNION ALL
SELECT DT + 1 FROM DATES
WHERE DT <  CAST(:DATA_INICIAL AS DATE) + :dias
)
SELECT DT FROM DATES INTO :V_data do
begin
  data_pago = :DATA_INICIAL;
  SELECT EXTRACT(WEEKDAY FROM :V_data) FROM RDB$DATABASE INTO :V_DIA;
  IF(V_DIA <> 6 AND V_DIA <> 0) THEN
  begin
    SELECT coalesce(SIM_NAO, 'N') FROM G_VERIFICA_SE_EH_FERIADO(CAST(cast(:V_data as date) AS VARCHAR(12))) INTO :FERIADO;
    if (FERIADO <> 'S') THEN
    BEGIN
      TITULO_ID = -1;
      data_pago = :V_data;
      suspend;
    end
  end
end
end ^

ALTER PROCEDURE P_DEPOSITO_VALORES (DATA_INI TIMESTAMP,
DATA_FIM TIMESTAMP,
PNLOTE NUMERICO)
RETURNS (ID INTEGER,
DATA DATAHORA,
PROTOCOLO INTEGER,
PESSOA_ID INTEGER,
APONTAMENTO NUMERICO,
DESCRICAO VARCHAR_260,
VALOR_EMOLUMENTO DINHEIRO,
VALOR_TAXA_JUDICIARIA DINHEIRO,
VALOR_FUNDESP DINHEIRO,
VALOR_ISS DINHEIRO,
VALOR_TOTAL DINHEIRO,
TIPO_LANCAMENTO VARCHAR_001,
TIPO VARCHAR_060,
SISTEMA_ID INTEGER,
NOME VARCHAR_120,
CPFCNPJ VARCHAR_030,
BANCO VARCHAR_003,
AGENCIA VARCHAR_030,
CONTA VARCHAR_030,
NOME_BANCO VARCHAR_030,
CIDADE_AGENCIA VARCHAR_030)
AS 
declare variable V_TABELA varchar(2);
declare variable V_LOTE integer;
declare variable V_TOTAL_SELO DINHEIRO;
declare variable V_SQL varchar(10000);
declare variable V_SQLW varchar(10000);
begin
    V_SQL = ' ';

  /* listar depositos do periodo */
    V_SQL = 'SELECT d.deposito_previo_id,
                    d.PROTOCOLO,
                    d.DESCRICAO,
                    cast(cast(d.DATA_LANCTO as date)as timestamp),
                    d.TIPO_LANCAMENTO,
                    D.valor_totaL,
                    d.SISTEMA_ID,
                    d.nlote,
                    (SELECT first 1 PESSOA_ID FROM p_pessoa_vinculo PV WHERE PV.tipo_vinculo in(''APRESENTANTE'',''CEDENTE'') AND PV.titulo_id = D.protocolo) PESSOA_ID,
                    (SELECT NUMERO_APONTAMENTO FROM p_titulo WHERE TITULO_ID = D.protocolo)
               FROM G_DEPOSITO_PREVIO d
               WHERE SISTEMA_ID = 13
              AND d.DATA_LANCTO BETWEEN cast( ''' ||cast(cast(:DATA_INI as date) as varchar_015)|| ''' as timestamp) AND cast( ''' ||cast(cast(:DATA_FIM as date) as varchar_015)|| ''' as timestamp) + 0.9999';

    if (PNLOTE <> 0) then
    BEGIN
        V_SQL = V_SQL || '  AND D.nlote = '||:PNLOTE;
        V_SQL = V_SQL || '  AND D.TIPO_LANCAMENTO <> '||'''Z''';
    END

    FOR EXECUTE STATEMENT V_SQL INTO
        :ID, :PROTOCOLO, :DESCRICAO, :DATA,  :TIPO_LANCAMENTO, :VALOR_TOTAL, :SISTEMA_ID, :v_lote, :PESSOA_ID, :APONTAMENTO DO
     begin
       VALOR_EMOLUMENTO = 0;
       VALOR_TAXA_JUDICIARIA = 0;
       VALOR_FUNDESP = 0;
       VALOR_ISS = 0;
       if (:tipo_lancamento = 'V') then
         tipo = 'Depósito Apresentante';
       if (:tipo_lancamento = 'D') then
         tipo = 'Depósito Cartório';
       if (:tipo_lancamento = 'T') then
         tipo = 'Taxa Edital/ Taxa Correios';
      if (:tipo_lancamento = 'Z') then
      begin
         tipo = 'Transferência/Saída';
         APONTAMENTO = null;
      end

           if (coalesce(:PESSOA_ID,0) > 0 and (:tipo_lancamento = 'V')) then
           begin
             SELECT FIRST 1 case coalesce(PV.NOME,'') when '' then p.nome else pv.nome end as nome,
                     case coalesce(PV.cpfcnpj,'') when '' then p.cpfcnpj else pv.cpfcnpj end as  cpfcnpj,
                     case coalesce(PV.banco,'') when '' then P.banco else pv.banco end as banco,
                     case coalesce(PV.agencia,'') when '' then P.agencia else pv.agencia end as agencia,
                     case coalesce(PV.conta,'') when '' then P.conta else pv.conta end as  conta,
                     case coalesce(PV.nome_banco,'') when '' then P.nome_banco else pv.nome_banco end as nome_banco,
                     case coalesce(PV.cidade_agencia,'') when '' then  P.cidade_agencia else pv.cidade_agencia end as cidade_agencia
                     FROM p_pessoa_vinculo PV
             INNER JOIN P_PESSOA P ON PV.pessoa_id = P.pessoa_id
             WHERE PV.pessoa_id = :PESSOA_ID
             into :nome,:cpfcnpj,:banco,:agencia,:conta,:nome_banco,:cidade_agencia;
               suspend;
           end
           else
           begin
              nome = '';
              cpfcnpj = '';
              banco  = '';
              agencia = '';
              conta   = '';
              nome_banco  = '';
              cidade_agencia = '';
             suspend;
           end
     --aqui
    end
    /* listando os selos convertidos em receitas */
    V_SQLW = ' ';
    V_SQLW = 'SELECT s.nlote,
                case position(''*'', s.Descricao) WHEN 0 Then s.Descricao
               Else Substring(s.Descricao from 1 for position(''*'', s.Descricao)-1)
               End as Descricao,
               cast(cast(s.DATA as date)as timestamp),
               s.VALOR_EMOLUMENTO,
               s.VALOR_TAXA_JUDICIARIA,
               s.VALOR_FUNDESP,
               s.VALOR_ISS,
               (s.VALOR_ISS+s.VALOR_TAXA_JUDICIARIA+s.VALOR_FUNDESP),
               left(s.TABELA,2),
               0 PESSOA_ID,
               (SELECT NUMERO_APONTAMENTO FROM p_titulo WHERE TITULO_ID = S.campo_id)                   
      FROM G_SELO_LIVRO s
     WHERE s.DATA BETWEEN cast( ''' ||cast(cast(:DATA_INI as date) as varchar_015)|| ''' as timestamp) AND cast( ''' ||cast(cast(:DATA_FIM as date) as varchar_015)|| ''' as timestamp) + 0.9999
       and s.nlote IS NOT NULL
       AND S.tabela = ''P_TITULO''
       AND coalesce(s.NLOTE,0) > 0
       and s.valor_total > 0';

     if (PNLOTE <> 0) then
        V_SQLW = V_SQLW || 'AND S.nlote = '||:PNLOTE;
    FOR EXECUTE STATEMENT V_SQLW INTO
       :ID, :DESCRICAO, :DATA, :VALOR_EMOLUMENTO, :VALOR_TAXA_JUDICIARIA, :VALOR_FUNDESP, :VALOR_ISS, :VALOR_TOTAL, :V_TABELA, :PESSOA_ID, :APONTAMENTO DO
     BEGIN
       TIPO_LANCAMENTO = 'R';
       Tipo = 'Fundos + Taxa + ISS';
       if (:V_TABELA = 'P_') then
          SISTEMA_ID = 13;
        nome = '';
          cpfcnpj = '';
          banco  = '';
          agencia = '';
          conta   = '';
          nome_banco  = '';
          cidade_agencia = '';
       suspend;
     END
  --END
end ^

ALTER PROCEDURE P_ENVIO_EMOLUMENTO_CENPROT (V_DATA_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(20) CHARACTER SET ISO8859_1)
RETURNS (TITULO_ID NUMERICO,
DEVEDOR VARCHAR(1100) CHARACTER SET ISO8859_1,
CREDOR VARCHAR(1100) CHARACTER SET ISO8859_1,
APRESENTANTE VARCHAR(1100) CHARACTER SET ISO8859_1,
PAGAMENTO_POSTERIOR VARCHAR_001,
VALOR_TAXA_AVERB NUMERICO,
VALOR_EMOL_RETIRADA NUMERICO,
VALOR_TOTAL_CUSTAS NUMERICO,
VALOR_TITULO NUMERICO,
CODIGO VARCHAR_010,
VALOR_TAXA NUMERICO,
DATA_ENVIO TIMESTAMP,
UF VARCHAR(2) CHARACTER SET ISO8859_1,
NUMERO_CARTORIO_CENPROT VARCHAR(2) CHARACTER SET ISO8859_1,
DATA_PROTESTO_OU_APONTAMENTO TIMESTAMP,
CHAVE_UNICA_CENPROT VARCHAR_120,
NUMERO_APONTAMENTO NUMERICO,
DATA_APONTAMENTO TIMESTAMP,
DATA_PROTESTO TIMESTAMP,
VALOR_TAXA_JUROS NUMERICO,
IBGE VARCHAR(20) CHARACTER SET ISO8859_1)
AS 
declare variable CLB VARCHAR_003;
declare variable PROTESTO_PAG_DIFERIDO_MICRO VARCHAR_010;
declare variable PROTESTO_PAG_DIFERIDO VARCHAR_010;
declare variable FUNDOS_ESTADUAIS NUMERICO;
declare variable ISS NUMERICO;
declare variable EMOLUMENTO_PERIODO VARCHAR_015;
declare variable TAXA_CANCEL_MICRO_DIFERIDO VARCHAR_030;
declare variable TAXA_CANCEL_PROTESTO VARCHAR_030;
declare variable TAXA_CANCEL_DIFERIDO VARCHAR_030;
declare variable V_SQL_TAXA VARCHAR_1000;
declare variable V_SQL_FILTROS VARCHAR_1000;
declare variable V_SQL varchar(2000);
begin
SELECT
  CURRENT_DATE AS DATA_ENVIO,
 (SELECT MAX(EMOLUMENTO_PERIODO_ID) FROM G_EMOLUMENTO_PERIODO where DATA_INICIAL = (select max(data_inicial) from G_EMOLUMENTO_PERIODO)) AS EMOLUMENTO_PERIODO,
  MAX(CASE WHEN SECAO = 'CARTORIO' AND NOME = 'COD_IBGE' THEN C.VALOR END) AS IBGE,
  MAX(CASE WHEN SECAO = 'CARTORIO' AND NOME = 'CODIGO_CRA' THEN C.VALOR END) AS NUMERO_CARTORIO_CENPROT,
  MAX(CASE WHEN SECAO = 'CARTORIO' AND NOME = 'SIGLA_ESTADO' THEN C.VALOR END) AS UF,
  REPLACE (MAX(CASE WHEN SECAO = 'GERAL' AND NOME = 'PERCENTUAL_ISS' THEN C.VALOR END), ',','.' ) AS ISS,
  REPLACE (MAX(CASE WHEN SECAO = 'GOIAS' AND NOME = 'PERCENTUAL_FUNDOS_ESTADUAIS' THEN C.VALOR END), ',','.') AS FUNDOS_ESTADUAIS,
  MAX(CASE WHEN SECAO = 'VALORES' AND NOME = 'PROTESTO_PAG_DIFERIDO' THEN C.VALOR END) AS PROTESTO_PAG_DIFERIDO,
  MAX(CASE WHEN SECAO = 'VALORES' AND NOME = 'TAXA_CANCEL_DIFERIDO' THEN C.VALOR END) AS TAXA_CANCEL_DIFERIDO,
  MAX(CASE WHEN SECAO = 'VALORES' AND NOME = 'TAXA_CANCEL_PROTESTO' THEN C.VALOR END) AS TAXA_CANCEL_PROTESTO,
  MAX(CASE WHEN SECAO = 'MICROEMPRESA' AND NOME = 'TAXA_CANCEL_MICRO_DIFERIDO' THEN C.VALOR END) AS TAXA_CANCEL_MICRO_DIFERIDO,
  MAX(CASE WHEN SECAO = 'MICROEMPRESA' AND NOME = 'PROTESTO_PAG_DIFERIDO_MICRO' THEN C.VALOR END) AS PROTESTO_PAG_DIFERIDO_MICRO
FROM G_CONFIG C
LEFT JOIN G_CONFIG_GRUPO CG ON CG.CONFIG_GRUPO_ID = C.CONFIG_GRUPO_ID
WHERE CG.SISTEMA_ID IN (5,13)
  INTO
  :DATA_ENVIO, 
  :EMOLUMENTO_PERIODO,
  :IBGE,
  :NUMERO_CARTORIO_CENPROT,
  :UF,
  :ISS,
  :FUNDOS_ESTADUAIS,
  :PROTESTO_PAG_DIFERIDO,
  :TAXA_CANCEL_DIFERIDO,
  :TAXA_CANCEL_PROTESTO,
  :TAXA_CANCEL_MICRO_DIFERIDO,
  :PROTESTO_PAG_DIFERIDO_MICRO;

    /*Quebra de linha*/
  CLB = ASCII_CHAR(13) || ASCII_CHAR(10);

      V_SQL = ' ';
      V_SQL = ' SELECT  ' 
      ||cLB||     ' T.TITULO_ID, '
      ||cLB||     ' MAX(CASE WHEN PV.TIPO_VINCULO = ''APRESENTANTE'' THEN PV.NOME END) AS APRESENTANTE, ' 
      ||cLB||     ' MAX(CASE WHEN PV.TIPO_VINCULO = ''CREDOR'' THEN PV.NOME END) AS CREDOR, ' 
      ||cLB||     ' MAX(CASE WHEN PV.TIPO_VINCULO = ''DEVEDOR'' THEN PV.NOME END) AS DEVEDOR, ' 
      ||cLB||     ' T.VALOR_TITULO, '
      ||cLB||     ' T.VALOR_TOTAL_CUSTAS, '
      ||cLB||     ' T.VALOR_TOTAL_CUSTAS AS RETIRADA, '
      ||cLB||     ' T.VALOR_TAXA_JUROS,'
      ||cLB||     ' O.CODIGO, '
      ||cLB||     ' REPLACE(T.CHAVE_UNICA_CENPROT, ''-'','''') AS CHAVE_UNICA_CENPROT, '
      ||cLB||     ' T.PAGAMENTO_POSTERIOR, '
      ||cLB||     ' coalesce(T.DATA_PROTESTO, T.DATA_APONTAMENTO) as DATA_PROTESTO_OU_APONTAMENTO,'
      ||cLB||     ' T.DATA_PROTESTO,'
      ||cLB||     ' T.DATA_APONTAMENTO,'
      ||cLB||     ' T.NUMERO_APONTAMENTO '
      ||cLB||     ' FROM P_TITULO T '
      ||cLB||     ' LEFT JOIN P_OCORRENCIAS O ON O.OCORRENCIAS_ID = T.OCORRENCIA_ID'
      ||cLB||     '  LEFT JOIN P_PESSOA_VINCULO PV ON PV.TITULO_ID = T.TITULO_ID'
      ||cLB||     ' WHERE 1=1 ';

  V_SQL_FILTROS = ' ';
  if (COALESCE( :V_DATA_INICIAL,'') <> '' and COALESCE(:V_DATA_FINAL,'') <> '') then
  BEGIN
    V_SQL_FILTROS = ' AND  COALESCE(T.DATA_PROTESTO,T.DATA_APONTAMENTO) BETWEEN CAST(''' || :V_DATA_INICIAL ||''' AS TIMESTAMP ) AND CAST(  '''|| :V_DATA_FINAL || ''' AS TIMESTAMP) + 0.999 ';
  END

  V_SQL = :V_SQL || :V_SQL_FILTROS;
 V_SQL = :V_SQL || '  AND O.CODIGO IN (''0'',''2'') '
                 ||cLB|| ' AND PV.TIPO_VINCULO IN (''DEVEDOR'',''APRESENTANTE'',''CREDOR'') '
                 ||cLB|| 'GROUP BY '
                 ||cLB|| '  T.VALOR_TITULO, '
                 ||cLB|| '  T.VALOR_TOTAL_CUSTAS, '
                 ||cLB|| '  O.CODIGO, '
                 ||cLB|| '  T.CHAVE_UNICA_CENPROT, '
                 ||cLB|| '  T.PAGAMENTO_POSTERIOR, '
                 ||cLB|| '  DATA_PROTESTO_OU_APONTAMENTO, '
                 ||cLB|| '  T.DATA_PROTESTO, '
                 ||cLB|| '  T.DATA_APONTAMENTO, '
                 ||cLB|| '  T.NUMERO_APONTAMENTO, '
                 ||cLB|| '  T.VALOR_TAXA_JUROS, '
                 ||cLB|| '  T.TITULO_ID ';

  V_SQL = :V_SQL || ' ORDER BY DATA_PROTESTO_OU_APONTAMENTO, T.NUMERO_APONTAMENTO ';

  V_SQL_TAXA = ' ';
  for EXECUTE STATEMENT :V_SQL into
    :TITULO_ID, :APRESENTANTE, :CREDOR, :DEVEDOR, :VALOR_TITULO,:VALOR_TOTAL_CUSTAS, :VALOR_EMOL_RETIRADA, :VALOR_TAXA_JUROS, :CODIGO,
    :CHAVE_UNICA_CENPROT, :PAGAMENTO_POSTERIOR, :DATA_PROTESTO_OU_APONTAMENTO, :DATA_PROTESTO, :DATA_APONTAMENTO, :NUMERO_APONTAMENTO
  do
  begin
    --PROTESTADO
    VALOR_TOTAL_CUSTAS = VALOR_TOTAL_CUSTAS - VALOR_TAXA_JUROS;

    if (CODIGO = 2) then
    BEGIN

    VALOR_EMOL_RETIRADA = 0;
    V_SQL_TAXA = ' SELECT VALOR_EMOLUMENTO FROM G_EMOLUMENTO_ITEM WHERE EMOLUMENTO_PERIODO_ID = '||:EMOLUMENTO_PERIODO || ' AND EMOLUMENTO_ID = ' ||:TAXA_CANCEL_DIFERIDO||
    'AND '|| VALOR_TITULO || ' BETWEEN VALOR_INICIO AND VALOR_FIM ';

    execute statement :V_SQL_TAXA into
    :VALOR_TAXA;

       VALOR_TAXA_AVERB = VALOR_TAXA  + ROUND((VALOR_TAXA * FUNDOS_ESTADUAIS)/100, 2) + ROUND((VALOR_TAXA * ISS)/100, 2);
    END
    ELSE
    BEGIN
       VALOR_TAXA_AVERB = 0;
    END
    SUSPEND;
  end 
end ^

ALTER PROCEDURE P_PESQUISA_CENPROT (V_TIPO_OCORRENCIA VARCHAR(3) CHARACTER SET ISO8859_1,
V_DATA_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_NUM_PRO_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUM_PRO_FIN VARCHAR(15) CHARACTER SET ISO8859_1,
V_GERAR_NOVAMENTE VARCHAR(1) CHARACTER SET ISO8859_1 = 'N')
RETURNS (TITULO_ID NUMERIC(18, 2),
NUMERO_APONTAMENTO NUMERIC(18, 2),
DATA_APONTAMENTO TIMESTAMP,
DATA_CADASTRO TIMESTAMP,
VALOR_TITULO NUMERIC(18, 2),
VALOR_TOTAL NUMERIC(18, 2),
DATA_ACEITE TIMESTAMP,
NATUREZA VARCHAR(120) CHARACTER SET ISO8859_1,
OCORRENCIA VARCHAR_1000,
CODIGO_OCORRENCIA VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO_TITULO VARCHAR(30) CHARACTER SET ISO8859_1,
MOTIVO_APONTAMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
ESPECIE_PROTESTO VARCHAR(3) CHARACTER SET ISO8859_1,
VALOR_EMOLUMENTO NUMERIC(18, 2),
VALOR_TAXA_JUDICIARIA NUMERIC(18, 2),
VALOR_TAXA_INTIMACAO NUMERIC(18, 2),
VALOR_TAXA_EDITAL NUMERIC(18, 2),
VALOR_TAXA_JUROS NUMERIC(18, 2),
VALOR_DESCONTO NUMERIC(18, 2),
VALOR_TAXA_FUNDESP NUMERIC(18, 2),
VALOR_TAXA_AVERB NUMERIC(18, 2),
VALOR_TAXA_CORREIOS NUMERIC(18, 2),
DATA_SUSTADO TIMESTAMP,
MOTIVO_CANCELAMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
DATA_PROTESTO TIMESTAMP,
NUMERO_LIVRO NUMERIC(18, 2),
FOLHA_PROTESTO NUMERIC(18, 2),
MOTIVO_APONTAMENTO_ID NUMERIC(18, 2),
PRACA_PAGAMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
TIPO_ENDOSSO VARCHAR(1) CHARACTER SET ISO8859_1,
DEVEDOR_TIPO_ACEITE VARCHAR(1) CHARACTER SET ISO8859_1,
EDITAL_MOTIVO VARCHAR(260) CHARACTER SET ISO8859_1,
APRESENTACAO TIMESTAMP,
DATA_EMISSAO_TITULO TIMESTAMP,
DATA_VENCIMENTO_TITULO TIMESTAMP,
TIPO_ACEITE VARCHAR(1) CHARACTER SET ISO8859_1,
DATA_CANCELAMENTO TIMESTAMP,
DATA_PAGO TIMESTAMP,
DATA_DESISTENCIA TIMESTAMP,
DATA_INTIMACAO TIMESTAMP,
LIVRO_NATUREZA_ID NUMERIC(18, 2),
CODIGO_BANCO VARCHAR(30) CHARACTER SET ISO8859_1,
NOSSO_NUMERO VARCHAR(30) CHARACTER SET ISO8859_1,
DATA_ANUENCIA TIMESTAMP,
ORIGEM_ANUENCIA VARCHAR(3) CHARACTER SET ISO8859_1,
APRESENTANTE_PERMITIDO VARCHAR(1) CHARACTER SET ISO8859_1,
CEDENTE_PERMITIDO VARCHAR(1) CHARACTER SET ISO8859_1,
CREDOR_PERMITIDO VARCHAR(1) CHARACTER SET ISO8859_1,
ANUENCIA VARCHAR(1) CHARACTER SET ISO8859_1,
APRESENTANTE VARCHAR(260) CHARACTER SET ISO8859_1,
CPFCNPJ_APRE VARCHAR(15) CHARACTER SET ISO8859_1,
APRESENTANTE_ID NUMERIC(18, 2),
CREDOR_CPFCNPJ VARCHAR(15) CHARACTER SET ISO8859_1,
FAIXA VARCHAR(10) CHARACTER SET ISO8859_1,
PAGAMENTO_DIFERIDO VARCHAR(1) CHARACTER SET ISO8859_1,
INST_PDF BLOB,
CREDOR_NOME VARCHAR_260,
TIPO VARCHAR(30) CHARACTER SET ISO8859_1)
AS 
declare variable VSQLTOTAL varchar(32500);
declare variable VSQL varchar(25000);
declare variable VWHERE varchar(10000);
declare variable VTIPO varchar(15);
declare variable VOCORRENCIA varchar(15);
declare variable VCAMPO_TIPO varchar(240);
begin
  vsql = '';  
  vsqlTotal = '';
  VTIPO = '';

  if (V_TIPO_OCORRENCIA = 'T') then
  begin
    VTIPO = 'A I P C';
  end
  else
  begin
    VTIPO = V_TIPO_OCORRENCIA;
  end
  --AREA DO SELECT
  --REPETE UMA VEZ PARA CADA TIPO DE OCORRENCIA
  while (VTIPO <> '') do
  begin
    select substring(''||:VTIPO||'' from 1 for 2) from rdb$database
    into VOCORRENCIA;

    begin
      if (trim(VOCORRENCIA) = 'A') then
      begin
        VCAMPO_TIPO = ' trim(''APONTAMENTO'') as TIPO ';
        --VOCORRENCIA = 'APONTAMENTO';
      end
      else if (trim(VOCORRENCIA) = 'I') then
      begin
        VCAMPO_TIPO = ' trim(''INTIMACAO'') as TIPO ';
        --VOCORRENCIA = 'INTIMACAO';
      end
      else if (trim(VOCORRENCIA) = 'E') then
      begin
        VCAMPO_TIPO = ' trim(''INTIMACAO'') as TIPO ';
        --VOCORRENCIA = 'INTIMACAO';
      end
      else if (trim(VOCORRENCIA) = 'P') then
      begin
        VCAMPO_TIPO = ' trim(''PROTESTO'') as TIPO ';
        --VOCORRENCIA = 'PROTESTO';
      end
      else if (trim(VOCORRENCIA) = 'C') then
      begin
        VCAMPO_TIPO = ' case
                        when T.DATA_CANCELAMENTO is not null then trim(''CANCELADO'')
                        when T.DATA_PAGO is not null then trim(''PAGO'')
                        else trim(''OUTROS'') end TIPO ';
        --VOCORRENCIA = 'CANCELADO';
      end
      else if (trim(VOCORRENCIA) = 'PA') then
      begin
        VCAMPO_TIPO = ' case
                        when T.DATA_CANCELAMENTO is not null then trim(''CANCELADO'')
                        when T.DATA_PAGO is not null then trim(''PAGO'')
                        else trim(''OUTROS'') end TIPO ';
        --VOCORRENCIA = 'CANCELADO';--'PAGO';
      end
      else if (trim(VOCORRENCIA) = 'O') then
      begin
        VCAMPO_TIPO = ' case
                        when T.DATA_CANCELAMENTO is not null then trim(''CANCELADO'')
                        when T.DATA_PAGO is not null then trim(''PAGO'')
                        else trim(''OUTROS'') end TIPO ';
        --VOCORRENCIA = 'CANCELADO';--'OUTROS';
      end
    end

    vwhere  = '';
    if (vsql <> '') then
    begin
      vsql = ' union all ';
    end

    vsql = vsql || ' select T.TITULO_ID,
                    T.NUMERO_APONTAMENTO,
                    cast(T.DATA_APONTAMENTO as date) as DATA_APONTAMENTO,
                    cast(T.DATA_CADASTRO as date) as DATA_CADASTRO,
                    T.VALOR_TITULO,
                    T.VALOR_TOTAL,
                    cast(T.DATA_ACEITE as date) as DATA_ACEITE,
                    case
                      when (trim(E.ESPECIE) = ''CBI'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CC'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CCB'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CCC'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CCE'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CCI'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CCR'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CD'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CDA'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CH'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CHP'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CJV'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CM'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CPH'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CPS'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CRH'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CRP'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CT'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''DM'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''DMI'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''DR'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''DRI'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''DS'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''DSI'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''DV'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''EC'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''LC'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''NCC'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''NCE'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''NCI'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''NCR'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''NP'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''NPR'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''RA'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''SJ'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''TA'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''TM'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''TS'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''W'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CRJ'') then E.ESPECIE
                      when (trim(E.ESPECIE) = ''CRE'') then E.ESPECIE
                      else ''DV'' end as NATUREZA,
                    O.DESCRICAO as OCORRENCIA,
                    case O.CODIGO
                    when ''1'' then O.CODIGO
                    when ''2'' then O.CODIGO
                    when ''3'' then O.CODIGO
                    when ''4'' then O.CODIGO
                    when ''5'' then O.CODIGO
                    when ''A'' then O.CODIGO
                    when ''X'' then O.CODIGO
                    when ''G'' then O.CODIGO
                    else ''Y''
                    end as CODIGO_OCORRENCIA,
                    T.NUMERO_TITULO,
                    M.DESCRICAO as MOTIVO_APONTAMENTO,
                    M.CODIGO as ESPECIE_PROTESTO,
                    T.VALOR_EMOLUMENTO,
                    T.VALOR_TAXA_JUDICIARIA,
                    T.VALOR_TAXA_INTIMACAO,
                    T.VALOR_TAXA_EDITAL,
                    T.VALOR_TAXA_JUROS,
                    T.VALOR_DESCONTO,
                    T.VALOR_TAXA_FUNDESP,
                   T.VALOR_TAXA_AVERB,
                    T.VALOR_TAXA_CORREIOS,
                   cast(T.DATA_SUSTADO as date) as DATA_SUSTADO,
                    C.DESCRICAO as MOTIVO_CANCELAMENTO,
                    T.DATA_PROTESTO,
                    L.NUMERO_LIVRO,
                    T.FOLHA_PROTESTO,
                    case
                      when T.MOTIVO_APONTAMENTO_ID > 3 then 1
                      else T.MOTIVO_APONTAMENTO_ID
                    end as MOTIVO_APONTAMENTO_ID,
                    T.PRACA_PAGAMENTO,
                    T.TIPO_ENDOSSO,
                    PA.DEVEDOR_TIPO_ACEITE,
                    (select first 1 DESCRICAO
                       from P_OCORRENCIAS OE
                      where OE.OCORRENCIAS_ID = PA.OCORRENCIA_ID) as EDITAL_MOTIVO,
                    T.DATA_CADASTRO as APRESENTACAO,
                    T.DATA_EMISSAO_TITULO,
                    T.DATA_VENCIMENTO_TITULO,
                    T.TIPO_ACEITE,
                    T.DATA_CANCELAMENTO,
                    T.DATA_PAGO,
                    T.DATA_DESISTENCIA,
                    T.DATA_INTIMACAO,
                    L.LIVRO_NATUREZA_ID,
                    case
                    when T.BANCO_ID > 0 then BA.CODIGO_BANCO
                    else ''TAB''
                    end as CODIGO_BANCO,
                    T.NOSSO_NUMERO,
                    T.DATA_ANUENCIA,
                    T.ORIGEM_ANUENCIA,
                    T.APRESENTANTE_PERMITIDO,
                    T.CEDENTE_PERMITIDO,
                    T.CREDOR_PERMITIDO,
                    T.ANUENCIA,
                    coalesce(PA.NOME, PC.NOME) as APRESENTANTE,
                    coalesce(PA.CPFCNPJ, PC.CPFCNPJ) as CPFCNPJ_APRE,
                    coalesce(PA.PESSOA_ID, PC.PESSOA_ID) as APRESENTANTE_ID,
                    PC.CPFCNPJ as CREDOR_CPFCNPJ,
                    PC.NOME as CREDOR_NOME,
                    CC.FAIXA,
                    T.PAGAMENTO_DIFERIDO,
                    (select first 1 IP.inst_pdf
                       from P_INST_PROTESTO IP
                      where IP.TITULO_ID = T.TITULO_ID) AS inst_pdf, '
                    ||VCAMPO_TIPO||'
               from P_TITULO T
               left join P_ESPECIE E on E.ESPECIE_ID = T.ESPECIE_ID
               left join P_OCORRENCIAS O on O.OCORRENCIAS_ID = T.OCORRENCIA_ID
               left join P_MOTIVOS M on M.MOTIVOS_ID = T.MOTIVO_APONTAMENTO_ID
               left join P_MOTIVOS_CANCELAMENTO C on C.MOTIVOS_CANCELAMENTO_ID = T.MOTIVO_CANCELAMENTO
               left join P_PESSOA_VINCULO PA on PA.TITULO_ID = T.TITULO_ID and PA.TIPO_VINCULO = ''APRESENTANTE''
               left join P_PESSOA_VINCULO PC on PC.TITULO_ID = T.TITULO_ID and PC.TIPO_VINCULO = ''CREDOR''
               left join P_LIVRO_ANDAMENTO L on L.LIVRO_ANDAMENTO_ID = T.LIVRO_ID_PROTESTO
               left join P_BANCO BA on T.BANCO_ID = BA.BANCO_ID
               left join P_CUSTAS_CANCELAMENTO CC on CC.CUSTAS_CANCELAMENTO_ID = T.CUSTAS_CANCELAMENTO_ID
              where 1 = 1 AND ( STATUS_IMPORTACAO <> ''C'' or coalesce(STATUS_IMPORTACAO,'''')='''')  ';
    
    /*if ((coalesce(:v_num_pro_ini, '') <> '') and (coalesce(:v_num_pro_fin, '') <> '')) then
    begin
        vwhere = vwhere || ' and (T.NUMERO_APONTAMENTO between '||:v_num_pro_ini||' and '||:v_num_pro_fin||') '  ;
    end*/

    if (VOCORRENCIA = 'A')  then
    begin
      vwhere = vwhere || ' and T.DATA_APONTAMENTO is not null ';

      if ((coalesce(:v_data_inicial,'') <> '') and (coalesce(:v_data_final,'') <> '')) then
        begin
            vwhere = vwhere ||' and (T.DATA_APONTAMENTO between cast('''||:v_data_inicial||''' as timestamp) and cast('''||:v_data_final||''' as timestamp) + 0.9999)';
        end
        if (coalesce(:V_GERAR_NOVAMENTE, '') <> 'S') then
        begin
            vwhere = vwhere ||' and T.SITUACAO_CENPROT is null ';
        end
        if ((coalesce(:v_num_pro_ini, '') <> '') and (coalesce(:v_num_pro_fin, '') <> '')) then
        begin
            vwhere = vwhere || ' and (T.NUMERO_APONTAMENTO between '||:v_num_pro_ini||' and '||:v_num_pro_fin||') '  ;
        end
      vsqlTotal = vsqlTotal || vsql || vwhere;
    end
    else if (VOCORRENCIA = 'I') then
    begin
      vwhere = vwhere || ' and T.DATA_APONTAMENTO is not null ';

      if ((coalesce(:v_data_inicial,'') <> '') and (coalesce(:v_data_final,'') <> '')) then
        begin
            vwhere = vwhere ||' and (T.DATA_INTIMACAO between cast('''||:v_data_inicial||''' as timestamp) and cast('''||:v_data_final||''' as timestamp) + 0.9999)';
        end
        if (coalesce(:V_GERAR_NOVAMENTE, '') <> 'S') then
        begin
            vwhere = vwhere ||' and T.SITUACAO_CENPROT is null ';
        end
        if ((coalesce(:v_num_pro_ini, '') <> '') and (coalesce(:v_num_pro_fin, '') <> '')) then
        begin
            vwhere = vwhere || ' and (T.NUMERO_APONTAMENTO between '||:v_num_pro_ini||' and '||:v_num_pro_fin||') '  ;
        end
      vsqlTotal = vsqlTotal || vsql || vwhere;
    end
    else if (VOCORRENCIA = 'P') then
    begin
        vwhere = ' and T.DATA_PROTESTO is not null ';

        if ((coalesce(:v_data_inicial,'') <> '') and (coalesce(:v_data_final,'') <> '')) then
        begin
            vwhere = ' and (T.DATA_PROTESTO between cast( '''||:v_data_inicial||''' as timestamp) and cast('''||:v_data_final||''' as timestamp) + 0.9999) ';
        end
    
        if (coalesce(:V_GERAR_NOVAMENTE, '') <> 'S') then
        begin
            vwhere = vwhere ||' and T.SITUACAO_CENPROT is null ';
        end

        if ((coalesce(:v_num_pro_ini, '') <> '') and (coalesce(:v_num_pro_fin, '') <> '')) then
        begin
            vwhere = vwhere || ' and (T.NUMERO_APONTAMENTO between '||:v_num_pro_ini||' and '||:v_num_pro_fin||') '  ;
        end

       vsqlTotal = vsqlTotal || vsql || vwhere;
    end
    --Cancelamento, Pago, Desistencia, Sustado
    else if ((VOCORRENCIA = 'C') or (VOCORRENCIA = 'PA') or (VOCORRENCIA = 'O')) then
    begin
       vwhere = 'and (T.DATA_CANCELAMENTO is not null
                   or T.DATA_DESISTENCIA is not  null
                   or T.DATA_PAGO is not null
                   or T.DATA_SUSTADO is not null )';
       if ((coalesce(:v_data_inicial,'') <> '') and (coalesce(:v_data_final,'') <> '')) then
       begin
         vwhere = ' and ((T.DATA_CANCELAMENTO between cast( '''||:v_data_inicial||''' as timestamp) and cast('''||:v_data_final||''' as timestamp) + 0.9999)
                     or (T.DATA_DESISTENCIA between cast('''||:v_data_inicial||''' as timestamp) and cast('''||v_data_final||''' as timestamp) + 0.9999)
                     or (T.DATA_PAGO between cast('''||:v_data_inicial||''' as timestamp) and cast('''||v_data_final||''' as timestamp) + 0.9999)
                     or (T.DATA_SUSTADO between cast('''||:v_data_inicial||''' as timestamp) and cast('''||v_data_final||''' as timestamp) + 0.9999)) ';
       end
       if (coalesce(:V_GERAR_NOVAMENTE, '') <> 'S') then
       begin
           vwhere = vwhere ||' and (T.SITUACAO_CENPROT is null
                                or T.SITUACAO_CENPROT = 1) ';
       end
       if ((coalesce(:v_num_pro_ini, '') <> '') and (coalesce(:v_num_pro_fin, '') <> '')) then
        begin
            vwhere = vwhere || ' and (T.NUMERO_APONTAMENTO between '||:v_num_pro_ini||' and '||:v_num_pro_fin||') '  ;
        end
       vsqlTotal = vsqlTotal || vsql || vwhere;
    end
    else
    if (VOCORRENCIA = 'E') then
    begin
      if ((coalesce(:v_data_inicial,'') <> '') and (coalesce(:v_data_final,'') <> '')) then
      begin
        vwhere = vwhere ||' and (T.DATA_ACEITE between cast('''||:v_data_inicial||''' as timestamp) and cast('''||:v_data_final||''' as timestamp) + 0.9999)';
        vwhere = vwhere ||' and (T.DATA_CANCELAMENTO is null)
                            and (T.DATA_DESISTENCIA is null)
                            AND (T.DATA_PAGO is null)
                            AND (T.DATA_SUSTADO is null) AND (T.TIPO_ACEITE = ''E'')
                            AND (T.DATA_PROTESTO is null)';
      end
      if ((coalesce(:v_num_pro_ini, '') <> '') and (coalesce(:v_num_pro_fin, '') <> '')) then
        begin
          vwhere = vwhere || ' and (T.NUMERO_APONTAMENTO between '||:v_num_pro_ini||' and '||:v_num_pro_fin||') '  ;
        end
       vsqlTotal = vsqlTotal || vsql || vwhere;
    end

    select substring(''||:VTIPO||'' from 3 for 12) from rdb$database
    into VTIPO;
  end

  for execute statement :vsqlTotal
  into :TITULO_ID, :NUMERO_APONTAMENTO, :DATA_APONTAMENTO, :DATA_CADASTRO,
        :VALOR_TITULO, :VALOR_TOTAL, :DATA_ACEITE, :NATUREZA, :OCORRENCIA,
        :CODIGO_OCORRENCIA, :NUMERO_TITULO, :MOTIVO_APONTAMENTO, :ESPECIE_PROTESTO,
        :VALOR_EMOLUMENTO, :VALOR_TAXA_JUDICIARIA, :VALOR_TAXA_INTIMACAO,
        :VALOR_TAXA_EDITAL, :VALOR_TAXA_JUROS, :VALOR_DESCONTO, :VALOR_TAXA_FUNDESP,
        :VALOR_TAXA_AVERB, :VALOR_TAXA_CORREIOS, :DATA_SUSTADO, :MOTIVO_CANCELAMENTO,
        :DATA_PROTESTO, :NUMERO_LIVRO, :FOLHA_PROTESTO, :MOTIVO_APONTAMENTO_ID,
        :PRACA_PAGAMENTO, :TIPO_ENDOSSO, :DEVEDOR_TIPO_ACEITE, :EDITAL_MOTIVO,
        :APRESENTACAO, :DATA_EMISSAO_TITULO, :DATA_VENCIMENTO_TITULO, :TIPO_ACEITE,
        :DATA_CANCELAMENTO, :DATA_PAGO, :DATA_DESISTENCIA, :DATA_INTIMACAO, :LIVRO_NATUREZA_ID,
        :CODIGO_BANCO, :NOSSO_NUMERO, :DATA_ANUENCIA, :ORIGEM_ANUENCIA, : APRESENTANTE_PERMITIDO,
        :CEDENTE_PERMITIDO, :CREDOR_PERMITIDO, :ANUENCIA, :APRESENTANTE, :CPFCNPJ_APRE,
        :APRESENTANTE_ID, :CREDOR_CPFCNPJ, :CREDOR_NOME,  :FAIXA, :PAGAMENTO_DIFERIDO, :INST_PDF, :TIPO do
  begin
    suspend;
  end
end ^

ALTER PROCEDURE P_PESQUISA_CERTIDAO (V_DATA_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_CRETIDO_ID VARCHAR(20) CHARACTER SET ISO8859_1)
RETURNS (DATA_CERTIDAO TIMESTAMP,
QTD_CERTIDAO INTEGER,
QTD_PROTESTOS INTEGER,
QTD_CANCELADOS INTEGER,
QTD_SUSTADO INTEGER,
N_REMESSA INTEGER)
AS 
declare variable V_SQL varchar(10000);
declare variable V_SQL_FILTRO varchar(5000);
declare variable V_DATA_MAX timestamp;
declare variable V_DATA_MIM timestamp;
declare variable V_INI integer;
declare variable V_FIN integer;
declare variable V_DIA timestamp;
declare variable V_FERIADO integer;
declare variable SIM_NAO varchar(2);

begin

V_SQL        = ' ';
V_SQL_FILTRO = ' ';
    V_SQL = ' select P.DATA_CERTIDAO,
                 count(P.CERTIDAO_ID) as QTD_CERTIDAO,
                 sum(P.QTD_PROTESTOS) as QTD_PROTESTOS,
                 sum(P.QTD_CANCELADOS) as QTD_CANCELADOS,
                 sum(P.QTD_SUSTADO) as QTD_SUSTADO,
                 P.N_REMESSA
                 from P_CERTIDAO P
                     WHERE 1=1 ';

     V_SQL_FILTRO = :V_SQL_FILTRO || ' AND P.DATA_CERTIDAO BETWEEN CAST(''' ||:V_DATA_INICIAL|| '''  AS TIMESTAMP )
                              AND CAST(  ''' ||:V_DATA_FINAL|| ''' AS TIMESTAMP) + 0.9999 ';
     if (V_CRETIDO_ID <> '') then
        V_SQL_FILTRO = :V_SQL_FILTRO || ' AND PROTECAO_CREDITO_ID IN('||V_CRETIDO_ID||') ';

     V_SQL = :V_SQL || :V_SQL_FILTRO ||'  group by P.DATA_CERTIDAO,
                                          P.N_REMESSA
                                          ORDER BY P.DATA_CERTIDAO ';

    FOR EXECUTE STATEMENT :V_SQL INTO
        :DATA_CERTIDAO, :QTD_CERTIDAO, :QTD_PROTESTOS,
        :QTD_CANCELADOS, :QTD_SUSTADO, :N_REMESSA DO
    begin
        suspend;
    end

    V_DATA_MAX = V_DATA_FINAL;
    V_DATA_MIM = V_DATA_INICIAL;


    V_FIN = V_DATA_MAX - V_DATA_MIM +1;
    V_INI = 0;
    V_DATA_MIM = :V_DATA_MIM;
    while(V_INI < V_FIN ) do
    begin
      V_DIA = null;
      V_SQL =  'select P.DATA_CERTIDAO
                  from P_CERTIDAO P
                  where 1=1
          and P.DATA_CERTIDAO = CAST('''||:V_DATA_MIM||''' as timestamp) +0.0000';

          if (V_CRETIDO_ID <> '') then
          V_SQL = V_SQL || 'and PROTECAO_CREDITO_ID IN('||:V_CRETIDO_ID||') ';
         FOR EXECUTE STATEMENT :V_SQL into V_DIA do
         begin

         end
      --select extract(WEEKDAY from :V_DATA_MIM)
      --from RDB$DATABASE INTO V_DIA;
       if (coalesce(V_DIA,'') = '') then
       begin
          DATA_CERTIDAO = :V_DATA_MIM; QTD_CERTIDAO = 0; QTD_PROTESTOS = 0;
          QTD_CANCELADOS = 0; QTD_SUSTADO = 0; N_REMESSA = 0;
          suspend;
       end

       V_DATA_MIM = :V_DATA_MIM + 1;
       V_INI = :V_INI + 1;

   end
end ^

ALTER PROCEDURE P_PESQUISA_INDICE_LIVRO (ID_LIVRO_PROTESTO NUMERICO)
RETURNS (TITULO_ID NUMERICO,
DATA_ACEITE DATAHORA,
NUMERO_APONTAMENTO NUMERICO,
DATA_APONTAMENTO DATAHORA,
DATA_CADASTRO DATAHORA,
VALOR_TITULO DINHEIRO,
NATUREZA VARCHAR_260,
OCORRENCIA VARCHAR_260,
NUMERO_TITULO VARCHAR_030,
NOSSO_NUMERO VARCHAR_030,
TIPO_ENDOSSO VARCHAR_003,
MOTIVO_APONTAMENTO VARCHAR_260,
VALOR_EMOLUMENTO DINHEIRO,
VALOR_TAXA_INTIMACAO DINHEIRO,
VALOR_TAXA_AVERB DINHEIRO,
VALOR_TAXA_FUNDESP DINHEIRO,
VALOR_ISS DINHEIRO,
VALOR_TAXA_JUDICIARIA DINHEIRO,
VALOR_TAXA_EDITAL DINHEIRO,
VALOR_TAXA_CORREIOS DINHEIRO,
VALOR_TAXA_JUROS DINHEIRO,
NUMERO_PROTESTO NUMERICO,
VALOR_CUSTAS DINHEIRO,
VALOR_TOTAL DINHEIRO,
DATA_SUSTADO DATAHORA,
MOTIVO_CANCELAMENTO VARCHAR_260,
DATA_PROTESTO DATAHORA,
LIVRO_PROTESTO NUMERICO,
FOLHA_PROTESTO NUMERICO,
LETRA_FOLHA VARCHAR_003,
OBSERVACOES VARCHAR_260,
CREDOR VARCHAR_260,
VALOR_RECIBO DINHEIRO,
ESPECIE VARCHAR_010,
CEDENTE_NOME VARCHAR_260,
CPFCNPJ_CEDENTE VARCHAR_030,
NUM_LV_APONTAMENTO VARCHAR_015,
FOLHA_APONTAMENTO VARCHAR_015,
NUMERO_LIVRO_APONT VARCHAR_015,
CPFCNPJ_APRESENTANTE VARCHAR_030,
DATA_CANCELAMENTO DATAHORA,
VALOR_TOTAL_PROTESTO DINHEIRO,
VALOR_TOTAL_CUSTAS DINHEIRO,
DEVEDOR_NOME VARCHAR_260,
CPFCNPJ_DEVEDOR VARCHAR_030,
APRESENTANTE_NOME VARCHAR_260,
CREDOR_NOME VARCHAR_260,
CPFCNPJ_CREDOR VARCHAR_030,
STATUS_IMPORTACAO VARCHAR_003)
AS 
BEGIN
  for select distinct T.TITULO_ID,
                T.DATA_ACEITE,
                T.NUMERO_APONTAMENTO,
                T.DATA_APONTAMENTO,
                T.DATA_CADASTRO,
                T.VALOR_TITULO,
                case
                  when coalesce(E.ESPECIE, '') = '' then E.DESCRICAO
                  when coalesce(E.ESPECIE, '') <> '' then E.ESPECIE || '-' || E.DESCRICAO
                end as NATUREZA,
                O.DESCRICAO as OCORRENCIA,
                T.NUMERO_TITULO,
                T.NOSSO_NUMERO,
                T.TIPO_ENDOSSO,
                M.DESCRICAO as MOTIVO_APONTAMENTO,
                T.VALOR_EMOLUMENTO,
                T.VALOR_TAXA_INTIMACAO,
                T.VALOR_TAXA_AVERB,
                T.VALOR_TAXA_FUNDESP,
                T.VALOR_ISS,
                T.VALOR_TAXA_JUDICIARIA,
                T.VALOR_TAXA_EDITAL,
                T.VALOR_TAXA_CORREIOS,
                T.VALOR_TAXA_JUROS,
                T.NUMERO_PROTESTO,
                coalesce(T.VALOR_TOTAL_CUSTAS,
                (coalesce(T.VALOR_EMOLUMENTO, 0) +
                coalesce(T.VALOR_TAXA_INTIMACAO, 0) +
                coalesce(T.VALOR_TAXA_AVERB, 0) +
                coalesce(T.VALOR_TAXA_FUNDESP, 0) +
                coalesce(T.VALOR_TAXA_JUDICIARIA, 0) +
                coalesce(T.VALOR_TAXA_EDITAL, 0) +
                coalesce(T.VALOR_TAXA_CORREIOS, 0) +
                coalesce(T.VALOR_TAXA_JUROS, 0))) as VALOR_CUSTAS,

                (T.VALOR_TITULO +
                coalesce(T.VALOR_TOTAL_CUSTAS,
                coalesce(T.VALOR_EMOLUMENTO, 0) +
                coalesce(T.VALOR_TAXA_INTIMACAO, 0) +
                coalesce(T.VALOR_TAXA_AVERB, 0) +
                coalesce(T.VALOR_TAXA_FUNDESP, 0) +
                coalesce(T.VALOR_TAXA_JUDICIARIA, 0) +
                coalesce(T.VALOR_TAXA_EDITAL, 0) +
                coalesce(T.VALOR_TAXA_CORREIOS, 0) +
                coalesce(T.VALOR_TAXA_JUROS, 0)) - T.VALOR_DESCONTO) as VALOR_TOTAL,
                T.DATA_SUSTADO,
                C.DESCRICAO as MOTIVO_CANCELAMENTO,
                T.DATA_PROTESTO,
                L.NUMERO_LIVRO LIVRO_PROTESTO,
                T.FOLHA_PROTESTO,
                T.LETRA_FOLHA,
                T.OBSERVACOES,
                PC.NOME as CREDOR,

                (coalesce(T.VALOR_EMOLUMENTO, 0) +
                coalesce(T.VALOR_TAXA_INTIMACAO, 0) +
                coalesce(T.VALOR_TAXA_CANCEL, 0) +
                ((coalesce(T.VALOR_EMOLUMENTO, 0) +
                coalesce(T.VALOR_TAXA_INTIMACAO, 0)) * 39 / 100) +
                coalesce(T.VALOR_TAXA_JUDICIARIA, 0) +
                coalesce(T.VALOR_TAXA_EDITAL, 0) +
                coalesce(T.VALOR_TAXA_CORREIOS, 0) +
                coalesce(T.VALOR_TAXA_JUROS, 0)) - T.VALOR_DESCONTO as VALOR_RECIBO,

                E.ESPECIE,
                PE.NOME as CEDENTE_NOME,
                PE.CPFCNPJ as CPFCNPJ_CEDENTE,
                LA.NUMERO_LIVRO as NUM_LV_APONTAMENTO,
                T.FOLHA_APONTAMENTO,
                T.NUMERO_LIVRO_APONT,
                PA.CPFCNPJ as CPFCNPJ_APRESENTANTE,
                T.DATA_CANCELAMENTO,
                T.VALOR_TOTAL as VALOR_TOTAL_PROTESTO,
                T.VALOR_TOTAL_CUSTAS,
                PD.nome DEVEDOR_NOME,
                PD.cpfcnpj CPFCNPJ_DEVEDOR,
                PA.nome APRESENTANTE_NOME,
                PC.nome CREDOR_NOME,
                PC.cpfcnpj CPFCNPJ_CREDOR,
                T.STATUS_IMPORTACAO
  from P_TITULO T
  left join P_ESPECIE E on E.ESPECIE_ID = T.ESPECIE_ID
  left join P_OCORRENCIAS O on O.OCORRENCIAS_ID = T.OCORRENCIA_ID
  left join P_MOTIVOS M on M.MOTIVOS_ID = T.MOTIVO_APONTAMENTO_ID
  left join P_MOTIVOS_CANCELAMENTO C on C.MOTIVOS_CANCELAMENTO_ID = T.MOTIVO_CANCELAMENTO
  left join P_PESSOA_VINCULO PA on PA.TITULO_ID = T.TITULO_ID and PA.TIPO_VINCULO = 'APRESENTANTE'
  left join P_PESSOA_VINCULO PC on PC.TITULO_ID = T.TITULO_ID and PC.TIPO_VINCULO = 'CREDOR'
  left join P_PESSOA_VINCULO PD on PD.TITULO_ID = T.TITULO_ID and PD.TIPO_VINCULO = 'DEVEDOR'
  left join P_PESSOA_VINCULO PE on PE.TITULO_ID = T.TITULO_ID and PE.TIPO_VINCULO = 'CEDENTE'
  left join P_LIVRO_ANDAMENTO L on L.LIVRO_ANDAMENTO_ID = T.LIVRO_ID_PROTESTO
  left join P_LIVRO_ANDAMENTO LA on LA.LIVRO_ANDAMENTO_ID = T.LIVRO_ID_APONTAMENTO
  left join G_USUARIO U on U.USUARIO_ID = T.USER_ASSINA_PROT
  left join P_PESSOA PPD on PPD.PESSOA_ID = PD.PESSOA_ID
  where t.LIVRO_ID_PROTESTO = :id_livro_protesto
  INTO :TITULO_ID,:DATA_ACEITE,:NUMERO_APONTAMENTO,:DATA_APONTAMENTO,:DATA_CADASTRO,:VALOR_TITULO,:NATUREZA,
       :OCORRENCIA,:NUMERO_TITULO,:NOSSO_NUMERO,:TIPO_ENDOSSO,:MOTIVO_APONTAMENTO,:VALOR_EMOLUMENTO,:VALOR_TAXA_INTIMACAO ,
       :VALOR_TAXA_AVERB,:VALOR_TAXA_FUNDESP ,:VALOR_ISS,:VALOR_TAXA_JUDICIARIA ,:VALOR_TAXA_EDITAL ,:VALOR_TAXA_CORREIOS,
       :VALOR_TAXA_JUROS, :NUMERO_PROTESTO, :VALOR_CUSTAS,:VALOR_TOTAL ,:DATA_SUSTADO,:MOTIVO_CANCELAMENTO,:DATA_PROTESTO,:LIVRO_PROTESTO,
       :FOLHA_PROTESTO, :LETRA_FOLHA,:OBSERVACOES,:CREDOR,:VALOR_RECIBO,:ESPECIE,:CEDENTE_NOME,:CPFCNPJ_CEDENTE,:NUM_LV_APONTAMENTO ,
       :FOLHA_APONTAMENTO,:NUMERO_LIVRO_APONT,:CPFCNPJ_APRESENTANTE,:DATA_CANCELAMENTO,:VALOR_TOTAL_PROTESTO,:VALOR_TOTAL_CUSTAS,
       :DEVEDOR_NOME,:CPFCNPJ_DEVEDOR,:APRESENTANTE_NOME,:CREDOR_NOME,:CPFCNPJ_CREDOR,:STATUS_IMPORTACAO do
  begin
  SUSPEND;
  end
END ^

ALTER PROCEDURE P_PESQUISA_PROTOCOLO (V_NUMERO_APONTAMENTO_INI VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_APONTAMENTO_FIN VARCHAR(10) CHARACTER SET ISO8859_1,
V_DATA_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_N_IMPRIME_TITULO VARCHAR(1) CHARACTER SET ISO8859_1)
RETURNS (TITULO_ID NUMERICO,
ESPECIE VARCHAR(3) CHARACTER SET ISO8859_1,
PROTOCOLO NUMERIC(18, 2),
DATA_APONTAMENTO TIMESTAMP,
APRESENTANTE VARCHAR(120) CHARACTER SET ISO8859_1,
VALOR_TITULO NUMERICO,
VALOR_EMOLUMENTO NUMERIC(18, 2),
NATUREZA VARCHAR(260) CHARACTER SET ISO8859_1,
ESPECIE_ID NUMERICO,
NUMERO_LIVRO NUMERIC(18, 2),
NUMERO_LIVRO_APONT VARCHAR(15) CHARACTER SET ISO8859_1,
NOSSO_NUMERO VARCHAR(30) CHARACTER SET ISO8859_1,
TIPO_ENDOSSO VARCHAR(1) CHARACTER SET ISO8859_1,
LIVRO VARCHAR(30) CHARACTER SET ISO8859_1,
FOLHA_APONTAMENTO NUMERICO,
DEVEDOR VARCHAR(120) CHARACTER SET ISO8859_1,
OCORRENCIA VARCHAR(260) CHARACTER SET ISO8859_1,
DATA_ACEITE TIMESTAMP,
DATA_DESISTENCIA TIMESTAMP,
DATA_PAGO TIMESTAMP,
DATA_PROTESTO TIMESTAMP,
DATA_CANCELAMENTO TIMESTAMP,
CREDOR VARCHAR(120) CHARACTER SET ISO8859_1,
CPFCNPJ_CREDOR VARCHAR(15) CHARACTER SET ISO8859_1,
CPFCNPJ_DEVEDOR VARCHAR(15) CHARACTER SET ISO8859_1,
DATA_EMISSAO_TITULO TIMESTAMP,
DATA_VENCIMENTO_TITULO TIMESTAMP,
FOLHA_PROTESTO NUMERIC(18, 2),
NUMERO_PROTESTO NUMERICO,
CEDENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
CPFCNPJ_CEDENTE VARCHAR(15) CHARACTER SET ISO8859_1,
CIDADE_AGENCIA VARCHAR(30) CHARACTER SET ISO8859_1,
NUMERO_TITULO VARCHAR(30) CHARACTER SET ISO8859_1,
VALOR_TOTAL_CUSTAS NUMERICO,
VALOR_TOTAL NUMERICO,
VALOR_TAXA_JUROS NUMERICO,
VALOR_TAXA_JUDICIARIA NUMERICO,
VALOR_TAXA_INTIMACAO NUMERICO,
VALOR_TAXA_FUNDESP NUMERICO,
VALOR_TAXA_EDITAL NUMERICO,
VALOR_TAXA_CORREIOS NUMERICO,
VALOR_TAXA_CANCEL NUMERICO,
VALOR_TAXA_AVERB NUMERICO,
VALOR_ISS NUMERICO,
VALOR_DESCONTO NUMERICO,
STATUS_IMPORTACAO VARCHAR_001)
AS 
declare variable V_SQL varchar(10000);
declare variable V_SQL_FILTRO varchar(5000);
declare variable V_DATA_TEMP timestamp;
declare variable V_DATA_MAX timestamp;
declare variable V_DATA_MIM timestamp;
declare variable V_INI integer;
declare variable V_FIN integer;
declare variable V_DIA_APONTAMENTO integer;
declare variable SIM_NAO varchar(2);
declare variable V_FERIADO integer;
declare variable V_DATA_EXISTE timestamp;
declare variable V_IMPRIME_T_DIAS VARCHAR_001;
declare variable V_IMPRIME_APENAS_EXISTENTES VARCHAR_001;
begin

SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PROTOCOLO', 'PROTOCOLO_SINTETICO', 'IMPRIME_T_DIAS', 13)
    INTO :V_IMPRIME_T_DIAS;

SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PROTOCOLO', 'PROTOCOLO_SINTETICO', 'IMPRIME_APENAS_EXISTENTES',13)
    INTO :V_IMPRIME_APENAS_EXISTENTES;


V_SQL        = ' ';
V_SQL_FILTRO = ' ';
    V_SQL = ' SELECT T.TITULO_ID,
                     E.Especie,
                     T.NUMERO_APONTAMENTO AS PROTOCOLO,
                     T.DATA_APONTAMENTO,
                     A.NOME AS APRESENTANTE,
                     T.VALOR_TITULO,
                     T.VALOR_EMOLUMENTO,
                     E.DESCRICAO AS NATUREZA,
                     T.ESPECIE_ID,
                     L.NUMERO_LIVRO,
                     T.NUMERO_LIVRO_APONT,
                     T.NOSSO_NUMERO,
                     T.TIPO_ENDOSSO,
                     N.DESCRICAO AS LIVRO,
                     T.FOLHA_APONTAMENTO,
                     PD.NOME AS DEVEDOR,
                     O.DESCRICAO AS OCORRENCIA,
                     T.DATA_ACEITE,
                     T.DATA_DESISTENCIA,
                     T.DATA_PAGO,
                     T.DATA_PROTESTO,
                     T.DATA_CANCELAMENTO,
                     PC.NOME AS CREDOR,
                     PC.CPFCNPJ AS CPFCNPJ_CREDOR,
                     PD.CPFCNPJ AS CPFCNPJ_DEVEDOR,
                     T.DATA_EMISSAO_TITULO,
                     T.DATA_VENCIMENTO_TITULO,
                     T.FOLHA_PROTESTO,
                     T.NUMERO_PROTESTO,
                     PE.NOME AS CEDENTE_NOME,
                     PE.CPFCNPJ AS CPFCNPJ_CEDENTE,
                     A.CIDADE_AGENCIA,
                     T.NUMERO_TITULO,
                     T.VALOR_TOTAL_CUSTAS,
                     T.VALOR_TOTAL,
                     T.VALOR_TAXA_JUROS,
                     T.VALOR_TAXA_JUDICIARIA,
                     T.VALOR_TAXA_INTIMACAO,
                     T.VALOR_TAXA_FUNDESP,
                     T.VALOR_TAXA_EDITAL,
                     T.VALOR_TAXA_CORREIOS,
                     T.VALOR_TAXA_CANCEL,
                     T.VALOR_TAXA_AVERB,
                     T.VALOR_ISS,
                     T.VALOR_DESCONTO,
                     T.VALOR_EMOLUMENTO,
                     T.STATUS_IMPORTACAO
                     FROM P_TITULO T
                     LEFT JOIN P_PESSOA_VINCULO  A ON A.TITULO_ID          = T.TITULO_ID AND A.TIPO_VINCULO = ''APRESENTANTE''
                     LEFT JOIN P_OCORRENCIAS     O ON O.OCORRENCIAS_ID     = T.OCORRENCIA_ID
                     LEFT JOIN P_PESSOA_VINCULO PC ON PC.TITULO_ID         = T.TITULO_ID AND PC.TIPO_VINCULO = ''CREDOR''
                     LEFT JOIN P_PESSOA_VINCULO  PD ON PD.TITULO_ID        = T.TITULO_ID AND PD.TIPO_VINCULO = ''DEVEDOR''
                     AND PD.PESSOA_ID IN (SELECT FIRST 1(PESSOA_ID)
                                          FROM   P_PESSOA_VINCULO
                                          WHERE TITULO_ID = T.TITULO_ID
                                          AND TIPO_VINCULO = ''DEVEDOR'' )
                     LEFT JOIN P_PESSOA_VINCULO  PE ON PE.TITULO_ID        = T.TITULO_ID AND PE.TIPO_VINCULO = ''CEDENTE''
                     LEFT JOIN P_ESPECIE         E ON E.ESPECIE_ID         = T.ESPECIE_ID
                     LEFT JOIN P_LIVRO_ANDAMENTO L ON L.LIVRO_ANDAMENTO_ID = T.LIVRO_ID_APONTAMENTO
                     LEFT JOIN P_LIVRO_NATUREZA  N ON N.LIVRO_NATUREZA_ID  = (SELECT LIVRO_NATUREZA_ID
                                                                               FROM P_LIVRO_ANDAMENTO
                                                                              WHERE LIVRO_ANDAMENTO_ID = T.LIVRO_ID_APONTAMENTO)
                     WHERE 1=1 ';

        --se protocolo estifer marcado
        if ((COALESCE(:V_NUMERO_APONTAMENTO_INI,'') <> '') and (COALESCE(:V_NUMERO_APONTAMENTO_FIN,'') <> '')) then
        begin
          V_SQL_FILTRO = :V_SQL_FILTRO || ' AND T.NUMERO_APONTAMENTO IS NOT NULL
                              AND T.NUMERO_APONTAMENTO BETWEEN '''||:V_NUMERO_APONTAMENTO_INI|| '''
                              AND  ' ||:V_NUMERO_APONTAMENTO_FIN||'  ';
        end
        -- se periodo estiver marcado
        if ((COALESCE(:V_DATA_INICIAL,'') <> '') and (COALESCE(:V_DATA_FINAL,'') <> '')) then
        begin
          V_SQL_FILTRO = :V_SQL_FILTRO || ' AND T.DATA_APONTAMENTO BETWEEN CAST(''' ||:V_DATA_INICIAL|| '''  AS TIMESTAMP )
                              AND CAST(  ''' ||:V_DATA_FINAL|| ''' AS TIMESTAMP) + 0.9999 ';
        end

        if (V_N_IMPRIME_TITULO = 'N') then
        begin
           V_SQL_FILTRO = :V_SQL_FILTRO || '  AND (T.DATA_PAGO         IS NOT NULL
                                 OR  T.DATA_DESISTENCIA  IS NOT NULL
                                 OR  T.DATA_PROTESTO     IS NOT NULL
                                 OR  T.DATA_CANCELAMENTO IS NOT NULL
                                 OR  T.DATA_SUSTADO      IS NOT NULL) ';
        end

            V_SQL = :V_SQL || :V_SQL_FILTRO ||' ORDER BY T.DATA_APONTAMENTO, T.NUMERO_APONTAMENTO, T.NUMERO_LIVRO_APONT, T.FOLHA_APONTAMENTO ';

    FOR EXECUTE STATEMENT :V_SQL INTO
        :TITULO_ID, :ESPECIE, :PROTOCOLO, :DATA_APONTAMENTO, :APRESENTANTE,
        :VALOR_TITULO, :VALOR_EMOLUMENTO, :NATUREZA, :ESPECIE_ID, :NUMERO_LIVRO,
        :NUMERO_LIVRO_APONT, :NOSSO_NUMERO, :TIPO_ENDOSSO, :LIVRO, :FOLHA_APONTAMENTO,
        :DEVEDOR, :OCORRENCIA, :DATA_ACEITE, :DATA_DESISTENCIA, :DATA_PAGO, :DATA_PROTESTO,
        :DATA_CANCELAMENTO, :CREDOR, :CPFCNPJ_CREDOR, CPFCNPJ_DEVEDOR, :DATA_EMISSAO_TITULO,
        :DATA_VENCIMENTO_TITULO, :FOLHA_PROTESTO, :NUMERO_PROTESTO, :CEDENTE_NOME,
        :CPFCNPJ_CEDENTE, :CIDADE_AGENCIA, :NUMERO_TITULO, :VALOR_TOTAL_CUSTAS, :VALOR_TOTAL,
        :VALOR_TAXA_JUROS, :VALOR_TAXA_JUDICIARIA, :VALOR_TAXA_INTIMACAO, :VALOR_TAXA_FUNDESP,
        :VALOR_TAXA_EDITAL, :VALOR_TAXA_CORREIOS, :VALOR_TAXA_CANCEL, :VALOR_TAXA_AVERB,
        :VALOR_ISS, :VALOR_DESCONTO, :valor_emolumento, :STATUS_IMPORTACAO DO
    begin
        suspend;
    end

    if (COALESCE(V_IMPRIME_APENAS_EXISTENTES, 'N') = 'N') then
    begin
        if ((COALESCE(:V_DATA_INICIAL,'') <> '') and (COALESCE(:V_DATA_FINAL,'') <> '')) then
        begin
            V_DATA_MAX = V_DATA_FINAL;
            V_DATA_MIM = V_DATA_INICIAL;
        end
        else
        begin
             V_SQL = ' SELECT max(T.DATA_APONTAMENTO)
             FROM P_TITULO T
             LEFT JOIN P_PESSOA_VINCULO  A ON A.TITULO_ID          = T.TITULO_ID AND A.TIPO_VINCULO = ''APRESENTANTE''
             LEFT JOIN P_OCORRENCIAS     O ON O.OCORRENCIAS_ID     = T.OCORRENCIA_ID
             LEFT JOIN P_PESSOA_VINCULO PC ON PC.TITULO_ID         = T.TITULO_ID AND PC.TIPO_VINCULO = ''CREDOR''
             LEFT JOIN P_PESSOA_VINCULO  PD ON PD.TITULO_ID        = T.TITULO_ID AND PD.TIPO_VINCULO = ''DEVEDOR''
             AND PD.PESSOA_ID IN (SELECT FIRST 1(PESSOA_ID)
                                  FROM   P_PESSOA_VINCULO
                                  WHERE TITULO_ID = T.TITULO_ID
                                  AND TIPO_VINCULO = ''DEVEDOR'' )
             LEFT JOIN P_PESSOA_VINCULO  PE ON PE.TITULO_ID        = T.TITULO_ID AND PE.TIPO_VINCULO = ''CEDENTE''
             LEFT JOIN P_ESPECIE         E ON E.ESPECIE_ID         = T.ESPECIE_ID
             LEFT JOIN P_LIVRO_ANDAMENTO L ON L.LIVRO_ANDAMENTO_ID = T.LIVRO_ID_APONTAMENTO
             LEFT JOIN P_LIVRO_NATUREZA  N ON N.LIVRO_NATUREZA_ID  = (SELECT LIVRO_NATUREZA_ID
                                                                       FROM P_LIVRO_ANDAMENTO
                                                                      WHERE LIVRO_ANDAMENTO_ID = T.LIVRO_ID_APONTAMENTO)
             WHERE 1=1 ' || V_SQL_FILTRO;
        
             EXECUTE STATEMENT V_SQL INTO V_DATA_MAX;
             --SUSPEND;
        
             V_SQL = 'SELECT MIN(DATA_APONTAMENTO)
             FROM P_TITULO T
             LEFT JOIN P_PESSOA_VINCULO  A ON A.TITULO_ID          = T.TITULO_ID AND A.TIPO_VINCULO = ''APRESENTANTE''
             LEFT JOIN P_OCORRENCIAS     O ON O.OCORRENCIAS_ID     = T.OCORRENCIA_ID
             LEFT JOIN P_PESSOA_VINCULO PC ON PC.TITULO_ID         = T.TITULO_ID AND PC.TIPO_VINCULO = ''CREDOR''
             LEFT JOIN P_PESSOA_VINCULO  PD ON PD.TITULO_ID        = T.TITULO_ID AND PD.TIPO_VINCULO = ''DEVEDOR''
             AND PD.PESSOA_ID IN (SELECT FIRST 1(PESSOA_ID)
                                  FROM   P_PESSOA_VINCULO
                                  WHERE TITULO_ID = T.TITULO_ID
                                  AND TIPO_VINCULO = ''DEVEDOR'' )
             LEFT JOIN P_PESSOA_VINCULO  PE ON PE.TITULO_ID        = T.TITULO_ID AND PE.TIPO_VINCULO = ''CEDENTE''
             LEFT JOIN P_ESPECIE         E ON E.ESPECIE_ID         = T.ESPECIE_ID
             LEFT JOIN P_LIVRO_ANDAMENTO L ON L.LIVRO_ANDAMENTO_ID = T.LIVRO_ID_APONTAMENTO
             LEFT JOIN P_LIVRO_NATUREZA  N ON N.LIVRO_NATUREZA_ID  = (SELECT LIVRO_NATUREZA_ID
                                                                       FROM P_LIVRO_ANDAMENTO
                                                                      WHERE LIVRO_ANDAMENTO_ID = T.LIVRO_ID_APONTAMENTO)
             WHERE 1=1 ' || V_SQL_FILTRO;
        
             EXECUTE STATEMENT V_SQL INTO V_DATA_MIM;
    
        end
    
         V_FIN = V_DATA_MAX - V_DATA_MIM +1 ;-- -1
         V_INI = 0;
         V_DATA_MIM = :V_DATA_MIM ; -- + 1
         while(V_INI < V_FIN ) do
         begin
            if (coalesce(V_IMPRIME_T_DIAS, 'N') = 'S') then
            begin
                
                V_DATA_EXISTE = null;

                SELECT first 1 T.DATA_APONTAMENTO
                FROM P_TITULO T
                LEFT JOIN P_PESSOA_VINCULO  A ON A.TITULO_ID          = T.TITULO_ID AND A.TIPO_VINCULO = 'APRESENTANTE'
                LEFT JOIN P_OCORRENCIAS     O ON O.OCORRENCIAS_ID     = T.OCORRENCIA_ID
                LEFT JOIN P_PESSOA_VINCULO PC ON PC.TITULO_ID         = T.TITULO_ID AND PC.TIPO_VINCULO = 'CREDOR'
                LEFT JOIN P_PESSOA_VINCULO  PD ON PD.TITULO_ID        = T.TITULO_ID AND PD.TIPO_VINCULO = 'DEVEDOR'
                AND PD.PESSOA_ID IN (SELECT FIRST 1(PESSOA_ID)
                              FROM   P_PESSOA_VINCULO
                              WHERE TITULO_ID = T.TITULO_ID
                              AND TIPO_VINCULO = 'DEVEDOR' )
                LEFT JOIN P_PESSOA_VINCULO  PE ON PE.TITULO_ID        = T.TITULO_ID AND PE.TIPO_VINCULO = 'CEDENTE'
                LEFT JOIN P_ESPECIE         E ON E.ESPECIE_ID         = T.ESPECIE_ID
                LEFT JOIN P_LIVRO_ANDAMENTO L ON L.LIVRO_ANDAMENTO_ID = T.LIVRO_ID_APONTAMENTO
                LEFT JOIN P_LIVRO_NATUREZA  N ON N.LIVRO_NATUREZA_ID  = (SELECT LIVRO_NATUREZA_ID
                                                                   FROM P_LIVRO_ANDAMENTO
                                                                  WHERE LIVRO_ANDAMENTO_ID = T.LIVRO_ID_APONTAMENTO)

                where CAST(CAST(T.DATA_APONTAMENTO AS DATE) AS TIMESTAMP) = :V_DATA_MIM
                into :V_DATA_EXISTE;

                if (coalesce(V_DATA_EXISTE, '') = '' ) then
                begin
                    TITULO_ID = -1; ESPECIE = null; PROTOCOLO = null; DATA_APONTAMENTO = V_DATA_MIM; APRESENTANTE = null;
                    VALOR_TITULO = null; VALOR_EMOLUMENTO = null; NATUREZA = null; ESPECIE_ID = null; NUMERO_LIVRO = null;
                    NUMERO_LIVRO_APONT = null; NOSSO_NUMERO = null; TIPO_ENDOSSO = null; LIVRO = null; FOLHA_APONTAMENTO = null;
                    DEVEDOR = null; OCORRENCIA = null; DATA_ACEITE = null; DATA_DESISTENCIA = null; DATA_PAGO = null;
                    DATA_PROTESTO = null; DATA_CANCELAMENTO = null; CREDOR = null; CPFCNPJ_CREDOR = null; CPFCNPJ_DEVEDOR = null;
                    DATA_EMISSAO_TITULO = null; DATA_VENCIMENTO_TITULO = null; FOLHA_PROTESTO = null; NUMERO_PROTESTO = null;
                    CEDENTE_NOME = null; CPFCNPJ_CEDENTE = null; CIDADE_AGENCIA = null; NUMERO_TITULO = null; VALOR_TOTAL_CUSTAS = null;
                    VALOR_TOTAL = null; VALOR_TAXA_JUROS = null; VALOR_TAXA_JUDICIARIA = null; VALOR_TAXA_INTIMACAO = null;
                    VALOR_TAXA_FUNDESP = null; VALOR_TAXA_EDITAL = null; VALOR_TAXA_CORREIOS = null; VALOR_TAXA_CANCEL = null;
                    VALOR_TAXA_AVERB = null; VALOR_ISS = null; VALOR_DESCONTO = null; VALOR_EMOLUMENTO = null; STATUS_IMPORTACAO = null;

                    SUSPEND;
                end
            end
            else
            begin
                select extract(WEEKDAY from :V_DATA_MIM)
                from RDB$DATABASE INTO V_DIA_APONTAMENTO;
        
        
                if ((V_DIA_APONTAMENTO <> 0) AND (V_DIA_APONTAMENTO <> 6)) then
                begin
        
                      SELECT FIRST 1 FERIADO_ID FROM G_FERIADO
                      WHERE SITUACAO = 'A'
                      AND DATA BETWEEN CAST(:V_DATA_MIM AS TIMESTAMP) AND CAST(:V_DATA_MIM AS TIMESTAMP) + 0.9999
                      INTO :V_FERIADO;
                      IF (:V_FERIADO > 0) THEN
                      BEGIN
                        SIM_NAO = 'S';
                      END
                      ELSE
                      BEGIN
                        SIM_NAO = 'N';
                      END
                    --suspend;
        
                    if (SIM_NAO = 'N') then
                    begin
                        V_DATA_EXISTE = null;
        
                        SELECT first 1 T.DATA_APONTAMENTO
                        FROM P_TITULO T
                        LEFT JOIN P_PESSOA_VINCULO  A ON A.TITULO_ID          = T.TITULO_ID AND A.TIPO_VINCULO = 'APRESENTANTE'
                        LEFT JOIN P_OCORRENCIAS     O ON O.OCORRENCIAS_ID     = T.OCORRENCIA_ID
                        LEFT JOIN P_PESSOA_VINCULO PC ON PC.TITULO_ID         = T.TITULO_ID AND PC.TIPO_VINCULO = 'CREDOR'
                        LEFT JOIN P_PESSOA_VINCULO  PD ON PD.TITULO_ID        = T.TITULO_ID AND PD.TIPO_VINCULO = 'DEVEDOR'
                        AND PD.PESSOA_ID IN (SELECT FIRST 1(PESSOA_ID)
                                      FROM   P_PESSOA_VINCULO
                                      WHERE TITULO_ID = T.TITULO_ID
                                      AND TIPO_VINCULO = 'DEVEDOR' )
                        LEFT JOIN P_PESSOA_VINCULO  PE ON PE.TITULO_ID        = T.TITULO_ID AND PE.TIPO_VINCULO = 'CEDENTE'
                        LEFT JOIN P_ESPECIE         E ON E.ESPECIE_ID         = T.ESPECIE_ID
                        LEFT JOIN P_LIVRO_ANDAMENTO L ON L.LIVRO_ANDAMENTO_ID = T.LIVRO_ID_APONTAMENTO
                        LEFT JOIN P_LIVRO_NATUREZA  N ON N.LIVRO_NATUREZA_ID  = (SELECT LIVRO_NATUREZA_ID
                                                                           FROM P_LIVRO_ANDAMENTO
                                                                          WHERE LIVRO_ANDAMENTO_ID = T.LIVRO_ID_APONTAMENTO)
        
                        where CAST(CAST(T.DATA_APONTAMENTO AS DATE) AS TIMESTAMP) = :V_DATA_MIM
                        into :V_DATA_EXISTE;
        
                        if (coalesce(V_DATA_EXISTE, '') = '' ) then
                        begin
                            TITULO_ID = -1; ESPECIE = null; PROTOCOLO = null; DATA_APONTAMENTO = V_DATA_MIM; APRESENTANTE = null;
                            VALOR_TITULO = null; VALOR_EMOLUMENTO = null; NATUREZA = null; ESPECIE_ID = null; NUMERO_LIVRO = null;
                            NUMERO_LIVRO_APONT = null; NOSSO_NUMERO = null; TIPO_ENDOSSO = null; LIVRO = null; FOLHA_APONTAMENTO = null;
                            DEVEDOR = null; OCORRENCIA = null; DATA_ACEITE = null; DATA_DESISTENCIA = null; DATA_PAGO = null;
                            DATA_PROTESTO = null; DATA_CANCELAMENTO = null; CREDOR = null; CPFCNPJ_CREDOR = null; CPFCNPJ_DEVEDOR = null;
                            DATA_EMISSAO_TITULO = null; DATA_VENCIMENTO_TITULO = null; FOLHA_PROTESTO = null; NUMERO_PROTESTO = null;
                            CEDENTE_NOME = null; CPFCNPJ_CEDENTE = null; CIDADE_AGENCIA = null; NUMERO_TITULO = null; VALOR_TOTAL_CUSTAS = null;
                            VALOR_TOTAL = null; VALOR_TAXA_JUROS = null; VALOR_TAXA_JUDICIARIA = null; VALOR_TAXA_INTIMACAO = null;
                            VALOR_TAXA_FUNDESP = null; VALOR_TAXA_EDITAL = null; VALOR_TAXA_CORREIOS = null; VALOR_TAXA_CANCEL = null;
                            VALOR_TAXA_AVERB = null; VALOR_ISS = null; VALOR_DESCONTO = null; VALOR_EMOLUMENTO = null; STATUS_IMPORTACAO = null;
        
                            SUSPEND;
                        end
                    end
                end
            end
            V_DATA_MIM = :V_DATA_MIM + 1;
            V_INI = :V_INI + 1;
        end
    end
end ^

ALTER PROCEDURE P_PR_SEQUENCIA_CENPROT RETURNS (CENPROT_ID NUMERICO)
AS 
declare variable V_DATA_TABELA timestamp;
declare variable V_DATA_ATUAL timestamp;
declare variable ID_AUX NUMERICO;
begin
    select first 1 DATA
      from P_SEQUENCIA_CENPROT
      INTO :V_DATA_TABELA;

    if (V_DATA_TABELA is not null) then
    begin
        select cast(CURRENT_TIMESTAMP as date) FROM RDB$DATABASE
        INTO :V_DATA_ATUAL;
    
        if (V_DATA_TABELA < V_DATA_ATUAL) then
        begin
            update P_SEQUENCIA_CENPROT
               set data = cast(:V_DATA_ATUAL as timestamp)
                   ,SEQUENCIA_CENPROT_ID = 1;
    
            CENPROT_ID = 1;
        end
        else
        begin
            SELECT SEQUENCIA_CENPROT_ID FROM P_SEQUENCIA_CENPROT
            INTO :id_aux;
    
            update P_SEQUENCIA_CENPROT
               set SEQUENCIA_CENPROT_ID = :id_aux+1;
    
              CENPROT_ID = :id_aux+1;
        end
    end
    else
    begin
       INSERT INTO P_SEQUENCIA_CENPROT (SEQUENCIA_CENPROT_ID, DATA)
                         VALUES (1,(select CURRENT_TIMESTAMP FROM RDB$DATABASE));
       CENPROT_ID = 1;
    end

    suspend;
end ^

ALTER PROCEDURE P_SERASA_TITULO (V_SEL VARCHAR(1) CHARACTER SET ISO8859_1,
V_TIPO VARCHAR(1) CHARACTER SET ISO8859_1,
V_DATA_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_ESPECIE INTEGER,
V_NUMERO_APONTAMENTO_INI VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_APONTAMENTO_FIN VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_TITULO VARCHAR(30) CHARACTER SET ISO8859_1,
V_CPFCNPJ VARCHAR(14) CHARACTER SET ISO8859_1,
V_VINCULO INTEGER,
V_ULTIMA_DATA VARCHAR(20) CHARACTER SET ISO8859_1,
V_GERAR_NOVAMENTE INTEGER)
RETURNS (SEL VARCHAR(1) CHARACTER SET ISO8859_1,
TITULO_ID NUMERICO,
NUMERO_APONTAMENTO NUMERIC(18, 2),
DATA_APONTAMENTO DATE,
DATA_CADASTRO DATE,
VALOR_TITULO NUMERIC(18, 2),
VALOR_TOTAL NUMERIC(18, 2),
DATA_ACEITE DATE,
NATUREZA VARCHAR(260) CHARACTER SET ISO8859_1,
OCORRENCIA VARCHAR(260) CHARACTER SET ISO8859_1,
CODIGO_OCORRENCIA VARCHAR(60) CHARACTER SET ISO8859_1,
NUMERO_TITULO VARCHAR(30) CHARACTER SET ISO8859_1,
MOTIVO_APONTAMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
ESPECIE_PROTESTO VARCHAR(3) CHARACTER SET ISO8859_1,
VALOR_EMOLUMENTO NUMERIC(18, 2),
VALOR_TAXA_JUDICIARIA NUMERIC(18, 2),
VALOR_TAXA_INTIMACAO NUMERIC(18, 2),
VALOR_TAXA_EDITAL NUMERIC(18, 2),
VALOR_TAXA_JUROS NUMERIC(18, 2),
VALOR_DESCONTO NUMERIC(18, 2),
VALOR_TAXA_FUNDESP NUMERIC(18, 2),
VALOR_TAXA_CORREIOS NUMERIC(18, 2),
VALOR_TAXA_AVERB NUMERIC(18, 2),
DATA_SUSTADO DATE,
MOTIVO_CANCELAMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
DATA_PROTESTO TIMESTAMP,
NUMERO_LIVRO NUMERIC(18, 2),
FOLHA_PROTESTO NUMERIC(18, 2),
MOTIVO_APONTAMENTO_ID NUMERICO,
PRACA_PAGAMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
TIPO_ENDOSSO VARCHAR(1) CHARACTER SET ISO8859_1,
DEVEDOR_TIPO_ACEITE VARCHAR(1) CHARACTER SET ISO8859_1,
EDITAL_MOTIVO VARCHAR(260) CHARACTER SET ISO8859_1,
APRESENTACAO TIMESTAMP,
APRESENTANTE VARCHAR(120) CHARACTER SET ISO8859_1,
APRESENTANTE_CPFCNPJ VARCHAR(60) CHARACTER SET ISO8859_1,
APRESENTANTE_ID NUMERICO,
CREDOR VARCHAR(120) CHARACTER SET ISO8859_1,
CREDOR_CPFCNPJ VARCHAR(15) CHARACTER SET ISO8859_1,
DEVEDOR VARCHAR(120) CHARACTER SET ISO8859_1,
DEVEDOR_CPFCNPJ VARCHAR(15) CHARACTER SET ISO8859_1,
DEVEDOR_ENDERECO VARCHAR(90) CHARACTER SET ISO8859_1,
DEVEDOR_CEP VARCHAR(15) CHARACTER SET ISO8859_1,
DEVEDOR_CIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
DEVEDOR_BAIRRO VARCHAR(60) CHARACTER SET ISO8859_1,
DEVEDOR_UF VARCHAR(3) CHARACTER SET ISO8859_1,
CEDENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
CEDENTE_CPFCNPJ VARCHAR(60) CHARACTER SET ISO8859_1,
CEDENTE_ENDERECO VARCHAR(90) CHARACTER SET ISO8859_1,
CEDENTE_CEP VARCHAR(15) CHARACTER SET ISO8859_1,
CEDENTE_DIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
CEDENTE_UF VARCHAR(3) CHARACTER SET ISO8859_1,
CEDENTE_BAIRRO VARCHAR(60) CHARACTER SET ISO8859_1,
CREDOR_ENDERECO VARCHAR(90) CHARACTER SET ISO8859_1,
CREDOR_CEP VARCHAR(15) CHARACTER SET ISO8859_1,
CREDOR_DIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
CREDOR_UF VARCHAR(3) CHARACTER SET ISO8859_1,
CREDOR_BAIRRO VARCHAR(60) CHARACTER SET ISO8859_1,
DATA_EMISSAO_TITULO TIMESTAMP,
DATA_VENCIMENTO_TITULO TIMESTAMP,
TIPO_ACEITE VARCHAR(1) CHARACTER SET ISO8859_1,
DATA_ENV_SERASA TIMESTAMP,
DATA_RET_SERASA TIMESTAMP,
DATA_CANCELAMENTO TIMESTAMP,
DATA_PAGO TIMESTAMP,
DATA_DESISTENCIA TIMESTAMP,
DATA_INTIMACAO TIMESTAMP,
LIVRO_NATUREZA_ID NUMERICO,
CODIGO_BANCO VARCHAR(10) CHARACTER SET ISO8859_1,
NOSSO_NUMERO VARCHAR(30) CHARACTER SET ISO8859_1,
DATA_ANUENCIA TIMESTAMP,
ORIGEM_ANUENCIA VARCHAR(3) CHARACTER SET ISO8859_1,
APRESENTANTE_PERMITIDO VARCHAR(1) CHARACTER SET ISO8859_1,
CEDENTE_PERMITIDO VARCHAR(1) CHARACTER SET ISO8859_1,
CREDOR_PERMITIDO VARCHAR(1) CHARACTER SET ISO8859_1,
ANUENCIA VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
declare variable V_SQL varchar(15000);
declare variable V_DATA_TEMP timestamp;
declare variable V_CONTFILTRO integer;
BEGIN
    if (V_TIPO = 'P') then
    begin
        v_ContFiltro = 0;
        V_SQL = ' select ''' ||V_SEL ||''' as SEL,
                     T.TITULO_ID,
                     T.NUMERO_APONTAMENTO,
                     cast(T.DATA_APONTAMENTO as date) as DATA_APONTAMENTO,
                     cast(T.DATA_CADASTRO as date) as DATA_CADASTRO,
                     T.VALOR_TITULO,
                     T.VALOR_TOTAL,
                     cast(T.DATA_ACEITE as date) as DATA_ACEITE,
                     case
                     when (e.especie_id > 39) then ''DV''
                     else E.especie
                     end as NATUREZA,
                     O.DESCRICAO as OCORRENCIA,
                     case O.DESCRICAO
                     when ''1'' then O.CODIGO
                     when ''2'' then O.CODIGO
                     when ''3'' then O.CODIGO
                     when ''4'' then O.CODIGO
                     when ''5'' then O.CODIGO
                     when ''A'' then O.CODIGO
                     when ''X'' then O.CODIGO
                     else ''Y''
                     end as CODIGO_OCORRENCIA,
                     T.NUMERO_TITULO,
                     M.DESCRICAO as MOTIVO_APONTAMENTO,
                     M.CODIGO as ESPECIE_PROTESTO,
                     T.VALOR_EMOLUMENTO,
                     T.VALOR_TAXA_JUDICIARIA,
                     T.VALOR_TAXA_INTIMACAO,
                     T.VALOR_TAXA_EDITAL,
                     T.VALOR_TAXA_JUROS,
                     T.VALOR_DESCONTO,
                     T.VALOR_TAXA_FUNDESP,
                     T.VALOR_TAXA_AVERB,
                     T.VALOR_TAXA_CORREIOS,
                     cast(T.DATA_SUSTADO as date) as DATA_SUSTADO,
                     C.DESCRICAO as MOTIVO_CANCELAMENTO,
                     T.DATA_PROTESTO,
                     L.NUMERO_LIVRO,
                     T.FOLHA_PROTESTO,
                     case
                     when T.MOTIVO_APONTAMENTO_ID > 3 then 1
                     else T.MOTIVO_APONTAMENTO_ID
                     end as MOTIVO_APONTAMENTO_ID,
                     T.PRACA_PAGAMENTO,
                     T.TIPO_ENDOSSO,
                     PA.DEVEDOR_TIPO_ACEITE,
                     (select first 1 DESCRICAO
                        from P_OCORRENCIAS OE
                       where OE.OCORRENCIAS_ID = PA.OCORRENCIA_ID ) as EDITAL_MOTIVO,
                     T.DATA_CADASTRO as APRESENTACAO,
                     case
                        when PA.NOME is not null then PA.NOME
                        else
                            (select first 1 DESCRICAO
                              from P_BANCO
                             where CODIGO_BANCO = (select first 1 PORTADOR_CODIGO
                                                     from p_arquivo_titulo
                                                    where ARQUIVO_TITULO_ID = (select first 1 ARQUIVO_TITULO_ID
                                                                                 from p_titulo TP
                                                                                where TP.titulo_id = t.titulo_id)))
                        end as  APRESENTANTE,
                     PA.CPFCNPJ as APRESENTANTE_CPFCNPJ,
                     PA.PESSOA_ID as APRESENTANTE_ID,

    /*SELECIONA APENAS O NOME DO APRESENTANTE */ PC.NOME as CREDOR,
    /*SELECIONA APENAS O NOME DO CREDOR */ PC.CPFCNPJ as CREDOR_CPFCNPJ,
    /*CPFCNPJ CREDOR*/ PD.NOME as DEVEDOR,
    /*SELECIONA APENAS O NOME DO DEVEDOR*/ PD.CPFCNPJ as DEVEDOR_CPFCNPJ,
                     PD.ENDERECO as DEVEDOR_ENDERECO,
                     PD.CEP as DEVEDOR_CEP,
                     PD.CIDADE as DEVEDOR_CIDADE,
                     PD.BAIRRO as DEVEDOR_BAIRRO,
                     PD.UF as DEVEDOR_UF,
                     PE.NOME as CEDENTE_NOME,
                     PE.CPFCNPJ as CEDENTE_CPFCNPJ,
                     PE.ENDERECO as CEDENTE_ENDERECO,
                     PE.CEP as CEDENTE_CEP,
                     PE.CIDADE as CEDENTE_DIDADE,
                     PE.UF as CEDENTER_UF,
                     PE.BAIRRO as CEDENTE_BAIRRO,
                     PC.ENDERECO as CREDOR_ENDERECO,
                     PC.CEP as CREDOR_CEP,
                     PC.CIDADE as CREDOR_DIDADE,
                     PC.UF as CREDOR_UF,
                     PC.BAIRRO as CREDOR_BAIRRO,
                     T.DATA_EMISSAO_TITULO,
                     T.DATA_VENCIMENTO_TITULO,
                     T.TIPO_ACEITE,
                     T.DATA_ENV_SERASA,
                     T.DATA_RET_SERASA,
                     T.DATA_CANCELAMENTO,
                     T.DATA_PAGO,
                     T.DATA_DESISTENCIA,
                     T.DATA_INTIMACAO,
                     L.LIVRO_NATUREZA_ID,
                     case
                        when T.BANCO_ID > 0 then BA.CODIGO_BANCO
                     else ''TAB''
                     end as CODIGO_BANCO,
                     T.NOSSO_NUMERO,
                     T.DATA_ANUENCIA,
                     T.ORIGEM_ANUENCIA,
                     T.APRESENTANTE_PERMITIDO,
                     T.CEDENTE_PERMITIDO,
                     T.CREDOR_PERMITIDO,
                     T.ANUENCIA,
                     trim(''PROTESTO'') as TIPO
                from P_TITULO T
               left join P_ESPECIE E on E.ESPECIE_ID = T.ESPECIE_ID
               left join P_OCORRENCIAS O on O.OCORRENCIAS_ID = T.OCORRENCIA_ID
               left join P_MOTIVOS M on M.MOTIVOS_ID = T.MOTIVO_APONTAMENTO_ID
               left join P_MOTIVOS_CANCELAMENTO C on C.MOTIVOS_CANCELAMENTO_ID = T.MOTIVO_CANCELAMENTO
               left join P_PESSOA_VINCULO PA on PA.TITULO_ID = T.TITULO_ID and PA.TIPO_VINCULO = ''APRESENTANTE''
               left join P_PESSOA_VINCULO PC on PC.TITULO_ID = T.TITULO_ID and PC.TIPO_VINCULO = ''CREDOR''
               left join P_PESSOA_VINCULO PD on PD.TITULO_ID = T.TITULO_ID and PD.TIPO_VINCULO = ''DEVEDOR''
               left join P_PESSOA_VINCULO PE on PE.TITULO_ID = T.TITULO_ID and PE.TIPO_VINCULO = ''CEDENTE''
               left join P_LIVRO_ANDAMENTO L on L.LIVRO_ANDAMENTO_ID = T.LIVRO_ID_PROTESTO
               left join P_BANCO BA on T.BANCO_ID = BA.BANCO_ID
               where 1 = 1 ';
               --AND T.data_cancelamento IS NULL ';

        -- se periodo estiver marcado
        IF ((COALESCE(:V_DATA_INICIAL,'') <> '') AND (COALESCE(:V_DATA_FINAL,'') <> '')) THEN
        BEGIN
          V_SQL = :V_SQL || ' AND T.DATA_PROTESTO BETWEEN CAST('|| ' '' '||:V_DATA_INICIAL|| ''''||'  AS TIMESTAMP )
            AND CAST( '|| ' '' '||:V_DATA_FINAL||' '' ' ||'AS TIMESTAMP) + 0.9999
            AND PD.TIPO_VINCULO = ''DEVEDOR''  ';
            v_ContFiltro = 1;
        END
    
        -- se natureza do titulo
        IF (COALESCE(:V_ESPECIE,0) <> 0) THEN
        BEGIN
          V_SQL = :V_SQL || ' AND T.ESPECIE_ID = ' || :V_ESPECIE || ' ';
          v_ContFiltro = 1;
        END
    
        -- se nº apontamento marcado
        IF (COALESCE(:V_NUMERO_APONTAMENTO_INI,'') <> '') THEN
        BEGIN
          V_SQL = :V_SQL || ' AND T.NUMERO_APONTAMENTO BETWEEN '''|| :V_NUMERO_APONTAMENTO_INI || ''' '
                         || ' AND ''' || :V_NUMERO_APONTAMENTO_FIN || ''' ';
          v_ContFiltro = 1;
        END
    
        -- se número do titulo marcado
        if (coalesce(:V_NUMERO_TITULO, '') <> '') then
        BEGIN
            V_SQL = :V_SQL || ' AND T.NUMERO_TITULO =  ''' || :V_NUMERO_TITULO || '''';
            v_ContFiltro = 1;
        END

        --CPF/CNPJ marcado
        if (coalesce(:V_CPFCNPJ, '') <> '') then
        begin
            if (V_VINCULO = 0) then
                V_SQL = :V_SQL || ' AND PA.CPFCNPJ = ''' || :V_CPFCNPJ || ''' ';

            else if (V_VINCULO =1 ) then
                V_SQL = :V_SQL || ' AND PC.CPFCNPJ = ''' || :V_CPFCNPJ || ''' ';

            else if (V_VINCULO = 2) then
                V_SQL = :V_SQL || ' AND PD.CPFCNPJ = ''' || :V_CPFCNPJ || ''' ';

            else if (V_VINCULO = 3) then
                V_SQL = :V_SQL || ' AND PE.CPFCNPJ = ''' || :V_CPFCNPJ || ''' ';

            v_ContFiltro = 1;
        end

        if (v_ContFiltro = 0 ) then
        begin
            if (V_GERAR_NOVAMENTE = 1) then
            begin
                V_SQL = :V_SQL  || 'AND NOT T.DATA_ENV_SERASA IS NULL
                                    AND T.DATA_RET_SERASA IS NULL
                                    AND NOT T.DATA_PROTESTO IS NULL
                                    AND T.DATA_MOV_SERASA =  '' ' ||:V_ULTIMA_DATA || ' ''
                                    AND PD.TIPO_VINCULO = ''DEVEDOR'' ';
            end
            else
            begin
                V_SQL = :V_SQL || ' AND T.DATA_ENV_SERASA IS NULL
                                    AND T.DATA_RET_SERASA IS NULL
                                    AND NOT T.DATA_PROTESTO IS NULL
                                    AND PD.TIPO_VINCULO = ''DEVEDOR''  ';
            end
        end
    end
    else if (V_TIPO = 'C') then
    begin
        v_ContFiltro = 0;
        V_SQL =  ' select ''' ||V_SEL ||''' as SEL,
                     T.TITULO_ID,
                     T.NUMERO_APONTAMENTO,
                     cast(T.DATA_APONTAMENTO as date) as DATA_APONTAMENTO,
                     cast(T.DATA_CADASTRO as date) as DATA_CADASTRO,
                     T.VALOR_TITULO,
                     T.VALOR_TOTAL,
                     cast(T.DATA_ACEITE as date) as DATA_ACEITE,
                     case
                     when (e.especie_id > 39) then ''DV''
                     else E.especie
                     end as NATUREZA,
                     O.DESCRICAO as OCORRENCIA,
                     case O.DESCRICAO
                     when ''1'' then O.CODIGO
                     when ''2'' then O.CODIGO
                     when ''3'' then O.CODIGO
                     when ''4'' then O.CODIGO
                     when ''5'' then O.CODIGO
                     when ''A'' then O.CODIGO
                     when ''X'' then O.CODIGO
                     else ''Y''
                     end as CODIGO_OCORRENCIA,
                     T.NUMERO_TITULO,
                     M.DESCRICAO as MOTIVO_APONTAMENTO,
                     M.CODIGO as ESPECIE_PROTESTO,
                     T.VALOR_EMOLUMENTO,
                     T.VALOR_TAXA_JUDICIARIA,
                     T.VALOR_TAXA_INTIMACAO,
                     T.VALOR_TAXA_EDITAL,
                     T.VALOR_TAXA_JUROS,
                     T.VALOR_DESCONTO,
                     T.VALOR_TAXA_FUNDESP,
                     T.VALOR_TAXA_AVERB,
                     T.VALOR_TAXA_CORREIOS,
                     cast(T.DATA_SUSTADO as date) as DATA_SUSTADO,
                     C.DESCRICAO as MOTIVO_CANCELAMENTO,
                     T.DATA_PROTESTO,
                     L.NUMERO_LIVRO,
                     T.FOLHA_PROTESTO,
                     case
                     when T.MOTIVO_APONTAMENTO_ID > 3 then 1
                     else T.MOTIVO_APONTAMENTO_ID
                     end as MOTIVO_APONTAMENTO_ID,
                     T.PRACA_PAGAMENTO,
                     T.TIPO_ENDOSSO,
                     PA.DEVEDOR_TIPO_ACEITE,
                     (select first 1 DESCRICAO
                        from P_OCORRENCIAS OE
                       where OE.OCORRENCIAS_ID = PA.OCORRENCIA_ID ) as EDITAL_MOTIVO,
                     T.DATA_CADASTRO as APRESENTACAO,
                     case
                        when PA.NOME is not null then PA.NOME
                        else
                            (select first 1 DESCRICAO
                              from P_BANCO
                             where CODIGO_BANCO = (select first 1 PORTADOR_CODIGO
                                                     from p_arquivo_titulo
                                                    where ARQUIVO_TITULO_ID = (select first 1 ARQUIVO_TITULO_ID
                                                                                 from p_titulo TP
                                                                                where TP.titulo_id = t.titulo_id)))
                        end as  APRESENTANTE,
                     PA.CPFCNPJ as APRESENTANTE_CPFCNPJ,
                     PA.PESSOA_ID as APRESENTANTE_ID,

    /*SELECIONA APENAS O NOME DO APRESENTANTE */ PC.NOME as CREDOR,
    /*SELECIONA APENAS O NOME DO CREDOR */ PC.CPFCNPJ as CREDOR_CPFCNPJ,
    /*CPFCNPJ CREDOR*/ PD.NOME as DEVEDOR,
    /*SELECIONA APENAS O NOME DO DEVEDOR*/ PD.CPFCNPJ as DEVEDOR_CPFCNPJ,
                     PD.ENDERECO as DEVEDOR_ENDERECO,
                     PD.CEP as DEVEDOR_CEP,
                     PD.CIDADE as DEVEDOR_CIDADE,
                     PD.BAIRRO as DEVEDOR_BAIRRO,
                     PD.UF as DEVEDOR_UF,
                     PE.NOME as CEDENTE_NOME,
                     PE.CPFCNPJ as CEDENTE_CPFCNPJ,
                     PE.ENDERECO as CEDENTE_ENDERECO,
                     PE.CEP as CEDENTE_CEP,
                     PE.CIDADE as CEDENTE_DIDADE,
                     PE.UF as CEDENTER_UF,
                     PE.BAIRRO as CEDENTE_BAIRRO,
                     PC.ENDERECO as CREDOR_ENDERECO,
                     PC.CEP as CREDOR_CEP,
                     PC.CIDADE as CREDOR_DIDADE,
                     PC.UF as CREDOR_UF,
                     PC.BAIRRO as CREDOR_BAIRRO,
                     T.DATA_EMISSAO_TITULO,
                     T.DATA_VENCIMENTO_TITULO,
                     T.TIPO_ACEITE,
                     T.DATA_ENV_SERASA,
                     T.DATA_RET_SERASA,
                     T.DATA_CANCELAMENTO,
                     T.DATA_PAGO,
                     T.DATA_DESISTENCIA,
                     T.DATA_INTIMACAO,
                     L.LIVRO_NATUREZA_ID,                           
                     case
                        when T.BANCO_ID > 0 then BA.CODIGO_BANCO
                     else ''TAB''
                     end as CODIGO_BANCO,
                     T.NOSSO_NUMERO,
                     T.DATA_ANUENCIA,
                     T.ORIGEM_ANUENCIA,
                     T.APRESENTANTE_PERMITIDO,
                     T.CEDENTE_PERMITIDO,
                     T.CREDOR_PERMITIDO,
                     T.ANUENCIA,
                     trim (''CANCELADO'') as TIPO
                from P_TITULO T
               left join P_ESPECIE E on E.ESPECIE_ID = T.ESPECIE_ID
               left join P_OCORRENCIAS O on O.OCORRENCIAS_ID = T.OCORRENCIA_ID
               left join P_MOTIVOS M on M.MOTIVOS_ID = T.MOTIVO_APONTAMENTO_ID
               left join P_MOTIVOS_CANCELAMENTO C on C.MOTIVOS_CANCELAMENTO_ID = T.MOTIVO_CANCELAMENTO
               left join P_PESSOA_VINCULO PA on PA.TITULO_ID = T.TITULO_ID and PA.TIPO_VINCULO = ''APRESENTANTE''
               left join P_PESSOA_VINCULO PC on PC.TITULO_ID = T.TITULO_ID and PC.TIPO_VINCULO = ''CREDOR''
               left join P_PESSOA_VINCULO PD on PD.TITULO_ID = T.TITULO_ID and PD.TIPO_VINCULO = ''DEVEDOR''
               left join P_PESSOA_VINCULO PE on PE.TITULO_ID = T.TITULO_ID and PE.TIPO_VINCULO = ''CEDENTE''
               left join P_LIVRO_ANDAMENTO L on L.LIVRO_ANDAMENTO_ID = T.LIVRO_ID_PROTESTO
               left join P_BANCO BA on T.BANCO_ID = BA.BANCO_ID
               where 1 = 1
               --AND T.data_ret_serasa IS NULL
               AND NOT T.DATA_CANCELAMENTO IS NULL';

        -- se periodo estiver marcado
        IF ((COALESCE(:V_DATA_INICIAL,'') <> '') AND (COALESCE(:V_DATA_FINAL,'') <> '')) THEN
        BEGIN
            V_SQL = :V_SQL || ' AND T.DATA_CANCELAMENTO BETWEEN CAST('||''''||:V_DATA_INICIAL||''''||' AS TIMESTAMP )
            AND CAST('||''''||:V_DATA_FINAL||''''||' AS TIMESTAMP) + 0.9999 ' ||
            'AND PD.TIPO_VINCULO = ''DEVEDOR''  ';
            v_ContFiltro = 1;
        END

        -- se natureza do titulo
        IF (COALESCE(:V_ESPECIE,0) <> 0) THEN
        BEGIN
          V_SQL = :V_SQL || ' AND T.ESPECIE_ID = ' || :V_ESPECIE || ' ';
          v_ContFiltro = 1;
        END
    
        -- se nº apontamento marcado
        IF (COALESCE(:V_NUMERO_APONTAMENTO_INI,'') <> '') THEN
        BEGIN
          V_SQL = :V_SQL || ' AND T.NUMERO_APONTAMENTO BETWEEN '''|| :V_NUMERO_APONTAMENTO_INI || ''' '
                         || ' AND ''' || :V_NUMERO_APONTAMENTO_FIN || ''' ';
          v_ContFiltro = 1;
        END
    
        -- se número do titulo marcado
         if (coalesce(:V_NUMERO_TITULO, '') <> '') then
        BEGIN
            V_SQL = :V_SQL || ' AND T.NUMERO_TITULO =  ''' || :V_NUMERO_TITULO || '''';
            v_ContFiltro = 1;
        END

        --CPF/CNPJ marcado
        if (coalesce(:V_CPFCNPJ, '') <> '') then
        begin
            if (V_VINCULO = 0) then
                V_SQL = :V_SQL || ' AND PA.CPFCNPJ = ''' || :V_CPFCNPJ || ''' ';

            else if (V_VINCULO =1 ) then
                V_SQL = :V_SQL || ' AND PC.CPFCNPJ = ''' || :V_CPFCNPJ || ''' ';

            else if (V_VINCULO = 2) then
                V_SQL = :V_SQL || ' AND PD.CPFCNPJ = ''' || :V_CPFCNPJ || ''' ';

            else if (V_VINCULO = 3) then
                V_SQL = :V_SQL || ' AND PE.CPFCNPJ = ''' || :V_CPFCNPJ || ''' ';

            v_ContFiltro = 1;
        end
        
        if (v_ContFiltro = 0) then
        begin
            if (V_GERAR_NOVAMENTE = 1) then
            begin
                V_SQL = :V_SQL || ' AND NOT T.DATA_RET_SERASA IS NULL
                                    AND NOT T.DATA_ENV_SERASA IS NULL
                                    AND T.DATA_MOV_SERASA  = '' ' ||:V_ULTIMA_DATA || ' ''
                                    AND PD.TIPO_VINCULO = ''DEVEDOR''  ';
            end
            else
            begin
                V_SQL = :V_SQL || ' AND NOT T.DATA_ENV_SERASA IS NULL
                                    AND NOT T.DATA_CANCELAMENTO IS NULL
                                    AND T.DATA_RET_SERASA IS NULL
                                    AND PD.TIPO_VINCULO = ''DEVEDOR''  ';
    
            end
        end
    end
    else if (V_TIPO = 'T') then
    begin
        v_ContFiltro = 0;
        V_SQL = ' select ''' ||V_SEL ||''' as SEL,
                     T.TITULO_ID,
                     T.NUMERO_APONTAMENTO,
                     cast(T.DATA_APONTAMENTO as date) as DATA_APONTAMENTO,
                     cast(T.DATA_CADASTRO as date) as DATA_CADASTRO,
                     T.VALOR_TITULO,
                     T.VALOR_TOTAL,
                     cast(T.DATA_ACEITE as date) as DATA_ACEITE,
                     case
                     when (e.especie_id > 39) then ''DV''
                     else E.especie
                     end as NATUREZA,
                     O.DESCRICAO as OCORRENCIA,
                     case O.DESCRICAO
                     when ''1'' then O.CODIGO
                     when ''2'' then O.CODIGO
                     when ''3'' then O.CODIGO
                     when ''4'' then O.CODIGO
                     when ''5'' then O.CODIGO
                     when ''A'' then O.CODIGO
                     when ''X'' then O.CODIGO
                     else ''Y''
                     end as CODIGO_OCORRENCIA,
                     T.NUMERO_TITULO,
                     M.DESCRICAO as MOTIVO_APONTAMENTO,
                     M.CODIGO as ESPECIE_PROTESTO,
                     T.VALOR_EMOLUMENTO,
                     T.VALOR_TAXA_JUDICIARIA,
                     T.VALOR_TAXA_INTIMACAO,
                     T.VALOR_TAXA_EDITAL,
                     T.VALOR_TAXA_JUROS,
                     T.VALOR_DESCONTO,
                     T.VALOR_TAXA_FUNDESP,
                     T.VALOR_TAXA_AVERB,
                     T.VALOR_TAXA_CORREIOS,
                     cast(T.DATA_SUSTADO as date) as DATA_SUSTADO,
                     C.DESCRICAO as MOTIVO_CANCELAMENTO,
                     T.DATA_PROTESTO,
                     L.NUMERO_LIVRO,
                     T.FOLHA_PROTESTO,
                     case
                     when T.MOTIVO_APONTAMENTO_ID > 3 then 1
                     else T.MOTIVO_APONTAMENTO_ID
                     end as MOTIVO_APONTAMENTO_ID,
                     T.PRACA_PAGAMENTO,
                     T.TIPO_ENDOSSO,
                     PA.DEVEDOR_TIPO_ACEITE,
                     (select first 1 DESCRICAO
                        from P_OCORRENCIAS OE
                       where OE.OCORRENCIAS_ID = PA.OCORRENCIA_ID ) as EDITAL_MOTIVO,
                     T.DATA_CADASTRO as APRESENTACAO,
                     case
