BEGIN
  --retornar os percents
  V_QTDE_PERCENT = 0;
  V_STRING = :V_NOME;
  V_ULTIMO_EH_PERCENT = 0;
  WHILE (V_STRING IS NOT NULL AND V_STRING <> '') DO
  BEGIN
    V_CH = SUBSTRING(V_STRING FROM 1 FOR 1);
    IF (:V_CH = '%') THEN
    BEGIN
      V_QTDE_PERCENT = :V_QTDE_PERCENT + 1;
      V_ULTIMO_EH_PERCENT = 1;
    END
    ELSE
      V_ULTIMO_EH_PERCENT = 0;
    V_STRING = SUBSTRING(V_STRING FROM 2 FOR 120);
  END

  IF ((SUBSTRING(:V_NOME FROM 1 FOR 1) = '%') OR (:V_QTDE_PERCENT > 1) OR
    ((:V_QTDE_PERCENT = 1) AND (:V_ULTIMO_EH_PERCENT = 0))) THEN
  BEGIN
    FOR SELECT PESSOA_ID, NOME, COALESCE(CPF_CNPJ, ''),
