    END
  END
  ELSE
  BEGIN
    SELECT TAMANHO FROM W_LENGTH(:V_NOME) INTO V_TAMANHO;
    IF (:V_ULTIMO_EH_PERCENT = 1) THEN
      V_NOME = SUBSTRING(:V_NOME FROM 1 FOR (:V_TAMANHO - 1));
      
    FOR SELECT PESSOA_ID, NOME, COALESCE(CPF_CNPJ, ''),
          SISTEMA_VELHO, MENSAGEM_IMPORTANTE,
          NACIONALIDADE, SEXO, TB_PROFISSAO_ID,
          TB_ESTADOCIVIL_ID, COALESCE(DOCUMENTO, '')
        FROM R_PESSOA
        WHERE NOME STARTING WITH :V_NOME
        AND COALESCE(SISTEMA_VELHO,'') <> ''
        ORDER BY 2
        INTO :PESSOA_ID, :NOME, :CPF_CNPJ, :SISTEMA_VELHO, :MENSAGEM_IMPORTANTE,
          :NACIONALIDADE, :SEXO, :TB_PROFISSAO_ID, :TB_ESTADOCIVIL_ID, :DOCUMENTO DO
    BEGIN
      SUSPEND;
    END
  END
END ^

ALTER PROCEDURE R_BUSCA_PESSOA_NOME_E_CPF (V_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
V_CPF VARCHAR(30) CHARACTER SET ISO8859_1)
RETURNS (PESSOA_ID NUMERIC(12, 2),
NOME VARCHAR(120) CHARACTER SET ISO8859_1,
DOCUMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
CPF_CNPJ VARCHAR(20) CHARACTER SET ISO8859_1,
SISTEMA_VELHO VARCHAR(1) CHARACTER SET ISO8859_1,
MENSAGEM_IMPORTANTE VARCHAR(260) CHARACTER SET ISO8859_1,
NACIONALIDADE VARCHAR(30) CHARACTER SET ISO8859_1,
SEXO VARCHAR(1) CHARACTER SET ISO8859_1,
TB_PROFISSAO_ID NUMERIC(12, 2),
TB_ESTADOCIVIL_ID NUMERIC(12, 2),
ULTIMO_ESTADO_CIVIL VARCHAR(120) CHARACTER SET ISO8859_1)
AS 
BEGIN
  FOR SELECT DISTINCT PESSOA_ID, NOME, CPF_CNPJ
      FROM R_PESSOA_VINCULO
      WHERE NOME LIKE :V_NOME
      AND CPF_CNPJ STARTING WITH :V_CPF
      UNION
      SELECT DISTINCT PESSOA_ID, NOME, CPF_CNPJ
      FROM R_PESSOA
      WHERE NOME LIKE :V_NOME
      AND CPF_CNPJ STARTING WITH :V_CPF      
      ORDER BY 2
      INTO :PESSOA_ID, :NOME, :CPF_CNPJ DO
  BEGIN
    IF (:PESSOA_ID IS NOT NULL) THEN
    BEGIN
      SELECT SISTEMA_VELHO, MENSAGEM_IMPORTANTE,
        NACIONALIDADE, SEXO, TB_PROFISSAO_ID,
        TB_ESTADOCIVIL_ID, COALESCE(DOCUMENTO,'')
      FROM R_PESSOA
      WHERE PESSOA_ID = :PESSOA_ID
      INTO :SISTEMA_VELHO, :MENSAGEM_IMPORTANTE,
        :NACIONALIDADE, :SEXO, :TB_PROFISSAO_ID,
        :TB_ESTADOCIVIL_ID, :DOCUMENTO;
    END
    ELSE
    BEGIN
      SISTEMA_VELHO = NULL;
      MENSAGEM_IMPORTANTE = NULL;
      NACIONALIDADE = NULL;
      SEXO = NULL;
      TB_PROFISSAO_ID = NULL;
      TB_ESTADOCIVIL_ID = NULL;
      DOCUMENTO = NULL;
    END
    if (COALESCE(:cpf_cnpj,'') <> '') then
    begin
      SELECT FIRST 1 upper(ec.descricao) from R_PESSOA_VINCULO pv, g_tb_estadocivil ec
      where pv.tb_estadocivil_id = ec.tb_estadocivil_id
      and pv.cpf_cnpj = :cpf_cnpj
      order by pv.data_ultima_atualizacao desc, pv.pessoa_vinculo_id desc
      into :ultimo_estado_civil;
    end
    else
    begin
      ultimo_estado_civil = '';
    end

    SUSPEND;
  END
END ^

