      WHERE NOME_FONETICO LIKE :V_NOME_FONETICO
      UNION
      SELECT DISTINCT PESSOA_ID, NOME, CPF_CNPJ
      FROM R_PESSOA
      WHERE NOME_FONETICO LIKE :V_NOME_FONETICO
      ORDER BY 2      
      INTO :PESSOA_ID, :NOME, :CPF_CNPJ DO
  BEGIN  
    IF (:PESSOA_ID IS NOT NULL) THEN
