      SELECT SISTEMA_VELHO, MENSAGEM_IMPORTANTE, COALESCE(DOCUMENTO,'')
      FROM R_PESSOA
      WHERE PESSOA_ID = :PESSOA_ID
      INTO :SISTEMA_VELHO, :MENSAGEM_IMPORTANTE, :DOCUMENTO;
    END
    ELSE
    BEGIN
      SISTEMA_VELHO = NULL;
      MENSAGEM_IMPORTANTE = NULL;
      DOCUMENTO = NULL;
    END

    if (COALESCE(:cpf_cnpj,'') <> '') then
    begin
      SELECT FIRST 1 upper(ec.descricao) from R_PESSOA_VINCULO pv, g_tb_estadocivil ec
      where pv.tb_estadocivil_id = ec.tb_estadocivil_id
      and pv.cpf_cnpj = :cpf_cnpj
      order by pv.data_ultima_atualizacao desc, pv.pessoa_vinculo_id desc
      into :ultimo_estado_civil;
    end
    else
    begin
      ultimo_estado_civil = '';
    end

    SUSPEND;
  END
END ^

ALTER PROCEDURE R_BUSCA_PESSOA_NOVO (V_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
V_CPF VARCHAR(30) CHARACTER SET ISO8859_1)
RETURNS (PESSOA_ID NUMERIC(12, 2),
NOME VARCHAR(120) CHARACTER SET ISO8859_1,
DOCUMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
CPF_CNPJ VARCHAR(20) CHARACTER SET ISO8859_1,
SISTEMA_VELHO VARCHAR(1) CHARACTER SET ISO8859_1,
MENSAGEM_IMPORTANTE VARCHAR(260) CHARACTER SET ISO8859_1,
NACIONALIDADE VARCHAR(30) CHARACTER SET ISO8859_1,
SEXO VARCHAR(1) CHARACTER SET ISO8859_1,
TB_PROFISSAO_ID NUMERIC(12, 2),
TB_ESTADOCIVIL_ID NUMERIC(12, 2),
ULTIMO_ESTADO_CIVIL VARCHAR(120) CHARACTER SET ISO8859_1)
AS 
declare variable v_sql varchar(2000);
  declare variable v_usar_sistema_velho varchar(3);
BEGIN
  PESSOA_ID = 0;
  v_usar_sistema_velho = '';
  select first 1 VALOR_PARAMETRO from g_buscar_config('PESSOAL','GERAL','USAR_SISTEMA_VELHO',1)
  into :v_usar_sistema_velho;

  v_sql = '';
  if (coalesce(:V_CPF, '') <> '') then
  begin
    v_sql = ' select distinct nome, cpf_cnpj, null, 0 from r_pessoa_vinculo
      where cpf_cnpj like '''||:v_cpf||''' ';

    if (coalesce(:v_usar_sistema_velho,'') = 'S') then
    begin
      v_sql = :v_sql || ' union all select distinct nome, cpf_cnpj, sistema_velho, pessoa_id from r_pessoa
        where cpf_cnpj like '''||:v_cpf||''' and coalesce(sistema_velho,'''||''') = '''||'S'||''' ';
    end
    v_sql = :v_sql ||' order by 1 ';
  end
  else
  begin
    v_sql = ' select distinct nome, cpf_cnpj, null, 0 from r_pessoa_vinculo
      where nome like '''||:v_nome||''' ';

    if (coalesce(:v_usar_sistema_velho,'') = 'S') then
    begin
      v_sql = :v_sql || ' union all select distinct nome, cpf_cnpj, sistema_velho, pessoa_id from r_pessoa
        where nome like '''||:v_nome||''' and coalesce(sistema_velho,'''||''') = '''||'S'||''' ';
    end
    v_sql = :v_sql ||' order by 1 ';
  end

  FOR EXECUTE STATEMENT :v_sql
      INTO :NOME, :CPF_CNPJ, :SISTEMA_VELHO, :PESSOA_ID do
  begin
    MENSAGEM_IMPORTANTE = NULL;
    NACIONALIDADE = NULL;
    SEXO = NULL;
    TB_PROFISSAO_ID = NULL;
    TB_ESTADOCIVIL_ID = NULL;
    DOCUMENTO = NULL;
    if (COALESCE(:cpf_cnpj,'') <> '') then
    begin
      if (coalesce(:pessoa_id,0) > 0) then
      begin
        SELECT FIRST 1 upper(ec.descricao), pv.nacionalidade, pv.sexo, pv.tb_profissao_id, pv.tb_estadocivil_id, pv.documento, pv.mensagem_importante
        from R_PESSOA pv, g_tb_estadocivil ec
        where pv.tb_estadocivil_id = ec.tb_estadocivil_id
        and pv.pessoa_id = :pessoa_id
        into :ultimo_estado_civil, :nacionalidade, :sexo, :tb_profissao_id, :tb_estadocivil_id, :documento, :mensagem_importante;
      end
      else
      begin
        SELECT FIRST 1 upper(ec.descricao), pv.nacionalidade, pv.sexo, pv.tb_profissao_id, pv.tb_estadocivil_id, pv.documento,
        (select first 1 mensagem_importante from r_pessoa where cpf_cnpj = pv.cpf_cnpj and coalesce(mensagem_importante,'') <> '' order by pessoa_id desc)
        from R_PESSOA_VINCULO pv, g_tb_estadocivil ec
        where pv.tb_estadocivil_id = ec.tb_estadocivil_id
        and pv.cpf_cnpj = :cpf_cnpj
        order by pv.data_ultima_atualizacao desc, pv.pessoa_vinculo_id desc
        into :ultimo_estado_civil, :nacionalidade, :sexo, :tb_profissao_id, :tb_estadocivil_id, :documento, :mensagem_importante;
      end
    end
    else
    begin
      ultimo_estado_civil = '';
      if (coalesce(:pessoa_id,0) > 0) then
      begin
        SELECT FIRST 1 upper(ec.descricao), pv.nacionalidade, pv.sexo, pv.tb_profissao_id, pv.tb_estadocivil_id, pv.documento, pv.mensagem_importante
        from R_PESSOA pv, g_tb_estadocivil ec
        where pv.tb_estadocivil_id = ec.tb_estadocivil_id
        and pv.pessoa_id = :pessoa_id
        into :ultimo_estado_civil, :nacionalidade, :sexo, :tb_profissao_id, :tb_estadocivil_id, :documento, :mensagem_importante;
      end
    end

    SUSPEND;
  END
END ^

ALTER PROCEDURE R_BUSCA_PESSOA_PROCURACAO (V_PESSOA_ID NUMERIC(12, 2))
RETURNS (PROCURACAO_ID NUMERIC(12, 2),
DATA TIMESTAMP,
DATA_VENCIMENTO TIMESTAMP,
TB_TIPO_PROCURACAO_ID NUMERIC(12, 2))
AS 
BEGIN
  FOR SELECT DISTINCT P.PROCURACAO_ID, P.DATA,
             P.DATA_VENCIMENTO, P.TB_TIPO_PROCURACAO_ID
  	  FROM R_PROCURACAO P, R_PESSOA_VINCULO V
      WHERE P.PROCURACAO_ID = V.PROCURACAO_ID
      AND V.PESSOA_ID = :V_PESSOA_ID
      ORDER BY P.DATA
      INTO :PROCURACAO_ID, :DATA,
           :DATA_VENCIMENTO, :TB_TIPO_PROCURACAO_ID DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_BUSCA_PESSOA_REG_AUXILIAR (V_PESSOA_ID NUMERIC(12, 2))
RETURNS (IMOVEL_ID NUMERIC(12, 2),
TIPO_CLASSE VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
DATA_REGISTRO TIMESTAMP,
NUMERO NUMERIC(12, 2),
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
CIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
DATA_BAIXA TIMESTAMP,
CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1,
INSCRICAO_IMOVEL VARCHAR(60) CHARACTER SET ISO8859_1,
SITUACAO VARCHAR(1) CHARACTER SET ISO8859_1,
TB_PRODUTO_SAFRA_ID NUMERIC(12, 2),
TB_TIPO_REG_AUXILIAR_ID NUMERIC(12, 2),
DATA_TRANSFERENCIA TIMESTAMP,
TB_TIPO_VINCULO_ID NUMERIC(12, 2))
AS 
BEGIN
  FOR SELECT DISTINCT I.IMOVEL_ID, I.TIPO_CLASSE, I.TIPO_REGISTRO,
             I.DATA_REGISTRO, I.NUMERO, I.NUMERO_LETRA, I.CIDADE,
             I.DATA_BAIXA, I.CARTORIO, I.INSCRICAO_IMOVEL, I.SITUACAO,
             I.TB_PRODUTO_SAFRA_ID, I.TB_TIPO_REG_AUXILIAR_ID,
             V.DATA_TRANSFERENCIA, V.TB_TIPO_VINCULO_ID
      FROM R_IMOVEL I, R_PESSOA_VINCULO V
      WHERE I.IMOVEL_ID = V.IMOVEL_ID
      AND TIPO_REGISTRO = 'A'
      AND V.PESSOA_ID = :V_PESSOA_ID
      ORDER BY I.NUMERO
      INTO :IMOVEL_ID, :TIPO_CLASSE, :TIPO_REGISTRO,
           :DATA_REGISTRO, :NUMERO, :NUMERO_LETRA, :CIDADE,
           :DATA_BAIXA, :CARTORIO, :INSCRICAO_IMOVEL, :SITUACAO,
           :TB_PRODUTO_SAFRA_ID, :TB_TIPO_REG_AUXILIAR_ID,
           :DATA_TRANSFERENCIA, :TB_TIPO_VINCULO_ID DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_BUSCA_PESSOA_TODO_SISTEMA_CPF (V_CPF VARCHAR(30) CHARACTER SET ISO8859_1,
V_TIPO_CPF_INFORMADO VARCHAR(2) CHARACTER SET ISO8859_1)
RETURNS (NOME VARCHAR(120) CHARACTER SET ISO8859_1,
CPF_CNPJ VARCHAR(120) CHARACTER SET ISO8859_1,
EMAIL VARCHAR(260) CHARACTER SET ISO8859_1,
TELEFONE VARCHAR(30) CHARACTER SET ISO8859_1,
CELULAR VARCHAR(15) CHARACTER SET ISO8859_1,
MENSAGEM_IMPORTANTE VARCHAR(260) CHARACTER SET ISO8859_1,
ENDERECO_NFSE VARCHAR_030,
ENDERECO_NUMERO_NFSE VARCHAR_010,
ENDERECO_COMPL_NFSE VARCHAR_030,
ENDERECO_BAIRRO_NFSE VARCHAR_030,
ENDERECO_COD_MUN_NFSE NUMERICO,
ENDERECO_CEP_NFSE VARCHAR_010,
ENDERECO_MUNICIPIO_NFSE VARCHAR_060,
ENDERECO_UF_NFSE VARCHAR_003,
CPF_NFSE VARCHAR_030,
NOME_NFSE VARCHAR_120,
IE_NFSE VARCHAR_030,
IM_NFSE VARCHAR_030)
AS 
BEGIN
  NOME = '';
  CPF_CNPJ = '';
  EMAIL = '';
  TELEFONE = '';
  CELULAR = '';
  MENSAGEM_IMPORTANTE = '';
  ENDERECO_NFSE = '';
  ENDERECO_NUMERO_NFSE = '';
  ENDERECO_COMPL_NFSE = '';
  ENDERECO_BAIRRO_NFSE = '';
  ENDERECO_COD_MUN_NFSE = 0;
  ENDERECO_CEP_NFSE = '';
  ENDERECO_MUNICIPIO_NFSE = '';
  ENDERECO_UF_NFSE = '';
  CPF_NFSE = '';
  NOME_NFSE = '';

  if (:V_TIPO_CPF_INFORMADO = '2') then
  BEGIN
      SELECT FIRST 1 COALESCE(APRESENTANTE_NOME,'') , APRESENTANTE_CPF_CNPJ, EMAIL_CONTATO,
        APRESENTANTE_FONE, CELULAR_CONTATO, SUBSTRING(COALESCE(ENDERECO_NFSE,'') FROM 1 FOR 30), ENDERECO_NUMERO_NFSE,
        ENDERECO_COMPL_NFSE, ENDERECO_BAIRRO_NFSE, CAST(ENDERECO_COD_MUN_NFSE AS INTEGER), ENDERECO_CEP_NFSE,
        ENDERECO_MUNICIPIO_NFSE, ENDERECO_UF_NFSE, CPF_NFSE, COALESCE(NOME_NFSE,''), IE_NFSE, IM_NFSE
      FROM R_PEDIDO
      WHERE CPF_NFSE LIKE :V_CPF
      ORDER BY PEDIDO_ID DESC
      INTO :NOME, :CPF_CNPJ, :EMAIL, :TELEFONE, :CELULAR, :ENDERECO_NFSE, :ENDERECO_NUMERO_NFSE,
        :ENDERECO_COMPL_NFSE, :ENDERECO_BAIRRO_NFSE, :ENDERECO_COD_MUN_NFSE, :ENDERECO_CEP_NFSE,
        :ENDERECO_MUNICIPIO_NFSE, :ENDERECO_UF_NFSE, :CPF_NFSE, :NOME_NFSE, :IE_NFSE, :IM_NFSE;
  END
  ELSE
  BEGIN
      SELECT FIRST 1 COALESCE(APRESENTANTE_NOME,'') , APRESENTANTE_CPF_CNPJ, EMAIL_CONTATO,
        APRESENTANTE_FONE, CELULAR_CONTATO, SUBSTRING(COALESCE(ENDERECO_NFSE,'') FROM 1 FOR 30), ENDERECO_NUMERO_NFSE,
        ENDERECO_COMPL_NFSE, ENDERECO_BAIRRO_NFSE, CAST(ENDERECO_COD_MUN_NFSE AS INTEGER), ENDERECO_CEP_NFSE,
        ENDERECO_MUNICIPIO_NFSE, ENDERECO_UF_NFSE, CPF_NFSE, COALESCE(NOME_NFSE,''), IE_NFSE, IM_NFSE
      FROM R_PEDIDO
      WHERE apresentante_cpf_cnpj LIKE :V_CPF
      ORDER BY PEDIDO_ID DESC
      INTO :NOME, :CPF_CNPJ, :EMAIL, :TELEFONE, :CELULAR, :ENDERECO_NFSE, :ENDERECO_NUMERO_NFSE,
        :ENDERECO_COMPL_NFSE, :ENDERECO_BAIRRO_NFSE, :ENDERECO_COD_MUN_NFSE, :ENDERECO_CEP_NFSE,
        :ENDERECO_MUNICIPIO_NFSE, :ENDERECO_UF_NFSE, :CPF_NFSE, :NOME_NFSE, :IE_NFSE, :IM_NFSE;
  END

  IF (COALESCE(:NOME,'') = '') THEN
  BEGIN
    SELECT FIRST 1 APRESENTANTE_NOME, APRESENTANTE_CPF_CNPJ, EMAIL_CONTATO,
      APRESENTANTE_FONE, CELULAR_CONTATO
    FROM R_PEDIDO
    WHERE APRESENTANTE_CPF_CNPJ LIKE :V_CPF
    ORDER BY PEDIDO_ID DESC
    INTO :NOME, :CPF_CNPJ, :EMAIL, :TELEFONE, :CELULAR;
  END

  IF (COALESCE(:NOME,'') = '') THEN
  BEGIN
    SELECT FIRST 1 ADQUIRENTE_NOME, ADQUIRENTE_CPF_CNPJ, EMAIL_CONTATO,
      APRESENTANTE_FONE, CELULAR_CONTATO
    FROM R_PEDIDO
    WHERE ADQUIRENTE_CPF_CNPJ LIKE :V_CPF
    ORDER BY PEDIDO_ID DESC
    INTO :NOME, :CPF_CNPJ, :EMAIL, :TELEFONE, :CELULAR;
  END

  IF (COALESCE(:NOME,'') = '') THEN
  BEGIN
    SELECT FIRST 1 NOME, CPF_CNPJ, MENSAGEM_IMPORTANTE
    FROM R_PESSOA
    WHERE CPF_CNPJ LIKE :V_CPF
    ORDER BY PESSOA_ID DESC
    INTO :NOME, :CPF_CNPJ, :MENSAGEM_IMPORTANTE;
  END

  SUSPEND;
END ^

ALTER PROCEDURE R_BUSCA_PRAZO_MAIOR_TITULO (V_PEDIDO_ID VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (DESCRICAO_NATUREZA_TITULO VARCHAR(60) CHARACTER SET ISO8859_1,
PRAZO NUMERIC(12, 2),
PRAZO_TIPO VARCHAR(1) CHARACTER SET ISO8859_1,
PRAZO_ESPECIAL NUMERIC(12, 2))
AS 
DECLARE V_DESCRICAO_NATUREZA_TITULO VARCHAR(60);
DECLARE V_PRAZO NUMERIC(12,2);
DECLARE V_PRAZO_TIPO VARCHAR(1);
DECLARE V_PRAZO_ESPECIAL NUMERIC(12,2);
BEGIN
  PRAZO = 0;
  FOR SELECT DESCRICAO, PRAZO, PRAZO_TIPO, PRAZO_ESPECIAL
      FROM R_PEDIDO_ITEM PI, G_NATUREZA_TITULO NT
      WHERE PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID
      AND PI.PEDIDO_ID = :V_PEDIDO_ID
      INTO :V_DESCRICAO_NATUREZA_TITULO, :V_PRAZO, :V_PRAZO_TIPO, :V_PRAZO_ESPECIAL DO
  BEGIN
    IF (:V_PRAZO > :PRAZO) THEN
    BEGIN
      DESCRICAO_NATUREZA_TITULO = :V_DESCRICAO_NATUREZA_TITULO;
      PRAZO = :V_PRAZO;
      PRAZO_TIPO = :V_PRAZO_TIPO;
      PRAZO_ESPECIAL = :V_PRAZO_ESPECIAL;
    END
  END
  SUSPEND;
END ^

ALTER PROCEDURE R_CALCULAR_EMOLUMENTO (V_EMOLUMENTO_ID INTEGER,
V_QUANTIDADE INTEGER,
V_EMOLUMENTO_PERIODO_ID INTEGER,
V_VALOR_DOCUMENTO NUMERIC(14, 2),
V_QUANTIDADE_BUSCA INTEGER,
V_EMOLUMENTO_ID_BUSCA INTEGER,
V_QUANTIDADE_FOLHA_EXCEDENTE INTEGER,
V_EMOLUMENTO_ID_FOLHA_EXCEDENTE INTEGER,
V_QUANTIDADE_ATOS_ACRESCIDOS INTEGER,
V_QUANTIDADE_QUESITOS INTEGER,
V_EMOLUMENTO_ID_ATOS_ACRESCIDOS INTEGER,
V_EMOLUMENTO_ID_QUESITOS INTEGER,
V_QUANTIDADE_ATOS_ACRES_COMP INTEGER,
V_QUANTIDADE_QUESITOS_COMP INTEGER,
V_EMOLUMENTO_ID_ATOS_ACRES_COMP INTEGER,
V_EMOLUMENTO_ID_QUESITOS_COMP INTEGER,
V_QUANTIDADE_PAGINAS INTEGER,
V_QUANTIDADE_UNID_AUT INTEGER,
V_DATA_PROTOCOLO VARCHAR(15) CHARACTER SET ISO8859_1 = '',
V_AREA NUMERIC(10, 2) = 0)
RETURNS (VALOR_FUNDO_SELO NUMERIC(15, 2),
VALOR_EMOLUMENTO NUMERIC(14, 2),
VALOR_TAXA_JUDICIARIA NUMERIC(14, 2),
VALOR_FUNDO_RI NUMERIC(14, 2),
VALOR_TOTAL NUMERIC(14, 2),
CODIGO_SELO VARCHAR(30) CHARACTER SET ISO8859_1,
CODIGO_TABELA VARCHAR(30) CHARACTER SET ISO8859_1,
EMOLUMENTO_ITEM_ID INTEGER,
VALOR_ISS NUMERIC(14, 2),
VALOR_ATOS_ACRESCIDOS NUMERIC(14, 2),
VALOR_ATO_COMPLEMENTO NUMERIC(14, 2),
VALOR_OUTROS NUMERIC(14, 2),
VALOR_EMOLUMENTO_CERT NUMERIC(14, 2),
VALOR_EMOLUMENTO_BUSCA NUMERIC(14, 2),
VALOR_EMOLUMENTO_FOLHA NUMERIC(14, 2),
VALOR_EMOLUMENTO_REVAL NUMERIC(14, 2),
VALOR_TAXA_JUD_CERT NUMERIC(14, 2),
VALOR_TAXA_JUD_BUSCA NUMERIC(14, 2),
VALOR_TAXA_JUD_FOLHA NUMERIC(14, 2),
VALOR_TAXA_JUD_REVAL NUMERIC(14, 2),
VALOR_FUNDO_RI_CERT NUMERIC(14, 2),
VALOR_FUNDO_RI_BUSCA NUMERIC(14, 2),
VALOR_FUNDO_RI_FOLHA NUMERIC(14, 2),
VALOR_FUNDO_RI_REVAL NUMERIC(14, 2))
AS 
declare variable V_VALOR_EMOLUMENTO numeric(14,2);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(14,2);
declare variable V_VALOR_FUNDO_RI numeric(14,2);
declare variable V_VALOR_ISS numeric(14,2);
declare variable V_VALOR_TOTAL numeric(14,2);
declare variable V_USAR_ISS varchar(3);
declare variable V_COBRAR_ISS_USUARIO varchar(3);
declare variable V_PERCENTUAL_ISS_TEMP varchar(30);
declare variable V_PERCENTUAL_ISS numeric(14,5);
declare variable V_UF varchar(5);
declare variable V_PERC_FUNDO_EST numeric(14,4);
declare variable V_EMOLUMENTO_ACRESCE numeric(14,2);
declare variable V_TAXA_ACRESCE numeric(14,2);
declare variable V_FUNCIVIL_ACRESCE numeric(14,2);
declare variable V_VALOR_PAGINAS_EMOL numeric(14,2);
declare variable V_VALOR_PAGINAS_TX_JUD numeric(14,2);
declare variable V_VALOR_PAGINAS_FUNDO numeric(14,2);
declare variable V_VALOR_UNID_AUT_EMOL numeric(14,2);
declare variable V_VALOR_UNID_AUT_TX_JUD numeric(14,2);
declare variable V_VALOR_UNID_AUT_FUNDO numeric(14,2);
declare variable V_EMOLUMENTO_PERIODO_ID_ATUAL integer;
declare variable V_VALOR_EMOLUMENTO_CERT numeric(14,2);
declare variable V_VALOR_TAXA_JUD_CERT numeric(14,2);
declare variable V_VALOR_FUNDO_RI_CERT numeric(14,2);
declare variable V_VALOR_EMOLUMENTO_BUSCA numeric(14,2);
declare variable V_VALOR_TAXA_JUD_BUSCA numeric(14,2);
declare variable V_VALOR_FUNDO_RI_BUSCA numeric(14,2);
declare variable V_VALOR_EMOLUMENTO_FOLHA numeric(14,2);
declare variable V_VALOR_TAXA_JUD_FOLHA numeric(14,2);
declare variable V_VALOR_FUNDO_RI_FOLHA numeric(14,2);
declare variable V_REG_AVERB varchar(3);
declare variable V_VALOR_CALCULO_ISS_GO numeric(14,2);
declare variable V_VALOR_QUESITO numeric(14,2);
BEGIN
  VALOR_EMOLUMENTO = 0;
  VALOR_TAXA_JUDICIARIA = 0;
  VALOR_FUNDO_RI = 0;
  VALOR_TOTAL = 0;
  VALOR_ISS = 0;
  VALOR_ATOS_ACRESCIDOS = 0;
  VALOR_ATO_COMPLEMENTO = 0;
  V_VALOR_PAGINAS_EMOL = 0;
  V_VALOR_PAGINAS_TX_JUD = 0;
  V_VALOR_PAGINAS_FUNDO = 0;
  V_VALOR_UNID_AUT_EMOL = 0;
  V_VALOR_UNID_AUT_TX_JUD = 0;
  V_VALOR_UNID_AUT_FUNDO = 0;

  VALOR_EMOLUMENTO_CERT = 0;
  VALOR_EMOLUMENTO_BUSCA = 0;
  VALOR_EMOLUMENTO_FOLHA = 0;
  VALOR_EMOLUMENTO_REVAL = 0;
  VALOR_TAXA_JUD_CERT = 0;
  VALOR_TAXA_JUD_BUSCA = 0;
  VALOR_TAXA_JUD_FOLHA = 0;
  VALOR_TAXA_JUD_REVAL = 0;
  VALOR_FUNDO_RI_CERT = 0;
  VALOR_FUNDO_RI_BUSCA = 0;
  VALOR_FUNDO_RI_FOLHA = 0;
  VALOR_FUNDO_RI_REVAL = 0;

  V_VALOR_CALCULO_ISS_GO = 0;
  v_valor_quesito = 0;

  V_REG_AVERB = '';

  IF (COALESCE(:V_EMOLUMENTO_PERIODO_ID,0) > 0) THEN
  BEGIN 
    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'USAR_ISS', 5) INTO :V_USAR_ISS;
    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'COBRAR_ISS_USUARIO', 5) INTO :V_COBRAR_ISS_USUARIO;

    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'PERCENTUAL_ISS', 5) INTO :V_PERCENTUAL_ISS_TEMP;
    SELECT RETORNO FROM W_TROCAR_VIRGULA_POR_PONTO(:V_PERCENTUAL_ISS_TEMP) INTO :V_PERCENTUAL_ISS;

    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'CARTORIO', 'UF', 1) INTO :V_UF;

    if (cast(:V_DATA_PROTOCOLO as date) < '24.03.2025') then
    begin
      V_PERC_FUNDO_EST = 21.25;
    end
    else
    begin
      SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'PERCENTUAL_FUNDOS_ESTADUAIS', 5) INTO :V_PERC_FUNDO_EST;
    end

    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO', 'ITENS DO PEDIDO', 'PERIODO_PADRAO', 1) INTO :V_EMOLUMENTO_PERIODO_ID_ATUAL;

-- Conforme orientação da corregedoria o valo dos fundos tem que ser 21.25 %
--    if ((coalesce(:V_DATA_PROTOCOLO,'') <> '') and (COALESCE(:V_UF,'') = 'GO')) then
 --   begin
   --   if (cast(:V_DATA_PROTOCOLO as date) < cast('29.06.2022' as date)) then
 --     begin
    --    V_PERC_FUNDO_EST = 40;
   --   end
--    end

    SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0), 
      CODIGO_SELO, CODIGO_TABELA, EMOLUMENTO_ITEM_ID, COALESCE(EMOLUMENTO_ACRESCE,0),
      COALESCE(TAXA_ACRESCE,0), COALESCE(FUNCIVIL_ACRESCE,0), FUNDO_SELO, REG_AVERB
    FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID, :V_EMOLUMENTO_PERIODO_ID, :V_VALOR_DOCUMENTO)
    INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI, 
      :CODIGO_SELO, :CODIGO_TABELA, :EMOLUMENTO_ITEM_ID, :V_EMOLUMENTO_ACRESCE,
      :V_TAXA_ACRESCE, :V_FUNCIVIL_ACRESCE, :VALOR_FUNDO_SELO, :V_REG_AVERB;

    IF ((COALESCE(:V_UF,'') = 'TO') AND (COALESCE(:CODIGO_TABELA,'') = '5088') AND (COALESCE(:V_AREA,0)>250)) THEN
    BEGIN
      VALOR_EMOLUMENTO = COALESCE(:V_VALOR_EMOLUMENTO,0) * 250;
      VALOR_TAXA_JUDICIARIA = COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * 250;
      VALOR_FUNDO_RI = COALESCE(:V_VALOR_FUNDO_RI,0) * 250;

      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          VALOR_ISS = cast(((COALESCE(:VALOR_EMOLUMENTO,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
        END
      END    

    END
    ELSE IF ((COALESCE(:V_UF,'') = 'TO') AND (COALESCE(:CODIGO_TABELA,'') = '5088') AND (COALESCE(:V_AREA,0)>0) ) then
    BEGIN
      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:V_VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          V_VALOR_ISS = cast(((COALESCE(:V_VALOR_EMOLUMENTO,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
          VALOR_ISS = COALESCE(:V_VALOR_ISS,0) * V_AREA;
        END
      END    
      VALOR_EMOLUMENTO = COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_AREA,0);
      VALOR_TAXA_JUDICIARIA = COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_AREA,0);
      VALOR_FUNDO_RI = COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_AREA,0);
    END
    ELSE IF ((COALESCE(:V_UF,'') = 'TO') AND (COALESCE(:CODIGO_TABELA,'') = '5087')) THEN
    BEGIN
      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:V_VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          V_VALOR_ISS = cast(((COALESCE(:V_VALOR_EMOLUMENTO,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
          VALOR_ISS = COALESCE(:V_VALOR_ISS,0) * COALESCE(:V_AREA,0);
        END
      END    

      VALOR_EMOLUMENTO = COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_AREA,0);
      VALOR_TAXA_JUDICIARIA = COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_AREA,0);
      VALOR_FUNDO_RI = COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_AREA,0);

      if (:VALOR_EMOLUMENTO > 11847.54) then
      begin
        VALOR_EMOLUMENTO = 11847.54;
      end
      if (:VALOR_TAXA_JUDICIARIA > 3244.98) then
      begin
        VALOR_TAXA_JUDICIARIA = 3244.98;
      end
      if (:VALOR_FUNDO_RI > 2169.64) then
      begin
        VALOR_FUNDO_RI = 2169.64;
      end
    END
    ELSE
    BEGIN
      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:V_VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          IF (COALESCE(:V_UF,'') = 'DF') THEN
          BEGIN
            /*if (coalesce(:V_DATA_PROTOCOLO,'') <> '') then
            begin
              if (cast(:V_DATA_PROTOCOLO as date) > cast('30.06.2022' as date)) then
              begin
                V_VALOR_ISS =  CAST(((COALESCE(:V_VALOR_EMOLUMENTO,0) + COALESCE(:V_VALOR_FUNDO_RI,0)) * (:V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
              end
            end*/
          END
          ELSE
          BEGIN
            V_VALOR_ISS = cast(((COALESCE(:V_VALOR_EMOLUMENTO,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
          END

          VALOR_ISS = COALESCE(:V_VALOR_ISS,0) * COALESCE(:V_QUANTIDADE,0);
        END
      END

      VALOR_EMOLUMENTO = COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE,0);
      VALOR_TAXA_JUDICIARIA = COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE,0);
      VALOR_FUNDO_RI = COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE,0);

      if (:V_REG_AVERB = 'C') then
      begin
        VALOR_EMOLUMENTO_CERT = COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE,0);
        VALOR_TAXA_JUD_CERT = COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE,0);
        VALOR_FUNDO_RI_CERT = COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE,0);
      end
      else if (:V_REG_AVERB = 'B') then
      begin
        VALOR_EMOLUMENTO_BUSCA = COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE,0);
        VALOR_TAXA_JUD_BUSCA = COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE,0);
        VALOR_FUNDO_RI_BUSCA = COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE,0);
      end
      else if (:V_REG_AVERB = 'F') then
      begin
        VALOR_EMOLUMENTO_FOLHA = COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE,0);
        VALOR_TAXA_JUD_FOLHA = COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE,0);
        VALOR_FUNDO_RI_FOLHA = COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE,0);
      end
      else if (:V_REG_AVERB = 'V') then
      begin
        VALOR_EMOLUMENTO_REVAL = COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE,0);
        VALOR_TAXA_JUD_REVAL = COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE,0);
        VALOR_FUNDO_RI_REVAL = COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE,0);
      end
    END

    IF (COALESCE(:V_QUANTIDADE_BUSCA,0) > 0) THEN
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_BUSCA, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:V_VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          IF (COALESCE(:V_UF,'') = 'DF') THEN
          BEGIN
            /*if (coalesce(:V_DATA_PROTOCOLO,'') <> '') then
            begin
              if (cast(:V_DATA_PROTOCOLO as date) > cast('30.06.2022' as date)) then
              begin
                V_VALOR_ISS =  CAST(((COALESCE(:V_VALOR_EMOLUMENTO,0) + COALESCE(:V_VALOR_FUNDO_RI,0)) * (:V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
              end
            end*/
          END
          ELSE
          BEGIN
            V_VALOR_ISS = cast(((COALESCE(:V_VALOR_EMOLUMENTO,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
          END

          VALOR_ISS = :VALOR_ISS + (COALESCE(:V_VALOR_ISS,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
        END
      END

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));

      VALOR_EMOLUMENTO_BUSCA = :VALOR_EMOLUMENTO_BUSCA + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
      VALOR_TAXA_JUD_BUSCA = :VALOR_TAXA_JUD_BUSCA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
      VALOR_FUNDO_RI_BUSCA = :VALOR_FUNDO_RI_BUSCA + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
    END
    IF (COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_FOLHA_EXCEDENTE, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:V_VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          IF (COALESCE(:V_UF,'') = 'DF') THEN
          BEGIN
            /*if (coalesce(:V_DATA_PROTOCOLO,'') <> '') then
            begin
              if (cast(:V_DATA_PROTOCOLO as date) > cast('30.06.2022' as date)) then
              begin
                V_VALOR_ISS =  CAST(((COALESCE(:V_VALOR_EMOLUMENTO,0) + COALESCE(:V_VALOR_FUNDO_RI,0)) * (:V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
              end
            end*/
          END
          ELSE
          BEGIN
            V_VALOR_ISS = cast(((COALESCE(:V_VALOR_EMOLUMENTO,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
          END

          VALOR_ISS = :VALOR_ISS + (COALESCE(:V_VALOR_ISS,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
        END
      END

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));

      VALOR_EMOLUMENTO_FOLHA = :VALOR_EMOLUMENTO_FOLHA + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
      VALOR_TAXA_JUD_FOLHA = :VALOR_TAXA_JUD_FOLHA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
      VALOR_FUNDO_RI_FOLHA = :VALOR_FUNDO_RI_FOLHA + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
    END
    IF (COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRESCIDOS, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_ATOS_ACRESCIDOS = (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0));

      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:V_VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          IF (COALESCE(:V_UF,'') = 'DF') THEN
          BEGIN
            /*if (coalesce(:V_DATA_PROTOCOLO,'') <> '') then
            begin
              if (cast(:V_DATA_PROTOCOLO as date) > cast('30.06.2022' as date)) then
              begin
                V_VALOR_ISS =  CAST(((COALESCE(:VALOR_ATOS_ACRESCIDOS,0) + COALESCE(:V_VALOR_FUNDO_RI,0)) * (:V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
              end
            end*/
          END
          ELSE IF (COALESCE(:V_UF,'') = 'GO') THEN
          BEGIN
            V_VALOR_CALCULO_ISS_GO = :V_VALOR_CALCULO_ISS_GO + COALESCE(:VALOR_ATOS_ACRESCIDOS,0);
            V_VALOR_ISS = 0;
          END
          ELSE
          BEGIN
            V_VALOR_ISS = cast(((COALESCE(:VALOR_ATOS_ACRESCIDOS,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
          END

          VALOR_ISS = :VALOR_ISS + (COALESCE(:V_VALOR_ISS,0));
        END
      END

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + COALESCE(:VALOR_ATOS_ACRESCIDOS,0);
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0));
    END
    IF (COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRES_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_ATO_COMPLEMENTO = (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0));

      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:V_VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          IF (COALESCE(:V_UF,'') = 'DF') THEN
          BEGIN
            /*if (coalesce(:V_DATA_PROTOCOLO,'') <> '') then
            begin
              if (cast(:V_DATA_PROTOCOLO as date) > cast('30.06.2022' as date)) then
              begin
                V_VALOR_ISS =  CAST(((COALESCE(:VALOR_ATO_COMPLEMENTO,0) + COALESCE(:V_VALOR_FUNDO_RI,0)) * (:V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
              end
            end*/
          END
          ELSE IF (COALESCE(:V_UF,'') = 'GO') THEN
          BEGIN
            V_VALOR_CALCULO_ISS_GO = :V_VALOR_CALCULO_ISS_GO + COALESCE(:VALOR_ATO_COMPLEMENTO,0);
            V_VALOR_ISS = 0;
          END
          ELSE
          BEGIN
            V_VALOR_ISS = cast(((COALESCE(:VALOR_ATO_COMPLEMENTO,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
          END

          VALOR_ISS = :VALOR_ISS + (COALESCE(:V_VALOR_ISS,0));
        END
      END    

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + COALESCE(:VALOR_ATO_COMPLEMENTO,0);
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0));      
    END        
    IF (COALESCE(:V_QUANTIDADE_QUESITOS,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      v_valor_quesito = (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_QUESITOS,0));

      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:V_VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          IF (COALESCE(:V_UF,'') = 'DF') THEN
          BEGIN
            /*if (coalesce(:V_DATA_PROTOCOLO,'') <> '') then
            begin
              if (cast(:V_DATA_PROTOCOLO as date) > cast('30.06.2022' as date)) then
              begin
                V_VALOR_ISS =  CAST(((COALESCE(:v_valor_quesito,0) + COALESCE(:V_VALOR_FUNDO_RI,0)) * (:V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
              end
            end*/
          END
          ELSE IF (COALESCE(:V_UF,'') = 'GO') THEN
          BEGIN
            V_VALOR_CALCULO_ISS_GO = :V_VALOR_CALCULO_ISS_GO + COALESCE(:v_valor_quesito,0);
            V_VALOR_ISS = 0;
          END
          ELSE
          BEGIN
            V_VALOR_ISS = cast(((COALESCE(:v_valor_quesito,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
          END
          VALOR_ISS = :VALOR_ISS + (COALESCE(:V_VALOR_ISS,0));
        END
      END    

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + COALESCE(:v_valor_quesito,0);
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_QUESITOS,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_QUESITOS,0));      
    END        
    IF (COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      v_valor_quesito = (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0));

      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:V_VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          IF (COALESCE(:V_UF,'') = 'DF') THEN
          BEGIN
            /*if (coalesce(:V_DATA_PROTOCOLO,'') <> '') then
            begin
              if (cast(:V_DATA_PROTOCOLO as date) > cast('30.06.2022' as date)) then
              begin
                V_VALOR_ISS =  CAST(((COALESCE(:v_valor_quesito,0) + COALESCE(:V_VALOR_FUNDO_RI,0)) * (:V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
              end
            end*/
          END
          ELSE IF (COALESCE(:V_UF,'') = 'GO') THEN
          BEGIN
            V_VALOR_CALCULO_ISS_GO = :V_VALOR_CALCULO_ISS_GO + COALESCE(:v_valor_quesito,0);
            V_VALOR_ISS = 0;
          END
          ELSE
          BEGIN
            V_VALOR_ISS = cast(((COALESCE(:v_valor_quesito,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
          END
          VALOR_ISS = :VALOR_ISS + (COALESCE(:V_VALOR_ISS,0));
        END
      END    

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + COALESCE(:v_valor_quesito,0);
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0));      
    END    

    IF (COALESCE(:V_UF,'') = 'TO') THEN
    BEGIN
      IF (COALESCE(V_QUANTIDADE_PAGINAS,0) > 3) THEN
      BEGIN
        V_VALOR_PAGINAS_EMOL = (:V_QUANTIDADE_PAGINAS - 3) * :V_EMOLUMENTO_ACRESCE;
        V_VALOR_PAGINAS_TX_JUD = (:V_QUANTIDADE_PAGINAS - 3) * :V_TAXA_ACRESCE;
        V_VALOR_PAGINAS_FUNDO = (:V_QUANTIDADE_PAGINAS - 3) * :V_FUNCIVIL_ACRESCE;
      END
      IF (COALESCE(V_QUANTIDADE_UNID_AUT,0) > 10) THEN
      BEGIN
        V_VALOR_UNID_AUT_EMOL = (:V_QUANTIDADE_UNID_AUT - 10) * :V_EMOLUMENTO_ACRESCE;
        V_VALOR_UNID_AUT_TX_JUD = (:V_QUANTIDADE_UNID_AUT - 10) * :V_TAXA_ACRESCE;
        V_VALOR_UNID_AUT_FUNDO = (:V_QUANTIDADE_UNID_AUT - 10) * :V_FUNCIVIL_ACRESCE;
      END

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (COALESCE(:V_VALOR_PAGINAS_EMOL,0)) + (COALESCE(:V_VALOR_UNID_AUT_EMOL,0));
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_PAGINAS_TX_JUD,0)) + (COALESCE(:V_VALOR_UNID_AUT_TX_JUD,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_PAGINAS_FUNDO,0)) + (COALESCE(:V_VALOR_UNID_AUT_FUNDO,0));

      IF ((COALESCE(:CODIGO_TABELA,'') = '5087')) THEN
      BEGIN
        if (COALESCE(:VALOR_EMOLUMENTO,0) > 9.99) THEN
        BEGIN
          VALOR_FUNDO_RI = :VALOR_FUNDO_RI + 2.33;
        END
      END

      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:V_VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          V_VALOR_ISS = cast(((COALESCE(:V_VALOR_PAGINAS_EMOL,0)) + (COALESCE(:V_VALOR_UNID_AUT_EMOL,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
          VALOR_ISS = :VALOR_ISS + (COALESCE(:V_VALOR_ISS,0));
        END
      END    
    END

    --VERIFICAR FUNDOS ESTADUAIS EM GOIAS
    IF (COALESCE(:V_UF,'') = 'GO') THEN      
    BEGIN
      VALOR_FUNDO_RI = (COALESCE(VALOR_EMOLUMENTO,0)) * (V_PERC_FUNDO_EST/100);

      IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          VALOR_ISS = :VALOR_ISS + cast(((COALESCE(:V_VALOR_CALCULO_ISS_GO,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
        END
        else
        begin
          VALOR_ISS = 0;
        end
      END    
    END
     IF (COALESCE(:V_UF,'') = 'TO') THEN -- 29-02-2024 -Jose
    BEGIN
     IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
      BEGIN
        IF (COALESCE(:VALOR_EMOLUMENTO,0) > 0) THEN
        BEGIN
          V_VALOR_ISS = VALOR_EMOLUMENTO * (:V_PERCENTUAL_ISS/100); -- cast(((COALESCE(:V_VALOR_PAGINAS_EMOL,0)) + (COALESCE(:V_VALOR_UNID_AUT_EMOL,0)) * (:V_PERCENTUAL_ISS/100)) as numeric(14,2));
          VALOR_ISS = V_VALOR_ISS;-- :VALOR_ISS + (COALESCE(:V_VALOR_ISS,0));
        END  --mudei aqui  PEGAR O VALOR DO EMOLUMENTO JÁ CALCULADO ESTAVA CORRETO
      END
    end
    VALOR_TOTAL = COALESCE(VALOR_EMOLUMENTO,0) + COALESCE(VALOR_TAXA_JUDICIARIA,0) + COALESCE(VALOR_FUNDO_RI,0) + COALESCE(VALOR_ISS,0);
    VALOR_TOTAL = CAST(:VALOR_TOTAL AS NUMERIC(14,2));
  END      

  IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S') and (COALESCE(:V_UF,'') = 'DF')) THEN
  BEGIN
    IF (COALESCE(:VALOR_EMOLUMENTO,0) > 0) THEN
    BEGIN
      if (coalesce(:V_DATA_PROTOCOLO,'') <> '') then
      begin
        if (cast(:V_DATA_PROTOCOLO as date) > cast('30.06.2022' as date)) then
        begin
          VALOR_ISS =  CAST(((COALESCE(:VALOR_EMOLUMENTO,0) + COALESCE(:VALOR_FUNDO_RI,0)) * (:V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));

          VALOR_TOTAL = COALESCE(VALOR_EMOLUMENTO,0) + COALESCE(VALOR_TAXA_JUDICIARIA,0) + COALESCE(VALOR_FUNDO_RI,0) + COALESCE(VALOR_ISS,0);
          VALOR_TOTAL = CAST(:VALOR_TOTAL AS NUMERIC(14,2));
        end
      end
    END
  END
  SUSPEND;
END ^

ALTER PROCEDURE R_CALCULAR_EMOLUMENTO_OLD (V_EMOLUMENTO_ID INTEGER,
V_QUANTIDADE INTEGER,
V_EMOLUMENTO_PERIODO_ID INTEGER,
V_VALOR_DOCUMENTO NUMERIC(14, 2),
V_QUANTIDADE_BUSCA INTEGER,
V_EMOLUMENTO_ID_BUSCA INTEGER,
V_QUANTIDADE_FOLHA_EXCEDENTE INTEGER,
V_EMOLUMENTO_ID_FOLHA_EXCEDENTE INTEGER,
V_QUANTIDADE_ATOS_ACRESCIDOS INTEGER,
V_QUANTIDADE_QUESITOS INTEGER,
V_EMOLUMENTO_ID_ATOS_ACRESCIDOS INTEGER,
V_EMOLUMENTO_ID_QUESITOS INTEGER,
V_QUANTIDADE_ATOS_ACRES_COMP INTEGER,
V_QUANTIDADE_QUESITOS_COMP INTEGER,
V_EMOLUMENTO_ID_ATOS_ACRES_COMP INTEGER,
V_EMOLUMENTO_ID_QUESITOS_COMP INTEGER)
RETURNS (VALOR_FUNDO_SELO NUMERIC(15, 2),
VALOR_EMOLUMENTO NUMERIC(14, 2),
VALOR_TAXA_JUDICIARIA NUMERIC(14, 2),
VALOR_FUNDO_RI NUMERIC(14, 2),
VALOR_TOTAL NUMERIC(14, 2),
CODIGO_SELO VARCHAR(30) CHARACTER SET ISO8859_1,
CODIGO_TABELA VARCHAR(30) CHARACTER SET ISO8859_1,
EMOLUMENTO_ITEM_ID INTEGER,
VALOR_ISS NUMERIC(14, 2),
VALOR_ATOS_ACRESCIDOS NUMERIC(14, 2),
VALOR_ATO_COMPLEMENTO NUMERIC(14, 2))
AS 
DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(14,2);
  DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(14,2);  
  DECLARE VARIABLE V_VALOR_FUNDO_RI NUMERIC(14,2);
  DECLARE VARIABLE V_VALOR_TOTAL NUMERIC(14,2);
  DECLARE VARIABLE V_USAR_ISS VARCHAR(3);
  DECLARE VARIABLE V_COBRAR_ISS_USUARIO VARCHAR(3);
  DECLARE VARIABLE V_PERCENTUAL_ISS NUMERIC(14,2);
  DECLARE VARIABLE V_UF VARCHAR(5);
  DECLARE VARIABLE V_PERC_FUNDO_EST NUMERIC(14,2);
BEGIN
  VALOR_EMOLUMENTO = 0;
  VALOR_TAXA_JUDICIARIA = 0;
  VALOR_FUNDO_RI = 0;
  VALOR_TOTAL = 0;
  VALOR_ISS = 0;
  IF (COALESCE(:V_EMOLUMENTO_PERIODO_ID,0) > 0) THEN
  BEGIN 
    SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0), 
      CODIGO_SELO, CODIGO_TABELA, EMOLUMENTO_ITEM_ID
    FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID, :V_EMOLUMENTO_PERIODO_ID, :V_VALOR_DOCUMENTO)
    INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI, 
      :CODIGO_SELO, :CODIGO_TABELA, :EMOLUMENTO_ITEM_ID;
    
    VALOR_EMOLUMENTO = COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE,0);
    VALOR_TAXA_JUDICIARIA = COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE,0);
    VALOR_FUNDO_RI = COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE,0);
    
    IF (COALESCE(:V_QUANTIDADE_BUSCA,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_BUSCA, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
    END
    IF (COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_FOLHA_EXCEDENTE, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
    END
    IF (COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRESCIDOS, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_ATOS_ACRESCIDOS = (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0));

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + COALESCE(:VALOR_ATOS_ACRESCIDOS,0);
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0));
    END
    IF (COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRES_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_ATO_COMPLEMENTO = (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0));

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + COALESCE(:VALOR_ATO_COMPLEMENTO,0);
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0));      
    END        
    IF (COALESCE(:V_QUANTIDADE_QUESITOS,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_QUESITOS,0));
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_QUESITOS,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_QUESITOS,0));      
    END        
    IF (COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0));
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0));      
    END    

    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'USAR_ISS', 5) INTO :V_USAR_ISS;
    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'COBRAR_ISS_USUARIO', 5) INTO :V_COBRAR_ISS_USUARIO;
    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'PERCENTUAL_ISS', 5) INTO :V_PERCENTUAL_ISS;
    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'CARTORIO', 'UF', 1) INTO :V_UF;
    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'PERCENTUAL_FUNDOS_ESTADUAIS', 5) INTO :V_PERC_FUNDO_EST;

    IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
    BEGIN
      IF (COALESCE(VALOR_EMOLUMENTO,0) > 0) THEN
      BEGIN
        IF (COALESCE(:V_UF,'') = 'GO') THEN      
        BEGIN
          IF (COALESCE(VALOR_FUNDO_RI,0) > 0) THEN
          BEGIN
            VALOR_ISS = ((COALESCE(VALOR_EMOLUMENTO,0)) - (VALOR_FUNDO_RI)) * (V_PERCENTUAL_ISS/100);
          END
          ELSE
          BEGIN
            VALOR_ISS = (COALESCE(VALOR_EMOLUMENTO,0)) * (V_PERCENTUAL_ISS/100);
          END          
        END
        ELSE
        BEGIN
          VALOR_ISS =  (COALESCE(VALOR_EMOLUMENTO,0) + COALESCE(VALOR_FUNDO_RI,0)) * (V_PERCENTUAL_ISS/100);
        END
      END
    END    

    VALOR_TOTAL = COALESCE(VALOR_EMOLUMENTO,0) + COALESCE(VALOR_TAXA_JUDICIARIA,0) + COALESCE(VALOR_ISS,0);
    VALOR_TOTAL = CAST(:VALOR_TOTAL AS NUMERIC(14,2));
  END      
  SUSPEND;
END ^

ALTER PROCEDURE R_CALCULAR_EMOLUMENTO_OLD_ISS (V_EMOLUMENTO_ID INTEGER,
V_QUANTIDADE INTEGER,
V_EMOLUMENTO_PERIODO_ID INTEGER,
V_VALOR_DOCUMENTO NUMERIC(14, 2),
V_QUANTIDADE_BUSCA INTEGER,
V_EMOLUMENTO_ID_BUSCA INTEGER,
V_QUANTIDADE_FOLHA_EXCEDENTE INTEGER,
V_EMOLUMENTO_ID_FOLHA_EXCEDENTE INTEGER,
V_QUANTIDADE_ATOS_ACRESCIDOS INTEGER,
V_QUANTIDADE_QUESITOS INTEGER,
V_EMOLUMENTO_ID_ATOS_ACRESCIDOS INTEGER,
V_EMOLUMENTO_ID_QUESITOS INTEGER,
V_QUANTIDADE_ATOS_ACRES_COMP INTEGER,
V_QUANTIDADE_QUESITOS_COMP INTEGER,
V_EMOLUMENTO_ID_ATOS_ACRES_COMP INTEGER,
V_EMOLUMENTO_ID_QUESITOS_COMP INTEGER)
RETURNS (VALOR_FUNDO_SELO NUMERIC(15, 2),
VALOR_EMOLUMENTO NUMERIC(14, 2),
VALOR_TAXA_JUDICIARIA NUMERIC(14, 2),
VALOR_FUNDO_RI NUMERIC(14, 2),
VALOR_TOTAL NUMERIC(14, 2),
CODIGO_SELO VARCHAR(30) CHARACTER SET ISO8859_1,
CODIGO_TABELA VARCHAR(30) CHARACTER SET ISO8859_1,
EMOLUMENTO_ITEM_ID INTEGER,
VALOR_ISS NUMERIC(14, 2),
VALOR_ATOS_ACRESCIDOS NUMERIC(14, 2),
VALOR_ATO_COMPLEMENTO NUMERIC(14, 2))
AS 
DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(14,2);
  DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(14,2);  
  DECLARE VARIABLE V_VALOR_FUNDO_RI NUMERIC(14,2);
  DECLARE VARIABLE V_VALOR_TOTAL NUMERIC(14,2);
  DECLARE VARIABLE V_USAR_ISS VARCHAR(3);
  DECLARE VARIABLE V_COBRAR_ISS_USUARIO VARCHAR(3);
  DECLARE VARIABLE V_PERCENTUAL_ISS NUMERIC(14,2);
  DECLARE VARIABLE V_UF VARCHAR(5);
  DECLARE VARIABLE V_PERC_FUNDO_EST NUMERIC(14,2);
BEGIN
  VALOR_EMOLUMENTO = 0;
  VALOR_TAXA_JUDICIARIA = 0;
  VALOR_FUNDO_RI = 0;
  VALOR_TOTAL = 0;
  VALOR_ISS = 0;
  IF (COALESCE(:V_EMOLUMENTO_PERIODO_ID,0) > 0) THEN
  BEGIN 
    SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0), 
      CODIGO_SELO, CODIGO_TABELA, EMOLUMENTO_ITEM_ID
    FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID, :V_EMOLUMENTO_PERIODO_ID, :V_VALOR_DOCUMENTO)
    INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI, 
      :CODIGO_SELO, :CODIGO_TABELA, :EMOLUMENTO_ITEM_ID;
    
    VALOR_EMOLUMENTO = COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE,0);
    VALOR_TAXA_JUDICIARIA = COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE,0);
    VALOR_FUNDO_RI = COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE,0);
    
    IF (COALESCE(:V_QUANTIDADE_BUSCA,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_BUSCA, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_BUSCA,0));
    END
    IF (COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_FOLHA_EXCEDENTE, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0));
    END
    IF (COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRESCIDOS, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_ATOS_ACRESCIDOS = (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0));

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + COALESCE(:VALOR_ATOS_ACRESCIDOS,0);
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0));
    END
    IF (COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRES_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_ATO_COMPLEMENTO = (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0));

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + COALESCE(:VALOR_ATO_COMPLEMENTO,0);
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_ATOS_ACRES_COMP,0));      
    END        
    IF (COALESCE(:V_QUANTIDADE_QUESITOS,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_QUESITOS,0));
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_QUESITOS,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_QUESITOS,0));      
    END        
    IF (COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0) > 0) THEN  
    BEGIN
      SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), COALESCE(VALOR_FUNDO_RI,0)
      FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
      INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_FUNDO_RI;

      VALOR_EMOLUMENTO = :VALOR_EMOLUMENTO + (COALESCE(:V_VALOR_EMOLUMENTO,0) * COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0));
      VALOR_TAXA_JUDICIARIA = :VALOR_TAXA_JUDICIARIA + (COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) * COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0));
      VALOR_FUNDO_RI = :VALOR_FUNDO_RI + (COALESCE(:V_VALOR_FUNDO_RI,0) * COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0));      
    END    

    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'USAR_ISS', 5) INTO :V_USAR_ISS;
    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'COBRAR_ISS_USUARIO', 5) INTO :V_COBRAR_ISS_USUARIO;
    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'PERCENTUAL_ISS', 5) INTO :V_PERCENTUAL_ISS;
    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'CARTORIO', 'UF', 1) INTO :V_UF;
    SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'PERCENTUAL_FUNDOS_ESTADUAIS', 5) INTO :V_PERC_FUNDO_EST;

    VALOR_TOTAL = COALESCE(VALOR_EMOLUMENTO,0) + COALESCE(VALOR_TAXA_JUDICIARIA,0);
    VALOR_TOTAL = CAST(:VALOR_TOTAL AS NUMERIC(14,2));
  END      
  SUSPEND;
END ^

ALTER PROCEDURE R_CALCULA_CREDITO_DEBITO (V_TIPO_SERVICO VARCHAR(5) CHARACTER SET ISO8859_1,
V_CHAVE_SERVICO VARCHAR(15) CHARACTER SET ISO8859_1,
V_DEVOLUCAO75 VARCHAR(10) CHARACTER SET ISO8859_1,
V_DEVOLUCAO100 VARCHAR(10) CHARACTER SET ISO8859_1,
V_DEVOLUCAOTJDFT VARCHAR(10) CHARACTER SET ISO8859_1,
V_DEVOLUCAOAPRESENTANTE VARCHAR(10) CHARACTER SET ISO8859_1)
RETURNS (CREDITO NUMERIC(18, 2),
DEBITO NUMERIC(18, 2),
DEVOLVEU_75_OU_100 VARCHAR(1) CHARACTER SET ISO8859_1,
DEVOLVEU_TJDFT VARCHAR(1) CHARACTER SET ISO8859_1,
DEVOLVEU_APRESENTANTE VARCHAR(1) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_DEVOLUCAO VARCHAR(10);
  DECLARE VARIABLE V_PEDIDO_ID INTEGER;
  DECLARE VARIABLE V_TIPO_PROTOCOLO VARCHAR(3);
  DECLARE VARIABLE V_PROTOCOLO_ID INTEGER;
  DECLARE VARIABLE V_CREDITO NUMERIC(18,2);
  DECLARE VARIABLE V_DEBITO NUMERIC(18,2);
BEGIN
  --INICIALIZAR VARIAVEIS
  CREDITO = 0;
  DEBITO = 0;  
  DEVOLVEU_75_OU_100 = 'N';
  DEVOLVEU_TJDFT = 'N';
  DEVOLVEU_APRESENTANTE = 'N';  

  --Pegar pedido_id
  SELECT PEDIDO_ID FROM R_PROTOCOLO 
  WHERE TIPO_PROTOCOLO = :V_TIPO_SERVICO
  AND PROTOCOLO_ID = :V_CHAVE_SERVICO
  INTO :V_PEDIDO_ID;
  
  FOR SELECT TIPO_PROTOCOLO, PROTOCOLO_ID FROM R_PROTOCOLO
      WHERE PEDIDO_ID = :V_PEDIDO_ID 
      INTO :V_TIPO_PROTOCOLO, V_PROTOCOLO_ID DO
  BEGIN    
    --Calculando os Creditos
    SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
    WHERE TIPO_SERVICO = :V_TIPO_PROTOCOLO
    AND CHAVE_SERVICO = :V_PROTOCOLO_ID
    AND TIPO_TRANSACAO = 'C'
    INTO :V_CREDITO;
    CREDITO = :CREDITO + COALESCE(:V_CREDITO,0);

    --Calculando os Debitos
    SELECT SUM(VALOR_PAGO) FROM C_CAIXA_ITEM
    WHERE TIPO_SERVICO = :V_TIPO_PROTOCOLO
    AND CHAVE_SERVICO = :V_PROTOCOLO_ID
    AND TIPO_TRANSACAO = 'D'
    INTO :V_DEBITO;
    DEBITO = :DEBITO + COALESCE(:V_DEBITO,0);

    FOR SELECT CAST(CAIXA_SERVICO_ID AS INTEGER) FROM C_CAIXA_ITEM
        WHERE TIPO_SERVICO = :V_TIPO_PROTOCOLO
        AND CHAVE_SERVICO = :V_PROTOCOLO_ID
        AND TIPO_TRANSACAO = 'D'
        INTO :V_DEVOLUCAO DO
    BEGIN
      IF (:V_DEVOLUCAO = :V_DEVOLUCAO75) THEN
        DEVOLVEU_75_OU_100 = 'S';
      IF (:V_DEVOLUCAO = :V_DEVOLUCAO100) THEN
        DEVOLVEU_75_OU_100 = 'S';
      IF (:V_DEVOLUCAO = :V_DEVOLUCAOTJDFT) THEN
        DEVOLVEU_TJDFT = 'S';
      IF (:V_DEVOLUCAO = :V_DEVOLUCAOAPRESENTANTE) THEN
        DEVOLVEU_APRESENTANTE = 'S';
    END
  END
  SUSPEND;
END ^

ALTER PROCEDURE R_CANCELAR_PROTOCOLOS (V_QTDE_DIAS_PROCESSAR INTEGER,
V_TIPO_ANDAMENTO_CANCELAMENTO INTEGER,
V_TIPO_ANDAMENTO_CANCEL_EXAME INTEGER,
V_TIPO_ANDAMENTO_REENTRADA INTEGER)
RETURNS (QTDE_PROTOCOLO_CANCELADO INTEGER,
PROTOCOLO INTEGER,
DATA_PROTOCOLO DATE)
AS 
DECLARE VARIABLE V_PEDIDO_ID INTEGER;
  DECLARE VARIABLE V_DATA_PROTOCOLO DATE;
  DECLARE VARIABLE V_DATA_REENTRADA DATE;
  DECLARE VARIABLE V_DATA_CONTAGEM_INI DATE;
  DECLARE VARIABLE V_QTDE INTEGER;
  DECLARE VARIABLE I INTEGER;
  DECLARE VARIABLE V_PODE_CANCELAR INTEGER;
  declare variable V_PROTOCOLO integer;  
  declare variable V_TIPO_AND_AVISO_INDISP integer;
  declare variable V_TIPO_AND_AVISO_INDISP_str VARCHAR(10);
  declare variable V_DATA_AVISO DATE;
  declare variable V_QTDE_DIA_CANCELAMENTO INTEGER;
BEGIN
  PROTOCOLO = null;
  DATA_PROTOCOLO = null;
  QTDE_PROTOCOLO_CANCELADO = 1;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO', 'ANDAMENTO', 'TIPO_ANDAMENTO_AVISO_INDISPONIBILIDADE', 1) INTO :V_TIPO_AND_AVISO_INDISP_STR;
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PROTOCOLO', 'CANCELAMENTO_AUTOMATICO', 'CANCELAR_NO_DIA', 1) INTO :V_QTDE_DIA_CANCELAMENTO;

  if (COALESCE(:V_TIPO_AND_AVISO_INDISP_STR,'') <> '') then
  begin
    V_TIPO_AND_AVISO_INDISP = CAST(:V_TIPO_AND_AVISO_INDISP_STR AS INTEGER);
  end
  else
  begin
    V_TIPO_AND_AVISO_INDISP = 0;
  end

  if (COALESCE(:V_QTDE_DIA_CANCELAMENTO,0) = 0) then
  begin
    V_QTDE_DIA_CANCELAMENTO = 31;
  end

  --PROCESSAR PROTOCOLOS
  FOR SELECT PR.PEDIDO_ID, CAST(PR.DATA AS DATE), PR.NUMERO_ORDEM
      FROM R_PROTOCOLO PR
      WHERE PR.TIPO_PROTOCOLO = '1'
      AND PR.DATA < (CAST(CURRENT_TIMESTAMP AS DATE) - 29)
      AND PR.DATA > (CAST(CURRENT_TIMESTAMP AS DATE) - :V_QTDE_DIAS_PROCESSAR) 
      AND (SELECT COUNT(*) FROM R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO T 
           WHERE A.TB_TIPO_ANDAMENTO_ID = T.TB_TIPO_ANDAMENTO_ID 
           AND A.PEDIDO_ID = PR.PEDIDO_ID
           AND (T.TIPO ='N' OR T.TIPO = 'C' OR T.TIPO = 'R')) = 0
      AND (SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
           WHERE I.natureza_titulo_id = N.natureza_titulo_id
           AND I.PEDIDO_ID = PR.PEDIDO_ID
           AND N.nao_cancelar_automatico = 'S') = 0
      INTO :V_PEDIDO_ID, :V_DATA_PROTOCOLO, :V_PROTOCOLO  DO
  BEGIN
    --INICIA A CONTAGEM APARTIR DO PROXIMO DIA UTIL
    V_DATA_CONTAGEM_INI = :V_DATA_PROTOCOLO + 1; 

    --verificar se existe protocolo com aviso de indisponibilidade
    V_DATA_AVISO = NULL;
    if (coalesce(:V_TIPO_AND_AVISO_INDISP,'') <> '') then
    begin
      select count(*) FROM R_ANDAMENTO
      WHERE PEDIDO_ID = :V_PEDIDO_ID
      AND tb_tipo_andamento_id = :V_TIPO_AND_AVISO_INDISP
      INTO :V_QTDE;
      if (coalesce(:V_QTDE,0)>0) then
      begin
        select cast(data as date) FROM R_ANDAMENTO
        WHERE PEDIDO_ID = :V_PEDIDO_ID
        AND tb_tipo_andamento_id = :V_TIPO_AND_AVISO_INDISP
        INTO :V_DATA_AVISO;
        V_DATA_CONTAGEM_INI = :V_DATA_AVISO + 1;
      end
    end
    V_PODE_CANCELAR = 0;
    I = 1;
    WHILE (I = 1) DO
    BEGIN 
      SELECT COUNT(*) FROM G_FERIADO
      WHERE SITUACAO = 'A'
      AND DATA BETWEEN CAST(:V_DATA_CONTAGEM_INI AS TIMESTAMP) AND CAST(:V_DATA_CONTAGEM_INI AS TIMESTAMP) + 0.9999
      INTO :V_QTDE;
      IF ((EXTRACT(WEEKDAY FROM :V_DATA_CONTAGEM_INI) IN (0,6)) OR (:V_QTDE > 0)) THEN --DOMINGO E SABADO OU FERIADO
      BEGIN                                
        V_DATA_CONTAGEM_INI = :V_DATA_CONTAGEM_INI + 1;
        I = 1;
      END
      ELSE
      BEGIN
        I = 0;
      END      
    END
    IF (CAST(CURRENT_TIMESTAMP AS DATE) >= (:V_DATA_CONTAGEM_INI + (V_QTDE_DIA_CANCELAMENTO - 1))) THEN -- PODE CONTINUAR VERIFICANDO SE PODE CANCELAR
    BEGIN        
      V_DATA_REENTRADA = NULL;
      --VERIFICAR SE EXISTE REENTRADA
      SELECT MAX(DATA) FROM R_ANDAMENTO A 
      WHERE A.PEDIDO_ID = :V_PEDIDO_ID 
      AND A.TB_TIPO_ANDAMENTO_ID = :V_TIPO_ANDAMENTO_REENTRADA
      INTO :V_DATA_REENTRADA; 
      
      IF (COALESCE(:V_DATA_REENTRADA,'') = '') THEN
      BEGIN
        V_PODE_CANCELAR = 1;
      END
      ELSE
      BEGIN
        V_QTDE = (CAST(CURRENT_TIMESTAMP AS DATE) - CAST(:V_DATA_REENTRADA AS DATE));
        IF (:V_QTDE > 15) THEN --Se ja houver mais de 15 dias que houve reentrada, executa o cancelamento  
        BEGIN
          V_PODE_CANCELAR = 1;
        END
        ELSE
        BEGIN
          IF ((CAST(CURRENT_TIMESTAMP AS DATE) - :V_DATA_CONTAGEM_INI) > 45) THEN
          BEGIN
            V_PODE_CANCELAR = 1;
          END
        END
      END
        
      IF (:V_PODE_CANCELAR = 1) THEN --PODE CANCELAR
      BEGIN
        INSERT INTO R_ANDAMENTO(ANDAMENTO_ID, PEDIDO_ID, DATA, DATA_INCLUSAO, USUARIO_ID, TB_TIPO_ANDAMENTO_ID)
        VALUES((SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('R_ANDAMENTO')),:V_PEDIDO_ID, 
          CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 123456, :V_TIPO_ANDAMENTO_CANCELAMENTO);
        
        protocolo = :V_PROTOCOLO;
        data_protocolo = :v_data_protocolo;
        SUSPEND;        
      END        
    END
  END
END ^

ALTER PROCEDURE R_CANCELAR_PROTOCOLOS_MP1805 (V_QTDE_DIAS_PROCESSAR INTEGER,
V_TIPO_ANDAMENTO_CANCELAMENTO INTEGER,
V_TIPO_ANDAMENTO_CANCEL_EXAME INTEGER,
V_TIPO_ANDAMENTO_REENTRADA INTEGER)
RETURNS (QTDE_PROTOCOLO_CANCELADO INTEGER,
PROTOCOLO INTEGER,
DATA_PROTOCOLO DATE)
AS 
DECLARE VARIABLE V_PEDIDO_ID INTEGER;
  DECLARE VARIABLE V_DATA_PROTOCOLO DATE;
  DECLARE VARIABLE V_DATA_REENTRADA DATE;
  DECLARE VARIABLE V_DATA_CONTAGEM_INI DATE;
  DECLARE VARIABLE V_QTDE INTEGER;
  DECLARE VARIABLE I INTEGER;
  DECLARE VARIABLE V_PODE_CANCELAR INTEGER;
  declare variable V_PROTOCOLO integer;  
  declare variable V_TIPO_AND_AVISO_INDISP integer;
  declare variable V_TIPO_AND_AVISO_INDISP_str VARCHAR(10);
  declare variable V_DATA_AVISO DATE;
  declare variable V_QTDE_DIA_CANCELAMENTO INTEGER;
  declare variable V_QTDE_UTIL INTEGER;
  declare variable v_data_temp varchar(20);
BEGIN
  --CANCELAMENTO COM 20 DIAS UTEIS CONFORME MEDIDA PROVISORIA 1805

  PROTOCOLO = null;
  DATA_PROTOCOLO = null;
  QTDE_PROTOCOLO_CANCELADO = 1;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO', 'ANDAMENTO', 'TIPO_ANDAMENTO_AVISO_INDISPONIBILIDADE', 1) INTO :V_TIPO_AND_AVISO_INDISP_STR;

  if (COALESCE(:V_TIPO_AND_AVISO_INDISP_STR,'') <> '') then
  begin
    V_TIPO_AND_AVISO_INDISP = CAST(:V_TIPO_AND_AVISO_INDISP_STR AS INTEGER);
  end
  else
  begin
    V_TIPO_AND_AVISO_INDISP = 0;
  end

  -- calcular 20 dias uteis
  V_QTDE_DIA_CANCELAMENTO = 0;
  V_QTDE_UTIL = 0;
  V_DATA_CONTAGEM_INI = current_date - 1;
  WHILE (:V_QTDE_UTIL < 20) DO
  BEGIN
    SELECT COUNT(*) FROM G_FERIADO
    WHERE SITUACAO = 'A'
    AND CAST(DATA AS DATE) = :V_DATA_CONTAGEM_INI
    INTO :V_QTDE;

    --verificar se tem feriados fixos
    if (coalesce(:V_QTDE,0) = 0) then
    begin
      v_data_temp = extract(day from :V_DATA_CONTAGEM_INI)||'/'||extract(month from :V_DATA_CONTAGEM_INI);
      if ((:v_data_temp = '1/1') or
        (:v_data_temp = '21/4') or
        (:v_data_temp = '1/5') or
        (:v_data_temp = '7/9') or
        (:v_data_temp = '12/10') or
        (:v_data_temp = '2/11') or
        (:v_data_temp = '15/11') or
        (:v_data_temp = '20/11') or
        (:v_data_temp = '24/12') or
        (:v_data_temp = '25/12') or
        (:v_data_temp = '31/12')) then
      begin
        v_qtde = 1;
      end
    end

    --verificar se eh sabado ou domingo
    if (coalesce(:V_QTDE,0) = 0) then
    begin
      v_data_temp = extract(WEEKDAY from :V_DATA_CONTAGEM_INI);
      if ((:v_data_temp = '0') or
        (:v_data_temp = '6')) then
      begin
        v_qtde = 1;
      end
    end

    IF (:V_QTDE = 0) THEN --se não for DOMINGO E SABADO OU FERIADO
    BEGIN
      V_QTDE_UTIL = :V_QTDE_UTIL + 1;
    END

    V_DATA_CONTAGEM_INI = :V_DATA_CONTAGEM_INI - 1;
    V_QTDE_DIA_CANCELAMENTO = :V_QTDE_DIA_CANCELAMENTO + 1;
  END

  --PROCESSAR PROTOCOLOS
  FOR SELECT PR.PEDIDO_ID, CAST(PR.DATA AS DATE), PR.NUMERO_ORDEM
      FROM R_PROTOCOLO PR
      WHERE PR.TIPO_PROTOCOLO = '1'
      AND PR.DATA < (CAST(CURRENT_TIMESTAMP AS DATE) - :V_QTDE_DIA_CANCELAMENTO)
      AND PR.DATA > (CAST(CURRENT_TIMESTAMP AS DATE) - :V_QTDE_DIAS_PROCESSAR) 
      AND (SELECT COUNT(*) FROM R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO T 
           WHERE A.TB_TIPO_ANDAMENTO_ID = T.TB_TIPO_ANDAMENTO_ID 
           AND A.PEDIDO_ID = PR.PEDIDO_ID
           AND (T.TIPO ='N' OR T.TIPO = 'C' OR T.TIPO = 'R')) = 0
      AND (SELECT COUNT(*) FROM R_PEDIDO_ITEM I, G_NATUREZA_TITULO N
           WHERE I.natureza_titulo_id = N.natureza_titulo_id
           AND I.PEDIDO_ID = PR.PEDIDO_ID
           AND N.nao_cancelar_automatico = 'S') = 0
      INTO :V_PEDIDO_ID, :V_DATA_PROTOCOLO, :V_PROTOCOLO  DO
  BEGIN
    --INICIA A CONTAGEM APARTIR DO PROXIMO DIA UTIL
    V_DATA_CONTAGEM_INI = :V_DATA_PROTOCOLO;

    --verificar se existe protocolo com aviso de indisponibilidade
    V_DATA_AVISO = NULL;
    if (coalesce(:V_TIPO_AND_AVISO_INDISP,'') <> '') then
    begin
      select count(*) FROM R_ANDAMENTO
      WHERE PEDIDO_ID = :V_PEDIDO_ID
      AND tb_tipo_andamento_id = :V_TIPO_AND_AVISO_INDISP
      INTO :V_QTDE;
      if (coalesce(:V_QTDE,0)>0) then
      begin
        select cast(data as date) FROM R_ANDAMENTO
        WHERE PEDIDO_ID = :V_PEDIDO_ID
        AND tb_tipo_andamento_id = :V_TIPO_AND_AVISO_INDISP
        INTO :V_DATA_AVISO;
        V_DATA_CONTAGEM_INI = :V_DATA_AVISO;
      end
    end
    V_PODE_CANCELAR = 0;

    IF (CAST(CURRENT_TIMESTAMP AS DATE) >= (:V_DATA_CONTAGEM_INI + (V_QTDE_DIA_CANCELAMENTO - 1))) THEN -- PODE CONTINUAR VERIFICANDO SE PODE CANCELAR
    BEGIN        
      V_DATA_REENTRADA = NULL;
      --VERIFICAR SE EXISTE REENTRADA
      SELECT MAX(DATA) FROM R_ANDAMENTO A 
      WHERE A.PEDIDO_ID = :V_PEDIDO_ID 
      AND A.TB_TIPO_ANDAMENTO_ID = :V_TIPO_ANDAMENTO_REENTRADA
      INTO :V_DATA_REENTRADA; 
      
      IF (COALESCE(:V_DATA_REENTRADA,'') = '') THEN
      BEGIN
        V_PODE_CANCELAR = 1;
      END
      ELSE
      BEGIN
        V_QTDE = (CAST(CURRENT_TIMESTAMP AS DATE) - CAST(:V_DATA_REENTRADA AS DATE));
        IF (:V_QTDE > 10) THEN --Se ja houver mais de 10 dias que houve reentrada, executa o cancelamento
        BEGIN
          V_PODE_CANCELAR = 1;
        END
        ELSE
        BEGIN
          IF ((CAST(CURRENT_TIMESTAMP AS DATE) - :V_DATA_CONTAGEM_INI) > 45) THEN
          BEGIN
            V_PODE_CANCELAR = 1;
          END
        END
      END
        
      IF (:V_PODE_CANCELAR = 1) THEN --PODE CANCELAR
      BEGIN
        INSERT INTO R_ANDAMENTO(ANDAMENTO_ID, PEDIDO_ID, DATA, DATA_INCLUSAO, USUARIO_ID, TB_TIPO_ANDAMENTO_ID)
        VALUES((SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('R_ANDAMENTO')),:V_PEDIDO_ID,
          CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 123456, :V_TIPO_ANDAMENTO_CANCELAMENTO);
        
        protocolo = :V_PROTOCOLO;
        data_protocolo = :v_data_protocolo;
        SUSPEND;        
      END        
    END
  END
END ^

ALTER PROCEDURE R_CONSISTENCIA_IMOVEL (V_CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1,
V_TIPO_REGISTRO VARCHAR(3) CHARACTER SET ISO8859_1,
V_NUMERO_REGISTRO VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_REGISTRO_LETRA VARCHAR(5) CHARACTER SET ISO8859_1,
V_USAR_CADASTRO_ONUS VARCHAR(3) CHARACTER SET ISO8859_1 DEFAULT 'S')
RETURNS (IMOVEL_ID INTEGER,
SITUACAO VARCHAR(3) CHARACTER SET ISO8859_1,
QTDE_PROTOCOLO_ANDAMENTO INTEGER,
QTDE_HISTORICO_ONUS INTEGER,
POSSUI_INDISPONIBILIDADE VARCHAR(1) CHARACTER SET ISO8859_1,
POSSUI_ONUS VARCHAR(1) CHARACTER SET ISO8859_1,
ONUS_CONFERIDO VARCHAR(1) CHARACTER SET ISO8859_1,
ONUS_ULTIMO_ATO_VERIFICADO VARCHAR(10) CHARACTER SET ISO8859_1,
ONUS_ULTIMO_ATO_VERIFICADO_NUM INTEGER,
LISTA_PROTOCOLOS_ANDAMENTO VARCHAR(5000) CHARACTER SET ISO8859_1,
LISTA_ONUS VARCHAR(5000) CHARACTER SET ISO8859_1,
LISTA_INCONSISTENCIA VARCHAR(5000) CHARACTER SET ISO8859_1)
AS 
DECLARE V_SQL VARCHAR(5000);
  DECLARE V_SQL2 VARCHAR(5000);
  DECLARE VARIABLE V_PEDIDO_ID INTEGER;  
  DECLARE VARIABLE V_NUMERO_ORDEM INTEGER;
  DECLARE VARIABLE V_DATA DATE;
  DECLARE VARIABLE V_USAR_MULTIPLOS_CARTORIOS VARCHAR(3);
--  declare variable V_NATUREZAS VARCHAR(1000);
  declare variable V_NATUREZAS VARCHAR(5000);
  declare variable V_DESCRICAO_NATUREZA VARCHAR(120);
  declare variable V_USAR_ANDAMENTO_EXTRA_PARA_LIBERACAO varchar(10);
  declare variable V_TIPO_ANDAMENTO_EXTRA_LIBERACAO varchar(10);
  declare variable V_DATA_INICIAL_ANDAMENTO_EXTRA varchar(20);
  declare variable V_DESC_ANDAMENTO_EXTRA_LIBERACAO varchar(120);
  declare variable V_QTDE_ANDAMENTO_EXTRA integer;
  declare variable V_MENSAGEM VARCHAR(1000);
  declare variable V_NUMERO_LETRA VARCHAR(5);
  declare variable V_CARTORIO_TEMP VARCHAR(5);
BEGIN
  LISTA_INCONSISTENCIA = NULL;
  V_NATUREZAS = NULL;
  --VERIFICAR SE REGISTRO EXISTE
  V_SQL = ' SELECT FIRST 1 IMOVEL_ID, SITUACAO FROM R_IMOVEL 
            WHERE TIPO_REGISTRO = '||''''||:V_TIPO_REGISTRO||''''||
          ' AND NUMERO = '||:V_NUMERO_REGISTRO;
  IF (COALESCE(:V_CARTORIO,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND CARTORIO = '||''''||:V_CARTORIO||'''';    
  END
  IF (COALESCE(:V_NUMERO_REGISTRO_LETRA,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND NUMERO_LETRA = '||''''||:V_NUMERO_REGISTRO_LETRA||'''';    
  END 
  ELSE
  BEGIN
    V_SQL = :V_SQL || ' AND (COALESCE(NUMERO_LETRA,'||''''||''''||') = '||''''||''''|| ' OR NUMERO_LETRA = '||''''||'#'||''''||') ';
  END 
  EXECUTE STATEMENT V_SQL INTO :IMOVEL_ID, :SITUACAO;
  IMOVEL_ID = COALESCE(:IMOVEL_ID, 0);
  IF (:IMOVEL_ID = 0) THEN
  BEGIN
    IF (COALESCE(:LISTA_INCONSISTENCIA,'') = '') THEN
    BEGIN
      LISTA_INCONSISTENCIA = '* Imóvel não encontrado.';
    END
    ELSE
    BEGIN
      LISTA_INCONSISTENCIA = SUBSTRING(:LISTA_INCONSISTENCIA||ASCII_CHAR(13)||'* Imóvel não encontrado.' FROM 1 FOR 5000);
    END  
  
    SUSPEND;
  END
  ELSE
  BEGIN  
    IF (:SITUACAO = 'E') THEN --ENCERRADO
    BEGIN
      IF (COALESCE(:LISTA_INCONSISTENCIA,'') = '') THEN
      BEGIN
        LISTA_INCONSISTENCIA = '* Imóvel ENCERRADO.';
      END
      ELSE
      BEGIN
        LISTA_INCONSISTENCIA = SUBSTRING(:LISTA_INCONSISTENCIA||ASCII_CHAR(13)||'* Imóvel ENCERRADO.' FROM 1 FOR 5000);
      END      
    END
    IF (:SITUACAO = 'C') THEN --CANCELADO
    BEGIN
      IF (COALESCE(:LISTA_INCONSISTENCIA,'') = '') THEN
      BEGIN
        LISTA_INCONSISTENCIA = '* Imóvel CANCELADO.';
      END
      ELSE
      BEGIN
        LISTA_INCONSISTENCIA = SUBSTRING(:LISTA_INCONSISTENCIA||ASCII_CHAR(13)||'* Imóvel CANCELADO.' FROM 1 FOR 5000);
      END      
    END
  
    --VERIFICAR SE EXISTEM PROTOCOLOS EM ANDAMENTO
    V_USAR_MULTIPLOS_CARTORIOS = (SELECT COALESCE(VALOR_PARAMETRO,'') FROM G_BUSCAR_CONFIG('REAL','GERAL','USAR_MULTIPLOS_CARTORIOS',1));
    LISTA_PROTOCOLOS_ANDAMENTO = NULL;
    IF (:V_USAR_MULTIPLOS_CARTORIOS = 'S') THEN
    BEGIN
      V_SQL = ' SELECT COUNT(*) FROM R_PROTOCOLOS_VINCULADOS_CART('||''''||:V_CARTORIO||''''||','||''''||:V_TIPO_REGISTRO||''''||','||
        ''''||:V_NUMERO_REGISTRO||''''||','||''''||COALESCE(:V_NUMERO_REGISTRO_LETRA,'')||''''||','||
        ''''||''''||','||''''||'A'||''''||') WHERE TIPO_PROTOCOLO = 1 ';
    END
    ELSE
    BEGIN
      V_SQL = ' SELECT COUNT(*) FROM R_PROTOCOLOS_VINCULADOS('||''''||:V_TIPO_REGISTRO||''''||','||
        ''''||:V_NUMERO_REGISTRO||''''||','||''''||COALESCE(:V_NUMERO_REGISTRO_LETRA,'')||''''||','||
        ''''||''''||','||''''||'A'||''''||') WHERE TIPO_PROTOCOLO = 1 ';    
    END
    EXECUTE STATEMENT V_SQL INTO :QTDE_PROTOCOLO_ANDAMENTO;
    IF (:QTDE_PROTOCOLO_ANDAMENTO > 0) THEN
    BEGIN
      LISTA_PROTOCOLOS_ANDAMENTO = 'Existe(m) protocolo(s) em andamento: ';
      IF (:V_USAR_MULTIPLOS_CARTORIOS = 'S') THEN
      BEGIN      
        V_SQL = ' SELECT DISTINCT PEDIDO_ID FROM R_PROTOCOLOS_VINCULADOS_CART('||''''||:V_CARTORIO||''''||','||''''||:V_TIPO_REGISTRO||''''||','||
          ''''||:V_NUMERO_REGISTRO||''''||','||''''||COALESCE(:V_NUMERO_REGISTRO_LETRA,'')||''''||','||
          ''''||''''||','||''''||'A'||''''||') WHERE TIPO_PROTOCOLO = 1 ';
      END
      ELSE
      BEGIN
        V_SQL = ' SELECT DISTINCT PEDIDO_ID FROM R_PROTOCOLOS_VINCULADOS('||''''||:V_TIPO_REGISTRO||''''||','||
          ''''||:V_NUMERO_REGISTRO||''''||','||''''||COALESCE(:V_NUMERO_REGISTRO_LETRA,'')||''''||','||
          ''''||''''||','||''''||'A'||''''||') WHERE TIPO_PROTOCOLO = 1 ';      
      END      
      FOR EXECUTE STATEMENT V_SQL 
          INTO :V_PEDIDO_ID DO
      BEGIN
        SELECT NUMERO_ORDEM, CAST(DATA AS DATE) FROM R_PROTOCOLO
        WHERE PEDIDO_ID = :V_PEDIDO_ID
        AND TIPO_PROTOCOLO = '1'
        INTO :V_NUMERO_ORDEM, :V_DATA;

        V_NATUREZAS = '';
        V_DESCRICAO_NATUREZA = '';

        V_SQL2 = ' SELECT NT.descricao FROM R_PEDIDO_ITEM PI, G_NATUREZA_TITULO NT, R_PEDIDO_ITEM_NUMERO PN
            WHERE PI.natureza_titulo_id = NT.natureza_titulo_id
            AND PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
            AND PI.pedido_id = '||:V_PEDIDO_ID||' AND PN.NUMERO = '||:V_NUMERO_REGISTRO;

        IF (COALESCE(:V_NUMERO_REGISTRO_LETRA,'') <> '') THEN
        BEGIN
          V_SQL2 = :V_SQL2 || ' AND PN.NUMERO_LETRA = '||''''||COALESCE(:V_NUMERO_REGISTRO_LETRA,'')||'''';
        END 
        ELSE
        BEGIN
          V_SQL2 = :V_SQL2 || ' AND (COALESCE(PN.NUMERO_LETRA,'||''''||''''||') = '||''''||''''|| ' OR PN.NUMERO_LETRA = '||''''||'#'||''''||') ';
        END 

        FOR EXECUTE STATEMENT V_SQL2 INTO :v_descricao_natureza DO
        BEGIN
          IF (COALESCE(:V_NATUREZAS,'') = '') THEN
          BEGIN
            V_NATUREZAS = :v_descricao_natureza;
          END
          ELSE
          BEGIN
            V_NATUREZAS = SUBSTRING(:V_NATUREZAS||','||COALESCE(:v_descricao_natureza,'') FROM 1 FOR 1000);
          END              
        END
        IF (COALESCE(:V_NATUREZAS,'') <> '') THEN
        BEGIN
          V_NATUREZAS = '('||:V_NATUREZAS||') ';
        END

        LISTA_PROTOCOLOS_ANDAMENTO = SUBSTRING(:LISTA_PROTOCOLOS_ANDAMENTO || :V_NUMERO_ORDEM ||:V_NATUREZAS|| ' de ' ||EXTRACT(DAY FROM :V_DATA)||'/'||
          EXTRACT(MONTH FROM :V_DATA)||'/'||EXTRACT(YEAR FROM :V_DATA)||'; ' FROM 1 FOR 5000);
      END    
      
      IF (COALESCE(:LISTA_INCONSISTENCIA,'') = '') THEN
      BEGIN
        LISTA_INCONSISTENCIA = SUBSTRING(LISTA_PROTOCOLOS_ANDAMENTO FROM 1 FOR 5000);
      END
      ELSE
      BEGIN
        LISTA_INCONSISTENCIA = SUBSTRING(:LISTA_INCONSISTENCIA||ASCII_CHAR(13)||LISTA_PROTOCOLOS_ANDAMENTO FROM 1 FOR 5000);
      END              
    END
    
    --VERIFICAR SE EXISTE HISTORICO CADASTRO DE ONUS
    if (:V_USAR_CADASTRO_ONUS = 'S') then
    begin
      SELECT COUNT(*) FROM R_IMOVEL_HISTORICO
      WHERE IMOVEL_ID = :IMOVEL_ID
      AND DATA_CANC IS NULL
      INTO :QTDE_HISTORICO_ONUS;
    
      IF (:QTDE_HISTORICO_ONUS = 0) THEN
      BEGIN
        IF (COALESCE(:LISTA_INCONSISTENCIA,'') = '') THEN
        BEGIN
          LISTA_INCONSISTENCIA = '* Não existe lançamento no cadastro de Ônus';
        END
        ELSE
        BEGIN
          LISTA_INCONSISTENCIA = SUBSTRING(:LISTA_INCONSISTENCIA||ASCII_CHAR(13)||'* Não existe lançamento no cadastro de Ônus' FROM 1 FOR 5000);
        END
      END
    end
        
    --VEFICAR SE POSSUI INDISPONIBILIDADE
    SELECT SIM_NAO FROM R_VERIFICA_SE_TEM_LRI(:IMOVEL_ID,NULL)
    INTO :POSSUI_INDISPONIBILIDADE;
    
    IF (:POSSUI_INDISPONIBILIDADE = 'S') THEN
    BEGIN    
      IF (COALESCE(:LISTA_INCONSISTENCIA,'') = '') THEN
      BEGIN
        LISTA_INCONSISTENCIA = '* Exite(m) indisponibilidade(s) de bens para este Imóvel.';
      END
      ELSE
      BEGIN
        LISTA_INCONSISTENCIA = SUBSTRING(:LISTA_INCONSISTENCIA||ASCII_CHAR(13)||'* Exite(m) indisponibilidade(s) de bens para este Imóvel.' FROM 1 FOR 5000);
      END
    END
    
    --VERIFICAR SE EXISTE ONUS
    LISTA_ONUS = NULL;
    SELECT EXISTE_ONUS, DESCRICAO, CONFERIDO,
      ULTIMO_ATO_VERIFICADO, ULTIMO_ATO_VERIFICADO_NUMERO 
    FROM R_BUSCA_ONUS(:IMOVEL_ID)
    INTO :POSSUI_ONUS, :LISTA_ONUS, :ONUS_CONFERIDO,
      :ONUS_ULTIMO_ATO_VERIFICADO, :ONUS_ULTIMO_ATO_VERIFICADO_NUM;
    IF (:POSSUI_ONUS = 'S') THEN
    BEGIN
      LISTA_ONUS = 'COM ÔNUS --> '||:LISTA_ONUS;
    END
    ELSE
    BEGIN
      LISTA_ONUS = 'SEM ÔNUS --> '||:LISTA_ONUS;
    END
    IF (:ONUS_CONFERIDO = 'N') THEN
    BEGIN
      LISTA_ONUS = :LISTA_ONUS || '(NÃO CONFERIDO)';
    END
    
    IF (:ONUS_CONFERIDO = 'N') THEN
    BEGIN
      IF (COALESCE(:LISTA_INCONSISTENCIA,'') = '') THEN
      BEGIN
        LISTA_INCONSISTENCIA = '* Existe(m) Lançamento(s) de Ônus sem conferir.';
      END
      ELSE
      BEGIN
        LISTA_INCONSISTENCIA = SUBSTRING(:LISTA_INCONSISTENCIA||ASCII_CHAR(13)||'* Existe(m) Lançamento(s) de Ônus sem conferir.' FROM 1 FOR 5000);
      END    
    END


    --VERIFICAR SE ESTA CONTROLANDO POR OUTRO ANDAMENTO ALEM DO REGISTRO, CASO SIM, FAZ A VALIDACAO
    --SOMENTE SE NAO HOUVER PROTOCOLOS EM ANDAMENTO
    IF (COALESCE(:LISTA_PROTOCOLOS_ANDAMENTO,'') = '') THEN
    BEGIN
      V_USAR_MULTIPLOS_CARTORIOS = (SELECT COALESCE(VALOR_PARAMETRO,'') FROM G_BUSCAR_CONFIG('REAL','GERAL','USAR_MULTIPLOS_CARTORIOS',1));
      V_USAR_ANDAMENTO_EXTRA_PARA_LIBERACAO = (SELECT COALESCE(VALOR_PARAMETRO,'') FROM G_BUSCAR_CONFIG('CERTIDAO','CERTIDAO_AUTOMATICA','USAR_ANDAMENTO_EXTRA_PARA_LIBERACAO',1));
      V_TIPO_ANDAMENTO_EXTRA_LIBERACAO = (SELECT COALESCE(VALOR_PARAMETRO,'') FROM G_BUSCAR_CONFIG('CERTIDAO','CERTIDAO_AUTOMATICA','TIPO_ANDAMENTO_EXTRA_LIBERACAO',1));
      V_DATA_INICIAL_ANDAMENTO_EXTRA = (SELECT COALESCE(VALOR_PARAMETRO,'') FROM G_BUSCAR_CONFIG('CERTIDAO','CERTIDAO_AUTOMATICA','DATA_INICIAL_ANDAMENTO_EXTRA',1));

      if ((COALESCE(:V_USAR_ANDAMENTO_EXTRA_PARA_LIBERACAO,'') = 'S') and
        (COALESCE(:V_TIPO_ANDAMENTO_EXTRA_LIBERACAO,'') <> '') and
        (COALESCE(:V_DATA_INICIAL_ANDAMENTO_EXTRA,'') <> '')) then
      begin
        SELECT descricao FROM r_tb_tipo_andamento
        WHERE tb_tipo_andamento_id = :V_TIPO_ANDAMENTO_EXTRA_LIBERACAO
        into :V_DESC_ANDAMENTO_EXTRA_LIBERACAO;

        FOR SELECT DISTINCT PI.PEDIDO_ID, PR.NUMERO_ORDEM, COALESCE(PN.NUMERO_LETRA,''), coalesce(PN.CARTORIO,'')
            FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                   R_PROTOCOLO PR, R_PEDIDO PE
            WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
            AND    PE.PEDIDO_ID = PI.PEDIDO_ID
            AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
            AND    PR.TIPO_PROTOCOLO = 1
            AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
            AND    PN.NUMERO = :V_NUMERO_REGISTRO
            AND    CAST(PR.data AS DATE) >= CAST(:V_DATA_INICIAL_ANDAMENTO_EXTRA AS DATE)
            AND    (SELECT COUNT(*) FROM R_PROTOCOLO_EM_ANDAMENTO WHERE PEDIDO_ID = PE.PEDIDO_ID) = 0
            ORDER BY PR.DATA DESC
            INTO :V_PEDIDO_ID, :V_NUMERO_ORDEM, :V_NUMERO_LETRA, :V_CARTORIO_TEMP DO
        BEGIN
          SELECT COUNT(*) FROM R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
          WHERE A.tb_tipo_andamento_id = TA.tb_tipo_andamento_id
          AND A.PEDIDO_ID = :V_PEDIDO_ID
          AND ((A.tb_tipo_andamento_id = :V_TIPO_ANDAMENTO_EXTRA_LIBERACAO) or (TA.TIPO = 'C'))
          INTO :V_QTDE_ANDAMENTO_EXTRA;

          if (:V_QTDE_ANDAMENTO_EXTRA = 0) then
          begin
            if (coalesce(:V_NUMERO_REGISTRO_LETRA,'') <> '') then
            begin
              if (coalesce(:V_NUMERO_REGISTRO_LETRA,'') <> coalesce(:V_NUMERO_LETRA,'')) then
              begin
                V_QTDE_ANDAMENTO_EXTRA = 1;
              end
            end
            IF (COALESCE(:V_USAR_MULTIPLOS_CARTORIOS,'') = 'S') THEN
            begin
              if (COALESCE(:V_CARTORIO_TEMP,'') <> '') then
              begin
                if (COALESCE(:V_CARTORIO_TEMP,'') <> COALESCE(:V_CARTORIO,'')) then
                begin
                  V_QTDE_ANDAMENTO_EXTRA = 1;
                end
              end
            end
          end
          if (:V_QTDE_ANDAMENTO_EXTRA = 0) then --verificar se permanceceu 0 (zero)
          begin
            V_MENSAGEM = '* Prot. '||:V_NUMERO_ORDEM||' não consta o andamento: '||:V_DESC_ANDAMENTO_EXTRA_LIBERACAO;
            IF (COALESCE(:LISTA_INCONSISTENCIA,'') = '') THEN
            BEGIN
              LISTA_INCONSISTENCIA = :V_MENSAGEM;
            END
            ELSE
            BEGIN
              LISTA_INCONSISTENCIA = SUBSTRING(:LISTA_INCONSISTENCIA||ASCII_CHAR(13)||:V_MENSAGEM FROM 1 FOR 5000);
            END    
          end
        end
      end
    end

    SUSPEND;
  END
END ^

ALTER PROCEDURE R_CONTROLE_INTIMACAO (V_ANDAMENTO_RETORNO_INTIMACAO VARCHAR(15) CHARACTER SET ISO8859_1,
V_ANDAMENTO_RETORNO_EDITAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_ANDAMENTO_FIM_PRAZO_INTIMACAO VARCHAR(15) CHARACTER SET ISO8859_1,
V_ANDAMENTO_FIM_PRAZO_EDITAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO_PESQUISA VARCHAR(5) CHARACTER SET ISO8859_1)
RETURNS (NUMERO_ORDEM NUMERIC(18, 2),
DATA_ANDAMENTO TIMESTAMP,
DESCRICAO_ANDAMENTO VARCHAR(50) CHARACTER SET ISO8859_1,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
ADQUIRENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
PEDIDO_ID NUMERIC(18, 2),
QTDE_DIAS NUMERIC(18, 2),
TB_TIPO_ANDAMENTO_ID NUMERIC(18, 2))
AS 
DECLARE VARIABLE V_ANDAMENTO_ID VARCHAR(20);
DECLARE VARIABLE V_QUANTIDADE INTEGER;
DECLARE VARIABLE V_QUANTIDADE2 INTEGER;
DECLARE VARIABLE V_DATA_ATUAL DATE;
BEGIN
  SELECT CURRENT_DATE FROM RDB$DATABASE
  INTO :V_DATA_ATUAL;

  IF (:V_TIPO_PESQUISA = 'T') THEN
  BEGIN
    FOR SELECT PR.NUMERO_ORDEM,
               A.DATA,
               TA.DESCRICAO,
               PE.APRESENTANTE_NOME,
               PE.ADQUIRENTE_NOME,
               PE.PEDIDO_ID,
               A.ANDAMENTO_ID,
               :V_DATA_ATUAL - CAST(A.DATA AS DATE),
               A.TB_TIPO_ANDAMENTO_ID
            FROM   R_PROTOCOLO PR,
                   R_PEDIDO PE,
                   R_ANDAMENTO A LEFT JOIN R_TB_TIPO_ANDAMENTO TA
                   ON A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
            WHERE  A.PEDIDO_ID = PE.PEDIDO_ID
            AND    PE.PEDIDO_ID = PR.PEDIDO_ID
            AND    (A.TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_RETORNO_INTIMACAO OR
                    A.TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_RETORNO_EDITAL)
            AND    A.DATA BETWEEN (:V_DATA_ATUAL - 90) AND
                                  (:V_DATA_ATUAL + 0.9999)
            ORDER BY A.DATA, PR.NUMERO_ORDEM
    INTO    :NUMERO_ORDEM, :DATA_ANDAMENTO, :DESCRICAO_ANDAMENTO, :APRESENTANTE_NOME,
            :ADQUIRENTE_NOME, :PEDIDO_ID, :V_ANDAMENTO_ID, :QTDE_DIAS, :TB_TIPO_ANDAMENTO_ID DO
    BEGIN
      SELECT COUNT(*) FROM R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
      WHERE A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND A.PEDIDO_ID = :PEDIDO_ID
      AND (TA.TIPO = 'C' OR TA.TIPO = 'R')
      INTO :V_QUANTIDADE;
      IF (:V_QUANTIDADE = 0) THEN  --Nao foi cancelado nem registrado
      BEGIN
        SUSPEND;
      END
    END
  END
  ELSE IF (:V_TIPO_PESQUISA = 'E') THEN
  BEGIN
    FOR SELECT PR.NUMERO_ORDEM,
               A.DATA,
               TA.DESCRICAO,
               PE.APRESENTANTE_NOME,
               PE.ADQUIRENTE_NOME,
               PE.PEDIDO_ID,
               A.ANDAMENTO_ID,
               :V_DATA_ATUAL - CAST(A.DATA AS DATE),
               A.TB_TIPO_ANDAMENTO_ID
            FROM   R_PROTOCOLO PR,
                   R_PEDIDO PE,
                   R_ANDAMENTO A LEFT JOIN R_TB_TIPO_ANDAMENTO TA
                   ON A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
            WHERE  A.PEDIDO_ID = PE.PEDIDO_ID
            AND    PE.PEDIDO_ID = PR.PEDIDO_ID
            AND    (A.TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_RETORNO_INTIMACAO OR
                    A.TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_RETORNO_EDITAL)
            AND    A.DATA BETWEEN (:V_DATA_ATUAL - 90) AND
                                  (:V_DATA_ATUAL + 0.9999)
            ORDER BY A.DATA, PR.NUMERO_ORDEM
    INTO    :NUMERO_ORDEM, :DATA_ANDAMENTO, :DESCRICAO_ANDAMENTO, :APRESENTANTE_NOME,
            :ADQUIRENTE_NOME, :PEDIDO_ID, :V_ANDAMENTO_ID, :QTDE_DIAS, :TB_TIPO_ANDAMENTO_ID DO
    BEGIN
      SELECT COUNT(*) FROM R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
      WHERE A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND A.PEDIDO_ID = :PEDIDO_ID
      AND (TA.TIPO = 'C' OR TA.TIPO = 'R')
      INTO :V_QUANTIDADE;
      IF (:V_QUANTIDADE = 0) THEN  --Nao foi cancelado nem registrado
      BEGIN
        SELECT COUNT(*) FROM R_ANDAMENTO
        WHERE PEDIDO_ID = :PEDIDO_ID
        AND   (TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_FIM_PRAZO_INTIMACAO OR TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_FIM_PRAZO_EDITAL)
        INTO :V_QUANTIDADE2;
        IF (:V_QUANTIDADE2 > 0) THEN  --Esta com Prazo Estourado
        BEGIN
          SUSPEND;
        END
      END
    END
  END
  ELSE IF (:V_TIPO_PESQUISA = 'D') THEN
  BEGIN
    FOR SELECT PR.NUMERO_ORDEM,
               A.DATA,
               TA.DESCRICAO,
               PE.APRESENTANTE_NOME,
               PE.ADQUIRENTE_NOME,
               PE.PEDIDO_ID,
               A.ANDAMENTO_ID,
               :V_DATA_ATUAL - CAST(A.DATA AS DATE),
               A.TB_TIPO_ANDAMENTO_ID
            FROM   R_PROTOCOLO PR,
                   R_PEDIDO PE,
                   R_ANDAMENTO A LEFT JOIN R_TB_TIPO_ANDAMENTO TA
                   ON A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
            WHERE  A.PEDIDO_ID = PE.PEDIDO_ID
            AND    PE.PEDIDO_ID = PR.PEDIDO_ID
            AND    (A.TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_RETORNO_INTIMACAO OR
                    A.TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_RETORNO_EDITAL)
            AND    A.DATA BETWEEN (:V_DATA_ATUAL - 90) AND
                                  (:V_DATA_ATUAL + 0.9999)
            ORDER BY A.DATA, PR.NUMERO_ORDEM
    INTO    :NUMERO_ORDEM, :DATA_ANDAMENTO, :DESCRICAO_ANDAMENTO, :APRESENTANTE_NOME,
            :ADQUIRENTE_NOME, :PEDIDO_ID, :V_ANDAMENTO_ID, :QTDE_DIAS, :TB_TIPO_ANDAMENTO_ID DO
    BEGIN
      SELECT COUNT(*) FROM R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
      WHERE A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND A.PEDIDO_ID = :PEDIDO_ID
      AND (TA.TIPO = 'C' OR TA.TIPO = 'R')
      INTO :V_QUANTIDADE;
      IF (:V_QUANTIDADE = 0) THEN  --Nao foi cancelado nem registrado
      BEGIN
        SELECT COUNT(*) FROM R_ANDAMENTO
        WHERE PEDIDO_ID = :PEDIDO_ID
        AND   (TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_FIM_PRAZO_INTIMACAO OR TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_FIM_PRAZO_EDITAL)
        INTO :V_QUANTIDADE2;
        IF (:V_QUANTIDADE2 = 0) THEN  --Esta Dentro do Prazo
        BEGIN
          SUSPEND;
        END
      END
    END
  END
END ^

ALTER PROCEDURE R_CORRIGIR_SELOS (V_TIPO_PROTOCOLO VARCHAR(3) CHARACTER SET ISO8859_1,
V_NUMERO_PROTOCOLO INTEGER)
RETURNS (TIPO_PROTOCOLO VARCHAR(3) CHARACTER SET ISO8859_1,
PROTOCOLO INTEGER,
DESCRICAO_ATO VARCHAR(120) CHARACTER SET ISO8859_1,
NUMERO_SELO VARCHAR(60) CHARACTER SET ISO8859_1,
PEDIDO_ITEM_ID INTEGER,
PEDIDO_ITEM_ID_APOS_ALTERACAO INTEGER,
VALOR_EMOLUMENTO NUMERIC(14, 2),
VALOR_EMOLUMENTO_APOS_ALTERACAO NUMERIC(14, 2),
VALOR_FUNDO NUMERIC(14, 2),
VALOR_FUNDO_APOS_ALTERACAO NUMERIC(14, 2),
VALOR_TX_JUD NUMERIC(14, 2),
VALOR_TX_JUD_APOS_ALTERACAO NUMERIC(14, 2))
AS 
declare variable V_SELO_LIVRO_ID integer;
  declare variable V_VALOR_ISS numeric(14,2);
  declare variable V_PERCENTUAL_FUNDOS_ESTADUAIS integer;
begin
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'PERCENTUAL_FUNDOS_ESTADUAIS', 5) INTO :V_PERCENTUAL_FUNDOS_ESTADUAIS;
  if (COALESCE(:V_PERCENTUAL_FUNDOS_ESTADUAIS,0) = 0) then
  BEGIN
    V_PERCENTUAL_FUNDOS_ESTADUAIS = 40;
  END
  V_PERCENTUAL_FUNDOS_ESTADUAIS = (:V_PERCENTUAL_FUNDOS_ESTADUAIS/100);

  for select selo_livro_id, pr.tipo_protocolo, pr.numero_ordem, nt.descricao, sl.numero_selo, pi.pedido_item_id,
      (select first 1 pedido_item_id from r_pedido_item pi2, g_emolumento_item ei2
        where pi2.emolumento_item_id = ei2.emolumento_item_id
        and ei2.selo_grupo_id = sg.selo_grupo_id
        and ei2.emolumento_periodo_id = 50004
        and pi2.pedido_id = pi.pedido_id) as pedido_item_id_correto,
      pi.valor_emolumento, ei.valor_emolumento as valor_emolumento_correto,
      pi.valor_fundo_ri, cast((ei.valor_emolumento * (:V_PERCENTUAL_FUNDOS_ESTADUAIS)) as numeric(14,2)) as valor_fundo_correto,
      pi.valor_taxa_judiciaria, ei.valor_taxa_judiciaria as valor_taxa_correto
      from g_selo_livro sl, r_pedido_item pi, g_natureza_titulo nt, g_selo_GRUPO sg, g_selo_lote sll,
      g_emolumento_item ei, r_protocolo pr
      where sl.tabela = 'R_PEDIDO_ITEM'
      and sl.campo_id = pi.pedido_item_id
      and pi.natureza_titulo_id = nt.natureza_titulo_id
      and sl.selo_lote_id = sll.selo_lote_id
      and sll.selo_grupo_id = sg.selo_grupo_id
      and ei.selo_grupo_id = sg.selo_grupo_id
      and pi.pedido_id = pr.pedido_id
      and ((pr.tipo_protocolo = '1') or (pr.tipo_protocolo = '3'))
      and ei.emolumento_periodo_id = 50004
      and ei.valor_emolumento <> pi.valor_emolumento
      order by pi.pedido_item_id
      into :v_selo_livro_id, :tipo_protocolo, :protocolo, :descricao_ato, :numero_selo, :pedido_item_id, :pedido_item_id_apos_alteracao,
        :valor_emolumento, :valor_emolumento_apos_alteracao, :valor_fundo, :valor_fundo_apos_alteracao, :valor_tx_jud,
        :valor_tx_jud_apos_alteracao do
  begin
    if ((coalesce(:v_tipo_protocolo,'') <> '') and (coalesce(:v_numero_protocolo,'') <> 0)) then
    begin
      if ((:v_tipo_protocolo = :tipo_protocolo) and (:v_numero_protocolo = :protocolo)) then
      begin
        select valor_iss from r_pedido_item
        where pedido_item_id = :pedido_item_id_apos_alteracao
        into :v_valor_iss;

        update g_selo_livro
        set campo_id = :pedido_item_id_apos_alteracao,
          valor_emolumento = :valor_emolumento_apos_alteracao,
          valor_fundesp = :valor_fundo_apos_alteracao,
          valor_taxa_judiciaria = :valor_tx_jud,
          valor_iss = :v_valor_iss,
          valor_total = (:valor_emolumento_apos_alteracao + :valor_fundo_apos_alteracao + :valor_tx_jud + :v_valor_iss)
        where selo_livro_id = :v_selo_livro_id;

        suspend;
      end
    end
    else
    begin
      select valor_iss from r_pedido_item
      where pedido_item_id = :pedido_item_id_apos_alteracao
      into :v_valor_iss;

      update g_selo_livro
      set campo_id = :pedido_item_id_apos_alteracao,
        valor_emolumento = :valor_emolumento_apos_alteracao,
        valor_fundesp = :valor_fundo_apos_alteracao,
        valor_taxa_judiciaria = :valor_tx_jud,
        valor_iss = :v_valor_iss,
        valor_total = (:valor_emolumento_apos_alteracao + :valor_fundo_apos_alteracao + :valor_tx_jud + :v_valor_iss)
      where selo_livro_id = :v_selo_livro_id;

      suspend;
    end
  end
end ^

ALTER PROCEDURE R_CORRIGIR_VINCULOS_SEM_CPF RETURNS (PESSOA_ID INTEGER,
NOME VARCHAR(120) CHARACTER SET ISO8859_1,
CPF_CNPJ VARCHAR(30) CHARACTER SET ISO8859_1)
AS 
begin
  for select distinct pessoa_id, nome
      from r_pessoa_vinculo
      where coalesce(cpf_cnpj,'') = ''
      into :pessoa_id, :nome do
  begin
    cpf_cnpj = '';

    select coalesce(cpf_cnpj,'') from r_pessoa
    where pessoa_id = :pessoa_id
    and nome = :nome
    and coalesce(cpf_cnpj,'') <> ''
    into :cpf_cnpj;

    if (:cpf_cnpj <> '') then
    begin
      update r_pessoa_vinculo
      set cpf_cnpj = :cpf_cnpj
      where pessoa_id = :pessoa_id
      and nome = :nome
      and coalesce(cpf_cnpj,'') = '';

      suspend;
    end
  end
end ^

ALTER PROCEDURE R_DADOS_IMOVEL (V_TIPO_REGISTRO VARCHAR(3) CHARACTER SET ISO8859_1,
V_NUMERO_INI VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_FIM VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_LETRA VARCHAR(10) CHARACTER SET ISO8859_1,
V_CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (IMOVEL_ID NUMERIC(12, 2),
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO NUMERIC(12, 2),
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
TIPO_CLASSE VARCHAR(1) CHARACTER SET ISO8859_1,
IMOVEL_TIPO_ID NUMERIC(12, 2),
AREA VARCHAR(120) CHARACTER SET ISO8859_1,
ENDERECO VARCHAR(260) CHARACTER SET ISO8859_1,
NUMERO_LOGRADOURO VARCHAR(15) CHARACTER SET ISO8859_1,
COMPLEMENTO VARCHAR(260) CHARACTER SET ISO8859_1,
COMPLEMENTO_COMPLETO VARCHAR(260) CHARACTER SET ISO8859_1,
QUADRA VARCHAR(120) CHARACTER SET ISO8859_1,
NUMERO_UNIDADE VARCHAR(120) CHARACTER SET ISO8859_1,
BAIRRO VARCHAR(90) CHARACTER SET ISO8859_1,
CEP NUMERIC(12, 2),
MUNICIPIO VARCHAR(60) CHARACTER SET ISO8859_1,
INSCRICAO_IMOVEL VARCHAR(60) CHARACTER SET ISO8859_1,
AREA_AVERBADA VARCHAR(17) CHARACTER SET ISO8859_1,
TIPO_CONSTRUCAO VARCHAR(1) CHARACTER SET ISO8859_1,
IMOVEL_UNIDADE_ID NUMERIC(12, 2),
CONJUNTO VARCHAR(10) CHARACTER SET ISO8859_1,
BLOCO VARCHAR(10) CHARACTER SET ISO8859_1,
NOME_EDIFICACAO VARCHAR(120) CHARACTER SET ISO8859_1,
NUMERO_CAR VARCHAR(60) CHARACTER SET ISO8859_1,
SIGLA VARCHAR(90) CHARACTER SET ISO8859_1,
CNM_NUMERO VARCHAR(30) CHARACTER SET ISO8859_1,
DESCRICAO_LOGRADOURO VARCHAR(90) CHARACTER SET ISO8859_1,
CIB VARCHAR(20) CHARACTER SET ISO8859_1,
CODIGO_INCRA VARCHAR(60) CHARACTER SET ISO8859_1,
NOVO VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_CARACTERISTICA VARCHAR(120);
DECLARE VARIABLE V_QUADRA_COND VARCHAR(15);
DECLARE VARIABLE V_NUMERO_UNIDADE_COND VARCHAR(60);
DECLARE VARIABLE V_IMOVEL_FICHAAUXILIAR_ID INTEGER;
DECLARE VARIABLE V_IMOVEL_TIPO VARCHAR(60);
BEGIN
  IF ((:V_CARTORIO IS NULL) OR (:V_CARTORIO = '')) THEN
  BEGIN
    IF ((:V_NUMERO_LETRA = '') OR (:V_NUMERO_LETRA = '''') OR (:V_NUMERO_LETRA IS NULL)) THEN
    BEGIN
      FOR SELECT I.IMOVEL_ID, I.TIPO_REGISTRO, I.NUMERO, NUMERO_LETRA,
                 I.TIPO_CLASSE, COALESCE(U.AREA,U.AREA_DESCRITIVA,''),
                 U.DESCRICAO_LOGRADOURO, U.IMOVEL_TIPO_ID,
                 U.NOME_EDIFICACAO, U.CARACTERISTICA, U.NUMERO_LOGRADOURO,
                 U.QUADRA, U.NUMERO_UNIDADE, U.IMOVEL_FICHAAUXILIAR_ID,
                 I.CEP, I.CIDADE, 
                 (SELECT FIRST 1 DESCRICAO FROM G_TB_TIPOLOGRADOURO
                 WHERE TB_TIPOLOGRADOURO_ID = U.TB_TIPOLOGRADOURO_ID),
                 (SELECT FIRST 1 DESCRICAO FROM G_TB_BAIRRO
                 WHERE TB_BAIRRO_ID = U.TB_BAIRRO_ID),
                 (SELECT FIRST 1 DESCRICAO FROM R_IMOVEL_TIPO
                 WHERE IMOVEL_TIPO_ID = U.IMOVEL_TIPO_ID),
                  I.INSCRICAO_IMOVEL, U.AREA_AVERBADA,
                  CAST(CAST(TIPO_CONSTRUCAO AS INTEGER) AS VARCHAR(1)),
                 U.IMOVEL_UNIDADE_ID, U.CONJUNTO, U.BLOCO,
                 I.NUMERO_CAR,
                 (SELECT FIRST 1 SIGLA FROM R_SIGLA
