                 U.DESCRICAO_LOGRADOURO, U.IMOVEL_TIPO_ID,
                 U.NOME_EDIFICACAO, U.CARACTERISTICA, U.NUMERO_LOGRADOURO,
                 U.QUADRA, U.NUMERO_UNIDADE, U.IMOVEL_FICHAAUXILIAR_ID,
                 I.CEP, I.CIDADE, 
                 (SELECT FIRST 1 DESCRICAO FROM G_TB_TIPOLOGRADOURO
                 WHERE TB_TIPOLOGRADOURO_ID = U.TB_TIPOLOGRADOURO_ID),
                 (SELECT FIRST 1 DESCRICAO FROM G_TB_BAIRRO
                 WHERE TB_BAIRRO_ID = U.TB_BAIRRO_ID),
                 (SELECT FIRST 1 DESCRICAO FROM R_IMOVEL_TIPO
                 WHERE IMOVEL_TIPO_ID = U.IMOVEL_TIPO_ID),
                  I.INSCRICAO_IMOVEL, U.AREA_AVERBADA,
                  CAST(CAST(TIPO_CONSTRUCAO AS INTEGER) AS VARCHAR(1)),
                 U.IMOVEL_UNIDADE_ID, U.CONJUNTO, U.BLOCO, I.NUMERO_CAR,
                 (SELECT FIRST 1 SIGLA FROM R_SIGLA
                 WHERE SIGLA_ID = U.SIGLA_ID),
                 I.CNM_NUMERO,
                 I.CIB,
                 U.ccir_codigo,
                 U.NOVO
      FROM R_IMOVEL I, R_IMOVEL_UNIDADE U
      WHERE I.IMOVEL_ID = U.IMOVEL_ID
      AND I.TIPO_REGISTRO = 'M'
      AND (I.NUMERO BETWEEN :V_NUMERO_INI AND :V_NUMERO_FIM)
      AND I.NUMERO_LETRA = :V_NUMERO_LETRA
      AND I.CARTORIO = :V_CARTORIO
      INTO :IMOVEL_ID, :TIPO_REGISTRO, :NUMERO, :NUMERO_LETRA,
           :TIPO_CLASSE, :AREA,
           :DESCRICAO_LOGRADOURO, :IMOVEL_TIPO_ID,
           :NOME_EDIFICACAO, :V_CARACTERISTICA, :NUMERO_LOGRADOURO,
           :QUADRA, :NUMERO_UNIDADE, :V_IMOVEL_FICHAAUXILIAR_ID,
           :CEP, :MUNICIPIO, :ENDERECO, :BAIRRO, :V_IMOVEL_TIPO, 
           :INSCRICAO_IMOVEL, :AREA_AVERBADA, :TIPO_CONSTRUCAO,
           :IMOVEL_UNIDADE_ID, :CONJUNTO, :BLOCO, :NUMERO_CAR, :SIGLA, :CNM_NUMERO, :CIB, :CODIGO_INCRA, :NOVO DO
      BEGIN
        IF ((:TIPO_CLASSE = 'L') OR (:TIPO_CLASSE = 'C')) THEN
        BEGIN
          ENDERECO = TRIM(:ENDERECO)||' '||TRIM(:DESCRICAO_LOGRADOURO);
          IF (:TIPO_CLASSE = 'L') THEN
          BEGIN
            COMPLEMENTO_COMPLETO = '';
            IF ((:QUADRA IS NOT NULL) AND (:QUADRA <> '')) THEN
              COMPLEMENTO_COMPLETO = 'QD. '|| TRIM(:QUADRA);
            IF ((:NUMERO_UNIDADE IS NOT NULL) AND (:NUMERO_UNIDADE <> '')) THEN
            BEGIN
              IF (TRIM(:COMPLEMENTO_COMPLETO) = '') THEN
              BEGIN
                COMPLEMENTO_COMPLETO = 'LT. '|| TRIM(:NUMERO_UNIDADE);
              END
              ELSE
              BEGIN
                COMPLEMENTO_COMPLETO = COMPLEMENTO_COMPLETO||', '||'LT. '||TRIM(:NUMERO_UNIDADE);
              END
            END
            IF ((:CONJUNTO IS NOT NULL) AND (:CONJUNTO <> '')) THEN
            BEGIN
              IF (TRIM(:COMPLEMENTO_COMPLETO) = '') THEN
              BEGIN
                COMPLEMENTO_COMPLETO = 'CJ. '|| TRIM(:CONJUNTO);
              END
              ELSE
              BEGIN
                COMPLEMENTO_COMPLETO = COMPLEMENTO_COMPLETO||', '||'CJ. '||TRIM(:CONJUNTO);
              END
            END
            IF ((:BLOCO IS NOT NULL) AND (:BLOCO <> '')) THEN
            BEGIN
              IF (TRIM(:COMPLEMENTO_COMPLETO) = '') THEN
              BEGIN
                COMPLEMENTO_COMPLETO = 'BL. '|| TRIM(:BLOCO);
              END
              ELSE
              BEGIN
                COMPLEMENTO_COMPLETO = COMPLEMENTO_COMPLETO||', '||'BL. '||TRIM(:BLOCO);
              END
            END
          END
          ELSE IF (:TIPO_CLASSE = 'C') THEN
          BEGIN
            SELECT FIRST 1 U.QUADRA, U.NUMERO_UNIDADE,
                   (SELECT FIRST 1 DESCRICAO FROM G_TB_BAIRRO
                    WHERE TB_BAIRRO_ID = U.TB_BAIRRO_ID),
                    U.CONJUNTO, U.BLOCO,
                   (SELECT FIRST 1 SIGLA FROM R_SIGLA
                   WHERE SIGLA_ID = U.SIGLA_ID),
                    U.NUMERO_LOGRADOURO,
                    (SELECT FIRST 1 DESCRICAO FROM G_TB_TIPOLOGRADOURO
                     WHERE TB_TIPOLOGRADOURO_ID = U.TB_TIPOLOGRADOURO_ID),
                     U.DESCRICAO_LOGRADOURO
            FROM R_IMOVEL I, R_IMOVEL_UNIDADE U, R_IMOVEL_FICHAAUXILIAR F
            WHERE I.IMOVEL_ID = U.IMOVEL_ID
            AND U.IMOVEL_ID = F.IMOVEL_ID
            AND F.IMOVEL_FICHAAUXILIAR_ID = :V_IMOVEL_FICHAAUXILIAR_ID
            INTO :V_QUADRA_COND, :V_NUMERO_UNIDADE_COND, :BAIRRO,
            :CONJUNTO, :BLOCO, :SIGLA, :NUMERO_LOGRADOURO, :ENDERECO,
            :DESCRICAO_LOGRADOURO;
            COMPLEMENTO_COMPLETO = '';
            COMPLEMENTO = '';     
            QUADRA = '';
            if (:DESCRICAO_LOGRADOURO <> '') then
            BEGIN
              ENDERECO = TRIM(:ENDERECO)||' '||TRIM(:DESCRICAO_LOGRADOURO);
            END

            IF ((:V_QUADRA_COND IS NOT NULL) AND (:V_QUADRA_COND <> '')) THEN
            BEGIN
              COMPLEMENTO_COMPLETO = 'QD. '|| TRIM(:V_QUADRA_COND);
              QUADRA = TRIM(:V_QUADRA_COND);
            END
            IF ((:V_NUMERO_UNIDADE_COND IS NOT NULL) AND (:V_NUMERO_UNIDADE_COND <> '')) THEN
            BEGIN                                                            
              IF (TRIM(:COMPLEMENTO_COMPLETO) = '') THEN
              BEGIN
                COMPLEMENTO_COMPLETO = 'LT. '|| TRIM(:V_NUMERO_UNIDADE_COND);
              END
              ELSE
              BEGIN
                COMPLEMENTO_COMPLETO = COMPLEMENTO_COMPLETO||', '||'LT. '|| TRIM(:V_NUMERO_UNIDADE_COND);
              END
            END
            IF ((:NUMERO_UNIDADE IS NOT NULL) AND (:NUMERO_UNIDADE <> '')) THEN
            BEGIN
              COMPLEMENTO = :V_IMOVEL_TIPO ||' '|| TRIM(:NUMERO_UNIDADE);
              IF (TRIM(:COMPLEMENTO_COMPLETO) = '') THEN
              BEGIN
                COMPLEMENTO_COMPLETO = :V_IMOVEL_TIPO ||' '|| TRIM(:NUMERO_UNIDADE);
              END
              ELSE
              BEGIN
                COMPLEMENTO_COMPLETO = COMPLEMENTO_COMPLETO||', '||:V_IMOVEL_TIPO ||' '|| TRIM(:NUMERO_UNIDADE);
              END
            END        
            IF ((:CONJUNTO IS NOT NULL) AND (:CONJUNTO <> '')) THEN
            BEGIN
              IF (TRIM(:COMPLEMENTO_COMPLETO) = '') THEN
              BEGIN
                COMPLEMENTO_COMPLETO = 'CJ. '|| TRIM(:CONJUNTO);
              END
              ELSE
              BEGIN
                COMPLEMENTO_COMPLETO = COMPLEMENTO_COMPLETO||', '||'CJ. '||TRIM(:CONJUNTO);
              END
            END
            IF ((:BLOCO IS NOT NULL) AND (:BLOCO <> '')) THEN
            BEGIN
              IF (TRIM(:COMPLEMENTO_COMPLETO) = '') THEN
              BEGIN
                COMPLEMENTO_COMPLETO = 'BL. '|| TRIM(:BLOCO);
              END
              ELSE
              BEGIN
                COMPLEMENTO_COMPLETO = COMPLEMENTO_COMPLETO||', '||'BL. '||TRIM(:BLOCO);
              END
            END
          END
        END
        ELSE IF (:TIPO_CLASSE = 'R') THEN
        BEGIN
          ENDERECO = TRIM(:NOME_EDIFICACAO);
          NUMERO_LOGRADOURO = '';
          COMPLEMENTO_COMPLETO = TRIM(:V_CARACTERISTICA);
          COMPLEMENTO = TRIM(:V_CARACTERISTICA);
          BAIRRO = '';
          SIGLA = '';
        END
        SUSPEND;
      END  
    END    
  END
END ^

ALTER PROCEDURE R_DEPOSITOS_APRESENTANTE_TJDFT (V_DATA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO VARCHAR(1) CHARACTER SET ISO8859_1)
RETURNS (NUMERO_ORDEM NUMERIC(18, 4),
PEDIDO_ID NUMERIC(18, 4),
PROTOCOLO_ID NUMERIC(18, 4),
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
DATA_PROTOCOLO DATE,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
DATA_PAGAMENTO DATE,
CONTA VARCHAR(200) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
VALOR_PAGO NUMERIC(18, 2),
NOME_TITULAR_CONTA VARCHAR(120) CHARACTER SET ISO8859_1,
CHAVE_PIX VARCHAR(260) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_TIPO_SERVICO VARCHAR(10);
DECLARE VARIABLE V_TIPO_TRANSACAO VARCHAR(5);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_APRESENTANTE VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_TJDFT VARCHAR(10);
DECLARE VARIABLE V_NUMERO_BANCO VARCHAR(20);
DECLARE VARIABLE V_NUMERO_AGENCIA VARCHAR(20);
DECLARE VARIABLE V_NUMERO_CONTA VARCHAR(20);
DECLARE VARIABLE V_CPF_CNPJ_INFORMADO VARCHAR(30);
DECLARE VARIABLE V_TIPO_CONTA VARCHAR(1);
DECLARE VARIABLE V_NUMERO_OPERACAO VARCHAR(10);
BEGIN
  --(1) Servicos de Devolucao
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_TJDFT'
  INTO :V_SERVICO_DEVOLUCAO_TJDFT;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_APRESENTANTE'
  INTO :V_SERVICO_DEVOLUCAO_APRESENTANTE;
  -- Fim (1)

  FOR SELECT  PR.NUMERO_ORDEM,
              COALESCE((SELECT TOTAL_EMOLUMENTO FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)),0) AS TOTAL_EMOLUMENTO,
              PE.PEDIDO_ID, PR.TIPO_PROTOCOLO, PR.PROTOCOLO_ID, PR.DATA, PE.APRESENTANTE_NOME,
              PE.NUMERO_BANCO, PE.NUMERO_AGENCIA, PE.NUMERO_CONTA, PE.CPF_CNPJ_INFORMADO,
              PE.TIPO_CONTA, PE.NUMERO_OPERACAO,
              CAST(C.CAIXA_SERVICO_ID AS INTEGER) TIPO_SERVICO,
              C.DATA_PAGAMENTO, COALESCE(C.VALOR_PAGO,0), C.TIPO_TRANSACAO, PE.NOME_TITULAR_CONTA,
              PE.CHAVE_PIX
      FROM R_PROTOCOLO PR, R_PEDIDO PE, C_CAIXA_ITEM C
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND   C.CHAVE_SERVICO = PR.PROTOCOLO_ID
      AND   C.TIPO_SERVICO = PR.TIPO_PROTOCOLO
      AND   C.DATA_PAGAMENTO BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)
                                 AND CAST(:V_DATA_FIM AS TIMESTAMP) + 0.99999
      AND PR.TIPO_PROTOCOLO = '1'
      ORDER BY PR.NUMERO_ORDEM
  INTO  :NUMERO_ORDEM, :TOTAL_EMOLUMENTO, :PEDIDO_ID, :TIPO_PROTOCOLO, :PROTOCOLO_ID,
        :DATA_PROTOCOLO, :APRESENTANTE_NOME, :V_NUMERO_BANCO, :V_NUMERO_AGENCIA,
        :V_NUMERO_CONTA, :V_CPF_CNPJ_INFORMADO, :V_TIPO_CONTA, :V_NUMERO_OPERACAO,
        :V_TIPO_SERVICO, :DATA_PAGAMENTO, :VALOR_PAGO, :V_TIPO_TRANSACAO, :NOME_TITULAR_CONTA,
        :CHAVE_PIX DO
  BEGIN
    -- (3) Montar Informacoes da Conta para Devolucao
    CONTA = NULL;
    IF ((:V_NUMERO_BANCO IS NOT NULL) AND (:V_NUMERO_BANCO <> '')) THEN
      CONTA = 'BANCO: ' || :V_NUMERO_BANCO || ' ';
    IF ((:V_NUMERO_AGENCIA IS NOT NULL) AND (:V_NUMERO_AGENCIA <> '')) THEN
    BEGIN
      IF (:CONTA IS NOT NULL) THEN
        CONTA = :CONTA || 'AGENCIA: ' || :V_NUMERO_AGENCIA || ' ';
      ELSE
        CONTA = 'AGENCIA: ' || :V_NUMERO_AGENCIA || ' ';
    END
    IF ((:V_NUMERO_CONTA IS NOT NULL) AND (:V_NUMERO_CONTA <> '')) THEN
    BEGIN
      IF (:CONTA IS NOT NULL) THEN
        CONTA = :CONTA || 'CONTA: ' || :V_NUMERO_CONTA || ' ';
      ELSE
        CONTA = 'CONTA: ' || :V_NUMERO_CONTA || ' ';
    END
    IF ((:V_NUMERO_OPERACAO IS NOT NULL) AND (:V_NUMERO_OPERACAO <> '')) THEN
    BEGIN
      IF (:CONTA IS NOT NULL) THEN
        CONTA = :CONTA || 'OPERACAO.: ' || :V_NUMERO_OPERACAO || ' ';
      ELSE
        CONTA = 'OPERACAO: ' || :V_NUMERO_OPERACAO || ' ';
    END
    IF ((:V_CPF_CNPJ_INFORMADO IS NOT NULL) AND (:V_CPF_CNPJ_INFORMADO <> '')) THEN
    BEGIN
      IF (:CONTA IS NOT NULL) THEN
        CONTA = :CONTA || 'CPF/CNPJ: ' || :V_CPF_CNPJ_INFORMADO || ' ';
      ELSE
        CONTA = 'CPF/CNPJ: ' || :V_CPF_CNPJ_INFORMADO || ' ';
    END
    IF ((:V_TIPO_CONTA IS NULL) AND (:CONTA IS NOT NULL)) THEN
      CONTA = 'C/C '|| :CONTA;
    ELSE IF ((:V_TIPO_CONTA = 'P') AND (:CONTA IS NOT NULL)) THEN
      CONTA = 'C/P '|| :CONTA;
    ELSE IF ((:V_TIPO_CONTA = 'C') AND (:CONTA IS NOT NULL)) THEN
      CONTA = 'C/C '|| :CONTA;

    if (COALESCE(:CHAVE_PIX,'') <> '') then
    begin
      CONTA = :CONTA || 'CHAVE PIX: ' || :CHAVE_PIX;
    end
    -- Fim (3)

    IF (:V_TIPO = 'A') THEN --Se for relatorio de devolucoes ao apresentante
    BEGIN
      IF (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_APRESENTANTE) THEN
        SUSPEND;
    END
    ELSE IF (:V_TIPO = 'T') THEN --Se for relatorio de devolucoes ao TJDFT
    BEGIN
      IF (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_TJDFT) THEN
        SUSPEND;
    END
  END
END ^

ALTER PROCEDURE R_DEVOLUCAO (V_DATA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_INDICE NUMERIC(18, 4),
V_TIPO VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (NUMERO_ORDEM NUMERIC(18, 4),
DATA_ANDAMENTO DATE,
NOVO_NUMERO_ORDEM NUMERIC(18, 4),
ANTIGO_NUMERO_ORDEM NUMERIC(18, 4),
PEDIDO_ID NUMERIC(18, 4),
PROTOCOLO_ID NUMERIC(18, 4),
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
DATA_PROTOCOLO DATE,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_DEVOLUCAO VARCHAR(5) CHARACTER SET ISO8859_1,
DATA_DEVOLUCAO DATE,
QTDE_DIAS NUMERIC(18, 4),
CONTA VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_CONTA VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO_OPERACAO VARCHAR(10) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
VALOR_PAGO NUMERIC(18, 2),
DIREITO_DEVOLUCAO NUMERIC(18, 2),
DIREITO_DEVOLUCAO_ATUALIZADO NUMERIC(18, 2),
VALOR_RETIDO NUMERIC(18, 2),
VALOR_DEVOLVIDO NUMERIC(18, 4),
VALOR_DEVOLVIDO_COMPENSACAO NUMERIC(18, 4),
VALOR_COMPENSADO NUMERIC(18, 4),
RECEITA_LIQUIDA NUMERIC(18, 4))
AS 
DECLARE VARIABLE V_VALOR_PAGO NUMERIC(18,4);
DECLARE VARIABLE V_CREDITOS NUMERIC(18,4);
DECLARE VARIABLE V_DEBITOS NUMERIC(18,4);
DECLARE VARIABLE V_DEBITOS_DEVOLUCAO NUMERIC(18,4);
DECLARE VARIABLE V_TIPO_SERVICO VARCHAR(10);
DECLARE VARIABLE V_TIPO_TRANSACAO VARCHAR(5);
DECLARE VARIABLE V_DATA_PAGAMENTO DATE;
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_75 VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_APRESENTANTE VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_100 VARCHAR(10);
DECLARE VARIABLE V_SERVICO_DEVOLUCAO_TJDFT VARCHAR(10);
DECLARE VARIABLE V_PERIODO_PADRAO VARCHAR(20);
DECLARE VARIABLE V_DATA_PERIODO_PADRAO DATE;
DECLARE VARIABLE V_QTDE_ANDAMENTO NUMERIC(18,4);
DECLARE VARIABLE V_DATA_HORA_BANCO DATE;
DECLARE VARIABLE V_NUMERO_BANCO VARCHAR(10);
DECLARE VARIABLE V_NUMERO_AGENCIA VARCHAR(10);
DECLARE VARIABLE V_NUMERO_CONTA VARCHAR(20);
DECLARE VARIABLE V_CPF_CNPJ_INFORMADO VARCHAR(30);
DECLARE VARIABLE V_PEDIDO_ID_TEMP NUMERIC(18,4); --Usado para pegar o numero do protocolo anterior
BEGIN
  -- (1) Retornar Data Inicial Periodo Padrao de Emolumentos
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'PEDIDO'
  AND C.SECAO = 'ITENS DO PEDIDO'
  AND C.NOME = 'PERIODO_PADRAO'
  INTO :V_PERIODO_PADRAO;

  SELECT DATA_INICIAL FROM G_EMOLUMENTO_PERIODO
  WHERE EMOLUMENTO_PERIODO_ID = :V_PERIODO_PADRAO
  INTO :V_DATA_PERIODO_PADRAO;
  -- Fim (1)

  -- (2) Retornar Codigos dos Servicos de Devolucao
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_75'
  INTO :V_SERVICO_DEVOLUCAO_75;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_100'
  INTO :V_SERVICO_DEVOLUCAO_100;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_TJDFT'
  INTO :V_SERVICO_DEVOLUCAO_TJDFT;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_APRESENTANTE'
  INTO :V_SERVICO_DEVOLUCAO_APRESENTANTE;
  -- Fim (2)

  FOR SELECT  CAST(A.DATA AS DATE) AS DATA_ANDAMENTO, PR.NUMERO_ORDEM,
             (SELECT NUMERO_ORDEM FROM R_PROTOCOLO WHERE PEDIDO_ID = PE.NOVO_PEDIDO_ID
                                                   AND TIPO_PROTOCOLO = '1') AS NOVO_NUMERO_ORDEM, --Novo Protocolo, quando compensado ou vinculado
             (SELECT PEDIDO_ID FROM R_PEDIDO WHERE NOVO_PEDIDO_ID = PE.PEDIDO_ID) AS V_PEDIDO_ID_TEMP, --Numero do Pedido_id do Protocolo Anterior
             (SELECT VALOR_COMPENSADO FROM R_PEDIDO WHERE PEDIDO_ID = PE.NOVO_PEDIDO_ID) AS VALOR_DEVOLVIDO_COMPENSACAO, --Valor deste protocolo Devolvido via Compensacao em outro
             (SELECT TOTAL_EMOLUMENTO + TOTAL_TAXA + TOTAL_FUNDO_RI + TOTAL_ISS FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
              PE.PEDIDO_ID, PR.TIPO_PROTOCOLO, PR.PROTOCOLO_ID, PR.DATA, PE.APRESENTANTE_NOME, PE.NUMERO_BANCO,
              PE.NUMERO_AGENCIA, PE.NUMERO_CONTA, PE.CPF_CNPJ_INFORMADO,
              PE.TIPO_CONTA, PE.NUMERO_OPERACAO, PE.VALOR_COMPENSADO
      FROM R_PROTOCOLO PR, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, R_PEDIDO PE
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.PEDIDO_ID = A.PEDIDO_ID
      AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
      AND A.DATA BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)
                     AND CAST(:V_DATA_FIM AS TIMESTAMP) + 0.99999
      AND TA.TIPO = 'C'
      AND PR.TIPO_PROTOCOLO = '1'
      ORDER BY CAST(A.DATA AS DATE), PR.NUMERO_ORDEM
  INTO  :DATA_ANDAMENTO, :NUMERO_ORDEM, :NOVO_NUMERO_ORDEM, :V_PEDIDO_ID_TEMP, :VALOR_DEVOLVIDO_COMPENSACAO, :TOTAL_EMOLUMENTO, 
        :PEDIDO_ID, :TIPO_PROTOCOLO, :PROTOCOLO_ID, :DATA_PROTOCOLO, :APRESENTANTE_NOME,
        :V_NUMERO_BANCO, :V_NUMERO_AGENCIA, :V_NUMERO_CONTA, :V_CPF_CNPJ_INFORMADO,
        :TIPO_CONTA, :NUMERO_OPERACAO, :VALOR_COMPENSADO DO
  BEGIN
    -- (4) Inicializacao de Variaveis
    ANTIGO_NUMERO_ORDEM = NULL;
    VALOR_PAGO = 0;
    VALOR_RETIDO = 0;
    VALOR_DEVOLVIDO = 0;
    RECEITA_LIQUIDA = 0;
    DIREITO_DEVOLUCAO = 0;
    DIREITO_DEVOLUCAO_ATUALIZADO = 0;
    V_CREDITOS = 0;
    V_DEBITOS = 0;
    V_DEBITOS_DEVOLUCAO = 0;
    TIPO_DEVOLUCAO = ''; -- (Nenhum), 'T' (Ao TJDFT), 'A' (Ao Apresentante), 'C' (Compensados), 'E' (Especie)
    DATA_DEVOLUCAO = NULL;
    QTDE_DIAS = NULL;
    IF (:VALOR_DEVOLVIDO_COMPENSACAO IS NULL) THEN
      VALOR_DEVOLVIDO_COMPENSACAO = 0;
    IF (:VALOR_COMPENSADO IS NULL) THEN
      VALOR_COMPENSADO = 0;
    -- Fim (4)

    --(7) Pegar o numero do protocolo anterior quando existir
    SELECT NUMERO_ORDEM FROM R_PROTOCOLO
    WHERE PEDIDO_ID = :V_PEDIDO_ID_TEMP
    AND TIPO_PROTOCOLO = '1'
    INTO :ANTIGO_NUMERO_ORDEM; --Antigo Protocolo, quando este for uma compensacao do anterior
    --Fim (7)
   
    -- (5) Verificar Valores do Caixa
    FOR SELECT CAST(CAIXA_SERVICO_ID AS INTEGER) TIPO_SERVICO, DATA_PAGAMENTO,
               VALOR_PAGO, TIPO_TRANSACAO FROM C_CAIXA_ITEM
        WHERE TIPO_SERVICO = :TIPO_PROTOCOLO
        AND CHAVE_SERVICO = :PROTOCOLO_ID
    INTO :V_TIPO_SERVICO, :V_DATA_PAGAMENTO, :V_VALOR_PAGO, :V_TIPO_TRANSACAO DO
    BEGIN
      IF (:V_VALOR_PAGO IS NULL) THEN
        V_VALOR_PAGO = 0;

      IF (:V_TIPO_TRANSACAO = 'C') THEN
      BEGIN
        V_CREDITOS = :V_CREDITOS + :V_VALOR_PAGO;
      END
      ELSE IF (:V_TIPO_TRANSACAO = 'D') THEN
      BEGIN
        IF ((:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_75) OR
            (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_100) OR
            (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_TJDFT) OR
            (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_APRESENTANTE)) THEN
        BEGIN
          V_DEBITOS_DEVOLUCAO = :V_DEBITOS_DEVOLUCAO + :V_VALOR_PAGO;
          DATA_DEVOLUCAO = CAST(:V_DATA_PAGAMENTO AS DATE);
          IF (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_TJDFT) THEN
            TIPO_DEVOLUCAO = 'T'; --Ao TJDFT
          ELSE IF (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_APRESENTANTE) THEN
            TIPO_DEVOLUCAO = 'A'; --Ao Apresentante
          ELSE
            TIPO_DEVOLUCAO = 'E'; --Em Especie
        END
        ELSE
        BEGIN
          V_DEBITOS = :V_DEBITOS + :V_VALOR_PAGO;
        END
      END
    END
    --Fim (5)
    
    VALOR_PAGO = :V_CREDITOS - :V_DEBITOS; --Valor Pago como Deposito

    IF (:VALOR_DEVOLVIDO_COMPENSACAO > 0) THEN
      TIPO_DEVOLUCAO = 'C'; --Foi feita compensacao em outro protocolo

    IF ((:TIPO_DEVOLUCAO = '') OR (:TIPO_DEVOLUCAO IS NULL)) THEN -- Se nao houver nenhum tipo de Devolucao e nem Compensacao (A Devolver)
    BEGIN
      VALOR_RETIDO = :TOTAL_EMOLUMENTO * 0.25;
      DIREITO_DEVOLUCAO = (:VALOR_PAGO  + :VALOR_COMPENSADO) - :VALOR_RETIDO;
      SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE
      INTO :V_DATA_HORA_BANCO;
      QTDE_DIAS = CAST(:V_DATA_HORA_BANCO AS DATE) - CAST(:DATA_ANDAMENTO AS DATE);
    END
    ELSE IF (:TIPO_DEVOLUCAO = 'C') THEN --Se for compensacao
    BEGIN
      VALOR_RETIDO = (:VALOR_PAGO + :VALOR_COMPENSADO) - :VALOR_DEVOLVIDO_COMPENSACAO;
      DIREITO_DEVOLUCAO = (:VALOR_PAGO  + :VALOR_COMPENSADO) - :VALOR_RETIDO;
    END
    ELSE
    BEGIN -- Se for Devolucao Ao TJDFT, Ao Apresentante ou em Especie
      VALOR_RETIDO = (:VALOR_PAGO + :VALOR_COMPENSADO) - :V_DEBITOS_DEVOLUCAO;
      VALOR_DEVOLVIDO = :V_DEBITOS_DEVOLUCAO;
      DIREITO_DEVOLUCAO = (:VALOR_PAGO  + :VALOR_COMPENSADO) - :VALOR_RETIDO;
    END
    IF (:DIREITO_DEVOLUCAO < 0) THEN
      DIREITO_DEVOLUCAO = 0;
    IF (:DIREITO_DEVOLUCAO < 0) THEN
      DIREITO_DEVOLUCAO = 0;

    DIREITO_DEVOLUCAO_ATUALIZADO = :DIREITO_DEVOLUCAO;

    -- (6) Atualizacao do Direito de devolucao em cima do Indice informado
    IF (CAST(:DATA_PROTOCOLO AS DATE) < CAST(:V_DATA_PERIODO_PADRAO AS DATE)) THEN
    BEGIN
      IF (:V_INDICE > 0) THEN
      BEGIN
        IF ((:VALOR_DEVOLVIDO = 0) AND (:VALOR_DEVOLVIDO_COMPENSACAO = 0) and (:DIREITO_DEVOLUCAO_ATUALIZADO > 0)) THEN
          DIREITO_DEVOLUCAO_ATUALIZADO = DIREITO_DEVOLUCAO_ATUALIZADO * :V_INDICE;
      END
    END
    --Fim (6)
    
    IF ((:TIPO_DEVOLUCAO = '') OR (:TIPO_DEVOLUCAO IS NULL)) THEN -- Se nao houver nenhum tipo de Devolucao e nem Compensacao (A Devolver)
    BEGIN
      SELECT COUNT(*) FROM R_ANDAMENTO
      WHERE PEDIDO_ID = :PEDIDO_ID
      AND TB_TIPO_ANDAMENTO_ID = 54 --Aguardando Procedimentos nao contabiliza
      INTO :V_QTDE_ANDAMENTO;
      IF (:V_QTDE_ANDAMENTO > 0) THEN -- Se houver o andamento, zera o direito de devolucao
      BEGIN
        DIREITO_DEVOLUCAO = 0;
        DIREITO_DEVOLUCAO_ATUALIZADO = 0;
        DATA_DEVOLUCAO = NULL;
      END
    END
    RECEITA_LIQUIDA = :VALOR_RETIDO;
    
    -- (3) Montar Informacoes da Conta para Devolucao
    CONTA = NULL;
    IF ((:V_NUMERO_BANCO IS NOT NULL) AND (:V_NUMERO_BANCO <> '')) THEN
      CONTA = 'BANCO: ' || :V_NUMERO_BANCO || ' ';
    IF ((:V_NUMERO_AGENCIA IS NOT NULL) AND (:V_NUMERO_AGENCIA <> '')) THEN
    BEGIN
      IF (:CONTA IS NOT NULL) THEN
        CONTA = :CONTA || 'AGENCIA: ' || :V_NUMERO_AGENCIA || ' ';
      ELSE
        CONTA = 'AGENCIA: ' || :V_NUMERO_AGENCIA || ' ';
    END
    IF ((:V_NUMERO_CONTA IS NOT NULL) AND (:V_NUMERO_CONTA <> '')) THEN
    BEGIN
      IF (:CONTA IS NOT NULL) THEN
        CONTA = :CONTA || 'CONTA: ' || :V_NUMERO_CONTA || ' ';
      ELSE
        CONTA = 'CONTA: ' || :V_NUMERO_CONTA || ' ';
    END
    IF ((:NUMERO_OPERACAO IS NOT NULL) AND (:NUMERO_OPERACAO <> '')) THEN
    BEGIN
      IF (:CONTA IS NOT NULL) THEN
        CONTA = :CONTA || 'OPERACAO.: ' || :NUMERO_OPERACAO || ' ';
      ELSE
        CONTA = 'OPERACAO: ' || :NUMERO_OPERACAO || ' ';
    END
    IF ((:V_CPF_CNPJ_INFORMADO IS NOT NULL) AND (:V_CPF_CNPJ_INFORMADO <> '')) THEN
    BEGIN
      IF (:CONTA IS NOT NULL) THEN
        CONTA = :CONTA || 'CPF/CNPJ: ' || :V_CPF_CNPJ_INFORMADO || ' ';
      ELSE
        CONTA = 'CPF/CNPJ: ' || :V_CPF_CNPJ_INFORMADO || ' ';
    END
    IF ((:TIPO_CONTA IS NULL) AND (:CONTA IS NOT NULL)) THEN
      CONTA = 'C/C '|| :CONTA;
    ELSE IF ((:TIPO_CONTA = 'P') AND (:CONTA IS NOT NULL)) THEN
      CONTA = 'C/P '|| :CONTA;
    ELSE IF ((:TIPO_CONTA = 'C') AND (:CONTA IS NOT NULL)) THEN
      CONTA = 'C/C '|| :CONTA;
    -- Fim (3)

    IF (:V_TIPO = 'T') THEN --TODOS
    BEGIN
      SUSPEND;
    END
    ELSE IF (:V_TIPO = 'D') THEN --DEVOLVIDOS OU COMPENSADOS
    BEGIN
      IF ((:TIPO_DEVOLUCAO = 'T') OR (:TIPO_DEVOLUCAO = 'A') OR (:TIPO_DEVOLUCAO = 'E') OR (:TIPO_DEVOLUCAO = 'C'))THEN
      BEGIN
        SUSPEND;
      END
    END
    ELSE IF (:V_TIPO = 'A') THEN --EM ABERTO ate 59 DIAS
    BEGIN
      IF (((:TIPO_DEVOLUCAO = '') OR (:TIPO_DEVOLUCAO IS NULL)) AND ((:QTDE_DIAS < 60) OR (:QTDE_DIAS IS NULL))) THEN -- Nao houve devolucao
      BEGIN
        SUSPEND;
      END
    END
    ELSE IF (:V_TIPO = 'M') THEN --EM ABERTO A MAIS DE 60 DIAS
    BEGIN
      IF (((:TIPO_DEVOLUCAO = '') OR (:TIPO_DEVOLUCAO IS NULL)) AND ((:QTDE_DIAS> 59) AND (:QTDE_DIAS IS NOT NULL))) THEN
      BEGIN
        SUSPEND;
      END
    END
  END
END ^

ALTER PROCEDURE R_DEVOLUCAO_CANCELADOS (V_DATA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO VARCHAR(3) CHARACTER SET ISO8859_1,
V_RETORNAR_VALOR_DEVOLUCAO_ZERADOS VARCHAR(3) CHARACTER SET ISO8859_1 = 'S')
RETURNS (NUMERO_ORDEM NUMERIC(18, 4),
DATA_ANDAMENTO DATE,
NOVO_NUMERO_ORDEM NUMERIC(18, 4),
ANTIGO_NUMERO_ORDEM NUMERIC(18, 4),
PEDIDO_ID NUMERIC(18, 4),
PROTOCOLO_ID NUMERIC(18, 4),
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
DATA_PROTOCOLO DATE,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_DEVOLUCAO VARCHAR(5) CHARACTER SET ISO8859_1,
DATA_DEVOLUCAO DATE,
QTDE_DIAS NUMERIC(18, 4),
CONTA VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_CONTA VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO_OPERACAO VARCHAR(10) CHARACTER SET ISO8859_1,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
VALOR_PAGO NUMERIC(18, 2),
DIREITO_DEVOLUCAO NUMERIC(18, 2),
VALOR_RETIDO NUMERIC(18, 2),
VALOR_DEVOLVIDO NUMERIC(18, 4),
VALOR_DEVOLVIDO_COMPENSACAO NUMERIC(18, 4),
VALOR_COMPENSADO NUMERIC(18, 4),
RECEITA_LIQUIDA NUMERIC(18, 4),
PAGADOR_CPF VARCHAR(30) CHARACTER SET ISO8859_1,
PAGADOR_NOME VARCHAR(120) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_VALOR_PAGO NUMERIC(18,4);
  DECLARE VARIABLE V_CREDITOS NUMERIC(18,4);
  DECLARE VARIABLE V_DEBITOS NUMERIC(18,4);
  DECLARE VARIABLE V_DEBITOS_DEVOLUCAO NUMERIC(18,4);
  DECLARE VARIABLE V_TIPO_SERVICO VARCHAR(10);
  DECLARE VARIABLE V_TIPO_TRANSACAO VARCHAR(5);
  DECLARE VARIABLE V_DATA_PAGAMENTO DATE;
  DECLARE VARIABLE V_SERVICO_DEVOLUCAO_75 VARCHAR(10);
  DECLARE VARIABLE V_SERVICO_DEVOLUCAO_APRESENTANTE VARCHAR(10);
  DECLARE VARIABLE V_SERVICO_DEVOLUCAO_100 VARCHAR(10);
  DECLARE VARIABLE V_SERVICO_DEVOLUCAO_TJDFT VARCHAR(10);
  DECLARE VARIABLE V_QTDE_ANDAMENTO NUMERIC(18,4);
  DECLARE VARIABLE V_DATA_HORA_BANCO DATE;
  DECLARE VARIABLE V_NUMERO_BANCO VARCHAR(10);
  DECLARE VARIABLE V_NUMERO_AGENCIA VARCHAR(10);
  DECLARE VARIABLE V_NUMERO_CONTA VARCHAR(20);
  DECLARE VARIABLE V_CPF_CNPJ_INFORMADO VARCHAR(30);
  DECLARE VARIABLE V_PEDIDO_ID_TEMP NUMERIC(18,4); --Usado para pegar o numero do protocolo anterior
  declare variable V_UF VARCHAR(3);
  declare variable V_PAGADOR_CPF VARCHAR(30);
  declare variable V_PAGADOR_NOME VARCHAR(120);
BEGIN
  -- Retornar UF
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 5 --CAIXA
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'CARTORIO'
  AND C.NOME = 'UF'
  INTO :V_UF;

  -- (2) Retornar Codigos dos Servicos de Devolucao
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_75'
  INTO :V_SERVICO_DEVOLUCAO_75;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_100'
  INTO :V_SERVICO_DEVOLUCAO_100;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_TJDFT'
  INTO :V_SERVICO_DEVOLUCAO_TJDFT;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'CAIXA'
  AND C.SECAO = 'SERVICOS'
  AND C.NOME = 'SERVICO_DEVOLUCAO_APRESENTANTE'
  INTO :V_SERVICO_DEVOLUCAO_APRESENTANTE;
  -- Fim (2)

  SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE
  INTO :V_DATA_HORA_BANCO;

  FOR SELECT DISTINCT
             (select first 1 a1.data from r_andamento a1, r_tb_tipo_andamento ta1
                where a1.tb_tipo_andamento_id = ta1.tb_tipo_andamento_id and a1.pedido_id = pr.pedido_id and ta1.tipo = 'C' order by a1.andamento_id),
             PR.NUMERO_ORDEM,
             (SELECT FIRST 1 NUMERO_ORDEM FROM R_PROTOCOLO WHERE PEDIDO_ID = PE.NOVO_PEDIDO_ID
                AND TIPO_PROTOCOLO = '1') AS NOVO_NUMERO_ORDEM, --Novo Protocolo, quando compensado ou vinculado
             (SELECT PEDIDO_ID FROM R_PEDIDO WHERE NOVO_PEDIDO_ID = PE.PEDIDO_ID) AS V_PEDIDO_ID_TEMP, --Numero do Pedido_id do Protocolo Anterior
             (SELECT coalesce(VALOR_COMPENSADO,0) FROM R_PEDIDO WHERE PEDIDO_ID = PE.NOVO_PEDIDO_ID) AS VALOR_DEVOLVIDO_COMPENSACAO, --Valor deste protocolo Devolvido via Compensacao em outro
             (SELECT coalesce(TOTAL_EMOLUMENTO,0) + coalesce(TOTAL_TAXA,0) + coalesce(TOTAL_FUNDO_RI,0) + coalesce(TOTAL_ISS,0) FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)) AS TOTAL_EMOLUMENTO,
              PE.PEDIDO_ID, PR.TIPO_PROTOCOLO, PR.PROTOCOLO_ID, PR.DATA, PE.APRESENTANTE_NOME, PE.NUMERO_BANCO,
              PE.NUMERO_AGENCIA, PE.NUMERO_CONTA, PE.CPF_CNPJ_INFORMADO,
              PE.TIPO_CONTA, PE.NUMERO_OPERACAO, PE.VALOR_COMPENSADO
      FROM R_PROTOCOLO PR, R_PEDIDO PE
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PR.TIPO_PROTOCOLO = '1'
      AND CAST(PR.DATA AS DATE) BETWEEN :V_DATA_INI AND :V_DATA_FIM
      AND (select count(*) from r_andamento a2, r_tb_tipo_andamento ta2
                where a2.tb_tipo_andamento_id = ta2.tb_tipo_andamento_id and a2.pedido_id = pr.pedido_id and ta2.tipo = 'C') > 0
      ORDER BY PR.NUMERO_ORDEM
  INTO  :DATA_ANDAMENTO, :NUMERO_ORDEM, :NOVO_NUMERO_ORDEM, :V_PEDIDO_ID_TEMP, :VALOR_DEVOLVIDO_COMPENSACAO, :TOTAL_EMOLUMENTO,
        :PEDIDO_ID, :TIPO_PROTOCOLO, :PROTOCOLO_ID, :DATA_PROTOCOLO, :APRESENTANTE_NOME,
        :V_NUMERO_BANCO, :V_NUMERO_AGENCIA, :V_NUMERO_CONTA, :V_CPF_CNPJ_INFORMADO,
        :TIPO_CONTA, :NUMERO_OPERACAO, :VALOR_COMPENSADO DO
  BEGIN
    -- (4) Inicializacao de Variaveis
    ANTIGO_NUMERO_ORDEM = NULL;
    VALOR_PAGO = 0;
    VALOR_RETIDO = 0;
    VALOR_DEVOLVIDO = 0;
    RECEITA_LIQUIDA = 0;
    DIREITO_DEVOLUCAO = 0;
    V_CREDITOS = 0;
    V_DEBITOS = 0;
    V_DEBITOS_DEVOLUCAO = 0;
    TIPO_DEVOLUCAO = ''; -- (Nenhum), 'T' (Ao TJDFT), 'A' (Ao Apresentante), 'C' (Compensados), 'E' (Especie)
    DATA_DEVOLUCAO = NULL;
    QTDE_DIAS = NULL;
    IF (:VALOR_DEVOLVIDO_COMPENSACAO IS NULL) THEN
      VALOR_DEVOLVIDO_COMPENSACAO = 0;
    IF (:VALOR_COMPENSADO IS NULL) THEN
      VALOR_COMPENSADO = 0;
    -- Fim (4)

    --(7) Pegar o numero do protocolo anterior quando existir
    SELECT NUMERO_ORDEM FROM R_PROTOCOLO
    WHERE PEDIDO_ID = :V_PEDIDO_ID_TEMP
    AND TIPO_PROTOCOLO = '1'
    INTO :ANTIGO_NUMERO_ORDEM; --Antigo Protocolo, quando este for uma compensacao do anterior
    --Fim (7)
   
    -- (5) Verificar Valores do Caixa Creditos
    PAGADOR_CPF = '';
    PAGADOR_NOME = '';
    FOR SELECT CAST(CAIXA_SERVICO_ID AS INTEGER) TIPO_SERVICO, DATA_PAGAMENTO,
               COALESCE(VALOR_PAGO,0), TIPO_TRANSACAO, cpf_cnpj_pagador, nome_pagador FROM C_CAIXA_ITEM
        WHERE TIPO_SERVICO = :TIPO_PROTOCOLO
        AND CHAVE_SERVICO = :PROTOCOLO_ID
        AND COALESCE(TIPO_TRANSACAO,'') = 'C'
    INTO :V_TIPO_SERVICO, :V_DATA_PAGAMENTO, :V_VALOR_PAGO, :V_TIPO_TRANSACAO, :V_PAGADOR_CPF, :V_PAGADOR_NOME DO
    BEGIN
      V_CREDITOS = :V_CREDITOS + :V_VALOR_PAGO;
      if ((coalesce(:PAGADOR_CPF,'') = '') and (coalesce(:PAGADOR_NOME,'') = '')) then
      begin
        PAGADOR_CPF = :V_PAGADOR_CPF;
        PAGADOR_NOME = :V_PAGADOR_NOME;
      end
    END
    --Fim (5)

    -- (6) Verificar Valores do Caixa Débitos
    FOR SELECT CAST(CAIXA_SERVICO_ID AS INTEGER) TIPO_SERVICO, DATA_PAGAMENTO,
               COALESCE(VALOR_PAGO,0), TIPO_TRANSACAO FROM C_CAIXA_ITEM
        WHERE TIPO_SERVICO = :TIPO_PROTOCOLO
        AND CHAVE_SERVICO = :PROTOCOLO_ID
        AND COALESCE(TIPO_TRANSACAO,'') = 'D'
        ORDER BY VALOR_PAGO DESC
    INTO :V_TIPO_SERVICO, :V_DATA_PAGAMENTO, :V_VALOR_PAGO, :V_TIPO_TRANSACAO DO
    BEGIN
      if (:V_UF = 'DF') then
      begin
        IF ((:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_75) OR
            (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_100) OR
            (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_TJDFT) OR
            (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_APRESENTANTE)) THEN
        BEGIN
          V_DEBITOS_DEVOLUCAO = :V_DEBITOS_DEVOLUCAO + :V_VALOR_PAGO;
          DATA_DEVOLUCAO = CAST(:V_DATA_PAGAMENTO AS DATE);
          IF (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_TJDFT) THEN
            TIPO_DEVOLUCAO = 'T'; --Ao TJDFT
          ELSE IF (:V_TIPO_SERVICO = :V_SERVICO_DEVOLUCAO_APRESENTANTE) THEN
            TIPO_DEVOLUCAO = 'A'; --Ao Apresentante
          ELSE
            TIPO_DEVOLUCAO = 'E'; --Em Especie
        END
        ELSE
        BEGIN
          V_DEBITOS = :V_DEBITOS + :V_VALOR_PAGO;
        END
      end
      else
      begin
        V_DEBITOS_DEVOLUCAO = :V_DEBITOS_DEVOLUCAO + :V_VALOR_PAGO;
        TIPO_DEVOLUCAO = 'A'; --Ao Apresentante
      end
    END
    --Fim (6)

    
    VALOR_PAGO = :V_CREDITOS - :V_DEBITOS; --Valor Pago como Deposito

    IF (:VALOR_DEVOLVIDO_COMPENSACAO > 0) THEN
      TIPO_DEVOLUCAO = 'C'; --Foi feita compensacao em outro protocolo

    if (:V_UF = 'DF') then
    begin
      if (coalesce(:TIPO_DEVOLUCAO,'') = '') THEN -- Se nao houver nenhum tipo de Devolucao e nem Compensacao (A Devolver)
      BEGIN
        VALOR_RETIDO = :TOTAL_EMOLUMENTO * 0.25;
        DIREITO_DEVOLUCAO = (:VALOR_PAGO  + :VALOR_COMPENSADO) - :VALOR_RETIDO;
        QTDE_DIAS = CAST(:V_DATA_HORA_BANCO AS DATE) - CAST(:DATA_ANDAMENTO AS DATE);
      END
      ELSE IF (:TIPO_DEVOLUCAO = 'C') THEN --Se for compensacao
      BEGIN
        VALOR_RETIDO = (:VALOR_PAGO + :VALOR_COMPENSADO) - :VALOR_DEVOLVIDO_COMPENSACAO;
        DIREITO_DEVOLUCAO = (:VALOR_PAGO  + :VALOR_COMPENSADO) - :VALOR_RETIDO;
      END
      ELSE
      BEGIN -- Se for Devolucao Ao TJDFT, Ao Apresentante ou em Especie
        VALOR_RETIDO = (:VALOR_PAGO + :VALOR_COMPENSADO) - :V_DEBITOS_DEVOLUCAO;
        VALOR_DEVOLVIDO = :V_DEBITOS_DEVOLUCAO;
        DIREITO_DEVOLUCAO = (:VALOR_PAGO  + :VALOR_COMPENSADO) - :VALOR_RETIDO;
      END
    end
    else
    begin
      select sum(coalesce(pi.valor_emolumento, 0) + coalesce(pi.valor_fundo_ri, 0) + coalesce(pi.valor_iss, 0) + coalesce(pi.valor_taxa_judiciaria, 0))
      from r_pedido_item pi
      where pi.pedido_id = :PEDIDO_ID
      and (select count(*) from g_selo_livro li where li.tabela = 'R_PEDIDO_ITEM'
      and li.campo_id = pi.pedido_item_id
      and li.selo_situacao_id = 2) > 0
      INTO :VALOR_RETIDO;

      VALOR_DEVOLVIDO = :V_DEBITOS_DEVOLUCAO;
      DIREITO_DEVOLUCAO = (:VALOR_PAGO  + :VALOR_COMPENSADO) - :VALOR_RETIDO;
      if (coalesce(:TIPO_DEVOLUCAO,'') = '') THEN -- Se nao houver nenhum tipo de Devolucao e nem Compensacao (A Devolver)
      begin
        QTDE_DIAS = CAST(:V_DATA_HORA_BANCO AS DATE) - CAST(:DATA_ANDAMENTO AS DATE);
      end
    end

    IF (:DIREITO_DEVOLUCAO < 0) THEN
      DIREITO_DEVOLUCAO = 0;

    if (:V_UF = 'DF') then
    begin
      IF (COALESCE(:TIPO_DEVOLUCAO,'') = '') THEN -- Se nao houver nenhum tipo de Devolucao e nem Compensacao (A Devolver)
      BEGIN
        SELECT COUNT(*) FROM R_ANDAMENTO
        WHERE PEDIDO_ID = :PEDIDO_ID
        AND TB_TIPO_ANDAMENTO_ID = 54 --Aguardando Procedimentos nao contabiliza
        INTO :V_QTDE_ANDAMENTO;
        IF (:V_QTDE_ANDAMENTO > 0) THEN -- Se houver o andamento, zera o direito de devolucao
        BEGIN
          DIREITO_DEVOLUCAO = 0;
          DATA_DEVOLUCAO = NULL;
        END
      END
    end
    RECEITA_LIQUIDA = :VALOR_RETIDO;
    
    -- (3) Montar Informacoes da Conta para Devolucao
    if (:V_UF = 'DF') then
    begin
      CONTA = NULL;
      IF ((:V_NUMERO_BANCO IS NOT NULL) AND (:V_NUMERO_BANCO <> '')) THEN
        CONTA = 'BANCO: ' || :V_NUMERO_BANCO || ' ';
      IF ((:V_NUMERO_AGENCIA IS NOT NULL) AND (:V_NUMERO_AGENCIA <> '')) THEN
      BEGIN
        IF (:CONTA IS NOT NULL) THEN
          CONTA = :CONTA || 'AGENCIA: ' || :V_NUMERO_AGENCIA || ' ';
        ELSE
          CONTA = 'AGENCIA: ' || :V_NUMERO_AGENCIA || ' ';
      END
      IF ((:V_NUMERO_CONTA IS NOT NULL) AND (:V_NUMERO_CONTA <> '')) THEN
      BEGIN
        IF (:CONTA IS NOT NULL) THEN
          CONTA = :CONTA || 'CONTA: ' || :V_NUMERO_CONTA || ' ';
        ELSE
          CONTA = 'CONTA: ' || :V_NUMERO_CONTA || ' ';
      END
      IF ((:NUMERO_OPERACAO IS NOT NULL) AND (:NUMERO_OPERACAO <> '')) THEN
      BEGIN
        IF (:CONTA IS NOT NULL) THEN
          CONTA = :CONTA || 'OPERACAO.: ' || :NUMERO_OPERACAO || ' ';
        ELSE
          CONTA = 'OPERACAO: ' || :NUMERO_OPERACAO || ' ';
      END
      IF ((:V_CPF_CNPJ_INFORMADO IS NOT NULL) AND (:V_CPF_CNPJ_INFORMADO <> '')) THEN
      BEGIN
        IF (:CONTA IS NOT NULL) THEN
          CONTA = :CONTA || 'CPF/CNPJ: ' || :V_CPF_CNPJ_INFORMADO || ' ';
        ELSE
          CONTA = 'CPF/CNPJ: ' || :V_CPF_CNPJ_INFORMADO || ' ';
      END
      IF ((:TIPO_CONTA IS NULL) AND (:CONTA IS NOT NULL)) THEN
        CONTA = 'C/C '|| :CONTA;
      ELSE IF ((:TIPO_CONTA = 'P') AND (:CONTA IS NOT NULL)) THEN
        CONTA = 'C/P '|| :CONTA;
      ELSE IF ((:TIPO_CONTA = 'C') AND (:CONTA IS NOT NULL)) THEN
        CONTA = 'C/C '|| :CONTA;
    end
    -- Fim (3)

    if ((coalesce(:V_RETORNAR_VALOR_DEVOLUCAO_ZERADOS,'') = 'N') and (coalesce(:DIREITO_DEVOLUCAO,0) = 0)) then
    begin
      --nao fazer nada
    end
    else
    begin
      if (:V_UF = 'DF') then
      begin
        IF (:V_TIPO = 'T') THEN --TODOS
        BEGIN
          SUSPEND;
        END
        ELSE IF (:V_TIPO = 'D') THEN --DEVOLVIDOS OU COMPENSADOS
        BEGIN
          IF ((:TIPO_DEVOLUCAO = 'T') OR (:TIPO_DEVOLUCAO = 'A') OR (:TIPO_DEVOLUCAO = 'E') OR (:TIPO_DEVOLUCAO = 'C'))THEN
          BEGIN
            SUSPEND;
          END
        END
        ELSE IF (:V_TIPO = 'A') THEN --EM ABERTO ate 59 DIAS
        BEGIN
          IF (coalesce(:TIPO_DEVOLUCAO,'') = '') THEN -- Nao houve devolucao
          BEGIN
            SUSPEND;
          END
        END
        /*ELSE IF (:V_TIPO = 'M') THEN --EM ABERTO A MAIS DE 60 DIAS
        BEGIN
          IF (((:TIPO_DEVOLUCAO = '') OR (:TIPO_DEVOLUCAO IS NULL)) AND ((:QTDE_DIAS> 59) AND (:QTDE_DIAS IS NOT NULL))) THEN
          BEGIN
            SUSPEND;
          END
        END*/
      end
      else
      begin
        IF (:V_TIPO = 'T') THEN --TODOS
        BEGIN
          SUSPEND;
        END
        ELSE IF (:V_TIPO = 'D') THEN --DEVOLVIDOS OU COMPENSADOS
        BEGIN
          IF (:TIPO_DEVOLUCAO = 'A') THEN
          BEGIN
            SUSPEND;
          END
        END
        ELSE IF (:V_TIPO = 'A') THEN --EM ABERTO ate 59 DIAS
        BEGIN
          if ((coalesce(:TIPO_DEVOLUCAO,'') = '') and (coalesce(:QTDE_DIAS,0) < 60)) THEN -- Nao houve devolucao até 60 dias
          BEGIN
            SUSPEND;
          END
        END
        ELSE IF (:V_TIPO = 'M') THEN --EM ABERTO A MAIS DE 60 DIAS
        BEGIN
          if ((coalesce(:TIPO_DEVOLUCAO,'') = '') and (coalesce(:QTDE_DIAS,0) > 59)) THEN
          BEGIN
            SUSPEND;
          END
        END
      end
    end
  END
END ^

ALTER PROCEDURE R_DEVOLUCAO_TOTAL (V_DATA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_INDICE NUMERIC(18, 4),
V_TIPO VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (TOTAL_EMOLUMENTO NUMERIC(18, 4),
TOTAL_VALOR_PAGO NUMERIC(18, 4),
TOTAL_DIREITO NUMERIC(18, 4),
TOTAL_DIREITO_ATUALIZADO NUMERIC(18, 4),
TOTAL_VALOR_RETIDO NUMERIC(18, 4),
TOTAL_VALOR_DEVOLVIDO NUMERIC(18, 4),
TOTAL_RECEITA_LIQUIDA NUMERIC(18, 4),
TOTAL_DEVOLVIDO_ESPECIE NUMERIC(18, 4),
TOTAL_DEVOLVIDO_APRESENTANTE NUMERIC(18, 4),
TOTAL_DEVOLVIDO_TJDFT NUMERIC(18, 4),
TOTAL_DEVOLVIDO_COMPENSACAO NUMERIC(18, 4))
AS 
DECLARE V_TOTAL_EMOLUMENTO NUMERIC(18,4);
  DECLARE V_TOTAL_VALOR_PAGO NUMERIC(18,4);
  DECLARE V_TOTAL_DIREITO NUMERIC(18,4);
  DECLARE V_TOTAL_DIREITO_ATUALIZADO NUMERIC(18,4);
  DECLARE V_TOTAL_VALOR_RETIDO NUMERIC(18,4);
  DECLARE V_TOTAL_VALOR_DEVOLVIDO NUMERIC(18,4);
  DECLARE V_TOTAL_VALOR_DEVOLVIDO_COMPENSACAO NUMERIC(18,4);
  
  DECLARE V_TOTAL_RECEITA_LIQUIDA NUMERIC(18,4);

  DECLARE V_TOTAL_DEVOLVIDO_ESPECIE NUMERIC(18,4);
  DECLARE V_TOTAL_DEVOLVIDO_APRESENTANTE NUMERIC(18,4);
  DECLARE V_TOTAL_DEVOLVIDO_TJDFT NUMERIC(18,4);
  DECLARE V_TOTAL_DEVOLVIDO_COMPENSACAO NUMERIC(18,4);

  DECLARE V_TIPO_DEVOLUCAO VARCHAR(1); -- '' (Nenhum), 'T' (Ao TJDFT), 'A' (Ao Apresentante), 'C' (Compensados), 'E' (Especie)
BEGIN
  TOTAL_EMOLUMENTO = 0;
  TOTAL_VALOR_PAGO = 0;
  TOTAL_DIREITO = 0;
  TOTAL_DIREITO_ATUALIZADO = 0;
  TOTAL_VALOR_RETIDO = 0;
  TOTAL_VALOR_DEVOLVIDO = 0;
  TOTAL_RECEITA_LIQUIDA = 0;
  TOTAL_DEVOLVIDO_ESPECIE = 0;
  TOTAL_DEVOLVIDO_APRESENTANTE = 0;
  TOTAL_DEVOLVIDO_TJDFT = 0;
  TOTAL_DEVOLVIDO_COMPENSACAO = 0;

  FOR SELECT TOTAL_EMOLUMENTO,
             VALOR_PAGO,
             DIREITO_DEVOLUCAO,
             DIREITO_DEVOLUCAO_ATUALIZADO,
             VALOR_RETIDO,
             VALOR_DEVOLVIDO,
             VALOR_DEVOLVIDO_COMPENSACAO,
             RECEITA_LIQUIDA,
             TIPO_DEVOLUCAO
      FROM R_DEVOLUCAO(:V_DATA_INI, :V_DATA_FIM, :V_INDICE, :V_TIPO)
  INTO      :V_TOTAL_EMOLUMENTO,
            :V_TOTAL_VALOR_PAGO,
            :V_TOTAL_DIREITO,
            :V_TOTAL_DIREITO_ATUALIZADO,
            :V_TOTAL_VALOR_RETIDO,
            :V_TOTAL_VALOR_DEVOLVIDO,
            :V_TOTAL_VALOR_DEVOLVIDO_COMPENSACAO,
            :V_TOTAL_RECEITA_LIQUIDA,
            :V_TIPO_DEVOLUCAO DO
  BEGIN
    V_TOTAL_DEVOLVIDO_ESPECIE = 0;
    V_TOTAL_DEVOLVIDO_APRESENTANTE =0;
    V_TOTAL_DEVOLVIDO_TJDFT = 0;

    IF (:V_TOTAL_VALOR_DEVOLVIDO_COMPENSACAO IS NULL) THEN
      V_TOTAL_VALOR_DEVOLVIDO_COMPENSACAO = 0;

    V_TOTAL_DEVOLVIDO_COMPENSACAO = :V_TOTAL_VALOR_DEVOLVIDO_COMPENSACAO;

    IF (:V_TOTAL_VALOR_DEVOLVIDO IS NULL) THEN
      V_TOTAL_VALOR_DEVOLVIDO = 0;

    IF (:V_TIPO_DEVOLUCAO = 'E') THEN --Devolvido em Especie
      V_TOTAL_DEVOLVIDO_ESPECIE = :V_TOTAL_VALOR_DEVOLVIDO;
    ELSE IF (:V_TIPO_DEVOLUCAO = 'A') THEN --Devolvido ao Apresentante via deposito
      V_TOTAL_DEVOLVIDO_APRESENTANTE = :V_TOTAL_VALOR_DEVOLVIDO;
    ELSE IF (:V_TIPO_DEVOLUCAO = 'T') THEN --Devolvido ao TJDFT
      V_TOTAL_DEVOLVIDO_TJDFT = :V_TOTAL_VALOR_DEVOLVIDO;


    IF (:V_TOTAL_EMOLUMENTO IS NULL) THEN
      V_TOTAL_EMOLUMENTO = 0;
    IF (:V_TOTAL_VALOR_PAGO IS NULL) THEN
      V_TOTAL_VALOR_PAGO = 0;
    IF (:V_TOTAL_DIREITO IS NULL) THEN
      V_TOTAL_DIREITO = 0;
    IF (:V_TOTAL_DIREITO_ATUALIZADO IS NULL) THEN
      V_TOTAL_DIREITO_ATUALIZADO = 0;
    IF (:V_TOTAL_VALOR_RETIDO IS NULL) THEN
      V_TOTAL_VALOR_RETIDO = 0;
    IF (:V_TOTAL_RECEITA_LIQUIDA IS NULL) THEN
      V_TOTAL_RECEITA_LIQUIDA = 0;

    TOTAL_EMOLUMENTO = :TOTAL_EMOLUMENTO + :V_TOTAL_EMOLUMENTO;
    TOTAL_VALOR_PAGO = :TOTAL_VALOR_PAGO + :V_TOTAL_VALOR_PAGO;
    TOTAL_DIREITO = :TOTAL_DIREITO + :V_TOTAL_DIREITO;
    TOTAL_DIREITO_ATUALIZADO = :TOTAL_DIREITO_ATUALIZADO + :V_TOTAL_DIREITO_ATUALIZADO;
    TOTAL_VALOR_RETIDO = :TOTAL_VALOR_RETIDO + :V_TOTAL_VALOR_RETIDO;
    TOTAL_VALOR_DEVOLVIDO = :TOTAL_VALOR_DEVOLVIDO + :V_TOTAL_VALOR_DEVOLVIDO;
    TOTAL_RECEITA_LIQUIDA = :TOTAL_RECEITA_LIQUIDA + :V_TOTAL_RECEITA_LIQUIDA;
    TOTAL_DEVOLVIDO_ESPECIE = :TOTAL_DEVOLVIDO_ESPECIE + :V_TOTAL_DEVOLVIDO_ESPECIE;
    TOTAL_DEVOLVIDO_APRESENTANTE = :TOTAL_DEVOLVIDO_APRESENTANTE + :V_TOTAL_DEVOLVIDO_APRESENTANTE;
    TOTAL_DEVOLVIDO_TJDFT = :TOTAL_DEVOLVIDO_TJDFT + :V_TOTAL_DEVOLVIDO_TJDFT;
    TOTAL_DEVOLVIDO_COMPENSACAO = :TOTAL_DEVOLVIDO_COMPENSACAO + :V_TOTAL_DEVOLVIDO_COMPENSACAO;
  END
  SUSPEND;
END ^

ALTER PROCEDURE R_DIA_UTIL (V_DATA DATE)
RETURNS (EH_DIA_UTIL VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
declare variable V_31_DEZEMBRO DATE;
  declare variable V_1_JANEIRO DATE;
  declare variable V_1_MAIO DATE;
  declare variable V_7_SETEMBRO DATE;
  declare variable V_15_NOVEMBRO DATE;
  declare variable V_24_DEZEMBRO DATE;
  declare variable V_25_DEZEMBRO DATE;
  declare variable V_QTDE_FERIADO integer;
begin
  V_31_DEZEMBRO = CAST('31.12.'||EXTRACT(YEAR FROM :V_DATA) AS DATE);
  V_1_JANEIRO = CAST('01.01.'||EXTRACT(YEAR FROM :V_DATA) AS DATE);
  V_1_MAIO = CAST('01.05.'||EXTRACT(YEAR FROM :V_DATA) AS DATE);
  V_7_SETEMBRO = CAST('07.09.'||EXTRACT(YEAR FROM :V_DATA) AS DATE);
  V_15_NOVEMBRO = CAST('15.11.'||EXTRACT(YEAR FROM :V_DATA) AS DATE);
  V_24_DEZEMBRO = CAST('24.12.'||EXTRACT(YEAR FROM :V_DATA) AS DATE);
  V_25_DEZEMBRO = CAST('25.12.'||EXTRACT(YEAR FROM :V_DATA) AS DATE);

  if ((:V_DATA <> :V_31_DEZEMBRO) and
     (:V_DATA <> :V_1_JANEIRO) and
     (:V_DATA <> :V_1_MAIO) and
     (:V_DATA <> :V_7_SETEMBRO) and
     (:V_DATA <> :V_15_NOVEMBRO) and
     (:V_DATA <> :V_24_DEZEMBRO) and
     (:V_DATA <> :V_25_DEZEMBRO) and
     (EXTRACT(WEEKDAY FROM :V_DATA) <> 0) and -- não é domingo
     (EXTRACT(WEEKDAY FROM :V_DATA) <> 6)) then -- não é sábado
   begin
     SELECT COUNT(*) FROM g_feriado
     WHERE data = :V_DATA
     INTO :V_QTDE_FERIADO;
     if (:V_QTDE_FERIADO > 0) then
     begin
       EH_DIA_UTIL = 'N';
     end
     else
     begin
       EH_DIA_UTIL = 'S';
     end
   end
   else
   begin
     EH_DIA_UTIL = 'N';
   end
  SUSPEND;
end ^

ALTER PROCEDURE R_DISTRIBUICAO_TITULOS (V_DATA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO_PESQUISA VARCHAR(3) CHARACTER SET ISO8859_1,
V_TIPO_RETORNO VARCHAR(3) CHARACTER SET ISO8859_1,
V_USUARIO_ID INTEGER)
RETURNS (TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
PROTOCOLO_ID INTEGER,
NUMERO_ORDEM INTEGER,
DATA_PROTOCOLO TIMESTAMP,
PEDIDO_ID INTEGER,
TB_TITULO_ID INTEGER,
NATUREZA_TITULO_ID INTEGER,
APRESENTANTE_NOME VARCHAR(260) CHARACTER SET ISO8859_1,
TOTAL_GERAL NUMERIC(18, 2),
DATA_DISTRIBUICAO TIMESTAMP,
ANDAMENTO_ID_DISTRIBUICAO INTEGER,
DATA_ANDAMENTO_DISTRIBUICAO TIMESTAMP,
ANDAMENTO_ID_FINALIZADO INTEGER,
DATA_ANDAMENTO_FINALIZACAO TIMESTAMP,
PEDIDO_DISTRIBUICAO_ID INTEGER,
QTDE_DIAS INTEGER,
DESCRICAO_TITULO VARCHAR(260) CHARACTER SET ISO8859_1,
DESCRICAO_NATUREZA VARCHAR(260) CHARACTER SET ISO8859_1)
AS 
declare variable V_UF VARCHAR(3);
  declare variable V_TIPO_ANDAMENTO_DISTRIBUICAO varchar(20);
  declare variable V_TIPO_ANDAMENTO_FINALIZA_DISTRIBUICAO varchar(20);
  declare variable V_SQL VARCHAR(10000);
  declare variable v_count integer;
  declare variable v_natureza_titulo_id_1 integer;
  declare variable v_natureza_titulo_id_2 integer;
BEGIN
  -- Retornar UF
  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 5 --CAIXA
  AND G.DESCRICAO = 'PRINCIPAL'
  AND C.SECAO = 'CARTORIO'
  AND C.NOME = 'UF'
  INTO :V_UF;


  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'PEDIDO'
  AND C.SECAO = 'DISTRIBUICAO_SERVICO'
  AND C.NOME = 'TIPO_ANDAMENTO_DISTRIBUICAO'
  INTO :V_TIPO_ANDAMENTO_DISTRIBUICAO;

  SELECT C.VALOR FROM G_CONFIG C, G_CONFIG_GRUPO G
  WHERE C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  AND G.SISTEMA_ID = 1
  AND G.DESCRICAO = 'PEDIDO'
  AND C.SECAO = 'DISTRIBUICAO_SERVICO'
  AND C.NOME = 'TIPO_ANDAMENTO_FINALIZA_DISTRIBUICAO'
  INTO :V_TIPO_ANDAMENTO_FINALIZA_DISTRIBUICAO;

  if (coalesce(:V_TIPO_PESQUISA,'') = 'P') then --pela data do protocolo
  begin
 /*   V_SQL = ' select pr.tipo_protocolo, pr.protocolo_id, pr.numero_ordem, pr.data, pr.pedido_id, pe.tb_titulo_id,
                pe.apresentante_nome, pd.data
              from r_protocolo pr,
                   r_pedido pe left join r_pedido_distribuicao pd
                     on (pe.pedido_id = pd.pedido_id)
              where pr.pedido_id = pe.pedido_id
              and pr.tipo_protocolo = '||'''1'''||'
              and pr.data between cast('||''''||:v_data_ini||''''||' as  timestamp) and cast('||''''||:v_data_fim||''''||' as timestamp) + 0.9999 ';*/

    V_SQL = ' select pr.tipo_protocolo, pr.protocolo_id, pr.numero_ordem, pr.data, pr.pedido_id, pe.tb_titulo_id,
                pe.apresentante_nome, pd.data,
                (select first 1 pi.natureza_titulo_id from r_pedido_item pi, g_natureza_titulo nt
                   where pi.pedido_id = pe.pedido_id
                   and pi.natureza_titulo_id = nt.natureza_titulo_id
                   and nt.emitir_etiqueta = '||'''S'''||'
                   order by pi.pedido_item_id),

                (select first 1 pi.natureza_titulo_id from r_pedido_item pi
                   where pi.pedido_id = pe.pedido_id),

                (select sum(coalesce(pi.valor_emolumento,0)+coalesce(pi.valor_taxa_judiciaria,0)+coalesce(pi.valor_fundo_ri,0)+coalesce(pi.valor_iss,0))
                   from r_pedido_item pi
                   where pi.pedido_id = pe.pedido_id),

                 pd.pedido_distribuicao_id
              from r_pedido pe, r_protocolo pr
                left join r_pedido_distribuicao pd
                on (pr.pedido_id = pd.pedido_id)
              where pr.pedido_id = pe.pedido_id
              and pr.tipo_protocolo = '||'''1'''||'
              and pr.data between cast('||''''||:v_data_ini||''''||' as  timestamp) and cast('||''''||:v_data_fim||''''||' as timestamp) + 0.9999 ';
  end
  else --pela data da distribuicao
  begin
    V_SQL = ' select pr.tipo_protocolo, pr.protocolo_id, pr.numero_ordem, pr.data, pr.pedido_id, pe.tb_titulo_id,
                pe.apresentante_nome, pd.data,
                (select first 1 pi.natureza_titulo_id from r_pedido_item pi, g_natureza_titulo nt
                   where pi.pedido_id = pe.pedido_id
                   and pi.natureza_titulo_id = nt.natureza_titulo_id
                   and nt.emitir_etiqueta = '||'''S'''||'
                   order by pi.pedido_item_id),

                (select first 1 pi.natureza_titulo_id from r_pedido_item pi
                   where pi.pedido_id = pe.pedido_id),

                (select sum(coalesce(pi.valor_emolumento,0)+coalesce(pi.valor_taxa_judiciaria,0)+coalesce(pi.valor_fundo_ri,0)+coalesce(pi.valor_iss,0))
                   from r_pedido_item pi
                   where pi.pedido_id = pe.pedido_id),

                 pd.pedido_distribuicao_id
              from r_pedido pe, r_protocolo pr
                left join r_pedido_distribuicao pd
                on (pr.pedido_id = pd.pedido_id)
              where pr.pedido_id = pe.pedido_id
              and pr.tipo_protocolo = '||'''1'''||'
              and pd.data between cast('||''''||:v_data_ini||''''||' as  timestamp) and cast('||''''||:v_data_fim||''''||' as timestamp) + 0.9999 ';
  end

  if (coalesce(:V_TIPO_RETORNO,'') = '2') then
  begin
    v_sql = :v_sql || ' and coalesce(pd.pedido_distribuicao_id,0) > 0 ';
  end
  else if (coalesce(:V_TIPO_RETORNO,'') = '3') then
  begin
    v_sql = :v_sql || ' and coalesce(pd.pedido_distribuicao_id,0) = 0 ';
  end

  if (coalesce(:V_USUARIO_ID,0) > 0) then
  begin
    v_sql = :v_sql || ' and pd.usuario_id_recebeu = '||:v_usuario_id;
  end

  v_sql = :v_sql || ' order by pr.numero_ordem ';

  FOR EXECUTE STATEMENT V_SQL
      INTO :TIPO_PROTOCOLO, :PROTOCOLO_ID, :NUMERO_ORDEM, :DATA_PROTOCOLO, :PEDIDO_ID,
        :TB_TITULO_ID, :APRESENTANTE_NOME, :data_distribuicao, :v_natureza_titulo_id_1, :v_natureza_titulo_id_2,
        :total_geral, :pedido_distribuicao_id do
  BEGIN
    natureza_titulo_id = null;
    andamento_id_distribuicao = null;
    data_andamento_distribuicao = null;
    andamento_id_finalizado = null;
    data_andamento_finalizacao = null;
    qtde_dias = 0;

    if (coalesce(:v_natureza_titulo_id_1,0) > 0) then
    begin
      natureza_titulo_id = :v_natureza_titulo_id_1;
    end
    else
    begin
      natureza_titulo_id = :v_natureza_titulo_id_2;
    end

    select first 1 a.andamento_id, cast(a.data as date) from r_andamento a
    where a.pedido_id = :pedido_id
    and a.tb_tipo_andamento_id = :v_tipo_andamento_distribuicao
    into :andamento_id_distribuicao, :data_andamento_distribuicao;

    select first 1 a.andamento_id, cast(a.data as date) from r_andamento a
    where a.pedido_id = :pedido_id
    and a.tb_tipo_andamento_id = :v_tipo_andamento_finaliza_distribuicao
    into :andamento_id_finalizado, :data_andamento_finalizacao;

    if ((:andamento_id_distribuicao > 0) and (:andamento_id_finalizado > 0)) then
    begin
      qtde_dias = (:data_andamento_finalizacao - :data_andamento_distribuicao);
    end
    else
    begin
      qtde_dias = (current_timestamp - :data_andamento_distribuicao);
    end

    select descricao from r_tb_titulo
    where tb_titulo_id = :TB_TITULO_ID
    into :descricao_titulo;

    select descricao from g_natureza_titulo
    where natureza_titulo_id = :natureza_titulo_id
    into :descricao_natureza;

    SUSPEND;
  END
END ^

ALTER PROCEDURE R_DUPLICAR_PEDIDO (V_PEDIDO_ID INTEGER,
V_QUANTIDADE_A_GERAR INTEGER)
RETURNS (PEDIDO_ID INTEGER)
AS 
declare variable V_PEDIDO_ID_NOVO INTEGER;
  declare variable V_PEDIDO_ITEM_ID_NOVO INTEGER;
  declare variable V_PEDIDO_ITEM_NUMERO_ID_NOVO INTEGER;

  declare variable V_PEDIDO_ITEM_ID INTEGER;
  declare variable V_PEDIDO_ITEM_NUMERO_ID INTEGER;

  declare variable i integer;
BEGIN
  i = 1;
  WHILE (i <= :V_QUANTIDADE_A_GERAR) DO
  BEGIN
    SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('R_PEDIDO')
    INTO :V_PEDIDO_ID_NOVO;
    INSERT INTO R_PEDIDO(PEDIDO_ID, DATA_PEDIDO, APRESENTANTE_NOME, APRESENTANTE_CPF_CNPJ,
      APRESENTANTE_FONE, ADQUIRENTE_NOME, ADQUIRENTE_CPF_CNPJ, TRANSMITENTE_NOME, TRANSMITENTE_CPF_CNPJ,
      OBSERVACAO, TB_TITULO_ID, ENDERECO, INFORMADO_CONTA, NUMERO_BANCO,
      NUMERO_AGENCIA, NUMERO_CONTA, CPF_CNPJ_INFORMADO, NUMERO_OPERACAO, TIPO_CONTA, NOME_TITULAR_CONTA,
      NUMERO_PAGINA, ORIGEM_PEDIDO, DATA_TITULO, TIPO_INCLUSAO, APRESENTANTE_EMAIL, TITULO_LIVRO,
      TITULO_FOLHA_INICIAL, TITULO_FOLHA_FINAL,  TITULO_CONTRATO,  MOTIVO_ISENTO, TIPO_COBRANCA,
      DESCRICAO_ISENTO_OUTROS, EMAIL_CONTATO, CELULAR_CONTATO, ADQUIRENTE_TIPO_DOC,
      TRANSMITENTE_TIPO_DOC, APRESENTANTE_TIPO_DOC, EMITIR_NOTA_PARA, OUTROS_TITULOS, ENDERECO_NFSE,
      ENDERECO_NUMERO_NFSE, ENDERECO_COMPL_NFSE, ENDERECO_BAIRRO_NFSE, ENDERECO_COD_MUN_NFSE,
      ENDERECO_CEP_NFSE, ENDERECO_MUNICIPIO_NFSE, ENDERECO_UF_NFSE, EH_OPTANTE_SIMPLES_NFSE,
      CPF_NFSE, NOME_NFSE, TIPO_DOC_NFSE, IE_NFSE, IM_NFSE)
    SELECT :V_PEDIDO_ID_NOVO, current_date, APRESENTANTE_NOME, APRESENTANTE_CPF_CNPJ,
      APRESENTANTE_FONE, ADQUIRENTE_NOME, ADQUIRENTE_CPF_CNPJ, TRANSMITENTE_NOME, TRANSMITENTE_CPF_CNPJ,
      OBSERVACAO, TB_TITULO_ID, ENDERECO, INFORMADO_CONTA, NUMERO_BANCO,
      NUMERO_AGENCIA, NUMERO_CONTA, CPF_CNPJ_INFORMADO, NUMERO_OPERACAO, TIPO_CONTA, NOME_TITULAR_CONTA,
      NUMERO_PAGINA, '1', DATA_TITULO, TIPO_INCLUSAO, APRESENTANTE_EMAIL, TITULO_LIVRO,
      TITULO_FOLHA_INICIAL, TITULO_FOLHA_FINAL,  TITULO_CONTRATO,  MOTIVO_ISENTO, TIPO_COBRANCA,
      DESCRICAO_ISENTO_OUTROS, EMAIL_CONTATO, CELULAR_CONTATO, ADQUIRENTE_TIPO_DOC,
      TRANSMITENTE_TIPO_DOC, APRESENTANTE_TIPO_DOC, EMITIR_NOTA_PARA, OUTROS_TITULOS, ENDERECO_NFSE,
      ENDERECO_NUMERO_NFSE, ENDERECO_COMPL_NFSE, ENDERECO_BAIRRO_NFSE, ENDERECO_COD_MUN_NFSE,
      ENDERECO_CEP_NFSE, ENDERECO_MUNICIPIO_NFSE, ENDERECO_UF_NFSE, EH_OPTANTE_SIMPLES_NFSE,
      CPF_NFSE, NOME_NFSE, TIPO_DOC_NFSE, IE_NFSE, IM_NFSE FROM R_PEDIDO WHERE PEDIDO_ID = :V_PEDIDO_ID;

    PEDIDO_ID = :V_PEDIDO_ID_NOVO;
  
    FOR SELECT PEDIDO_ITEM_ID FROM R_PEDIDO_ITEM WHERE PEDIDO_ID = :V_PEDIDO_ID
        INTO :V_PEDIDO_ITEM_ID DO
    BEGIN
      SELECT GEN_ID(PEDIDO_ITEM_SEQ,1) FROM RDB$DATABASE
      INTO :V_PEDIDO_ITEM_ID_NOVO;
  
      INSERT INTO R_PEDIDO_ITEM(PEDIDO_ITEM_ID, PEDIDO_ID, NATUREZA_TITULO_ID,
        VALOR_DOCUMENTO, VALOR_EMOLUMENTO, VALOR_TAXA_JUDICIARIA, QUANTIDADE, EMOLUMENTO_ID, CALCULADO,
        FICHA, VALOR_DESCONTO,  PORCENTAGEM_DESCONTO, VALOR_UNITARIO, USUARIO_DESCONTO_ID, TIPO_PEDIDO,
        LETRA_NUMERO, SEQUENCIA, QUANTIDADE_BUSCA, QUANTIDADE_FOLHA_EXCEDENTE,
        VALOR_FUNDO_RI, CODIGO_TABELA_EMOLUMENTOS, VALOR_ITBI, NUMERO_CARTORIO, QUANTIDADE_ATOS_ACRESCIDOS,
        TIPO_ATOS_ACRESCIDOS, QUANTIDADE_QUESITOS, EMOLUMENTO_ID_ATOS_ACRESCIDOS, EMOLUMENTO_ID_QUESITOS,
        EMOLUMENTO_ITEM_ID, EMOLUMENTO_ID_ATOS_ACRESC_COMPL, EMOLUMENTO_ID_QUESITOS_COMPL, VALOR_MERCADO,
        VALOR_ISS, EH_ISENTO, QUANTIDADE_PAGINA, QUANTIDADE_UNIDADE_AUTONOMA, MOTIVO_ISENCAO, VALOR_OUTROS,
        VALOR_EMOLUMENTO_BUSCA, VALOR_FUNDO_RI_BUSCA, VALOR_TAXA_JUD_BUSCA, VALOR_EMOLUMENTO_FOLHA,
        VALOR_FUNDO_RI_FOLHA, VALOR_TAXA_JUD_FOLHA)
      SELECT :V_PEDIDO_ITEM_ID_NOVO, :V_PEDIDO_ID_NOVO, NATUREZA_TITULO_ID,
        VALOR_DOCUMENTO, VALOR_EMOLUMENTO, VALOR_TAXA_JUDICIARIA, QUANTIDADE, EMOLUMENTO_ID, CALCULADO,
        FICHA, VALOR_DESCONTO,  PORCENTAGEM_DESCONTO, VALOR_UNITARIO, USUARIO_DESCONTO_ID, TIPO_PEDIDO,
        LETRA_NUMERO, SEQUENCIA, QUANTIDADE_BUSCA, QUANTIDADE_FOLHA_EXCEDENTE,
        VALOR_FUNDO_RI, CODIGO_TABELA_EMOLUMENTOS, VALOR_ITBI, NUMERO_CARTORIO, QUANTIDADE_ATOS_ACRESCIDOS,
        TIPO_ATOS_ACRESCIDOS, QUANTIDADE_QUESITOS, EMOLUMENTO_ID_ATOS_ACRESCIDOS, EMOLUMENTO_ID_QUESITOS,
        EMOLUMENTO_ITEM_ID, EMOLUMENTO_ID_ATOS_ACRESC_COMPL, EMOLUMENTO_ID_QUESITOS_COMPL, VALOR_MERCADO,
        VALOR_ISS, EH_ISENTO, QUANTIDADE_PAGINA, QUANTIDADE_UNIDADE_AUTONOMA, MOTIVO_ISENCAO, VALOR_OUTROS,
        VALOR_EMOLUMENTO_BUSCA, VALOR_FUNDO_RI_BUSCA, VALOR_TAXA_JUD_BUSCA, VALOR_EMOLUMENTO_FOLHA,
        VALOR_FUNDO_RI_FOLHA, VALOR_TAXA_JUD_FOLHA FROM R_PEDIDO_ITEM  WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID;
  
      FOR SELECT PEDIDO_ITEM_NUMERO_ID FROM R_PEDIDO_ITEM_NUMERO WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID DO
      BEGIN
        SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('R_PEDIDO_ITEM_NUMERO')
        INTO :V_PEDIDO_ITEM_NUMERO_ID_NOVO;
  
        INSERT INTO R_PEDIDO_ITEM_NUMERO(PEDIDO_ITEM_NUMERO_ID, PEDIDO_ITEM_ID, NUMERO, ATO_TIPO, ATO_NUMERO,
           TIPO_REGISTRO, LOGRADOURO, NOME, CPF, DOCUMENTO, NOME_SOLTEIRO, SEXO, ESTADO_CIVIL, CONJUGE,
           CONJUGE_SOLTEIRO,  CONJUGE_CPF,  CONJUGE_DOCUMENTO,  NUMERO_LETRA, ENDERECO_RESIDENCIAL,
           PROFISSAO,  CONJUGE_PROFISSAO, CARTORIO)
        SELECT :V_PEDIDO_ITEM_NUMERO_ID_NOVO, :V_PEDIDO_ITEM_ID_NOVO, NUMERO, ATO_TIPO, ATO_NUMERO,
           TIPO_REGISTRO, LOGRADOURO, NOME, CPF, DOCUMENTO, NOME_SOLTEIRO, SEXO, ESTADO_CIVIL, CONJUGE,
           CONJUGE_SOLTEIRO,  CONJUGE_CPF,  CONJUGE_DOCUMENTO,  NUMERO_LETRA, ENDERECO_RESIDENCIAL,
           PROFISSAO,  CONJUGE_PROFISSAO, CARTORIO FROM R_PEDIDO_ITEM_NUMERO WHERE PEDIDO_ITEM_NUMERO_ID = :V_PEDIDO_ITEM_NUMERO_ID;
      END
    END
    SUSPEND;
    I = I + 1;
  END
END ^

ALTER PROCEDURE R_ENDERECO_URB_MAIS_1_MAT RETURNS (QUANTIDADE INTEGER,
BAIRRO VARCHAR(120) CHARACTER SET ISO8859_1,
QUADRA VARCHAR(120) CHARACTER SET ISO8859_1,
LOTE VARCHAR(60) CHARACTER SET ISO8859_1,
CONJUNTO VARCHAR(60) CHARACTER SET ISO8859_1,
BLOCO VARCHAR(60) CHARACTER SET ISO8859_1,
MATRICULAS VARCHAR(500) CHARACTER SET ISO8859_1)
AS 
declare variable v_numero varchar(20);
  declare variable v_numero_letra varchar(6);
begin
  for select count(*), b.descricao, coalesce(u.quadra,''),
        coalesce(u.numero_unidade,''), coalesce(u.CONJUNTO,''),
        coalesce(u.bloco,'')
      from r_imovel i, r_imovel_unidade u, g_tb_bairro b
      where i.imovel_id = u.imovel_id
      and i.tipo_registro = 'M'
      and i.tipo_classe = 'L'
      and u.tb_bairro_id = b.tb_bairro_id
      group by b.descricao, coalesce(u.quadra,''),
        coalesce(u.numero_unidade,''), coalesce(u.CONJUNTO,''),
        coalesce(u.bloco,'')
      having count(*) > 1
  into :quantidade, :bairro, :quadra, :lote, :conjunto, :bloco do
  begin
    matriculas = '';
    for select cast(i.numero as integer), coalesce(i.numero_letra,'#')
        from r_imovel i, r_imovel_unidade u, g_tb_bairro b
        where i.imovel_id = u.imovel_id
        and u.tb_bairro_id = b.tb_bairro_id
        and b.descricao = :bairro
        and coalesce(u.quadra,'') = :quadra
        and coalesce(u.numero_unidade,'') = :lote
        and coalesce(u.conjunto,'') = :conjunto
        and coalesce(u.bloco,'') = :bloco
        order by i.numero
    into :v_numero, :v_numero_letra do
    begin
      if (:v_numero_letra <> '#' ) then
      begin
        v_numero = :v_numero ||'-'||:v_numero_letra;
      end
      if (:matriculas = '') then
      begin
        matriculas = :v_numero;
      end
      else
      begin
        matriculas = :matriculas||', '||:v_numero;
      end
    end
    suspend;
  end
end ^

ALTER PROCEDURE R_ERI_VISUALIZAR_REQ_CENTRAL RETURNS (CENTRAL_ID INTEGER,
DATA_PEDIDO TIMESTAMP,
DATA_PREVISAO TIMESTAMP,
SITUACAO VARCHAR(60) CHARACTER SET ISO8859_1,
OBSERVACAO VARCHAR(260) CHARACTER SET ISO8859_1,
DATA_ENTREGUE_ANOREG TIMESTAMP,
DATA_LIMITE_PRONTAS TIMESTAMP)
AS 
DECLARE VARIABLE V_ULTIMA_DATA_PEDIDO DATE;
DECLARE VARIABLE V_QTDE_DIAS INTEGER;
DECLARE VARIABLE V_QTDE INTEGER;
DECLARE VARIABLE V_QTDE_FERIADO INTEGER;
DECLARE VARIABLE V_CENTRAL_ID INTEGER;
DECLARE VARIABLE V_DATA_LANCAR DATE;
DECLARE VARIABLE V_DIA_SEMANA INTEGER;
DECLARE VARIABLE V_DATA_PREVISAO DATE;
DECLARE VARIABLE V_QTDE_DIAS_UTEIS INTEGER;
BEGIN 
  SELECT FIRST 1 CAST(DATA_PEDIDO AS DATE) FROM R_ERI_CENTRAL 
  ORDER BY DATA_PEDIDO DESC
  INTO :V_ULTIMA_DATA_PEDIDO;
  
  SELECT FIRST 1 CAST(CURRENT_DATE - CAST(DATA_PEDIDO AS DATE) AS INTEGER) FROM R_ERI_CENTRAL 
  ORDER BY DATA_PEDIDO DESC
  INTO :V_QTDE_DIAS;
  
  --PRIMEIRO LANCAR AS DATA FALTANTES
  IF (:V_QTDE_DIAS > 0) THEN 
  BEGIN
    --CRIAR OS DIAS NAO LANCADOS
    V_QTDE = 0;
    WHILE (:V_QTDE < :V_QTDE_DIAS) DO
    BEGIN    
      V_QTDE = :V_QTDE + 1;
      V_DATA_LANCAR = :V_ULTIMA_DATA_PEDIDO + :V_QTDE;

      SELECT COUNT(*) FROM G_FERIADO 
      WHERE SITUACAO = 'A'
      AND CAST(DATA AS DATE) = :V_DATA_LANCAR
      INTO :V_QTDE_FERIADO;
      
      IF (:V_QTDE_FERIADO = 0) THEN
      BEGIN
        --VERIFICA SE EH SABADO OU DOMINGO
        --0=DOMINGO E 6=SABADO
        V_DIA_SEMANA = EXTRACT(WEEKDAY FROM :V_DATA_LANCAR);
        IF ((:V_DIA_SEMANA <> 0) AND (:V_DIA_SEMANA <> 6)) THEN
        BEGIN	
          V_DATA_PREVISAO = :V_DATA_LANCAR + 10;
          V_DIA_SEMANA = EXTRACT(WEEKDAY FROM :V_DATA_PREVISAO);
          IF (:V_DIA_SEMANA = 0) THEN --DOMINGO
          BEGIN
            V_DATA_PREVISAO = :V_DATA_PREVISAO + 1;            
          END
          IF (:V_DIA_SEMANA = 6) THEN --SABADO
          BEGIN
            V_DATA_PREVISAO = :V_DATA_PREVISAO + 2;            
          END                    
          SELECT GEN_ID(R_ERI_CENTRAL_SEQ,1) FROM RDB$DATABASE
          INTO :V_CENTRAL_ID;
          INSERT INTO R_ERI_CENTRAL(CENTRAL_ID, DATA_PEDIDO, DATA_PREVISAO, SITUACAO)
          VALUES(:V_CENTRAL_ID, :V_DATA_LANCAR, :V_DATA_PREVISAO, '1');           
        END
      END                         
    END      
  END
  
  --LISTAR OS PEDIDOS
  FOR SELECT FIRST 30 CENTRAL_ID, DATA_PEDIDO, 
        DATA_PREVISAO, OBSERVACAO, DATA_ENTREGUE_ANOREG,
        case SITUACAO 
          when '1' then 'Aguardando retorno' 
          when '2' then 'Pronto para entrega' 
          when '3' then 'Nao houve pedidos' 
          else ''
        end
      FROM R_ERI_CENTRAL 
      ORDER BY DATA_PEDIDO DESC
      INTO :CENTRAL_ID, :DATA_PEDIDO, :DATA_PREVISAO, :OBSERVACAO, 
        :DATA_ENTREGUE_ANOREG, :SITUACAO DO
  BEGIN    
    --CALCULAR QUANTIDADE DE DIAS UTEIS (5 DIAS) PARA DATA A SER ENTREGUE NA ANOREG
    V_QTDE_DIAS_UTEIS = 0;
    V_QTDE_DIAS = 0;
    WHILE (:V_QTDE_DIAS_UTEIS < 5) DO
    BEGIN    
      V_QTDE_DIAS = :V_QTDE_DIAS + 1;
      SELECT COUNT(*) FROM G_FERIADO 
      WHERE SITUACAO = 'A'
      AND CAST(DATA AS DATE) = (:DATA_PEDIDO + :V_QTDE_DIAS)
      INTO :V_QTDE_FERIADO;
      
      IF (:V_QTDE_FERIADO = 0) THEN
      BEGIN                    
        --VERIFICA SE EH SABADO OU DOMINGO
        --0=DOMINGO E 6=SABADO
        V_DIA_SEMANA = EXTRACT(WEEKDAY FROM (:DATA_PEDIDO + :V_QTDE_DIAS));
        IF ((:V_DIA_SEMANA <> 0) AND (:V_DIA_SEMANA <> 6)) THEN
        BEGIN	
          V_QTDE_DIAS_UTEIS = :V_QTDE_DIAS_UTEIS + 1;
        END
      END                         
    END        
    DATA_LIMITE_PRONTAS = (:DATA_PEDIDO + :V_QTDE_DIAS);
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_GERAR_PROTOCOLO_RETROATIVO (NUMERO_PROTOCOLO INTEGER,
DATA VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (V_QTDE INTEGER,
PEDIDO_ID INTEGER)
AS 
declare variable V_PEDIDO_ID INTEGER;
  declare variable V_COUNT INTEGER;
begin
  SELECT COUNT(*) FROM R_PROTOCOLO
  WHERE NUMERO_ORDEM = :NUMERO_PROTOCOLO
  AND TIPO_PROTOCOLO = '1'
  INTO :V_COUNT;

  PEDIDO_ID = 0;
  V_QTDE = 0;
  if (:V_COUNT = 0) then
  BEGIN
      select sequencia from G_SP_SEQUENCIAS('R_PEDIDO')
      INTO :V_PEDIDO_ID;
    
      insert into r_pedido(pedido_id, apresentante_nome, data_pedido)
      VALUES(:V_PEDIDO_ID, 'PROTOCOLO RETROATIVO', cast(:data as date));
    
      INSERT INTO R_PROTOCOLO(PROTOCOLO_ID, PEDIDO_ID, NUMERO_ORDEM, TIPO_PROTOCOLO, DATA)
      VALUES((SELECT GEN_ID(PROTOCOLO_SEQ,1) FROM RDB$DATABASE), :V_PEDIDO_ID, :NUMERO_PROTOCOLO, '1', cast(:data as date));

      PEDIDO_ID = :V_PEDIDO_ID;

      V_QTDE = 1;
  END

  suspend;
end ^

ALTER PROCEDURE R_GERAR_SEQUENCIA_PEDIDO_ITEM (PEDIDO_ID INTEGER,
PEDIDO_ITEM_ID_POSICAO1 INTEGER)
RETURNS (STATUS VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_ULTIMA_SEQ INTEGER;
  DECLARE VARIABLE V_PEDIDO_ITEM_ID INTEGER;
  DECLARE VARIABLE V_SEQUENCIA INTEGER;
BEGIN
  SELECT COALESCE(MAX(SEQUENCIA),0) FROM R_PEDIDO_ITEM
  WHERE PEDIDO_ID = :PEDIDO_ID
  INTO :V_ULTIMA_SEQ;

  --COLOCAR EM ORDEM
  FOR SELECT PEDIDO_ITEM_ID, COALESCE(SEQUENCIA,0) FROM R_PEDIDO_ITEM
      WHERE PEDIDO_ID = :PEDIDO_ID
      ORDER BY COALESCE(SEQUENCIA,0), PEDIDO_ITEM_ID
      INTO :V_PEDIDO_ITEM_ID, :V_SEQUENCIA DO
  BEGIN
    IF (:V_SEQUENCIA = 0) THEN
    BEGIN
      V_ULTIMA_SEQ = :V_ULTIMA_SEQ + 1;
      UPDATE R_PEDIDO_ITEM
      SET SEQUENCIA = :V_ULTIMA_SEQ
      WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID;
    END
  END

  --VER SE VAI COLOCAR ALGUM ITEM EM POSICAO 1
  IF (COALESCE(:PEDIDO_ITEM_ID_POSICAO1,0) > 0) THEN
  BEGIN
    UPDATE R_PEDIDO_ITEM
    SET SEQUENCIA = SEQUENCIA + 1
    WHERE PEDIDO_ID = :PEDIDO_ID;

    UPDATE R_PEDIDO_ITEM
    SET SEQUENCIA = 1
    WHERE PEDIDO_ITEM_ID = :PEDIDO_ITEM_ID_POSICAO1;
  END

  STATUS = 'OK';
  SUSPEND;
END ^

ALTER PROCEDURE R_IMOVEL_PESSOA (V_CPF_CNPJ VARCHAR(20) CHARACTER SET ISO8859_1)
RETURNS (PESSOA_ID NUMERIC(12, 2),
CPF_CNPJ VARCHAR(15) CHARACTER SET ISO8859_1,
NOME VARCHAR(120) CHARACTER SET ISO8859_1,
IMOVEL_ID NUMERIC(12, 2),
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO NUMERIC(12, 2),
TIPO_CLASSE VARCHAR(1) CHARACTER SET ISO8859_1,
IMOVEL_TIPO_ID NUMERIC(12, 2),
AREA VARCHAR(120) CHARACTER SET ISO8859_1,
ENDERECO VARCHAR(260) CHARACTER SET ISO8859_1,
NUMERO_LOGRADOURO VARCHAR(15) CHARACTER SET ISO8859_1,
COMPLEMENTO VARCHAR(260) CHARACTER SET ISO8859_1,
COMPLEMENTO_COMPLETO VARCHAR(260) CHARACTER SET ISO8859_1,
QUADRA VARCHAR(120) CHARACTER SET ISO8859_1,
NUMERO_UNIDADE VARCHAR(120) CHARACTER SET ISO8859_1,
BAIRRO VARCHAR(90) CHARACTER SET ISO8859_1,
CEP NUMERIC(12, 2),
MUNICIPIO VARCHAR(60) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_NUMERO VARCHAR(10); --Numero da mat./transc. do imovel
DECLARE VARIABLE V_NUMERO_LETRA VARCHAR(10); 
DECLARE VARIABLE V_TIPO_REGISTRO VARCHAR(1); --M, T, I ou A
DECLARE VARIABLE V_CARTORIO VARCHAR(3);
BEGIN
  FOR SELECT DISTINCT I.TIPO_REGISTRO, I.NUMERO, P.PESSOA_ID, P.CPF_CNPJ, P.NOME, I.NUMERO_LETRA, I.CARTORIO
      FROM R_IMOVEL I, R_PESSOA_VINCULO P
      WHERE I.IMOVEL_ID = P.IMOVEL_ID
      AND P.CPF_CNPJ = :V_CPF_CNPJ
  INTO :V_TIPO_REGISTRO, :V_NUMERO, :PESSOA_ID, :CPF_CNPJ, :NOME, :V_NUMERO_LETRA, :V_CARTORIO DO
  BEGIN
    SELECT FIRST 1 IMOVEL_ID, TIPO_REGISTRO, NUMERO, TIPO_CLASSE,
   	       IMOVEL_TIPO_ID, AREA, ENDERECO, NUMERO_LOGRADOURO,
  		   COMPLEMENTO, COMPLEMENTO_COMPLETO, QUADRA, NUMERO_UNIDADE,
  		   BAIRRO, CEP, MUNICIPIO
    FROM R_DADOS_IMOVEL(:V_TIPO_REGISTRO, :V_NUMERO, :V_NUMERO, :V_NUMERO_LETRA, :V_CARTORIO)
    ORDER BY IMOVEL_UNIDADE_ID DESC
    INTO :IMOVEL_ID, :TIPO_REGISTRO, :NUMERO, :TIPO_CLASSE,
   	       :IMOVEL_TIPO_ID, :AREA, :ENDERECO, :NUMERO_LOGRADOURO,
  		   :COMPLEMENTO, :COMPLEMENTO_COMPLETO, :QUADRA, :NUMERO_UNIDADE,
  		   :BAIRRO, :CEP, :MUNICIPIO   ;
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_IMOVEL_RURAL_ESTRANGEIRO (V_TIPO VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (IMOVEL_ID INTEGER,
MATRICULA VARCHAR(10) CHARACTER SET ISO8859_1,
AREA NUMERIC(14, 2),
AREA_M2 NUMERIC(14, 2),
AREA_DESCRICAO VARCHAR(120) CHARACTER SET ISO8859_1,
PESSOA_VINCULO_ID INTEGER,
CPF_CNPJ_PROPRIETARIO VARCHAR(20) CHARACTER SET ISO8859_1,
NOME_PROPRIETARIO VARCHAR(120) CHARACTER SET ISO8859_1,
NACIONALIDADE VARCHAR(120) CHARACTER SET ISO8859_1,
DATA_TRANSFERENCIA TIMESTAMP,
NUMERO_ATO VARCHAR(10) CHARACTER SET ISO8859_1,
PORCENTAGEM NUMERIC(10, 2),
CPF_CNPJ_TRANSMITENTE VARCHAR(20) CHARACTER SET ISO8859_1,
NOME_TRANSMITENTE VARCHAR(120) CHARACTER SET ISO8859_1,
AUTORIZACAO VARCHAR(60) CHARACTER SET ISO8859_1,
CARTORIO VARCHAR(10) CHARACTER SET ISO8859_1,
CARTORIO_ANTERIOR VARCHAR(10) CHARACTER SET ISO8859_1,
DESCRICAO_IMOVEL VARCHAR(120) CHARACTER SET ISO8859_1,
STATUS VARCHAR(1) CHARACTER SET ISO8859_1)
AS 
declare variable v_numero_cartorio varchar(10);
  declare variable v_tipo_registro varchar(10);
  declare variable v_matricula integer;
  declare variable v_matricula_letra varchar(10);
  declare variable v_data_envio_rural date;
  declare variable v_tipo_ato varchar(1);
  declare variable v_numero_ato integer;
begin
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'CARTORIO', 'CARTORIO_NUMERO', 1) INTO :v_numero_cartorio;

  for select i.imovel_id, i.numero, i.numero_letra, i.cartorio, i.tipo_registro, i.inscricao_imovel
      from r_imovel i
      where i.tipo_classe = 'R'
      or (i.tipo_classe = 'L' and i.TRATAR_COMO_RURAL = 'S')
      into :imovel_id, :v_matricula, :v_matricula_letra, :cartorio, :v_tipo_registro, :autorizacao do
  begin
    if (coalesce(:v_matricula_letra,'') <> '') then
    begin
      matricula = cast(:v_matricula as varchar(10))||:v_matricula_letra;
    end
    else
    begin
      matricula = :v_matricula;
    end

    cartorio_anterior = '';
    if (coalesce(:cartorio,'') <> :v_numero_cartorio) then
    begin
      cartorio_anterior = :cartorio;
    end
    cartorio = :v_numero_cartorio;

    area = 0;
    area_descricao = '';
    select first 1 coalesce(area_averbada,0), area_descritiva, nome_edificacao
    from r_imovel_unidade
    where imovel_id = :imovel_id
    into :area, :area_descricao, :descricao_imovel;

    area_m2 = :area * 10000;

    data_transferencia = null;
    cpf_cnpj_transmitente = '';
    nome_transmitente = '';
    select first 1 data_transferencia, cpf_cnpj, nome
    from r_pessoa_vinculo
    where imovel_id = :imovel_id
    and data_transferencia is not null
    order by data_transferencia desc
    into :data_transferencia, :cpf_cnpj_transmitente, :nome_transmitente;

    status = '';
    for select pessoa_vinculo_id, data_envio_estrangeiro, cpf_cnpj, nome, nacionalidade, coalesce(tipo_ato,''), coalesce(numero_ato,0), coalesce(area_percent,0)
        from r_pessoa_vinculo
        where imovel_id = :imovel_id
        and data_transferencia is null
        and coalesce(nacionalidade,'') <> ''
        and upper(coalesce(nacionalidade,'')) <> 'BRASILEIRO'
        and upper(coalesce(nacionalidade,'')) <> 'BRASILEIRA'
        into :pessoa_vinculo_id, :v_data_envio_rural, :cpf_cnpj_proprietario, :nome_proprietario, :nacionalidade, :v_tipo_ato, :v_numero_ato, :porcentagem do
    begin
      if (coalesce(:v_data_envio_rural,'') = '') then
      begin
        status = 'P';
      end
      else
      begin
        status = 'E';
      end

      numero_ato = :v_tipo_ato||'.'||cast(:v_numero_ato as varchar(10));
      if (:V_TIPO = 'T') then --todos
      begin
        suspend;
      end
      else if ((:V_TIPO = 'P') and (:status = 'P')) then --somente pendetes de envio
      begin
        suspend;
      end
    end
  end
end ^

ALTER PROCEDURE R_IMOVEL_RURAL_ESTRANGEIRO_GO (V_TIPO VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (IMOVEL_ID INTEGER,
MATRICULA VARCHAR(10) CHARACTER SET ISO8859_1,
AREA NUMERIC(14, 2),
AREA_M2 NUMERIC(14, 2),
AREA_DESCRICAO VARCHAR_260,
PESSOA_VINCULO_ID INTEGER,
CPF_CNPJ_PROPRIETARIO VARCHAR(20) CHARACTER SET ISO8859_1,
NOME_PROPRIETARIO VARCHAR(120) CHARACTER SET ISO8859_1,
DOCUMENTO_PROPRIETARIO VARCHAR(120) CHARACTER SET ISO8859_1,
NACIONALIDADE VARCHAR(120) CHARACTER SET ISO8859_1,
NACIONALIDADE_TRANSMITENTE VARCHAR(120) CHARACTER SET ISO8859_1,
DATA_TRANSFERENCIA TIMESTAMP,
NUMERO_ATO VARCHAR(10) CHARACTER SET ISO8859_1,
PORCENTAGEM NUMERIC(10, 2),
CPF_CNPJ_TRANSMITENTE VARCHAR(20) CHARACTER SET ISO8859_1,
NOME_TRANSMITENTE VARCHAR(120) CHARACTER SET ISO8859_1,
DOCUMENTO_TRANSMITENTE VARCHAR(120) CHARACTER SET ISO8859_1,
AUTORIZACAO VARCHAR(60) CHARACTER SET ISO8859_1,
CARTORIO VARCHAR(10) CHARACTER SET ISO8859_1,
CARTORIO_ANTERIOR VARCHAR(10) CHARACTER SET ISO8859_1,
DESCRICAO_IMOVEL VARCHAR(120) CHARACTER SET ISO8859_1,
CCIR_CODIGO VARCHAR(30) CHARACTER SET ISO8859_1,
CIDADE VARCHAR_090,
REGISTRO NUMERICO,
DATA_REGISTRO DATAHORA,
COMPLEMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
STATUS VARCHAR(1) CHARACTER SET ISO8859_1)
AS 
declare variable V_NUMERO_CARTORIO varchar(10);
declare variable V_TIPO_REGISTRO varchar(10);
declare variable V_MATRICULA integer;
declare variable V_MATRICULA_LETRA varchar(10);
declare variable V_DATA_ENVIO_RURAL date;
declare variable V_TIPO_ATO varchar(1);
declare variable V_NUMERO_ATO integer;
declare variable V_PESSOA_VINCULO_ID integer;
begin
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'CARTORIO', 'CARTORIO_NUMERO', 1) INTO :v_numero_cartorio;

  for select i.imovel_id, i.numero, i.numero_letra, i.cartorio, i.tipo_registro, i.inscricao_imovel, i.cidade
      from r_imovel i
      where i.tipo_classe = 'R'
      or (i.tipo_classe = 'L' and i.TRATAR_COMO_RURAL = 'S')
      into :imovel_id, :v_matricula, :v_matricula_letra, :cartorio, :v_tipo_registro, :autorizacao,:cidade do
  begin
    if (coalesce(:v_matricula_letra,'') <> '') then
    begin
      matricula = cast(:v_matricula as varchar(10))||:v_matricula_letra;
    end
    else
    begin
      matricula = :v_matricula;
    end

    cartorio_anterior = '';
    if (coalesce(:cartorio,'') <> :v_numero_cartorio) then
    begin
      cartorio_anterior = :cartorio;
    end
    cartorio = :v_numero_cartorio;

    area = 0;
    area_descricao = '';
    select first 1 coalesce(area_averbada,0), area_descritiva, nome_edificacao, CCIR_CODIGO ,
    COMPLEMENTO
    from r_imovel_unidade
    where imovel_id = :imovel_id
    into :area, :area_descricao, :descricao_imovel, :CCIR_CODIGO, :COMPLEMENTO;

    area_m2 = :area * 10000;

    data_transferencia = null;
    cpf_cnpj_transmitente = '';
    nome_transmitente = '';
    select first 1 data_transferencia, cpf_cnpj, nome, DOCUMENTO, NACIONALIDADE
    from r_pessoa_vinculo
    where imovel_id = :imovel_id
    and data_transferencia is not null
    order by data_transferencia desc
    into :data_transferencia, :cpf_cnpj_transmitente, :nome_transmitente, :DOCUMENTO_TRANSMITENTE, :NACIONALIDADE_TRANSMITENTE;

    status = '';
    for select rp.pessoa_vinculo_id, cpf_cnpj, nome, nacionalidade, coalesce(rp.tipo_ato,''),
       coalesce(rp.numero_ato,0), coalesce(rp.area_percent,0), rp.documento
        from r_pessoa_vinculo rp , R_TB_TIPO_VINCULO rv
        where rp.tb_tipo_vinculo_id = rv.tb_tipo_vinculo_id
        and rp.imovel_id = :imovel_id
        and data_transferencia is null
        and coalesce(nacionalidade,'') <> ''
        and upper(coalesce(nacionalidade,'')) <> 'BRASILEIRO'
        and upper(coalesce(nacionalidade,'')) <> 'BRASILEIRA'
        and upper(coalesce( (SELECT NOME_SEM_ACENTUACAO FROM w_retirar_acentuacao(rv.descricao)),'')) = 'PROPRIETARIO'
        into :pessoa_vinculo_id, :cpf_cnpj_proprietario, :nome_proprietario,
        :nacionalidade, :v_tipo_ato, :v_numero_ato, :porcentagem, :DOCUMENTO_PROPRIETARIO do
    begin

      select data_registro,REGISTRO from r_registro_livro_estrangeiro where
      pessoa_vinculo_id = :pessoa_vinculo_id into :DATA_REGISTRO, :registro ;

       select count(pessoa_vinculo_id) from r_registro_livro_estrangeiro where
        pessoa_vinculo_id = :pessoa_vinculo_id into :v_Pessoa_vinculo_id ;

      if (coalesce(:v_Pessoa_vinculo_id,0) = 0) then
      begin
        status = 'P';
        DATA_REGISTRO = null;
        registro = null;
      end
      else
      begin
        status = 'R';
      end

      numero_ato = :v_tipo_ato||'.'||cast(:v_numero_ato as varchar(10));
      if (:V_TIPO = 'T') then --todos
      begin
        suspend;
      end
      else if ((:V_TIPO = 'P') and (:status = 'P')) then --somente pendetes de envio
      begin
        suspend;
      end
      else if ((:V_TIPO = 'R') and (:status = 'R')) then --somente pendetes de envio
      begin
        suspend;
      end
    end
  end
end ^

ALTER PROCEDURE R_INCLUIR_ITEM_NUMERO_CERTIDAO (V_PEDIDO_ITEM_ID INTEGER,
V_NOME VARCHAR_120,
V_CPF VARCHAR_030,
V_DOCUMENTO VARCHAR_030,
V_NOME_SOLTEIRO VARCHAR_120,
V_ESTADO_CIVIL VARCHAR_003,
V_CONJUGE VARCHAR_120,
V_CONJUGE_SOLTEIRO VARCHAR_120,
V_CONJUGE_CPF VARCHAR_030,
V_CONJUGE_DOCUMENTO VARCHAR_030,
V_LOGRADOURO VARCHAR_090,
V_TIPO_REGISTRO VARCHAR_001,
V_NUMERO INTEGER,
V_CARTORIO VARCHAR_003,
V_RETORNAR_PESSOA_TODOS VARCHAR_003)
RETURNS (PEDIDO_ITEM_NUMERO_ID NUMERIC(9, 0))
AS 
DECLARE VARIABLE V_MATRICULAS VARCHAR(3000);
  DECLARE VARIABLE V_QUANTIDADE INTEGER;
  DECLARE VARIABLE V_RESULTADO_TIPO VARCHAR_010;
BEGIN
  SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('R_PEDIDO_ITEM_NUMERO')
  INTO :PEDIDO_ITEM_NUMERO_ID;
  
  --VERFICAR RESULTADO
  V_MATRICULAS = '';
  V_QUANTIDADE = 0;
  V_RESULTADO_TIPO = '';
  IF (:V_RETORNAR_PESSOA_TODOS = 'S') THEN
  BEGIN
    SELECT QTDE_ENCONTRADA FROM R_VERIFICA_QTDE_PESSOA_TODAS(:V_CPF,NULL,NULL)
    INTO :V_QUANTIDADE;
    IF ((:V_QUANTIDADE = 0) AND (:V_CONJUGE_CPF <> '')) THEN
    BEGIN
      SELECT QTDE_ENCONTRADA FROM R_VERIFICA_QTDE_PESSOA_TODAS(:V_CONJUGE_CPF,NULL,NULL)
      INTO :V_QUANTIDADE;
    END
    IF ((:V_QUANTIDADE = 0) AND (:V_NOME <> '')) THEN
    BEGIN
      SELECT QTDE_ENCONTRADA FROM R_VERIFICA_QTDE_PESSOA_TODAS(NULL,:V_NOME,NULL)
      INTO :V_QUANTIDADE;
    END
    IF ((:V_QUANTIDADE = 0) AND (:V_NOME_SOLTEIRO <> '')) THEN
    BEGIN
      SELECT QTDE_ENCONTRADA FROM R_VERIFICA_QTDE_PESSOA_TODAS(NULL,:V_NOME_SOLTEIRO,NULL)
      INTO :V_QUANTIDADE;
    END
    IF ((:V_QUANTIDADE = 0) AND (:V_CONJUGE <> '')) THEN
    BEGIN
      SELECT QTDE_ENCONTRADA FROM R_VERIFICA_QTDE_PESSOA_TODAS(NULL,:V_CONJUGE,NULL)
      INTO :V_QUANTIDADE;
    END
    IF ((:V_QUANTIDADE = 0) AND (:V_CONJUGE_SOLTEIRO <> '')) THEN
    BEGIN
      SELECT QTDE_ENCONTRADA FROM R_VERIFICA_QTDE_PESSOA_TODAS(NULL,:V_CONJUGE_SOLTEIRO,NULL)
      INTO :V_QUANTIDADE;
    END  
  END
  ELSE
  BEGIN  
    SELECT MATRICULAS FROM R_VERIFICA_QTDE_MAT_PESSOA(:V_CPF,NULL,NULL)
    INTO :V_MATRICULAS;
    IF ((:V_MATRICULAS = '') AND (:V_CONJUGE_CPF <> '')) THEN
    BEGIN
      SELECT MATRICULAS FROM R_VERIFICA_QTDE_MAT_PESSOA(:V_CONJUGE_CPF,NULL,NULL)
      INTO :V_MATRICULAS;
    END
    IF ((:V_MATRICULAS = '') AND (:V_NOME <> '')) THEN
    BEGIN
      SELECT MATRICULAS FROM R_VERIFICA_QTDE_MAT_PESSOA(NULL,:V_NOME,NULL)
      INTO :V_MATRICULAS;
    END
    IF ((:V_MATRICULAS = '') AND (:V_NOME_SOLTEIRO <> '')) THEN
    BEGIN
      SELECT MATRICULAS FROM R_VERIFICA_QTDE_MAT_PESSOA(NULL,:V_NOME_SOLTEIRO,NULL)
      INTO :V_MATRICULAS;
    END
    IF ((:V_MATRICULAS = '') AND (:V_CONJUGE <> '')) THEN
    BEGIN
      SELECT MATRICULAS FROM R_VERIFICA_QTDE_MAT_PESSOA(NULL,:V_CONJUGE,NULL)
      INTO :V_MATRICULAS;
    END
    IF ((:V_MATRICULAS = '') AND (:V_CONJUGE_SOLTEIRO <> '')) THEN
    BEGIN
      SELECT MATRICULAS FROM R_VERIFICA_QTDE_MAT_PESSOA(NULL,:V_CONJUGE_SOLTEIRO,NULL)
      INTO :V_MATRICULAS;
    END      
  END
  
  IF ((:V_MATRICULAS <> '') OR (:V_QUANTIDADE > 0)) THEN
  BEGIN
    V_RESULTADO_TIPO = 'POSITIVA';
  END
  
  --VERIFICAR NO SISTEMA VELHO
  IF (:V_RESULTADO_TIPO = '') THEN
  BEGIN
    SELECT QUANTIDADE FROM R_VERIFICA_QTDE_SISTEMA_VELHO(:V_CPF,NULL)
    INTO :V_QUANTIDADE;
    IF ((:V_QUANTIDADE = 0) AND (:V_CONJUGE_CPF <> '')) THEN
    BEGIN
      SELECT QUANTIDADE FROM R_VERIFICA_QTDE_SISTEMA_VELHO(:V_CONJUGE_CPF,NULL)
      INTO :V_QUANTIDADE;
    END
    IF ((:V_QUANTIDADE = 0) AND (:V_NOME <> '')) THEN
    BEGIN
      SELECT QUANTIDADE FROM R_VERIFICA_QTDE_SISTEMA_VELHO(NULL,:V_NOME)
      INTO :V_QUANTIDADE;
    END
    IF ((:V_QUANTIDADE = 0) AND (:V_NOME_SOLTEIRO <> '')) THEN
    BEGIN
      SELECT QUANTIDADE FROM R_VERIFICA_QTDE_SISTEMA_VELHO(NULL,:V_NOME_SOLTEIRO)
      INTO :V_QUANTIDADE;
    END
    IF ((:V_QUANTIDADE = 0) AND (:V_CONJUGE <> '')) THEN
    BEGIN
      SELECT QUANTIDADE FROM R_VERIFICA_QTDE_SISTEMA_VELHO(NULL,:V_CONJUGE)
      INTO :V_QUANTIDADE;
    END
    IF ((:V_QUANTIDADE = 0) AND (:V_CONJUGE_SOLTEIRO <> '')) THEN
    BEGIN
      SELECT QUANTIDADE FROM R_VERIFICA_QTDE_SISTEMA_VELHO(NULL,:V_CONJUGE_SOLTEIRO)
      INTO :V_QUANTIDADE;
    END      
  END
  
  IF (:V_QUANTIDADE > 0) THEN
  BEGIN
    V_RESULTADO_TIPO = 'POSITIVA';
  END

  INSERT INTO R_PEDIDO_ITEM_NUMERO(PEDIDO_ITEM_NUMERO_ID, NUMERO, PEDIDO_ITEM_ID,
    TIPO_REGISTRO, LOGRADOURO, NOME, CPF, DOCUMENTO, NOME_SOLTEIRO, ESTADO_CIVIL, 
    CONJUGE, CONJUGE_SOLTEIRO, CONJUGE_CPF, CONJUGE_DOCUMENTO, RESULTADO_TIPO,
    RESULTADO_MATRICULAS, CARTORIO)
  VALUES(:PEDIDO_ITEM_NUMERO_ID, :V_NUMERO, :V_PEDIDO_ITEM_ID,
    :V_TIPO_REGISTRO, :V_LOGRADOURO, :V_NOME, :V_CPF, :V_DOCUMENTO, :V_NOME_SOLTEIRO, 
    :V_ESTADO_CIVIL, :V_CONJUGE, :V_CONJUGE_SOLTEIRO, :V_CONJUGE_CPF, :V_CONJUGE_DOCUMENTO, 
    :V_RESULTADO_TIPO, SUBSTRING(:V_MATRICULAS FROM 1 FOR 260), :V_CARTORIO);

  SUSPEND;  
END ^

ALTER PROCEDURE R_INCLUIR_PEDIDO_CERTIDAO (V_APRESENTANTE_NOME VARCHAR_120,
V_APRESENTANTE_FONE VARCHAR_030,
V_ADQUIRENTE_NOME VARCHAR_120,
V_TRANSMITENTE_NOME VARCHAR_120,
V_TB_TITULO_ID NUMERICO,
V_ORIGEM_PEDIDO VARCHAR_001,
V_TIPO_INCLUSAO VARCHAR_003,
V_TIPO_COBRANCA VARCHAR_001)
RETURNS (PEDIDO_ID NUMERIC(9, 0))
AS 
DECLARE VARIABLE V_PEDIDO_ID INTEGER;
BEGIN
  SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('R_PEDIDO')
  INTO :V_PEDIDO_ID;
  
  INSERT INTO R_PEDIDO(PEDIDO_ID, DATA_PEDIDO, APRESENTANTE_NOME, APRESENTANTE_FONE,
    ADQUIRENTE_NOME, TRANSMITENTE_NOME, TB_TITULO_ID, ORIGEM_PEDIDO,
    TIPO_INCLUSAO, TIPO_COBRANCA)
  VALUES(:V_PEDIDO_ID, CURRENT_TIMESTAMP, :V_APRESENTANTE_NOME, :V_APRESENTANTE_FONE,
    :V_ADQUIRENTE_NOME, :V_TRANSMITENTE_NOME, :V_TB_TITULO_ID, :V_ORIGEM_PEDIDO,
    :V_TIPO_INCLUSAO, :V_TIPO_COBRANCA);
  
  PEDIDO_ID = :V_PEDIDO_ID;
  
  SUSPEND;  
END ^

ALTER PROCEDURE R_INCLUIR_PEDIDO_ITEM_CERTIDAO (V_PEDIDO_ID INTEGER,
V_QUANTIDADE INTEGER,
V_NATUREZA_TITULO_ID INTEGER,
V_EMOLUMENTO_PERIODO_ID INTEGER,
V_CODIGO_TABELA_SELO_BUSCA VARCHAR_030,
V_CODIGO_TABELA_SELO_FOLHA_EXC VARCHAR_030,
V_QUANTIDADE_BUSCA INTEGER,
V_QUANTIDADE_FOLHA_EXCEDENTE INTEGER,
V_PROTOCOLO_CENTRAL VARCHAR_030,
V_TIPO_PEDIDO VARCHAR_001)
RETURNS (PEDIDO_ITEM_ID NUMERIC(9, 0))
AS 
DECLARE VARIABLE V_PEDIDO_ITEM_ID INTEGER;
  DECLARE VARIABLE V_SEQUENCIA INTEGER;
  DECLARE VARIABLE V_EMOLUMENTO_ID INTEGER;
  DECLARE VARIABLE V_VALOR_EMOLUMENTO DINHEIRO;
  DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA DINHEIRO;
  DECLARE VARIABLE V_CODIGO_SELO VARCHAR_030;
  DECLARE VARIABLE V_VALOR_FUNDO_RI DINHEIRO;
  DECLARE VARIABLE V_CODIGO_TABELA VARCHAR_030; 
  DECLARE VARIABLE V_VALOR_UNITARIO DINHEIRO;
  
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_BUSCA DINHEIRO;
  DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA_BUSCA DINHEIRO;
  DECLARE VARIABLE V_CODIGO_SELO_BUSCA VARCHAR_030;
  DECLARE VARIABLE V_VALOR_FUNDO_RI_BUSCA DINHEIRO;

  DECLARE VARIABLE V_VALOR_EMOLUMENTO_FOLHA_EXC DINHEIRO;
  DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA_FOLHA_EXC DINHEIRO;
  DECLARE VARIABLE V_CODIGO_SELO_FOLHA_EXC VARCHAR_030;
  DECLARE VARIABLE V_VALOR_FUNDO_RI_FOLHA_EXC DINHEIRO;  
  
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_TOTAL DINHEIRO;
  DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA_TOTAL DINHEIRO;
  DECLARE VARIABLE V_VALOR_FUNDO_RI_TOTAL DINHEIRO;  
BEGIN
  SELECT GEN_ID(PEDIDO_ITEM_SEQ,1) FROM RDB$DATABASE
  INTO :V_PEDIDO_ITEM_ID;
  
  SELECT COALESCE(MAX(SEQUENCIA),0) + 1 FROM R_PEDIDO_ITEM 
  WHERE PEDIDO_ID = :V_PEDIDO_ID
  INTO :V_SEQUENCIA;
  
  SELECT EMOLUMENTO_ID
  FROM G_NATUREZA_TITULO 
  WHERE NATUREZA_TITULO_ID = :V_NATUREZA_TITULO_ID
  INTO :V_EMOLUMENTO_ID;

  V_VALOR_EMOLUMENTO_TOTAL = 0;
  V_VALOR_TAXA_JUDICIARIA_TOTAL = 0;
  V_VALOR_FUNDO_RI_TOTAL = 0;
  
  SELECT FIRST 1 COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), CODIGO_SELO,
    COALESCE(VALOR_FUNDO_RI,0), CODIGO_TABELA
  FROM G_EMOLUMENTO_ITEM
  WHERE EMOLUMENTO_ID = :V_EMOLUMENTO_ID
  AND EMOLUMENTO_PERIODO_ID = :V_EMOLUMENTO_PERIODO_ID
  INTO :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, :V_CODIGO_SELO,
    :V_VALOR_FUNDO_RI, :V_CODIGO_TABELA;
    
  V_VALOR_EMOLUMENTO_TOTAL = (:V_VALOR_EMOLUMENTO_TOTAL + (:V_VALOR_EMOLUMENTO * :V_QUANTIDADE));
  V_VALOR_TAXA_JUDICIARIA_TOTAL = (:V_VALOR_TAXA_JUDICIARIA_TOTAL + (:V_VALOR_TAXA_JUDICIARIA * :V_QUANTIDADE));
  V_VALOR_FUNDO_RI_TOTAL = (:V_VALOR_FUNDO_RI_TOTAL + (:V_VALOR_FUNDO_RI * :V_QUANTIDADE));
          
  --VER BUSCAS
  V_VALOR_EMOLUMENTO_BUSCA = 0;
  V_VALOR_TAXA_JUDICIARIA_BUSCA = 0;
  V_CODIGO_SELO_BUSCA = 0;
  V_VALOR_FUNDO_RI_BUSCA = 0;
  IF (:V_QUANTIDADE_BUSCA > 0) THEN
  BEGIN  
    SELECT FIRST 1 COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), 
      CODIGO_SELO, COALESCE(VALOR_FUNDO_RI,0)
    FROM G_EMOLUMENTO_ITEM 
    WHERE CODIGO_SELO = :V_CODIGO_TABELA_SELO_BUSCA
    AND EMOLUMENTO_PERIODO_ID = :V_EMOLUMENTO_PERIODO_ID
    INTO :V_VALOR_EMOLUMENTO_BUSCA, :V_VALOR_TAXA_JUDICIARIA_BUSCA, 
      :V_CODIGO_SELO_BUSCA, :V_VALOR_FUNDO_RI_BUSCA;
  END
  V_VALOR_EMOLUMENTO_TOTAL = (:V_VALOR_EMOLUMENTO_TOTAL + (:V_VALOR_EMOLUMENTO_BUSCA * V_QUANTIDADE_BUSCA));
  V_VALOR_TAXA_JUDICIARIA_TOTAL = (:V_VALOR_TAXA_JUDICIARIA_TOTAL + (:V_VALOR_TAXA_JUDICIARIA_BUSCA * V_QUANTIDADE_BUSCA));
  V_VALOR_FUNDO_RI_TOTAL = (:V_VALOR_FUNDO_RI_TOTAL + (:V_VALOR_FUNDO_RI_BUSCA * V_QUANTIDADE_BUSCA));      

  --VER FOLHAS EXCEDENTES
  V_VALOR_EMOLUMENTO_FOLHA_EXC = 0;
  V_VALOR_TAXA_JUDICIARIA_FOLHA_EXC = 0;
  V_CODIGO_SELO_FOLHA_EXC = 0;
  V_VALOR_FUNDO_RI_FOLHA_EXC = 0;
  IF (:V_QUANTIDADE_FOLHA_EXCEDENTE > 0) THEN
  BEGIN  
    SELECT FIRST 1 COALESCE(VALOR_EMOLUMENTO,0), COALESCE(VALOR_TAXA_JUDICIARIA,0), 
      CODIGO_SELO, COALESCE(VALOR_FUNDO_RI,0)
    FROM G_EMOLUMENTO_ITEM 
    WHERE CODIGO_SELO = :V_CODIGO_TABELA_SELO_FOLHA_EXC
    AND EMOLUMENTO_PERIODO_ID = :V_EMOLUMENTO_PERIODO_ID
    INTO :V_VALOR_EMOLUMENTO_FOLHA_EXC, :V_VALOR_TAXA_JUDICIARIA_FOLHA_EXC, 
      :V_CODIGO_SELO_FOLHA_EXC, :V_VALOR_FUNDO_RI_FOLHA_EXC;
  END
  V_VALOR_EMOLUMENTO_TOTAL = (:V_VALOR_EMOLUMENTO_TOTAL + (:V_VALOR_EMOLUMENTO_FOLHA_EXC * V_QUANTIDADE_FOLHA_EXCEDENTE));
  V_VALOR_TAXA_JUDICIARIA_TOTAL = (:V_VALOR_TAXA_JUDICIARIA_TOTAL + (:V_VALOR_TAXA_JUDICIARIA_FOLHA_EXC * V_QUANTIDADE_FOLHA_EXCEDENTE));
  V_VALOR_FUNDO_RI_TOTAL = (:V_VALOR_FUNDO_RI_TOTAL + (:V_VALOR_FUNDO_RI_FOLHA_EXC * V_QUANTIDADE_FOLHA_EXCEDENTE));      
  
  V_VALOR_UNITARIO = ((:V_VALOR_EMOLUMENTO + :V_VALOR_TAXA_JUDICIARIA + :V_VALOR_FUNDO_RI)+
    (:V_VALOR_EMOLUMENTO_BUSCA + :V_VALOR_TAXA_JUDICIARIA_BUSCA + :V_VALOR_FUNDO_RI_BUSCA)+
    (:V_VALOR_EMOLUMENTO_FOLHA_EXC + :V_VALOR_TAXA_JUDICIARIA_FOLHA_EXC + :V_VALOR_FUNDO_RI_FOLHA_EXC));
  
  INSERT INTO R_PEDIDO_ITEM(PEDIDO_ITEM_ID, PEDIDO_ID, NATUREZA_TITULO_ID,
    VALOR_DOCUMENTO, VALOR_EMOLUMENTO, VALOR_TAXA_JUDICIARIA, QUANTIDADE,
    EMOLUMENTO_ID, VALOR_UNITARIO, TIPO_PEDIDO, SEQUENCIA, CODIGO_SELO_DIGITAL,
    QUANTIDADE_BUSCA, QUANTIDADE_FOLHA_EXCEDENTE, PROTOCOLO_CENTRAL, VALOR_FUNDO_RI,
    CODIGO_TABELA_EMOLUMENTOS, VALOR_ITBI)
  VALUES(:V_PEDIDO_ITEM_ID, :V_PEDIDO_ID, :V_NATUREZA_TITULO_ID,
    0, :V_VALOR_EMOLUMENTO_TOTAL, :V_VALOR_TAXA_JUDICIARIA_TOTAL, :V_QUANTIDADE,
    :V_EMOLUMENTO_ID, :V_VALOR_UNITARIO, :V_TIPO_PEDIDO, :V_SEQUENCIA, :V_CODIGO_SELO,
    :V_QUANTIDADE_BUSCA, :V_QUANTIDADE_FOLHA_EXCEDENTE, :V_PROTOCOLO_CENTRAL, :V_VALOR_FUNDO_RI_TOTAL,
    :V_CODIGO_TABELA, 0);

  PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID;
  
  SUSPEND;  
END ^

ALTER PROCEDURE R_INDICE_PESSOAL (V_LETRA VARCHAR(1) CHARACTER SET ISO8859_1,
V_DATA_INICIAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (ANO NUMERIC(18, 4),
ATO_NUMERO NUMERIC(18, 4),
ATO_TIPO VARCHAR(10) CHARACTER SET ISO8859_1,
IMOVEL_ID NUMERIC(18, 4),
NUMERO NUMERIC(18, 4),
PESSOA_VINCULO_ID NUMERIC(18, 4),
ADQUIRENTE VARCHAR(120) CHARACTER SET ISO8859_1,
TRANSMITENTE VARCHAR(120) CHARACTER SET ISO8859_1,
DETALHE_IMOVEL VARCHAR(1000) CHARACTER SET ISO8859_1,
NUMERO_ORDEM NUMERIC(18, 4))
AS 
DECLARE VARIABLE D_TIPO_ATO VARCHAR(10);
DECLARE VARIABLE D_ATO_NUMERO NUMERIC(18,4);
DECLARE VARIABLE D_ATO_NUMERO_TRANSMITENTE NUMERIC(18,4);
DECLARE VARIABLE D_TRANSMITENTE VARCHAR(120);
DECLARE VARIABLE D_QUANT_ATOS NUMERIC(18,4);
DECLARE VARIABLE D_DETALHE_IMOVEL VARCHAR(1000);
DECLARE VARIABLE D_TIPO_CLASSE VARCHAR(3);
DECLARE VARIABLE D_LOGRADOURO VARCHAR(1000);
DECLARE VARIABLE D_QUADRA VARCHAR(1000);
DECLARE VARIABLE D_LOTE VARCHAR(1000);
DECLARE VARIABLE D_TB_BAIRRO_ID NUMERIC(18,4);
DECLARE VARIABLE D_BAIRRO VARCHAR(1000);
BEGIN
  FOR SELECT EXTRACT(YEAR FROM PR.DATA) AS ANO,
             PV.TIPO_ATO, PV.NUMERO_ATO,
             IM.IMOVEL_ID, IM.NUMERO, PV.PESSOA_VINCULO_ID,
             PV.NOME, IM.TIPO_CLASSE, PR.NUMERO_ORDEM
      FROM   R_PROTOCOLO PR, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
             R_PESSOA_VINCULO PV, R_IMOVEL IM
      WHERE  PR.DATA BETWEEN CAST(:V_DATA_INICIAL AS TIMESTAMP)
                         AND CAST(:V_DATA_FINAL AS TIMESTAMP) + 0.99999
      AND    PR.PEDIDO_ID = PI.PEDIDO_ID
      AND    PR.TIPO_PROTOCOLO = '1'
      AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
      AND    PN.TIPO_REGISTRO = IM.TIPO_REGISTRO
      AND    PN.NUMERO = IM.NUMERO
      AND    IM.IMOVEL_ID = PV.IMOVEL_ID
      AND    PV.NUMERO_ATO = PN.ATO_NUMERO
      AND    PV.TB_TIPO_VINCULO_ID IN (7,18,94)
      AND    PV.NOME LIKE :V_LETRA||'%'
      ORDER BY PV.NOME
      INTO   :ANO, :D_TIPO_ATO, :D_ATO_NUMERO, :IMOVEL_ID, :NUMERO,
             :PESSOA_VINCULO_ID, :ADQUIRENTE, :D_TIPO_CLASSE, :NUMERO_ORDEM DO
  BEGIN
    IF (:D_TIPO_ATO = 'A') THEN --AVERBACAO
    BEGIN
      D_TIPO_ATO = 'Av.';
    END
    ELSE IF (:D_TIPO_ATO = 'R') THEN --REGISTRO
    BEGIN
      D_TIPO_ATO = 'R.';
    END
    ELSE IF (:D_TIPO_ATO = 'M') THEN --MATRICULA
    BEGIN
      D_TIPO_ATO = 'Mat.';
    END
    ATO_NUMERO = :D_ATO_NUMERO;
    ATO_TIPO = :D_TIPO_ATO;
    D_TRANSMITENTE = '';
    IF (:D_ATO_NUMERO > 0) THEN
    BEGIN
      SELECT MAX(NUMERO_ATO) FROM R_PESSOA_VINCULO
      WHERE  IMOVEL_ID = :IMOVEL_ID
      AND    NUMERO_ATO < :D_ATO_NUMERO
      AND    DATA_TRANSFERENCIA IS NOT NULL
      INTO   :D_ATO_NUMERO_TRANSMITENTE;
    
      SELECT COUNT(*) FROM R_PESSOA_VINCULO
      WHERE  IMOVEL_ID = :IMOVEL_ID
      AND    NUMERO_ATO = :D_ATO_NUMERO_TRANSMITENTE
      INTO   :D_QUANT_ATOS;
      IF (:D_QUANT_ATOS = 1) THEN
      BEGIN
        SELECT FIRST 1 NOME FROM R_PESSOA_VINCULO
        WHERE  IMOVEL_ID = :IMOVEL_ID
        AND    NUMERO_ATO = :D_ATO_NUMERO_TRANSMITENTE
        INTO :D_TRANSMITENTE;
      END
      ELSE IF (:D_QUANT_ATOS > 1) THEN
      BEGIN
        SELECT FIRST 1 NOME FROM R_PESSOA_VINCULO
        WHERE  IMOVEL_ID = :IMOVEL_ID
        AND    NUMERO_ATO = :D_ATO_NUMERO_TRANSMITENTE
        INTO :D_TRANSMITENTE;
        D_TRANSMITENTE = :D_TRANSMITENTE||' E OUTROS';
      END
      TRANSMITENTE = :D_TRANSMITENTE;    
    END
    ELSE
    BEGIN
      TRANSMITENTE = :ADQUIRENTE;    
    END    
    D_DETALHE_IMOVEL = '';
    IF (:D_TIPO_CLASSE = 'C') THEN --SE FOR CONDOMINIO
    BEGIN

    END
    ELSE IF (:D_TIPO_CLASSE = 'L') THEN --SE FOR URBANO
    BEGIN
      SELECT FIRST 1 T.DESCRICAO||' '||U.DESCRICAO_LOGRADOURO, U.QUADRA,
             U.NUMERO_UNIDADE, U.TB_BAIRRO_ID
      FROM R_IMOVEL_UNIDADE U, G_TB_TIPOLOGRADOURO T
      WHERE U.TB_TIPOLOGRADOURO_ID = T.TB_TIPOLOGRADOURO_ID
      AND U.IMOVEL_ID = :IMOVEL_ID
      INTO :D_LOGRADOURO, :D_QUADRA, D_LOTE, D_TB_BAIRRO_ID;
      D_DETALHE_IMOVEL = :D_LOGRADOURO;
      IF ((:D_QUADRA <> '') AND (:D_QUADRA IS NOT NULL)) THEN
      BEGIN
        D_DETALHE_IMOVEL = :D_DETALHE_IMOVEL || ', Quadra: '||:D_QUADRA;
      END
      IF ((:D_LOTE <> '') AND (:D_LOTE IS NOT NULL)) THEN
      BEGIN
        D_DETALHE_IMOVEL = :D_DETALHE_IMOVEL || ', Lote: '||:D_LOTE;
      END
      SELECT DESCRICAO FROM G_TB_BAIRRO
      WHERE TB_BAIRRO_ID = :D_TB_BAIRRO_ID
      INTO :D_BAIRRO;
      IF ((:D_BAIRRO <> '') AND (:D_BAIRRO IS NOT NULL)) THEN
      BEGIN
        D_DETALHE_IMOVEL = :D_DETALHE_IMOVEL || ' - '||:D_BAIRRO;
      END
    END
    ELSE IF (:D_TIPO_CLASSE = 'R') THEN --SE FOR RURAL
    BEGIN
      SELECT NOME_EDIFICACAO FROM R_IMOVEL_UNIDADE
      WHERE IMOVEL_ID = :IMOVEL_ID
      INTO :D_DETALHE_IMOVEL;
    END
    DETALHE_IMOVEL = :D_DETALHE_IMOVEL;

    SUSPEND;
  END
END ^

ALTER PROCEDURE R_INDICE_PESSOAL_LETRA (V_DATA_INICIAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (LETRA VARCHAR(1) CHARACTER SET ISO8859_1)
AS 
BEGIN
  FOR SELECT  DISTINCT SUBSTRING(PV.NOME FROM 1 FOR 1) AS LETRA
      FROM   R_PROTOCOLO PR, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN, R_PESSOA_VINCULO PV, R_IMOVEL IM
      WHERE  PR.PEDIDO_ID = PI.PEDIDO_ID
      AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
      AND    PR.TIPO_PROTOCOLO = '1'
      AND    PR.DATA BETWEEN CAST(:V_DATA_INICIAL AS TIMESTAMP)
                         AND CAST(:V_DATA_FINAL AS TIMESTAMP) + 0.99999
      AND    PN.TIPO_REGISTRO = IM.TIPO_REGISTRO
      AND    PN.NUMERO = IM.NUMERO
      AND    IM.IMOVEL_ID = PV.IMOVEL_ID
      AND    PV.NUMERO_ATO = PN.ATO_NUMERO
      AND    PV.TB_TIPO_VINCULO_ID IN (7,18,94)
      ORDER BY 1
      INTO   :LETRA DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_LIBERAR_CERT_ON_REMONTAGEM (V_PEDIDO_ID INTEGER,
V_PEDIDO_ITEM_ID INTEGER)
RETURNS (RESULTADO VARCHAR(100) CHARACTER SET ISO8859_1)
AS 
begin
  if (coalesce(:v_pedido_id, 0) > 0) then
  begin
    update r_pedido_item
    set xml_row_do_item = null,
      usuario_id_postou_cert = null
    where pedido_id = :v_pedido_id;

    Resultado = 'OK';
  end
  else if (coalesce(:v_pedido_item_id, 0) > 0) then
  begin
    update r_pedido_item
    set xml_row_do_item = null,
      usuario_id_postou_cert = null
    where pedido_item_id = :v_pedido_item_id;

    Resultado = 'OK';
  end
  suspend;
end ^

ALTER PROCEDURE R_MATRICULAS_COM_ONUS (V_NUMERO_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUMERO_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO_RETORNO VARCHAR(10) CHARACTER SET ISO8859_1,
V_TIPO_PESQUISA VARCHAR(10) CHARACTER SET ISO8859_1)
RETURNS (IMOVEL_ID NUMERIC(18, 2),
NUMERO NUMERIC(18, 2))
AS 
DECLARE VARIABLE V_QUANTIDADE INTEGER;
DECLARE VARIABLE V_INI INTEGER;
DECLARE VARIABLE V_FIM INTEGER;
DECLARE VARIABLE V_CONT INTEGER;
BEGIN
--Tipo_Retorno O=COM ONUS  S=SEM ONUS  I=INEXISTENTES   E=EXISTENTES
--             C=CANCELADAS   G=OUTROS CARTORIOS (GUARA)
--Tipo_Pesquisa T=Todos I=Intervalo
  IF (:V_TIPO_PESQUISA = 'T') THEN --SE FOR TODOS
  BEGIN
    IF (:V_TIPO_RETORNO = 'C') THEN  --CANCELADAS
    BEGIN
      FOR SELECT I.IMOVEL_ID, NUMERO FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = 'M'
          AND I.SITUACAO = 'C'
          AND (I.DE_OUTRO_CARTORIO <> 'S' OR I.DE_OUTRO_CARTORIO IS NULL)
          ORDER BY I.NUMERO
          INTO :IMOVEL_ID, :NUMERO DO
      BEGIN
        SUSPEND;
      END
    END
    ELSE IF (:V_TIPO_RETORNO = 'EN') THEN  --ENCERRADAS
    BEGIN
      FOR SELECT I.IMOVEL_ID, NUMERO FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = 'M'
          AND I.SITUACAO = 'E'
          AND (I.DE_OUTRO_CARTORIO <> 'S' OR I.DE_OUTRO_CARTORIO IS NULL)
          ORDER BY I.NUMERO
          INTO :IMOVEL_ID, :NUMERO DO
      BEGIN
        SUSPEND;
      END
    END
    ELSE IF (:V_TIPO_RETORNO = 'G') THEN  --DE OUTRO CARTORIO (GUARA)
    BEGIN
      FOR SELECT I.IMOVEL_ID, NUMERO FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = 'M'
          AND I.DE_OUTRO_CARTORIO = 'S'
          ORDER BY I.NUMERO
          INTO :IMOVEL_ID, :NUMERO DO
      BEGIN
        SUSPEND;
      END
    END
    ELSE
    BEGIN
      FOR SELECT I.IMOVEL_ID, NUMERO FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = 'M'
          AND ((I.SITUACAO <> 'C' AND I.SITUACAO <> 'E') OR I.SITUACAO IS NULL)
          AND (I.DE_OUTRO_CARTORIO <> 'S' OR I.DE_OUTRO_CARTORIO IS NULL)
          ORDER BY I.NUMERO
          INTO :IMOVEL_ID, :NUMERO DO
      BEGIN
        IF (:V_TIPO_RETORNO = 'E') THEN  --EXISTENTES
        BEGIN
          SUSPEND;
        END
        ELSE
        BEGIN
          SELECT COUNT(H.IMOVEL_ID) FROM R_IMOVEL_HISTORICO H
          WHERE H.USUARIO_ID_CANC IS NULL
          AND H.IMOVEL_ID = :IMOVEL_ID
          INTO :V_QUANTIDADE;
          IF ((:V_TIPO_RETORNO = 'O') AND (:V_QUANTIDADE > 0)) THEN --COM ONUS
          BEGIN
            SUSPEND;
          END
          ELSE IF ((:V_TIPO_RETORNO = 'S') AND (:V_QUANTIDADE = 0)) THEN --SEM ONUS
          BEGIN
            SUSPEND;
          END
        END
      END
    END
  END
  ELSE --SE FOR POR INTERVALO
  BEGIN
    V_INI = CAST(V_NUMERO_INI AS INTEGER);
    V_FIM = CAST(V_NUMERO_FIM AS INTEGER);
    IF (:V_TIPO_RETORNO = 'I') THEN --INEXISTENTES (ESTA OPCAO SO COM INTERVALO)
    BEGIN
      V_CONT = :V_INI;
      WHILE (:V_CONT <= :V_FIM) DO
      BEGIN
        SELECT COUNT(I.IMOVEL_ID) FROM R_IMOVEL I
        WHERE I.TIPO_REGISTRO = 'M'
        AND I.NUMERO = :V_CONT
        INTO :V_QUANTIDADE;
        IF (:V_QUANTIDADE = 0) THEN
        BEGIN
          IMOVEL_ID = 0;
          NUMERO = :V_CONT;
          SUSPEND;
        END
        V_CONT = (:V_CONT + 1);
      END
    END
    ELSE IF (:V_TIPO_RETORNO = 'C') THEN  --CANCELADAS
    BEGIN
      FOR SELECT I.IMOVEL_ID, NUMERO FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = 'M'
          AND I.SITUACAO = 'C'
          AND (I.DE_OUTRO_CARTORIO <> 'S' OR I.DE_OUTRO_CARTORIO IS NULL)
          AND I.NUMERO BETWEEN :V_INI AND :V_FIM
          ORDER BY I.NUMERO
          INTO :IMOVEL_ID, :NUMERO DO
      BEGIN
        SUSPEND;
      END
    END
    ELSE IF (:V_TIPO_RETORNO = 'EN') THEN  --ENCERRADAS
    BEGIN
      FOR SELECT I.IMOVEL_ID, NUMERO FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = 'M'
          AND I.SITUACAO = 'E'
          AND (I.DE_OUTRO_CARTORIO <> 'S' OR I.DE_OUTRO_CARTORIO IS NULL)
          AND I.NUMERO BETWEEN :V_INI AND :V_FIM
          ORDER BY I.NUMERO
          INTO :IMOVEL_ID, :NUMERO DO
      BEGIN
        SUSPEND;
      END
    END
    ELSE IF (:V_TIPO_RETORNO = 'G') THEN  --DE OUTRO CARTORIO (GUARA)
    BEGIN
      FOR SELECT I.IMOVEL_ID, NUMERO FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = 'M'
          AND I.DE_OUTRO_CARTORIO = 'S'
          AND I.NUMERO BETWEEN :V_INI AND :V_FIM
          ORDER BY I.NUMERO
          INTO :IMOVEL_ID, :NUMERO DO
      BEGIN
        SUSPEND;
      END
    END
    ELSE
    BEGIN
      FOR SELECT I.IMOVEL_ID, NUMERO FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = 'M'
          AND ((I.SITUACAO <> 'C' AND I.SITUACAO <> 'E') OR I.SITUACAO IS NULL)
          AND (I.DE_OUTRO_CARTORIO <> 'S' OR I.DE_OUTRO_CARTORIO IS NULL)
          AND I.NUMERO BETWEEN :V_INI AND :V_FIM
          ORDER BY I.NUMERO
          INTO :IMOVEL_ID, :NUMERO DO
      BEGIN
        IF (:V_TIPO_RETORNO = 'E') THEN --EXISTENTES
        BEGIN
          SUSPEND;
        END
        ELSE
        BEGIN
          SELECT COUNT(H.IMOVEL_ID) FROM R_IMOVEL_HISTORICO H
          WHERE H.USUARIO_ID_CANC IS NULL
          AND H.IMOVEL_ID = :IMOVEL_ID
          INTO :V_QUANTIDADE;
          IF ((:V_TIPO_RETORNO = 'O') AND (:V_QUANTIDADE > 0)) THEN --COM ONUS
          BEGIN
            SUSPEND;
          END
          ELSE IF ((:V_TIPO_RETORNO = 'S') AND (:V_QUANTIDADE = 0)) THEN --SEM ONUS
          BEGIN
            SUSPEND;
          END
        END
      END
    END
  END
END ^

ALTER PROCEDURE R_MATRICULAS_CONFERIDAS (V_NUMERO_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUMERO_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO_RETORNO VARCHAR(10) CHARACTER SET ISO8859_1,
V_TIPO_PESQUISA VARCHAR(10) CHARACTER SET ISO8859_1,
V_CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1 = '',
V_USAR_MULTIPLOS_CARTORIOS VARCHAR(3) CHARACTER SET ISO8859_1 = 'N')
RETURNS (IMOVEL_ID NUMERIC(18, 2),
NUMERO NUMERIC(18, 2))
AS 
DECLARE VARIABLE V_QUANTIDADE INTEGER;
DECLARE VARIABLE V_INI INTEGER;
DECLARE VARIABLE V_FIM INTEGER;
DECLARE VARIABLE V_CONT INTEGER;
declare variable V_SQL VARCHAR(1000);
declare variable V_SQL_COMPLEMENTO VARCHAR(1000);
BEGIN
--Tipo_Retorno CO=CONFERIDO  NCO=NÃO CONFERIDO
--Tipo_Pesquisa T=Todos I=Intervalo
  V_SQL = '';
  V_SQL_COMPLEMENTO = '';

  IF (COALESCE(:V_USAR_MULTIPLOS_CARTORIOS,'') = 'S') THEN
  BEGIN
    V_SQL_COMPLEMENTO = ' AND CARTORIO = '||:V_CARTORIO;
  END

  IF (:V_TIPO_PESQUISA = 'T') THEN --SE FOR TODOS
  BEGIN
    IF (:V_TIPO_RETORNO = 'CO') THEN  --CONFERIDOS
    BEGIN
      V_SQL = ' SELECT I.IMOVEL_ID, NUMERO FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = ''M''
          AND COALESCE(I.conferido_usuario_id,0) > 0 ';

      V_SQL = :V_SQL||' '||:V_SQL_COMPLEMENTO||' ORDER BY I.NUMERO ';
    
      FOR EXECUTE STATEMENT :V_SQL
          INTO :IMOVEL_ID, :NUMERO DO
      BEGIN
        SUSPEND;
      END
    END
  END
  ELSE --SE FOR POR INTERVALO
  BEGIN
    V_INI = CAST(V_NUMERO_INI AS INTEGER);
    V_FIM = CAST(V_NUMERO_FIM AS INTEGER);
    IF (:V_TIPO_RETORNO = 'CO') THEN  --CONFERIDOS
    BEGIN
      V_SQL = ' SELECT I.IMOVEL_ID, NUMERO FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = ''M''
          AND COALESCE(I.conferido_usuario_id,0) > 0
          AND I.NUMERO BETWEEN '||:V_INI||' AND '||:V_FIM;

      V_SQL = :V_SQL||' '||:V_SQL_COMPLEMENTO||' ORDER BY I.NUMERO ';
    
      FOR EXECUTE STATEMENT :V_SQL
          INTO :IMOVEL_ID, :NUMERO DO
      BEGIN
        SUSPEND;
      END
    END
    ELSE IF (:V_TIPO_RETORNO = 'NCO') THEN  --NAO CONFERIDOS (ESTA OPCAO SO COM INTERVALO)
    BEGIN
      V_CONT = :V_INI;
      WHILE (:V_CONT <= :V_FIM) DO
      BEGIN
        IF (COALESCE(:V_USAR_MULTIPLOS_CARTORIOS,'') = 'S') THEN
        begin
          SELECT COUNT(I.IMOVEL_ID) FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = 'M'
          AND COALESCE(I.conferido_usuario_id,0) > 0
          AND I.NUMERO = :V_CONT
          AND I.CARTORIO = :V_CARTORIO
          INTO :V_QUANTIDADE;
          IF (:V_QUANTIDADE = 0) THEN
          BEGIN
            IMOVEL_ID = 0;
            NUMERO = :V_CONT;
            SUSPEND;
          END
          V_CONT = (:V_CONT + 1);
        end
        else
        begin
          SELECT COUNT(I.IMOVEL_ID) FROM R_IMOVEL I
          WHERE I.TIPO_REGISTRO = 'M'
          AND COALESCE(I.conferido_usuario_id,0) > 0
          AND I.NUMERO = :V_CONT
          INTO :V_QUANTIDADE;
          IF (:V_QUANTIDADE = 0) THEN
          BEGIN
            IMOVEL_ID = 0;
            NUMERO = :V_CONT;
            SUSPEND;
          END
          V_CONT = (:V_CONT + 1);
        END
      END
    end
  END
END ^

ALTER PROCEDURE R_MATRICULAS_DIGITALIZADAS_REAL (V_NUMERO_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUMERO_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO_RETORNO VARCHAR(10) CHARACTER SET ISO8859_1,
V_SOMENTE_CADASTRADAS VARCHAR(10) CHARACTER SET ISO8859_1,
V_INCLUIR_CANCELADAS VARCHAR(10) CHARACTER SET ISO8859_1)
RETURNS (IMOVEL_ID NUMERIC(18, 2),
NUMERO NUMERIC(18, 2))
AS 
DECLARE VARIABLE V_MATRICULA INTEGER;
DECLARE VARIABLE V_ID INTEGER;
DECLARE VARIABLE V_CONT INTEGER;
DECLARE VARIABLE V_QUANTIDADE INTEGER;
DECLARE VARIABLE V_INI INTEGER;
DECLARE VARIABLE V_FIM INTEGER;
BEGIN
  V_INI = CAST(:V_NUMERO_INI AS INTEGER);
  V_FIM = CAST(:V_NUMERO_FIM AS INTEGER);
  --Tipo_Retorno D=Digitalizados N=Nao Digitalizados
  IF (:V_TIPO_RETORNO = 'D') THEN --SE FOR AS DIGITALIZADAS
  BEGIN
    FOR SELECT NUMERO FROM G_INDEXACAO
        WHERE LIVRO_OU_TALAO = 'R'
        AND TIPO = 'M'
        AND NUMERO BETWEEN :V_NUMERO_INI AND :V_NUMERO_FIM
        ORDER BY NUMERO
        INTO :V_MATRICULA DO
    BEGIN
      IMOVEL_ID = 0;
      NUMERO = :V_MATRICULA;
      SUSPEND;
    END
  END
  ELSE --SE FOR AS NAO DIGITALIZADAS
  BEGIN
    IF (:V_SOMENTE_CADASTRADAS = 'S') THEN
    BEGIN
      IF (:V_INCLUIR_CANCELADAS = 'S') THEN
      BEGIN
        FOR SELECT I.IMOVEL_ID, I.NUMERO FROM R_IMOVEL I
            WHERE I.TIPO_REGISTRO = 'M'
            AND (I.DE_OUTRO_CARTORIO <> 'S' OR I.DE_OUTRO_CARTORIO IS NULL)
            AND I.NUMERO BETWEEN :V_INI AND :V_FIM
            ORDER BY NUMERO
            INTO :V_ID, :V_MATRICULA DO
        BEGIN
          SELECT COUNT(INDEXACAO_ID) FROM G_INDEXACAO
          WHERE LIVRO_OU_TALAO = 'R'
          AND TIPO = 'M'
          AND NUMERO = :V_MATRICULA
          INTO :V_QUANTIDADE;
          IF (:V_QUANTIDADE = 0) THEN
          BEGIN
            IMOVEL_ID = 0;
            NUMERO = :V_MATRICULA;
            SUSPEND;
          END
        END
      END
      ELSE
      BEGIN
        FOR SELECT I.IMOVEL_ID, I.NUMERO FROM R_IMOVEL I
            WHERE I.TIPO_REGISTRO = 'M'
            AND ((I.SITUACAO <> 'C' AND I.SITUACAO <> 'E') OR I.SITUACAO IS NULL)
            AND (I.DE_OUTRO_CARTORIO <> 'S' OR I.DE_OUTRO_CARTORIO IS NULL)
            AND I.NUMERO BETWEEN :V_INI AND :V_FIM
            ORDER BY NUMERO
            INTO :V_ID, :V_MATRICULA DO
        BEGIN
          SELECT COUNT(INDEXACAO_ID) FROM G_INDEXACAO
          WHERE LIVRO_OU_TALAO = 'R'
          AND TIPO = 'M'
          AND NUMERO = :V_MATRICULA
          INTO :V_QUANTIDADE;
          IF (:V_QUANTIDADE = 0) THEN
          BEGIN
            IMOVEL_ID = 0;
            NUMERO = :V_MATRICULA;
            SUSPEND;
          END
        END
      END
    END
    ELSE
    BEGIN
      V_CONT = :V_INI;
      WHILE (:V_CONT <= :V_FIM) DO
      BEGIN
        SELECT COUNT(INDEXACAO_ID) FROM G_INDEXACAO
        WHERE LIVRO_OU_TALAO = 'R'
        AND TIPO = 'M'
        AND NUMERO = :V_CONT
        INTO :V_QUANTIDADE;
        IF (:V_QUANTIDADE = 0) THEN
        BEGIN
          IMOVEL_ID = 0;
          NUMERO = :V_CONT;
          SUSPEND;
        END
        V_CONT = (:V_CONT + 1);
      END
    END
  END
END ^

ALTER PROCEDURE R_MATRICULAS_DO_PEDIDO (V_PEDIDO_ID VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (MATRICULAS VARCHAR(200) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE TIPO_REGISTRO VARCHAR(5);
DECLARE VARIABLE RETORNO VARCHAR(2000);
DECLARE VARIABLE MATRICULA VARCHAR(8);
DECLARE VARIABLE QUANTIDADE INTEGER;
BEGIN
  RETORNO = '';
  QUANTIDADE = 0;
  FOR SELECT DISTINCT CAST(PN.NUMERO AS INTEGER), TIPO_REGISTRO FROM R_PEDIDO_ITEM_NUMERO PN, R_PEDIDO_ITEM PI
      WHERE PN.PEDIDO_ITEM_ID = PI.PEDIDO_ITEM_ID
      AND PI.PEDIDO_ID = :V_PEDIDO_ID
      AND PN.NUMERO IS NOT NULL
      AND PN.NUMERO > 0
      ORDER BY PN.NUMERO
      INTO :MATRICULA, :TIPO_REGISTRO DO
  BEGIN
    QUANTIDADE = :QUANTIDADE + 1;
    IF (RETORNO = '') THEN
    BEGIN
      IF (:TIPO_REGISTRO = 'A') THEN
        RETORNO = :MATRICULA ||'(LV.3)';
      ELSE
        RETORNO = :MATRICULA;
    END
    ELSE
    BEGIN
      IF (:TIPO_REGISTRO = 'A') THEN
        RETORNO = :RETORNO ||', '||:MATRICULA ||'(LV.3)';
      ELSE
        RETORNO = :RETORNO ||', '||:MATRICULA;
    END
    IF (:QUANTIDADE = 12) THEN
      LEAVE;
  END
  MATRICULAS = :RETORNO;
  SUSPEND;
END ^

ALTER PROCEDURE R_MATRICULAS_OUTRAS_SERVENTIAS (MATRICULA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
MATRICULA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
COMPLEMENTO_SERVENTIA VARCHAR(200) CHARACTER SET ISO8859_1,
BAIRRO_DESCRICAO VARCHAR(120) CHARACTER SET ISO8859_1)
RETURNS (MATRICULA INTEGER,
MATRICULA_LETRA VARCHAR(10) CHARACTER SET ISO8859_1,
DADOS_IMOVEL VARCHAR(5000) CHARACTER SET ISO8859_1,
REGISTRO_ANTERIOR VARCHAR(60) CHARACTER SET ISO8859_1,
COMPLEMENTO VARCHAR(260) CHARACTER SET ISO8859_1,
VINCULOS VARCHAR(5000) CHARACTER SET ISO8859_1,
DATA_REGISTRO TIMESTAMP)
AS 
DECLARE VARIABLE V_TIPO VARCHAR(20);
  DECLARE VARIABLE V_NUMERO INTEGER;
  DECLARE VARIABLE V_IMOVEL_ID INTEGER;
  
  DECLARE VARIABLE V_NOME VARCHAR(120);
  DECLARE VARIABLE V_DOCUMENTO VARCHAR(120);
  DECLARE VARIABLE V_CPF_CNPJ VARCHAR(20);
  DECLARE VARIABLE V_TB_ESTADOCIVIL_ID INTEGER;
  DECLARE VARIABLE V_DESCRICAO VARCHAR(120);
  DECLARE VARIABLE V_DESCRICAO_PESSOA VARCHAR(5000);
  DECLARE VARIABLE V_TB_TIPO_VINCULO_ID INTEGER;
  DECLARE VARIABLE V_DESC_VINCULO VARCHAR(120); 
  DECLARE VARIABLE V_SQL VARCHAR(5000);
  declare variable V_BAIRRO_IDS VARCHAR(5000);
  declare variable V_ID VARCHAR(10);
  declare variable V_NUMERO_ATO VARCHAR(20);
BEGIN
  V_BAIRRO_IDS = '';
  if (COALESCE(:BAIRRO_DESCRICAO,'') <> '') then
  BEGIN
    FOR SELECT TB_BAIRRO_ID FROM G_TB_BAIRRO
        WHERE DESCRICAO = :BAIRRO_DESCRICAO
        AND SITUACAO = 'A'
        AND SISTEMA_ID = 1
        INTO :V_ID DO
    BEGIN
      if (:V_BAIRRO_IDS = '') then
      BEGIN
        V_BAIRRO_IDS = :V_ID;
      END
      ELSE
      BEGIN
        V_BAIRRO_IDS = ','||:V_ID;
      END
    END
  END

  V_SQL = 'SELECT I.IMOVEL_ID, I.NUMERO, A.TIPO, A.NUMERO, I.NUMERO_LETRA, I.DATA_REGISTRO, A.COMPLEMENTO
      FROM R_IMOVEL I, R_IMOVEL_ANTERIOR A, R_IMOVEL_UNIDADE U
      WHERE I.IMOVEL_ID = A.IMOVEL_ID
      AND I.IMOVEL_ID = U.IMOVEL_ID
      AND I.TIPO_REGISTRO = '||'''M'''||
      ' AND I.NUMERO BETWEEN '||:MATRICULA_INI||' AND '||:MATRICULA_FIM;

  IF (COALESCE(:COMPLEMENTO_SERVENTIA,'') <> '') THEN
  BEGIN        
    V_SQL = :V_SQL || ' AND A.COMPLEMENTO = '||''''||:COMPLEMENTO_SERVENTIA||'''';
  END

  if (:V_BAIRRO_IDS <> '') then
  BEGIN
    V_SQL = :V_SQL || ' AND U.TB_BAIRRO_ID IN ('||:V_BAIRRO_IDS||') ';
  END

  V_SQL = :V_SQL || ' ORDER BY I.NUMERO ';

  FOR EXECUTE STATEMENT V_SQL
      INTO :V_IMOVEL_ID, :MATRICULA, :V_TIPO, :V_NUMERO, :MATRICULA_LETRA, :DATA_REGISTRO, :COMPLEMENTO DO
  BEGIN
    SELECT FIRST 1 COALESCE(ENDERECO,'')||', '||COALESCE(COMPLEMENTO_COMPLETO,'')||', '||
      COALESCE(BAIRRO,'')||', '||COALESCE(MUNICIPIO,'')||' - Área: '||COALESCE(AREA,'')
    FROM R_DADOS_IMOVEL('M', :MATRICULA, :MATRICULA, '', '')
    ORDER BY IMOVEL_UNIDADE_ID DESC
    INTO :DADOS_IMOVEL;
    
    IF (:V_TIPO = 'M') THEN
    BEGIN
      REGISTRO_ANTERIOR = 'Mat. '||:V_NUMERO;
    END
    ELSE IF (:V_TIPO = 'T') THEN
    BEGIN
      REGISTRO_ANTERIOR = 'Transc. '||:V_NUMERO;
    END
    ELSE IF (:V_TIPO = 'I') THEN
    BEGIN
      REGISTRO_ANTERIOR = 'Insc. '||:V_NUMERO;
    END
    ELSE 
    BEGIN
      REGISTRO_ANTERIOR = :V_NUMERO;
    END    

    VINCULOS = '';
    FOR SELECT first 1 V.NOME, V.DOCUMENTO, V.CPF_CNPJ, V.TB_ESTADOCIVIL_ID, V.TB_TIPO_VINCULO_ID, COALESCE(V.tipo_ato,'')||'-'||CAST(CAST(V.numero_ato AS integer) AS VARCHAR(20))
        FROM R_PESSOA_VINCULO V
        WHERE V.IMOVEL_ID = :V_IMOVEL_ID
        AND V.DATA_TRANSFERENCIA IS NULL
        ORDER BY V.NUMERO_ATO desc
        INTO :V_NOME, :V_DOCUMENTO, :V_CPF_CNPJ, :V_TB_ESTADOCIVIL_ID, :V_TB_TIPO_VINCULO_ID, :V_NUMERO_ATO DO
    BEGIN
      IF (:VINCULOS <> '') THEN
      BEGIN
        VINCULOS = :VINCULOS ||ASCII_CHAR(13);      
      END
    
      IF (COALESCE(:V_TB_ESTADOCIVIL_ID,0) > 0) THEN
      BEGIN
        SELECT E.DESCRICAO 
        FROM G_TB_ESTADOCIVIL E
        WHERE E.TB_ESTADOCIVIL_ID = :V_TB_ESTADOCIVIL_ID
        INTO :V_DESCRICAO;
      END
      ELSE
      BEGIN
        V_DESCRICAO = '';
      END

      IF (COALESCE(:V_TB_TIPO_VINCULO_ID,0) > 0) THEN
      BEGIN
        SELECT T.DESCRICAO 
        FROM R_TB_TIPO_VINCULO T
        WHERE T.TB_TIPO_VINCULO_ID = :V_TB_TIPO_VINCULO_ID
        INTO :V_DESC_VINCULO;
      END
      ELSE
      BEGIN
        V_DESC_VINCULO = '';
      END

      IF (COALESCE(:V_DESC_VINCULO,'') = '') THEN
      BEGIN
        V_DESCRICAO_PESSOA = :V_NOME;
      END
      ELSE
      BEGIN
        V_DESCRICAO_PESSOA = :V_DESC_VINCULO || ': ' || :V_NOME;
      END
      
      IF (COALESCE(:V_DOCUMENTO,'') <> '') THEN
      BEGIN
        V_DESCRICAO_PESSOA = :V_DESCRICAO_PESSOA || ' - Documento: '||:V_DOCUMENTO;
      END
      IF (COALESCE(:V_CPF_CNPJ,'') <> '') THEN
      BEGIN
        V_DESCRICAO_PESSOA = :V_DESCRICAO_PESSOA || ' - CPF/CNPJ: '||
          (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CPF_CNPJ));
      END
      IF (COALESCE(:V_DESCRICAO,'') <> '') THEN
      BEGIN
        V_DESCRICAO_PESSOA = :V_DESCRICAO_PESSOA || ' - Estado Civil: '||:V_DESCRICAO;
      END                 
      VINCULOS = :V_NUMERO_ATO||': '|| :VINCULOS || :V_DESCRICAO_PESSOA;
    END        
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_MATRICULAS_OUTRAS_SERV_DATA (DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
COMPLEMENTO_SERVENTIA VARCHAR(200) CHARACTER SET ISO8859_1,
BAIRRO_DESCRICAO VARCHAR(120) CHARACTER SET ISO8859_1)
RETURNS (MATRICULA INTEGER,
MATRICULA_LETRA VARCHAR(10) CHARACTER SET ISO8859_1,
DADOS_IMOVEL VARCHAR(5000) CHARACTER SET ISO8859_1,
REGISTRO_ANTERIOR VARCHAR(60) CHARACTER SET ISO8859_1,
COMPLEMENTO VARCHAR(260) CHARACTER SET ISO8859_1,
VINCULOS VARCHAR(5000) CHARACTER SET ISO8859_1,
DATA_ABERTURA DATAHORA,
DATA_REGISTRO DATAHORA)
AS 
DECLARE VARIABLE V_TIPO VARCHAR(20);
  DECLARE VARIABLE V_NUMERO INTEGER;
  DECLARE VARIABLE V_IMOVEL_ID INTEGER;
  
  DECLARE VARIABLE V_NOME VARCHAR(120);
  DECLARE VARIABLE V_DOCUMENTO VARCHAR(120);
  DECLARE VARIABLE V_CPF_CNPJ VARCHAR(20);
  DECLARE VARIABLE V_TB_ESTADOCIVIL_ID INTEGER;
  DECLARE VARIABLE V_DESCRICAO VARCHAR(120);
  DECLARE VARIABLE V_DESCRICAO_PESSOA VARCHAR(5000);
  DECLARE VARIABLE V_TB_TIPO_VINCULO_ID INTEGER;
  DECLARE VARIABLE V_DESC_VINCULO VARCHAR(120); 
  DECLARE VARIABLE V_SQL VARCHAR(5000);
  declare variable V_BAIRRO_IDS VARCHAR(5000);
  declare variable V_ID VARCHAR(10);
  declare variable V_NUMERO_ATO VARCHAR(20);
BEGIN
  V_BAIRRO_IDS = '';
  if (COALESCE(:BAIRRO_DESCRICAO,'') <> '') then
  BEGIN
    FOR SELECT TB_BAIRRO_ID FROM G_TB_BAIRRO
        WHERE DESCRICAO = :BAIRRO_DESCRICAO
        AND SITUACAO = 'A'
        AND SISTEMA_ID = 1
        INTO :V_ID DO
    BEGIN
      if (:V_BAIRRO_IDS = '') then
      BEGIN
        V_BAIRRO_IDS = :V_ID;
      END
      ELSE
      BEGIN
        V_BAIRRO_IDS = ','||:V_ID;
      END
    END
  END

  V_SQL = 'SELECT I.IMOVEL_ID, I.NUMERO, A.TIPO, A.NUMERO, I.NUMERO_LETRA, I.DATA_REGISTRO, A.COMPLEMENTO, I.DATA_ABERTURA
      FROM R_IMOVEL I, R_IMOVEL_ANTERIOR A, R_IMOVEL_UNIDADE U
      WHERE I.IMOVEL_ID = A.IMOVEL_ID
      AND I.IMOVEL_ID = U.IMOVEL_ID
      AND I.TIPO_REGISTRO = '||'''M'''||
      ' AND CAST(I.data_registro AS DATE) BETWEEN '||''''||:DATA_INI||''''||' AND '||''''||:DATA_FIM||'''';

  IF (COALESCE(:COMPLEMENTO_SERVENTIA,'') <> '') THEN
  BEGIN        
    V_SQL = :V_SQL || ' AND A.COMPLEMENTO = '||''''||:COMPLEMENTO_SERVENTIA||'''';
  END

  if (:V_BAIRRO_IDS <> '') then
  BEGIN
    V_SQL = :V_SQL || ' AND U.TB_BAIRRO_ID IN ('||:V_BAIRRO_IDS||') ';
  END

  V_SQL = :V_SQL || ' ORDER BY I.NUMERO ';

  FOR EXECUTE STATEMENT V_SQL
      INTO :V_IMOVEL_ID, :MATRICULA, :V_TIPO, :V_NUMERO, :MATRICULA_LETRA, :DATA_REGISTRO, :COMPLEMENTO, :DATA_ABERTURA DO
  BEGIN
    SELECT FIRST 1 COALESCE(ENDERECO,'')||', '||COALESCE(COMPLEMENTO_COMPLETO,'')||', '||
      COALESCE(BAIRRO,'')||', '||COALESCE(MUNICIPIO,'')||' - Área: '||COALESCE(AREA,'')
    FROM R_DADOS_IMOVEL('M', :MATRICULA, :MATRICULA, '', '')
    ORDER BY IMOVEL_UNIDADE_ID DESC
    INTO :DADOS_IMOVEL;
    
    IF (:V_TIPO = 'M') THEN
    BEGIN
      REGISTRO_ANTERIOR = 'Mat. '||:V_NUMERO;
    END
    ELSE IF (:V_TIPO = 'T') THEN
    BEGIN
      REGISTRO_ANTERIOR = 'Transc. '||:V_NUMERO;
    END
    ELSE IF (:V_TIPO = 'I') THEN
    BEGIN
      REGISTRO_ANTERIOR = 'Insc. '||:V_NUMERO;
    END
    ELSE 
    BEGIN
      REGISTRO_ANTERIOR = :V_NUMERO;
    END    

    VINCULOS = '';
    FOR SELECT first 1 V.NOME, V.DOCUMENTO, V.CPF_CNPJ, V.TB_ESTADOCIVIL_ID, V.TB_TIPO_VINCULO_ID, COALESCE(V.tipo_ato,'')||'-'||CAST(CAST(V.numero_ato AS integer) AS VARCHAR(20))
        FROM R_PESSOA_VINCULO V
        WHERE V.IMOVEL_ID = :V_IMOVEL_ID
        AND V.DATA_TRANSFERENCIA IS NULL
        ORDER BY V.NUMERO_ATO desc
        INTO :V_NOME, :V_DOCUMENTO, :V_CPF_CNPJ, :V_TB_ESTADOCIVIL_ID, :V_TB_TIPO_VINCULO_ID, :V_NUMERO_ATO DO
    BEGIN
      IF (:VINCULOS <> '') THEN
      BEGIN
        VINCULOS = :VINCULOS ||ASCII_CHAR(13);      
      END
    
      IF (COALESCE(:V_TB_ESTADOCIVIL_ID,0) > 0) THEN
      BEGIN
        SELECT E.DESCRICAO 
        FROM G_TB_ESTADOCIVIL E
        WHERE E.TB_ESTADOCIVIL_ID = :V_TB_ESTADOCIVIL_ID
        INTO :V_DESCRICAO;
      END
      ELSE
      BEGIN
        V_DESCRICAO = '';
      END

      IF (COALESCE(:V_TB_TIPO_VINCULO_ID,0) > 0) THEN
      BEGIN
        SELECT T.DESCRICAO 
        FROM R_TB_TIPO_VINCULO T
        WHERE T.TB_TIPO_VINCULO_ID = :V_TB_TIPO_VINCULO_ID
        INTO :V_DESC_VINCULO;
      END
      ELSE
      BEGIN
        V_DESC_VINCULO = '';
      END

      IF (COALESCE(:V_DESC_VINCULO,'') = '') THEN
      BEGIN
        V_DESCRICAO_PESSOA = :V_NOME;
      END
      ELSE
      BEGIN
        V_DESCRICAO_PESSOA = :V_DESC_VINCULO || ': ' || :V_NOME;
      END
      
      IF (COALESCE(:V_DOCUMENTO,'') <> '') THEN
      BEGIN
        V_DESCRICAO_PESSOA = :V_DESCRICAO_PESSOA || ' - Documento: '||:V_DOCUMENTO;
      END
      IF (COALESCE(:V_CPF_CNPJ,'') <> '') THEN
      BEGIN
        V_DESCRICAO_PESSOA = :V_DESCRICAO_PESSOA || ' - CPF/CNPJ: '||
          (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CPF_CNPJ));
      END
      IF (COALESCE(:V_DESCRICAO,'') <> '') THEN
      BEGIN
        V_DESCRICAO_PESSOA = :V_DESCRICAO_PESSOA || ' - Estado Civil: '||:V_DESCRICAO;
      END                 
      VINCULOS = :V_NUMERO_ATO||': '|| :VINCULOS || :V_DESCRICAO_PESSOA;
    END        
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_MONTAR_COAF (V_PROTOCOLO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_DATA_INI DATE,
V_DATA_FIM DATE)
RETURNS (NUMERO_PROTOCOLO NUMERIC(10, 2),
PROTOCOLO_ID NUMERIC(10, 2),
DATA_PROTOCOLO TIMESTAMP,
LIVRO VARCHAR(10) CHARACTER SET ISO8859_1,
FOLHA VARCHAR(10) CHARACTER SET ISO8859_1,
MATRICULA NUMERIC(9, 0),
REGISTRO VARCHAR(15) CHARACTER SET ISO8859_1,
SITUACAO VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_TRANSACAO VARCHAR(3) CHARACTER SET ISO8859_1,
RETIFICACAO_ATO VARCHAR(1) CHARACTER SET ISO8859_1,
DATA_TITULO TIMESTAMP,
VALOR_ALIENACAO NUMERIC(18, 4),
DETALHE VARCHAR_260,
NUMERO_LETRA VARCHAR(15) CHARACTER SET ISO8859_1,
NATUREZA_TITULO_ID INTEGER,
NUMERO_ATO VARCHAR(15) CHARACTER SET ISO8859_1,
DATA_ANDAMENTO TIMESTAMP)
AS 
declare variable V_SQL varchar(5000);
declare variable V_FILTRO VARCHAR_1000;
declare variable V_PROT_ID integer;
declare variable V_TIPO_REGISTRO varchar(3);
declare variable V_TITULO VARCHAR_120;
BEGIN
  IF (TRIM(:V_PROTOCOLO_ID) <> '0') THEN
  BEGIN 
    V_FILTRO =  ' AND    PR.PROTOCOLO_ID = '||:V_PROTOCOLO_ID;
  END
  ELSE
  BEGIN
    V_FILTRO =  ' AND  CAST(A.DATA AS DATE) BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP)
           and cast('||''''||:V_DATA_FIM||''''||' as timestamp) + 0.9999 ';
  END
  V_SQL = ' SELECT DISTINCT
               CAST(PR.NUMERO_ORDEM AS INTEGER) AS NUMERO_ORDEM,
               PR.DATA AS DATA_PROTOCOLO,
               PR.FOLHA_NUMERO||PR.FOLHA_FV AS FOLHA,
               CAST(PN.NUMERO AS INTEGER) AS MATRICULA,
               PN.NUMERO_LETRA,
               PE.DATA_TITULO AS DATA_TITULO,
               PI.VALOR_DOCUMENTO AS VALOR_ALIENACAO,
               PI.NATUREZA_TITULO_ID,
               TRIM(SUBSTRING(CAST(CAST(COALESCE(PN.ATO_NUMERO,0) AS INTEGER) AS VARCHAR(12)) FROM 1 FOR 5)),
               CASE PN.ATO_TIPO
                    WHEN ''A'' THEN ''AV.''
                    WHEN ''R'' THEN ''R.''
                    ELSE ''''
               END AS REGISTRO,
               CAST(A.DATA AS DATE) DATA,
               PR.PROTOCOLO_ID,
               PN.TIPO_REGISTRO,
               PR.PROTOCOLO_ID,
               RTB.descricao
          FROM   R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A,
                 R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                 g_natureza_titulo rtb, r_tb_tipo_andamento rta
          WHERE  PR.PEDIDO_ID = PE.PEDIDO_ID
          AND    PI.PEDIDO_ID = PE.PEDIDO_ID
          AND    PE.PEDIDO_ID = A.PEDIDO_ID
          AND    PN.PEDIDO_ITEM_ID = PI.PEDIDO_ITEM_ID
          AND    RTB.NATUREZA_TITULO_ID = pi.natureza_titulo_id
          AND    A.tb_tipo_andamento_id = RTA.tb_tipo_andamento_id
          AND    RTA.tipo = ''R''
          AND    PI.VALOR_DOCUMENTO >= 100000
          AND    ((PN.TIPO_REGISTRO = ''M'') OR (PN.TIPO_REGISTRO = ''T''))
           '|| V_FILTRO||
        ' AND PI.VALOR_DOCUMENTO > 0
          AND    PR.TIPO_PROTOCOLO = ''1'''; --Somente protocolos
  FOR EXECUTE STATEMENT :V_SQL INTO
                 :NUMERO_PROTOCOLO,
                 :DATA_PROTOCOLO,
                 :FOLHA,
                 :MATRICULA,
                 :NUMERO_LETRA,
                 :DATA_TITULO,
                 :VALOR_ALIENACAO,
                 :NATUREZA_TITULO_ID,
                 :NUMERO_ATO ,
                 :REGISTRO,
                 :DATA_ANDAMENTO,
                 :V_PROT_ID,
                 :V_TIPO_REGISTRO,
                 :PROTOCOLO_ID,
                 :v_TITULO DO
 BEGIN
   DETALHE =  'Protocolo: '||cast(:NUMERO_PROTOCOLO as integer)||' - Matricula: '||:MATRICULA||' '||REGISTRO||' '||:NUMERO_ATO||' '||:v_TITULO;
 SUSPEND;
 END
END ^

ALTER PROCEDURE R_MONTAR_DOI (V_PROTOCOLO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_DATA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO_ANDAMENTO_DOI VARCHAR(10) CHARACTER SET ISO8859_1,
V_TIPO_PESQUISA_DOI VARCHAR(3) CHARACTER SET ISO8859_1,
V_TIPO_NATUREZA_ALIENACAO_VALOR VARCHAR(10) CHARACTER SET ISO8859_1,
V_CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (NUMERO_PROTOCOLO NUMERIC(10, 2),
DATA_PROTOCOLO TIMESTAMP,
LIVRO VARCHAR(10) CHARACTER SET ISO8859_1,
FOLHA VARCHAR(10) CHARACTER SET ISO8859_1,
MATRICULA VARCHAR(15) CHARACTER SET ISO8859_1,
REGISTRO VARCHAR(15) CHARACTER SET ISO8859_1,
SITUACAO VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_TRANSACAO VARCHAR(3) CHARACTER SET ISO8859_1,
RETIFICACAO_ATO VARCHAR(1) CHARACTER SET ISO8859_1,
DATA_TITULO TIMESTAMP,
VALOR_ALIENACAO NUMERIC(18, 4),
VALOR_ITBI NUMERIC(18, 4),
FORMA_ALIENACAO VARCHAR(1) CHARACTER SET ISO8859_1,
ANDAMENTO VARCHAR(1) CHARACTER SET ISO8859_1,
LOCALIZACAO VARCHAR(1) CHARACTER SET ISO8859_1,
AREA VARCHAR(17) CHARACTER SET ISO8859_1,
AREA_AVERBADA VARCHAR(17) CHARACTER SET ISO8859_1,
ENDERECO VARCHAR(60) CHARACTER SET ISO8859_1,
NUMERO_LOGRADOURO VARCHAR(6) CHARACTER SET ISO8859_1,
COMPLEMENTO VARCHAR(30) CHARACTER SET ISO8859_1,
BAIRRO VARCHAR(30) CHARACTER SET ISO8859_1,
CEP VARCHAR(10) CHARACTER SET ISO8859_1,
MUNICIPIO VARCHAR(30) CHARACTER SET ISO8859_1,
TIPO_IMOVEL VARCHAR(3) CHARACTER SET ISO8859_1,
INSCRICAO_IMOVEL VARCHAR(15) CHARACTER SET ISO8859_1,
NUMERO_ATO INTEGER,
NATUREZA_TITULO_ID INTEGER,
DATA_ANDAMENTO TIMESTAMP,
IMOVEL_ID INTEGER,
DESCRICAO_IMOVEL VARCHAR(60) CHARACTER SET ISO8859_1,
NUMERO_LETRA VARCHAR(10) CHARACTER SET ISO8859_1,
CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1,
CODIGO_NATUREZA_SEF VARCHAR(6) CHARACTER SET ISO8859_1,
DESCRICAO_NATUREZA VARCHAR(120) CHARACTER SET ISO8859_1,
DESCRICAO_NATUREZA_SINTER VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_LOGRADOURO_SINTER VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_IMOVEL_SINTER VARCHAR(120) CHARACTER SET ISO8859_1,
UNIDADE_AREA_SINTER VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_CLASSE VARCHAR(1) CHARACTER SET ISO8859_1,
TERMO_QUITACAO VARCHAR(30) CHARACTER SET ISO8859_1,
CNM_NUMERO VARCHAR(30) CHARACTER SET ISO8859_1,
DESCRICAO_LOGRADOURO VARCHAR(90) CHARACTER SET ISO8859_1,
TB_TITULO_ID INTEGER,
CODIGO_TITULO VARCHAR(3) CHARACTER SET ISO8859_1,
TIPO_ATO VARCHAR(10) CHARACTER SET ISO8859_1,
CIB VARCHAR(60) CHARACTER SET ISO8859_1,
CODIGO_INCRA VARCHAR(60) CHARACTER SET ISO8859_1,
TIPO_LIVRO VARCHAR(3) CHARACTER SET ISO8859_1,
DENOMINACAO VARCHAR(300) CHARACTER SET ISO8859_1)
AS 
declare variable V_IMOVEL_TIPO_ID integer;
declare variable V_QUANTIDADE integer;
declare variable V_PROT_ID integer;
declare variable V_MAT varchar(15);
declare variable v_count integer;
declare variable V_IMOVEL_UNIDADE_ID INTEGER;
declare variable v_tipo_imovel varchar(120);
declare variable v_pos integer;
declare variable v_numero_car varchar(60);
declare variable v_numero_nirf varchar(260);
declare variable v_descricao_titulo varchar(120);
declare variable v_novo varchar(3);
BEGIN
  CARTORIO = :V_CARTORIO;
  LIVRO = '2';
  IF (TRIM(:V_PROTOCOLO_ID) <> '') THEN
  BEGIN 
    FOR SELECT DISTINCT
               CAST(PR.NUMERO_ORDEM AS INTEGER) AS NUMERO_ORDEM,
               PR.DATA AS DATA_PROTOCOLO,
               PR.FOLHA_NUMERO||PR.FOLHA_FV AS FOLHA,
               CAST(PN.NUMERO AS INTEGER) AS MATRICULA,
               PN.NUMERO_LETRA,
               PE.DATA_TITULO AS DATA_TITULO,
               PI.VALOR_DOCUMENTO AS VALOR_ALIENACAO,
               PI.VALOR_ITBI AS VALOR_ITBI,
               PI.NATUREZA_TITULO_ID,
               CAST(COALESCE(PN.ATO_NUMERO,0) AS INTEGER),
               CASE PN.ATO_TIPO
                    WHEN 'A' THEN 'AV.'
                    WHEN 'R' THEN 'R.'
                    ELSE ''
               END AS REGISTRO,
               A.DATA,
               PR.PROTOCOLO_ID,
               PN.TIPO_REGISTRO,
               PN.guia_numero,
               PE.tb_titulo_id,
               pn.ato_tipo
          FROM   R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A,
                 R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN
          WHERE  PR.PEDIDO_ID = PE.PEDIDO_ID
          AND    PI.PEDIDO_ID = PE.PEDIDO_ID
          AND    PE.PEDIDO_ID = A.PEDIDO_ID
          AND    PN.PEDIDO_ITEM_ID = PI.PEDIDO_ITEM_ID
          AND    PR.PROTOCOLO_ID = :V_PROTOCOLO_ID
          AND    A.TB_TIPO_ANDAMENTO_ID = :V_TIPO_ANDAMENTO_DOI
          AND    ((PN.TIPO_REGISTRO = 'M') OR (PN.TIPO_REGISTRO = 'T')) --Somente matriculas e transcricoes
          AND    (SELECT COUNT(*) FROM G_NATUREZA_TITULO N WHERE N.NATUREZA_TITULO_ID = PI.NATUREZA_TITULO_ID AND N.INFORMAR_DOI = 'S') > 0
          ORDER BY PR.DATA, PI.PEDIDO_ITEM_ID
          INTO   :NUMERO_PROTOCOLO,
                 :DATA_PROTOCOLO,
                 :FOLHA,
                 :MATRICULA,
                 :NUMERO_LETRA,
                 :DATA_TITULO,
                 :VALOR_ALIENACAO,
                 :VALOR_ITBI,        
                 :NATUREZA_TITULO_ID,
                 :NUMERO_ATO,
                 :REGISTRO,
                 :DATA_ANDAMENTO,
                 :V_PROT_ID,
                 :TIPO_LIVRO,
                 :TERMO_QUITACAO,
                 :TB_TITULO_ID,
                 :TIPO_ATO DO
    BEGIN
      SELECT FIRST 1 CAST(CODIGO_DOI AS INTEGER), DESCRICAO, COALESCE(DESCRICAO_SINTER,''),
        COALESCE(CAST(CAST(CODIGO_NATUREZA_SEF AS INTEGER) AS VARCHAR(6)),'')
      FROM G_NATUREZA_TITULO
      WHERE NATUREZA_TITULO_ID = :NATUREZA_TITULO_ID
      INTO :TIPO_TRANSACAO, :DESCRICAO_NATUREZA, :DESCRICAO_NATUREZA_SINTER, :CODIGO_NATUREZA_SEF;

      if ((coalesce(:DESCRICAO_NATUREZA,'') <> '') and (coalesce(:DESCRICAO_NATUREZA_SINTER,'') = '')) then
      begin
        select count(*) from g_sinter_tabelas
        where tabela = 'TIPOATOREGISTRAL'
        and valor = ''''||:DESCRICAO_NATUREZA||''''
        into :v_count;

        if (:v_count > 0) then --existe no cadastro
        begin
          DESCRICAO_NATUREZA_SINTER = :DESCRICAO_NATUREZA;
        end
      end

      SELECT FIRST 1 CODIGO_TITULO, DESCRICAO FROM R_TB_TITULO
      WHERE TB_TITULO_ID = :TB_TITULO_ID
      INTO :CODIGO_TITULO, :v_descricao_titulo;
      if (COALESCE(:CODIGO_TITULO,'') = '') then
      begin
        if ((select position('ESCRITURA', UPPER(:v_descricao_titulo)) from rdb$database) > 0) then
        begin
          CODIGO_TITULO = '2';
        end
        else if ((select position('JUDICIAL', UPPER(:v_descricao_titulo)) from rdb$database) > 0) then
        begin
          CODIGO_TITULO = '3';
        end
        else if ((select position('CONTRATO', UPPER(:v_descricao_titulo)) from rdb$database) > 0) then
        begin
          CODIGO_TITULO = '4';
        end
        else if ((select position('INSTRUMENTO', UPPER(:v_descricao_titulo)) from rdb$database) > 0) then
        begin
          CODIGO_TITULO = '1';
        end
        else if ((select position('ESTRANGEIRO', UPPER(:v_descricao_titulo)) from rdb$database) > 0) then
        begin
          CODIGO_TITULO = '5';
        end
        else if (((select position('ESC', UPPER(:v_descricao_titulo)) from rdb$database) > 0) and
                ((select position('PUB', UPPER(:v_descricao_titulo)) from rdb$database) > 0)) then
        begin
          CODIGO_TITULO = '2';
        end
        else if (((select position('ESC', UPPER(:v_descricao_titulo)) from rdb$database) > 0) and
                ((select position('PÚB', UPPER(:v_descricao_titulo)) from rdb$database) > 0)) then
        begin
          CODIGO_TITULO = '2';
        end
        else if (((select position('INST', UPPER(:v_descricao_titulo)) from rdb$database) > 0) and
                ((select position('PART', UPPER(:v_descricao_titulo)) from rdb$database) > 0)) then
        begin
          CODIGO_TITULO = '1';
        end
      end

      V_MAT = :MATRICULA;
      --IF (COALESCE(:TIPO_LIVRO,'') = 'T') THEN
      --BEGIN
        --MATRICULA = 'T'||:MATRICULA;
      --END
      
      IF (:REGISTRO <> '') THEN
      BEGIN
        REGISTRO = :REGISTRO || :NUMERO_ATO;
      END

      IF ((:VALOR_ITBI = 0) OR (:VALOR_ITBI IS NULL)) THEN
      BEGIN
        VALOR_ITBI = :VALOR_ALIENACAO;
      END
      
      IF (:V_TIPO_NATUREZA_ALIENACAO_VALOR <> '') THEN
      BEGIN
        SELECT COUNT(*) FROM R_PEDIDO_ITEM PI, R_PROTOCOLO PR
        WHERE PI.PEDIDO_ID = PR.PEDIDO_ID
        AND PR.TIPO_PROTOCOLO = '1'
        AND PR.PROTOCOLO_ID = :V_PROT_ID
        AND PI.NATUREZA_TITULO_ID = :V_TIPO_NATUREZA_ALIENACAO_VALOR
        INTO :V_QUANTIDADE;
        
        IF (:V_QUANTIDADE > 0) THEN
        BEGIN
          SELECT FIRST 1 PI.VALOR_DOCUMENTO FROM R_PEDIDO_ITEM PI, R_PROTOCOLO PR
          WHERE PI.PEDIDO_ID = PR.PEDIDO_ID
          AND PR.TIPO_PROTOCOLO = '1'
          AND PR.PROTOCOLO_ID = :V_PROT_ID
          AND PI.NATUREZA_TITULO_ID = :V_TIPO_NATUREZA_ALIENACAO_VALOR
          INTO :VALOR_ALIENACAO;          
        END
      END

      SITUACAO = '0'; -- 0.DOI Normal  1.Retificadora  3.Canceladora

      RETIFICACAO_ATO = '0'; -- 0.A operacao nao eh uma retificacao de ato anterior.
                           -- 1.A operacao eh uma retificacao de um ato anterior.

      FORMA_ALIENACAO = ''; --5.A vista  7.A prazo  9.Nao se Aplica

      TIPO_CLASSE = NULL;
      V_IMOVEL_TIPO_ID = NULL;
      AREA = NULL;
      ENDERECO = NULL;
      NUMERO_LOGRADOURO = NULL;
      COMPLEMENTO = NULL;
      BAIRRO = NULL;
      CEP = NULL;
      MUNICIPIO = NULL;
      INSCRICAO_IMOVEL = NULL;
      AREA_AVERBADA = NULL;
      ANDAMENTO = NULL;
      LOCALIZACAO = NULL;
      TIPO_IMOVEL = NULL;
      DESCRICAO_IMOVEL = NULL;      
      V_NUMERO_CAR = NULL;

      SELECT FIRST 1 TIPO_CLASSE, IMOVEL_TIPO_ID,
             TRIM(SUBSTRING(AREA FROM 1 FOR 17)),
             TRIM(SUBSTRING(ENDERECO FROM 1 FOR 60)),
             TRIM(SUBSTRING(NUMERO_LOGRADOURO FROM 1 FOR 6)),
             TRIM(SUBSTRING(COMPLEMENTO_COMPLETO FROM 1 FOR 30)),
             TRIM(SUBSTRING(BAIRRO FROM 1 FOR 30)),
             TRIM(SUBSTRING(CAST(CAST(CEP AS INTEGER) AS VARCHAR(20)) FROM 1 FOR 8)),
             TRIM(SUBSTRING(MUNICIPIO FROM 1 FOR 30)),
             TRIM(SUBSTRING(INSCRICAO_IMOVEL FROM 1 FOR 15)),
             AREA_AVERBADA, TIPO_CONSTRUCAO, IMOVEL_ID,
             IMOVEL_UNIDADE_ID,
             TRIM(SUBSTRING(NUMERO_CAR FROM 1 FOR 15)),
             CNM_NUMERO, DESCRICAO_LOGRADOURO, CIB, CODIGO_INCRA,
             NOME_EDIFICACAO, novo
      FROM R_DADOS_IMOVEL(:TIPO_LIVRO,:V_MAT,:V_MAT, :NUMERO_LETRA, :V_CARTORIO)
      ORDER BY IMOVEL_UNIDADE_ID DESC
      INTO :TIPO_CLASSE, :V_IMOVEL_TIPO_ID,
           :AREA,
           :ENDERECO,
           :NUMERO_LOGRADOURO,
           :COMPLEMENTO,
           :BAIRRO,
           :CEP,
           :MUNICIPIO,
           :INSCRICAO_IMOVEL,
           :AREA_AVERBADA,
           :ANDAMENTO,
           :IMOVEL_ID,
           :V_IMOVEL_UNIDADE_ID,
           :V_NUMERO_CAR,
           :CNM_NUMERO,
           :DESCRICAO_LOGRADOURO,
           :CIB, :CODIGO_INCRA, :DENOMINACAO, :v_novo;

      if (:v_novo = 'S') then
      begin
        select first 1 area, area_averbada from r_imovel_unidade
        where imovel_id = :imovel_id
        and coalesce(novo,'') <> 'S'
        into :area, :area_averbada;
      end

      select numero_nirf from r_imovel
      where imovel_id = :imovel_id
      into :v_numero_nirf;

      if ((coalesce(:tipo_classe,'') = 'R') AND (COALESCE(:v_numero_nirf,'') <> '')) then --SE FOR IMOVEL RURAL
      begin
        INSCRICAO_IMOVEL = TRIM(SUBSTRING(:v_numero_nirf FROM 1 FOR 15));
      end

      if (coalesce(:endereco,'') = '') then
      begin
        endereco = :complemento;
      end

      tipo_logradouro_sinter = '';
      if (coalesce(:V_IMOVEL_UNIDADE_ID,0) > 0) then
      begin
        select first 1 tl.descricao from r_imovel_logradouro il, g_tb_tipologradouro tl
        where il.tb_tipologradouro_id = tl.tb_tipologradouro_id
        and il.imovel_unidade_id = :V_IMOVEL_UNIDADE_ID
        order by il.imovel_logradouro_id
        into :tipo_logradouro_sinter;
      end
      if (coalesce(:tipo_logradouro_sinter,'') = '') then
      begin
        select first 1 tl.descricao from r_imovel_unidade u,  g_tb_tipologradouro tl
        where u.tb_tipologradouro_id = tl.tb_tipologradouro_id
        and u.imovel_unidade_id = :V_IMOVEL_UNIDADE_ID
        order by u.imovel_unidade_id desc
        into :tipo_logradouro_sinter;
      end

      TIPO_IMOVEL_SINTER = '';
      UNIDADE_AREA_SINTER = '';
      IF (COALESCE(:TIPO_CLASSE,'') = 'L') THEN
      BEGIN
        TIPO_IMOVEL_SINTER = 'Terreno/Lote';
        UNIDADE_AREA_SINTER = 'm2 (metro quadrado)';
      END
      ELSE IF (COALESCE(:TIPO_CLASSE,'') = 'R') THEN
      BEGIN
        TIPO_IMOVEL_SINTER = 'Gleba';
        UNIDADE_AREA_SINTER = 'Ha (hectare)';
      END
      ELSE --SE FOR CONDOMINIO
      BEGIN
        UNIDADE_AREA_SINTER = 'm2 (metro quadrado)';
        if (coalesce(:V_IMOVEL_TIPO_ID,0) > 0) then
        begin
          select FIRST 1 descricao from r_imovel_tipo
          where imovel_tipo_id = :V_IMOVEL_TIPO_ID
          into :v_tipo_imovel;

          if ((select position('Apto', :v_tipo_imovel) from rdb$database) > 0) then
          begin
            TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Apartamento';
          end
          else if ((select position('Apartamento', :v_tipo_imovel) from rdb$database) > 0) then
          begin
            TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Apartamento';
          end
          else if ((select position('Apart.', :v_tipo_imovel) from rdb$database) > 0) then
          begin
            TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Apartamento';
          end
          else if ((select position('Lote', :v_tipo_imovel) from rdb$database) > 0) then
          begin
            TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Lote';
          end
          else if ((select position('Sala', :v_tipo_imovel) from rdb$database) > 0) then
          begin
            TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Sala/Loja';
          end
          else if ((select position('Loja', :v_tipo_imovel) from rdb$database) > 0) then
          begin
            TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Sala/Loja';
          end
          else
          begin
            TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Garagem, Box, Outras';
          end
        end
        else
        begin
          TIPO_IMOVEL_SINTER = 'Terreno/Lote';
        end
      END

      IF ((:ANDAMENTO = '') OR (:ANDAMENTO IS NULL)) THEN
      BEGIN
        SELECT FIRST 1 TIPO_CONSTRUCAO
        FROM R_DADOS_IMOVEL(:TIPO_LIVRO,:V_MAT,:V_MAT,:NUMERO_LETRA, :V_CARTORIO)
        ORDER BY IMOVEL_UNIDADE_ID
        INTO :ANDAMENTO;
      END
      IF ((:ANDAMENTO = '') OR (:ANDAMENTO IS NULL)) THEN
      BEGIN
        ANDAMENTO = '2'; -- 0.Construcao Averbada  1.Em Construcao  2.Nao se Aplica
      END 

      SELECT FIRST 1 TRIM(SUBSTRING(CAST(CAST(CODIGO_DOI AS INTEGER) AS VARCHAR(12)) FROM 1 FOR 3)), DESCRICAO
      FROM R_IMOVEL_TIPO
      WHERE IMOVEL_TIPO_ID = :V_IMOVEL_TIPO_ID
      INTO :TIPO_IMOVEL, :DESCRICAO_IMOVEL;

      IF (:TIPO_CLASSE = 'R') THEN
      BEGIN
        LOCALIZACAO = '3'; --Rural
        IF ((:TIPO_IMOVEL = '') OR (:TIPO_IMOVEL IS NULL)) THEN
        BEGIN
          TIPO_IMOVEL = '69';
        END
      END
      ELSE
      BEGIN
        LOCALIZACAO = '1'; --Urbano
        IF ((:TIPO_IMOVEL = '') OR (:TIPO_IMOVEL IS NULL)) THEN
        BEGIN
          TIPO_IMOVEL = '71';
        END        
      END

      SUSPEND;
    END
  END  
  ELSE
  BEGIN  
    IF ((:V_TIPO_PESQUISA_DOI <> '2') OR (:V_TIPO_PESQUISA_DOI IS NULL)) THEN
    BEGIN
      FOR SELECT DISTINCT
                 CAST(PR.NUMERO_ORDEM AS INTEGER) AS NUMERO_ORDEM,
                 PR.DATA AS DATA_PROTOCOLO,
                 PR.FOLHA_NUMERO||PR.FOLHA_FV AS FOLHA,
                 CAST(PN.NUMERO AS INTEGER) AS MATRICULA,
                 PN.NUMERO_LETRA,
                 PE.DATA_TITULO AS DATA_TITULO,
                 PI.VALOR_DOCUMENTO AS VALOR_ALIENACAO,
                 PI.VALOR_ITBI AS VALOR_ITBI,
                 PI.NATUREZA_TITULO_ID,
                 TRIM(SUBSTRING(CAST(CAST(COALESCE(PN.ATO_NUMERO,0) AS INTEGER) AS VARCHAR(12)) FROM 1 FOR 5)),
                 CASE PN.ATO_TIPO
                      WHEN 'A' THEN 'AV.'
                      WHEN 'R' THEN 'R.'
                      ELSE ''
                 END AS REGISTRO,
                 A.DATA,
                 PR.PROTOCOLO_ID,
                 PN.TIPO_REGISTRO,
                 PN.guia_numero,
                 PE.tb_titulo_id,
                 PN.ATO_TIPO
            FROM   R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A,
                   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN                               
            WHERE  PR.PEDIDO_ID = PE.PEDIDO_ID
            AND    PI.PEDIDO_ID = PE.PEDIDO_ID
            AND    PE.PEDIDO_ID = A.PEDIDO_ID
            AND    PN.PEDIDO_ITEM_ID = PI.PEDIDO_ITEM_ID
            AND    PR.DATA BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)
                               AND CAST(:V_DATA_FIM AS TIMESTAMP) + 0.99999
            AND    A.TB_TIPO_ANDAMENTO_ID = :V_TIPO_ANDAMENTO_DOI
            AND    ((PN.TIPO_REGISTRO = 'M') OR (PN.TIPO_REGISTRO = 'T')) --Somente matriculas e transcricoes
            AND    (SELECT COUNT(*) FROM G_NATUREZA_TITULO N WHERE N.NATUREZA_TITULO_ID = PI.NATUREZA_TITULO_ID AND N.INFORMAR_DOI = 'S') > 0            
            AND    PR.TIPO_PROTOCOLO = '1' --Somente protocolos
            ORDER BY PR.DATA, PI.PEDIDO_ITEM_ID
            INTO   :NUMERO_PROTOCOLO,
                   :DATA_PROTOCOLO,
                   :FOLHA,
                   :MATRICULA,
                   :NUMERO_LETRA,
                   :DATA_TITULO,
                   :VALOR_ALIENACAO,
                   :VALOR_ITBI,        
                   :NATUREZA_TITULO_ID,
                   :NUMERO_ATO,
                   :REGISTRO,
                   :DATA_ANDAMENTO,
                   :V_PROT_ID,
                   :TIPO_LIVRO,
                   :TERMO_QUITACAO,
                   :TB_TITULO_ID,
                   :TIPO_ATO DO
      BEGIN
        SELECT FIRST 1 CAST(CODIGO_DOI AS INTEGER), DESCRICAO, COALESCE(DESCRICAO_SINTER,''),
          COALESCE(CAST(CAST(CODIGO_NATUREZA_SEF AS INTEGER) AS VARCHAR(6)),'')
        FROM G_NATUREZA_TITULO
        WHERE NATUREZA_TITULO_ID = :NATUREZA_TITULO_ID
        INTO :TIPO_TRANSACAO, :DESCRICAO_NATUREZA, :DESCRICAO_NATUREZA_SINTER, :CODIGO_NATUREZA_SEF;

        if ((coalesce(:DESCRICAO_NATUREZA,'') <> '') and (coalesce(:DESCRICAO_NATUREZA_SINTER,'') = '')) then
        begin
          select count(*) from g_sinter_tabelas
          where tabela = 'TIPOATOREGISTRAL'
          and valor = ''''||:DESCRICAO_NATUREZA||''''
          into :v_count;

          if (:v_count > 0) then --existe no cadastro
          begin
            DESCRICAO_NATUREZA_SINTER = :DESCRICAO_NATUREZA;
          end
        end

        SELECT FIRST 1 CODIGO_TITULO, DESCRICAO FROM R_TB_TITULO
        WHERE TB_TITULO_ID = :TB_TITULO_ID
        INTO :CODIGO_TITULO, :v_descricao_titulo;
        if (COALESCE(:CODIGO_TITULO,'') = '') then
        begin
          if ((select position('ESCRITURA', UPPER(:v_descricao_titulo)) from rdb$database) > 0) then
          begin
            CODIGO_TITULO = '2';
          end
          else if ((select position('JUDICIAL', UPPER(:v_descricao_titulo)) from rdb$database) > 0) then
          begin
            CODIGO_TITULO = '3';
          end
          else if ((select position('CONTRATO', UPPER(:v_descricao_titulo)) from rdb$database) > 0) then
          begin
            CODIGO_TITULO = '4';
          end
          else if ((select position('INSTRUMENTO', UPPER(:v_descricao_titulo)) from rdb$database) > 0) then
          begin
            CODIGO_TITULO = '1';
          end
          else if ((select position('ESTRANGEIRO', UPPER(:v_descricao_titulo)) from rdb$database) > 0) then
          begin
            CODIGO_TITULO = '5';
          end
        end

        V_MAT = :MATRICULA;
        --IF (COALESCE(:TIPO_LIVRO,'') = 'T') THEN
        --BEGIN
          --MATRICULA = 'T'||:MATRICULA;
        --END
      
        IF (:REGISTRO <> '') THEN
        BEGIN
          REGISTRO = :REGISTRO || :NUMERO_ATO;
        END

        IF ((:VALOR_ITBI = 0) OR (:VALOR_ITBI IS NULL)) THEN
        BEGIN
          VALOR_ITBI = :VALOR_ALIENACAO;
        END
        
        IF (:V_TIPO_NATUREZA_ALIENACAO_VALOR <> '') THEN
        BEGIN
          SELECT COUNT(*) FROM R_PEDIDO_ITEM PI, R_PROTOCOLO PR
          WHERE PI.PEDIDO_ID = PR.PEDIDO_ID
          AND PR.TIPO_PROTOCOLO = '1'
          AND PR.PROTOCOLO_ID = :V_PROT_ID
          AND PI.NATUREZA_TITULO_ID = :V_TIPO_NATUREZA_ALIENACAO_VALOR
          INTO :V_QUANTIDADE;
          
          IF (:V_QUANTIDADE > 0) THEN
          BEGIN
            SELECT FIRST 1 PI.VALOR_DOCUMENTO FROM R_PEDIDO_ITEM PI, R_PROTOCOLO PR
            WHERE PI.PEDIDO_ID = PR.PEDIDO_ID
            AND PR.TIPO_PROTOCOLO = '1'
            AND PR.PROTOCOLO_ID = :V_PROT_ID
            AND PI.NATUREZA_TITULO_ID = :V_TIPO_NATUREZA_ALIENACAO_VALOR
            INTO :VALOR_ALIENACAO;          
          END
        END
        
        SITUACAO = '0'; -- 0.DOI Normal  1.Retificadora  3.Canceladora

        RETIFICACAO_ATO = '0'; -- 0.A operacao nao eh uma retificacao de ato anterior.
                             -- 1.A operacao eh uma retificacao de um ato anterior.

        FORMA_ALIENACAO = ''; --5.A vista  7.A prazo  9.Nao se Aplica

        ANDAMENTO = '2'; -- 0.Construcao Averbada  1.Em Construcao  2.Nao se Aplica

        TIPO_CLASSE = NULL;
        V_IMOVEL_TIPO_ID = NULL;
        AREA = NULL;
        ENDERECO = NULL;
        NUMERO_LOGRADOURO = NULL;
        COMPLEMENTO = NULL;
        BAIRRO = NULL;
        CEP = NULL;
        MUNICIPIO = NULL;
        INSCRICAO_IMOVEL = NULL;
        AREA_AVERBADA = NULL;
        ANDAMENTO = NULL;
        LOCALIZACAO = NULL;
        TIPO_IMOVEL = NULL;
        DESCRICAO_IMOVEL = NULL;
        V_NUMERO_CAR = NULL;

        SELECT FIRST 1 TIPO_CLASSE, IMOVEL_TIPO_ID,
               TRIM(SUBSTRING(AREA FROM 1 FOR 17)),
               TRIM(SUBSTRING(ENDERECO FROM 1 FOR 60)),
               TRIM(SUBSTRING(NUMERO_LOGRADOURO FROM 1 FOR 6)),
               TRIM(SUBSTRING(COMPLEMENTO_COMPLETO FROM 1 FOR 30)),
               TRIM(SUBSTRING(BAIRRO FROM 1 FOR 30)),
               TRIM(SUBSTRING(CAST(CAST(CEP AS INTEGER) AS VARCHAR(20)) FROM 1 FOR 8)),
               TRIM(SUBSTRING(MUNICIPIO FROM 1 FOR 30)),
               TRIM(SUBSTRING(INSCRICAO_IMOVEL FROM 1 FOR 15)),
               AREA_AVERBADA, TIPO_CONSTRUCAO, IMOVEL_ID, IMOVEL_UNIDADE_ID,
               TRIM(SUBSTRING(NUMERO_CAR FROM 1 FOR 15)),
               CNM_NUMERO, DESCRICAO_LOGRADOURO, CIB, CODIGO_INCRA, NOME_EDIFICACAO, novo
        FROM R_DADOS_IMOVEL(:TIPO_LIVRO,:V_MAT,:V_MAT,:NUMERO_LETRA, :V_CARTORIO)
        ORDER BY IMOVEL_UNIDADE_ID DESC
        INTO :TIPO_CLASSE, :V_IMOVEL_TIPO_ID,
             :AREA,
             :ENDERECO,
             :NUMERO_LOGRADOURO,
             :COMPLEMENTO,
             :BAIRRO,
             :CEP,
             :MUNICIPIO, 
             :INSCRICAO_IMOVEL,
             :AREA_AVERBADA,
             :ANDAMENTO,
             :IMOVEL_ID,
             :V_IMOVEL_UNIDADE_ID,
             :V_NUMERO_CAR,
             :CNM_NUMERO,
             :DESCRICAO_LOGRADOURO,
             :CIB, :CODIGO_INCRA, :DENOMINACAO, :v_novo;

        if (:v_novo = 'S') then
        begin
          select first 1 area, area_averbada from r_imovel_unidade
          where imovel_id = :imovel_id
          and coalesce(novo,'') <> 'S'
          into :area, :area_averbada;
        end

        if ((COALESCE(:inscricao_imovel,'') = '') AND (COALESCE(:v_numero_car,'') <> '')) then
        begin
          INSCRICAO_IMOVEL = :v_numero_car;
        end


        if (coalesce(:endereco,'') = '') then
        begin
          endereco = :complemento;
        end

        tipo_logradouro_sinter = '';
        if (coalesce(:V_IMOVEL_UNIDADE_ID,0) > 0) then
        begin
          select FIRST 1 tl.descricao from r_imovel_logradouro il, g_tb_tipologradouro tl
          where il.tb_tipologradouro_id = tl.tb_tipologradouro_id
          and il.imovel_unidade_id = :V_IMOVEL_UNIDADE_ID
          into :tipo_logradouro_sinter;
        end
        if (coalesce(:tipo_logradouro_sinter,'') = '') then
        begin
          select first 1 tl.descricao from r_imovel_unidade u,  g_tb_tipologradouro tl
          where u.tb_tipologradouro_id = tl.tb_tipologradouro_id
          and u.imovel_unidade_id = :V_IMOVEL_UNIDADE_ID
          order by u.imovel_unidade_id desc
          into :tipo_logradouro_sinter;
        end

        TIPO_IMOVEL_SINTER = '';
        UNIDADE_AREA_SINTER = '';
        IF (COALESCE(:TIPO_CLASSE,'') = 'L') THEN
        BEGIN
          TIPO_IMOVEL_SINTER = 'Terreno/Lote';
          UNIDADE_AREA_SINTER = 'm2 (metro quadrado)';
        END
        ELSE IF (COALESCE(:TIPO_CLASSE,'') = 'R') THEN
        BEGIN
          TIPO_IMOVEL_SINTER = 'Gleba';
          UNIDADE_AREA_SINTER = 'Ha (hectare)';
        END
        ELSE --SE FOR CONDOMINIO
        BEGIN
          UNIDADE_AREA_SINTER = 'm2 (metro quadrado)';
          if (coalesce(:V_IMOVEL_TIPO_ID,0) > 0) then
          begin
            select first 1 descricao from r_imovel_tipo
            where imovel_tipo_id = :V_IMOVEL_TIPO_ID
            into :v_tipo_imovel;
  
            if ((select position('Apto', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Apartamento';
            end
            else if ((select position('Apartamento', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Apartamento';
            end
            else if ((select position('Apart.', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Apartamento';
            end
            else if ((select position('Lote', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Lote';
            end
            else if ((select position('Sala', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Sala/Loja';
            end
            else if ((select position('Loja', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Sala/Loja';
            end
            else
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Garagem, Box, Outras';
            end
          end
          else
          begin
            TIPO_IMOVEL_SINTER = 'Terreno/Lote';
          end
        END

        IF ((:ANDAMENTO = '') OR (:ANDAMENTO IS NULL)) THEN
        BEGIN
          SELECT FIRST 1 TIPO_CONSTRUCAO
          FROM R_DADOS_IMOVEL(:TIPO_LIVRO,:V_MAT,:V_MAT,:NUMERO_LETRA, :V_CARTORIO)
          ORDER BY IMOVEL_UNIDADE_ID
          INTO :ANDAMENTO;    
        END       
        IF ((:ANDAMENTO = '') OR (:ANDAMENTO IS NULL)) THEN
        BEGIN
          ANDAMENTO = '2'; -- 0.Construcao Averbada  1.Em Construcao  2.Nao se Aplica
        END
                                             
        SELECT FIRST 1 TRIM(SUBSTRING(CAST(CAST(CODIGO_DOI AS INTEGER) AS VARCHAR(12)) FROM 1 FOR 3)), DESCRICAO
        FROM R_IMOVEL_TIPO
        WHERE IMOVEL_TIPO_ID = :V_IMOVEL_TIPO_ID
        INTO :TIPO_IMOVEL, :DESCRICAO_IMOVEL;

        IF (:TIPO_CLASSE = 'R') THEN
        BEGIN
          LOCALIZACAO = '3'; --Rural
          IF ((:TIPO_IMOVEL = '') OR (:TIPO_IMOVEL IS NULL)) THEN
          BEGIN
            TIPO_IMOVEL = '69';
          END
        END
        ELSE
        BEGIN
          LOCALIZACAO = '1'; --Urbano
          IF ((:TIPO_IMOVEL = '') OR (:TIPO_IMOVEL IS NULL)) THEN
          BEGIN
            TIPO_IMOVEL = '71';
          END        
        END     
        SUSPEND;
      END
    END
    ELSE
    BEGIN
      FOR SELECT DISTINCT
                 CAST(PR.NUMERO_ORDEM AS INTEGER) AS NUMERO_ORDEM,
                 PR.DATA AS DATA_PROTOCOLO,
                 PR.FOLHA_NUMERO||PR.FOLHA_FV AS FOLHA,
                 CAST(PN.NUMERO AS INTEGER) AS MATRICULA,
                 PN.NUMERO_LETRA,
                 PE.DATA_TITULO AS DATA_TITULO,
                 PI.VALOR_DOCUMENTO AS VALOR_ALIENACAO,
                 PI.VALOR_ITBI AS VALOR_ITBI,
                 PI.NATUREZA_TITULO_ID,
                 TRIM(SUBSTRING(CAST(CAST(COALESCE(PN.ATO_NUMERO,0) AS INTEGER) AS VARCHAR(12)) FROM 1 FOR 5)),
                 CASE PN.ATO_TIPO
                      WHEN 'A' THEN 'AV.'
                      WHEN 'R' THEN 'R.'
                      ELSE ''
                 END AS REGISTRO,
                 A.DATA,
                 PR.PROTOCOLO_ID,
                 PN.TIPO_REGISTRO,
                 PN.guia_numero,
                 PE.TB_TITULO_ID,
                 PN.ATO_TIPO
            FROM   R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A,
                   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN
            WHERE  PR.PEDIDO_ID = PE.PEDIDO_ID
            AND    PI.PEDIDO_ID = PE.PEDIDO_ID
            AND    PE.PEDIDO_ID = A.PEDIDO_ID
            AND    PN.PEDIDO_ITEM_ID = PI.PEDIDO_ITEM_ID
            AND    A.DATA BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)
                               AND CAST(:V_DATA_FIM AS TIMESTAMP) + 0.99999
            AND    A.TB_TIPO_ANDAMENTO_ID = :V_TIPO_ANDAMENTO_DOI
            AND    ((PN.TIPO_REGISTRO = 'M') OR (PN.TIPO_REGISTRO = 'T')) --Somente matriculas e trancricoes
            AND    (SELECT COUNT(*) FROM G_NATUREZA_TITULO N WHERE N.NATUREZA_TITULO_ID = PI.NATUREZA_TITULO_ID AND N.INFORMAR_DOI = 'S') > 0                        
--            AND    PN.ATO_TIPO = 'R' --Somente Registro
            AND    PR.TIPO_PROTOCOLO = '1' --Somente protocolos
            ORDER BY PR.DATA, PI.PEDIDO_ITEM_ID
            INTO   :NUMERO_PROTOCOLO,
                   :DATA_PROTOCOLO,
                   :FOLHA,
                   :MATRICULA,
                   :NUMERO_LETRA,
                   :DATA_TITULO,
                   :VALOR_ALIENACAO,
                   :VALOR_ITBI,        
                   :NATUREZA_TITULO_ID,
                   :NUMERO_ATO,
                   :REGISTRO,
                   :DATA_ANDAMENTO,
                   :V_PROT_ID,
                   :TIPO_LIVRO,
                   :TERMO_QUITACAO,
                   :TB_TITULO_ID,
                   :TIPO_ATO DO
      BEGIN
        SELECT first 1 CAST(CODIGO_DOI AS INTEGER), DESCRICAO, COALESCE(DESCRICAO_SINTER,''),
          COALESCE(CAST(CAST(CODIGO_NATUREZA_SEF AS INTEGER) AS VARCHAR(6)),'')
        FROM G_NATUREZA_TITULO
        WHERE NATUREZA_TITULO_ID = :NATUREZA_TITULO_ID
        INTO :TIPO_TRANSACAO, :DESCRICAO_NATUREZA, :DESCRICAO_NATUREZA_SINTER, :CODIGO_NATUREZA_SEF;

        if ((coalesce(:DESCRICAO_NATUREZA,'') <> '') and (coalesce(:DESCRICAO_NATUREZA_SINTER,'') = '')) then
        begin
          select count(*) from g_sinter_tabelas
          where tabela = 'TIPOATOREGISTRAL'
          and valor = ''''||:DESCRICAO_NATUREZA||''''
          into :v_count;

          if (:v_count > 0) then --existe no cadastro
          begin
            DESCRICAO_NATUREZA_SINTER = :DESCRICAO_NATUREZA;
          end
        end

        V_MAT = :MATRICULA;
        --IF (COALESCE(:TIPO_LIVRO,'') = 'T') THEN
        --BEGIN
          --MATRICULA = 'T'||:MATRICULA;
        --END
      
        IF (:REGISTRO <> '') THEN
        BEGIN
          REGISTRO = :REGISTRO || :NUMERO_ATO;
        END

        IF ((:VALOR_ITBI = 0) OR (:VALOR_ITBI IS NULL)) THEN
        BEGIN
          VALOR_ITBI = :VALOR_ALIENACAO;
        END
        
        IF (:V_TIPO_NATUREZA_ALIENACAO_VALOR <> '') THEN
        BEGIN
          SELECT COUNT(*) FROM R_PEDIDO_ITEM PI, R_PROTOCOLO PR
          WHERE PI.PEDIDO_ID = PR.PEDIDO_ID
          AND PR.TIPO_PROTOCOLO = '1'
          AND PR.PROTOCOLO_ID = :V_PROT_ID
          AND PI.NATUREZA_TITULO_ID = :V_TIPO_NATUREZA_ALIENACAO_VALOR
          INTO :V_QUANTIDADE;
          
          IF (:V_QUANTIDADE > 0) THEN
          BEGIN
            SELECT FIRST 1 PI.VALOR_DOCUMENTO FROM R_PEDIDO_ITEM PI, R_PROTOCOLO PR
            WHERE PI.PEDIDO_ID = PR.PEDIDO_ID
            AND PR.TIPO_PROTOCOLO = '1'
            AND PR.PROTOCOLO_ID = :V_PROT_ID
            AND PI.NATUREZA_TITULO_ID = :V_TIPO_NATUREZA_ALIENACAO_VALOR
            INTO :VALOR_ALIENACAO;          
          END
        END
        
        SITUACAO = '0'; -- 0.DOI Normal  1.Retificadora  3.Canceladora

        RETIFICACAO_ATO = '0'; -- 0.A operacao nao eh uma retificacao de ato anterior.
                             -- 1.A operacao eh uma retificacao de um ato anterior.

        FORMA_ALIENACAO = ''; --5.A vista  7.A prazo  9.Nao se Aplica

        ANDAMENTO = '2'; -- 0.Construcao Averbada  1.Em Construcao  2.Nao se Aplica

        TIPO_CLASSE = NULL;
        V_IMOVEL_TIPO_ID = NULL;
        AREA = NULL;
        ENDERECO = NULL;
        NUMERO_LOGRADOURO = NULL;
        COMPLEMENTO = NULL;
        BAIRRO = NULL;
        CEP = NULL;
        MUNICIPIO = NULL;
        INSCRICAO_IMOVEL = NULL;
        AREA_AVERBADA = NULL;
        ANDAMENTO = NULL;
        LOCALIZACAO = NULL;
        TIPO_IMOVEL = NULL;
        DESCRICAO_IMOVEL = NULL;
        V_NUMERO_CAR = NULL;

        SELECT FIRST 1 TIPO_CLASSE, IMOVEL_TIPO_ID,
               TRIM(SUBSTRING(AREA FROM 1 FOR 17)),
               TRIM(SUBSTRING(ENDERECO FROM 1 FOR 60)),
               TRIM(SUBSTRING(NUMERO_LOGRADOURO FROM 1 FOR 6)),
               TRIM(SUBSTRING(COMPLEMENTO_COMPLETO FROM 1 FOR 30)),
               TRIM(SUBSTRING(BAIRRO FROM 1 FOR 30)),
               TRIM(SUBSTRING(CAST(CAST(CEP AS INTEGER) AS VARCHAR(20)) FROM 1 FOR 8)),
               TRIM(SUBSTRING(MUNICIPIO FROM 1 FOR 30)),
               TRIM(SUBSTRING(INSCRICAO_IMOVEL FROM 1 FOR 15)),
               AREA_AVERBADA, TIPO_CONSTRUCAO, IMOVEL_ID, IMOVEL_UNIDADE_ID,
               TRIM(SUBSTRING(NUMERO_CAR FROM 1 FOR 15)),
               CNM_NUMERO, DESCRICAO_LOGRADOURO, CIB, CODIGO_INCRA, NOME_EDIFICACAO, novo
        FROM R_DADOS_IMOVEL(:TIPO_LIVRO,:V_MAT,:V_MAT,:NUMERO_LETRA, :V_CARTORIO)
        ORDER BY IMOVEL_UNIDADE_ID DESC
        INTO :TIPO_CLASSE, :V_IMOVEL_TIPO_ID,
             :AREA,
             :ENDERECO,
             :NUMERO_LOGRADOURO,
             :COMPLEMENTO,
             :BAIRRO,
             :CEP,
             :MUNICIPIO, 
             :INSCRICAO_IMOVEL,
             :AREA_AVERBADA,
             :ANDAMENTO,
             :IMOVEL_ID,
             :V_IMOVEL_UNIDADE_ID,
             :V_NUMERO_CAR,
             :CNM_NUMERO,
             :DESCRICAO_LOGRADOURO,
             :CIB, :CODIGO_INCRA, :DENOMINACAO, :v_novo;

        if (:v_novo = 'S') then
        begin
          select first 1 area, area_averbada from r_imovel_unidade
          where imovel_id = :imovel_id
          and coalesce(novo,'') <> 'S'
          into :area, :area_averbada;
        end

        if ((COALESCE(:inscricao_imovel,'') = '') AND (COALESCE(:v_numero_car,'') <> '')) then
        begin
          INSCRICAO_IMOVEL = :v_numero_car;
        end

        if (coalesce(:endereco,'') = '') then
        begin
          endereco = :complemento;
        end

        tipo_logradouro_sinter = '';
        if (coalesce(:V_IMOVEL_UNIDADE_ID,0) > 0) then
        begin
          select first 1 tl.descricao from r_imovel_logradouro il, g_tb_tipologradouro tl
          where il.tb_tipologradouro_id = tl.tb_tipologradouro_id
          and il.imovel_unidade_id = :V_IMOVEL_UNIDADE_ID
          into :tipo_logradouro_sinter;
        end
        if (coalesce(:tipo_logradouro_sinter,'') = '') then
        begin
          select first 1 tl.descricao from r_imovel_unidade u,  g_tb_tipologradouro tl
          where u.tb_tipologradouro_id = tl.tb_tipologradouro_id
          and u.imovel_unidade_id = :V_IMOVEL_UNIDADE_ID
          order by u.imovel_unidade_id desc
          into :tipo_logradouro_sinter;
        end

        TIPO_IMOVEL_SINTER = '';
        UNIDADE_AREA_SINTER = '';
        IF (COALESCE(:TIPO_CLASSE,'') = 'L') THEN
        BEGIN
          TIPO_IMOVEL_SINTER = 'Terreno/Lote';
          UNIDADE_AREA_SINTER = 'm2 (metro quadrado)';
        END
        ELSE IF (COALESCE(:TIPO_CLASSE,'') = 'R') THEN
        BEGIN
          TIPO_IMOVEL_SINTER = 'Gleba';
          UNIDADE_AREA_SINTER = 'Ha (hectare)';
        END
        ELSE --SE FOR CONDOMINIO
        BEGIN
          UNIDADE_AREA_SINTER = 'm2 (metro quadrado)';
          if (coalesce(:V_IMOVEL_TIPO_ID,0) > 0) then
          begin
            select first 1 descricao from r_imovel_tipo
            where imovel_tipo_id = :V_IMOVEL_TIPO_ID
            into :v_tipo_imovel;
  
            if ((select position('Apto', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Apartamento';
            end
            else if ((select position('Apartamento', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Apartamento';
            end
            else if ((select position('Apart.', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Apartamento';
            end
            else if ((select position('Lote', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Lote';
            end
            else if ((select position('Sala', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Sala/Loja';
            end
            else if ((select position('Loja', :v_tipo_imovel) from rdb$database) > 0) then
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Sala/Loja';
            end
            else
            begin
              TIPO_IMOVEL_SINTER = 'Unidade Autônoma - Garagem, Box, Outras';
            end
          end
          else
          begin
            TIPO_IMOVEL_SINTER = 'Terreno/Lote';
          end
        END

        IF ((:ANDAMENTO = '') OR (:ANDAMENTO IS NULL)) THEN
        BEGIN
          SELECT FIRST 1 TIPO_CONSTRUCAO
          FROM R_DADOS_IMOVEL(:TIPO_LIVRO,:V_MAT,:V_MAT,:NUMERO_LETRA, :V_CARTORIO)
          ORDER BY IMOVEL_UNIDADE_ID
          INTO :ANDAMENTO;             
        END
        IF ((:ANDAMENTO = '') OR (:ANDAMENTO IS NULL)) THEN
        BEGIN
          ANDAMENTO = '2'; -- 0.Construcao Averbada  1.Em Construcao  2.Nao se Aplica
        END
                                             
        SELECT FIRST 1 TRIM(SUBSTRING(CAST(CAST(CODIGO_DOI AS INTEGER) AS VARCHAR(12)) FROM 1 FOR 3)), DESCRICAO
        FROM R_IMOVEL_TIPO
        WHERE IMOVEL_TIPO_ID = :V_IMOVEL_TIPO_ID
        INTO :TIPO_IMOVEL, :DESCRICAO_IMOVEL;

        IF (:TIPO_CLASSE = 'R') THEN
        BEGIN
          LOCALIZACAO = '3'; --Rural
          IF ((:TIPO_IMOVEL = '') OR (:TIPO_IMOVEL IS NULL)) THEN
          BEGIN
            TIPO_IMOVEL = '69';
          END
        END
        ELSE
        BEGIN
          LOCALIZACAO = '1'; --Urbano
          IF ((:TIPO_IMOVEL = '') OR (:TIPO_IMOVEL IS NULL)) THEN
          BEGIN
            TIPO_IMOVEL = '71';
          END        
        END     
        SUSPEND;
      END    
    END
  END
END ^

ALTER PROCEDURE R_MONTAR_DOI_ENVOLVIDOS (V_MATRICULA VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUMERO_LETRA VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_ATO VARCHAR(10) CHARACTER SET ISO8859_1,
V_DATA_TRANSFERENCIA VARCHAR(20) CHARACTER SET ISO8859_1,
V_CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (PARTICIPACAO NUMERIC(12, 2),
TIPO_ATO VARCHAR(3) CHARACTER SET ISO8859_1,
ADQUIRENTE_ALIENANTE VARCHAR(3) CHARACTER SET ISO8859_1,
PESSOA_VINCULO_ID NUMERIC(12, 2),
CPF_CNPJ VARCHAR(15) CHARACTER SET ISO8859_1,
DATA_TRANSFERENCIA TIMESTAMP,
TB_TIPO_VINCULO_ID NUMERIC(12, 2),
DESCRICAO_VINCULO VARCHAR(120) CHARACTER SET ISO8859_1,
DESCRICAO_VINCULO_SINTER VARCHAR(120) CHARACTER SET ISO8859_1,
CPF_PROCURADOR_DOI VARCHAR(30) CHARACTER SET ISO8859_1,
CPF_CONJUGE VARCHAR(30) CHARACTER SET ISO8859_1,
NACIONALIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
ESTADO_CIVIL VARCHAR(60) CHARACTER SET ISO8859_1,
TIPO_ESTADO_CIVIL INTEGER,
CPF_INVENTARIANTE VARCHAR(30) CHARACTER SET ISO8859_1,
CONJUGE_PARTICIPA VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_IMOVEL_ID INTEGER;
  DECLARE VARIABLE V_NUMERO_ATO_TEMP INTEGER;
  DECLARE VARIABLE V_MAT VARCHAR(15);
  DECLARE VARIABLE V_TIPO VARCHAR(3);
  declare variable v_count integer;
BEGIN
  IF (SUBSTRING(:V_MATRICULA FROM 1 FOR 1) = 'T') THEN
  BEGIN
    V_TIPO = 'T';
    V_MAT = TRIM(SUBSTRING(:V_MATRICULA FROM 2 FOR 14));
  END
  ELSE
  BEGIN
    V_TIPO = 'M';
    V_MAT = :V_MATRICULA;
  END

  IF ((:V_CARTORIO IS NULL) OR (:V_CARTORIO = '')) THEN
  BEGIN
    IF (:V_TIPO = 'T') THEN
    BEGIN
      IF (TRIM(:V_NUMERO_LETRA) = '') THEN
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA IS NULL OR NUMERO_LETRA = '' OR NUMERO_LETRA = '#')
        AND TIPO_REGISTRO = 'T'
        INTO :V_IMOVEL_ID;                       
      END
      ELSE
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA = :V_NUMERO_LETRA) 
        AND TIPO_REGISTRO = 'T'
        INTO :V_IMOVEL_ID;                       
      END    
    END
    ELSE
    BEGIN    
      IF (TRIM(:V_NUMERO_LETRA) = '') THEN
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA IS NULL OR NUMERO_LETRA = '' OR NUMERO_LETRA = '#')
        AND TIPO_REGISTRO = 'M'
        INTO :V_IMOVEL_ID;                       
      END
      ELSE
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA = :V_NUMERO_LETRA) 
        AND TIPO_REGISTRO = 'M'
        INTO :V_IMOVEL_ID;                       
      END
    END
  END
  ELSE
  BEGIN
    IF (:V_TIPO = 'T') THEN
    BEGIN  
      IF (TRIM(:V_NUMERO_LETRA) = '') THEN
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA IS NULL OR NUMERO_LETRA = '' OR NUMERO_LETRA = '#')
        AND TIPO_REGISTRO = 'T'
        AND CARTORIO = :V_CARTORIO
        INTO :V_IMOVEL_ID;                       
      END
      ELSE
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA = :V_NUMERO_LETRA) 
        AND TIPO_REGISTRO = 'T'
        AND CARTORIO = :V_CARTORIO
        INTO :V_IMOVEL_ID;                       
      END  
    END
    ELSE
    BEGIN
      IF (TRIM(:V_NUMERO_LETRA) = '') THEN
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA IS NULL OR NUMERO_LETRA = '' OR NUMERO_LETRA = '#')
        AND TIPO_REGISTRO = 'M'
        AND CARTORIO = :V_CARTORIO
        INTO :V_IMOVEL_ID;                       
      END
      ELSE
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA = :V_NUMERO_LETRA) 
        AND TIPO_REGISTRO = 'M'
        AND CARTORIO = :V_CARTORIO
        INTO :V_IMOVEL_ID;                       
      END      
    END
  END
  
  
  V_NUMERO_ATO_TEMP = CAST(:V_NUMERO_ATO AS INTEGER);
                                                      
  --Buscar os adquirentes
  FOR SELECT V.AREA_PERCENT, V.TIPO_ATO, '1', V.CPF_CNPJ, V.PESSOA_VINCULO_ID, V.TB_TIPO_VINCULO_ID, V.CPF_PROCURADOR_DOI,
            (select coalesce(cpf_cnpj,'') from r_pessoa where pessoa_id = V.pessoa_conjuge_id), V.NACIONALIDADE,
            (select coalesce(descricao,'') from g_tb_estadocivil where tb_estadocivil_id = v.tb_estadocivil_id),
            (select coalesce(tipo,0) from g_tb_estadocivil where tb_estadocivil_id = v.tb_estadocivil_id),
            V.CPF_INVENTARIANTE, V.CONJUGE_PARTICIPA
      FROM R_PESSOA_VINCULO V
      WHERE  V.IMOVEL_ID = :V_IMOVEL_ID
      AND    V.NUMERO_ATO = :V_NUMERO_ATO_TEMP
      AND    V.DATA_TRANSFERENCIA IS NULL
      ORDER BY V.PESSOA_VINCULO_ID
      INTO :PARTICIPACAO, --Participacao em %
           :TIPO_ATO, --Tipo do Ato A ou R    
           :ADQUIRENTE_ALIENANTE, --Aqui eh adquirente
           :CPF_CNPJ, --CPF OU CNPJ do Adquirente
           :PESSOA_VINCULO_ID,
           :TB_TIPO_VINCULO_ID,
           :CPF_PROCURADOR_DOI,
           :CPF_CONJUGE,
           :NACIONALIDADE,
           :ESTADO_CIVIL,
           :TIPO_ESTADO_CIVIL,
           :CPF_INVENTARIANTE,
           :CONJUGE_PARTICIPA DO
  BEGIN
    DATA_TRANSFERENCIA = null;

    SELECT descricao, coalesce(descricao_sinter,'') FROM R_TB_TIPO_VINCULO
    WHERE TB_TIPO_VINCULO_ID = :TB_TIPO_VINCULO_ID
    INTO :DESCRICAO_VINCULO, :DESCRICAO_VINCULO_SINTER;

    if ((coalesce(:DESCRICAO_VINCULO,'') <> '') and (coalesce(:DESCRICAO_VINCULO_SINTER,'') = '')) then
    begin
      select count(*) from g_sinter_tabelas
      where tabela = 'TIPORELACAOJURIDICARI'
      and valor = ''''||:DESCRICAO_VINCULO||''''
      into :v_count;

      if (:v_count > 0) then --existe no cadastro
      begin
        DESCRICAO_VINCULO_SINTER = :DESCRICAO_VINCULO;
      end
    end

    SUSPEND;
  END
  
  IF ((:V_DATA_TRANSFERENCIA = '') OR (:V_DATA_TRANSFERENCIA = '''')) THEN
  BEGIN
    V_NUMERO_ATO_TEMP = :V_NUMERO_ATO_TEMP - 1;
    
    IF ((:V_NUMERO_ATO_TEMP > 0) OR (:V_NUMERO_ATO_TEMP = 0)) THEN
    BEGIN 
      --Buscar os Alientantes
      FOR SELECT V.AREA_PERCENT, V.TIPO_ATO, '2', V.CPF_CNPJ, V.PESSOA_VINCULO_ID, V.DATA_TRANSFERENCIA, V.TB_TIPO_VINCULO_ID, V.CPF_PROCURADOR_DOI,
                (select coalesce(cpf_cnpj,'') from r_pessoa where pessoa_id = V.pessoa_conjuge_id), V.NACIONALIDADE,
                (select coalesce(descricao,'') from g_tb_estadocivil where tb_estadocivil_id = v.tb_estadocivil_id),
                (select coalesce(tipo,0) from g_tb_estadocivil where tb_estadocivil_id = v.tb_estadocivil_id),
                V.CPF_INVENTARIANTE, V.CONJUGE_PARTICIPA
          FROM R_PESSOA_VINCULO V
          WHERE  V.IMOVEL_ID = :V_IMOVEL_ID
          AND    V.NUMERO_ATO = :V_NUMERO_ATO_TEMP
          ORDER BY V.PESSOA_VINCULO_ID
          INTO :PARTICIPACAO, --Participacao em %
               :TIPO_ATO, --Tipo do Ato A ou R    
               :ADQUIRENTE_ALIENANTE, --Aqui eh alienante
               :CPF_CNPJ, --CPF OU CNPJ do Adquirente
               :PESSOA_VINCULO_ID,
               :DATA_TRANSFERENCIA,
               :TB_TIPO_VINCULO_ID,
               :CPF_PROCURADOR_DOI,
               :CPF_CONJUGE,
               :NACIONALIDADE,
               :ESTADO_CIVIL,
               :TIPO_ESTADO_CIVIL,
               :CPF_INVENTARIANTE,
               :CONJUGE_PARTICIPA DO
      BEGIN                                      
        IF (:TIPO_ATO <> 'A') THEN
        BEGIN
          SELECT descricao, coalesce(descricao_sinter,'') FROM R_TB_TIPO_VINCULO
          WHERE TB_TIPO_VINCULO_ID = :TB_TIPO_VINCULO_ID
          INTO :DESCRICAO_VINCULO, :DESCRICAO_VINCULO_SINTER;

          if ((coalesce(:DESCRICAO_VINCULO,'') <> '') and (coalesce(:DESCRICAO_VINCULO_SINTER,'') = '')) then
          begin
            select count(*) from g_sinter_tabelas
            where tabela = 'TIPORELACAOJURIDICARI'
            and valor = ''''||:DESCRICAO_VINCULO||''''
            into :v_count;

            if (:v_count > 0) then --existe no cadastro
            begin
              DESCRICAO_VINCULO_SINTER = :DESCRICAO_VINCULO;
            end
          end

          SUSPEND;
        END
      END
    END
  END
  ELSE
  BEGIN
    --Buscar os Alientantes
    FOR SELECT V.AREA_PERCENT, V.TIPO_ATO, '2', V.CPF_CNPJ, V.PESSOA_VINCULO_ID, V.DATA_TRANSFERENCIA, V.TB_TIPO_VINCULO_ID, V.CPF_PROCURADOR_DOI,
        (select coalesce(cpf_cnpj,'') from r_pessoa where pessoa_id = V.pessoa_conjuge_id), V.NACIONALIDADE,
        (select coalesce(descricao,'') from g_tb_estadocivil where tb_estadocivil_id = v.tb_estadocivil_id),
        (select coalesce(tipo,0) from g_tb_estadocivil where tb_estadocivil_id = v.tb_estadocivil_id),
        V.CPF_INVENTARIANTE, V.CONJUGE_PARTICIPA
        FROM R_PESSOA_VINCULO V
        WHERE  V.IMOVEL_ID = :V_IMOVEL_ID
        AND    V.DATA_TRANSFERENCIA BETWEEN CAST(:V_DATA_TRANSFERENCIA AS TIMESTAMP)
                                      AND CAST(:V_DATA_TRANSFERENCIA AS TIMESTAMP) + 0.9999
        ORDER BY V.PESSOA_VINCULO_ID
        INTO :PARTICIPACAO, --Participacao em %
             :TIPO_ATO, --Tipo do Ato A ou R    
             :ADQUIRENTE_ALIENANTE, --Aqui eh alienante
             :CPF_CNPJ, --CPF OU CNPJ do Adquirente
             :PESSOA_VINCULO_ID,
             :DATA_TRANSFERENCIA,
             :TB_TIPO_VINCULO_ID,
             :CPF_PROCURADOR_DOI,
             :CPF_CONJUGE,
             :NACIONALIDADE,
             :ESTADO_CIVIL,
             :TIPO_ESTADO_CIVIL,
             :CPF_INVENTARIANTE,
             :CONJUGE_PARTICIPA DO
    BEGIN
      SELECT descricao, coalesce(descricao_sinter,'') FROM R_TB_TIPO_VINCULO
      WHERE TB_TIPO_VINCULO_ID = :TB_TIPO_VINCULO_ID
      INTO :DESCRICAO_VINCULO, :DESCRICAO_VINCULO_SINTER;

      if ((coalesce(:DESCRICAO_VINCULO,'') <> '') and (coalesce(:DESCRICAO_VINCULO_SINTER,'') = '')) then
      begin
        select count(*) from g_sinter_tabelas
        where tabela = 'TIPORELACAOJURIDICARI'
        and valor = ''''||:DESCRICAO_VINCULO||''''
        into :v_count;

        if (:v_count > 0) then --existe no cadastro
        begin
          DESCRICAO_VINCULO_SINTER = :DESCRICAO_VINCULO;
        end
      end

      SUSPEND;
    END
  END
END ^

ALTER PROCEDURE R_MONTAR_ENVOLVIDOS_COAF (V_MATRICULA VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUMERO_LETRA VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_ATO VARCHAR(10) CHARACTER SET ISO8859_1,
V_DATA_TRANSFERENCIA VARCHAR(20) CHARACTER SET ISO8859_1,
V_CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1,
PROTOCOLO_ID NUMERIC(10, 2))
RETURNS (PARTICIPACAO NUMERIC(12, 2),
TIPO_ATO VARCHAR(3) CHARACTER SET ISO8859_1,
ADQUIRENTE_ALIENANTE VARCHAR(3) CHARACTER SET ISO8859_1,
PESSOA_VINCULO_ID NUMERIC(12, 2),
CPF_CNPJ VARCHAR(15) CHARACTER SET ISO8859_1,
DATA_TRANSFERENCIA TIMESTAMP,
TB_TIPO_VINCULO_ID NUMERIC(12, 2),
DESCRICAO_VINCULO VARCHAR(120) CHARACTER SET ISO8859_1,
DESCRICAO_VINCULO_SINTER VARCHAR(120) CHARACTER SET ISO8859_1,
CPF_PROCURADOR_DOI VARCHAR(30) CHARACTER SET ISO8859_1,
NOME VARCHAR_120)
AS 
declare variable V_IMOVEL_ID integer;
declare variable V_NUMERO_ATO_TEMP integer;
declare variable V_MAT varchar(15);
declare variable V_TIPO varchar(3);
declare variable V_COUNT integer;
BEGIN
  IF (SUBSTRING(:V_MATRICULA FROM 1 FOR 1) = 'T') THEN
  BEGIN
    V_TIPO = 'T';
    V_MAT = TRIM(SUBSTRING(:V_MATRICULA FROM 2 FOR 14));
  END
  ELSE
  BEGIN
    V_TIPO = 'M';
    V_MAT = :V_MATRICULA;
  END

  IF ((:V_CARTORIO IS NULL) OR (:V_CARTORIO = '')) THEN
  BEGIN
    IF (:V_TIPO = 'T') THEN
    BEGIN
      IF (TRIM(:V_NUMERO_LETRA) = '') THEN
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA IS NULL OR NUMERO_LETRA = '' OR NUMERO_LETRA = '#')
        AND TIPO_REGISTRO = 'T'
        INTO :V_IMOVEL_ID;                       
      END
      ELSE
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA = :V_NUMERO_LETRA) 
        AND TIPO_REGISTRO = 'T'
        INTO :V_IMOVEL_ID;                       
      END    
    END
    ELSE
    BEGIN    
      IF (TRIM(:V_NUMERO_LETRA) = '') THEN
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA IS NULL OR NUMERO_LETRA = '' OR NUMERO_LETRA = '#')
        AND TIPO_REGISTRO = 'M'
        INTO :V_IMOVEL_ID;                       
      END
      ELSE
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA = :V_NUMERO_LETRA) 
        AND TIPO_REGISTRO = 'M'
        INTO :V_IMOVEL_ID;                       
      END
    END
  END
  ELSE
  BEGIN
    IF (:V_TIPO = 'T') THEN
    BEGIN  
      IF (TRIM(:V_NUMERO_LETRA) = '') THEN
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA IS NULL OR NUMERO_LETRA = '' OR NUMERO_LETRA = '#')
        AND TIPO_REGISTRO = 'T'
        AND CARTORIO = :V_CARTORIO
        INTO :V_IMOVEL_ID;                       
      END
      ELSE
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA = :V_NUMERO_LETRA) 
        AND TIPO_REGISTRO = 'T'
        AND CARTORIO = :V_CARTORIO
        INTO :V_IMOVEL_ID;                       
      END  
    END
    ELSE
    BEGIN
      IF (TRIM(:V_NUMERO_LETRA) = '') THEN
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA IS NULL OR NUMERO_LETRA = '' OR NUMERO_LETRA = '#')
        AND TIPO_REGISTRO = 'M'
        AND CARTORIO = :V_CARTORIO
        INTO :V_IMOVEL_ID;                       
      END
      ELSE
      BEGIN
        SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
        WHERE NUMERO = :V_MAT
        AND (NUMERO_LETRA = :V_NUMERO_LETRA) 
        AND TIPO_REGISTRO = 'M'
        AND CARTORIO = :V_CARTORIO
        INTO :V_IMOVEL_ID;                       
      END      
    END
  END
  
  
  V_NUMERO_ATO_TEMP = CAST(:V_NUMERO_ATO AS INTEGER);
                                                      
  --Buscar os adquirentes
  FOR SELECT AREA_PERCENT, TIPO_ATO, '1', CPF_CNPJ, PESSOA_VINCULO_ID, TB_TIPO_VINCULO_ID,
     CPF_PROCURADOR_DOI, NOME
      FROM R_PESSOA_VINCULO
      WHERE  IMOVEL_ID = :V_IMOVEL_ID
      AND    NUMERO_ATO = :V_NUMERO_ATO_TEMP
      AND    DATA_TRANSFERENCIA IS NULL
      ORDER BY PESSOA_VINCULO_ID
      INTO :PARTICIPACAO, --Participacao em %
           :TIPO_ATO, --Tipo do Ato A ou R    
           :ADQUIRENTE_ALIENANTE, --Aqui eh adquirente
           :CPF_CNPJ, --CPF OU CNPJ do Adquirente
           :PESSOA_VINCULO_ID,
           :TB_TIPO_VINCULO_ID,
           :CPF_PROCURADOR_DOI,
           :NOME  DO
  BEGIN
    DATA_TRANSFERENCIA = null;

    SELECT descricao, coalesce(descricao_sinter,'') FROM R_TB_TIPO_VINCULO
    WHERE TB_TIPO_VINCULO_ID = :TB_TIPO_VINCULO_ID
    INTO :DESCRICAO_VINCULO, :DESCRICAO_VINCULO_SINTER;

    if ((coalesce(:DESCRICAO_VINCULO,'') <> '') and (coalesce(:DESCRICAO_VINCULO_SINTER,'') = '')) then
    begin
      select count(*) from g_sinter_tabelas
      where tabela = 'TIPORELACAOJURIDICARI'
      and valor = ''''||:DESCRICAO_VINCULO||''''
      into :v_count;

      if (:v_count > 0) then --existe no cadastro
      begin
        DESCRICAO_VINCULO_SINTER = :DESCRICAO_VINCULO;
      end
    end

    SUSPEND;
  END
  
  IF ((:V_DATA_TRANSFERENCIA = '') OR (:V_DATA_TRANSFERENCIA = '''')) THEN
  BEGIN
    V_NUMERO_ATO_TEMP = :V_NUMERO_ATO_TEMP - 1;
    
    IF ((:V_NUMERO_ATO_TEMP > 0) OR (:V_NUMERO_ATO_TEMP = 0)) THEN
    BEGIN 
      --Buscar os Alientantes
      FOR SELECT AREA_PERCENT, TIPO_ATO, '2', CPF_CNPJ, PESSOA_VINCULO_ID, DATA_TRANSFERENCIA, TB_TIPO_VINCULO_ID, CPF_PROCURADOR_DOI
        , nome
          FROM R_PESSOA_VINCULO
          WHERE  IMOVEL_ID = :V_IMOVEL_ID
          AND    NUMERO_ATO = :V_NUMERO_ATO_TEMP
          ORDER BY PESSOA_VINCULO_ID
          INTO :PARTICIPACAO, --Participacao em %
               :TIPO_ATO, --Tipo do Ato A ou R    
               :ADQUIRENTE_ALIENANTE, --Aqui eh alienante
               :CPF_CNPJ, --CPF OU CNPJ do Adquirente
               :PESSOA_VINCULO_ID,
               :DATA_TRANSFERENCIA,
               :TB_TIPO_VINCULO_ID,
               :CPF_PROCURADOR_DOI,
               :nome DO
      BEGIN                                      
        IF (:TIPO_ATO <> 'A') THEN
        BEGIN
          SELECT descricao, coalesce(descricao_sinter,'') FROM R_TB_TIPO_VINCULO
          WHERE TB_TIPO_VINCULO_ID = :TB_TIPO_VINCULO_ID
          INTO :DESCRICAO_VINCULO, :DESCRICAO_VINCULO_SINTER;

          if ((coalesce(:DESCRICAO_VINCULO,'') <> '') and (coalesce(:DESCRICAO_VINCULO_SINTER,'') = '')) then
          begin
            select count(*) from g_sinter_tabelas
            where tabela = 'TIPORELACAOJURIDICARI'
            and valor = ''''||:DESCRICAO_VINCULO||''''
            into :v_count;

            if (:v_count > 0) then --existe no cadastro
            begin
              DESCRICAO_VINCULO_SINTER = :DESCRICAO_VINCULO;
            end
          end

          SUSPEND;
        END
      END
    END
  END
  ELSE
  BEGIN
    --Buscar os Alientantes
    FOR SELECT AREA_PERCENT, TIPO_ATO, '2', CPF_CNPJ, PESSOA_VINCULO_ID, DATA_TRANSFERENCIA, TB_TIPO_VINCULO_ID, CPF_PROCURADOR_DOI
        FROM R_PESSOA_VINCULO
        WHERE  IMOVEL_ID = :V_IMOVEL_ID
        AND    DATA_TRANSFERENCIA BETWEEN CAST(:V_DATA_TRANSFERENCIA AS TIMESTAMP)
                                      AND CAST(:V_DATA_TRANSFERENCIA AS TIMESTAMP) + 0.9999
        ORDER BY PESSOA_VINCULO_ID
        INTO :PARTICIPACAO, --Participacao em %
             :TIPO_ATO, --Tipo do Ato A ou R    
             :ADQUIRENTE_ALIENANTE, --Aqui eh alienante
             :CPF_CNPJ, --CPF OU CNPJ do Adquirente
             :PESSOA_VINCULO_ID,
             :DATA_TRANSFERENCIA,
             :TB_TIPO_VINCULO_ID,
             :CPF_PROCURADOR_DOI DO
    BEGIN
      SELECT descricao, coalesce(descricao_sinter,'') FROM R_TB_TIPO_VINCULO
      WHERE TB_TIPO_VINCULO_ID = :TB_TIPO_VINCULO_ID
      INTO :DESCRICAO_VINCULO, :DESCRICAO_VINCULO_SINTER;

      if ((coalesce(:DESCRICAO_VINCULO,'') <> '') and (coalesce(:DESCRICAO_VINCULO_SINTER,'') = '')) then
      begin
        select count(*) from g_sinter_tabelas
        where tabela = 'TIPORELACAOJURIDICARI'
        and valor = ''''||:DESCRICAO_VINCULO||''''
        into :v_count;

        if (:v_count > 0) then --existe no cadastro
        begin
          DESCRICAO_VINCULO_SINTER = :DESCRICAO_VINCULO;
        end
      end

      SUSPEND;
    END
  END
   --Buscar apresentante do protocolo
  FOR SELECT 0, 'C', '3', RPR.apresentante_cpf_cnpj
     , RPR.apresentante_nome NOME
      FROM R_PEDIDO RPR, r_protocolo rp
      WHERE  rpr.pedido_id = rp.pedido_id
      AND    rp.tipo_protocolo = '1'
      AND    rp.protocolo_id = :protocolo_id
      INTO :PARTICIPACAO, --Participacao em %
           :TIPO_ATO, --Tipo do Ato A ou R    
           :ADQUIRENTE_ALIENANTE, --Aqui eh adquirente
           :CPF_CNPJ, --CPF OU CNPJ do Adquirente
           :NOME  DO
  BEGIN
    DATA_TRANSFERENCIA = null;

    DESCRICAO_VINCULO = 'Apresentante';

    SUSPEND;
  END
END ^

ALTER PROCEDURE R_MONTAR_PLANILHA (V_DATA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_DEVOLUCAO_75 VARCHAR(10) CHARACTER SET ISO8859_1,
V_DEVOLUCAO_100 VARCHAR(10) CHARACTER SET ISO8859_1,
V_DEVOLUCAO_TJDFT VARCHAR(10) CHARACTER SET ISO8859_1,
V_TJDFT VARCHAR(10) CHARACTER SET ISO8859_1,
V_INDICE_ATUALIZACAO VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_PERIODO_INI TIMESTAMP,
V_DATA_PERIODO_FIM TIMESTAMP)
RETURNS (DATA_CANCELAMENTO TIMESTAMP,
NUMERO_ORDEM NUMERIC(18, 2),
NOVO_NUMERO_ORDEM NUMERIC(18, 2),
TOTAL_PROTOCOLO NUMERIC(18, 4),
CREDITOS NUMERIC(18, 4),
DEBITOS NUMERIC(18, 4),
VALOR_ATUAL NUMERIC(18, 4),
VALOR_ATUAL_75 NUMERIC(18, 4),
VALOR_DEVOLVIDO NUMERIC(18, 4),
TIPO_DEVOLUCAO VARCHAR(1) CHARACTER SET ISO8859_1,
DATA_DEVOLUCAO TIMESTAMP,
RECEITA_LIQUIDA NUMERIC(18, 4))
AS 
DECLARE VARIABLE V_PEDIDO_ID INTEGER;
DECLARE VARIABLE V_TIPO_PROTOCOLO VARCHAR(4);
DECLARE VARIABLE V_PROTOCOLO_ID INTEGER;
DECLARE VARIABLE V_DATA_PROTOCOLO TIMESTAMP;
DECLARE VARIABLE V_DEVOLUCAO VARCHAR(15);
DECLARE VARIABLE V_DATA_DEVOLUCAO_TEMP TIMESTAMP;
DECLARE VARIABLE V_CREDITOS NUMERIC(18,4);
DECLARE VARIABLE V_DEBITOS NUMERIC(18,4);
DECLARE VARIABLE V_OUTROS_DEBITOS NUMERIC(18,4);
DECLARE VARIABLE V_VALOR_PAGO NUMERIC(18,4);
DECLARE VARIABLE V_TIPO_TRANSACAO VARCHAR(1);
BEGIN
  FOR SELECT  CAST(A.DATA AS DATE),
              PR.NUMERO_ORDEM,
              (SELECT NUMERO_ORDEM FROM R_PROTOCOLO WHERE PEDIDO_ID = PE.NOVO_PEDIDO_ID),
              (SELECT TOTAL_GERAL FROM R_TOTAL_PEDIDO(PE.PEDIDO_ID)),
              (SELECT CREDITO FROM R_CALCULA_CREDITO_DEBITO(PR.TIPO_PROTOCOLO,PR.PROTOCOLO_ID,0,0,0,0)),
              (SELECT DEBITO FROM R_CALCULA_CREDITO_DEBITO(PR.TIPO_PROTOCOLO,PR.PROTOCOLO_ID,0,0,0,0)),
               PE.PEDIDO_ID,
               PR.TIPO_PROTOCOLO,
               PR.PROTOCOLO_ID,
               PR.DATA
  FROM R_PROTOCOLO PR, R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, R_PEDIDO PE
  WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
  AND PE.PEDIDO_ID = A.PEDIDO_ID
  AND A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
  AND A.DATA BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)
  AND CAST(:V_DATA_FIM AS TIMESTAMP) + 0.9999
  AND TA.TIPO = 'C'
  AND PR.TIPO_PROTOCOLO = '1'
  AND NOT EXISTS (SELECT A2.ANDAMENTO_ID FROM R_ANDAMENTO A2
                  WHERE A2.PEDIDO_ID = PE.PEDIDO_ID
                  AND A2.TB_TIPO_ANDAMENTO_ID = 54 )
  ORDER BY CAST(A.DATA AS DATE), PR.NUMERO_ORDEM
  INTO :DATA_CANCELAMENTO, :NUMERO_ORDEM, :NOVO_NUMERO_ORDEM,
       :TOTAL_PROTOCOLO, :CREDITOS, :DEBITOS, :V_PEDIDO_ID,
       :V_TIPO_PROTOCOLO, :V_PROTOCOLO_ID, :V_DATA_PROTOCOLO DO
  BEGIN
    DATA_DEVOLUCAO = 0;
    V_DEBITOS = 0;
    V_CREDITOS = 0;
    V_OUTROS_DEBITOS = 0;
    TIPO_DEVOLUCAO = '';
    FOR SELECT CAST(CAIXA_SERVICO_ID AS INTEGER), DATA_PAGAMENTO, VALOR_PAGO, TIPO_TRANSACAO FROM C_CAIXA_ITEM
        WHERE TIPO_SERVICO = :V_TIPO_PROTOCOLO
        AND CHAVE_SERVICO = :V_PROTOCOLO_ID
        AND TIPO_TRANSACAO = 'D'
        INTO :V_DEVOLUCAO, :V_DATA_DEVOLUCAO_TEMP, :V_VALOR_PAGO, :V_TIPO_TRANSACAO DO
    BEGIN
      IF (:V_TIPO_TRANSACAO = 'D') THEN
      BEGIN
        IF ((:V_DEVOLUCAO = :V_DEVOLUCAO_75) OR
           (:V_DEVOLUCAO = :V_DEVOLUCAO_100) OR
           (:V_DEVOLUCAO = :V_DEVOLUCAO_TJDFT)) THEN
        BEGIN
          V_OUTROS_DEBITOS = :V_OUTROS_DEBITOS + :V_VALOR_PAGO;
          DATA_DEVOLUCAO = :V_DATA_DEVOLUCAO_TEMP;
          --E=ESPECIE, C=COMPENSACAO, T=TJDFT
          IF (:NOVO_NUMERO_ORDEM > 0) THEN
          BEGIN
            TIPO_DEVOLUCAO = 'C';
          END
          ELSE
          BEGIN
            IF (:V_DEVOLUCAO = :V_DEVOLUCAO_TJDFT) THEN
              TIPO_DEVOLUCAO = 'T';
            ELSE
              TIPO_DEVOLUCAO = 'E';
          END
        END
        ELSE
        BEGIN
          V_DEBITOS = :V_DEBITOS + :V_VALOR_PAGO;
        END
      END
      IF (:V_TIPO_TRANSACAO = 'C') THEN
      BEGIN
        V_CREDITOS = :V_CREDITOS + :V_VALOR_PAGO;
      END
    END
    VALOR_ATUAL = (:V_CREDITOS - :V_DEBITOS);
    VALOR_ATUAL_75 = (:VALOR_ATUAL * 0.75);
    IF (:V_DATA_PROTOCOLO BETWEEN :V_DATA_PERIODO_INI
                              AND :V_DATA_PERIODO_FIM + 0.9999) THEN
    BEGIN
      VALOR_ATUAL = :VALOR_ATUAL * CAST(:V_INDICE_ATUALIZACAO AS NUMERIC(18,4));
      VALOR_ATUAL_75 = (:VALOR_ATUAL * 0.75);
    END
    VALOR_DEVOLVIDO = :V_OUTROS_DEBITOS;
    RECEITA_LIQUIDA = (:V_CREDITOS)-(:V_DEBITOS + :V_OUTROS_DEBITOS);
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_MONTAR_SEFAZ_DF (V_DATA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO_ANDAMENTO_SEF VARCHAR(10) CHARACTER SET ISO8859_1,
V_CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (NUMERO_PROTOCOLO NUMERIC(10, 2),
DATA_PROTOCOLO TIMESTAMP,
LIVRO VARCHAR(10) CHARACTER SET ISO8859_1,
FOLHA VARCHAR(15) CHARACTER SET ISO8859_1,
IMOVEL_ID INTEGER,
MATRICULA VARCHAR(15) CHARACTER SET ISO8859_1,
MATRICULA_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
REGISTRO VARCHAR(20) CHARACTER SET ISO8859_1,
INSCRICAO VARCHAR(20) CHARACTER SET ISO8859_1,
NUMERO_ATO INTEGER,
NATUREZA_TITULO_ID INTEGER,
DESCRICAO_TITULO VARCHAR(60) CHARACTER SET ISO8859_1,
DATA_ANDAMENTO TIMESTAMP,
CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1,
CODIGO_NATUREZA_SEF VARCHAR(6) CHARACTER SET ISO8859_1)
AS 
BEGIN
  FOR SELECT DISTINCT
             CAST(PR.NUMERO_ORDEM AS INTEGER) AS NUMERO_ORDEM,
             PR.DATA AS DATA_PROTOCOLO,
             PR.LIVRO,
             COALESCE(CAST(CAST(PR.FOLHA_NUMERO AS INTEGER) AS VARCHAR(12)),'')||COALESCE(PR.FOLHA_FV,'') AS FOLHA,
             CAST(PN.NUMERO AS INTEGER) AS MATRICULA,
             COALESCE(PN.NUMERO_LETRA,''),
             PI.NATUREZA_TITULO_ID,
             TRIM(SUBSTRING(CAST(CAST(COALESCE(PN.ATO_NUMERO,0) AS INTEGER) AS VARCHAR(12)) FROM 1 FOR 5)),
             CASE PN.ATO_TIPO
                  WHEN 'A' THEN 'AV.'
                  WHEN 'R' THEN 'R.'
                  ELSE ''
             END AS REGISTRO,
             (SELECT COALESCE(CAST(CAST(CODIGO_NATUREZA_SEF AS INTEGER) AS VARCHAR(6)),'') FROM G_NATUREZA_TITULO
              WHERE NATUREZA_TITULO_ID = PI.NATUREZA_TITULO_ID),
             (SELECT COALESCE(DESCRICAO,'') FROM G_NATUREZA_TITULO
              WHERE NATUREZA_TITULO_ID = PI.NATUREZA_TITULO_ID),                            
             A.DATA, PN.CARTORIO
        FROM   R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A,
               R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN
        WHERE  PR.PEDIDO_ID = PE.PEDIDO_ID
        AND    PI.PEDIDO_ID = PE.PEDIDO_ID
        AND    PE.PEDIDO_ID = A.PEDIDO_ID
        AND    PN.PEDIDO_ITEM_ID = PI.PEDIDO_ITEM_ID
        AND    A.TB_TIPO_ANDAMENTO_ID = :V_TIPO_ANDAMENTO_SEF
        AND    PN.TIPO_REGISTRO = 'M' --Somente matriculas
        AND    A.DATA BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)
                          AND CAST(:V_DATA_FIM AS TIMESTAMP) + 0.99999        
        AND    (SELECT COUNT(*) FROM G_NATUREZA_TITULO N 
                WHERE N.NATUREZA_TITULO_ID = PI.NATUREZA_TITULO_ID 
                AND COALESCE(CODIGO_NATUREZA_SEF,'') <> '') > 0
        ORDER BY PR.DATA, PI.PEDIDO_ITEM_ID
        INTO   :NUMERO_PROTOCOLO,
               :DATA_PROTOCOLO,
               :LIVRO,
               :FOLHA,
               :MATRICULA,
               :MATRICULA_LETRA,
               :NATUREZA_TITULO_ID,
               :NUMERO_ATO,
               :REGISTRO, 
               :CODIGO_NATUREZA_SEF,
               :DESCRICAO_TITULO,
               :DATA_ANDAMENTO,
               :CARTORIO DO
  BEGIN
    IF (:REGISTRO <> '') THEN
    BEGIN
      REGISTRO = :REGISTRO || :NUMERO_ATO;
    END

    IF (COALESCE(:CARTORIO,'') = '') THEN
    BEGIN
      CARTORIO = :V_CARTORIO;
    END
    
    IF (TRIM(:MATRICULA_LETRA) = '') THEN
    BEGIN
      SELECT FIRST 1 IMOVEL_ID, TRIM(SUBSTRING(INSCRICAO_IMOVEL FROM 1 FOR 15))
      FROM R_IMOVEL
      WHERE TIPO_REGISTRO = 'M'
      AND NUMERO = :MATRICULA
      AND CARTORIO = :CARTORIO
      ORDER BY NUMERO_LETRA
      INTO :IMOVEL_ID, :INSCRICAO;
    END
    ELSE
    BEGIN
      SELECT FIRST 1 IMOVEL_ID, TRIM(SUBSTRING(INSCRICAO_IMOVEL FROM 1 FOR 15))
      FROM R_IMOVEL
      WHERE TIPO_REGISTRO = 'M'
      AND NUMERO = :MATRICULA
      AND NUMERO_LETRA = TRIM(:MATRICULA_LETRA)
      AND CARTORIO = :CARTORIO
      INTO :IMOVEL_ID, :INSCRICAO;    
    END      
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_MONTAR_SEFAZ_DF_ENVOLVIDOS (V_MATRICULA VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUMERO_LETRA VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_ATO VARCHAR(10) CHARACTER SET ISO8859_1,
V_DATA_TRANSFERENCIA VARCHAR(20) CHARACTER SET ISO8859_1,
V_CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (PARTICIPACAO NUMERIC(12, 2),
TIPO_ATO VARCHAR(3) CHARACTER SET ISO8859_1,
ADQUIRENTE_ALIENANTE VARCHAR(3) CHARACTER SET ISO8859_1,
PESSOA_VINCULO_ID NUMERIC(12, 2),
CPF_CNPJ VARCHAR(15) CHARACTER SET ISO8859_1,
DATA_TRANSFERENCIA TIMESTAMP,
TB_TIPO_VINCULO_ID NUMERIC(12, 2),
NOME VARCHAR(120) CHARACTER SET ISO8859_1,
CODIGO_SEF VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_IMOVEL_ID INTEGER;
  DECLARE VARIABLE V_NUMERO_ATO_TEMP INTEGER;
BEGIN
  IF ((:V_CARTORIO IS NULL) OR (:V_CARTORIO = '')) THEN
  BEGIN
    IF (TRIM(:V_NUMERO_LETRA) = '') THEN
    BEGIN
      SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
      WHERE NUMERO = :V_MATRICULA
      AND (NUMERO_LETRA IS NULL OR NUMERO_LETRA = '' OR NUMERO_LETRA = '#')
      AND TIPO_REGISTRO = 'M'
      INTO :V_IMOVEL_ID;                       
    END
    ELSE
    BEGIN
      SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
      WHERE NUMERO = :V_MATRICULA
      AND (NUMERO_LETRA = :V_NUMERO_LETRA) 
      AND TIPO_REGISTRO = 'M'
      INTO :V_IMOVEL_ID;                       
    END
  END
  ELSE
  BEGIN
    IF (TRIM(:V_NUMERO_LETRA) = '') THEN
    BEGIN
      SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
      WHERE NUMERO = :V_MATRICULA
      AND (NUMERO_LETRA IS NULL OR NUMERO_LETRA = '' OR NUMERO_LETRA = '#')
      AND TIPO_REGISTRO = 'M'
      AND CARTORIO = :V_CARTORIO
      INTO :V_IMOVEL_ID;                       
    END
    ELSE
    BEGIN
      SELECT FIRST 1 IMOVEL_ID FROM R_IMOVEL
      WHERE NUMERO = :V_MATRICULA
      AND (NUMERO_LETRA = :V_NUMERO_LETRA) 
      AND TIPO_REGISTRO = 'M'
      AND CARTORIO = :V_CARTORIO
      INTO :V_IMOVEL_ID;                       
    END  
  END
  
  
  V_NUMERO_ATO_TEMP = CAST(:V_NUMERO_ATO AS INTEGER);
                                                      
  --Buscar os adquirentes
  FOR SELECT AREA_PERCENT, TIPO_ATO, '1', CPF_CNPJ, PESSOA_VINCULO_ID, TB_TIPO_VINCULO_ID, NOME 
      FROM R_PESSOA_VINCULO
      WHERE  IMOVEL_ID = :V_IMOVEL_ID
      AND    NUMERO_ATO = :V_NUMERO_ATO_TEMP
      ORDER BY PESSOA_VINCULO_ID
      INTO :PARTICIPACAO, --Participacao em %
           :TIPO_ATO, --Tipo do Ato A ou R    
           :ADQUIRENTE_ALIENANTE, --Aqui eh adquirente
           :CPF_CNPJ, --CPF OU CNPJ do Adquirente
    	   :PESSOA_VINCULO_ID,
           :TB_TIPO_VINCULO_ID,
           :NOME DO 
  BEGIN
    SELECT COALESCE(CODIGO_SEF,'') FROM R_TB_TIPO_VINCULO
    WHERE TB_TIPO_VINCULO_ID = :TB_TIPO_VINCULO_ID
    INTO :CODIGO_SEF;
    DATA_TRANSFERENCIA = null;
    SUSPEND;
  END
  
  IF ((:V_DATA_TRANSFERENCIA = '') OR (:V_DATA_TRANSFERENCIA = '''')) THEN
  BEGIN
    V_NUMERO_ATO_TEMP = :V_NUMERO_ATO_TEMP - 1;
    
    IF ((:V_NUMERO_ATO_TEMP > 0) OR (:V_NUMERO_ATO_TEMP = 0)) THEN
    BEGIN 
      --Buscar os Alientantes
      FOR SELECT AREA_PERCENT, TIPO_ATO, '2', CPF_CNPJ, PESSOA_VINCULO_ID, DATA_TRANSFERENCIA, TB_TIPO_VINCULO_ID, NOME
          FROM R_PESSOA_VINCULO
          WHERE  IMOVEL_ID = :V_IMOVEL_ID
          AND    NUMERO_ATO = :V_NUMERO_ATO_TEMP
          ORDER BY PESSOA_VINCULO_ID
          INTO :PARTICIPACAO, --Participacao em %
               :TIPO_ATO, --Tipo do Ato A ou R    
               :ADQUIRENTE_ALIENANTE, --Aqui eh alienante
               :CPF_CNPJ, --CPF OU CNPJ do Adquirente
               :PESSOA_VINCULO_ID,
               :DATA_TRANSFERENCIA,
               :TB_TIPO_VINCULO_ID,
               :NOME DO
      BEGIN 
        CODIGO_SEF = '';                                     
        IF (:TIPO_ATO <> 'A') THEN
          SUSPEND;
      END
    END
  END
  ELSE
  BEGIN
    --Buscar os Alientantes
    FOR SELECT AREA_PERCENT, TIPO_ATO, '2', CPF_CNPJ, PESSOA_VINCULO_ID, DATA_TRANSFERENCIA, TB_TIPO_VINCULO_ID, NOME
        FROM R_PESSOA_VINCULO
        WHERE  IMOVEL_ID = :V_IMOVEL_ID
        AND    DATA_TRANSFERENCIA BETWEEN CAST(:V_DATA_TRANSFERENCIA AS TIMESTAMP)
                                      AND CAST(:V_DATA_TRANSFERENCIA AS TIMESTAMP) + 0.9999
        ORDER BY PESSOA_VINCULO_ID
        INTO :PARTICIPACAO, --Participacao em %
             :TIPO_ATO, --Tipo do Ato A ou R    
             :ADQUIRENTE_ALIENANTE, --Aqui eh alienante
             :CPF_CNPJ, --CPF OU CNPJ do Adquirente
             :PESSOA_VINCULO_ID,
             :DATA_TRANSFERENCIA,
             :TB_TIPO_VINCULO_ID, 
             :NOME DO
    BEGIN   
      CODIGO_SEF = '';
      SUSPEND;
    END
  END
END ^

ALTER PROCEDURE R_MOVIMENTACAO_PROTOCOLO (V_TIPO VARCHAR(10) CHARACTER SET ISO8859_1,
V_TIPO_DATA VARCHAR(1) CHARACTER SET ISO8859_1,
V_DATA_INICIAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_NATUREZA_FORMAL_TITULO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_USUARIO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_EMOLUMENTO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_ANDAMENTOS VARCHAR(2000) CHARACTER SET ISO8859_1,
V_MATRICULA_INI VARCHAR(10) CHARACTER SET ISO8859_1,
V_MATRICULA_FIM VARCHAR(10) CHARACTER SET ISO8859_1,
V_TRAZER_SEM_PAGAMENTO VARCHAR(5) CHARACTER SET ISO8859_1 DEFAULT 'S',
V_TRAZER_COMPENSACAO_EM_NOVO VARCHAR(5) CHARACTER SET ISO8859_1 DEFAULT 'S',
V_ANDAMENTOS_INEXISTENTES VARCHAR(2000) CHARACTER SET ISO8859_1 DEFAULT '',
V_ANDAMENTOS_CONTEM VARCHAR(2000) CHARACTER SET ISO8859_1 DEFAULT '',
V_ANDAMENTO_MEDIA VARCHAR(15) CHARACTER SET ISO8859_1 DEFAULT '',
V_CATEGORIA_ATO VARCHAR(10) CHARACTER SET ISO8859_1 DEFAULT '')
RETURNS (PROTOCOLO_ID INTEGER,
DATA TIMESTAMP,
NUMERO_ORDEM INTEGER,
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_PROT_DESC VARCHAR(20) CHARACTER SET ISO8859_1,
PEDIDO_ID INTEGER,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
ADQUIRENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
ANDAMENTO_ID INTEGER,
DATA_ANDAMENTO TIMESTAMP,
USUARIO_ID INTEGER,
TB_TIPO_ANDAMENTO_ID INTEGER,
NATUREZA_TITULO_ID INTEGER,
EMOLUMENTO_ID INTEGER,
QUANTIDADE_REGISTRO INTEGER,
QUANTIDADE_AVERBACAO INTEGER,
QUANTIDADE_CERTIDAO INTEGER,
TOTAL_REGISTRO NUMERIC(18, 2),
TOTAL_AVERBACAO NUMERIC(18, 2),
TOTAL_CERTIDAO NUMERIC(18, 2),
ORIGEM_PEDIDO VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_ORIGEM_SITE VARCHAR(3) CHARACTER SET ISO8859_1,
ULTIMO_ANDAMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
NUMERO_SELO VARCHAR(100) CHARACTER SET ISO8859_1,
QTDE_DIAS_APOS_PROTOCOLAR INTEGER,
CATEGORIA_ATO INTEGER,
TOTAL_ISS NUMERIC(18, 2),
VALOR_COMPENSADO NUMERIC(18, 2),
VALOR_TRANSFERIDO NUMERIC(18, 2),
QUANTIDADE INTEGER,
VALOR_EMOLUMENTO NUMERIC(18, 2),
VALOR_FUNDO_RI NUMERIC(18, 2),
VALOR_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_GERAL NUMERIC(18, 2),
DESCRICAO_ANDAMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
DESCRICAO_NATUREZA VARCHAR(120) CHARACTER SET ISO8859_1,
DESCRICAO_TITULO VARCHAR(120) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE D_TIPO_PROTOCOLO VARCHAR(1);
DECLARE VARIABLE D_ULTIMO_PROTOCOLO_ID INTEGER;
DECLARE VARIABLE D_TIPO_COBRANCA VARCHAR(1);
DECLARE VARIABLE D_PEDIDO VARCHAR(15);
DECLARE VARIABLE D_RETORNAR_REGISTRO VARCHAR(1);
DECLARE VARIABLE D_QTDE_ANDAMENTO INTEGER;
DECLARE VARIABLE D_PEDIDO_ITEM_ID INTEGER;
DECLARE VARIABLE D_QTDE_MATRICULA INTEGER;
DECLARE VARIABLE D_QTDE_PEDIDO_ITEM INTEGER;
DECLARE VARIABLE V_SQL VARCHAR(5000);
declare variable V_UF VARCHAR(10);
declare variable V_NOVO_PEDIDO_ID INTEGER;
declare variable V_CREDITO NUMERIC(18,2);
declare variable V_QTDE_TEMP INTEGER;
declare variable V_DATA_PROTOCOLO DATE;
declare variable V_DATA_MEDIA DATE;
declare variable V_ULTIMO_ANDAMENTO_ID INTEGER;
declare variable V_DATA_ULTIMO_ANDAMENTO DATE;
declare variable V_PERIODO_PADRAO VARCHAR(10);
declare variable V_REG_AVERB VARCHAR(3);
BEGIN
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL','CARTORIO','UF',1)
  INTO :V_UF;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','PERIODO_PADRAO',1)
  INTO :V_PERIODO_PADRAO;

  DATA_ANDAMENTO = null;
  QUANTIDADE_REGISTRO = 0;
  QUANTIDADE_AVERBACAO = 0;
  QUANTIDADE_CERTIDAO = 0;
  TOTAL_REGISTRO = 0;
  TOTAL_AVERBACAO = 0;
  TOTAL_CERTIDAO = 0;
  ORIGEM_PEDIDO = '';
  TIPO_ORIGEM_SITE = '';
  ULTIMO_ANDAMENTO = '';
  NUMERO_SELO = '';
  QTDE_DIAS_APOS_PROTOCOLAR = 0;
  CATEGORIA_ATO = 0;
  TOTAL_ISS = 0;
  VALOR_COMPENSADO = 0;
  VALOR_TRANSFERIDO = 0;
  QUANTIDADE = 0;
  VALOR_EMOLUMENTO = 0;
  VALOR_FUNDO_RI = 0;
  VALOR_TAXA_JUDICIARIA = 0;
  TOTAL_GERAL = 0;
  V_REG_AVERB = '';

  V_SQL = ' SELECT DISTINCT PR.PROTOCOLO_ID, PR.DATA,
               PR.NUMERO_ORDEM, PR.TIPO_PROTOCOLO,
               PE.PEDIDO_ID, PE.APRESENTANTE_NOME,
               PE.ADQUIRENTE_NOME, A.ANDAMENTO_ID, A.DATA DATA_ANDAMENTO,
               A.USUARIO_ID, A.TB_TIPO_ANDAMENTO_ID, PR.TIPO_PROTOCOLO, PE.TIPO_COBRANCA,
               PE.ORIGEM_PEDIDO, PE.TIPO_ORIGEM_SITE, PE.NOVO_PEDIDO_ID,
               PI.NATUREZA_TITULO_ID, PI.EMOLUMENTO_ID, PI.PEDIDO_ITEM_ID,
               PE.VALOR_COMPENSADO, COALESCE(PI.QUANTIDADE,0), COALESCE(PI.VALOR_EMOLUMENTO,0),
               COALESCE(PI.VALOR_FUNDO_RI,0), COALESCE(PI.VALOR_TAXA_JUDICIARIA,0),
               COALESCE(PI.VALOR_ISS,0), E.reg_averb, PI.NUMERO_SELO, TA.descricao, NT.descricao,
               TI.descricao
        FROM   R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A, R_PEDIDO_ITEM PI, R_TB_TITULO TI,
          G_EMOLUMENTO E, R_TB_TIPO_ANDAMENTO TA, G_NATUREZA_TITULO NT
        WHERE  PR.PEDIDO_ID = PE.PEDIDO_ID
        AND    PE.PEDIDO_ID = PI.PEDIDO_ID
        AND    PE.PEDIDO_ID = A.PEDIDO_ID
        AND    PI.EMOLUMENTO_ID = E.EMOLUMENTO_ID
        AND    A.tb_tipo_andamento_id = TA.tb_tipo_andamento_id
        AND    PI.natureza_titulo_id = NT.natureza_titulo_id
        AND    PE.tb_titulo_id = TI.tb_titulo_id ';

  IF (COALESCE(:V_TIPO_DATA,'') = 'P') THEN --Pela Data do Protocolo
  BEGIN
    V_SQL = :V_SQL || ' AND PR.DATA BETWEEN CAST('||''''||:V_DATA_INICIAL||''''||' AS TIMESTAMP)
                                        AND CAST('||''''||:V_DATA_FINAL||''''||' AS TIMESTAMP) + 0.99999 ';
  END
  ELSE --Pela Data do Andamento
  BEGIN
    V_SQL = :V_SQL || ' AND A.DATA BETWEEN CAST('||''''||:V_DATA_INICIAL||''''||' AS TIMESTAMP)
                                       AND CAST('||''''||:V_DATA_FINAL||''''||' AS TIMESTAMP) + 0.99999 ';
  END

  IF (COALESCE(:V_TIPO,'') = 'E') THEN --Pela tipo de exame
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 2 ';
  END
  else IF (COALESCE(:V_TIPO,'') = 'P') THEN --Todos os protocolos
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'PB') THEN --protocolos balcão
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
    V_SQL = :V_SQL || ' AND ((COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'1'||''''||') OR (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''||''''||') = '||''''||''||''''||'))';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'PE') THEN --protocolos penhora
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'1'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'PI') THEN --protocolos intimação
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'3'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'PEE') THEN --protocolos escritura eletronica
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'4'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'C') THEN --Todas as certidoes
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'CB') THEN --certidoes balcao
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND ((COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'1'||''''||') OR (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''||''''||') = '||''''||''||''''||'))';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'CP') THEN --certidao eridft publico
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'2'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'CC') THEN --certidao eridft codhab
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'5'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'CT') THEN --certidao eridft terracap
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'6'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'CCC') THEN --certidao central de certidoes
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'3'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'PR_LV3') THEN -- protocolos de livro 03
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_PEDIDO_ITEM_NUMERO PN2, R_PEDIDO_ITEM PI2
                             WHERE PN2.PEDIDO_ITEM_ID = PI2.PEDIDO_ITEM_ID
                             AND PI2.PEDIDO_ID = PR.PEDIDO_ID
                             AND PN2.TIPO_REGISTRO = '||''''||'A'||''''||') > 0 ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'C_LV3') THEN --Pedidos de certidão de livro 03
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_PEDIDO_ITEM_NUMERO PN2, R_PEDIDO_ITEM PI2
                             WHERE PN2.PEDIDO_ITEM_ID = PI2.PEDIDO_ITEM_ID
                             AND PI2.PEDIDO_ID = PR.PEDIDO_ID
                             AND PN2.TIPO_REGISTRO = '||''''||'A'||''''||') > 0 ';
  END

  IF (COALESCE(:V_ANDAMENTOS,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND A.TB_TIPO_ANDAMENTO_ID IN ('||:V_ANDAMENTOS||') ';
  END

  IF (COALESCE(:V_USUARIO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND A.USUARIO_ID = '||:V_USUARIO_ID;
  END

  IF (COALESCE(:V_ANDAMENTOS_INEXISTENTES,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_ANDAMENTO WHERE PEDIDO_ID = PR.PEDIDO_ID AND TB_TIPO_ANDAMENTO_ID IN ('||:V_ANDAMENTOS_INEXISTENTES||')) = 0 ';
  END

  IF (COALESCE(:V_ANDAMENTOS_CONTEM,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_ANDAMENTO WHERE PEDIDO_ID = PR.PEDIDO_ID AND TB_TIPO_ANDAMENTO_ID IN ('||:V_ANDAMENTOS_CONTEM||')) > 0 ';
  END

  IF (COALESCE(:V_CATEGORIA_ATO,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM G_NATUREZA_TITULO NT, R_PEDIDO_ITEM PI WHERE NT.NATUREZA_TITULO_ID = PI.NATUREZA_TITULO_ID AND PI.PEDIDO_ID = PR.PEDIDO_ID AND NT.CATEGORIA_ATO = '||:V_CATEGORIA_ATO||') > 0 ';
  END

  IF (COALESCE(:V_NATUREZA_FORMAL_TITULO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PI.NATUREZA_TITULO_ID  = '||:V_NATUREZA_FORMAL_TITULO_ID;
  END

  IF (COALESCE(:V_EMOLUMENTO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PI.EMOLUMENTO_ID  = '||:V_EMOLUMENTO_ID;
  END


  V_SQL = :V_SQL || ' ORDER BY PR.PROTOCOLO_ID ';

  D_ULTIMO_PROTOCOLO_ID = 0;
  FOR EXECUTE STATEMENT V_SQL
  INTO :PROTOCOLO_ID, :DATA, :NUMERO_ORDEM, :TIPO_PROTOCOLO, :PEDIDO_ID,
    :APRESENTANTE_NOME, :ADQUIRENTE_NOME, :ANDAMENTO_ID, :DATA_ANDAMENTO,
    :USUARIO_ID, :TB_TIPO_ANDAMENTO_ID, :D_TIPO_PROTOCOLO, :D_TIPO_COBRANCA,
    :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE, :V_NOVO_PEDIDO_ID, :NATUREZA_TITULO_ID,
    :EMOLUMENTO_ID, :D_PEDIDO_ITEM_ID, :VALOR_COMPENSADO, :QUANTIDADE, :VALOR_EMOLUMENTO,
    :VALOR_FUNDO_RI, :VALOR_TAXA_JUDICIARIA, :TOTAL_ISS, :V_REG_AVERB, :NUMERO_SELO,
    :DESCRICAO_ANDAMENTO, :DESCRICAO_NATUREZA, :DESCRICAO_TITULO DO
  BEGIN
    QUANTIDADE_REGISTRO = 0;
    QUANTIDADE_AVERBACAO = 0;
    QUANTIDADE_CERTIDAO = 0;
    TOTAL_REGISTRO = 0;
    TOTAL_AVERBACAO = 0;
    TOTAL_CERTIDAO = 0;
    ULTIMO_ANDAMENTO = '';
    QTDE_DIAS_APOS_PROTOCOLAR = 0;
    CATEGORIA_ATO = 0;
    VALOR_TRANSFERIDO = 0;

    TOTAL_GERAL = COALESCE(:VALOR_EMOLUMENTO,0) + COALESCE(:VALOR_FUNDO_RI,0) +
      COALESCE(:VALOR_TAXA_JUDICIARIA,0) + COALESCE(:TOTAL_ISS,0);

    if ((COALESCE(:TIPO_PROTOCOLO,'') = '1') or (COALESCE(:TIPO_PROTOCOLO,'') = '2')) then --protocolo ou exame
    begin
      IF (COALESCE(:V_REG_AVERB,'') = 'A') THEN
      BEGIN
        QUANTIDADE_AVERBACAO = :QUANTIDADE;
        TOTAL_AVERBACAO = COALESCE(:VALOR_EMOLUMENTO,0) + COALESCE(:VALOR_FUNDO_RI,0) + COALESCE(:VALOR_TAXA_JUDICIARIA,0);
      END
      ELSE
      BEGIN
        QUANTIDADE_REGISTRO = :QUANTIDADE;
        TOTAL_REGISTRO = COALESCE(:VALOR_EMOLUMENTO,0) + COALESCE(:VALOR_FUNDO_RI,0) + COALESCE(:VALOR_TAXA_JUDICIARIA,0);
      END
    end
    ELSE
    BEGIN
      QUANTIDADE_CERTIDAO = :QUANTIDADE;
      TOTAL_CERTIDAO = COALESCE(:VALOR_EMOLUMENTO,0) + COALESCE(:VALOR_FUNDO_RI,0) + COALESCE(:VALOR_TAXA_JUDICIARIA,0);
    END

    if (COALESCE(:ORIGEM_PEDIDO,'') = '') then
    BEGIN
      ORIGEM_PEDIDO = '1'; --BALCAO
    END

    D_RETORNAR_REGISTRO = 'S';

    IF (:D_RETORNAR_REGISTRO = 'S') THEN
    BEGIN
      IF (COALESCE(:V_MATRICULA_INI,'') <> '') THEN
      BEGIN
        SELECT COUNT(*) FROM R_PEDIDO_ITEM_NUMERO
        WHERE NUMERO BETWEEN :V_MATRICULA_INI AND :V_MATRICULA_FIM
        AND PEDIDO_ITEM_ID = :D_PEDIDO_ITEM_ID
        INTO :D_QTDE_MATRICULA;
        IF (:D_QTDE_MATRICULA = 0) THEN
        BEGIN
          D_RETORNAR_REGISTRO = 'N';
        END
      END
    END

    IF (:D_RETORNAR_REGISTRO = 'S') THEN
    BEGIN
      IF (COALESCE(:V_NOVO_PEDIDO_ID,0) > 0) THEN
      BEGIN
        SELECT VALOR_COMPENSADO
        FROM R_PEDIDO
        WHERE PEDIDO_ID = :V_NOVO_PEDIDO_ID
        INTO :VALOR_TRANSFERIDO;
  
        if ((COALESCE(:V_TRAZER_COMPENSACAO_EM_NOVO,'') = 'N') AND (COALESCE(:VALOR_TRANSFERIDO,0) > 0)) then
        begin
          D_RETORNAR_REGISTRO = 'N';
        end
      END
    END

    IF (:D_RETORNAR_REGISTRO = 'S') THEN
    BEGIN
      IF (COALESCE(:V_TRAZER_SEM_PAGAMENTO,'') = 'N') THEN
      BEGIN
        D_PEDIDO = CAST(CAST(:PEDIDO_ID AS INTEGER) AS VARCHAR(15));
        SELECT CREDITO
        FROM R_TOTAL_PEDIDO(:D_PEDIDO, :V_PERIODO_PADRAO, :V_UF)
        INTO :V_CREDITO;

        if (COALESCE(:V_CREDITO,0) = 0) then
        begin
          D_RETORNAR_REGISTRO = 'N';
        end
      END
    END

    IF (:D_RETORNAR_REGISTRO = 'S') THEN
    BEGIN
      D_PEDIDO = CAST(CAST(:PEDIDO_ID AS INTEGER) AS VARCHAR(15));

      --ULTIMO ANDAMENTO
      SELECT FIRST 1 TA.descricao, a.tb_tipo_andamento_id, A.data
      FROM R_ANDAMENTO A, r_tb_tipo_andamento TA
      WHERE A.tb_tipo_andamento_id = TA.tb_tipo_andamento_id
      AND A.pedido_id = :D_PEDIDO
      ORDER BY A.andamento_id DESC
      INTO :ULTIMO_ANDAMENTO, :V_ULTIMO_ANDAMENTO_ID, :V_DATA_ULTIMO_ANDAMENTO;

      --NUMERO DO SELO
      if (COALESCE(V_UF,'') = 'DF') then
      BEGIN
        if (:TIPO_PROTOCOLO = '1') then
        begin
          SELECT FIRST 1 NUMERO_SELO FROM R_PROTOCOLO
          WHERE TIPO_PROTOCOLO = '1'
          AND PEDIDO_ID = :PEDIDO_ID
          INTO :NUMERO_SELO;
        end
      END
      ELSE
      BEGIN
        NUMERO_SELO = '';
      END

      if (:TIPO_PROTOCOLO = '1') then
      begin
        TIPO_PROT_DESC = 'Protcoloco';
      end
      else if (:TIPO_PROTOCOLO = '2') then
      begin
        TIPO_PROT_DESC = 'Exame/Cálculo';
      end
      else
      begin
        TIPO_PROT_DESC = 'Ped. de Certidão';
      end

      --CALCULAR QTDE DIAS
      QTDE_DIAS_APOS_PROTOCOLAR = 0;
      IF (COALESCE(:V_ANDAMENTO_MEDIA,'') <> '') THEN
      BEGIN
        SELECT COUNT(*) FROM R_ANDAMENTO
        WHERE PEDIDO_ID = :PEDIDO_ID
        AND TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_MEDIA
        INTO :V_QTDE_TEMP;

        IF (COALESCE(:V_QTDE_TEMP,0) > 0) THEN
        BEGIN
          SELECT FIRST 1 CAST(DATA AS DATE) FROM R_ANDAMENTO
          WHERE PEDIDO_ID = :PEDIDO_ID
          AND TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_MEDIA
          INTO :V_DATA_MEDIA;
          V_DATA_PROTOCOLO = CAST(:DATA AS DATE);
          QTDE_DIAS_APOS_PROTOCOLAR = :V_DATA_MEDIA - :V_DATA_PROTOCOLO;
        END
      END
      else
      BEGIN
        --PEGAR PELA DATA DO ultimo andamento
        V_DATA_MEDIA = CAST(:V_DATA_ULTIMO_ANDAMENTO AS DATE);
        V_DATA_PROTOCOLO = CAST(:DATA AS DATE);
        QTDE_DIAS_APOS_PROTOCOLAR = :V_DATA_MEDIA - :V_DATA_PROTOCOLO;
      END

      select CATEGORIA_ATO from g_natureza_titulo
      where natureza_titulo_id = :natureza_titulo_id
      into :CATEGORIA_ATO;

      SUSPEND;
      D_ULTIMO_PROTOCOLO_ID = :PROTOCOLO_ID;
    END
  END
END ^

ALTER PROCEDURE R_MOVIMENTACAO_PROT_AGRUPADO (V_TIPO VARCHAR(10) CHARACTER SET ISO8859_1,
V_TIPO_DATA VARCHAR(1) CHARACTER SET ISO8859_1,
V_DATA_INICIAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_NATUREZA_FORMAL_TITULO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_USUARIO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_EMOLUMENTO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_ANDAMENTOS VARCHAR(2000) CHARACTER SET ISO8859_1,
V_MATRICULA_INI VARCHAR(10) CHARACTER SET ISO8859_1,
V_MATRICULA_FIM VARCHAR(10) CHARACTER SET ISO8859_1,
V_TRAZER_SEM_PAGAMENTO VARCHAR(5) CHARACTER SET ISO8859_1 DEFAULT 'S',
V_TRAZER_COMPENSACAO_EM_NOVO VARCHAR(5) CHARACTER SET ISO8859_1 DEFAULT 'S',
V_ANDAMENTOS_INEXISTENTES VARCHAR(2000) CHARACTER SET ISO8859_1 DEFAULT '',
V_ANDAMENTOS_CONTEM VARCHAR(2000) CHARACTER SET ISO8859_1 DEFAULT '',
V_ANDAMENTO_MEDIA VARCHAR(15) CHARACTER SET ISO8859_1 DEFAULT '',
V_CATEGORIA_ATO VARCHAR(10) CHARACTER SET ISO8859_1 DEFAULT '')
RETURNS (PROTOCOLO_ID INTEGER,
DATA TIMESTAMP,
NUMERO_ORDEM INTEGER,
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_PROT_DESC VARCHAR(20) CHARACTER SET ISO8859_1,
PEDIDO_ID INTEGER,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
ADQUIRENTE_NOME VARCHAR(1000) CHARACTER SET ISO8859_1,
ANDAMENTO_ID INTEGER,
DATA_ANDAMENTO TIMESTAMP,
USUARIO_ID INTEGER,
TB_TIPO_ANDAMENTO_ID INTEGER,
NATUREZA_TITULO_ID INTEGER,
EMOLUMENTO_ID INTEGER,
QUANTIDADE_REGISTRO INTEGER,
QUANTIDADE_AVERBACAO INTEGER,
QUANTIDADE_CERTIDAO INTEGER,
TOTAL_REGISTRO NUMERIC(18, 2),
TOTAL_AVERBACAO NUMERIC(18, 2),
TOTAL_CERTIDAO NUMERIC(18, 2),
ORIGEM_PEDIDO VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_ORIGEM_SITE VARCHAR(3) CHARACTER SET ISO8859_1,
ULTIMO_ANDAMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
NUMERO_SELO VARCHAR(100) CHARACTER SET ISO8859_1,
QTDE_DIAS_APOS_PROTOCOLAR INTEGER,
CATEGORIA_ATO INTEGER,
TOTAL_ISS NUMERIC(18, 2),
VALOR_COMPENSADO NUMERIC(18, 2),
VALOR_TRANSFERIDO NUMERIC(18, 2),
QUANTIDADE INTEGER,
VALOR_EMOLUMENTO NUMERIC(18, 2),
VALOR_FUNDO_RI NUMERIC(18, 2),
VALOR_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_GERAL NUMERIC(18, 2),
DESCRICAO_ANDAMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
DESCRICAO_NATUREZA VARCHAR(120) CHARACTER SET ISO8859_1,
DESCRICAO_TITULO VARCHAR(120) CHARACTER SET ISO8859_1)
AS 
declare variable D_TIPO_PROTOCOLO varchar(1);
declare variable D_ULTIMO_PROTOCOLO_ID numeric(18,4);
declare variable D_TIPO_COBRANCA varchar(1);
declare variable D_PEDIDO varchar(15);
declare variable D_RETORNAR_REGISTRO varchar(1);
declare variable D_QTDE_ANDAMENTO numeric(18,4);
declare variable D_PEDIDO_ITEM_ID numeric(18,4);
declare variable D_QTDE_MATRICULA numeric(18,4);
declare variable D_QTDE_PEDIDO_ITEM numeric(18,4);
declare variable V_SQL varchar(5000);
declare variable V_UF varchar(10);
declare variable V_NOVO_PEDIDO_ID integer;
declare variable V_VALOR_COMPENSADO numeric(18,4);
declare variable V_CREDITO numeric(18,4);
declare variable V_QTDE_TEMP integer;
declare variable V_DATA_PROTOCOLO date;
declare variable V_DATA_MEDIA date;
declare variable V_ULTIMO_ANDAMENTO_ID integer;
declare variable V_DATA_ULTIMO_ANDAMENTO date;
declare variable V_natureza_titulo_id integer;
declare variable V_TITULO_ID INTEGER;
BEGIN
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL','CARTORIO','UF',1)
  INTO :V_UF;

  DATA_ANDAMENTO = null;
  QUANTIDADE_REGISTRO = 0;
  QUANTIDADE_AVERBACAO = 0;
  QUANTIDADE_CERTIDAO = 0;
  TOTAL_REGISTRO = 0;
  TOTAL_AVERBACAO = 0;
  TOTAL_CERTIDAO = 0;
  ORIGEM_PEDIDO = '';
  TIPO_ORIGEM_SITE = '';
  ULTIMO_ANDAMENTO = '';
  NUMERO_SELO = '';
  QTDE_DIAS_APOS_PROTOCOLAR = 0;
  CATEGORIA_ATO = 0;
  TOTAL_ISS = 0;
  VALOR_COMPENSADO = 0;
  VALOR_TRANSFERIDO = 0;
  QUANTIDADE = 0;
  VALOR_EMOLUMENTO = 0;
  VALOR_FUNDO_RI = 0;
  VALOR_TAXA_JUDICIARIA = 0;
  TOTAL_GERAL = 0;

  V_SQL = ' SELECT DISTINCT PR.PROTOCOLO_ID, PR.DATA,
               PR.NUMERO_ORDEM, PR.TIPO_PROTOCOLO,
               PE.PEDIDO_ID, PE.APRESENTANTE_NOME,
               PE.ADQUIRENTE_NOME, A.ANDAMENTO_ID, A.DATA DATA_ANDAMENTO,
               A.USUARIO_ID, A.TB_TIPO_ANDAMENTO_ID, PR.TIPO_PROTOCOLO, PE.TIPO_COBRANCA,
               PE.ORIGEM_PEDIDO, PE.TIPO_ORIGEM_SITE, PE.NOVO_PEDIDO_ID, PE.VALOR_COMPENSADO, PE.tb_titulo_id
        FROM   R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A
        WHERE  PR.PEDIDO_ID = PE.PEDIDO_ID
        AND    PE.PEDIDO_ID = A.PEDIDO_ID ';

  IF (COALESCE(:V_TIPO_DATA,'') = 'P') THEN --Pela Data do Protocolo
  BEGIN
    V_SQL = :V_SQL || ' AND PR.DATA BETWEEN CAST('||''''||:V_DATA_INICIAL||''''||' AS TIMESTAMP)
                                        AND CAST('||''''||:V_DATA_FINAL||''''||' AS TIMESTAMP) + 0.99999 ';
  END
  ELSE --Pela Data do Andamento
  BEGIN
    V_SQL = :V_SQL || ' AND A.DATA BETWEEN CAST('||''''||:V_DATA_INICIAL||''''||' AS TIMESTAMP)
                                       AND CAST('||''''||:V_DATA_FINAL||''''||' AS TIMESTAMP) + 0.99999 ';
  END

  IF (COALESCE(:V_TIPO,'') = 'E') THEN --Pela tipo de exame
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 2 ';
  END
  else IF (COALESCE(:V_TIPO,'') = 'P') THEN --Todos os protocolos
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'PB') THEN --protocolos balcão
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
    V_SQL = :V_SQL || ' AND ((COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'1'||''''||') OR (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''||''''||') = '||''''||''||''''||'))';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'PE') THEN --protocolos penhora
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'1'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'PI') THEN --protocolos intimação
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'3'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'PEE') THEN --protocolos escritura eletronica
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'4'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'C') THEN --Todas as certidoes
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'CB') THEN --certidoes balcao
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND ((COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'1'||''''||') OR (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''||''''||') = '||''''||''||''''||'))';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'CP') THEN --certidao eridft publico
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'2'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'CC') THEN --certidao eridft codhab
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'5'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'CT') THEN --certidao eridft terracap
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'2'||''''||') ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.TIPO_ORIGEM_SITE,'||''''||''''||''||') = '||''''||'6'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'CCC') THEN --certidao central de certidoes
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND (COALESCE(PE.ORIGEM_PEDIDO,'||''''||''''||''||') = '||''''||'3'||''''||') ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'PR_LV3') THEN -- protocolos de livro 03
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_PEDIDO_ITEM_NUMERO PN2, R_PEDIDO_ITEM PI2
                             WHERE PN2.PEDIDO_ITEM_ID = PI2.PEDIDO_ITEM_ID
                             AND PI2.PEDIDO_ID = PR.PEDIDO_ID
                             AND PN2.TIPO_REGISTRO = '||''''||'A'||''''||') > 0 ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'C_LV3') THEN --Pedidos de certidão de livro 03
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_PEDIDO_ITEM_NUMERO PN2, R_PEDIDO_ITEM PI2
                             WHERE PN2.PEDIDO_ITEM_ID = PI2.PEDIDO_ITEM_ID
                             AND PI2.PEDIDO_ID = PR.PEDIDO_ID
                             AND PN2.TIPO_REGISTRO = '||''''||'A'||''''||') > 0 ';
  END

  IF (COALESCE(:V_ANDAMENTOS,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND A.TB_TIPO_ANDAMENTO_ID IN ('||:V_ANDAMENTOS||') ';
  END

  IF (COALESCE(:V_USUARIO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND A.USUARIO_ID = '||:V_USUARIO_ID;
  END

  IF (COALESCE(:V_ANDAMENTOS_INEXISTENTES,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_ANDAMENTO WHERE PEDIDO_ID = PR.PEDIDO_ID AND TB_TIPO_ANDAMENTO_ID IN ('||:V_ANDAMENTOS_INEXISTENTES||')) = 0 ';
  END

  IF (COALESCE(:V_ANDAMENTOS_CONTEM,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_ANDAMENTO WHERE PEDIDO_ID = PR.PEDIDO_ID AND TB_TIPO_ANDAMENTO_ID IN ('||:V_ANDAMENTOS_CONTEM||')) > 0 ';
  END

  IF (COALESCE(:V_CATEGORIA_ATO,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM G_NATUREZA_TITULO NT, R_PEDIDO_ITEM PI WHERE NT.NATUREZA_TITULO_ID = PI.NATUREZA_TITULO_ID AND PI.PEDIDO_ID = PR.PEDIDO_ID AND NT.CATEGORIA_ATO = '||:V_CATEGORIA_ATO||') > 0 ';
  END

  IF (COALESCE(:V_EMOLUMENTO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_PEDIDO_ITEM WHERE PEDIDO_ID = PR.PEDIDO_ID AND EMOLUMENTO_ID = '||:V_EMOLUMENTO_ID||') > 0 ';
  END



  V_SQL = :V_SQL || ' ORDER BY PR.PROTOCOLO_ID ';

  D_ULTIMO_PROTOCOLO_ID = 0;
  FOR EXECUTE STATEMENT V_SQL
  INTO :PROTOCOLO_ID, :DATA, :NUMERO_ORDEM, :TIPO_PROTOCOLO, :PEDIDO_ID,
    :APRESENTANTE_NOME, :ADQUIRENTE_NOME, :ANDAMENTO_ID, :DATA_ANDAMENTO,
    :USUARIO_ID, :TB_TIPO_ANDAMENTO_ID, :D_TIPO_PROTOCOLO, :D_TIPO_COBRANCA,
    :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE, :V_NOVO_PEDIDO_ID, :VALOR_COMPENSADO, :V_TITULO_ID DO
  BEGIN
    CATEGORIA_ATO = 0;
    VALOR_TRANSFERIDO = 0;
    EMOLUMENTO_ID = NULL;

    if (COALESCE(:ORIGEM_PEDIDO,'') = '') then
    BEGIN
      ORIGEM_PEDIDO = '1'; --BALCAO
    END

    D_RETORNAR_REGISTRO = 'S';
    IF ((COALESCE(:V_ANDAMENTOS,'') = '') AND (:D_ULTIMO_PROTOCOLO_ID = :PROTOCOLO_ID) AND (TRIM(:V_USUARIO_ID) = '')) THEN
    BEGIN
      D_RETORNAR_REGISTRO = 'N';
    END

    IF (:D_RETORNAR_REGISTRO = 'S') THEN
    BEGIN
      IF (COALESCE(:V_MATRICULA_INI,'') <> '') THEN
      BEGIN
        SELECT COUNT(*) FROM R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PIN
        WHERE PIN.NUMERO BETWEEN :V_MATRICULA_INI AND :V_MATRICULA_FIM
        AND PI.PEDIDO_ITEM_ID = PIN.PEDIDO_ITEM_ID
        AND PI.PEDIDO_ID = :PEDIDO_ID
        INTO :D_QTDE_MATRICULA;
        IF (:D_QTDE_MATRICULA = 0) THEN
        BEGIN
          D_RETORNAR_REGISTRO = 'N';
        END
      END
    END

    IF (:D_RETORNAR_REGISTRO = 'S') THEN
    BEGIN
      IF (COALESCE(:V_NATUREZA_FORMAL_TITULO_ID,'') <> '') THEN
      BEGIN
        SELECT COUNT(*)
        FROM R_PEDIDO_ITEM
        WHERE PEDIDO_ID = :PEDIDO_ID
        AND NATUREZA_TITULO_ID = TRIM(:V_NATUREZA_FORMAL_TITULO_ID)
        INTO :D_QTDE_PEDIDO_ITEM;

        IF (:D_QTDE_PEDIDO_ITEM > 0) THEN
        BEGIN
          D_RETORNAR_REGISTRO = 'S';
          SELECT FIRST 1 PI.NATUREZA_TITULO_ID, PI.PEDIDO_ITEM_ID, PI.EMOLUMENTO_ID
          FROM R_PEDIDO_ITEM PI
          WHERE PI.PEDIDO_ID = :PEDIDO_ID
          AND PI.NATUREZA_TITULO_ID = :V_NATUREZA_FORMAL_TITULO_ID
          INTO :NATUREZA_TITULO_ID, :D_PEDIDO_ITEM_ID, :EMOLUMENTO_ID;
        END
        ELSE
        BEGIN
          D_RETORNAR_REGISTRO = 'N';
        END
      END
      ELSE if (COALESCE(:V_EMOLUMENTO_ID,'') <> '') THEN
      BEGIN
        SELECT FIRST 1 PI.NATUREZA_TITULO_ID, PI.PEDIDO_ITEM_ID, PI.EMOLUMENTO_ID
        FROM R_PEDIDO_ITEM PI
        WHERE PI.PEDIDO_ID = :PEDIDO_ID
        AND PI.EMOLUMENTO_ID = :V_EMOLUMENTO_ID
        INTO :NATUREZA_TITULO_ID, :D_PEDIDO_ITEM_ID, :EMOLUMENTO_ID;
      END
    END

    IF (:D_RETORNAR_REGISTRO = 'S') THEN
    BEGIN
      IF ((COALESCE(:V_TRAZER_COMPENSACAO_EM_NOVO,'') = 'N') AND (COALESCE(:V_NOVO_PEDIDO_ID,0) > 0)) THEN
      BEGIN
        V_VALOR_COMPENSADO = 0;
        SELECT VALOR_COMPENSADO
        FROM R_PEDIDO
        WHERE PEDIDO_ID = :V_NOVO_PEDIDO_ID
        INTO :V_VALOR_COMPENSADO;

        if (COALESCE(:V_VALOR_COMPENSADO,0) > 0) then
        begin
          D_RETORNAR_REGISTRO = 'N';
        end
      END
    END

    IF (:D_RETORNAR_REGISTRO = 'S') THEN
    BEGIN
      IF (COALESCE(:V_TRAZER_SEM_PAGAMENTO,'') = 'N') THEN
      BEGIN
        D_PEDIDO = CAST(CAST(:PEDIDO_ID AS INTEGER) AS VARCHAR(15));
        SELECT CREDITO
        FROM R_TOTAL_PEDIDO(:D_PEDIDO)
        INTO :V_CREDITO;

        if (COALESCE(:V_CREDITO,0) = 0) then
        begin
          D_RETORNAR_REGISTRO = 'N';
        end
      END
    END

    IF (:D_RETORNAR_REGISTRO = 'S') THEN
    BEGIN
      IF (COALESCE(:V_NOVO_PEDIDO_ID,0) > 0) THEN
      BEGIN
        SELECT VALOR_COMPENSADO
        FROM R_PEDIDO
        WHERE PEDIDO_ID = :V_NOVO_PEDIDO_ID
        INTO :VALOR_TRANSFERIDO;
  
        if ((COALESCE(:V_TRAZER_COMPENSACAO_EM_NOVO,'') = 'N') AND (COALESCE(:VALOR_TRANSFERIDO,0) > 0)) then
        begin
          D_RETORNAR_REGISTRO = 'N';
        end
      END
    END

    IF (:D_RETORNAR_REGISTRO = 'S') THEN
    BEGIN
      D_PEDIDO = CAST(CAST(:PEDIDO_ID AS INTEGER) AS VARCHAR(15));

      IF (COALESCE(:V_NATUREZA_FORMAL_TITULO_ID,'') <> '') THEN
      BEGIN
        SELECT QUANTIDADE_REGISTRO, QUANTIDADE_AVERBACAO, TOTAL_REGISTRO, TOTAL_AVERBACAO,
          QUANTIDADE_CERTIDAO, TOTAL_CERTIDAO, TOTAL_ISS, QUANTIDADE_GERAL, TOTAL_EMOLUMENTO,
          TOTAL_FUNDO_RI, TOTAL_TAXA, TOTAL_GERAL
        FROM R_TOTAL_PEDIDO_POR_ATO(:D_PEDIDO, TRIM(:V_NATUREZA_FORMAL_TITULO_ID))
        INTO :QUANTIDADE_REGISTRO, QUANTIDADE_AVERBACAO, :TOTAL_REGISTRO, :TOTAL_AVERBACAO,
          :QUANTIDADE_CERTIDAO, :TOTAL_CERTIDAO, :TOTAL_ISS, :QUANTIDADE, :VALOR_EMOLUMENTO,
          :VALOR_FUNDO_RI, :VALOR_TAXA_JUDICIARIA, :TOTAL_GERAL;
      END
      ELSE
      BEGIN
        SELECT QUANTIDADE_REGISTRO, QUANTIDADE_AVERBACAO, TOTAL_REGISTRO, TOTAL_AVERBACAO,
          (QUANTIDADE_CERTIDAO + QUANTIDADE_BUSCA + QUANTIDADE_REVALIDACAO),
          (TOTAL_CERTIDAO + TOTAL_BUSCA + TOTAL_REVALIDACAO), TOTAL_ISS, QUANTIDADE_GERAL, TOTAL_EMOLUMENTO,
          TOTAL_FUNDO_RI, TOTAL_TAXA, TOTAL_GERAL
        FROM R_TOTAL_PEDIDO(:D_PEDIDO)
        INTO :QUANTIDADE_REGISTRO, QUANTIDADE_AVERBACAO, :TOTAL_REGISTRO, :TOTAL_AVERBACAO,
          :QUANTIDADE_CERTIDAO, :TOTAL_CERTIDAO, :TOTAL_ISS, :QUANTIDADE, :VALOR_EMOLUMENTO,
          :VALOR_FUNDO_RI, :VALOR_TAXA_JUDICIARIA, :TOTAL_GERAL;
      END


      --ULTIMO ANDAMENTO
      SELECT FIRST 1 TA.descricao, a.tb_tipo_andamento_id, A.data
      FROM R_ANDAMENTO A, r_tb_tipo_andamento TA
      WHERE A.tb_tipo_andamento_id = TA.tb_tipo_andamento_id
      AND A.pedido_id = :D_PEDIDO
      ORDER BY A.andamento_id DESC
      INTO :ULTIMO_ANDAMENTO, :V_ULTIMO_ANDAMENTO_ID, :V_DATA_ULTIMO_ANDAMENTO;

      --NUMERO DO SELO
      NUMERO_SELO = '';
      if (COALESCE(V_UF,'') = 'DF') then
      BEGIN
        if (:TIPO_PROTOCOLO = '1') then
        begin
          SELECT NUMERO_SELO FROM R_PROTOCOLO
          WHERE TIPO_PROTOCOLO = '1'
          AND PEDIDO_ID = :PEDIDO_ID
          INTO :NUMERO_SELO;
        end
        else
        begin
          SELECT FIRST 1 NUMERO_SELO FROM R_PEDIDO_ITEM
          WHERE PEDIDO_ID = :PEDIDO_ID
          INTO :NUMERO_SELO;
        end
      END
      if (:TIPO_PROTOCOLO = '1') then
      begin
        TIPO_PROT_DESC = 'Protcoloco';
      end
      else if (:TIPO_PROTOCOLO = '2') then
      begin
        TIPO_PROT_DESC = 'Exame/Cálculo';
      end
      else
      begin
        TIPO_PROT_DESC = 'Ped. de Certidão';
      end

      --CALCULAR QTDE DIAS
      QTDE_DIAS_APOS_PROTOCOLAR = 0;
      IF (COALESCE(:V_ANDAMENTO_MEDIA,'') <> '') THEN
      BEGIN
        SELECT COUNT(*) FROM R_ANDAMENTO
        WHERE PEDIDO_ID = :PEDIDO_ID
        AND TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_MEDIA
        INTO :V_QTDE_TEMP;

        IF (COALESCE(:V_QTDE_TEMP,0) > 0) THEN
        BEGIN
          SELECT FIRST 1 CAST(DATA AS DATE) FROM R_ANDAMENTO
          WHERE PEDIDO_ID = :PEDIDO_ID
          AND TB_TIPO_ANDAMENTO_ID = :V_ANDAMENTO_MEDIA
          INTO :V_DATA_MEDIA;
          V_DATA_PROTOCOLO = CAST(:DATA AS DATE);
          QTDE_DIAS_APOS_PROTOCOLAR = :V_DATA_MEDIA - :V_DATA_PROTOCOLO;
        END
      END
      else
      BEGIN
        --PEGAR PELA DATA DO ultimo andamento
        V_DATA_MEDIA = CAST(:V_DATA_ULTIMO_ANDAMENTO AS DATE);
        V_DATA_PROTOCOLO = CAST(:DATA AS DATE);
        QTDE_DIAS_APOS_PROTOCOLAR = :V_DATA_MEDIA - :V_DATA_PROTOCOLO;
      END

      SELECT FIRST 1 natureza_titulo_id from r_pedido_item
      where pedido_id = :pedido_id
      into :V_natureza_titulo_id;

      select CATEGORIA_ATO, descricao from g_natureza_titulo
      where natureza_titulo_id = :v_natureza_titulo_id
      into :CATEGORIA_ATO, :descricao_natureza;

      select descricao from r_tb_titulo
      where  tb_titulo_id = :V_TITULO_ID
      into :descricao_titulo;


      select TA.descricao from R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA
      where A.tb_tipo_andamento_id = TA.tb_tipo_andamento_id
      AND A.andamento_id = :andamento_id
      into :descricao_andamento;

      SUSPEND;
      D_ULTIMO_PROTOCOLO_ID = :PROTOCOLO_ID;
    END
  END
END ^

ALTER PROCEDURE R_NOME_USUARIO (V_USUARIO_ID VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (LOGIN VARCHAR(30) CHARACTER SET ISO8859_1,
NOME_COMPLETO VARCHAR(120) CHARACTER SET ISO8859_1,
ULTIMO_LOGIN_REGS TIMESTAMP,
ANDAMENTO_PADRAO NUMERIC(12, 2),
DESCRICAO_TIPO_ANDAMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
ANDAMENTO_PADRAO2 NUMERIC(12, 2),
DESCRICAO_TIPO_ANDAMENTO2 VARCHAR(60) CHARACTER SET ISO8859_1,
PODE_ALTERAR_CAIXA VARCHAR(1) CHARACTER SET ISO8859_1)
AS 
BEGIN
  SELECT LOGIN, NOME_COMPLETO, ULTIMO_LOGIN_REGS, 
         ANDAMENTO_PADRAO, ANDAMENTO_PADRAO2, 
         PODE_ALTERAR_CAIXA
  FROM G_USUARIO
  WHERE USUARIO_ID = :V_USUARIO_ID
  INTO :LOGIN, :NOME_COMPLETO, :ULTIMO_LOGIN_REGS,
         :ANDAMENTO_PADRAO, ANDAMENTO_PADRAO2,
         :PODE_ALTERAR_CAIXA ;

  SELECT DESCRICAO
  FROM R_TB_TIPO_ANDAMENTO
  WHERE TB_TIPO_ANDAMENTO_ID = :ANDAMENTO_PADRAO
  INTO :DESCRICAO_TIPO_ANDAMENTO;
  
  SELECT DESCRICAO
  FROM R_TB_TIPO_ANDAMENTO
  WHERE TB_TIPO_ANDAMENTO_ID = :ANDAMENTO_PADRAO2
  INTO :DESCRICAO_TIPO_ANDAMENTO2;

  SUSPEND;
END ^

ALTER PROCEDURE R_NOTAS_DO_PROTOCOLO (V_PEDIDO_ID VARCHAR(10) CHARACTER SET ISO8859_1)
RETURNS (NUMERO_RPS INTEGER,
NUMERO_NOTA INTEGER,
SERIE_NOTA VARCHAR(10) CHARACTER SET ISO8859_1,
DATA_EMISSAO TIMESTAMP,
DATA_ENVIO TIMESTAMP,
VALOR_NOTA NUMERIC(18, 2),
TOMADOR_CNPJ VARCHAR(20) CHARACTER SET ISO8859_1,
TOMADOR_NOME VARCHAR(260) CHARACTER SET ISO8859_1,
ITEM_DESCRICAO VARCHAR(3000) CHARACTER SET ISO8859_1,
CHAVE_NOTA VARCHAR(260) CHARACTER SET ISO8859_1,
DESCRICAO_SITUACAO VARCHAR(100) CHARACTER SET ISO8859_1,
MENSAGEM_ERRO VARCHAR(10000) CHARACTER SET ISO8859_1,
SITUACAO INTEGER,
WEB_COD_VERIFICACAO VARCHAR(10) CHARACTER SET ISO8859_1,
EPOCA VARCHAR(20) CHARACTER SET ISO8859_1)
AS 
declare variable v_mensagem_erro varchar(10000);
  declare variable v_data_protocolo date;
BEGIN
  select data from r_protocolo
  where pedido_id = :v_pedido_id
  and ((tipo_protocolo = '1') or (tipo_protocolo = '3'))
  into :v_data_protocolo;

  FOR SELECT 'ANTIGA' AS EPOCA, NFSE_ID, IDE_NNFS, IDE_SERIE, IDE_DEMISSAO, WEB_DHRECEBTO,
          VALOR_SERVICOS, ITEM_DESCRICAO, TOMADOR_CNPJ, TOMADOR_RAZAOSOCIAL,
          WEB_CHAVE, SITUACAO, WEB_XMOTIVO, WEB_COD_VERIFICACAO FROM C_NFSE_ANTIGA
        WHERE TABELA = 'R_PEDIDO'
        AND CAMPO_ID = :V_PEDIDO_ID
        and situacao in (0,1,2,3,9) --pendente, emitir, enviada, erro
        union all
        SELECT 'NOVA' AS EPOCA, NFSE_ID, IDE_NNFS, IDE_SERIE, IDE_DEMISSAO, WEB_DHRECEBTO,
          VALOR_SERVICOS, ITEM_DESCRICAO, TOMADOR_CNPJ, TOMADOR_RAZAOSOCIAL,
          WEB_CHAVE, SITUACAO, WEB_XMOTIVO, WEB_COD_VERIFICACAO FROM C_NFSE
        WHERE TABELA = 'R_PEDIDO'
        AND CAMPO_ID = :V_PEDIDO_ID
        and situacao in (0,1,2,3,9) --pendente, emitir, enviada, erro
        order by 2
        INTO :EPOCA, :NUMERO_RPS, :NUMERO_NOTA, :SERIE_NOTA, :DATA_EMISSAO, :DATA_ENVIO,
          :VALOR_NOTA, :ITEM_DESCRICAO, :TOMADOR_CNPJ, TOMADOR_NOME,
          :CHAVE_NOTA, :SITUACAO, v_mensagem_erro, :WEB_COD_VERIFICACAO DO
  BEGIN
      MENSAGEM_ERRO = '';
      if (:SITUACAO = 0) then
      begin
        DESCRICAO_SITUACAO = 'Agendamento, aguardando emissão';
      end
      if (:SITUACAO = 1) then
      begin
        DESCRICAO_SITUACAO = 'Pronto para envio';
      end
      else if (:SITUACAO = 2) then
      begin
        DESCRICAO_SITUACAO = 'RPS enviada para prefeitura';
      end
      else if (:SITUACAO = 3) then
      begin
        DESCRICAO_SITUACAO = 'Emitida';
      end
      else if (:SITUACAO = 4) then
      begin
        DESCRICAO_SITUACAO = 'Cancelada';
      end
      else if (:SITUACAO = 9) then
      begin
        DESCRICAO_SITUACAO = 'ERRO';
        MENSAGEM_ERRO = :V_MENSAGEM_ERRO;
      end
      else
      begin
        DESCRICAO_SITUACAO = '';
      end
      SUSPEND;
  END
END ^

ALTER PROCEDURE R_NOTAS_DUPLICADAS (DATA_INICIAL_PERIODO VARCHAR(20) CHARACTER SET ISO8859_1,
DATA_FINAL_PERIODO VARCHAR(20) CHARACTER SET ISO8859_1,
DATA_INICIAL_BUSCA VARCHAR(20) CHARACTER SET ISO8859_1,
TAMANHO_CARACTER_CERT INTEGER,
TAMANHO_CARACTER_PROT INTEGER)
RETURNS (NUMERO_NOTA INTEGER,
NUMERO_NOTA_CORRETA INTEGER,
DATA_NOTA_CORRETA DATE,
BASE_CALCULO NUMERIC(14, 2),
DESCRICAO VARCHAR(100) CHARACTER SET ISO8859_1)
AS 
declare variable qtde_duplicidade integer;
  declare variable tamanho_cert integer;
  declare variable tamanho_eridf integer;
  declare variable tamanho_prot integer;
begin
  tamanho_cert = (:tamanho_caracter_cert + 18);
  tamanho_eridf = (:tamanho_caracter_cert + 14);
  tamanho_prot = (:tamanho_caracter_prot + 11);

  for select count(*),
      substring(trim(cast(trim(item_descricao) as varchar(1000))) from 1 for (cast(:tamanho_cert as integer))),
      base_calculo
      from c_nfse
      where cast(ide_demissao as date) between cast(:data_inicial_busca as date) and cast(:data_final_periodo as date)
      and substring(trim(cast(trim(item_descricao) as varchar(1000))) from 1 for  16) = 'Ped. de certidao'
      group by 2,3
      having count(*) > 1
      union
      select count(*),
      substring(trim(cast(trim(item_descricao) as varchar(1000))) from 1 for (cast(:tamanho_eridf as integer))),
      base_calculo
      from c_nfse
      where cast(ide_demissao as date) between cast(:data_inicial_busca as date) and cast(:data_final_periodo as date)
      and substring(trim(cast(trim(item_descricao) as varchar(1000))) from 1 for 12) = 'Ped.Certidao'
      group by 2,3
      having count(*) > 1
      union
      select count(*),
      substring(trim(cast(trim(item_descricao) as varchar(1000))) from 1 for (cast(:tamanho_prot as integer))),
      base_calculo
      from c_nfse
      where cast(ide_demissao as date) between cast(:data_inicial_busca as date) and cast(:data_final_periodo as date)
      and substring(trim(cast(trim(item_descricao) as varchar(1000))) from 1 for 9) = 'Protocolo'
      group by 2,3
      having count(*) > 1
      into :qtde_duplicidade, :descricao, :base_calculo do
  begin
   for select ide_nnfs, base_calculo from c_nfse
        where trim(item_descricao) like :descricao||'%'
        and cast(ide_demissao as date) between cast(:data_inicial_periodo as date) and cast(:data_final_periodo as date)
        and base_calculo = :base_calculo
        order by ide_nnfs
        into :numero_nota, :base_calculo do
    begin
      select first 1 ide_nnfs, cast(ide_demissao as date) from c_nfse
      where trim(item_descricao) like :descricao||'%'
      and base_calculo = :base_calculo
      order by ide_nnfs
      into :numero_nota_correta, :data_nota_correta;

      if (coalesce(:numero_nota,0) <> coalesce(:numero_nota_correta,0)) then
      begin
        suspend;
      end
    end
  end
end ^

ALTER PROCEDURE R_NUMERO_PEDIDO (V_NUMERO_ORDEM VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO_PROTOCOLO VARCHAR(5) CHARACTER SET ISO8859_1)
RETURNS (PEDIDO_ID NUMERIC(12, 2))
AS 
BEGIN
  SELECT PEDIDO_ID
  FROM R_PROTOCOLO
  WHERE NUMERO_ORDEM = :V_NUMERO_ORDEM
  AND TIPO_PROTOCOLO = :V_TIPO_PROTOCOLO
  INTO :PEDIDO_ID;
  SUSPEND;
END ^

ALTER PROCEDURE R_ONUS_DO_PROTOCOLO (V_PEDIDO_ID VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO NUMERIC(12, 2),
ATO_TIPO VARCHAR(1) CHARACTER SET ISO8859_1,
ATO_NUMERO NUMERIC(12, 2),
NATUREZA_TITULO_ID NUMERIC(12, 2),
DATA_LANC TIMESTAMP,
DATA_CONF TIMESTAMP,
DATA_BAIXA TIMESTAMP,
IMOVEL_ID NUMERIC(12, 2))
AS 
BEGIN
  FOR SELECT DISTINCT PN.NUMERO, PN.TIPO_REGISTRO,
             PN.ATO_TIPO, PN.ATO_NUMERO
      FROM   R_PEDIDO_ITEM_NUMERO PN, R_PEDIDO_ITEM PI
      WHERE  PN.PEDIDO_ITEM_ID = PI.PEDIDO_ITEM_ID
      AND    PI.PEDIDO_ID = :V_PEDIDO_ID
      ORDER BY PN.NUMERO
      INTO   :NUMERO, :TIPO_REGISTRO, :ATO_TIPO,
             :ATO_NUMERO DO
  BEGIN
    SELECT FIRST 1 IH.NATUREZA_TITULO_ID, IH.DATA_LANC,
           IH.DATA_CONF, IH.DATA_BAIXA, I.IMOVEL_ID
    FROM   R_IMOVEL I LEFT OUTER JOIN R_IMOVEL_HISTORICO IH
    ON     I.IMOVEL_ID = IH.IMOVEL_ID
    WHERE  I.TIPO_REGISTRO = :TIPO_REGISTRO
    AND    I.NUMERO = :NUMERO
    AND    (IH.ATO_TIPO = :ATO_TIPO OR IH.ATO_TIPO_BAIXA = :ATO_TIPO)
    AND    (IH.ATO_NUMERO = :ATO_NUMERO OR IH.ATO_NUMERO_BAIXA = :ATO_NUMERO)
    ORDER BY IH.IMOVEL_HISTORICO_ID
    INTO   :NATUREZA_TITULO_ID, :DATA_LANC,
           :DATA_CONF, :DATA_BAIXA,
           :IMOVEL_ID;
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_PEDIDO_ITEM_ON_CALC (V_PEDIDO_ITEM_ID INTEGER)
RETURNS (DADOS_CERTIDAO_CALC VARCHAR(2000) CHARACTER SET ISO8859_1,
NATUREZA_TITULO_CALC VARCHAR(260) CHARACTER SET ISO8859_1,
TIPO_TITULO_CALC VARCHAR(1) CHARACTER SET ISO8859_1,
MATRICULA_CALC VARCHAR(1) CHARACTER SET ISO8859_1,
EMOLUMENTO_CALC VARCHAR(260) CHARACTER SET ISO8859_1,
VALOR_MANUAL_CALC VARCHAR(1) CHARACTER SET ISO8859_1,
USAR_LANCAR_ITENS_AUT_CALC VARCHAR(1) CHARACTER SET ISO8859_1,
EDITAR_QUANTIDADE_CALC VARCHAR(1) CHARACTER SET ISO8859_1,
NOME_AUTORIZOU_CALC VARCHAR(30) CHARACTER SET ISO8859_1,
COMPLEMENTO_CALC VARCHAR(100) CHARACTER SET ISO8859_1,
VALOR_TOTAL_CALC DINHEIRO,
NUMERO_NFSE INTEGER,
CODIGO_NFSE VARCHAR(15) CHARACTER SET ISO8859_1,
DATA_NFSE TIMESTAMP,
DATA_RPS TIMESTAMP,
QTDE_SELO INTEGER)
AS 
DECLARE VARIABLE V_DADOS_ITENS VARCHAR(4000);
  DECLARE VARIABLE V_COMPLEMENTO VARCHAR(500);

  DECLARE VARIABLE V_TIPO_PEDIDO VARCHAR(1);
  DECLARE VARIABLE V_NATUREZA_TITULO_ID INTEGER;
  DECLARE VARIABLE V_EMOLUMENTO_ID INTEGER;
  DECLARE VARIABLE V_VALOR_EMOLUMENTO DINHEIRO;
  DECLARE VARIABLE V_VALOR_FUNDO_RI DINHEIRO;
  DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA DINHEIRO;
  DECLARE VARIABLE V_VALOR_ISS DINHEIRO;
  DECLARE VARIABLE V_VALOR_DESCONTO DINHEIRO;
  DECLARE VARIABLE V_VALOR_OUTROS DINHEIRO;

  DECLARE VARIABLE V_NOME VARCHAR(120);
  DECLARE VARIABLE V_CPF VARCHAR(30);
  DECLARE VARIABLE V_DOCUMENTO VARCHAR(30);
  DECLARE VARIABLE V_ESTADO_CIVIL VARCHAR(3);
  DECLARE VARIABLE V_TIPO_REGISTRO VARCHAR(1);
  DECLARE VARIABLE V_NUMERO INTEGER;
  DECLARE VARIABLE V_NOME_SOLTEIRO VARCHAR(120);
  DECLARE VARIABLE V_CONJUGE VARCHAR(120);
  DECLARE VARIABLE V_CONJUGE_CPF VARCHAR(30);
  DECLARE VARIABLE V_CONJUGE_DOCUMENTO VARCHAR(30);
  DECLARE VARIABLE V_CONJUGE_SOLTEIRO VARCHAR(120);

  DECLARE VARIABLE ID_CASADO INTEGER;
  DECLARE VARIABLE ID_SOLTEIRO INTEGER;
  DECLARE VARIABLE ID_DIVORCIADO INTEGER;
  DECLARE VARIABLE ID_SEPARADO INTEGER;
  DECLARE VARIABLE ID_SEPARADO_JUDICIALMENTE INTEGER;
  DECLARE VARIABLE ID_NAO_DECLARADO INTEGER;
  DECLARE VARIABLE ID_JURIDICO INTEGER;
  DECLARE VARIABLE ID_MENOR INTEGER;
  DECLARE VARIABLE ID_DESQUITADO INTEGER;
  DECLARE VARIABLE ID_ESPOLIO INTEGER;
  DECLARE VARIABLE ID_COMPANHEIRO INTEGER;
  DECLARE VARIABLE ID_VIUVO INTEGER;

  DECLARE VARIABLE V_ATO_TIPO VARCHAR(1);
  DECLARE VARIABLE V_ATO_NUMERO INTEGER;
  DECLARE VARIABLE V_LOGRADOURO VARCHAR(260);
  DECLARE VARIABLE V_USUARIO_DESCONTO_ID INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_BUSCA INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_FOLHA_EXCEDENTE INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_ATOS_ACRESCIDOS INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_QUESITOS INTEGER;

  DECLARE VARIABLE V_PEDIDO_ID INTEGER;
  DECLARE VARIABLE V_USAR_NFSE VARCHAR(1);
  DECLARE VARIABLE V_NFSE_ID INTEGER;

  declare variable V_QTDE_SELO INTEGER;
  declare variable V_PEDIDO_ITEM_NUMERO_ID INTEGER;
BEGIN
  V_QTDE_SELO = 0;
  QTDE_SELO = 0;
  SELECT I.TIPO_PEDIDO, I.NATUREZA_TITULO_ID, I.EMOLUMENTO_ID, I.VALOR_EMOLUMENTO,
        I.VALOR_FUNDO_RI, I.VALOR_TAXA_JUDICIARIA, I.VALOR_ISS, I.VALOR_DESCONTO,
        I.USUARIO_DESCONTO_ID, I.QUANTIDADE_BUSCA, I.QUANTIDADE_FOLHA_EXCEDENTE,
        I.QUANTIDADE_ATOS_ACRESCIDOS, I.QUANTIDADE_QUESITOS, I.PEDIDO_ID,
        P.NFSE_RPS, I.VALOR_OUTROS
  FROM R_PEDIDO_ITEM I, R_PEDIDO P
  WHERE P.PEDIDO_ID = I.PEDIDO_ID
  AND I.PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
  INTO :V_TIPO_PEDIDO, :V_NATUREZA_TITULO_ID, :V_EMOLUMENTO_ID, :V_VALOR_EMOLUMENTO,
    :V_VALOR_FUNDO_RI, :V_VALOR_TAXA_JUDICIARIA, :V_VALOR_ISS, :V_VALOR_DESCONTO,
    :V_USUARIO_DESCONTO_ID, :V_QUANTIDADE_BUSCA, :V_QUANTIDADE_FOLHA_EXCEDENTE,
    :V_QUANTIDADE_ATOS_ACRESCIDOS, :V_QUANTIDADE_QUESITOS, :V_PEDIDO_ID,
    :V_NFSE_ID, :V_VALOR_OUTROS;

  --VERIFICAR SE TEM SELOS
  SELECT COUNT(*) FROM G_SELO_LIVRO
  WHERE TABELA = 'R_PEDIDO_ITEM'
  AND CAMPO_ID = :V_PEDIDO_ITEM_ID
  AND COALESCE(SELO_SITUACAO_ID,0) = 2
  INTO :V_QTDE_SELO;

  QTDE_SELO = :V_QTDE_SELO;

  --VERIFICAR SE VAI USAR NFSE
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('NFSE','CARTORIO','USAR_NFSE',5)
  INTO :V_USAR_NFSE;

  IF ((COALESCE(:V_USAR_NFSE,'') = 'S') AND (COALESCE(:V_NFSE_ID,0) > 0)) THEN
  BEGIN
    SELECT IDE_NNFS, WEB_COD_VERIFICACAO, IDE_DEMISSAO, WEB_DHRECEBTO
    FROM C_NFSE
    WHERE NFSE_ID = :V_NFSE_ID
    INTO :NUMERO_NFSE, :CODIGO_NFSE, :DATA_RPS, :DATA_NFSE;
  END

  --MONTAR DADOS DA CERTIDAO
  V_DADOS_ITENS = '';
  FOR SELECT N.PEDIDO_ITEM_NUMERO_ID, N.NOME, N.CPF, N.DOCUMENTO, N.ESTADO_CIVIL, N.TIPO_REGISTRO, N.NUMERO,
        N.NOME_SOLTEIRO, N.CONJUGE, N.CONJUGE_CPF, N.CONJUGE_DOCUMENTO,
        N.CONJUGE_SOLTEIRO, N.ATO_TIPO,  N.ATO_NUMERO, N.LOGRADOURO
      FROM R_PEDIDO_ITEM_NUMERO N
      WHERE N.PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
      INTO :V_PEDIDO_ITEM_NUMERO_ID, :V_NOME, :V_CPF, :V_DOCUMENTO, :V_ESTADO_CIVIL, :V_TIPO_REGISTRO, :V_NUMERO,
        :V_NOME_SOLTEIRO, :V_CONJUGE, :V_CONJUGE_CPF, :V_CONJUGE_DOCUMENTO,
        :V_CONJUGE_SOLTEIRO, :V_ATO_TIPO, :V_ATO_NUMERO, :V_LOGRADOURO DO
  BEGIN
    --VERIFICAR SE TEM SELOS
    if (COALESCE(:V_QTDE_SELO,0) = 0) THEN
    begin
      SELECT COUNT(*) FROM G_SELO_LIVRO
      WHERE TABELA = 'R_PEDIDO_ITEM_NUMERO'
      AND CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID
      AND COALESCE(SELO_SITUACAO_ID,0) = 2
      INTO :V_QTDE_SELO;

      QTDE_SELO = :QTDE_SELO + :V_QTDE_SELO;
    end

    IF (CHAR_LENGTH(:V_DADOS_ITENS) < 3800) THEN
    BEGIN
      IF (COALESCE(:V_DADOS_ITENS,'') <> '') THEN
      BEGIN
        V_DADOS_ITENS = :V_DADOS_ITENS || Ascii_Char(13);
      END
      V_DADOS_ITENS = :V_DADOS_ITENS || '* ';
      IF (COALESCE(:V_NOME,'') <> '') THEN --CERTIDAO PESSOA
      BEGIN
        IF (COALESCE(:V_TIPO_PEDIDO,'') = '1') THEN -- OUTROS FINS
        BEGIN
          V_DADOS_ITENS = :V_DADOS_ITENS || '(OUTROS FINS) - ';
        END
        ELSE IF (COALESCE(:V_TIPO_PEDIDO,'') = '2') THEN -- CODHAB
        BEGIN
          V_DADOS_ITENS = :V_DADOS_ITENS || '(CODHAB) - ';
        END
        V_DADOS_ITENS = :V_DADOS_ITENS || 'Nome: '||:V_NOME;
        IF (COALESCE(:V_CPF,'') <> '') THEN
        BEGIN
          SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CPF)
          INTO :V_CPF;
          if (char_length(:v_cpf) = 18) then
          begin
            V_DADOS_ITENS = :V_DADOS_ITENS ||', CNPJ: '||:V_CPF;
          end
          else
          begin
            V_DADOS_ITENS = :V_DADOS_ITENS ||', CPF: '||:V_CPF;
          end
        END
        IF (COALESCE(:V_DOCUMENTO,'') <> '') THEN
        BEGIN
          V_DADOS_ITENS = :V_DADOS_ITENS ||', Doc.: '||:V_DOCUMENTO;
        END
        IF (COALESCE(:V_ESTADO_CIVIL,'') <> '') THEN
        BEGIN
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_CASADO',1)
          INTO :ID_CASADO;
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_SOLTEIRO',1)
          INTO :ID_SOLTEIRO;
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_DIVORCIADO',1)
          INTO :ID_DIVORCIADO;
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_SEPARADO',1)
          INTO :ID_SEPARADO;
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_SEPARADO_JUDICIALMENTE',1)
          INTO :ID_SEPARADO_JUDICIALMENTE;
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_NAO_DECLARADO',1)
          INTO :ID_NAO_DECLARADO;
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_JURIDICO',1)
          INTO :ID_JURIDICO;
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_MENOR',1)
          INTO :ID_MENOR;
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_DESQUITADO',1)
          INTO :ID_DESQUITADO;
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_ESPOLIO',1)
          INTO :ID_ESPOLIO;
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_COMPANHEIRO',1)
          INTO :ID_COMPANHEIRO;
          SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','ESTADO_CIVIL_VIUVO',1)
          INTO :ID_VIUVO;
  
          IF (:V_ESTADO_CIVIL = :ID_CASADO) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: Casado(a)';
          END
          ELSE IF (:V_ESTADO_CIVIL = :ID_SOLTEIRO) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: Solteiro(a)';
          END
          ELSE IF (:V_ESTADO_CIVIL = :ID_DIVORCIADO) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: Divorciado(a)';
          END
          ELSE IF (:V_ESTADO_CIVIL = :ID_SEPARADO) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: Separado(a)';
          END
          ELSE IF (:V_ESTADO_CIVIL = :ID_SEPARADO_JUDICIALMENTE) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: Separado(a) judicialmente';
          END
          ELSE IF (:V_ESTADO_CIVIL = :ID_NAO_DECLARADO) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: Não Declarado';
          END
          ELSE IF (:V_ESTADO_CIVIL = :ID_JURIDICO) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: Jurídico';
          END
          ELSE IF (:V_ESTADO_CIVIL = :ID_MENOR) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: Menor';
          END
          ELSE IF (:V_ESTADO_CIVIL = :ID_DESQUITADO) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: Desquitado(a)';
          END
          ELSE IF (:V_ESTADO_CIVIL = :ID_ESPOLIO) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: Espólio';
          END
          ELSE IF (:V_ESTADO_CIVIL = :ID_COMPANHEIRO) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: Companheiro(a)';
          END
          ELSE IF (:V_ESTADO_CIVIL = :ID_VIUVO) THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||', Est.Civil: viúvo(a)';
          END
        END
        IF (COALESCE(:V_NOME_SOLTEIRO,'') <> '') THEN
        BEGIN
          V_DADOS_ITENS = :V_DADOS_ITENS ||', Que anteriormente assinava: '||:V_NOME_SOLTEIRO;
        END
        IF (COALESCE(:V_CONJUGE,'') <> '') THEN
        BEGIN
          V_DADOS_ITENS = :V_DADOS_ITENS ||', Cônjuge: '||:V_CONJUGE;
        END
        IF (COALESCE(:V_CONJUGE_CPF,'') <> '') THEN
        BEGIN
          SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CONJUGE_CPF)
          INTO :V_CONJUGE_CPF;
          if (char_length(:v_cpf) = 18) then
          begin
            V_DADOS_ITENS = :V_DADOS_ITENS ||', CNPJ: '||:V_CONJUGE_CPF;
          end
          else
          begin
            V_DADOS_ITENS = :V_DADOS_ITENS ||', CPF: '||:V_CONJUGE_CPF;
          end
        END
        IF (COALESCE(:V_CONJUGE_DOCUMENTO,'') <> '') THEN
        BEGIN
          V_DADOS_ITENS = :V_DADOS_ITENS ||', Doc. Conj: '||:V_CONJUGE_DOCUMENTO;
        END
        IF (COALESCE(:V_CONJUGE_SOLTEIRO,'') <> '') THEN
        BEGIN
          V_DADOS_ITENS = :V_DADOS_ITENS ||', Que anteriormente assinava: '||:V_CONJUGE_SOLTEIRO;
        END
      END
      ELSE --CERTIDAO DE IMOVEL
      BEGIN
        IF (COALESCE(:V_TIPO_REGISTRO,'') <> '') THEN
        BEGIN
          IF (:V_TIPO_REGISTRO = 'M') THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||'Mat.';
          END
          ELSE IF (:V_TIPO_REGISTRO = 'T') THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||'Transc.';
          END
          ELSE IF (:V_TIPO_REGISTRO = 'I') THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||'Insc.';
          END
          ELSE IF (:V_TIPO_REGISTRO = 'A') THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS ||'Reg. Aux.';
          END
        END
        IF (COALESCE(:V_NUMERO,'') <> '') THEN
        BEGIN
          V_DADOS_ITENS = :V_DADOS_ITENS || ' '||:V_NUMERO;
        END
        IF (COALESCE(:V_ATO_NUMERO,'') <> '') THEN
        BEGIN
          IF (COALESCE(:V_ATO_TIPO,'') = 'A') THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS || ', AV-'||:V_ATO_NUMERO;
          END
          IF (COALESCE(:V_ATO_TIPO,'') = 'R') THEN
          BEGIN
            V_DADOS_ITENS = :V_DADOS_ITENS || ', R-'||:V_ATO_NUMERO;
          END
        END
        IF (COALESCE(:V_LOGRADOURO,'') <> '') THEN
        BEGIN
          V_DADOS_ITENS = :V_DADOS_ITENS || ', '||:V_LOGRADOURO;
        END
      END
    END
  END
  DADOS_CERTIDAO_CALC = SUBSTRING(:V_DADOS_ITENS FROM 1 FOR 2000);

  NATUREZA_TITULO_CALC = NULL;
  TIPO_TITULO_CALC = NULL;
  MATRICULA_CALC = NULL;
  EMOLUMENTO_CALC = NULL;
  VALOR_MANUAL_CALC = NULL;
  USAR_LANCAR_ITENS_AUT_CALC = NULL;
  EDITAR_QUANTIDADE_CALC = NULL;
  IF (COALESCE(:V_NATUREZA_TITULO_ID,0) > 0) THEN
  BEGIN
    SELECT DESCRICAO, TIPO_TITULO, ABRIR_MATRICULA, DESCRICAO_EMOLUMENTO,
      VALOR_MANUAL, USAR_LANCAR_ITENS_AUTOMATICOS, EDITAR_QUANTIDADE
    FROM R_BUSCA_NATUREZA_TITULO(:V_NATUREZA_TITULO_ID, :V_EMOLUMENTO_ID)
    INTO :NATUREZA_TITULO_CALC, :TIPO_TITULO_CALC, :MATRICULA_CALC, :EMOLUMENTO_CALC,
      :VALOR_MANUAL_CALC, :USAR_LANCAR_ITENS_AUT_CALC, :EDITAR_QUANTIDADE_CALC;
  END

  VALOR_TOTAL_CALC = (COALESCE(:V_VALOR_EMOLUMENTO,0)+COALESCE(:V_VALOR_FUNDO_RI,0)+
    COALESCE(:V_VALOR_TAXA_JUDICIARIA,0)+COALESCE(:V_VALOR_ISS,0) + COALESCE(:V_VALOR_OUTROS,0)) - (COALESCE(:V_VALOR_DESCONTO,0));

  VALOR_TOTAL_CALC = CAST(:VALOR_TOTAL_CALC AS NUMERIC(18,2));

  NOME_AUTORIZOU_CALC = NULL;
  IF (COALESCE(:V_USUARIO_DESCONTO_ID,0) > 0) THEN
  BEGIN
    SELECT LOGIN FROM R_NOME_USUARIO(:V_USUARIO_DESCONTO_ID)
    INTO :NOME_AUTORIZOU_CALC;
  END

  V_COMPLEMENTO = '';
  IF (COALESCE(:V_QUANTIDADE_BUSCA,0) > 0) THEN
  BEGIN
    IF (COALESCE(:V_QUANTIDADE_BUSCA,0) > 1) THEN
    BEGIN
      V_COMPLEMENTO = :V_QUANTIDADE_BUSCA||' Buscas';
    END
    ELSE
    BEGIN
      V_COMPLEMENTO = :V_QUANTIDADE_BUSCA||' Busca';
    END
  END
  IF (COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0) > 0) THEN
  BEGIN
    IF (COALESCE(:V_QUANTIDADE_FOLHA_EXCEDENTE,0) > 1) THEN
    BEGIN
      IF (COALESCE(:V_COMPLEMENTO,'') = '') THEN
      BEGIN
        V_COMPLEMENTO = :V_QUANTIDADE_FOLHA_EXCEDENTE||' Folhas Excedentes';
      END
      ELSE
      BEGIN
        V_COMPLEMENTO = ' e '||:V_QUANTIDADE_FOLHA_EXCEDENTE||' Folhas Excedentes';
      END
    END
    ELSE
    BEGIN
      IF (COALESCE(:V_COMPLEMENTO,'') = '') THEN
      BEGIN
        V_COMPLEMENTO = :V_QUANTIDADE_FOLHA_EXCEDENTE||' Folha Excedente';
      END
      ELSE
      BEGIN
        V_COMPLEMENTO = ' e '||:V_QUANTIDADE_FOLHA_EXCEDENTE||' Folha Excedente';
      END
    END
  END
  IF (COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0) > 0) THEN
  BEGIN
    IF (COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0) > 1) THEN
    BEGIN
      IF (COALESCE(:V_COMPLEMENTO,'') = '') THEN
      BEGIN
        V_COMPLEMENTO = :V_QUANTIDADE_ATOS_ACRESCIDOS||' Atos acrescidos';
      END
      ELSE
      BEGIN
        V_COMPLEMENTO = ' e '||:V_QUANTIDADE_ATOS_ACRESCIDOS||' Atos acrescidos';
      END
    END
    ELSE
    BEGIN
      IF (COALESCE(:V_COMPLEMENTO,'') = '') THEN
      BEGIN
        V_COMPLEMENTO = :V_QUANTIDADE_ATOS_ACRESCIDOS||' Ato acrescido';
      END
      ELSE
      BEGIN
        V_COMPLEMENTO = ' e '||:V_QUANTIDADE_ATOS_ACRESCIDOS||' Ato acrescido';
      END
    END
  END
  IF (COALESCE(:V_QUANTIDADE_QUESITOS,0) > 0) THEN
  BEGIN
    IF (COALESCE(:V_QUANTIDADE_QUESITOS,0) > 1) THEN
    BEGIN
      IF (COALESCE(:V_COMPLEMENTO,'') = '') THEN
      BEGIN
        V_COMPLEMENTO = :V_QUANTIDADE_QUESITOS||' Quesitos';
      END
      ELSE
      BEGIN
        V_COMPLEMENTO = ' e '||:V_QUANTIDADE_QUESITOS||' Quesitos';
      END
    END
    ELSE
    BEGIN
      IF (COALESCE(:V_COMPLEMENTO,'') = '') THEN
      BEGIN
        V_COMPLEMENTO = :V_QUANTIDADE_QUESITOS||' Quesito';
      END
      ELSE
      BEGIN
        V_COMPLEMENTO = ' e '||:V_QUANTIDADE_QUESITOS||' Quesito';
      END
    END
  END
  COMPLEMENTO_CALC = SUBSTRING(:V_COMPLEMENTO FROM 1 FOR 100);

  SUSPEND;
END ^

ALTER PROCEDURE R_PESQUISA_CNIB (V_LRI_XML_ID INTEGER,
V_STATUS VARCHAR(5) CHARACTER SET ISO8859_1,
V_LRI_ID_INICIAL INTEGER,
V_LRI_ID_FINAL INTEGER,
V_PROTOCOLO_INDISPONIBILIDADE VARCHAR(260) CHARACTER SET ISO8859_1,
V_NUMERO_PROCESSO VARCHAR(260) CHARACTER SET ISO8859_1,
V_TB_ORIGEM_LRI_ID INTEGER,
V_CANCELAMENTO_INDIPONIBILIDADE VARCHAR(260) CHARACTER SET ISO8859_1,
V_CPF_CNPJ VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_IMPORTACAO_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_IMPORTACAO_FINAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_PEDIDO_INICIAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_PEDIDO_FINAL VARCHAR(20) CHARACTER SET ISO8859_1,
V_FORUM_VARA VARCHAR(260) CHARACTER SET ISO8859_1)
RETURNS (LRI_XML_ID INTEGER,
DATA_IMPORTACAO DATAHORA,
USUARIO_FEZ_IMPORTACAO VARCHAR(120) CHARACTER SET ISO8859_1,
LRI_ID INTEGER,
OFICIO VARCHAR(260) CHARACTER SET ISO8859_1,
PROTOCOLO_PROCESSO VARCHAR(260) CHARACTER SET ISO8859_1,
TB_ORIGEM_LRI_ID INTEGER,
DESCRICAO_ORIGEM VARCHAR(260) CHARACTER SET ISO8859_1,
DATA DATAHORA,
USUARIO VARCHAR(260) CHARACTER SET ISO8859_1,
EMAIL VARCHAR(260) CHARACTER SET ISO8859_1,
TELEFONE VARCHAR(15) CHARACTER SET ISO8859_1,
FORUM_VARA VARCHAR(260) CHARACTER SET ISO8859_1,
DATA_PEDIDO DATAHORA,
CANCELAMENTO_TIPO VARCHAR(1) CHARACTER SET ISO8859_1,
OFICIO_CANCELAMENTO VARCHAR(260) CHARACTER SET ISO8859_1,
LRI_CANCELAMENTO_ID INTEGER,
DATA_CANCELAMENTO DATAHORA,
PESSOAS_ENVOLVIDAS VARCHAR(5000) CHARACTER SET ISO8859_1,
IMOVEIS_ENVOLVIDOS VARCHAR(5000) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_SQL BLOB;
  DECLARE VARIABLE V_USUARIO_ID INTEGER;
  DECLARE VARIABLE CPF_CNPJ VARCHAR(15);
  DECLARE VARIABLE NOME VARCHAR(120);
  DECLARE VARIABLE TIPO_IMOVEL VARCHAR(1);
  DECLARE VARIABLE NUMERO INTEGER;
  DECLARE VARIABLE TIPO_IMOVEL_DESC VARCHAR(20);
BEGIN
  V_SQL = 'SELECT X.LRI_XML_ID, X.DATA_IMPORTACAO, X.USUARIO_ID_IMPORTACAO, L.LRI_ID, 
             L.OFICIO, L.PROTOCOLO_PROCESSO, L.TB_ORIGEM_LRI_ID, L.DATA, L.USUARIO, 
             L.EMAIL, L.TELEFONE, L.FORUM_VARA, L.DATA_PEDIDO             
           FROM R_LRI L LEFT JOIN R_LRI_XML X
           ON L.LRI_XML_ID = X.LRI_XML_ID
           WHERE L.LRI_ID > 0 ';
  --PELO ID DO XML
  IF (COALESCE(:V_LRI_XML_ID,0) > 0) THEN 
  BEGIN
    V_SQL = :V_SQL || ' AND X.LRI_XML_ID = '||:V_LRI_XML_ID;    
  END    
           
  --PELO ID DO LRI
  IF (COALESCE(:V_LRI_ID_INICIAL,0) > 0) THEN 
  BEGIN
    IF (COALESCE(:V_LRI_ID_FINAL,0) = 0) THEN 
    BEGIN
      V_LRI_ID_FINAL = :V_LRI_ID_INICIAL;
    END
    V_SQL = :V_SQL || ' AND L.LRI_ID BETWEEN '||:V_LRI_ID_INICIAL||' AND '||:V_LRI_ID_FINAL;
  END
  --PELO OFICIO/PROTOCOLOINDISPONIBILIDADE
  IF (COALESCE(:V_PROTOCOLO_INDISPONIBILIDADE,'') <> '') THEN 
  BEGIN
    V_SQL = :V_SQL || ' AND L.OFICIO LIKE '||:V_PROTOCOLO_INDISPONIBILIDADE;
  END
  --PELO PROCESSO
  IF (COALESCE(:V_NUMERO_PROCESSO,'') <> '') THEN 
  BEGIN
    V_SQL = :V_SQL || ' AND L.PROTOCOLO_PROCESSO LIKE '||:V_NUMERO_PROCESSO;
  END
  --PELO FORUM/VARA
  IF (COALESCE(:V_FORUM_VARA,'') <> '') THEN 
  BEGIN
    V_SQL = :V_SQL || ' AND L.FORUM_VARA LIKE '||:V_FORUM_VARA;
  END  
  --PELA ORIGEM
  IF (COALESCE(:V_TB_ORIGEM_LRI_ID,0) > 0) THEN 
  BEGIN
    V_SQL = :V_SQL || ' AND L.TB_ORIGEM_LRI_ID = '||:V_TB_ORIGEM_LRI_ID;
  END
  --PELA DATA DE IMPORTACAO/INCLUSAO
  IF (COALESCE(:V_DATA_IMPORTACAO_INICIAL,'') <> '') THEN 
  BEGIN
    IF (COALESCE(:V_DATA_IMPORTACAO_FINAL,'') = '') THEN 
    BEGIN
      V_DATA_IMPORTACAO_FINAL = :V_DATA_IMPORTACAO_INICIAL;
    END  
    V_SQL = :V_SQL || 'AND L.DATA BETWEEN CAST('||:V_DATA_IMPORTACAO_INICIAL||' AS TIMESTAMP) '||
                                     'AND CAST('||:V_DATA_IMPORTACAO_FINAL||' AS TIMESTAMP) + 0.99999 ';    
  END
  --PELA DATA DO PEDIDO NO CNIB
  IF (COALESCE(:V_DATA_PEDIDO_INICIAL,'') <> '') THEN 
  BEGIN
    IF (COALESCE(:V_DATA_PEDIDO_FINAL,'') = '') THEN 
    BEGIN
      V_DATA_PEDIDO_FINAL = :V_DATA_PEDIDO_INICIAL;
    END  
    V_SQL = :V_SQL || 'AND L.DATA_PEDIDO BETWEEN CAST('||:V_DATA_PEDIDO_INICIAL||' AS TIMESTAMP) '||
                                            'AND CAST('||:V_DATA_PEDIDO_FINAL||' AS TIMESTAMP) + 0.99999 ';
  END
  --PELO OFICIO DE CANCELAMENTO
  IF (COALESCE(:V_CANCELAMENTO_INDIPONIBILIDADE,'') <> '') THEN 
  BEGIN
    V_SQL = :V_SQL || ' AND ((SELECT COUNT(*) FROM R_LRI_CANCELAMENTO C, R_PESSOA_VINCULO V 
                             WHERE C.LRI_CANCELAMENTO_ID = V.LRI_CANCELAMENTO_ID
                             AND C.OFICIO_CANCELAMENTO LIKE '||''''||:V_CANCELAMENTO_INDIPONIBILIDADE||''''||') > 0
                             OR (SELECT COUNT(*) FROM R_LRI_CANCELAMENTO C, R_LRI_IMOVEL I
                             WHERE C.LRI_CANCELAMENTO_ID = I.LRI_CANCELAMENTO_ID
                             AND C.OFICIO_CANCELAMENTO LIKE '||''''||:V_CANCELAMENTO_INDIPONIBILIDADE||''''||') > 0)';
  END  
  --PELO CPF/CNPJ
  IF (COALESCE(:V_CPF_CNPJ,'') <> '') THEN 
  BEGIN
    V_SQL = :V_SQL || ' AND ((SELECT COUNT(*) FROM R_LRI L2, R_PESSOA_VINCULO V
                              WHERE L2.LRI_ID = L.LRI_ID
                              AND L2.LRI_ID = V.LRI_ID
                            AND V.CPF_CNPJ = '||''''||:V_CPF_CNPJ||''''||') > 0) ';
  END  

  FOR EXECUTE STATEMENT V_SQL
  INTO :LRI_XML_ID, :DATA_IMPORTACAO, :V_USUARIO_ID, :LRI_ID, :OFICIO, 
    :PROTOCOLO_PROCESSO, :TB_ORIGEM_LRI_ID, :DATA, :USUARIO, :EMAIL, 
    :TELEFONE, :FORUM_VARA, :DATA_PEDIDO DO
  BEGIN
    USUARIO_FEZ_IMPORTACAO = NULL;
    DESCRICAO_ORIGEM = '';
    IF (COALESCE(:V_USUARIO_ID,0) > 0) THEN
    BEGIN
      SELECT NOME_COMPLETO FROM G_USUARIO
      WHERE USUARIO_ID = :V_USUARIO_ID
      INTO :USUARIO_FEZ_IMPORTACAO;
    END
    IF (COALESCE(:TB_ORIGEM_LRI_ID,0)> 0) THEN
    BEGIN
      SELECT DESCRICAO FROM R_TB_ORIGEM_LRI
      WHERE TB_ORIGEM_LRI_ID = :TB_ORIGEM_LRI_ID
      INTO :DESCRICAO_ORIGEM;
    END

    LRI_CANCELAMENTO_ID = NULL;
    CANCELAMENTO_TIPO = '';
    OFICIO_CANCELAMENTO = '';
    DATA_CANCELAMENTO = NULL;
    SELECT FIRST 1 C.LRI_CANCELAMENTO_ID, C.CANCELAMENTO_TIPO, C.OFICIO_CANCELAMENTO, 
      C.DATA_CANCELAMENTO
    FROM R_LRI_CANCELAMENTO C, R_PESSOA_VINCULO V
    WHERE C.LRI_CANCELAMENTO_ID = V.LRI_CANCELAMENTO_ID
    AND V.LRI_ID = :LRI_ID
    UNION
    SELECT FIRST 1 C.LRI_CANCELAMENTO_ID, C.CANCELAMENTO_TIPO, C.OFICIO_CANCELAMENTO, 
      C.DATA_CANCELAMENTO
    FROM R_LRI_CANCELAMENTO C, R_LRI_IMOVEL I
    WHERE C.LRI_CANCELAMENTO_ID = I.LRI_CANCELAMENTO_ID
    AND I.LRI_ID = :LRI_ID
    INTO :LRI_CANCELAMENTO_ID, :CANCELAMENTO_TIPO, :OFICIO_CANCELAMENTO, :DATA_CANCELAMENTO;
  
    --PESSOAS ENVOLVIDAS
    PESSOAS_ENVOLVIDAS = NULL;
    FOR SELECT CPF_CNPJ, NOME FROM R_PESSOA_VINCULO
        WHERE LRI_ID = :LRI_ID
        INTO  :CPF_CNPJ, :NOME DO
    BEGIN
      IF (COALESCE(:PESSOAS_ENVOLVIDAS,'') = '') THEN
      BEGIN
        PESSOAS_ENVOLVIDAS = (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:CPF_CNPJ))||' - '||:NOME;
      END
      ELSE
      BEGIN
        PESSOAS_ENVOLVIDAS = SUBSTRING((:PESSOAS_ENVOLVIDAS||ASCII_CHAR(13)||(SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:CPF_CNPJ))||' - '||:NOME) FROM 1 FOR 5000);
      END
    END
    
    --IMOVEIS ENVOLVIDOS
    IMOVEIS_ENVOLVIDOS = NULL;
    TIPO_IMOVEL_DESC = '';
    FOR SELECT TIPO_IMOVEL, NUMERO FROM R_LRI_IMOVEL
        WHERE LRI_ID = :LRI_ID
        INTO  :TIPO_IMOVEL, :NUMERO DO
    BEGIN
      IF (COALESCE(:TIPO_IMOVEL,'') = 'T') THEN
      BEGIN
        TIPO_IMOVEL_DESC = 'TRANS.';
      END
      ELSE
      BEGIN
        TIPO_IMOVEL_DESC = 'MAT.';
      END
      IF (COALESCE(:IMOVEIS_ENVOLVIDOS,'') = '') THEN
      BEGIN
        IMOVEIS_ENVOLVIDOS = TIPO_IMOVEL_DESC||' '||:NUMERO;
      END
      ELSE
      BEGIN
        IMOVEIS_ENVOLVIDOS = SUBSTRING((:IMOVEIS_ENVOLVIDOS||ASCII_CHAR(13)||TIPO_IMOVEL_DESC||' '||:NUMERO) FROM 1 FOR 5000);
      END
    END   
        
    IF ((COALESCE(:V_STATUS,'') = 'T') OR (COALESCE(:V_STATUS,'') = '')) THEN
    BEGIN
      SUSPEND;
    END
    ELSE IF ((COALESCE(:V_STATUS,'') = 'C') AND (COALESCE(:LRI_CANCELAMENTO_ID,0)> 0)) THEN
    BEGIN
      SUSPEND;
    END
    ELSE IF ((COALESCE(:V_STATUS,'') = 'R') AND (COALESCE(:LRI_CANCELAMENTO_ID,0) = 0)) THEN
    BEGIN
      SUSPEND;
    END
  END  
END ^

ALTER PROCEDURE R_PESQUISA_CNIB_CANCELAMENTO (V_LRI_XML_ID INTEGER)
RETURNS (LRI_XML_ID INTEGER,
DATA_IMPORTACAO DATAHORA,
USUARIO_FEZ_IMPORTACAO VARCHAR(120) CHARACTER SET ISO8859_1,
LRI_CANCELAMENTO_ID INTEGER,
OFICIO VARCHAR(260) CHARACTER SET ISO8859_1,
PROTOCOLO_PROCESSO VARCHAR(260) CHARACTER SET ISO8859_1,
TB_ORIGEM_LRI_ID INTEGER,
DESCRICAO_ORIGEM VARCHAR(260) CHARACTER SET ISO8859_1,
DATA DATAHORA,
USUARIO VARCHAR(260) CHARACTER SET ISO8859_1,
EMAIL VARCHAR(260) CHARACTER SET ISO8859_1,
FORUM_VARA VARCHAR(260) CHARACTER SET ISO8859_1,
DATA_PEDIDO DATAHORA,
CANCELAMENTO_TIPO VARCHAR(1) CHARACTER SET ISO8859_1,
CANCELAMENTO_TIPO_DESC VARCHAR(20) CHARACTER SET ISO8859_1,
OFICIO_CANCELAMENTO VARCHAR(260) CHARACTER SET ISO8859_1,
DATA_CANCELAMENTO DATAHORA,
PESSOAS_ENVOLVIDAS VARCHAR(5000) CHARACTER SET ISO8859_1,
IMOVEIS_ENVOLVIDOS VARCHAR(5000) CHARACTER SET ISO8859_1)
AS 
declare variable V_SQL blob sub_type 0 segment size 80;
declare variable V_USUARIO_ID integer;
declare variable CPF_CNPJ varchar(15);
declare variable NOME varchar(120);
declare variable TIPO_IMOVEL varchar(1);
declare variable NUMERO integer;
declare variable TIPO_IMOVEL_DESC varchar(20);
BEGIN
  FOR SELECT X.LRI_XML_ID, X.DATA_IMPORTACAO, X.USUARIO_ID_IMPORTACAO, 
        C.CANCELAMENTO_TIPO, C.OFICIO_CANCELAMENTO,  C.LRI_CANCELAMENTO_ID,
        C.DATA_CANCELAMENTO, C.TB_ORIGEM_LRI_ID, C.FORUM_VARA, C.USUARIO,
        C.EMAIL
      FROM R_LRI_CANCELAMENTO C LEFT JOIN R_LRI_XML X
      ON C.LRI_XML_ID = X.LRI_XML_ID
      WHERE C.LRI_XML_ID = :V_LRI_XML_ID 
      INTO :LRI_XML_ID, :DATA_IMPORTACAO, :V_USUARIO_ID,
        :CANCELAMENTO_TIPO, :OFICIO_CANCELAMENTO, :LRI_CANCELAMENTO_ID,
        :DATA_CANCELAMENTO, :TB_ORIGEM_LRI_ID, :FORUM_VARA, :USUARIO,
        :EMAIL DO
  BEGIN
    CANCELAMENTO_TIPO_DESC = NULL;
    IF (:CANCELAMENTO_TIPO = '1') THEN
    BEGIN
      CANCELAMENTO_TIPO_DESC = 'TOTAL';
    END
    ELSE IF (:CANCELAMENTO_TIPO = '2') THEN
    BEGIN
      CANCELAMENTO_TIPO_DESC = 'PESSOA';    
    END
    ELSE IF (:CANCELAMENTO_TIPO = '3') THEN
    BEGIN
      CANCELAMENTO_TIPO_DESC = 'MATRÍCULA';    
    END    
    USUARIO_FEZ_IMPORTACAO = NULL;
    IF (COALESCE(:V_USUARIO_ID,0) > 0) THEN
    BEGIN
      SELECT NOME_COMPLETO FROM G_USUARIO
      WHERE USUARIO_ID = :V_USUARIO_ID
      INTO :USUARIO_FEZ_IMPORTACAO;
    END
    IF (COALESCE(:TB_ORIGEM_LRI_ID,0)> 0) THEN
    BEGIN
      SELECT DESCRICAO FROM R_TB_ORIGEM_LRI
      WHERE TB_ORIGEM_LRI_ID = :TB_ORIGEM_LRI_ID
      INTO :DESCRICAO_ORIGEM;
    END
    ELSE
    BEGIN
      DESCRICAO_ORIGEM = '';
    END
    
    SELECT FIRST 1 L.OFICIO, L.PROTOCOLO_PROCESSO, L.DATA, L.DATA_PEDIDO
    FROM R_LRI L, R_PESSOA_VINCULO V
    WHERE L.LRI_ID = V.LRI_ID
    AND V.LRI_CANCELAMENTO_ID = :LRI_CANCELAMENTO_ID
    UNION
    SELECT FIRST 1 L.OFICIO, L.PROTOCOLO_PROCESSO, L.DATA, L.DATA_PEDIDO
    FROM R_LRI L, R_LRI_IMOVEL I
    WHERE L.LRI_ID = I.LRI_ID
    AND I.LRI_CANCELAMENTO_ID = :LRI_CANCELAMENTO_ID
    INTO :OFICIO, :PROTOCOLO_PROCESSO, :DATA, :DATA_PEDIDO;
  
    --PESSOAS ENVOLVIDAS
    PESSOAS_ENVOLVIDAS = NULL;
    FOR SELECT CPF_CNPJ, LEFT(NOME,120) FROM R_PESSOA_VINCULO
        WHERE LRI_CANCELAMENTO_ID = :LRI_CANCELAMENTO_ID
        INTO  :CPF_CNPJ, :NOME DO
    BEGIN
      IF (COALESCE(:PESSOAS_ENVOLVIDAS,'') = '') THEN
      BEGIN
        PESSOAS_ENVOLVIDAS = (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:CPF_CNPJ))||' - '||:NOME;
      END
      ELSE
      BEGIN
        PESSOAS_ENVOLVIDAS = SUBSTRING((:PESSOAS_ENVOLVIDAS||ASCII_CHAR(13)||(SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:CPF_CNPJ))||' - '||:NOME) FROM 1 FOR 5000);
      END
    END    
    
    --IMOVEIS ENVOLVIDOS
    IMOVEIS_ENVOLVIDOS = NULL;
    FOR SELECT TIPO_IMOVEL, NUMERO FROM R_LRI_IMOVEL
        WHERE LRI_CANCELAMENTO_ID = :LRI_CANCELAMENTO_ID
        INTO  :TIPO_IMOVEL, :NUMERO DO
    BEGIN
      IF (COALESCE(:TIPO_IMOVEL,'') = 'T') THEN
      BEGIN
        TIPO_IMOVEL_DESC = 'TRANS.';
      END
      ELSE
      BEGIN
        TIPO_IMOVEL_DESC = 'MAT.';
      END
      IF (COALESCE(:IMOVEIS_ENVOLVIDOS,'') = '') THEN
      BEGIN
        IMOVEIS_ENVOLVIDOS = TIPO_IMOVEL_DESC||' '||:NUMERO;
      END
      ELSE
      BEGIN
        IMOVEIS_ENVOLVIDOS = SUBSTRING((:IMOVEIS_ENVOLVIDOS||ASCII_CHAR(13)||TIPO_IMOVEL_DESC||' '||:NUMERO) FROM 1 FOR 5000);
      END
    END   
    SUSPEND;        
  END  
END ^

ALTER PROCEDURE R_PESQUISA_CNIB_CONSISTENCIA (V_LRI_XML_ID INTEGER,
V_TRAZER_SOMENTE_VINCULOS_DOI VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (TIPO_RETORNO VARCHAR(1) CHARACTER SET ISO8859_1,
CPF_CNPJ VARCHAR(20) CHARACTER SET ISO8859_1,
NOME VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO INTEGER,
NUMERO_LETRA VARCHAR(5) CHARACTER SET ISO8859_1,
CARTORIO VARCHAR(5) CHARACTER SET ISO8859_1,
CPF_NO_CNIB VARCHAR(20) CHARACTER SET ISO8859_1,
VINCULO VARCHAR(120) CHARACTER SET ISO8859_1,
DATA_IMPORTACAO DATE,
NOME_USUARIO_IMPORTOU VARCHAR(120) CHARACTER SET ISO8859_1,
PROTOCOLO_PROCESSO VARCHAR(120) CHARACTER SET ISO8859_1,
PROTOCOLO_CANCELAMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
DATA_CANCELAMENTO TIMESTAMP)
AS 
declare variable V_CPF_CNPJ varchar(15);
declare variable V_NOME varchar(120);
declare variable V_CPF_CNPJ_LOCALIZADO varchar(20);
declare variable V_TB_TIPO_VINCULO_ID integer;
declare variable V_DATA_TRANSFERENCIA timestamp;
declare variable V_USUARIO_ID_IMPORTACAO integer;
declare variable V_MOSTRAR_CPF_TRANSFERIDO varchar(5);
declare variable v_usar_na_doi varchar(3);
declare variable v_lri_cancelamento_id integer;

--declare variable v_count integer;
BEGIN
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('OUTROS','ONR_CNIB','MOSTRAR_CPF_TRANSFERIDO',1)
  INTO :V_MOSTRAR_CPF_TRANSFERIDO;

  NOME_USUARIO_IMPORTOU = '';
  --LOCALIZAR PESSOAS INFORMADAS NA ORDEM CONSTANTES NO INDICADOR PESSOAL
  FOR SELECT V.CPF_CNPJ, X.data_importacao, X.usuario_id_importacao, L.OFICIO, COALESCE(V.lri_cancelamento_id,0)
      FROM R_PESSOA_VINCULO V, R_LRI L, r_lri_xml X
      WHERE V.LRI_ID = L.LRI_ID
      AND L.lri_xml_id = X.lri_xml_id
      AND X.LRI_XML_ID = :V_LRI_XML_ID
      INTO :V_CPF_CNPJ, :DATA_IMPORTACAO, :V_USUARIO_ID_IMPORTACAO, :PROTOCOLO_PROCESSO, :v_lri_cancelamento_id DO
  BEGIN
    if (TRIM(:NOME_USUARIO_IMPORTOU) = '') then
    begin
      SELECT login FROM G_USUARIO
      where usuario_id = :V_USUARIO_ID_IMPORTACAO
      into :NOME_USUARIO_IMPORTOU;
    end

    protocolo_cancelamento = '';
    data_cancelamento = null;
    if (:v_lri_cancelamento_id > 0) then
    begin
      SELECT first 1 oficio_cancelamento, data_cancelamento FROM r_lri_cancelamento
      where lri_cancelamento_id = :v_lri_cancelamento_id
      into :PROTOCOLO_CANCELAMENTO, :DATA_CANCELAMENTO;
    end

    if (COALESCE(:V_MOSTRAR_CPF_TRANSFERIDO,'') = 'S') then --trazer tb com data de transferencia preenchida
    begin
      FOR SELECT DISTINCT P.CPF_CNPJ, LEFT(P.NOME,120), I.TIPO_REGISTRO, I.NUMERO, I.CARTORIO, P.TB_TIPO_VINCULO_ID, P.DATA_TRANSFERENCIA, i.numero_letra
          FROM R_PESSOA_VINCULO P, R_IMOVEL I
          WHERE P.IMOVEL_ID = I.IMOVEL_ID
          AND P.CPF_CNPJ = :V_CPF_CNPJ
          AND COALESCE(P.LRI_ID,0) = 0
          AND I.tipo_registro <> 'A'
          INTO :V_CPF_CNPJ_LOCALIZADO, :NOME, :TIPO_REGISTRO, :NUMERO, :CARTORIO, :V_TB_TIPO_VINCULO_ID, :V_DATA_TRANSFERENCIA, :NUMERO_LETRA DO
      BEGIN
        TIPO_RETORNO = '1';--LOCALIZADO
        CPF_CNPJ = (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CPF_CNPJ_LOCALIZADO));
        CPF_NO_CNIB = (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CPF_CNPJ_LOCALIZADO));

        VINCULO = '';
        IF (COALESCE(:V_TB_TIPO_VINCULO_ID, 0) > 0) THEN
        BEGIN
          v_usar_na_doi = '';
          SELECT DESCRICAO, usar_na_doi FROM R_TB_TIPO_VINCULO
          WHERE TB_TIPO_VINCULO_ID = :V_TB_TIPO_VINCULO_ID
          INTO :VINCULO, :v_usar_na_doi;

          IF (:V_DATA_TRANSFERENCIA IS NOT NULL) THEN
          BEGIN
            VINCULO = 'EX-'||:VINCULO;
          END

          if (COALESCE(:V_TRAZER_SOMENTE_VINCULOS_DOI,'') <> 'S') then
          begin
            suspend;
          end
          else
          begin
            if (COALESCE(:v_usar_na_doi,'') = 'S') then
            begin
              suspend;
            end
          end
        END
        else
        begin
          SUSPEND;
        end
      END
    end
    else
    begin
      FOR SELECT DISTINCT P.CPF_CNPJ, LEFT(P.NOME,120), I.TIPO_REGISTRO, I.NUMERO, I.CARTORIO, P.TB_TIPO_VINCULO_ID, P.DATA_TRANSFERENCIA, i.numero_letra
          FROM R_PESSOA_VINCULO P, R_IMOVEL I
          WHERE P.IMOVEL_ID = I.IMOVEL_ID
          AND P.CPF_CNPJ = :V_CPF_CNPJ
          AND COALESCE(P.DATA_TRANSFERENCIA,'') = ''
          AND COALESCE(P.LRI_ID,0) = 0
          AND I.tipo_registro <> 'A'
          INTO :V_CPF_CNPJ_LOCALIZADO, :NOME, :TIPO_REGISTRO, :NUMERO, :CARTORIO, :V_TB_TIPO_VINCULO_ID, :V_DATA_TRANSFERENCIA, :NUMERO_LETRA DO
      BEGIN
        TIPO_RETORNO = '1';--LOCALIZADO
        CPF_CNPJ = (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CPF_CNPJ_LOCALIZADO));
        CPF_NO_CNIB = (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CPF_CNPJ_LOCALIZADO));

        VINCULO = '';
        IF (COALESCE(:V_TB_TIPO_VINCULO_ID, 0) > 0) THEN
        BEGIN
          v_usar_na_doi = '';
          SELECT DESCRICAO, usar_na_doi FROM R_TB_TIPO_VINCULO
          WHERE TB_TIPO_VINCULO_ID = :V_TB_TIPO_VINCULO_ID
          INTO :VINCULO, :v_usar_na_doi;

          IF (:V_DATA_TRANSFERENCIA IS NOT NULL) THEN
          BEGIN
            VINCULO = 'EX-'||:VINCULO;
          END

          if (COALESCE(:V_TRAZER_SOMENTE_VINCULOS_DOI,'') <> 'S') then
          begin
            suspend;
          end
          else
          begin
            if (COALESCE(:v_usar_na_doi,'') = 'S') then
            begin
              suspend;
            end
          end
        END
        else
        begin
          SUSPEND;
        end
      END
    end
  END

  CPF_CNPJ = '';
  NOME_USUARIO_IMPORTOU = '';
  --LOCALIZAR POSSIVEIS HOMONIMOS PARA AS PESSOAS INFORMADAS NAS ORDENS
  FOR SELECT V.CPF_CNPJ, LEFT(V.NOME,120), X.data_importacao, X.usuario_id_importacao, L.OFICIO
      FROM R_PESSOA_VINCULO V, R_LRI L, r_lri_xml X
      WHERE V.LRI_ID = L.LRI_ID
      AND L.lri_xml_id = X.lri_xml_id
      AND X.LRI_XML_ID = :V_LRI_XML_ID
      INTO :V_CPF_CNPJ, :V_NOME, :DATA_IMPORTACAO, :V_USUARIO_ID_IMPORTACAO, :PROTOCOLO_PROCESSO DO
  BEGIN
    if (TRIM(:NOME_USUARIO_IMPORTOU) = '') then
    begin
      SELECT login FROM G_USUARIO
      where usuario_id = :V_USUARIO_ID_IMPORTACAO
      into :NOME_USUARIO_IMPORTOU;
    end

    if (COALESCE(:V_MOSTRAR_CPF_TRANSFERIDO,'') = 'S') then --trazer tb com data de transferencia preenchida
    begin
      FOR SELECT DISTINCT LEFT(P.NOME,120), I.TIPO_REGISTRO, I.NUMERO, I.CARTORIO, P.TB_TIPO_VINCULO_ID, P.DATA_TRANSFERENCIA
          FROM R_PESSOA_VINCULO P, R_IMOVEL I
          WHERE P.IMOVEL_ID = I.IMOVEL_ID
          AND P.NOME = :V_NOME
          AND COALESCE(P.LRI_ID,0) = 0
          AND COALESCE(P.CPF_CNPJ,'') = ''
          AND I.tipo_registro <> 'A'
          INTO :NOME, :TIPO_REGISTRO, :NUMERO, :CARTORIO, :V_TB_TIPO_VINCULO_ID, :V_DATA_TRANSFERENCIA DO
      BEGIN
        TIPO_RETORNO = '2';--HOMONIMO
        CPF_NO_CNIB = :V_CPF_CNPJ;
  
        VINCULO = '';
        IF (COALESCE(:V_TB_TIPO_VINCULO_ID, 0) > 0) THEN
        BEGIN
          v_usar_na_doi = '';
          SELECT DESCRICAO, usar_na_doi FROM R_TB_TIPO_VINCULO
          WHERE TB_TIPO_VINCULO_ID = :V_TB_TIPO_VINCULO_ID
          INTO :VINCULO, :v_usar_na_doi;

          IF (:V_DATA_TRANSFERENCIA IS NOT NULL) THEN
          BEGIN
            VINCULO = 'EX-'||:VINCULO;
          END

          if (COALESCE(:V_TRAZER_SOMENTE_VINCULOS_DOI,'') <> 'S') then
          begin
            suspend;
          end
          else
          begin
            if (COALESCE(:v_usar_na_doi,'') = 'S') then
            begin
              suspend;
            end
          end
        end
        else
        begin
          suspend;
        end
      END
    end
    else
    begin
      FOR SELECT DISTINCT LEFT(P.NOME,120), I.TIPO_REGISTRO, I.NUMERO, I.CARTORIO, P.TB_TIPO_VINCULO_ID, P.DATA_TRANSFERENCIA
          FROM R_PESSOA_VINCULO P, R_IMOVEL I
          WHERE P.IMOVEL_ID = I.IMOVEL_ID
          AND P.NOME = :V_NOME
          AND COALESCE(P.DATA_TRANSFERENCIA,'') = ''
          AND COALESCE(P.LRI_ID,0) = 0
          AND COALESCE(P.CPF_CNPJ,'') = ''
          AND I.tipo_registro <> 'A'
          INTO :NOME, :TIPO_REGISTRO, :NUMERO, :CARTORIO, :V_TB_TIPO_VINCULO_ID, :V_DATA_TRANSFERENCIA DO
      BEGIN
        TIPO_RETORNO = '2';--HOMONIMO
        CPF_NO_CNIB = :V_CPF_CNPJ;
  
        VINCULO = '';
        IF (COALESCE(:V_TB_TIPO_VINCULO_ID, 0) > 0) THEN
        BEGIN
          v_usar_na_doi = '';
          SELECT DESCRICAO, usar_na_doi FROM R_TB_TIPO_VINCULO
          WHERE TB_TIPO_VINCULO_ID = :V_TB_TIPO_VINCULO_ID
          INTO :VINCULO, :v_usar_na_doi;

          IF (:V_DATA_TRANSFERENCIA IS NOT NULL) THEN
          BEGIN
            VINCULO = 'EX-'||:VINCULO;
          END

          if (COALESCE(:V_TRAZER_SOMENTE_VINCULOS_DOI,'') <> 'S') then
          begin
            suspend;
          end
          else
          begin
            if (COALESCE(:v_usar_na_doi,'') = 'S') then
            begin
              suspend;
            end
          end
        END
        else
        begin
          SUSPEND;
        end
      END
    end
  END
END ^

ALTER PROCEDURE R_PESQUISA_CNIB_CONSIST_CANC (V_LRI_XML_ID INTEGER)
RETURNS (TIPO_RETORNO VARCHAR(1) CHARACTER SET ISO8859_1,
CPF_CNPJ VARCHAR(20) CHARACTER SET ISO8859_1,
NOME VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO INTEGER,
NUMERO_LETRA VARCHAR(5) CHARACTER SET ISO8859_1,
CARTORIO VARCHAR(5) CHARACTER SET ISO8859_1,
CPF_NO_CNIB VARCHAR(20) CHARACTER SET ISO8859_1,
VINCULO VARCHAR(120) CHARACTER SET ISO8859_1,
CANCELAMENTO_TIPO_DESC VARCHAR(50) CHARACTER SET ISO8859_1,
CANCELAMENTO_TIPO VARCHAR(10) CHARACTER SET ISO8859_1,
DATA_IMPORTACAO DATE,
NOME_USUARIO_IMPORTOU VARCHAR(120) CHARACTER SET ISO8859_1,
OFICIO_CANCELAMENTO VARCHAR(260) CHARACTER SET ISO8859_1)
AS 
declare variable V_CPF_CNPJ varchar(15);
declare variable V_NOME varchar(120);
declare variable V_CPF_CNPJ_LOCALIZADO varchar(20);
declare variable V_TB_TIPO_VINCULO_ID integer;
declare variable V_DATA_TRANSFERENCIA timestamp;
declare variable V_LRI_CANCELAMENTO_ID integer;
declare variable V_USUARIO_ID_IMPORTACAO integer;
declare variable V_MOSTRAR_CPF_TRANSFERIDO varchar(5);
BEGIN
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('OUTROS','ONR_CNIB','MOSTRAR_CPF_TRANSFERIDO',1)
  INTO :V_MOSTRAR_CPF_TRANSFERIDO;

  NOME_USUARIO_IMPORTOU = '';
  FOR SELECT C.LRI_CANCELAMENTO_ID, X.data_importacao, X.usuario_id_importacao, C.cancelamento_tipo, C.OFICIO_CANCELAMENTO
      FROM R_LRI_CANCELAMENTO C LEFT JOIN R_LRI_XML X
      ON C.LRI_XML_ID = X.LRI_XML_ID
      WHERE C.LRI_XML_ID = :V_LRI_XML_ID 
      INTO :V_LRI_CANCELAMENTO_ID, :DATA_IMPORTACAO, :V_USUARIO_ID_IMPORTACAO, :CANCELAMENTO_TIPO, :OFICIO_CANCELAMENTO DO
  BEGIN
    if (TRIM(:NOME_USUARIO_IMPORTOU) = '') then
    begin
      SELECT login FROM G_USUARIO
      where usuario_id = :V_USUARIO_ID_IMPORTACAO
      into :NOME_USUARIO_IMPORTOU;
    end

    CANCELAMENTO_TIPO_DESC = NULL;
    IF (:CANCELAMENTO_TIPO = '1') THEN
    BEGIN
      CANCELAMENTO_TIPO_DESC = 'TOTAL';
    END
    ELSE IF (:CANCELAMENTO_TIPO = '2') THEN
    BEGIN
      CANCELAMENTO_TIPO_DESC = 'PESSOA';    
    END
    ELSE IF (:CANCELAMENTO_TIPO = '3') THEN
    BEGIN
      CANCELAMENTO_TIPO_DESC = 'MATRÍCULA';    
    END    

    --PESSOAS ENVOLVIDAS
    FOR SELECT DISTINCT CPF_CNPJ, LEFT(NOME,120) FROM R_PESSOA_VINCULO
        WHERE LRI_CANCELAMENTO_ID = :V_LRI_CANCELAMENTO_ID
        INTO  :V_CPF_CNPJ, :V_NOME DO
    BEGIN
      if (COALESCE(:V_MOSTRAR_CPF_TRANSFERIDO,'') = 'S') then --trazer tb com data de transferencia preenchida
      begin
        FOR SELECT DISTINCT P.CPF_CNPJ, LEFT(P.NOME,120) , I.TIPO_REGISTRO, I.NUMERO, I.CARTORIO, P.TB_TIPO_VINCULO_ID, P.DATA_TRANSFERENCIA, i.numero_letra
            FROM R_PESSOA_VINCULO P, R_IMOVEL I
            WHERE P.IMOVEL_ID = I.IMOVEL_ID
            AND P.CPF_CNPJ = :V_CPF_CNPJ
            AND COALESCE(P.LRI_ID,0) = 0
            AND I.tipo_registro <> 'A'
            INTO :V_CPF_CNPJ_LOCALIZADO, :NOME, :TIPO_REGISTRO, :NUMERO, :CARTORIO, :V_TB_TIPO_VINCULO_ID, :V_DATA_TRANSFERENCIA, :NUMERO_LETRA DO
        BEGIN
          TIPO_RETORNO = '1';--LOCALIZADO
          CPF_CNPJ = (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CPF_CNPJ_LOCALIZADO));
          CPF_NO_CNIB = (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CPF_CNPJ_LOCALIZADO));
    
          VINCULO = '';
          IF (COALESCE(:V_TB_TIPO_VINCULO_ID, 0) > 0) THEN
          BEGIN
            SELECT DESCRICAO FROM R_TB_TIPO_VINCULO
            WHERE TB_TIPO_VINCULO_ID = :V_TB_TIPO_VINCULO_ID
            INTO :VINCULO;
    
            IF (:V_DATA_TRANSFERENCIA IS NOT NULL) THEN
            BEGIN
              VINCULO = 'EX-'||:VINCULO;
            END
          END
          SUSPEND;
        END
  
        FOR SELECT DISTINCT LEFT(P.NOME,120), I.TIPO_REGISTRO, I.NUMERO, I.CARTORIO, P.TB_TIPO_VINCULO_ID, P.DATA_TRANSFERENCIA
            FROM R_PESSOA_VINCULO P, R_IMOVEL I
            WHERE P.IMOVEL_ID = I.IMOVEL_ID
            AND P.NOME = :V_NOME
            AND COALESCE(P.LRI_ID,0) = 0
            AND COALESCE(P.CPF_CNPJ,'') = ''
            AND I.tipo_registro <> 'A'
            INTO :NOME, :TIPO_REGISTRO, :NUMERO, :CARTORIO, :V_TB_TIPO_VINCULO_ID, :V_DATA_TRANSFERENCIA DO
        BEGIN
          TIPO_RETORNO = '2';--HOMONIMO
          CPF_NO_CNIB = :V_CPF_CNPJ;
    
          VINCULO = '';
          IF (COALESCE(:V_TB_TIPO_VINCULO_ID, 0) > 0) THEN
          BEGIN
            SELECT DESCRICAO FROM R_TB_TIPO_VINCULO
            WHERE TB_TIPO_VINCULO_ID = :V_TB_TIPO_VINCULO_ID
            INTO :VINCULO;
    
            IF (:V_DATA_TRANSFERENCIA IS NOT NULL) THEN
            BEGIN
              VINCULO = 'EX-'||:VINCULO;
            END
          END
          SUSPEND;
        END
      end
      else
      begin
      FOR SELECT DISTINCT P.CPF_CNPJ, LEFT(P.NOME,120) , I.TIPO_REGISTRO, I.NUMERO, I.CARTORIO, P.TB_TIPO_VINCULO_ID, P.DATA_TRANSFERENCIA, i.numero_letra
            FROM R_PESSOA_VINCULO P, R_IMOVEL I
            WHERE P.IMOVEL_ID = I.IMOVEL_ID
            AND P.CPF_CNPJ = :V_CPF_CNPJ
            AND COALESCE(P.DATA_TRANSFERENCIA,'') = ''
            AND COALESCE(P.LRI_ID,0) = 0
            AND I.tipo_registro <> 'A'
            INTO :V_CPF_CNPJ_LOCALIZADO, :NOME, :TIPO_REGISTRO, :NUMERO, :CARTORIO, :V_TB_TIPO_VINCULO_ID, :V_DATA_TRANSFERENCIA, :NUMERO_LETRA DO
        BEGIN
          TIPO_RETORNO = '1';--LOCALIZADO
          CPF_CNPJ = (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CPF_CNPJ_LOCALIZADO));
          CPF_NO_CNIB = (SELECT RETORNO FROM W_FORMATAR_CPF_CNPJ(:V_CPF_CNPJ_LOCALIZADO));
    
          VINCULO = '';
          IF (COALESCE(:V_TB_TIPO_VINCULO_ID, 0) > 0) THEN
          BEGIN
            SELECT DESCRICAO FROM R_TB_TIPO_VINCULO
            WHERE TB_TIPO_VINCULO_ID = :V_TB_TIPO_VINCULO_ID
            INTO :VINCULO;
    
            IF (:V_DATA_TRANSFERENCIA IS NOT NULL) THEN
            BEGIN
              VINCULO = 'EX-'||:VINCULO;
            END
          END
          SUSPEND;
        END
  
        FOR SELECT DISTINCT LEFT(P.NOME,120), I.TIPO_REGISTRO, I.NUMERO, I.CARTORIO, P.TB_TIPO_VINCULO_ID, P.DATA_TRANSFERENCIA
            FROM R_PESSOA_VINCULO P, R_IMOVEL I
            WHERE P.IMOVEL_ID = I.IMOVEL_ID
            AND P.NOME = :V_NOME
            AND COALESCE(P.DATA_TRANSFERENCIA,'') = ''
            AND COALESCE(P.LRI_ID,0) = 0
            AND COALESCE(P.CPF_CNPJ,'') = ''
            AND I.tipo_registro <> 'A'
            INTO :NOME, :TIPO_REGISTRO, :NUMERO, :CARTORIO, :V_TB_TIPO_VINCULO_ID, :V_DATA_TRANSFERENCIA DO
        BEGIN
          TIPO_RETORNO = '2';--HOMONIMO
          CPF_NO_CNIB = :V_CPF_CNPJ;
    
          VINCULO = '';
          IF (COALESCE(:V_TB_TIPO_VINCULO_ID, 0) > 0) THEN
          BEGIN
            SELECT DESCRICAO FROM R_TB_TIPO_VINCULO
            WHERE TB_TIPO_VINCULO_ID = :V_TB_TIPO_VINCULO_ID
            INTO :VINCULO;
    
            IF (:V_DATA_TRANSFERENCIA IS NOT NULL) THEN
            BEGIN
              VINCULO = 'EX-'||:VINCULO;
            END
          END
          SUSPEND;
        END
      end
    END
  END
END ^

ALTER PROCEDURE R_PESQUISA_FICHAAUXILIAR (V_NOME_CONDOMINIO VARCHAR(90) CHARACTER SET ISO8859_1,
V_BAIRRO VARCHAR(16) CHARACTER SET ISO8859_1,
V_SIGLA VARCHAR(16) CHARACTER SET ISO8859_1,
V_TIPO_QUADRA VARCHAR(10) CHARACTER SET ISO8859_1,
V_QUADRA VARCHAR(60) CHARACTER SET ISO8859_1,
V_BLOCO VARCHAR(16) CHARACTER SET ISO8859_1,
V_LOTE VARCHAR(30) CHARACTER SET ISO8859_1,
V_CL VARCHAR(6) CHARACTER SET ISO8859_1,
V_CR VARCHAR(6) CHARACTER SET ISO8859_1,
V_CONJ VARCHAR(6) CHARACTER SET ISO8859_1,
V_AE VARCHAR(6) CHARACTER SET ISO8859_1,
V_PROJ VARCHAR(6) CHARACTER SET ISO8859_1,
V_TR VARCHAR(6) CHARACTER SET ISO8859_1,
V_AO VARCHAR(6) CHARACTER SET ISO8859_1,
V_CH VARCHAR(6) CHARACTER SET ISO8859_1,
V_TIPO_FICHA VARCHAR(5) CHARACTER SET ISO8859_1)
RETURNS (NUMERO_UNIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
IMOVEL_ID NUMERIC(18, 2),
TIPO_CLASSE VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO NUMERIC(18, 2),
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
SITUACAO VARCHAR(1) CHARACTER SET ISO8859_1,
NOME_CONDOMINIO VARCHAR(90) CHARACTER SET ISO8859_1,
IMOVEL_FICHAAUXILIAR_ID NUMERIC(18, 2),
QUADRA VARCHAR(60) CHARACTER SET ISO8859_1,
BLOCO VARCHAR(10) CHARACTER SET ISO8859_1,
TB_BAIRRO_ID NUMERIC(18, 2),
SIGLA_ID NUMERIC(18, 2),
TIPO_COMPLEMENTAR VARCHAR(10) CHARACTER SET ISO8859_1,
TIPO_COMPLEMENTAR_DESC VARCHAR(30) CHARACTER SET ISO8859_1,
SIGLA VARCHAR(10) CHARACTER SET ISO8859_1,
TIPO_QUADRA VARCHAR(3) CHARACTER SET ISO8859_1,
TIPO_FICHA VARCHAR(3) CHARACTER SET ISO8859_1,
TIPO_ARQUIVO VARCHAR(3) CHARACTER SET ISO8859_1,
CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
DECLARE VSQL VARCHAR(1000);
BEGIN
  VSQL = 'SELECT I.IMOVEL_ID, I.TIPO_CLASSE, I.TIPO_REGISTRO,
                I.NUMERO, I.NUMERO_LETRA, I.SITUACAO,
                F.NOME_CONDOMINIO, F.IMOVEL_FICHAAUXILIAR_ID,
                U.QUADRA, U.BLOCO, U.TB_BAIRRO_ID, U.SIGLA_ID,
                U.TIPO_COMPLEMENTAR, U.TIPO_COMPLEMENTAR_DESC,
                U.TIPO_QUADRA, S.SIGLA, U.NUMERO_UNIDADE, F.TIPO_FICHA, F.TIPO_ARQUIVO, I.CARTORIO
          FROM R_IMOVEL I, R_IMOVEL_FICHAAUXILIAR F, R_IMOVEL_UNIDADE U, R_SIGLA S
          WHERE I.IMOVEL_ID = F.IMOVEL_ID
          AND F.IMOVEL_ID = U.IMOVEL_ID
          AND U.SIGLA_ID = S.SIGLA_ID ';

  IF ((:V_TIPO_FICHA <> '') AND (:V_TIPO_FICHA IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND F.TIPO_FICHA = ' || :V_TIPO_FICHA;

  IF ((:V_BAIRRO <> '') AND (:V_BAIRRO IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TB_BAIRRO_ID = ' || :V_BAIRRO;
  IF ((:V_SIGLA <> '') AND (:V_SIGLA IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND S.SIGLA STARTING WITH '|| :V_SIGLA;
  IF ((:V_TIPO_QUADRA <> '') AND (:V_TIPO_QUADRA IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TIPO_QUADRA = ' || :V_TIPO_QUADRA;
  IF ((:V_QUADRA <> '') AND (:V_QUADRA IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.QUADRA STARTING WITH '|| :V_QUADRA;
  IF ((:V_BLOCO <> '') AND (:V_BLOCO IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.BLOCO STARTING WITH '|| :V_BLOCO;
  IF ((:V_LOTE <> '') AND (:V_LOTE IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.NUMERO_UNIDADE LIKE '|| :V_LOTE;
  IF ((:V_CL <> '') AND (:V_CL IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TIPO_COMPLEMENTAR LIKE '|| :V_CL;
  IF ((:V_CR <> '') AND (:V_CR IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TIPO_COMPLEMENTAR LIKE '|| :V_CR;
  IF ((:V_CONJ <> '') AND (:V_CONJ IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TIPO_COMPLEMENTAR LIKE '|| :V_CONJ;
  IF ((:V_AE <> '') AND (:V_AE IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TIPO_COMPLEMENTAR LIKE '|| :V_AE;
  IF ((:V_PROJ <> '') AND (:V_PROJ IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TIPO_COMPLEMENTAR LIKE '|| :V_PROJ;
  IF ((:V_TR <> '') AND (:V_TR IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TIPO_COMPLEMENTAR LIKE '|| :V_TR;
  IF ((:V_AO <> '') AND (:V_AO IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TIPO_COMPLEMENTAR LIKE '|| :V_AO;
  IF ((:V_CH <> '') AND (:V_CH IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TIPO_COMPLEMENTAR LIKE '|| :V_CH;
  IF ((:V_NOME_CONDOMINIO <> '') AND (:V_NOME_CONDOMINIO IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND F.NOME_CONDOMINIO LIKE '|| :V_NOME_CONDOMINIO;

  VSQL = :VSQL || ' ORDER BY S.SIGLA, U.QUADRA, U.BLOCO ';

  FOR EXECUTE STATEMENT VSQL
      INTO   :IMOVEL_ID, :TIPO_CLASSE, :TIPO_REGISTRO, :NUMERO, :NUMERO_LETRA, :SITUACAO, :NOME_CONDOMINIO, :IMOVEL_FICHAAUXILIAR_ID, :QUADRA, :BLOCO, :TB_BAIRRO_ID, :SIGLA_ID, :TIPO_COMPLEMENTAR, :TIPO_COMPLEMENTAR_DESC, :TIPO_QUADRA, :SIGLA, :NUMERO_UNIDADE,  :TIPO_FICHA, :TIPO_ARQUIVO, :CARTORIO DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_PESQUISA_FICHAAUXILIAR_SEM (V_NOME_CONDOMINIO VARCHAR(90) CHARACTER SET ISO8859_1)
RETURNS (NUMERO_UNIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
IMOVEL_ID NUMERIC(18, 2),
TIPO_CLASSE VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO NUMERIC(18, 2),
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
SITUACAO VARCHAR(1) CHARACTER SET ISO8859_1,
NOME_CONDOMINIO VARCHAR(90) CHARACTER SET ISO8859_1,
IMOVEL_FICHAAUXILIAR_ID NUMERIC(18, 2),
QUADRA VARCHAR(60) CHARACTER SET ISO8859_1,
BLOCO VARCHAR(10) CHARACTER SET ISO8859_1,
TB_BAIRRO_ID NUMERIC(18, 2),
SIGLA_ID NUMERIC(18, 2),
TIPO_COMPLEMENTAR VARCHAR(10) CHARACTER SET ISO8859_1,
TIPO_COMPLEMENTAR_DESC VARCHAR(30) CHARACTER SET ISO8859_1,
SIGLA VARCHAR(10) CHARACTER SET ISO8859_1,
TIPO_QUADRA VARCHAR(3) CHARACTER SET ISO8859_1,
TIPO_FICHA VARCHAR(3) CHARACTER SET ISO8859_1,
TIPO_ARQUIVO VARCHAR(3) CHARACTER SET ISO8859_1,
CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
BEGIN
--ESTA PROCEDURE EH USADA PARA IMOVEIS SEM SIGLA
  FOR SELECT I.IMOVEL_ID, I.TIPO_CLASSE, I.TIPO_REGISTRO,
             I.NUMERO, I.NUMERO_LETRA, I.SITUACAO,
             F.NOME_CONDOMINIO, F.IMOVEL_FICHAAUXILIAR_ID,
             U.QUADRA, U.BLOCO, U.TB_BAIRRO_ID, U.SIGLA_ID,
             U.TIPO_COMPLEMENTAR, U.TIPO_COMPLEMENTAR_DESC,
             U.TIPO_QUADRA, NULL, U.NUMERO_UNIDADE, F.TIPO_FICHA, 
             F.TIPO_ARQUIVO, I.CARTORIO
      FROM R_IMOVEL I, R_IMOVEL_FICHAAUXILIAR F, R_IMOVEL_UNIDADE U
      WHERE I.IMOVEL_ID = F.IMOVEL_ID
      AND F.IMOVEL_ID = U.IMOVEL_ID
      AND F.NOME_CONDOMINIO LIKE :V_NOME_CONDOMINIO
      ORDER BY U.QUADRA, U.BLOCO
  INTO :IMOVEL_ID, :TIPO_CLASSE, :TIPO_REGISTRO, :NUMERO, :NUMERO_LETRA, :SITUACAO, :NOME_CONDOMINIO, :IMOVEL_FICHAAUXILIAR_ID, :QUADRA, :BLOCO, :TB_BAIRRO_ID, :SIGLA_ID, :TIPO_COMPLEMENTAR, :TIPO_COMPLEMENTAR_DESC, :TIPO_QUADRA, :SIGLA, :NUMERO_UNIDADE,  :TIPO_FICHA, :TIPO_ARQUIVO, :CARTORIO DO
  BEGIN
    SUSPEND;
  END
END ^

