PROJECAO VARCHAR(60) CHARACTER SET ISO8859_1,
TRECHO VARCHAR(30) CHARACTER SET ISO8859_1,
AREA_OCTOGONAL VARCHAR(30) CHARACTER SET ISO8859_1,
CHACARA VARCHAR(30) CHARACTER SET ISO8859_1,
CASA VARCHAR(30) CHARACTER SET ISO8859_1,
NOME_EDIFICIO_DF VARCHAR(120) CHARACTER SET ISO8859_1,
NOVO VARCHAR(1) CHARACTER SET ISO8859_1,
CONJUNTO VARCHAR(30) CHARACTER SET ISO8859_1,
COMPLEMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1,
AREA VARCHAR(20) CHARACTER SET ISO8859_1,
NUMERO_UNIDADE_2 VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
declare variable VSQL varchar(1024);
declare variable VSQL2 varchar(1024);
declare variable V_IMOVEL_FICHAAUXILIAR_ID integer;
declare variable v_tipo_ficha varchar(3);
BEGIN
  VSQL = 'SELECT I.IMOVEL_ID, I.TIPO_CLASSE, I.TIPO_REGISTRO,
                I.NUMERO, I.NUMERO_LETRA, I.SITUACAO,
                U.IMOVEL_FICHAAUXILIAR_ID,
                U.QUADRA, U.BLOCO, U.TB_BAIRRO_ID, U.SIGLA_ID,
                U.TIPO_COMPLEMENTAR, U.TIPO_COMPLEMENTAR_DESC,
                U.TIPO_QUADRA, U.NUMERO_UNIDADE, U.NOME_EDIFICACAO,
                U.IMOVEL_TIPO_ID, U.IMOVEL_UNIDADE_ID, U.AREA_ESPECIAL,
                U.PROJECAO, U.TRECHO, U.AREA_OCTOGONAL, U.CHACARA,
                U.CASA, U.NOME_EDIFICIO_DF, U.NOVO, U.CONJUNTO, 
                U.COMPLEMENTO, I.CARTORIO, U.AREA, U.NUMERO_UNIDADE_2
                FROM R_IMOVEL I, R_IMOVEL_UNIDADE U
                WHERE I.IMOVEL_ID = U.IMOVEL_ID ';
  IF ((:V_SIGLA <> '') AND (:V_SIGLA IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.SIGLA_ID = '|| :V_SIGLA;
  IF ((:V_QUADRA <> '') AND (:V_QUADRA IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.QUADRA STARTING WITH '|| :V_QUADRA;
  IF ((:V_BLOCO <> '') AND (:V_BLOCO IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.BLOCO STARTING WITH '|| :V_BLOCO;
  IF ((:V_LOTE <> '') AND (:V_LOTE IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.NUMERO_UNIDADE LIKE '|| :V_LOTE;
  IF ((:V_CONJ <> '') AND (:V_CONJ IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.CONJUNTO LIKE '|| :V_CONJ;
  IF ((:V_BAIRRO <> '') AND (:V_BAIRRO IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TB_BAIRRO_ID = ' || :V_BAIRRO;
  IF ((:V_CH <> '') AND (:V_CH IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.CHACARA LIKE '|| :V_CH;
  IF ((:V_TR <> '') AND (:V_TR IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.TRECHO LIKE '|| :V_TR;
  IF ((:V_PROJ <> '') AND (:V_PROJ IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.PROJECAO LIKE '|| :V_PROJ;
  IF ((:V_AO <> '') AND (:V_AO IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.AREA_OCTOGONAL LIKE '|| :V_AO;
  IF ((:V_AE <> '') AND (:V_AE IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.AREA_ESPECIAL LIKE '|| :V_AE;
  IF ((:V_COMPL <> '') AND (:V_COMPL IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.COMPLEMENTO LIKE '|| :V_COMPL;
  IF ((:V_EDIFICIO <> '') AND (:V_EDIFICIO IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.NOME_EDIFICIO_DF LIKE '|| :V_EDIFICIO;
  IF ((:V_CASA <> '') AND (:V_CASA IS NOT NULL)) THEN
    VSQL = :VSQL || ' AND U.CASA LIKE '|| :V_CASA;

  if ((:V_TIPO_QUADRA <> 'T') AND (:V_TIPO_QUADRA <> '')) then
    VSQL = :VSQL ||' AND U.TIPO_QUADRA = '||:V_TIPO_QUADRA;

  VSQL = :VSQL ||' ORDER BY U.SIGLA_ID, U.QUADRA, U.BLOCO ';
  FOR EXECUTE STATEMENT VSQL
      INTO   :IMOVEL_ID, :TIPO_CLASSE, :TIPO_REGISTRO, :NUMERO, :NUMERO_LETRA, :SITUACAO,  :IMOVEL_FICHAAUXILIAR_ID, :QUADRA, :BLOCO, :TB_BAIRRO_ID, :SIGLA_ID, :TIPO_COMPLEMENTAR, :TIPO_COMPLEMENTAR_DESC, :TIPO_QUADRA, :NUMERO_UNIDADE, :NOME_EDIFICACAO,
             :IMOVEL_TIPO_ID, :IMOVEL_UNIDADE_ID, :AREA_ESPECIAL, :PROJECAO, :TRECHO, :AREA_OCTOGONAL, :CHACARA, :CASA, :NOME_EDIFICIO_DF, :NOVO, :CONJUNTO, :COMPLEMENTO, :CARTORIO, :AREA, :NUMERO_UNIDADE_2 DO
  BEGIN
    SUSPEND;
    if (coalesce(:V_TRAZER_UNIDADES_VINCULADAS,'') = 'S') then
    begin
      --VERIFICAR SE EH UMA FICHA MAE
      V_IMOVEL_FICHAAUXILIAR_ID = 0;
      SELECT first 1 IMOVEL_FICHAAUXILIAR_ID, tipo_ficha FROM R_IMOVEL_FICHAAUXILIAR
      WHERE IMOVEL_ID = :IMOVEL_ID
      into :V_IMOVEL_FICHAAUXILIAR_ID, :v_tipo_ficha;

      if ((coalesce(:V_IMOVEL_FICHAAUXILIAR_ID,0) > 0) and (coalesce(:v_tipo_ficha,'') = 'C')) then
      begin
        VSQL2 = 'SELECT I.IMOVEL_ID, I.TIPO_CLASSE, I.TIPO_REGISTRO,
                  I.NUMERO, I.NUMERO_LETRA, I.SITUACAO,
                  U.IMOVEL_FICHAAUXILIAR_ID, U.BLOCO,
                  U.TIPO_COMPLEMENTAR, U.TIPO_COMPLEMENTAR_DESC,
                  U.TIPO_QUADRA, U.NUMERO_UNIDADE, U.NOME_EDIFICACAO,
                  U.IMOVEL_TIPO_ID, U.IMOVEL_UNIDADE_ID,
                  U.CASA, U.NOME_EDIFICIO_DF, U.NOVO, U.CONJUNTO,
                  I.CARTORIO, U.AREA, U.NUMERO_UNIDADE_2
                  FROM R_IMOVEL I, R_IMOVEL_UNIDADE U
                  WHERE I.IMOVEL_ID = U.IMOVEL_ID
                  AND  U.IMOVEL_FICHAAUXILIAR_ID = '||:V_IMOVEL_FICHAAUXILIAR_ID||
                  ' order by i.numero ';

        FOR EXECUTE STATEMENT VSQL2
        INTO   :IMOVEL_ID, :TIPO_CLASSE, :TIPO_REGISTRO, :NUMERO, :NUMERO_LETRA, :SITUACAO,  :IMOVEL_FICHAAUXILIAR_ID, :BLOCO, :TIPO_COMPLEMENTAR, :TIPO_COMPLEMENTAR_DESC, :TIPO_QUADRA, :NUMERO_UNIDADE, :NOME_EDIFICACAO,
               :IMOVEL_TIPO_ID, :IMOVEL_UNIDADE_ID, :CASA, :NOME_EDIFICIO_DF, :NOVO, :CONJUNTO, :CARTORIO, :AREA, :NUMERO_UNIDADE_2 DO
        BEGIN
          SUSPEND;
        END
      end
      else if (coalesce(:V_IMOVEL_FICHAAUXILIAR_ID,0) > 0) then
      begin
        VSQL2 = 'SELECT I.IMOVEL_ID, I.TIPO_CLASSE, I.TIPO_REGISTRO,
                  I.NUMERO, I.NUMERO_LETRA, I.SITUACAO,
                  U.IMOVEL_FICHAAUXILIAR_ID,
                  U.QUADRA, U.BLOCO, U.TB_BAIRRO_ID, U.SIGLA_ID,
                  U.TIPO_COMPLEMENTAR, U.TIPO_COMPLEMENTAR_DESC,
                  U.TIPO_QUADRA, U.NUMERO_UNIDADE, U.NOME_EDIFICACAO,
                  U.IMOVEL_TIPO_ID, U.IMOVEL_UNIDADE_ID, U.AREA_ESPECIAL,
                  U.PROJECAO, U.TRECHO, U.AREA_OCTOGONAL, U.CHACARA,
                  U.CASA, U.NOME_EDIFICIO_DF, U.NOVO, U.CONJUNTO,
                  U.COMPLEMENTO, I.CARTORIO, U.AREA, U.NUMERO_UNIDADE_2
                  FROM R_IMOVEL I, R_IMOVEL_UNIDADE U
                  WHERE I.IMOVEL_ID = U.IMOVEL_ID
                  AND  U.IMOVEL_FICHAAUXILIAR_ID = '||:V_IMOVEL_FICHAAUXILIAR_ID||
                  ' order by i.numero ';


        FOR EXECUTE STATEMENT VSQL2
        INTO   :IMOVEL_ID, :TIPO_CLASSE, :TIPO_REGISTRO, :NUMERO, :NUMERO_LETRA, :SITUACAO,  :IMOVEL_FICHAAUXILIAR_ID, :QUADRA, :BLOCO, :TB_BAIRRO_ID, :SIGLA_ID, :TIPO_COMPLEMENTAR, :TIPO_COMPLEMENTAR_DESC, :TIPO_QUADRA, :NUMERO_UNIDADE, :NOME_EDIFICACAO,
               :IMOVEL_TIPO_ID, :IMOVEL_UNIDADE_ID, :AREA_ESPECIAL, :PROJECAO, :TRECHO, :AREA_OCTOGONAL, :CHACARA, :CASA, :NOME_EDIFICIO_DF, :NOVO, :CONJUNTO, :COMPLEMENTO, :CARTORIO, :AREA, :NUMERO_UNIDADE_2 DO
        BEGIN
          SUSPEND;
        END
      end
    end
  END
END ^

ALTER PROCEDURE R_PESQUISA_IMOVEIS_PESSOA (V_PESSOA_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_ATUAL VARCHAR(3) CHARACTER SET ISO8859_1,
V_TIPO_CLASSE VARCHAR(3) CHARACTER SET ISO8859_1,
V_NOME VARCHAR(120) CHARACTER SET ISO8859_1 DEFAULT '',
V_CPF_CNPJ VARCHAR(120) CHARACTER SET ISO8859_1 DEFAULT '',
V_DOCUMENTO VARCHAR(120) CHARACTER SET ISO8859_1 DEFAULT '',
V_TRAZER_PROPRIETARIOS VARCHAR(3) CHARACTER SET ISO8859_1 DEFAULT '',
V_OMITIR_TRANSMITENTES VARCHAR(3) CHARACTER SET ISO8859_1 DEFAULT '')
RETURNS (IMOVEL_ID NUMERIC(10, 2),
TIPO_CLASSE VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
DATA_REGISTRO TIMESTAMP,
NUMERO NUMERIC(10, 2),
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
CIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
DATA_BAIXA TIMESTAMP,
CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1,
INSCRICAO_IMOVEL VARCHAR(60) CHARACTER SET ISO8859_1,
SITUACAO VARCHAR(1) CHARACTER SET ISO8859_1,
TB_TIPO_VINCULO_ID NUMERIC(10, 2),
DATA_TRANSFERENCIA TIMESTAMP,
NUMERO_UNIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
QUADRA VARCHAR(60) CHARACTER SET ISO8859_1,
NOME_EDIFICACAO VARCHAR(90) CHARACTER SET ISO8859_1,
IMOVEL_TIPO_ID NUMERIC(10, 2),
IMOVEL_UNIDADE_ID NUMERIC(10, 2),
TB_BAIRRO_ID NUMERIC(10, 2),
TIPO_ATO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO_ATO NUMERIC(10, 2),
AREA VARCHAR(120) CHARACTER SET ISO8859_1,
CONJUNTO VARCHAR(10) CHARACTER SET ISO8859_1,
BLOCO VARCHAR(10) CHARACTER SET ISO8859_1,
SIGLA_ID NUMERIC(10, 2),
TIPO_COMPLEMENTAR_DESC VARCHAR(30) CHARACTER SET ISO8859_1,
TIPO_QUADRA VARCHAR(3) CHARACTER SET ISO8859_1,
NOME_EDIFICIO_DF VARCHAR(90) CHARACTER SET ISO8859_1,
COMPLEMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
TIPO_COMPLEMENTAR VARCHAR(10) CHARACTER SET ISO8859_1,
IMOVEL_FICHAAUXILIAR_ID NUMERIC(10, 2),
TB_ESTADOCIVIL_ID NUMERIC(10, 2),
NUMERO_UNIDADE_2 VARCHAR(60) CHARACTER SET ISO8859_1,
PROPRIETARIOS VARCHAR(10000) CHARACTER SET ISO8859_1)
AS 
declare variable VSQL varchar(10000);
declare variable VAREA varchar(120);
declare variable VAREA_DESCRITIVA varchar(120);
declare variable V_NOME_PROPRIETARIO VARCHAR(260);
declare variable V_CPF_PROPRIETARIO VARCHAR(50);
declare variable V_COUNT INTEGER;
declare variable v_pessoa_id_temp integer;
declare variable v_numero_ato integer;
BEGIN
  VSQL = 'SELECT DISTINCT I.IMOVEL_ID, I.TIPO_CLASSE, I.TIPO_REGISTRO,
                 I.DATA_REGISTRO, I.NUMERO, I.NUMERO_LETRA, I.CIDADE,
                 I.DATA_BAIXA, I.CARTORIO, I.INSCRICAO_IMOVEL, I.SITUACAO,
                 V.TB_TIPO_VINCULO_ID, V.DATA_TRANSFERENCIA,
                 V.TB_ESTADOCIVIL_ID, V.TIPO_ATO, V.NUMERO_ATO,
                 U.NUMERO_UNIDADE, U.QUADRA, U.NOME_EDIFICACAO,
        U.IMOVEL_TIPO_ID, U.IMOVEL_UNIDADE_ID, U.TB_BAIRRO_ID,
        U.AREA, U.CONJUNTO, U.BLOCO,
        U.SIGLA_ID, U.TIPO_COMPLEMENTAR_DESC,
        U.TIPO_QUADRA, U.NOME_EDIFICIO_DF, U.COMPLEMENTO,
        U.TIPO_COMPLEMENTAR, U.IMOVEL_FICHAAUXILIAR_ID,
        U.AREA_DESCRITIVA, U.NUMERO_UNIDADE_2, V.PESSOA_ID, coalesce(V.numero_ato,0)
      FROM R_IMOVEL I, R_PESSOA_VINCULO V, R_IMOVEL_UNIDADE U, R_TB_TIPO_VINCULO TV
      WHERE I.IMOVEL_ID = V.IMOVEL_ID
      AND I.IMOVEL_ID = U.IMOVEL_ID
      AND V.TB_TIPO_VINCULO_ID = TV.TB_TIPO_VINCULO_ID
      AND   I.TIPO_REGISTRO <> ''A''';

  if (COALESCE(:V_PESSOA_ID,0) > 0) then
  begin
    VSQL = :VSQL || ' AND   V.PESSOA_ID = '||:V_PESSOA_ID;
  end
  else
  begin
    if (COALESCE(:V_CPF_CNPJ,'') <> '') then
    begin
      VSQL = :VSQL || ' AND V.cpf_cnpj = '||''''||:V_CPF_CNPJ||'''';
    end
    if (COALESCE(:V_DOCUMENTO,'') <> '') then
    begin
      VSQL = :VSQL || ' AND V.DOCUMENTO = '||''''||:V_DOCUMENTO||'''';
    end
    if (COALESCE(:V_NOME,'') <> '') then
    begin
      VSQL = :VSQL || ' AND V.NOME LIKE '||''''||:V_NOME||'''';
    end
  end

  IF ((:V_TIPO_CLASSE <> '') and (:V_TIPO_CLASSE <> 'T')) then --diferente de vazio e diferente de todos (T)
  BEGIN
    VSQL = :VSQL || ' AND I.TIPO_CLASSE = '||''''||:V_TIPO_CLASSE||'''';
  END

  IF (:V_ATUAL = 'S') THEN
  BEGIN
    VSQL = :VSQL || ' AND V.DATA_TRANSFERENCIA IS NULL ';
  END
  IF (:V_ATUAL = 'N') THEN
  BEGIN
    VSQL = :VSQL || ' AND V.DATA_TRANSFERENCIA IS NOT NULL ';
  END
  IF (:V_ATUAL = 'D') THEN --SOMENTE LINKS DA DOI
  BEGIN
    VSQL = :VSQL || ' AND V.DATA_TRANSFERENCIA IS NULL ';
    VSQL = :VSQL || ' and    (tv.usar_na_doi <> ''N'')';
  END

  VSQL = :VSQL || ' ORDER BY I.NUMERO, V.DATA_TRANSFERENCIA ';

  if ((COALESCE(:V_PESSOA_ID,0) > 0) or (COALESCE(:V_CPF_CNPJ,'') <> '') or (COALESCE(:V_DOCUMENTO,'') <> '') or (COALESCE(:V_NOME,'') <> '')) then
  begin
    FOR EXECUTE STATEMENT VSQL
    INTO :IMOVEL_ID, :TIPO_CLASSE, :TIPO_REGISTRO,
         :DATA_REGISTRO, :NUMERO, :NUMERO_LETRA,
         :CIDADE, :DATA_BAIXA, :CARTORIO, :INSCRICAO_IMOVEL,
         :SITUACAO, :TB_TIPO_VINCULO_ID, :DATA_TRANSFERENCIA,
         :TB_ESTADOCIVIL_ID, :TIPO_ATO, :NUMERO_ATO,
         :NUMERO_UNIDADE, :QUADRA, :NOME_EDIFICACAO, :IMOVEL_TIPO_ID,
         :IMOVEL_UNIDADE_ID, :TB_BAIRRO_ID, :VAREA,
         :CONJUNTO, :BLOCO, :SIGLA_ID, :TIPO_COMPLEMENTAR_DESC,
         :TIPO_QUADRA, :NOME_EDIFICIO_DF, :COMPLEMENTO, :TIPO_COMPLEMENTAR,
         :IMOVEL_FICHAAUXILIAR_ID, :VAREA_DESCRITIVA, :NUMERO_UNIDADE_2,
         :v_pessoa_id_temp, :v_numero_ato  DO
    BEGIN
      PROPRIETARIOS = '';
      IF (:TIPO_CLASSE = 'R') THEN --Rural
      BEGIN
        AREA = :VAREA_DESCRITIVA;
      END
      ELSE
      BEGIN
        AREA = :VAREA;
      END

      --PEGAR PROPRIETARIOS
      if (COALESCE(:V_TRAZER_PROPRIETARIOS,'') = 'S') then
      begin
        FOR SELECT V.NOME, V.CPF_CNPJ FROM R_PESSOA_VINCULO V, r_tb_tipo_vinculo TV
            WHERE TV.tb_tipo_vinculo_id = V.tb_tipo_vinculo_id
            AND V.imovel_id = :IMOVEL_ID
            AND TV.usar_na_doi = 'S'
            AND V.data_transferencia IS NULL INTO
            :V_NOME_PROPRIETARIO, :V_CPF_PROPRIETARIO DO
        BEGIN
          if (COALESCE(:PROPRIETARIOS, '') = '') then
          begin
            PROPRIETARIOS = :V_NOME_PROPRIETARIO;
          end
          else
          begin
            PROPRIETARIOS = :PROPRIETARIOS||' - '||:V_NOME_PROPRIETARIO;
          end
          if (COALESCE(:V_CPF_PROPRIETARIO, '') <> '') then
          begin
            PROPRIETARIOS = :PROPRIETARIOS||' '||:V_CPF_PROPRIETARIO;
          end
        END
      END

      V_COUNT = 0;
      IF (:V_OMITIR_TRANSMITENTES = 'S') THEN
      BEGIN
        SELECT count(*) FROM R_PESSOA_VINCULO V, r_tb_tipo_vinculo TV
        WHERE TV.tb_tipo_vinculo_id = V.tb_tipo_vinculo_id
        AND V.imovel_id = :IMOVEL_ID
        AND V.pessoa_id = :v_pessoa_id_temp
        AND TV.tipo_vinculo = '3' --tipo_vinculo transmitente
        and coalesce(v.numero_ato,0) >= :v_numero_ato
        INTO :V_COUNT;
      END

      if (:V_COUNT = 0) then
      begin
        SUSPEND;
      end
    END
  END
END ^

ALTER PROCEDURE R_PESQUISA_IMOVEIS_POR_UNIDADE (V_IMOVEL_UNIDADE_ID VARCHAR(16) CHARACTER SET ISO8859_1)
RETURNS (NUMERO_UNIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
IMOVEL_ID NUMERIC(18, 2),
TIPO_CLASSE VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO NUMERIC(18, 2),
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
SITUACAO VARCHAR(1) CHARACTER SET ISO8859_1,
IMOVEL_FICHAAUXILIAR_ID NUMERIC(18, 2),
QUADRA VARCHAR(60) CHARACTER SET ISO8859_1,
BLOCO VARCHAR(10) CHARACTER SET ISO8859_1,
TB_BAIRRO_ID NUMERIC(18, 2),
SIGLA_ID NUMERIC(18, 2),
TIPO_COMPLEMENTAR VARCHAR(10) CHARACTER SET ISO8859_1,
TIPO_COMPLEMENTAR_DESC VARCHAR(30) CHARACTER SET ISO8859_1,
TIPO_QUADRA VARCHAR(3) CHARACTER SET ISO8859_1,
NOME_EDIFICACAO VARCHAR(90) CHARACTER SET ISO8859_1,
IMOVEL_TIPO_ID NUMERIC(18, 2),
IMOVEL_UNIDADE_ID NUMERIC(18, 2),
AREA_ESPECIAL VARCHAR(10) CHARACTER SET ISO8859_1,
PROJECAO VARCHAR(10) CHARACTER SET ISO8859_1,
TRECHO VARCHAR(10) CHARACTER SET ISO8859_1,
AREA_OCTOGONAL VARCHAR(10) CHARACTER SET ISO8859_1,
CHACARA VARCHAR(10) CHARACTER SET ISO8859_1,
CASA VARCHAR(10) CHARACTER SET ISO8859_1,
NOME_EDIFICIO_DF VARCHAR(90) CHARACTER SET ISO8859_1,
NOVO VARCHAR(1) CHARACTER SET ISO8859_1,
CONJUNTO VARCHAR(10) CHARACTER SET ISO8859_1,
AREA VARCHAR(20) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE VSQL VARCHAR(1024);
BEGIN
  VSQL = 'SELECT I.IMOVEL_ID, I.TIPO_CLASSE, I.TIPO_REGISTRO,
                I.NUMERO, I.NUMERO_LETRA, I.SITUACAO,
                U.IMOVEL_FICHAAUXILIAR_ID,
                U.QUADRA, U.BLOCO, U.TB_BAIRRO_ID, U.SIGLA_ID,
                U.TIPO_COMPLEMENTAR, U.TIPO_COMPLEMENTAR_DESC,
                U.TIPO_QUADRA, U.NUMERO_UNIDADE, U.NOME_EDIFICACAO,
                U.IMOVEL_TIPO_ID, U.IMOVEL_UNIDADE_ID, U.AREA_ESPECIAL,
                U.PROJECAO, U.TRECHO, U.AREA_OCTOGONAL, U.CHACARA,
                U.CASA, U.NOME_EDIFICIO_DF, U.NOVO, U.CONJUNTO, U.AREA
                FROM R_IMOVEL I, R_IMOVEL_UNIDADE U
                WHERE I.IMOVEL_ID = U.IMOVEL_ID 
                AND U.IMOVEL_UNIDADE_ID = '|| :V_IMOVEL_UNIDADE_ID ;
  VSQL = :VSQL ||' ORDER BY U.SIGLA_ID, U.QUADRA, U.BLOCO ';
  FOR EXECUTE STATEMENT VSQL
      INTO   :IMOVEL_ID, :TIPO_CLASSE, :TIPO_REGISTRO, :NUMERO, :NUMERO_LETRA, :SITUACAO,  :IMOVEL_FICHAAUXILIAR_ID, :QUADRA, :BLOCO, :TB_BAIRRO_ID, :SIGLA_ID, :TIPO_COMPLEMENTAR, :TIPO_COMPLEMENTAR_DESC, :TIPO_QUADRA, :NUMERO_UNIDADE, :NOME_EDIFICACAO,
             :IMOVEL_TIPO_ID, :IMOVEL_UNIDADE_ID, :AREA_ESPECIAL, :PROJECAO, :TRECHO, :AREA_OCTOGONAL, :CHACARA, :CASA, :NOME_EDIFICIO_DF, :NOVO, :CONJUNTO, :AREA DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_PESQUISA_IMOVEL_TIPO_UNID (V_IMOVEL_TIPO VARCHAR(100) CHARACTER SET ISO8859_1,
V_TIPO_REGISTRO VARCHAR(5) CHARACTER SET ISO8859_1)
RETURNS (TIPO_REGISTRO VARCHAR(3) CHARACTER SET ISO8859_1,
NUMERO VARCHAR(20) CHARACTER SET ISO8859_1,
ENDERECO VARCHAR(500) CHARACTER SET ISO8859_1,
INSCRICAO_MUNICIPAL VARCHAR(100) CHARACTER SET ISO8859_1,
AREA_TOTAL VARCHAR(30) CHARACTER SET ISO8859_1,
TIPO_UNIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
SIGLA VARCHAR(120) CHARACTER SET ISO8859_1)
AS 
declare variable v_numero_registro varchar(15);
  declare variable v_numero_letra varchar(3);
  declare variable v_area varchar(30);
  declare variable v_area_averbada varchar(30);
  declare variable v_cartorio varchar(3);

  declare variable v_endereco varchar(260);
  declare variable v_numero_logradouro varchar(15);
  declare variable v_complemento varchar(260);
  declare variable v_bairro varchar(90);
  declare variable v_sql varchar(3000);
begin
  tipo_registro = :v_tipo_registro;
  v_numero_registro = '';
  v_numero_letra = '';
  inscricao_municipal = '';
  v_area = '';
  v_area_averbada = '';
  v_cartorio = '';
  tipo_unidade = '';
  v_bairro = '';

  for select CAST(i.numero AS INTEGER),
        COALESCE(I.NUMERO_LETRA,''),
        I.inscricao_imovel, u.area, u.area_averbada,
        i.cartorio, t.descricao
      from r_imovel i, r_imovel_unidade u, r_imovel_tipo t
      where i.imovel_id = u.imovel_id
      and u.imovel_tipo_id = t.imovel_tipo_id
      and i.tipo_registro = :v_tipo_registro
      and u.imovel_tipo_id = :v_imovel_tipo
      order by i.numero
      into :v_numero_registro, :v_numero_letra, :inscricao_municipal, :v_area,
        :v_area_averbada, :v_cartorio, :tipo_unidade do
  begin
    --numero
    numero = :v_numero_registro;
    if (coalesce(:v_numero_letra,'') <> '') then
    begin
      numero = :numero||:v_numero_letra;
    end

    --area
    area_total = '';
    if (coalesce(:v_area_averbada,'') = '') then
    begin
      area_total = :v_area;
    end
    else
    begin
      area_total = :v_area_averbada;
    end

    --endereco
    endereco = '';
    sigla = '';
    select first 1 ENDERECO, NUMERO_LOGRADOURO, COMPLEMENTO_COMPLETO, BAIRRO, sigla
    from r_dados_imovel(:v_tipo_registro,:v_numero_registro, :v_numero_registro, :v_numero_letra, :v_cartorio)
    into :v_endereco, :v_numero_logradouro, :v_complemento, :v_bairro, :sigla;

    if (coalesce(v_endereco,'') <> '') then
    begin
      endereco = :v_endereco;
    end
    if (coalesce(v_numero_logradouro,'') <> '') then
    begin
      if (coalesce(:endereco,'') = '') then
      begin
        endereco = 'nr.'||:v_numero_logradouro;
      end
      else
      begin
        endereco = :endereco || ', nr.'||:v_numero_logradouro;
      end
    end
    if (coalesce(v_complemento,'') <> '') then
    begin
      if (coalesce(:endereco,'') = '') then
      begin
        endereco = :v_complemento;
      end
      else
      begin
        endereco = :endereco || ', '||:v_complemento;
      end
    end
    if (coalesce(v_bairro,'') <> '') then
    begin
      if (coalesce(:endereco,'') = '') then
      begin
        endereco = :v_bairro;
      end
      else
      begin
        endereco = :endereco || ', '||:v_bairro;
      end
    end
    suspend;
  end
end ^

ALTER PROCEDURE R_PESQUISA_LRI_PESSOA (V_PESSOA_ID INTEGER,
V_NOME VARCHAR(120) CHARACTER SET ISO8859_1 DEFAULT '',
V_CPF_CNPJ VARCHAR(120) CHARACTER SET ISO8859_1 DEFAULT '',
V_DOCUMENTO VARCHAR(120) CHARACTER SET ISO8859_1 DEFAULT '')
RETURNS (LRI_ID INTEGER,
OFICIO VARCHAR(260) CHARACTER SET ISO8859_1,
PROTOCOLO_PROCESSO VARCHAR(260) CHARACTER SET ISO8859_1,
ORIGEM VARCHAR(260) CHARACTER SET ISO8859_1,
FORUM_VARA VARCHAR(260) CHARACTER SET ISO8859_1,
DATA TIMESTAMP,
DATA_PEDIDO TIMESTAMP,
IMOVEIS_INFORMADOS_CNIB VARCHAR(1000) CHARACTER SET ISO8859_1,
OFICIO_CANCELAMENTO VARCHAR(260) CHARACTER SET ISO8859_1,
TIPO_CANCELAMENTO VARCHAR(20) CHARACTER SET ISO8859_1,
DATA_CANCELAMENTO TIMESTAMP,
OBSERVACOES VARCHAR(260) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_TB_ORIGEM_LRI_ID INTEGER;
  DECLARE VARIABLE V_TIPO_IMOVEL VARCHAR(1);
  DECLARE VARIABLE V_NUMERO INTEGER;
  DECLARE VARIABLE V_TEMP VARCHAR(30);
  DECLARE VARIABLE V_LRI_CANCELAMENTO_ID INTEGER;
  DECLARE VARIABLE V_QTDE INTEGER;
  DECLARE VARIABLE V_TIPO_CANCELAMENTO VARCHAR(1);
  declare variable VSQL VARCHAR(3000);
BEGIN
  if (COALESCE(:V_PESSOA_ID,0) > 0) then
  BEGIN
    DATA_CANCELAMENTO = NULL;
    FOR SELECT DISTINCT L.LRI_ID, L.OFICIO, L.PROTOCOLO_PROCESSO,
          COALESCE(L.TB_ORIGEM_LRI_ID,0), L.FORUM_VARA, CAST(L.DATA AS DATE), CAST(L.DATA_PEDIDO AS DATE),
          V.DATA_TRANSFERENCIA, L.OBSERVACOES
        FROM R_LRI L, R_PESSOA_VINCULO V
        WHERE L.LRI_ID = V.LRI_ID
        AND V.PESSOA_ID = :V_PESSOA_ID
        ORDER BY L.DATA_PEDIDO, L.LRI_ID
        INTO :LRI_ID, :OFICIO, :PROTOCOLO_PROCESSO, :V_TB_ORIGEM_LRI_ID,
          :FORUM_VARA, :DATA, :DATA_PEDIDO, :DATA_CANCELAMENTO, :OBSERVACOES DO
    BEGIN
      SELECT DESCRICAO FROM R_TB_ORIGEM_LRI
      WHERE TB_ORIGEM_LRI_ID = :V_TB_ORIGEM_LRI_ID
      INTO :ORIGEM;
  
      IMOVEIS_INFORMADOS_CNIB = '';
      FOR SELECT TIPO_IMOVEL, NUMERO FROM R_LRI_IMOVEL
          WHERE LRI_ID = :LRI_ID
          INTO :V_TIPO_IMOVEL, :V_NUMERO DO
      BEGIN
        IF (:V_TIPO_IMOVEL = 'T') THEN
        BEGIN
          V_TEMP = 'TRANSC.'||:V_NUMERO;
        END
        ELSE
        BEGIN
          V_TEMP = :V_NUMERO;
        END
        IF (:IMOVEIS_INFORMADOS_CNIB = '') THEN
        BEGIN
          IMOVEIS_INFORMADOS_CNIB = :V_TEMP;
        END
        ELSE
        BEGIN
          IF (CHAR_LENGTH(:IMOVEIS_INFORMADOS_CNIB) < 950) THEN
          BEGIN
            IMOVEIS_INFORMADOS_CNIB = :IMOVEIS_INFORMADOS_CNIB ||'; '||:V_TEMP;
          END
        END    
      END
  
      if (:DATA_CANCELAMENTO IS NULL) then
      BEGIN
        OFICIO_CANCELAMENTO = '';
        V_LRI_CANCELAMENTO_ID = 0;
        TIPO_CANCELAMENTO = '';
        V_TIPO_CANCELAMENTO = '';
        --VERIFICAR SE TEM CANCELAMENTO TOTAL OU PARCIAL
        SELECT FIRST 1 LRI_CANCELAMENTO_ID FROM R_PESSOA_VINCULO
        WHERE LRI_ID = :LRI_ID
        AND LRI_CANCELAMENTO_ID > 0
        INTO :V_LRI_CANCELAMENTO_ID;
        IF (COALESCE(:V_LRI_CANCELAMENTO_ID,0) = 0) THEN
        BEGIN
          --VERIFCAR CANCELAMENTOS DE ORDENS ESPECIFICAS DE IMOVEIS
          SELECT FIRST 1 LRI_CANCELAMENTO_ID FROM R_LRI_IMOVEL
          WHERE LRI_ID = :LRI_ID
          AND LRI_CANCELAMENTO_ID > 0
          INTO :V_LRI_CANCELAMENTO_ID;
        END
        --SE ALGUMA ORDEM DE CANCELAMENTO FOI ENCONTRADO
        IF (COALESCE(:V_LRI_CANCELAMENTO_ID,0) > 0) THEN
        BEGIN
          FOR SELECT LRI_CANCELAMENTO_ID FROM R_PESSOA_VINCULO
              WHERE LRI_ID = :LRI_ID
              AND LRI_CANCELAMENTO_ID > 0
              UNION
              SELECT LRI_CANCELAMENTO_ID FROM R_LRI_IMOVEL
              WHERE LRI_ID = :LRI_ID
              AND LRI_CANCELAMENTO_ID > 0
              ORDER BY 1
              INTO :V_LRI_CANCELAMENTO_ID DO
          BEGIN
            SELECT OFICIO_CANCELAMENTO, CANCELAMENTO_TIPO, CAST(DATA_CANCELAMENTO AS DATE)
            FROM R_LRI_CANCELAMENTO
            WHERE LRI_CANCELAMENTO_ID = :V_LRI_CANCELAMENTO_ID
            INTO :OFICIO_CANCELAMENTO, :V_TIPO_CANCELAMENTO, :DATA_CANCELAMENTO;
            IF (:V_TIPO_CANCELAMENTO = '2') THEN
            BEGIN
              TIPO_CANCELAMENTO = 'PESSOA';
            END
            ELSE IF (:V_TIPO_CANCELAMENTO = '3') THEN
            BEGIN
              TIPO_CANCELAMENTO = 'MATRÍCULA';
            END
            ELSE
            BEGIN
              TIPO_CANCELAMENTO = 'TOTAL';
            END
            SUSPEND;
          END
        END
        ELSE
        BEGIN
          SUSPEND;
        END
      END
      ELSE
      BEGIN
        SUSPEND;
      END
    END
  END
  ELSE
  BEGIN
    DATA_CANCELAMENTO = NULL;


    VSQL = 'SELECT DISTINCT L.LRI_ID, L.OFICIO, L.PROTOCOLO_PROCESSO,
          COALESCE(L.TB_ORIGEM_LRI_ID,0), L.FORUM_VARA, CAST(L.DATA AS DATE), CAST(L.DATA_PEDIDO AS DATE),
          V.DATA_TRANSFERENCIA, L.OBSERVACOES
        FROM R_LRI L, R_PESSOA_VINCULO V
        WHERE L.LRI_ID = V.LRI_ID ';

    if (COALESCE(:V_CPF_CNPJ,'') <> '') then
    begin
      VSQL = :VSQL || ' AND V.cpf_cnpj = '||''''||:V_CPF_CNPJ||'''';
    end
    if (COALESCE(:V_DOCUMENTO,'') <> '') then
    begin
      VSQL = :VSQL || ' AND V.DOCUMENTO = '||''''||:V_DOCUMENTO||'''';
    end
    if (COALESCE(:V_NOME,'') <> '') then
    begin
      VSQL = :VSQL || ' AND V.NOME LIKE '||''''||:V_NOME||'''';
    end
    VSQL = :VSQL || ' ORDER BY L.DATA_PEDIDO, L.LRI_ID ';

    if ((COALESCE(:V_CPF_CNPJ,'') <> '') or (COALESCE(:V_DOCUMENTO,'') <> '') or (COALESCE(:V_NOME,'') <> '')) then
    begin
      FOR EXECUTE STATEMENT VSQL
        INTO :LRI_ID, :OFICIO, :PROTOCOLO_PROCESSO, :V_TB_ORIGEM_LRI_ID,
          :FORUM_VARA, :DATA, :DATA_PEDIDO, :DATA_CANCELAMENTO, :OBSERVACOES DO
      BEGIN
        SELECT DESCRICAO FROM R_TB_ORIGEM_LRI
        WHERE TB_ORIGEM_LRI_ID = :V_TB_ORIGEM_LRI_ID
        INTO :ORIGEM;
    
        IMOVEIS_INFORMADOS_CNIB = '';
        FOR SELECT TIPO_IMOVEL, NUMERO FROM R_LRI_IMOVEL
            WHERE LRI_ID = :LRI_ID
            INTO :V_TIPO_IMOVEL, :V_NUMERO DO
        BEGIN
          IF (:V_TIPO_IMOVEL = 'T') THEN
          BEGIN
            V_TEMP = 'TRANSC.'||:V_NUMERO;
          END
          ELSE
          BEGIN
            V_TEMP = :V_NUMERO;
          END
          IF (:IMOVEIS_INFORMADOS_CNIB = '') THEN
          BEGIN
            IMOVEIS_INFORMADOS_CNIB = :V_TEMP;
          END
          ELSE
          BEGIN
            IF (CHAR_LENGTH(:IMOVEIS_INFORMADOS_CNIB) < 950) THEN
            BEGIN
              IMOVEIS_INFORMADOS_CNIB = :IMOVEIS_INFORMADOS_CNIB ||'; '||:V_TEMP;
            END
          END    
        END
    
        if (:DATA_CANCELAMENTO IS NULL) then
        BEGIN
          OFICIO_CANCELAMENTO = '';
          V_LRI_CANCELAMENTO_ID = 0;
          TIPO_CANCELAMENTO = '';
          V_TIPO_CANCELAMENTO = '';
          --VERIFICAR SE TEM CANCELAMENTO TOTAL OU PARCIAL
          SELECT FIRST 1 LRI_CANCELAMENTO_ID FROM R_PESSOA_VINCULO
          WHERE LRI_ID = :LRI_ID
          AND LRI_CANCELAMENTO_ID > 0
          INTO :V_LRI_CANCELAMENTO_ID;
          IF (COALESCE(:V_LRI_CANCELAMENTO_ID,0) = 0) THEN
          BEGIN
            --VERIFCAR CANCELAMENTOS DE ORDENS ESPECIFICAS DE IMOVEIS
            SELECT FIRST 1 LRI_CANCELAMENTO_ID FROM R_LRI_IMOVEL
            WHERE LRI_ID = :LRI_ID
            AND LRI_CANCELAMENTO_ID > 0
            INTO :V_LRI_CANCELAMENTO_ID;
          END
          --SE ALGUMA ORDEM DE CANCELAMENTO FOI ENCONTRADO
          IF (COALESCE(:V_LRI_CANCELAMENTO_ID,0) > 0) THEN
          BEGIN
            FOR SELECT LRI_CANCELAMENTO_ID FROM R_PESSOA_VINCULO
                WHERE LRI_ID = :LRI_ID
                AND LRI_CANCELAMENTO_ID > 0
                UNION
                SELECT LRI_CANCELAMENTO_ID FROM R_LRI_IMOVEL
                WHERE LRI_ID = :LRI_ID
                AND LRI_CANCELAMENTO_ID > 0
                ORDER BY 1
                INTO :V_LRI_CANCELAMENTO_ID DO
            BEGIN
              SELECT OFICIO_CANCELAMENTO, CANCELAMENTO_TIPO, CAST(DATA_CANCELAMENTO AS DATE)
              FROM R_LRI_CANCELAMENTO
              WHERE LRI_CANCELAMENTO_ID = :V_LRI_CANCELAMENTO_ID
              INTO :OFICIO_CANCELAMENTO, :V_TIPO_CANCELAMENTO, :DATA_CANCELAMENTO;
              IF (:V_TIPO_CANCELAMENTO = '2') THEN
              BEGIN
                TIPO_CANCELAMENTO = 'PESSOA';
              END
              ELSE IF (:V_TIPO_CANCELAMENTO = '3') THEN
              BEGIN
                TIPO_CANCELAMENTO = 'MATRÍCULA';
              END
              ELSE
              BEGIN
                TIPO_CANCELAMENTO = 'TOTAL';
              END
              SUSPEND;
            END
          END
          ELSE
          BEGIN
            SUSPEND;
          END
        END
        ELSE
        BEGIN
          SUSPEND;
        END
      END
    END
  END
END ^

ALTER PROCEDURE R_PESQUISA_ONUS (V_TIPO_PESQUISA VARCHAR(3) CHARACTER SET ISO8859_1,
V_COM_OU_SEM_ONUS VARCHAR(3) CHARACTER SET ISO8859_1,
V_DATA_INICIAL_LANC VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FINAL_LANC VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_INICIAL_CONF VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FINAL_CONF VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUMERO_INI VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_FIM VARCHAR(10) CHARACTER SET ISO8859_1,
V_USUARIO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_NATUREZAS VARCHAR(120) CHARACTER SET ISO8859_1,
V_JUNTAR_MATRICULAS VARCHAR(3) CHARACTER SET ISO8859_1,
V_NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (IMOVEL_ID NUMERIC(18, 2),
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO NUMERIC(12, 2),
DATA_LANC TIMESTAMP,
DATA_CONF TIMESTAMP,
DATA_BAIXA TIMESTAMP,
DATA_CANC TIMESTAMP,
USUARIO_ID_LANC NUMERIC(12, 2),
USUARIO_ID_CONF NUMERIC(12, 2),
USUARIO_ID_CANC NUMERIC(12, 2),
USUARIO_ID_BAIXA NUMERIC(12, 2),
USUARIO_ID_CONF_BAIXA NUMERIC(12, 2),
NOME_USUARIO_ID_LANC VARCHAR(30) CHARACTER SET ISO8859_1,
NOME_USUARIO_ID_CONF VARCHAR(30) CHARACTER SET ISO8859_1,
NOME_USUARIO_ID_CANC VARCHAR(30) CHARACTER SET ISO8859_1,
NOME_USUARIO_ID_BAIXA VARCHAR(30) CHARACTER SET ISO8859_1,
NOME_USUARIO_ID_CONF_BAIXA VARCHAR(30) CHARACTER SET ISO8859_1,
NATUREZA_TITULO_ID NUMERIC(12, 2),
DESCRICAO_NATUREZA VARCHAR(120) CHARACTER SET ISO8859_1,
ATO_TIPO VARCHAR(1) CHARACTER SET ISO8859_1,
ATO_NUMERO NUMERIC(12, 2),
EXISTE_ONUS VARCHAR(3) CHARACTER SET ISO8859_1,
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_MATRICULA_INI VARCHAR(10);
  DECLARE VARIABLE V_MATRICULA_FIM VARCHAR(10);
  DECLARE VARIABLE V_NUMERO_ANTERIOR NUMERIC(12,2);
  DECLARE VARIABLE V_IDX INTEGER;
  DECLARE VARIABLE V_NATUREZA_TITULO_ID VARCHAR(20);
  DECLARE VARIABLE V_TAMANHO INTEGER;
  DECLARE VARIABLE V_RETORNAR VARCHAR(1);
  DECLARE VARIABLE V_NATUREZA_WHILE VARCHAR(120);
BEGIN
  IF (:V_NUMERO_INI IS NULL) THEN
  BEGIN
    V_MATRICULA_INI = '0';
    V_MATRICULA_FIM = '9999999';
  END
  ELSE
  BEGIN
    V_MATRICULA_INI = :V_NUMERO_INI;
    V_MATRICULA_FIM = :V_NUMERO_FIM;
  END
  
  IF ((:V_NUMERO_LETRA IS NULL) OR (:V_NUMERO_LETRA = '') OR (:V_NUMERO_LETRA = '''') OR (:V_NUMERO_LETRA = '#')) THEN
  BEGIN
    IF (:V_TIPO_PESQUISA = 'L') THEN  --POR DATA DE LANCAMENTO
    BEGIN
      V_NUMERO_ANTERIOR = 0;
      FOR SELECT I.IMOVEL_ID, I.TIPO_REGISTRO, I.NUMERO, I.NUMERO_LETRA,
               IH.DATA_LANC, IH.DATA_CONF, IH.DATA_BAIXA,
               IH.DATA_CANC, IH.USUARIO_ID_LANC,
               IH.USUARIO_ID_CONF, IH.USUARIO_ID_CANC,
               IH.USUARIO_ID_BAIXA, IH.USUARIO_ID_CONF_BAIXA,
               IH.NATUREZA_TITULO_ID
        FROM   R_IMOVEL I, R_IMOVEL_HISTORICO IH
        WHERE  I.IMOVEL_ID = IH.IMOVEL_ID
        AND    IH.DATA_CANC IS NULL
        AND    I.NUMERO BETWEEN :V_MATRICULA_INI AND :V_MATRICULA_FIM
        AND    (I.NUMERO_LETRA IS NULL OR I.NUMERO_LETRA = '' OR I.NUMERO_LETRA = '#')
        AND    IH.DATA_LANC BETWEEN CAST(:V_DATA_INICIAL_LANC AS TIMESTAMP)
                                AND CAST(:V_DATA_FINAL_LANC AS TIMESTAMP) + 0.99999
        ORDER  BY I.NUMERO ASC, IH.DATA_LANC DESC
        INTO   :IMOVEL_ID, :TIPO_REGISTRO, :NUMERO, :NUMERO_LETRA,
               :DATA_LANC, :DATA_CONF, :DATA_BAIXA,
               :DATA_CANC, :USUARIO_ID_LANC,
               :USUARIO_ID_CONF, :USUARIO_ID_CANC,
               :USUARIO_ID_BAIXA, :USUARIO_ID_CONF_BAIXA, :NATUREZA_TITULO_ID DO
      BEGIN
        SELECT EXISTE_ONUS
        FROM R_BUSCA_ONUS(:IMOVEL_ID)
        INTO :EXISTE_ONUS;
        IF  (:V_COM_OU_SEM_ONUS = 'T') THEN
        BEGIN
          V_RETORNAR = 'S';
        END
        ELSE IF ((:V_COM_OU_SEM_ONUS = 'C') AND (:EXISTE_ONUS = 'S')) THEN
        BEGIN
          V_RETORNAR = 'S';
        END
        ELSE IF ((:V_COM_OU_SEM_ONUS = 'S') AND (:EXISTE_ONUS = 'N')) THEN
        BEGIN
          V_RETORNAR = 'S';
        END
        ELSE
        BEGIN
          V_RETORNAR = 'N';
        END
        IF ((:V_NATUREZAS IS NOT NULL) AND (:V_RETORNAR = 'S')) THEN
        BEGIN
          V_RETORNAR = 'N';
          V_NATUREZA_WHILE = :V_NATUREZAS;
          WHILE (V_NATUREZA_WHILE <> '') DO
          BEGIN
            SELECT TAMANHO FROM W_LENGTH(:V_NATUREZA_WHILE) INTO :V_TAMANHO;
            SELECT POS FROM W_POS(',', :V_NATUREZA_WHILE) INTO :V_IDX;
            IF (:V_IDX = 0) THEN
            BEGIN
              V_NATUREZA_TITULO_ID = V_NATUREZA_WHILE;
              V_NATUREZA_WHILE = '';
            END
            ELSE
            BEGIN
              V_NATUREZA_TITULO_ID = SUBSTRING(V_NATUREZA_WHILE FROM 1 FOR V_IDX - 1);
              V_NATUREZA_WHILE = SUBSTRING(V_NATUREZA_WHILE FROM V_IDX + 1 FOR V_TAMANHO - V_IDX);
            END
            IF (CAST(:V_NATUREZA_TITULO_ID AS INTEGER) = CAST(:NATUREZA_TITULO_ID AS INTEGER)) THEN
            BEGIN
              V_RETORNAR = 'S';
            END
          END
        END

        IF (:V_RETORNAR = 'S') THEN
        BEGIN
          NOME_USUARIO_ID_LANC = '';
          NOME_USUARIO_ID_CONF = '';
          NOME_USUARIO_ID_CANC = '';
          NOME_USUARIO_ID_BAIXA = '';
          NOME_USUARIO_ID_CONF_BAIXA = '';
          
          IF (:NATUREZA_TITULO_ID IS NULL) THEN
          BEGIN                     
            DESCRICAO_NATUREZA = '';        
          END
          ELSE
          BEGIN
            SELECT DESCRICAO FROM G_NATUREZA_TITULO
            WHERE NATUREZA_TITULO_ID = :NATUREZA_TITULO_ID
            INTO :DESCRICAO_NATUREZA;
          END
          
          IF (:USUARIO_ID_LANC IS NOT NULL) THEN
          BEGIN
            SELECT LOGIN FROM G_USUARIO
            WHERE USUARIO_ID = :USUARIO_ID_LANC
            INTO :NOME_USUARIO_ID_LANC;
          END
          IF (:USUARIO_ID_CONF IS NOT NULL) THEN
          BEGIN
            SELECT LOGIN FROM G_USUARIO
            WHERE USUARIO_ID = :USUARIO_ID_CONF
            INTO :NOME_USUARIO_ID_CONF;
          END
          IF (:USUARIO_ID_CANC IS NOT NULL) THEN
          BEGIN
            SELECT LOGIN FROM G_USUARIO
            WHERE USUARIO_ID = :USUARIO_ID_CANC
            INTO :NOME_USUARIO_ID_CANC;
          END
          IF (:USUARIO_ID_BAIXA IS NOT NULL) THEN
          BEGIN
            SELECT LOGIN FROM G_USUARIO
            WHERE USUARIO_ID = :USUARIO_ID_BAIXA
            INTO :NOME_USUARIO_ID_BAIXA;
          END
          IF (:USUARIO_ID_CONF_BAIXA IS NOT NULL) THEN
          BEGIN
            SELECT LOGIN FROM G_USUARIO
            WHERE USUARIO_ID = :USUARIO_ID_CONF_BAIXA
            INTO :NOME_USUARIO_ID_CONF_BAIXA;
          END
          IF ((:V_USUARIO_ID <> '') AND (:V_USUARIO_ID IS NOT NULL)) THEN
          BEGIN
            IF (:V_USUARIO_ID = :USUARIO_ID_LANC) THEN
            BEGIN
              IF (:V_JUNTAR_MATRICULAS IS NOT NULL) THEN
              BEGIN
                IF (CAST(:NUMERO AS INTEGER) <> CAST(:V_NUMERO_ANTERIOR AS INTEGER)) THEN
                  SUSPEND;
              END
              ELSE
              BEGIN
                SUSPEND;
              END
            END
          END
          ELSE
          BEGIN
            IF (:V_JUNTAR_MATRICULAS IS NOT NULL) THEN
            BEGIN
              IF (CAST(:NUMERO AS INTEGER) <> CAST(:V_NUMERO_ANTERIOR AS INTEGER)) THEN
                SUSPEND;
            END
            ELSE
            BEGIN
              SUSPEND;
            END
          END
        END
        V_NUMERO_ANTERIOR = :NUMERO;
      END
    END
    ELSE IF (:V_TIPO_PESQUISA = 'C') THEN  --POR DATA DE CONFIRMACAO
    BEGIN
      V_NUMERO_ANTERIOR = 0;
      FOR SELECT I.IMOVEL_ID, I.TIPO_REGISTRO, I.NUMERO, I.NUMERO_LETRA,
               IH.DATA_LANC, IH.DATA_CONF, IH.DATA_BAIXA,
               IH.DATA_CANC, IH.USUARIO_ID_LANC,
               IH.USUARIO_ID_CONF, IH.USUARIO_ID_CANC,
               IH.USUARIO_ID_BAIXA, IH.USUARIO_ID_CONF_BAIXA,
               IH.NATUREZA_TITULO_ID
        FROM   R_IMOVEL I, R_IMOVEL_HISTORICO IH
        WHERE  I.IMOVEL_ID = IH.IMOVEL_ID
        AND    IH.DATA_CANC IS NULL
        AND    I.NUMERO BETWEEN :V_MATRICULA_INI AND :V_MATRICULA_FIM
        AND    (I.NUMERO_LETRA IS NULL OR I.NUMERO_LETRA = '' OR I.NUMERO_LETRA = '#')
        AND    IH.DATA_CONF BETWEEN CAST(:V_DATA_INICIAL_CONF AS TIMESTAMP)
                                AND CAST(:V_DATA_FINAL_CONF AS TIMESTAMP) + 0.99999
        INTO   :IMOVEL_ID, :TIPO_REGISTRO, :NUMERO, :NUMERO_LETRA,
