          V_RETORNAR = 'N';
        END

        IF ((:V_NATUREZAS IS NOT NULL) AND (:V_RETORNAR = 'S')) THEN
        BEGIN
          V_RETORNAR = 'N';
          V_NATUREZA_WHILE = :V_NATUREZAS;
          WHILE (V_NATUREZA_WHILE <> '') DO
          BEGIN
            SELECT TAMANHO FROM W_LENGTH(:V_NATUREZA_WHILE) INTO :V_TAMANHO;
            SELECT POS FROM W_POS(',', :V_NATUREZA_WHILE) INTO :V_IDX;
            IF (:V_IDX = 0) THEN
            BEGIN
              V_NATUREZA_TITULO_ID = V_NATUREZA_WHILE;
              V_NATUREZA_WHILE = '';
            END
            ELSE
            BEGIN
              V_NATUREZA_TITULO_ID = SUBSTRING(V_NATUREZA_WHILE FROM 1 FOR V_IDX - 1);
              V_NATUREZA_WHILE = SUBSTRING(V_NATUREZA_WHILE FROM V_IDX + 1 FOR V_TAMANHO - V_IDX);
            END
            IF (CAST(:V_NATUREZA_TITULO_ID AS INTEGER) = CAST(:NATUREZA_TITULO_ID AS INTEGER)) THEN
            BEGIN
              V_RETORNAR = 'S';
            END
          END
        END

        IF (:V_RETORNAR = 'S') THEN
        BEGIN
          NOME_USUARIO_ID_LANC = '';
          NOME_USUARIO_ID_CONF = '';
          NOME_USUARIO_ID_CANC = '';
          NOME_USUARIO_ID_BAIXA = '';
          NOME_USUARIO_ID_CONF_BAIXA = '';
                                  
          IF (:NATUREZA_TITULO_ID IS NULL) THEN
          BEGIN                     
            DESCRICAO_NATUREZA = '';        
          END
          ELSE
          BEGIN
            SELECT DESCRICAO FROM G_NATUREZA_TITULO
            WHERE NATUREZA_TITULO_ID = :NATUREZA_TITULO_ID
            INTO :DESCRICAO_NATUREZA;
          END

          IF (:USUARIO_ID_LANC IS NOT NULL) THEN
          BEGIN
            SELECT LOGIN FROM G_USUARIO
            WHERE USUARIO_ID = :USUARIO_ID_LANC
            INTO :NOME_USUARIO_ID_LANC;
          END
          IF (:USUARIO_ID_CONF IS NOT NULL) THEN
          BEGIN
            SELECT LOGIN FROM G_USUARIO
            WHERE USUARIO_ID = :USUARIO_ID_CONF
            INTO :NOME_USUARIO_ID_CONF;
          END
          IF (:USUARIO_ID_CANC IS NOT NULL) THEN
          BEGIN
            SELECT LOGIN FROM G_USUARIO
            WHERE USUARIO_ID = :USUARIO_ID_CANC
            INTO :NOME_USUARIO_ID_CANC;
          END
          IF (:USUARIO_ID_BAIXA IS NOT NULL) THEN
          BEGIN
            SELECT LOGIN FROM G_USUARIO
            WHERE USUARIO_ID = :USUARIO_ID_BAIXA
            INTO :NOME_USUARIO_ID_BAIXA;
          END
          IF (:USUARIO_ID_CONF_BAIXA IS NOT NULL) THEN
          BEGIN
            SELECT LOGIN FROM G_USUARIO
            WHERE USUARIO_ID = :USUARIO_ID_CONF_BAIXA
            INTO :NOME_USUARIO_ID_CONF_BAIXA;
          END
          IF (:V_JUNTAR_MATRICULAS IS NOT NULL) THEN
          BEGIN
            IF (CAST(:NUMERO AS INTEGER) <> CAST(:V_NUMERO_ANTERIOR AS INTEGER)) THEN
              SUSPEND;
          END
          ELSE
          BEGIN
            SUSPEND;
          END
        END
        V_NUMERO_ANTERIOR = :NUMERO;
      END
    END  
  END
END ^

ALTER PROCEDURE R_PESQUISA_PEDIDO (V_TIPO_NOME_CPF_PESQUISA VARCHAR(5) CHARACTER SET ISO8859_1,
V_NOME_PESQUISA VARCHAR(120) CHARACTER SET ISO8859_1,
V_CPF_PESQUISA VARCHAR(25) CHARACTER SET ISO8859_1,
V_TIPO_DATA_NUMERO_PESQUISA VARCHAR(5) CHARACTER SET ISO8859_1,
V_DATA_PESQUISA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_PESQUISA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUMERO_PESQUISA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUMERO_PESQUISA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_NATUREZA_TITULO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_EMOLUMENTO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO_CALCULO VARCHAR(5) CHARACTER SET ISO8859_1,
V_PROTOCOLO_CENTRAL VARCHAR(30) CHARACTER SET ISO8859_1,
V_MATRICULA VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_SELO_DF VARCHAR(30) CHARACTER SET ISO8859_1,
V_ENDERECO VARCHAR(300) CHARACTER SET ISO8859_1,
V_NOME_ITEM_PESQUISA VARCHAR(120) CHARACTER SET ISO8859_1,
V_CPF_ITEM_PESQUISA VARCHAR(25) CHARACTER SET ISO8859_1)
RETURNS (PEDIDO_ID INTEGER,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
ADQUIRENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
TRANSMITENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
NUMERO_ORDEM INTEGER,
DATA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_SQL VARCHAR(1024);
BEGIN
  IF ((COALESCE(:V_MATRICULA,'') <> '') or (COALESCE(:V_ENDERECO,'') <> '') or (COALESCE(:V_CPF_ITEM_PESQUISA,'') <> '') OR (COALESCE(:V_NOME_ITEM_PESQUISA,'') <> ''))  THEN
  BEGIN
    V_SQL = 'SELECT DISTINCT P.PEDIDO_ID, P.APRESENTANTE_NOME, P.ADQUIRENTE_NOME, 
               P.TRANSMITENTE_NOME, PR.NUMERO_ORDEM, PR.DATA, PR.TIPO_PROTOCOLO
             FROM R_PEDIDO P, R_PROTOCOLO PR, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN
             WHERE P.PEDIDO_ID = PR.PEDIDO_ID 
             AND P.PEDIDO_ID = PI.PEDIDO_ID
             AND PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID ';
  END
  ELSE IF ((COALESCE(:V_NATUREZA_TITULO_ID,'') <> '') OR (COALESCE(:V_EMOLUMENTO_ID,'') <> '') 
    OR (COALESCE(:V_PROTOCOLO_CENTRAL,'') <> '') OR (COALESCE(:V_NUMERO_SELO_DF,'') <> '')) THEN
  BEGIN
    V_SQL = 'SELECT DISTINCT P.PEDIDO_ID, P.APRESENTANTE_NOME, P.ADQUIRENTE_NOME, 
               P.TRANSMITENTE_NOME, PR.NUMERO_ORDEM, PR.DATA, PR.TIPO_PROTOCOLO
             FROM R_PEDIDO P, R_PROTOCOLO PR, R_PEDIDO_ITEM PI
             WHERE P.PEDIDO_ID = PR.PEDIDO_ID 
             AND P.PEDIDO_ID = PI.PEDIDO_ID ';
  END
  ELSE
  BEGIN
    V_SQL = 'SELECT DISTINCT P.PEDIDO_ID, P.APRESENTANTE_NOME, P.ADQUIRENTE_NOME, 
               P.TRANSMITENTE_NOME, PR.NUMERO_ORDEM, PR.DATA, PR.TIPO_PROTOCOLO
             FROM R_PEDIDO P, R_PROTOCOLO PR
             WHERE P.PEDIDO_ID = PR.PEDIDO_ID ';
  END

  IF (COALESCE(:V_NOME_PESQUISA,'') <> '') THEN
  BEGIN
    IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'AP') THEN
    BEGIN
      V_SQL = :V_SQL || ' AND P.APRESENTANTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||'''';
    END
    ELSE IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'AD') THEN
    BEGIN
      V_SQL = :V_SQL || ' AND P.ADQUIRENTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||'''';
    END    
    ELSE IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'TR') THEN
    BEGIN
      V_SQL = :V_SQL || ' AND P.TRANSMITENTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||'''';
    END    
    ELSE
    BEGIN
      V_SQL = :V_SQL || ' AND (P.APRESENTANTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||''''||
        ' OR P.ADQUIRENTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||''''||
        ' OR P.TRANSMITENTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||''''||') ';
    END      
  END
  IF (COALESCE(:V_CPF_PESQUISA,'') <> '') THEN
  BEGIN
    IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'AP') THEN
    BEGIN
      V_SQL = :V_SQL || ' AND P.APRESENTANTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||'''';
    END
    ELSE IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'AD') THEN
    BEGIN
      V_SQL = :V_SQL || ' AND P.ADQUIRENTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||'''';
    END    
    ELSE IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'TR') THEN
    BEGIN
      V_SQL = :V_SQL || ' AND P.TRANSMITENTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||'''';
    END    
    ELSE
    BEGIN
      V_SQL = :V_SQL || ' AND (P.APRESENTANTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||''''||
        ' OR P.ADQUIRENTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||''''||
        ' OR P.TRANSMITENTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||''''||') ';
    END      
  END

  IF ((COALESCE(:V_DATA_PESQUISA_INI,'') <> '') AND (COALESCE(:V_DATA_PESQUISA_INI,'') <> '00.00.0000') AND
    (COALESCE(:V_DATA_PESQUISA_INI,'') <> '00/00/0000')) THEN
  BEGIN
    IF (COALESCE(:V_DATA_PESQUISA_FIM,'') = '') THEN
    BEGIN
      V_DATA_PESQUISA_FIM = :V_DATA_PESQUISA_INI;
    END
    V_SQL = :V_SQL || ' AND PR.DATA BETWEEN CAST('||''''||:V_DATA_PESQUISA_INI||''''||' AS TIMESTAMP) '||
      ' AND CAST('||''''||:V_DATA_PESQUISA_FIM||''''||' AS TIMESTAMP) + 0.99999 ';    
  END
  IF (COALESCE(:V_NUMERO_PESQUISA_INI,'') <> '') THEN
  BEGIN
    IF (COALESCE(:V_NUMERO_PESQUISA_FIM,'') = '') THEN
    BEGIN
      V_NUMERO_PESQUISA_FIM = :V_NUMERO_PESQUISA_INI;
    END
    V_SQL = :V_SQL || ' AND PR.NUMERO_ORDEM BETWEEN '||:V_NUMERO_PESQUISA_INI||' AND '||:V_NUMERO_PESQUISA_FIM;
  END
  IF ((COALESCE(:V_TIPO_DATA_NUMERO_PESQUISA,'') = '1') OR 
    (COALESCE(:V_TIPO_DATA_NUMERO_PESQUISA,'') = '2') OR 
    (COALESCE(:V_TIPO_DATA_NUMERO_PESQUISA,'') = '3')) THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = '||''''||:V_TIPO_DATA_NUMERO_PESQUISA||'''';
  END
  IF (COALESCE(:V_NATUREZA_TITULO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PI.NATUREZA_TITULO_ID = '||:V_NATUREZA_TITULO_ID;
  END
  IF (COALESCE(:V_EMOLUMENTO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PI.EMOLUMENTO_ID = '||:V_EMOLUMENTO_ID;
  END
  IF (COALESCE(:V_TIPO_CALCULO,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND P.TIPO_COBRANCA = '||''''||:V_TIPO_CALCULO||'''';
  END
  IF (COALESCE(:V_PROTOCOLO_CENTRAL,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PI.PROTOCOLO_CENTRAL LIKE '||''''||:V_PROTOCOLO_CENTRAL||'%'||'''';
  END    
  IF (COALESCE(:V_MATRICULA,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PN.NUMERO = '||''''||:V_MATRICULA||'''';
  END    
  IF (COALESCE(:V_ENDERECO,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PN.LOGRADOURO LIKE '||''''||:V_ENDERECO||'''';
  END    
  IF (COALESCE(:V_CPF_ITEM_PESQUISA,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND ((PN.CPF = '||''''||:V_CPF_ITEM_PESQUISA||''''||') OR (PN.CONJUGE_CPF = '||''''||:V_CPF_ITEM_PESQUISA||''''||'))';
  END    
  IF (COALESCE(:V_NOME_ITEM_PESQUISA,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND ((PN.NOME STARTING WITH '||''''||:V_NOME_ITEM_PESQUISA||''''||') OR (PN.CONJUGE STARTING WITH '||''''||:V_NOME_ITEM_PESQUISA||''''||'))';
  END
  IF (COALESCE(:V_NUMERO_SELO_DF,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND (PI.NUMERO_SELO LIKE '||''''||:V_NUMERO_SELO_DF||'%'||''''||
      ' OR PR.NUMERO_SELO LIKE '||''''||:V_NUMERO_SELO_DF||'%'||''''||') ';
  END
          
  V_SQL = :V_SQL ||' ORDER BY PR.DATA ';
  
  FOR EXECUTE STATEMENT V_SQL
      INTO :PEDIDO_ID, :APRESENTANTE_NOME, :ADQUIRENTE_NOME, :TRANSMITENTE_NOME, 
        :NUMERO_ORDEM, :DATA, :TIPO_PROTOCOLO DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_PESQUISA_PEDIDO_NOVO (V_TIPO_NOME_CPF_PESQUISA VARCHAR(5) CHARACTER SET ISO8859_1,
V_NOME_PESQUISA VARCHAR(120) CHARACTER SET ISO8859_1,
V_CPF_PESQUISA VARCHAR(25) CHARACTER SET ISO8859_1,
V_TIPO_DATA_NUMERO_PESQUISA VARCHAR(5) CHARACTER SET ISO8859_1,
V_DATA_PESQUISA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_PESQUISA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUMERO_PESQUISA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_NUMERO_PESQUISA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_NATUREZA_TITULO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_EMOLUMENTO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO_CALCULO VARCHAR(5) CHARACTER SET ISO8859_1,
V_PROTOCOLO_CENTRAL VARCHAR(30) CHARACTER SET ISO8859_1,
V_MATRICULA VARCHAR(10) CHARACTER SET ISO8859_1,
V_NUMERO_SELO_DF VARCHAR(30) CHARACTER SET ISO8859_1,
V_ENDERECO VARCHAR(300) CHARACTER SET ISO8859_1,
V_NOME_ITEM_PESQUISA VARCHAR(120) CHARACTER SET ISO8859_1,
V_CPF_ITEM_PESQUISA VARCHAR(25) CHARACTER SET ISO8859_1,
V_TIPO_PEDIDO_ERIDF VARCHAR(5) CHARACTER SET ISO8859_1,
V_NUMERO_ONLINE VARCHAR(15) CHARACTER SET ISO8859_1,
V_SITUACAO_ERIDF VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (PEDIDO_ID INTEGER,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
ADQUIRENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
TRANSMITENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
NUMERO_ORDEM INTEGER,
DATA TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_SQL VARCHAR(1024);
  declare variable V_ORIGEM VARCHAR(5);
  declare variable V_TIPO_ORIGEM VARCHAR(5);
BEGIN
  IF ((COALESCE(:V_MATRICULA,'') <> '') or (COALESCE(:V_ENDERECO,'') <> '') or (COALESCE(:V_CPF_ITEM_PESQUISA,'') <> '') OR (COALESCE(:V_NOME_ITEM_PESQUISA,'') <> ''))  THEN
  BEGIN
    V_SQL = 'SELECT DISTINCT P.PEDIDO_ID, P.APRESENTANTE_NOME, P.ADQUIRENTE_NOME, 
               P.TRANSMITENTE_NOME, PR.NUMERO_ORDEM, PR.DATA, PR.TIPO_PROTOCOLO
             FROM R_PEDIDO P, R_PROTOCOLO PR, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN
             WHERE P.PEDIDO_ID = PR.PEDIDO_ID 
             AND P.PEDIDO_ID = PI.PEDIDO_ID
             AND PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID ';
  END
  ELSE IF ((COALESCE(:V_NATUREZA_TITULO_ID,'') <> '') OR (COALESCE(:V_EMOLUMENTO_ID,'') <> '') 
    OR (COALESCE(:V_PROTOCOLO_CENTRAL,'') <> '') OR (COALESCE(:V_NUMERO_SELO_DF,'') <> '')) THEN
  BEGIN
    V_SQL = 'SELECT DISTINCT P.PEDIDO_ID, P.APRESENTANTE_NOME, P.ADQUIRENTE_NOME, 
               P.TRANSMITENTE_NOME, PR.NUMERO_ORDEM, PR.DATA, PR.TIPO_PROTOCOLO
             FROM R_PEDIDO P, R_PROTOCOLO PR, R_PEDIDO_ITEM PI
             WHERE P.PEDIDO_ID = PR.PEDIDO_ID 
             AND P.PEDIDO_ID = PI.PEDIDO_ID ';
  END
  ELSE
  BEGIN
    V_SQL = 'SELECT DISTINCT P.PEDIDO_ID, P.APRESENTANTE_NOME, P.ADQUIRENTE_NOME, 
               P.TRANSMITENTE_NOME, PR.NUMERO_ORDEM, PR.DATA, PR.TIPO_PROTOCOLO
             FROM R_PEDIDO P, R_PROTOCOLO PR
             WHERE P.PEDIDO_ID = PR.PEDIDO_ID ';
  END

  IF (COALESCE(:V_NOME_PESQUISA,'') <> '') THEN
  BEGIN
    IF (position('%',:V_NOME_PESQUISA) > 0) THEN
    BEGIN
      IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'AP') THEN
      BEGIN
        V_SQL = :V_SQL || ' AND P.APRESENTANTE_NOME LIKE '||''''||:V_NOME_PESQUISA||'''';
      END
      ELSE IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'AD') THEN
      BEGIN
        V_SQL = :V_SQL || ' AND P.ADQUIRENTE_NOME LIKE '||''''||:V_NOME_PESQUISA||'''';
      END
      ELSE IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'TR') THEN
      BEGIN
        V_SQL = :V_SQL || ' AND P.TRANSMITENTE_NOME LIKE '||''''||:V_NOME_PESQUISA||'''';
      END
      ELSE
      BEGIN
        V_SQL = :V_SQL || ' AND (P.APRESENTANTE_NOME LIKE '||''''||:V_NOME_PESQUISA||''''||
          ' OR P.ADQUIRENTE_NOME LIKE '||''''||:V_NOME_PESQUISA||''''||
          ' OR P.TRANSMITENTE_NOME LIKE '||''''||:V_NOME_PESQUISA||''''||') ';
      END
    END
    ELSE
    BEGIN
      IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'AP') THEN
      BEGIN
        V_SQL = :V_SQL || ' AND P.APRESENTANTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||'''';
      END
      ELSE IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'AD') THEN
      BEGIN
        V_SQL = :V_SQL || ' AND P.ADQUIRENTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||'''';
      END
      ELSE IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'TR') THEN
      BEGIN
        V_SQL = :V_SQL || ' AND P.TRANSMITENTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||'''';
      END
      ELSE
      BEGIN
        V_SQL = :V_SQL || ' AND (P.APRESENTANTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||''''||
          ' OR P.ADQUIRENTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||''''||
          ' OR P.TRANSMITENTE_NOME STARTING WITH '||''''||:V_NOME_PESQUISA||''''||') ';
      END
    END
  END
  IF (COALESCE(:V_CPF_PESQUISA,'') <> '') THEN
  BEGIN
    IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'AP') THEN
    BEGIN
      V_SQL = :V_SQL || ' AND P.APRESENTANTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||'''';
    END
    ELSE IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'AD') THEN
    BEGIN
      V_SQL = :V_SQL || ' AND P.ADQUIRENTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||'''';
    END    
    ELSE IF (COALESCE(:V_TIPO_NOME_CPF_PESQUISA,'') = 'TR') THEN
    BEGIN
      V_SQL = :V_SQL || ' AND P.TRANSMITENTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||'''';
    END    
    ELSE
    BEGIN
      V_SQL = :V_SQL || ' AND (P.APRESENTANTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||''''||
        ' OR P.ADQUIRENTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||''''||
        ' OR P.TRANSMITENTE_CPF_CNPJ = '||''''||:V_CPF_PESQUISA||''''||') ';
    END      
  END

  IF ((COALESCE(:V_DATA_PESQUISA_INI,'') <> '') AND (COALESCE(:V_DATA_PESQUISA_INI,'') <> '00.00.0000') AND
    (COALESCE(:V_DATA_PESQUISA_INI,'') <> '00/00/0000')) THEN
  BEGIN
    IF (COALESCE(:V_DATA_PESQUISA_FIM,'') = '') THEN
    BEGIN
      V_DATA_PESQUISA_FIM = :V_DATA_PESQUISA_INI;
    END
    V_SQL = :V_SQL || ' AND PR.DATA BETWEEN CAST('||''''||:V_DATA_PESQUISA_INI||''''||' AS TIMESTAMP) '||
      ' AND CAST('||''''||:V_DATA_PESQUISA_FIM||''''||' AS TIMESTAMP) + 0.99999 ';    
  END
  IF (COALESCE(:V_NUMERO_PESQUISA_INI,'') <> '') THEN
  BEGIN
    IF (COALESCE(:V_NUMERO_PESQUISA_FIM,'') = '') THEN
    BEGIN
      V_NUMERO_PESQUISA_FIM = :V_NUMERO_PESQUISA_INI;
    END
    V_SQL = :V_SQL || ' AND PR.NUMERO_ORDEM BETWEEN '||:V_NUMERO_PESQUISA_INI||' AND '||:V_NUMERO_PESQUISA_FIM;
  END
  IF ((COALESCE(:V_TIPO_DATA_NUMERO_PESQUISA,'') = '1') OR 
    (COALESCE(:V_TIPO_DATA_NUMERO_PESQUISA,'') = '2') OR 
    (COALESCE(:V_TIPO_DATA_NUMERO_PESQUISA,'') = '3')) THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = '||''''||:V_TIPO_DATA_NUMERO_PESQUISA||'''';
  END
  IF (COALESCE(:V_NATUREZA_TITULO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PI.NATUREZA_TITULO_ID = '||:V_NATUREZA_TITULO_ID;
  END
  IF (COALESCE(:V_EMOLUMENTO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PI.EMOLUMENTO_ID = '||:V_EMOLUMENTO_ID;
  END
  IF (COALESCE(:V_TIPO_CALCULO,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND P.TIPO_COBRANCA = '||''''||:V_TIPO_CALCULO||'''';
  END
  IF (COALESCE(:V_PROTOCOLO_CENTRAL,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PI.PROTOCOLO_CENTRAL LIKE '||''''||:V_PROTOCOLO_CENTRAL||'%'||'''';
  END    
  IF (COALESCE(:V_MATRICULA,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PN.NUMERO = '||''''||:V_MATRICULA||'''';
  END    
  IF (COALESCE(:V_ENDERECO,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PN.LOGRADOURO LIKE '||''''||:V_ENDERECO||'''';
  END    
  IF (COALESCE(:V_CPF_ITEM_PESQUISA,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND ((PN.CPF = '||''''||:V_CPF_ITEM_PESQUISA||''''||') OR (PN.CONJUGE_CPF = '||''''||:V_CPF_ITEM_PESQUISA||''''||'))';
  END    
  IF (COALESCE(:V_NOME_ITEM_PESQUISA,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND ((PN.NOME STARTING WITH '||''''||:V_NOME_ITEM_PESQUISA||''''||') OR (PN.CONJUGE STARTING WITH '||''''||:V_NOME_ITEM_PESQUISA||''''||'))';
  END
  IF (COALESCE(:V_NUMERO_SELO_DF,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND (PI.NUMERO_SELO LIKE '||''''||:V_NUMERO_SELO_DF||'%'||''''||
      ' OR PR.NUMERO_SELO LIKE '||''''||:V_NUMERO_SELO_DF||'%'||''''||') ';
  END

  IF (COALESCE(:V_TIPO_PEDIDO_ERIDF,'') = '2') THEN --penhora
  BEGIN
    V_ORIGEM = '2';
    V_TIPO_ORIGEM = '1';
    V_SQL = :V_SQL || ' AND P.ORIGEM_PEDIDO = '||''''||:V_ORIGEM||''''||
      ' AND P.TIPO_ORIGEM_SITE = '||''''||:V_TIPO_ORIGEM||'''';
  END
  IF (COALESCE(:V_TIPO_PEDIDO_ERIDF,'') = '3') THEN --INTIMACAO
  BEGIN
    V_ORIGEM = '2';
    V_TIPO_ORIGEM = '3';
    V_SQL = :V_SQL || ' AND P.ORIGEM_PEDIDO = '||''''||:V_ORIGEM||''''||
      ' AND P.TIPO_ORIGEM_SITE = '||''''||:V_TIPO_ORIGEM||'''';
  END
  IF (COALESCE(:V_TIPO_PEDIDO_ERIDF,'') = '4') THEN --PED. PUBLICO
  BEGIN
    V_ORIGEM = '2';
    V_TIPO_ORIGEM = '2';
    V_SQL = :V_SQL || ' AND P.ORIGEM_PEDIDO = '||''''||:V_ORIGEM||''''||
      ' AND P.TIPO_ORIGEM_SITE = '||''''||:V_TIPO_ORIGEM||'''';
  END
  IF (COALESCE(:V_TIPO_PEDIDO_ERIDF,'') = '5') THEN --CODHAB
  BEGIN
    V_ORIGEM = '2';
    V_TIPO_ORIGEM = '5';
    V_SQL = :V_SQL || ' AND P.ORIGEM_PEDIDO = '||''''||:V_ORIGEM||''''||
      ' AND P.TIPO_ORIGEM_SITE = '||''''||:V_TIPO_ORIGEM||'''';
  END
  IF (COALESCE(:V_TIPO_PEDIDO_ERIDF,'') = '6') THEN --TERRACAP
  BEGIN
    V_ORIGEM = '2';
    V_TIPO_ORIGEM = '6';
    V_SQL = :V_SQL || ' AND P.ORIGEM_PEDIDO = '||''''||:V_ORIGEM||''''||
      ' AND P.TIPO_ORIGEM_SITE = '||''''||:V_TIPO_ORIGEM||'''';
  END

  IF (COALESCE(:V_NUMERO_ONLINE,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND P.NUMERO_ONLINE = '||''''||:V_NUMERO_ONLINE||'''';
  END    

  IF (COALESCE(:V_SITUACAO_ERIDF,'') = 'A') THEN --AGUARDANDO RESPOSTA
  BEGIN
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_PEDIDO_ITEM WHERE PEDIDO_ID = P.PEDIDO_ID AND COALESCE(USUARIO_ID_POSTOU_CERT,0) = 0) > 0 ';
  END
  IF (COALESCE(:V_SITUACAO_ERIDF,'') = 'R') THEN --RESPONDIDO
  BEGIN
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_PEDIDO_ITEM WHERE PEDIDO_ID = P.PEDIDO_ID AND COALESCE(USUARIO_ID_POSTOU_CERT,0) > 0) > 0 ';
  END

  V_SQL = :V_SQL ||' ORDER BY PR.DATA ';
  
  FOR EXECUTE STATEMENT V_SQL
      INTO :PEDIDO_ID, :APRESENTANTE_NOME, :ADQUIRENTE_NOME, :TRANSMITENTE_NOME, 
        :NUMERO_ORDEM, :DATA, :TIPO_PROTOCOLO DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_PESQUISA_PESSOAS_POR_VINCULOS (V_SOMENTE_ATUAIS VARCHAR(3) CHARACTER SET ISO8859_1,
V_TIPO_PESQUISA VARCHAR(3) CHARACTER SET ISO8859_1,
V_VINCULOS VARCHAR(2000) CHARACTER SET ISO8859_1,
V_ATO_MAIOR VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (PESSOA_ID NUMERIC(12, 2),
NOME VARCHAR(120) CHARACTER SET ISO8859_1,
DOCUMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
TB_PROFISSAO_ID NUMERIC(12, 2),
TB_ESTADOCIVIL_ID NUMERIC(12, 2),
DATA_VINCULO TIMESTAMP,
PESSOA_VINCULO_ID NUMERIC(12, 2),
IMOVEL_ID NUMERIC(12, 2),
DATA_TRANSFERENCIA TIMESTAMP,
TIPO_ATO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO_ATO NUMERIC(12, 2),
TB_TIPO_VINCULO_ID NUMERIC(12, 2),
AREA_PERCENT NUMERIC(18, 4),
CPF_CNPJ VARCHAR(15) CHARACTER SET ISO8859_1,
PESSOA_CONJUGE_ID NUMERIC(12, 2),
OBSERVACAO BLOB,
LRI_ID NUMERIC(12, 2),
PROCURACAO_ID NUMERIC(12, 2),
VINCULO_PROCURACAO NUMERIC(12, 2),
ORGAO_EXPEDIDOR VARCHAR(15) CHARACTER SET ISO8859_1,
ORGAO_EXPEDIDOR_UF VARCHAR(3) CHARACTER SET ISO8859_1,
TB_TIPO_VINCULO_ID_TEMP NUMERIC(12, 2),
NUMERO NUMERIC(12, 2),
DESCRICAO_VINCULO VARCHAR(60) CHARACTER SET ISO8859_1,
EXISTE_ONUS VARCHAR(1) CHARACTER SET ISO8859_1,
CONFERIDO VARCHAR(1) CHARACTER SET ISO8859_1,
DESCRICAO VARCHAR(2000) CHARACTER SET ISO8859_1,
QUANTIDADE_LANCADO INTEGER,
ULTIMO_ATO_VERIFICADO VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
DECLARE V_IDX INTEGER;
  DECLARE V_TB_TIPO_VINCULO_ID VARCHAR(20);
  DECLARE V_TAMANHO INTEGER;
  DECLARE V_ULTIMO_ATO_VERIFICADO_NUMERO INTEGER;
BEGIN
  WHILE ((:V_VINCULOS <> '') AND (:V_VINCULOS IS NOT NULL)) DO
  BEGIN
    SELECT TAMANHO FROM W_LENGTH(:V_VINCULOS) INTO :V_TAMANHO;
    SELECT POS FROM W_POS(',', :V_VINCULOS) INTO :V_IDX;
    IF (:V_IDX = 0) THEN
    BEGIN
      V_TB_TIPO_VINCULO_ID = V_VINCULOS;
      V_VINCULOS = '';
    END
    ELSE
    BEGIN
      V_TB_TIPO_VINCULO_ID = SUBSTRING(V_VINCULOS FROM 1 FOR V_IDX - 1);
      V_VINCULOS = SUBSTRING(V_VINCULOS FROM V_IDX + 1 FOR V_TAMANHO - V_IDX);
    END

    FOR SELECT V.PESSOA_ID, V.NOME, V.DOCUMENTO, V.TB_PROFISSAO_ID,
               V.TB_ESTADOCIVIL_ID, V.DATA_VINCULO, V.PESSOA_VINCULO_ID,
               V.IMOVEL_ID, V.DATA_TRANSFERENCIA, V.TIPO_ATO, V.NUMERO_ATO,
               V.TB_TIPO_VINCULO_ID, V.AREA_PERCENT, V.CPF_CNPJ, V.PESSOA_CONJUGE_ID,
               V.OBSERVACAO, V.LRI_ID, V.PROCURACAO_ID, V.VINCULO_PROCURACAO,
               V.ORGAO_EXPEDIDOR, V.ORGAO_EXPEDIDOR_UF, I.NUMERO
        FROM R_PESSOA_VINCULO V, R_IMOVEL I
        WHERE  V.IMOVEL_ID = I.IMOVEL_ID
        AND    V.TB_TIPO_VINCULO_ID = :V_TB_TIPO_VINCULO_ID
        AND    I.TIPO_REGISTRO = 'M'
        ORDER BY I.NUMERO
        INTO   :PESSOA_ID, :NOME, :DOCUMENTO, :TB_PROFISSAO_ID,
               :TB_ESTADOCIVIL_ID, :DATA_VINCULO, :PESSOA_VINCULO_ID,
               :IMOVEL_ID, :DATA_TRANSFERENCIA, :TIPO_ATO, :NUMERO_ATO,
               :TB_TIPO_VINCULO_ID, :AREA_PERCENT, :CPF_CNPJ, :PESSOA_CONJUGE_ID,
               :OBSERVACAO, :LRI_ID, :PROCURACAO_ID, :VINCULO_PROCURACAO,
               :ORGAO_EXPEDIDOR, :ORGAO_EXPEDIDOR_UF, :NUMERO DO
    BEGIN
      IF (((:V_SOMENTE_ATUAIS = 'S') AND (:DATA_TRANSFERENCIA IS NULL)) OR
         (:V_SOMENTE_ATUAIS = 'N')) THEN
      BEGIN
        SELECT EXISTE_ONUS, CONFERIDO, DESCRICAO,
               QUANTIDADE_LANCADO, ULTIMO_ATO_VERIFICADO, ULTIMO_ATO_VERIFICADO_NUMERO
        FROM R_BUSCA_ONUS(:IMOVEL_ID)
        INTO :EXISTE_ONUS, :CONFERIDO, :DESCRICAO,
             :QUANTIDADE_LANCADO, :ULTIMO_ATO_VERIFICADO, :V_ULTIMO_ATO_VERIFICADO_NUMERO;

        IF (((:V_TIPO_PESQUISA = 'N') AND (:EXISTE_ONUS = 'N')) OR --Nao possuem Onus
            ((:V_TIPO_PESQUISA = 'P') AND (:EXISTE_ONUS = 'S')) OR
             (:V_TIPO_PESQUISA = 'T')) THEN
        BEGIN
          SELECT DESCRICAO FROM R_TB_TIPO_VINCULO
          WHERE TB_TIPO_VINCULO_ID = :TB_TIPO_VINCULO_ID
          INTO :DESCRICAO_VINCULO;
          IF (:V_ATO_MAIOR = 'P') THEN --Ato do Pessoal maior
          BEGIN
            IF (:NUMERO_ATO > :V_ULTIMO_ATO_VERIFICADO_NUMERO) THEN
            BEGIN
              SUSPEND;
            END
          END
          ELSE IF (:V_ATO_MAIOR = 'O') THEN --Ato do Onus maior
          BEGIN
            IF (:V_ULTIMO_ATO_VERIFICADO_NUMERO > :NUMERO_ATO) THEN
            BEGIN
              SUSPEND;
            END
          END
          ELSE
          BEGIN
            SUSPEND;
          END
        END
      END
    END
  END
END ^

ALTER PROCEDURE R_PESQUISA_PESSOAS_SEM_VINCULOS RETURNS (PESSOA_ID NUMERIC(12, 2),
NOME VARCHAR(120) CHARACTER SET ISO8859_1,
DOCUMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
CPF_CNPJ VARCHAR(20) CHARACTER SET ISO8859_1)
AS 
DECLARE VQUANTIDADE INTEGER;
BEGIN
  FOR SELECT PESSOA_ID, NOME, DOCUMENTO, CPF_CNPJ
      FROM R_PESSOA
      WHERE (SISTEMA_VELHO IS NULL OR SISTEMA_VELHO = 'N' OR SISTEMA_VELHO = '')
  INTO :PESSOA_ID, :NOME, :DOCUMENTO, :CPF_CNPJ DO
  BEGIN
    SELECT COUNT(*) FROM R_PESSOA_VINCULO
    WHERE PESSOA_ID = :PESSOA_ID
    INTO :VQUANTIDADE;
    IF (:VQUANTIDADE = 0) THEN
      SUSPEND;
  END
END ^

ALTER PROCEDURE R_PESQUISA_PROCURACAO_PESSOA (V_PESSOA_ID NUMERIC(12, 2),
V_NOME VARCHAR(120) CHARACTER SET ISO8859_1 DEFAULT '',
V_CPF_CNPJ VARCHAR(120) CHARACTER SET ISO8859_1 DEFAULT '')
RETURNS (PROCURACAO_ID NUMERIC(12, 2),
DATA TIMESTAMP,
DATA_VENCIMENTO TIMESTAMP,
TB_TIPO_PROCURACAO_ID NUMERIC(12, 2))
AS 
DECLARE VSQL VARCHAR(1000);
BEGIN
  if (COALESCE(:V_PESSOA_ID,0) > 0) then
  BEGIN
    FOR SELECT DISTINCT P.PROCURACAO_ID, P.DATA,
                 P.DATA_VENCIMENTO, P.TB_TIPO_PROCURACAO_ID
          FROM R_PROCURACAO P, R_PESSOA_VINCULO V
          WHERE P.PROCURACAO_ID = V.PROCURACAO_ID
          AND V.PESSOA_ID = :V_PESSOA_ID
          ORDER BY P.DATA
    INTO :PROCURACAO_ID,
         :DATA,
         :DATA_VENCIMENTO,
         :TB_TIPO_PROCURACAO_ID DO
    BEGIN
      SUSPEND;
    END
  END
  ELSE
  BEGIN
    FOR SELECT DISTINCT P.PROCURACAO_ID, P.DATA,
                 P.DATA_VENCIMENTO, P.TB_TIPO_PROCURACAO_ID
          FROM R_PROCURACAO P, R_PESSOA_VINCULO V
          WHERE P.PROCURACAO_ID = V.PROCURACAO_ID
          AND V.nome like :V_NOME
          AND V.cpf_cnpj = :V_CPF_CNPJ
          ORDER BY P.DATA
    INTO :PROCURACAO_ID,
         :DATA,
         :DATA_VENCIMENTO,
         :TB_TIPO_PROCURACAO_ID DO
    BEGIN
      SUSPEND;
    END
  END
END ^

ALTER PROCEDURE R_PESQUISA_PROT_POR_NATUREZA_DF (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
V_NATUREZA_ID INTEGER)
RETURNS (MATRICULA INTEGER,
ENDERECO VARCHAR(1000) CHARACTER SET ISO8859_1,
INSCRICAO_MUN VARCHAR(260) CHARACTER SET ISO8859_1,
AREA_TOTAL VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_UNIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
NATUREZA VARCHAR(120) CHARACTER SET ISO8859_1,
ATO VARCHAR(20) CHARACTER SET ISO8859_1,
PROTOCOLO INTEGER,
DATA_REGISTRO DATE,
VALOR_DOCUMENTO NUMERIC(18, 2),
VALOR_ITBI NUMERIC(18, 2),
FRACAO_TRANSACAO NUMERIC(18, 2))
AS 
declare variable v_ato_tipo varchar(10);
  declare variable v_ato_numero varchar(10);
  declare variable v_imovel_id varchar(20);
begin
  for select pn.numero, nt.descricao, pn.ato_tipo, cast(cast(pn.ato_numero as integer) as varchar(10)), pr.numero_ordem, cast(a.data as date), pi.valor_documento, pi.valor_itbi
      from r_protocolo pr, r_pedido pe, r_pedido_item pi, r_pedido_item_numero pn, r_andamento a, r_tb_tipo_andamento ta, g_natureza_titulo nt
      where pr.pedido_id = pe.pedido_id
      and pe.pedido_id = pi.pedido_id
      and pi.pedido_item_id = pn.pedido_item_id
      and pe.pedido_id = a.pedido_id
      and a.tb_tipo_andamento_id = ta.tb_tipo_andamento_id
      and pi.natureza_titulo_id = nt.natureza_titulo_id
      and pi.natureza_titulo_id = :v_natureza_id
      and pr.tipo_protocolo = '1'
      and ta.tipo = 'R'
      and pn.tipo_registro = 'M'
      and a.data between cast(:v_data_ini as date) and cast(:v_data_fim as date) + 0.99999
      order by a.data
  into :matricula, :natureza, :v_ato_tipo, :v_ato_numero, :protocolo, :data_registro, :valor_documento, :valor_itbi do
  begin
    if (:v_ato_tipo = 'A') then
    begin
      ato = 'Av.'||:v_ato_numero;
    end
    else
    begin
      ato = 'R.'||:v_ato_numero;
    end

    select first 1 i.imovel_id, i.inscricao_imovel, u.area, t.descricao
    from r_imovel i, r_imovel_unidade u, r_imovel_tipo t
    where i.imovel_id = u.imovel_id
    and u.imovel_tipo_id = t.imovel_tipo_id
    and i.tipo_registro = 'M'
    and i.numero = :matricula
    into :v_imovel_id, :inscricao_mun, :area_total, :tipo_unidade;

    select DETALHES from R_BUSCA_DETALHE_IMOVEL_DF(:v_imovel_id)
    into :endereco;

    select sum(area_percent)
    from r_pessoa_vinculo
    where imovel_id = :v_imovel_id
    and numero_ato = :v_ato_numero
    into :fracao_transacao;

    if (:fracao_transacao > 100) then
    begin
      fracao_transacao = 100;
    end

    SUSPEND;
  end
end ^

ALTER PROCEDURE R_PESQUISA_REG_AUX_PESSOA (V_PESSOA_ID NUMERIC(12, 2),
V_ATUAL VARCHAR(3) CHARACTER SET ISO8859_1,
V_TB_TIPO_REG_AUXILIAR_ID NUMERIC(12, 2),
V_TB_PRODUTO_SAFRA_ID NUMERIC(12, 2),
V_TB_TIPO_VINCULO_ID NUMERIC(12, 2),
V_TB_PRODUTO_ID NUMERIC(12, 2),
V_TB_SAFRA_ID NUMERIC(12, 2),
V_NOME VARCHAR(120) CHARACTER SET ISO8859_1 DEFAULT '',
V_CPF_CNPJ VARCHAR(120) CHARACTER SET ISO8859_1 DEFAULT '',
V_DOCUMENTO VARCHAR(120) CHARACTER SET ISO8859_1 DEFAULT '')
RETURNS (IMOVEL_ID NUMERIC(12, 2),
TIPO_CLASSE VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
DATA_REGISTRO TIMESTAMP,
NUMERO NUMERIC(12, 2),
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
CIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
DATA_BAIXA TIMESTAMP,
CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1,
INSCRICAO_IMOVEL VARCHAR(60) CHARACTER SET ISO8859_1,
SITUACAO VARCHAR(1) CHARACTER SET ISO8859_1,
TB_PRODUTO_SAFRA_ID NUMERIC(12, 2),
TB_TIPO_REG_AUXILIAR_ID NUMERIC(12, 2),
DATA_TRANSFERENCIA TIMESTAMP,
TB_TIPO_VINCULO_ID NUMERIC(12, 2))
AS 
DECLARE V_RETORNAR VARCHAR(1);
  DECLARE V_QUANTIDADE INTEGER;
  declare variable VSQL VARCHAR(3000);
BEGIN
  if (COALESCE(:V_PESSOA_ID,0) > 0) then
  BEGIN
    FOR SELECT DISTINCT I.IMOVEL_ID, I.TIPO_CLASSE, I.TIPO_REGISTRO,
                   I.DATA_REGISTRO, I.NUMERO, I.NUMERO_LETRA, I.CIDADE,
                   I.DATA_BAIXA, I.CARTORIO, I.INSCRICAO_IMOVEL, I.SITUACAO,
                   I.TB_PRODUTO_SAFRA_ID, I.TB_TIPO_REG_AUXILIAR_ID,
                   V.DATA_TRANSFERENCIA, V.TB_TIPO_VINCULO_ID
        FROM R_IMOVEL I, R_PESSOA_VINCULO V
        WHERE I.IMOVEL_ID = V.IMOVEL_ID
        AND TIPO_REGISTRO = 'A'
        AND V.PESSOA_ID = :V_PESSOA_ID
        ORDER BY I.NUMERO
        INTO :IMOVEL_ID,
             :TIPO_CLASSE,
             :TIPO_REGISTRO,
             :DATA_REGISTRO,
             :NUMERO,
             :NUMERO_LETRA,
             :CIDADE,
             :DATA_BAIXA,
             :CARTORIO,
             :INSCRICAO_IMOVEL,
             :SITUACAO,
             :TB_PRODUTO_SAFRA_ID,
             :TB_TIPO_REG_AUXILIAR_ID,
             :DATA_TRANSFERENCIA,
             :TB_TIPO_VINCULO_ID DO
    BEGIN
      V_RETORNAR = 'S';
    
      IF (:V_ATUAL = 'S') THEN
      BEGIN
        IF (:DATA_TRANSFERENCIA IS NOT NULL) THEN
        BEGIN
          V_RETORNAR = 'N';
        END
      END
      IF (:V_TB_TIPO_REG_AUXILIAR_ID IS NOT NULL) THEN
      BEGIN
        IF ((:V_TB_TIPO_REG_AUXILIAR_ID <> :TB_TIPO_REG_AUXILIAR_ID) OR (:TB_TIPO_REG_AUXILIAR_ID IS NULL)) THEN
        BEGIN
          V_RETORNAR = 'N';
        END
      END
      IF (:V_TB_PRODUTO_SAFRA_ID IS NOT NULL) THEN
      BEGIN
        IF ((:V_TB_PRODUTO_SAFRA_ID <> :TB_PRODUTO_SAFRA_ID) OR (:TB_PRODUTO_SAFRA_ID IS NULL)) THEN
        BEGIN
          V_RETORNAR = 'N';
        END
      END
      IF (:V_TB_TIPO_VINCULO_ID IS NOT NULL) THEN
      BEGIN
        IF ((:V_TB_TIPO_VINCULO_ID <> :TB_TIPO_VINCULO_ID) OR (:TB_TIPO_VINCULO_ID IS NULL)) THEN
        BEGIN
          V_RETORNAR = 'N';
        END
      END
      IF (:V_TB_PRODUTO_ID IS NOT NULL) THEN
      BEGIN
        SELECT COUNT(*) FROM R_CEDULA
        WHERE IMOVEL_ID = :IMOVEL_ID
        AND TB_PRODUTO_ID = :V_TB_PRODUTO_ID
        INTO :V_QUANTIDADE;
        IF (:V_QUANTIDADE = 0) THEN
        BEGIN 
          V_RETORNAR = 'N';
        END
      END
      IF (:V_TB_SAFRA_ID IS NOT NULL) THEN
      BEGIN
        SELECT COUNT(*) FROM R_CEDULA
        WHERE IMOVEL_ID = :IMOVEL_ID
        AND TB_SAFRA_ID = :V_TB_SAFRA_ID
        INTO :V_QUANTIDADE;
        IF (:V_QUANTIDADE = 0) THEN
        BEGIN 
          V_RETORNAR = 'N';
        END
      END
      IF (V_RETORNAR = 'S') THEN
      BEGIN
        SUSPEND;
      END
    END
  end
  else
  begin
    VSQL = 'SELECT DISTINCT I.IMOVEL_ID, I.TIPO_CLASSE, I.TIPO_REGISTRO,
                   I.DATA_REGISTRO, I.NUMERO, I.NUMERO_LETRA, I.CIDADE,
                   I.DATA_BAIXA, I.CARTORIO, I.INSCRICAO_IMOVEL, I.SITUACAO,
                   I.TB_PRODUTO_SAFRA_ID, I.TB_TIPO_REG_AUXILIAR_ID,
                   V.DATA_TRANSFERENCIA, V.TB_TIPO_VINCULO_ID
        FROM R_IMOVEL I, R_PESSOA_VINCULO V
        WHERE I.IMOVEL_ID = V.IMOVEL_ID
        AND   I.TIPO_REGISTRO = ''A''';
    if (COALESCE(:V_CPF_CNPJ,'') <> '') then
    begin
      VSQL = :VSQL || ' AND V.cpf_cnpj = '||''''||:V_CPF_CNPJ||'''';
    end
    if (COALESCE(:V_DOCUMENTO,'') <> '') then
    begin
      VSQL = :VSQL || ' AND V.DOCUMENTO = '||''''||:V_DOCUMENTO||'''';
    end
    if (COALESCE(:V_NOME,'') <> '') then
    begin
      VSQL = :VSQL || ' AND V.NOME LIKE '||''''||:V_NOME||'''';
    end
    VSQL = :VSQL || ' ORDER BY I.NUMERO ';

    if ((COALESCE(:V_CPF_CNPJ,'') <> '') or (COALESCE(:V_DOCUMENTO,'') <> '') or (COALESCE(:V_NOME,'') <> '')) then
    begin
      FOR EXECUTE STATEMENT VSQL
        INTO :IMOVEL_ID,
             :TIPO_CLASSE,
             :TIPO_REGISTRO,
             :DATA_REGISTRO,
             :NUMERO,
             :NUMERO_LETRA,
             :CIDADE,
             :DATA_BAIXA,
             :CARTORIO,
             :INSCRICAO_IMOVEL,
             :SITUACAO,
             :TB_PRODUTO_SAFRA_ID,
             :TB_TIPO_REG_AUXILIAR_ID,
             :DATA_TRANSFERENCIA,
             :TB_TIPO_VINCULO_ID DO
      BEGIN
        V_RETORNAR = 'S';
      
        IF (:V_ATUAL = 'S') THEN
        BEGIN
          IF (:DATA_TRANSFERENCIA IS NOT NULL) THEN
          BEGIN
            V_RETORNAR = 'N';
          END
        END
        IF (:V_TB_TIPO_REG_AUXILIAR_ID IS NOT NULL) THEN
        BEGIN
          IF ((:V_TB_TIPO_REG_AUXILIAR_ID <> :TB_TIPO_REG_AUXILIAR_ID) OR (:TB_TIPO_REG_AUXILIAR_ID IS NULL)) THEN
          BEGIN
            V_RETORNAR = 'N';
          END
        END
        IF (:V_TB_PRODUTO_SAFRA_ID IS NOT NULL) THEN
        BEGIN
          IF ((:V_TB_PRODUTO_SAFRA_ID <> :TB_PRODUTO_SAFRA_ID) OR (:TB_PRODUTO_SAFRA_ID IS NULL)) THEN
          BEGIN
            V_RETORNAR = 'N';
          END
        END
        IF (:V_TB_TIPO_VINCULO_ID IS NOT NULL) THEN
        BEGIN
          IF ((:V_TB_TIPO_VINCULO_ID <> :TB_TIPO_VINCULO_ID) OR (:TB_TIPO_VINCULO_ID IS NULL)) THEN
          BEGIN
            V_RETORNAR = 'N';
          END
        END
        IF (:V_TB_PRODUTO_ID IS NOT NULL) THEN
        BEGIN
          SELECT COUNT(*) FROM R_CEDULA
          WHERE IMOVEL_ID = :IMOVEL_ID
          AND TB_PRODUTO_ID = :V_TB_PRODUTO_ID
          INTO :V_QUANTIDADE;
          IF (:V_QUANTIDADE = 0) THEN
          BEGIN 
            V_RETORNAR = 'N';
          END
        END
        IF (:V_TB_SAFRA_ID IS NOT NULL) THEN
        BEGIN
          SELECT COUNT(*) FROM R_CEDULA
          WHERE IMOVEL_ID = :IMOVEL_ID
          AND TB_SAFRA_ID = :V_TB_SAFRA_ID
          INTO :V_QUANTIDADE;
          IF (:V_QUANTIDADE = 0) THEN
          BEGIN 
            V_RETORNAR = 'N';
          END
        END
        IF (V_RETORNAR = 'S') THEN
        BEGIN
          SUSPEND;
        END
      END
    END
  end
END ^

ALTER PROCEDURE R_PESQUISA_SELOS_NAO_ENVIADOS (V_DATA_INICIAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (TB_TIPO_ANDAMENTO_ID INTEGER,
ANDAMENTO_ID INTEGER,
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO_ORDEM NUMERIC(12, 2),
NUMERO_SELO VARCHAR(30) CHARACTER SET ISO8859_1,
TB_TITULO_ID INTEGER,
PEDIDO_ID INTEGER,
DATA TIMESTAMP,
STATUS_SELO_DIGITAL VARCHAR(3) CHARACTER SET ISO8859_1,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
DATA_PROTOCOLO TIMESTAMP,
ORIGEM_PEDIDO VARCHAR(3) CHARACTER SET ISO8859_1,
SELO_ENVIADO_COMO_CANC VARCHAR(1) CHARACTER SET ISO8859_1,
SELO_ENVIADO_COMO_EMITIDO VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_COBRANCA VARCHAR(3) CHARACTER SET ISO8859_1,
MOTIVO_ISENTO VARCHAR(60) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_DATA_I VARCHAR(12);
  DECLARE VARIABLE V_DATA_F VARCHAR(12);
  DECLARE VARIABLE V_CONT INTEGER;
  DECLARE VARIABLE V_MOTIVO_ISENTO VARCHAR(3);
BEGIN
  --INVERTER DATAS
  V_DATA_I = SUBSTRING(:V_DATA_INICIAL FROM 7 FOR 4)||'/'||
 		     SUBSTRING(:V_DATA_INICIAL FROM 4 FOR 2)||'/'||
             SUBSTRING(:V_DATA_INICIAL FROM 1 FOR 2);
  V_DATA_F = SUBSTRING(:V_DATA_FINAL FROM 7 FOR 4)||'/'||
 			 SUBSTRING(:V_DATA_FINAL FROM 4 FOR 2)||'/'||
             SUBSTRING(:V_DATA_FINAL FROM 1 FOR 2);
  
  FOR SELECT A.TB_TIPO_ANDAMENTO_ID, A.ANDAMENTO_ID, 
        PR.TIPO_PROTOCOLO, PR.NUMERO_ORDEM, PR.NUMERO_SELO, 
        PE.TB_TITULO_ID, PE.PEDIDO_ID, A.DATA, T.STATUS_SELO_DIGITAL, 
        PE.APRESENTANTE_NOME, PR.DATA AS DATA_PROTOCOLO, PE.ORIGEM_PEDIDO,
        PE.TIPO_COBRANCA, PE.MOTIVO_ISENTO
      FROM R_ANDAMENTO A, R_PROTOCOLO PR, 
        R_PEDIDO PE, R_TB_TIPO_ANDAMENTO T 
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID 
      AND PE.PEDIDO_ID = A.PEDIDO_ID 
      AND A.TB_TIPO_ANDAMENTO_ID = T.TB_TIPO_ANDAMENTO_ID 
      AND T.STATUS_SELO_DIGITAL IS NOT NULL 
      AND T.STATUS_SELO_DIGITAL <> ''
      AND (PR.TIPO_PROTOCOLO = '1'
           OR PR.TIPO_PROTOCOLO = '3'
           OR PR.TIPO_PROTOCOLO = '4')
      AND A.DATA_INCLUSAO BETWEEN CAST(:V_DATA_I AS TIMESTAMP) - 7
                              AND CAST(:V_DATA_F AS TIMESTAMP) + 0.99999
      AND (SELECT COUNT(*) FROM R_SELO_HISTORICO 
           WHERE ANDAMENTO_ID = A.ANDAMENTO_ID 
           AND DATA_ENVIO IS NOT NULL) = 0
      ORDER BY A.DATA 
      INTO :TB_TIPO_ANDAMENTO_ID, :ANDAMENTO_ID, 
        :TIPO_PROTOCOLO, :NUMERO_ORDEM, :NUMERO_SELO, 
        :TB_TITULO_ID, PEDIDO_ID, :DATA, :STATUS_SELO_DIGITAL, 
        :APRESENTANTE_NOME, :DATA_PROTOCOLO, :ORIGEM_PEDIDO,
        :TIPO_COBRANCA, :V_MOTIVO_ISENTO DO
  BEGIN  
    IF ((:TIPO_PROTOCOLO = '1') AND (:STATUS_SELO_DIGITAL = '9')) THEN
    BEGIN
      -- NAO FAZ NADA, POIS NAO TEM CERTIDAO EMITIDA PARA PROTOCOLO
    END
    ELSE IF ((:TIPO_PROTOCOLO = '1') AND (:STATUS_SELO_DIGITAL = '13')) THEN
    BEGIN
      -- NAO FAZ NADA, POIS NAO TEM CERTIDAO SOLICITADA PARA PROTOCOLO
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:STATUS_SELO_DIGITAL = '1')) THEN
    BEGIN
      -- NAO FAZ NADA
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:STATUS_SELO_DIGITAL = '2')) THEN
    BEGIN
      -- NAO FAZ NADA
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:STATUS_SELO_DIGITAL = '3')) THEN
    BEGIN
      -- NAO FAZ NADA
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:STATUS_SELO_DIGITAL = '4')) THEN
    BEGIN
      -- NAO FAZ NADA
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:STATUS_SELO_DIGITAL = '5')) THEN
    BEGIN
      -- NAO FAZ NADA
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:STATUS_SELO_DIGITAL = '6')) THEN
    BEGIN
      -- NAO FAZ NADA
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:STATUS_SELO_DIGITAL = '7')) THEN
    BEGIN
      -- NAO FAZ NADA
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:STATUS_SELO_DIGITAL = '8')) THEN
    BEGIN
      -- NAO FAZ NADA
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:STATUS_SELO_DIGITAL = '10')) THEN
    BEGIN
      -- NAO FAZ NADA
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:STATUS_SELO_DIGITAL = '11')) THEN
    BEGIN
      -- NAO FAZ NADA
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:STATUS_SELO_DIGITAL = '12')) THEN
    BEGIN
      -- NAO FAZ NADA
    END
    ELSE IF ((:TIPO_PROTOCOLO = '3') AND (:ORIGEM_PEDIDO = '3') AND (:STATUS_SELO_DIGITAL = '13')) THEN
    BEGIN
      --NAO FAZ NADA, POIS TRATA-SE DE PEDIDO DA CENTRAL E NO MANUAL PREVE QUE NAO EH NECESSARIO ENVIAR STATUS 13 (FASE I) 
    END    
    ELSE
    BEGIN    
      --VERIFICAR SE EXISTE STATUS MAIS ATUAL QUE ESTE
      SELECT COUNT(*)
      FROM R_ANDAMENTO A, R_PEDIDO PE, R_TB_TIPO_ANDAMENTO T 
      WHERE PE.PEDIDO_ID = A.PEDIDO_ID 
      AND A.TB_TIPO_ANDAMENTO_ID = T.TB_TIPO_ANDAMENTO_ID 
      AND T.STATUS_SELO_DIGITAL IS NOT NULL 
      AND T.STATUS_SELO_DIGITAL <> ''
      AND (CAST(T.STATUS_SELO_DIGITAL AS INTEGER) > CAST(:STATUS_SELO_DIGITAL AS INTEGER))
      AND PE.PEDIDO_ID = :PEDIDO_ID
      AND PE.ORIGEM_PEDIDO <> '3'
      INTO :V_CONT;
      
      IF (:V_CONT > 0) THEN
      BEGIN
        --NAO FAZ NADA, POIS EXISTE SELO MAIS ATUAL PARA O PEDIDO
      END
      ELSE
      BEGIN            
        --SE ISENTO, MONTAR MOTIVO ISECAO
        IF (:V_MOTIVO_ISENTO = '1') THEN
        BEGIN
          MOTIVO_ISENTO = 'ORGAOS PUBLICOS';
        END 
        ELSE IF (:V_MOTIVO_ISENTO = '2') THEN
        BEGIN
          MOTIVO_ISENTO = 'JUSTICA GRATUITA';
        END 
        ELSE IF (:V_MOTIVO_ISENTO = '3') THEN
        BEGIN
          MOTIVO_ISENTO = 'RETIFICACAO POR ERRO DO CARTORIO';
        END 
        ELSE IF (:V_MOTIVO_ISENTO = '9') THEN
        BEGIN
          MOTIVO_ISENTO = 'OUTROS';
        END 
        ELSE
        BEGIN
          MOTIVO_ISENTO = '';
        END
        
        --VERIFICAR SE FOI ENVIADO COMO PROTOCOLO CANCELADO
        SELECT COUNT(*) FROM R_SELO_HISTORICO 
        WHERE NUMERO_SELO = :NUMERO_SELO
        AND DATA_ENVIO IS NOT NULL 
        AND STATUS = '8'
        INTO :V_CONT;
        IF (:V_CONT > 0) THEN
        BEGIN
          SELO_ENVIADO_COMO_CANC = 'S';
        END
        ELSE
        BEGIN
          SELO_ENVIADO_COMO_CANC = 'N';
        END

        --VERIFICAR SE FOI ENVIADO COMO CERTIDAO EMITIDA
        SELECT COUNT(*) FROM R_SELO_HISTORICO 
        WHERE NUMERO_SELO = :NUMERO_SELO
        AND DATA_ENVIO IS NOT NULL 
        AND STATUS = '9'
        INTO :V_CONT;
        IF (:V_CONT > 0) THEN
        BEGIN
          SELO_ENVIADO_COMO_EMITIDO = 'S';
        END
        ELSE
        BEGIN
          SELO_ENVIADO_COMO_EMITIDO = 'N';
        END

        SUSPEND;
      END
    END
  END
END ^

ALTER PROCEDURE R_PESQUISA_UNIDADE_FIC_AUX (V_IMOVEL_FICHAAUXILIAR_ID NUMERIC(12, 2))
RETURNS (IMOVEL_UNIDADE_ID NUMERIC(12, 2),
IMOVEL_ID NUMERIC(12, 2),
IMOVEL_FICHAAUXILIAR_ID NUMERIC(12, 2),
NUMERO_UNIDADE VARCHAR(60) CHARACTER SET ISO8859_1,
QUADRA VARCHAR(60) CHARACTER SET ISO8859_1,
AREA VARCHAR(30) CHARACTER SET ISO8859_1,
NUMERO_EDIFICACAO VARCHAR(10) CHARACTER SET ISO8859_1,
CONJUNTO VARCHAR(10) CHARACTER SET ISO8859_1,
BLOCO VARCHAR(10) CHARACTER SET ISO8859_1,
IMOVEL_TIPO_ID NUMERIC(12, 2),
AREA_DESCRITIVA VARCHAR(120) CHARACTER SET ISO8859_1,
CARACTERISTICA VARCHAR(120) CHARACTER SET ISO8859_1,
GEO_REFERENCIAMENTO VARCHAR(1) CHARACTER SET ISO8859_1,
NOME_EDIFICACAO VARCHAR(90) CHARACTER SET ISO8859_1,
RESERVA_FLORESTAL VARCHAR(1) CHARACTER SET ISO8859_1,
TB_BAIRRO_ID NUMERIC(12, 2),
TIPO_CONSTRUCAO NUMERIC(12, 2),
NOVO VARCHAR(1) CHARACTER SET ISO8859_1,
SIGLA_ID NUMERIC(12, 2),
TIPO_COMPLEMENTAR VARCHAR(10) CHARACTER SET ISO8859_1,
TIPO_COMPLEMENTAR_DESC VARCHAR(30) CHARACTER SET ISO8859_1,
TIPO_QUADRA VARCHAR(3) CHARACTER SET ISO8859_1,
NOME_EDIFICIO_DF VARCHAR(90) CHARACTER SET ISO8859_1,
COMPLEMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
TIPO_REGISTRO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO NUMERIC(12, 2),
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
BEGIN
  FOR SELECT IMOVEL_UNIDADE_ID, IMOVEL_ID,
                 IMOVEL_FICHAAUXILIAR_ID, NUMERO_UNIDADE,
                 QUADRA, AREA, NUMERO_EDIFICACAO,
                 CONJUNTO, BLOCO, IMOVEL_TIPO_ID, AREA_DESCRITIVA,
                 CARACTERISTICA, GEO_REFERENCIAMENTO,
                 NOME_EDIFICACAO, RESERVA_FLORESTAL,
                 TB_BAIRRO_ID, TIPO_CONSTRUCAO, NOVO, SIGLA_ID,
                 TIPO_COMPLEMENTAR, TIPO_COMPLEMENTAR_DESC, 
                 TIPO_QUADRA, NOME_EDIFICIO_DF, COMPLEMENTO 
      FROM   R_IMOVEL_UNIDADE
      WHERE IMOVEL_FICHAAUXILIAR_ID = :V_IMOVEL_FICHAAUXILIAR_ID 
      ORDER BY NOME_EDIFICACAO, NUMERO_UNIDADE 
      INTO :IMOVEL_UNIDADE_ID,
           :IMOVEL_ID,
           :IMOVEL_FICHAAUXILIAR_ID,
           :NUMERO_UNIDADE,
           :QUADRA,
           :AREA,
           :NUMERO_EDIFICACAO,
           :CONJUNTO,
           :BLOCO,
           :IMOVEL_TIPO_ID,
           :AREA_DESCRITIVA,
           :CARACTERISTICA,
           :GEO_REFERENCIAMENTO,
           :NOME_EDIFICACAO,
           :RESERVA_FLORESTAL,
           :TB_BAIRRO_ID,
           :TIPO_CONSTRUCAO,
           :NOVO,
           :SIGLA_ID,
           :TIPO_COMPLEMENTAR, 
           :TIPO_COMPLEMENTAR_DESC, 
  	       :TIPO_QUADRA, 
	       :NOME_EDIFICIO_DF, 
	       :COMPLEMENTO  DO
  BEGIN
    TIPO_REGISTRO = NULL;
    NUMERO = NULL;
    NUMERO_LETRA = NULL;
    CARTORIO = NULL;

    SELECT TIPO_REGISTRO, NUMERO, NUMERO_LETRA, CARTORIO FROM R_IMOVEL
    WHERE IMOVEL_ID = :IMOVEL_ID
    INTO :TIPO_REGISTRO, :NUMERO, :NUMERO_LETRA, :CARTORIO;
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_PESSOAL_EH_POS_PARA_NEG_PROP (V_CPF_CNPJ VARCHAR(20) CHARACTER SET ISO8859_1,
V_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
V_NOME_SOLTEIRO VARCHAR(120) CHARACTER SET ISO8859_1,
V_CPF_CONJUGE VARCHAR(20) CHARACTER SET ISO8859_1,
V_NOME_CONJUGE VARCHAR(120) CHARACTER SET ISO8859_1,
V_NOME_CONJUGE_SOLTEIRO VARCHAR(120) CHARACTER SET ISO8859_1,
V_TIPO_PESQUISA VARCHAR(5) CHARACTER SET ISO8859_1,
V_PESQUISAR_HOMONIMIA VARCHAR(5) CHARACTER SET ISO8859_1 DEFAULT 'S')
RETURNS (POSITIVO VARCHAR(5) CHARACTER SET ISO8859_1)
AS 
declare variable V_QTDE_ENCONTRADA INTEGER;
  declare variable I INTEGER;
  declare variable V_NOME_PESQUISA VARCHAR(120);
BEGIN
  V_QTDE_ENCONTRADA = 0;

  --CPF PRINCIPAL
  IF (COALESCE(:V_CPF_CNPJ,'') <> '') THEN
  BEGIN  
    if (coalesce(:V_TIPO_PESQUISA,'') = '3') then --qualquer referencia
    begin
      SELECT COUNT(*) FROM R_PESSOA
      WHERE CPF_CNPJ = :V_CPF_CNPJ
      INTO :V_QTDE_ENCONTRADA;

      if (coalesce(:V_QTDE_ENCONTRADA,0) = 0) then
      begin
        SELECT COUNT(*) FROM R_PESSOA_VINCULO
        WHERE CPF_CNPJ = :V_CPF_CNPJ
        AND COALESCE(LRI_ID, 0) = 0
        AND COALESCE(PROCURACAO_ID, 0) = 0
        INTO :V_QTDE_ENCONTRADA;
      end
    END
    ELSE if (coalesce(:V_TIPO_PESQUISA,'') = '1') then --SOMENTE ATUAIS
    begin
      SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
      where  i.imovel_id = v.imovel_id
      and    (select count(*) from r_tb_tipo_vinculo where tb_tipo_vinculo_id = v.tb_tipo_vinculo_id and usar_na_doi = 'N') = 0
      and    i.tipo_registro = 'M'
      and    v.cpf_cnpj = :V_CPF_CNPJ
      AND    V.DATA_TRANSFERENCIA IS NULL
      into :V_QTDE_ENCONTRADA;
    end
    else --todos vinculos
    begin
      SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
      where  i.imovel_id = v.imovel_id
      and    (select count(*) from r_tb_tipo_vinculo where tb_tipo_vinculo_id = v.tb_tipo_vinculo_id and usar_na_doi = 'N') = 0
      and    i.tipo_registro = 'M'
      and    v.cpf_cnpj = :V_CPF_CNPJ
      into :V_QTDE_ENCONTRADA;
    end
  end

  --CPF_CONJUGE
  if (coalesce(:V_QTDE_ENCONTRADA,0) = 0) then
  begin
    IF (COALESCE(:V_CPF_CONJUGE,'') <> '') THEN
    BEGIN
      if (coalesce(:V_TIPO_PESQUISA,'') = '3') then --qualquer referencia
      begin
        SELECT COUNT(*) FROM R_PESSOA
        WHERE CPF_CNPJ = :V_CPF_CONJUGE
        INTO :V_QTDE_ENCONTRADA;

        if (coalesce(:V_QTDE_ENCONTRADA,0) = 0) then
        begin
          SELECT COUNT(*) FROM R_PESSOA_VINCULO
          WHERE CPF_CNPJ = :V_CPF_CONJUGE
          AND COALESCE(LRI_ID, 0) = 0
          AND COALESCE(PROCURACAO_ID, 0) = 0
          INTO :V_QTDE_ENCONTRADA;
        end
      END
      ELSE if (coalesce(:V_TIPO_PESQUISA,'') = '1') then --SOMENTE ATUAIS
      begin
        SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
        where  i.imovel_id = v.imovel_id
        and    (select count(*) from r_tb_tipo_vinculo where tb_tipo_vinculo_id = v.tb_tipo_vinculo_id and usar_na_doi = 'N') = 0
        and    i.tipo_registro = 'M'
        and    v.cpf_cnpj = :V_CPF_CONJUGE
        AND    V.DATA_TRANSFERENCIA IS NULL
        into :V_QTDE_ENCONTRADA;
      end
      else --todos vinculos
      begin
        SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
        where  i.imovel_id = v.imovel_id
        and    (select count(*) from r_tb_tipo_vinculo where tb_tipo_vinculo_id = v.tb_tipo_vinculo_id and usar_na_doi = 'N') = 0
        and    i.tipo_registro = 'M'
        and    v.cpf_cnpj = :V_CPF_CONJUGE
        into :V_QTDE_ENCONTRADA;
      end
    end
  end

  if (COALESCE(:V_PESQUISAR_HOMONIMIA,'') = 'S') then
  begin
    --VERIFICAR HOMONIMIA PELO NOME
    I = 0;
    WHILE (:I < 4) DO
    BEGIN
      if (:I = 0) then --PESQUISAR NOME PRINCIPAL
      begin
        V_NOME_PESQUISA = :V_NOME;
      end
      if (:I = 1) then --PESQUISAR NOME PRINCIPAL(solteiro)
      begin
        V_NOME_PESQUISA = :V_NOME_SOLTEIRO;
      end
      if (:I = 2) then --PESQUISAR NOME conjuge
      begin
        V_NOME_PESQUISA = :V_NOME_CONJUGE;
      end
      if (:I = 3) then --PESQUISAR NOME conjuge (solteiro)
      begin
        V_NOME_PESQUISA = :V_NOME_CONJUGE_SOLTEIRO;
      end
  
      if (coalesce(:V_QTDE_ENCONTRADA,0) = 0) then
      begin
        IF (COALESCE(:V_NOME_PESQUISA,'') <> '') THEN
        BEGIN
          if (coalesce(:V_TIPO_PESQUISA,'') = '3') then --qualquer referencia
          begin
            SELECT COUNT(*) FROM R_PESSOA
            WHERE NOME = :V_NOME_PESQUISA
            AND COALESCE(CPF_CNPJ,'') = ''
            INTO :V_QTDE_ENCONTRADA;
  
            if (coalesce(:V_QTDE_ENCONTRADA,0) = 0) then
            begin
              SELECT COUNT(*) FROM R_PESSOA_VINCULO
              WHERE NOME = :V_NOME_PESQUISA
              AND COALESCE(CPF_CNPJ,'') = ''
              AND COALESCE(LRI_ID, 0) = 0
              AND COALESCE(PROCURACAO_ID, 0) = 0
              INTO :V_QTDE_ENCONTRADA;
            end
          END
          ELSE if (coalesce(:V_TIPO_PESQUISA,'') = '1') then --SOMENTE ATUAIS
          begin
            SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
            where  i.imovel_id = v.imovel_id
            and    (select count(*) from r_tb_tipo_vinculo where tb_tipo_vinculo_id = v.tb_tipo_vinculo_id and usar_na_doi = 'N') = 0
            and    i.tipo_registro = 'M'
            AND    V.NOME = :V_NOME_PESQUISA
            AND    COALESCE(V.CPF_CNPJ,'') = ''
            AND    V.DATA_TRANSFERENCIA IS NULL
            into :V_QTDE_ENCONTRADA;
          end
          else --todos vinculos
          begin
            SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
            where  i.imovel_id = v.imovel_id
            and    (select count(*) from r_tb_tipo_vinculo where tb_tipo_vinculo_id = v.tb_tipo_vinculo_id and usar_na_doi = 'N') = 0
            and    i.tipo_registro = 'M'
            AND    V.NOME = :V_NOME_PESQUISA
            AND    COALESCE(V.CPF_CNPJ,'') = ''
            into :V_QTDE_ENCONTRADA;
          end
        end
      end
      I = :i + 1;
    end
  end

  if (coalesce(:V_QTDE_ENCONTRADA,0) = 0) then
  begin
    POSITIVO = 'NAO';
  end
  else
  begin
    POSITIVO = 'SIM';
  end

  SUSPEND;  
END ^

ALTER PROCEDURE R_PODE_SELAR_PROTOCOLO_GO (V_PEDIDO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_TIPO_PROTOCOLO VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (STATUS CHAR(1) CHARACTER SET ISO8859_1,
TEXTO_INEXISTENTE VARCHAR(2000) CHARACTER SET ISO8859_1,
TEXTO_INCONSISTENTE VARCHAR(2000) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_PEDIDO_ITEM_ID INTEGER;
DECLARE VARIABLE V_PEDIDO_ITEM_NUMERO_ID INTEGER;
DECLARE VARIABLE V_QUANTIDADE INTEGER;
DECLARE VARIABLE V_SELO_GRUPO_ID INTEGER;
DECLARE VARIABLE V_COUNT INTEGER;
DECLARE VARIABLE V_TEXTO_INEXISTENTE VARCHAR(2000);
DECLARE VARIABLE V_TEXTO_INCONSISTENCIA VARCHAR(2000);
DECLARE VARIABLE V_NUMERO_GRUPO INTEGER;
DECLARE VARIABLE V_DESCRICAO_GRUPO VARCHAR(120);
DECLARE VARIABLE V_DESCRICAO_EMOLUMENTO VARCHAR(60);
BEGIN
  V_TEXTO_INEXISTENTE = '';
  V_TEXTO_INCONSISTENCIA = '';
  STATUS = 'T';
  TEXTO_INEXISTENTE = '';
  TEXTO_INCONSISTENTE = '';
  FOR SELECT PI.PEDIDO_ITEM_ID, PI.QUANTIDADE, I.SELO_GRUPO_ID, 
        E.DESCRICAO 
      FROM R_PEDIDO PE, R_PEDIDO_ITEM PI, G_EMOLUMENTO E, G_EMOLUMENTO_ITEM I, G_SELO_GRUPO S, 
        G_NATUREZA_TITULO N 
      WHERE PE.PEDIDO_ID = PI.PEDIDO_ID 
      AND PI.EMOLUMENTO_ID = E.EMOLUMENTO_ID 
      AND PI.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID 
      AND E.EMOLUMENTO_ID = I.EMOLUMENTO_ID
      AND I.SELO_GRUPO_ID = S.SELO_GRUPO_ID 
      AND PE.PEDIDO_ID = :V_PEDIDO_ID
      AND (PI.EXCLUI_DO_RELATORIO = 'N' OR PI.EXCLUI_DO_RELATORIO IS NULL OR PI.EXCLUI_DO_RELATORIO = '')       
      ORDER BY PI.PEDIDO_ITEM_ID
      INTO :V_PEDIDO_ITEM_ID, :V_QUANTIDADE, :V_SELO_GRUPO_ID, 
        :V_DESCRICAO_EMOLUMENTO DO
  BEGIN  
    IF (:V_QUANTIDADE > 0) THEN
    BEGIN
      --Verificar disponibilidade de selos para todos os atos  
	      SELECT COUNT(*) FROM G_SELO_LIVRO 
	      WHERE SELO_SITUACAO_ID = 1 --SITUACAO DISPONIVEL
	      AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
				   WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID)
      INTO :V_COUNT;
      IF ((:V_COUNT  = 0) OR (:V_COUNT <= :V_QUANTIDADE)) THEN
      BEGIN
        STATUS = 'F';
        SELECT NUMERO, DESCRICAO FROM G_SELO_GRUPO 
        WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID
        INTO :V_NUMERO_GRUPO, :V_DESCRICAO_GRUPO;

        IF (:V_TEXTO_INEXISTENTE = '') THEN
        BEGIN
          V_TEXTO_INEXISTENTE = ' * '||TRIM(CAST(:V_NUMERO_GRUPO AS VARCHAR(30))) ||'-'|| :V_DESCRICAO_GRUPO;
        END
        ELSE
        BEGIN
          V_TEXTO_INEXISTENTE = :V_TEXTO_INEXISTENTE ||
                    ' * '||TRIM(CAST(:V_NUMERO_GRUPO AS VARCHAR(30))) ||'-'|| :V_DESCRICAO_GRUPO;
        END      
      END
      SELECT COUNT(*) FROM R_PEDIDO_ITEM_NUMERO 
      WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
      INTO :V_COUNT;
      IF ((:V_COUNT > :V_QUANTIDADE) AND (V_TIPO_PROTOCOLO = '3')) THEN
      BEGIN
        STATUS = 'F';
        IF (:V_TEXTO_INCONSISTENCIA = '') THEN
        BEGIN
          V_TEXTO_INCONSISTENCIA = ' * '||:V_DESCRICAO_EMOLUMENTO;
        END
        ELSE
        BEGIN
          V_TEXTO_INCONSISTENCIA = :V_TEXTO_INCONSISTENCIA ||' * '||:V_DESCRICAO_EMOLUMENTO;
        END      
      END      
    END                
  END
  IF (STATUS = 'F') THEN
  BEGIN
    TEXTO_INEXISTENTE = TRIM(SUBSTRING(:V_TEXTO_INEXISTENTE from 1 for 2000));
    TEXTO_INCONSISTENTE = TRIM(SUBSTRING(:V_TEXTO_INCONSISTENCIA from 1 for 2000));
  END
  SUSPEND;  
END ^

ALTER PROCEDURE R_PRODUCAO_PROTOCOLO (V_TIPO VARCHAR(10) CHARACTER SET ISO8859_1,
V_TIPO_DATA VARCHAR(1) CHARACTER SET ISO8859_1,
V_DATA_INICIAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_NATUREZA_FORMAL_TITULO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_USUARIO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_USUARIO_DESTINO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_ANDAMENTOS VARCHAR(2000) CHARACTER SET ISO8859_1,
V_ANDAMENTOS_INEXISTENTES VARCHAR(2000) CHARACTER SET ISO8859_1 DEFAULT '')
RETURNS (STATUS VARCHAR(60) CHARACTER SET ISO8859_1,
USUARIO_QUE_ENVIOU VARCHAR(60) CHARACTER SET ISO8859_1,
USUARIO_QUE_RECEBEU VARCHAR(60) CHARACTER SET ISO8859_1,
DATA_PREVISTA DATE,
QTDE_DIAS_NO_ANDAMENTO INTEGER,
QTDE_DIAS_PROTOCOLO_FIM INTEGER,
QTDE_DIAS_PROTOCOLO_ENTREGA INTEGER,
DATA_ENTREGA DATE,
USUARIO_COM_TITULO VARCHAR(60) CHARACTER SET ISO8859_1,
PROTOCOLO_ID INTEGER,
DATA_PROTOCOLO DATE,
NUMERO_ORDEM INTEGER,
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_PROT_DESC VARCHAR(20) CHARACTER SET ISO8859_1,
PEDIDO_ID INTEGER,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
ANDAMENTO_ID INTEGER,
DATA_ANDAMENTO DATE,
USUARIO_ID INTEGER,
USUARIO_DESTINO_ID INTEGER,
TB_TIPO_ANDAMENTO_ID INTEGER,
NATUREZA_TITULO_ID INTEGER,
EMOLUMENTO_ID INTEGER,
QUANTIDADE_REGISTRO INTEGER,
QUANTIDADE_AVERBACAO INTEGER,
QUANTIDADE_CERTIDAO INTEGER,
TOTAL_REGISTRO NUMERIC(18, 2),
TOTAL_AVERBACAO NUMERIC(18, 2),
TOTAL_CERTIDAO NUMERIC(18, 2),
ORIGEM_PEDIDO VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_ORIGEM_SITE VARCHAR(3) CHARACTER SET ISO8859_1,
ULTIMO_ANDAMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
QTDE_DIAS_APOS_PROTOCOLAR INTEGER,
TOTAL_ISS NUMERIC(18, 2),
VALOR_COMPENSADO NUMERIC(18, 2),
VALOR_TRANSFERIDO NUMERIC(18, 2),
QUANTIDADE INTEGER,
VALOR_EMOLUMENTO NUMERIC(18, 2),
VALOR_FUNDO_RI NUMERIC(18, 2),
VALOR_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_GERAL NUMERIC(18, 2),
DESCRICAO_ANDAMENTO VARCHAR(260) CHARACTER SET ISO8859_1,
DESCRICAO_NATUREZA VARCHAR(260) CHARACTER SET ISO8859_1,
DESCRICAO_TITULO VARCHAR(260) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE D_TIPO_PROTOCOLO VARCHAR(1);
  DECLARE VARIABLE D_ULTIMO_PROTOCOLO_ID INTEGER;
  DECLARE VARIABLE D_TIPO_COBRANCA VARCHAR(1);
  DECLARE VARIABLE D_PEDIDO VARCHAR(15);
  DECLARE VARIABLE D_RETORNAR_REGISTRO VARCHAR(1);
  DECLARE VARIABLE D_QTDE_ANDAMENTO INTEGER;
  DECLARE VARIABLE D_PEDIDO_ITEM_ID INTEGER;
  DECLARE VARIABLE D_QTDE_MATRICULA INTEGER;
  DECLARE VARIABLE D_QTDE_PEDIDO_ITEM INTEGER;
  DECLARE VARIABLE V_SQL VARCHAR(5000);
  declare variable V_UF VARCHAR(10);
  declare variable V_NOVO_PEDIDO_ID INTEGER;
  declare variable V_CREDITO NUMERIC(18,2);
  declare variable V_QTDE_TEMP INTEGER;
  declare variable V_DATA_PROTOCOLO DATE;
  declare variable V_DATA_MEDIA DATE;
  declare variable V_ULTIMO_ANDAMENTO_ID INTEGER;
  declare variable V_DATA_ULTIMO_ANDAMENTO DATE;
  declare variable V_PERIODO_PADRAO VARCHAR(10);
  declare variable V_REG_AVERB VARCHAR(3);
  declare variable v_status_andamento varchar(3);
  declare variable v_status_data date;
BEGIN
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL','CARTORIO','UF',1)
  INTO :V_UF;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','PERIODO_PADRAO',1)
  INTO :V_PERIODO_PADRAO;

  DATA_ANDAMENTO = null;
  QUANTIDADE_REGISTRO = 0;
  QUANTIDADE_AVERBACAO = 0;
  QUANTIDADE_CERTIDAO = 0;
  TOTAL_REGISTRO = 0;
  TOTAL_AVERBACAO = 0;
  TOTAL_CERTIDAO = 0;
  ORIGEM_PEDIDO = '';
  TIPO_ORIGEM_SITE = '';
  ULTIMO_ANDAMENTO = '';
  QTDE_DIAS_APOS_PROTOCOLAR = 0;
  TOTAL_ISS = 0;
  VALOR_COMPENSADO = 0;
  VALOR_TRANSFERIDO = 0;
  QUANTIDADE = 0;
  VALOR_EMOLUMENTO = 0;
  VALOR_FUNDO_RI = 0;
  VALOR_TAXA_JUDICIARIA = 0;
  TOTAL_GERAL = 0;
  V_REG_AVERB = '';

  V_SQL = ' SELECT DISTINCT PR.PROTOCOLO_ID, PR.DATA,
               PR.NUMERO_ORDEM, PR.TIPO_PROTOCOLO,
               PE.PEDIDO_ID, PE.APRESENTANTE_NOME,
               A.ANDAMENTO_ID, A.DATA DATA_ANDAMENTO,
               A.USUARIO_ID, A.TB_TIPO_ANDAMENTO_ID, PR.TIPO_PROTOCOLO, PE.TIPO_COBRANCA,
               PE.ORIGEM_PEDIDO, PE.TIPO_ORIGEM_SITE, PE.NOVO_PEDIDO_ID,
               PI.NATUREZA_TITULO_ID, PI.EMOLUMENTO_ID, PI.PEDIDO_ITEM_ID,
               PE.VALOR_COMPENSADO, COALESCE(PI.QUANTIDADE,0), COALESCE(PI.VALOR_EMOLUMENTO,0),
               COALESCE(PI.VALOR_FUNDO_RI,0), COALESCE(PI.VALOR_TAXA_JUDICIARIA,0),
               COALESCE(PI.VALOR_ISS,0), E.reg_averb, TA.descricao, NT.descricao,
               TI.descricao, A.USUARIO_DESTINO_ID, PE.DATA_PREVISTA
        FROM   R_PROTOCOLO PR, R_PEDIDO PE, R_ANDAMENTO A, R_PEDIDO_ITEM PI, R_TB_TITULO TI,
          G_EMOLUMENTO E, R_TB_TIPO_ANDAMENTO TA, G_NATUREZA_TITULO NT
        WHERE  PR.PEDIDO_ID = PE.PEDIDO_ID
        AND    PE.PEDIDO_ID = PI.PEDIDO_ID
        AND    PE.PEDIDO_ID = A.PEDIDO_ID
        AND    PI.EMOLUMENTO_ID = E.EMOLUMENTO_ID
        AND    A.tb_tipo_andamento_id = TA.tb_tipo_andamento_id
        AND    PI.natureza_titulo_id = NT.natureza_titulo_id
        AND    PE.tb_titulo_id = TI.tb_titulo_id ';

  IF (COALESCE(:V_TIPO_DATA,'') = 'P') THEN --Pela Data do Protocolo
  BEGIN
    V_SQL = :V_SQL || ' AND PR.DATA BETWEEN CAST('||''''||:V_DATA_INICIAL||''''||' AS TIMESTAMP)
                                        AND CAST('||''''||:V_DATA_FINAL||''''||' AS TIMESTAMP) + 0.99999 ';
  END
  ELSE --Pela Data do Andamento
  BEGIN
    V_SQL = :V_SQL || ' AND A.DATA BETWEEN CAST('||''''||:V_DATA_INICIAL||''''||' AS TIMESTAMP)
                                       AND CAST('||''''||:V_DATA_FINAL||''''||' AS TIMESTAMP) + 0.99999 ';
  END

  IF (COALESCE(:V_TIPO,'') = 'E') THEN --Pela tipo de exame
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 2 ';
  END
  else IF (COALESCE(:V_TIPO,'') = 'P') THEN --Todos os protocolos
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 1 ';
  END
  ELSE IF (COALESCE(:V_TIPO,'') = 'C') THEN --Todas as certidoes
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = 3 ';
  END

  IF (COALESCE(:V_ANDAMENTOS,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND A.TB_TIPO_ANDAMENTO_ID IN ('||:V_ANDAMENTOS||') ';
  END

  IF (COALESCE(:V_USUARIO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND A.USUARIO_ID = '||:V_USUARIO_ID;
  END

  IF (COALESCE(:V_USUARIO_DESTINO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND A.USUARIO_DESTINO_ID = '||:V_USUARIO_DESTINO_ID;
  END

  IF (COALESCE(:V_ANDAMENTOS_INEXISTENTES,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND (SELECT COUNT(*) FROM R_ANDAMENTO WHERE PEDIDO_ID = PR.PEDIDO_ID AND TB_TIPO_ANDAMENTO_ID IN ('||:V_ANDAMENTOS_INEXISTENTES||')) = 0 ';
  END

  IF (COALESCE(:V_NATUREZA_FORMAL_TITULO_ID,'') <> '') THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PI.NATUREZA_TITULO_ID  = '||:V_NATUREZA_FORMAL_TITULO_ID;
  END

  V_SQL = :V_SQL || ' ORDER BY PR.PROTOCOLO_ID ';

  D_ULTIMO_PROTOCOLO_ID = 0;
  FOR EXECUTE STATEMENT V_SQL
  INTO :PROTOCOLO_ID, :DATA_PROTOCOLO, :NUMERO_ORDEM, :TIPO_PROTOCOLO, :PEDIDO_ID,
    :APRESENTANTE_NOME, :ANDAMENTO_ID, :DATA_ANDAMENTO,
    :USUARIO_ID, :TB_TIPO_ANDAMENTO_ID, :D_TIPO_PROTOCOLO, :D_TIPO_COBRANCA,
    :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE, :V_NOVO_PEDIDO_ID, :NATUREZA_TITULO_ID,
    :EMOLUMENTO_ID, :D_PEDIDO_ITEM_ID, :VALOR_COMPENSADO, :QUANTIDADE, :VALOR_EMOLUMENTO,
    :VALOR_FUNDO_RI, :VALOR_TAXA_JUDICIARIA, :TOTAL_ISS, :V_REG_AVERB,
    :DESCRICAO_ANDAMENTO, :DESCRICAO_NATUREZA, :DESCRICAO_TITULO, :usuario_destino_id,
    :DATA_PREVISTA DO
  BEGIN
    QUANTIDADE_REGISTRO = 0;
    QUANTIDADE_AVERBACAO = 0;
    QUANTIDADE_CERTIDAO = 0;
    TOTAL_REGISTRO = 0;
    TOTAL_AVERBACAO = 0;
    TOTAL_CERTIDAO = 0;
    ULTIMO_ANDAMENTO = '';
    QTDE_DIAS_APOS_PROTOCOLAR = 0;
    VALOR_TRANSFERIDO = 0;

    TOTAL_GERAL = COALESCE(:VALOR_EMOLUMENTO,0) + COALESCE(:VALOR_FUNDO_RI,0) +
      COALESCE(:VALOR_TAXA_JUDICIARIA,0) + COALESCE(:TOTAL_ISS,0);

    if ((COALESCE(:TIPO_PROTOCOLO,'') = '1') or (COALESCE(:TIPO_PROTOCOLO,'') = '2')) then --protocolo ou exame
    begin
      IF (COALESCE(:V_REG_AVERB,'') = 'A') THEN
      BEGIN
        QUANTIDADE_AVERBACAO = :QUANTIDADE;
        TOTAL_AVERBACAO = COALESCE(:VALOR_EMOLUMENTO,0) + COALESCE(:VALOR_FUNDO_RI,0) + COALESCE(:VALOR_TAXA_JUDICIARIA,0);
      END
      ELSE
      BEGIN
        QUANTIDADE_REGISTRO = :QUANTIDADE;
        TOTAL_REGISTRO = COALESCE(:VALOR_EMOLUMENTO,0) + COALESCE(:VALOR_FUNDO_RI,0) + COALESCE(:VALOR_TAXA_JUDICIARIA,0);
      END
    end
    ELSE
    BEGIN
      QUANTIDADE_CERTIDAO = :QUANTIDADE;
      TOTAL_CERTIDAO = COALESCE(:VALOR_EMOLUMENTO,0) + COALESCE(:VALOR_FUNDO_RI,0) + COALESCE(:VALOR_TAXA_JUDICIARIA,0);
    END

    if (COALESCE(:ORIGEM_PEDIDO,'') = '') then
    BEGIN
      ORIGEM_PEDIDO = '1'; --BALCAO
    END

    D_RETORNAR_REGISTRO = 'S';

    IF (:D_RETORNAR_REGISTRO = 'S') THEN
    BEGIN
      D_PEDIDO = CAST(CAST(:PEDIDO_ID AS INTEGER) AS VARCHAR(15));

      --ULTIMO ANDAMENTO
      SELECT FIRST 1 TA.descricao, a.tb_tipo_andamento_id, A.data
      FROM R_ANDAMENTO A, r_tb_tipo_andamento TA
      WHERE A.tb_tipo_andamento_id = TA.tb_tipo_andamento_id
      AND A.pedido_id = :D_PEDIDO
      ORDER BY A.andamento_id DESC
      INTO :ULTIMO_ANDAMENTO, :V_ULTIMO_ANDAMENTO_ID, :V_DATA_ULTIMO_ANDAMENTO;

      if (:TIPO_PROTOCOLO = '1') then
      begin
        TIPO_PROT_DESC = 'Protcoloco';
      end
      else if (:TIPO_PROTOCOLO = '2') then
      begin
        TIPO_PROT_DESC = 'Exame/Cálculo';
      end
      else
      begin
        TIPO_PROT_DESC = 'Ped. de Certidão';
      end

      STATUS = '';
  
      select status_andamento, data_andamento from R_ANDAMENTO_PROTOCOLO(:NUMERO_ORDEM)
      into :v_status_andamento, :v_status_data;
  
      select datediff (day, :DATA_PROTOCOLO, current_date) from rdb$database
      INTO :QTDE_DIAS_PROTOCOLO_FIM;
      if (coalesce(:v_status_andamento,'') = '1') then
      begin
        STATUS = 'EM ANÁLISE';
      end
      else if (coalesce(:v_status_andamento,'') = '2') then
      begin
        STATUS = 'EM EXIGÊNCIA';
      end
      else if (coalesce(:v_status_andamento,'') = '3') then
      begin
        STATUS = 'EM PROCESSO DE REGISTRO';
      end
      else if (coalesce(:v_status_andamento,'') = '4') then
      begin
        STATUS = 'REGISTRADO';
        QTDE_DIAS_PROTOCOLO_FIM = :v_status_data - :data_protocolo;
      end
      else if (coalesce(:v_status_andamento,'') = '5') then
      begin
        STATUS = 'CANCELADO';
        QTDE_DIAS_PROTOCOLO_FIM = :v_status_data - :data_protocolo;
      end
      else
      begin
        STATUS = '';
      end

      select login from g_usuario
      where usuario_id = :USUARIO_ID
      into :USUARIO_QUE_ENVIOU;

      select login from g_usuario
      where usuario_id = :usuario_destino_id
      into :USUARIO_QUE_RECEBEU;

      qtde_dias_no_andamento = :data_andamento - :data_protocolo;

      data_entrega = null;
      select first 1 a2.data from r_andamento a2, r_tb_tipo_andamento ta2
      where a2.tb_tipo_andamento_id = ta2.tb_tipo_andamento_id
      and a2.pedido_id = :pedido_id
      and ta2.sequencia_on_line = 6
      order by a2.andamento_id desc
      into :data_entrega;

      --verificar se foi entregue
      if (:data_entrega is null) then
      begin
        QTDE_DIAS_PROTOCOLO_ENTREGA = 0;
        --último usuário com o título
  
        select first 1 u.login
        from r_andamento a, g_usuario u
        where a.usuario_destino_id = u.usuario_id
        and a.pedido_id = :pedido_id
        and a.usuario_destino_id > 0
        order by a.andamento_id desc
        into :usuario_com_titulo;
      end
      else
      begin
        QTDE_DIAS_PROTOCOLO_ENTREGA = :data_entrega - :data_protocolo;
        USUARIO_COM_TITULO = '';
      end


      SUSPEND;
      D_ULTIMO_PROTOCOLO_ID = :PROTOCOLO_ID;
    END
  END
END ^

ALTER PROCEDURE R_PROTOCOLAR_PEDIDO_CENTRAL (V_PEDIDO_ID INTEGER,
V_USUARIO_ID INTEGER,
V_TB_TIPO_ANDAMENTO_ID INTEGER,
V_COMPLEMENTO VARCHAR_060,
V_CAIXA_SERVICO_ID INTEGER)
RETURNS (PROTOCOLO_ID INTEGER,
TIPO_PROTOCOLO VARCHAR_001,
NUMERO_ORDEM INTEGER)
AS 
DECLARE VARIABLE V_ANDAMENTO_ID INTEGER;
  DECLARE VARIABLE V_CAIXA_ITEM_ID INTEGER;
  DECLARE VARIABLE V_DESCRICAO VARCHAR_120;
  DECLARE VARIABLE V_APRESENTANTE VARCHAR_120;
  DECLARE VARIABLE V_VALOR_TOTAL DINHEIRO;
  DECLARE VARIABLE V_TAMANHO INTEGER;
  DECLARE VARIABLE V_PEDIDO_ITEM_ID INTEGER;
  DECLARE VARIABLE V_QUANTIDADE INTEGER;
  DECLARE VARIABLE V_SELO_USAR_ID INTEGER;
  DECLARE VARIABLE V_NUMERO_SELO VARCHAR_030;
  DECLARE VARIABLE V_USUARIO_NOME VARCHAR_120;
  DECLARE VARIABLE V_USUARIO_NOME2 VARCHAR_060;
BEGIN
  --Lock na tabela Contador
  UPDATE R_CONTADOR SET PED_CERTIDAO = PED_CERTIDAO;
  
  SELECT (COALESCE(PED_CERTIDAO,0) + 1) FROM R_CONTADOR
  INTO :NUMERO_ORDEM;
  
  --INCLUIR PROTOCOLO
  SELECT GEN_ID(PROTOCOLO_SEQ,1) FROM RDB$DATABASE
  INTO :PROTOCOLO_ID;  
  INSERT INTO R_PROTOCOLO(PROTOCOLO_ID, PEDIDO_ID, DATA, NUMERO_ORDEM,
    TIPO_PROTOCOLO)
  VALUES(:PROTOCOLO_ID, :V_PEDIDO_ID, CURRENT_TIMESTAMP, :NUMERO_ORDEM,
    '3');
  
  --ATUALIZAR CONTADOR
  UPDATE R_CONTADOR SET PED_CERTIDAO = :NUMERO_ORDEM;
  
  --INCLUIR ANDAMENTO
  SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('R_ANDAMENTO')
  INTO :V_ANDAMENTO_ID;  
  INSERT INTO R_ANDAMENTO(ANDAMENTO_ID, PEDIDO_ID, DATA, USUARIO_ID, TB_TIPO_ANDAMENTO_ID,
    COMPLEMENTO, DATA_INCLUSAO)
  VALUES(:V_ANDAMENTO_ID, :V_PEDIDO_ID, CURRENT_TIMESTAMP, :V_USUARIO_ID, :V_TB_TIPO_ANDAMENTO_ID,
    :V_COMPLEMENTO, CURRENT_TIMESTAMP);
  
  SELECT APRESENTANTE_NOME FROM R_PEDIDO
  WHERE PEDIDO_ID = :V_PEDIDO_ID  
  INTO :V_APRESENTANTE;
  
  V_DESCRICAO = 'Ped.Cert.:'||:NUMERO_ORDEM||' - '||:V_APRESENTANTE;
  
  SELECT TAMANHO FROM W_LENGTH(:V_DESCRICAO)
  INTO :V_TAMANHO;
  
  IF (:V_TAMANHO > 120) THEN
  BEGIN
    V_DESCRICAO = SUBSTRING(:V_DESCRICAO FROM 1 FOR 120);
  END
  
  SELECT TOTAL_GERAL FROM R_TOTAL_PEDIDO(:V_PEDIDO_ID)
  INTO :V_VALOR_TOTAL;
  
  --INCLUIR CAIXA    
  SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('C_CAIXA_ITEM')
  INTO :V_CAIXA_ITEM_ID;    
  INSERT INTO C_CAIXA_ITEM(CAIXA_ITEM_ID, CAIXA_SERVICO_ID, ESPECIE_PAGAMENTO,
    USUARIO_SERVICO_ID, CHAVE_SERVICO, DESCRICAO, DATA_PAGAMENTO, SITUACAO,
    TIPO_DOCUMENTO, TIPO_TRANSACAO, VALOR_SERVICO, VALOR_PAGO, HORA_PAGAMENTO, 
    TIPO_SERVICO)
  VALUES(:V_CAIXA_ITEM_ID, :V_CAIXA_SERVICO_ID, 'D', 
    :V_USUARIO_ID, :PROTOCOLO_ID, :V_DESCRICAO, CURRENT_TIMESTAMP, '4',
    'C', 'C', :V_VALOR_TOTAL, 0, '', 
    '3');                 
    
   --SELAR PROTOCOLO (DF)
   FOR SELECT PI.PEDIDO_ITEM_ID 
       FROM R_PEDIDO_ITEM PI, G_NATUREZA_TITULO NT 
       WHERE  PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID 
       AND PI.PEDIDO_ID = :V_PEDIDO_ID
       AND (NT.NAO_GERAR_SELO IS NULL OR 
            NT.NAO_GERAR_SELO = 'N' OR 
            NT.NAO_GERAR_SELO = '')
       ORDER BY PI.SEQUENCIA, PI.PEDIDO_ITEM_ID 
       INTO :V_PEDIDO_ITEM_ID DO
   BEGIN
     SELECT COUNT(*) FROM R_PEDIDO_ITEM 
     WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
     AND (NUMERO_SELO IS NULL OR NUMERO_SELO = '')
     INTO :V_QUANTIDADE;
     
     IF (:V_QUANTIDADE > 0) THEN
     BEGIN
       SELECT GEN_ID(R_SELO_USAR_SEQ,1) FROM RDB$DATABASE
       INTO :V_SELO_USAR_ID;
       
       SELECT NUMERO_SELO FROM R_SELO
       WHERE SELO_ID = :V_SELO_USAR_ID
       INTO :V_NUMERO_SELO;
       
       IF (NOT ((:V_NUMERO_SELO IS NULL) OR (:V_NUMERO_SELO = ''))) THEN
       BEGIN
         UPDATE R_PEDIDO_ITEM SET NUMERO_SELO = :V_NUMERO_SELO
         WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID;       

         SELECT NOME_COMPLETO FROM G_USUARIO
         WHERE USUARIO_ID = :V_USUARIO_ID
         INTO :V_USUARIO_NOME;

         SELECT TAMANHO FROM W_LENGTH(:V_USUARIO_NOME)
         INTO :V_TAMANHO;
  
         IF (:V_TAMANHO > 60) THEN
         BEGIN           
           V_USUARIO_NOME = SUBSTRING(:V_USUARIO_NOME FROM 1 FOR 120);
         END
         V_USUARIO_NOME2 = CAST(V_USUARIO_NOME AS VARCHAR(60));
                  
         UPDATE R_SELO 
         SET STATUS = '2',
             USUARIO_USOU_SELO = :V_USUARIO_NOME2
         WHERE NUMERO_SELO = :V_NUMERO_SELO;
       END
     END        
   END
  SUSPEND;  
END ^

ALTER PROCEDURE R_PROTOCOLOS_FALTANTES (TIPO_PROTOCOLO VARCHAR(3) CHARACTER SET ISO8859_1,
NUMERO_INICIAL INTEGER)
RETURNS (PROTOCOLO_FALTANTE INTEGER)
AS 
declare variable protocolo_atual integer;
  declare variable protocolo_temp integer;
begin
  protocolo_temp = NUMERO_INICIAL;
  for select numero_ordem from r_protocolo
      where tipo_protocolo = :TIPO_PROTOCOLO
      order by numero_ordem
      into :protocolo_atual do
  begin
    while (:protocolo_atual >= :protocolo_temp) do
    begin
      if (:protocolo_atual > :protocolo_temp) then
      begin
        protocolo_faltante = :protocolo_temp;
        suspend;
      end
      protocolo_temp = :protocolo_temp + 1;
    end
  end
end ^

ALTER PROCEDURE R_PROTOCOLOS_VINCULADOS (V_TIPO_REGISTRO VARCHAR(5) CHARACTER SET ISO8859_1,
V_NUMERO VARCHAR(12) CHARACTER SET ISO8859_1,
V_NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
V_PESSOA_ID VARCHAR(12) CHARACTER SET ISO8859_1,
V_TODOS VARCHAR(5) CHARACTER SET ISO8859_1)
RETURNS (PEDIDO_ID NUMERIC(18, 2),
REGISTRO_TIPO VARCHAR(5) CHARACTER SET ISO8859_1,
NUMERO NUMERIC(18, 2),
ATO_TIPO VARCHAR(5) CHARACTER SET ISO8859_1,
ATO_NUMERO NUMERIC(18, 2),
NATUREZA_TITULO_ID NUMERIC(18, 2),
ADQUIRENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE VSQL VARCHAR(2000);
DECLARE VARIABLE V_REG_TIPO VARCHAR(5);
DECLARE VARIABLE V_NUM NUMERIC(18, 2);
DECLARE VARIABLE V_NUM_LETRA VARCHAR(3);
DECLARE VARIABLE V_ATO_TIPO VARCHAR(5);
DECLARE VARIABLE V_ATO_NUMERO NUMERIC(18, 2);
DECLARE VARIABLE REG_TIPO VARCHAR(5);
DECLARE VARIABLE NUM NUMERIC(18, 2);
DECLARE VARIABLE V_QUANT NUMERIC(18, 2);
DECLARE VARIABLE V_QTDE_DIA INTEGER;
BEGIN
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','GERAL','QTDE_DIA_PROTOCOLO_VINCULADO',1)
  INTO :V_QTDE_DIA;

  if (COALESCE(:V_QTDE_DIA,0) = 0) then
  begin
    V_QTDE_DIA = 1800;
  end

  IF ((:V_PESSOA_ID <> '') AND (:V_PESSOA_ID IS NOT NULL)) THEN
  BEGIN
    FOR SELECT DISTINCT I.NUMERO, I.NUMERO_LETRA, I.TIPO_REGISTRO,
               V.TIPO_ATO, V.NUMERO_ATO
        FROM   R_IMOVEL I, R_PESSOA_VINCULO V
        WHERE V.IMOVEL_ID = I.IMOVEL_ID
        AND V.PESSOA_ID =  :V_PESSOA_ID
        ORDER BY I.NUMERO
        INTO :V_NUM, :V_NUM_LETRA, :V_REG_TIPO, :V_ATO_TIPO, :V_ATO_NUMERO DO
    BEGIN
      IF ((:V_NUM_LETRA IS NULL) OR (:V_NUM_LETRA = '') OR (:V_NUM_LETRA = '#')) THEN
      BEGIN
        IF (:V_TODOS = 'A') THEN --Prot. em andamento
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = :V_REG_TIPO
              AND    PN.NUMERO = :V_NUM
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
              AND    (PN.ATO_TIPO = :V_ATO_TIPO OR PN.ATO_TIPO IS NULL)
              AND    (PN.ATO_NUMERO = :V_ATO_NUMERO OR PN.ATO_NUMERO IS NULL)
              AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
              AND    PR.DATA > CURRENT_DATE - :V_QTDE_DIA
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID,:ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
        ELSE IF (:V_TODOS = 'T') THEN --Todos Prot. ou Exames
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = :V_REG_TIPO
              AND    PN.NUMERO = :V_NUM
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
              AND    (PN.ATO_TIPO = :V_ATO_TIPO OR PN.ATO_TIPO IS NULL)
              AND    (PN.ATO_NUMERO = :V_ATO_NUMERO OR PN.ATO_NUMERO IS NULL)
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID,:ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
        ELSE IF (:V_TODOS = 'P') THEN --Todos Ped. Certidao
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 3 OR PR.TIPO_PROTOCOLO = 4)
              AND    PN.TIPO_REGISTRO = :V_REG_TIPO
              AND    PN.NUMERO = :V_NUM
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
              AND    (PN.ATO_TIPO = :V_ATO_TIPO OR PN.ATO_TIPO IS NULL)
              AND    (PN.ATO_NUMERO = :V_ATO_NUMERO OR PN.ATO_NUMERO IS NULL)
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID,:ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END      
      END
    END
  END
  ELSE
  BEGIN
    IF ((:V_NUMERO_LETRA IS NULL) OR (:V_NUMERO_LETRA = '')) THEN
    BEGIN  
      SELECT COUNT(*)
      FROM   R_IMOVEL I
      WHERE  I.TIPO_REGISTRO =  :V_TIPO_REGISTRO
      AND    I.NUMERO = :V_NUMERO
      AND    (I.NUMERO_LETRA IS NULL OR I.NUMERO_LETRA = '' OR I.NUMERO_LETRA = '#')
      INTO V_QUANT;
    END
    ELSE
    BEGIN
      SELECT COUNT(*)
      FROM   R_IMOVEL I
      WHERE  I.TIPO_REGISTRO =  :V_TIPO_REGISTRO
      AND   I.NUMERO = :V_NUMERO
      AND I.NUMERO_LETRA = :V_NUMERO_LETRA
      INTO V_QUANT;    
    END
      
    IF (V_QUANT = 0) THEN
    BEGIN
      IF ((:V_NUMERO_LETRA IS NULL) OR (:V_NUMERO_LETRA = '')) THEN
      BEGIN
        IF (:V_TODOS = 'A') THEN --Prot. em andamento
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
              AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
              AND    PR.DATA > CURRENT_DATE - :V_QTDE_DIA
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
        ELSE IF (:V_TODOS = 'T') THEN --Todos Protocolos
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
        ELSE IF (:V_TODOS = 'P') THEN --Todos Ped.Certidao
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 3 OR PR.TIPO_PROTOCOLO = 4)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
      END
      ELSE
      BEGIN
        IF (:V_TODOS = 'A') THEN --Prot. em andamento
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
              AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
              AND    PR.DATA > CURRENT_DATE - :V_QTDE_DIA
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
        ELSE IF (:V_TODOS = 'T') THEN --Todos Protocolos
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
        ELSE IF (:V_TODOS = 'P') THEN --Todos Ped.Certidao
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 3 OR PR.TIPO_PROTOCOLO = 4)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END            
      END
    END
    ELSE
    BEGIN
      IF ((:V_NUMERO_LETRA IS NULL) OR (:V_NUMERO_LETRA = '')) THEN
      BEGIN   
        FOR SELECT DISTINCT I.NUMERO, I.TIPO_REGISTRO
            FROM   R_IMOVEL I
            WHERE  I.TIPO_REGISTRO = :V_TIPO_REGISTRO
            AND    I.NUMERO = :V_NUMERO
            AND    (I.NUMERO_LETRA IS NULL OR I.NUMERO_LETRA = '' OR I.NUMERO_LETRA = '#')
            ORDER BY I.NUMERO
            INTO :V_NUM, :V_REG_TIPO DO
        BEGIN
          IF (:V_TODOS = 'A') THEN --Protocolos em andamento
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
                AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
                AND    PR.DATA > CURRENT_DATE - :V_QTDE_DIA
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
