          ELSE IF (:V_TODOS = 'T') THEN --Todos Protocolos
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
          END
          ELSE IF (:V_TODOS = 'P') THEN --Todos Ped. Certidao
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 3 OR PR.TIPO_PROTOCOLO = 4)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
          END        
        END
      END
      ELSE
      BEGIN            
        FOR SELECT DISTINCT I.NUMERO, I.TIPO_REGISTRO
            FROM   R_IMOVEL I
            WHERE  I.TIPO_REGISTRO = :V_TIPO_REGISTRO
            AND    I.NUMERO = :V_NUMERO
            AND    I.NUMERO_LETRA = :V_NUMERO_LETRA
            ORDER BY I.NUMERO
            INTO :V_NUM, :V_REG_TIPO DO
        BEGIN
          IF (:V_TODOS = 'A') THEN --Protocolos em andamento
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
                AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
                AND    PR.DATA > CURRENT_DATE - :V_QTDE_DIA
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
          END
          ELSE IF (:V_TODOS = 'T') THEN --Todos Protocolos
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
          END
          ELSE IF (:V_TODOS = 'P') THEN --Todos Ped. Certidao
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 3 OR PR.TIPO_PROTOCOLO = 4)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
          END        
        END            
      END
    END      
  END
END ^

ALTER PROCEDURE R_PROTOCOLOS_VINCULADOS_CART (V_CARTORIO VARCHAR(5) CHARACTER SET ISO8859_1,
V_TIPO_REGISTRO VARCHAR(5) CHARACTER SET ISO8859_1,
V_NUMERO VARCHAR(12) CHARACTER SET ISO8859_1,
V_NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
V_PESSOA_ID VARCHAR(12) CHARACTER SET ISO8859_1,
V_TODOS VARCHAR(5) CHARACTER SET ISO8859_1)
RETURNS (PEDIDO_ID NUMERIC(18, 2),
REGISTRO_TIPO VARCHAR(5) CHARACTER SET ISO8859_1,
NUMERO NUMERIC(18, 2),
ATO_TIPO VARCHAR(5) CHARACTER SET ISO8859_1,
ATO_NUMERO NUMERIC(18, 2),
NATUREZA_TITULO_ID NUMERIC(18, 2),
ADQUIRENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE VSQL VARCHAR(2000);
DECLARE VARIABLE V_REG_TIPO VARCHAR(5);
DECLARE VARIABLE V_NUM NUMERIC(18, 2);
DECLARE VARIABLE V_NUM_LETRA VARCHAR(3);
DECLARE VARIABLE V_ATO_TIPO VARCHAR(5);
DECLARE VARIABLE V_ATO_NUMERO NUMERIC(18, 2);
DECLARE VARIABLE REG_TIPO VARCHAR(5);
DECLARE VARIABLE NUM NUMERIC(18, 2);
DECLARE VARIABLE V_QUANT NUMERIC(18, 2);
declare variable V_SQL VARCHAR(2000);
declare variable V_QTDE_DIA INTEGER;
BEGIN
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','GERAL','QTDE_DIA_PROTOCOLO_VINCULADO',1)
  INTO :V_QTDE_DIA;

  if (COALESCE(:V_QTDE_DIA,0) = 0) then
  begin
    V_QTDE_DIA = 1800;
  end

  IF ((:V_PESSOA_ID <> '') AND (:V_PESSOA_ID IS NOT NULL)) THEN
  BEGIN
    IF (:V_TODOS = 'A') THEN --Prot. em andamento
    BEGIN
      V_SQL = 'SELECT DISTINCT I.NUMERO, I.NUMERO_LETRA, I.TIPO_REGISTRO,
                 V.TIPO_ATO, V.NUMERO_ATO, PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME, PR.TIPO_PROTOCOLO
          FROM   R_IMOVEL I, R_PESSOA_VINCULO V, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
          WHERE V.IMOVEL_ID = I.IMOVEL_ID
          AND V.PESSOA_ID =  '||:V_PESSOA_ID||'
          AND PE.PEDIDO_ID = PR.PEDIDO_ID
          AND    PE.PEDIDO_ID = PI.PEDIDO_ID
          AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
          AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
          AND    PN.TIPO_REGISTRO = I.TIPO_REGISTRO
          AND    PN.NUMERO = I.NUMERO
          AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '||''''''||')
          AND    (PN.ATO_TIPO = V.TIPO_ATO OR PN.ATO_TIPO IS NULL)
          AND    (PN.ATO_NUMERO = V.NUMERO_ATO OR PN.ATO_NUMERO IS NULL)
          AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
          AND    PR.DATA > CURRENT_DATE - '||:V_QTDE_DIA||'
          ORDER BY I.NUMERO, PR.DATA ';
    END
    ELSE IF (:V_TODOS = 'T') THEN --Todos Prot. ou Exames
    BEGIN
      V_SQL = 'SELECT DISTINCT I.NUMERO, I.NUMERO_LETRA, I.TIPO_REGISTRO,
                 V.TIPO_ATO, V.NUMERO_ATO, PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME, PR.TIPO_PROTOCOLO
          FROM   R_IMOVEL I, R_PESSOA_VINCULO V, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
          WHERE V.IMOVEL_ID = I.IMOVEL_ID
          AND V.PESSOA_ID =  '||:V_PESSOA_ID||'
          AND PE.PEDIDO_ID = PR.PEDIDO_ID
          AND    PE.PEDIDO_ID = PI.PEDIDO_ID
          AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
          AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
          AND    PN.TIPO_REGISTRO = I.TIPO_REGISTRO
          AND    PN.NUMERO = I.NUMERO
          AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '||''''''||')
          AND    (PN.ATO_TIPO = V.TIPO_ATO OR PN.ATO_TIPO IS NULL)
          AND    (PN.ATO_NUMERO = V.NUMERO_ATO OR PN.ATO_NUMERO IS NULL)
          ORDER BY I.NUMERO, PR.DATA ';
    END
    ELSE IF (:V_TODOS = 'P') THEN --Todos Ped. Certidao
    BEGIN
      V_SQL = 'SELECT DISTINCT I.NUMERO, I.NUMERO_LETRA, I.TIPO_REGISTRO,
                 V.TIPO_ATO, V.NUMERO_ATO, PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME, PR.TIPO_PROTOCOLO
          FROM   R_IMOVEL I, R_PESSOA_VINCULO V, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
          WHERE V.IMOVEL_ID = I.IMOVEL_ID
          AND V.PESSOA_ID =  '||:V_PESSOA_ID||'
          AND PE.PEDIDO_ID = PR.PEDIDO_ID
          AND    PE.PEDIDO_ID = PI.PEDIDO_ID
          AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
          AND    PR.TIPO_PROTOCOLO = 3
          AND    PN.TIPO_REGISTRO = I.TIPO_REGISTRO
          AND    PN.NUMERO = I.NUMERO
          AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '||''''''||')
          AND    (PN.ATO_TIPO = V.TIPO_ATO OR PN.ATO_TIPO IS NULL)
          AND    (PN.ATO_NUMERO = V.NUMERO_ATO OR PN.ATO_NUMERO IS NULL)
          ORDER BY I.NUMERO, PR.DATA ';
    END


    FOR EXECUTE STATEMENT :V_SQL
        INTO :V_NUM, :V_NUM_LETRA, :V_REG_TIPO, :V_ATO_TIPO, :V_ATO_NUMERO,
        :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID,:ADQUIRENTE_NOME, :APRESENTANTE_NOME, :TIPO_PROTOCOLO  DO
    BEGIN
      SUSPEND;
    END
  END
  ELSE
  BEGIN
    IF ((:V_NUMERO_LETRA IS NULL) OR (:V_NUMERO_LETRA = '')) THEN
    BEGIN  
      SELECT COUNT(*)
      FROM   R_IMOVEL I
      WHERE  I.TIPO_REGISTRO =  :V_TIPO_REGISTRO
      AND    I.NUMERO = :V_NUMERO
      AND    (I.NUMERO_LETRA IS NULL OR I.NUMERO_LETRA = '' OR I.NUMERO_LETRA = '#')
      AND    i.CARTORIO = :V_CARTORIO
      INTO V_QUANT;
    END
    ELSE
    BEGIN
      SELECT COUNT(*)
      FROM   R_IMOVEL I
      WHERE  I.TIPO_REGISTRO =  :V_TIPO_REGISTRO
      AND   I.NUMERO = :V_NUMERO
      AND I.NUMERO_LETRA = :V_NUMERO_LETRA
      AND    I.CARTORIO = :V_CARTORIO
      INTO V_QUANT;    
    END
      
    IF (V_QUANT = 0) THEN
    BEGIN
      IF ((:V_NUMERO_LETRA IS NULL) OR (:V_NUMERO_LETRA = '')) THEN
      BEGIN
        IF (:V_TODOS = 'A') THEN --Prot. em andamento
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
              AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
              AND    PR.DATA > CURRENT_DATE - :V_QTDE_DIA
              AND    PN.CARTORIO = :V_CARTORIO
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
        ELSE IF (:V_TODOS = 'T') THEN --Todos Protocolos
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
              AND    PN.CARTORIO = :V_CARTORIO
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
        ELSE IF (:V_TODOS = 'P') THEN --Todos Ped.Certidao
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 3 OR PR.TIPO_PROTOCOLO = 4)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
              AND    PN.CARTORIO = :V_CARTORIO
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
      END
      ELSE
      BEGIN
        IF (:V_TODOS = 'A') THEN --Prot. em andamento
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
              AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
              AND    PR.DATA > CURRENT_DATE - :V_QTDE_DIA
              AND    PN.CARTORIO = :V_CARTORIO
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
        ELSE IF (:V_TODOS = 'T') THEN --Todos Protocolos
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
              AND    PN.CARTORIO = :V_CARTORIO
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END
        ELSE IF (:V_TODOS = 'P') THEN --Todos Ped.Certidao
        BEGIN
          FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                     PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                     PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
              FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                     R_PROTOCOLO PR, R_PEDIDO PE
              WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 3 OR PR.TIPO_PROTOCOLO = 4)
              AND    PN.TIPO_REGISTRO = :V_TIPO_REGISTRO
              AND    PN.NUMERO = :V_NUMERO
              AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
              AND    PN.CARTORIO = :V_CARTORIO
              ORDER BY PR.DATA DESC
          INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
          BEGIN
            SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
            WHERE PR.PEDIDO_ID = :PEDIDO_ID
            ORDER BY PR.TIPO_PROTOCOLO
            INTO :TIPO_PROTOCOLO;
            SUSPEND;
          END
        END            
      END
    END
    ELSE
    BEGIN
      IF ((:V_NUMERO_LETRA IS NULL) OR (:V_NUMERO_LETRA = '')) THEN
      BEGIN   
        FOR SELECT DISTINCT I.NUMERO, I.TIPO_REGISTRO
            FROM   R_IMOVEL I
            WHERE  I.TIPO_REGISTRO = :V_TIPO_REGISTRO
            AND    I.NUMERO = :V_NUMERO
            AND    (I.NUMERO_LETRA IS NULL OR I.NUMERO_LETRA = '' OR I.NUMERO_LETRA = '#')
            ORDER BY I.NUMERO
            INTO :V_NUM, :V_REG_TIPO DO
        BEGIN
          IF (:V_TODOS = 'A') THEN --Protocolos em andamento
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
                AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
                AND    PR.DATA > CURRENT_DATE - :V_QTDE_DIA
                AND    PN.CARTORIO = :V_CARTORIO
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
          END
          ELSE IF (:V_TODOS = 'T') THEN --Todos Protocolos
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
                AND    PN.CARTORIO = :V_CARTORIO
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
          END
          ELSE IF (:V_TODOS = 'P') THEN --Todos Ped. Certidao
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 3 OR PR.TIPO_PROTOCOLO = 4)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '')
                AND    PN.CARTORIO = :V_CARTORIO
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
          END        
        END
      END
      ELSE
      BEGIN            
        FOR SELECT DISTINCT I.NUMERO, I.TIPO_REGISTRO
            FROM   R_IMOVEL I
            WHERE  I.TIPO_REGISTRO = :V_TIPO_REGISTRO
            AND    I.NUMERO = :V_NUMERO
            AND    I.NUMERO_LETRA = :V_NUMERO_LETRA
            ORDER BY I.NUMERO
            INTO :V_NUM, :V_REG_TIPO DO
        BEGIN
          IF (:V_TODOS = 'A') THEN --Protocolos em andamento
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
                AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
                AND    PR.DATA > CURRENT_DATE - :V_QTDE_DIA
                AND    PN.CARTORIO = :V_CARTORIO
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
          END
          ELSE IF (:V_TODOS = 'T') THEN --Todos Protocolos
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
                AND    PN.CARTORIO = :V_CARTORIO
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
          END
          ELSE IF (:V_TODOS = 'P') THEN --Todos Ped. Certidao
          BEGIN
            FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                       PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                       PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                       R_PROTOCOLO PR, R_PEDIDO PE
                WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                AND    (PR.TIPO_PROTOCOLO = 3 OR PR.TIPO_PROTOCOLO = 4)
                AND    PN.TIPO_REGISTRO = :V_REG_TIPO
                AND    PN.NUMERO = :V_NUM
                AND    PN.NUMERO_LETRA = :V_NUMERO_LETRA
                AND    PN.CARTORIO = :V_CARTORIO
                ORDER BY PR.DATA DESC
            INTO :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
                 :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
            BEGIN
              SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
              WHERE PR.PEDIDO_ID = :PEDIDO_ID
              ORDER BY PR.TIPO_PROTOCOLO
              INTO :TIPO_PROTOCOLO;
              SUSPEND;
            END
          END        
        END            
      END
    END      
  END
END ^

ALTER PROCEDURE R_PROTOCOLOS_VINCULADOS_NOVO (V_CARTORIO VARCHAR(5) CHARACTER SET ISO8859_1,
V_TIPO_REGISTRO VARCHAR(5) CHARACTER SET ISO8859_1,
V_NUMERO VARCHAR(12) CHARACTER SET ISO8859_1,
V_NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1,
V_CPF_CNPJ VARCHAR(30) CHARACTER SET ISO8859_1,
V_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
V_TODOS VARCHAR(5) CHARACTER SET ISO8859_1)
RETURNS (PEDIDO_ID NUMERIC(18, 2),
REGISTRO_TIPO VARCHAR(5) CHARACTER SET ISO8859_1,
NUMERO NUMERIC(18, 2),
ATO_TIPO VARCHAR(5) CHARACTER SET ISO8859_1,
ATO_NUMERO NUMERIC(18, 2),
NATUREZA_TITULO_ID NUMERIC(18, 2),
ADQUIRENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO_LETRA VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE VSQL VARCHAR(2000);
DECLARE VARIABLE V_REG_TIPO VARCHAR(5);
DECLARE VARIABLE V_NUM NUMERIC(18, 2);
DECLARE VARIABLE V_NUM_LETRA VARCHAR(3);
DECLARE VARIABLE V_ATO_TIPO VARCHAR(5);
DECLARE VARIABLE V_ATO_NUMERO NUMERIC(18, 2);
DECLARE VARIABLE REG_TIPO VARCHAR(5);
DECLARE VARIABLE NUM NUMERIC(18, 2);
DECLARE VARIABLE V_QUANT NUMERIC(18, 2);
declare variable V_SQL VARCHAR(2000);
declare variable V_QTDE_DIA INTEGER;
declare variable V_USAR_MULT_CART VARCHAR(3);
BEGIN
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','GERAL','QTDE_DIA_PROTOCOLO_VINCULADO',1)
  INTO :V_QTDE_DIA;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('REAL','GERAL','USAR_MULTIPLOS_CARTORIOS',1)
  INTO :V_USAR_MULT_CART;

  if (COALESCE(:V_QTDE_DIA,0) = 0) then
  begin
    V_QTDE_DIA = 1800;
  end

  if ((coalesce(:v_cpf_cnpj,'') <> '') or (coalesce(:v_nome,'') <> '')) then
  begin
    if (coalesce(:v_cpf_cnpj,'') <> '') then
    BEGIN
        IF (:V_TODOS = 'A') THEN --Prot. em andamento
        BEGIN
          V_SQL = 'SELECT DISTINCT I.NUMERO, I.NUMERO_LETRA, I.TIPO_REGISTRO,
                     V.TIPO_ATO, V.NUMERO_ATO, PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                           PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                           PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME, PR.TIPO_PROTOCOLO
              FROM   R_IMOVEL I, R_PESSOA_VINCULO V, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                           R_PROTOCOLO PR, R_PEDIDO PE
              WHERE V.IMOVEL_ID = I.IMOVEL_ID
              AND V.cpf_cnpj =  '||''''||:v_cpf_cnpj||''''||'
              AND PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = I.TIPO_REGISTRO
              AND    PN.NUMERO = I.NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '||''''''||')
              AND    (PN.ATO_TIPO = V.TIPO_ATO OR PN.ATO_TIPO IS NULL)
              AND    (PN.ATO_NUMERO = V.NUMERO_ATO OR PN.ATO_NUMERO IS NULL)
              AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
              AND    PR.DATA > CURRENT_DATE - '||:V_QTDE_DIA||'
              ORDER BY I.NUMERO, PR.DATA ';
        END
        ELSE IF (:V_TODOS = 'T') THEN --Todos Prot. ou Exames
        BEGIN
          V_SQL = 'SELECT DISTINCT I.NUMERO, I.NUMERO_LETRA, I.TIPO_REGISTRO,
                     V.TIPO_ATO, V.NUMERO_ATO, PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                           PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                           PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME, PR.TIPO_PROTOCOLO
              FROM   R_IMOVEL I, R_PESSOA_VINCULO V, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                           R_PROTOCOLO PR, R_PEDIDO PE
              WHERE V.IMOVEL_ID = I.IMOVEL_ID
              AND V.cpf_cnpj =  '||''''||:v_cpf_cnpj||''''||'
              AND PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = I.TIPO_REGISTRO
              AND    PN.NUMERO = I.NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '||''''''||')
              AND    (PN.ATO_TIPO = V.TIPO_ATO OR PN.ATO_TIPO IS NULL)
              AND    (PN.ATO_NUMERO = V.NUMERO_ATO OR PN.ATO_NUMERO IS NULL)
              ORDER BY I.NUMERO, PR.DATA ';
        END
        ELSE IF (:V_TODOS = 'P') THEN --Todos Ped. Certidao
        BEGIN
          V_SQL = 'SELECT DISTINCT I.NUMERO, I.NUMERO_LETRA, I.TIPO_REGISTRO,
                     V.TIPO_ATO, V.NUMERO_ATO, PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                           PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                           PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME, PR.TIPO_PROTOCOLO
              FROM   R_IMOVEL I, R_PESSOA_VINCULO V, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                           R_PROTOCOLO PR, R_PEDIDO PE
              WHERE V.IMOVEL_ID = I.IMOVEL_ID
              AND V.cpf_cnpj =  '||''''||:v_cpf_cnpj||''''||'
              AND PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    PR.TIPO_PROTOCOLO = 3
              AND    PN.TIPO_REGISTRO = I.TIPO_REGISTRO
              AND    PN.NUMERO = I.NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '||''''''||')
              AND    (PN.ATO_TIPO = V.TIPO_ATO OR PN.ATO_TIPO IS NULL)
              AND    (PN.ATO_NUMERO = V.NUMERO_ATO OR PN.ATO_NUMERO IS NULL)
              ORDER BY I.NUMERO, PR.DATA ';
        END
    end
    else
    begin
        IF (:V_TODOS = 'A') THEN --Prot. em andamento
        BEGIN
          V_SQL = 'SELECT DISTINCT I.NUMERO, I.NUMERO_LETRA, I.TIPO_REGISTRO,
                     V.TIPO_ATO, V.NUMERO_ATO, PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                           PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                           PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME, PR.TIPO_PROTOCOLO
              FROM   R_IMOVEL I, R_PESSOA_VINCULO V, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                           R_PROTOCOLO PR, R_PEDIDO PE
              WHERE V.IMOVEL_ID = I.IMOVEL_ID
              AND V.nome LIKE  '||''''||:v_nome||''''||'
              AND PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = I.TIPO_REGISTRO
              AND    PN.NUMERO = I.NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '||''''''||')
              AND    (PN.ATO_TIPO = V.TIPO_ATO OR PN.ATO_TIPO IS NULL)
              AND    (PN.ATO_NUMERO = V.NUMERO_ATO OR PN.ATO_NUMERO IS NULL)
              AND    PE.PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_PROTOCOLO_EM_ANDAMENTO )
              AND    PR.DATA > CURRENT_DATE - '||:V_QTDE_DIA||'
              ORDER BY I.NUMERO, PR.DATA ';
        END
        ELSE IF (:V_TODOS = 'T') THEN --Todos Prot. ou Exames
        BEGIN
          V_SQL = 'SELECT DISTINCT I.NUMERO, I.NUMERO_LETRA, I.TIPO_REGISTRO,
                     V.TIPO_ATO, V.NUMERO_ATO, PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                           PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                           PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME, PR.TIPO_PROTOCOLO
              FROM   R_IMOVEL I, R_PESSOA_VINCULO V, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                           R_PROTOCOLO PR, R_PEDIDO PE
              WHERE V.IMOVEL_ID = I.IMOVEL_ID
              AND V.nome LIKE  '||''''||:v_nome||''''||'
              AND PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
              AND    PN.TIPO_REGISTRO = I.TIPO_REGISTRO
              AND    PN.NUMERO = I.NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '||''''''||')
              AND    (PN.ATO_TIPO = V.TIPO_ATO OR PN.ATO_TIPO IS NULL)
              AND    (PN.ATO_NUMERO = V.NUMERO_ATO OR PN.ATO_NUMERO IS NULL)
              ORDER BY I.NUMERO, PR.DATA ';
        END
        ELSE IF (:V_TODOS = 'P') THEN --Todos Ped. Certidao
        BEGIN
          V_SQL = 'SELECT DISTINCT I.NUMERO, I.NUMERO_LETRA, I.TIPO_REGISTRO,
                     V.TIPO_ATO, V.NUMERO_ATO, PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                           PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                           PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME, PR.TIPO_PROTOCOLO
              FROM   R_IMOVEL I, R_PESSOA_VINCULO V, R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                           R_PROTOCOLO PR, R_PEDIDO PE
              WHERE V.IMOVEL_ID = I.IMOVEL_ID
              AND V.nome LIKE  '||''''||:v_nome||''''||'
              AND PE.PEDIDO_ID = PR.PEDIDO_ID
              AND    PE.PEDIDO_ID = PI.PEDIDO_ID
              AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
              AND    PR.TIPO_PROTOCOLO = 3
              AND    PN.TIPO_REGISTRO = I.TIPO_REGISTRO
              AND    PN.NUMERO = I.NUMERO
              AND    (PN.NUMERO_LETRA IS NULL OR PN.NUMERO_LETRA = '||''''''||')
              AND    (PN.ATO_TIPO = V.TIPO_ATO OR PN.ATO_TIPO IS NULL)
              AND    (PN.ATO_NUMERO = V.NUMERO_ATO OR PN.ATO_NUMERO IS NULL)
              ORDER BY I.NUMERO, PR.DATA ';
        END
    end


    FOR EXECUTE STATEMENT :V_SQL
        INTO :V_NUM, :V_NUM_LETRA, :V_REG_TIPO, :V_ATO_TIPO, :V_ATO_NUMERO,
        :PEDIDO_ID, :REGISTRO_TIPO, :NUMERO, :NUMERO_LETRA, :ATO_TIPO, :ATO_NUMERO,
               :NATUREZA_TITULO_ID,:ADQUIRENTE_NOME, :APRESENTANTE_NOME, :TIPO_PROTOCOLO  DO
    BEGIN
      SUSPEND;
    END
  END
  ELSE
  BEGIN
    IF ((:V_NUMERO_LETRA IS NULL) OR (:V_NUMERO_LETRA = '')) THEN
    BEGIN  
      if (coalesce(:V_USAR_MULT_CART,'') = 'S') then
      begin
        SELECT COUNT(*)
        FROM   R_IMOVEL I
        WHERE  I.TIPO_REGISTRO =  :V_TIPO_REGISTRO
        AND    I.NUMERO = :V_NUMERO
        AND    (I.NUMERO_LETRA IS NULL OR I.NUMERO_LETRA = '' OR I.NUMERO_LETRA = '#')
        AND    i.CARTORIO = :V_CARTORIO
        INTO V_QUANT;
      end
      else
      begin
        SELECT COUNT(*)
        FROM   R_IMOVEL I
