                     :NATUREZA_TITULO_ID, :ADQUIRENTE_NOME, :APRESENTANTE_NOME DO
                BEGIN
                  SELECT FIRST 1 PR.TIPO_PROTOCOLO FROM R_PROTOCOLO PR
                  WHERE PR.PEDIDO_ID = :PEDIDO_ID
                  ORDER BY PR.TIPO_PROTOCOLO
                  INTO :TIPO_PROTOCOLO;
                  SUSPEND;
                END
            end
          END
          ELSE IF (:V_TODOS = 'T') THEN --Todos Protocolos
          BEGIN
            if (coalesce(:V_USAR_MULT_CART,'') = 'S') then
            begin
                FOR SELECT DISTINCT PI.PEDIDO_ID, PN.TIPO_REGISTRO, PN.NUMERO, PN.NUMERO_LETRA,
                           PN.ATO_TIPO, PN.ATO_NUMERO, PI.NATUREZA_TITULO_ID,
                           PE.ADQUIRENTE_NOME, PE.APRESENTANTE_NOME
                    FROM   R_PEDIDO_ITEM PI, R_PEDIDO_ITEM_NUMERO PN,
                           R_PROTOCOLO PR, R_PEDIDO PE
                    WHERE  PE.PEDIDO_ID = PR.PEDIDO_ID
                    AND    PE.PEDIDO_ID = PI.PEDIDO_ID
                    AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
                    AND    (PR.TIPO_PROTOCOLO = 1 OR PR.TIPO_PROTOCOLO = 2)
