ALTER PROCEDURE R_PROTOCOLO_ANALITICO (V_TIPO_PROTOCOLO INTEGER,
V_NUMERO_INICIAL INTEGER,
V_NUMERO_FINAL INTEGER,
V_DATA_INICIAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (PROTOCOLO_ID INTEGER,
DATA_PROTOCOLO TIMESTAMP,
TIPO_PROTOCOLO VARCHAR(1) CHARACTER SET ISO8859_1,
NUMERO_ORDEM INTEGER,
PEDIDO_ID INTEGER,
TB_TITULO_ID INTEGER,
DESCRICAO_TITULO VARCHAR(120) CHARACTER SET ISO8859_1,
NATUREZA_TITULO_ID INTEGER,
DESCRICAO_NATUREZA VARCHAR(120) CHARACTER SET ISO8859_1,
ATOS_PRATICADOS_DETALHADO VARCHAR(10000) CHARACTER SET ISO8859_1,
ATOS_PRATICADOS VARCHAR(10000) CHARACTER SET ISO8859_1,
NUMERO_SELO VARCHAR(260) CHARACTER SET ISO8859_1,
ANDAMENTOS VARCHAR(10000) CHARACTER SET ISO8859_1,
APRESENTANTE VARCHAR(120) CHARACTER SET ISO8859_1,
ADQUIRENTE VARCHAR(120) CHARACTER SET ISO8859_1,
TRANSMITENTE VARCHAR(120) CHARACTER SET ISO8859_1,
STATUS_PROTOCOLO VARCHAR(20) CHARACTER SET ISO8859_1,
DIFERENCA_CUSTAS NUMERIC(18, 2),
TOTAL_GERAL NUMERIC(18, 2),
VALOR_COMPENSADO NUMERIC(18, 2),
CREDITO NUMERIC(18, 2),
DEBITO NUMERIC(18, 2),
QTDE_SELOS_GERADOS INTEGER,
QTDE_SELOS_NAO_GERADOS INTEGER,
STATUS_SELOS VARCHAR(20) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_SQL VARCHAR(5000);
  DECLARE VARIABLE V_DATA_ANDAMENTO TIMESTAMP;
  DECLARE VARIABLE V_DESCRICAO_ANDAMENTO VARCHAR(120);
  DECLARE VARIABLE V_COMPLEMENTO VARCHAR(120);
  DECLARE VARIABLE V_LOGIN VARCHAR(120);
  DECLARE VARIABLE V_ANDAMENTO_COMPLETO VARCHAR(500);
  DECLARE VARIABLE V_UF VARCHAR(5);
  DECLARE VARIABLE V_MODELO_ATOS VARCHAR(5);
  DECLARE VARIABLE V_SAIR_PROTOCOLO_DESCRICAO VARCHAR(120);
  DECLARE VARIABLE V_COUNT INTEGER;
  DECLARE VARIABLE V_TIPO_NA_NATUREZA VARCHAR(5);
  DECLARE VARIABLE V_TOTAL_PEDIDO NUMERIC(18,2);
BEGIN
/*  --PARAMETROS
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'CARTORIO', 'UF', 1) INTO :V_UF;
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PROTOCOLO', 'ATOS_PRATICADOS', 'MODELO', 1) INTO :V_MODELO_ATOS;
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PROTOCOLO', 'PROTOCOLO_SINTETICO', 'TIPO_NA_NATUREZA', 1) INTO :V_TIPO_NA_NATUREZA;

  V_SQL = ' SELECT PR.PROTOCOLO_ID, PR.PEDIDO_ID, PR.DATA, PR.NUMERO_ORDEM,
    PR.TIPO_PROTOCOLO, PE.TB_TITULO_ID, PE.APRESENTANTE_NOME, PE.ADQUIRENTE_NOME,
    PE.TRANSMITENTE_NOME
    FROM R_PROTOCOLO PR, R_PEDIDO PE
    WHERE PR.PEDIDO_ID = PE.PEDIDO_ID ';

  IF (COALESCE(:V_TIPO_PROTOCOLO,0) > 0) THEN
  BEGIN
    V_SQL = :V_SQL || ' AND PR.TIPO_PROTOCOLO = '||:V_TIPO_PROTOCOLO;
  END

  IF (COALESCE(:V_NUMERO_INICIAL,0) > 0) THEN
  BEGIN
    IF ((COALESCE(:V_NUMERO_FINAL,0) = 0) OR (COALESCE(:V_NUMERO_FINAL,0) < COALESCE(:V_NUMERO_INICIAL,0)))  THEN
    BEGIN
      V_NUMERO_FINAL = :V_NUMERO_INICIAL;
    END
    V_SQL = :V_SQL || ' AND PR.NUMERO_ORDEM BETWEEN '||:V_NUMERO_INICIAL||' AND '||:V_NUMERO_FINAL;
  END

  IF (COALESCE(:V_DATA_INICIAL,'') <> '') THEN
  BEGIN
    IF (COALESCE(:V_DATA_FINAL,'') = '') THEN
    BEGIN
      V_DATA_FINAL = :V_DATA_INICIAL;
    END
    V_SQL = :V_SQL || ' AND PR.DATA BETWEEN CAST('||''''||:V_DATA_INICIAL||''''||' AS TIMESTAMP)
       AND CAST('||''''||:V_DATA_FINAL||''''||' AS TIMESTAMP)+ 0.9999 ';
  END

  V_SQL = :V_SQL ||' ORDER BY PR.DATA, PR.NUMERO_ORDEM ';

  FOR EXECUTE STATEMENT :V_SQL INTO
    :PROTOCOLO_ID, :PEDIDO_ID, :DATA_PROTOCOLO, :NUMERO_ORDEM, :TIPO_PROTOCOLO, :TB_TITULO_ID,
    :APRESENTANTE, :ADQUIRENTE, :TRANSMITENTE DO
  BEGIN
    DESCRICAO_TITULO = '';
    SELECT DESCRICAO FROM R_TB_TITULO WHERE TB_TITULO_ID = :TB_TITULO_ID
    INTO :DESCRICAO_TITULO;

    SELECT FIRST 1 NATUREZA_TITULO_ID FROM R_PEDIDO_ITEM
    WHERE PEDIDO_ID = :PEDIDO_ID
    ORDER BY SEQUENCIA, PEDIDO_ITEM_ID
    INTO :NATUREZA_TITULO_ID;

    DESCRICAO_NATUREZA = '';
    SELECT DESCRICAO FROM G_NATUREZA_TITULO WHERE NATUREZA_TITULO_ID = :NATUREZA_TITULO_ID
    INTO :DESCRICAO_NATUREZA;

    V_ANDAMENTO_COMPLETO = '';
    ANDAMENTOS = '';
    FOR SELECT A.DATA, TA.DESCRICAO, A.COMPLEMENTO, U.LOGIN
        FROM R_ANDAMENTO A, R_TB_TIPO_ANDAMENTO TA, G_USUARIO U
        WHERE A.TB_TIPO_ANDAMENTO_ID = TA.TB_TIPO_ANDAMENTO_ID
        AND A.USUARIO_ID = U.USUARIO_ID
        AND A.PEDIDO_ID = :PEDIDO_ID
        ORDER BY A.DATA
    INTO :V_DATA_ANDAMENTO, :V_DESCRICAO_ANDAMENTO, :V_COMPLEMENTO, :V_LOGIN DO
    BEGIN
      IF (COALESCE(:V_COMPLEMENTO,'') <> '') THEN
      BEGIN
        V_ANDAMENTO_COMPLETO = EXTRACT(DAY FROM :V_DATA_ANDAMENTO)||'/'||
          EXTRACT(MONTH FROM :V_DATA_ANDAMENTO)||'/'||EXTRACT(YEAR FROM :V_DATA_ANDAMENTO)||' - '||
          :V_DESCRICAO_ANDAMENTO||' ('||:V_COMPLEMENTO||') - ['||:V_LOGIN||']';
      END
      ELSE
      BEGIN
        V_ANDAMENTO_COMPLETO = EXTRACT(DAY FROM :V_DATA_ANDAMENTO)||'/'||
          EXTRACT(MONTH FROM :V_DATA_ANDAMENTO)||'/'||EXTRACT(YEAR FROM :V_DATA_ANDAMENTO)||' - '||
          :V_DESCRICAO_ANDAMENTO||' - ['||:V_LOGIN||']';
      END
      IF (:ANDAMENTOS = '') THEN
      BEGIN
        ANDAMENTOS = :V_ANDAMENTO_COMPLETO;
      END
      ELSE
      BEGIN
        ANDAMENTOS = SUBSTRING((:ANDAMENTOS||ASCII_CHAR(13)||:V_ANDAMENTO_COMPLETO) FROM 1 FOR 10000);
      END
    END

    NUMERO_SELO = '';
    IF (:TIPO_PROTOCOLO = '1') THEN
    BEGIN
      IF (COALESCE(:V_UF, '') = 'DF') then
      BEGIN
        SELECT NUMERO_SELO FROM R_PROTOCOLO
        WHERE TIPO_PROTOCOLO = '1'
        AND PEDIDO_ID = :PEDIDO_ID
        INTO :NUMERO_SELO;
      END
      ELSE IF (COALESCE(:V_UF, '') = 'GO')then
      BEGIN
        SELECT FIRST 1 NUMERO_SELO FROM R_SELOS_DO_PROTOCOLO_GO(:PEDIDO_ID,'1')
        WHERE AGRUPADOR = 'T'
        INTO :NUMERO_SELO;
        IF (COALESCE(:NUMERO_SELO,'') = '') THEN
        BEGIN
          SELECT FIRST 1 NUMERO_SELO FROM R_SELOS_DO_PROTOCOLO_GO(:PEDIDO_ID,'1')
          INTO :NUMERO_SELO;
        END
      END
      ELSE IF (COALESCE(:V_UF, '') = 'TO') then
      BEGIN
        SELECT FIRST 1 NUMERO_SELO FROM R_SELOS_DO_PROTOCOLO_TO(:PEDIDO_ID,'1')
        ORDER BY PEDIDO_ITEM_ID ASC
        INTO :NUMERO_SELO;
      END
    END
    SELECT SUBSTRING(ATOS_PRATICADOS_SINTETICO FROM 1 FOR 10000), SUBSTRING(ATOS_PRATICADOS_COMPLETO FROM 1 FOR 10000)
    FROM R_ATOS_PRATICADOS(:PEDIDO_ID,:V_MODELO_ATOS,'S')
    INTO :ATOS_PRATICADOS, :ATOS_PRATICADOS_DETALHADO;

    STATUS_PROTOCOLO = '';
    --VERIFICAR SE FOI REGISTRADO
    SELECT COUNT(*)
    FROM R_TB_TIPO_ANDAMENTO TA, R_ANDAMENTO A
    WHERE TA.TB_TIPO_ANDAMENTO_ID = A.TB_TIPO_ANDAMENTO_ID
    AND   A.PEDIDO_ID = :PEDIDO_ID
    AND   TA.TIPO = 'R'
    INTO :V_COUNT;
    IF (:V_COUNT > 0) THEN
    BEGIN
      STATUS_PROTOCOLO = 'REGISTRADO';
    END

    --VERIFICAR SE FOI CANCELADO
    SELECT COUNT(*)
    FROM R_TB_TIPO_ANDAMENTO TA, R_ANDAMENTO A
    WHERE TA.TB_TIPO_ANDAMENTO_ID = A.TB_TIPO_ANDAMENTO_ID
    AND   A.PEDIDO_ID = :PEDIDO_ID
    AND   TA.TIPO = 'C'
    INTO :V_COUNT;
    IF (:V_COUNT > 0) THEN
    BEGIN
      STATUS_PROTOCOLO = 'CANCELADO';
    END

    --VERIFICAR SE DESCRICAO SERÁ MESMA DO ANDAMENTO
    V_SAIR_PROTOCOLO_DESCRICAO = '';
    IF (COALESCE(:STATUS_PROTOCOLO,'') <> 'R') THEN
    BEGIN
      SELECT FIRST 1 TA.DESCRICAO
      FROM R_TB_TIPO_ANDAMENTO TA, R_ANDAMENTO A
      WHERE TA.TB_TIPO_ANDAMENTO_ID = A.TB_TIPO_ANDAMENTO_ID
      AND   A.PEDIDO_ID = :PEDIDO_ID
      AND   TA.SAIR_PROTOCOLO = 'S'
      ORDER BY A.DATA DESC
      INTO :V_SAIR_PROTOCOLO_DESCRICAO;
    END

    --Se conter andamento para sair na descrição, verificar se já não foi registrado
    IF (COALESCE(:V_SAIR_PROTOCOLO_DESCRICAO,'') <> '') THEN
    BEGIN
      ATOS_PRATICADOS = :V_SAIR_PROTOCOLO_DESCRICAO;
    END

    --Diferença de custas
    SELECT COALESCE(TOTAL_GERAL,0), COALESCE(VALOR_COMPENSADO,0),
      COALESCE(CREDITO,0), COALESCE(DEBITO,0), COALESCE(DIFERENCA_CUSTAS,0)
    FROM R_TOTAL_PEDIDO(:PEDIDO_ID)
    INTO :TOTAL_GERAL, :VALOR_COMPENSADO, :CREDITO, :DEBITO, :DIFERENCA_CUSTAS;

    IF (COALESCE(DIFERENCA_CUSTAS,0) > 0) THEN
    BEGIN
      IF (COALESCE(DIFERENCA_CUSTAS,0) < 0.50) THEN
      BEGIN
        DIFERENCA_CUSTAS = 0;
      END
    END
    IF (COALESCE(DIFERENCA_CUSTAS,0) < 0) THEN
    BEGIN
      IF (COALESCE(DIFERENCA_CUSTAS,0) > - 0.50) THEN
      BEGIN
        DIFERENCA_CUSTAS = 0;
      END
    END

    --verificacao de selos
    QTDE_SELOS_NAO_GERADOS = 0;
    QTDE_SELOS_GERADOS = 0;
    select COUNT(*) from R_SELOS_A_SEREM_USADOS(:PEDIDO_ID, :V_UF, 'N')
    INTO :QTDE_SELOS_NAO_GERADOS;

    IF (COALESCE(:V_UF,'') = 'GO') THEN
    BEGIN
      select count(*) from R_SELOS_DO_PROTOCOLO_GO(:PEDIDO_ID, :TIPO_PROTOCOLO)
      INTO :QTDE_SELOS_GERADOS;
    END

    SUSPEND;
  END*/
END ^

ALTER PROCEDURE R_PROTOCOLO_COM_USUARIO (V_USUARIO_ID INTEGER,
V_TB_TIPO_ANDAMENTO INTEGER = 0)
RETURNS (NUMERO_ORDEM INTEGER,
STATUS VARCHAR(60) CHARACTER SET ISO8859_1,
USUARIO_QUE_ENVIOU VARCHAR(60) CHARACTER SET ISO8859_1,
USUARIO_QUE_RECEBEU VARCHAR(60) CHARACTER SET ISO8859_1,
DATA_PROTOCOLO DATE,
DATA_PREVISTA DATE,
APRESENTANTE VARCHAR(120) CHARACTER SET ISO8859_1,
VALOR_TOTAL NUMERIC(18, 2),
VALOR_PAGO NUMERIC(18, 2),
VALOR_A_RECEBER NUMERIC(18, 2),
ANDAMENTO_DESC VARCHAR(120) CHARACTER SET ISO8859_1,
ANDAMENTO_DATA DATE,
QTDE_DIAS_NO_ANDAMENTO INTEGER,
QTDE_DIAS_PROTOCOLO_FIM INTEGER,
QTDE_DIAS_PROTOCOLO_ENTREGA INTEGER,
NATUREZA_TITULO VARCHAR(260) CHARACTER SET ISO8859_1,
DATA_ENTREGA DATE,
USUARIO_COM_TITULO VARCHAR(60) CHARACTER SET ISO8859_1,
ANDAMENTO_ID INTEGER)
AS 
declare variable v_usuario_origem_id integer;
  declare variable v_usuario_destino_id integer;
  declare variable v_pedido_id integer;
  declare variable v_andamento_id integer;
  declare variable v_tb_tipo_andamento_id integer;
  declare variable v_sql varchar(5000);
  declare variable v_sql_2 varchar(5000);
  declare variable v_qtde_entregue integer;
  declare variable v_retornar varchar(3);
  declare variable v_qtde integer;
  declare variable v_status_andamento varchar(3);
  declare variable v_status_data date;
begin
  v_sql = '  select distinct pr.numero_ordem, pr.data,
               pe.data_prevista, pe.apresentante_nome, pe.pedido_id
             FROM R_PEDIDO PE, R_PROTOCOLO PR
             where pe.pedido_id = pr.pedido_id
             and pr.data > current_date - 60
             and pr.tipo_protocolo = '||''''||'1'||'''';

    v_sql = :v_sql ||' and (select count(*) from r_andamento a1, r_tb_tipo_andamento ta1
                            where a1.pedido_id = pe.pedido_id
                            and a1.tb_tipo_andamento_id = ta1.tb_tipo_andamento_id
                            and coalesce(ta1.sequencia_on_line,0) = 6) = 0 ';

  if (coalesce(:V_USUARIO_ID,0) > 0) then
  begin
    v_sql = :v_sql ||' and (select first 1 usuario_destino_id from r_andamento a2
                            where a2.pedido_id = pe.pedido_id
                            and coalesce(a2.usuario_destino_id,0) > 0
                            order by a2.andamento_id desc) = '||:V_USUARIO_ID;
  end

  if (coalesce(:V_TB_TIPO_ANDAMENTO,0) > 0) then
  begin
    v_sql = :v_sql ||' and (select first 1 tb_tipo_andamento_id from r_andamento a3
                            where a3.pedido_id = pe.pedido_id
                            and coalesce(a3.usuario_destino_id,0) > 0
                            order by a3.andamento_id desc) = '||:V_TB_TIPO_ANDAMENTO;
  end

  V_SQL = :V_SQL || ' ORDER BY PR.NUMERO_ORDEM ';


  FOR EXECUTE STATEMENT :V_SQL
  INTO :NUMERO_ORDEM, :DATA_PROTOCOLO, :DATA_PREVISTA, :APRESENTANTE, :v_pedido_id DO
  BEGIN
    data_entrega = null;

    QTDE_DIAS_PROTOCOLO_ENTREGA = 0;
    --último usuário com o título

    select first 1 u.login
    from r_andamento a, g_usuario u
    where a.usuario_destino_id = u.usuario_id
    and a.pedido_id = :v_pedido_id
    and a.usuario_destino_id > 0
    order by a.andamento_id desc
    into :usuario_com_titulo;

    v_sql_2 = ' select first 1 a.usuario_id, a.usuario_destino_id, a.data, a.tb_tipo_andamento_id, a.andamento_id,
                  u.login, ta.descricao
                from r_andamento a, g_usuario u, r_tb_tipo_andamento ta
                where a.pedido_id = '||:v_pedido_id|| '
                and a.usuario_destino_id > 0
                and a.usuario_id = u.usuario_id
                and a.tb_tipo_andamento_id = ta.tb_tipo_andamento_id ';

    if (coalesce(:V_USUARIO_ID,0) > 0) then
    begin
      v_sql_2 = :v_sql_2 ||' and a.usuario_destino_id = '||:v_usuario_id;
    end
  
    if (coalesce(:V_TB_TIPO_ANDAMENTO,0) > 0) then
    begin
      v_sql_2 = :v_sql_2 ||' and a.tb_tipo_andamento_id = '||:v_tb_tipo_andamento;
    end

    v_sql_2 = :v_sql_2 ||' order by a.andamento_id desc ';

    EXECUTE STATEMENT :V_SQL_2
    INTO :v_usuario_origem_id, :v_usuario_destino_id,
        :ANDAMENTO_DATA, :v_tb_tipo_andamento_id, :v_andamento_id,
        :USUARIO_QUE_ENVIOU, :ANDAMENTO_DESC;

    qtde_dias_no_andamento = :andamento_data - :data_protocolo;

    select login from g_usuario
    where usuario_id = :v_usuario_destino_id
    into :USUARIO_QUE_RECEBEU;

    --select total_geral, (credito - debito) from R_TOTAL_PEDIDO (:v_pedido_id)
    --into :VALOR_TOTAL, :valor_pago;

    --VALOR_A_RECEBER = :VALOR_TOTAL - :VALOR_PAGO;

    select first 1 nt.descricao from r_pedido_item pi, g_natureza_titulo nt
    where pi.natureza_titulo_id = nt.natureza_titulo_id
    and pi.pedido_id = :v_pedido_id
    order by pi.pedido_item_id
    into :NATUREZA_TITULO;

    STATUS = '';

    select status_andamento, data_andamento from R_ANDAMENTO_PROTOCOLO(:NUMERO_ORDEM)
    into :v_status_andamento, :v_status_data;

    select datediff (day, :DATA_PROTOCOLO, current_date) from rdb$database
    INTO :QTDE_DIAS_PROTOCOLO_FIM;
    if (coalesce(:v_status_andamento,'') = '1') then
    begin
      STATUS = 'EM ANÁLISE';
    end
    else if (coalesce(:v_status_andamento,'') = '2') then
    begin
      STATUS = 'EM EXIGÊNCIA';
    end
    else if (coalesce(:v_status_andamento,'') = '3') then
    begin
      STATUS = 'EM PROCESSO DE REGISTRO';
    end
    else if (coalesce(:v_status_andamento,'') = '4') then
    begin
      STATUS = 'REGISTRADO';
      QTDE_DIAS_PROTOCOLO_FIM = :v_status_data - :data_protocolo;
    end
    else if (coalesce(:v_status_andamento,'') = '5') then
    begin
      STATUS = 'CANCELADO';
      QTDE_DIAS_PROTOCOLO_FIM = :v_status_data - :data_protocolo;
    end
    else
    begin
      STATUS = '';
    end
    suspend;
  end
END ^

ALTER PROCEDURE R_PROTOCOLO_COM_USUARIO_DATA (V_USUARIO_ID INTEGER,
V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
V_TB_TIPO_ANDAMENTO INTEGER = 0)
RETURNS (NUMERO_ORDEM INTEGER,
STATUS VARCHAR(60) CHARACTER SET ISO8859_1,
USUARIO_QUE_ENVIOU VARCHAR(60) CHARACTER SET ISO8859_1,
USUARIO_QUE_RECEBEU VARCHAR(60) CHARACTER SET ISO8859_1,
DATA_PROTOCOLO DATE,
DATA_PREVISTA DATE,
APRESENTANTE VARCHAR(120) CHARACTER SET ISO8859_1,
VALOR_TOTAL NUMERIC(18, 2),
VALOR_PAGO NUMERIC(18, 2),
VALOR_A_RECEBER NUMERIC(18, 2),
ANDAMENTO_DESC VARCHAR(120) CHARACTER SET ISO8859_1,
ANDAMENTO_DATA DATE,
QTDE_DIAS_NO_ANDAMENTO INTEGER,
QTDE_DIAS_PROTOCOLO_FIM INTEGER,
QTDE_DIAS_PROTOCOLO_ENTREGA INTEGER,
NATUREZA_TITULO VARCHAR(260) CHARACTER SET ISO8859_1,
DATA_ENTREGA DATE,
USUARIO_COM_TITULO VARCHAR(60) CHARACTER SET ISO8859_1,
ANDAMENTO_ID INTEGER)
AS 
declare variable v_usuario_origem_id integer;
  declare variable v_usuario_destino_id integer;
  declare variable v_pedido_id integer;
  declare variable v_andamento_id integer;
  declare variable v_tb_tipo_andamento_id integer;
  declare variable v_sql varchar(5000);
  declare variable v_sql_2 varchar(5000);
  declare variable v_qtde_entregue integer;
  declare variable v_retornar varchar(3);
  declare variable v_qtde integer;
  declare variable v_status_andamento varchar(3);
  declare variable v_status_data date;
begin
  v_sql = '  select distinct pr.numero_ordem, pr.data,
               pe.data_prevista, pe.apresentante_nome, pe.pedido_id
             FROM R_PEDIDO PE, R_PROTOCOLO PR
             where pe.pedido_id = pr.pedido_id
             and pr.tipo_protocolo = '||''''||'1'||'''';

  if (coalesce(:V_USUARIO_ID,0) > 0) then
  begin
    v_sql = :v_sql ||' and (select count(*) from r_andamento a
                            where a.pedido_id = pe.pedido_id
                            and a.usuario_destino_id = '||:V_USUARIO_ID||') > 0 ';
  end

  if (coalesce(:V_TB_TIPO_ANDAMENTO,0) > 0) then
  begin
    v_sql = :v_sql ||' and (select count(*) from r_andamento a
                            where a.pedido_id = pe.pedido_id
                            and a.tb_tipo_andamento_id = '||:V_TB_TIPO_ANDAMENTO||') > 0 ';
  end
  v_sql = :v_sql ||' and pr.data BETWEEN CAST('||''''||:V_DATA_INI||''''||' AS TIMESTAMP) AND CAST('||''''||:V_DATA_FIM||''''||' AS TIMESTAMP) + 0.9999 ';

  V_SQL = :V_SQL || ' ORDER BY PR.NUMERO_ORDEM ';

  FOR EXECUTE STATEMENT :V_SQL
  INTO :NUMERO_ORDEM, :DATA_PROTOCOLO, :DATA_PREVISTA, :APRESENTANTE, :v_pedido_id DO
  BEGIN
    data_entrega = null;
    select first 1 a2.data from r_andamento a2, r_tb_tipo_andamento ta2
    where a2.tb_tipo_andamento_id = ta2.tb_tipo_andamento_id
    and a2.pedido_id = :v_pedido_id
    and ta2.sequencia_on_line = 6
    order by a2.andamento_id desc
    into :data_entrega;

    --verificar se foi entregue
    if (:data_entrega is null) then
    begin
      QTDE_DIAS_PROTOCOLO_ENTREGA = 0;
      --último usuário com o título

      select first 1 u.login
      from r_andamento a, g_usuario u
      where a.usuario_destino_id = u.usuario_id
      and a.pedido_id = :v_pedido_id
      and a.usuario_destino_id > 0
      order by a.andamento_id desc
      into :usuario_com_titulo;
    end
    else
    begin
      QTDE_DIAS_PROTOCOLO_ENTREGA = :data_entrega - :data_protocolo;
      USUARIO_COM_TITULO = '';
    end

    v_sql_2 = ' select first 1 a.usuario_id, a.usuario_destino_id, a.data, a.tb_tipo_andamento_id, a.andamento_id,
                  u.login, ta.descricao
                from r_andamento a, g_usuario u, r_tb_tipo_andamento ta
                where a.pedido_id = '||:v_pedido_id|| '
                and a.usuario_destino_id > 0
                and a.usuario_id = u.usuario_id
                and a.tb_tipo_andamento_id = ta.tb_tipo_andamento_id ';

    if (coalesce(:V_USUARIO_ID,0) > 0) then
    begin
      v_sql_2 = :v_sql_2 ||' and a.usuario_destino_id = '||:v_usuario_id;
    end
  
    if (coalesce(:V_TB_TIPO_ANDAMENTO,0) > 0) then
    begin
      v_sql_2 = :v_sql_2 ||' and a.tb_tipo_andamento_id = '||:v_tb_tipo_andamento;
    end

    v_sql_2 = :v_sql_2 ||' order by a.andamento_id desc ';

    EXECUTE STATEMENT :V_SQL_2
    INTO :v_usuario_origem_id, :v_usuario_destino_id,
        :ANDAMENTO_DATA, :v_tb_tipo_andamento_id, :v_andamento_id,
        :USUARIO_QUE_ENVIOU, :ANDAMENTO_DESC;

    qtde_dias_no_andamento = :andamento_data - :data_protocolo;

    select login from g_usuario
    where usuario_id = :v_usuario_destino_id
    into :USUARIO_QUE_RECEBEU;

    --select total_geral, (credito - debito) from R_TOTAL_PEDIDO (:v_pedido_id)
    --into :VALOR_TOTAL, :valor_pago;

    --VALOR_A_RECEBER = :VALOR_TOTAL - :VALOR_PAGO;

    --select first 1 nt.descricao from r_pedido_item pi, g_natureza_titulo nt
    --where pi.natureza_titulo_id = nt.natureza_titulo_id
    --and pi.pedido_id = :v_pedido_id
    --order by pi.pedido_item_id
    --into :NATUREZA_TITULO;

    STATUS = '';

    select status_andamento, data_andamento from R_ANDAMENTO_PROTOCOLO(:NUMERO_ORDEM)
    into :v_status_andamento, :v_status_data;

    select datediff (day, :DATA_PROTOCOLO, current_date) from rdb$database
    INTO :QTDE_DIAS_PROTOCOLO_FIM;
    if (coalesce(:v_status_andamento,'') = '1') then
    begin
      STATUS = 'EM ANÁLISE';
    end
    else if (coalesce(:v_status_andamento,'') = '2') then
    begin
      STATUS = 'EM EXIGÊNCIA';
    end
    else if (coalesce(:v_status_andamento,'') = '3') then
    begin
      STATUS = 'EM PROCESSO DE REGISTRO';
    end
    else if (coalesce(:v_status_andamento,'') = '4') then
    begin
      STATUS = 'REGISTRADO';
      QTDE_DIAS_PROTOCOLO_FIM = :v_status_data - :data_protocolo;
    end
    else if (coalesce(:v_status_andamento,'') = '5') then
    begin
      STATUS = 'CANCELADO';
      QTDE_DIAS_PROTOCOLO_FIM = :v_status_data - :data_protocolo;
    end
    else
    begin
      STATUS = '';
    end
    suspend;
  end
END ^

ALTER PROCEDURE R_PROTOCOLO_OU_EXAME_VINCULADO (V_PEDIDO_ID VARCHAR(15) CHARACTER SET ISO8859_1,
V_TIPO_PROTOCOLO VARCHAR(5) CHARACTER SET ISO8859_1)
RETURNS (PROTOCOLO_OU_EXAME NUMERIC(12, 2))
AS 
BEGIN
  SELECT NUMERO_ORDEM
  FROM R_PROTOCOLO
  WHERE PEDIDO_ID = :V_PEDIDO_ID
  AND TIPO_PROTOCOLO <> :V_TIPO_PROTOCOLO
  INTO :PROTOCOLO_OU_EXAME;
  SUSPEND;
END ^

ALTER PROCEDURE R_PROTOCOLO_PENDENTE (V_TIPO_PESQUISA VARCHAR(3) CHARACTER SET ISO8859_1,
V_DATA_INICIAL VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FINAL VARCHAR(15) CHARACTER SET ISO8859_1)
RETURNS (PROTOCOLO_ID INTEGER,
PEDIDO_ID INTEGER,
DATA_PROTOCOLO TIMESTAMP,
NUMERO_ORDEM INTEGER,
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
ADQUIRENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
ORIGEM_PEDIDO VARCHAR(1) CHARACTER SET ISO8859_1,
TIPO_ORIGEM_SITE VARCHAR(3) CHARACTER SET ISO8859_1,
QUANTIDADE INTEGER,
TOTAL_EMOLUMENTO NUMERIC(18, 2),
TOTAL_FUNDO_RI NUMERIC(18, 2),
TOTAL_TAXA_JUDICIARIA NUMERIC(18, 2),
TOTAL_ISS NUMERIC(18, 2),
TOTAL_GERAL NUMERIC(18, 2),
VALOR_PAGO NUMERIC(18, 2),
VALOR_A_RECEBER NUMERIC(18, 2),
QTDE_DIAS_APOS_PROTOCOLAR INTEGER,
QTDE_DIAS_UTEIS_APOS_PROT INTEGER,
QTDE_DIAS_UTEIS_ATE_EXIGENCIA INTEGER,
QTDE_EXIGENCIA INTEGER,
QTDE_REENTRADA INTEGER,
POSSUI_EXIGENCIA VARCHAR(3) CHARACTER SET ISO8859_1,
POSSUI_REENTRADA VARCHAR(3) CHARACTER SET ISO8859_1,
DATA_ULTIMA_EXIGENCIA TIMESTAMP,
DATA_ULTIMA_REENTRADA TIMESTAMP,
ULTIMO_ANDAMENTO VARCHAR(120) CHARACTER SET ISO8859_1,
DATA_ULTIMO_ANDAMENTO TIMESTAMP,
DESCRICAO_TITULO VARCHAR(120) CHARACTER SET ISO8859_1,
STATUS_PRAZO VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
declare variable V_UF VARCHAR(10);
declare variable V_TB_TITULO_ID INTEGER;
declare variable V_DATA_TEMP DATE;
declare variable V_EH_DIA_UTIL VARCHAR(3);
declare variable V_PERIODO_PADRAO VARCHAR(10);
DECLARE VARIABLE V_SQL VARCHAR(5000);
declare variable V_PRAZO INTEGER;

--DECLARE VARIABLE D_TIPO_PROTOCOLO VARCHAR(1);
--DECLARE VARIABLE D_ULTIMO_PROTOCOLO_ID INTEGER;
--DECLARE VARIABLE D_TIPO_COBRANCA VARCHAR(1);
--DECLARE VARIABLE D_PEDIDO VARCHAR(15);
--DECLARE VARIABLE D_RETORNAR_REGISTRO VARCHAR(1);
--DECLARE VARIABLE D_QTDE_ANDAMENTO INTEGER;
--DECLARE VARIABLE D_PEDIDO_ITEM_ID INTEGER;
--DECLARE VARIABLE D_QTDE_MATRICULA INTEGER;
--DECLARE VARIABLE D_QTDE_PEDIDO_ITEM INTEGER;
--declare variable V_NOVO_PEDIDO_ID INTEGER;
--declare variable V_CREDITO NUMERIC(18,2);
--declare variable V_QTDE_TEMP INTEGER;
--declare variable V_DATA_PROTOCOLO DATE;
--declare variable V_DATA_MEDIA DATE;
--declare variable V_ULTIMO_ANDAMENTO_ID INTEGER;
--declare variable V_DATA_ULTIMO_ANDAMENTO DATE;

--declare variable V_REG_AVERB VARCHAR(3);
BEGIN
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL','CARTORIO','UF',1)
  INTO :V_UF;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PEDIDO','ITENS DO PEDIDO','PERIODO_PADRAO',1)
  INTO :V_PERIODO_PADRAO;

  V_SQL = ' SELECT DISTINCT PR.PROTOCOLO_ID, PE.PEDIDO_ID, PR.DATA,
               PR.NUMERO_ORDEM, PE.APRESENTANTE_NOME, PE.ADQUIRENTE_NOME,
               PE.ORIGEM_PEDIDO, PE.TIPO_ORIGEM_SITE, PE.tb_titulo_id,
               (CURRENT_DATE - CAST(PR.DATA AS DATE))
        FROM   R_PROTOCOLO PR, R_PEDIDO PE
        WHERE  PR.PEDIDO_ID = PE.PEDIDO_ID
        AND    PR.TIPO_PROTOCOLO = '||''''||'1'||''''||'
        AND NOT EXISTS (SELECT FIRST 1 A.PEDIDO_ID FROM R_ANDAMENTO A,
                                        R_TB_TIPO_ANDAMENTO T
                      WHERE A.TB_TIPO_ANDAMENTO_ID = T.TB_TIPO_ANDAMENTO_ID
                      AND A.PEDIDO_ID = PR.PEDIDO_ID
                      AND (T.TIPO = '||''''||'R'||''''||' OR T.TIPO = '||''''||'C'||''''||')) ';

  IF ((COALESCE(:V_DATA_INICIAL,'') <> '') and (COALESCE(:V_DATA_FINAL,'') <> '')) THEN --Pela Data do Protocolo
  BEGIN
    V_SQL = :V_SQL || ' AND PR.DATA BETWEEN CAST('||''''||:V_DATA_INICIAL||''''||' AS TIMESTAMP)
                                        AND CAST('||''''||:V_DATA_FINAL||''''||' AS TIMESTAMP) + 0.99999 ';
  END
  ELSE --TODOS
  BEGIN
    V_SQL = :V_SQL || ' AND PR.DATA > CURRENT_DATE - 1800 ' ;
  END

  V_SQL = :V_SQL || ' ORDER BY PR.PROTOCOLO_ID ';

  FOR EXECUTE STATEMENT V_SQL
  INTO :PROTOCOLO_ID, :PEDIDO_ID, :DATA_PROTOCOLO, :NUMERO_ORDEM,
    :APRESENTANTE_NOME, :ADQUIRENTE_NOME, :ORIGEM_PEDIDO, :TIPO_ORIGEM_SITE,
    :V_TB_TITULO_ID, :QTDE_DIAS_APOS_PROTOCOLAR DO
  BEGIN
    if (COALESCE(:ORIGEM_PEDIDO,'') = '') then
    BEGIN
      ORIGEM_PEDIDO = '1'; --BALCAO
    END
    STATUS_PRAZO = '2';--em analise

    SELECT SUM(COALESCE(PI.valor_emolumento,0)), SUM(COALESCE(PI.valor_fundo_ri,0)),
      SUM(COALESCE(PI.valor_taxa_judiciaria,0)), SUM(COALESCE(PI.valor_iss,0)), SUM(COALESCE(PI.quantidade,0))
    FROM R_PEDIDO_ITEM PI
    WHERE PI.pedido_id = :PEDIDO_ID
    INTO :total_emolumento, :total_fundo_ri, :total_taxa_judiciaria, :total_iss, :quantidade;

    TOTAL_GERAL = COALESCE(:total_emolumento,0) + COALESCE(:total_fundo_ri,0) +
      COALESCE(:total_taxa_judiciaria,0) + COALESCE(:total_iss,0);

    SELECT COALESCE(CREDITO,0) - COALESCE(DEBITO,0)
    FROM R_TOTAL_PEDIDO(:PEDIDO_ID, :V_PERIODO_PADRAO, :V_UF)
    INTO :VALOR_PAGO;
    VALOR_A_RECEBER = :TOTAL_GERAL - :VALOR_PAGO;

    V_DATA_TEMP = CAST(:DATA_PROTOCOLO AS DATE);
    QTDE_DIAS_UTEIS_APOS_PROT = 0;

    WHILE (:V_DATA_TEMP < CURRENT_DATE) DO
    BEGIN
      V_DATA_TEMP = :V_DATA_TEMP + 1;
      SELECT EH_DIA_UTIL FROM R_DIA_UTIL(:V_DATA_TEMP)
      INTO :V_EH_DIA_UTIL;

      if (:V_EH_DIA_UTIL = 'S') then
      begin
        QTDE_DIAS_UTEIS_APOS_PROT = :QTDE_DIAS_UTEIS_APOS_PROT + 1;
      end
    END

    DATA_ULTIMA_EXIGENCIA = NULL;
    select count(*) from r_pedido pe, r_andamento a, r_tb_tipo_andamento ta
    where pe.pedido_id = a.pedido_id
    and a.tb_tipo_andamento_id = ta.tb_tipo_andamento_id
    and pe.pedido_id = :pedido_id
    and ta.tipo = 'X' --exisgencia
    into :QTDE_EXIGENCIA;
    if (:QTDE_EXIGENCIA > 0) then
    begin
      POSSUI_EXIGENCIA = 'S';

      select first 1 a.data from r_pedido pe, r_andamento a, r_tb_tipo_andamento ta
      where pe.pedido_id = a.pedido_id
      and a.tb_tipo_andamento_id = ta.tb_tipo_andamento_id
      and pe.pedido_id = :pedido_id
      and ta.tipo = 'X' --exisgencia
      order by a.andamento_id desc
      into :DATA_ULTIMA_EXIGENCIA;
    end
    else
    begin
      POSSUI_EXIGENCIA = 'N';
    end

    DATA_ULTIMA_REENTRADA = null;
    select count(*) from r_pedido pe, r_andamento a, r_tb_tipo_andamento ta
    where pe.pedido_id = a.pedido_id
    and a.tb_tipo_andamento_id = ta.tb_tipo_andamento_id
    and pe.pedido_id = :pedido_id
    and ta.tipo = 'D' --reentrada
    into :QTDE_REENTRADA;
    if (:QTDE_REENTRADA > 0) then
    begin
      POSSUI_REENTRADA = 'S';

      select first 1 a.data from r_pedido pe, r_andamento a, r_tb_tipo_andamento ta
      where pe.pedido_id = a.pedido_id
      and a.tb_tipo_andamento_id = ta.tb_tipo_andamento_id
      and pe.pedido_id = :pedido_id
      and ta.tipo = 'D' --reentrada
      order by a.andamento_id desc
      into :DATA_ULTIMA_REENTRADA;
    end
    else
    begin
      POSSUI_REENTRADA = 'N';
    end

    if ((:POSSUI_EXIGENCIA = 'S') AND (:POSSUI_REENTRADA = 'N')) then
    begin
      STATUS_PRAZO = '3';--em exigencia
    end
    else if ((:POSSUI_EXIGENCIA = 'S') AND (:POSSUI_REENTRADA = 'S')) then
    begin
      if (:DATA_ULTIMA_REENTRADA > :DATA_ULTIMA_EXIGENCIA) then
      begin
        STATUS_PRAZO = '2';--em analise
      end
      else
      begin
        STATUS_PRAZO = '3';--em exigencia
      end
    end
    else
    begin
      STATUS_PRAZO = '2';--em analise
    end

    --verificar se está em atraso
    if (:STATUS_PRAZO = '2') then
    begin
      select first 1 coalesce(nt.prazo,0) from r_pedido_item pi, g_natureza_titulo nt
      where pi.natureza_titulo_id = nt.natureza_titulo_id
      and pi.pedido_id = :pedido_id
      and nt.tipo_titulo <> '8' --busca
      and nt.tipo_titulo <> '12' --prenotação
      order by pi.pedido_item_id
      into :V_PRAZO;

      if (:POSSUI_REENTRADA = 'S') then
      begin
        if (:v_prazo < (current_date - :DATA_ULTIMA_REENTRADA)) then
        begin
          STATUS_PRAZO = '4';--em atraso
        end
      end
      else
      begin
        if (:QTDE_DIAS_UTEIS_APOS_PROT > :v_prazo) then
        begin
          STATUS_PRAZO = '4';--em atraso
        end
      end
    end

    --ULTIMO ANDAMENTO
    SELECT FIRST 1 ta.descricao, a.data
    FROM R_ANDAMENTO A, r_tb_tipo_andamento TA
    WHERE A.tb_tipo_andamento_id = TA.tb_tipo_andamento_id
    AND A.pedido_id = :PEDIDO_ID
    ORDER BY A.andamento_id DESC
    INTO :ULTIMO_ANDAMENTO, :DATA_ULTIMO_ANDAMENTO;


    select descricao from r_tb_titulo
    where tb_titulo_id = :V_TB_TITULO_ID
    into :DESCRICAO_TITULO;

    if ((:V_TIPO_PESQUISA = :STATUS_PRAZO) or
       (:V_TIPO_PESQUISA = '1')) then
    begin
      SUSPEND;
    end
  END
END ^

ALTER PROCEDURE R_PROTOCOLO_POR_ANDAMENTO_DATA (V_DATA_INI VARCHAR(15) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(15) CHARACTER SET ISO8859_1,
V_TB_TIPO_ANDAMENTO_ID VARCHAR(10) CHARACTER SET ISO8859_1)
RETURNS (NUMERO_ORDEM NUMERIC(18, 2),
DATA TIMESTAMP,
TB_TITULO_ID NUMERIC(18, 2),
APRESENTANTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
ADQUIRENTE_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
ATOS_PRATICADOS VARCHAR(200) CHARACTER SET ISO8859_1,
PEDIDO_ID NUMERIC(18, 2),
DESCRICAO_TITULO VARCHAR(60) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE VSQL VARCHAR(2000);
BEGIN
  VSQL = 'SELECT PR.NUMERO_ORDEM,
                 A.DATA,
                 PE.TB_TITULO_ID,
                 PE.APRESENTANTE_NOME,
                 PE.ADQUIRENTE_NOME,
                 (SELECT MATRICULAS FROM R_MATRICULAS_DO_PEDIDO(PE.PEDIDO_ID)) AS ATOS_PRATICADOS,
                 PE.PEDIDO_ID,
                 T.DESCRICAO
          FROM   R_ANDAMENTO A,
                 R_PROTOCOLO PR,
                 R_PEDIDO PE LEFT JOIN R_TB_TITULO T
                 ON PE.TB_TITULO_ID = T.TB_TITULO_ID
          WHERE  A.PEDIDO_ID = PE.PEDIDO_ID
          AND    PE.PEDIDO_ID = PR.PEDIDO_ID
          AND    A.DATA BETWEEN CAST('||:V_DATA_INI ||' AS TIMESTAMP)
                            AND CAST('||:V_DATA_FIM ||' AS TIMESTAMP)+ 0.9999
          AND    A.TB_TIPO_ANDAMENTO_ID = '||:V_TB_TIPO_ANDAMENTO_ID||
          ' ORDER BY A.DATA, PR.NUMERO_ORDEM ';

  FOR EXECUTE STATEMENT VSQL
      INTO :NUMERO_ORDEM, :DATA, :TB_TITULO_ID, :APRESENTANTE_NOME,
           :ADQUIRENTE_NOME, :ATOS_PRATICADOS, :PEDIDO_ID, :DESCRICAO_TITULO DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_QUANTIDADE_ATOS_MATRICULAS (MATRICULA_INI INTEGER,
MATRICULA_FIM INTEGER)
RETURNS (MATRICULA INTEGER,
QTDE_ATOS INTEGER)
AS 
DECLARE VARIABLE V_IMOVEL_ID INTEGER;
BEGIN  
  FOR SELECT IMOVEL_ID, NUMERO FROM R_IMOVEL
      WHERE NUMERO BETWEEN :MATRICULA_INI AND :MATRICULA_FIM
      AND TIPO_REGISTRO = 'M'
      ORDER BY NUMERO
      INTO :V_IMOVEL_ID, :MATRICULA DO
  BEGIN    
    SELECT MAX(NUMERO_ATO) FROM R_PESSOA_VINCULO
    WHERE IMOVEL_ID = :V_IMOVEL_ID
    INTO :QTDE_ATOS;
    QTDE_ATOS = COALESCE(:QTDE_ATOS,0);
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_REGISTRO_ANTERIOR (V_CARTORIO VARCHAR(5) CHARACTER SET ISO8859_1,
V_TIPO_REGISTRO VARCHAR(5) CHARACTER SET ISO8859_1,
V_NUMERO_REGISTRO VARCHAR(10) CHARACTER SET ISO8859_1)
RETURNS (NUMERO INTEGER)
AS 
DECLARE VARIABLE VSQL VARCHAR(2000);
DECLARE VARIABLE VNUMERO_IMOVEL INTEGER;
DECLARE VARIABLE VNUMERO_INDEXADO INTEGER;
BEGIN
  IF ((:V_CARTORIO = '') OR (:V_CARTORIO = '''') OR (:V_CARTORIO IS NULL)) THEN
  BEGIN
    SELECT MAX(NUMERO) FROM R_IMOVEL
    WHERE NUMERO < :V_NUMERO_REGISTRO
    AND TIPO_REGISTRO = :V_TIPO_REGISTRO
    INTO :VNUMERO_IMOVEL;
  END
  ELSE
  BEGIN
    SELECT MAX(NUMERO) FROM R_IMOVEL
    WHERE NUMERO < :V_NUMERO_REGISTRO
    AND TIPO_REGISTRO = :V_TIPO_REGISTRO
    AND CARTORIO = :V_CARTORIO
    INTO :VNUMERO_IMOVEL;
  END
  SELECT MAX(NUMERO) FROM G_INDEXACAO
  WHERE NUMERO < :V_NUMERO_REGISTRO
  AND TIPO = :V_TIPO_REGISTRO
  AND LIVRO_OU_TALAO = 'F'
  INTO :VNUMERO_INDEXADO;

  IF ((:VNUMERO_INDEXADO IS NULL) OR ((:VNUMERO_INDEXADO - CAST(:V_NUMERO_REGISTRO AS INTEGER)) < (:VNUMERO_IMOVEL - CAST(:V_NUMERO_REGISTRO AS INTEGER)))) THEN
  BEGIN
    NUMERO = :VNUMERO_IMOVEL;
  END
  ELSE
  BEGIN
    NUMERO = :VNUMERO_INDEXADO;
  END
  SUSPEND;
END ^

