ALTER PROCEDURE R_RESULTADO_CERT_PROPRIEDADE (V_CPF_CNPJ VARCHAR(20) CHARACTER SET ISO8859_1,
V_CPF_CNPJ_CONJUGE VARCHAR(20) CHARACTER SET ISO8859_1,
V_NOME VARCHAR(120) CHARACTER SET ISO8859_1,
V_NOME_SOLTEIRO VARCHAR(120) CHARACTER SET ISO8859_1,
V_NOME_CONJUGE VARCHAR(120) CHARACTER SET ISO8859_1,
V_NOME_SOLTEIRO_CONJUGE VARCHAR(120) CHARACTER SET ISO8859_1,
V_RETORNAR_NOME_IGUAL_CPF_DIF VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (RESULTADO VARCHAR(1) CHARACTER SET ISO8859_1,
CPF_CNPJ_POSITIVAS VARCHAR(100) CHARACTER SET ISO8859_1,
NOME_POSITIVAS VARCHAR(120) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_QTDE INTEGER;
DECLARE VARIABLE V_QTDE_TOTAL INTEGER;
BEGIN
  V_QTDE_TOTAL = 0;  
  CPF_CNPJ_POSITIVAS = '';
  NOME_POSITIVAS = '';
  IF (:V_CPF_CNPJ IS NOT NULL) THEN
  BEGIN  
    SELECT COUNT(*)
    FROM R_IMOVEL I, R_PESSOA_VINCULO V
    WHERE I.IMOVEL_ID = V.IMOVEL_ID
    AND I.TIPO_REGISTRO = 'M'
    AND V.CPF_CNPJ = :V_CPF_CNPJ
    INTO :V_QTDE;
    V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
    IF (:V_QTDE > 0) THEN
    BEGIN
      IF (:CPF_CNPJ_POSITIVAS = '') THEN
      BEGIN
        CPF_CNPJ_POSITIVAS = :V_CPF_CNPJ;
      END
      ELSE
      BEGIN
        CPF_CNPJ_POSITIVAS = :CPF_CNPJ_POSITIVAS ||'; '||:V_CPF_CNPJ;
      END
    END        
  END
  
  IF (:V_CPF_CNPJ_CONJUGE IS NOT NULL) THEN
  BEGIN  
    SELECT COUNT(*) 
    FROM R_IMOVEL I, R_PESSOA_VINCULO V
    WHERE I.IMOVEL_ID = V.IMOVEL_ID
    AND I.TIPO_REGISTRO = 'M'
    AND V.CPF_CNPJ = :V_CPF_CNPJ_CONJUGE
    INTO :V_QTDE;
    V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
    IF (:V_QTDE > 0) THEN
    BEGIN
      IF (:CPF_CNPJ_POSITIVAS = '') THEN
      BEGIN
        CPF_CNPJ_POSITIVAS = :V_CPF_CNPJ_CONJUGE;
      END
      ELSE
      BEGIN
        CPF_CNPJ_POSITIVAS = :CPF_CNPJ_POSITIVAS ||'; '||:V_CPF_CNPJ_CONJUGE;
      END
    END        
  END
  
  IF (V_QTDE_TOTAL > 0) THEN
  BEGIN
    RESULTADO = 'P';
    SUSPEND;    
  END
  ELSE
  BEGIN
    IF (:V_NOME IS NOT NULL) THEN
    BEGIN      
      SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
      WHERE I.IMOVEL_ID = V.IMOVEL_ID
      AND I.TIPO_REGISTRO = 'M'
      AND V.NOME = :V_NOME
      INTO :V_QTDE;
      IF (:V_QTDE > 0) THEN
      BEGIN
        IF (:V_CPF_CNPJ IS NULL) THEN
        BEGIN
          V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
          NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME;
        END
        ELSE IF (:V_RETORNAR_NOME_IGUAL_CPF_DIF = 'S') THEN
        BEGIN
          V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
          NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME;
        END
        ELSE
        BEGIN
          SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
          WHERE I.IMOVEL_ID = V.IMOVEL_ID
          AND I.TIPO_REGISTRO = 'M'
          AND V.NOME = :V_NOME
          AND (V.CPF_CNPJ IS NULL OR V.CPF_CNPJ = '')
          INTO :V_QTDE;    
          IF (:V_QTDE > 0) THEN
          BEGIN
            V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
            NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME;          
          END                 
        END
      END
    END
    IF (:V_NOME_SOLTEIRO IS NOT NULL) THEN
    BEGIN      
      SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
      WHERE I.IMOVEL_ID = V.IMOVEL_ID
      AND I.TIPO_REGISTRO = 'M'
      AND V.NOME = :V_NOME_SOLTEIRO
      INTO :V_QTDE;
      IF (:V_QTDE > 0) THEN
      BEGIN
        IF (:V_CPF_CNPJ IS NULL) THEN
        BEGIN
          V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
          NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME_SOLTEIRO;
        END
        ELSE IF (:V_RETORNAR_NOME_IGUAL_CPF_DIF = 'S') THEN
        BEGIN
          V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
          NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME_SOLTEIRO;
        END
        ELSE
        BEGIN
          SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
          WHERE I.IMOVEL_ID = V.IMOVEL_ID
          AND I.TIPO_REGISTRO = 'M'
          AND V.NOME = :V_NOME_SOLTEIRO
          AND (V.CPF_CNPJ IS NULL OR V.CPF_CNPJ = '')
          INTO :V_QTDE;    
          IF (:V_QTDE > 0) THEN
          BEGIN
            V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
            NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME_SOLTEIRO;          
          END                 
        END
      END
    END    
    IF (:V_NOME_CONJUGE IS NOT NULL) THEN
    BEGIN      
      SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
      WHERE I.IMOVEL_ID = V.IMOVEL_ID
      AND I.TIPO_REGISTRO = 'M'
      AND V.NOME = :V_NOME_CONJUGE
      INTO :V_QTDE;
      IF (:V_QTDE > 0) THEN
      BEGIN
        IF (:V_CPF_CNPJ_CONJUGE IS NULL) THEN
        BEGIN
          V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
          NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME_CONJUGE;
        END
        ELSE IF (:V_RETORNAR_NOME_IGUAL_CPF_DIF = 'S') THEN
        BEGIN
          V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
          NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME_CONJUGE;
        END
        ELSE
        BEGIN
          SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
          WHERE I.IMOVEL_ID = V.IMOVEL_ID
          AND I.TIPO_REGISTRO = 'M'
          AND V.NOME = :V_NOME_CONJUGE
          AND (V.CPF_CNPJ IS NULL OR V.CPF_CNPJ = '')
          INTO :V_QTDE;    
          IF (:V_QTDE > 0) THEN
          BEGIN
            V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
            NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME_CONJUGE;          
          END                 
        END
      END
    END    
    IF (:V_NOME_SOLTEIRO_CONJUGE IS NOT NULL) THEN
    BEGIN      
      SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
      WHERE I.IMOVEL_ID = V.IMOVEL_ID
      AND I.TIPO_REGISTRO = 'M'
      AND V.NOME = :V_NOME_SOLTEIRO_CONJUGE
      INTO :V_QTDE;
      IF (:V_QTDE > 0) THEN
      BEGIN
        IF (:V_CPF_CNPJ_CONJUGE IS NULL) THEN
        BEGIN
          V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
          NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME_SOLTEIRO_CONJUGE;
        END
        ELSE IF (:V_RETORNAR_NOME_IGUAL_CPF_DIF = 'S') THEN
        BEGIN
          V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
          NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME_SOLTEIRO_CONJUGE;
        END
        ELSE
        BEGIN
          SELECT COUNT(*) FROM R_IMOVEL I, R_PESSOA_VINCULO V
          WHERE I.IMOVEL_ID = V.IMOVEL_ID
          AND I.TIPO_REGISTRO = 'M'
          AND V.NOME = :V_NOME_SOLTEIRO_CONJUGE
          AND (V.CPF_CNPJ IS NULL OR V.CPF_CNPJ = '')
          INTO :V_QTDE;    
          IF (:V_QTDE > 0) THEN
          BEGIN
            V_QTDE_TOTAL = :V_QTDE_TOTAL + :V_QTDE;
            NOME_POSITIVAS = :NOME_POSITIVAS ||'; '||:V_NOME_SOLTEIRO_CONJUGE;          
          END                 
        END
      END
    END    
    
    IF (V_QTDE_TOTAL > 0) THEN
    BEGIN
      RESULTADO = 'P';
    END
    ELSE
    BEGIN
      RESULTADO = 'N';
    END
    SUSPEND;    
  END  
END ^

ALTER PROCEDURE R_SECRETARIA_FAZENDA (V_DATA_INI VARCHAR(20) CHARACTER SET ISO8859_1,
V_DATA_FIM VARCHAR(20) CHARACTER SET ISO8859_1,
V_TIPO_ANDAMENTO_SEF VARCHAR(10) CHARACTER SET ISO8859_1)
RETURNS (DATA TIMESTAMP,
CODIGO_NATUREZA_SEF NUMERIC(18, 2),
NUMERO NUMERIC(18, 2),
VALOR_DOCUMENTO NUMERIC(18, 4),
ATO_NUMERO NUMERIC(18, 2),
GUIA_TIPO VARCHAR(1) CHARACTER SET ISO8859_1,
GUIA_NUMERO VARCHAR(30) CHARACTER SET ISO8859_1,
CEP NUMERIC(18, 2),
IMOVEL_ID NUMERIC(18, 2),
INSCRICAO_IMOVEL VARCHAR(60) CHARACTER SET ISO8859_1,
TIPO_CLASSE VARCHAR(1) CHARACTER SET ISO8859_1,
PEDIDO_ID NUMERIC(18, 2),
CARTORIO VARCHAR(3) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE VSQL VARCHAR(2000);
BEGIN
  FOR SELECT A.DATA, N.CODIGO_NATUREZA_SEF, PN.NUMERO,
             PI.VALOR_DOCUMENTO, PN.ATO_NUMERO, PN.GUIA_TIPO,
             PN.GUIA_NUMERO, I.CEP, I.IMOVEL_ID, I.INSCRICAO_IMOVEL,
             I.TIPO_CLASSE, PI.PEDIDO_ID, I.CARTORIO
  FROM R_ANDAMENTO A, R_PEDIDO_ITEM PI,
       R_PEDIDO_ITEM_NUMERO PN,
       R_IMOVEL I, G_NATUREZA_TITULO N
  WHERE  A.PEDIDO_ID = PI.PEDIDO_ID
  AND    PI.PEDIDO_ITEM_ID = PN.PEDIDO_ITEM_ID
  AND    PN.NUMERO = I.NUMERO
  AND    (PN.TIPO_REGISTRO = I.TIPO_REGISTRO OR PN.TIPO_REGISTRO IS NULL)
  AND    (PN.CARTORIO = I.CARTORIO OR PN.CARTORIO IS NULL)
  AND    PN.TIPO_REGISTRO = I.TIPO_REGISTRO
  AND    PI.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID
  AND    A.TB_TIPO_ANDAMENTO_ID = :V_TIPO_ANDAMENTO_SEF
  AND    PN.TIPO_REGISTRO = 'M'
  AND    N.CODIGO_NATUREZA_SEF > 0
  AND    A.DATA BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)
                    AND CAST(:V_DATA_FIM AS TIMESTAMP)+ 0.9999
  ORDER BY CAST(A.DATA AS DATE), I.TIPO_REGISTRO, I.NUMERO 
  INTO :DATA, :CODIGO_NATUREZA_SEF, :NUMERO,
       :VALOR_DOCUMENTO, :ATO_NUMERO, :GUIA_TIPO,
       :GUIA_NUMERO, :CEP, :IMOVEL_ID, :INSCRICAO_IMOVEL,
       :TIPO_CLASSE, :PEDIDO_ID, :CARTORIO DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE R_SELAR_PEDIDO_CERTIDAO_GO (V_PEDIDO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_USUARIO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_IP_MAQUINA VARCHAR(30) CHARACTER SET ISO8859_1,
V_PERIODO_PADRAO INTEGER)
RETURNS (STATUS VARCHAR(1) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_PEDIDO_ITEM_ID INTEGER;
  DECLARE VARIABLE V_PEDIDO_ITEM_NUMERO_ID INTEGER;
  DECLARE VARIABLE V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO INTEGER;
  DECLARE VARIABLE V_QUANTIDADE INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_ATOS_ACRESCIDOS INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_ATOS_ACRESC_COMP INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_QUESITOS INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_QUESITOS_COMP INTEGER;
  DECLARE VARIABLE V_SELO_GRUPO_ID INTEGER;
  DECLARE VARIABLE V_APRESENTANTE_NOME VARCHAR(120);
  DECLARE VARIABLE V_EMOLUMENTO_ID INTEGER;
  DECLARE VARIABLE V_EMOLUMENTO_ID_ATOS_ACRESCIDOS INTEGER;
  DECLARE VARIABLE V_EMOLUMENTO_ID_ATOS_ACRESC_COMP INTEGER;
  DECLARE VARIABLE V_EMOLUMENTO_ID_QUESITOS INTEGER;
  DECLARE VARIABLE V_EMOLUMENTO_ID_QUESITOS_COMP INTEGER;
  DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_TEMP NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_BASE NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_QUESITOS NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_QUESITOS_COMP NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_FUNDO_RI NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_ISS NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_TOTAL NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_DESCONTO NUMERIC(18,4);
  DECLARE VARIABLE V_PORCENTAGEM_DESCONTO NUMERIC(18,4);
  DECLARE VARIABLE V_TIPO_TITULO VARCHAR(60);
  DECLARE VARIABLE V_COUNT INTEGER;
  DECLARE VARIABLE V_NUMERO_GRUPO INTEGER;
  DECLARE VARIABLE V_DESCRICAO_GRUPO VARCHAR(260);
  DECLARE VARIABLE V_DESCRICAO_EMOLUMENTO VARCHAR(260);
  DECLARE VARIABLE V_SELO_LIVRO_ID INTEGER;
  DECLARE VARIABLE V_NUMERO_AGRUPADOR_PED_CERTIDAO VARCHAR(50);
  DECLARE VARIABLE I INTEGER;
  DECLARE VARIABLE J INTEGER;
  DECLARE VARIABLE V_ENVIOU_TAXA CHAR(1);
  DECLARE VARIABLE V_TAMANHO INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_EMITIDA INTEGER;
  DECLARE VARIABLE V_DESCRICAO_SELO VARCHAR(260);
  DECLARE VARIABLE V_EMOLUMENTO_PERIODO_ID INTEGER;
  
  DECLARE VARIABLE V_SELO_GRUPO_ID_ATOS_ACRESCIDOS INTEGER;
  DECLARE VARIABLE V_VALOR_ATOS_ACRESCIDOS NUMERIC(14,2);
  
  DECLARE VARIABLE V_SELO_GRUPO_ID_ATOS_ACRESC_COMP INTEGER;
  DECLARE VARIABLE V_VALOR_ATOS_ACRESC_COMP NUMERIC(14,2);
  
  DECLARE VARIABLE V_SELO_GRUPO_ID_QUESITOS INTEGER;
  DECLARE VARIABLE V_VALOR_QUESITOS NUMERIC(14,2);
  
  DECLARE VARIABLE V_SELO_GRUPO_ID_QUESITOS_COMP INTEGER;
  DECLARE VARIABLE V_VALOR_QUESITOS_COMP NUMERIC(14,2);
  
  DECLARE VARIABLE V_TOTAL_INDIVIDUAL_ACUMULADO NUMERIC(14,2);
  
  DECLARE VARIABLE V_ID_ATO_ISENTADO NUMERIC(14,2);
  DECLARE VARIABLE V_EH_ISENTO VARCHAR(1);
  
  DECLARE VARIABLE V_RI_ISENCAO_SELO_GRUPO_ID VARCHAR(10);

  DECLARE VARIABLE V_USAR_ISS VARCHAR(3);
  DECLARE VARIABLE V_COBRAR_ISS_USUARIO VARCHAR(3);
  DECLARE VARIABLE V_PERCENTUAL_ISS NUMERIC(14,5);
  declare variable V_PERCENTUAL_ISS_STR VARCHAR(10);

  DECLARE VARIABLE V_NUMERO_SELO VARCHAR(60);
  declare variable V_PERCENTUAL_FUNDOS_ESTADUAIS numeric(18,4);
BEGIN
  STATUS = 'T';
  V_ENVIOU_TAXA = 'F';  

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'RI_ISENCAO_SELO_GRUPO_ID', 5) INTO :V_RI_ISENCAO_SELO_GRUPO_ID;
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'USAR_ISS', 5) INTO :V_USAR_ISS;
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'COBRAR_ISS_USUARIO', 5) INTO :V_COBRAR_ISS_USUARIO;
  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL', 'GERAL', 'PERCENTUAL_ISS', 5) INTO :V_PERCENTUAL_ISS_STR;

  SELECT RETORNO FROM W_TROCAR_VIRGULA_POR_PONTO(:V_PERCENTUAL_ISS_STR) INTO :V_PERCENTUAL_ISS;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'PERCENTUAL_FUNDOS_ESTADUAIS', 5) INTO :V_PERCENTUAL_FUNDOS_ESTADUAIS;
  if (COALESCE(:V_PERCENTUAL_FUNDOS_ESTADUAIS,0) = 0) then
  BEGIN
    V_PERCENTUAL_FUNDOS_ESTADUAIS = 40;
  END
  V_PERCENTUAL_FUNDOS_ESTADUAIS = (:V_PERCENTUAL_FUNDOS_ESTADUAIS/100);
   
  FOR SELECT PI.PEDIDO_ITEM_ID, COALESCE(PI.QUANTIDADE,0) QUANTIDADE, I.SELO_GRUPO_ID, 
        PE.APRESENTANTE_NOME, COALESCE(PI.VALOR_EMOLUMENTO,0) VALOR_EMOLUMENTO, 
        COALESCE(PI.VALOR_TAXA_JUDICIARIA,0) VALOR_TAXA_JUDICIARIA, 
        COALESCE(PI.VALOR_FUNDO_RI,0) VALOR_FUNDO_RI, N.TIPO_TITULO, E.DESCRICAO,      
        COALESCE(PI.VALOR_DESCONTO,0) VALOR_DESCONTO,
        COALESCE(PI.PORCENTAGEM_DESCONTO,0) PORCENTAGEM_DESCONTO,
        COALESCE(PI.QUANTIDADE_ATOS_ACRESCIDOS,0),
        COALESCE(PI.QUANTIDADE_QUESITOS,0),
        COALESCE(PI.EMOLUMENTO_ID,0), 
        COALESCE(PI.EMOLUMENTO_ID_ATOS_ACRESCIDOS,0), 
        COALESCE(PI.EMOLUMENTO_ID_QUESITOS,0),
        COALESCE(PI.EMOLUMENTO_ID_ATOS_ACRESC_COMPL,0),
        COALESCE(PI.EMOLUMENTO_ID_QUESITOS_COMPL,0),
        PI.EH_ISENTO, COALESCE(PI.VALOR_ISS,0)
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, G_EMOLUMENTO E, 
        G_EMOLUMENTO_ITEM I, G_SELO_GRUPO S, G_NATUREZA_TITULO N
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID 
      AND PE.PEDIDO_ID = PI.PEDIDO_ID 
      AND PI.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID 
      AND PI.EMOLUMENTO_ITEM_ID = I.EMOLUMENTO_ITEM_ID
      AND I.EMOLUMENTO_ID = E.EMOLUMENTO_ID 
      AND I.SELO_GRUPO_ID = S.SELO_GRUPO_ID 
      AND PE.PEDIDO_ID = :V_PEDIDO_ID
      AND PR.TIPO_PROTOCOLO = '3'
      AND (PI.EXCLUI_DO_RELATORIO = 'N' OR PI.EXCLUI_DO_RELATORIO IS NULL OR PI.EXCLUI_DO_RELATORIO = '')       
      ORDER BY S.AGRUPADOR DESC, PI.PEDIDO_ITEM_ID ASC
      INTO :V_PEDIDO_ITEM_ID, :V_QUANTIDADE, :V_SELO_GRUPO_ID, 
        :V_APRESENTANTE_NOME, :V_VALOR_EMOLUMENTO_TEMP, :V_VALOR_TAXA_JUDICIARIA, 
        :V_VALOR_FUNDO_RI, :V_TIPO_TITULO, :V_DESCRICAO_EMOLUMENTO,
        :V_VALOR_DESCONTO, :V_PORCENTAGEM_DESCONTO, :V_QUANTIDADE_ATOS_ACRESCIDOS,
        :V_QUANTIDADE_QUESITOS, :V_EMOLUMENTO_ID, :V_EMOLUMENTO_ID_ATOS_ACRESCIDOS, 
        :V_EMOLUMENTO_ID_QUESITOS, :V_EMOLUMENTO_ID_ATOS_ACRESC_COMP, 
        :V_EMOLUMENTO_ID_QUESITOS_COMP, :V_EH_ISENTO, :V_VALOR_ISS DO
  BEGIN
    IF (:V_QUANTIDADE > 0) THEN
    BEGIN
      SELECT FIRST 1 'PEDIDO CERTIDÃO: '||CAST(PR.NUMERO_ORDEM AS INTEGER)||', '||
        SUBSTRING(NT.DESCRICAO FROM 1 FOR 100)
      FROM R_PROTOCOLO PR, R_PEDIDO_ITEM PI, G_NATUREZA_TITULO NT
      WHERE PR.PEDIDO_ID = PI.PEDIDO_ID
      AND PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID
      AND PR.TIPO_PROTOCOLO = '3'
      AND PI.PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
      INTO :V_DESCRICAO_SELO;
      
      --se existir menor quantidade de mat/reg.auxiliar que a quantidade calculada, cria os mesmos
      SELECT COUNT(*) FROM R_PEDIDO_ITEM_NUMERO 
      WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
      INTO :V_COUNT;
      IF (:V_COUNT < :V_QUANTIDADE) THEN
      BEGIN
        I = :V_COUNT;
        WHILE (I < :V_QUANTIDADE) DO
        BEGIN
          SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('R_PEDIDO_ITEM_NUMERO')
          INTO :V_PEDIDO_ITEM_NUMERO_ID;

          INSERT INTO R_PEDIDO_ITEM_NUMERO(PEDIDO_ITEM_NUMERO_ID, PEDIDO_ITEM_ID)                                             
                                   VALUES (:V_PEDIDO_ITEM_NUMERO_ID, :V_PEDIDO_ITEM_ID);
          I = I + 1;
        END
      END

      IF (COALESCE(V_PERIODO_PADRAO,0) > 0) THEN
      BEGIN
        V_EMOLUMENTO_PERIODO_ID = :V_PERIODO_PADRAO;
      END
      ELSE
      BEGIN
        --PEGAR EMOLUMENTO PERIODO PADRAO
        SELECT FIRST 1 EMOLUMENTO_PERIODO_ID FROM G_EMOLUMENTO_PERIODO 
        WHERE DATA_INICIAL < CURRENT_TIMESTAMP ORDER BY DATA_INICIAL DESC        
        INTO :V_EMOLUMENTO_PERIODO_ID;           
      END

      IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
      BEGIN
        V_VALOR_EMOLUMENTO_BASE = 0;
        V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS = 0;
        V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP = 0;
        V_VALOR_EMOLUMENTO_QUESITOS = 0;
        V_VALOR_EMOLUMENTO_QUESITOS_COMP = 0;
        V_SELO_GRUPO_ID_ATOS_ACRESCIDOS = 0;
        V_SELO_GRUPO_ID_ATOS_ACRESC_COMP = 0;
        V_SELO_GRUPO_ID_QUESITOS = 0;
        V_SELO_GRUPO_ID_QUESITOS_COMP = 0;      
        IF ((:V_QUANTIDADE_ATOS_ACRESCIDOS > 0) OR (:V_QUANTIDADE_QUESITOS > 0)) THEN
        BEGIN
          --VERIFICAR QUANTIDADE DE ATOS ACRESCIDOS E QUESITO E VER SE EXISTE COMPLEMENTO
          IF (:V_QUANTIDADE_ATOS_ACRESCIDOS > 6) THEN
          BEGIN
            V_QUANTIDADE_ATOS_ACRESCIDOS = 6;
            V_QUANTIDADE_ATOS_ACRESC_COMP = 1;
          END
          IF (:V_QUANTIDADE_QUESITOS > 3) THEN
          BEGIN
            V_QUANTIDADE_QUESITOS = 3;
            V_QUANTIDADE_QUESITOS_COMP = 1;
          END
          --PEGAR GRUPO DE ATOS ACRESCIDOS
          IF (COALESCE(:V_EMOLUMENTO_ID_ATOS_ACRESCIDOS,0) > 0) THEN
          BEGIN
            SELECT COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRESCIDOS, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS;
          END
          ELSE
          BEGIN
            V_SELO_GRUPO_ID_ATOS_ACRESCIDOS = 0;
          END
          
          --PEGAR GRUPO DE COMPLEMENTO DE ATOS ACRESCIDOS
          IF (COALESCE(:V_EMOLUMENTO_ID_ATOS_ACRESC_COMP,0) > 0) THEN
          BEGIN
            SELECT COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRESC_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP;
          END
          ELSE
          BEGIN
            V_SELO_GRUPO_ID_ATOS_ACRESC_COMP = 0;
          END

          --PEGAR GRUPO DE QUESITOS
          IF (:V_EMOLUMENTO_ID_QUESITOS > 0) THEN
          BEGIN
            SELECT COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_SELO_GRUPO_ID_QUESITOS;
          END
          ELSE
          BEGIN
            V_SELO_GRUPO_ID_QUESITOS = 0;
          END          

          --PEGAR GRUPO DE COMPLEMENTO DE QUESITOS
          IF (:V_EMOLUMENTO_ID_QUESITOS_COMP > 0) THEN
          BEGIN
            SELECT COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_SELO_GRUPO_ID_QUESITOS_COMP;
          END
          ELSE
          BEGIN
            V_SELO_GRUPO_ID_QUESITOS_COMP = 0;
          END          
        END

        --GRAVAR SELO DE CERTIDAO
        V_NUMERO_AGRUPADOR_PED_CERTIDAO = ''; 
        FOR SELECT PEDIDO_ITEM_NUMERO_ID FROM R_PEDIDO_ITEM_NUMERO 
            WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
            INTO :V_PEDIDO_ITEM_NUMERO_ID DO
        BEGIN
          V_ID_ATO_ISENTADO = 0;
          IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
          BEGIN
            SELECT NUMERO FROM G_SELO_GRUPO
            WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID
            INTO :V_ID_ATO_ISENTADO;
  
            V_SELO_GRUPO_ID = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
          END
  
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
          AND L.ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
          AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
          INTO :V_QUANTIDADE_EMITIDA;
          IF (COALESCE(:V_QUANTIDADE_EMITIDA,0) = 0) THEN
          BEGIN                
            SELECT FIRST 1 LV.SELO_LIVRO_ID, LV.NUMERO_SELO
            FROM G_SELO_LIVRO LV, G_SELO_LOTE LT, G_SELO_GRUPO GP
            WHERE LV.SELO_SITUACAO_ID = 1
            AND LV.SELO_LOTE_ID = LT.SELO_LOTE_ID
            AND LT.SELO_GRUPO_ID = GP.SELO_GRUPO_ID
            AND GP.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
            ORDER BY LV.SELO_LOTE_ID, LV.SELO_LIVRO_ID
--            INTO :V_SELO_LIVRO_ID, :V_SIGLA, :V_NUMERO;
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;

            IF (COALESCE(:V_NUMERO_AGRUPADOR_PED_CERTIDAO,'') = '') THEN
            BEGIN              
              V_NUMERO_AGRUPADOR_PED_CERTIDAO = :V_NUMERO_SELO;
            END
                    
            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = 0,
                VALOR_EMOLUMENTO = 0,
                VALOR_TAXA_JUDICIARIA = 0,
                VALOR_FUNDESP = 0,
                DESCRICAO = :V_DESCRICAO_SELO,
                ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;
          END
        END

        --GRAVAR SELO ATOS ACRESCIDOS
        IF ((COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0) > 0) AND (COALESCE(V_SELO_GRUPO_ID_ATOS_ACRESCIDOS,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;
                
          V_ID_ATO_ISENTADO = 0;
          IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
          BEGIN
            SELECT NUMERO FROM G_SELO_GRUPO
            WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS
            INTO :V_ID_ATO_ISENTADO;
  
            V_SELO_GRUPO_ID_ATOS_ACRESCIDOS = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
          END
  
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS
          AND L.ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
          AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
          INTO :V_QUANTIDADE_EMITIDA;
  
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_ATOS_ACRESCIDOS) DO
          BEGIN                
            --SELECIONAR PROXIMO SELO PARA O PEDIDO
            SELECT FIRST 1 LI.SELO_LIVRO_ID, LI.NUMERO_SELO
            FROM G_SELO_LIVRO LI, G_SELO_LOTE LO
            WHERE LI.SELO_LOTE_ID = LO.SELO_LOTE_ID
            AND LI.SELO_SITUACAO_ID = 1
            AND LO.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS
            ORDER BY LI.SELO_LOTE_ID, LI.SELO_LIVRO_ID
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;

          
            IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
            BEGIN
              SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
              WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
              AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
              AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
              AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
              AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
              INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
            END                  
            
            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = 0,
                VALOR_EMOLUMENTO = 0,
                VALOR_TAXA_JUDICIARIA = 0, 
                VALOR_FUNDESP = 0,
                DESCRICAO = :V_DESCRICAO_SELO,
                ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    

            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;

          END
        END
        
        --GRAVAR SELO ATOS ACRESCIDOS - COMPLEMENTO
        IF ((COALESCE(:V_QUANTIDADE_ATOS_ACRESC_COMP,0) > 0) AND (COALESCE(V_SELO_GRUPO_ID_ATOS_ACRESC_COMP,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;
  
          V_ID_ATO_ISENTADO = 0;
          IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
          BEGIN
            SELECT NUMERO FROM G_SELO_GRUPO
            WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP
            INTO :V_ID_ATO_ISENTADO;
  
            V_SELO_GRUPO_ID_ATOS_ACRESC_COMP = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
          END
                
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP
          AND L.ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
          AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
          INTO :V_QUANTIDADE_EMITIDA;
          
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_ATOS_ACRESC_COMP) DO
          BEGIN                
            --SELECIONAR PROXIMO SELO PARA O PEDIDO
            SELECT FIRST 1 LI.SELO_LIVRO_ID, LI.NUMERO_SELO
            FROM G_SELO_LIVRO LI, G_SELO_LOTE LO
            WHERE LI.SELO_LOTE_ID = LO.SELO_LOTE_ID
            AND LI.SELO_SITUACAO_ID = 1
            AND LO.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP
            ORDER BY LI.SELO_LOTE_ID, LI.SELO_LIVRO_ID
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;

          
            IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
            BEGIN
              SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
              WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
              AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
              AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
              AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
              AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
              INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
            END                  
            
            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = 0,
                VALOR_EMOLUMENTO = 0,
                VALOR_TAXA_JUDICIARIA = 0, 
                VALOR_FUNDESP = 0,
                DESCRICAO = :V_DESCRICAO_SELO,
                ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    

            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END
        END      

        --GRAVAR SELO QUESITOS
        IF ((COALESCE(:V_QUANTIDADE_QUESITOS,0) > 0) AND (COALESCE(:V_SELO_GRUPO_ID_QUESITOS,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;      
  
          V_ID_ATO_ISENTADO = 0;
          IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
          BEGIN
            SELECT NUMERO FROM G_SELO_GRUPO
            WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS
            INTO :V_ID_ATO_ISENTADO;
  
            V_SELO_GRUPO_ID_QUESITOS = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
          END
        
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS
          AND L.ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
          AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
          INTO :V_QUANTIDADE_EMITIDA;
          
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_QUESITOS) DO
          BEGIN                
            --SELECIONAR PROXIMO SELO PARA O PEDIDO
            SELECT FIRST 1 LI.SELO_LIVRO_ID, LI.NUMERO_SELO
            FROM G_SELO_LIVRO LI, G_SELO_LOTE LO
            WHERE LI.SELO_LOTE_ID = LO.SELO_LOTE_ID
            AND LI.SELO_SITUACAO_ID = 1
            AND LO.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS
            ORDER BY LI.SELO_LOTE_ID, LI.SELO_LIVRO_ID
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;

            IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
            BEGIN
              SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
              WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
              AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
              AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
              AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
              AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
              INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
            END                  
            
            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = 0,
                VALOR_EMOLUMENTO = 0,
                VALOR_TAXA_JUDICIARIA = 0, 
                VALOR_FUNDESP = 0,
                DESCRICAO = :V_DESCRICAO_SELO,
                ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    

            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END                
        END

        --GRAVAR SELO QUESITOS - COMPLEMENTO
        IF ((COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0) > 0) AND (COALESCE(:V_SELO_GRUPO_ID_QUESITOS_COMP,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;      
  
          V_ID_ATO_ISENTADO = 0;
          IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
          BEGIN
            SELECT NUMERO FROM G_SELO_GRUPO
            WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS_COMP
            INTO :V_ID_ATO_ISENTADO;
  
            V_SELO_GRUPO_ID_QUESITOS_COMP = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
          END
        
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS_COMP
          AND L.ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
          AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
          INTO :V_QUANTIDADE_EMITIDA;
          
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_QUESITOS_COMP) DO
          BEGIN                
            --SELECIONAR PROXIMO SELO PARA O PEDIDO
            SELECT FIRST 1 LI.SELO_LIVRO_ID, LI.NUMERO_SELO
            FROM G_SELO_LIVRO LI, G_SELO_LOTE LO
            WHERE LI.SELO_LOTE_ID = LO.SELO_LOTE_ID
            AND LI.SELO_SITUACAO_ID = 1
            AND LO.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS_COMP
            ORDER BY LI.SELO_LOTE_ID, LI.SELO_LIVRO_ID
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;

          
            IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
            BEGIN
              SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
              WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
              AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
              AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
              AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
              AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
              INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
            END                  
            
            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = 0,
                VALOR_EMOLUMENTO = 0,
                VALOR_TAXA_JUDICIARIA = 0, 
                VALOR_FUNDESP = 0,
                DESCRICAO = :V_DESCRICAO_SELO,
                ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    

            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END                  
        END
      END
      ELSE
      BEGIN
      --NAO ISENTADOS
        V_VALOR_EMOLUMENTO_BASE = 0;
        V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS = 0;
        V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP = 0;
        V_VALOR_EMOLUMENTO_QUESITOS = 0;
        V_VALOR_EMOLUMENTO_QUESITOS_COMP = 0;
        V_SELO_GRUPO_ID_ATOS_ACRESCIDOS = 0;
        V_SELO_GRUPO_ID_ATOS_ACRESC_COMP = 0;
        V_SELO_GRUPO_ID_QUESITOS = 0;
        V_SELO_GRUPO_ID_QUESITOS_COMP = 0;      
        IF ((:V_QUANTIDADE_ATOS_ACRESCIDOS > 0) OR (:V_QUANTIDADE_QUESITOS > 0)) THEN
        BEGIN
          --VERIFICAR QUANTIDADE DE ATOS ACRESCIDOS E QUESITO E VER SE EXISTE COMPLEMENTO
          IF (:V_QUANTIDADE_ATOS_ACRESCIDOS > 6) THEN
          BEGIN
            V_QUANTIDADE_ATOS_ACRESCIDOS = 6;
            V_QUANTIDADE_ATOS_ACRESC_COMP = 1;
          END
          IF (:V_QUANTIDADE_QUESITOS > 3) THEN
          BEGIN
            V_QUANTIDADE_QUESITOS = 3;
            V_QUANTIDADE_QUESITOS_COMP = 1;
          END
          --PEGAR VALOR BASE DE EMOLUMENTOS
          SELECT COALESCE(VALOR_EMOLUMENTO,0)
          FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID, :V_EMOLUMENTO_PERIODO_ID, 0)
          INTO :V_VALOR_EMOLUMENTO_BASE;
          --PEGAR VALORES DE EMOLUMENTOS DE ATOS ACRESCIDOS
          IF (COALESCE(:V_EMOLUMENTO_ID_ATOS_ACRESCIDOS,0) > 0) THEN
          BEGIN
            SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRESCIDOS, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS, :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS;
          END
          ELSE
          BEGIN
            V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS = 0;
            V_SELO_GRUPO_ID_ATOS_ACRESCIDOS = 0;
          END
          
          --PEGAR VALORES DE EMOLUMENTOS DE COMPLEMENTO DE ATOS ACRESCIDOS
          IF (COALESCE(:V_EMOLUMENTO_ID_ATOS_ACRESC_COMP,0) > 0) THEN
          BEGIN
            SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRESC_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP, :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP;
          END
          ELSE
          BEGIN
            V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP = 0;
            V_SELO_GRUPO_ID_ATOS_ACRESC_COMP = 0;
          END
          --PEGAR VALORES DE EMOLUMENTOS DE QUESITOS
          IF (:V_EMOLUMENTO_ID_QUESITOS > 0) THEN
          BEGIN
            SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_VALOR_EMOLUMENTO_QUESITOS, :V_SELO_GRUPO_ID_QUESITOS;
          END
          ELSE
          BEGIN
            V_VALOR_EMOLUMENTO_QUESITOS = 0;
            V_SELO_GRUPO_ID_QUESITOS = 0;
          END          
          --PEGAR VALORES DE EMOLUMENTOS DE COMPLEMENTO DE QUESITOS
          IF (:V_EMOLUMENTO_ID_QUESITOS_COMP > 0) THEN
          BEGIN
            SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_VALOR_EMOLUMENTO_QUESITOS_COMP, :V_SELO_GRUPO_ID_QUESITOS_COMP;
          END
          ELSE
          BEGIN
            V_VALOR_EMOLUMENTO_QUESITOS_COMP = 0;
            V_SELO_GRUPO_ID_QUESITOS_COMP = 0;
          END          
          V_VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO_BASE;
        END
        ELSE
        BEGIN
          V_VALOR_EMOLUMENTO = CAST((:V_VALOR_EMOLUMENTO_TEMP / :V_QUANTIDADE) AS NUMERIC(14,2));      
        END      
        --VALOR DE TAXA JUDICIARIA
        IF (:V_VALOR_TAXA_JUDICIARIA > 0) THEN
        BEGIN
          V_VALOR_TAXA_JUDICIARIA = CAST((:V_VALOR_TAXA_JUDICIARIA / :V_QUANTIDADE) AS NUMERIC(14,2));
        END

        V_ID_ATO_ISENTADO = 0;

        --GRAVAR SELO DE CERTIDAO
        V_NUMERO_AGRUPADOR_PED_CERTIDAO = ''; 
        FOR SELECT PEDIDO_ITEM_NUMERO_ID FROM R_PEDIDO_ITEM_NUMERO 
            WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
            INTO :V_PEDIDO_ITEM_NUMERO_ID DO
        BEGIN
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
          AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
          INTO :V_QUANTIDADE_EMITIDA;
          IF (COALESCE(:V_QUANTIDADE_EMITIDA,0) = 0) THEN
          BEGIN                
            --SELECIONAR PROXIMO SELO PARA O PEDIDO
            SELECT FIRST 1 LI.SELO_LIVRO_ID, LI.NUMERO_SELO
            FROM G_SELO_LIVRO LI, G_SELO_LOTE LO
            WHERE LI.SELO_LOTE_ID = LO.SELO_LOTE_ID
            AND LI.SELO_SITUACAO_ID = 1
            AND LO.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
            ORDER BY LI.SELO_LOTE_ID, LI.SELO_LIVRO_ID
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;
            
            IF (COALESCE(:V_NUMERO_AGRUPADOR_PED_CERTIDAO,'') = '') THEN
            BEGIN              
              V_NUMERO_AGRUPADOR_PED_CERTIDAO = :V_NUMERO_SELO;
            END          

            --CALCULAR FUNDO
            V_VALOR_FUNDO_RI = CAST((COALESCE(:V_VALOR_EMOLUMENTO,0)*(:V_PERCENTUAL_FUNDOS_ESTADUAIS)) AS NUMERIC(14,2));
            V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO,0) + COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

            V_VALOR_ISS = 0;
            IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
            BEGIN
              IF (COALESCE(V_VALOR_EMOLUMENTO,0) > 0) THEN
              BEGIN
                V_VALOR_ISS = cast((COALESCE(V_VALOR_EMOLUMENTO,0)) * (V_PERCENTUAL_ISS/100) as numeric(14,2));
              END
            END    

            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = :V_VALOR_TOTAL, 
                VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO, 
                VALOR_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA, 
                VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                VALOR_ISS = :V_VALOR_ISS,
                DESCRICAO = :V_DESCRICAO_SELO,
                ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;
          END
        END
        V_TOTAL_INDIVIDUAL_ACUMULADO = :V_VALOR_EMOLUMENTO;
        
        --GRAVAR SELO ATOS ACRESCIDOS
        IF ((COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0) > 0) AND (COALESCE(V_SELO_GRUPO_ID_ATOS_ACRESCIDOS,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;

          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS
          AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
          INTO :V_QUANTIDADE_EMITIDA;
          
          V_TOTAL_INDIVIDUAL_ACUMULADO = :V_TOTAL_INDIVIDUAL_ACUMULADO + (COALESCE(V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS,0)*COALESCE(:V_QUANTIDADE_EMITIDA,0));
  
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_ATOS_ACRESCIDOS) DO
          BEGIN                
            IF (:V_TOTAL_INDIVIDUAL_ACUMULADO < :V_VALOR_EMOLUMENTO_TEMP) THEN
            BEGIN
              --SELECIONAR PROXIMO SELO PARA O PEDIDO
              SELECT FIRST 1 LI.SELO_LIVRO_ID, LI.NUMERO_SELO
              FROM G_SELO_LIVRO LI, G_SELO_LOTE LO
              WHERE LI.SELO_LOTE_ID = LO.SELO_LOTE_ID
              AND LI.SELO_SITUACAO_ID = 1
              AND LO.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS
              ORDER BY LI.selo_lote_id,  LI.SELO_LIVRO_ID
              INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;

              IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
              BEGIN
                SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
                WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
                AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
                AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
                AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
                AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
                INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
              END                  
              
              IF ((COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS,0)) > :V_VALOR_EMOLUMENTO_TEMP) THEN
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST((COALESCE((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)),0)*(:V_PERCENTUAL_FUNDOS_ESTADUAIS)) AS NUMERIC(14,2));
                V_VALOR_TOTAL = COALESCE((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)),0) + COALESCE(:V_VALOR_FUNDO_RI,0);

                V_VALOR_ISS = 0;
                IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
                BEGIN
                  V_VALOR_ISS = CAST((COALESCE((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)),0)*(V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
                END

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = (COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)), 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    VALOR_ISS = :V_VALOR_ISS,
                    DESCRICAO = :V_DESCRICAO_SELO,
                    ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    
              END
              ELSE
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST((COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS,0)*(:V_PERCENTUAL_FUNDOS_ESTADUAIS)) AS NUMERIC(14,2));
                V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

                V_VALOR_ISS = 0;
                IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
                BEGIN
                  V_VALOR_ISS = CAST((COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS,0)*(V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
                END


                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS, 
