                AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
                AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
                INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
              END                  
              
              IF ((COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS,0)) > :V_VALOR_EMOLUMENTO_TEMP) THEN
              BEGIN
