                V_VALOR_FUNDO_RI = CAST(((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0))*(:V_PERCENTUAL_FUNDOS_ESTADUAIS)) AS NUMERIC(14,2));
