                IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
                BEGIN
                  V_VALOR_ISS = CAST(((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0))*(V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
                END

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = (COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)), 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    VALOR_ISS = :V_VALOR_ISS,
                    DESCRICAO = :V_DESCRICAO_SELO,
                    ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    
              END
              ELSE
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST((COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS,0)*(:V_PERCENTUAL_FUNDOS_ESTADUAIS)) AS NUMERIC(14,2));
                V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

                V_VALOR_ISS = 0;
                IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
                BEGIN
                  V_VALOR_ISS = CAST((COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS,0)*(V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
                END

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO_QUESITOS, 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    VALOR_ISS = :V_VALOR_ISS,
                    DESCRICAO = :V_DESCRICAO_SELO,
                    ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                              
              END
              V_TOTAL_INDIVIDUAL_ACUMULADO = COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS,0);
            END                
            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END                  
        END
        --GRAVAR SELO QUESITOS - COMPLEMENTO
        IF ((COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0) > 0) AND (COALESCE(:V_SELO_GRUPO_ID_QUESITOS_COMP,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
