                AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
                AND COALESCE(L.SELO_SITUACAO_ID,0) = 2
                INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
              END                  
              
              IF ((COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS_COMP,0)) > :V_VALOR_EMOLUMENTO_TEMP) THEN
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST(((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0))*(:V_PERCENTUAL_FUNDOS_ESTADUAIS)) AS NUMERIC(14,2));
                V_VALOR_TOTAL = (COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)) + COALESCE(:V_VALOR_FUNDO_RI,0);

                V_VALOR_ISS = 0;
                IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
                BEGIN
                  V_VALOR_ISS = CAST(((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0))*(V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
                END

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = (COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)), 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    VALOR_ISS = :V_VALOR_ISS,
                    DESCRICAO = :V_DESCRICAO_SELO,
                    ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    
              END
              ELSE
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST((COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS_COMP,0)*(:V_PERCENTUAL_FUNDOS_ESTADUAIS)) AS NUMERIC(14,2));
                V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS_COMP,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

                V_VALOR_ISS = 0;
                IF ((COALESCE(:V_USAR_ISS,'') = 'S') AND (COALESCE(:V_COBRAR_ISS_USUARIO,'') = 'S')) THEN
                BEGIN
                  V_VALOR_ISS = CAST((COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS_COMP,0)*(V_PERCENTUAL_ISS/100)) AS NUMERIC(14,2));
                END

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO_QUESITOS_COMP, 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    VALOR_ISS = :V_VALOR_ISS,
                    DESCRICAO = :V_DESCRICAO_SELO,
                    ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                              
              END
              V_TOTAL_INDIVIDUAL_ACUMULADO = COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS_COMP,0);
            END                
            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END                  
        END
      END
    END
  END
  SUSPEND;
END ^

ALTER PROCEDURE R_SELAR_PEDIDO_CERTIDAO_GO_OLD (V_PEDIDO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_USUARIO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_IP_MAQUINA VARCHAR(30) CHARACTER SET ISO8859_1,
V_PERIODO_PADRAO INTEGER,
V_DATA VARCHAR(20) CHARACTER SET ISO8859_1)
RETURNS (STATUS VARCHAR(1) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_PEDIDO_ITEM_ID INTEGER;
  DECLARE VARIABLE V_PEDIDO_ITEM_NUMERO_ID INTEGER;
  DECLARE VARIABLE V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO INTEGER;
  DECLARE VARIABLE V_QUANTIDADE INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_ATOS_ACRESCIDOS INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_ATOS_ACRESC_COMP INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_QUESITOS INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_QUESITOS_COMP INTEGER;
  DECLARE VARIABLE V_SELO_GRUPO_ID INTEGER;
  DECLARE VARIABLE V_APRESENTANTE_NOME VARCHAR(120);
  DECLARE VARIABLE V_EMOLUMENTO_ID INTEGER;
  DECLARE VARIABLE V_EMOLUMENTO_ID_ATOS_ACRESCIDOS INTEGER;
  DECLARE VARIABLE V_EMOLUMENTO_ID_ATOS_ACRESC_COMP INTEGER;
  DECLARE VARIABLE V_EMOLUMENTO_ID_QUESITOS INTEGER;
  DECLARE VARIABLE V_EMOLUMENTO_ID_QUESITOS_COMP INTEGER;
  DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_TEMP NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_BASE NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_QUESITOS NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_EMOLUMENTO_QUESITOS_COMP NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_FUNDO_RI NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_TOTAL NUMERIC(18,4);
  DECLARE VARIABLE V_VALOR_DESCONTO NUMERIC(18,4);
  DECLARE VARIABLE V_PORCENTAGEM_DESCONTO NUMERIC(18,4);
  DECLARE VARIABLE V_TIPO_TITULO VARCHAR(60);
  DECLARE VARIABLE V_COUNT INTEGER;
  DECLARE VARIABLE V_NUMERO_GRUPO INTEGER;
  DECLARE VARIABLE V_DESCRICAO_GRUPO VARCHAR(260);
  DECLARE VARIABLE V_DESCRICAO_EMOLUMENTO VARCHAR(260);
  DECLARE VARIABLE V_SELO_LIVRO_ID INTEGER;
  DECLARE VARIABLE V_NUMERO_AGRUPADOR_PED_CERTIDAO VARCHAR(50);
  DECLARE VARIABLE I INTEGER;
  DECLARE VARIABLE J INTEGER;
  DECLARE VARIABLE V_ENVIOU_TAXA CHAR(1);
  DECLARE VARIABLE V_TAMANHO INTEGER;
  DECLARE VARIABLE V_QUANTIDADE_EMITIDA INTEGER;
  DECLARE VARIABLE V_DESCRICAO_SELO VARCHAR(260);
  DECLARE VARIABLE V_EMOLUMENTO_PERIODO_ID INTEGER;
  
  DECLARE VARIABLE V_SELO_GRUPO_ID_ATOS_ACRESCIDOS INTEGER;
  DECLARE VARIABLE V_VALOR_ATOS_ACRESCIDOS NUMERIC(14,2);
  
  DECLARE VARIABLE V_SELO_GRUPO_ID_ATOS_ACRESC_COMP INTEGER;
  DECLARE VARIABLE V_VALOR_ATOS_ACRESC_COMP NUMERIC(14,2);
  
  DECLARE VARIABLE V_SELO_GRUPO_ID_QUESITOS INTEGER;
  DECLARE VARIABLE V_VALOR_QUESITOS NUMERIC(14,2);
  
  DECLARE VARIABLE V_SELO_GRUPO_ID_QUESITOS_COMP INTEGER;
  DECLARE VARIABLE V_VALOR_QUESITOS_COMP NUMERIC(14,2);
  
  DECLARE VARIABLE V_TOTAL_INDIVIDUAL_ACUMULADO NUMERIC(14,2);
  
  DECLARE VARIABLE V_ID_ATO_ISENTADO NUMERIC(14,2);
  DECLARE VARIABLE V_EH_ISENTO VARCHAR(1);
  
  DECLARE VARIABLE V_RI_ISENCAO_SELO_GRUPO_ID VARCHAR(10);

  DECLARE VARIABLE V_NUMERO_SELO VARCHAR(60);
BEGIN
  STATUS = 'T';
  V_ENVIOU_TAXA = 'F';  

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'RI_ISENCAO_SELO_GRUPO_ID', 5) INTO :V_RI_ISENCAO_SELO_GRUPO_ID;
   
  FOR SELECT PI.PEDIDO_ITEM_ID, COALESCE(PI.QUANTIDADE,0) QUANTIDADE, I.SELO_GRUPO_ID, 
        PE.APRESENTANTE_NOME, COALESCE(PI.VALOR_EMOLUMENTO,0) VALOR_EMOLUMENTO, 
        COALESCE(PI.VALOR_TAXA_JUDICIARIA,0) VALOR_TAXA_JUDICIARIA, 
        COALESCE(PI.VALOR_FUNDO_RI,0) VALOR_FUNDO_RI, N.TIPO_TITULO, E.DESCRICAO,      
        COALESCE(PI.VALOR_DESCONTO,0) VALOR_DESCONTO,
        COALESCE(PI.PORCENTAGEM_DESCONTO,0) PORCENTAGEM_DESCONTO,
        COALESCE(PI.QUANTIDADE_ATOS_ACRESCIDOS,0),
        COALESCE(PI.QUANTIDADE_QUESITOS,0),
        COALESCE(PI.EMOLUMENTO_ID,0), 
        COALESCE(PI.EMOLUMENTO_ID_ATOS_ACRESCIDOS,0), 
        COALESCE(PI.EMOLUMENTO_ID_QUESITOS,0),
        COALESCE(PI.EMOLUMENTO_ID_ATOS_ACRESC_COMPL,0),
        COALESCE(PI.EMOLUMENTO_ID_QUESITOS_COMPL,0),
        PI.EH_ISENTO
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, G_EMOLUMENTO E, 
        G_EMOLUMENTO_ITEM I, G_SELO_GRUPO S, G_NATUREZA_TITULO N
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID 
      AND PE.PEDIDO_ID = PI.PEDIDO_ID 
      AND PI.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID 
      AND PI.EMOLUMENTO_ITEM_ID = I.EMOLUMENTO_ITEM_ID
      AND I.EMOLUMENTO_ID = E.EMOLUMENTO_ID 
      AND I.SELO_GRUPO_ID = S.SELO_GRUPO_ID 
      AND PE.PEDIDO_ID = :V_PEDIDO_ID
      AND PR.TIPO_PROTOCOLO = '3'
      AND (PI.EXCLUI_DO_RELATORIO = 'N' OR PI.EXCLUI_DO_RELATORIO IS NULL OR PI.EXCLUI_DO_RELATORIO = '')       
      ORDER BY S.AGRUPADOR DESC, PI.PEDIDO_ITEM_ID ASC
      INTO :V_PEDIDO_ITEM_ID, :V_QUANTIDADE, :V_SELO_GRUPO_ID, 
        :V_APRESENTANTE_NOME, :V_VALOR_EMOLUMENTO_TEMP, :V_VALOR_TAXA_JUDICIARIA, 
        :V_VALOR_FUNDO_RI, :V_TIPO_TITULO, :V_DESCRICAO_EMOLUMENTO,
        :V_VALOR_DESCONTO, :V_PORCENTAGEM_DESCONTO, :V_QUANTIDADE_ATOS_ACRESCIDOS,
        :V_QUANTIDADE_QUESITOS, :V_EMOLUMENTO_ID, :V_EMOLUMENTO_ID_ATOS_ACRESCIDOS, 
        :V_EMOLUMENTO_ID_QUESITOS, :V_EMOLUMENTO_ID_ATOS_ACRESC_COMP, 
        :V_EMOLUMENTO_ID_QUESITOS_COMP, :V_EH_ISENTO DO
  BEGIN
    IF (:V_QUANTIDADE > 0) THEN
    BEGIN
      SELECT FIRST 1 'PEDIDO CERTIDÃO: '||CAST(PR.NUMERO_ORDEM AS INTEGER)||', '||
        SUBSTRING(NT.DESCRICAO FROM 1 FOR 100)
      FROM R_PROTOCOLO PR, R_PEDIDO_ITEM PI, G_NATUREZA_TITULO NT
      WHERE PR.PEDIDO_ID = PI.PEDIDO_ID
      AND PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID
      AND PR.TIPO_PROTOCOLO = '3'
      AND PI.PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
      INTO :V_DESCRICAO_SELO;
      
      --se existir menor quantidade de mat/reg.auxiliar que a quantidade calculada, cria os mesmos
      SELECT COUNT(*) FROM R_PEDIDO_ITEM_NUMERO 
      WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
      INTO :V_COUNT;
      IF (:V_COUNT < :V_QUANTIDADE) THEN
      BEGIN
        I = :V_COUNT;
        WHILE (I < :V_QUANTIDADE) DO
        BEGIN
          SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('R_PEDIDO_ITEM_NUMERO')
          INTO :V_PEDIDO_ITEM_NUMERO_ID;

          INSERT INTO R_PEDIDO_ITEM_NUMERO(PEDIDO_ITEM_NUMERO_ID, PEDIDO_ITEM_ID)                                             
                                   VALUES (:V_PEDIDO_ITEM_NUMERO_ID, :V_PEDIDO_ITEM_ID);
          I = I + 1;
        END
      END

      IF (COALESCE(V_PERIODO_PADRAO,0) > 0) THEN
      BEGIN
        V_EMOLUMENTO_PERIODO_ID = :V_PERIODO_PADRAO;
      END
      ELSE
      BEGIN
        --PEGAR EMOLUMENTO PERIODO PADRAO
        SELECT FIRST 1 EMOLUMENTO_PERIODO_ID FROM G_EMOLUMENTO_PERIODO 
        WHERE DATA_INICIAL < CURRENT_TIMESTAMP ORDER BY DATA_INICIAL DESC        
        INTO :V_EMOLUMENTO_PERIODO_ID;           
      END

      IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
      BEGIN
        V_VALOR_EMOLUMENTO_BASE = 0;
        V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS = 0;
        V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP = 0;
        V_VALOR_EMOLUMENTO_QUESITOS = 0;
        V_VALOR_EMOLUMENTO_QUESITOS_COMP = 0;
        V_SELO_GRUPO_ID_ATOS_ACRESCIDOS = 0;
        V_SELO_GRUPO_ID_ATOS_ACRESC_COMP = 0;
        V_SELO_GRUPO_ID_QUESITOS = 0;
        V_SELO_GRUPO_ID_QUESITOS_COMP = 0;      
        IF ((:V_QUANTIDADE_ATOS_ACRESCIDOS > 0) OR (:V_QUANTIDADE_QUESITOS > 0)) THEN
        BEGIN
          --VERIFICAR QUANTIDADE DE ATOS ACRESCIDOS E QUESITO E VER SE EXISTE COMPLEMENTO
          IF (:V_QUANTIDADE_ATOS_ACRESCIDOS > 6) THEN
          BEGIN
            V_QUANTIDADE_ATOS_ACRESCIDOS = 6;
            V_QUANTIDADE_ATOS_ACRESC_COMP = 1;
          END
          IF (:V_QUANTIDADE_QUESITOS > 3) THEN
          BEGIN
            V_QUANTIDADE_QUESITOS = 3;
            V_QUANTIDADE_QUESITOS_COMP = 1;
          END
          --PEGAR GRUPO DE ATOS ACRESCIDOS
          IF (COALESCE(:V_EMOLUMENTO_ID_ATOS_ACRESCIDOS,0) > 0) THEN
          BEGIN
            SELECT COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRESCIDOS, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS;
          END
          ELSE
          BEGIN
            V_SELO_GRUPO_ID_ATOS_ACRESCIDOS = 0;
          END
          
          --PEGAR GRUPO DE COMPLEMENTO DE ATOS ACRESCIDOS
          IF (COALESCE(:V_EMOLUMENTO_ID_ATOS_ACRESC_COMP,0) > 0) THEN
          BEGIN
            SELECT COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRESC_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP;
          END
          ELSE
          BEGIN
            V_SELO_GRUPO_ID_ATOS_ACRESC_COMP = 0;
          END

          --PEGAR GRUPO DE QUESITOS
          IF (:V_EMOLUMENTO_ID_QUESITOS > 0) THEN
          BEGIN
            SELECT COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_SELO_GRUPO_ID_QUESITOS;
          END
          ELSE
          BEGIN
            V_SELO_GRUPO_ID_QUESITOS = 0;
          END          

          --PEGAR GRUPO DE COMPLEMENTO DE QUESITOS
          IF (:V_EMOLUMENTO_ID_QUESITOS_COMP > 0) THEN
          BEGIN
            SELECT COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_SELO_GRUPO_ID_QUESITOS_COMP;
          END
          ELSE
          BEGIN
            V_SELO_GRUPO_ID_QUESITOS_COMP = 0;
          END          
        END

        --GRAVAR SELO DE CERTIDAO
        V_NUMERO_AGRUPADOR_PED_CERTIDAO = ''; 
        FOR SELECT PEDIDO_ITEM_NUMERO_ID FROM R_PEDIDO_ITEM_NUMERO 
            WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
            INTO :V_PEDIDO_ITEM_NUMERO_ID DO
        BEGIN
          V_ID_ATO_ISENTADO = 0;
          IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
          BEGIN
            SELECT NUMERO FROM G_SELO_GRUPO
            WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID
            INTO :V_ID_ATO_ISENTADO;
  
            V_SELO_GRUPO_ID = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
          END
  
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
          AND L.ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
          INTO :V_QUANTIDADE_EMITIDA;
          IF (COALESCE(:V_QUANTIDADE_EMITIDA,0) = 0) THEN
          BEGIN                
            --SELECIONAR PROXIMO SELO PARA O PEDIDO
            SELECT FIRST 1 SELO_LIVRO_ID, NUMERO_SELO FROM G_SELO_LIVRO
            WHERE SELO_SITUACAO_ID = 1 
            AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                 WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID) 
            ORDER BY SELO_LIVRO_ID
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;
            
            IF (COALESCE(:V_NUMERO_AGRUPADOR_PED_CERTIDAO,'') = '') THEN
            BEGIN              
              V_NUMERO_AGRUPADOR_PED_CERTIDAO = :V_NUMERO_SELO;
            END          
                    
            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = :V_DATA,
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = 0,
                VALOR_EMOLUMENTO = 0,
                VALOR_TAXA_JUDICIARIA = 0,
                VALOR_FUNDESP = 0,
                DESCRICAO = :V_DESCRICAO_SELO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;
          END
        END

        --GRAVAR SELO ATOS ACRESCIDOS
        IF ((COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0) > 0) AND (COALESCE(V_SELO_GRUPO_ID_ATOS_ACRESCIDOS,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;
                
          V_ID_ATO_ISENTADO = 0;
          IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
          BEGIN
            SELECT NUMERO FROM G_SELO_GRUPO
            WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS
            INTO :V_ID_ATO_ISENTADO;
  
            V_SELO_GRUPO_ID_ATOS_ACRESCIDOS = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
          END
  
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS
          AND L.ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
          INTO :V_QUANTIDADE_EMITIDA;
  
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_ATOS_ACRESCIDOS) DO
          BEGIN                
            --SELECIONAR PROXIMO SELO PARA O PEDIDO
            SELECT FIRST 1 SELO_LIVRO_ID, NUMERO_SELO FROM G_SELO_LIVRO
            WHERE SELO_SITUACAO_ID = 1 
            AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                 WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS) 
            ORDER BY SELO_LIVRO_ID
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;
          
            IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
            BEGIN
              SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
              WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
              AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
              AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
              AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
              INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
            END                  
            
            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = :V_DATA,
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = 0,
                VALOR_EMOLUMENTO = 0,
                VALOR_TAXA_JUDICIARIA = 0, 
                VALOR_FUNDESP = 0,
                DESCRICAO = :V_DESCRICAO_SELO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    

            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;

          END
        END
        
        --GRAVAR SELO ATOS ACRESCIDOS - COMPLEMENTO
        IF ((COALESCE(:V_QUANTIDADE_ATOS_ACRESC_COMP,0) > 0) AND (COALESCE(V_SELO_GRUPO_ID_ATOS_ACRESC_COMP,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;
  
          V_ID_ATO_ISENTADO = 0;
          IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
          BEGIN
            SELECT NUMERO FROM G_SELO_GRUPO
            WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP
            INTO :V_ID_ATO_ISENTADO;
  
            V_SELO_GRUPO_ID_ATOS_ACRESC_COMP = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
          END
                
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP
          AND L.ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
          INTO :V_QUANTIDADE_EMITIDA;
          
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_ATOS_ACRESC_COMP) DO
          BEGIN                
            --SELECIONAR PROXIMO SELO PARA O PEDIDO
            SELECT FIRST 1 SELO_LIVRO_ID, NUMERO_SELO FROM G_SELO_LIVRO
            WHERE SELO_SITUACAO_ID = 1 
            AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                 WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP) 
            ORDER BY SELO_LIVRO_ID
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;
          
            IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
            BEGIN
              SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
              WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
              AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
              AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
              AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
              INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
            END                  
            
            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = :V_DATA,
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = 0,
                VALOR_EMOLUMENTO = 0,
                VALOR_TAXA_JUDICIARIA = 0, 
                VALOR_FUNDESP = 0,
                DESCRICAO = :V_DESCRICAO_SELO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    

            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END
        END      

        --GRAVAR SELO QUESITOS
        IF ((COALESCE(:V_QUANTIDADE_QUESITOS,0) > 0) AND (COALESCE(:V_SELO_GRUPO_ID_QUESITOS,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;      
  
          V_ID_ATO_ISENTADO = 0;
          IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
          BEGIN
            SELECT NUMERO FROM G_SELO_GRUPO
            WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS
            INTO :V_ID_ATO_ISENTADO;
  
            V_SELO_GRUPO_ID_QUESITOS = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
          END
        
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS
          AND L.ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
          INTO :V_QUANTIDADE_EMITIDA;
          
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_QUESITOS) DO
          BEGIN                
            --SELECIONAR PROXIMO SELO PARA O PEDIDO
            SELECT FIRST 1 SELO_LIVRO_ID, NUMERO_SELO FROM G_SELO_LIVRO
            WHERE SELO_SITUACAO_ID = 1 
            AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                 WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS) 
            ORDER BY SELO_LIVRO_ID
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;
          
            IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
            BEGIN
              SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
              WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
              AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
              AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
              AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
              INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
            END                  
            
            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = :V_DATA,
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = 0,
                VALOR_EMOLUMENTO = 0,
                VALOR_TAXA_JUDICIARIA = 0, 
                VALOR_FUNDESP = 0,
                DESCRICAO = :V_DESCRICAO_SELO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    

            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END                
        END

        --GRAVAR SELO QUESITOS - COMPLEMENTO
        IF ((COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0) > 0) AND (COALESCE(:V_SELO_GRUPO_ID_QUESITOS_COMP,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;      
  
          V_ID_ATO_ISENTADO = 0;
          IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
          BEGIN
            SELECT NUMERO FROM G_SELO_GRUPO
            WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS_COMP
            INTO :V_ID_ATO_ISENTADO;
  
            V_SELO_GRUPO_ID_QUESITOS_COMP = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
          END
        
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS_COMP
          AND L.ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
          INTO :V_QUANTIDADE_EMITIDA;
          
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_QUESITOS_COMP) DO
          BEGIN                
            --SELECIONAR PROXIMO SELO PARA O PEDIDO
            SELECT FIRST 1 SELO_LIVRO_ID, NUMERO_SELO FROM G_SELO_LIVRO
            WHERE SELO_SITUACAO_ID = 1 
            AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                 WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS_COMP) 
            ORDER BY SELO_LIVRO_ID
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;
          
            IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
            BEGIN
              SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
              WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
              AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
              AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
              AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
              INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
            END                  
            
            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = :V_DATA,
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = 0,
                VALOR_EMOLUMENTO = 0,
                VALOR_TAXA_JUDICIARIA = 0, 
                VALOR_FUNDESP = 0,
                DESCRICAO = :V_DESCRICAO_SELO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    

            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END                  
        END
      END
      ELSE
      BEGIN
      --NAO ISENTADOS
        V_VALOR_EMOLUMENTO_BASE = 0;
        V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS = 0;
        V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP = 0;
        V_VALOR_EMOLUMENTO_QUESITOS = 0;
        V_VALOR_EMOLUMENTO_QUESITOS_COMP = 0;
        V_SELO_GRUPO_ID_ATOS_ACRESCIDOS = 0;
        V_SELO_GRUPO_ID_ATOS_ACRESC_COMP = 0;
        V_SELO_GRUPO_ID_QUESITOS = 0;
        V_SELO_GRUPO_ID_QUESITOS_COMP = 0;      
        IF ((:V_QUANTIDADE_ATOS_ACRESCIDOS > 0) OR (:V_QUANTIDADE_QUESITOS > 0)) THEN
        BEGIN
          --VERIFICAR QUANTIDADE DE ATOS ACRESCIDOS E QUESITO E VER SE EXISTE COMPLEMENTO
          IF (:V_QUANTIDADE_ATOS_ACRESCIDOS > 6) THEN
          BEGIN
            V_QUANTIDADE_ATOS_ACRESCIDOS = 6;
            V_QUANTIDADE_ATOS_ACRESC_COMP = 1;
          END
          IF (:V_QUANTIDADE_QUESITOS > 3) THEN
          BEGIN
            V_QUANTIDADE_QUESITOS = 3;
            V_QUANTIDADE_QUESITOS_COMP = 1;
          END
          --PEGAR VALOR BASE DE EMOLUMENTOS
          SELECT COALESCE(VALOR_EMOLUMENTO,0)
          FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID, :V_EMOLUMENTO_PERIODO_ID, 0)
          INTO :V_VALOR_EMOLUMENTO_BASE;
          --PEGAR VALORES DE EMOLUMENTOS DE ATOS ACRESCIDOS
          IF (COALESCE(:V_EMOLUMENTO_ID_ATOS_ACRESCIDOS,0) > 0) THEN
          BEGIN
            SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRESCIDOS, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS, :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS;
          END
          ELSE
          BEGIN
            V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS = 0;
            V_SELO_GRUPO_ID_ATOS_ACRESCIDOS = 0;
          END
          
          --PEGAR VALORES DE EMOLUMENTOS DE COMPLEMENTO DE ATOS ACRESCIDOS
          IF (COALESCE(:V_EMOLUMENTO_ID_ATOS_ACRESC_COMP,0) > 0) THEN
          BEGIN
            SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_ATOS_ACRESC_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP, :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP;
          END
          ELSE
          BEGIN
            V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP = 0;
            V_SELO_GRUPO_ID_ATOS_ACRESC_COMP = 0;
          END
          --PEGAR VALORES DE EMOLUMENTOS DE QUESITOS
          IF (:V_EMOLUMENTO_ID_QUESITOS > 0) THEN
          BEGIN
            SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_VALOR_EMOLUMENTO_QUESITOS, :V_SELO_GRUPO_ID_QUESITOS;
          END
          ELSE
          BEGIN
            V_VALOR_EMOLUMENTO_QUESITOS = 0;
            V_SELO_GRUPO_ID_QUESITOS = 0;
          END          
          --PEGAR VALORES DE EMOLUMENTOS DE COMPLEMENTO DE QUESITOS
          IF (:V_EMOLUMENTO_ID_QUESITOS_COMP > 0) THEN
          BEGIN
            SELECT COALESCE(VALOR_EMOLUMENTO,0), COALESCE(SELO_GRUPO_ID,0)
            FROM G_BUSCAR_EMOLUMENTO(:V_EMOLUMENTO_ID_QUESITOS_COMP, :V_EMOLUMENTO_PERIODO_ID, 0)
            INTO :V_VALOR_EMOLUMENTO_QUESITOS_COMP, :V_SELO_GRUPO_ID_QUESITOS_COMP;
          END
          ELSE
          BEGIN
            V_VALOR_EMOLUMENTO_QUESITOS_COMP = 0;
            V_SELO_GRUPO_ID_QUESITOS_COMP = 0;
          END          
          V_VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO_BASE;
        END
        ELSE
        BEGIN
          V_VALOR_EMOLUMENTO = CAST((:V_VALOR_EMOLUMENTO_TEMP / :V_QUANTIDADE) AS NUMERIC(14,2));      
        END      
        --VALOR DE TAXA JUDICIARIA
        IF (:V_VALOR_TAXA_JUDICIARIA > 0) THEN
        BEGIN
          V_VALOR_TAXA_JUDICIARIA = CAST((:V_VALOR_TAXA_JUDICIARIA / :V_QUANTIDADE) AS NUMERIC(14,2));
        END

        V_ID_ATO_ISENTADO = 0;

        --GRAVAR SELO DE CERTIDAO
        V_NUMERO_AGRUPADOR_PED_CERTIDAO = ''; 
        FOR SELECT PEDIDO_ITEM_NUMERO_ID FROM R_PEDIDO_ITEM_NUMERO 
            WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
            INTO :V_PEDIDO_ITEM_NUMERO_ID DO
        BEGIN
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
          INTO :V_QUANTIDADE_EMITIDA;
          IF (COALESCE(:V_QUANTIDADE_EMITIDA,0) = 0) THEN
          BEGIN                
            --SELECIONAR PROXIMO SELO PARA O PEDIDO
            SELECT FIRST 1 SELO_LIVRO_ID, NUMERO_SELO FROM G_SELO_LIVRO
            WHERE SELO_SITUACAO_ID = 1 
            AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                 WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID) 
            ORDER BY SELO_LIVRO_ID
            INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;
            
            IF (COALESCE(:V_NUMERO_AGRUPADOR_PED_CERTIDAO,'') = '') THEN
            BEGIN              
              V_NUMERO_AGRUPADOR_PED_CERTIDAO = :V_NUMERO_SELO;
            END          

            --CALCULAR FUNDO
            V_VALOR_FUNDO_RI = CAST((COALESCE(:V_VALOR_EMOLUMENTO,0)*0.10) AS NUMERIC(14,3));
            V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO,0) + COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

            UPDATE G_SELO_LIVRO
            SET SELO_SITUACAO_ID = 2,
                DATA = :V_DATA,
                TABELA = 'R_PEDIDO_ITEM_NUMERO',
                CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                APRESENTANTE = :V_APRESENTANTE_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = :V_VALOR_TOTAL, 
                VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO, 
                VALOR_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA, 
                VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                DESCRICAO = :V_DESCRICAO_SELO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;
          END
        END
        V_TOTAL_INDIVIDUAL_ACUMULADO = :V_VALOR_EMOLUMENTO;
        
        --GRAVAR SELO ATOS ACRESCIDOS
        IF ((COALESCE(:V_QUANTIDADE_ATOS_ACRESCIDOS,0) > 0) AND (COALESCE(V_SELO_GRUPO_ID_ATOS_ACRESCIDOS,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;

          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS
          INTO :V_QUANTIDADE_EMITIDA;
          
          V_TOTAL_INDIVIDUAL_ACUMULADO = :V_TOTAL_INDIVIDUAL_ACUMULADO + (COALESCE(V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS,0)*COALESCE(:V_QUANTIDADE_EMITIDA,0));
  
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_ATOS_ACRESCIDOS) DO
          BEGIN                
            IF (:V_TOTAL_INDIVIDUAL_ACUMULADO < :V_VALOR_EMOLUMENTO_TEMP) THEN
            BEGIN
              --SELECIONAR PROXIMO SELO PARA O PEDIDO
              SELECT FIRST 1 SELO_LIVRO_ID, NUMERO_SELO FROM G_SELO_LIVRO
              WHERE SELO_SITUACAO_ID = 1 
              AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                   WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESCIDOS) 
              ORDER BY SELO_LIVRO_ID
              INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;
            
              IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
              BEGIN
                SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
                WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
                AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
                AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
                AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
                INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
              END                  
              
              IF ((COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS,0)) > :V_VALOR_EMOLUMENTO_TEMP) THEN
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST((COALESCE((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)),0)*0.10) AS NUMERIC(14,3));
                V_VALOR_TOTAL = COALESCE((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)),0) + COALESCE(:V_VALOR_FUNDO_RI,0);

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = :V_DATA,
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = (COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)), 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    DESCRICAO = :V_DESCRICAO_SELO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    
              END
              ELSE
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST((COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS,0)*0.10) AS NUMERIC(14,3));
                V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = :V_DATA,
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS, 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    DESCRICAO = :V_DESCRICAO_SELO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                              
              END
              V_TOTAL_INDIVIDUAL_ACUMULADO = COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESCIDOS,0);
            END                
            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END
        END
        
        --GRAVAR SELO ATOS ACRESCIDOS - COMPLEMENTO
        IF ((COALESCE(:V_QUANTIDADE_ATOS_ACRESC_COMP,0) > 0) AND (COALESCE(V_SELO_GRUPO_ID_ATOS_ACRESC_COMP,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;
  
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP
          INTO :V_QUANTIDADE_EMITIDA;
          
          V_TOTAL_INDIVIDUAL_ACUMULADO = :V_TOTAL_INDIVIDUAL_ACUMULADO + (COALESCE(V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP,0)*COALESCE(:V_QUANTIDADE_EMITIDA,0));
  
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_ATOS_ACRESC_COMP) DO
          BEGIN                
            IF (:V_TOTAL_INDIVIDUAL_ACUMULADO < :V_VALOR_EMOLUMENTO_TEMP) THEN
            BEGIN
              --SELECIONAR PROXIMO SELO PARA O PEDIDO
              SELECT FIRST 1 SELO_LIVRO_ID, NUMERO_SELO FROM G_SELO_LIVRO
              WHERE SELO_SITUACAO_ID = 1 
              AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                   WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_ATOS_ACRESC_COMP) 
              ORDER BY SELO_LIVRO_ID
              INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;
            
              IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
              BEGIN
                SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
                WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
                AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
                AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
                AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
                INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
              END                  
              
              IF ((COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP,0)) > :V_VALOR_EMOLUMENTO_TEMP) THEN
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST(((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0))*0.10) AS NUMERIC(14,3));
                V_VALOR_TOTAL = (COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)) + COALESCE(:V_VALOR_FUNDO_RI,0);

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = :V_DATA,
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = (COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)), 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    DESCRICAO = :V_DESCRICAO_SELO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    
              END
              ELSE
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST((COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP,0)*0.10) AS NUMERIC(14,3));
                V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = :V_DATA,
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP, 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    DESCRICAO = :V_DESCRICAO_SELO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                              
              END
              V_TOTAL_INDIVIDUAL_ACUMULADO = COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_ATOS_ACRESC_COMP,0);
            END                
            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END
        END      
        --GRAVAR SELO QUESITOS
        IF ((COALESCE(:V_QUANTIDADE_QUESITOS,0) > 0) AND (COALESCE(:V_SELO_GRUPO_ID_QUESITOS,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;      
  
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS
          INTO :V_QUANTIDADE_EMITIDA;
          
          V_TOTAL_INDIVIDUAL_ACUMULADO = :V_TOTAL_INDIVIDUAL_ACUMULADO + (COALESCE(V_VALOR_EMOLUMENTO_QUESITOS,0)*COALESCE(:V_QUANTIDADE_EMITIDA,0));
  
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_QUESITOS) DO
          BEGIN                
            IF (:V_TOTAL_INDIVIDUAL_ACUMULADO < :V_VALOR_EMOLUMENTO_TEMP) THEN
            BEGIN
              --SELECIONAR PROXIMO SELO PARA O PEDIDO
              SELECT FIRST 1 SELO_LIVRO_ID, NUMERO_SELO FROM G_SELO_LIVRO
              WHERE SELO_SITUACAO_ID = 1 
              AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                   WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS) 
              ORDER BY SELO_LIVRO_ID
              INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;
            
              IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
              BEGIN
                SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
                WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
                AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
                AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
                AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
                INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
              END                  
              
              IF ((COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS,0)) > :V_VALOR_EMOLUMENTO_TEMP) THEN
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST(((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0))*0.10) AS NUMERIC(14,3));
                V_VALOR_TOTAL = (COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)) + COALESCE(:V_VALOR_FUNDO_RI,0);

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = :V_DATA,
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = (COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)), 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    DESCRICAO = :V_DESCRICAO_SELO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    
              END
              ELSE
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST((COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS,0)*0.10) AS NUMERIC(14,3));
                V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = :V_DATA,
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO_QUESITOS, 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    DESCRICAO = :V_DESCRICAO_SELO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                              
              END
              V_TOTAL_INDIVIDUAL_ACUMULADO = COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS,0);
            END                
            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END                  
        END
        --GRAVAR SELO QUESITOS - COMPLEMENTO
        IF ((COALESCE(:V_QUANTIDADE_QUESITOS_COMP,0) > 0) AND (COALESCE(:V_SELO_GRUPO_ID_QUESITOS_COMP,0) > 0)) THEN
        BEGIN
          SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID 
          FROM R_PEDIDO_ITEM_NUMERO
          WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
          ORDER BY PEDIDO_ITEM_NUMERO_ID
          INTO :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO;      
  
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO L, G_SELO_LOTE L2
          WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
          AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
          AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
          AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS_COMP
          INTO :V_QUANTIDADE_EMITIDA;
          
          V_TOTAL_INDIVIDUAL_ACUMULADO = :V_TOTAL_INDIVIDUAL_ACUMULADO + (COALESCE(V_VALOR_EMOLUMENTO_QUESITOS_COMP,0)*COALESCE(:V_QUANTIDADE_EMITIDA,0));
  
          WHILE (COALESCE(:V_QUANTIDADE_EMITIDA,0) < :V_QUANTIDADE_QUESITOS_COMP) DO
          BEGIN                
            IF (:V_TOTAL_INDIVIDUAL_ACUMULADO < :V_VALOR_EMOLUMENTO_TEMP) THEN
            BEGIN
              --SELECIONAR PROXIMO SELO PARA O PEDIDO
              SELECT FIRST 1 SELO_LIVRO_ID, NUMERO_SELO FROM G_SELO_LIVRO
              WHERE SELO_SITUACAO_ID = 1 
              AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                   WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID_QUESITOS_COMP) 
              ORDER BY SELO_LIVRO_ID
              INTO :V_SELO_LIVRO_ID, :V_NUMERO_SELO;
            
              IF (:V_NUMERO_AGRUPADOR_PED_CERTIDAO = '') THEN
              BEGIN
                SELECT FIRST 1 L.NUMERO_AGRUPADOR FROM G_SELO_LIVRO L, G_SELO_LOTE L2
                WHERE L.SELO_LOTE_ID = L2.SELO_LOTE_ID
                AND L.TABELA = 'R_PEDIDO_ITEM_NUMERO'
                AND L.CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO
                AND L2.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
                INTO :V_NUMERO_AGRUPADOR_PED_CERTIDAO;
              END                  
              
              IF ((COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS_COMP,0)) > :V_VALOR_EMOLUMENTO_TEMP) THEN
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST(((COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0))*0.10) AS NUMERIC(14,3));
                V_VALOR_TOTAL = (COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)) + COALESCE(:V_VALOR_FUNDO_RI,0);

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = :V_DATA,
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = (COALESCE(:V_VALOR_EMOLUMENTO_TEMP,0) - COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0)), 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    DESCRICAO = :V_DESCRICAO_SELO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                    
              END
              ELSE
              BEGIN
                --CALCULAR FUNDO
                V_VALOR_FUNDO_RI = CAST((COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS_COMP,0)*0.10) AS NUMERIC(14,3));
                V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS_COMP,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

                UPDATE G_SELO_LIVRO
                SET SELO_SITUACAO_ID = 2,
                    DATA = :V_DATA,
                    TABELA = 'R_PEDIDO_ITEM_NUMERO',
                    CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID_PRIMEIRO,
                    USUARIO_ID = :V_USUARIO_ID,
                    NUMERO_AGRUPADOR = :V_NUMERO_AGRUPADOR_PED_CERTIDAO, 
                    APRESENTANTE = :V_APRESENTANTE_NOME, 
                    IP_MAQUINA = :V_IP_MAQUINA,
                    VALOR_TOTAL = :V_VALOR_TOTAL,
                    VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO_QUESITOS_COMP, 
                    VALOR_TAXA_JUDICIARIA = 0, 
                    VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                    DESCRICAO = :V_DESCRICAO_SELO
                WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;                              
              END
              V_TOTAL_INDIVIDUAL_ACUMULADO = COALESCE(:V_TOTAL_INDIVIDUAL_ACUMULADO,0) + COALESCE(:V_VALOR_EMOLUMENTO_QUESITOS_COMP,0);
            END                
            V_QUANTIDADE_EMITIDA = :V_QUANTIDADE_EMITIDA + 1;
          END                  
        END
      END
    END
  END
  SUSPEND;
END ^

ALTER PROCEDURE R_SELAR_PROTOCOLO_GO (V_PEDIDO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_CHAVE VARCHAR(30) CHARACTER SET ISO8859_1,
V_USUARIO_ID VARCHAR(20) CHARACTER SET ISO8859_1,
V_NATUREZA_FORMAL_TAXA_JUD VARCHAR(10) CHARACTER SET ISO8859_1,
V_IP_MAQUINA VARCHAR(30) CHARACTER SET ISO8859_1)
RETURNS (STATUS CHAR(1) CHARACTER SET ISO8859_1)
AS 
declare variable V_PEDIDO_ITEM_ID integer;
declare variable V_PEDIDO_ITEM_NUMERO_ID integer;
declare variable V_QUANTIDADE integer;
declare variable V_SELO_GRUPO_ID integer;
declare variable V_APRESENTANTE_NOME varchar(120);
declare variable V_ADQUIRENTE_NOME varchar(120);
declare variable V_NOME varchar(120);
declare variable V_VALOR_EMOLUMENTO numeric(18,3);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(18,3);
declare variable V_VALOR_FUNDO_RI numeric(18,3);
declare variable V_VALOR_ISS numeric(18,3);
declare variable V_VALOR_TOTAL numeric(18,3);
declare variable V_VALOR_DESCONTO numeric(18,3);
declare variable V_PORCENTAGEM_DESCONTO numeric(18,3);
declare variable V_TIPO_TITULO varchar(60);
declare variable V_COUNT integer;
declare variable V_NUMERO_GRUPO integer;
declare variable V_DESCRICAO_EMOLUMENTO varchar(260);
declare variable V_SELO_LIVRO_ID integer;
declare variable V_SIGLA varchar(30);
--declare variable V_NUMERO integer;
declare variable V_NUMERO_SELO VARCHAR(60);
declare variable V_NUMERO_STRING varchar(6);
declare variable V_NUMERO_AGRUPADOR_PROTOCOLO varchar(50);
declare variable I integer;
declare variable J integer;
declare variable V_ENVIOU_TAXA char(1);
declare variable V_TAMANHO integer;
declare variable V_QUANTIDADE_EMITIDA integer;
declare variable PEDIDO_ITEM_ID_AUX integer;
declare variable PEDIDO_ITEM_ID_ANTERIOR_AUX integer;
declare variable V_SIGLA_AUX varchar(30);
declare variable V_NUMERO_AUX integer;
declare variable V_DESCRICAO_SELO varchar(120);
declare variable V_ID_ATO_ISENTADO numeric(14,2);
declare variable V_EH_ISENTO varchar(1);
declare variable V_RI_ISENCAO_SELO_GRUPO_ID varchar(10);
declare variable V_DATA_SELO_NOVO_STR varchar(30);
declare variable V_DATA_SELO_NOVO date;
declare variable V_DATA_PROTOCOLO date;
declare variable V_NOVO_ANTIGO integer; /* 1 novo, 2 antigo */
declare variable V_QUANTIDADE_EMITIDA_ANTIGA integer;
declare variable V_QTDE_TEMP integer;
declare variable V_EH_AGRUPADOR varchar(6);
declare variable V_QTDE_LOTE_COM_AGRUPADOR integer;
declare variable V_PERCENTUAL_FUNDOS_ESTADUAIS numeric(18,4);
BEGIN
  STATUS = 'T';
  V_ENVIOU_TAXA = 'F';
  V_NUMERO_AGRUPADOR_PROTOCOLO = '';
  V_EH_AGRUPADOR = '';
  IF (:V_NATUREZA_FORMAL_TAXA_JUD = '') THEN
  BEGIN
    V_NATUREZA_FORMAL_TAXA_JUD = NULL;
  END

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'RI_ISENCAO_SELO_GRUPO_ID', 5) INTO :V_RI_ISENCAO_SELO_GRUPO_ID;

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'PERCENTUAL_FUNDOS_ESTADUAIS', 5) INTO :V_PERCENTUAL_FUNDOS_ESTADUAIS;
  if (COALESCE(:V_PERCENTUAL_FUNDOS_ESTADUAIS,0) = 0) then
  BEGIN
    V_PERCENTUAL_FUNDOS_ESTADUAIS = 40;
  END
  V_PERCENTUAL_FUNDOS_ESTADUAIS = (:V_PERCENTUAL_FUNDOS_ESTADUAIS/100);

  --PEGAR DATA DO PROTOCOLO
  SELECT CAST(DATA AS DATE) FROM R_PROTOCOLO
  WHERE ((TIPO_PROTOCOLO = '1') or (TIPO_PROTOCOLO = '3'))
  AND PEDIDO_ID = :V_PEDIDO_ID
  INTO :V_DATA_PROTOCOLO;

  SELECT COUNT(*) FROM RDB$RELATIONS
  WHERE RDB$SYSTEM_FLAG = 0
  AND RDB$RELATION_NAME = 'G_SELO_LIVRO_ANTIGO'
  INTO V_QTDE_TEMP;

  SELECT COALESCE(VALOR_PARAMETRO,'') FROM G_BUSCAR_CONFIG('SELO','GOIAS','DATA_SELO_NOVO',5)
  INTO :V_DATA_SELO_NOVO_STR;

  if (:V_DATA_SELO_NOVO_STR = '12/31/1899') then
  BEGIN
    V_DATA_SELO_NOVO_STR = '';
  END
  if (:V_DATA_SELO_NOVO_STR <> '') then
  BEGIN
    V_DATA_SELO_NOVO = CAST(V_DATA_SELO_NOVO_STR AS DATE);
  END
  else
  begin
    V_DATA_SELO_NOVO = '31.12.2099';
  end

  FOR SELECT PI.PEDIDO_ITEM_ID, COALESCE(PI.QUANTIDADE,0) QUANTIDADE, I.SELO_GRUPO_ID, 
        PE.APRESENTANTE_NOME, PE.ADQUIRENTE_NOME, COALESCE(PI.VALOR_EMOLUMENTO,0) VALOR_EMOLUMENTO, 
        COALESCE(PI.VALOR_TAXA_JUDICIARIA,0) VALOR_TAXA_JUDICIARIA, 
        COALESCE(PI.VALOR_FUNDO_RI,0) VALOR_FUNDO_RI, N.TIPO_TITULO, E.DESCRICAO,      
        COALESCE(PI.VALOR_DESCONTO,0) VALOR_DESCONTO,
        COALESCE(PI.PORCENTAGEM_DESCONTO,0) PORCENTAGEM_DESCONTO,
        PI.EH_ISENTO, COALESCE(PI.VALOR_ISS,0) VALOR_ISS, S.AGRUPADOR,
        'PROTOCOLO: '||CAST(PR.NUMERO_ORDEM AS INTEGER)||', '|| SUBSTRING(N.DESCRICAO FROM 1 FOR 100)
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, G_EMOLUMENTO E, 
        G_EMOLUMENTO_ITEM I, G_SELO_GRUPO S, G_NATUREZA_TITULO N 
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.PEDIDO_ID = PI.PEDIDO_ID       
      AND PI.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID 
      AND PI.EMOLUMENTO_ITEM_ID = I.EMOLUMENTO_ITEM_ID
      AND I.EMOLUMENTO_ID = E.EMOLUMENTO_ID
      AND I.SELO_GRUPO_ID = S.SELO_GRUPO_ID 
      AND PE.PEDIDO_ID = :V_PEDIDO_ID
      AND PR.TIPO_PROTOCOLO = '1'
      AND (PI.EXCLUI_DO_RELATORIO = 'N' OR PI.EXCLUI_DO_RELATORIO IS NULL OR PI.EXCLUI_DO_RELATORIO = '')       
      ORDER BY S.AGRUPADOR DESC, PI.PEDIDO_ITEM_ID ASC
      INTO :V_PEDIDO_ITEM_ID, :V_QUANTIDADE, :V_SELO_GRUPO_ID, 
        :V_APRESENTANTE_NOME, :V_ADQUIRENTE_NOME, :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, 
        :V_VALOR_FUNDO_RI, :V_TIPO_TITULO, :V_DESCRICAO_EMOLUMENTO,
        :V_VALOR_DESCONTO, :V_PORCENTAGEM_DESCONTO, :V_EH_ISENTO, :V_VALOR_ISS, :V_EH_AGRUPADOR, :V_DESCRICAO_SELO DO
  BEGIN    
    IF (:V_QUANTIDADE > 0) THEN
    BEGIN           
      --VALOR DE EMOLUMENTO
      IF (:V_VALOR_EMOLUMENTO > 0) THEN
      BEGIN
        V_VALOR_EMOLUMENTO = (CAST((:V_VALOR_EMOLUMENTO / :V_QUANTIDADE) AS NUMERIC(14,2)));
      END
           
      --FUNDO
      IF (:V_VALOR_FUNDO_RI > 0) THEN
      BEGIN
        V_VALOR_FUNDO_RI = CAST((:V_VALOR_FUNDO_RI / :V_QUANTIDADE) AS NUMERIC(14,3));
      END
      ELSE
      BEGIN
        V_VALOR_FUNDO_RI = CAST((COALESCE(:V_VALOR_EMOLUMENTO,0)*(:V_PERCENTUAL_FUNDOS_ESTADUAIS)) AS NUMERIC(14,3));
      END                

      --FUNDO
      IF (:V_VALOR_ISS > 0) THEN
      BEGIN
        V_VALOR_ISS = CAST((:V_VALOR_ISS / :V_QUANTIDADE) AS NUMERIC(14,3));
      END

      V_ID_ATO_ISENTADO = 0;
      IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
      BEGIN
        SELECT NUMERO FROM G_SELO_GRUPO
        WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID
        INTO :V_ID_ATO_ISENTADO;

        V_SELO_GRUPO_ID = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
      END
      
      V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO,0) + COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

      SELECT COUNT(PI.PEDIDO_ITEM_ID) FROM R_PEDIDO_ITEM PI, R_SELAR_PROTOCOLO SP
      WHERE PI.pedido_item_id = SP.pedido_item_id
      and sp.chave = :V_CHAVE
      AND PI.PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
      INTO :V_COUNT;

      IF ((:V_COUNT = 0)) THEN
      BEGIN
        SELECT COUNT(PI.PEDIDO_ITEM_ID) FROM R_PEDIDO_ITEM PI, R_SELAR_PROTOCOLO SP
        WHERE PI.pedido_id = SP.pedido_id
        and sp.chave = :V_CHAVE
        AND PI.PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
        INTO :V_COUNT;
      END

      IF ((:V_COUNT > 0)) THEN
      BEGIN
        --pegar agrupador
        V_NUMERO_AGRUPADOR_PROTOCOLO = '';
        SELECT FIRST 1 COALESCE(SELO_AGRUPADOR,'') FROM R_SELAR_PROTOCOLO
        WHERE CHAVE = :V_CHAVE
        ORDER BY SELO_AGRUPADOR DESC
        INTO :V_NUMERO_AGRUPADOR_PROTOCOLO;

        I = 0;
        WHILE (I < :V_QUANTIDADE) DO
        BEGIN
          --verificar quantidade de selos ja emitidos
          V_QUANTIDADE_EMITIDA_ANTIGA = 0;
          if ((:V_QTDE_TEMP > 0) AND (:V_DATA_PROTOCOLO < (:V_DATA_SELO_NOVO+1))) then --SE EXISTIR TABELAS G_SELO_LIVRO_ANTIGO E DATA DO PROTOCOLO FOR ANTERIOR A DATA DO SELO NOVO
          BEGIN
            EXECUTE STATEMENT 'SELECT COUNT(*) FROM G_SELO_LIVRO_ANTIGO
                               WHERE TABELA = '||'''R_PEDIDO_ITEM'''||'
                               AND COALESCE(SELO_SITUACAO_ID,0) = 2
                               AND CAMPO_ID = '||:V_PEDIDO_ITEM_ID
            INTO :V_QUANTIDADE_EMITIDA_ANTIGA;
          END

          SELECT COUNT(*) FROM G_SELO_LIVRO
          WHERE TABELA = 'R_PEDIDO_ITEM'
          AND CAMPO_ID = :V_PEDIDO_ITEM_ID
          AND COALESCE(SELO_SITUACAO_ID,0) = 2
          INTO :V_QUANTIDADE_EMITIDA;

          V_QUANTIDADE_EMITIDA = COALESCE(:V_QUANTIDADE_EMITIDA,0) + COALESCE(:V_QUANTIDADE_EMITIDA_ANTIGA,0);

          IF (:V_QUANTIDADE_EMITIDA < :V_QUANTIDADE) THEN
          BEGIN        
            --verificar qtde de lotes com o agruapdor
            V_QTDE_LOTE_COM_AGRUPADOR = 0;
            if (coalesce(:V_NUMERO_AGRUPADOR_PROTOCOLO,'') <> '') then
            begin
              SELECT COUNT(*)
              FROM G_SELO_LIVRO LV, G_SELO_LOTE LT, G_SELO_GRUPO GP
              WHERE LV.SELO_SITUACAO_ID = 1
              AND LV.SELO_LOTE_ID = LT.SELO_LOTE_ID
              AND LT.SELO_GRUPO_ID = GP.SELO_GRUPO_ID
              AND GP.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
              AND LT.NUMERO_SELO_PRENOTACAO = :V_NUMERO_AGRUPADOR_PROTOCOLO
              INTO :V_QTDE_LOTE_COM_AGRUPADOR;
            end

            if (coalesce(V_QTDE_LOTE_COM_AGRUPADOR,0) > 0) then
            begin
              --SELECIONAR PROXIMO SELO PARA O PROTOCOLO
              SELECT FIRST 1 LV.SELO_LIVRO_ID, LV.SIGLA, LV.NUMERO_SELO
              FROM G_SELO_LIVRO LV, G_SELO_LOTE LT, G_SELO_GRUPO GP
              WHERE LV.SELO_SITUACAO_ID = 1
              AND LV.SELO_LOTE_ID = LT.SELO_LOTE_ID
              AND LT.SELO_GRUPO_ID = GP.SELO_GRUPO_ID
              AND GP.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
              AND LT.NUMERO_SELO_PRENOTACAO = :V_NUMERO_AGRUPADOR_PROTOCOLO
              ORDER BY LV.SELO_LOTE_ID, LV.SELO_LIVRO_ID
              INTO :V_SELO_LIVRO_ID, :V_SIGLA, :V_NUMERO_SELO;
            end
            else
            begin
              --SELECIONAR PROXIMO SELO PARA O PROTOCOLO
              SELECT FIRST 1 LV.SELO_LIVRO_ID, LV.SIGLA, LV.NUMERO_SELO
              FROM G_SELO_LIVRO LV, G_SELO_LOTE LT, G_SELO_GRUPO GP
              WHERE LV.SELO_SITUACAO_ID = 1
              AND LV.SELO_LOTE_ID = LT.SELO_LOTE_ID
              AND LT.SELO_GRUPO_ID = GP.SELO_GRUPO_ID
              AND GP.SELO_GRUPO_ID = :V_SELO_GRUPO_ID
              AND COALESCE(LT.NUMERO_SELO_PRENOTACAO,'') = ''
              ORDER BY LV.SELO_LOTE_ID, LV.SELO_LIVRO_ID
              INTO :V_SELO_LIVRO_ID, :V_SIGLA, :V_NUMERO_SELO;
            end

            if ((coalesce(:V_NUMERO_AGRUPADOR_PROTOCOLO,'') = '') and (coalesce(:V_EH_AGRUPADOR,'') = 'S')) then
            begin
              V_NUMERO_AGRUPADOR_PROTOCOLO = :V_NUMERO_SELO;
            end

            IF (COALESCE(:V_NUMERO_AGRUPADOR_PROTOCOLO,'') = '') THEN
            BEGIN
              --ver se ja existe um numero agrupador anterior
              if ((:V_QTDE_TEMP > 0) AND (:V_DATA_PROTOCOLO < (:V_DATA_SELO_NOVO+1))) then --SE EXISTIR TABELAS G_SELO_LIVRO_ANTIGO E DATA DO PROTOCOLO FOR ANTERIOR A DATA DO SELO NOVO
              BEGIN
                EXECUTE STATEMENT 'SELECT FIRST 1 NUMERO_AGRUPADOR FROM G_SELO_LIVRO_ANTIGO
                                   WHERE TABELA = '||'''R_PEDIDO_ITEM'''||'
                                   AND CAMPO_ID IN (SELECT PEDIDO_ITEM_ID FROM R_PEDIDO_ITEM
                                                    WHERE PEDIDO_ID = '||:V_PEDIDO_ID||')
                                   AND NUMERO_AGRUPADOR IS NOT NULL
                                   AND COALESCE(SELO_SITUACAO_ID,0) = 2
                                   AND COALESCE(NUMERO_AGRUPADOR,'''') <> '''''
                INTO :V_NUMERO_AGRUPADOR_PROTOCOLO;
              END
              IF (COALESCE(:V_NUMERO_AGRUPADOR_PROTOCOLO,'') = '') THEN
              BEGIN
                SELECT FIRST 1 SL.NUMERO_AGRUPADOR FROM G_SELO_LIVRO SL, R_PEDIDO_ITEM PI
                WHERE SL.TABELA = 'R_PEDIDO_ITEM'
                AND SL.CAMPO_ID = PI.PEDIDO_ITEM_ID
                AND PI.PEDIDO_ID = :V_PEDIDO_ID
                AND COALESCE(SL.NUMERO_AGRUPADOR,'') <> ''
                AND COALESCE(SL.SELO_SITUACAO_ID,0) = 2
                INTO :V_NUMERO_AGRUPADOR_PROTOCOLO;
              END
            END
            IF (COALESCE(:V_NUMERO_AGRUPADOR_PROTOCOLO,'') <> '') THEN
            BEGIN
              IF (TRIM(COALESCE(:V_ADQUIRENTE_NOME,'')) <> '') THEN
              BEGIN
                V_NOME = :V_ADQUIRENTE_NOME;
              END
              ELSE
              BEGIN
                V_NOME = :V_APRESENTANTE_NOME;
              END
                
              UPDATE G_SELO_LIVRO 
              SET SELO_SITUACAO_ID = 2,
                  DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                  TABELA = 'R_PEDIDO_ITEM',
                  CAMPO_ID = :V_PEDIDO_ITEM_ID,
                  USUARIO_ID = :V_USUARIO_ID,
                  NUMERO_AGRUPADOR = COALESCE(:V_NUMERO_AGRUPADOR_PROTOCOLO,''), 
                  APRESENTANTE = :V_NOME, 
                  IP_MAQUINA = :V_IP_MAQUINA,
                  VALOR_TOTAL = :V_VALOR_TOTAL, 
                  VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO, 
                  VALOR_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA, 
                  VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                  VALOR_ISS = :V_VALOR_ISS,
                  DESCRICAO = :V_DESCRICAO_SELO,
                  ID_DO_ATO_ISENTADO = :V_ID_ATO_ISENTADO
              WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;
            END
          END
          I = I + 1;
        END
      END
    END                  
  END
  DELETE FROM R_SELAR_PROTOCOLO
  WHERE CHAVE = :V_CHAVE;
  SUSPEND;
END ^

ALTER PROCEDURE R_SELAR_PROTOCOLO_GO_OLD (V_PEDIDO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_CHAVE VARCHAR(30) CHARACTER SET ISO8859_1,
V_USUARIO_ID VARCHAR(20) CHARACTER SET ISO8859_1,
V_NATUREZA_FORMAL_TAXA_JUD VARCHAR(10) CHARACTER SET ISO8859_1,
V_IP_MAQUINA VARCHAR(30) CHARACTER SET ISO8859_1,
V_DATA VARCHAR(20) CHARACTER SET ISO8859_1)
RETURNS (STATUS CHAR(1) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_PEDIDO_ITEM_ID INTEGER;
DECLARE VARIABLE V_PEDIDO_ITEM_NUMERO_ID INTEGER;
DECLARE VARIABLE V_QUANTIDADE INTEGER;
DECLARE VARIABLE V_SELO_GRUPO_ID INTEGER;
DECLARE VARIABLE V_APRESENTANTE_NOME VARCHAR(120);
DECLARE VARIABLE V_ADQUIRENTE_NOME VARCHAR(120);
DECLARE VARIABLE V_NOME VARCHAR(120);
DECLARE VARIABLE V_VALOR_EMOLUMENTO NUMERIC(18,3);
DECLARE VARIABLE V_VALOR_TAXA_JUDICIARIA NUMERIC(18,3);
DECLARE VARIABLE V_VALOR_FUNDO_RI NUMERIC(18,3);
DECLARE VARIABLE V_VALOR_TOTAL NUMERIC(18,3);
DECLARE VARIABLE V_VALOR_DESCONTO NUMERIC(18,3);
DECLARE VARIABLE V_PORCENTAGEM_DESCONTO NUMERIC(18,3);
DECLARE VARIABLE V_TIPO_TITULO VARCHAR(60);
DECLARE VARIABLE V_COUNT INTEGER;
DECLARE VARIABLE V_NUMERO_GRUPO INTEGER;
DECLARE VARIABLE V_DESCRICAO_EMOLUMENTO VARCHAR(260);
DECLARE VARIABLE V_SELO_LIVRO_ID INTEGER;
DECLARE VARIABLE V_SIGLA VARCHAR(30);
DECLARE VARIABLE V_NUMERO INTEGER;
DECLARE VARIABLE V_NUMERO_STRING VARCHAR(6);
DECLARE VARIABLE V_NUMERO_AGRUPADOR_PROTOCOLO VARCHAR(50);
DECLARE VARIABLE I INTEGER;
DECLARE VARIABLE J INTEGER;
DECLARE VARIABLE V_ENVIOU_TAXA CHAR(1);
DECLARE VARIABLE V_TAMANHO INTEGER;
DECLARE VARIABLE V_QUANTIDADE_EMITIDA INTEGER;
DECLARE VARIABLE PEDIDO_ITEM_ID_AUX INTEGER;
DECLARE VARIABLE PEDIDO_ITEM_ID_ANTERIOR_AUX INTEGER;
DECLARE VARIABLE V_SIGLA_AUX VARCHAR(30);
DECLARE VARIABLE V_NUMERO_AUX INTEGER;
DECLARE VARIABLE V_DESCRICAO_SELO VARCHAR(120);
DECLARE VARIABLE V_ID_ATO_ISENTADO NUMERIC(14,2);
DECLARE VARIABLE V_EH_ISENTO VARCHAR(1);
DECLARE VARIABLE V_RI_ISENCAO_SELO_GRUPO_ID VARCHAR(10);
BEGIN
  STATUS = 'T';
  V_ENVIOU_TAXA = 'F';
  V_NUMERO_AGRUPADOR_PROTOCOLO = '';
  IF (:V_NATUREZA_FORMAL_TAXA_JUD = '') THEN
  BEGIN
    V_NATUREZA_FORMAL_TAXA_JUD = NULL;
  END

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('SELO', 'GOIAS', 'RI_ISENCAO_SELO_GRUPO_ID', 5) INTO :V_RI_ISENCAO_SELO_GRUPO_ID;
  
  FOR SELECT PI.PEDIDO_ITEM_ID, COALESCE(PI.QUANTIDADE,0) QUANTIDADE, I.SELO_GRUPO_ID, 
        PE.APRESENTANTE_NOME, PE.ADQUIRENTE_NOME, COALESCE(PI.VALOR_EMOLUMENTO,0) VALOR_EMOLUMENTO, 
        COALESCE(PI.VALOR_TAXA_JUDICIARIA,0) VALOR_TAXA_JUDICIARIA, 
        COALESCE(PI.VALOR_FUNDO_RI,0) VALOR_FUNDO_RI, N.TIPO_TITULO, E.DESCRICAO,      
        COALESCE(PI.VALOR_DESCONTO,0) VALOR_DESCONTO,
        COALESCE(PI.PORCENTAGEM_DESCONTO,0) PORCENTAGEM_DESCONTO,
        PI.EH_ISENTO
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, G_EMOLUMENTO E, 
        G_EMOLUMENTO_ITEM I, G_SELO_GRUPO S, G_NATUREZA_TITULO N 
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.PEDIDO_ID = PI.PEDIDO_ID       
      AND PI.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID 
      AND PI.EMOLUMENTO_ITEM_ID = I.EMOLUMENTO_ITEM_ID
      AND I.EMOLUMENTO_ID = E.EMOLUMENTO_ID
      AND I.SELO_GRUPO_ID = S.SELO_GRUPO_ID 
      AND PE.PEDIDO_ID = :V_PEDIDO_ID
      AND PR.TIPO_PROTOCOLO = '1'
      AND (PI.EXCLUI_DO_RELATORIO = 'N' OR PI.EXCLUI_DO_RELATORIO IS NULL OR PI.EXCLUI_DO_RELATORIO = '')       
      ORDER BY S.AGRUPADOR DESC, PI.PEDIDO_ITEM_ID ASC
      INTO :V_PEDIDO_ITEM_ID, :V_QUANTIDADE, :V_SELO_GRUPO_ID, 
        :V_APRESENTANTE_NOME, :V_ADQUIRENTE_NOME, :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, 
        :V_VALOR_FUNDO_RI, :V_TIPO_TITULO, :V_DESCRICAO_EMOLUMENTO,
        :V_VALOR_DESCONTO, :V_PORCENTAGEM_DESCONTO, :V_EH_ISENTO DO
  BEGIN    
    IF (:V_QUANTIDADE > 0) THEN
    BEGIN           
      --VALOR DE EMOLUMENTO
      IF (:V_VALOR_EMOLUMENTO > 0) THEN
      BEGIN
        V_VALOR_EMOLUMENTO = (CAST((:V_VALOR_EMOLUMENTO / :V_QUANTIDADE) AS NUMERIC(14,2)));
      END
           
      --FUNDO
      IF (:V_VALOR_FUNDO_RI > 0) THEN
      BEGIN
        V_VALOR_FUNDO_RI = CAST((:V_VALOR_FUNDO_RI / :V_QUANTIDADE) AS NUMERIC(14,3));
      END
      ELSE
      BEGIN
        V_VALOR_FUNDO_RI = CAST((COALESCE(:V_VALOR_EMOLUMENTO,0)*0.10) AS NUMERIC(14,3));
      END                

      V_ID_ATO_ISENTADO = 0;
      IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
      BEGIN
        SELECT NUMERO FROM G_SELO_GRUPO
        WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID
        INTO :V_ID_ATO_ISENTADO;

        V_SELO_GRUPO_ID = :V_RI_ISENCAO_SELO_GRUPO_ID; --ID GRUPO DE SELO DE GRATUIDADE RI
      END
      
      V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO,0) + COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

      --DESCRICAO DO SELO
      SELECT FIRST 1 'PROTOCOLO: '||CAST(PR.NUMERO_ORDEM AS INTEGER)||', '|| SUBSTRING(NT.DESCRICAO FROM 1 FOR 100)
      FROM R_PROTOCOLO PR, R_PEDIDO_ITEM PI, G_NATUREZA_TITULO NT
      WHERE PR.PEDIDO_ID = PI.PEDIDO_ID
      AND PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID
      AND PR.TIPO_PROTOCOLO = '1'
      AND PI.PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
      INTO :V_DESCRICAO_SELO;
        

      SELECT COUNT(PI.PEDIDO_ITEM_ID) FROM R_PEDIDO_ITEM PI, R_SELAR_PROTOCOLO SP
      WHERE PI.pedido_item_id = SP.pedido_item_id
      and sp.chave = :V_CHAVE
      AND PI.PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
      INTO :V_COUNT;

      IF ((:V_COUNT = 0)) THEN
      BEGIN
        SELECT COUNT(PI.PEDIDO_ITEM_ID) FROM R_PEDIDO_ITEM PI, R_SELAR_PROTOCOLO SP
        WHERE PI.pedido_id = SP.pedido_id
        and sp.chave = :V_CHAVE
        AND PI.PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
        INTO :V_COUNT;
      END

      IF ((:V_COUNT > 0)) THEN
      BEGIN      
        I = 0;
        WHILE (I < :V_QUANTIDADE) DO
        BEGIN
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO
          WHERE TABELA = 'R_PEDIDO_ITEM'
          AND CAMPO_ID = :V_PEDIDO_ITEM_ID
          INTO :V_QUANTIDADE_EMITIDA;
          IF (:V_QUANTIDADE_EMITIDA < :V_QUANTIDADE) THEN
          BEGIN        
            --SELECIONAR PROXIMO SELO PARA O PROTOCOLO
            SELECT FIRST 1 SELO_LIVRO_ID, SIGLA, NUMERO FROM G_SELO_LIVRO 
            WHERE SELO_SITUACAO_ID = 1 
            AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                 WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID) 
            ORDER BY SELO_LIVRO_ID                     
            INTO :V_SELO_LIVRO_ID, :V_SIGLA, :V_NUMERO;
              
            IF (COALESCE(:V_NUMERO_AGRUPADOR_PROTOCOLO,'') = '') THEN
            BEGIN
              --ver se ja existe um numero agrupador anterior
              SELECT FIRST 1 NUMERO_AGRUPADOR FROM G_SELO_LIVRO
              WHERE TABELA = 'R_PEDIDO_ITEM'
              AND CAMPO_ID IN (SELECT PEDIDO_ITEM_ID FROM R_PEDIDO_ITEM
                               WHERE PEDIDO_ID = :V_PEDIDO_ID)
              AND NUMERO_AGRUPADOR IS NOT NULL 
              AND NUMERO_AGRUPADOR <> ''
              INTO :V_NUMERO_AGRUPADOR_PROTOCOLO;
                
              IF (COALESCE(:V_NUMERO_AGRUPADOR_PROTOCOLO,'') = '') THEN
              BEGIN              
                SELECT TAMANHO FROM W_LENGTH(TRIM(CAST(:V_NUMERO AS VARCHAR(5))))
                INTO :V_TAMANHO;
                V_NUMERO_STRING = '';
                J = :V_TAMANHO;
                WHILE (J < 5) DO
                BEGIN
                  V_NUMERO_STRING = :V_NUMERO_STRING || '0';
                  J = J + 1;
                END
                V_NUMERO_STRING = :V_NUMERO_STRING || TRIM(CAST(:V_NUMERO AS VARCHAR(5)));
                V_NUMERO_AGRUPADOR_PROTOCOLO = :V_SIGLA || :V_NUMERO_STRING;
              END
            END
            IF (TRIM(COALESCE(:V_ADQUIRENTE_NOME,'')) <> '') THEN
            BEGIN
              V_NOME = :V_ADQUIRENTE_NOME;
            END
            ELSE
            BEGIN
              V_NOME = :V_APRESENTANTE_NOME;
            END
              
            UPDATE G_SELO_LIVRO 
            SET SELO_SITUACAO_ID = 2,
                DATA = :V_DATA,
                TABELA = 'R_PEDIDO_ITEM',
                CAMPO_ID = :V_PEDIDO_ITEM_ID,
                USUARIO_ID = :V_USUARIO_ID,
                NUMERO_AGRUPADOR = COALESCE(:V_NUMERO_AGRUPADOR_PROTOCOLO,''), 
                APRESENTANTE = :V_NOME, 
                IP_MAQUINA = :V_IP_MAQUINA,
                VALOR_TOTAL = :V_VALOR_TOTAL, 
                VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO, 
                VALOR_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA, 
                VALOR_FUNDESP = (COALESCE(:V_VALOR_EMOLUMENTO,0) * 0.10),
                DESCRICAO = :V_DESCRICAO_SELO
            WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;
          END
          I = I + 1;
        END
      END
    END                  
  END
  DELETE FROM R_SELAR_PROTOCOLO
  WHERE CHAVE = :V_CHAVE;  
  SUSPEND;
END ^

ALTER PROCEDURE R_SELAR_PROTOCOLO_TO (V_PEDIDO_ID VARCHAR(10) CHARACTER SET ISO8859_1,
V_CHAVE VARCHAR(30) CHARACTER SET ISO8859_1,
V_USUARIO_ID VARCHAR(20) CHARACTER SET ISO8859_1,
V_IP_MAQUINA VARCHAR(30) CHARACTER SET ISO8859_1,
V_HASH_STRING VARCHAR(3) CHARACTER SET ISO8859_1)
RETURNS (STATUS CHAR(1) CHARACTER SET ISO8859_1)
AS 
declare variable V_PROC_REF_LEI_352 VARCHAR_010;
declare variable V_PEDIDO_ITEM_ID integer;
declare variable V_PEDIDO_ITEM_NUMERO_ID integer;
declare variable V_QUANTIDADE integer;
declare variable V_SELO_GRUPO_ID integer;
declare variable V_APRESENTANTE_NOME varchar(120);
declare variable V_ADQUIRENTE_NOME varchar(120);
declare variable V_APRESENTANTE_CPF varchar(20);
declare variable V_ADQUIRENTE_CPF varchar(20);
declare variable V_NOME varchar(120);
declare variable V_CPF varchar(20);
declare variable V_VALOR_EMOLUMENTO numeric(18,3);
declare variable V_VALOR_TAXA_JUDICIARIA numeric(18,3);
declare variable V_VALOR_FUNDO_RI numeric(18,3);
declare variable V_VALOR_ISS numeric(18,3);
declare variable V_VALOR_TOTAL numeric(18,3);
declare variable V_VALOR_DESCONTO numeric(18,3);
declare variable V_PORCENTAGEM_DESCONTO numeric(18,3);
declare variable V_TIPO_TITULO varchar(60);
declare variable V_COUNT integer;
declare variable V_NUMERO_GRUPO integer;
declare variable V_DESCRICAO_EMOLUMENTO varchar(260);
declare variable V_SELO_LIVRO_ID integer;
declare variable V_SIGLA varchar(30);
declare variable V_NUMERO integer;
declare variable V_NUMERO_STRING varchar(6);
declare variable V_NUMERO_SELO varchar(50);
declare variable I integer;
declare variable J integer;
declare variable V_ENVIOU_TAXA char(1);
declare variable V_TAMANHO integer;
declare variable V_QUANTIDADE_EMITIDA integer;
declare variable PEDIDO_ITEM_ID_AUX integer;
declare variable PEDIDO_ITEM_ID_ANTERIOR_AUX integer;
declare variable V_SIGLA_AUX varchar(30);
declare variable V_NUMERO_AUX integer;
declare variable V_DESCRICAO_SELO varchar(120);
declare variable V_CNS varchar(10);
declare variable V_NUMERO_FORMATADO varchar(6);
declare variable V_TAG_SELO varchar(2000);
declare variable V_TAG_PROTOCOLO VARCHAR_120;
declare variable V_MODELO_TAG varchar(3);
declare variable V_CODIGO_TABELA varchar(10);
declare variable V_DATA_PROTOCOLO timestamp;
declare variable V_DATA_PROTOCOLO_STR varchar(30);
declare variable V_DATA_ATO varchar(30);
declare variable V_VALOR_DOCUMENTO numeric(18,2);
declare variable V_VALOR_ITBI numeric(18,2);
declare variable V_VALOR_MERCADO numeric(18,2);
declare variable V_NUMERO_ORDEM integer;
declare variable V_MATRICULA integer;
declare variable V_SELO_TABELIONATO varchar(30);
declare variable V_QUANTIDADE_PAGINA integer;
declare variable V_QUANTIDADE_UNIDADE_AUTONOMA integer;
declare variable V_TIPO_PROTOCOLO varchar(1);
declare variable V_DIA varchar(2);
declare variable V_MES varchar(2);
declare variable V_HORA varchar(2);
declare variable V_MINUTO varchar(2);
declare variable V_SEGUNDO varchar(2);
declare variable V_TAG_ISS varchar(100);
declare variable V_EH_ISENTO varchar(1);
declare variable V_MOTIVO_ISENCAO varchar(260);
declare variable V_TAG_ISENCAO varchar(300);
declare variable V_TIPO_ATO varchar(30);
declare variable V_LIVRO varchar(10);
declare variable V_FOLHA varchar(15);
declare variable V_TIPO varchar(2);
declare variable V_UND_AUTONOMA NUMERICO;
declare variable V_NUMERO_AVERBACAO NUMERICO;
declare variable V_NUMERO_REGISTRO NUMERICO;
declare variable V_PEDIDO_ONLINE varchar(10);
declare variable V_TAG_REDUCAO varchar(50);
declare variable V_REDUCAO varchar(120);
declare variable V_ACAO_TO varchar(3);
declare variable V_REURB varchar(50);
declare variable V_COVALIDACAO varchar(50);
declare variable V_INTEIRO_TEOR varchar(50);
declare variable V_AREA NUMERICO;
declare variable V_MES_REFERENCIA_INFORMADO VARCHAR_030;
declare variable V_NUMERO_PROCESSO VARCHAR_030;
BEGIN
  STATUS = 'T';
  V_ENVIOU_TAXA = 'F';
  V_NUMERO_SELO = '';

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL','CARTORIO','CODIGO_SERVENTIA',5)
  INTO :V_CNS;

  FOR SELECT PI.PEDIDO_ITEM_ID, COALESCE(PI.QUANTIDADE,0) QUANTIDADE, PE.APRESENTANTE_NOME,
        PE.ADQUIRENTE_NOME, COALESCE(PI.VALOR_EMOLUMENTO,0) VALOR_EMOLUMENTO,
        COALESCE(PI.VALOR_TAXA_JUDICIARIA,0) VALOR_TAXA_JUDICIARIA, 
        COALESCE(PI.VALOR_FUNDO_RI,0) VALOR_FUNDO_RI, N.TIPO_TITULO, E.DESCRICAO,      
        COALESCE(PI.VALOR_DESCONTO,0) VALOR_DESCONTO,
        COALESCE(PI.PORCENTAGEM_DESCONTO,0) PORCENTAGEM_DESCONTO,
        COALESCE(PI.VALOR_ISS,0) VALOR_ISS, E.MODELO_TAG, I.CODIGO_TABELA, PR.DATA,
        COALESCE(PI.VALOR_DOCUMENTO,0), PR.NUMERO_ORDEM, COALESCE(PE.APRESENTANTE_CPF_CNPJ,''),
        COALESCE(PE.ADQUIRENTE_CPF_CNPJ,''), COALESCE(PI.VALOR_ITBI,0), COALESCE(PI.VALOR_MERCADO,0),
        COALESCE(PI.SELO_TABELIONATO,'0'), COALESCE(PI.QUANTIDADE_PAGINA,1),
        COALESCE(PI.QUANTIDADE_UNIDADE_AUTONOMA,0), PR.TIPO_PROTOCOLO, COALESCE(PI.EH_ISENTO,''),
        COALESCE(PI.MOTIVO_ISENCAO,''), COALESCE(I.CODIGO_TABELA,'0'), COALESCE( PR.livro, '2'), 'NA' ,
        COALESCE(PI.quantidade_unidade_autonoma,0), PR.codigo_acesso_online, E.motivo_reducao, COALESCE(N.acao_to,''),
        COALESCE(PI.area,1)
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, G_EMOLUMENTO E,
        G_EMOLUMENTO_ITEM I, G_NATUREZA_TITULO N
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.PEDIDO_ID = PI.PEDIDO_ID       
      AND PI.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID 
      AND PI.EMOLUMENTO_ITEM_ID = I.EMOLUMENTO_ITEM_ID
      AND COALESCE(I.CODIGO_TABELA,'') <> ''
      AND I.EMOLUMENTO_ID = E.EMOLUMENTO_ID
      AND PE.PEDIDO_ID = :V_PEDIDO_ID
      AND (PR.TIPO_PROTOCOLO = '1' OR PR.TIPO_PROTOCOLO = '3')
      AND (PI.EXCLUI_DO_RELATORIO = 'N' OR PI.EXCLUI_DO_RELATORIO IS NULL OR PI.EXCLUI_DO_RELATORIO = '')       
      ORDER BY PI.PEDIDO_ITEM_ID ASC
      INTO :V_PEDIDO_ITEM_ID, :V_QUANTIDADE,
        :V_APRESENTANTE_NOME, :V_ADQUIRENTE_NOME, :V_VALOR_EMOLUMENTO, :V_VALOR_TAXA_JUDICIARIA, 
        :V_VALOR_FUNDO_RI, :V_TIPO_TITULO, :V_DESCRICAO_EMOLUMENTO,
        :V_VALOR_DESCONTO, :V_PORCENTAGEM_DESCONTO, :V_VALOR_ISS, :V_MODELO_TAG, :V_CODIGO_TABELA,
        :V_DATA_PROTOCOLO, :V_VALOR_DOCUMENTO, :V_NUMERO_ORDEM,
        :V_APRESENTANTE_CPF, :V_ADQUIRENTE_CPF, :V_VALOR_ITBI, :V_VALOR_MERCADO, :V_SELO_TABELIONATO,
        :V_QUANTIDADE_PAGINA,:V_QUANTIDADE_UNIDADE_AUTONOMA, :V_TIPO_PROTOCOLO,
        :V_EH_ISENTO, :V_MOTIVO_ISENCAO, :V_TIPO_ATO, :V_LIVRO, :V_FOLHA, :V_UND_AUTONOMA, :V_PEDIDO_ONLINE,
        :V_REDUCAO, :V_ACAO_TO, :v_area  DO
  BEGIN
    V_FOLHA  = 'NA';
    V_LIVRO = '2';
    if (:V_TIPO_TITULO = 1) then
    BEGIN
      V_LIVRO = '2';
    END
    ELSE
    if (:V_TIPO_TITULO = 2) then
    BEGIN
      V_LIVRO = '3';
    END
    ELSE
    if (:V_TIPO_TITULO = 3) then
    BEGIN
      V_LIVRO = '2';
    END
    ELSE
    if (:V_TIPO_TITULO = 4) then
    BEGIN
      V_LIVRO = '3';
    END


    if (:V_VALOR_DOCUMENTO = 0) then
    BEGIN
      V_VALOR_DOCUMENTO = 0.01;
    END
    if (:V_VALOR_ITBI = 0) then
    BEGIN
      V_VALOR_ITBI = 0.01;
    END
    if (:V_VALOR_MERCADO = 0) then
    BEGIN
      V_VALOR_ITBI = 0.01;
    END
    IF (:V_QUANTIDADE > 0) THEN
    BEGIN           
      --VALOR DE EMOLUMENTO
      IF (:V_VALOR_EMOLUMENTO > 0) THEN
      BEGIN
        V_VALOR_EMOLUMENTO = (CAST((:V_VALOR_EMOLUMENTO / :V_QUANTIDADE) AS NUMERIC(14,2)));
      END
           
      --FUNDO
      IF (:V_VALOR_FUNDO_RI > 0) THEN
      BEGIN
        V_VALOR_FUNDO_RI = CAST((:V_VALOR_FUNDO_RI / :V_QUANTIDADE) AS NUMERIC(14,2));
      END

      --FUNDO
      IF (:V_VALOR_ISS > 0) THEN
      BEGIN
        V_VALOR_ISS = CAST((:V_VALOR_ISS / 1) AS NUMERIC(14,2));
      END

      V_VALOR_TOTAL = COALESCE(:V_VALOR_EMOLUMENTO,0) + COALESCE(:V_VALOR_TAXA_JUDICIARIA,0) + COALESCE(:V_VALOR_FUNDO_RI,0);

      --SELO_GRUPO_ID RI;
      SELECT FIRST 1 SELO_GRUPO_ID FROM G_SELO_GRUPO
      WHERE SITUACAO = 'A'
      AND TIPO_CARTORIO = '2'
      ORDER BY SELO_GRUPO_ID DESC
      INTO :V_SELO_GRUPO_ID;

      IF (:V_TIPO_PROTOCOLO = '1') THEN
      BEGIN
        --DESCRICAO DO SELO
        SELECT FIRST 1 'PROTOCOLO: '||CAST(PR.NUMERO_ORDEM AS INTEGER)||', '|| SUBSTRING(NT.DESCRICAO FROM 1 FOR 100)
        FROM R_PROTOCOLO PR, R_PEDIDO_ITEM PI, G_NATUREZA_TITULO NT
        WHERE PR.PEDIDO_ID = PI.PEDIDO_ID
        AND PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID
        AND PR.TIPO_PROTOCOLO = '1'
        AND PI.PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
        INTO :V_DESCRICAO_SELO;

        SELECT COUNT(*) FROM R_PEDIDO_ITEM
        WHERE (PEDIDO_ITEM_ID IN (SELECT PEDIDO_ITEM_ID FROM R_SELAR_PROTOCOLO
                                 WHERE CHAVE = :V_CHAVE) OR
               PEDIDO_ID IN (SELECT PEDIDO_ID FROM R_SELAR_PROTOCOLO
                             WHERE CHAVE  = :V_CHAVE))         
        AND PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
        INTO :V_COUNT;              
      END
      ELSE
      BEGIN
        --DESCRICAO DO SELO
        SELECT FIRST 1 'PEDIDO Nº: '||CAST(PR.NUMERO_ORDEM AS INTEGER)||', '|| SUBSTRING(NT.DESCRICAO FROM 1 FOR 100)
        FROM R_PROTOCOLO PR, R_PEDIDO_ITEM PI, G_NATUREZA_TITULO NT
        WHERE PR.PEDIDO_ID = PI.PEDIDO_ID
        AND PI.NATUREZA_TITULO_ID = NT.NATUREZA_TITULO_ID
        AND PR.TIPO_PROTOCOLO = '3'
        AND PI.PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
        INTO :V_DESCRICAO_SELO;

        --se existir menor quantidade de mat/reg.auxiliar que a quantidade calculada, cria os mesmos
        SELECT COUNT(*) FROM R_PEDIDO_ITEM_NUMERO 
        WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
        INTO :V_COUNT;
        IF (:V_COUNT < :V_QUANTIDADE) THEN
        BEGIN
          I = :V_COUNT;
          WHILE (I < :V_QUANTIDADE) DO
          BEGIN
            SELECT SEQUENCIA FROM G_SP_SEQUENCIAS('R_PEDIDO_ITEM_NUMERO')
            INTO :V_PEDIDO_ITEM_NUMERO_ID;
  
            INSERT INTO R_PEDIDO_ITEM_NUMERO(PEDIDO_ITEM_NUMERO_ID, PEDIDO_ITEM_ID)                                             
                                     VALUES (:V_PEDIDO_ITEM_NUMERO_ID, :V_PEDIDO_ITEM_ID);
            I = I + 1;
          END
          V_COUNT = :V_QUANTIDADE;
        END
      END
                  
      IF ((:V_COUNT > 0)) THEN
      BEGIN      
        I = 0;
        WHILE (I < :V_QUANTIDADE) DO
        BEGIN
          --verificar quantidade de selos ja emitidos
          SELECT COUNT(*) FROM G_SELO_LIVRO
          WHERE TABELA = 'R_PEDIDO_ITEM'
          AND CAMPO_ID = :V_PEDIDO_ITEM_ID
          INTO :V_QUANTIDADE_EMITIDA;
          IF (:V_QUANTIDADE_EMITIDA < :V_QUANTIDADE) THEN
          BEGIN        
            --SELECIONAR PROXIMO SELO PARA O PROTOCOLO
            SELECT FIRST 1 SELO_LIVRO_ID, SIGLA, NUMERO FROM G_SELO_LIVRO 
            WHERE SELO_SITUACAO_ID = 1 
            AND SELO_LOTE_ID IN (SELECT SELO_LOTE_ID FROM G_SELO_LOTE 
                                 WHERE SELO_GRUPO_ID = :V_SELO_GRUPO_ID) 
            ORDER BY SELO_LIVRO_ID                     
            INTO :V_SELO_LIVRO_ID, :V_SIGLA, :V_NUMERO;

            SELECT STRING FROM W_RETORNAR_COM_ZERO_ESQUERDA(:V_NUMERO,6)
            INTO :V_NUMERO_FORMATADO;

            SELECT STRING FROM G_GERAR_STRING_RANDOMICA(3) INTO :V_HASH_STRING;

            V_NUMERO_SELO = :V_CNS||:V_SIGLA||:V_NUMERO_FORMATADO||:V_HASH_STRING;

            IF (TRIM(COALESCE(:V_ADQUIRENTE_NOME,'')) <> '') THEN
            BEGIN
              SELECT NOME_SEM_ACENTUACAO FROM G_retirar_acentuacao(:V_ADQUIRENTE_NOME)
              INTO :V_NOME;
              V_TIPO = '14';
            END
            ELSE
            BEGIN
              SELECT NOME_SEM_ACENTUACAO FROM G_retirar_acentuacao(:V_APRESENTANTE_NOME)
              INTO :V_NOME;
              V_TIPO = '13';
            END

            IF (TRIM(COALESCE(:V_ADQUIRENTE_CPF,'')) <> '') THEN
            BEGIN
              SELECT INTEIRO FROM W_RETORNAR_INTEIRO(:V_ADQUIRENTE_CPF)
              INTO :V_CPF;
            END
            ELSE
            BEGIN
              SELECT INTEIRO FROM W_RETORNAR_INTEIRO(:V_APRESENTANTE_CPF)
              INTO :V_CPF;
            END

            SELECT FIRST 1 NUMERO FROM R_PEDIDO_ITEM_NUMERO
            WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
            AND TIPO_REGISTRO = 'M'
            INTO :V_MATRICULA;

            SELECT FIRST 1 PROC_REF_LEI_352 FROM R_PEDIDO_ITEM_NUMERO
            WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
            AND PROC_REF_LEI_352 IS NOT NULL
            INTO :V_PROC_REF_LEI_352;

            SELECT FIRST 1 COMPLEMENTO FROM R_ANDAMENTO RA , r_tb_tipo_andamento RT
            WHERE RA.tb_tipo_andamento_id = RT.tb_tipo_andamento_id
            AND RT.descricao = 'Nº Processo'
            AND RA.pedido_id = :V_PEDIDO_ID
            INTO :V_NUMERO_PROCESSO;

            if (coalesce(:V_NUMERO_PROCESSO,'')='') then
              V_NUMERO_PROCESSO = '1';

            SELECT FIRST 1 REURB FROM R_PEDIDO_ITEM_NUMERO
            WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
            INTO :V_REURB;

            SELECT FIRST 1 CONVALIDACAO FROM R_PEDIDO_ITEM_NUMERO
            WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
            INTO :V_COVALIDACAO;

            SELECT FIRST 1(COALESCE(ATO_NUMERO,1)) FROM R_PEDIDO_ITEM_NUMERO
            WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
            AND TIPO_REGISTRO = 'M'
            INTO :V_NUMERO_REGISTRO;

            IF (COALESCE(:V_NUMERO_REGISTRO,0) = 0) THEN
            BEGIN
              V_NUMERO_REGISTRO = 1;
            END

           IF (COALESCE(:V_PROC_REF_LEI_352,'') = 'S') THEN
            BEGIN
              V_PROC_REF_LEI_352 = 'true';
            END
            ELSE
            BEGIN
              V_PROC_REF_LEI_352 = 'false';
            END
            V_REURB = '';
            V_COVALIDACAO = '';
            V_INTEIRO_TEOR = '';
            --if (CURRENT_DATE >= CAST('2022.09.01' AS DATE )) then
            begin
                V_INTEIRO_TEOR = 'inteiro_teor=';
                IF (COALESCE(:V_REURB,'') = 'S') THEN
                BEGIN
                  V_REURB = ' reurb="true" ';
                END
                ELSE
                BEGIN
                  V_REURB = ' reurb="false" ';
                END
        
                IF (COALESCE(:V_COVALIDACAO,'') = 'S') THEN
                BEGIN
                  V_COVALIDACAO = ' convalidacao="true"  ';
                END
                ELSE
                BEGIN
                  V_COVALIDACAO = ' convalidacao="false" ';
                END
            end

            SELECT FIRST 1(COALESCE(ATO_NUMERO,1)) FROM R_PEDIDO_ITEM_NUMERO
            WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
            AND TIPO_REGISTRO = 'A'
            INTO :V_NUMERO_AVERBACAO;

            IF (COALESCE(:V_NUMERO_AVERBACAO,0) = 0) THEN
            BEGIN
              V_NUMERO_AVERBACAO = 1;
            END

            V_DIA = EXTRACT(DAY FROM CURRENT_DATE);
            IF (CHAR_LENGTH(:V_DIA) = 1) THEN
            BEGIN
              V_DIA = '0'||:V_DIA;
            END
            V_MES = EXTRACT(MONTH FROM CURRENT_DATE);
            IF (CHAR_LENGTH(:V_MES) = 1) THEN
            BEGIN
              V_MES = '0'||:V_MES;
            END

            V_MES_REFERENCIA_INFORMADO = :V_MES||'/'||EXTRACT(YEAR FROM CURRENT_TIMESTAMP);

            V_HORA = EXTRACT(HOUR FROM CURRENT_TIMESTAMP);
            V_MINUTO = EXTRACT(MINUTE FROM CURRENT_TIMESTAMP);
            V_SEGUNDO = CAST(EXTRACT(SECOND FROM CURRENT_TIMESTAMP) AS INTEGER);
            IF (CHAR_LENGTH(:V_HORA) = 1) THEN
            BEGIN
              V_HORA = '0'||:V_HORA;
            END

            IF (CHAR_LENGTH(:V_MINUTO) = 1) THEN
            BEGIN
              V_MINUTO = '0'||:V_MINUTO;
            END

            if (:v_area = 0) then
              v_area = 1;

            IF (CHAR_LENGTH(:V_SEGUNDO) = 1) THEN
            BEGIN
              V_SEGUNDO = '0'||:V_SEGUNDO;
            END
            if (V_SEGUNDO = '60' ) then
            BEGIN
              V_SEGUNDO = '59';
            END

            V_DATA_ATO = EXTRACT(YEAR FROM CURRENT_DATE)||'-'||:V_MES||'-'||:V_DIA||'T'||V_HORA||':'||V_MINUTO||':'||V_SEGUNDO;

            V_DIA = EXTRACT(DAY FROM :V_DATA_PROTOCOLO);
            IF (CHAR_LENGTH(:V_DIA) = 1) THEN
            BEGIN
              V_DIA = '0'||:V_DIA;
            END
            V_MES = EXTRACT(MONTH FROM :V_DATA_PROTOCOLO);
            IF (CHAR_LENGTH(:V_MES) = 1) THEN
            BEGIN
              V_MES = '0'||:V_MES;
            END
            V_HORA = EXTRACT(HOUR FROM cast( :V_DATA_PROTOCOLO as timestamp));
            V_MINUTO = EXTRACT(MINUTE FROM cast( :V_DATA_PROTOCOLO as timestamp));
            V_SEGUNDO = CAST(EXTRACT(SECOND FROM cast( :V_DATA_PROTOCOLO as timestamp)) AS INTEGER);
            IF (CHAR_LENGTH(:V_HORA) = 1) THEN
            BEGIN
              V_HORA = '0'||:V_HORA;
            END

            IF (CHAR_LENGTH(:V_MINUTO) = 1) THEN
            BEGIN
              V_MINUTO = '0'||:V_MINUTO;
            END

            IF (CHAR_LENGTH(:V_SEGUNDO) = 1) THEN
            BEGIN
              V_SEGUNDO = '0'||:V_SEGUNDO;
            END

            if (V_SEGUNDO = '60' ) then
            BEGIN
              V_SEGUNDO = '59';
            END

            V_DATA_PROTOCOLO_STR = EXTRACT(YEAR FROM :V_DATA_PROTOCOLO)||'-'||:V_MES||'-'||:V_DIA||'T'||V_HORA||':'||V_MINUTO||':'||V_SEGUNDO;

            V_TAG_ISS = '';
            IF (COALESCE(:V_VALOR_ISS,0) > 0) THEN
            BEGIN
              V_TAG_ISS = ' valor_issqn="'||(SELECT RETORNO FROM W_TROCAR_VIRGULA_POR_PONTO(CAST(:V_VALOR_ISS AS VARCHAR(20))))||'" ';
            END

            V_TAG_REDUCAO = '';
            IF (TRIM(COALESCE(:V_REDUCAO,'')) <> '') THEN
            BEGIN
              V_TAG_REDUCAO = ' fator ="'||:V_REDUCAO||'" ';
            END

            V_TAG_ISENCAO = '';
            IF (COALESCE(:V_EH_ISENTO,'') = 'S') THEN
            BEGIN
              IF (:V_MOTIVO_ISENCAO = '') THEN
              BEGIN
                V_MOTIVO_ISENCAO = 'GRATUITO';
              END
              V_TAG_ISENCAO = ' gratuito="true" observacao="'||:V_MOTIVO_ISENCAO||'" ';
            END

            IF (COALESCE(:V_NUMERO_ORDEM,0) = 0) THEN
            BEGIN
              V_NUMERO_ORDEM = 1;
            END

            --INICIO MOTAGEM DAS TAGS
            V_TAG_SELO =  '<selo codigo_selo="'||:V_SIGLA||:V_NUMERO_FORMATADO||'" codigo_validacao="'||:V_HASH_STRING||'">';

           IF (:V_CODIGO_TABELA = 5062) THEN --5062 - Tabela IV 1.1 - Protocolo de qualquer título apresentado em meio físico ou eletrônico
           BEGIN
             V_TAG_PROTOCOLO = ' >';

             if (CURRENT_DATE >= CAST('2019.07.01' AS DATE )) then
               V_TAG_PROTOCOLO = ' numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" ';--||'" reurb="'||''||'"  convalidacao="'||''||'" >';

             if (CURRENT_DATE >= CAST('2022.09.01' AS DATE )) then
               V_TAG_PROTOCOLO = ' numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" '||:v_reurb||:v_covalidacao||'>';

             V_TAG_SELO = V_TAG_SELO||  '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||' livro="'||:V_LIVRO||'"  folha="'||:V_FOLHA||'" '||V_TAG_PROTOCOLO||'
                                                <detalhe nome="'||:V_NOME||'" cpf_cnpj="'||:V_CPF||'"'||' tipo="9" '||'/>
                                            </ato>';
            END
            ELSE    
            IF (:V_CODIGO_TABELA IN (5067,5068,5069)) THEN
            BEGIN
               if (COALESCE(:V_ACAO_TO,'') = '' ) then
                 V_ACAO_TO = '22';

               V_TAG_SELO = V_TAG_SELO||  '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||' livro="'||:V_LIVRO||'"  folha="'||:V_FOLHA||'"  numero_registro="'||:V_NUMERO_REGISTRO||'"
