                V_TAG_SELO = V_TAG_SELO||  '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  livro="'||:V_LIVRO||'"  folha="'||:V_FOLHA||'" numero_averbacao="'||:V_NUMERO_AVERBACAO||'" valor_economico="'||(SELECT RETORNO FROM W_TROCAR_VIRGULA_POR_PONTO(CAST(:V_VALOR_DOCUMENTO AS VARCHAR(20))))||'"  valor_fiscal="'||(SELECT RETORNO FROM W_TROCAR_VIRGULA_POR_PONTO(CAST(:V_VALOR_ITBI AS VARCHAR(20))))||'" valor_avaliacao="'||(SELECT RETORNO FROM W_TROCAR_VIRGULA_POR_PONTO(CAST(:V_VALOR_MERCADO AS VARCHAR(20))))||'" numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" '||' '||V_INTEIRO_TEOR||' >
                                                <detalhe  nome="'||:V_NOME||'"  cpf_cnpj="'||:V_CPF||'"  tipo="9"  />
                                                <objeto  matricula="'||CAST(COALESCE(:V_MATRICULA,0) AS VARCHAR(10))||'" /> 
                                            </ato>';
            END
            ELSE                
            IF (:V_CODIGO_TABELA IN (5100)) THEN
            BEGIN
                V_TAG_SELO = V_TAG_SELO||  '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  livro="'||:V_LIVRO||'"  folha="'||:V_FOLHA||'" numero_averbacao="'||:V_NUMERO_AVERBACAO||'" valor_economico="'||(SELECT RETORNO FROM W_TROCAR_VIRGULA_POR_PONTO(CAST(:V_VALOR_DOCUMENTO AS VARCHAR(20))))||'"  valor_fiscal="'||(SELECT RETORNO FROM W_TROCAR_VIRGULA_POR_PONTO(CAST(:V_VALOR_ITBI AS VARCHAR(20))))||'" valor_avaliacao="'||(SELECT RETORNO FROM W_TROCAR_VIRGULA_POR_PONTO(CAST(:V_VALOR_MERCADO AS VARCHAR(20))))||'" numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" '||:v_reurb||' '||V_INTEIRO_TEOR||' >
                                                <detalhe  nome="'||:V_NOME||'"  cpf_cnpj="'||:V_CPF||'"  tipo="9"  />
                                                <objeto  matricula="'||CAST(COALESCE(:V_MATRICULA,0) AS VARCHAR(10))||'" /> 
                                            </ato>';
            END
            ELSE                
            IF (:V_CODIGO_TABELA IN (5170,5171)) THEN
            BEGIN
                V_TAG_SELO = V_TAG_SELO||  '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  quantidade_buscas="'||:V_QUANTIDADE||'"  central_informacao="6" mes_referencia_informado="'||:v_mes_referencia_informado||'" >
                                                <detalhe  nome="'||:V_NOME||'"  cpf_cnpj="'||:V_CPF||'" />
                                            </ato>';
            END
             -- ATOS CONUNS
            IF (:V_CODIGO_TABELA in (5142,5156)) THEN
            BEGIN
               V_TAG_SELO = V_TAG_SELO||       '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'" segmento_origem="IMOVEIS"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" >
                                             </ato>';
            END

            IF  (:V_CODIGO_TABELA IN (5143,5144,5146,5149)) THEN
            begin
               V_TAG_SELO = V_TAG_SELO||       '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'" segmento_origem="IMOVEIS"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" >
                                                 <detalhe  nome="'||:V_NOME||'"  cpf_cnpj="'||:V_CPF||'"  /> 
                                             </ato>'; 
            END

            IF  (:V_CODIGO_TABELA IN (5148)) THEN
            begin
               V_TAG_SELO = V_TAG_SELO||       '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'" segmento_origem="IMOVEIS"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||' quantidade_pessoas="1" '||'  numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" >
                                                 <detalhe  nome="'||:V_NOME||'"  cpf_cnpj="'||:V_CPF||'"  /> 
                                             </ato>'; 
            END

            IF (:V_CODIGO_TABELA = 5147)THEN
               V_TAG_SELO = V_TAG_SELO||       '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'" segmento_origem="IMOVEIS"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  quantidade_unidade_autonomas="'||:V_UND_AUTONOMA||'"  numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" >
                                             </ato>';            
            End

            IF (:V_CODIGO_TABELA = 5150)THEN
            begin
               V_TAG_SELO = V_TAG_SELO||       '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'" segmento_origem="IMOVEIS"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  livro="'||:V_LIVRO||'"  folha="'||:V_FOLHA||'"  numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'"  minutos="" >
                                                     <detalhe  nome="'||:V_NOME||'"  cpf_cnpj="'||:V_CPF||'"  /> 
                                             </ato>'; 
            end

            IF (:V_CODIGO_TABELA = 5151)THEN
            begin
               V_TAG_SELO = V_TAG_SELO||       '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'" segmento_origem="IMOVEIS"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  destino_comunicacao=""  numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" >
                                             </ato>'; 
            end

            IF (:V_CODIGO_TABELA = 5152)THEN
            begin
               V_TAG_SELO = V_TAG_SELO||       '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'" segmento_origem="IMOVEIS"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  livro="'||:V_LIVRO||'"  folha="'||:V_FOLHA||'"  origem_documento=""  numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" >
                                                     <detalhe  nome="'||:V_NOME||'"  cpf_cnpj="'||:V_CPF||'"  /> 
                                             </ato>';            
            end

            IF (:V_CODIGO_TABELA IN (5153,5154,5155,5167))THEN
            begin
               V_TAG_SELO = V_TAG_SELO||       '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'" segmento_origem="IMOVEIS"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  juiz_paz=""  fora_expediente="false"  numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" >
                                             </ato>';
            end

            IF (:V_CODIGO_TABELA = 5119 )THEN
            begin
               V_TAG_SELO = V_TAG_SELO||       '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'" segmento_origem="IMOVEIS"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  numero_processo="'||:V_NUMERO_PROCESSO||'"  numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'" >
                                                     <detalhe  nome="'||:V_NOME||'"  cpf_cnpj="'||:V_CPF||'"  /> 
                                             </ato>';
            end

            IF (:V_CODIGO_TABELA IN (5138,5139))THEN
            BEGIN
               V_TAG_SELO = V_TAG_SELO||       '<ato codigo="'||:V_CODIGO_TABELA||'" data_ato="'||:V_DATA_ATO||'" data_protocolo="'||:V_DATA_PROTOCOLO_STR||'" segmento_origem="IMOVEIS"'||:V_TAG_ISS||:V_TAG_ISENCAO||V_TAG_REDUCAO||'  fora_expediente="false"  numero_protocolo="'||CAST(:V_NUMERO_ORDEM AS VARCHAR(10))||'"  km="'||:V_QUANTIDADE||'" >
                                             </ato>';
            end


             I = I + 1;
            END
            --FIM DA MOTAGEM DAS TAGS
             V_TAG_SELO =  V_TAG_SELO || '</selo>';

            IF (:V_TIPO_PROTOCOLO = '1') THEN
            BEGIN
              UPDATE G_SELO_LIVRO
              SET SELO_SITUACAO_ID = 2,
                  DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                  TABELA = 'R_PEDIDO_ITEM',
                  CAMPO_ID = :V_PEDIDO_ITEM_ID,
                  USUARIO_ID = :V_USUARIO_ID,
                  NUMERO_AGRUPADOR = :V_NUMERO_SELO,
                  APRESENTANTE = :V_NOME, 
                  IP_MAQUINA = :V_IP_MAQUINA,
                  VALOR_TOTAL = :V_VALOR_TOTAL, 
                  VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO, 
                  VALOR_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA, 
                  VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                  VALOR_ISS = :V_VALOR_ISS,
                  DESCRICAO = :V_DESCRICAO_SELO,
                  TAG_SELO = :V_TAG_SELO,
                  TIPO_ATO = :V_TIPO_ATO
              WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;
            END
            ELSE
            BEGIN
              SELECT FIRST 1 PEDIDO_ITEM_NUMERO_ID FROM R_PEDIDO_ITEM_NUMERO
              WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
              INTO :V_PEDIDO_ITEM_NUMERO_ID;

              UPDATE G_SELO_LIVRO
              SET SELO_SITUACAO_ID = 2,
                  DATA = (SELECT CURRENT_TIMESTAMP FROM RDB$DATABASE),
                  TABELA = 'R_PEDIDO_ITEM_NUMERO',
                  CAMPO_ID = :V_PEDIDO_ITEM_NUMERO_ID,
                  USUARIO_ID = :V_USUARIO_ID,
                  NUMERO_AGRUPADOR = :V_NUMERO_SELO,
                  APRESENTANTE = :V_NOME, 
                  IP_MAQUINA = :V_IP_MAQUINA,
                  VALOR_TOTAL = :V_VALOR_TOTAL, 
                  VALOR_EMOLUMENTO = :V_VALOR_EMOLUMENTO, 
                  VALOR_TAXA_JUDICIARIA = :V_VALOR_TAXA_JUDICIARIA, 
                  VALOR_FUNDESP = :V_VALOR_FUNDO_RI,
                  VALOR_ISS = :V_VALOR_ISS,
                  DESCRICAO = :V_DESCRICAO_SELO,
                  TAG_SELO = :V_TAG_SELO,
                  TIPO_ATO = :V_TIPO_ATO
              WHERE SELO_LIVRO_ID = :V_SELO_LIVRO_ID;
            END
          END
        END
      END
  DELETE FROM R_SELAR_PROTOCOLO
  WHERE CHAVE = :V_CHAVE;
  SUSPEND;
END ^

ALTER PROCEDURE R_SELAR_PROTOCOLO_TO_VALIDAR (V_PEDIDO_ID VARCHAR(10) CHARACTER SET ISO8859_1)
RETURNS (STATUS VARCHAR(10) CHARACTER SET ISO8859_1,
MENSAGEM VARCHAR(3000) CHARACTER SET ISO8859_1)
AS 
declare variable V_PEDIDO_ITEM_ID integer;
declare variable V_QUANTIDADE integer;
declare variable V_APRESENTANTE_NOME varchar(120);
declare variable V_ADQUIRENTE_NOME varchar(120);
declare variable V_APRESENTANTE_CPF varchar(20);
declare variable V_NOME varchar(120);
declare variable V_ADQUIRENTE_CPF varchar(20);
declare variable V_CPF varchar(20);
declare variable V_CNS varchar(10);
declare variable V_CODIGO_TABELA varchar(10);
declare variable V_DATA_PROTOCOLO timestamp;
declare variable V_VALOR_DOCUMENTO numeric(18,2);
declare variable V_VALOR_ITBI numeric(18,2);
declare variable V_VALOR_MERCADO numeric(18,2);
declare variable V_NUMERO_ORDEM integer;
declare variable V_MATRICULA integer;
declare variable V_SELO_TABELIONATO varchar(30);
declare variable V_QUANTIDADE_PAGINA integer;
declare variable V_QUANTIDADE_UNIDADE_AUTONOMA integer;
declare variable V_TIPO_PROTOCOLO varchar(1);
declare variable V_TIPO_ATO varchar(30);
declare variable V_LIVRO varchar(10);
declare variable V_FOLHA varchar(15);
declare variable V_UND_AUTONOMA NUMERICO;
declare variable V_NUMERO_REGISTRO NUMERICO;
declare variable V_PEDIDO_ONLINE varchar(10);
declare variable V_TAG_FATOR varchar(50);
declare variable V_FATOR varchar(120);
declare variable V_ACAO_TO varchar(3);
declare variable V_TIPO_REGISTRO varchar(10);
declare variable V_QTDE_MENSAGEM integer;
declare variable V_TIPO_COBRANCA varchar(3);
BEGIN
  STATUS = 'OK';

  MENSAGEM = '';

  SELECT VALOR_PARAMETRO FROM G_BUSCAR_CONFIG('PRINCIPAL','CARTORIO','CODIGO_SERVENTIA',5)
  INTO :V_CNS;
  if (coalesce(:V_CNS,'') = '') then
  begin
    STATUS = 'ERRO';
    if (:MENSAGEM = '') then
    begin
      MENSAGEM = '* CNS não informado';
    end
    else
    begin
      MENSAGEM = :MENSAGEM||ASCII_CHAR(13)||'* CNS não informado';
    end
  end

  V_QTDE_MENSAGEM = 0;

  --VALIDACAO DE INFORMACOES
  FOR SELECT PI.PEDIDO_ITEM_ID, COALESCE(PI.QUANTIDADE,0) QUANTIDADE, PE.APRESENTANTE_NOME,
        PE.ADQUIRENTE_NOME, I.CODIGO_TABELA, PR.DATA,
        COALESCE(PI.VALOR_DOCUMENTO,0), PR.NUMERO_ORDEM, COALESCE(PE.APRESENTANTE_CPF_CNPJ,''),
        COALESCE(PE.ADQUIRENTE_CPF_CNPJ,''), COALESCE(PI.VALOR_ITBI,0), COALESCE(PI.VALOR_MERCADO,0),
        COALESCE(PI.SELO_TABELIONATO,'0'), COALESCE(PI.QUANTIDADE_PAGINA,1),
        COALESCE(PI.QUANTIDADE_UNIDADE_AUTONOMA,0), PR.TIPO_PROTOCOLO, COALESCE(I.CODIGO_TABELA,'0'),
        COALESCE( PR.livro, '1'), CAST(COALESCE(PR.folha_numero,1) AS INTEGER),
        COALESCE(PI.quantidade_unidade_autonoma,0), PR.codigo_acesso_online, E.motivo_reducao,
        COALESCE(N.acao_to,''), coalesce(PE.TIPO_COBRANCA,'2')
      FROM R_PROTOCOLO PR, R_PEDIDO PE, R_PEDIDO_ITEM PI, G_EMOLUMENTO E,
        G_EMOLUMENTO_ITEM I, G_NATUREZA_TITULO N
      WHERE PR.PEDIDO_ID = PE.PEDIDO_ID
      AND PE.PEDIDO_ID = PI.PEDIDO_ID       
      AND PI.NATUREZA_TITULO_ID = N.NATUREZA_TITULO_ID 
      AND PI.EMOLUMENTO_ITEM_ID = I.EMOLUMENTO_ITEM_ID
      AND COALESCE(I.CODIGO_TABELA,'') <> ''
      AND I.EMOLUMENTO_ID = E.EMOLUMENTO_ID
      AND PI.PEDIDO_ITEM_ID = :V_PEDIDO_ID
      AND (PR.TIPO_PROTOCOLO = '1' OR PR.TIPO_PROTOCOLO = '3')
      AND (PI.EXCLUI_DO_RELATORIO = 'N' OR PI.EXCLUI_DO_RELATORIO IS NULL OR PI.EXCLUI_DO_RELATORIO = '')       
      ORDER BY PI.PEDIDO_ITEM_ID ASC
      INTO :V_PEDIDO_ITEM_ID, :V_QUANTIDADE,
        :V_APRESENTANTE_NOME, :V_ADQUIRENTE_NOME,
        :V_CODIGO_TABELA,
        :V_DATA_PROTOCOLO, :V_VALOR_DOCUMENTO, :V_NUMERO_ORDEM,
        :V_APRESENTANTE_CPF, :V_ADQUIRENTE_CPF, :V_VALOR_ITBI, :V_VALOR_MERCADO, :V_SELO_TABELIONATO,
        :V_QUANTIDADE_PAGINA,:V_QUANTIDADE_UNIDADE_AUTONOMA, :V_TIPO_PROTOCOLO,
        :V_TIPO_ATO, :V_LIVRO, :V_FOLHA, :V_UND_AUTONOMA, :V_PEDIDO_ONLINE,
        :V_FATOR, :V_ACAO_TO, :V_TIPO_COBRANCA  DO
  BEGIN
    if (:V_QTDE_MENSAGEM < 11) then
    begin
        IF (:V_QUANTIDADE = 0) THEN
        BEGIN
          STATUS = 'ERRO';
          if (:MENSAGEM = '') then
          begin
            MENSAGEM = '* Quantidade não pode ser 0';
          end
          else
          begin
            MENSAGEM = :MENSAGEM||ASCII_CHAR(13)||'* Quantidade não pode ser 0';
          end
          V_QUANTIDADE = 1;
          V_QTDE_MENSAGEM = :V_QTDE_MENSAGEM + 1;
        END
        if (coalesce(:V_CODIGO_TABELA,'') = '') then
        begin
          STATUS = 'ERRO';
          if (:MENSAGEM = '') then
          begin
            MENSAGEM = '* Código do Ato não configurado em Emolumentos';
          end
          else
          begin
            MENSAGEM = :MENSAGEM||ASCII_CHAR(13)||'* Código do Ato não configurado em Emolumentos';
          end
          V_QTDE_MENSAGEM = :V_QTDE_MENSAGEM + 1;
        end
        if (:V_DATA_PROTOCOLO is null) then
        begin
          STATUS = 'ERRO';
          if (:MENSAGEM = '') then
          begin
            MENSAGEM = '* Data do protocolo não pode ser nulo';
          end
          else
          begin
            MENSAGEM = :MENSAGEM||ASCII_CHAR(13)||'* Data do protocolo não pode ser nulo';
          end
          V_QTDE_MENSAGEM = :V_QTDE_MENSAGEM + 1;
        end
        if (coalesce(:V_NUMERO_ORDEM,0) = 0) then
        begin
          STATUS = 'ERRO';
          if (:MENSAGEM = '') then
          begin
            MENSAGEM = '* Protocolo não pode ser nulo';
          end
          else
          begin
            MENSAGEM = :MENSAGEM||ASCII_CHAR(13)||'* Protocolo não pode ser nulo';
          end
          V_QTDE_MENSAGEM = :V_QTDE_MENSAGEM + 1;
        end
    
        IF (TRIM(COALESCE(:V_ADQUIRENTE_NOME,'')) <> '') THEN
        BEGIN
          V_NOME = :V_ADQUIRENTE_NOME;
        END
        ELSE
        BEGIN
          V_NOME = :V_APRESENTANTE_NOME;
        END
    
        IF (TRIM(COALESCE(:V_ADQUIRENTE_CPF,'')) <> '') THEN
        BEGIN
          V_CPF = :V_ADQUIRENTE_CPF;
        END
        ELSE
        BEGIN
          V_CPF = :V_APRESENTANTE_CPF;
        END
    
        SELECT TRIM(INTEIRO) FROM W_RETORNAR_INTEIRO(:V_CPF)
        INTO :V_CPF;
    
        SELECT FIRST 1 (COALESCE(ATO_NUMERO,1)), NUMERO, TIPO_REGISTRO
        FROM R_PEDIDO_ITEM_NUMERO
        WHERE PEDIDO_ITEM_ID = :V_PEDIDO_ITEM_ID
        INTO :V_NUMERO_REGISTRO, :V_MATRICULA, :V_TIPO_REGISTRO;
    
        --VALIDAR CPF E NOME
        IF (:V_CODIGO_TABELA IN (5067,5068,5069,5070,5071,5072,5073,5074,5075,5076,5077,5078,5062,5063,5064,5065,5079,5080,5081,5082,5083,5084,5085,5086,5087,5088,5089,5090,5091,5092,5093,5094,5095,5098,5099,5100,5143,5144,5146,5148,5149,5150,5152,5119)) THEN
        BEGIN
          if (coalesce(:V_CPF,'') = '') then
          begin
            STATUS = 'ERRO';
            if (:MENSAGEM = '') then
            begin
              MENSAGEM = '* Para essa solicitação é necessário informar o CPF/CNPJ.';
            end
            else
            begin
              MENSAGEM = :MENSAGEM||ASCII_CHAR(13)||'* Para essa solicitação é necessário informar o CPF/CNPJ.';
            end
            V_QTDE_MENSAGEM = :V_QTDE_MENSAGEM + 1;
          end
          if (coalesce(:V_NOME,'') = '') then
          begin
            STATUS = 'ERRO';
            if (:MENSAGEM = '') then
            begin
              MENSAGEM = '* Para essa solicitação é necessário informar o NOME da parte.';
            end
            else
            begin
              MENSAGEM = :MENSAGEM||ASCII_CHAR(13)||'* Para essa solicitação é necessário informar o NOME da parte.';
            end
            V_QTDE_MENSAGEM = :V_QTDE_MENSAGEM + 1;
          end
        END
    
        --VALIDAR MATRICULA
        IF (:V_CODIGO_TABELA IN (5067,5068,5069,5070,5071,5072,5073,5074,5075,5076,5077,5066,5080,5081,5084,5085,5086,5087,5088,5089,5090,5091,5092,5098,5099,5100)) THEN
        begin
          if (coalesce(:V_MATRICULA,0) = 0) then
          begin
            STATUS = 'ERRO';
            if (:MENSAGEM = '') then
            begin
              MENSAGEM = '* Para essa solicitação é necessário informar a MATRÍCULA ou REG. AUXILIAR.';
            end
            else
            begin
              MENSAGEM = :MENSAGEM||ASCII_CHAR(13)||'* Para essa solicitação é necessário informar a MATRÍCULA ou REG. AUXILIAR.';
            end
            V_QTDE_MENSAGEM = :V_QTDE_MENSAGEM + 1;
          end
        end
    
        --VALIDAR NUMERO REGISTRO
        IF (:V_CODIGO_TABELA IN (5067,5068,5069,5070,5071,5072,5073,5074,5075,5078,5063,5064,5065,5079,5082,5083,5084)) THEN
        begin
          IF (COALESCE(:V_NUMERO_REGISTRO,0) = 0) THEN
          begin
            STATUS = 'ERRO';
            if (:MENSAGEM = '') then
            begin
              MENSAGEM = '* Para essa solicitação é necessário informar o número de Registro/Averbação.';
            end
            else
            begin
              MENSAGEM = :MENSAGEM||ASCII_CHAR(13)||'* Para essa solicitação é necessário informar o número de Registro/Averbação.';
            end
            V_QTDE_MENSAGEM = :V_QTDE_MENSAGEM + 1;
          end
        end
    
        --VALIDAR NUMERO AVERBACAO
        IF (:V_CODIGO_TABELA IN (5077,5066,5098,5099,5100)) THEN
        begin
          IF (COALESCE(:V_NUMERO_REGISTRO,0) = 0) THEN
          begin
            STATUS = 'ERRO';
            if (:MENSAGEM = '') then
            begin
              MENSAGEM = '* Para essa solicitação é necessário informar o número de Averbação.';
            end
            else
            begin
              MENSAGEM = :MENSAGEM||ASCII_CHAR(13)||'* Para essa solicitação é necessário informar o número de Averbação.';
            end
