             else 'certidão de pacto antenupcial lavrada sob matrícula nº '||td.matricula||' no '||coalesce(td.cartorio,'')||', realizado em '||coalesce(LPAD(EXTRACT(DAY FROM td.dt_ass), 2, '0') || '/' ||LPAD(EXTRACT(MONTH FROM td.dt_ass), 2, '0') || '/' ||LPAD(EXTRACT(YEAR FROM td.dt_ass), 4, '0'),'') end
         from t_dados_certidao td where td.tipo_documento = 'A' and td.pessoa_id = :V_PESSOA_ID
         INTO :AUX do
         begin
           AUXA =  :AUX;
           if (STRING = '') then
           begin
             STRING = :AUX;
           end
           else
           begin
             STRING = STRING||', '||:AUX ;
           end
         end
      for select first 1 case char_length(trim(coalesce(td.matricula,''))) when 0 then 'certidão de pacto antenupcial lavrado no livro '||coalesce(td.livro,'')||
         ', as folhas nº '||coalesce(td.folha,'')||' termo nº '||coalesce(td.termo,'') ||' no '||coalesce(td.cartorio,'')||', realizado em '||coalesce(LPAD(EXTRACT(DAY FROM td.dt_ass), 2, '0') || '/' ||LPAD(EXTRACT(MONTH FROM td.dt_ass), 2, '0') || '/' ||LPAD(EXTRACT(YEAR FROM td.dt_ass), 4, '0'),'')
             else 'certidão de pacto antenupcial lavrada sob matrícula nº '||td.matricula||' no '||coalesce(td.cartorio,'')||', realizado em '||coalesce(LPAD(EXTRACT(DAY FROM td.dt_ass), 2, '0') || '/' ||LPAD(EXTRACT(MONTH FROM td.dt_ass), 2, '0') || '/' ||LPAD(EXTRACT(YEAR FROM td.dt_ass), 4, '0'),'') end
         from t_dados_certidao td where td.tipo_documento = 'A' and td.pessoa_id in (select  first 1 pessoa_conjuge_id
                                        from t_pessoa where pessoa_id =  :V_PESSOA_ID )
              INTO :AUX do
              begin
                 if (AUXA = '') then
           begin
             STRING = :AUX;
           end
           else
           begin
             --STRING = STRING||', '||:AUX ;
           end
              end
  SUSPEND;
END ^

ALTER PROCEDURE T_RETORNA_PAISFAL (REGISTRO_ID NUMERICO)
RETURNS (STRING VARCHAR(1000) CHARACTER SET ISO8859_1)
AS 
declare variable AUXM varchar(1000);
declare variable AUXP varchar(1000);
BEGIN
  STRING = '';
 select  Nome from v_pessoa_vinculo where registro_id = :REGISTRO_ID
and livro_natureza_id = 2 and tipo_cadastro_familia = '2'
         INTO :AUXM;
 select  coalesce(Nome,'') from v_pessoa_vinculo where registro_id = :REGISTRO_ID
and livro_natureza_id = 2 and tipo_cadastro_familia = '1'
into auxP;

  if (coalesce(AuxM,'') <> '')  then
  begin
    if (coalesce(AuxP,'') <> '')  then
    begin
      STRING =  AuxM||' e '||AuxP;
    end
    else
    begin
      STRING =  AuxM;
    end
  end
  else
  begin
    if (coalesce(AuxP,'') <> '')  then
    begin
      STRING = AuxP;
    end
  end
  SUSPEND;
END ^

ALTER PROCEDURE V_JUSTIF_SIRC (REGISTRO_ID NUMERICO,
TABELA VARCHAR_060)
RETURNS (JUSTIFICATIVA VARCHAR_1000)
AS 
declare variable V_SQL varchar(4000);
declare variable V_CODIGO VARCHAR_260;
BEGIN
  if (COALESCE(TABELA,'') = 'V_NASCIMENTO' ) then
  BEGIN
      SELECT replace(v.codigo_just_sirc,';','') from v_nascimento v where v.NASCIMENTO_ID = :registro_id
      INTO :v_codigo;
  END

  if (COALESCE(TABELA,'') = 'V_OBITO' ) then
  BEGIN
      SELECT replace(v.codigo_just_sirc,';','') from v_OBITO v where v.OBITO_ID = :registro_id
      INTO :v_codigo;
  END

  if (COALESCE(TABELA,'') = 'V_CASAMENTO' ) then
  BEGIN
      SELECT replace(v.codigo_just_sirc,';','') from v_CASAMENTO v where v.CASAMENTO_ID = :registro_id
      INTO :v_codigo;
  END

  if (COALESCE(V_CODIGO,'') <> '' ) then
  BEGIN

   V_SQL = ' select descricao from v_justificativa_sirc where TABELA = '||''''||TABELA||'''';
   V_SQL = V_SQL ||' AND  INDICE in ';
   V_SQL = V_SQL ||' ( '||V_CODIGO||' )';

    for execute statement V_SQL
          into :JUSTIFICATIVA DO
       BEGIN
        suspend;
      end
  END
END ^

ALTER PROCEDURE V_PESQUISA_PAI_AUSENTE (DATA_INI DATE,
DATA_FIM DATE)
RETURNS (A_TERMO NUMERICO,
NASCIMENTO_ID NUMERICO,
REG_NOME VARCHAR_120,
REG_DATA_NASCIMENTO DATAHORA,
A_DATA_ASSENTO DATAHORA,
A_FOLHA NUMERICO,
NUMERO_LIVRO NUMERICO,
NOME_MAE VARCHAR_120,
TELEFONE_MAE VARCHAR_030,
ENDERECO_MAE VARCHAR_260)
AS 
BEGIN      
      FOR 
      SELECT A_TERMO,
       N.NASCIMENTO_ID,
       N.REG_NOME,
       N.REG_DATA_NASCIMENTO,
       N.A_DATA_ASSENTO,
       A_FOLHA,
       LA.NUMERO_LIVRO,
       VP.NOME AS NOME_MAE,
       '(' || VP.DDD || ')' || VP.TELEFONE AS TELEFONE_MAE,
       vp.ENDERECO || ',' || VP.BAIRRO || ',' || ( SELECT RETORNO FROM S_PRIMEIRA_LETRA_MAIUSCULA(VP.CIDADE)) ||   '-'  || VP.UF  as ENDERECO_MAE
        FROM V_NASCIMENTO N
        LEFT OUTER JOIN V_LIVRO_ANDAMENTO LA
        ON   N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID
        LEFT OUTER JOIN V_PESSOA_VINCULO PV
        ON   N.NASCIMENTO_ID = PV.REGISTRO_ID
        AND PV.LIVRO_NATUREZA_ID = 1
        AND TIPO_CADASTRO_FAMILIA IN( '2','0')
        LEFT JOIN v_pessoa VP ON VP.pessoa_id = PV.pessoa_id
        WHERE NOT NASCIMENTO_ID IN (SELECT REGISTRO_ID
                                FROM V_PESSOA_VINCULO PV
                                LEFT JOIN V_PESSOA VP
                                ON PV.pessoa_id = VP.pessoa_id
                                WHERE LIVRO_NATUREZA_ID = 1
                                AND VP.sexo = 'M')
        AND LA.ANTIGO <> 'S'
        AND N.A_DATA_ASSENTO
        BETWEEN CAST(:DATA_INI AS TIMESTAMP)
        AND CAST(:DATA_FIM AS TIMESTAMP) + 0.9999
        union
        SELECT A_TERMO, N.NASCIMENTO_ID, N.REG_NOME, N.REG_DATA_NASCIMENTO,
        N.A_DATA_ASSENTO, A_FOLHA, LA.NUMERO_LIVRO,  n.filiacao_mae_la AS NOME_MAE,
        '' AS TELEFONE_MAE,
        '' AS ENDERECO_MAE
        FROM V_NASCIMENTO N
        LEFT OUTER JOIN V_LIVRO_ANDAMENTO LA
        ON   N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID
        WHERE NASCIMENTO_ID IN (SELECT nascimento_id
                                FROM V_nascimento
                                WHERE a_situacao is null
                                AND filiacao_pai_la is null)
        AND N.A_DATA_ASSENTO
        BETWEEN CAST(:DATA_INI AS TIMESTAMP)
        AND CAST(:DATA_FIM AS TIMESTAMP) + 0.9999
        AND N.a_termo > 0
        AND N.reg_data_nascimento IS NOT NULL
        AND LA.numero_livro IS NOT NULL
        AND N.A_FOLHA IS NOT NULL
        order by 1  desc
       INTO
          :A_TERMO,
          :NASCIMENTO_ID,
          :REG_NOME,
          :REG_DATA_NASCIMENTO,
          :A_DATA_ASSENTO,
          :A_FOLHA,
          :NUMERO_LIVRO,
          :NOME_MAE,
          :TELEFONE_MAE,
          :ENDERECO_MAE

       DO
       BEGIN
        SUSPEND;
       END
END ^

ALTER PROCEDURE V_PESQUISA_PESSOA (V_PARTE_LIVRO_ID NUMERICO,
V_LIVRO_NATUREZA_ID NUMERICO,
V_REGISTRO_ID NUMERICO)
RETURNS (NOME VARCHAR(60) CHARACTER SET ISO8859_1,
REGISTRO_ID NUMERICO,
NOME_PAI VARCHAR(60) CHARACTER SET ISO8859_1,
NOME_MAE VARCHAR(60) CHARACTER SET ISO8859_1,
TB_PROFISSAO_ID NUMERICO,
PESSOA_ID NUMERICO,
TB_ESTADOCIVIL_ID NUMERICO,
TB_DOCUMENTOTIPO_ID NUMERICO,
NATURALIDADE_CIDADE_ID NUMERICO,
PAIS_NASCIMENTO NUMERICO,
CIDADE_NAT_ID NUMERICO,
CIDADE_RES_ID NUMERICO,
ORGAO_EMISSOR_ID NUMERICO,
CIDADE_RES VARCHAR(60) CHARACTER SET ISO8859_1,
CIDADE_NAT VARCHAR(60) CHARACTER SET ISO8859_1,
COMUNICADO_DOCUMENTO_ID NUMERICO,
CARTORIO_BRASIL_ID NUMERICO,
UF VARCHAR(2) CHARACTER SET ISO8859_1,
NUMERO_TERMO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_LIVRO VARCHAR(10) CHARACTER SET ISO8859_1,
NUMERO_FOLHA VARCHAR(10) CHARACTER SET ISO8859_1,
NOME_CARTORIO_TABELIONATO VARCHAR(60) CHARACTER SET ISO8859_1,
FOLHA_INICIAL_TABELIONATO VARCHAR(10) CHARACTER SET ISO8859_1,
FOLHA_FINAL_TABELIONATO VARCHAR(10) CHARACTER SET ISO8859_1,
DATA_LAVRATURA_TABELIONATO TIMESTAMP,
LIVRO_TABELIONATO NUMERIC(10, 2),
TPO_CADASTRO_GERAL VARCHAR(3) CHARACTER SET ISO8859_1,
DATA_NASCIMENTO TIMESTAMP,
CIDADE_CARTORIO NUMERICO,
SEXO VARCHAR(1) CHARACTER SET ISO8859_1,
DOCUMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
JUIZ_MANDATO VARCHAR(30) CHARACTER SET ISO8859_1,
JUIZ_SENTENCA VARCHAR(30) CHARACTER SET ISO8859_1,
DATA_EXPEDICAO TIMESTAMP,
DATA_SENTENCA TIMESTAMP,
NUMERO_AUTOS VARCHAR(30) CHARACTER SET ISO8859_1,
PROTOCOLO_PROCESSO VARCHAR(30) CHARACTER SET ISO8859_1,
PROTOCOLO VARCHAR(30) CHARACTER SET ISO8859_1)
AS 
declare variable V_SQL varchar(10000);

begin

    V_SQL = ' ';
    V_SQL = '   SELECT
                P.NOME AS NOME,
                P.NOME_PAI AS NOME_PAI,
                P.NOME_MAE AS NOME_MAE,
                P.TB_PROFISSAO_ID,
                P.PESSOA_ID,
                P.TB_ESTADOCIVIL_ID,
                P.TB_DOCUMENTOTIPO_ID,
                P.NATURALIDADE_CIDADE_ID,
                P.PAIS_NASCIMENTO,
                P.CIDADE_NAT_ID,
                P.CIDADE_RES_ID,
                P.ORGAO_EMISSOR_ID,
                 (select first 1 cidade_nome
                 from g_cidade CR
                 where cr.cidade_id = p.cidade_res_id)as CIDADE_RES,
                (select first 1 cidade_nome
                from g_cidade CN
                where cn.cidade_id = p.cidade_nat_id) as CIDADE_NAT,
                CD.comunicado_documento_id,
                CD.CARTORIO_BRASIL_ID,
                CD.UF,
                CD.NUMERO_TERMO,
                CD.NUMERO_LIVRO,
                CD.NUMERO_FOLHA,
                E.NOME_CARTORIO_TABELIONATO,
                E.FOLHA_INICIAL_TABELIONATO,
                E.FOLHA_FINAL_TABELIONATO,
                E.DATA_LAVRATURA_TABELIONATO,
                E.LIVRO_TABELIONATO,
                CD.TPO_CADASTRO_GERAL,
                P.DATA_NASCIMENTO,
                CD.CIDADE_ID AS CIDADE_CARTORIO,
                P.SEXO,
                P.DOCUMENTO,
                E.JUIZ_MANDATO,
                E.JUIZ_SENTENCA,
                E.data_expedicao,
                E.data_sentenca,
                E.numero_autos,
                E.protocolo_processo,
                E.protocolo
                FROM  V_PESSOA_VINCULO PV
                left join V_PESSOA P ON PV.PESSOA_ID = P.PESSOA_ID
                left join V_LIVROE E on E.LIVROE_ID = PV.REGISTRO_ID
                left join V_COMUNICADO_DOCUMENTO CD ON E.LIVROE_ID = CD.REGISTRO_ID
                WHERE 1=1
                AND PV.tb_partelivroe_id = '||:V_PARTE_LIVRO_ID||'
                AND PV.LIVRO_NATUREZA_ID = '||:V_LIVRO_NATUREZA_ID||'
                AND PV.REGISTRO_ID = '||:V_REGISTRO_ID||' ';

    FOR EXECUTE STATEMENT :V_SQL INTO
        :NOME, :NOME_PAI, :NOME_MAE, :TB_PROFISSAO_ID, :PESSOA_ID,
        :TB_ESTADOCIVIL_ID, :TB_DOCUMENTOTIPO_ID, :NATURALIDADE_CIDADE_ID,
        :PAIS_NASCIMENTO, :CIDADE_NAT_ID, :CIDADE_RES_ID, :ORGAO_EMISSOR_ID,
        :CIDADE_RES, :CIDADE_NAT, :comunicado_documento_id, :CARTORIO_BRASIL_ID,
        :UF, :NUMERO_TERMO, :NUMERO_LIVRO, :NUMERO_FOLHA, :NOME_CARTORIO_TABELIONATO,
        :FOLHA_INICIAL_TABELIONATO, :FOLHA_FINAL_TABELIONATO, :DATA_LAVRATURA_TABELIONATO,
        :LIVRO_TABELIONATO, :TPO_CADASTRO_GERAL, :DATA_NASCIMENTO, :CIDADE_CARTORIO, :SEXO,
        :DOCUMENTO, :JUIZ_MANDATO, :JUIZ_SENTENCA, :data_expedicao, :data_sentenca,
        :numero_autos, :protocolo_processo, :protocolo DO
    begin
        suspend;
    end
END ^

ALTER PROCEDURE V_PESQUISA_SERVICO (V_DATA_INI DATE,
V_DATA_FIM DATE)
RETURNS (NUMERO_PROTOCOLO DINHEIRO,
ATO_PRATICADO VARCHAR_001,
SERVICO VARCHAR_260,
FUNDESP VARCHAR_003,
LIVRO_NATUREZA_ID DINHEIRO,
USUARIO_ID DINHEIRO,
DATA_ATO DATAHORA,
QTD DINHEIRO,
EMOLUMENTO DINHEIRO,
TAXA_JUDICIARIA DINHEIRO,
REGISTRO_ID DINHEIRO,
VALOR DINHEIRO,
IMPRESSAO DINHEIRO,
DESCRICAO VARCHAR_260,
SITUACAO VARCHAR_003,
NUMERO_SERIE VARCHAR_030)
AS 
BEGIN      
      FOR 
      SELECT coalesce(st.ato_praticado,'S'),
       COALESCE(GS.descricao,st.descricao) AS SERVICO,
       coalesce(ST.FUNDESP,'1') AS FUNDESP,
       coalesce(SR.LIVRO_NATUREZA_ID,gs.campo_id),
      COALESCE(SR.USUARIO_ID, GS.usuario_id),
      COALESCE(SR.DATA_ATO,GS.data),
      COALESCE(SR.QTD,1),
      COALESCE(GS.valor_emolumento,SR.EMOLUMENTO),
      COALESCE(GS.valor_taxa_judiciaria,SR.TAXA_JUDICIARIA),
      COALESCE(SR.REGISTRO_ID,CAMPO_ID),
      COALESCE(GS.valor_total,SR.VALOR),
      coalesce(SR.IMPRESSAO,'1'),
      COALESCE(SR.DESCRICAO,GS.descricao),
      COALESCE(SR.SITUACAO,4),
       SR.NUMERO_SERIE,
      COALESCE(SR.numero_protocolo,0)
        FROM G_SELO_LIVRO GS
        left outer JOIN V_SERVICO_REALIZADO SR ON GS.campo_id = SR.servico_realizado_id
       LEFT outer JOIN v_livroe VE ON VE.livroe_id = GS.campo_id
      LEFT OUTER JOIN V_SERVICO_TIPO ST ON    SR.SERVICO_TIPO_ID = ST.SERVICO_TIPO_ID
       LEFT outer JOIN v_casamento CV ON CV.casamento_id = GS.campo_id
        WHERE GS.data  BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)      AND
        CAST(:v_data_fim AS TIMESTAMP) + 0.9999
        AND TABELA IN( 'V_SERVICO_REALIZADO', 'V_CASAMENTO','V_LIVROE','V_LIVRO_E')
        ORDER BY SR.LIVRO_NATUREZA_ID, SR.NUMERO_SERIE, SR.DATA_ATO, SR.SERVICO_REALIZADO_ID
       INTO
         :ato_praticado ,
         :SERVICO  ,
         :FUNDESP   ,
         :LIVRO_NATUREZA_ID  ,
         :usuario_id   ,
         :DATA_ATO ,
         :QTD  ,
         :EMOLUMENTO  ,
         :TAXA_JUDICIARIA ,
         :REGISTRO_ID  ,
         :VALOR      ,
         :IMPRESSAO  ,
         :DESCRICAO ,
         :SITUACAO  ,
         :NUMERO_SERIE,
         :numero_protocolo
       DO
       BEGIN
        SUSPEND;
       END
END ^

ALTER PROCEDURE V_PESQUISA_SERVICOS (V_DATA_INI DATE,
V_DATA_FIM DATE)
RETURNS (NUMERO_PROTOCOLO DINHEIRO,
ATO_PRATICADO VARCHAR_001,
SERVICO VARCHAR_260,
FUNDESP VARCHAR_003,
LIVRO_NATUREZA_ID DINHEIRO,
USUARIO_ID DINHEIRO,
DATA_ATO DATAHORA,
QTD DINHEIRO,
EMOLUMENTO DINHEIRO,
TAXA_JUDICIARIA DINHEIRO,
REGISTRO_ID DINHEIRO,
VALOR DINHEIRO,
IMPRESSAO DINHEIRO,
DESCRICAO VARCHAR_260,
SITUACAO VARCHAR_003,
NUMERO_SERIE VARCHAR_030)
AS 
BEGIN      
      FOR 
      SELECT coalesce(st.ato_praticado,'S'),
       COALESCE(GS.descricao,st.descricao) AS SERVICO,
       coalesce(ST.FUNDESP,'1') AS FUNDESP,
       coalesce(SR.LIVRO_NATUREZA_ID,CV.a_livro_natureza_id),
      COALESCE(SR.USUARIO_ID, GS.usuario_id),
      COALESCE(SR.DATA_ATO,GS.data),
      COALESCE(SR.QTD,1),
      COALESCE(GS.valor_emolumento,SR.EMOLUMENTO),
      COALESCE(GS.valor_taxa_judiciaria,SR.TAXA_JUDICIARIA),
      COALESCE(SR.REGISTRO_ID,CAMPO_ID),
      COALESCE(GS.valor_total,SR.VALOR),
      coalesce(SR.IMPRESSAO,'1'),
      COALESCE(SR.DESCRICAO,GS.descricao),
      COALESCE(SR.SITUACAO,4),
       SR.NUMERO_SERIE,
      COALESCE(SR.numero_protocolo,0)
        FROM G_SELO_LIVRO GS
        left outer JOIN V_SERVICO_REALIZADO SR ON GS.campo_id = SR.servico_realizado_id
        AND GS.tabela = 'V_SERVICO_REALIZADO'
       LEFT outer JOIN v_livroe VE ON VE.livroe_id = GS.campo_id
      LEFT OUTER JOIN V_SERVICO_TIPO ST ON    SR.SERVICO_TIPO_ID = ST.SERVICO_TIPO_ID
       LEFT outer JOIN v_casamento CV ON CV.casamento_id = GS.campo_id
        WHERE GS.data  BETWEEN CAST(:V_DATA_INI AS TIMESTAMP)      AND
        CAST(:v_data_fim AS TIMESTAMP) + 0.9999
        AND TABELA IN( 'V_SERVICO_REALIZADO', 'V_CASAMENTO','V_LIVROE','V_LIVRO_E')
        ORDER BY SR.LIVRO_NATUREZA_ID, SR.NUMERO_SERIE, SR.DATA_ATO, SR.SERVICO_REALIZADO_ID
       INTO
         :ato_praticado ,
         :SERVICO  ,
         :FUNDESP   ,
         :LIVRO_NATUREZA_ID  ,
         :usuario_id   ,
         :DATA_ATO ,
         :QTD  ,
         :EMOLUMENTO  ,
         :TAXA_JUDICIARIA ,
         :REGISTRO_ID  ,
         :VALOR      ,
         :IMPRESSAO  ,
         :DESCRICAO ,
         :SITUACAO  ,
         :NUMERO_SERIE,
         :numero_protocolo
       DO
       BEGIN
        SUSPEND;
       END
END ^

ALTER PROCEDURE V_PESQUISA_SERVICO_REALIZADO (VPREGISTROID NUMERIC(18, 2),
VPNATUREZAID NUMERIC(18, 2))
RETURNS (VPSERVICOTIPO VARCHAR(200) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE VTIPO VARCHAR(20) CHARACTER SET ISO8859_1;
DECLARE VARIABLE VLISTA VARCHAR(1000) CHARACTER SET ISO8859_1;
BEGIN
  VLISTA = '';
  FOR SELECT SERVICO_TIPO_ID FROM V_SERVICO_TIPO
      WHERE LIVRO_NATUREZA_ID = :VPNATUREZAID INTO :VTIPO DO
  BEGIN
    if (:VLISTA = '') then
         VLISTA = VTIPO;
    ELSE VLISTA = VLISTA || ', ' || VTIPO;
  END
  VPSERVICOTIPO = VLISTA;
  SUSPEND;
END ^

