AS 
declare variable VNATUREZA integer;
declare variable V_COUNT integer;
declare variable V_DESCRICAO VARCHAR_260;
declare variable V_DATAINISECULAR timestamp;
declare variable SQLNASCIMENTO varchar(5000);
declare variable SQLOBITO varchar(5000);
declare variable SQLCASAMENTO varchar(5000);
declare variable VDTINI varchar(35);
declare variable VSQLCOMPLEMENTOCASAMENTO varchar(5000);
declare variable VSQLCOMPLEMENTOOBITO varchar(5000);
declare variable VDTFIM varchar(35);
declare variable SQLUNIONLVE varchar(5000);
declare variable V_TERMOSQLWHERE varchar(50);
declare variable V_SQLGERAL TEXTO_BLOB;
declare variable V_TABELAW varchar(100);
begin
--
  V_COUNT = 0;
  vDtIni = ' ';
  vDtFim = ' ';
  SQLUNIONLVE = ' ';
  SQLNASCIMENTO = ' ';
  VSQLCOMPLEMENTOCASAMENTO = ' ';
  VSQLCOMPLEMENTOOBITO = ' ';
  V_TABELAW = '';
  V_DATAINISECULAR = CAST('1920-01-01' AS timestamp);
  vNatureza = 0;
  if ((:v_tabela = '') or (:V_TABELA = 'TODOS')or (V_TABELA IS NULL)  ) then
  BEGIN
    V_TABELAW = '';
  END ELSE
  BEGIN
    V_TABELAW = ' AND TABELA in (''V_LIVROE'','''||:V_TABELA||''')';
  END
  if (COALESCE(:V_TERMO,0) = 0) then
  begin
  vDtIni = ''''||cast(:V_DATA_INICIAL AS VARCHAR(30))||'''';
  vDtFim = ''''||cast(:V_DATA_FINAL AS VARCHAR(30))||'''';
  V_TERMOSQLWHERE = '1 = 1 ';
  vNatureza = :V_NATUREZA_ID;
  end else
  begin
    vDtIni = ''''||cast(:V_DATAINISECULAR AS VARCHAR(30))||'''';
    vDtFim = ''''||cast(current_date AS VARCHAR(30))||'''';
    V_TERMOSQLWHERE =' TERMO BETWEEN '||CAST(:V_TERMO AS VARCHAR(15)) || 'AND ' || CAST(:V_TERMOFIM AS VARCHAR(15));
    vNatureza = :V_NATUREZA_ID;
  end

  if((vNatureza = 4) or (vNatureza = 5))then
  begin
    vsqlcomplementoCasamento = ' left outer join V_LIVRO_ANDAMENTO LA on N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID  AND N.A_LIVRO_NATUREZA_ID in (4, 5) '||
                      ' left join V_LIVRO_NATUREZA Nt on N.A_LIVRO_NATUREZA_ID = nt.livro_natureza_id '||
                      ' where '||
                      '  1 = 1 '||
                      '  AND N.A_DATA_ASSENTO between cast('||vDtIni||' as timestamp) and cast('||vDtFim||' as timestamp) '||
                      '  AND N.A_LIVRO_NATUREZA_ID in ('||vNatureza||') ';
  end else
  begin
    vsqlcomplementoCasamento = ' left outer join V_LIVRO_ANDAMENTO LA on N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID  '||
                      ' left join V_LIVRO_NATUREZA Nt on N.A_LIVRO_NATUREZA_ID = nt.livro_natureza_id '||
                      ' where '||
                      '  1 = 1 '||
                      '  AND N.A_DATA_ASSENTO between cast('||vDtIni||' as timestamp) and cast('||vDtFim||' as timestamp) '||
                      '  AND N.A_LIVRO_NATUREZA_ID in (4, 5) ';
  end

  if((vNatureza = 2) or (vNatureza = 3))then
  begin
    vsqlcomplementoObito = ' left outer join V_LIVRO_ANDAMENTO LA on N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID  AND N.A_LIVRO_NATUREZA_ID in (2, 3) '||
                      ' left join V_LIVRO_NATUREZA Nt on N.A_LIVRO_NATUREZA_ID = nt.livro_natureza_id '||
                      ' where '||
                      '  1 = 1 '||
                      '  AND N.A_DATA_ASSENTO between cast('||vDtIni||' as timestamp) and cast('||vDtFim||' as timestamp) '||
                      '  AND N.A_LIVRO_NATUREZA_ID in ('||vNatureza||') ';
  end else
  begin
    vsqlcomplementoObito = ' left outer join V_LIVRO_ANDAMENTO LA on N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID  '||
                      ' left join V_LIVRO_NATUREZA Nt on N.A_LIVRO_NATUREZA_ID = nt.livro_natureza_id '||
                      ' where '||
                      '  1 = 1 '||
                      '  AND N.A_DATA_ASSENTO between cast('||vDtIni||' as timestamp) and cast('||vDtFim||' as timestamp) '||
                      '  AND N.A_LIVRO_NATUREZA_ID in (2, 3) ';
  end

if ((:v_tabela = '') or (:V_TABELA = 'TODOS')or (:V_TABELA IS NULL) or (:V_TABELA = 'V_LIVROE')) then
begin -- SELECT DO LIVRO E
  SQLUNIONLVE = 'select '||
                 '  LA.NUMERO_LIVRO AS NUMERO_LIVRO,'||
                 '  LA.SIGLA  AS SIGLA,'||
                 '  NE.A_FOLHA AS FOLHA,'||
                 '  NE.A_TERMO AS TERMO,'||
                 '  NE.A_SITUACAO AS SITUACAO,'||
                 '  NE.A_DATA_ASSENTO AS DATA_ASSENTO,'||
                 '  NE.data_lavratura_tabelionato AS DATA_OCORRENCIA,'||
                 '  null AS LOCAL_OCORRENCIA,'||
                 '  null AS GEMEO,'||
                 '  null AS SEXO,'||
                 '  null AS DATA_NASCIMENTO,'||
                 '  NE.livroe_id AS REGISTRO_ID,'||
                 '  NE.A_LIVRO_NATUREZA_ID AS NATUREZA_ID,'||
                 '  NE.A_LIVRO_ANDAMENTO_ID AS LIVRO_ANDAMENTO,'||
                 '  coalesce (Coalesce(NE.a_primeira_parte,NE.a_segunda_parte),''NAO DECLARADO'')  AS PESSOA,'||
                 '  NE.a_usuario_id AS USUARIO_ID,'||
                 '  NE.TEXTO_OBSERVACAO_CERTIDAO  AS TEXTO_OBSERV,'||
                 '  NULL AS DECLARANTE_TIPO,'||
                 '  NULL  AS BAIRRO_NASCIMENTO,'||
                 '  NE.cidade_id_tabelionato  AS CIDADE_ID_PARTO,'||
                 '  NULL AS MAE_PARTO_CIDADEID,'||
                 '  NULL AS DECLARACAO_REGISTRO,'||
                 '  null AS HORA_OCORRENCIA,'||
                 '  null AS BAIRRO_OCORRENCIA,'||
                 '  null AS LOGRAD_OCORRENCIA,'||
                 '  null AS ATESTANTE_PRIMARIO,'||
                 '  NE.protocolo_processo AS NUMEROPROCESSO,'||
                 '  NE.data_sentenca AS DATA_SENTENCA,'||
                 '  null AS ELEITOR_OBITO,'||
                 '  null AS CRM_ATESTANTE,'||
                 '  null AS NOMENOIVO,'||
                 '  null AS NOMENOIVA,'||
                 '  null AS CPF,'||
                 '  null AS JUST_CAMPOS_OBRIG,'||
                 '  0 AS INDICE_REG,'||
                 '  CAST(''V_LIVROE'' AS VARCHAR(15)) AS tabela,'||
                 '  NULL AS NOIVO_NOME_NOVO,'||
                 '  NULL AS NOIVA_NOME_NOVO,'||
                 '  NULL AS PACTO_DT_LAVRATURA,'||
                 '  NULL AS CARTORIO_BRASIL_ID,'||
                 '  NE.a_segunda_parte AS ANT_NOME_MAE,'||
                 '  NE.a_primeira_parte AS ANT_NOME_PAI,'||
                 '  lt.descricao AS NATUREZA,'||
                 '  NE.ORG_EMIS_DOC_ORIGINAL,'||
                 '  NE.CNS_CONSULADO,'||
                 '  NE.INF_COMPL_CONSULADO,'||
                 '  NE.LIVROE_TIPO_ID, '||
                 '  0 AS NRTRANSCRICAO, '||
                 '  NULL AS CDS_NACIONALIDADE '||
             ' from  '||
             '      V_LIVROE NE'||
             '      left join V_LIVRO_ANDAMENTO LA on (NE.a_livro_andamento_id = LA.LIVRO_ANDAMENTO_ID)'||
             '      left join v_livroe_tipo lt on (NE.livroe_tipo_id = lt.livroe_tipo_id)'||
             ' WHERE '||
             ' 1 = 1'||
             ' and NE.A_DATA_ASSENTO between cast('||vDtIni||' as timestamp) and cast('||vDtFim||' as timestamp) '||
             ' and NE.A_LIVRO_NATUREZA_ID = 7 '||
             ' AND NE.ORG_EMIS_DOC_ORIGINAL is not null '||
             ' AND NE.CNS_CONSULADO is not null  '||
             ' AND NE.LIVROE_TIPO_ID in (4,5,6) '||
                ASCII_CHAR(13);

          V_SQLGERAL = trim(SQLUNIONLVE);

end
if ((:v_tabela = '') or (:V_TABELA = 'TODOS')or (:V_TABELA IS NULL) or (:V_TABELA = 'V_NASCIMENTO')) then
begin --SELECT DO NASCIMENTO

  SQLNASCIMENTO = 'select '||
                  '   LA.NUMERO_LIVRO AS NUMERO_LIVRO, '||
                  '   LA.SIGLA AS SIGLA, '||
                  '   N.A_FOLHA AS FOLHA, '||
                  '   N.A_TERMO AS TERMO, '||
                  '   N.A_SITUACAO AS SITUACAO, '||
                  '   N.A_DATA_ASSENTO AS DATA_ASSENTO, '||
                  '   N.REG_DATA_NASCIMENTO AS DATA_OCORRENCIA, '||
                  '   N.REG_LOCAL_OCORRENCIA AS LOCAL_OCORRENCIA, '||
                  '   N.REG_GEMEO AS GEMEO,'||
                  '   N.REG_SEXO AS SEXO,'||
                  '   N.REG_DATA_NASCIMENTO AS DATA_NASCIMENTO,'||
                  '   N.NASCIMENTO_ID AS REGISTRO_ID,'||
                  '   N.A_LIVRO_NATUREZA_ID AS NATUREZA_ID,'||
                  '   N.A_LIVRO_ANDAMENTO_ID AS LIVRO_ANDAMENTO,'||
                  '   coalesce(N.REG_NOME,''NAO DECLARADO'') AS PESSOA,'||
                  '   N.A_USUARIO_ID AS USUARIO_ID,'||
                  '   N.TEXTO_OBSERVACAO_CERTIDAO AS TEXTO_OBSERV,'||
                  '   N.DECLARANTE_TIPO AS DECLARANTE_TIPO,'||
                  '   N.REG_LOCAL_UF AS BAIRRO_NASCIMENTO,'||
                  '   N.REG_CIDADE_ID AS CIDADE_ID_PARTO,'||
                  '   N.PARTO_CIDADE_ID AS MAE_PARTO_CIDADEID,'||
                  '   N.DNV_NUMERO AS DECLARACAO_REGISTRO,'||
                  '   cast(N.REG_HORA as time) AS HORA_OCORRENCIA,'||
                  '   null AS BAIRRO_OCORRENCIA,'||
                  '   null AS LOGRAD_OCORRENCIA,'||
                  '   null AS ATESTANTE_PRIMARIO,'||
                  '   N.NUMERO_PROCESSO AS NUMEROPROCESSO,'||
                  '   N.DATA_SENTENCA AS DATA_SENTENCA,'||
                  '   null AS ELEITOR_OBITO,'||
                  '   null AS CRM_ATESTANTE,'||
                  '   null AS NOMENOIVO,'||
                  '   null AS NOMENOIVA,'||
                  '   N.CPF_REGISTRADO AS CPF,'||
                  '   N.JUST_CAMPOS_OBRIG,'||
                  '   null AS INDICE_REG,'||
                  '   CAST(''V_NASCIMENTO'' AS VARCHAR(15)) AS tabela,'||
                  '   NULL AS NOIVO_NOME_NOVO,'||
                  '   NULL AS NOIVA_NOME_NOVO,'||
                  '   NULL AS PACTO_DT_LAVRATURA,'||
                  '   NULL AS CARTORIO_BRASIL_ID,'||
                  '   NULL AS ANT_NOME_MAE,'||
                  '   NULL AS ANT_NOME_PAI,'||
                  '   nt.descricao AS NATUREZA,'||
                  '   NULL AS ORG_EMIS_DOC_ORIGINAL,'||
                  '   NULL ASCNS_CONSULADO,'||
                  '   NULL INF_COMPL_CONSULADO,'||
                  '   0 as LIVROE_TIPO_ID, '||
                  '   LIVROE_ID AS NRTRANSCRICAO, '||
                  '   CDG_NACIONALIDADE  AS CDS_NACIONALIDADE '||
                  ' from '||
                  '     V_NASCIMENTO N '||
                  ' left outer join V_LIVRO_ANDAMENTO LA on N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID '||
                  ' left join V_LIVRO_NATUREZA Nt on N.A_LIVRO_NATUREZA_ID = nt.livro_natureza_id '||
                  ' where '||
                  '     1 = 1 '||
                  '     AND N.A_DATA_ASSENTO between cast('||vDtIni||' as timestamp) and cast('||vDtFim||' as timestamp) '||
                  '     and n.reg_nome not like ''%Transporte do Termo%'' '||
                ASCII_CHAR(13);

         if ((V_SQLGERAL <> '') and (not(V_SQLGERAL is null)))  then
          V_SQLGERAL = V_SQLGERAL||ASCII_CHAR(13)||' UNION ALL '||ASCII_CHAR(13)||trim(SQLNASCIMENTO);
        else
         V_SQLGERAL = trim(SQLNASCIMENTO);
end

if ((:v_tabela = '') or (:V_TABELA = 'TODOS')or (:V_TABELA IS NULL) or (:V_TABELA = 'V_CASAMENTO')) then
begin  --SELECT DO CASAMENTO
 SQLCASAMENTO = 'select '||
                '     LA.NUMERO_LIVRO AS NUMERO_LIVRO,'||
                '     LA.SIGLA AS SIGLA,'||
                '     N.A_FOLHA AS FOLHA,'||
                '     N.A_TERMO AS TERMO,'||
                '     N.A_SITUACAO AS SITUACAO,'||
                '     N.A_DATA_ASSENTO AS DATA_ASSENTO,'||
                '     N.EDITAL_DATA_EMISSAO AS DATA_OCORRENCIA,'||
                '     N.CASAMENTO_TB_LOCAL_ID AS LOCAL_OCORRENCIA,'||
                '     null AS GEMEO,'||
                '     NULL AS SEXO,'||
                '     NULL AS DATA_NASCIMENTO,'||
                '     N.CASAMENTO_ID AS REGISTRO_ID,'||
                '     N.A_LIVRO_NATUREZA_ID AS NATUREZA_ID,'||
                '     N.A_LIVRO_ANDAMENTO_ID AS LIVRO_ANDAMENTO,'||
                '     (coalesce(N.noivo_nome_novo,n.NOIVO_NOME_ATUAL)||'' / ''||coalesce(n.noiva_nome_novo,n.NOIVA_NOME_ATUAL))  AS PESSOA,'||
                '     N.A_USUARIO_ID AS USUARIO_ID,'||
                '     N.TEXTO_OBSERVACAO_CERTIDAO AS TEXTO_OBSERV,'||
                '     null  AS DECLARANTE_TIPO,'||
                '     null  AS BAIRRO_NASCIMENTO,'||
                '     null  AS CIDADE_ID_PARTO,'||
                '     null  AS MAE_PARTO_CIDADEID,'||
                '     null  AS DECLARACAO_REGISTRO,'||
                '     cast(N.CASAMENTO_HORA as time)   AS HORA_OCORRENCIA,'||
                '     case N.CASAMENTO_REGIME when 1 then ''COMUNHAO_PARCIAL'' when 2 then ''COMUNHAO_UNIVERSAL'' when 3 then ''SEPARACAO_BENS'' when 4 then ''SEPARACAO_BENS'' when 5 then ''PARTICIPACAO_FINAL_AQUESTOS'' end AS BAIRRO_OCORRENCIA,'||
                '     null  AS LOGRAD_OCORRENCIA,'||
                '     null  AS ATESTANTE_PRIMARIO,'||
                '     N.PROCESSO_NUMERO AS NUMEROPROCESSO,'||
                '     N.DATA_LAVRATURA_ANTENUPCIAL AS DATA_SENTENCA,'||
                '     null AS ELEITOR_OBITO,'||
                '     null AS CRM_ATESTANTE,'||
                '     N.NOIVO_NOME_ATUAL AS NOMENOIVO,'||
                '     N.NOIVA_NOME_ATUAL AS NOMENOIVA,'||
                '     null  AS CPF,'||
                '     N.JUST_CAMPOS_OBRIG AS JUST_CAMPOS_OBRIG,'||
                '     null AS INDICE_REG,'||
                '     CAST(''V_CASAMENTO'' AS VARCHAR(15))AS tabela,'||
                '     case when upper(N.NOIVO_MUDOU_NOME) = ''N'' then '''' else N.NOIVO_NOME_NOVO end AS NOIVO_NOME_NOVO,'||
                '     case when upper(N.NOIVA_MUDOU_NOME) = ''N'' then '''' else N.NOIVA_NOME_NOVO end AS NOIVA_NOME_NOVO,'||
                '     N.DATA_LAVRATURA_ANTENUPCIAL  AS PACTO_DT_LAVRATURA,'||
                '     N.CARTORIO_BRASIL_ID AS CARTORIO_BRASIL_ID,'||
                '     N.LV_ANTIGO_NOIVO_MAE AS ANT_NOME_MAE,'||
                '     N.LV_ANTIGO_NOIVO_PAI AS ANT_NOME_PAI,'||
                '     nt.descricao AS NATUREZA,'||
                '     NULL AS ORG_EMIS_DOC_ORIGINAL,'||
                '     NULL ASCNS_CONSULADO,'||
                '     NULL INF_COMPL_CONSULADO,'||
                '   0 as LIVROE_TIPO_ID, '||
                '   LIVROE_ID AS NRTRANSCRICAO, '||
                '   NULL AS CDS_NACIONALIDADE '||
                '   from '||
                '     V_CASAMENTO N '|| VSQLCOMPLEMENTOCASAMENTO ||
                ASCII_CHAR(13);
       if ((V_SQLGERAL <> '') and (not(V_SQLGERAL is null)))  then
         V_SQLGERAL = V_SQLGERAL||ASCII_CHAR(13)||' UNION ALL '||ASCII_CHAR(13)||trim(SQLCASAMENTO);
       else
         V_SQLGERAL = trim(SQLCASAMENTO);
end

if ((:v_tabela = '') or (:V_TABELA = 'TODOS')or (:V_TABELA IS NULL) or (:V_TABELA = 'V_OBITO') ) then
begin -- SELECT DO OBITO
  SQLOBITO =' select '||
            '    LA.NUMERO_LIVRO AS NUMERO_LIVRO,'||
            '    LA.SIGLA AS SIGLA,'||
            '    N.A_FOLHA AS FOLHA,'||
            '    N.A_TERMO AS TERMO,'||
            '    N.A_SITUACAO AS SITUACAO,'||
            '    N.A_DATA_ASSENTO AS DATA_ASSENTO,'||
            '    N.MORTE_DATA AS DATA_OCORRENCIA,'||
            '    N.MORTE_LOCAL_OCORRENCIA AS LOCAL_OCORRENCIA,'||
            '    null AS GEMEO,'||
            '    N.FAL_SEXO AS SEXO,'||
            '    N.FAL_DATA_NASCIMENTO AS DATA_NASCIMENTO,'||
            '    N.OBITO_ID AS REGISTRO_ID,'||
            '    N.A_LIVRO_NATUREZA_ID AS NATUREZA_ID,'||
            '    N.A_LIVRO_ANDAMENTO_ID AS LIVRO_ANDAMENTO,'||
            '    COALESCE(N.FAL_NOME,''NAO DECLARADO'') AS PESSOA,'||
            '    N.A_USUARIO_ID AS USUARIO_ID,'||
            '    N.TEXTO_OBSERVACAO_CERTIDAO AS TEXTO_OBSERV,'||
            '    null AS DECLARANTE_TIPO,'||
            '    N.MORTE_UF AS BAIRRO_NASCIMENTO,'||
            '    N.MORTE_CIDADE_ID AS CIDADE_ID_PARTO,'||
            '    N.RESIDENCIA_CIDADE_ID AS MAE_PARTO_CIDADEID,'||
            '    N.DO_NUMERO AS DECLARACAO_REGISTRO,'||
            '    cast(N.MORTE_HORA as time) AS HORA_OCORRENCIA,'||
            '    N.MORTE_BAIRRO  AS BAIRRO_OCORRENCIA,'||
            '    N.MORTE_LOGRADOURO AS LOGRAD_OCORRENCIA,'||
            '    N.ATESTANTE_PRIMARIO AS ATESTANTE_PRIMARIO,'||
            '    N.NUMERO_PROCESSO AS NUMEROPROCESSO,'||
            '    N.DATA_SENTENCA AS DATA_SENTENCA,'||
            '    N.COMPLEMENTO_ELEITOR AS ELEITOR_OBITO,'||
            '    N.CRM_ATESTANTE AS CRM_ATESTANTE,'||
            '    null AS NOMENOIVO,'||
            '    null AS NOMENOIVA,'||
            '    N.FAL_CPF AS CPF,'||
            '    N.JUST_CAMPOS_OBRIG AS JUST_CAMPOS_OBRIG,'||
            '    NULL AS INDICE_REG,'||
            '    CAST(''V_OBITO'' AS VARCHAR(15)) AS tabela,'||
            '    NULL AS NOIVO_NOME_NOVO,'||
            '    NULL AS NOIVA_NOME_NOVO,'||
            '    NULL AS PACTO_DT_LAVRATURA,'||
            '    NULL AS CARTORIO_BRASIL_ID,'||
            '    NULL AS ANT_NOME_MAE,'||
            '    NULL AS ANT_NOME_PAI,'||
            '    nt.descricao AS NATUREZA,'||
            '    NULL AS ORG_EMIS_DOC_ORIGINAL,'||
            '    NULL ASCNS_CONSULADO,'||
            '    NULL INF_COMPL_CONSULADO,'||
            '    0 as LIVROE_TIPO_ID, '||
            '    LIVROE_ID AS NRTRANSCRICAO, '||
            '   NULL AS CDS_NACIONALIDADE '||
            ' from '||
            '    V_OBITO N '|| VSQLCOMPLEMENTOOBITO ||
                ASCII_CHAR(13);
        if ((V_SQLGERAL <> '') and (not(V_SQLGERAL is null)))  then
          V_SQLGERAL = V_SQLGERAL||ASCII_CHAR(13)||' UNION ALL '||ASCII_CHAR(13)||trim(SQLOBITO);
        else
         V_SQLGERAL = trim(SQLOBITO);
end
  --V_SQLGERAL


  V_SQLGERAL = 'SELECT * FROM ('||V_SQLGERAL||' ) X '||ASCII_CHAR(13)||
                                'WHERE '||ASCII_CHAR(13)
                                ||TRIM(V_TERMOSQLWHERE)||ASCII_CHAR(13)
                                ||TRIM(V_TABELAw)||ASCII_CHAR(13)||
                                ' ORDER BY 2,4,6';



     FOR EXECUTE STATEMENT V_SQLGERAL into
     :NUMERO_LIVRO,
     :SIGLA,
     :FOLHA,
     :TERMO,
     :SITUACAO,
     :DATA_ASSENTO,
     :DATA_OCORRENCIA,
     :LOCAL_OCORRENCIA,
     :GEMEO,
     :SEXO,
     :DATA_NASCIMENTO,
     :REGISTRO_ID,
     :NATUREZA_ID,
     :LIVRO_ANDAMENTO,
     :PESSOA,
     :USUARIO_ID,
     :TEXTO_OBSERV,
     :DECLARANTE_TIPO,
     :BAIRRO_NASCIMENTO,
     :CIDADE_ID_PARTO,
     :MAE_PARTO_CIDADEID,
     :DECLARACAO_REGISTRO,
     :HORA_OCORRENCIA,
     :BAIRRO_OCORRENCIA,
     :LOGRAD_OCORRENCIA,
     :ATESTANTE_PRIMARIO,
     :NUMEROPROCESSO,
     :DATA_SENTENCA,
     :ELEITOR_OBITO,
     :CRM_ATESTANTE,
     :NOMENOIVO,
     :NOMENOIVA,
     :CPF,
     :JUST_CAMPOS_OBRIG,
     :INDICE_REG,
     :tabela,
     :NOIVO_NOME_NOVO,
     :NOIVA_NOME_NOVO,            
     :PACTO_DT_LAVRATURA,
     :CARTORIO_BRASIL_ID,
     :ANT_NOME_MAE, 
     :ANT_NOME_PAI,
     :NATUREZA,
     :ORG_EMIS_DOC_ORIGINAL,
     :CNS_CONSULADO,
     :INF_COMPL_CONSULADO,
     :LIVROE_TIPO_ID,
     :NRTRANSCRICAO,
     :CDS_NACIONALIDADE 
    
    do
    begin
      V_COUNT = :V_COUNT+1;
      INDICE_REG = :V_COUNT;
      if (:tabela <> 'V_LIVROE') then
      begin
        select
          count(AVERBACAO_ID)
         from
           V_AVERBACAO
         where
           1 = 1 and
           LIVRO_NATUREZA_ID = :NATUREZA_ID and
           REGISTRO_ID = :REGISTRO_ID and
           cast(DATA as date) between :V_DATA_INICIAL and :V_DATA_FINAL
         into
          :V_COUNT_AVERBACAO;
      end
      suspend;
    end
END ^

ALTER PROCEDURE V_PESQUISA_SIRC_AVERBACAO (V_DATA_INICIAL TIMESTAMP,
V_TERMO NUMERIC(15, 2),
V_DATA_FINAL TIMESTAMP,
V_TERMOFIM NUMERIC(15, 2),
V_TABELA VARCHAR(15) CHARACTER SET ISO8859_1,
V_TODOS VARCHAR(1) CHARACTER SET ISO8859_1,
V_NATUREZA_ID NUMERIC(9, 0))
RETURNS (JUST_CAMPOS_OBRIG VARCHAR(260) CHARACTER SET ISO8859_1,
INDICE_REG INTEGER,
NUMERO_LIVRO INTEGER,
SIGLA VARCHAR(10) CHARACTER SET ISO8859_1,
FOLHA NUMERIC(15, 2),
TERMO NUMERIC(15, 2),
SITUACAO VARCHAR(3) CHARACTER SET ISO8859_1,
CARTORIO_BRASIL_ID NUMERIC(10, 2),
PACTO_DT_LAVRATURA TIMESTAMP,
DATA_ASSENTO TIMESTAMP,
DATA_OCORRENCIA TIMESTAMP,
LOCAL_OCORRENCIA INTEGER,
GEMEO INTEGER,
SEXO VARCHAR(3) CHARACTER SET ISO8859_1,
REGISTRO_ID NUMERIC(18, 4),
NATUREZA_ID NUMERIC(18, 4),
TABELA VARCHAR(15) CHARACTER SET ISO8859_1,
LIVRO_ANDAMENTO NUMERIC(15, 4),
NATUREZA VARCHAR(15) CHARACTER SET ISO8859_1,
PESSOA VARCHAR(120) CHARACTER SET ISO8859_1,
USUARIO_ID NUMERIC(15, 4),
TEXTO_OBSERV BLOB,
DECLARANTE_TIPO INTEGER,
BAIRRO_NASCIMENTO VARCHAR(60) CHARACTER SET ISO8859_1,
CIDADE_ID_PARTO INTEGER,
MAE_PARTO_CIDADEID INTEGER,
DECLARACAO_REGISTRO VARCHAR(60) CHARACTER SET ISO8859_1,
HORA_OCORRENCIA TIME,
BAIRRO_OCORRENCIA VARCHAR(30) CHARACTER SET ISO8859_1,
LOGRAD_OCORRENCIA VARCHAR(60) CHARACTER SET ISO8859_1,
ELEITOR_OBITO VARCHAR(1) CHARACTER SET ISO8859_1,
ATESTANTE_PRIMARIO VARCHAR(90) CHARACTER SET ISO8859_1,
NUMEROPROCESSO VARCHAR(30) CHARACTER SET ISO8859_1,
DATA_SENTENCA TIMESTAMP,
CRM_ATESTANTE VARCHAR(15) CHARACTER SET ISO8859_1,
ANT_NOME_MAE VARCHAR(120) CHARACTER SET ISO8859_1,
ANT_NOME_PAI VARCHAR(120) CHARACTER SET ISO8859_1,
NOMENOIVO VARCHAR(120) CHARACTER SET ISO8859_1,
CPF VARCHAR(15) CHARACTER SET ISO8859_1,
NOMENOIVA VARCHAR(120) CHARACTER SET ISO8859_1,
V_COUNT_AVERBACAO NUMERIC(15, 4),
RETORNO_SQLGERAL TEXTO_BLOB,
NOIVO_NOME_NOVO VARCHAR(120) CHARACTER SET ISO8859_1,
NOIVA_NOME_NOVO VARCHAR(120) CHARACTER SET ISO8859_1,
ORG_EMIS_DOC_ORIGINAL VARCHAR(120) CHARACTER SET ISO8859_1,
CNS_CONSULADO VARCHAR(120) CHARACTER SET ISO8859_1,
INF_COMPL_CONSULADO VARCHAR(1000) CHARACTER SET ISO8859_1,
LIVROE_TIPO_ID NUMERIC(15, 4),
DATA_AVERBACAO DATAHORA,
CDS_NACIONALIDADE VARCHAR(4) CHARACTER SET ISO8859_1)
AS 
declare variable V_COUNT integer;
declare variable V_DESCRICAO VARCHAR_260;
BEGIN
 v_count = 0;
  if (:v_todos = 'S') then
  BEGIN
    FOR SELECT distinct
              LA.NUMERO_LIVRO,
              LA.SIGLA,
              N.A_FOLHA,
              N.A_TERMO,
              N.A_SITUACAO,
              N.A_DATA_ASSENTO,
              N.REG_DATA_NASCIMENTO,
              N.REG_LOCAL_OCORRENCIA,
              N.REG_GEMEO,
              N.REG_SEXO,
              N.NASCIMENTO_ID,
              N.A_LIVRO_NATUREZA_ID,
              N.a_livro_andamento_id,
              N.reg_nome,
              N.a_usuario_id,
              n.texto_observacao_certidao,
              n.declarante_tipo,
              n.reg_local_uf,
              Coalesce(N.PARTO_CIDADE_ID,REG_CIDADE_ID),
              N.NATURALIDADE_CIDADE_ID,
              n.dnv_numero,
              cast(n.reg_hora as time),
              null, 
              null,
              null,
              n.numero_processo,
              n.data_sentenca,
              null,
              NULL,
              null, 
              NULL,
              N.cpf_registrado,
              row_count,
              N.A_DATA_ASSENTO,
              N.JUST_CAMPOS_OBRIG
        FROM V_AVERBACAO VA
        LEFT OUTER JOIN V_NASCIMENTO N ON VA.registro_id = N.nascimento_id
        and va.livro_natureza_id = 1
        LEFT OUTER JOIN V_LIVRO_ANDAMENTO LA ON    N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID
        WHERE CAST(VA.DATA as DATE)
        BETWEEN :v_data_inicial AND  :v_data_final
        ORDER BY LA.SIGLA, N.A_DATA_ASSENTO, N.A_TERMO
      INTO :numero_livro, :sigla, :folha, :termo, :situacao, :data_assento, :data_ocorrencia, :local_ocorrencia,
           :gemeo, :sexo, :registro_id, :natureza_id, :livro_andamento, :pessoa, :usuario_id,:TEXTO_OBSERV,
           :declarante_tipo, :bairro_nascimento, :cidade_id_parto, :mae_parto_cidadeid, :declaracao_registro, :hora_ocorrencia,
           :bairro_ocorrencia,:lograd_ocorrencia,:atestante_primario,:numeroprocesso,:data_sentenca,:eleitor_obito,:crm_atestante,
           :nomenoivo,:nomenoiva, :cpf, :v_count, :data_averbacao, :JUST_CAMPOS_OBRIG DO
       BEGIN
         indice_reg = v_count;
         SELECT COUNT(AVERBACAO_ID) FROM V_AVERBACAO
          WHERE 1=1
          AND LIVRO_NATUREZA_ID = :natureza_id
          AND REGISTRO_ID =  :registro_id
          and CAST(data AS DATE) BETWEEN :v_data_inicial AND  :v_data_final
          into :V_COUNT_AVERBACAO;
         SUSPEND;
       END

     FOR  SELECT distinct LA.NUMERO_LIVRO,
              LA.SIGLA,
              N.A_FOLHA,
              N.A_TERMO,
              N.A_SITUACAO,
              N.A_DATA_ASSENTO,
              N.morte_data,
              N.morte_local_ocorrencia,--unidade saude fora unidade saude
              N.fal_sexo,
              N.obito_id,
              N.a_livro_natureza_id,
              N.a_livro_andamento_id,
              N.fal_nome,
              N.a_usuario_id,
              n.texto_observacao_certidao,
              null, 
              n.residencia_distrito,
              null, 
              null, 
              n.do_numero,
              cast(n.morte_hora as time),
              n.morte_bairro,
              n.morte_logradouro,
              n.atestante_primario,
              null,
              null,
              n.complemento_eleitor,
              N.crm_atestante,
              null, 
              NULL,
              N.fal_cpf,
              row_count,
              N.A_DATA_ASSENTO,
              N.JUST_CAMPOS_OBRIG
        FROM V_AVERBACAO VA
        LEFT OUTER JOIN V_OBITO N ON N.obito_id = VA.registro_id
        and va.livro_natureza_id in(2,3)
        LEFT OUTER JOIN V_LIVRO_ANDAMENTO LA ON  N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID
        WHERE CAST(VA.DATA as DATE)
        BETWEEN :v_data_inicial AND :v_data_final
        AND N.A_LIVRO_NATUREZA_ID in (2,3)
        ORDER BY LA.SIGLA,
                 N.A_DATA_ASSENTO,
                 N.A_TERMO
       INTO :numero_livro, :sigla, :folha, :termo, :situacao, :data_assento, :data_ocorrencia, :local_ocorrencia,
            :sexo, :registro_id, :natureza_id, :livro_andamento, :pessoa, :usuario_id,:TEXTO_OBSERV,
            :declarante_tipo, :bairro_nascimento, :cidade_id_parto, :mae_parto_cidadeid, :declaracao_registro, :hora_ocorrencia,
            :bairro_ocorrencia,:lograd_ocorrencia,:atestante_primario,:numeroprocesso,:data_sentenca,:eleitor_obito,:crm_atestante,
            :nomenoivo,:nomenoiva, :cpf, :indice_reg, :data_averbacao, :JUST_CAMPOS_OBRIG do
       BEGIN
         v_count    =  1+v_count;
         indice_reg = v_count;
         SELECT COUNT(AVERBACAO_ID) FROM V_AVERBACAO
          WHERE 1=1
          AND LIVRO_NATUREZA_ID = :natureza_id
          AND REGISTRO_ID =  :registro_id
          and CAST(data AS DATE) BETWEEN :v_data_inicial AND  :v_data_final
          into :V_COUNT_AVERBACAO;
         SUSPEND;
       END

      FOR SELECT distinct LA.NUMERO_LIVRO,
              LA.SIGLA,
              N.A_FOLHA,
              N.A_TERMO,
              N.A_SITUACAO,
              N.A_DATA_ASSENTO,
              n.edital_data_emissao,
              N.casamento_id,
              N.A_LIVRO_NATUREZA_ID,
              N.a_livro_andamento_id,
              NULL,
              (coalesce(N.noivo_nome_novo,n.NOIVO_NOME_ATUAL)||' / '||coalesce(n.noiva_nome_novo,n.NOIVA_NOME_ATUAL)) as nome,
              N.a_usuario_id,
              n.texto_observacao_certidao,
              null,
              null,
              null,
              null,
              case n.casamento_regime
                  when 1 then 'COMUNHAO_PARCIAL'
                  when 2 then 'COMUNHAO_UNIVERSAL'
                  when 3 then 'SEPARACAO_BENS'
                  when 4 then 'SEPARACAO_BENS'
                  when 5 then 'PARTICIPACAO_FINAL_AQUESTOS'
              end as casamento_regime,
              cast(n.casamento_hora as time),
              null,
              null,
              null,
              null, 
              null,
              null,
              NULL,
              N.noivo_nome_atual,
              N.noiva_nome_atual,
              row_count,
              n.lv_antigo_noivo_mae,
              n.lv_antigo_noivo_pai,
              case when upper(n.noivo_mudou_nome) = 'N' then '' else  n.noivo_nome_novo end as noivo_nome_novo,
              case when upper(n.noiva_mudou_nome) = 'N' then '' else  n.noiva_nome_novo end as noiva_nome_novo,
            --  n.noivo_nome_novo,
            --  n.noiva_nome_novo,
              n.data_lavratura_antenupcial,
              n.cartorio_brasil_id,
              N.A_DATA_ASSENTO,
              N.JUST_CAMPOS_OBRIG
        FROM V_AVERBACAO VA
       LEFT OUTER JOIN  V_CASAMENTO N on va.registro_id = n.casamento_id
       and va.livro_natureza_id in(4,5)
       LEFT OUTER JOIN V_LIVRO_ANDAMENTO LA
       ON    N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID
       WHERE CAST(VA.DATA as DATE) BETWEEN :v_data_inicial
       AND  :v_data_final
       ORDER BY LA.SIGLA, N.A_DATA_ASSENTO, N.A_TERMO
      INTO :numero_livro, :sigla, :folha, :termo, :situacao, :data_assento, :data_ocorrencia,
           :registro_id, :natureza_id, :livro_andamento, :sexo, :pessoa, :usuario_id, :texto_observ,
           :declarante_tipo, :bairro_nascimento, :cidade_id_parto, :mae_parto_cidadeid, :declaracao_registro,
           :hora_ocorrencia, :bairro_ocorrencia,:lograd_ocorrencia,:atestante_primario,:numeroprocesso,:data_sentenca,
           :eleitor_obito,:crm_atestante,:nomenoivo,:nomenoiva, :indice_reg, :ant_nome_mae, :ant_nome_pai,
           :noivo_nome_novo, :noiva_nome_novo, :pacto_dt_lavratura, :cartorio_brasil_id, :data_averbacao, :JUST_CAMPOS_OBRIG DO
       BEGIN
         v_count    =  1+v_count;
         indice_reg = v_count;
         SELECT COUNT(AVERBACAO_ID) FROM V_AVERBACAO
          WHERE 1=1
          AND LIVRO_NATUREZA_ID = :natureza_id
          AND REGISTRO_ID =  :registro_id
          and CAST(data AS DATE) BETWEEN :v_data_inicial AND  :v_data_final
          into :V_COUNT_AVERBACAO;
         SUSPEND;
       END

  END
  else
  BEGIN
  if (:V_TABELA = 'V_NASCIMENTO') then
  begin
  if (:V_TERMO <> 0 ) then
  begin
  FOR SELECT distinct LA.NUMERO_LIVRO,
              LA.SIGLA,
              N.A_FOLHA,
              N.A_TERMO,
              N.A_SITUACAO,
              N.A_DATA_ASSENTO,
              N.REG_DATA_NASCIMENTO,
              N.REG_LOCAL_OCORRENCIA,
              N.REG_GEMEO,
              N.REG_SEXO,
              N.NASCIMENTO_ID,
              N.A_LIVRO_NATUREZA_ID,
              N.a_livro_andamento_id,
              N.reg_nome,
              N.a_usuario_id,
              N.texto_observacao_certidao,
              n.declarante_tipo,
              n.reg_local_uf,
              Coalesce(N.PARTO_CIDADE_ID,REG_CIDADE_ID),
              N.NATURALIDADE_CIDADE_ID,
              n.dnv_numero,
              n.reg_hora,
              null,
              null,
              null, 
              n.numero_processo,
              n.data_sentenca,
              null,
              NULL,
              NULL,
              NULL,
              N.cpf_registrado,
              row_count,
              N.A_DATA_ASSENTO,
              N.JUST_CAMPOS_OBRIG
        FROM V_AVERBACAO VA
        LEFT OUTER JOIN V_NASCIMENTO N on va.registro_id = n.nascimento_id
        and va.livro_natureza_id = 1
        LEFT OUTER JOIN V_LIVRO_ANDAMENTO LA
        ON    N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID
        WHERE N.a_termo between cast(:v_termo as varchar(15)) and cast(:v_termofim as varchar(15))
        and CAST(VA.DATA as DATE) BETWEEN :v_data_inicial
        AND  :v_data_final
        ORDER BY LA.SIGLA, N.A_DATA_ASSENTO, N.A_TERMO
      INTO :numero_livro, :sigla, :folha, :termo, :situacao, :data_assento, :data_ocorrencia, :local_ocorrencia,
           :gemeo, :sexo, :registro_id, :natureza_id, :livro_andamento, :pessoa, :usuario_id, :texto_observ,
           :declarante_tipo, :bairro_nascimento, :cidade_id_parto, :mae_parto_cidadeid, :declaracao_registro,
           :hora_ocorrencia, :bairro_ocorrencia,:lograd_ocorrencia,:atestante_primario,:numeroprocesso,:data_sentenca,
           :eleitor_obito,:crm_atestante,:nomenoivo,:nomenoiva, :cpf, :indice_reg, :data_averbacao, :JUST_CAMPOS_OBRIG do
       BEGIN
         SELECT COUNT(AVERBACAO_ID) FROM V_AVERBACAO
          WHERE 1=1
          AND LIVRO_NATUREZA_ID = :natureza_id
          AND REGISTRO_ID =  :registro_id
          and CAST(data AS DATE) BETWEEN :v_data_inicial AND  :v_data_final
          into :V_COUNT_AVERBACAO;
         SUSPEND;
       END
  END
  ELSE
  BEGIN
  FOR SELECT distinct  LA.NUMERO_LIVRO,
              LA.SIGLA,
              N.A_FOLHA,
              N.A_TERMO,
              N.A_SITUACAO,
              N.A_DATA_ASSENTO,
              N.REG_DATA_NASCIMENTO,
              N.REG_LOCAL_OCORRENCIA,
              N.REG_GEMEO,
              N.REG_SEXO,
              N.NASCIMENTO_ID,
              N.A_LIVRO_NATUREZA_ID,
              N.a_livro_andamento_id,
              N.reg_nome,
              N.a_usuario_id,
              N.texto_observacao_certidao,
              n.declarante_tipo,
              n.reg_local_uf,
              Coalesce(N.PARTO_CIDADE_ID,REG_CIDADE_ID),
              N.NATURALIDADE_CIDADE_ID,
              n.dnv_numero,
              n.reg_hora,
              null,
              null,
              null, 
              n.numero_processo,
              n.data_sentenca,
              null,
              NULL,
              NULL,
              NULL,
              N.cpf_registrado,
              row_count,
              N.A_DATA_ASSENTO,
              N.JUST_CAMPOS_OBRIG
        from V_AVERBACAO VA
        LEFT OUTER JOIN V_NASCIMENTO N on va.registro_id = n.nascimento_id
        and va.livro_natureza_id = 1
        LEFT OUTER JOIN V_LIVRO_ANDAMENTO LA
        ON    N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID
        WHERE CAST(VA.DATA as DATE)
        BETWEEN :v_data_inicial AND  :v_data_final
        ORDER BY LA.SIGLA, N.A_DATA_ASSENTO, N.A_TERMO
      INTO :numero_livro, :sigla, :folha, :termo, :situacao, :data_assento, :data_ocorrencia, :local_ocorrencia,
           :gemeo, :sexo, :registro_id, :natureza_id, :livro_andamento, :pessoa, :usuario_id, :texto_observ,
           :declarante_tipo, :bairro_nascimento, :cidade_id_parto, :mae_parto_cidadeid, :declaracao_registro,
           :hora_ocorrencia, :bairro_ocorrencia,:lograd_ocorrencia,:atestante_primario,:numeroprocesso,:data_sentenca,
           :eleitor_obito,:crm_atestante,:nomenoivo,:nomenoiva, :cpf, :indice_reg, :data_averbacao, :JUST_CAMPOS_OBRIG do
       BEGIN
         SELECT COUNT(AVERBACAO_ID) FROM V_AVERBACAO
          WHERE 1=1
          AND LIVRO_NATUREZA_ID = :natureza_id
          AND REGISTRO_ID =  :registro_id
          and CAST(data AS DATE) BETWEEN :v_data_inicial AND  :v_data_final
          into :V_COUNT_AVERBACAO;
         SUSPEND;
       END
   END
  END
  if (:V_TABELA = 'V_OBITO') then
  begin
  if (:V_TERMO <> 0 ) then
  begin
  FOR SELECT distinct  LA.NUMERO_LIVRO,
              LA.SIGLA,
              N.A_FOLHA,
              N.A_TERMO,
              N.A_SITUACAO,
              N.A_DATA_ASSENTO,
              N.morte_data,
              N.morte_local_ocorrencia,
              N.fal_sexo,
              N.obito_id,
              N.a_livro_natureza_id,
              N.a_livro_andamento_id,
              N.fal_nome,
              N.a_usuario_id,
              N.texto_observacao_certidao,
              null,
              n.residencia_distrito,
              null,
              null, 
              n.do_numero,
              n.morte_hora,
              n.morte_bairro,
              n.morte_logradouro,
              n.atestante_primario,
              null,
              null,
              n.complemento_eleitor,
              N.crm_atestante,
              NULL,
              NULL,
              N.fal_cpf,
              row_count,
              N.A_DATA_ASSENTO,
              N.JUST_CAMPOS_OBRIG
        FROM V_AVERBACAO VA
        LEFT OUTER JOIN V_OBITO N on va.registro_id = n.obito_id
        and va.livro_natureza_id in (2,3)
              LEFT OUTER JOIN V_LIVRO_ANDAMENTO LA
              ON  N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID
        WHERE n.a_termo between cast(:v_termo as varchar(15)) and cast(:v_termofim as varchar(15))
        and CAST(VA.DATA as DATE) BETWEEN :v_data_inicial
       AND  :v_data_final
        AND N.A_LIVRO_NATUREZA_ID = :v_natureza_id
        ORDER BY LA.SIGLA,
                 N.A_DATA_ASSENTO,
                 N.A_TERMO
       INTO :numero_livro, :sigla, :folha, :termo, :situacao, :data_assento, :data_ocorrencia, :local_ocorrencia,
            :sexo, :registro_id, :natureza_id, :livro_andamento, :pessoa, :usuario_id, :texto_observ,
            :declarante_tipo, :bairro_nascimento, :cidade_id_parto, :mae_parto_cidadeid, :declaracao_registro,
            :hora_ocorrencia,:bairro_ocorrencia,:lograd_ocorrencia,:atestante_primario,:numeroprocesso,:data_sentenca,
            :eleitor_obito,:CRM_ATESTANTE,:nomenoivo,:nomenoiva, :cpf, :indice_reg, :data_averbacao, :JUST_CAMPOS_OBRIG DO
       BEGIN
         SELECT COUNT(AVERBACAO_ID) FROM V_AVERBACAO
          WHERE 1=1
          AND LIVRO_NATUREZA_ID = :natureza_id
          AND REGISTRO_ID =  :registro_id
          and CAST(data AS DATE) BETWEEN :v_data_inicial AND  :v_data_final
          into :V_COUNT_AVERBACAO;
         SUSPEND;
       END
  END
  ELSE
  BEGIN
  FOR SELECT distinct LA.NUMERO_LIVRO,
              LA.SIGLA,
              N.A_FOLHA,
              N.A_TERMO,
              N.A_SITUACAO,
              N.A_DATA_ASSENTO,
              N.morte_data,
              N.morte_local_ocorrencia,
              N.fal_sexo,
              N.obito_id,
              N.a_livro_natureza_id,
              N.a_livro_andamento_id,
              N.fal_nome,
              N.a_usuario_id,
              N.texto_observacao_certidao,
              null,
              n.residencia_distrito,
              null,
              null, 
              n.do_numero,
              n.morte_hora,
              n.morte_bairro,
              n.morte_logradouro,
              n.atestante_primario,
              null,
              null,
              n.complemento_eleitor,
              N.crm_atestante,
              NULL,
              NULL,
              N.fal_cpf,
              row_count,
              N.A_DATA_ASSENTO,
              N.JUST_CAMPOS_OBRIG
        FROM V_AVERBACAO VA
        LEFT OUTER JOIN V_OBITO N on va.registro_id = n.obito_id
        and va.livro_natureza_id in (2,3)
              LEFT OUTER JOIN V_LIVRO_ANDAMENTO LA
              ON  N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID
        WHERE CAST(VA.DATA as DATE)
        BETWEEN :v_data_inicial AND :v_data_final
        AND N.A_LIVRO_NATUREZA_ID = :v_natureza_id
        ORDER BY LA.SIGLA,
                 N.A_DATA_ASSENTO,
                 N.A_TERMO
       INTO :numero_livro, :sigla, :folha, :termo, :situacao, :data_assento, :data_ocorrencia, :local_ocorrencia,
            :sexo, :registro_id, :natureza_id, :livro_andamento, :pessoa, :usuario_id, :texto_observ,
            :declarante_tipo, :bairro_nascimento, :cidade_id_parto, :mae_parto_cidadeid, :declaracao_registro,
            :hora_ocorrencia,:bairro_ocorrencia,:lograd_ocorrencia,:atestante_primario,:numeroprocesso,:data_sentenca,
            :eleitor_obito,:CRM_ATESTANTE,:nomenoivo,:nomenoiva, :cpf, :indice_reg, :data_averbacao, :JUST_CAMPOS_OBRIG DO
       BEGIN
         SELECT COUNT(AVERBACAO_ID) FROM V_AVERBACAO
          WHERE 1=1
          AND LIVRO_NATUREZA_ID = :natureza_id
          AND REGISTRO_ID =  :registro_id
          and CAST(data AS DATE) BETWEEN :v_data_inicial AND  :v_data_final
          into :V_COUNT_AVERBACAO;
         SUSPEND;
       END
   END
  END
  if (:V_TABELA = 'V_CASAMENTO') then
  begin
  if (:V_TERMO <> 0 ) then
  begin
   FOR SELECT distinct LA.NUMERO_LIVRO,
              LA.SIGLA,
              N.A_FOLHA,
              N.A_TERMO,
              N.A_SITUACAO,
              N.A_DATA_ASSENTO,
              n.edital_data_emissao,
              N.casamento_id,
              N.A_LIVRO_NATUREZA_ID,
              N.a_livro_andamento_id,
              NULL,
              (coalesce(N.noivo_nome_novo,n.NOIVO_NOME_ATUAL)||' / '||coalesce(n.noiva_nome_novo,n.NOIVA_NOME_ATUAL)) as nome,
              N.a_usuario_id,
              N.texto_observacao_certidao,
              null,
              null, 
              null,
              null,
              case n.casamento_regime
                  when 1 then 'COMUNHAO_PARCIAL'
                  when 2 then 'COMUNHAO_UNIVERSAL'
                  when 3 then 'SEPARACAO_BENS'
                  when 4 then 'SEPARACAO_BENS'
                  when 5 then 'PARTICIPACAO_FINAL_AQUESTOS'
              end as casamento_regime,
              n.casamento_hora,
              null, 
              null,
              null,
              null, 
              null,
              null,
              NULL,
              N.noivo_nome_atual,
              N.noiva_nome_atual,
              row_count,
              n.lv_antigo_noivo_mae,
              n.lv_antigo_noivo_pai,
              case when upper(n.noivo_mudou_nome) = 'N' then '' else  n.noivo_nome_novo end as noivo_nome_novo,
              case when upper(n.noiva_mudou_nome) = 'N' then '' else  n.noiva_nome_novo end as noiva_nome_novo,
            --  n.noivo_nome_novo,
            --  n.noiva_nome_novo,
              n.data_lavratura_antenupcial,
              n.cartorio_brasil_id,
              N.A_DATA_ASSENTO,
              N.JUST_CAMPOS_OBRIG
        FROM V_AVERBACAO VA
       LEFT OUTER JOIN V_CASAMENTO N on va.registro_id = n.casamento_id
       and va.livro_natureza_id in (4,5)
       LEFT OUTER JOIN V_LIVRO_ANDAMENTO LA
       ON    N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID
       WHERE N.a_termo between cast(:v_termo as varchar(15)) and cast(:v_termofim as varchar(15))
      AND N.A_LIVRO_NATUREZA_ID = :v_natureza_id
      and CAST(VA.DATA as DATE) BETWEEN :v_data_inicial
       AND  :v_data_final
       ORDER BY LA.SIGLA, N.A_DATA_ASSENTO, N.A_TERMO
       INTO :numero_livro, :sigla, :folha, :termo, :situacao, :data_assento, :data_ocorrencia,
            :registro_id, :natureza_id, :livro_andamento, :sexo, :pessoa, :usuario_id, :texto_observ,
            :declarante_tipo, :bairro_nascimento, :cidade_id_parto, :mae_parto_cidadeid, :declaracao_registro,
            :hora_ocorrencia,:bairro_ocorrencia,:lograd_ocorrencia,:atestante_primario,:numeroprocesso,:data_sentenca,
            :eleitor_obito,:CRM_ATESTANTE,:nomenoivo,:nomenoiva, :indice_reg, :ant_nome_mae, :ant_nome_pai,
            :noivo_nome_novo, :noiva_nome_novo, :pacto_dt_lavratura, :cartorio_brasil_id, :data_averbacao, :JUST_CAMPOS_OBRIG do
       BEGIN
         SELECT COUNT(AVERBACAO_ID) FROM V_AVERBACAO
          WHERE 1=1
          AND LIVRO_NATUREZA_ID = :natureza_id
          AND REGISTRO_ID =  :registro_id
          and CAST(data AS DATE) BETWEEN :v_data_inicial AND  :v_data_final
          into :V_COUNT_AVERBACAO;
         SUSPEND;
       END
  END
  else
  BEGIN
  FOR SELECT distinct LA.NUMERO_LIVRO,
              LA.SIGLA,
              N.A_FOLHA,
              N.A_TERMO,
              N.A_SITUACAO,
              N.A_DATA_ASSENTO,
              n.edital_data_emissao,
              N.casamento_id,
              N.A_LIVRO_NATUREZA_ID,
              N.a_livro_andamento_id,
              NULL,
              (coalesce(N.noivo_nome_novo,n.NOIVO_NOME_ATUAL)||' / '||coalesce(n.noiva_nome_novo,n.NOIVA_NOME_ATUAL)) as nome,
              N.a_usuario_id,
              N.texto_observacao_certidao,
              null,
              null, 
              null,
              null,
              case n.casamento_regime
                  when 1 then 'COMUNHAO_PARCIAL'
                  when 2 then 'COMUNHAO_UNIVERSAL'
                  when 3 then 'SEPARACAO_BENS'
                  when 4 then 'SEPARACAO_BENS'
                  when 5 then 'PARTICIPACAO_FINAL_AQUESTOS'
              end as casamento_regime,
              n.casamento_hora,
              null, 
              null,
              null,
              null, 
              null,
              null,
              NULL,
              N.noivo_nome_atual,
              N.noiva_nome_atual,
              row_count,
              n.lv_antigo_noivo_mae,
              n.lv_antigo_noivo_pai,
              case when upper(n.noivo_mudou_nome) = 'N' then '' else  n.noivo_nome_novo end as noivo_nome_novo,
              case when upper(n.noiva_mudou_nome) = 'N' then '' else  n.noiva_nome_novo end as noiva_nome_novo,
            --  n.noivo_nome_novo,
            --  n.noiva_nome_novo,
              n.data_lavratura_antenupcial,
              n.cartorio_brasil_id,
              N.A_DATA_ASSENTO,
              N.JUST_CAMPOS_OBRIG
        FROM V_AVERBACAO VA
       LEFT OUTER JOIN  V_CASAMENTO N on va.registro_id = n.casamento_id
       and va.livro_natureza_id in (4,5)
       LEFT OUTER JOIN V_LIVRO_ANDAMENTO LA
       ON    N.A_LIVRO_ANDAMENTO_ID = LA.LIVRO_ANDAMENTO_ID
       WHERE CAST(VA.DATA as DATE) BETWEEN :v_data_inicial
       AND  :v_data_final
      AND N.A_LIVRO_NATUREZA_ID = :v_natureza_id
       ORDER BY LA.SIGLA, N.A_DATA_ASSENTO, N.A_TERMO
       INTO :numero_livro, :sigla, :folha, :termo, :situacao, :data_assento, :data_ocorrencia,
            :registro_id, :natureza_id, :livro_andamento, :sexo, :pessoa, :usuario_id, :texto_observ,
            :declarante_tipo, :bairro_nascimento, :cidade_id_parto, :mae_parto_cidadeid, :declaracao_registro,
            :hora_ocorrencia,:bairro_ocorrencia,:lograd_ocorrencia,:atestante_primario,:numeroprocesso,:data_sentenca,
            :eleitor_obito,:CRM_ATESTANTE,:nomenoivo,:nomenoiva, :indice_reg,:ant_nome_mae, :ant_nome_pai,
            :noivo_nome_novo, :noiva_nome_novo, :pacto_dt_lavratura, :cartorio_brasil_id, :data_averbacao, :JUST_CAMPOS_OBRIG do
       BEGIN
         SELECT COUNT(AVERBACAO_ID) FROM V_AVERBACAO
          WHERE 1=1
          AND LIVRO_NATUREZA_ID = :natureza_id
          AND REGISTRO_ID =  :registro_id
          and CAST(data AS DATE) BETWEEN :v_data_inicial AND  :v_data_final
          into :V_COUNT_AVERBACAO;
         SUSPEND;
       END
     END
   END
  END
end ^

ALTER PROCEDURE V_RETORNAIDADE (REGISTRO_ID NUMERICO)
RETURNS (STRING VARCHAR(1000) CHARACTER SET ISO8859_1)
AS 
declare variable IDADE INTEGER;
declare variable DIA integer;
declare variable MES integer;
BEGIN
  STRING = '';
 select EXTRACT(DAY FROM O.data_nascimento),EXTRACT(MONTH FROM O.data_nascimento),
 DateDiff(Year, O.data_nascimento, Current_Date)
 from v_PESSOA O where PESSOA_ID = :registro_id
         INTO :DIA,:MES,IDADE;

  if ( EXTRACT(MONTH FROM Current_Date) >= coalesce(MES,0) )  then
  begin
    --STRING = 'Nada Consta';
     if (EXTRACT(DAY FROM Current_Date) >= coalesce(DIA,0)   )  then
      begin
        if (coalesce(IDADE,'') <> '' ) then
        begin
          IDADE = IDADE+1;
          STRING = 'com '||IDADE||' anos';
        end
        else
          STRING = '';
      end
  end
  else
  begin
    if (coalesce(IDADE,'') <> '' ) then
        begin
          STRING = 'com '||IDADE||' anos';
        end
        else
          STRING = '';
  end
  SUSPEND;
END ^

ALTER PROCEDURE W_ATUALIZAR_TABELA_DF (V_ANO_NOVO INTEGER,
V_EMOLUMENTO_PERIODO_ID INTEGER,
V_MULTIPLICADOR_PERCENTUAL NUMERIC(10, 5))
RETURNS (QTDE_ITENS_NOVOS_EMOL INTEGER,
QTDE_SELOS_NOVOS INTEGER,
QTDE_SELOS_DESCARTADOS INTEGER)
AS 
declare variable v_selo_id integer;
  declare variable v_sql varchar(1000);
begin
  select count(*) from g_emolumento_item
  where emolumento_periodo_id = :v_emolumento_periodo_id
  into :qtde_itens_novos_emol;

  update g_emolumento_item
  set valor_inicio = cast((valor_inicio * :v_multiplicador_percentual) as numeric(18,2))
  where emolumento_periodo_id = :v_emolumento_periodo_id
  and valor_inicio > 0;

  update g_emolumento_item
  set valor_fim = cast((valor_fim * :v_multiplicador_percentual) as numeric(18,2))
  where emolumento_periodo_id = :v_emolumento_periodo_id
  and valor_fim < 999999999;

  update g_emolumento_item
  set valor_emolumento = cast(((valor_emolumento + valor_fundo_ri) * :v_multiplicador_percentual) as numeric(18,2)) - (cast((cast(((valor_emolumento + valor_fundo_ri) * :v_multiplicador_percentual) as numeric(18,2)) * 0.06542) as numeric(18,2))),
    valor_fundo_ri = cast((cast(((valor_emolumento + valor_fundo_ri) * :v_multiplicador_percentual) as numeric(18,2)) * 0.06542) as numeric(18,2))
  where emolumento_periodo_id = :v_emolumento_periodo_id
  and valor_emolumento > 0;

  UPDATE G_CONFIG SET VALOR = cast(:v_emolumento_periodo_id as varchar(4)) WHERE NOME = 'PERIODO_PADRAO';

  select count(*) from r_selo
  where numero_selo like 'TJDFT'||cast(:v_ano_novo as varchar(4))||'%'
  into :qtde_selos_novos;

  update r_selo
  set ano = :v_ano_novo
  where numero_selo like 'TJDFT'||cast(:v_ano_novo as varchar(4))||'%';

  select count(*) from r_selo
  where ano < :v_ano_novo
  and status = '1'
  into :qtde_selos_descartados;

  update r_selo
  set status = '3',
    observacao = 'DESCARTE PARA MUDANÇA DE ANO',
    data_envio_canc = current_date,
    usuario_cancelou = 'SOFTWIKI',
    motivo_cancelamento = '1'
  where ano < :v_ano_novo
  and status = '1';

  select first 1 selo_id from r_selo
  where numero_selo like 'TJDFT'||cast((:v_ano_novo - 1) as varchar(4))||'%'
  order by selo_id desc
  into :v_selo_id;

  v_sql = 'ALTER SEQUENCE R_SELO_USAR_SEQ RESTART WITH '||cast(:v_selo_id as varchar(20));
  execute statement :v_sql;

  suspend;
end ^

ALTER PROCEDURE W_BISEXTO (V_ANO INTEGER)
RETURNS (RESULTADO VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
BEGIN
  RESULTADO = 'NÃO';
  if (mod(:V_ANO,4) = 0) then
  begin
    if ((mod(:V_ANO,100) <> 0) or (mod(:V_ANO,400) = 0)) then
    begin
      RESULTADO = 'SIM';
    end
  end
  suspend;
end ^

ALTER PROCEDURE W_BUSCAR_VALOR_GENERATOR (V_GENERATOR VARCHAR(60) CHARACTER SET ISO8859_1)
RETURNS (RESULTADO INTEGER)
AS 
DECLARE VARIABLE V_SQL VARCHAR(200);
  DECLARE VARIABLE V_QTDE INTEGER;
BEGIN
  --VERIFICAR SE GENERATOR EXISTE
  SELECT COUNT(*) FROM RDB$GENERATORS
  WHERE RDB$GENERATOR_NAME = :V_GENERATOR
  INTO :V_QTDE;
  --SE NAO EXISTIR CRIA GENERATOR
  IF (COALESCE(:V_QTDE,0) = 0) THEN
  BEGIN
    V_SQL = 'CREATE GENERATOR '||:V_GENERATOR;
    EXECUTE STATEMENT V_SQL;
  END

  V_SQL = 'SELECT GEN_ID('||:V_GENERATOR||',1) FROM RDB$DATABASE '; 
  FOR EXECUTE STATEMENT V_SQL
      INTO :RESULTADO  DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE W_CONFERIR_EMOLUMENTO_GO RETURNS (EMOLUMENTO_ID INTEGER,
DESCRICAO VARCHAR(260) CHARACTER SET ISO8859_1,
VALOR_EMOLUMENTO DINHEIRO,
VALOR_EMOLUMENTO_OLD DINHEIRO,
VALOR_EMOLUMENTO_OLD_CALC DINHEIRO,
VALOR_TAXA DINHEIRO,
VALOR_TAXA_OLD DINHEIRO,
SELO_GRUPO_ID INTEGER,
SISTEMA_ID INTEGER,
GRUPO INTEGER)
AS 
begin
  for select i.emolumento_id, e.descricao, i.valor_emolumento, i.valor_taxa_judiciaria,
        i.selo_grupo_id, e.sistema_id
      from g_emolumento_item i, g_emolumento e
      where i.emolumento_id = e.emolumento_id
      and i.emolumento_periodo_id = 50027
      and e.situacao_ri = 'A'
      and e.sistema_id = 1
      into :emolumento_id, :descricao, :valor_emolumento, :valor_taxa, :selo_grupo_id,
        :sistema_id do
  begin
    valor_emolumento_old = 0;
    valor_taxa_old = 0;
    valor_emolumento_old_calc = 0;
    select first 1 i.valor_emolumento, i.valor_taxa_judiciaria
      from g_emolumento_item i, g_emolumento e
      where i.emolumento_id = e.emolumento_id
      and i.emolumento_id = :emolumento_id
      and i.emolumento_periodo_id = 50026
      and e.situacao_ri = 'A'
      and i.selo_grupo_id = :selo_grupo_id
      and e.sistema_id = :sistema_id
      into :valor_emolumento_old, :valor_taxa_old;
    if (coalesce(:valor_emolumento_old,0) > 0) then
    begin
      valor_emolumento_old_calc = cast((:valor_emolumento_old * 1.0662) as numeric(18,2));
    end
    if (:valor_emolumento_old_calc <> :valor_emolumento) then
    begin
      select g.numero from g_selo_grupo g
      where selo_grupo_id = :selo_grupo_id
      into :grupo;
      suspend;
    end
  end

  for select i.emolumento_id, e.descricao, i.valor_emolumento, i.valor_taxa_judiciaria,
        i.selo_grupo_id, e.sistema_id
      from g_emolumento_item i, g_emolumento e
      where i.emolumento_id = e.emolumento_id
      and i.emolumento_periodo_id = 50027
      and e.situacao = 'A'
      and e.sistema_id <> 1
      into :emolumento_id, :descricao, :valor_emolumento, :valor_taxa, :selo_grupo_id,
        :sistema_id do
  begin
    valor_emolumento_old = 0;
    valor_taxa_old = 0;
    valor_emolumento_old_calc = 0;
    select first 1 i.valor_emolumento, i.valor_taxa_judiciaria
      from g_emolumento_item i, g_emolumento e
      where i.emolumento_id = e.emolumento_id
      and i.emolumento_id = :emolumento_id
      and i.emolumento_periodo_id = 50026
      and e.situacao = 'A'
      and i.selo_grupo_id = :selo_grupo_id
      and e.sistema_id = :sistema_id
      into :valor_emolumento_old, :valor_taxa_old;
    if (coalesce(:valor_emolumento_old,0) > 0) then
    begin
      valor_emolumento_old_calc = cast((:valor_emolumento_old * 1.0662) as numeric(18,2));
    end
    if (:valor_emolumento_old_calc <> :valor_emolumento) then
    begin
      select g.numero from g_selo_grupo g
      where selo_grupo_id = :selo_grupo_id
      into :grupo;

      suspend;
    end
  end
end ^

ALTER PROCEDURE W_CONTAR_STRING (V_STRING VARCHAR(200) CHARACTER SET ISO8859_1,
V_TEXTO_PARA_PESQUISA TEXTO_BLOB)
RETURNS (QUANTIDADE INTEGER)
AS 
DECLARE VARIABLE V_TAMANHO_STRING INTEGER;
  DECLARE VARIABLE V_TAMANHO_TEXTO INTEGER;
  DECLARE VARIABLE V_POS INTEGER;
  DECLARE VARIABLE V_QTDE INTEGER;
  DECLARE VARIABLE V_TEXTO TEXTO_BLOB;
BEGIN
  V_TAMANHO_STRING = CHAR_LENGTH(:V_STRING);
  V_TAMANHO_TEXTO = CHAR_LENGTH(:V_TEXTO_PARA_PESQUISA);
  V_TEXTO = :V_TEXTO_PARA_PESQUISA;
  V_QTDE = 0;
  V_POS = POSITION(:V_STRING IN :V_TEXTO);
  WHILE (:V_POS > 0) DO
  BEGIN
    V_QTDE = :V_QTDE + 1;
    V_TEXTO = SUBSTRING(:V_TEXTO FROM (:V_POS + :V_TAMANHO_STRING) FOR :V_TAMANHO_TEXTO);
    V_POS = POSITION(:V_STRING IN :V_TEXTO);
  END
  QUANTIDADE = :V_QTDE;
  SUSPEND;
END ^

ALTER PROCEDURE W_CORRIGE_MENUS_DUPLICADOS RETURNS (STATUS VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_COUNT INTEGER;
  DECLARE VARIABLE V_DESCRICAO VARCHAR(60);
  DECLARE VARIABLE V_SISTEMA_ID INTEGER;
  DECLARE VARIABLE V_SISTEMA_MENU_ID INTEGER;
BEGIN
  FOR SELECT COUNT(*), DESCRICAO, SISTEMA_ID FROM G_SISTEMA_MENU
      GROUP BY DESCRICAO, SISTEMA_ID
      HAVING COUNT(*) > 1
      INTO :V_COUNT, :V_DESCRICAO, :V_SISTEMA_ID DO
  BEGIN
    SELECT FIRST 1 SISTEMA_MENU_ID FROM G_SISTEMA_MENU
    WHERE DESCRICAO = :V_DESCRICAO
    AND SISTEMA_ID = :V_SISTEMA_ID
    ORDER BY SISTEMA_MENU_ID DESC
    INTO :V_SISTEMA_MENU_ID;
    
    DELETE FROM G_PERMISSAO_GRUPO
    WHERE SISTEMA_ROTINA_ID IN (
      SELECT SISTEMA_ROTINA_ID FROM G_SISTEMA_ROTINA
      WHERE SISTEMA_MENU_ID = :V_SISTEMA_MENU_ID);
    
    DELETE FROM G_SISTEMA_ROTINA    
    WHERE SISTEMA_MENU_ID = :V_SISTEMA_MENU_ID;

    DELETE FROM G_SISTEMA_MENU
    WHERE SISTEMA_MENU_ID = :V_SISTEMA_MENU_ID;
  END
  STATUS = 'OK';
  SUSPEND;
END ^

ALTER PROCEDURE W_CORRIGE_PARAMETROS_DUPLICADOS RETURNS (STATUS VARCHAR(10) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE V_COUNT INTEGER;
DECLARE VARIABLE V_SISTEMA_ID INTEGER;
DECLARE VARIABLE V_DESCRICAO VARCHAR(120);
DECLARE VARIABLE V_CONFIG_GRUPO_ID INTEGER;
BEGIN
  FOR SELECT COUNT(*), DESCRICAO, SISTEMA_ID FROM G_CONFIG_GRUPO
      GROUP BY DESCRICAO, SISTEMA_ID
      HAVING COUNT(*) > 1
      INTO :V_COUNT, :V_DESCRICAO, :V_SISTEMA_ID DO
  BEGIN
    SELECT FIRST 1 CONFIG_GRUPO_ID FROM G_CONFIG_GRUPO
    WHERE DESCRICAO = :V_DESCRICAO
    AND SISTEMA_ID = :V_SISTEMA_ID
    ORDER BY CONFIG_GRUPO_ID DESC
    INTO :V_CONFIG_GRUPO_ID;
    
    DELETE FROM G_CONFIG
    WHERE CONFIG_GRUPO_ID = :V_CONFIG_GRUPO_ID;

    DELETE FROM G_CONFIG_GRUPO
    WHERE CONFIG_GRUPO_ID = :V_CONFIG_GRUPO_ID;
  END
  STATUS = 'OK';
  SUSPEND;
END ^

ALTER PROCEDURE W_CORRIGIR_LOGRADOURO RETURNS (TIPO_REGISTRO VARCHAR(3) CHARACTER SET ISO8859_1,
NUMERO INTEGER)
AS 
declare variable IMOVEL_LOGRADOURO_ID  NUMERICO;
  declare variable IMOVEL_UNIDADE_ID     NUMERICO;
  declare variable DESCRICAO             VARCHAR_090;
  declare variable DESCRICAO_LOGRADOURO             VARCHAR_090;
  declare variable NUMERO_LOGRADOURO     VARCHAR_015;
  declare variable TB_TIPOLOGRADOURO_ID  NUMERICO;
begin
  for select i.tipo_registro, i.numero, il.imovel_logradouro_id, il.imovel_unidade_id, il.descricao,
             il.numero_logradouro, il.tb_tipologradouro_id, iu.descricao_logradouro
      from r_imovel i, r_imovel_logradouro il, r_imovel_unidade iu
      where i.imovel_id = iu.imovel_id
      and il.imovel_unidade_id = iu.imovel_unidade_id
      into :tipo_registro, :numero, :imovel_logradouro_id, :imovel_unidade_id,
           :descricao, :numero_logradouro, :tb_tipologradouro_id, :descricao_logradouro do
  begin
    if ((coalesce(:descricao_logradouro,'') = '') and (coalesce(:descricao,'') <> '')) then
    begin
      update r_imovel_unidade
      set descricao_logradouro = :descricao,
          numero_logradouro = :numero_logradouro,
          tb_tipologradouro_id = :tb_tipologradouro_id
      where imovel_unidade_id = :imovel_unidade_id;

      suspend;
    end
  end
end ^

ALTER PROCEDURE W_CORRIGIR_LOGRADOURO_COND RETURNS (TIPO_REGISTRO VARCHAR(3) CHARACTER SET ISO8859_1,
NUMERO INTEGER)
AS 
declare variable IMOVEL_LOGRADOURO_ID  NUMERICO;
  declare variable IMOVEL_UNIDADE_ID     NUMERICO;
  declare variable IMOVEL_FICHAAUXILIAR_ID     NUMERICO;
  declare variable DESCRICAO_LOGRADOURO  VARCHAR_090;
  declare variable DESCRICAO_LOGRADOURO2  VARCHAR_090;
  declare variable NUMERO_LOGRADOURO     VARCHAR_015;
  declare variable TB_TIPOLOGRADOURO_ID  NUMERICO;
begin
  for select iu.numero_logradouro, iu.tb_tipologradouro_id, iu.descricao_logradouro,
             if.imovel_fichaauxiliar_id
      from r_imovel i, r_imovel_unidade iu, r_imovel_fichaauxiliar if
      where i.imovel_id = iu.imovel_id
      and if.imovel_id = i.imovel_id
      and if.tipo_ficha = 'C' --condominio
      into :numero_logradouro, :tb_tipologradouro_id, :descricao_logradouro, :imovel_fichaauxiliar_id do
  begin
    for select i2.tipo_registro, i2.numero, iu2.imovel_unidade_id, iu2.descricao_logradouro
        from r_imovel i2, r_imovel_unidade iu2
        where i2.imovel_id = iu2.imovel_id
        and iu2.imovel_fichaauxiliar_id = :imovel_fichaauxiliar_id
        into :tipo_registro, :numero, :imovel_unidade_id, :descricao_logradouro2 do
    begin
      if ((coalesce(:descricao_logradouro2,'') = '') and (coalesce(:descricao_logradouro,'') <> '')) then
      begin
        update r_imovel_unidade
        set descricao_logradouro = :descricao_logradouro,
            numero_logradouro = :numero_logradouro,
            tb_tipologradouro_id = :tb_tipologradouro_id
        where imovel_unidade_id = :imovel_unidade_id;

        suspend;
      end
    end
  end
end ^

ALTER PROCEDURE W_DECODE_B64 (V_TEXTO_B64 BLOB CHARACTER SET ISO8859_1)
RETURNS (TEXTO BLOB CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE I INTEGER;
  DECLARE VARIABLE A INTEGER;
  DECLARE VARIABLE X INTEGER;
  DECLARE VARIABLE B INTEGER;
  DECLARE VARIABLE CODES64 VARCHAR(70);
BEGIN
  CODES64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  TEXTO = '';
  A = 0;
  B = 0;
  I = 1;
  WHILE (:I <= CHAR_LENGTH(:V_TEXTO_B64)) DO
  BEGIN
    X = POSITION(SUBSTRING(:V_TEXTO_B64 FROM :I FOR 1) IN :CODES64 ) - 1;
    IF (:X >= 0) THEN
    BEGIN
      B = :B * 64 + :X;
      A = :A + 6;
      IF (:A >=8) THEN
      BEGIN
        A = :A - 8;
        X = BIN_SHR(:B, :A);
        B = MOD(:B, BIN_SHL (1,:A));
        X = MOD(:X, 256);
        TEXTO = :TEXTO || ASCII_CHAR(:X);
      END
    END  
    I = I + 1;
  END  
  SUSPEND;
END ^

ALTER PROCEDURE W_ENCERRAR_PROTOCOLOS_EM_ABERTO (DATA_FINAL VARCHAR(15) CHARACTER SET ISO8859_1,
TB_TIPO_ANDAMENTO_ID INTEGER,
COMPLEMENTO VARCHAR(60) CHARACTER SET ISO8859_1)
RETURNS (PEDIDO_ID INTEGER,
NUMERO_ORDEM INTEGER,
DATA_PROTOCOLO DATE)
AS 
declare variable v_andamento_id integer;
begin
  for select pr.pedido_id, pr.numero_ordem, pr.data from r_protocolo pr
      where pr.tipo_protocolo = '1'
      and (select count(*) from r_andamento a, r_tb_tipo_andamento ta
           where a.tb_tipo_andamento_id = ta.tb_tipo_andamento_id
           and a.pedido_id = pr.pedido_id
           and coalesce(ta.tipo,'') = 'R') = 0
      and (select count(*) from r_andamento a, r_tb_tipo_andamento ta
           where a.tb_tipo_andamento_id = ta.tb_tipo_andamento_id
           and a.pedido_id = pr.pedido_id
           and coalesce(ta.tipo,'') = 'C') = 0
      and (select count(*) from r_andamento a, r_tb_tipo_andamento ta
           where a.tb_tipo_andamento_id = ta.tb_tipo_andamento_id
           and a.pedido_id = pr.pedido_id
           and ta.tb_tipo_andamento_id = :tb_tipo_andamento_id) = 0
      and cast(pr.data as date) < :data_final
      order by pr.numero_ordem
  into :pedido_id, :numero_ordem, :data_protocolo do
  begin
    select first 1 (andamento_id + 1) from r_andamento
    order by andamento_id desc
    into :v_andamento_id;

    insert into r_andamento (andamento_id, complemento, data, pedido_id, tb_tipo_andamento_id, usuario_id)
    values (:v_andamento_id, :complemento, current_timestamp, :pedido_id, :tb_tipo_andamento_id, 123456);

    suspend;
  end
  update g_sequencia
  set sequencia = :v_andamento_id
  where tabela = 'R_ANDAMENTO';
end ^

ALTER PROCEDURE W_ENCODE_B64 (V_TEXTO BLOB CHARACTER SET ISO8859_1)
RETURNS (TEXTO_B64 BLOB CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE I INTEGER;
  DECLARE VARIABLE A INTEGER;
  DECLARE VARIABLE X INTEGER;
  DECLARE VARIABLE B INTEGER;
  DECLARE VARIABLE CODES64 VARCHAR(70);
BEGIN
  CODES64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  TEXTO_B64 = '';
  A = 0;
  B = 0;
  I = 1;
  WHILE (:I <= CHAR_LENGTH(:V_TEXTO)) DO
  BEGIN
    X = ASCII_VAL(SUBSTRING(:V_TEXTO FROM :I FOR 1));
    B = :B * 256 + :X;
    A = :A + 8;
    WHILE (:A >= 6) DO
    BEGIN
      A = :A - 6;
      X = CAST((:B/BIN_SHL(1,:A)) AS INTEGER);
      B = MOD(:B, BIN_SHL(1,:A));
      TEXTO_B64 = :TEXTO_B64 || SUBSTRING(:CODES64 FROM (:X + 1) FOR 1);      
    END
    I = :I + 1;
  END
  IF (:A > 0) THEN
  BEGIN
    X = BIN_SHL(:B,(6 - :A));
    TEXTO_B64 = :TEXTO_B64 || SUBSTRING(:CODES64 FROM (:X + 1) FOR 1);      
  END
  A = MOD(CHAR_LENGTH(:TEXTO_B64), 4);
  IF (:A = 2) THEN
  BEGIN
    TEXTO_B64 = :TEXTO_B64 ||'==';
  END
  ELSE IF (:A = 3) THEN
  BEGIN  
    TEXTO_B64 = :TEXTO_B64 ||'=';
  END
  SUSPEND;
END ^

ALTER PROCEDURE W_FORMATAR_CPF_CNPJ (STR VARCHAR(20) CHARACTER SET ISO8859_1)
RETURNS (RETORNO VARCHAR(20) CHARACTER SET ISO8859_1)
AS 
BEGIN  
  IF (CHAR_LENGTH(:STR) = 11) THEN --CPF
  BEGIN
    RETORNO = SUBSTRING(:STR FROM 1 FOR 3)||'.'||SUBSTRING(:STR FROM 4 FOR 3)||'.'||
      SUBSTRING(:STR FROM 7 FOR 3)||'-'||SUBSTRING(:STR FROM 10 FOR 2);
  END
  ELSE IF (CHAR_LENGTH(:STR) = 14) THEN --CNPJ
  BEGIN
    RETORNO = SUBSTRING(:STR FROM 1 FOR 2)||'.'||SUBSTRING(:STR FROM 3 FOR 3)||'.'||
      SUBSTRING(:STR FROM 6 FOR 3)||'/'||SUBSTRING(:STR FROM 9 FOR 4)||'-'||SUBSTRING(:STR FROM 13 FOR 2);
  END
  ELSE
  BEGIN
    RETORNO = :STR;
  END
  SUSPEND;
END ^

ALTER PROCEDURE W_LENGTH (STR VARCHAR(2000) CHARACTER SET ISO8859_1)
RETURNS (TAMANHO INTEGER)
AS 
DECLARE VARIABLE V_PAT VARCHAR(2000);
BEGIN
  TAMANHO = null;
  IF (STR IS NULL) THEN
    EXIT;
  V_PAT = '';
  TAMANHO = 0;
  WHILE (NOT STR LIKE V_PAT) DO
  BEGIN
    V_PAT = V_PAT || '_';
    TAMANHO = TAMANHO + 1;
  END
  SUSPEND;
END ^

