ALTER PROCEDURE W_POS (SUBSTR VARCHAR(2000) CHARACTER SET ISO8859_1,
STR VARCHAR(2000) CHARACTER SET ISO8859_1)
RETURNS (POS INTEGER)
AS 
DECLARE VARIABLE SubStr2 VARCHAR(4001); /* 1 + SubStr-lenght + Str-length */
  DECLARE VARIABLE Tmp VARCHAR(2000);
BEGIN
  IF (SubStr IS NULL OR Str IS NULL) THEN
  BEGIN
    Pos = NULL;
    EXIT;
  END
  SubStr2 = SubStr || '%';
  Tmp = '';
  Pos = 1;
  WHILE (Str NOT LIKE SubStr2 AND Str NOT LIKE Tmp) DO
  BEGIN
    SubStr2 = '_' || SubStr2;
    Tmp = Tmp || '_';
    Pos = Pos + 1;
  END
  IF (Str LIKE Tmp) THEN
    Pos = 0;
  SUSPEND;
END ^

ALTER PROCEDURE W_QTDE_REGISTROS_TABELAS RETURNS (TABELA VARCHAR(100) CHARACTER SET ISO8859_1,
QUANTIDADE_REGISTRO INTEGER)
AS 
declare variable V_SQL VARCHAR(1000);
BEGIN
  FOR SELECT TRIM(RDB$RELATION_NAME) TABELA FROM RDB$RELATIONS
    WHERE RDB$SYSTEM_FLAG = 0
    AND RDB$RELATION_TYPE = 0
    ORDER  BY RDB$RELATION_NAME
    INTO :TABELA DO
  BEGIN
    V_SQL = 'SELECT COUNT(*) FROM '||:TABELA;

    EXECUTE STATEMENT :V_SQL INTO :quantidade_registro;

    SUSPEND;
  END
END ^

ALTER PROCEDURE W_RETIRAR_ACENTUACAO (NOME VARCHAR(1000) CHARACTER SET ISO8859_1)
RETURNS (NOME_SEM_ACENTUACAO VARCHAR(1000) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE I INTEGER;
  DECLARE VARIABLE AUX VARCHAR(1000);
  DECLARE VARIABLE STR VARCHAR(1);
BEGIN
  AUX = UPPER(:NOME);
  I = 0;
  WHILE (:I < CHAR_LENGTH(:AUX)) DO
  BEGIN
    I = (:I + 1);
    STR = SUBSTRING(:AUX FROM :I FOR 1);
    SELECT CASE 
      WHEN (:STR IN ('Á', 'Â', 'Ã', 'À', 'Ä', 'Å')) THEN 'A'
      WHEN (:STR IN ('É', 'Ê', 'È', 'Ë')) THEN 'E'
      WHEN (:STR IN ('Í', 'Î', 'Ì', 'Ï')) THEN 'I'
      WHEN (:STR IN ('Ó', 'Ô', 'Õ', 'Ò', 'Ö')) THEN 'O'
      WHEN (:STR IN ('Ú', 'Û', 'Ù', 'Ü')) THEN 'U'
      WHEN (:STR IN ('Ç')) THEN 'C'
      WHEN (:STR IN ('Ñ')) THEN 'N'
      WHEN (:STR IN ('Ý', '')) THEN 'Y'            
      ELSE :STR
      END AS VSTR      
    FROM RDB$DATABASE
    INTO :STR;
    IF (:I = 1) THEN
    BEGIN
      AUX = :STR|| SUBSTRING(:AUX FROM 2 FOR (CHAR_LENGTH(:AUX) -1));
    END
    ELSE
    BEGIN
      AUX = SUBSTRING(:AUX FROM 1 FOR (:I-1))||:STR||SUBSTRING(:AUX FROM (:I+1) FOR (CHAR_LENGTH(:AUX) -I));
    END      
  END
  NOME_SEM_ACENTUACAO = :AUX;
  SUSPEND;
END ^

ALTER PROCEDURE W_RETIRAR_CARACTERESPECIAL (NOME VARCHAR(1000) CHARACTER SET ISO8859_1)
RETURNS (NOME_SEM_ACENTUACAO VARCHAR(1000) CHARACTER SET ISO8859_1)
AS 
declare variable I integer;
declare variable AUX varchar(1000);
declare variable STR varchar(1);
BEGIN
  AUX = UPPER(:NOME);
  I = 0;
  WHILE (:I < CHAR_LENGTH(:AUX)) DO
  BEGIN
    I = (:I + 1);
    STR = SUBSTRING(:AUX FROM :I FOR 1);
    SELECT CASE 
      WHEN (:STR IN ('&', '-', '/', '\', '.', 'Å')) THEN ''
      ELSE :STR
      END AS VSTR      
    FROM RDB$DATABASE
    INTO :STR;
    IF (:I = 1) THEN
    BEGIN
      AUX = :STR|| SUBSTRING(:AUX FROM 2 FOR (CHAR_LENGTH(:AUX) -1));
    END
    ELSE
    BEGIN
      AUX = SUBSTRING(:AUX FROM 1 FOR (:I-1))||:STR||SUBSTRING(:AUX FROM (:I+1) FOR (CHAR_LENGTH(:AUX) -I));
    END      
  END
  NOME_SEM_ACENTUACAO = :AUX;
  SUSPEND;
END ^

ALTER PROCEDURE W_RETORNAR_COM_ZERO_ESQUERDA (V_VALOR VARCHAR(20) CHARACTER SET ISO8859_1,
TAMANHO_RETORNO INTEGER)
RETURNS (STRING VARCHAR(100) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE I INTEGER;
DECLARE VARIABLE V_TAMANHO INTEGER;
DECLARE VARIABLE V_DIFERENCA INTEGER;
BEGIN
  STRING = '';
  I = 0;

  SELECT TAMANHO FROM W_LENGTH(:V_VALOR)
  INTO :V_TAMANHO;
  
  IF (:TAMANHO_RETORNO > :V_TAMANHO) THEN
  BEGIN
    V_DIFERENCA = :TAMANHO_RETORNO - :V_TAMANHO;
    STRING = '';
    WHILE (:I < V_DIFERENCA) DO
    BEGIN
      STRING = :STRING ||'0';
      I = :I + 1;
    END
    STRING = :STRING || :V_VALOR;
  END
  ELSE
  BEGIN
    STRING = :V_VALOR;
  END
  SUSPEND;
END ^

ALTER PROCEDURE W_RETORNAR_INTEIRO (V_STRING VARCHAR(100) CHARACTER SET ISO8859_1)
RETURNS (INTEIRO VARCHAR(100) CHARACTER SET ISO8859_1)
AS 
DECLARE CH CHAR(1);
BEGIN
  INTEIRO = '';
  WHILE (V_STRING IS NOT NULL AND V_STRING <> '') DO
  BEGIN
    CH = SUBSTRING(V_STRING FROM 1 FOR 1);
    IF ((CH >= '0') AND (CH <= '9')) THEN
      INTEIRO = INTEIRO || CH;
    V_STRING = SUBSTRING(V_STRING FROM 2 FOR 100);
  END
  SUSPEND;
END ^

ALTER PROCEDURE W_RETORNAR_STRING (V_STRING VARCHAR(100) CHARACTER SET ISO8859_1)
RETURNS (STRING VARCHAR(100) CHARACTER SET ISO8859_1)
AS 
DECLARE CH CHAR(1);
BEGIN
  STRING = '';
  WHILE (V_STRING IS NOT NULL AND V_STRING <> '') DO
  BEGIN
    CH = SUBSTRING(V_STRING FROM 1 FOR 1);
    IF (NOT ((CH >= '0') AND (CH <= '9'))) THEN
      STRING = STRING || CH;
    V_STRING = SUBSTRING(V_STRING FROM 2 FOR 100);
  END
  SUSPEND;
END ^

