ALTER PROCEDURE W_ULTIMO_DIA_MES (V_MES INTEGER,
V_ANO INTEGER)
RETURNS (ULTIMO_DIA INTEGER)
AS 
declare variable eh_bisexto varchar(10);
BEGIN
  ULTIMO_DIA = 0;
  if (:V_MES in (1,3,5,7,8,10,12)) then
  begin
    ULTIMO_DIA = 31;
  end
  else if (:V_MES in (4,6,9,11)) then
  begin
    ULTIMO_DIA = 30;
  end
  else if (:V_MES = 2) then
  begin
    select resultado from w_bisexto(:V_ANO)
    into :eh_bisexto;
    if (:eh_bisexto = 'SIM') then
    begin
      ULTIMO_DIA = 29;
    end
    else
    begin
      ULTIMO_DIA = 28;
    end
  end
  SUSPEND;
END ^

ALTER PROCEDURE W_ULTIMO_DIA_UTIL_MES (V_MES INTEGER,
V_ANO INTEGER)
RETURNS (ULTIMO_DIA_UTIL INTEGER)
AS 
declare variable EH_BISEXTO varchar(10);
  declare variable EH_UTIL varchar(1);
  declare variable V_DATA DATE;
  declare variable V_FERIADO varchar(1);
BEGIN
  ULTIMO_DIA_UTIL = 0;
  if (:V_MES in (1,3,5,7,8,10,12)) then
  begin
    ULTIMO_DIA_UTIL = 31;
  end
  else if (:V_MES in (4,6,9,11)) then
  begin
    ULTIMO_DIA_UTIL = 30;
  end
  else if (:V_MES = 2) then
  begin
    select resultado from w_bisexto(:V_ANO)
    into :eh_bisexto;
    if (:eh_bisexto = 'SIM') then
    begin
      ULTIMO_DIA_UTIL = 29;
    end
    else
    begin
      ULTIMO_DIA_UTIL = 28;
    end
  end

  --FAZER VERIFICACAO DE DIAS UTEIS
  EH_UTIL = 'N';
  while (:EH_UTIL = 'N') do
  begin
    V_DATA = CAST((CAST(:ULTIMO_DIA_UTIL AS VARCHAR(2))||'.'||CAST(:V_MES AS VARCHAR(2))||'.'||CAST(:V_ANO AS VARCHAR(4))) AS DATE);

    SELECT coalesce(SIM_NAO, 'N') FROM g_verifica_se_eh_feriado(CAST(:V_DATA AS VARCHAR(12))) INTO :V_FERIADO;
    if (V_FERIADO = 'S') THEN
    BEGIN
      ULTIMO_DIA_UTIL = (:ULTIMO_DIA_UTIL - 1);
    END
    ELSE if ((EXTRACT(WEEKDAY FROM :V_DATA) = 0) or ((EXTRACT(WEEKDAY FROM :V_DATA) = 6))) then
    BEGIN
      ULTIMO_DIA_UTIL = (:ULTIMO_DIA_UTIL - 1);
    END
    ELSE
    BEGIN
      EH_UTIL = 'S';
    END
  end
  SUSPEND;
END ^

ALTER PROCEDURE W_VALIDAR_CPF_CNPJ (STR VARCHAR(20) CHARACTER SET ISO8859_1)
RETURNS (RETORNO CHAR(1) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE N1 INTEGER;
DECLARE VARIABLE N2 INTEGER;
DECLARE VARIABLE N3 INTEGER;
DECLARE VARIABLE N4 INTEGER;
DECLARE VARIABLE N5 INTEGER;
DECLARE VARIABLE N6 INTEGER;
DECLARE VARIABLE N7 INTEGER;
DECLARE VARIABLE N8 INTEGER;
DECLARE VARIABLE N9 INTEGER;
DECLARE VARIABLE D1 INTEGER;
DECLARE VARIABLE D2 INTEGER;
DECLARE VARIABLE D4 INTEGER;
DECLARE VARIABLE XX INTEGER;
DECLARE VARIABLE NCOUNT INTEGER;
DECLARE VARIABLE FATOR INTEGER;
DECLARE VARIABLE RESTO INTEGER;
DECLARE VARIABLE DIGITO1 INTEGER;
DECLARE VARIABLE DIGITO2 INTEGER;
DECLARE VARIABLE CALCULADO CHAR(2);
DECLARE VARIABLE DIGITADO CHAR(2);
DECLARE VARIABLE TAMANHO INTEGER;
DECLARE VARIABLE STR_TRATADO VARCHAR(20);
BEGIN  
  RETORNO = 'F';
  SELECT INTEIRO FROM W_RETORNAR_INTEIRO(:STR)
  INTO :STR_TRATADO; 
  SELECT TAMANHO FROM W_LENGTH(:STR_TRATADO)
  INTO :TAMANHO;
  IF ((:TAMANHO <> 11) AND (:TAMANHO <> 14)) THEN
  BEGIN
    SUSPEND;
    EXIT;
  END
  IF (:TAMANHO = 11) THEN -- SE FOR CPF
  BEGIN
    N1 = CAST(SUBSTRING(STR_TRATADO FROM 1 FOR 1) AS INTEGER);
    N2 = CAST(SUBSTRING(STR_TRATADO FROM 2 FOR 1) AS INTEGER);
    N3 = CAST(SUBSTRING(STR_TRATADO FROM 3 FOR 1) AS INTEGER);
    N4 = CAST(SUBSTRING(STR_TRATADO FROM 4 FOR 1) AS INTEGER);
    N5 = CAST(SUBSTRING(STR_TRATADO FROM 5 FOR 1) AS INTEGER);
    N6 = CAST(SUBSTRING(STR_TRATADO FROM 6 FOR 1) AS INTEGER);
    N7 = CAST(SUBSTRING(STR_TRATADO FROM 7 FOR 1) AS INTEGER);
    N8 = CAST(SUBSTRING(STR_TRATADO FROM 8 FOR 1) AS INTEGER);
    N9 = CAST(SUBSTRING(STR_TRATADO FROM 9 FOR 1) AS INTEGER);
    D1 = N9*2+N8*3+N7*4+N6*5+N5*6+N4*7+N3*8+N2*9+N1*10;
    D1 = 11 - MOD(D1,11);
    IF (D1 >= 10) then
      D1 = 0;
    D2 = D1*2+N9*3+N8*4+N7*5+N6*6+N5*7+N4*8+N3*9+N2*10+N1*11;
    D2 = 11 - MOD(D2,11);
    IF (D2 >= 10) then
      D2 = 0;
    CALCULADO = CAST(D1 AS VARCHAR(1))||CAST(D2 AS VARCHAR(1));
    DIGITADO = SUBSTRING(STR_TRATADO FROM 10 FOR 2);
    IF (:CALCULADO = :DIGITADO) THEN
      RETORNO = 'T';
    ELSE
      RETORNO = 'F';      
  END
  IF (:TAMANHO = 14) THEN -- SE FOR CNPJ
  BEGIN
    D1 = 0;
    D4 = 0;
    XX = 1;
    NCOUNT = 0;
    WHILE (NCOUNT < (TAMANHO - 2)) DO
    BEGIN
      NCOUNT = (NCOUNT + 1);
      IF (XX < 5) THEN
        FATOR = (6 - XX);
      ELSE
        FATOR = (14 - XX);
      D1 = D1 + CAST(SUBSTRING(STR_TRATADO FROM NCOUNT FOR 1) AS INTEGER) * FATOR;
      IF (XX < 6) THEN
        FATOR = (7 - XX);
      ELSE
        FATOR = (15 - XX);
      D4 = D4 + CAST(SUBSTRING(STR_TRATADO FROM NCOUNT FOR 1) AS INTEGER) * FATOR;
      XX = XX + 1;
    END
    RESTO = MOD(D1,11);
    IF (RESTO < 2) then
      DIGITO1 = 0;
    ELSE
      DIGITO1 = (11 - RESTO);
    D4 = D4 + 2 * DIGITO1;
    RESTO = MOD(D4,11);
    IF (RESTO < 2) then
      DIGITO2 = 0;
    ELSE
      DIGITO2 = (11 - RESTO);
    CALCULADO = CAST(DIGITO1 AS VARCHAR(1))||CAST(DIGITO2 AS VARCHAR(1));
    DIGITADO = SUBSTRING(STR_TRATADO FROM (TAMANHO - 1) FOR 2);
    IF (:CALCULADO = :DIGITADO) THEN
      RETORNO = 'T';
    ELSE
      RETORNO = 'F';      
  END
  SUSPEND;
END ^

ALTER PROCEDURE W_VALORES_ENTRE_CARACTER (V_STRING VARCHAR(20000) CHARACTER SET ISO8859_1,
V_CARACTER VARCHAR(1) CHARACTER SET ISO8859_1)
RETURNS (ID INTEGER,
VALOR_RETORNO VARCHAR(8000) CHARACTER SET ISO8859_1)
AS 
DECLARE VARIABLE LETRA CHAR(1);
DECLARE VARIABLE TEXTO VARCHAR(10);
begin
  ID = 0;
  VALOR_RETORNO = '';
  while (:V_STRING <> '') do
  begin
    LETRA = substring(:V_STRING from 1 for 1);
    if (LETRA<>:V_CARACTER) then
    begin
       VALOR_RETORNO = :VALOR_RETORNO || LETRA;
       V_STRING = substring(:V_STRING from 2 for (CHAR_LENGTH(:V_STRING)-1));
       if (TRIM(:V_STRING) = '') then
       begin
        ID = :ID + 1;
        suspend;
       end
    end
    else
    begin
      ID = :ID + 1;
      suspend;
      V_STRING = substring(:V_STRING from 2 for (CHAR_LENGTH(:V_STRING)-1));
      VALOR_RETORNO = '';
    end
  end
end ^

SET TERM ; ^
COMMIT WORK;
