/* Triggers only will work for SQL triggers */
CREATE TRIGGER C_ATUALIZACAO_002 
ACTIVE ON CONNECT POSITION 0 
AS
BEGIN

END ^

CREATE TRIGGER G_TR_CONNECT_1 
ACTIVE ON CONNECT POSITION 0 
as
  declare variable v_uf varchar(10);
  declare variable v_drop varchar(500);  
begin
  if (CURRENT_DATE >= CAST('01.01.2022' AS DATE)) then
  begin
    select first 1 trim(c.valor) from g_config c, g_config_grupo g
    where c.config_grupo_id = g.config_grupo_id
    and g.sistema_id = 5 --caixa
    and c.secao = 'CARTORIO'
    and c.nome = 'UF'
    into :v_uf;
    
    if (:v_uf = 'TO') then
    begin    
      v_drop = 'DROP TRIGGER G_TR_CONNECT_1';
      execute statement :v_drop;
    end
  end
end ^

CREATE TRIGGER G_SELO_DECENDIO_BU0 FOR G_SELO_DECENDIO 
ACTIVE BEFORE UPDATE POSITION 0 
AS
declare variable v_codigo_ato varchar(30);
begin

  for
  select i.codigo_ato
    from g_selo_decendio_item i
   where i.g_selo_decendio_id = new.selo_decendio_id
    into :v_codigo_ato do
   begin

     /* marcar os selos ja conciliados */
     update g_selo_livro
        set conciliado = 'S'
     where numero_selo = :v_codigo_ato;
   end

end ^

CREATE TRIGGER G_SELO_LIVRO_BI FOR G_SELO_LIVRO 
ACTIVE BEFORE INSERT POSITION 0 
as
declare variable v_uf varchar(10) ;
begin
  if (coalesce(new.NUMERO_SELO,'') = '') then
  begin
    select first 1 coalesce(c.valor,'') from g_config c, g_config_grupo g
    where c.config_grupo_id = g.config_grupo_id
    and g.sistema_id = 5 --caixa
    and c.secao = 'CARTORIO'
    and c.nome = 'UF'
    into :v_uf;

    if (:v_uf = 'GO') then
    begin
      new.NUMERO_SELO = case char_length(new.SIGLA)
                          when 17 then new.SIGLA||LPAD(CAST(new.NUMERO AS INTEGER),6,'0')
                          when 18 then new.SIGLA||LPAD(CAST(new.NUMERO AS INTEGER),5,'0')
                          when 19 then new.SIGLA||LPAD(CAST(new.NUMERO AS INTEGER),4,'0')
                        end;
    end
    else if (:v_uf = 'TO') then
    begin
      new.NUMERO_SELO = new.SIGLA||LPAD(CAST(new.NUMERO AS INTEGER),6,'0');
    end
    else if (:v_uf = 'BA') then
    begin
      new.NUMERO_SELO = new.SIGLA||LPAD(CAST(new.NUMERO AS INTEGER),5,'0');
    end
  end
end ^

CREATE TRIGGER G_SELO_LIVRO_BU0 FOR G_SELO_LIVRO 
ACTIVE BEFORE UPDATE POSITION 0 
AS
declare variable vdepprevioid integer;
declare variable vemolumentos dinheiro;
declare variable vlote integer;
begin
  if (new.SELO_SITUACAO_ID <> old.SELO_SITUACAO_ID) then
  begin
    if (new.SELO_SITUACAO_ID = 2) then
    begin
      new.DATA_CADASTRO = CURRENT_TIMESTAMP;
    end

    /* caso o selo seja extornado, reintegrar o valor do mesmo ao deposito previo */
    if (new.SELO_SITUACAO_ID = 1) then
    begin

      if (coalesce(new.nlote,0) <> 0) then
      begin
        update g_deposito_previo
           set nlote = abs(new.nlote)
         where abs(nlote) = abs(new.nlote)
           and cast(data_lancto as date) = cast(new.data as date);
      end

      /* liberando o num do lote, ja que esse selo foi extornado */
      new.APONTAMENTO_PROTESTO = null; 
      new.nlote = 0;
      new.DATA_CADASTRO = null;
    end
  end
end ^

CREATE TRIGGER G_SESSAOUSUARIO FOR G_SESSAO_USUARIOS 
ACTIVE BEFORE INSERT POSITION 0 
AS
begin
  delete from G_SESSAO_USUARIOS where SESSION_ID not in (select MON$ATTACHMENT_ID from MON$ATTACHMENTS);
end ^


